    {
      name: '__session',
      value: 'mock_session_token_123',
      domain: 'localhost',
      path: '/',
    },
    {
      name: '__e2e_test',
      value: '1',
      domain: 'localhost',
      path: '/',
    },
    {
      name: '__e2e_bypass_onboarding',
      value: '1',
      domain: 'localhost',
      path: '/',
    },
    {
      name: 'mock_user_subscription_plan',
      value: mappedPlan,
      domain: 'localhost',
      path: '/',
