          if (nowChecked !== wasChecked) {
            return;
          }
          console.log(`[E2EDebug] Checkbox click failed to toggle state (wasChecked: ${wasChecked}, nowChecked: ${nowChecked}), retrying...`);
          continue;
        }

        await locator.page().waitForTimeout(200);
        return;
