describe('Acquisition Phase LOI PDF Generation API Tests', () => {
  const mockProject = {
    id: 'project_123',
    propertyName: 'Atlanta Duplex',
    addressLine: '123 Main St, Atlanta, GA 30309',
    organizationId: 'org_test_123',
    dispositionType: 'RENT',
    subStrategy: 'LONG_TERM',
    financials: {
