describe('Equity Parties & Roster Management with Phase Access Gating', () => {
  const PROJECT_ID = 'project_equity_test';
  const OWNER_UID = 'user_owner';
  const LEAD_UID = 'user_lead_investor';
  const LP_UID = 'user_lp';
  const OUTSIDE_UID = 'user_outside';

  const mockProject = {
    id: PROJECT_ID,
    organizationId: 'org_test',
    ownerUid: OWNER_UID,
    completedFundCards: [],
    financials: {
      purchasePrice: 200000_00,
      capitalStack: [
        { id: 'source_1', category: 'Borrower Injection', amount: 50000_00 },
      ],
    },
    members: {
      [OWNER_UID]: { role: 'Lead Investor' },
    },
    equityParties: [
      {
        id: 'party_lp',
        projectId: PROJECT_ID,
        role: 'LP',
        name: 'LP Investor',
        email: 'lp@paperworking.io',
        entityType: 'Individual',
        memberId: LP_UID,
        ownershipPct: 15,
        phasePermissions: {
          'phase-1': { canView: true, canEdit: false },
          'phase-2': { canView: true, canEdit: false },
          'phase-3': { canView: false, canEdit: false },
          'phase-4': { canView: false, canEdit: false },
        },
      },
    ],
  };

  beforeEach(() => {
    jest.clearAllMocks();

    // Default Client-side mock states
    mockUseParams.mockReturnValue({ id: PROJECT_ID });
    mockUseAuth.mockReturnValue({ user: { uid: LP_UID, email: 'lp@paperworking.io' } });
    mockUseProjectStore.mockImplementation((selector) => {
      return mockProject;
    });
    mockUsePermissions.mockReturnValue({ isLead: false });

    // Default API mock states
    mockVerifyIdToken.mockResolvedValue({
      uid: OWNER_UID,
      email: 'lead@paperworking.io',
      name: 'Lead Investor',
    });

    mockUserGet.mockResolvedValue({
      exists: true,
      data: () => ({
        personalOrganizationId: 'org_test',
        name: 'Lead Investor',
      }),
    });

    mockProjectGet.mockResolvedValue({
      exists: true,
      data: () => mockProject,
    });
  });

  // ─── SECTION 1: usePhaseAccess client hook checks ─────────────────
  describe('Client Hook usePhaseAccess', () => {
    it('returns loading state when project, user, or params are missing', () => {
      mockUseParams.mockReturnValue(null);
      const res = usePhaseAccess('phase-2');
      expect(res.loading).toBe(true);
    });

    it('grants full view/edit access to project owner / lead investor', () => {
      mockUseAuth.mockReturnValue({ user: { uid: OWNER_UID, email: 'owner@paperworking.io' } });
      const res = usePhaseAccess('phase-2');
      expect(res.canView).toBe(true);
      expect(res.canEdit).toBe(true);
      expect(res.loading).toBe(false);
    });

    it('grants full view/edit access when user is verified lead investor role', () => {
      mockUseAuth.mockReturnValue({ user: { uid: 'some_admin', email: 'admin@paperworking.io' } });
      mockUsePermissions.mockReturnValue({ isLead: true });
      const res = usePhaseAccess('phase-3');
      expect(res.canView).toBe(true);
      expect(res.canEdit).toBe(true);
      expect(res.loading).toBe(false);
    });

    it('restricts or allows based on phasePermissions for linked equity party', () => {
      // User is LP_UID who has view-only for phase-2, but no view for phase-3
      mockUseAuth.mockReturnValue({ user: { uid: LP_UID, email: 'lp@paperworking.io' } });

      const rPhase2 = usePhaseAccess('phase-2');
      expect(rPhase2.canView).toBe(true);
      expect(rPhase2.canEdit).toBe(false);

      const rPhase3 = usePhaseAccess('phase-3');
      expect(rPhase3.canView).toBe(false);
      expect(rPhase3.canEdit).toBe(false);
    });

    it('denies access entirely for unlinked non-owner users', () => {
      mockUseAuth.mockReturnValue({ user: { uid: OUTSIDE_UID, email: 'stranger@paperworking.io' } });
      const res = usePhaseAccess('phase-2');
      expect(res.canView).toBe(false);
      expect(res.canEdit).toBe(false);
    });
  });

  // ─── SECTION 2: API GET Endpoint & GP Defaulting ──────────────────
  describe('GET API Endpoint', () => {
    const buildGetRequest = () =>
      new NextRequest(`http://localhost/api/projects/${PROJECT_ID}/equity-parties`, {
        method: 'GET',
        headers: {
          Authorization: 'Bearer valid-token',
        },
      });

    it('should reject unauthenticated requests', async () => {
      mockVerifyIdToken.mockResolvedValue({ status: 401, error: 'Unauthorized' });
      const res = await GET(buildGetRequest(), { params: Promise.resolve({ id: PROJECT_ID }) });
      expect(res.status).toBe(401);
    });

    it('should default syndication Lead Investor to GP and sync to project', async () => {
      mockProjectGet.mockResolvedValue({
        exists: true,
        data: () => ({
          ...mockProject,
          fundingPlan: { modality: ['syndication_equity'] },
          equityParties: [], // empty roster initially
        }),
      });

      // Lead user is GET caller
      mockVerifyIdToken.mockResolvedValue({
        uid: OWNER_UID,
        email: 'owner@paperworking.io',
        name: 'Project Owner',
      });
      mockUserGet.mockResolvedValue({
        exists: true,
        data: () => ({
          personalOrganizationId: 'org_test',
          displayName: 'Project Owner',
        }),
      });

      const res = await GET(buildGetRequest(), { params: Promise.resolve({ id: PROJECT_ID }) });
      expect(res.status).toBe(200);
      const json = await res.json();
      expect(json.success).toBe(true);
      expect(json.equityParties.length).toBe(1);
      expect(json.equityParties[0].role).toBe('GP');
      expect(json.equityParties[0].memberId).toBe(OWNER_UID);

      // Verify DB update was triggered
      expect(mockProjectUpdate).toHaveBeenCalledWith(
        expect.objectContaining({
          equityParties: expect.arrayContaining([
            expect.objectContaining({ role: 'GP', memberId: OWNER_UID }),
          ]),
        })
      );
    });
  });

  // ─── SECTION 3: API POST Endpoint & Roster Management ──────────────
  describe('POST API Endpoint', () => {
    const buildPostRequest = (body: Record<string, any>) =>
      new NextRequest(`http://localhost/api/projects/${PROJECT_ID}/equity-parties`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: 'Bearer valid-token',
        },
        body: JSON.stringify(body),
      });

    it('should add/update an equity party member and trigger F2.1 completion', async () => {
      const partyData = {
        role: 'LP',
        name: 'New LP Partner',
        email: 'newlp@paperworking.io',
        entityType: 'LLC',
        ownershipPct: 20,
      };

      const res = await POST(
        buildPostRequest({ action: 'save', party: partyData }),
        { params: Promise.resolve({ id: PROJECT_ID }) }
      );

      expect(res.status).toBe(200);
      const json = await res.json();
      expect(json.success).toBe(true);
      expect(json.completedFundCards).toContain('F2.1');
      expect(mockProjectUpdate).toHaveBeenCalledWith(
        expect.objectContaining({
          completedFundCards: expect.arrayContaining(['F2.1']),
          equityParties: expect.arrayContaining([
            expect.objectContaining({
              name: 'New LP Partner',
              entityType: 'LLC',
            }),
          ]),
        })
      );
    });

    it('should synchronize GP Co-investment into project capital stack', async () => {
      const gpParty = {
        id: 'party_gp_123',
        role: 'GP',
        name: 'Syndicate GP',
        email: 'gp@paperworking.io',
        entityType: 'LLC',
      };

      const res = await POST(
        buildPostRequest({ action: 'save', party: gpParty, gpCoInvestAmount: 15000_00 }),
        { params: Promise.resolve({ id: PROJECT_ID }) }
      );

      expect(res.status).toBe(200);
      const json = await res.json();
      expect(json.success).toBe(true);

      // Verify db update synced GP Co-investment to financials
      expect(mockProjectUpdate).toHaveBeenCalledWith(
        expect.objectContaining({
          financials: expect.objectContaining({
            capitalStack: expect.arrayContaining([
              expect.objectContaining({
                category: 'GP Co-investment',
                amount: 15000_00,
                status: 'Funded',
              }),
            ]),
          }),
        })
      );
    });

    it('should delete an equity party and remove its corresponding GP co-investment', async () => {
      // Seed with existing GP party and capital stack source
      mockProjectGet.mockResolvedValue({
        exists: true,
        data: () => ({
          ...mockProject,
          equityParties: [{ id: 'party_gp_del', role: 'GP', name: 'GP To Delete' }],
          financials: {
            capitalStack: [{ id: 'source_gp_1', category: 'GP Co-investment', amount: 10000_00 }],
          },
        }),
      });

      const res = await POST(
        buildPostRequest({ action: 'delete', partyId: 'party_gp_del' }),
        { params: Promise.resolve({ id: PROJECT_ID }) }
      );

      expect(res.status).toBe(200);
      const json = await res.json();
      expect(json.success).toBe(true);

      // Verify GP Co-investment was removed from the capital stack
      expect(mockProjectUpdate).toHaveBeenCalledWith(
        expect.objectContaining({
          financials: expect.objectContaining({
            capitalStack: [],
          }),
        })
      );
    });
  });
});

import { trackEvent, recordSearchTelemetry, recordConversionTelemetry, getSearchTelemetryData } from '@/actions/telemetry';

// Mock Firestore
let mockEventsStore: any[] = [];
let mockSearchesStore: any[] = [];
let mockUsers: Record<string, any> = {};

jest.mock('@/lib/firebase/admin', () => ({
  adminAuth: {
    verifyIdToken: async (idToken: string) => {
      if (idToken === 'token_admin') return { uid: 'user_admin' };
      throw new Error('Invalid token');
    },
  },
  adminDb: {
    collection: jest.fn((colName) => ({
      doc: jest.fn((docId = 'temp_id') => ({
        id: docId,
        set: jest.fn(async (payload: any) => {
          if (colName === 'telemetry_events') mockEventsStore.push(payload);
          if (colName === 'search_telemetry') mockSearchesStore.push(payload);
        }),
        get: jest.fn(async () => {
          let data = null;
          if (colName === 'users') data = mockUsers[docId];
          return {
            exists: !!data,
            data: () => data,
            id: docId,
          };
        }),
      })),
      get: jest.fn(async () => {
        const store = colName === 'telemetry_events' ? mockEventsStore : mockSearchesStore;
        return {
          forEach: (cb: (doc: any) => void) => {
            store.forEach((data) => cb({ data: () => data }));
          },
        };
      }),
    })),
  },
}));

var mockCapture = jest.fn();
jest.mock('@/lib/flags', () => ({
  __esModule: true,
  getPostHogServer: () => ({
    capture: mockCapture,
  }),
}));

describe('DM-44: Event Taxonomy & Conversion Funnel', () => {
  beforeEach(() => {
    mockEventsStore = [];
    mockSearchesStore = [];
    mockUsers = {};
    jest.clearAllMocks();
  });

  it('enforces Event Taxonomy on trackEvent and formats Firestore and PostHog outputs', async () => {
    await trackEvent(
      'deal_detail_viewed',
      {
        listingId: 'listing_123',
        mode: 'teaser',
        visibilityMode: 'PUBLIC_SOLICITED',
      },
      'session_token_123'
    );

    // Verify Firestore storage
    expect(mockEventsStore.length).toBe(1);
    expect(mockEventsStore[0]).toEqual(
      expect.objectContaining({
        eventType: 'deal_detail_viewed',
        listingId: 'listing_123',
        details: {
          listingId: 'listing_123',
          mode: 'teaser',
          visibilityMode: 'PUBLIC_SOLICITED',
        },
      })
    );

    // Verify hashed sessionId is present, not raw session_token_123
    expect(mockEventsStore[0].sessionId).toBeDefined();
    expect(mockEventsStore[0].sessionId).not.toBe('session_token_123');

    // Verify PostHog emission
    expect(mockCapture).toHaveBeenCalledWith(
      expect.objectContaining({
        event: 'deal_detail_viewed',
        properties: {
          listingId: 'listing_123',
          mode: 'teaser',
          visibilityMode: 'PUBLIC_SOLICITED',
        },
      })
    );
  });

  it('rejects PII fields (no email, phone, name, or raw search queries) in event properties', async () => {
    await recordSearchTelemetry({
      query: '1600 Pennsylvania Ave NW, Washington DC',
      placeId: 'place_whitehouse',
      resultCount: 1,
      resolved: true,
      sessionToken: 'token_xyz',
    });

    // Check search event
    expect(mockEventsStore.length).toBe(1);
    const event = mockEventsStore[0];
    expect(event.eventType).toBe('address_search_performed');

    // Properties should omit the raw address query string
    expect(event.details.query).toBeUndefined();
    expect(event.details.queryLength).toBe(39);
    expect(event.details.placeId).toBe('place_whitehouse');

    // Anonymized session ID
    expect(event.sessionId).toBeDefined();
    expect(event.sessionId).not.toBe('token_xyz');
  });

  it('maps legacy eventType conversions into taxonomy events seamlessly', async () => {
    await recordConversionTelemetry({
      eventType: 'deal_view',
      listingId: 'listing_abc',
      details: { mode: 'teaser', visibilityMode: 'PUBLIC_SOLICITED' },
      sessionToken: 'sess_123',
    });

    // The handler writes the raw legacy trace for compat and forwards the new taxonomy event
    const taxonomyEvent = mockEventsStore.find((e) => e.eventType === 'deal_detail_viewed');
    expect(taxonomyEvent).toBeDefined();
    expect(taxonomyEvent.details.listingId).toBe('listing_abc');
    expect(taxonomyEvent.details.mode).toBe('teaser');
  });

  it('computes the full 7-step conversion funnel correctly from real session metrics', async () => {
    // Populate sessions for all 7 steps of the funnel
    const sessSearch = 'token_s1';
    const sessView = 'token_s2';
    const sessInvite = 'token_s3';
    const sessResponse = 'token_s4';
    const sessExchange = 'token_s5';
    const sessIndication = 'token_s6';
    const sessSubscribe = 'token_s7';

    // 1. Search
    await recordSearchTelemetry({ query: '123 Main St', placeId: 'p1', resultCount: 2, resolved: true, sessionToken: sessSearch });
    // 2. View
    await trackEvent('deal_detail_viewed', { listingId: 'l1', mode: 'teaser', visibilityMode: 'PUBLIC_SOLICITED' }, sessView);
    // 3. Invite
    await trackEvent('deal_invitation_viewed', { listingId: 'l1', projectId: 'p1' }, sessInvite);
    // 4. Response
    await trackEvent('deal_terms_responded', { listingId: 'l1', projectId: 'p1', isCounter: false, amountCents: 5000000 }, sessResponse);
    // 5. Exchange
    await trackEvent('contact_details_exchanged', { listingId: 'l1', projectId: 'p1', recipientUid: 'u_leadInvestor' }, sessExchange);
    // 6. Indication
    await trackEvent('deal_interest_indicated', { listingId: 'l1', projectId: 'p1', type: 'amount', currency: 'USD', value: 50000 }, sessIndication);
    // 7. Subscribe
    await trackEvent('subscription_converted', { plan: 'Pro', subscriptionId: 'sub_123' }, sessSubscribe);

    // Verify mock db populated correctly
    expect(mockSearchesStore.length).toBe(1);
    expect(mockEventsStore.length).toBe(7); // 1 search taxonomy + 6 others

    // Retrieve funnel analysis
    mockUsers = {
      user_admin: { role: 'Admin', subscriptionPlan: 'Pro', subscriptionStatus: 'active' },
    };

    const data = await getSearchTelemetryData('token_admin');

    // Assert 7-step conversion session counts are correctly unique aggregated
    expect(data.conversions).toEqual(
      expect.objectContaining({
        search: 1, // Deduplicated unique session count
        view: 1,
        invitation: 1,
        response: 1,
        exchange: 1,
        indication: 1,
        subscribe: 1,
      })
    );
  });
});

