      }
    });

    it('should verify A->U dual-slot mappings exist and are distinct for critical loan/closing fields', () => {
      const dualSlotFields = [
        'purchase_price',
        'loan_amount',
        'loan_interest_rate',
        'loan_term',
        'loanOriginationPoints',
        'closing_costs',
        'cash_to_close',
