describe('Insights Metric Taxonomy & Classification Integrity', () => {
  it('should define the 10 Hero KPIs and verify their presence and calculation functions', () => {
    const heroKpiKeys = [
      'NOI',
      'CASH_FLOW',
      'CAP_RATE',
      'COC',
      'GRM',
      'DSCR',
      'IRR',
      'OCCUPANCY',
      'OER',
      'APPRECIATION',
