    // Verify transitions log was written
    expect(mockSubDocSet).toHaveBeenCalledWith(
      expect.objectContaining({
        fromStatus: 'Application-Submitted',
        toStatus: 'Processing',
        actor: expect.objectContaining({
          uid: OWNER_UID,
          name: 'Marcus Teammate'
        })
