      appraisalFileName: 'appraisal_report.pdf',
      appraisalFileUrl: 'https://storage/appraisal_report.pdf'
    };

    const req = new NextRequest(`http://localhost/api/projects/${PROJECT_ID}/loans/${LOAN_ID}`, {
      method: 'PATCH',
