    expect(stack[1].id).toBe('sba504-borrower-injection');
    expect(stack[1].amount).toBe(50000); // 10% of $500k
  });

  /* ═══ Timeline & Notification ════════════════════════════════════════════ */
  it('writes activity log on successful configuration', async () => {
    const req = buildRequest(defaultPayload);
    await POST(req, { params: Promise.resolve({ id: PROJECT_ID }) });
    expect(mockWriteActivityLog).toHaveBeenCalledTimes(1);
    expect(mockWriteActivityLog).toHaveBeenCalledWith(
      PROJECT_ID,
      OWNER_UID,
      expect.arrayContaining([
        expect.objectContaining({ fieldPath: 'financials.sbaInjectionTier' }),
      ]),
      'manual'
    );
  });

  it('fires notification on successful configuration', async () => {
    const req = buildRequest(defaultPayload);
    await POST(req, { params: Promise.resolve({ id: PROJECT_ID }) });
    expect(mockCreateNotification).toHaveBeenCalledTimes(1);
    expect(mockCreateNotification).toHaveBeenCalledWith(
      expect.objectContaining({
        type: 'LOAN_STATUS_UPDATE',
        objectReference: expect.objectContaining({
          task: expect.stringContaining('SBA 504 structure configured'),
        }),
      })
    );
  });

  /* ═══ Credit Context (Optional) ══════════════════════════════════════════ */
  it('stores optional credit scores with source provenance', async () => {
    const req = buildRequest({
      ...defaultPayload,
      paydexScore: 82,
      paydexSource: 'D&B Report, Feb 2026',
      sbssScore: 170,
      sbssSource: 'SBA Prescreen',
    });
    const res = await POST(req, { params: Promise.resolve({ id: PROJECT_ID }) });
    expect(res.status).toBe(200);

    const updateCalls = mockProjectDocUpdate.mock.calls;
    const lastCall = updateCalls[updateCalls.length - 1][0];
    expect(lastCall['financials.sbaPaydexScore']).toBe(82);
    expect(lastCall['financials.sbaPaydexSource']).toBe('D&B Report, Feb 2026');
    expect(lastCall['financials.sbaSbssScore']).toBe(170);
  });

  /* ═══ new_construction Flow ══════════════════════════════════════════════ */
  it('accepts valid new_construction with ten-year projection', async () => {
    const req = buildRequest({
      ...defaultPayload,
      occupancyType: 'new_construction',
      occupancyRate: 62,
      occupancyRateTenYears: 85,
      injectionTier: 15,
    });
    const res = await POST(req, { params: Promise.resolve({ id: PROJECT_ID }) });
    expect(res.status).toBe(200);
    const json = await res.json();
    expect(json.structure.cdcPct).toBe(35);
    expect(json.structure.injectionPct).toBe(15);

    const updateCalls = mockProjectDocUpdate.mock.calls;
    const lastCall = updateCalls[updateCalls.length - 1][0];
    expect(lastCall['financials.sbaOccupancyType']).toBe('new_construction');
    expect(lastCall['financials.sbaOccupancyRateTenYears']).toBe(85);
  });
});

/**
 * Scenario IRR — No Multiplier Regression Tests
 *
 * Background: dashboard/reports/page.tsx previously derived scenario IRRs by
 * scaling a baseIRR with multipliers (e.g. baseIRR * 0.7 for Conservative,
 * baseIRR * 1.2 for Aggressive). Those numbers were scaled fictions — editing
 * a scenario's vacancy or rent growth had no effect on the result.
 *
 * Fix (src/lib/projections/scenarioIRR.ts):
 *   - projectScenarioCashFlows() builds a real year-by-year cash-flow series
 *     from each scenario's assumption set (rentGrowthPct, vacancyPct,
 *     exitCapRate, appreciationPct, holdYears).
 *   - computeScenarioIRR() solves the internal rate of return from those flows
 *     via Newton-Raphson (computeIRR from reiMetrics.ts).
 *   - computeAllScenarioIRRs() runs all three presets through the same engine.
 *   - The IRRScenario card in reports passes `assumptions` so rent growth and
 *     vacancy display alongside each result.
 *
 * Evidence in tests:
 *   - No multiplier math exists in scenarioIRR.ts or reports/page.tsx (static).
 *   - Changing a single assumption (e.g. vacancy 5 → 12) changes IRR through
 *     the real model, hand-verifiable on a simple fixture.
 *   - Conservative/Base/Aggressive presets produce genuinely different IRRs
 *     (not a constant ratio of a base figure).
 *   - The three preset IRRs are ordered: Conservative < Base < Aggressive.
 *   - Assumptions display: IRRScenario renders `assumptions` prop.
 *   - Missing-input gate: projectScenarioCashFlows returns [] when required
 *     fields (purchasePrice, monthlyRent, totalCashInvested) are absent.
 */

import * as fs from 'fs';
import * as path from 'path';
import {
  projectScenarioCashFlows,
  computeScenarioIRR,
  computeAllScenarioIRRs,
  PRESET_SCENARIOS,
  type ScenarioAssumptions,
} from '../lib/projections/scenarioIRR';
import { computeIRR } from '../lib/metrics/reiMetrics';
import type { Project } from '../types/schema';

const SRC = path.resolve(__dirname, '..');
function read(rel: string) {
  return fs.readFileSync(path.join(SRC, rel), 'utf8');
