    expect(updatedInvite.indication.currency).toBe('EUR');

    expect(mockSendEmail).toHaveBeenCalled();
    const emailArgs = mockSendEmail.mock.calls[0][0];
    expect(emailArgs.html).toContain('EUR 50,000');
  });

