            listingId: 'listing_j1',
            inviterUid: 'user_lead_investor_seed',
            inviteeEmail: 'sub@paperworking.com',
            inviteeName: 'In-Platform subscriber',
            status: 'sent',
            visibilityMode: 'PRIVATE',
