}

/**
 * Decline or express interest in a Deal invitation.
 */
export async function respondToDealInvitation(
  idToken: string,
  projectId: string,
  response: 'declined' | 'interested'
): Promise<{ success: boolean }> {
  try {
    const caller = await verifyActionAuth(idToken);
    const emailLower = caller.email.toLowerCase();

    // Query active invitation
    const inviteSnap = await adminDb.collection('dealInvitations')
      .where('projectId', '==', projectId)
      .where('inviteeEmail', '==', emailLower)
      .limit(1)
      .get();

    if (inviteSnap.empty) {
      throw new Error('No invitation found for this deal.');
    }

    const inviteDoc = inviteSnap.docs[0];
    const inviteData = inviteDoc.data() as DealInvitation;

    const batch = adminDb.batch();
    const now = new Date().toISOString();

    // Update status
    batch.update(inviteDoc.ref, {
      status: response,
      respondedAt: now,
    });

    // Write Ledger response entry
    const ledgerRef = adminDb.collection('projects').doc(projectId)
      .collection('dealLedger').doc();
    const ledgerData: DealLedgerEntry = {
      id: ledgerRef.id,
      projectId,
      listingId: inviteData.listingId,
      eventType: 'INVITATION_RESPONSE',
      performedBy: caller.uid,
      inviteeEmail: emailLower,
      version: inviteData.version,
      visibilityMode: inviteData.visibilityMode,
      timestamp: now,
      metadata: {
        response,
        invitationId: inviteDoc.id,
      },
    };
    batch.set(ledgerRef, ledgerData);

    await batch.commit();

    // Track timeline activity
    await trackDealActivity(
      projectId,
      projectId,
      caller.uid,
      response === 'interested' ? 'interest' : 'decline',
      {
        inviteeEmail: emailLower,
      }
    ).catch(err => console.error('[respondToDealInvitation timeline tracking failed]', err));

    // Write Activity Log
    await writeActivityLog(projectId, caller.uid, [{
      fieldPath: `invitations.${emailLower.replace(/\./g, '_')}.status`,
      oldValue: inviteData.status,
      newValue: response,
    }], 'system');

    return { success: true };
  } catch (err) {
    console.error('respondToDealInvitation error:', err);
    throw err instanceof Error ? err : new Error('Failed to submit response.');
  }
}

/**
 * Fetch list of possible invite targets (contacts + subscribers).
 */
export async function getInviteTargets(
  idToken: string,
  projectId: string
): Promise<Array<{ email: string; name?: string; source: string }>> {
  try {
    if (process.env.NODE_ENV !== 'production' && (process.env.ENABLE_MOCK_AUTH === 'true' || process.env.NODE_ENV === 'test') && (idToken === 'mock_token' || idToken === 'mock_token_123' || idToken === 'mock_session_token_123')) {
      return [
        { email: 'sub@paperworking.com', name: 'Platform Subscriber', source: 'Platform Subscriber' },
        { email: 'external@gmail.com', name: 'External Email', source: 'Project Contact' }
      ];
    }

    const caller = await verifyActionAuth(idToken);
    const targets: Array<{ email: string; name?: string; source: string }> = [];

    // 1. Fetch project contacts
    const contactsSnap = await adminDb.collection('projects').doc(projectId)
      .collection('investor_contacts').get();
    for (const doc of contactsSnap.docs) {
      const data = doc.data();
      if (data.email) {
        targets.push({
          email: data.email,
          name: data.name || data.displayName,
          source: 'Project Contact',
        });
      }
    }

    // 2. Fetch existing platform subscribers
    const usersSnap = await adminDb.collection('users')
      .where('role', '==', 'Subscriber')
      .get();
    for (const doc of usersSnap.docs) {
      const data = doc.data();
      if (data.email && !targets.some(t => t.email.toLowerCase() === data.email.toLowerCase())) {
        targets.push({
          email: data.email,
          name: data.displayName || data.name,
          source: 'Platform Subscriber',
        });
      }
    }

    return targets;
  } catch (err) {
    console.error('getInviteTargets error:', err);
    return [];
  }
}

"use server";

import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';

// ─── Types ─────────────────────────────────────────────────────
export interface FinancialsPayload {
  income: {
    grossRent: number;
    otherIncome: number;
    vacancyRate: number;
  };
  expenses: {
    opex: number;
  };
  financing: {
    loanAmount: number;
    interestRate: number;
    loanTermYears: number;
    otherMonthlyDebt: number;
  };
}

interface FinancialsDoc extends FinancialsPayload {
  updatedAt: FirebaseFirestore.Timestamp | FieldValue;
  updatedBy: string;
}

// ─── Auth helper (mirrors verifyActionAuth in actions/index.ts) ─
async function verifyAuth(idToken: string) {
  if (!idToken) throw new Error('Unauthorized');
  try {
    let isE2eTest = false;
    let cookieStore: any = null;
    try {
      const { cookies } = require('next/headers');
      cookieStore = await cookies();
      isE2eTest = cookieStore?.get('__e2e_test')?.value === '1';
    } catch {
      // Ignored
    }
    if ((process.env.NODE_ENV !== 'production' || isE2eTest) && (process.env.ENABLE_MOCK_AUTH === 'true' || process.env.NODE_ENV === 'test') && (idToken === 'mock_token' || idToken === 'mock_token_123' || idToken === 'mock_session_token_123')) {
      const uid = cookieStore?.get('mock_user_uid')?.value || 'user_lead_investor_seed';
      const email = cookieStore?.get('mock_user_email')?.value || 'marcus@apexcapital.io';
      const name = cookieStore?.get('mock_user_name')?.value || 'Marcus Aurelius';
      const role = cookieStore?.get('mock_user_role')?.value || 'Lead Investor';
      const accountType = cookieStore?.get('mock_user_account_type')?.value || (role === 'Vendor' ? 'vendor' : 'investor');
      const subscriptionPlan = cookieStore?.get('mock_user_subscription_plan')?.value || 'Team';
      const subscriptionStatus = subscriptionPlan === 'None' ? 'inactive' : 'active';
      const organizationId = cookieStore?.get('mock_user_org_id')?.value || 'org_paperworking_seed';
      return {
        uid,
        email,
        displayName: name,
        role,
        accountType,
        subscriptionPlan,
        subscriptionStatus,
        organizationId,
      };
    }

    const decoded = await adminAuth.verifyIdToken(idToken);
    const userSnap = await adminDb.collection('users').doc(decoded.uid).get();
    if (!userSnap.exists) throw new Error('User profile not found.');
    const data = userSnap.data() as Record<string, unknown>;
    return { uid: decoded.uid, organizationId: data.organizationId as string, ...data };
  } catch {
    throw new Error('Unauthorized');
  }
}

// ─── Ownership / membership check ──────────────────────────────
async function verifyProjectAccess(projectRef: FirebaseFirestore.DocumentReference, uid: string, organizationId: string) {
  const snap = await projectRef.get();
  if (!snap.exists) throw new Error('Project not found.');
  const data = snap.data()!;

  // Owner check
  if (data.ownerUid === uid) return;

  // Organization match
  if (data.organizationId === organizationId) return;

  // Team membership check
  if (data.members?.[uid]) return;
  if (Array.isArray(data.assignedUsers) && data.assignedUsers.includes(uid)) return;

  throw new Error('You do not have access to this project.');
}

/**
 * SAVE FINANCIALS
 * Persists the Financials Terminal inputs to Firestore
 * at projects/{projectId}/financials/current
 */
export async function saveFinancials(
  idToken: string,
  projectId: string,
  data: FinancialsPayload
): Promise<{ success: true }> {
  const user = await verifyAuth(idToken);
  const projectRef = adminDb.collection('projects').doc(projectId);

  await verifyProjectAccess(projectRef, user.uid, user.organizationId);

  // Validate payload shape
  if (!data.income || !data.expenses || !data.financing) {
    throw new Error('Invalid financials payload — income, expenses, and financing are required.');
  }

  const doc: FinancialsDoc = {
    income: {
      grossRent: Number(data.income.grossRent) || 0,
      otherIncome: Number(data.income.otherIncome) || 0,
      vacancyRate: Number(data.income.vacancyRate) || 0,
    },
    expenses: {
      opex: Number(data.expenses.opex) || 0,
    },
    financing: {
      loanAmount: Number(data.financing.loanAmount) || 0,
      interestRate: Number(data.financing.interestRate) || 0,
      loanTermYears: Number(data.financing.loanTermYears) || 0,
      otherMonthlyDebt: Number(data.financing.otherMonthlyDebt) || 0,
    },
    updatedAt: FieldValue.serverTimestamp(),
    updatedBy: user.uid,
  };

  await adminDb
    .collection('projects')
    .doc(projectId)
    .collection('financials')
    .doc('current')
    .set(doc, { merge: true });

  return { success: true };
}

/**
 * LOAD FINANCIALS
 * Reads projects/{projectId}/financials/current from Firestore
 * Returns null if the document doesn't exist yet (first visit)
 */
export async function loadFinancials(
  idToken: string,
  projectId: string
): Promise<FinancialsPayload | null> {
  const user = await verifyAuth(idToken);
  const projectRef = adminDb.collection('projects').doc(projectId);

  await verifyProjectAccess(projectRef, user.uid, user.organizationId);

  const snap = await projectRef.collection('financials').doc('current').get();

  if (!snap.exists) return null;

  const d = snap.data()!;
  return {
    income: {
      grossRent: d.income?.grossRent ?? 0,
      otherIncome: d.income?.otherIncome ?? 0,
      vacancyRate: d.income?.vacancyRate ?? 0,
    },
    expenses: {
      opex: d.expenses?.opex ?? 0,
    },
    financing: {
      loanAmount: d.financing?.loanAmount ?? 0,
      interestRate: d.financing?.interestRate ?? 0,
      loanTermYears: d.financing?.loanTermYears ?? 0,
      otherMonthlyDebt: d.financing?.otherMonthlyDebt ?? 0,
    },
  };
}

