// ── Constants ────────────────────────────────────────────

const LISTINGS_COLLECTION = 'dealListings';
const POSTING_ROLES = ['Lead Investor', 'Platform Admin', 'Admin'];
const ADMIN_ROLES = ['Platform Admin', 'Admin'];

