    } catch (notifErr) {
      console.error('Failed to send final terms confirmation notification:', notifErr);
    }

    return { success: true };
  } catch (err) {
    console.error('confirmFinalTerms error:', err);
    throw err instanceof Error ? err : new Error('Failed to confirm final terms.');
  }
}

