// ─────────────────────────────────────────────────────────
// 6. CONFIRM TRANSACTION NUMBERS (Investor only → pre-fills Cap Table)
// ─────────────────────────────────────────────────────────

export async function confirmTransactionNumbers(
  idToken: string,
  negotiationId: string
): Promise<{ success: boolean }> {
  try {
    const user = await verifyActionAuth(idToken);
    rejectVendor(user);

    const negRef = adminDb.collection('negotiations').doc(negotiationId);
    const negSnap = await negRef.get();
    if (!negSnap.exists) throw new Error('Negotiation thread not found.');

    const neg = negSnap.data() as Negotiation;
    if (neg.investorUid !== user.uid) {
      throw new Error('Only the responding investor can confirm final transaction numbers.');
    }

    const leadTxn = neg.confirmations?.transactionLead;
    if (!leadTxn) {
      throw new Error('Lead Investor has not recorded transaction details yet.');
    }

    const now = new Date().toISOString();
    const rounds = [...(neg.rounds || [])];
    const currentVersion = (neg.currentTerms?.version ?? 0) + 1;

    // Record investor confirmation
    const transactionInvestor = {
      confirmedAt: now,
      priceBasis: leadTxn.priceBasis,
      contribution: leadTxn.contribution,
      equityPercentage: leadTxn.equityPercentage,
    };

    const confirmRound: NegotiationRound = {
      version: currentVersion,
      type: 'message',
      senderUid: user.uid,
      senderName: user.displayName || user.email || 'Investor',
      createdAt: now,
      note: `Confirmed final transaction numbers. Price basis: $${(leadTxn.priceBasis / 100).toLocaleString()} · Contribution: $${(leadTxn.contribution / 100).toLocaleString()} · Equity: ${leadTxn.equityPercentage}%.`,
    };
    rounds.push(confirmRound);

    // Build unique ID for record, versioning increments if correction superseded it
    const recordId = `${negotiationId}_txn`;
    const oldRecordVersion = neg.transactionConfirmationRecord?.version ?? 0;

    const transactionConfirmationRecord = {
      id: recordId,
      confirmedAt: now,
      priceBasis: leadTxn.priceBasis,
      contribution: leadTxn.contribution,
      equityPercentage: leadTxn.equityPercentage,
      locked: true,
      version: oldRecordVersion + 1,
      createdAt: neg.transactionConfirmationRecord?.createdAt || now,
    };

    await negRef.update({
      status: 'transaction_confirmed',
      'confirmations.transactionInvestor': transactionInvestor,
      transactionConfirmationRecord,
      rounds,
      updatedAt: now,
    });

    // Write to projects/{projectId}/commitments subcollection with status 'cleared' (confirmed)
    // This pre-fills the Fund's Investment Team cap table (fractionalInvestors) via legacy sync.
    try {
      const commitmentsRef = adminDb.collection('projects').doc(neg.projectId).collection('commitments');
      await commitmentsRef.doc(negotiationId).set({
        id: negotiationId,
        projectId: neg.projectId,
        listingId: neg.listingId,
        name: neg.investorName,
        email: neg.investorEmail,
        amountCents: leadTxn.contribution,
        status: 'cleared', // Cleared corresponds to 'confirmed' status on Cap Table
        notes: `Marketplace Ingested Transaction (Double-Confirmed). Ref ID: ${negotiationId}`,
        createdAt: now,
        updatedAt: now,
      });

      // Invoke the Cap Table sync bridge
      await syncFractionalInvestorFromCommitment(neg.projectId, {
        id: negotiationId,
        name: neg.investorName,
        email: neg.investorEmail,
        amountCents: leadTxn.contribution,
        status: 'cleared',
      });
    } catch (syncErr) {
      console.error('Failed to sync transaction to project cap table:', syncErr);
    }

    // Notify Lead Investor
    try {
      await NotificationService.createNotification({
        recipientId: neg.leadInvestorUid,
        type: 'NEGOTIATION_UPDATE',
        actor: { uid: user.uid, name: user.displayName || user.email || 'Investor' },
        objectReference: {
          projectId: neg.projectId,
          metadata: {
            negotiationId,
            subject: 'Transaction Fully Confirmed & Locked',
            body: `${user.displayName || user.email} has confirmed final transaction numbers. Transaction locked. Partner cap table has been pre-filled.`,
          },
        },
        deepLinkUrl: `/dashboard/inbox?negotiationId=${negotiationId}`,
      });
    } catch (notifErr) {
      console.error('Failed to send transaction confirmation notification:', notifErr);
    }

    return { success: true };
  } catch (err) {
    console.error('confirmTransactionNumbers error:', err);
    throw err instanceof Error ? err : new Error('Failed to confirm transaction numbers.');
  }
}

// ─────────────────────────────────────────────────────────
// 7. CORRECT TRANSACTION RECORD (Lead Investor only)
// ─────────────────────────────────────────────────────────

export async function correctTransactionRecord(
  idToken: string,
  negotiationId: string,
  newNumbers: {
    priceBasisCents: number;
    contributionCents: number;
    equityPct: number;
  }
): Promise<{ success: boolean }> {
  try {
    const user = await verifyActionAuth(idToken);
    rejectVendor(user);

    const negRef = adminDb.collection('negotiations').doc(negotiationId);
    const negSnap = await negRef.get();
    if (!negSnap.exists) throw new Error('Negotiation thread not found.');

    const neg = negSnap.data() as Negotiation;
    if (neg.leadInvestorUid !== user.uid) {
      throw new Error('Only the Lead Investor can correct transaction records.');
    }

    const currentRecord = neg.transactionConfirmationRecord;
    if (!currentRecord || !currentRecord.locked) {
      throw new Error('There is no locked transaction record to correct.');
    }

    const now = new Date().toISOString();
    const rounds = [...(neg.rounds || [])];
    const currentVersion = (neg.currentTerms?.version ?? 0) + 1;

    // Log the correction proposal round
    const correctionRound: NegotiationRound = {
      version: currentVersion,
      type: 'message',
      senderUid: user.uid,
      senderName: user.displayName || user.email || 'Lead Investor',
      createdAt: now,
      note: `PROPOSED CORRECTION to locked transaction. Old numbers superseded. New proposed numbers: Price basis: $${(newNumbers.priceBasisCents / 100).toLocaleString()} · Contribution: $${(newNumbers.contributionCents / 100).toLocaleString()} · Equity: ${newNumbers.equityPct}%. Pending investor confirmation.`,
    };
    rounds.push(correctionRound);

    // Create a new version of the transaction record, marked as unlocked (pending) and linking to the previous superseded record
    const supersededRecord = {
      id: `${negotiationId}_txn_v${currentRecord.version}`,
      confirmedAt: currentRecord.confirmedAt,
      priceBasis: currentRecord.priceBasis,
      contribution: currentRecord.contribution,
      equityPercentage: currentRecord.equityPercentage,
      locked: false, // unlocked pending confirmation
      supersededById: currentRecord.id || `${negotiationId}_txn`,
      version: currentRecord.version + 1,
      createdAt: now,
    };

    await negRef.update({
      status: 'transaction_pending',
      'confirmations.transactionLead': {
        confirmedAt: now,
        priceBasis: newNumbers.priceBasisCents,
        contribution: newNumbers.contributionCents,
        equityPercentage: newNumbers.equityPct,
      },
      'confirmations.transactionInvestor': FieldValue.delete(),
      transactionConfirmationRecord: supersededRecord,
      rounds,
      updatedAt: now,
    });

    // Notify investor
    try {
      await NotificationService.createNotification({
        recipientId: neg.investorUid,
        type: 'NEGOTIATION_UPDATE',
        actor: { uid: user.uid, name: user.displayName || user.email || 'Lead Investor' },
        objectReference: {
          projectId: neg.projectId,
          metadata: {
            negotiationId,
            subject: 'Transaction Correction Proposed',
            body: `${user.displayName || user.email} has proposed a correction to the transaction record for ${neg.projectName}. Review and confirm new final numbers in your inbox.`,
          },
        },
        deepLinkUrl: `/dashboard/inbox?negotiationId=${negotiationId}`,
      });
    } catch (notifErr) {
      console.error('Failed to send correction notification:', notifErr);
    }

    return { success: true };
  } catch (err) {
    console.error('correctTransactionRecord error:', err);
    throw err instanceof Error ? err : new Error('Failed to correct transaction record.');
  }
}

"use server";

import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { isSubscriptionActive } from '@/lib/stripe/subscription';
import { NotificationService } from '@/lib/services/notificationService';
import { logOrgActivity } from '@/lib/firebase/orgActivityWriter';
import { writeActivityLog } from '@/lib/firebase/activityLogWriter';
import type { UserProfile } from '@/types/user';

/* ═══════════════════════════════════════════════════════
   Card F4.3 — RFP & Bids Server Actions

   Slot-scoped RFP dispatch and bid acceptance.
   Sub-collection: projects/{projectId}/rfpBids/{bidId}

   Reuses the existing vendorAssignment pipeline:
   - vendorAssignments (project-level)
   - vendorRequests (project-level, for vendor portal)
   - vendorInbox (user-level, for vendor's inbox)
   ═══════════════════════════════════════════════════════ */

// ── Valid F4 slot keys ─────────────────────────────────────────────────────
const VALID_SLOT_KEYS = [
  'f4TitleEscrowVendor',
  'f4ClosingAttorneyVendor',
  'f4AppraiserVendor',
  'f4EnvironmentalVendor',
  'f4SurveyorVendor',
  'f4InsuranceBrokerVendor',
  'f4CdcVendor',
  'f4HardMoneyLenderVendor',
] as const;

type SlotKey = typeof VALID_SLOT_KEYS[number];

const SLOT_LABELS: Record<string, string> = {
  f4TitleEscrowVendor: 'Title / Escrow',
  f4ClosingAttorneyVendor: 'Closing Attorney',
  f4AppraiserVendor: 'Appraiser',
  f4EnvironmentalVendor: 'Environmental Consultant',
  f4SurveyorVendor: 'Surveyor',
  f4InsuranceBrokerVendor: 'Insurance Broker',
  f4CdcVendor: 'CDC (SBA 504)',
  f4HardMoneyLenderVendor: 'Private / Hard-Money Lender',
};

// ── Auth helper ────────────────────────────────────────────────────────────
interface VerifiedUser {
  uid: string;
  displayName: string;
  email: string;
  organizationId: string;
  personalOrganizationId: string;
  memberships?: Record<string, unknown>;
  membershipScopes?: Record<string, { isScoped: boolean; scopedProjectIds: string[] }>;
  [key: string]: unknown;
}

async function verifyAuth(idToken: string): Promise<VerifiedUser> {
  if (!idToken) throw new Error('Missing authentication token.');
  const decoded = await adminAuth.verifyIdToken(idToken);
  const snap = await adminDb.collection('users').doc(decoded.uid).get();
  if (!snap.exists) throw new Error('User profile not found.');
  return { uid: decoded.uid, ...snap.data() } as VerifiedUser;
}

function hasProjectAccess(
  profile: VerifiedUser,
  targetOrgId: string | undefined,
  projectId?: string
): boolean {
  if (!targetOrgId) return false;
  const orgMember =
    profile.personalOrganizationId === targetOrgId ||
    profile.organizationId === targetOrgId ||
    (profile.memberships != null && Boolean(profile.memberships[targetOrgId]));
  if (!orgMember) return false;
  if (projectId && profile.membershipScopes) {
    const scope = profile.membershipScopes[targetOrgId];
    if (scope?.isScoped) {
      return Array.isArray(scope.scopedProjectIds) && scope.scopedProjectIds.includes(projectId);
    }
  }
  return true;
}

/** Generate a short unique ID for RFP grouping */
function generateRfpId(): string {
  return `rfp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
}

/* ──────────────────────────────────────────────────────
   1. ISSUE SLOT RFP
   Dispatches an RFP to multiple vendors for a specific
   F4 team slot. Creates vendorAssignment + rfpBid docs
   for each vendor.
   ────────────────────────────────────────────────────── */
export async function issueSlotRfp(
  idToken: string,
  projectId: string,
  slotKey: string,
  vendorUids: string[],
  message?: string,
  urgency?: 'standard' | 'rush' | 'asap',
  desiredTimeline?: string
): Promise<{ success: boolean; rfpId?: string; bidIds?: string[]; error?: string }> {
  try {
    // ── Validate inputs ──────────────────────────────────────────────────
    if (!VALID_SLOT_KEYS.includes(slotKey as SlotKey)) {
      return { success: false, error: `Invalid slot key: ${slotKey}` };
    }

    if (!vendorUids || vendorUids.length === 0) {
      return { success: false, error: 'At least one vendor is required.' };
    }

    if (vendorUids.length > 10) {
      return { success: false, error: 'Maximum 10 vendors per RFP.' };
    }

    // ── Auth & access ────────────────────────────────────────────────────
    const user = await verifyAuth(idToken);
    const hasActiveSub = isSubscriptionActive(user as unknown as UserProfile);
    if (!hasActiveSub) {
      return { success: false, error: 'An active subscription is required.' };
    }

    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return { success: false, error: 'Project not found.' };
    }
    const projectData = projectSnap.data()!;

    if (!hasProjectAccess(user, projectData.organizationId, projectId)) {
      return { success: false, error: 'Access denied.' };
    }

    // ── Generate shared RFP ID ───────────────────────────────────────────
    const rfpId = generateRfpId();
    const slotLabel = SLOT_LABELS[slotKey] || slotKey;
    const serviceType = slotLabel;
    const actorName = user.displayName || user.email || 'Investor';
    const dealAddress = projectData.propertyName || projectData.address?.street || 'the project';
    const bidIds: string[] = [];

    // ── Create assignment + bid for each vendor ──────────────────────────
    const batch = adminDb.batch();

    for (const vendorUid of vendorUids) {
      // Verify vendor exists
      const vendorSnap = await adminDb.collection('users').doc(vendorUid).get();
      if (!vendorSnap.exists) continue;

      const vendorData = vendorSnap.data()!;
      const vendorProfile = vendorData.vendorProfile || vendorData;
      const vendorName = vendorProfile.companyName || vendorData.displayName || 'Unknown Vendor';

      // 1. Create vendorAssignment doc
      const assignmentRef = adminDb
        .collection('projects')
        .doc(projectId)
        .collection('vendorAssignments')
        .doc();

      const assignmentId = assignmentRef.id;

      batch.set(assignmentRef, {
        id: assignmentId,
        projectId,
        vendorId: vendorUid,
        vendorName,
        vendorCompanyName: vendorName,
        serviceType,
        requestedBy: user.uid,
        requestedByName: actorName,
        status: 'PENDING',
        message: message?.trim() || null,
        urgency: urgency ?? 'standard',
        desiredTimeline: desiredTimeline?.trim() || null,
        rfpId, // tag so we can group them
        slotKey,
        createdAt: FieldValue.serverTimestamp(),
        updatedAt: FieldValue.serverTimestamp(),
      });

      // 2. Create vendorInbox entry
      const inboxRef = adminDb
        .collection('users')
        .doc(vendorUid)
        .collection('vendorInbox')
        .doc(assignmentId);

      batch.set(inboxRef, {
        assignmentId,
        projectId,
        projectName: projectData.propertyName || dealAddress,
        projectAddress: projectData.address?.street || 'N/A',
        investorId: user.uid,
        investorName: actorName,
        serviceType,
        message: message?.trim() || null,
        urgency: urgency ?? 'standard',
        desiredTimeline: desiredTimeline?.trim() || null,
        status: 'PENDING',
        rfpId,
        slotKey,
        createdAt: FieldValue.serverTimestamp(),
      });

      // 3. Create vendorRequest (for vendor portal collection group)
      const requestRef = adminDb
        .collection('projects')
        .doc(projectId)
        .collection('vendorRequests')
        .doc(assignmentId);

      batch.set(requestRef, {
        id: assignmentId,
        projectId,
        vendorUid,
        serviceType,
        type: serviceType,
        message: message?.trim() || null,
        urgency: urgency ?? 'standard',
        desiredTimeline: desiredTimeline?.trim() || null,
        status: 'PENDING',
        requestedAt: FieldValue.serverTimestamp(),
        requestedBy: user.uid,
        requestedByName: actorName,
        rfpId,
        slotKey,
      });

      // 4. Create rfpBid doc (new for F4.3)
      const bidRef = adminDb
        .collection('projects')
        .doc(projectId)
        .collection('rfpBids')
        .doc();

      const bidId = bidRef.id;
      bidIds.push(bidId);

      batch.set(bidRef, {
        id: bidId,
        rfpId,
        slotKey,
        vendorUid,
        vendorName,
        vendorCompanyName: vendorName,
        price: null,
        turnaroundDays: null,
        notes: '',
        status: 'PENDING',
        assignmentId,
        createdAt: FieldValue.serverTimestamp(),
      });
    }

    await batch.commit();

    // ── Notifications (non-blocking) ─────────────────────────────────────
    for (const vendorUid of vendorUids) {
      NotificationService.createNotification({
        type: 'VENDOR_LEAD',
        recipientId: vendorUid,
        actor: { uid: user.uid, name: actorName },
        objectReference: {
          projectId,
          task: `RFP: ${slotLabel}`,
          dealAddress,
        },
        deepLinkUrl: `/dashboard/inbox`,
      }).catch((err) => {
        console.error('[RFP] Notification failed (non-critical):', err);
      });
    }

    // ── Timeline / Activity (non-blocking) ───────────────────────────────
    if (projectData.organizationId) {
      logOrgActivity({
        organizationId: projectData.organizationId,
        type: 'phase_change',
        actorId: user.uid,
        actorName,
        summary: `Issued RFP for ${slotLabel} to ${vendorUids.length} vendor${vendorUids.length > 1 ? 's' : ''}`,
        projectId,
        projectName: projectData.propertyName || dealAddress,
      });
    }

    writeActivityLog(projectId, user.uid, [{
      fieldPath: `rfp.${slotKey}`,
      oldValue: null,
      newValue: `RFP issued to ${vendorUids.length} vendor(s)`,
    }], 'manual').catch(() => {});

    return { success: true, rfpId, bidIds };
  } catch (error: any) {
    console.error('[RFP] issueSlotRfp error:', error);
    if (error.message === 'Missing authentication token.' || error.message === 'User profile not found.') {
      return { success: false, error: 'Session expired. Please log in again.' };
    }
    return { success: false, error: 'Failed to issue RFP.' };
  }
}

/* ──────────────────────────────────────────────────────
   2. ACCEPT SLOT BID
   Assigns the winning vendor to the F4 team slot,
   cancels all other bids in the same rfpId group.
   ────────────────────────────────────────────────────── */
export async function acceptSlotBid(
  idToken: string,
  projectId: string,
  bidId: string
): Promise<{ success: boolean; error?: string }> {
  try {
    const user = await verifyAuth(idToken);

    // ── Fetch bid ────────────────────────────────────────────────────────
    const bidRef = adminDb.collection('projects').doc(projectId).collection('rfpBids').doc(bidId);
    const bidSnap = await bidRef.get();
    if (!bidSnap.exists) {
      return { success: false, error: 'Bid not found.' };
    }
    const bid = bidSnap.data()!;

    if (bid.status === 'ACCEPTED') {
      return { success: false, error: 'This bid has already been accepted.' };
    }
    if (bid.status === 'CANCELLED' || bid.status === 'DECLINED') {
      return { success: false, error: `Cannot accept a ${bid.status.toLowerCase()} bid.` };
    }

    // ── Verify project access ────────────────────────────────────────────
    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return { success: false, error: 'Project not found.' };
    }
    const projectData = projectSnap.data()!;

    if (!hasProjectAccess(user, projectData.organizationId, projectId)) {
      return { success: false, error: 'Access denied.' };
    }

    // ── Fetch vendor for structured assignment ───────────────────────────
    const vendorSnap = await adminDb.collection('users').doc(bid.vendorUid).get();
    const vendorData = vendorSnap.exists ? vendorSnap.data()! : {};
    const vendorProfile = vendorData.vendorProfile || vendorData;

    // ── Build F4VendorAssignment record ──────────────────────────────────
    const now = new Date().toISOString();
    const vendorRecord = {
      name: bid.vendorName || vendorProfile.companyName || 'Vendor',
      firm: bid.vendorCompanyName || null,
      phone: vendorProfile.phone || null,
      email: vendorData.email || null,
      source: 'marketplace' as const,
      marketplaceVendorId: bid.vendorUid,
      assignedAt: now,
      assignedBy: user.uid,
    };

    const batch = adminDb.batch();

    // 1. Assign F4 slot
    const slotKey = bid.slotKey;
    const updatePath = `financials.${slotKey}`;
    const projectRef = adminDb.collection('projects').doc(projectId);
    batch.update(projectRef, { [updatePath]: vendorRecord });

    // 2. Mark winning bid as ACCEPTED
    batch.update(bidRef, {
      status: 'ACCEPTED',
      acceptedAt: FieldValue.serverTimestamp(),
    });

    // 3. Mark winning assignment as ACCEPTED
    const assignmentRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('vendorAssignments')
      .doc(bid.assignmentId);
    batch.update(assignmentRef, {
      status: 'ACCEPTED',
      updatedAt: FieldValue.serverTimestamp(),
      respondedAt: FieldValue.serverTimestamp(),
    });

    // 3b. Mark winning vendor inbox as ACCEPTED
    const inboxRef = adminDb
      .collection('users')
      .doc(bid.vendorUid)
      .collection('vendorInbox')
      .doc(bid.assignmentId);
    batch.update(inboxRef, {
      status: 'ACCEPTED',
      updatedAt: FieldValue.serverTimestamp(),
    });

    // 4. Cancel all other bids in the same rfpId
    const otherBidsSnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('rfpBids')
      .where('rfpId', '==', bid.rfpId)
      .get();

    const cancelledVendorUids: string[] = [];

    for (const doc of otherBidsSnap.docs) {
      if (doc.id === bidId) continue;
      const otherBid = doc.data();
      if (otherBid.status === 'PENDING' || otherBid.status === 'QUOTED') {
        batch.update(doc.ref, { status: 'CANCELLED' });

        // Also cancel the linked assignment
        const otherAssignmentRef = adminDb
          .collection('projects')
          .doc(projectId)
          .collection('vendorAssignments')
          .doc(otherBid.assignmentId);
        batch.update(otherAssignmentRef, {
          status: 'CANCELLED',
          updatedAt: FieldValue.serverTimestamp(),
        });

        // Update vendor inbox
        const otherInboxRef = adminDb
          .collection('users')
          .doc(otherBid.vendorUid)
          .collection('vendorInbox')
          .doc(otherBid.assignmentId);
        batch.update(otherInboxRef, { status: 'CANCELLED' });

        cancelledVendorUids.push(otherBid.vendorUid);
      }
    }

    await batch.commit();

    // ── Notifications ────────────────────────────────────────────────────
    const actorName = user.displayName || user.email || 'Investor';
    const slotLabel = SLOT_LABELS[slotKey] || slotKey;
    const dealAddress = projectData.propertyName || projectData.address?.street || 'the project';

    // Winner notification
    NotificationService.createNotification({
      type: 'VENDOR_BID',
      recipientId: bid.vendorUid,
      actor: { uid: user.uid, name: actorName },
      objectReference: {
        projectId,
        task: `Your bid for ${slotLabel} has been accepted`,
        dealAddress,
      },
      deepLinkUrl: `/dashboard/inbox`,
    }).catch(() => {});

    // Cancellation notifications
    for (const vendorUid of cancelledVendorUids) {
      NotificationService.createNotification({
        type: 'VENDOR_BID',
        recipientId: vendorUid,
        actor: { uid: user.uid, name: actorName },
        objectReference: {
          projectId,
          task: `RFP for ${slotLabel} — another vendor was selected`,
          dealAddress,
        },
        deepLinkUrl: `/dashboard/inbox`,
      }).catch(() => {});
    }

    // ── Timeline ─────────────────────────────────────────────────────────
    writeActivityLog(projectId, user.uid, [{
      fieldPath: `financials.${slotKey}`,
      oldValue: null,
      newValue: `${bid.vendorName} assigned as ${slotLabel} from RFP`,
    }], 'manual').catch(() => {});

    if (projectData.organizationId) {
      logOrgActivity({
        organizationId: projectData.organizationId,
        type: 'phase_change',
        actorId: user.uid,
        actorName,
        summary: `${bid.vendorName} assigned as ${slotLabel} from RFP`,
        projectId,
        projectName: projectData.propertyName || dealAddress,
      });
    }

    // Enqueue timeline sync
    try {
      const { jobQueue } = await import('@/lib/queue/jobQueue');
      await jobQueue.enqueue('timeline_sync', { projectId });
    } catch (err: any) {
      console.error('Failed to enqueue timeline sync on acceptSlotBid:', err.message);
    }

    return { success: true };
  } catch (error: any) {
    console.error('[RFP] acceptSlotBid error:', error);
    return { success: false, error: 'Failed to accept bid.' };
  }
}

/* ──────────────────────────────────────────────────────
   3. GET SLOT RFP BIDS
   Returns all rfpBid docs for a project, optionally
   filtered by slot key. Grouped by rfpId.
   ────────────────────────────────────────────────────── */
export async function getSlotRfpBids(
  idToken: string,
  projectId: string,
  slotKey?: string
): Promise<{ success: boolean; bids?: any[]; error?: string }> {
  try {
    const user = await verifyAuth(idToken);

    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return { success: false, error: 'Project not found.' };
    }
    const projectData = projectSnap.data()!;

    if (!hasProjectAccess(user, projectData.organizationId, projectId)) {
      return { success: false, error: 'Access denied.' };
    }

    let ref: FirebaseFirestore.Query = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('rfpBids')
      .orderBy('createdAt', 'desc');

    if (slotKey && VALID_SLOT_KEYS.includes(slotKey as SlotKey)) {
      ref = ref.where('slotKey', '==', slotKey);
    }

    const snap = await ref.get();

    const bids = snap.docs.map((doc) => {
      const data = doc.data();
      return {
        ...data,
        id: doc.id,
        createdAt: data.createdAt?.toDate?.()?.toISOString() || null,
        quotedAt: data.quotedAt?.toDate?.()?.toISOString() || null,
        acceptedAt: data.acceptedAt?.toDate?.()?.toISOString() || null,
      };
    });

    return { success: true, bids };
  } catch (error: any) {
    console.error('[RFP] getSlotRfpBids error:', error);
    return { success: false, error: 'Failed to fetch bids.' };
  }
}

'use server';

import { adminDb } from '@/lib/firebase/admin';
import type { DealLedgerEntry } from '@/types/dealInvitation';

export interface TakedownReportInput {
  reporterName: string;
  reporterEmail: string;
  relationship: string;
  listingId?: string;
  propertyAddress?: string;
  reason: string;
  details: string;
}

/**
 * Public, unauthenticated server action to submit a takedown report
 * for a property deal listing.
 */
export async function submitTakedownReport(input: TakedownReportInput): Promise<{ success: boolean; ticketId: string }> {
  // Validate input
  if (!input.reporterName || !input.reporterEmail || !input.reason || !input.details) {
    throw new Error('Missing required report fields.');
  }

  const now = new Date();
  const slaDate = new Date(now.getTime() + 24 * 60 * 60 * 1000); // 24-hour response SLA

  const ticketRef = adminDb.collection('support_tickets').doc();
  const ticketId = ticketRef.id;

  let targetListingId = input.listingId || '';
  let targetProjectId = '';
  let targetAddress = input.propertyAddress || '';
  let visibilityMode = 'PUBLIC_SOLICITED';
  let version = 1;

  // Resolve matching listing and project
  if (targetListingId) {
    const listingSnap = await adminDb.collection('dealListings').doc(targetListingId).get();
    if (listingSnap.exists) {
      const listingData = listingSnap.data();
      targetProjectId = listingData?.projectId || '';
      targetAddress = listingData?.address || targetAddress;
      visibilityMode = listingData?.visibilityMode || 'PUBLIC_SOLICITED';
      version = listingData?.version || 1;

      // 1. Move deal listing to the interim review state: 'takedown_review'
      // This immediately removes public visibility without deleting any underlying data.
      await adminDb.collection('dealListings').doc(targetListingId).update({
        status: 'takedown_review',
        updatedAt: now.toISOString(),
      });

      // 2. Write immutable ledger event TAKEDOWN_REVIEW_STARTED
      const ledgerRef = adminDb.collection('projects').doc(targetProjectId)
        .collection('dealLedger').doc();
      const ledgerData: DealLedgerEntry = {
        id: ledgerRef.id,
        projectId: targetProjectId,
        listingId: targetListingId,
        eventType: 'TAKEDOWN_REVIEW_STARTED',
        performedBy: 'anonymous_reporter',
        inviteeEmail: input.reporterEmail,
        version,
        visibilityMode: visibilityMode as any,
        timestamp: now.toISOString(),
        metadata: {
          ticketId,
          reporterName: input.reporterName,
          relationship: input.relationship,
          reason: input.reason,
          details: input.details,
        },
      };
      await ledgerRef.set(ledgerData);
    }
  }

  // Create operator queue support ticket
  await ticketRef.set({
    ticketId,
    subject: `Property Takedown: ${targetAddress || targetListingId || 'Unspecified Property'}`,
    requesterName: input.reporterName,
    requesterEmail: input.reporterEmail,
    priority: 'high',
    status: 'open',
    category: 'Property Takedown',
    createdAt: now.toISOString(),
    updatedAt: now.toISOString(),
    assignee: 'Unassigned',
    responseSla: slaDate.toISOString(),
    metadata: {
      listingId: targetListingId,
      projectId: targetProjectId,
      relationship: input.relationship,
      reason: input.reason,
      details: input.details,
      propertyAddress: targetAddress,
    },
  });

  return { success: true, ticketId };
}

/**
 * Server action for platform operators to resolve a takedown report
 * in either direction (restoring or permanently withdrawing the deal).
 */
export async function resolveTakedownReport(
  idToken: string,
  ticketId: string,
  resolution: 'restore' | 'withdraw',
  notes: string
): Promise<{ success: boolean }> {
  const { adminAuth } = await import('@/lib/firebase/admin');
  const decoded = await adminAuth.verifyIdToken(idToken);
  if (!decoded.uid) throw new Error('Unauthenticated');

  // Verify caller has operator / platform admin permissions
  const userSnap = await adminDb.collection('users').doc(decoded.uid).get();
  const userData = userSnap.data();
  if (userData?.role !== 'Platform Admin' && userData?.role !== 'Admin') {
    throw new Error('Unauthorized');
  }

  const ticketSnap = await adminDb.collection('support_tickets').doc(ticketId).get();
  if (!ticketSnap.exists) throw new Error('Ticket not found');

  const ticket = ticketSnap.data();
  const { listingId, projectId } = ticket?.metadata || {};

  const now = new Date();

  if (listingId && projectId) {
    const listingSnap = await adminDb.collection('dealListings').doc(listingId).get();
    if (listingSnap.exists) {
      const listingData = listingSnap.data();
      const version = listingData?.version || 1;
      const visibilityMode = listingData?.visibilityMode || 'PUBLIC_SOLICITED';

      const batch = adminDb.batch();

      if (resolution === 'restore') {
        // Restore listing back to 'published'
        batch.update(adminDb.collection('dealListings').doc(listingId), {
          status: 'published',
          updatedAt: now.toISOString(),
        });

        // Write ledger entry
        const ledgerRef = adminDb.collection('projects').doc(projectId)
          .collection('dealLedger').doc();
        const ledgerData: DealLedgerEntry = {
          id: ledgerRef.id,
          projectId,
          listingId,
          eventType: 'TAKEDOWN_RESOLVED_RESTORED',
          performedBy: decoded.uid,
          inviteeEmail: ticket?.requesterEmail || '',
          version,
          visibilityMode: visibilityMode as any,
          timestamp: now.toISOString(),
          metadata: {
            ticketId,
            notes,
          },
        };
        batch.set(ledgerRef, ledgerData);
      } else {
        // Permanently withdraw the listing
        batch.update(adminDb.collection('dealListings').doc(listingId), {
          status: 'withdrawn',
          updatedAt: now.toISOString(),
        });

        // Write ledger entry
        const ledgerRef = adminDb.collection('projects').doc(projectId)
          .collection('dealLedger').doc();
        const ledgerData: DealLedgerEntry = {
          id: ledgerRef.id,
          projectId,
          listingId,
          eventType: 'TAKEDOWN_RESOLVED_WITHDRAWN',
          performedBy: decoded.uid,
          inviteeEmail: ticket?.requesterEmail || '',
          version,
          visibilityMode: visibilityMode as any,
          timestamp: now.toISOString(),
          metadata: {
            ticketId,
            notes,
          },
        };
        batch.set(ledgerRef, ledgerData);
      }

      // Close the ticket
      batch.update(adminDb.collection('support_tickets').doc(ticketId), {
        status: 'closed',
        updatedAt: now.toISOString(),
      });

      await batch.commit();
    }
  } else {
    // Ticket resolved without listing mapping
    await adminDb.collection('support_tickets').doc(ticketId).update({
      status: 'closed',
      updatedAt: now.toISOString(),
    });
  }

  return { success: true };
}

"use server";

import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import type { OrgTeamMember, InternalRole, TeamInvitation, Permission, AuditLog } from '@/types/schema';
import { cookies } from 'next/headers';
import { NotificationService } from '@/lib/services/notificationService';
import crypto from 'crypto';
import { assignVendorToProject } from '@/actions/vendorAssignment';

function escapeHtml(unsafe: string): string {
  return (unsafe || '').replace(/[&<"'>]/g, (m) => {
    switch (m) {
      case '&': return '&amp;';
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '"': return '&quot;';
      case "'": return '&#39;';
      default: return m;
    }
  });
}

async function getCallerUid(): Promise<string> {
  const cookieStore = await cookies();
  const token = cookieStore.get('__session')?.value;
  if (!token) throw new Error('Unauthorized: no session cookie.');
  const decoded = await adminAuth.verifyIdToken(token);
  return decoded.uid;
}

async function logAuditAction(
  organizationId: string,
  actorUid: string,
  actorName: string,
  action: AuditLog['action'],
  metadata: Record<string, any>,
  targetUid?: string,
  targetEmail?: string
) {
  const auditRef = adminDb.collection('auditLogs').doc();
  const log: AuditLog = {
    id: auditRef.id,
    organizationId,
    actorUid,
    actorName,
    action,
    targetUid,
    targetEmail,
    metadata,
    createdAt: new Date(),
  };
  await auditRef.set(log);
}

/**
 * Creates a tokenized team invitation and stores it in the `teamInvitations` collection.
 * Replaces the old array-based approach.
 */
export async function persistTeamInvite(member: OrgTeamMember): Promise<void> {
  const callerUid = await getCallerUid();

  const userSnap = await adminDb.collection('users').doc(callerUid).get();
  const userData = userSnap.data();

  if (!userData) throw new Error('User profile not found.');
  if (userData.subscriptionPlan !== 'Team') throw new Error('Team features require the Team plan.');
  if (userData.role !== 'Lead Investor' && userData.role !== 'Admin') {
    throw new Error('Only Lead Investors and Admins may invite team members.');
  }

  const organizationId: string = userData.organizationId;
  if (!organizationId) throw new Error('Organization not found for this account.');

  const orgRef = adminDb.collection('organizations').doc(organizationId);
  const orgSnap = await orgRef.get();
  if (!orgSnap.exists) throw new Error('Organization document not found.');
  const orgData = orgSnap.data()!;

  const existingMembers: OrgTeamMember[] = orgData.teamMembers ?? [];
  const activeMembers = existingMembers.filter((m: OrgTeamMember) => m.status !== 'removed');

  // Query pending invites
  const pendingInvitesSnap = await adminDb.collection('teamInvitations')
    .where('organizationId', '==', organizationId)
    .where('status', '==', 'pending')
    .get();

  const maxSeats: number = orgData.maxSeats ?? 10;
  const currentSeatUsage = activeMembers.length + pendingInvitesSnap.size;

  if (currentSeatUsage >= maxSeats) throw new Error(`Seat limit of ${maxSeats} reached.`);

  const alreadyMember = activeMembers.find(
    (m: OrgTeamMember) => m.email.toLowerCase() === member.email.toLowerCase()
  );
  if (alreadyMember) throw new Error('This email is already on the team.');

  const alreadyInvited = pendingInvitesSnap.docs.find(d => d.data().email.toLowerCase() === member.email.toLowerCase());
  if (alreadyInvited) throw new Error('This email already has a pending invitation.');

  const token = crypto.randomBytes(32).toString('hex');
  const now = new Date();
  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days

  const inviteRef = adminDb.collection('teamInvitations').doc();

  const scopedProjectIds: string[] = Array.isArray(member.scopedProjectIds) && member.scopedProjectIds.length > 0
    ? member.scopedProjectIds
    : member.assignedProjectIds.length > 0 ? member.assignedProjectIds : [];
  const isScoped = member.isScoped === true || (member.scope === 'project' && scopedProjectIds.length > 0);

  const inviteData = {
    id: inviteRef.id,
    token,
    organizationId,
    organizationName: orgData.name || 'Organization',
    email: member.email.toLowerCase(),
    role: member.internalRole,
    status: 'pending',
    invitedByUid: callerUid,
    invitedByName: userData.displayName || userData.email,
    createdAt: now,
    expiresAt,
    scopedProjectIds,
    isScoped,
    // Legacy compat: populate single-project field when exactly one project scoped
    ...(scopedProjectIds.length === 1 ? { invitedToProjectId: scopedProjectIds[0] } : {}),
    day3ReminderSent: false,
    day6ReminderSent: false,
  };

  await inviteRef.set(inviteData);

  await logAuditAction(
    organizationId,
    callerUid,
    userData.displayName || userData.email,
    'MEMBER_INVITED',
    { role: member.internalRole, isScoped, scopedProjectIds },
    undefined,
    inviteData.email
  );

  // Send Notification
  // Determine if the invitee exists in our users collection by email
  const inviteeSnap = await adminDb.collection('users').where('email', '==', inviteData.email).limit(1).get();
  if (!inviteeSnap.empty) {
    const inviteeDoc = inviteeSnap.docs[0];
    await NotificationService.createNotification({
      recipientId: inviteeDoc.id,
      type: 'TEAM_INVITE',
      actor: { uid: callerUid, name: inviteData.invitedByName },
      objectReference: {
        organizationId: inviteData.organizationId,
        organizationName: inviteData.organizationName,
      },
      deepLinkUrl: `/invite/team?token=${token}`,
      expiresAt: inviteData.expiresAt,
    });
  } else {
    // If they aren't registered yet, queue an email
    await adminDb.collection('queued_emails').add({
      recipientEmail: inviteData.email,
      status: 'pending',
      isBatchable: false,
      type: 'TEAM_INVITE',
      actorName: inviteData.invitedByName,
      deepLinkUrl: `${process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co'}/invite/team?token=${token}`,
      sendEmail: true,
      sendPush: false,
      title: `${escapeHtml(inviteData.invitedByName)} invited you to join team ${escapeHtml(inviteData.organizationName)}`,
      body: `You have been invited to join the organization '${inviteData.organizationName}'. Click to accept the invitation.`,
      subject: `${escapeHtml(inviteData.invitedByName)} invited you to join team ${escapeHtml(inviteData.organizationName)}`,
      html: `<p>${escapeHtml(inviteData.invitedByName)} invited you to join team ${escapeHtml(inviteData.organizationName)}.</p><a href="${process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co'}/invite/team?token=${token}">Accept Invitation</a>`,
      createdAt: FieldValue.serverTimestamp(),
      retryCount: 0,
      expiresAt: inviteData.expiresAt,
    });
  }
}

/**
 * Resends a pending team invitation, extending its expiry and queueing a new email/notification.
 */
export async function resendTeamInvite(email: string): Promise<void> {
  const callerUid = await getCallerUid();

  const userSnap = await adminDb.collection('users').doc(callerUid).get();
  const userData = userSnap.data();

  if (!userData) throw new Error('User profile not found.');
  if (userData.role !== 'Lead Investor' && userData.role !== 'Admin') {
    throw new Error('Only Lead Investors and Admins may resend team invitations.');
  }

  const organizationId: string = userData.organizationId;
  if (!organizationId) throw new Error('Organization not found for this account.');

  const invitesSnap = await adminDb.collection('teamInvitations')
    .where('organizationId', '==', organizationId)
    .where('email', '==', email.toLowerCase())
    .where('status', '==', 'pending')
    .limit(1)
    .get();

  if (invitesSnap.empty) {
    throw new Error('No pending invitation found for this email.');
  }

  const inviteDoc = invitesSnap.docs[0];
  const inviteData = inviteDoc.data() as TeamInvitation;

  const now = new Date();

  // Enforce 60-second rate limit to prevent spam
  const lastSent = inviteData.lastSentAt || inviteData.createdAt;
  if (lastSent) {
    const lastSentTime = (lastSent as any).toDate ? (lastSent as any).toDate().getTime() : new Date(lastSent).getTime();
    if (now.getTime() - lastSentTime < 60 * 1000) {
      throw new Error('Please wait at least 60 seconds between resend attempts.');
    }
  }

  const expiresAt = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days
  const token = crypto.randomBytes(32).toString('hex');

  await inviteDoc.ref.update({
    token,
    expiresAt,
    day3ReminderSent: false,
    day6ReminderSent: false,
    createdAt: now,
    lastSentAt: now,
  });

  await logAuditAction(
    organizationId,
    callerUid,
    userData.displayName || userData.email,
    'MEMBER_INVITED',
    { role: inviteData.role, resent: true },
    undefined,
    inviteData.email
  );

  const inviteeSnap = await adminDb.collection('users').where('email', '==', inviteData.email).limit(1).get();
  if (!inviteeSnap.empty) {
    const inviteeDoc = inviteeSnap.docs[0];
    await NotificationService.createNotification({
      recipientId: inviteeDoc.id,
      type: 'TEAM_INVITE',
      actor: { uid: callerUid, name: userData.displayName || userData.email },
      objectReference: {
        organizationId: inviteData.organizationId,
        organizationName: inviteData.organizationName,
      },
      deepLinkUrl: `/invite/team?token=${token}`,
      expiresAt,
    });
  } else {
    await adminDb.collection('queued_emails').add({
      recipientEmail: inviteData.email,
      status: 'pending',
      isBatchable: false,
      type: 'TEAM_INVITE',
      actorName: userData.displayName || userData.email,
      deepLinkUrl: `${process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co'}/invite/team?token=${token}`,
      sendEmail: true,
      sendPush: false,
      title: `${escapeHtml(userData.displayName || userData.email)} invited you to join team ${escapeHtml(inviteData.organizationName)}`,
      body: `You have been invited to join the organization '${inviteData.organizationName}'. Click to accept the invitation.`,
      subject: `${escapeHtml(userData.displayName || userData.email)} invited you to join team ${escapeHtml(inviteData.organizationName)}`,
      html: `<p>${escapeHtml(userData.displayName || userData.email)} invited you to join team ${escapeHtml(inviteData.organizationName)}.</p><a href="${process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co'}/invite/team?token=${token}">Accept Invitation</a>`,
      createdAt: FieldValue.serverTimestamp(),
      retryCount: 0,
      expiresAt,
    });
  }
}

/**
 * Accepts a tokenized team invitation.
 */
export async function acceptTeamInvitation(token: string): Promise<void> {
  const callerUid = await getCallerUid();

  const userSnap = await adminDb.collection('users').doc(callerUid).get();
  const userData = userSnap.data();
  if (!userData) throw new Error('User profile not found.');

  const invitesSnap = await adminDb.collection('teamInvitations').where('token', '==', token).limit(1).get();
  if (invitesSnap.empty) throw new Error('Invalid or expired invitation token.');

  const inviteDoc = invitesSnap.docs[0];
  const inviteData = inviteDoc.data() as TeamInvitation;

  const userEmails = [
    userData.email.toLowerCase(),
    ...(Array.isArray(userData.claimedEmails) ? userData.claimedEmails.map((e: string) => e.toLowerCase()) : [])
  ];
  if (!userEmails.includes(inviteData.email.toLowerCase())) {
    throw new Error('This invitation was sent to a different email address. Please sign in with the correct account.');
  }

  await adminDb.runTransaction(async (t) => {
    const tInviteSnap = await t.get(inviteDoc.ref);
    if (!tInviteSnap.exists) throw new Error('Invitation no longer exists.');
    const tInviteData = tInviteSnap.data() as TeamInvitation;

    if (tInviteData.status !== 'pending') throw new Error(`Invitation is already ${tInviteData.status}.`);
    if ((tInviteData.expiresAt as any).toDate() < new Date()) {
      t.update(inviteDoc.ref, { status: 'expired' });
      throw new Error('This invitation has expired.');
    }

    const orgRef = adminDb.collection('organizations').doc(tInviteData.organizationId);
    const orgSnap = await t.get(orgRef);
    if (!orgSnap.exists) throw new Error('Organization no longer exists.');

    t.update(inviteDoc.ref, { status: 'accepted' });

    // Resolve the authoritative scoped project list:
    // prefer new scopedProjectIds field; fall back to legacy invitedToProjectId for old invites.
    const resolvedScopedIds: string[] =
      Array.isArray(tInviteData.scopedProjectIds) && tInviteData.scopedProjectIds.length > 0
        ? tInviteData.scopedProjectIds
        : tInviteData.invitedToProjectId ? [tInviteData.invitedToProjectId] : [];

    const resolvedIsScoped = tInviteData.isScoped === true || resolvedScopedIds.length > 0;

    const newMember: OrgTeamMember = {
      id: callerUid,
      email: tInviteData.email,
      displayName: userData.displayName || userData.email,
      internalRole: tInviteData.role,
      assignedProjectIds: resolvedScopedIds,
      scopedProjectIds: resolvedScopedIds,
      isScoped: resolvedIsScoped,
      scope: resolvedIsScoped ? 'project' : 'tenant',
      invitedAt: tInviteData.createdAt,
      status: 'active',
    };

    t.update(orgRef, {
      teamMembers: FieldValue.arrayUnion(newMember),
      updatedAt: FieldValue.serverTimestamp(),
    });

    // Write scope onto the user's own document so per-project server actions
    // can enforce access without fetching the full org document.
    t.update(userSnap.ref, {
      [`memberships.${tInviteData.organizationId}`]: tInviteData.role,
      [`membershipScopes.${tInviteData.organizationId}`]: {
        isScoped: resolvedIsScoped,
        scopedProjectIds: resolvedScopedIds,
      },
      updatedAt: FieldValue.serverTimestamp(),
    });
  });
}

/**
 * Revokes a pending team invitation.
 */
export async function revokeTeamInvitation(inviteId: string): Promise<void> {
  const callerUid = await getCallerUid();

  const userSnap = await adminDb.collection('users').doc(callerUid).get();
  const userData = userSnap.data();

  if (!userData) throw new Error('User profile not found.');
  if (userData.role !== 'Lead Investor' && userData.role !== 'Admin') {
    throw new Error('Insufficient privileges.');
  }

  const inviteRef = adminDb.collection('teamInvitations').doc(inviteId);
  const inviteSnap = await inviteRef.get();
  if (!inviteSnap.exists) throw new Error('Invitation not found.');
  const inviteData = inviteSnap.data() as TeamInvitation;

  if (inviteData.organizationId !== userData.organizationId) {
    throw new Error('Unauthorized.');
  }

  if (inviteData.status !== 'pending') {
    throw new Error(`Cannot revoke invitation that is already ${inviteData.status}.`);
  }

  await inviteRef.update({ status: 'revoked' });
}

/**
 * Removes a team member from the organization (soft-delete via status).
 */
export async function removeTeamMember(memberId: string): Promise<void> {
  const callerUid = await getCallerUid();

  const userSnap = await adminDb.collection('users').doc(callerUid).get();
  const userData = userSnap.data();

  if (!userData) throw new Error('User profile not found.');
  if (userData.role !== 'Lead Investor' && userData.role !== 'Admin') {
    throw new Error('Insufficient privileges.');
  }

  const organizationId: string = userData.organizationId;
  const orgRef = adminDb.collection('organizations').doc(organizationId);
  const orgSnap = await orgRef.get();
  if (!orgSnap.exists) throw new Error('Organization not found.');

  const members: OrgTeamMember[] = orgSnap.data()?.teamMembers ?? [];
  const targetMember = members.find((m: OrgTeamMember) => m.id === memberId);
  if (!targetMember) throw new Error('Member not found.');

  // Guardrail: Cannot remove the last Lead Investor
  const targetUserSnap = await adminDb.collection('users').doc(memberId).get();
  if (targetUserSnap.exists && targetUserSnap.data()?.role === 'Lead Investor') {
    const allLeadInvestors = await adminDb.collection('users')
      .where('organizationId', '==', organizationId)
      .where('role', '==', 'Lead Investor')
      .get();
    if (allLeadInvestors.size <= 1) {
      throw new Error('Cannot remove the last Lead Investor of the organization.');
    }
  }

  const updated = members.map((m: OrgTeamMember) =>
    m.id === memberId ? { ...m, status: 'removed' as const } : m
  );

  const batch = adminDb.batch();

  batch.update(orgRef, {
    teamMembers: updated,
    updatedAt: FieldValue.serverTimestamp(),
  });

  // Guardrail: remove user's access token mapping to strictly drop permissions
  const targetUserRef = adminDb.collection('users').doc(memberId);
  batch.update(targetUserRef, {
    [`memberships.${organizationId}`]: FieldValue.delete(),
    updatedAt: FieldValue.serverTimestamp(),
  });

  // Mark tasks for reassignment
  const projectsSnap = await adminDb.collection('projects').where('organizationId', '==', organizationId).get();
  for (const pdoc of projectsSnap.docs) {
    const pdata = pdoc.data();
    const actionItems = pdata.actionItems || [];
    let updatedActionItems = false;
    const newActionItems = actionItems.map((item: any) => {
      if (item.assignee?.toLowerCase() === targetMember.email.toLowerCase()) {
        updatedActionItems = true;
        return { ...item, needsReassignment: true };
      }
      return item;
    });

    if (updatedActionItems) {
      batch.update(pdoc.ref, { actionItems: newActionItems });
    }
  }

  await batch.commit();

  await logAuditAction(
    organizationId,
    callerUid,
    userData.displayName || userData.email,
    'MEMBER_REMOVED',
    { previousRole: targetMember.internalRole },
    memberId,
    targetMember.email
  );
}

