import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 1. Fetch user projects
    const projectsSnap = await adminDb
      .collection('projects')
      .where('ownerUid', '==', uid)
      .get();

    const projects = projectsSnap.docs.map(doc => ({
      id: doc.id,
      propertyName: doc.data().propertyName || doc.data().address || 'Unnamed Project',
    }));

    const projectIds = projects.map(p => p.id);

    // 2. Fetch activity logs for all owned projects
    interface ActivityRow {
      projectName: string;
      userId: string;
      fieldPath: string;
      oldValue: string;
      newValue: string;
      source: string;
      timestamp: string;
    }

    const rows: ActivityRow[] = [];

    for (const project of projects) {
      const logsSnap = await adminDb
        .collection('projects')
        .doc(project.id)
        .collection('activityLog')
        .orderBy('timestamp', 'desc')
        .get();

      for (const logDoc of logsSnap.docs) {
        const data = logDoc.data();
        const timestampDate = data.timestamp?.toDate
          ? data.timestamp.toDate()
          : data.timestamp
          ? new Date(data.timestamp)
          : null;

        rows.push({
          projectName: project.propertyName,
          userId: data.userId || 'system',
          fieldPath: data.fieldPath || '',
          oldValue: JSON.stringify(data.oldValue ?? ''),
          newValue: JSON.stringify(data.newValue ?? ''),
          source: data.source || 'manual',
          timestamp: timestampDate ? timestampDate.toISOString() : '',
        });
      }
    }

    // 3. Compile CSV content
    let csv = 'Project,User ID,Field Path,Old Value,New Value,Source,Timestamp\n';

    const escapeCSV = (val: string) => {
      const clean = val.replace(/"/g, '""');
      return `"${clean}"`;
    };

    for (const row of rows) {
      csv += `${escapeCSV(row.projectName)},${escapeCSV(row.userId)},${escapeCSV(row.fieldPath)},${escapeCSV(row.oldValue)},${escapeCSV(row.newValue)},${escapeCSV(row.source)},${escapeCSV(row.timestamp)}\n`;
    }

    return new NextResponse(csv, {
      status: 200,
      headers: {
        'Content-Type': 'text/csv',
        'Content-Disposition': `attachment; filename=PaperWorking_AuditLog_${uid}.csv`,
        'Cache-Control': 'no-store, max-age=0',
      },
    });
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Audit Exporter] Error exporting CSV:', errMsg);
    return NextResponse.json(
      { error: 'Failed to compile audit CSV', details: errMsg },
      { status: 500 }
    );
  }
}

'use server';

import { google } from 'googleapis';
import { adminDb } from '@/lib/firebase/admin';

/**
 * Universal Document Hub (Google Drive Auto-folder generation)
 * 
 * Secure Backend function to authenticate to GCP via Service Account,
 * create a new folder structurally mapping to the specified Property,
 * and binding the new folderId to the Deal object in Firestore.
 */
export async function createPropertyDriveFolder(projectId: string, propertyName: string, ownerEmail: string) {
  try {
    // 1. Authenticate with Google Drive using a Service Account Key
    // Must be provided in env logic as GOOGLE_DRIVE_SERVICE_ACCOUNT_KEY
    if (!process.env.GOOGLE_DRIVE_SERVICE_ACCOUNT_KEY) {
      throw new Error('Google Drive Service Account Key missing. Cannot create Document Hub folder.');
    }

    const credentials = JSON.parse(process.env.GOOGLE_DRIVE_SERVICE_ACCOUNT_KEY);

    const auth = new google.auth.GoogleAuth({
      credentials,
      scopes: ['https://www.googleapis.com/auth/drive.file'],
    });

    const drive = google.drive({ version: 'v3', auth });

    // 2. Create the unified Hub Directory
    const folderMetadata = {
      name: `Property: ${propertyName} - ${projectId}`,
      mimeType: 'application/vnd.google-apps.folder',
      // Optional: Set a Master 'Properties' parent folder via parents: [MASTER_FOLDER_ID]
    };

    const folder = await drive.files.create({
      requestBody: folderMetadata,
      fields: 'id',
    });

    const folderId = folder.data.id;

    if (!folderId) {
      throw new Error('Failed to retrieve Folder ID from Google Drive');
    }

    // 3. Optional: Transfer Drive Folder Ownership or Share with OwnerEmail
    await drive.permissions.create({
      fileId: folderId,
      requestBody: {
        role: 'writer',
        type: 'user',
        emailAddress: ownerEmail,
      },
    });

    // 4. Update the Firestore Document with the external Hub pointer
    await adminDb.collection('projects').doc(projectId).update({
      documentHubFolderId: folderId,
      updatedAt: new Date()
    });

    return { success: true, folderId };
  } catch (error: any) {
    console.error('Google Drive Hub Error:', error);
    return { success: false, error: error.message };
  }
}

"use server";

import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';

export async function submitSupportMessage(formData: FormData): Promise<{ success: boolean; error?: string }> {
  try {
    const name = formData.get('name') as string;
    const email = formData.get('email') as string;
    const subject = formData.get('subject') as string;
    const message = formData.get('message') as string;

    if (!name || !email || !subject || !message) {
      return { success: false, error: 'All fields are required.' };
    }

    await adminDb.collection('support_messages').add({
      name,
      email,
      subject,
      message,
      createdAt: FieldValue.serverTimestamp(),
      status: 'new',
    });

    return { success: true };
  } catch (error: any) {
    console.error('Error submitting support message:', error);
    return { success: false, error: error.message || 'Failed to submit message.' };
  }
}

