            <circle cx="18" cy="18" r="15.9" fill="none" stroke="#f2f2f2" strokeWidth="3" />
            <circle
              cx="18" cy="18" r="15.9" fill="none" stroke="#0d0d0d" strokeWidth="3"
              strokeDasharray={`${(investors / total) * 100} ${100 - (investors / total) * 100}`}
              strokeLinecap="round"
            />
