        </div>
        <button
          onClick={handleRefresh}
          disabled={refreshing}
          className="flex items-center gap-2 px-3 py-2 text-xs font-semibold transition-colors border rounded"
          style={{
            borderColor: 'var(--border-ui)',
            color: 'var(--text-primary)',
            opacity: refreshing ? 0.5 : 1,
          }}
