        />
      ),
    },
    {
      key: 'projectCount',
      label: 'Projects',
      sortable: true,
      render: (row) => (
        <span className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
          {row.projectCount}
        </span>
      ),
    },
    {
      key: 'lastLoginAt',
      label: 'Last Login',
      sortable: true,
      render: (row) => (
        <span className="text-xs" style={{ color: 'var(--text-secondary)' }}>
          {row.lastLoginAt}
        </span>
      ),
    },
    {
      key: 'createdAt',
      label: 'Joined',
      sortable: true,
      render: (row) => (
        <span className="text-xs" style={{ color: 'var(--text-secondary)' }}>
          {row.createdAt}
        </span>
      ),
    },
