          <p className="text-sm" style={{ color: 'var(--text-secondary)' }}>Failed to load users.</p>
          <button onClick={handleRefresh} className="mt-2 text-xs font-semibold underline" style={{ color: 'var(--text-primary)' }}>Retry</button>
