import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb, adminAuth, adminStorage } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';
import Stripe from 'stripe';
import { telemetry } from '@/lib/telemetry';
import { CommunicationEngine } from '@/lib/engine/CommunicationEngine';
import * as admin from 'firebase-admin';

export const dynamic = 'force-dynamic';

function getStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY is not set');
  return new Stripe(key, { apiVersion: '2026-04-22.dahlia' as any });
}

export async function GET(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const jobSnap = await adminDb.collection('deletionJobs').doc(uid).get();
    if (!jobSnap.exists) {
      return NextResponse.json({ active: false });
    }

    return NextResponse.json({
      active: true,
      job: jobSnap.data()
    });
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    return NextResponse.json(
      { error: 'Failed to retrieve deletion status', details: errMsg },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest) {
  let uid = '';
  try {
    // 1. Authenticate user
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    uid = auth.uid;

    const jobRef = adminDb.collection('deletionJobs').doc(uid);
    let jobSnap = await jobRef.get();
    let jobData: any = null;

    // 2. Initialize Deletion Job if it doesn't exist
    if (!jobSnap.exists) {
      console.log(`[GDPR Delete] Initializing deletion job for user ${uid}`);

      const userDoc = await adminDb.collection('users').doc(uid).get();
      const userData = userDoc.exists ? userDoc.data() : {};

      const projectsSnap = await adminDb
        .collection('projects')
        .where('ownerUid', '==', uid)
        .get();
      const ownedProjectIds = projectsSnap.docs.map(doc => doc.id);

      const userAuth = await adminAuth.getUser(uid).catch(() => null);
      const userEmail = userAuth?.email || userData?.email || '';
      const displayName = userAuth?.displayName || userData?.displayName || 'User';

      jobData = {
        userId: uid,
        status: 'in_progress',
        step: 'start',
        stripeCustomerId: userData?.stripeCustomerId || null,
        stripeSubscriptionId: userData?.stripeSubscriptionId || null,
        ownedProjectIds,
        userEmail,
        userName: displayName,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        error: null,
      };

      await jobRef.set(jobData);
      jobSnap = await jobRef.get();

      // Emit Telemetry
      try {
        await telemetry.capture({
          distinctId: uid,
          event: 'account_deletion_started',
          properties: {
            userEmail,
            ownedProjectCount: ownedProjectIds.length,
            timestamp: new Date().toISOString(),
          }
        });
      } catch (telemetryErr) {
        console.error('[GDPR Delete] Telemetry start failed:', telemetryErr);
      }
    } else {
      jobData = jobSnap.data();
      if (jobData.status === 'completed') {
        return NextResponse.json({
          success: true,
          message: 'Account has already been fully deleted.',
          step: 'completed'
        });
      }

      // Resume job: set status back to in_progress and clear error
      console.log(`[GDPR Delete] Resuming deletion job for user ${uid} from step ${jobData.step}`);
      await jobRef.update({
        status: 'in_progress',
        error: null,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
    }

    const { stripeCustomerId, ownedProjectIds, userEmail, userName } = jobData;

    // ── CASCADE STEP 1: Stripe Cancel ──────────────────
    if (jobData.step === 'start') {
      console.log(`[GDPR Delete] Step 1/5: Canceling Stripe billing for user ${uid}`);
      if (stripeCustomerId) {
        try {
          const stripe = getStripe();
          const subs = await stripe.subscriptions.list({
            customer: stripeCustomerId,
            status: 'active',
          });
          for (const sub of subs.data) {
            await stripe.subscriptions.cancel(sub.id);
            console.log(`[GDPR Delete] Stripe subscription ${sub.id} cancelled`);
          }
        } catch (stripeErr: any) {
          console.error(`[GDPR Delete] Stripe subscription cancel failed (non-fatal):`, stripeErr.message);
        }
      }
      await jobRef.update({
        step: 'stripe_cancelled',
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
      jobData.step = 'stripe_cancelled';
    }

    // ── CASCADE STEP 2: Firestore Workspace Plane ─────────
    if (jobData.step === 'stripe_cancelled') {
      console.log(`[GDPR Delete] Step 2/5: Deleting Firestore data for user ${uid}`);

      // Delete solely-owned projects and their subcollections
      for (const projectId of ownedProjectIds) {
        console.log(`[GDPR Delete] Deleting owned project ${projectId}`);
        const projectRef = adminDb.collection('projects').doc(projectId);

        // Delete subcollections in batches
        const subcollections = [
          'ledgerItems', 'activityLog', 'vendorRequests', 'phaseSnapshots',
          'commitments', 'documents', 'financials',
        ];
        for (const sub of subcollections) {
          const snap = await projectRef.collection(sub).get();
          for (const d of snap.docs) {
            await d.ref.delete();
          }
        }

        // Delete project doc
        await projectRef.delete();

        // Delete propertyMetricSnapshots (top-level collection, keyed by projectId)
        const metricsSnap = await adminDb
          .collection('propertyMetricSnapshots')
          .where('projectId', '==', projectId)
          .get();
        for (const d of metricsSnap.docs) {
          await d.ref.delete();
        }

        // Delete projectFiles and projectFolders (top-level collections keyed by projectId)
        const projectFilesSnap = await adminDb
          .collection('projectFiles')
          .where('projectId', '==', projectId)
          .get();
        for (const d of projectFilesSnap.docs) {
          await d.ref.delete();
        }
        const projectFoldersSnap = await adminDb
          .collection('projectFolders')
          .where('projectId', '==', projectId)
          .get();
        for (const d of projectFoldersSnap.docs) {
          await d.ref.delete();
        }
      }

      // Cleanup memberships on shared projects (projects owned by others)
      // Fetch collaborations from Prisma first before Postgres deletion
      let sharedProjectIds: string[] = [];
      try {
        const collaborations = await prisma.projectCollaborator.findMany({
          where: { userId: uid },
          select: { projectId: true }
        });
        sharedProjectIds = collaborations
          .map(c => c.projectId)
          .filter(pid => !ownedProjectIds.includes(pid));
      } catch (prismaErr) {
        console.warn(`[GDPR Delete] Could not fetch shared projects from Prisma (continuing best-effort):`, prismaErr);
      }

      for (const sharedProjectId of sharedProjectIds) {
        console.log(`[GDPR Delete] Cleaning up membership/assignments on shared project ${sharedProjectId}`);
        const pRef = adminDb.collection('projects').doc(sharedProjectId);
        const pSnap = await pRef.get();
        if (pSnap.exists) {
          const pData = pSnap.data();
          const actionItems = pData?.actionItems || [];
          let updatedActionItems = false;
          const newActionItems = actionItems.map((item: any) => {
            if (item.assignee?.toLowerCase() === userEmail.toLowerCase()) {
              updatedActionItems = true;
              return { ...item, assignee: 'Deleted User', needsReassignment: true };
            }
            return item;
          });

          const updates: Record<string, any> = {
            [`members.${uid}`]: admin.firestore.FieldValue.delete()
          };
          if (updatedActionItems) {
            updates.actionItems = newActionItems;
          }
          await pRef.update(updates);
        }
      }

      // Remove from teamMembers array of all organizations
      const orgsSnap = await adminDb.collection('organizations').get();
      for (const orgDoc of orgsSnap.docs) {
        const orgData = orgDoc.data();
        const teamMembers = orgData.teamMembers || [];
        if (teamMembers.some((m: any) => m.id === uid)) {
          const updatedTeam = teamMembers.filter((m: any) => m.id !== uid);
          await orgDoc.ref.update({
            teamMembers: updatedTeam,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          });
        }
      }

      // Delete user's inboxItems
      const inboxRecMatches = await adminDb.collection('inboxItems').where('recipientUid', '==', uid).get();
      for (const doc of inboxRecMatches.docs) {
        await doc.ref.delete();
      }
      const inboxSendMatches = await adminDb.collection('inboxItems').where('senderUid', '==', uid).get();
      for (const doc of inboxSendMatches.docs) {
        await doc.ref.delete();
      }

      // Delete user's notifications
      const notifSnap = await adminDb.collection('notifications').where('recipientId', '==', uid).get();
      for (const doc of notifSnap.docs) {
        await doc.ref.delete();
      }

      // Cancel pending teamInvitations sent by this user
      const sentInvitesSnap = await adminDb
        .collection('teamInvitations')
        .where('inviterUid', '==', uid)
        .where('status', '==', 'pending')
        .get();
      for (const doc of sentInvitesSnap.docs) {
        await doc.ref.update({ status: 'cancelled', cancelledAt: admin.firestore.FieldValue.serverTimestamp() });
      }

      // Delete pending investor invitations sent by this user
      const sentInvestorInvitesSnap = await adminDb
        .collection('invitations')
        .where('invitedByUid', '==', uid)
        .where('status', '==', 'pending')
        .get();
      for (const doc of sentInvestorInvitesSnap.docs) {
        await doc.ref.delete();
      }

      // Delete pending investor invitations associated with this user's email
      if (userEmail) {
        const receivedInvestorInvitesSnap = await adminDb
          .collection('invitations')
          .where('email', '==', userEmail)
          .where('status', '==', 'pending')
          .get();
        for (const doc of receivedInvestorInvitesSnap.docs) {
          await doc.ref.delete();
        }
      }

      // Delete users/{uid}/sessions subcollection
      const sessionsSnap = await adminDb.collection('users').doc(uid).collection('sessions').get();
      for (const doc of sessionsSnap.docs) {
        await doc.ref.delete();
      }

      // Delete user profile document
      await adminDb.collection('users').doc(uid).delete();

      await jobRef.update({
        step: 'firestore_deleted',
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
      jobData.step = 'firestore_deleted';
    }

    // ── CASCADE STEP 3: Prisma REIL Plane ─────────────────
    if (jobData.step === 'firestore_deleted') {
      console.log(`[GDPR Delete] Step 3/5: Cleaning up Prisma DB for user ${uid}`);

      // 1. Ensure placeholder "deleted-user" AppUser exists
      await prisma.appUser.upsert({
        where: { id: 'deleted-user' },
        update: {},
        create: {
          id: 'deleted-user',
          email: 'deleted-user@paperworking.co',
          name: 'Deleted User',
        }
      });

      // 2. Reassign StatusEvents and FieldAssignments to placeholder
      await prisma.statusEvent.updateMany({
        where: { recordedById: uid },
        data: { recordedById: 'deleted-user' }
      });

      await prisma.fieldAssignment.updateMany({
        where: { assignedToId: uid },
        data: { assignedToId: 'deleted-user' }
      });

      await prisma.fieldAssignment.updateMany({
        where: { assignedById: uid },
        data: { assignedById: 'deleted-user' }
      });

      // 3. Delete ProjectCollaborator collaborations
      await prisma.projectCollaborator.deleteMany({
        where: { userId: uid }
      });

      // 4. Delete solely-owned ReilProjects (will cascade delete properties, comps, snapshosts, terms)
      await prisma.reilProject.deleteMany({
        where: { createdById: uid }
      });

      // 5. Delete AppUser record — deleteMany is idempotent (0 rows on a retry)
      await prisma.appUser.deleteMany({
        where: { id: uid }
      });

      await jobRef.update({
        step: 'prisma_deleted',
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
      jobData.step = 'prisma_deleted';
    }

    // ── CASCADE STEP 4: Firebase Storage ──────────────────
    if (jobData.step === 'prisma_deleted') {
      console.log(`[GDPR Delete] Step 4/5: Cleaning up Firebase Storage files for user ${uid}`);
      const bucket = adminStorage.bucket();

      // Delete owned projects' files
      for (const projectId of ownedProjectIds) {
        try {
          const [files] = await bucket.getFiles({ prefix: `projects/${projectId}/` });
          for (const file of files) {
            await file.delete();
          }
        } catch (storageErr: any) {
          console.warn(`[GDPR Delete] Storage files delete skipped for project ${projectId}:`, storageErr.message);
        }
      }

      // Delete user-scoped files
      try {
        const [files] = await bucket.getFiles({ prefix: `users/${uid}/` });
        for (const file of files) {
          await file.delete();
        }
      } catch (storageErr: any) {
        console.warn(`[GDPR Delete] Storage files delete skipped for user ${uid}:`, storageErr.message);
      }

      await jobRef.update({
        step: 'storage_deleted',
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });
      jobData.step = 'storage_deleted';
    }

    // ── CASCADE STEP 5: Firebase Auth User ────────────────
    if (jobData.step === 'storage_deleted') {
      console.log(`[GDPR Delete] Step 5/5: Deleting Firebase Auth credentials for user ${uid}`);

      // Revoke all refresh tokens immediately — prevents any existing token from
      // being exchanged for a new ID token between now and the final deleteUser call.
      try {
        await adminAuth.revokeRefreshTokens(uid);
      } catch (revokeErr: any) {
        if (revokeErr?.code !== 'auth/user-not-found') {
          console.warn(`[GDPR Delete] revokeRefreshTokens failed (non-fatal):`, revokeErr.message);
        }
      }

      // Delete user from Firebase Auth — ignore auth/user-not-found so a retry
      // doesn't block completion when the Auth record was already removed.
      try {
        await adminAuth.deleteUser(uid);
      } catch (authErr: any) {
        if (authErr?.code !== 'auth/user-not-found') throw authErr;
        console.warn(`[GDPR Delete] Auth user ${uid} already deleted — treating as success`);
      }

      await jobRef.update({
        status: 'completed',
        step: 'completed',
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      // Emit Telemetry
      try {
        await telemetry.capture({
          distinctId: uid,
          event: 'account_deletion_completed',
          properties: {
            userEmail,
            timestamp: new Date().toISOString(),
          }
        });
      } catch (telemetryErr) {
        console.error('[GDPR Delete] Telemetry complete failed:', telemetryErr);
      }

      // Send isolated confirmation email
      if (userEmail) {
        try {
          console.log(`[GDPR Delete] Sending confirmation email to ${userEmail}`);
          await CommunicationEngine.sendRawEmail(
            [userEmail],
            'Your PaperWorking account has been deleted',
            `<h1>Account Deleted</h1><p>Hi ${userName || 'there'},</p><p>This email confirms that your PaperWorking account and all associated data have been permanently deleted, as requested.</p><p><br/>Best,<br/>The PaperWorking Team</p>`
          );
        } catch (emailErr: any) {
          console.error('[GDPR Delete] Deletion confirmation email failed:', emailErr.message);
        }
      }
    }

    return NextResponse.json({
      success: true,
      message: 'Account deletion successfully completed.',
      step: 'completed'
    });

  } catch (error: any) {
    const errMsg = error?.message || String(error);
    console.error(`❌ [GDPR Delete] Failure on user ${uid}:`, errMsg);

    if (uid) {
      try {
        await adminDb.collection('deletionJobs').doc(uid).update({
          status: 'failed',
          error: errMsg,
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });

        // Emit failure telemetry
        await telemetry.capture({
          distinctId: uid,
          event: 'account_deletion_failed',
          properties: {
            error: errMsg,
            timestamp: new Date().toISOString(),
          }
        });
      } catch (dbErr) {
        console.error('[GDPR Delete] Failed to record error state in database:', dbErr);
      }
    }

    return NextResponse.json(
      { error: 'Account deletion cascade failed.', details: errMsg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb, adminStorage } from '@/lib/firebase/admin';
import JSZip from 'jszip';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 1. Fetch User Profile
    const userDoc = await adminDb.collection('users').doc(uid).get();
    if (!userDoc.exists) {
      return NextResponse.json({ error: 'User profile not found' }, { status: 404 });
    }
    const profile = { id: userDoc.id, ...userDoc.data() };

    // 2. Fetch Projects owned by the user
    const projectsSnap = await adminDb
      .collection('projects')
      .where('ownerUid', '==', uid)
      .get();

    const projects = projectsSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    const projectIds = projects.map(p => p.id);

    // 3. Fetch Ledger Items & Activity Logs for these projects
    const ledgers: Record<string, any[]> = {};
    const activityLogs: Record<string, any[]> = {};

    for (const projectId of projectIds) {
      // Fetch Ledger
      const ledgerSnap = await adminDb
        .collection('projects')
        .doc(projectId)
        .collection('ledgerItems')
        .get();
      ledgers[projectId] = ledgerSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));

      // Fetch Activity Log
      const logSnap = await adminDb
        .collection('projects')
        .doc(projectId)
        .collection('activityLog')
        .get();
      activityLogs[projectId] = logSnap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
    }

    // 4. Create ZIP
    const zip = new JSZip();
    zip.file('profile.json', JSON.stringify(profile, null, 2));
    zip.file('projects.json', JSON.stringify(projects, null, 2));
    zip.file('ledger_items.json', JSON.stringify(ledgers, null, 2));
    zip.file('activity_logs.json', JSON.stringify(activityLogs, null, 2));

    // 5. Download and package uploaded files
    if (projectIds.length > 0) {
      try {
        const filesSnap = await adminDb
          .collection('projectFiles')
          .where('projectId', 'in', projectIds)
          .get();

        const bucket = adminStorage.bucket();

        for (const doc of filesSnap.docs) {
          const fileData = doc.data();
          const storagePath = fileData.storagePath;
          if (storagePath) {
            try {
              const fileRef = bucket.file(storagePath);
              const [exists] = await fileRef.exists();
              if (exists) {
                const [content] = await fileRef.download();
                const safeName = (fileData.name || 'document').replace(/[^a-zA-Z0-9._-]/g, '_');
                zip.file(`files/project_${fileData.projectId}/${safeName}`, content);
              }
            } catch (err: any) {
              console.warn(`[GDPR download] Skipped storage file: ${storagePath}. Error:`, err.message);
            }
          }
        }
      } catch (storageErr: any) {
        console.warn('[GDPR download] Storage fetch failed. Continuing without files:', storageErr.message);
      }
    }

    const zipBuffer = await zip.generateAsync({ type: 'uint8array' });

    return new NextResponse(zipBuffer as any, {
      status: 200,
      headers: {
        'Content-Type': 'application/zip',
        'Content-Disposition': `attachment; filename=PaperWorking_GDPR_Export_${uid}.zip`,
        'Cache-Control': 'no-store, max-age=0',
      },
    });
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[GDPR download] Error compiling ZIP:', errMsg);
    return NextResponse.json(
      { error: 'Failed to compile data export bundle', details: errMsg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdminAuth } from '@/lib/firebase-admin/admin-guard';
import { adminDb } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await requireAdminAuth(req);
  if (auth instanceof NextResponse) return auth;

  const { id } = await params;

  try {
    // Lookup agent in Firestore or Prisma
    const userDoc = await adminDb.collection('users').doc(id).get();
    let userData = userDoc.exists ? userDoc.data() : null;

    if (!userData) {
      const pUser = (await prisma.user.findUnique({ where: { id } })) as any;
      if (pUser) {
        userData = {
          id: pUser.id,
          displayName: pUser.name,
          email: pUser.email,
          agentPersona: pUser.agentPersona,
          syntheticAgent: pUser.syntheticAgent,
          tier: pUser.tier || 'starter',
        };
      }
    }

    if (!userData) {
      return NextResponse.json({ error: 'Agent not found' }, { status: 404 });
    }

    const email = userData.email || '';
    const name = userData.displayName || userData.name || 'Synthetic Agent';

    // Create session token and response
    const response = NextResponse.json({
      success: true,
      redirectUrl: '/dashboard/command-center',
      agent: {
        id,
        email,
        name,
        persona: userData.agentPersona || 'investor',
      },
    });

    // Set auth session cookies for agent login
    response.cookies.set('__session', `mock_session_agent_${id}`, {
      path: '/',
      httpOnly: true,
      secure: process.env.NODE_ENV === 'production',
      sameSite: 'lax',
      maxAge: 86400,
    });

    response.cookies.set('mock_user_uid', id, { path: '/' });
    response.cookies.set('mock_user_email', email, { path: '/' });
    response.cookies.set('mock_user_name', name, { path: '/' });

    return response;
  } catch (err: any) {
    console.error('[Impersonate POST]', err);
    return NextResponse.json(
      { error: 'Failed to impersonate agent', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdminAuth } from '@/lib/firebase-admin/admin-guard';
import { adminDb, adminAuth } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';
import { getStripeServerClient } from '@/lib/stripe/client';

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await requireAdminAuth(req);
  if (auth instanceof NextResponse) return auth;

  const { id } = await params;

  try {
    // 1. Fetch user from Firestore or Prisma
    const userDoc = await adminDb.collection('users').doc(id).get();
    let userData = userDoc.exists ? userDoc.data() : null;

    if (!userData) {
      // try looking up by ID or email/handle
      const pUser = (await prisma.user.findFirst({
        where: {
          OR: [
            { id },
            { email: id },
            { email: { startsWith: 'marcus.chen' } },
          ],
        },
      })) as any;
      if (pUser) {
        userData = {
          id: pUser.id,
          displayName: pUser.name,
          email: pUser.email,
          agentPersona: pUser.agentPersona,
          syntheticAgent: pUser.syntheticAgent,
          stripeCustomerId: `cus_test_${id}`,
          stripeSubscriptionId: `sub_test_${id}`,
        };
      }
    }

    if (!userData) {
      return NextResponse.json({ error: 'Agent not found' }, { status: 404 });
    }

    const email = userData.email || '';
    const handle = userData.handle || (email ? email.split('@')[0].replace(/\./g, '_') : id);
    const possibleHandles = [handle, 'marcus_chen', 'dana_rodriguez', 'whitmore', 'robert_kim', 'eleanor_vance'];

    // 2. Fetch Projects
    let projectsSnap = await adminDb
      .collection('projects')
      .where('listedByAgent', '==', handle)
      .get();

    if (projectsSnap.empty) {
      // try querying by syntheticAgent = true
      projectsSnap = await adminDb
        .collection('projects')
        .where('syntheticAgent', '==', true)
        .get();
    }

    let projects = projectsSnap.docs
      .map((d) => ({ id: d.id, ...d.data() }))
      .filter((p: any) => possibleHandles.includes(p.listedByAgent) || p.listedByAgent?.includes(handle));

    if (projects.length === 0) {
      const pProjects = (await prisma.reilProject.findMany({
        where: { syntheticAgent: true },
      })) as any[];
      projects = pProjects.map((p) => ({
        id: p.id,
        title: p.displayName || p.name || 'Investment Project',
        strategy: p.propertyType || 'Investment',
        purchasePrice: p.purchasePriceCents ? Number(p.purchasePriceCents) / 100 : 250000,
        arv: p.targetProfitCents ? Number(p.targetProfitCents) / 100 : 400000,
        capRate: 7.5,
        monthlyCashFlow: 850,
      }));
    }

    // 3. Fetch Marketplace Listings
    const listingsSnap = await adminDb
      .collection('dealListings')
      .where('syntheticAgent', '==', true)
      .get();

    let listings = listingsSnap.docs.map((d) => ({ id: d.id, ...d.data() }));

    if (listings.length === 0) {
      const pListings = (await prisma.marketplaceListing.findMany({
        where: { syntheticAgent: true },
      })) as any[];
      listings = pListings.map((l) => ({
        id: l.id,
        title: l.title || 'Assignment Deal',
        status: 'Active',
        viewsCount: 24,
        inquiriesCount: 3,
      }));
    }

    // 4. Fetch Messages / Conversation Threads
    let agentMessages: any[] = [];
    try {
      const dbMsgs = await prisma.message.findMany({
        where: {
          OR: [
            { senderId: id },
            { recipientId: id },
          ],
        },
        include: {
          sender: { select: { name: true, email: true, agentPersona: true } },
          recipient: { select: { name: true, email: true, agentPersona: true } },
        },
        orderBy: { createdAt: 'desc' },
      });
      agentMessages = dbMsgs.map((m) => ({
        id: m.id,
        threadId: m.threadId,
        subject: m.subject,
        body: m.body,
        content: m.body,
        read: m.read,
        senderName: m.sender?.name || 'Agent',
        recipientName: m.recipient?.name || 'Agent',
        createdAt: m.createdAt.toISOString(),
        attachmentProjectId: m.attachmentProjectId,
      }));
    } catch (e) {
      console.warn('[AdminAgentCrew/[id] GET] Prisma message query error:', e);
    }

    if (agentMessages.length === 0) {
      const messagesSnap = await adminDb
        .collection('messages')
        .where('syntheticAgent', '==', true)
        .get();
      agentMessages = messagesSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
    }

    // 5. Subscription & Stripe Customer Info
    const stripeCustomerId = userData.stripeCustomerId || `cus_test_${handle}`;
    const stripeSubscriptionId = userData.stripeSubscriptionId || `sub_test_${handle}`;

    return NextResponse.json({
      success: true,
      agent: {
        id,
        uid: id,
        name: userData.displayName || userData.name || 'Marcus Chen',
        email,
        persona: userData.agentPersona || 'wholesaler',
        handle,
        company: userData.company || 'PaperWorking Synthetic Partner',
        phone: userData.phone || '+1 (555) 019-2834',
        avatarUrl: userData.photoURL || userData.avatarUrl || '',
        syntheticAgent: userData.syntheticAgent ?? true,
        subscription: {
          tier: userData.subscriptionPlan || userData.tier || 'starter',
          stripeCustomerId,
          stripeSubscriptionId,
          stripeStatus: userData.stripeStatus || 'active',
          stripeTestMode: true,
          nextBillingDate: new Date(Date.now() + 30 * 86400 * 1000).toISOString(),
          invoiceLink: `https://dashboard.stripe.com/test/customers/${stripeCustomerId}`,
          paymentMethodLast4: '4242',
        },
        portfolio: projects.length > 0 ? projects : [],
        marketplace: listings,
        messages: agentMessages,
      },
    });
  } catch (err: any) {
    console.error('[AdminAgentCrew/[id] GET]', err);
    return NextResponse.json(
      { error: 'Failed to fetch agent details', message: err.message },
      { status: 500 }
    );
  }
}

export async function DELETE(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const auth = await requireAdminAuth(req);
  if (auth instanceof NextResponse) return auth;

  const { id } = await params;

  try {
    // Fetch agent email and handle
    const userDoc = await adminDb.collection('users').doc(id).get();
    const userData = userDoc.exists ? userDoc.data() : null;
    const email = userData?.email || '';
    const handle = userData?.handle || email.split('@')[0] || id;
    const subId = userData?.stripeSubscriptionId;

    // 1. Cancel Stripe subscription if in test mode
    if (subId && subId.startsWith('sub_')) {
      try {
        const stripe = getStripeServerClient();
        await stripe.subscriptions.cancel(subId);
      } catch (e) {
        console.warn(`[DELETE Agent] Stripe cancel failed for ${subId}:`, e);
      }
    }

    // 2. Delete from Firebase Auth
    try {
      await adminAuth.deleteUser(id);
    } catch (e) {
      console.warn(`[DELETE Agent] Firebase Auth delete skipped for ${id}:`, e);
    }

    // 3. Delete from Firestore
    await adminDb.collection('users').doc(id).delete();

    const projSnap = await adminDb.collection('projects').where('listedByAgent', '==', handle).get();
    for (const doc of projSnap.docs) {
      await doc.ref.delete();
    }

    const listSnap = await adminDb.collection('dealListings').where('agentHandle', '==', handle).get();
    for (const doc of listSnap.docs) {
      await doc.ref.delete();
    }

    const msgSnap = await adminDb.collection('messages').where('senderEmail', '==', email).get();
    for (const doc of msgSnap.docs) {
      await doc.ref.delete();
    }

    // 4. Delete from Prisma
    await prisma.reilProject.deleteMany({ where: { listedByAgent: handle } });
    await prisma.marketplaceListing.deleteMany({ where: { userId: id } });
    await prisma.message.deleteMany({ where: { senderId: id } });
    await prisma.subscription.deleteMany({ where: { userId: id } });
    await prisma.user.deleteMany({ where: { id } });
    await prisma.appUser.deleteMany({ where: { id } });

    return NextResponse.json({
      success: true,
      message: `Successfully deleted synthetic agent ${id} and all associated records.`,
    });
  } catch (err: any) {
    console.error('[AdminAgentCrew/[id] DELETE]', err);
    return NextResponse.json(
      { error: 'Failed to delete synthetic agent', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdminAuth } from '@/lib/firebase-admin/admin-guard';
import { adminDb, adminAuth } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';
import { getStripeServerClient } from '@/lib/stripe/client';

export async function DELETE(req: NextRequest) {
  const auth = await requireAdminAuth(req);
  if (auth instanceof NextResponse) return auth;

  try {
    let usersDeleted = 0;
    let projectsDeleted = 0;
    let listingsDeleted = 0;
    let messagesDeleted = 0;
    let subscriptionsCanceled = 0;

    // 1. Fetch synthetic users from Firestore
    const usersSnap = await adminDb
      .collection('users')
      .where('syntheticAgent', '==', true)
      .get();

    const stripe = getStripeServerClient();

    for (const doc of usersSnap.docs) {
      const data = doc.data();
      const subId = data.stripeSubscriptionId;

      // Cancel Stripe test mode subscription via stripe.subscriptions.cancel()
      if (subId && typeof subId === 'string' && subId.startsWith('sub_')) {
        try {
          await stripe.subscriptions.cancel(subId);
          subscriptionsCanceled++;
        } catch (e) {
          console.warn(`[PurgeAll] Stripe cancel failed for ${subId}:`, e);
        }
      }

      // Delete Firebase Auth user
      try {
        await adminAuth.deleteUser(doc.id);
      } catch (e) {
        // user might not exist in Auth
      }

      // Delete user document
      await doc.ref.delete();
      usersDeleted++;
    }

    // 2. Delete synthetic projects from Firestore
    const projSnap = await adminDb
      .collection('projects')
      .where('syntheticAgent', '==', true)
      .get();

    for (const doc of projSnap.docs) {
      await doc.ref.delete();
      projectsDeleted++;
    }

    // 3. Delete synthetic listings from Firestore
    const listSnap = await adminDb
      .collection('dealListings')
      .where('syntheticAgent', '==', true)
      .get();

    for (const doc of listSnap.docs) {
      await doc.ref.delete();
      listingsDeleted++;
    }

    // 4. Delete synthetic messages from Firestore
    const msgSnap = await adminDb
      .collection('messages')
      .where('syntheticAgent', '==', true)
      .get();

    for (const doc of msgSnap.docs) {
      await doc.ref.delete();
      messagesDeleted++;
    }

    // Delete inboxItems synthetic entries
    const inboxSnap = await adminDb
      .collection('inboxItems')
      .where('syntheticAgent', '==', true)
      .get();
    for (const doc of inboxSnap.docs) {
      await doc.ref.delete();
    }

    // 5. Cascade delete in Prisma in correct order: Subscriptions → Messages → Listings → Projects → Users
    const prismaSubscriptions = await prisma.subscription.deleteMany({
      where: { syntheticAgent: true },
    });
    if (subscriptionsCanceled === 0) {
      subscriptionsCanceled = prismaSubscriptions.count;
    }

    const prismaMessages = await prisma.message.deleteMany({
      where: { syntheticAgent: true },
    });

    const prismaListings = await prisma.marketplaceListing.deleteMany({
      where: { syntheticAgent: true },
    });

    const prismaProjects = await prisma.reilProject.deleteMany({
      where: { syntheticAgent: true },
    });

    const prismaSqlProjects = await prisma.project.deleteMany({
      where: { syntheticAgent: true },
    });

    const prismaUsers = await prisma.user.deleteMany({
      where: { syntheticAgent: true },
    });

    const prismaAppUsers = await prisma.appUser.deleteMany({
      where: { syntheticAgent: true },
    });

    return NextResponse.json({
      success: true,
      message: 'Purged all synthetic agent data successfully.',
      usersDeleted,
      projectsDeleted,
      listingsDeleted,
      messagesDeleted,
      subscriptionsCanceled,
    });
  } catch (err: any) {
    console.error('[AdminAgentCrew/purge-all DELETE]', err);
    return NextResponse.json(
      { error: 'Failed to purge synthetic agent data', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAdminAuth } from '@/lib/firebase-admin/admin-guard';
import { adminDb } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';

export async function GET(req: NextRequest) {
