    // 1. Fetch synthetic agent users from Firestore
    const usersSnap = await adminDb
      .collection('users')
      .where('syntheticAgent', '==', true)
      .get();

    const firestoreUsers = usersSnap.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as any[];

