        company: u.company || 'PaperWorking Synthetic Partner',
        phone: u.phone || '+1 (555) 019-2834',
        avatarUrl: u.photoURL || u.avatarUrl || '',
        tier: u.subscriptionPlan || u.tier || 'starter',
        stripeCustomerId: u.stripeCustomerId || '',
        stripeSubscriptionId: u.stripeSubscriptionId || '',
        stripeStatus: u.stripeStatus || 'active',
        stripeTestMode: u.stripeTestMode ?? true,
        syntheticAgent: true,
      });
    }

    for (const u of prismaUsers) {
      if (!agentMap.has(u.id)) {
        agentMap.set(u.id, {
          id: u.id,
          uid: u.id,
          name: u.name || 'Synthetic Agent',
          email: u.email || '',
          persona: u.agentPersona || 'investor',
          handle: (u.email || 'agent').split('@')[0],
          company: u.company || 'PaperWorking Synthetic Partner',
          phone: u.phone || '+1 (555) 019-2834',
          avatarUrl: u.avatarUrl || '',
          tier: u.tier || 'starter',
          stripeCustomerId: u.stripeCustomerId || '',
          stripeSubscriptionId: u.stripeSubscriptionId || '',
          stripeStatus: u.stripeStatus || 'active',
          stripeTestMode: u.stripeTestMode ?? true,
          syntheticAgent: true,
        });
      }
    }

    const agents = Array.from(agentMap.values());

    // Aggregate stats per agent
    const agentsWithStats = await Promise.all(
      agents.map(async (agent) => {
        // Fetch projects count
        const projectsSnap = await adminDb
          .collection('projects')
          .where('listedByAgent', '==', agent.handle)
          .get();

        const prismaProjectCount = await prisma.reilProject.count({
          where: { listedByAgent: agent.handle },
        });

        const projectCount = Math.max(projectsSnap.size, prismaProjectCount, 3);

        // Fetch marketplace listings count
        const listingsSnap = await adminDb
          .collection('dealListings')
          .where('agentHandle', '==', agent.handle)
          .get();

        const prismaListingCount = await prisma.marketplaceListing.count({
          where: { userId: agent.id },
        });

        const listingCount = Math.max(listingsSnap.size, prismaListingCount, 1);

        // Fetch messages count
        const messagesSnap = await adminDb
          .collection('messages')
          .where('senderEmail', '==', agent.email)
          .get();

        const prismaMessageCount = await prisma.message.count({
          where: { senderId: agent.id },
        });

        const messageCount = Math.max(messagesSnap.size, prismaMessageCount, 1);

        return {
          ...agent,
          stats: {
            projectsCount: projectCount,
            listingsCount: listingCount,
            messagesCount: messageCount,
          },
        };
      })
    );

    return NextResponse.json({
      success: true,
      count: agentsWithStats.length,
      agents: agentsWithStats,
    });
  } catch (err: any) {
    console.error('[AdminAgentCrew GET]', err);
    return NextResponse.json(
      { error: 'Failed to fetch synthetic agents', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { DEFAULT_CHECKLIST_DEFINITIONS, parseChecklistsDoc } from '@/lib/providers/lenderChecklists';

/* ═══════════════════════════════════════════════════════════════
   GET  /api/admin/lender-checklists
     Returns the current checklist templates from Firestore, or
     DEFAULT_CHECKLIST_DEFINITIONS if the systemConfig doc hasn't been written.
     Auth: any authenticated user

   PUT  /api/admin/lender-checklists
     Replaces the checklists templates object.
     Body: { Conventional, "SBA 504", "Hard Money", Bridge }
     Auth: Lead Investor or Admin orgRole only
   ═══════════════════════════════════════════════════════════════ */

const CONFIG_DOC = adminDb.collection('systemConfig').doc('lenderChecklists');

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;

    const snap = await CONFIG_DOC.get();
    if (!snap.exists) {
      return NextResponse.json({
        checklists: DEFAULT_CHECKLIST_DEFINITIONS,
        updatedAt: null,
        updatedByEmail: null,
      });
    }

    const data = snap.data()!;
    const checklists = parseChecklistsDoc(data);

    return NextResponse.json({
      checklists,
      updatedAt: data.updatedAt?.toDate?.()?.toISOString() ?? null,
      updatedByEmail: data.updatedByEmail ?? null,
    });
  } catch (err: any) {
    console.error('[LenderChecklists GET]', err.message);
    return NextResponse.json({ error: 'Failed to fetch lender checklists' }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // Admin gate: Lead Investor or Admin orgRole
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }
    const userData = userSnap.data()!;
    const orgRole = userData.orgRole ?? '';
    const isAdmin = orgRole === 'Lead Investor' || orgRole === 'Admin';
    if (!isAdmin) {
      return NextResponse.json(
        { error: 'Only Lead Investors and Admins can update lender checklists' },
        { status: 403 }
      );
    }

    const body = await request.json();
    const { Conventional, 'SBA 504': sba504, 'Hard Money': hardMoney, Bridge } = body;

    // Validate parameters are arrays of strings
    if (Conventional && (!Array.isArray(Conventional) || !Conventional.every(item => typeof item === 'string'))) {
      return NextResponse.json({ error: 'Conventional must be an array of strings' }, { status: 422 });
    }
    if (sba504 && (!Array.isArray(sba504) || !sba504.every(item => typeof item === 'string'))) {
      return NextResponse.json({ error: 'SBA 504 must be an array of strings' }, { status: 422 });
    }
    if (hardMoney && (!Array.isArray(hardMoney) || !hardMoney.every(item => typeof item === 'string'))) {
      return NextResponse.json({ error: 'Hard Money must be an array of strings' }, { status: 422 });
    }
    if (Bridge && (!Array.isArray(Bridge) || !Bridge.every(item => typeof item === 'string'))) {
      return NextResponse.json({ error: 'Bridge must be an array of strings' }, { status: 422 });
    }

    const now = FieldValue.serverTimestamp();
    const updateData = {
      Conventional: Conventional || DEFAULT_CHECKLIST_DEFINITIONS.Conventional,
      'SBA 504': sba504 || DEFAULT_CHECKLIST_DEFINITIONS['SBA 504'],
      'Hard Money': hardMoney || DEFAULT_CHECKLIST_DEFINITIONS['Hard Money'],
      Bridge: Bridge || DEFAULT_CHECKLIST_DEFINITIONS.Bridge,
      updatedAt: now,
      updatedByUid: uid,
      updatedByEmail: userData.email ?? '',
    };

    await CONFIG_DOC.set(updateData);

    return NextResponse.json({ success: true, checklists: parseChecklistsDoc(updateData) });
  } catch (err: any) {
    console.error('[LenderChecklists PUT]', err.message);
    return NextResponse.json({ error: err.message ?? 'Failed to update lender checklists' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { DEFAULT_RATES, parseRatesDoc } from '@/lib/providers/lenderRates';

/* ═══════════════════════════════════════════════════════════════
   GET  /api/admin/lender-rates
     Returns the current lender rates from Firestore, or DEFAULT_RATES
     if the systemConfig doc hasn't been written yet.
     Auth: any authenticated user (rates are read-only for members)

   PUT  /api/admin/lender-rates
     Replaces the rates array. Caller must be orgRole 'Lead Investor'
     or 'Admin'. Each rate gets an asOf = serverTimestamp().
     Body: { rates: [{ id, name, interestRate, points, lenderFeesCents }] }
     Auth: Lead Investor or Admin only
   ═══════════════════════════════════════════════════════════════ */

const CONFIG_DOC = adminDb.collection('systemConfig').doc('lenderRates');

export async function GET(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;

    const snap = await CONFIG_DOC.get();
    if (!snap.exists) {
      return NextResponse.json({
        rates: DEFAULT_RATES.map((r) => ({ ...r, asOf: null })),
        updatedAt: null,
        updatedByEmail: null,
      });
    }

    const data = snap.data()!;
    const rates = parseRatesDoc(data).map((r) => ({
      ...r,
      asOf: r.asOf.getTime() === 0 ? null : r.asOf.toISOString(),
    }));

    return NextResponse.json({
      rates,
      updatedAt: data.updatedAt?.toDate?.()?.toISOString() ?? null,
      updatedByEmail: data.updatedByEmail ?? null,
    });
  } catch (err: any) {
    console.error('[LenderRates GET]', err.message);
    return NextResponse.json({ error: 'Failed to fetch lender rates' }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // Admin gate: Lead Investor or Admin orgRole
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }
    const userData = userSnap.data()!;
    const orgRole = userData.orgRole ?? '';
    const isAdmin = orgRole === 'Lead Investor' || orgRole === 'Admin';
    if (!isAdmin) {
      return NextResponse.json(
        { error: 'Only Lead Investors and Admins can update lender rates' },
        { status: 403 }
      );
    }

    const body = await request.json();
    if (!Array.isArray(body.rates) || body.rates.length === 0) {
      return NextResponse.json({ error: 'rates array is required' }, { status: 422 });
    }

    const now = FieldValue.serverTimestamp();
    const rates = body.rates.map((r: any) => {
      if (!r.id || typeof r.id !== 'string') throw new Error('Each rate needs an id');
      if (typeof r.interestRate !== 'number' || r.interestRate <= 0) throw new Error(`interestRate must be a positive number for ${r.id}`);
      if (typeof r.points !== 'number' || r.points < 0) throw new Error(`points must be >= 0 for ${r.id}`);
      if (typeof r.lenderFeesCents !== 'number' || r.lenderFeesCents < 0) throw new Error(`lenderFeesCents must be >= 0 for ${r.id}`);
      return {
        id:              r.id,
        name:            String(r.name ?? r.id),
        interestRate:    r.interestRate,
        points:          r.points,
        lenderFeesCents: Math.round(r.lenderFeesCents),
        asOf:            now,
      };
    });

    await CONFIG_DOC.set({
      rates,
      updatedAt:       now,
      updatedByUid:    uid,
      updatedByEmail:  userData.email ?? '',
    });

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[LenderRates PUT]', err.message);
    const status = err.message?.includes('Lead') ? 403 : err.message?.includes('required') || err.message?.includes('must') ? 422 : 500;
    return NextResponse.json({ error: err.message ?? 'Failed to update lender rates' }, { status });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError } from "@/lib/firebase-admin/auth-guard";
import { adminDb } from "@/lib/firebase/admin";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

// GET /api/admin/rentcast-usage
// Retrieve the number of RentCast API calls made in the current calendar month
export async function GET(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  // Optional: restrict to admin users if project had roles, but for now verifying auth token is sufficient
  const now = new Date();
  const year = now.getFullYear();
  const month = now.getMonth() + 1; // 1-indexed

  try {
    const logsRef = adminDb.collection("rentcastCallLogs");
    const query = logsRef
      .where("year", "==", year)
      .where("month", "==", month);

    const snapshot = await query.get();
    const count = snapshot.size;

    logger.info(`[Admin Usage API] Sourced RentCast calls for ${month}/${year}: ${count}`);

    return NextResponse.json({
      success: true,
      year,
      month,
      count,
      limit: 500,
    });
  } catch (err: any) {
    logger.error("[Admin Usage API] Failed to fetch RentCast call logs", err);
    return NextResponse.json(
      { error: "Failed to retrieve API usage stats." },
      { status: 500 }
    );
  }
}

