import { NextResponse } from 'next/server';
import { getUpcomingEvents } from '@/lib/calendar/google';
import { cookies } from 'next/headers';

export const dynamic = "force-dynamic";

export async function GET() {
  try {
    // 1. Verify user is authenticated
    const cookieStore = await cookies();
    const sessionCookie = cookieStore.get('__session')?.value;

    if (!sessionCookie) {
      return new NextResponse('Unauthorized', { status: 401 });
    }

    // Verify session
    const { adminAuth, adminDb } = await import('@/lib/firebase/admin');
    const decodedToken = await adminAuth.verifySessionCookie(sessionCookie, true);
    const uid = decodedToken.uid;

    // 2. Fetch user's refresh token
    const userDoc = await adminDb.collection('users').doc(uid).get();
    if (!userDoc.exists) {
      return new NextResponse('User not found', { status: 404 });
    }

    const userData = userDoc.data();
    const refreshToken = userData?.googleCalendarRefreshToken;

    if (!refreshToken) {
      return new NextResponse(JSON.stringify({ connected: false }), { 
        status: 200, 
        headers: { 'Content-Type': 'application/json' } 
      });
    }

    // 3. Fetch upcoming events
    try {
      const events = await getUpcomingEvents(refreshToken, 5);

      return new NextResponse(JSON.stringify({ 
        connected: true, 
        events: events.map((event: any) => ({
          id: event.id,
          summary: event.summary,
          start: (event.start as Record<string, string>)?.dateTime || (event.start as Record<string, string>)?.date,
          end: (event.end as Record<string, string>)?.dateTime || (event.end as Record<string, string>)?.date,
          htmlLink: event.htmlLink,
          location: event.location,
          conferenceData: event.conferenceData,
        }))
      }), { 
        status: 200,
        headers: { 'Content-Type': 'application/json' }
      });
    } catch (apiError: unknown) {
      const errorObj = apiError as { message?: string };
      // Handle revoked tokens or invalid grants
      if (errorObj.message && (errorObj.message.includes('invalid_grant') || errorObj.message.includes('revoked'))) {
        // Clear the invalid token
        await adminDb.collection('users').doc(uid).update({
          googleCalendarRefreshToken: null,
          updatedAt: new Date(),
        });
        return new NextResponse(JSON.stringify({ connected: false }), { 
          status: 200, 
          headers: { 'Content-Type': 'application/json' } 
        });
      }
      throw apiError;
    }
  } catch (error) {
    console.error('Error fetching calendar events:', error);
    return new NextResponse('Internal Server Error', { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { google } from 'googleapis';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';

/**
 * Google Calendar Event Sync
 *
 * Creates or updates a Calendar event tied to a deal milestone.
 *
 * POST /api/calendar/sync
 * Body: {
 *   idToken: string
 *   projectId: string
 *   eventType: 'inspection' | 'closing' | 'appraisal' | 'listing' | 'custom'
 *   title: string
 *   date: string          // ISO-8601 date string
 *   durationMinutes?: number  // default 60
 *   description?: string
 *   attendeeEmails?: string[]
 *   existingEventId?: string  // when updating
 * }
 */

type EventType = 'inspection' | 'closing' | 'appraisal' | 'listing' | 'custom';

const EVENT_COLORS: Record<EventType, number> = {
  inspection: 5,  // banana
  closing:    2,  // sage
  appraisal:  6,  // tangerine
  listing:    9,  // blueberry
  custom:     1,  // lavender
};

function buildGoogleAuth() {
  if (!process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL || !process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY) {
    return null;
  }
  return new google.auth.GoogleAuth({
    credentials: {
      client_email: process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL,
      private_key: process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY.replace(/\\n/g, '\n'),
    },
    scopes: ['https://www.googleapis.com/auth/calendar'],
  });
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const {
      idToken,
      projectId,
      eventType = 'custom',
      title,
      date,
      durationMinutes = 60,
      description = '',
      attendeeEmails = [],
      existingEventId,
    } = body;

    // ── Validation ─────────────────────────────────────────
    if (!idToken || !projectId || !title || !date) {
      return NextResponse.json(
        { error: 'Missing required fields: idToken, projectId, title, date' },
        { status: 400 },
      );
    }

    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    const [dealSnap, userSnap] = await Promise.all([
      adminDb.collection('projects').doc(projectId).get(),
      adminDb.collection('users').doc(uid).get(),
    ]);

    if (!dealSnap.exists) return NextResponse.json({ error: 'Deal not found.' }, { status: 404 });
    if (!userSnap.exists)  return NextResponse.json({ error: 'User not found.' }, { status: 404 });

    const dealData = dealSnap.data()!;
    const userData = userSnap.data()!;

    if (dealData.organizationId !== userData.organizationId) {
      return NextResponse.json({ error: 'Cross-tenant access denied.' }, { status: 403 });
    }

    const auth = buildGoogleAuth();
    if (!auth) {
      return NextResponse.json(
        { error: 'Google Service Account credentials missing. Cannot sync calendar.' },
        { status: 500 }
      );
    }

    // ── Live Google Calendar path ───────────────────────────
    const calendar = google.calendar({ version: 'v3', auth });

    const startDt = new Date(date);
    const endDt = new Date(startDt.getTime() + durationMinutes * 60_000);

    const eventBody = {
      summary: title,
      description: description || `PaperWorking deal milestone — ${dealData.propertyName || projectId}`,
      colorId: String(EVENT_COLORS[eventType as EventType] ?? 1),
      start: { dateTime: startDt.toISOString(), timeZone: 'America/New_York' },
      end:   { dateTime: endDt.toISOString(),   timeZone: 'America/New_York' },
      attendees: attendeeEmails.map((email: string) => ({ email })),
      extendedProperties: {
        private: { paperworkingProjectId: projectId, eventType },
      },
    };

    let eventId: string;
    let htmlLink: string;

    if (existingEventId) {
      const res = await calendar.events.update({
        calendarId: 'primary',
        eventId: existingEventId,
        requestBody: eventBody,
      });
      eventId = res.data.id!;
      htmlLink = res.data.htmlLink!;
    } else {
      const res = await calendar.events.insert({
        calendarId: 'primary',
        requestBody: eventBody,
        sendUpdates: attendeeEmails.length > 0 ? 'all' : 'none',
      });
      eventId = res.data.id!;
      htmlLink = res.data.htmlLink!;
    }

    // Write back to Firestore
    await adminDb.collection('projects').doc(projectId).update({
      [`calendarEvents.${eventType}`]: {
        eventId,
        htmlLink,
        title,
        date,
        eventType,
        syncedAt: FieldValue.serverTimestamp(),
      },
      updatedAt: FieldValue.serverTimestamp(),
    });

    return NextResponse.json({ success: true, eventId, htmlLink });
  } catch (error: any) {
    console.error('[Calendar Sync] Error:', error);
    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ error: 'Session expired.' }, { status: 401 });
    }
    return NextResponse.json({ error: 'Failed to sync calendar event.', details: error.message }, { status: 500 });
  }
}

