import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { logOrgActivity } from '@/lib/firebase/orgActivityWriter';
import type { TitleCheckItem } from '@/types/schema';
import { FieldValue } from 'firebase-admin/firestore';

function deriveChainStatus(
  checks: TitleCheckItem[]
): 'pending' | 'verified' | 'failed' {
  if (checks.some((c) => c.status === 'Issue Found')) return 'failed';
  if (checks.every((c) => c.status === 'Cleared')) return 'verified';
  return 'pending';
}

export async function POST(req: NextRequest) {
  // ── Auth ──────────────────────────────────────────────────
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;
  const { uid } = auth;
  const actorName = (auth as any).token?.name || (auth as any).token?.email || 'Unknown';

  let body: { projectId?: string; organizationId?: string; projectName?: string; checks?: TitleCheckItem[] };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { success: false, error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  const { projectId, organizationId, projectName, checks } = body;

  if (!projectId) {
    return NextResponse.json(
      { success: false, error: 'projectId is required' },
      { status: 400 }
    );
  }

  if (checks === undefined) {
    return NextResponse.json(
      {
        success: false,
        providerDecisionRequired: true,
        error:
          'Title search provider not configured. A real provider (county records API, First American, Stewart Title, etc.) must be integrated before live title data is available.',
      },
      { status: 503 }
    );
  }

  if (!Array.isArray(checks)) {
    return NextResponse.json(
      { success: false, error: 'checks must be an array' },
      { status: 400 }
    );
  }

  // Check project access and scope
  const projectSnap = await adminDb.collection('projects').doc(projectId).get();
  if (!projectSnap.exists) {
    return NextResponse.json({ success: false, error: 'Project not found' }, { status: 404 });
  }
  const projectData = projectSnap.data();
  const orgId = projectData?.organizationId;

  const userSnap = await adminDb.collection('users').doc(uid).get();
  if (!userSnap.exists) {
    return NextResponse.json({ error: 'Access denied' }, { status: 403 });
  }
  const profile = userSnap.data();

  // Helper to check project scoped access
  function hasProjectAccess(
    profile: any,
    targetOrgId: string | undefined,
    projectId?: string
  ): boolean {
    if (!targetOrgId) return false;
    const orgMember =
      profile.personalOrganizationId === targetOrgId ||
      profile.organizationId === targetOrgId ||
      (profile.memberships != null && Boolean(profile.memberships[targetOrgId]));

    if (!orgMember) return false;

    if (projectId && profile.membershipScopes) {
      const scope = profile.membershipScopes[targetOrgId];
      if (scope?.isScoped) {
        return Array.isArray(scope.scopedProjectIds) && scope.scopedProjectIds.includes(projectId);
      }
    }
    return true;
  }

  if (!hasProjectAccess(profile, orgId, projectId)) {
    return NextResponse.json({ error: 'Access denied' }, { status: 403 });
  }

  const chainOfTitleStatus = deriveChainStatus(checks);

  // ── Persist to Firestore ─────────────────────────────────
  try {
    await adminDb
      .collection('projects')
      .doc(projectId)
      .update({
        'closingRoom.titleChecks': checks,
        'closingRoom.chainOfTitleStatus': chainOfTitleStatus,
        updatedAt: FieldValue.serverTimestamp(),
      });
  } catch (err: any) {
    console.error('[title-search] Firestore write failed:', err);
    return NextResponse.json(
      { success: false, error: 'Failed to persist title checks' },
      { status: 500 }
    );
  }

  // ── Activity log (fire-and-forget) ───────────────────────
  if (organizationId) {
    logOrgActivity({
      organizationId,
      type: 'doc_uploaded',
      actorId: uid,
      actorName,
      summary: `Title clearance checklist updated for ${projectName || projectId}`,
      targetRef: `projects/${projectId}`,
      projectId,
      projectName,
    }).catch((e) =>
      console.warn('[title-search] Activity log failed (non-fatal):', e)
    );
  }

  return NextResponse.json({
    success: true,
    data: {
      projectId,
      chainOfTitleStatus,
      checks,
      updatedAt: new Date().toISOString(),
    },
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import {
  ATTORNEY_CLOSE_STATES_SEED,
  ATTORNEY_STATES_DOC_PATH,
} from '@/lib/config/attorneyStates';

export const dynamic = 'force-dynamic';

/**
 * GET /api/config/attorney-states
 *
 * Returns the current attorney-close state list from Firestore.
 * If the document doesn't exist yet, seeds it from the default list.
 *
 * Public read — no auth required (the list is non-sensitive config data).
 */
export async function GET() {
  try {
    const docRef = adminDb.doc(ATTORNEY_STATES_DOC_PATH);
    const snap = await docRef.get();

    if (snap.exists) {
      const data = snap.data()!;
      return NextResponse.json({
        states: data.states || [],
        seededAt: data.seededAt || null,
        updatedAt: data.updatedAt || null,
      });
    }

    // Auto-seed on first read
    const now = new Date().toISOString();
    const seedPayload = {
      states: [...ATTORNEY_CLOSE_STATES_SEED],
      seededAt: now,
      updatedAt: now,
      updatedBy: 'system_seed',
      description:
        'States where attorney involvement at closing is customary or required. ' +
        'Founder-editable — the platform organizes eligibility, never makes a legal determination.',
    };
    await docRef.set(seedPayload);

    return NextResponse.json({
      states: seedPayload.states,
      seededAt: now,
      updatedAt: now,
    });
  } catch (err: any) {
    console.error('[Attorney States Config]', err.message);
    return NextResponse.json({ error: 'Failed to load attorney states' }, { status: 500 });
  }
}

/**
 * PUT /api/config/attorney-states
 *
 * Updates the attorney-close state list. Founder/admin only.
 *
 * Body: { states: string[] }
 */
export async function PUT(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;

    const body = await request.json();
    const { states } = body;

    if (!Array.isArray(states) || states.some((s: any) => typeof s !== 'string' || s.length !== 2)) {
      return NextResponse.json(
        { error: 'states must be an array of 2-letter state codes' },
        { status: 422 }
      );
    }

    const normalized = states.map((s: string) => s.toUpperCase().trim());
    const unique = [...new Set(normalized)].sort();

    const now = new Date().toISOString();
    const docRef = adminDb.doc(ATTORNEY_STATES_DOC_PATH);
    await docRef.set(
      {
        states: unique,
        updatedAt: now,
        updatedBy: auth.uid,
      },
      { merge: true }
    );

    return NextResponse.json({ success: true, states: unique, updatedAt: now });
  } catch (err: any) {
    console.error('[Attorney States Config PUT]', err.message);
    return NextResponse.json({ error: 'Failed to update attorney states' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';

/**
 * /api/contact — Public Contact Form Intake Endpoint
 * Creates real tickets in Firestore support_tickets collection (Part A requirement 3).
 * Failure-safe additive write: ticket creation errors do not fail contact form response.
 */
export async function POST(req: Request) {
  try {
    const json = await req.json();
    const { name, email, subject, body, category } = json || {};

    if (!email || typeof email !== 'string' || !email.includes('@')) {
      return NextResponse.json({ success: false, error: 'Valid email is required.' }, { status: 400 });
    }
    if (!subject || typeof subject !== 'string' || !subject.trim()) {
      return NextResponse.json({ success: false, error: 'Subject is required.' }, { status: 400 });
    }
    if (!body || typeof body !== 'string' || !body.trim()) {
      return NextResponse.json({ success: false, error: 'Message body is required.' }, { status: 400 });
    }

    const cleanName = (name && typeof name === 'string') ? name.trim() : email.split('@')[0];
    const ticketId = `ticket_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    const now = new Date();

    // Default starter tags mapping
    const tag = (category && typeof category === 'string') ? category.toLowerCase().replace(/\s+/g, '-') : 'general-inquiry';

    // Additive & failure-safe Firestore ticket creation
    try {
      const ticketRef = adminDb.collection('support_tickets').doc(ticketId);
      await ticketRef.set({
        id: ticketId,
        subject: subject.trim(),
        body: body.trim(),
        requesterUid: null,
        requesterEmail: email.trim().toLowerCase(),
        requesterName: cleanName,
        status: 'active',
        priority: 'normal',
        assigneeUid: null,
        assigneeName: null,
        tags: [tag],
        createdAt: FieldValue.serverTimestamp(),
        updatedAt: FieldValue.serverTimestamp(),
        lastCustomerReplyAt: FieldValue.serverTimestamp(),
        lastInternalReplyAt: null,
        firstResponseAt: null,
        resolvedAt: null,
        snoozedUntil: null,
        fcrEligible: true,
      });

      // Add initial customer message to subcollection
      const msgRef = ticketRef.collection('messages').doc();
      await msgRef.set({
        id: msgRef.id,
        authorType: 'customer',
        authorUid: null,
        authorEmail: email.trim().toLowerCase(),
        authorName: cleanName,
        body: body.trim(),
        createdAt: FieldValue.serverTimestamp(),
      });
    } catch (dbErr) {
      console.error('[POST /api/contact] Additive ticket creation error:', dbErr);
      // Proceed safely without throwing to client
    }

    return NextResponse.json({
      success: true,
      message: 'Thank you for reaching out. Your message has been received.',
      ticketId,
    });
  } catch (error: any) {
    console.error('[POST /api/contact] Fatal handler error:', error);
    return NextResponse.json({ success: false, error: error?.message || 'Server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';

export const dynamic = 'force-dynamic';

/**
 * GET /api/cron/bridge-sync
 *
 * Cron-triggered endpoint that enqueues all three MLS replication jobs:
 *   1. bridge_sync  — Property listings
 *   2. member_sync  — Agents / Members
 *   3. office_sync  — Offices
 *
 * After enqueuing, immediately triggers /api/worker/drain to process the queue.
 *
 * Schedule: Every 6 hours
 *   - Firebase Scheduler: configure in firebase.json extensions
 *   - Vercel Cron: add to vercel.json crons array
 *   - External: cURL from any cron service
 *
 * Protected by CRON_SECRET or WORKER_SECRET in the Authorization header.
 *
 * Query params:
 *   ?resources=property,member,office  — comma-separated list (default: all)
 *   ?drain=true                        — auto-drain after enqueue (default: true)
 */
export async function GET(req: NextRequest) {
  // ── Auth ──
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET;

  if (!cronSecret) {
    console.error('[Cron/BridgeSync] CRON_SECRET env var not set');
    return NextResponse.json({ error: 'Server misconfiguration' }, { status: 500 });
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const startTime = Date.now();

  try {
    const { jobQueue } = await import('@/lib/queue/jobQueue');

    // ── Parse which resources to sync ──
    const resourcesParam = req.nextUrl.searchParams.get('resources') ?? 'property,member,office';
    const requested = new Set(resourcesParam.split(',').map(s => s.trim().toLowerCase()));
    const autoDrain = req.nextUrl.searchParams.get('drain') !== 'false';

    const enqueued: Record<string, string> = {};

    if (requested.has('property') || requested.has('all')) {
      enqueued.bridge_sync = await jobQueue.enqueue('bridge_sync', {
        triggeredBy: 'cron',
        scheduledAt: new Date().toISOString(),
      });
    }

    if (requested.has('member') || requested.has('all')) {
      enqueued.member_sync = await jobQueue.enqueue('member_sync', {
        triggeredBy: 'cron',
        scheduledAt: new Date().toISOString(),
      });
    }

    if (requested.has('office') || requested.has('all')) {
      enqueued.office_sync = await jobQueue.enqueue('office_sync', {
        triggeredBy: 'cron',
        scheduledAt: new Date().toISOString(),
      });
    }

    console.log(`📅 [CRON BRIDGE-SYNC] Enqueued jobs:`, enqueued);

    // ── Auto-drain ──
    let drainResult = null;
    if (autoDrain && Object.keys(enqueued).length > 0) {
      try {
        const { drainAll } = await import('@/lib/queue/jobConsumer');
        drainResult = await drainAll(5);
        console.log(`✅ [CRON BRIDGE-SYNC] Drain complete:`, drainResult);
      } catch (drainError: any) {
        console.error('⚠️ [CRON BRIDGE-SYNC] Drain failed (jobs remain in queue):', drainError.message);
        drainResult = { error: drainError.message };
      }
    }

    // ── Watermark status ──
    const prisma = (await import('@/lib/prisma')).default;
    const watermarks = await prisma.bridgeSyncState.findMany();
    const watermarkMap: Record<string, string> = {};
    for (const w of watermarks) {
      watermarkMap[w.id] = w.mostRecentModificationTimestamp.toISOString();
    }

    return NextResponse.json({
      ok: true,
      enqueued,
      drain: drainResult,
      watermarks: watermarkMap,
      durationMs: Date.now() - startTime,
    });
  } catch (error: any) {
    console.error('❌ [CRON BRIDGE-SYNC] Uncaught error:', error);
    return NextResponse.json(
      { error: 'cron_failed', detail: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { NotificationService } from '@/lib/services/notificationService';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest) {
  // Cron authorization verification
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET || 'mock_secret';

  const isTest = process.env.NODE_ENV === 'test';
  if (!isTest && authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const results = {
    projectsScanned: 0,
    remindersSent: 0,
    errors: [] as any[],
  };

  try {
    const projectsSnap = await adminDb
      .collection('projects')
      .where('status', 'in', ['Active', 'Under Contract', 'Renovating', 'Rented'])
      .get();

    results.projectsScanned = projectsSnap.size;

    for (const projectDoc of projectsSnap.docs) {
      const projectId = projectDoc.id;
      const project = projectDoc.data();
      const ownerUid = project.ownerUid;
      if (!ownerUid) continue;

      try {
        const packageColl = adminDb
          .collection('projects')
          .doc(projectId)
          .collection('lenderPackage');

        const itemsSnap = await packageColl.get();
        if (itemsSnap.empty) continue;

        for (const itemDoc of itemsSnap.docs) {
          const itemId = itemDoc.id;
          const item = itemDoc.data();

          if (item.status === 'Uploaded') continue;
          if (item.reminderCadence === 'none' || !item.reminderCadence) continue;

          // Check if it's time to remind based on lastRemindedAt
          const lastReminded = item.lastRemindedAt ? new Date(item.lastRemindedAt) : null;
          const cadence = item.reminderCadence;
          const now = new Date();

          let shouldRemind = false;
          if (!lastReminded) {
            shouldRemind = true;
          } else {
            const diffMs = now.getTime() - lastReminded.getTime();
            if (cadence === 'daily') {
              shouldRemind = diffMs >= 24 * 60 * 60 * 1000;
            } else if (cadence === 'weekly') {
              shouldRemind = diffMs >= 7 * 24 * 60 * 60 * 1000;
            }
          }

          if (shouldRemind) {
            // Dispatch notification via NotificationService
            await NotificationService.createNotification({
              recipientId: ownerUid,
              type: 'LENDER_CHECKLIST_REMINDER',
              actor: {
                uid: 'system',
                name: 'PaperWorking',
              },
              objectReference: {
                projectId,
                dealAddress: project.address || 'project property',
                documentName: item.name,
              },
              deepLinkUrl: `/dashboard/projects/${projectId}/phase-2?card=F3.2`,
            });

            // Update item in Firestore
            await itemDoc.ref.update({
              lastRemindedAt: now.toISOString(),
            });

            results.remindersSent++;
          }
        }
      } catch (err: any) {
        results.errors.push({ projectId, error: err.message });
      }
    }

    return NextResponse.json({ success: true, ...results });
  } catch (err: any) {
    console.error('[Lender Package Reminders Cron]', err.message);
    return NextResponse.json({ error: 'Failed to process reminders' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { scanAllProjectsForLifecycleAlerts } from '@/lib/notifications/lifecycleAlertEngine';

/* ═══════════════════════════════════════════════════════
   GET /api/cron/lifecycle-alerts

   Daily cron that scans all active projects for lifecycle
   deadline alerts (lease renewal, property tax, insurance,
   valuation review).

   Triggered by Vercel Cron daily at 8:00 AM UTC or an
   external scheduler.

   Security: Requires CRON_SECRET via Bearer token.
   ═══════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';
export const maxDuration = 60; // Allow up to 60s for batch scanning

export async function GET(request: Request) {
  // ── Auth: Verify cron secret ──────────────────────────
  const authHeader = request.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    console.error('[Cron/LifecycleAlerts] CRON_SECRET env var not set');
    return NextResponse.json(
      { error: 'Server misconfiguration' },
      { status: 500 }
    );
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    );
  }

  const startTime = Date.now();

  try {
    // ── Scan all active projects ─────────────────────────
    const result = await scanAllProjectsForLifecycleAlerts();

    const durationMs = Date.now() - startTime;
    console.log(
      `[Cron/LifecycleAlerts] Scanned ${result.projectsScanned} projects, ` +
        `fired ${result.totalAlertsFired} alerts, ` +
        `debounced ${result.totalAlertsDebounced} in ${durationMs}ms` +
        (result.errors.length > 0 ? ` (${result.errors.length} errors)` : '')
    );

    return NextResponse.json({
      projectsScanned: result.projectsScanned,
      alertsFired: result.totalAlertsFired,
      alertsDebounced: result.totalAlertsDebounced,
      errors: result.errors,
      durationMs,
    });
  } catch (error: any) {
    console.error('[Cron/LifecycleAlerts] Fatal error:', error?.message);
    return NextResponse.json(
      { error: `Cron execution failed: ${error?.message}` },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminStorage } from '@/lib/firebase/admin';
import { Project, Organization, MetricSnapshot } from '@/types/schema';
import { FieldValue } from 'firebase-admin/firestore';
import { saveActiveSnapshotsForProjectAdmin } from '@/lib/metrics/snapshotService.admin';

export const dynamic = 'force-dynamic';

/**
 * GET /api/cron/process-daily-kpis
 *
 * Runs daily via Vercel Cron.
 * Aggregates document counts, signatures, efficiency, and storage usage 
 * for each organization and writes a snapshot.
 * Protected by Vercel CRON_SECRET or WORKER_SECRET.
 */
export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET;

  if (!cronSecret) {
    console.error('[Cron/ProcessDailyKPIs] CRON_SECRET env var not set');
    return NextResponse.json({ error: 'Server misconfiguration' }, { status: 500 });
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const today = new Date();
    // Use ISO string for the date key: 'YYYY-MM-DD'
    const dateKey = today.toISOString().split('T')[0];

    const orgsSnapshot = await adminDb.collection('organizations').get();
    const processedOrgs: string[] = [];
    const errors: any[] = [];

    for (const orgDoc of orgsSnapshot.docs) {
      const orgId = orgDoc.id;
      const org = orgDoc.data() as Organization;

      // Skip invalid or placeholder orgs
      if (orgId === 'org_placeholder' || !orgId) continue;

      try {
        const projectsSnapshot = await adminDb.collection('projects')
          .where('organizationId', '==', orgId)
          .get();

        let totalDocuments = 0;
        let pendingSignatures = 0;
        let storageUsageBytes = 0;

        let totalActionItems = 0;
        let completedActionItems = 0;

        const bucket = adminStorage.bucket(process.env.NEXT_PUBLIC_FIREBASE_STORAGE_BUCKET);

        for (const projectDoc of projectsSnapshot.docs) {
          const project = { ...projectDoc.data(), id: projectDoc.id } as Project;

          // Compute and save active financial snapshots for the project
          try {
            await saveActiveSnapshotsForProjectAdmin(project);
          } catch (snapshotErr: any) {
            console.error(`Failed to save active snapshots for project ${projectDoc.id}:`, snapshotErr);
          }

          // 1. Storage Usage (Real bytes from Cloud Storage)
          try {
            const [files] = await bucket.getFiles({ prefix: `projects/${projectDoc.id}/` });
            const projectStorageBytes = files.reduce((sum, file) => sum + parseInt(file.metadata.size?.toString() || '0', 10), 0);
            storageUsageBytes += projectStorageBytes;
          } catch (storageErr) {
            console.error(`Failed to fetch storage for project ${projectDoc.id}:`, storageErr);
          }

          // 2. Total Documents
          if (project.roleLinkedDocuments && Array.isArray(project.roleLinkedDocuments)) {
            totalDocuments += project.roleLinkedDocuments.length;
          }

          if (project.purchaseReadinessChecklist && Array.isArray(project.purchaseReadinessChecklist)) {
            const docs = project.purchaseReadinessChecklist.filter(item => item.documentUrl);
            totalDocuments += docs.length;
          }

          if (project.settlementDocuments && Array.isArray(project.settlementDocuments)) {
            totalDocuments += project.settlementDocuments.length;
          }

          // 2. Pending Signatures (LOIs that are Drafted, Sent, or Viewed)
          if (project.loiDocuments && Array.isArray(project.loiDocuments)) {
            const pending = project.loiDocuments.filter(
              loi => loi.status === 'Drafted' || loi.status === 'Sent' || loi.status === 'Viewed'
            );
            pendingSignatures += pending.length;
          }

          // 3. Team Efficiency (Action Items / ProjectTodoList)
          if (project.actionItems && Array.isArray(project.actionItems)) {
            totalActionItems += project.actionItems.length;
            completedActionItems += project.actionItems.filter(item => item.completed).length;
          }
        }

        // Calculate Team Efficiency Score (0-100)
        let teamEfficiencyScore = 0;
        if (totalActionItems > 0) {
          teamEfficiencyScore = Math.round((completedActionItems / totalActionItems) * 100);
        }

        const snapshotData: MetricSnapshot = {
          id: dateKey,
          organizationId: orgId,
          date: today,
          totalDocuments,
          pendingSignatures,
          teamEfficiencyScore,
          storageUsageBytes,
          createdAt: new Date()
        };

        // Write the snapshot document
        await adminDb.collection('organizations')
          .doc(orgId)
          .collection('metricSnapshots')
          .doc(dateKey)
          .set(snapshotData);

        processedOrgs.push(orgId);
      } catch (err: any) {
        errors.push({ orgId, error: err.message });
      }
    }

    return NextResponse.json({ 
      ok: true, 
      processedCount: processedOrgs.length,
      processed: processedOrgs,
      errors 
    });
  } catch (error: any) {
    console.error('❌ [CRON KPI PROCESSOR] Uncaught error:', error);
    return NextResponse.json({ error: 'cron_failed', detail: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminStorage } from '@/lib/firebase/admin';
import admin from 'firebase-admin';
import Stripe from 'stripe';

export const dynamic = 'force-dynamic';

function getStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY is not set');
  return new Stripe(key, { apiVersion: '2026-04-22.dahlia' as any });
}

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET;

  if (!cronSecret) {
    console.error('[Cron/ProcessDeletions] CRON_SECRET env var not set');
    return NextResponse.json({ error: 'Server misconfiguration' }, { status: 500 });
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const deletedUserIds: string[] = [];
  const errors: any[] = [];

  try {
    // 1. Fetch expired deletion requests (scheduledAt <= now)
    const now = new Date();
    const requestsSnap = await adminDb
      .collection('accountDeletionRequests')
      .where('scheduledAt', '<=', now)
      .get();

    for (const docSnap of requestsSnap.docs) {
      const uid = docSnap.id;
      try {
        // A. Cancel active Stripe subscription if present
        const userDoc = await adminDb.collection('users').doc(uid).get();
        const userData = userDoc.exists ? userDoc.data() : null;
        const stripeSubscriptionId = userData?.stripeSubscriptionId;

        if (stripeSubscriptionId) {
          try {
            const stripe = getStripe();
            await stripe.subscriptions.cancel(stripeSubscriptionId);
            console.log(`[Cron Deletion] Stripe subscription cancelled: ${stripeSubscriptionId} for user ${uid}`);
          } catch (stripeErr: any) {
            console.error(`[Cron Deletion] Stripe subscription cancel failed for user ${uid}:`, stripeErr.message);
          }
        }

        // 2. Query all projects owned by the user
        const projectsSnap = await adminDb
          .collection('projects')
          .where('ownerUid', '==', uid)
          .get();

        const bucket = adminStorage.bucket();

        for (const projectDoc of projectsSnap.docs) {
          const projectId = projectDoc.id;

          // A. Fetch all activity logs of the project to archive
          const activitySnap = await adminDb
            .collection('projects')
            .doc(projectId)
            .collection('activityLog')
            .get();

          const logs = activitySnap.docs.map(l => ({ id: l.id, ...l.data() }));

          if (logs.length > 0) {
            // Write to archivedAuditLogs with a 7-year retention lease
            await adminDb.collection('archivedAuditLogs').add({
              projectId,
              ownerUid: uid,
              archivedAt: new Date(),
              expiresAt: new Date(Date.now() + 7 * 365 * 24 * 60 * 60 * 1000), // 7 years
              logs,
            });
          }

          // B. Delete activityLog subcollection documents
          for (const lDoc of activitySnap.docs) {
            await lDoc.ref.delete();
          }

          // C. Delete ledgerItems subcollection documents
          const ledgerSnap = await adminDb
            .collection('projects')
            .doc(projectId)
            .collection('ledgerItems')
            .get();

          for (const lItem of ledgerSnap.docs) {
            await lItem.ref.delete();
          }

          // D. Delete files from Firebase Storage
          try {
            const [files] = await bucket.getFiles({ prefix: `projects/${projectId}/` });
            for (const file of files) {
              await file.delete();
            }
          } catch (storageErr: any) {
            console.warn(`[Cron Deletion] Storage files delete skipped for project ${projectId}:`, storageErr.message);
          }

          // E. Delete project document
          await projectDoc.ref.delete();
        }

        // 3. Delete user document in users/{uid}
        await adminDb.collection('users').doc(uid).delete();

        // 4. Delete the user from Firebase Authentication
        try {
          await admin.auth().deleteUser(uid);
        } catch (authErr: any) {
          if (authErr.code !== 'auth/user-not-found') {
            throw authErr;
          }
        }

        // 5. Delete the accountDeletionRequest document
        await docSnap.ref.delete();

        deletedUserIds.push(uid);
      } catch (err: any) {
        errors.push({ userId: uid, error: err.message });
        console.error(`[Cron Deletion] Failed to delete user ${uid}:`, err);
      }
    }

    return NextResponse.json({
      success: true,
      processedCount: deletedUserIds.length,
      deletedUserIds,
      errors,
    });
  } catch (error: any) {
    console.error('❌ [CRON DELETION PROCESSOR] Uncaught error:', error);
    return NextResponse.json({ error: 'cron_failed', detail: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminMessaging } from '@/lib/firebase/admin';
import { CommunicationMessage, ApplicationUser, Project } from '@/types/schema';
import { generateNotificationEmailHtml } from '@/lib/emails/NotificationTemplate';
import { FieldValue } from 'firebase-admin/firestore';
import { CommunicationEngine } from '@/lib/engine/CommunicationEngine';
import { isUserInDND } from '@/lib/services/notificationService';
import { generateSystemNotificationEmail } from '@/lib/emails/templates/SystemNotificationEmail';

export const dynamic = 'force-dynamic';

const FROM_EMAIL = 'notifications@mail.paperworking.co';

async function sendPushNotification(
  recipientId: string,
  userData: any,
  title: string,
  body: string,
  deepLinkUrl: string,
  expiresAt?: Date
) {
  try {
    const fcmTokens = userData?.fcmTokens || [];
    if (fcmTokens.length > 0) {
      let ttlSeconds: number | undefined = undefined;
      if (expiresAt) {
        const remainingMs = expiresAt.getTime() - Date.now();
        ttlSeconds = Math.max(0, Math.floor(remainingMs / 1000));
      }

      const multicastMessage = {
        tokens: fcmTokens,
        notification: { title, body },
        data: { deepLinkUrl, title, body },
        webpush: {
          headers: {
            Urgency: 'high',
            ...(ttlSeconds !== undefined ? { TTL: String(ttlSeconds) } : {})
          },
          notification: { clickAction: deepLinkUrl, requireInteraction: true },
        },
      };

      const response = await adminMessaging.sendEachForMulticast(multicastMessage);
      console.log(`[process-email-notifications] Sent push to ${fcmTokens.length} devices. Success: ${response.successCount}`);

      // Stale token cleanup
      const tokensToRemove: string[] = [];
      response.responses.forEach((resp, idx) => {
        if (!resp.success && resp.error) {
          const code = resp.error.code;
          if (
            code === 'messaging/invalid-registration-token' ||
            code === 'messaging/registration-token-not-registered'
          ) {
            tokensToRemove.push(fcmTokens[idx]);
          }
        }
      });

      if (tokensToRemove.length > 0) {
        await adminDb.collection('users').doc(recipientId).update({
          fcmTokens: FieldValue.arrayRemove(...tokensToRemove),
        });
        console.log(`[process-email-notifications] Cleaned up ${tokensToRemove.length} stale FCM tokens`);
      }
    }
  } catch (err) {
    console.error('[process-email-notifications] FCM push dispatch failed:', err);
  }
}

function getBatchedContent(
  type: string,
  count: number,
  dealAddress: string,
  items: any[]
): { title: string; body: string } {
  const address = dealAddress || 'the property';

  if (count === 1) {
    return {
      title: items[0].title || `${items[0].type} Notification`,
      body: items[0].body || '',
    };
  }

  let title = '';
  let body = '';

  switch (type) {
    case 'VENDOR_BID':
      title = `${count} new bids on ${address}`;
      body = `You have received ${count} new bids on ${address}:\n` +
        items.map(item => `• ${item.actorName || 'A contractor'} bid ${item.amount || '$0.00'} for task '${item.task || 'the assigned task'}'`).join('\n');
      break;
    case 'TASK_COMPLETE':
      title = `${count} tasks completed on ${address}`;
      body = `${count} tasks have been marked complete on ${address}:\n` +
        items.map(item => `• '${item.task || 'assigned task'}' completed by ${item.actorName || 'teammate'}`).join('\n');
      break;
    case 'DOCUMENT_SIGNED':
      title = `${count} documents signed for ${address}`;
      body = `${count} documents have been signed for ${address}:\n` +
        items.map(item => `• '${item.documentName || 'document'}' signed by ${item.actorName || 'teammate'}`).join('\n');
      break;
    case 'RECEIPT_APPROVAL':
      title = `${count} receipts uploaded for ${address} — approval required`;
      body = `${count} receipts require approval for ${address}:\n` +
        items.map(item => `• Receipt of ${item.amount || '$0.00'} uploaded by ${item.actorName || 'teammate'}`).join('\n');
      break;
    case 'TEAM_INVITE':
      title = `You have ${count} team invitations`;
      body = `You have received ${count} invitations to join teams:\n` +
        items.map(item => `• Invitation from ${item.actorName || 'teammate'} to join team '${item.organizationName || 'organization'}'`).join('\n');
      break;
    case 'PHASE_TRANSITION':
      title = `${count} phase transitions on ${address}`;
      body = `Multiple phase changes on ${address}:\n` +
        items.map(item => `• Project advanced to '${item.phase || 'new'}' phase`).join('\n');
      break;
    default:
      title = `${count} new notifications for ${address}`;
      body = `You have received ${count} updates for ${address}:\n` +
        items.map(item => `• ${item.title || item.body || 'System notification'}`).join('\n');
  }

  return { title, body };
}

interface QueuedEmailItem {
  id: string;
  ref: FirebaseFirestore.DocumentReference<FirebaseFirestore.DocumentData>;
  recipientId: string;
  isBatchable?: boolean;
  sendEmail?: boolean;
  sendPush?: boolean;
  expiresAt?: any;
  title?: string;
  body?: string;
  deepLinkUrl?: string;
  subject?: string;
  html?: string;
  recipientEmail?: string;
  retryCount?: number;
  type: string;
  projectId?: string;
  dealAddress?: string;
  actorName?: string;
  amount?: number | string;
  task?: string;
  documentName?: string;
  organizationName?: string;
  phase?: string;
  [key: string]: any;
}

async function processQueuedEmails() {
  const queuedSnapshot = await adminDb.collection('queued_emails')
    .where('status', '==', 'pending')
    .get();

  const processedIds: string[] = [];
  const errors: any[] = [];

  if (queuedSnapshot.empty) {
    return { processedIds, errors };
  }

  // 1. Fetch user docs cache
  const userCache = new Map<string, any>();
  const recipientIds = Array.from(new Set(queuedSnapshot.docs.map(doc => doc.data().recipientId)));
  for (const recipientId of recipientIds) {
    try {
      const userDoc = await adminDb.collection('users').doc(recipientId).get();
      if (userDoc.exists) {
        userCache.set(recipientId, userDoc.data());
      }
    } catch (err) {
      console.error(`[process-email-notifications] Failed to fetch user ${recipientId}:`, err);
    }
  }

  // 2. Filter, check expiration, check retry backoff, check DND
  const now = new Date();
  const activeDocs: FirebaseFirestore.QueryDocumentSnapshot<FirebaseFirestore.DocumentData>[] = [];

  for (const doc of queuedSnapshot.docs) {
    const data = doc.data();
    const expiresAt = data.expiresAt ? (data.expiresAt.toDate ? data.expiresAt.toDate() : new Date(data.expiresAt)) : null;

    // Check expiration
    if (expiresAt && expiresAt < now) {
      console.log(`[process-email-notifications] Suppressing expired queued email ${doc.id}`);
      await doc.ref.update({
        status: 'suppressed',
        suppressedAt: FieldValue.serverTimestamp(),
        error: 'Expired before delivery'
      });
      continue;
    }

    // Check retry backoff
    const nextAttemptAfter = data.nextAttemptAfter ? (data.nextAttemptAfter.toDate ? data.nextAttemptAfter.toDate() : new Date(data.nextAttemptAfter)) : null;
    if (nextAttemptAfter && nextAttemptAfter > now) {
      console.log(`[process-email-notifications] Skipping queued email ${doc.id} due to retry backoff (next attempt after ${nextAttemptAfter})`);
      continue;
    }

    const userData = userCache.get(data.recipientId);
    if (!userData) continue;

    // Filter DND
    if (isUserInDND(userData)) {
      console.log(`[process-email-notifications] Skipping queued email ${doc.id} because user is in DND.`);
      continue;
    }

    activeDocs.push(doc);
  }

  // 3. Separate batchable and individual items
  const batchableItems: QueuedEmailItem[] = [];
  const individualItems: QueuedEmailItem[] = [];

  for (const doc of activeDocs) {
    const data = doc.data();
    const item: QueuedEmailItem = { id: doc.id, ref: doc.ref, recipientId: data.recipientId || '', type: data.type || '', ...data };
    if (data.isBatchable === true) {
      batchableItems.push(item);
    } else {
      individualItems.push(item);
    }
  }

  // 4. Process individual items
  for (const item of individualItems) {
    try {
      const userData = userCache.get(item.recipientId);

      // Check opt-out or synthetic test account exclusion
      if (userData?.is_test_account === true || userData?.persona_key || (item.recipientEmail && (item.recipientEmail.includes('+crew') || item.recipientEmail.endsWith('@paperworking.co')))) {
        await item.ref.update({
          status: 'cancelled',
          error: 'Test account excluded from outbound emails',
          cancelledAt: FieldValue.serverTimestamp(),
        });
        continue;
      }

      if (userData?.preferences?.emailEnabled === false && item.sendEmail) {
        await item.ref.update({
          status: 'cancelled',
          error: 'User opted out of email notifications',
          cancelledAt: FieldValue.serverTimestamp(),
        });
        continue;
      }

      // Lock document
      let lockAcquired = false;
      try {
        await adminDb.runTransaction(async (transaction) => {
          const freshDoc = await transaction.get(item.ref);
          if (!freshDoc.exists || freshDoc.data()?.status !== 'pending') {
            throw new Error('Already processed or status changed');
          }
          transaction.update(item.ref, { status: 'processing' });
        });
        lockAcquired = true;
      } catch (lockErr) {
        console.log(`[process-email-notifications] Lock failed for queued email ${item.id}`);
        continue;
      }

      if (lockAcquired) {
        // Send email
        let providerMessageId = null;
        if (item.sendEmail && userData?.email) {
          const res = await CommunicationEngine.sendRawEmail([item.recipientEmail || ''], item.subject || '', item.html || '');
          providerMessageId = res.id;
        }

        // Send push
        if (item.sendPush) {
          const expiresAtDate = item.expiresAt ? (item.expiresAt.toDate ? item.expiresAt.toDate() : new Date(item.expiresAt)) : undefined;
          await sendPushNotification(item.recipientId, userData, item.title || '', item.body || '', item.deepLinkUrl || '', expiresAtDate);
        }

        await item.ref.update({
          status: 'sent',
          sentAt: FieldValue.serverTimestamp(),
          ...(providerMessageId ? { providerMessageId } : {}),
        });
        processedIds.push(item.id);
      }
    } catch (err: any) {
      console.error(`[process-email-notifications] Failed to process individual item ${item.id}:`, err);
      try {
        const retryCount = (item.retryCount || 0) + 1;
        if (retryCount <= 3) {
          const backoffMinutes = 5 * retryCount;
          const nextAttemptAfter = new Date(Date.now() + backoffMinutes * 60 * 1000);
          await item.ref.update({
            status: 'pending', // retry later
            retryCount,
            nextAttemptAfter,
            error: err.message,
            lastFailedAt: FieldValue.serverTimestamp()
          });
        } else {
          await item.ref.update({
            status: 'failed',
            retryCount,
            error: `Max retries (3) exceeded: ${err.message}`,
            failedAt: FieldValue.serverTimestamp(),
          });
        }
      } catch (updateErr) {
        console.error(`[process-email-notifications] Failed to update error status for ${item.id}:`, updateErr);
      }
      errors.push({ id: item.id, error: err.message });
    }
  }

  // 5. Group batchable items
  // Group key: recipientId_type_projectId (or dealAddress if projectId is missing)
  const groups = new Map<string, QueuedEmailItem[]>();
  for (const item of batchableItems) {
    const key = `${item.recipientId}_${item.type}_${item.projectId || item.dealAddress || 'global'}`;
    if (!groups.has(key)) {
      groups.set(key, []);
    }
    groups.get(key)!.push(item);
  }

  // Process grouped batchable items
  for (const [groupKey, groupItems] of groups.entries()) {
    try {
      // Find the earliest createdAt in the group
      const dates = groupItems.map(item => item.createdAt ? item.createdAt.toDate().getTime() : Date.now());
      const earliestTime = Math.min(...dates);

      // Check if the 15-minute window has passed since the earliest event
      if (now.getTime() - earliestTime < 15 * 60 * 1000) {
        console.log(`[process-email-notifications] Group ${groupKey} is still inside the 15m batching window. Skipping.`);
        continue;
      }

      // Lock all documents in the group
      let groupLocked = false;
      try {
        await adminDb.runTransaction(async (transaction) => {
          const freshDocs: FirebaseFirestore.DocumentSnapshot<FirebaseFirestore.DocumentData>[] = [];
          for (const item of groupItems) {
            const freshDoc = await transaction.get(item.ref);
            if (!freshDoc.exists || freshDoc.data()?.status !== 'pending') {
              throw new Error(`Item ${item.id} already processed or status changed`);
            }
            freshDocs.push(freshDoc);
          }
          // If all are pending, mark them processing
          for (const freshDoc of freshDocs) {
            transaction.update(freshDoc.ref, { status: 'processing' });
          }
        });
        groupLocked = true;
      } catch (lockErr) {
        console.log(`[process-email-notifications] Lock failed for group ${groupKey}:`, lockErr);
        continue;
      }

      if (groupLocked) {
        const firstItem = groupItems[0];
        const userData = userCache.get(firstItem.recipientId);
        const count = groupItems.length;

        const { title, body } = getBatchedContent(
          firstItem.type,
          count,
          firstItem.dealAddress || '',
          groupItems
        );

        const sendEmail = groupItems.some(item => item.sendEmail);
        const sendPush = groupItems.some(item => item.sendPush);

        // Send Email
        let providerMessageId = null;
        if (sendEmail && userData?.email) {
          const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co';
          const { html, subject } = generateSystemNotificationEmail({
            title,
            body: body.replace(/\n/g, '<br/>'),
            deepLinkUrl: firstItem.deepLinkUrl || '/dashboard',
            appUrl,
            type: firstItem.type,
            objectReference: {
              dealAddress: firstItem.dealAddress,
              amount: firstItem.amount,
              task: firstItem.task,
              documentName: firstItem.documentName,
              organizationName: firstItem.organizationName,
              phase: firstItem.phase,
              dailyBurnRate: firstItem.dailyBurnRate,
              projectId: firstItem.projectId,
            },
            actorName: firstItem.actorName,
          });

          const res = await CommunicationEngine.sendRawEmail([userData.email], subject, html);
          providerMessageId = res.id;
        }

        // Send Push
        if (sendPush) {
          // Push notification body is single line summary
          let pushBody = body.split('\n')[0]; // First line summary
          if (count > 1) {
            const actors = Array.from(new Set(groupItems.map(item => item.actorName))).filter(Boolean);
            if (actors.length > 0) {
              const actorList = actors.slice(0, 2).join(', ');
              const remaining = actors.length - 2;
              pushBody = `Latest from ${actorList}${remaining > 0 ? ` and ${remaining} other(s)` : ''}.`;
            }
          }
          const minExpiresAt = groupItems.reduce((min, item) => {
            if (!item.expiresAt) return min;
            const date = item.expiresAt.toDate ? item.expiresAt.toDate() : new Date(item.expiresAt);
            if (!min || date < min) return date;
            return min;
          }, null as Date | null);

          await sendPushNotification(firstItem.recipientId, userData, title, pushBody, firstItem.deepLinkUrl || '', minExpiresAt || undefined);
        }

        // Update all documents status to sent
        const batch = adminDb.batch();
        for (const item of groupItems) {
          batch.update(item.ref, {
            status: 'sent',
            sentAt: FieldValue.serverTimestamp(),
            ...(providerMessageId ? { providerMessageId } : {}),
          });
          processedIds.push(item.id);
        }
        await batch.commit();
        console.log(`[process-email-notifications] Successfully processed batch of ${count} items for group ${groupKey}`);
      }
    } catch (err: any) {
      console.error(`[process-email-notifications] Failed to process group ${groupKey}:`, err);
      // Mark all documents in group as failed/retry
      try {
        const batch = adminDb.batch();
        for (const item of groupItems) {
          const retryCount = (item.retryCount || 0) + 1;
          if (retryCount <= 3) {
            const backoffMinutes = 5 * retryCount;
            const nextAttemptAfter = new Date(Date.now() + backoffMinutes * 60 * 1000);
            batch.update(item.ref, {
              status: 'pending',
              retryCount,
              nextAttemptAfter,
              error: err.message,
              lastFailedAt: FieldValue.serverTimestamp()
            });
          } else {
            batch.update(item.ref, {
              status: 'failed',
              retryCount,
              error: `Max retries (3) exceeded: ${err.message}`,
              failedAt: FieldValue.serverTimestamp()
            });
          }
        }
        await batch.commit();
      } catch (updateErr) {
        console.error(`[process-email-notifications] Failed to update error status for group ${groupKey}:`, updateErr);
      }
      errors.push({ group: groupKey, error: err.message });
    }
  }

  return { processedIds, errors };
}

async function performDailyAutoArchive() {
  console.log('[process-email-notifications] Running daily auto-archive cleanup...');
  const now = new Date();

  try {
    // Fetch read, unarchived notifications
    const readNotificationsSnap = await adminDb.collection('notifications')
      .where('read', '==', true)
      .where('archived', '==', false)
      .get();

    if (readNotificationsSnap.empty) {
      console.log('[process-email-notifications] No read notifications found to auto-archive.');
      return;
    }

    // Cache for user preferences
    const userArchiveDays = new Map<string, number>();
    const batch = adminDb.batch();
    let archiveCount = 0;

    for (const doc of readNotificationsSnap.docs) {
      const data = doc.data();
      const recipientId = data.recipientId;
      if (!recipientId) continue;

      // Get autoArchiveDays for this user
      let days = userArchiveDays.get(recipientId);
      if (days === undefined) {
        days = 30; // default
        try {
          const userDoc = await adminDb.collection('users').doc(recipientId).get();
          if (userDoc.exists) {
            const userData = userDoc.data();
            days = userData?.preferences?.autoArchiveDays || 30;
          }
        } catch (err) {
          console.error(`[process-email-notifications] Failed to fetch autoArchiveDays for ${recipientId}:`, err);
        }
        userArchiveDays.set(recipientId, days || 30);
      }

      const finalDays = days ?? 30;
      const readAt = data.readAt ? (data.readAt.toDate ? data.readAt.toDate() : new Date(data.readAt)) : null;
      if (readAt) {
        const archiveThreshold = new Date(now.getTime() - finalDays * 24 * 60 * 60 * 1000);
        if (readAt < archiveThreshold) {
          batch.update(doc.ref, { archived: true });
          archiveCount++;
        }
      }
    }

    if (archiveCount > 0) {
      await batch.commit();
      console.log(`[process-email-notifications] Auto-archived ${archiveCount} stale read notifications.`);
    }
  } catch (err) {
    console.error('[process-email-notifications] Daily auto-archive failed:', err);
  }
}

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET;

  if (!cronSecret) {
    console.error('[Cron/ProcessEmailNotifications] CRON_SECRET env var not set');
    return NextResponse.json({ error: 'Server misconfiguration' }, { status: 500 });
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const cronResults = {
    messagesProcessed: 0,
    queuedEmailsProcessed: 0,
    errors: [] as any[],
  };

  // 1. Process Queue first
  try {
    const queueResults = await processQueuedEmails();
    cronResults.queuedEmailsProcessed = queueResults.processedIds.length;
    if (queueResults.errors.length > 0) {
      cronResults.errors.push(...queueResults.errors.map(e => ({ type: 'queue', ...e })));
    }
  } catch (err: any) {
    console.error('❌ [CRON EMAIL NOTIFICATIONS] Queue processing failed:', err);
    cronResults.errors.push({ type: 'queue_global', error: err.message });
  }

  // Run daily auto-archive cleanup
  try {
    await performDailyAutoArchive();
  } catch (err: any) {
    console.error('❌ [CRON EMAIL NOTIFICATIONS] Daily auto-archive failed:', err);
    cronResults.errors.push({ type: 'auto_archive', error: err.message });
  }

  // 2. Scan and process offline message notifications (backup loop)
  try {
    const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
    const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co';

    const messagesSnapshot = await adminDb.collectionGroup('messages')
      .where('emailNotificationSent', '==', false)
      .get();

    const processedMessages: string[] = [];

    for (const doc of messagesSnapshot.docs) {
      const message = doc.data() as CommunicationMessage;

      const messageDate = message.createdAt ? (message.createdAt as any).toDate() : new Date();
      if (messageDate > fiveMinutesAgo) {
        continue;
      }

      if (message.type === 'EMAIL_OUTBOUND') {
        continue;
      }

      const projectId = message.projectId;

      try {
        let unreadUids: string[] = [];
        let projectName = '';

        const projectDoc = await adminDb.collection('projects').doc(projectId).get();
        if (projectDoc.exists) {
          const project = projectDoc.data() as Project;
          projectName = project.propertyName || '';

          if (message.recipientsUid && message.recipientsUid.length > 0) {
             unreadUids = message.recipientsUid.filter(uid => !message.readByUid?.includes(uid));
          } else {
             const members = project?.members || {};
             const memberUids = Object.keys(members).filter(uid => uid !== message.senderUid);
             unreadUids = memberUids.filter(uid => !message.readByUid?.includes(uid));
          }
        }

        let usersSnapshot: any = null;
        if (unreadUids.length > 0) {
           const uidsToQuery = unreadUids.slice(0, 30);
           usersSnapshot = await adminDb.collection('users')
              .where('uid', 'in', uidsToQuery)
              .get();
        }

        const recipientsToNotifyImmediately: string[] = [];
        if (usersSnapshot && !usersSnapshot.empty) {
          for (const userDoc of usersSnapshot.docs) {
            const user = userDoc.data() as ApplicationUser;
            if (!user.email) continue;

            if (user.preferences?.emailEnabled === false) {
              console.log(`[process-email-notifications] User ${user.uid} opted out of emails.`);
              continue;
            }

            const snippet = message.body.length > 80 ? `${message.body.substring(0, 80)}...` : message.body;
            const subject = `New message from ${message.senderName}`;
            const html = generateNotificationEmailHtml({
              senderName: message.senderName,
              projectName,
              messageSnippet: snippet,
              projectId,
              appUrl,
            });

            const isQuiet = CommunicationEngine.isQuietHoursActive(user.preferences?.quietHours);
            if (isQuiet) {
              console.log(`[process-email-notifications] Quiet hours active for ${user.uid}. Queueing message email.`);
              await adminDb.collection('queued_emails').add({
                recipientId: user.uid,
                recipientEmail: user.email,
                subject,
                html,
                deepLinkUrl: `/dashboard/projects/${projectId}`,
                status: 'pending',
                createdAt: FieldValue.serverTimestamp(),
              });
            } else {
              recipientsToNotifyImmediately.push(user.email);
            }
          }
        }

        if (recipientsToNotifyImmediately.length > 0) {
          const snippet = message.body.length > 80 ? `${message.body.substring(0, 80)}...` : message.body;
          const subject = `New message from ${message.senderName}`;

          const html = generateNotificationEmailHtml({
            senderName: message.senderName,
            projectName,
            messageSnippet: snippet,
            projectId,
            appUrl,
          });

          const result = await CommunicationEngine.sendRawEmail(recipientsToNotifyImmediately, subject, html);

          if (result) {
            await adminDb.collection('projects').doc(projectId)
              .collection('messages')
              .add({
                senderEmail: FROM_EMAIL,
                senderName: 'PaperWorking',
                body: `Automated notification sent to ${recipientsToNotifyImmediately.length} recipients.`,
                subject,
                type: 'EMAIL_OUTBOUND',
                recipients: recipientsToNotifyImmediately,
                providerMessageId: result.id,
                projectId,
                organizationId: message.organizationId,
                mock: result.mock,
                createdAt: FieldValue.serverTimestamp(),
              });
          }
        }

        await doc.ref.update({
          emailNotificationSent: true
        });

        processedMessages.push(doc.id);
      } catch (err: any) {
        cronResults.errors.push({ type: 'message', id: doc.id, error: err.message });
      }
    }

    cronResults.messagesProcessed = processedMessages.length;
  } catch (err: any) {
    console.error('❌ [CRON EMAIL NOTIFICATIONS] Message scanning failed:', err);
    cronResults.errors.push({ type: 'messages_global', error: err.message });
  }

  const status = cronResults.errors.length > 0 ? 500 : 200;
  return NextResponse.json({
    ok: cronResults.errors.length === 0,
    results: cronResults
  }, { status });
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { NotificationService } from '@/lib/services/notificationService';
import { TeamInvitation } from '@/types/schema';

export const dynamic = 'force-dynamic';

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET;

  if (!cronSecret) {
    console.error('[Cron/ProcessTeamInvites] CRON_SECRET env var not set');
    return NextResponse.json({ error: 'Server misconfiguration' }, { status: 500 });
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const results = {
    expiredCount: 0,
    day3RemindersSent: 0,
    day6RemindersSent: 0,
    errors: [] as any[],
  };

  try {
    const now = new Date();

    // Process pending invites
    const pendingSnap = await adminDb.collection('teamInvitations')
      .where('status', '==', 'pending')
      .get();

    for (const doc of pendingSnap.docs) {
      const invite = doc.data() as TeamInvitation;
      const expiresAt = (invite.expiresAt as any).toDate ? (invite.expiresAt as any).toDate() : new Date(invite.expiresAt);
      const createdAt = (invite.createdAt as any).toDate ? (invite.createdAt as any).toDate() : new Date(invite.createdAt);

      // 1. Expiration check
      if (expiresAt < now) {
        try {
          await doc.ref.update({ status: 'expired' });
          results.expiredCount++;
        } catch (err: any) {
          results.errors.push({ id: doc.id, error: err.message, action: 'expire' });
        }
        continue;
      }

      // 2. Reminders check
      const daysSinceCreation = (now.getTime() - createdAt.getTime()) / (1000 * 60 * 60 * 24);

      let shouldSendDay3 = daysSinceCreation >= 3 && daysSinceCreation < 6 && !invite.day3ReminderSent;
      let shouldSendDay6 = daysSinceCreation >= 6 && !invite.day6ReminderSent;

      if (shouldSendDay3 || shouldSendDay6) {
        try {
          // Check if user exists by email
          const userSnap = await adminDb.collection('users').where('email', '==', invite.email).limit(1).get();

          if (!userSnap.empty) {
            const userDoc = userSnap.docs[0];
            await NotificationService.createNotification({
              recipientId: userDoc.id,
              type: 'TEAM_INVITE_REMINDER',
              actor: { uid: invite.invitedByUid, name: invite.invitedByName },
              objectReference: {
                organizationId: invite.organizationId,
                organizationName: invite.organizationName,
              },
              deepLinkUrl: `/invite/team?token=${invite.token}`,
              expiresAt,
            });
          } else {
            // Unregistered user, queue email directly
            await adminDb.collection('queued_emails').add({
              recipientEmail: invite.email,
              status: 'pending',
              isBatchable: false,
              type: 'TEAM_INVITE_REMINDER',
              actorName: invite.invitedByName,
              deepLinkUrl: `${process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co'}/invite/team?token=${invite.token}`,
              sendEmail: true,
              sendPush: false,
              title: `Reminder: ${invite.invitedByName} invited you to join team ${invite.organizationName}`,
              body: `Don't forget! You have a pending invitation to join the organization '${invite.organizationName}'.`,
              subject: `Reminder: ${invite.invitedByName} invited you to join team ${invite.organizationName}`,
              html: `<p>${invite.invitedByName} invited you to join team ${invite.organizationName}.</p><p>This invitation will expire soon.</p><a href="${process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co'}/invite/team?token=${invite.token}">Accept Invitation</a>`,
              createdAt: FieldValue.serverTimestamp(),
              retryCount: 0,
              expiresAt,
            });
          }

          if (shouldSendDay6) {
            await doc.ref.update({ day6ReminderSent: true });
            results.day6RemindersSent++;
          } else if (shouldSendDay3) {
            await doc.ref.update({ day3ReminderSent: true });
            results.day3RemindersSent++;
          }
        } catch (err: any) {
          results.errors.push({ id: doc.id, error: err.message, action: 'reminder' });
        }
      }
    }
  } catch (err: any) {
    console.error('❌ [CRON TEAM INVITES] Global error:', err);
    results.errors.push({ type: 'global', error: err.message });
  }

  const status = results.errors.length > 0 ? 500 : 200;
  return NextResponse.json({
    ok: results.errors.length === 0,
    results
  }, { status });
}

