import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { ApplicationUser } from '@/types/schema';
import { generateInboxDigestEmail } from '@/lib/emails/templates/InboxDigestEmail';
import { CommunicationEngine } from '@/lib/engine/CommunicationEngine';

export const dynamic = 'force-dynamic';

function isBusinessHours(timezone: string): boolean {
  try {
    const now = new Date();
    const weekdayFormatter = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      weekday: 'long'
    });
    const weekday = weekdayFormatter.format(now);

    if (weekday === 'Saturday' || weekday === 'Sunday') {
      return false;
    }

    const hourFormatter = new Intl.DateTimeFormat('en-US', {
      timeZone: timezone,
      hour: 'numeric',
      hour12: false
    });
    const hour = parseInt(hourFormatter.format(now), 10);
    return hour >= 9 && hour < 17; // 9:00 AM to 5:00 PM
  } catch (err) {
    console.error('[send-digest] Error checking business hours:', err);
    return false;
  }
}

async function executeDigest() {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co';
  const usersSnapshot = await adminDb.collection('users').get();

  const processedUsers: string[] = [];
  const errors: any[] = [];

  for (const userDoc of usersSnapshot.docs) {
    const user = userDoc.data() as ApplicationUser;
    if (!user.email) continue;

    // Check opt-out
    if (user.preferences?.emailEnabled === false) {
      continue;
    }

    // Check timezone business hours
    const timezone = user.preferences?.quietHours?.timezone || (user.preferences as any)?.timezone || 'America/New_York';
    if (!isBusinessHours(timezone)) {
      console.log(`[send-digest] Outside business hours for user ${user.uid} (${timezone}). Skipping digest.`);
      continue;
    }

    try {
      // Query unread & unarchived notifications
      const notificationsSnap = await adminDb.collection('notifications')
        .where('recipientId', '==', user.uid)
        .where('read', '==', false)
        .where('archived', '==', false)
        .get();

      const unreadItems = notificationsSnap.docs
        .map((d) => {
          const data = d.data();
          return {
            id: d.id,
            ref: d.ref,
            title: data.title || 'Notification',
            body: data.body || '',
            deepLinkUrl: data.deepLinkUrl || '/dashboard',
            digestSent: !!data.digestSent,
            createdAt: data.createdAt ? (data.createdAt as any).toDate() : new Date(),
          };
        })
        .filter((n) => !n.digestSent);

      if (unreadItems.length === 0) {
        continue;
      }

      // Group items and compile digest email
      const { subject, html } = generateInboxDigestEmail({
        recipientName: user.displayName || 'User',
        items: unreadItems,
        appUrl,
      });

      // Send the email
      console.log(`[send-digest] Sending digest to ${user.email} with ${unreadItems.length} items.`);
      await CommunicationEngine.sendRawEmail([user.email], subject, html);

      // Mark these notifications as digestSent = true in a batch write
      const batch = adminDb.batch();
      for (const item of unreadItems) {
        batch.update(item.ref, { digestSent: true });
      }
      await batch.commit();

      processedUsers.push(user.uid);
    } catch (err: any) {
      console.error(`[send-digest] Failed to send digest for user ${user.uid}:`, err);
      errors.push({ uid: user.uid, error: err.message });
    }
  }

  return { processedUsers, errors };
}

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET || process.env.WORKER_SECRET;

  if (!cronSecret) {
    console.error('[Cron/SendDigest] CRON_SECRET env var not set');
    return NextResponse.json({ error: 'Server misconfiguration' }, { status: 500 });
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const results = await executeDigest();
    const status = results.errors.length > 0 ? 500 : 200;
    return NextResponse.json({
      ok: results.errors.length === 0,
      processedCount: results.processedUsers.length,
      processed: results.processedUsers,
      errors: results.errors
    }, { status });
  } catch (error: any) {
    console.error('❌ [CRON SEND DIGEST] Uncaught error:', error);
    return NextResponse.json({ error: 'cron_failed', detail: error.message }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  return GET(req);
}

import { NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { writeMetricSnapshotsBatch } from '@/lib/firebase/snapshotWriter';

/* ═══════════════════════════════════════════════════════
   GET /api/cron/snapshots

   Nightly cron that recomputes metric snapshots for all
   active projects. Triggered by Vercel Cron at 2:00 AM UTC
   or an external scheduler.

   Security: Requires CRON_SECRET via Bearer token.
   Rate limit: Max 100 projects per invocation.
   ═══════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';
export const maxDuration = 60; // Allow up to 60s for batch processing

const MAX_PROJECTS_PER_RUN = 100;

export async function GET(request: Request) {
  // ── Auth: Verify cron secret ──────────────────────────
  const authHeader = request.headers.get('authorization');
  const cronSecret = process.env.CRON_SECRET;

  if (!cronSecret) {
    console.error('[Cron/Snapshots] CRON_SECRET env var not set');
    return NextResponse.json(
      { error: 'Server misconfiguration' },
      { status: 500 }
    );
  }

  if (authHeader !== `Bearer ${cronSecret}`) {
    return NextResponse.json(
      { error: 'Unauthorized' },
      { status: 401 }
    );
  }

  const startTime = Date.now();

  try {
    // ── Query active projects ─────────────────────────────
    //    Exclude archived projects to avoid wasting compute.
    //    Firestore doesn't support != queries well, so we query
    //    all and filter in-memory (projects collection is typically < 1000).
    const projectsSnap = await adminDb
      .collection('projects')
      .select() // metadata-only — we don't need field data here
      .limit(MAX_PROJECTS_PER_RUN * 2) // over-fetch to account for filtered-out projects
      .get();

    // Filter out archived projects
    const projectIds: string[] = [];
    for (const doc of projectsSnap.docs) {
      const data = doc.data();
      const status = (data?.status ?? '').toLowerCase();
      if (status !== 'archived') {
        projectIds.push(doc.id);
      }
      if (projectIds.length >= MAX_PROJECTS_PER_RUN) break;
    }

    if (projectIds.length === 0) {
      return NextResponse.json({
        projectsProcessed: 0,
        snapshotsWritten: 0,
        errors: [],
        durationMs: Date.now() - startTime,
      });
    }

    // ── Batch-process snapshots ───────────────────────────
    const result = await writeMetricSnapshotsBatch(projectIds);

    const durationMs = Date.now() - startTime;
    console.log(
      `[Cron/Snapshots] Processed ${result.projectsProcessed} projects, wrote ${result.snapshotsWritten} snapshots in ${durationMs}ms` +
        (result.errors.length > 0 ? ` (${result.errors.length} errors)` : '')
    );

    return NextResponse.json({
      ...result,
      durationMs,
    });
  } catch (error: any) {
    console.error('[Cron/Snapshots] Fatal error:', error?.message);
    return NextResponse.json(
      { error: `Cron execution failed: ${error?.message}` },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getBankingProvider } from '@/lib/banking';
import * as tokenVault from '@/lib/encryption/tokenVault';
import { classifyTransaction } from '@/lib/banking/classifier';
import { bridgeCategory, normalizeAmount } from '@/lib/banking/categoryBridge';
import { Prisma } from '@prisma/client';

/**
 * GET/POST /api/cron/sync-financial-transactions
 *
 * Reads all ACTIVE PlaidConnections, syncs via Plaid /transactions/sync,
 * upserts PlaidRawTransaction records, and writes to the unified
 * FinancialTransaction ledger via the categoryBridge.
 *
 * This is the NEW pipeline. The legacy /api/cron/sync-transactions route
 * (BankConnection → Transaction) continues to run in parallel until cut-over.
 *
 * Auth: CRON_SECRET (Authorization: Bearer header or x-cron-secret header)
 */

export const dynamic = 'force-dynamic';

function authGuard(req: NextRequest): NextResponse | null {
  const authHeader = req.headers.get('Authorization');
  const cronHeader = req.headers.get('CRON_SECRET') || req.headers.get('x-cron-secret');
  const expected = process.env.CRON_SECRET;

  if (!expected) {
    return NextResponse.json({ success: false, error: 'CRON_SECRET not configured' }, { status: 500 });
  }
  if (authHeader !== `Bearer ${expected}` && cronHeader !== expected) {
    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
  }
  return null;
}

export async function GET(req: NextRequest) {
  const guard = authGuard(req);
  if (guard) return guard;

  try {
    const bankingProvider = getBankingProvider();

    const connections = await prisma.plaidConnection.findMany({
      where: { status: 'ACTIVE' },
    });

    let synced = 0;
    let failures = 0;
    let rawUpserted = 0;
    let ledgerUpserted = 0;

    for (const connection of connections) {
      try {
        const decryptedToken = tokenVault.decrypt(connection.accessToken);

        let cursor = connection.lastSyncCursor ?? undefined;
        let hasMore = true;

        while (hasMore) {
          const result = await bankingProvider.getTransactions({
            accessToken: decryptedToken,
            startDate: new Date(Date.now() - 7 * 86400_000).toISOString().split('T')[0],
            endDate: new Date().toISOString().split('T')[0],
            cursor,
          });

          // ── Added / Modified ─────────────────────────────────────────────
          for (const tx of [...result.added, ...result.modified]) {
            const classified = classifyTransaction(tx.name);
            const { absoluteAmount, direction } = normalizeAmount(tx.amount);
            const bridge = bridgeCategory(classified.reiCategory, tx.amount);

            // 1. Upsert PlaidRawTransaction (write-only sink)
            const raw = await prisma.plaidRawTransaction.upsert({
              where: { plaidTransactionId: tx.plaidId },
              update: {
                rawPlaidData: tx as unknown as Prisma.InputJsonValue,
                amount: new Prisma.Decimal(absoluteAmount),
                direction,
                name: tx.name,
                merchantName: tx.merchantName ?? null,
                pending: tx.pending,
                category: tx.category,
                postedDate: tx.date,
                removed: false,
                updatedAt: new Date(),
              },
              create: {
                plaidConnectionId: connection.id,
                plaidTransactionId: tx.plaidId,
                plaidAccountId: tx.accountId,
                rawPlaidData: tx as unknown as Prisma.InputJsonValue,
                amount: new Prisma.Decimal(absoluteAmount),
                direction,
                name: tx.name,
                merchantName: tx.merchantName ?? null,
                pending: tx.pending,
                category: tx.category,
                postedDate: tx.date,
              },
            });
            rawUpserted++;

            // 2. Upsert FinancialTransaction ledger entry
            await prisma.financialTransaction.upsert({
              where: { plaidTransactionId: raw.id },
              update: {
                amount: new Prisma.Decimal(absoluteAmount),
                direction: bridge.direction,
                transactionDate: tx.date,
                postedDate: tx.pending ? null : tx.date,
                payee: tx.merchantName ?? tx.name,
                description: tx.name,
                category: bridge.category,
                status: tx.pending ? 'PENDING_REVIEW' : 'AUTO_APPROVED',
                confidenceScore: classified.confidence,
              },
              create: {
                projectId: connection.projectId ?? '',
                userId: connection.userId,
                source: 'PLAID_TRANSACTIONS',
                plaidTransactionId: raw.id,
                amount: new Prisma.Decimal(absoluteAmount),
                direction: bridge.direction,
                transactionDate: tx.date,
                postedDate: tx.pending ? null : tx.date,
                payee: tx.merchantName ?? tx.name,
                description: tx.name,
                category: bridge.category,
                status: tx.pending ? 'PENDING_REVIEW' : 'AUTO_APPROVED',
                confidenceScore: classified.confidence,
                ...(bridge.taxTreatment ? { taxTreatment: bridge.taxTreatment as any } : {}),
              },
            });
            ledgerUpserted++;
          }

          // ── Removed ──────────────────────────────────────────────────────
          for (const plaidId of result.removed) {
            try {
              await prisma.plaidRawTransaction.update({
                where: { plaidTransactionId: plaidId },
                data: { removed: true, updatedAt: new Date() },
              });
            } catch {
              // already removed or never synced — skip
            }
          }

          cursor = result.nextCursor;
          hasMore = result.hasMore;
        }

        // Mark connection sync success
        await prisma.plaidConnection.update({
          where: { id: connection.id },
          data: {
            lastSyncCursor: cursor,
            lastSyncAt: new Date(),
            lastSuccessfulSyncAt: new Date(),
            syncErrorCount: 0,
            lastSyncErrorMessage: null,
            status: 'ACTIVE',
          },
        });

        synced++;
      } catch (err: any) {
        failures++;
        const msg = err instanceof Error ? err.message : String(err);
        console.error(`[SyncFinancialTransactions] Failed for connection ${connection.id}:`, msg);

        await prisma.plaidConnection.update({
          where: { id: connection.id },
          data: {
            syncErrorCount: { increment: 1 },
            lastSyncErrorMessage: msg.slice(0, 500),
            ...(msg.includes('ITEM_LOGIN_REQUIRED') || msg.includes('item_login_required')
              ? { status: 'ERROR' }
              : {}),
          },
        });
      }
    }

    // PostHog telemetry
    const posthogKey = process.env.NEXT_PUBLIC_POSTHOG_KEY;
    if (posthogKey && synced > 0) {
      fetch('https://app.posthog.com/capture/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          api_key: posthogKey,
          event: 'financial_transactions_synced',
          distinct_id: 'system',
          properties: { synced, failures, rawUpserted, ledgerUpserted },
        }),
      }).catch(() => {/* ignore */});
    }

    return NextResponse.json({ synced, failures, rawUpserted, ledgerUpserted });
  } catch (error: any) {
    console.error('[SyncFinancialTransactions] Fatal:', error);
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

