/**
 * Google Drive Folder Provisioning Endpoint
 * 
 * Authenticates via GCP Service Account, creates a parent folder named
 * after the property address, generates 3 nested sub-folders, and writes
 * the resulting folder URLs back to the Deal document in Firestore.
 * 
 * POST /api/drive/provision
 * Body: { idToken: string, projectId: string, propertyAddress: string }
 */

// Sub-folders to create inside each property folder
const SUB_FOLDERS = ['Closing Docs', 'Receipts', 'Permits'] as const;

/**
 * Creates a Google Drive folder and returns its ID + web link
 */
async function createFolder(
  drive: ReturnType<typeof google.drive>,
  name: string,
  parentId?: string
): Promise<{ id: string; webViewLink: string }> {
  const fileMetadata: any = {
    name,
    mimeType: 'application/vnd.google-apps.folder',
  };
  if (parentId) {
    fileMetadata.parents = [parentId];
  }

  const response = await drive.files.create({
    requestBody: fileMetadata,
    fields: 'id, webViewLink',
  });

  return {
    id: response.data.id as string,
    webViewLink: response.data.webViewLink as string,
  };
}

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { idToken, projectId, propertyAddress } = body;

    // ── Authentication ──────────────────────────────────────────
    if (!idToken || !projectId || !propertyAddress) {
      return NextResponse.json(
        { error: 'Missing required fields: idToken, projectId, propertyAddress' },
        { status: 400 }
      );
    }

    const decodedToken = await adminAuth.verifyIdToken(idToken);
    const uid = decodedToken.uid;

    // Verify the deal exists and belongs to this user's organization
    const dealRef = adminDb.collection('projects').doc(projectId);
    const dealSnap = await dealRef.get();

    if (!dealSnap.exists) {
      return NextResponse.json({ error: 'Deal not found.' }, { status: 404 });
    }

    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ error: 'User profile not found.' }, { status: 404 });
    }

    const dealData = dealSnap.data();
    const userData = userSnap.data();

    if (dealData?.organizationId !== userData?.organizationId) {
      return NextResponse.json({ error: 'Cross-tenant access denied.' }, { status: 403 });
    }

    // ── Google Drive Client Setup ───────────────────────────────
    const auth = new google.auth.GoogleAuth({
      credentials: {
        client_email: process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL,
        private_key: process.env.GOOGLE_SERVICE_ACCOUNT_PRIVATE_KEY?.replace(/\\n/g, '\n'),
      },
      scopes: ['https://www.googleapis.com/auth/drive'],
    });

    const drive = google.drive({ version: 'v3', auth });

    // ── Folder Creation Pipeline ────────────────────────────────

    // 1. Create the parent folder named after the property address
    const parentFolder = await createFolder(drive, `PW — ${propertyAddress}`);

    // 2. Create nested sub-folders inside the parent
    const subFolderResults: Record<string, { id: string; webViewLink: string }> = {};

    for (const folderName of SUB_FOLDERS) {
      const result = await createFolder(drive, folderName, parentFolder.id);
      subFolderResults[folderName] = result;
    }

    // ── Firestore Update ────────────────────────────────────────
    // Write the folder structure back to the Deal document
    const driveFolders = {
      parentFolderId: parentFolder.id,
      parentFolderUrl: parentFolder.webViewLink,
      subFolders: {
        closingDocs: {
          id: subFolderResults['Closing Docs'].id,
          url: subFolderResults['Closing Docs'].webViewLink,
        },
        receipts: {
          id: subFolderResults['Receipts'].id,
          url: subFolderResults['Receipts'].webViewLink,
        },
        permits: {
          id: subFolderResults['Permits'].id,
          url: subFolderResults['Permits'].webViewLink,
        },
      },
    };

    await dealRef.update({
      driveFolders,
      updatedAt: FieldValue.serverTimestamp(),
    });

    return NextResponse.json({
      success: true,
      projectId,
      driveFolders,
    });
  } catch (error: any) {
    console.error('[Drive Provision] Error:', error);

    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ error: 'Session expired. Please re-authenticate.' }, { status: 401 });
    }

    return NextResponse.json(
      { error: 'Failed to provision Drive folders.', details: error.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { CommunicationEngine } from '@/lib/engine/CommunicationEngine';

/**
 * Transactional Email API — Unified via CommunicationEngine
 *
 * POST /api/emails/send
 * Body: {
 *   idToken: string
 *   projectId: string
 *   to: string[]           // recipient email addresses
 *   subject: string
 *   html: string           // HTML body
 *   text?: string          // plain-text fallback
 * }
 *
 * All dispatch, audit logging, and delivery tracking is handled by
 * the CommunicationEngine module. The route only handles auth validation
 * and cross-tenant security checks.
 */

interface SendEmailBody {
  idToken: string;
  projectId: string;
  to: string[];
  subject: string;
  html: string;
  text?: string;
}

export async function POST(request: NextRequest) {
  try {
    const body: SendEmailBody = await request.json();
    const { idToken, projectId, to, subject, html, text } = body;

    // ── Validation ─────────────────────────────────────────
    if (!idToken || !projectId || !to?.length || !subject || !html) {
      return NextResponse.json(
        { error: 'Missing required fields: idToken, projectId, to, subject, html' },
        { status: 400 },
      );
    }

    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    const [dealSnap, userSnap] = await Promise.all([
      adminDb.collection('projects').doc(projectId).get(),
      adminDb.collection('users').doc(uid).get(),
    ]);

    if (!dealSnap.exists) return NextResponse.json({ error: 'Deal not found.' }, { status: 404 });
    if (!userSnap.exists) return NextResponse.json({ error: 'User not found.' }, { status: 404 });

    const dealData = dealSnap.data()!;
    const userData = userSnap.data()!;

    if (dealData.organizationId !== userData.organizationId) {
      return NextResponse.json({ error: 'Cross-tenant access denied.' }, { status: 403 });
    }

    // ── Dispatch via CommunicationEngine ────────────────────
    const result = await CommunicationEngine.sendCustomEmail({
      senderUid: uid,
      projectId,
      to,
      subject,
      html,
      text,
    });

    if (!result.success) {
      return NextResponse.json({ error: result.error || 'Failed to send.' }, { status: 500 });
    }

    return NextResponse.json({
      success: true,
      messageId: result.messageId,
      mock: result.mock,
      recipientCount: result.recipientCount,
      ...(result.mock && { message: 'Email mocked — set RESEND_API_KEY to enable live delivery.' }),
    });
  } catch (error: any) {
    console.error('[Email Send] Error:', error);
    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ error: 'Session expired.' }, { status: 401 });
    }
    return NextResponse.json(
      { error: 'Failed to send email.', details: error.message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { getESignProvider } from '@/lib/providers/esign';
import { logger } from '@/lib/logger';

/**
 * POST /api/esign/create
 *
 * Creates an e-signature envelope for a project document.
 *
 * Security contract:
 *   • Requires Firebase ID token (Bearer scheme). No token → 401.
 *   • Caller must be a member of the project. Not a member → 403.
 *   • Provider (DocuSign or Mock) is selected via ESIGN_PROVIDER env var.
 *   • On success, writes the envelopeId + status to Firestore so the UI
 *     can poll /api/esign/status/[envelopeId] or wait for the webhook.
 *
 * Body:
 *   projectId    string  (required)
 *   documentId   string  (required)  — Firestore document ID in project's documents subcollection
 *   documentName string  (required)  — Human-readable label
 *   signerRole   string  (required)  — e.g. "General Contractor"
 *   signerEmail  string  (required)
 *   signerName   string  (required)
 *   documentUrl  string  (required)  — Firebase Storage download URL
 */

export async function POST(req: NextRequest) {
  // ── 1. Authenticate ──────────────────────────────────────────────────────
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;
  const callerUid = auth.uid;

  // ── 2. Parse body ────────────────────────────────────────────────────────
  let body: {
    projectId: string;
    documentId: string;
    documentName: string;
    signerRole: string;
    signerEmail: string;
    signerName: string;
    documentUrl: string;
  };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  const { projectId, documentId, documentName, signerRole, signerEmail, signerName, documentUrl } = body;
  if (!projectId || !documentId || !documentName || !signerRole || !signerEmail || !signerName || !documentUrl) {
    return NextResponse.json(
      { success: false, error: 'Missing required fields: projectId, documentId, documentName, signerRole, signerEmail, signerName, documentUrl' },
      { status: 400 },
    );
  }

  // ── 3. Verify project membership ─────────────────────────────────────────
  try {
    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return NextResponse.json({ success: false, error: 'Project not found' }, { status: 404 });
    }

    const project = projectSnap.data()!;
    const members = project.members ?? {};
    let authorized = !!members[callerUid];

    if (!authorized) {
      const callerSnap = await adminDb.collection('users').doc(callerUid).get();
      const callerOrgId = callerSnap.data()?.organizationId;
      if (callerOrgId && callerOrgId === project.organizationId) authorized = true;
    }

    if (!authorized) {
      logger.warn('[esign/create] Unauthorized attempt', { callerUid, projectId });
      return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
    }

    // ── 4. Create envelope via provider ────────────────────────────────────
    const provider = getESignProvider();
    const result = await provider.createEnvelope({
      projectId, documentId, documentName, signerRole, signerEmail, signerName, documentUrl,
    });

    // ── 5. Persist envelope record to Firestore ───────────────────────────
    const envelopeRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('esign_envelopes')
      .doc(result.envelopeId);

    // Only write if the mock adapter hasn't already created the doc
    const existing = await envelopeRef.get();
    if (!existing.exists) {
      await envelopeRef.set({
        envelopeId:   result.envelopeId,
        provider:     provider.providerName,
        documentId,
        documentName,
        signerRole,
        signerEmail,
        signerName,
        status:       result.status,
        createdAt:    result.createdAt,
        updatedAt:    result.createdAt,
        requestedByUid: callerUid,
      });
    }

    // ── 6. Update the DealDocument's eSignStatus to 'Awaiting Signature' ──
    await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('documents')
      .doc(documentId)
      .update({
        eSignStatus:       'Awaiting Signature',
        eSignRequestedAt:  new Date(),
        eSignEnvelopeId:   result.envelopeId,
        eSignProvider:     provider.providerName,
      });

    logger.info('[esign/create] Envelope created', {
      projectId, documentId, envelopeId: result.envelopeId, provider: provider.providerName,
    });

    // Send signature request notification to the signer (failure-isolated)
    try {
      const { NotificationService } = await import('@/lib/services/notificationService');
      const { adminAuth } = await import('@/lib/firebase/admin');
      const userRecord = await adminAuth.getUserByEmail(signerEmail).catch(() => null);
      if (userRecord?.uid) {
        await NotificationService.createNotification({
          recipientId: userRecord.uid,
          type: 'DOCUMENT_SIGNED',
          actor: { uid: callerUid, name: auth.token.name || auth.token.email || 'LeadInvestor' },
          objectReference: {
            projectId,
            dealAddress: project.propertyName || project.address?.street || 'the project',
            documentName,
            task: `Signature required: Please sign '${documentName}'`,
          },
          deepLinkUrl: `/dashboard/projects/${projectId}`,
        });
      }
    } catch (notifErr: any) {
      logger.error('[esign/create] Failed to send signature request notification:', notifErr.message);
    }

    return NextResponse.json({
      success:    true,
      envelopeId: result.envelopeId,
      status:     result.status,
      signingUrl: result.signingUrl ?? null,
      provider:   provider.providerName,
    });
  } catch (error) {
    logger.error('[esign/create] Unexpected error', error instanceof Error ? error : undefined);
    return NextResponse.json({ success: false, error: 'Failed to create envelope' }, { status: 500 });
  }
}

