      type: 'APPEAL_REQUEST',
      userId: uid,
      details: `Lead Investor requested appeal for invitation suspension. Reason: ${reason || 'No details provided.'}`,
      createdAt: new Date(),
      resolved: false,
    });

    // 2. Update user profile to track appeal status
    await userRef.update({
      appealSubmitted: true,
      appealReason: reason || '',
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    return NextResponse.json({
      success: true,
      message: 'Your appeal has been submitted successfully. Our safety team will review it within 24 hours.',
    });
  } catch (err: any) {
    console.error('[Appeal Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { mergeIdentityHistory } from '@/lib/firebase/identityMerge';
import { telemetry } from '@/lib/telemetry';
import * as admin from 'firebase-admin';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const body = await request.json();
    const { token } = body;

    if (!token || typeof token !== 'string') {
      return NextResponse.json({ error: 'token is required.' }, { status: 400 });
    }

    let invitedEmail = '';
    let inviteDocRef: any = null;

    // 1. Search dealInvitations
    const dealInvSnap = await adminDb.collection('dealInvitations')
      .where('token', '==', token)
      .limit(1)
      .get();
    if (!dealInvSnap.empty) {
      const dealInv = dealInvSnap.docs[0].data();
      invitedEmail = dealInv.inviteeEmail;
      inviteDocRef = dealInvSnap.docs[0].ref;
    } else {
      // 2. Search teamInvitations
      const teamInvSnap = await adminDb.collection('teamInvitations')
        .where('token', '==', token)
        .limit(1)
        .get();
      if (!teamInvSnap.empty) {
        const teamInv = teamInvSnap.docs[0].data();
        invitedEmail = teamInv.email;
        inviteDocRef = teamInvSnap.docs[0].ref;
      }
    }

    if (!invitedEmail) {
      return NextResponse.json({ error: 'Invitation not found.' }, { status: 404 });
    }

    const emailLower = invitedEmail.toLowerCase().trim();

    // 3. Perform merge (token anchors identity, so no verification is needed)
    const userDisplayName = auth.token.name || '';
    await mergeIdentityHistory(uid, emailLower, userDisplayName);

    // 4. Update the invitation record
    if (inviteDocRef) {
      await inviteDocRef.update({
        inviteeUid: uid,
        ...(userDisplayName ? { inviteeName: userDisplayName } : {}),
      });
    }

    // 5. Update user document claimedEmails array
    const userRef = adminDb.collection('users').doc(uid);
    await userRef.update({
      claimedEmails: admin.firestore.FieldValue.arrayUnion(emailLower),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    // 6. Telemetry event
    try {
      await telemetry.capture({
        distinctId: uid,
        event: 'identity_history_bound_via_token',
        properties: {
          claimedEmail: emailLower,
          token,
          timestamp: new Date().toISOString(),
        },
      });
    } catch (telemetryErr) {
      console.error('[Claim/BindToken] Telemetry failed:', telemetryErr);
    }

    return NextResponse.json({
      success: true,
      message: `History for ${emailLower} has been bound successfully.`,
    });
  } catch (err: any) {
    console.error('[Claim/BindToken Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { CommunicationEngine } from '@/lib/engine/CommunicationEngine';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const body = await request.json();
    const { claimEmail } = body;

    if (!claimEmail || typeof claimEmail !== 'string') {
      return NextResponse.json({ error: 'claimEmail is required.' }, { status: 400 });
    }

    const emailLower = claimEmail.toLowerCase().trim();

    if (auth.token.email?.toLowerCase() === emailLower) {
      return NextResponse.json({ error: 'You cannot claim your own primary email.' }, { status: 400 });
    }

    // 1. Verify history exists in the database
    const [dealInv, teamInv, contacts, commitments] = await Promise.all([
      adminDb.collection('dealInvitations').where('inviteeEmail', '==', emailLower).limit(1).get(),
      adminDb.collection('teamInvitations').where('email', '==', emailLower).limit(1).get(),
      adminDb.collectionGroup('investor_contacts').where('email', '==', emailLower).limit(1).get(),
      adminDb.collectionGroup('commitments').where('email', '==', emailLower).limit(1).get(),
    ]);

    const hasHistory = !dealInv.empty || !teamInv.empty || !contacts.empty || !commitments.empty;
    if (!hasHistory) {
      return NextResponse.json({ error: 'No prior history found for this email address.' }, { status: 400 });
    }

    // 2. Generate secure 6-digit code
    const code = Math.floor(100000 + Math.random() * 900000).toString();

    // 3. Store code in identityVerificationClaims
    const docId = `${uid}_${emailLower}`;
    await adminDb.collection('identityVerificationClaims').doc(docId).set({
      userId: uid,
      claimEmail: emailLower,
      code,
      expiresAt: new Date(Date.now() + 15 * 60 * 1000), // 15 mins
      verified: false,
      createdAt: new Date(),
    });

    // 4. Send email
    const subject = 'Your PaperWorking Verification Code';
    const emailHtml = `
      <div style="font-family: sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #eee; border-radius: 8px;">
        <h2>Verify your email to claim your PaperWorking history</h2>
        <p>You requested to claim the history of <strong>${emailLower}</strong> and merge it with your account.</p>
        <p>Please enter the following 6-digit verification code in your settings panel:</p>
        <div style="background: #f4f4f5; padding: 15px; text-align: center; font-size: 24px; font-weight: bold; letter-spacing: 4px; border-radius: 6px; margin: 20px 0;">
          ${code}
        </div>
        <p style="font-size: 12px; color: #666;">This code will expire in 15 minutes. If you did not request this, you can ignore this email.</p>
      </div>
    `;

    await CommunicationEngine.sendRawEmail([emailLower], subject, emailHtml);

    return NextResponse.json({ success: true, message: 'Verification code sent.' });
  } catch (err: any) {
    console.error('[Claim/Start Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { mergeIdentityHistory } from '@/lib/firebase/identityMerge';
import { telemetry } from '@/lib/telemetry';
import * as admin from 'firebase-admin';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const body = await request.json();
    const { claimEmail, code } = body;

    if (!claimEmail || !code) {
      return NextResponse.json({ error: 'claimEmail and code are required.' }, { status: 400 });
    }

    const emailLower = claimEmail.toLowerCase().trim();
    const docId = `${uid}_${emailLower}`;
    const claimRef = adminDb.collection('identityVerificationClaims').doc(docId);
    const claimSnap = await claimRef.get();

    if (!claimSnap.exists) {
      return NextResponse.json({ error: 'Verification code not found or expired.' }, { status: 400 });
    }

    const claim = claimSnap.data()!;
    if (claim.code !== code.trim()) {
      return NextResponse.json({ error: 'Invalid verification code.' }, { status: 400 });
    }

    const expiresAt = claim.expiresAt?.toDate ? claim.expiresAt.toDate() : new Date(claim.expiresAt);
    if (expiresAt < new Date()) {
      return NextResponse.json({ error: 'Verification code has expired.' }, { status: 400 });
    }

    if (claim.verified) {
      return NextResponse.json({ error: 'This email has already been verified.' }, { status: 400 });
    }

    // 1. Mark verified
    await claimRef.update({
      verified: true,
      verifiedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    // 2. Perform merge
    const userDisplayName = auth.token.name || '';
    await mergeIdentityHistory(uid, emailLower, userDisplayName);

    // 3. Update user document claimedEmails array
    const userRef = adminDb.collection('users').doc(uid);
    await userRef.update({
      claimedEmails: admin.firestore.FieldValue.arrayUnion(emailLower),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    // 4. Telemetry event
    try {
      await telemetry.capture({
        distinctId: uid,
        event: 'identity_history_claimed',
        properties: {
          claimedEmail: emailLower,
          timestamp: new Date().toISOString(),
        },
      });
    } catch (telemetryErr) {
      console.error('[Claim/Verify] Telemetry failed:', telemetryErr);
    }

    return NextResponse.json({
      success: true,
      message: `History for ${emailLower} has been successfully merged.`,
    });
  } catch (err: any) {
    console.error('[Claim/Verify Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import * as admin from 'firebase-admin';

export const dynamic = 'force-dynamic';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { email, token, projectId } = body;

    if (!email || !token || !projectId) {
      return NextResponse.json(
        { error: 'Missing required fields: email, token, projectId.' },
        { status: 400 }
      );
    }

    const emailLower = email.toLowerCase().trim();

    // 1. Locate invitation by token
    let invitationDoc: any = null;
    let inviterUid = '';

    const dealInvSnap = await adminDb.collection('dealInvitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    if (!dealInvSnap.empty) {
      invitationDoc = dealInvSnap.docs[0];
      const data = invitationDoc.data();
      inviterUid = data.inviterUid || '';
    } else {
      const legacyInvSnap = await adminDb.collection('invitations')
        .where('token', '==', token)
        .limit(1)
        .get();
      if (!legacyInvSnap.empty) {
        invitationDoc = legacyInvSnap.docs[0];
        const data = invitationDoc.data();
        inviterUid = data.invitedByUid || '';
      }
    }

    if (!invitationDoc) {
      return NextResponse.json({ error: 'Invitation not found for the provided token.' }, { status: 404 });
    }

    // 2. Update invitation status to reported
    await invitationDoc.ref.update({
      status: 'reported',
      reportedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    // 3. Log to operatorQueue
    await adminDb.collection('operatorQueue').add({
      type: 'RECIPIENT_REPORT',
      userId: inviterUid,
      projectId,
      email: emailLower,
      details: `Recipient (${emailLower}) reported invitation for project ${projectId} as spam.`,
      createdAt: new Date(),
      resolved: false,
    });

    // 4. Increment complaint count and apply suspension if threshold met (>= 2 complaints)
    if (inviterUid) {
      const userRef = adminDb.collection('users').doc(inviterUid);
      const userSnap = await userRef.get();

      let currentComplaints = 0;
      if (userSnap.exists) {
        currentComplaints = userSnap.data()?.complaintCount || 0;
      }

      const newComplaints = currentComplaints + 1;
      const userUpdates: Record<string, any> = {
        complaintCount: newComplaints,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      };

      if (newComplaints >= 2) {
        userUpdates.invitationSuspended = true;
        userUpdates.suspensionReason = 'USER_COMPLAINT';

        // Log suspension alert to operatorQueue
        await adminDb.collection('operatorQueue').add({
          type: 'SUSPENSION_ALERT',
          userId: inviterUid,
          details: `Lead Investor invitation privileges suspended automatically due to complaint threshold breach (${newComplaints} complaints).`,
          createdAt: new Date(),
          resolved: false,
        });
      }

      await userRef.update(userUpdates);
    }

    return NextResponse.json({
      success: true,
      message: 'Thank you for your report. The invitation has been reported and logged.',
    });
  } catch (err: any) {
    console.error('[Spam Report Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

