}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { adminDb } from '@/lib/firebase/admin';
import { calculateKPIs } from '@/lib/insights/kpiEngine';

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const userId = searchParams.get('userId') || searchParams.get('uid');

    let projects: any[] = [];
    let userPersona: string | undefined = undefined;

    if (userId) {
      // 1. Fetch user to determine persona
      const userRecord = await prisma.user.findUnique({
        where: { id: userId },
      });

      if (userRecord) {
        userPersona = (userRecord as any).agentPersona || undefined;
      }

      // 2. Query Prisma for projects owned by user
      const dbProjects = await prisma.project.findMany({
        where: { userId },
        orderBy: { createdAt: 'desc' },
      });

      projects = dbProjects.map((p: any) => ({
        id: p.id,
        title: p.title || p.propertyName || 'Project',
        propertyName: p.title || p.propertyName || 'Project',
        userId: p.userId,
        currentPhase: p.currentPhase,
        dispositionType: p.dispositionType,
        createdAt: p.createdAt ? new Date(p.createdAt).toISOString() : new Date().toISOString(),
        syntheticAgent: p.syntheticAgent,
        financials: p.financials || {},
      }));

      // Fallback to Firestore if no projects in Prisma
      if (projects.length === 0) {
        const snap = await adminDb
          .collection('projects')
          .where('userId', '==', userId)
          .get();

        if (!snap.empty) {
          projects = snap.docs.map((d) => ({ id: d.id, ...d.data() }));
        }
      }
    }

    // If still no projects found, check if userId matches synthetic agent handles or UIDs in fixture
    if (projects.length === 0) {
      const allProjectsSnap = await adminDb.collection('projects').get();
      if (!allProjectsSnap.empty) {
        projects = allProjectsSnap.docs.map((d) => ({ id: d.id, ...d.data() }));
        if (userId) {
          projects = projects.filter((p) => p.userId === userId || p.listedByAgent === userId);
        }
      }
    }

    const kpiResult = calculateKPIs(projects, userPersona);

    return NextResponse.json({
      success: true,
      persona: kpiResult.persona,
      totalProjects: kpiResult.totalProjects,
      metrics: kpiResult.metrics,
      categories: kpiResult.categories,
    });
  } catch (err: any) {
    console.error('[API /api/insights GET]', err);
    return NextResponse.json(
      { error: 'Failed to calculate insights', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import prisma from '@/lib/prisma';

// In-memory cache for trends (1-hour TTL)
interface CacheEntry {
  data: any;
  expiresAt: number;
}
const cache = new Map<string, CacheEntry>();
const CACHE_TTL = 60 * 60 * 1000; // 1 hour in ms

export async function GET(req: NextRequest) {
  const authHeader = req.headers.get('Authorization');
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
  }

  const idToken = authHeader.split('Bearer ')[1];
  let userId: string;
  let orgId: string;

  try {
    const decoded = await adminAuth.verifyIdToken(idToken);
    userId = decoded.uid;
    orgId = decoded.organizationId || 'org_paperworking_seed';
  } catch (error) {
    console.error('[Insights Trends API] Token verification failed:', error);
    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
  }

  const { searchParams } = new URL(req.url);
  const metric = searchParams.get('metric') || 'noi';
  const projectId = searchParams.get('projectId') || null;

  // Cache lookup
  const cacheKey = `trends_${orgId}_${projectId || 'portfolio'}_${metric}`;
  const cached = cache.get(cacheKey);
  if (cached && Date.now() < cached.expiresAt) {
    return NextResponse.json(cached.data);
  }

  try {
    // 1. Fetch user's project list to ensure proper tenant/org isolation
    let projectIds: string[] = [];
    if (projectId) {
      const projSnap = await adminDb.collection('projects').doc(projectId).get();
      if (!projSnap.exists) {
        return NextResponse.json({ success: false, error: 'Project not found' }, { status: 404 });
      }
      const projData = projSnap.data();
      if (projData?.organizationId !== orgId) {
        return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
      }
      projectIds = [projectId];
    } else {
      const projectsSnap = await adminDb.collection('projects')
        .where('organizationId', '==', orgId)
        .get();
      projectIds = projectsSnap.docs.map(doc => doc.id);
    }

    // Generate chronological monthly keys for the last 24 months (e.g. 2024-06 to 2026-05)
    const months: string[] = [];
    const now = new Date();
    for (let i = 23; i >= 0; i--) {
      const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
      const year = d.getFullYear();
      const mStr = String(d.getMonth() + 1).padStart(2, '0');
      months.push(`${year}-${mStr}`);
    }

    let finalData: { date: string; value: number }[] = [];

    if (metric === 'occupancy') {
      // Query propertyMetricSnapshots from Firestore
      let queryRef: any = adminDb.collection('propertyMetricSnapshots')
        .where('periodType', '==', 'monthly');

      if (projectId) {
        queryRef = queryRef.where('projectId', '==', projectId);
      } else {
        queryRef = queryRef.where('organizationId', '==', orgId);
      }

      const snap = await queryRef.get();
      const grouped = new Map<string, { totalWeight: number; weightedSum: number; counts: number; sum: number }>();

      // Initialize groups for all 24 months
      for (const m of months) {
        grouped.set(m, { totalWeight: 0, weightedSum: 0, counts: 0, sum: 0 });
      }

      snap.docs.forEach((doc: any) => {
        const d = doc.data();
        const m = d.period; // YYYY-MM
        if (grouped.has(m) && d.occupancyRate !== undefined && d.occupancyRate !== null) {
          const occ = Number(d.occupancyRate);
          const weight = Number(d.propertyValue || d.totalCashInvested || 1);
          const grp = grouped.get(m)!;
          grp.weightedSum += occ * weight;
          grp.totalWeight += weight;
          grp.sum += occ;
          grp.counts += 1;
        }
      });

      finalData = months.map(m => {
        const grp = grouped.get(m)!;
        let value = 100.0; // Default to 100% if no data is found for the month
        if (projectId) {
          if (grp.counts > 0) {
            value = grp.sum / grp.counts;
          }
        } else {
          if (grp.totalWeight > 0) {
            value = grp.weightedSum / grp.totalWeight;
          } else if (grp.counts > 0) {
            value = grp.sum / grp.counts;
          }
        }
        return { date: m, value: Math.round(value * 10) / 10 };
      });

    } else {
      // Transaction-based metrics: noi, cash_flow, revenue, expenses
      if (projectIds.length === 0) {
        finalData = months.map(m => ({ date: m, value: 0 }));
      } else {
        const startDate = new Date();
        startDate.setMonth(startDate.getMonth() - 24);

        const txs = await prisma.transaction.findMany({
          where: {
            projectId: { in: projectIds },
            date: { gte: startDate },
          },
          orderBy: { date: 'asc' },
        });

        // Initialize maps
        const rentMap = new Map<string, number>();
        const opexMap = new Map<string, number>();
        const allExpensesMap = new Map<string, number>();

        for (const m of months) {
          rentMap.set(m, 0);
          opexMap.set(m, 0);
          allExpensesMap.set(m, 0);
        }

        const opexCategories = ['hoa_fees', 'insurance', 'property_tax', 'maintenance', 'utilities', 'property_management'];
        const allExpenseCategories = [...opexCategories, 'debt_service', 'rehab_staging', 'closing_costs', 'unknown'];

        txs.forEach(t => {
          const dateObj = new Date(t.date);
          const year = dateObj.getFullYear();
          const mStr = String(dateObj.getMonth() + 1).padStart(2, '0');
          const m = `${year}-${mStr}`;

          if (rentMap.has(m)) {
            const amountVal = Math.abs(Number(t.amount)) / 100;
            const category = t.reiCategory || 'unknown';

            if (category === 'rental_income') {
              rentMap.set(m, rentMap.get(m)! + amountVal);
            } else if (opexCategories.includes(category)) {
              opexMap.set(m, opexMap.get(m)! + amountVal);
              allExpensesMap.set(m, allExpensesMap.get(m)! + amountVal);
            } else if (allExpenseCategories.includes(category)) {
              allExpensesMap.set(m, allExpensesMap.get(m)! + amountVal);
            }
          }
        });

        finalData = months.map(m => {
          const rents = rentMap.get(m)!;
          const opex = opexMap.get(m)!;
          const expenses = allExpensesMap.get(m)!;

          let val = 0;
          if (metric === 'noi') {
            val = rents - opex;
          } else if (metric === 'cash_flow') {
            val = rents - expenses;
          } else if (metric === 'revenue') {
            val = rents;
          } else if (metric === 'expenses') {
            val = opex;
          }

          return { date: m, value: Math.round(val) };
        });
      }
    }

    const resPayload = finalData;

    // Cache the result
    cache.set(cacheKey, {
      data: resPayload,
      expiresAt: Date.now() + CACHE_TTL,
    });

    return NextResponse.json(resPayload);

  } catch (err: any) {
    console.error('[Trends API] Failure:', err);
    return NextResponse.json({ success: false, error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import * as admin from 'firebase-admin';

// Helper to determine headers for HTML responses
const htmlHeaders = { 'Content-Type': 'text/html; charset=utf-8' };

export async function GET(req: NextRequest, { params }: { params: { action?: string[] } }) {
  const actionPath = params.action || [];

  // 1. GET /api/integrations/[provider]/authorize
  if (actionPath.length === 2 && actionPath[1] === 'authorize') {
    const provider = actionPath[0];
    const origin = new URL(req.url).origin;

    // Redirect to mock OAuth callback
    const redirectUrl = `${origin}/api/integrations/${provider}/callback?code=mock_oauth_code_123`;
    return NextResponse.redirect(redirectUrl);
  }

  // 2. GET /api/integrations/[provider]/callback
  if (actionPath.length === 2 && actionPath[1] === 'callback') {
    const provider = actionPath[0];
    const code = req.nextUrl.searchParams.get('code') || 'no_code';

    // Verify token from query or headers if authenticated.
    // For popup auth, we can pass authorization/idToken via session state, cookie,
    // or simply hook up a generic callback since it's a simulated flow.
    // To identify the acting user, we can resolve from the mock callback state or default to orgId.
    // Let's retrieve from database: since we want to persist it, let's write to a generic placeholder organization
    // or read the user identity if the cookie/bearer token is present.
    let orgId = 'org_placeholder';
    try {
      const auth = await requireAuth(req);
      if (!isAuthError(auth)) {
        const userDoc = await adminDb.collection('users').doc(auth.uid).get();
        orgId = userDoc.data()?.organizationId || 'org_placeholder';
      }
    } catch {
      // Fallback for popup/redirect auth flows
    }

    // Save connection to Firestore
    await adminDb.collection('organizations').doc(orgId).collection('integrations').doc(provider).set({
      connected: true,
      status: 'connected',
      connectedAt: new Date().toISOString(),
      code,
    });

    // Render HTML template communicating with parent and self-closing
    const html = `
      <!DOCTYPE html>
      <html>
        <head>
          <title>Authorization Successful</title>
          <style>
            body {
              font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
              display: flex;
              flex-direction: column;
              align-items: center;
              justify-content: center;
              height: 100vh;
              margin: 0;
              background-color: #FAF9F6;
              color: #334155;
            }
            .card {
              background: white;
              padding: 2rem;
              border-radius: 1rem;
              box-shadow: 0 4px 6px -1px rgb(0 0 0 / 0.1);
              text-align: center;
            }
            h1 { font-size: 1.25rem; margin-bottom: 0.5rem; color: #6B8E6B; }
            p { font-size: 0.875rem; color: #64748B; }
          </style>
        </head>
        <body>
          <div class="card">
            <h1>Connection Successful</h1>
            <p>You have connected ${provider.toUpperCase()} to PaperWorking.</p>
            <p>Closing this window...</p>
          </div>
          <script>
            if (window.opener) {
              window.opener.postMessage({ type: 'INTEGRATION_SUCCESS', provider: '${provider}' }, '*');
            }
            setTimeout(() => {
              window.close();
            }, 1000);
          </script>
        </body>
      </html>
    `;

    return new NextResponse(html, { headers: htmlHeaders });
  }

  return NextResponse.json({ error: 'Endpoint not found' }, { status: 404 });
}

export async function DELETE(req: NextRequest, { params }: { params: { action?: string[] } }) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const actionPath = params.action || [];
  const uid = auth.uid;

  const userDoc = await adminDb.collection('users').doc(uid).get();
  const orgId = userDoc.data()?.organizationId || 'org_placeholder';

  // DELETE /api/integrations/[provider]/disconnect
  if (actionPath.length === 2 && actionPath[1] === 'disconnect') {
    const provider = actionPath[0];

    await adminDb.collection('organizations').doc(orgId).collection('integrations').doc(provider).delete();

    return NextResponse.json({ success: true });
  }

  return NextResponse.json({ error: 'Endpoint not found' }, { status: 404 });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { getDriveProvider } from '@/lib/providers/integrations/googleDrive';

/* ═══════════════════════════════════════════════════════════════
   GET /api/integrations/google-drive/authorize
   ───────────────────────────────────────────────────────────────
   Returns the Google consent-page URL for the authenticated user.
   The state parameter is HMAC-signed with WORKER_SECRET so the
   callback can verify it belongs to this user.

   Security:
   - Requires valid Firebase ID token (rejected → 401).
   - GOOGLE_CLIENT_SECRET never leaves the server.
   - State is signed; replayed or forged states are rejected.
   ═══════════════════════════════════════════════════════════════ */

export async function GET(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  try {
    const provider = getDriveProvider();
    const authUrl  = provider.getAuthUrl(auth.uid);
    return NextResponse.json({ authUrl });
  } catch (err: any) {
    console.error('[drive/authorize]', err.message);
    return NextResponse.json({ error: err.message ?? 'Failed to build auth URL' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { getDriveProvider, RealDriveProvider, verifyState } from '@/lib/providers/integrations/googleDrive';
import { FieldValue } from 'firebase-admin/firestore';

/* ═══════════════════════════════════════════════════════════════
   GET /api/integrations/google-drive/callback
   ───────────────────────────────────────────────────────────────
   Handles the OAuth2 callback from Google.

   Flow:
   1. Google redirects here with ?code=...&state=...
   2. State is verified (HMAC + timestamp TTL) — contains uid.
   3. Code is exchanged for tokens server-side.
   4. Connected status + email written to Firestore:
      users/{uid}/integrations/google_drive
   5. Returns a minimal HTML page that posts a message to the
      opener window and closes itself (popup pattern).

   Security:
   - State is HMAC-signed — forged or replayed states are rejected.
   - Refresh token stored in Firestore server-side, never in client.
   - No secrets appear in the response.
   ═══════════════════════════════════════════════════════════════ */

function closePopup(success: boolean, errorMsg?: string): NextResponse {
  const message = success
    ? { type: 'google-drive-connected', success: true }
    : { type: 'google-drive-connected', success: false, error: errorMsg ?? 'Unknown error' };

  const html = `<!DOCTYPE html>
<html>
<head><title>Connecting…</title></head>
<body style="font-family:system-ui;display:flex;align-items:center;justify-content:center;height:100vh;background:#0d0a0b;color:#9E9DA0;">
  <p>${success ? 'Connected! Closing…' : `Error: ${errorMsg}`}</p>
  <script>
    try {
      window.opener && window.opener.postMessage(${JSON.stringify(message)}, window.location.origin);
    } catch(e) {}
    setTimeout(() => window.close(), 800);
  </script>
</body>
</html>`;

  return new NextResponse(html, {
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
    status: success ? 200 : 400,
  });
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const code  = searchParams.get('code');
  const state = searchParams.get('state');
  const error = searchParams.get('error');

  if (error) {
    return closePopup(false, `Google OAuth error: ${error}`);
  }

  if (!code || !state) {
    return closePopup(false, 'Missing code or state parameter');
  }

  try {
    const provider = getDriveProvider();

    let uid: string;
    let email: string;
    let refreshToken: string | null = null;

    if (provider instanceof RealDriveProvider) {
      const result = await provider.exchangeCodeWithTokens(code, state);
      uid          = result.uid;
      email        = result.email;
      refreshToken = result.refreshToken;
    } else {
      // Mock provider — verifyState handles CSRF check, exchangeCode returns fixed email
      const result = await provider.exchangeCode(code, state);
      uid   = result.uid;
      email = result.email;
    }

    // Store refresh token in a server-only subcollection (never readable by the client)
    if (refreshToken) {
      await adminDb
        .collection('users')
        .doc(uid)
        .collection('integrations_private')
        .doc('google_drive')
        .set({ refreshToken, updatedAt: FieldValue.serverTimestamp() });
    }

    // Public connection status — client reads this via /api/integrations/status
    await adminDb
      .collection('users')
      .doc(uid)
      .collection('integrations')
      .doc('google_drive')
      .set({ connected: true, email, updatedAt: FieldValue.serverTimestamp() });

    return closePopup(true);
  } catch (err: any) {
    console.error('[drive/callback]', err.message);
    return closePopup(false, err.message ?? 'Token exchange failed');
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { getMLSProvider } from '@/lib/providers/integrations/mls';
import { FieldValue } from 'firebase-admin/firestore';

/* ═══════════════════════════════════════════════════════════════
   POST /api/integrations/mls/connect
   ───────────────────────────────────────────────────────────────
   Tests the MLS connection and stores the result in Firestore.

   Security:
   - Requires valid Firebase ID token (rejected → 401).
   - BRIDGE_SERVER_TOKEN never leaves the server.
   - Provider failure is surfaced as a 502 with actionable message.
   ═══════════════════════════════════════════════════════════════ */

export async function POST(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const provider = getMLSProvider();

  let testResult: { ok: boolean; message: string };
  try {
    testResult = await provider.testConnection();
  } catch (err: any) {
    console.error('[mls/connect] provider error:', err.message);
    return NextResponse.json(
      { error: 'MLS connection failed', detail: err.message ?? 'Provider unreachable' },
      { status: 502 }
    );
  }

  if (!testResult.ok) {
    return NextResponse.json({ error: testResult.message }, { status: 502 });
  }

  // Persist connected status so the settings page reflects the real state
  await adminDb
    .collection('users')
    .doc(auth.uid)
    .collection('integrations')
    .doc('mls')
    .set({
      connected:  true,
      provider:   provider.providerId,
      updatedAt:  FieldValue.serverTimestamp(),
    });

  return NextResponse.json({ connected: true, message: testResult.message });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';

export const dynamic = 'force-dynamic';

export async function GET(request: NextRequest) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;
    const email = auth.token.email;
    const userSnap = await adminDb.collection('users').doc(uid).get();
    const userData = userSnap.exists ? userSnap.data() : null;

    if (userData && (userData.role === 'Vendor' || userData.accountType === 'vendor')) {
      return NextResponse.json({ error: 'Not Found' }, { status: 404 });
    }

    const claimedEmails: string[] = userData?.claimedEmails || [];
    const allUserEmails = [
      email?.toLowerCase().trim(),
      ...claimedEmails.map((e) => e.toLowerCase().trim()),
    ].filter(Boolean) as string[];

    // Fetch projects owned by this user
    const projectsSnap = await adminDb
      .collection('projects')
      .where('ownerUid', '==', uid)
      .get();
    const ownedProjectIds = new Set(projectsSnap.docs.map((d) => d.id));

    // Fetch all timeline events to filter in memory
    const activitiesSnap = await adminDb.collection('dealActivityTimeline').get();

    const activities = activitiesSnap.docs.map((d) => {
      const data = d.data();
      return {
        id: d.id,
        projectId: data.projectId,
        dealId: data.dealId,
        actorUid: data.actorUid,
        type: data.type,
        metadata: data.metadata || {},
        createdAt: data.createdAt?.toDate?.()?.toISOString() ?? data.createdAt ?? new Date().toISOString(),
      };
    });

    // Filter in-memory securely
    const filtered = activities.filter((act) => {
      // 1. If user is the Lead Investor of the project
      if (ownedProjectIds.has(act.projectId)) {
        return true;
      }
      // 2. If user is the direct actor of this event
      if (act.actorUid === uid) {
        return true;
      }
      // 3. If user is the invitee/recipient of this event
      const inviteeEmail = act.metadata?.inviteeEmail?.toLowerCase().trim();
      if (inviteeEmail && allUserEmails.includes(inviteeEmail)) {
        return true;
      }
      return false;
    });

    // Sort descending by date
    filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    return NextResponse.json({ timeline: filtered });
  } catch (err: any) {
    console.error('[Investor Timeline GET]', err.message);
    return NextResponse.json({ error: 'Failed to fetch investor timeline' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { FieldValue } from 'firebase-admin/firestore';
import { adminDb } from '@/lib/firebase/admin';
import { getEmailProvider } from '@/lib/email/getEmailProvider';
import { generateInvestorInquiryEmail } from '@/lib/emails/templates/InvestorInquiryEmail';

/* ═══════════════════════════════════════════════════════════════
   POST /api/invitations/[token]/ask

   Unauthenticated (investor-facing) — token is the credential,
   same trust model as /api/invitations/respond.

   Body: { message: string }

   Persists a real investor inquiry (projects/{id}/investorInquiries)
   and emails the deal owner — replaces the client-timer fake
   "Ask LeadInvestor" behavior on the Guest Portal.
   ═══════════════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';

const MAX_INQUIRIES_PER_INVITATION = 5;
const MAX_MESSAGE_LENGTH = 2000;

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;

  try {
    if (!token || typeof token !== 'string' || token.length < 16) {
      return NextResponse.json({ error: 'Invalid token format' }, { status: 400 });
    }

    const body = await request.json();
    const message: string = typeof body?.message === 'string' ? body.message.trim() : '';

    if (!message) {
      return NextResponse.json({ error: 'Message is required.' }, { status: 400 });
    }
    if (message.length > MAX_MESSAGE_LENGTH) {
      return NextResponse.json({ error: `Message must be ${MAX_MESSAGE_LENGTH} characters or fewer.` }, { status: 400 });
    }

    // ── Resolve invitation ──────────────────────────────────
    let snap = await adminDb
      .collection('invitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    let isDealInvitation = false;
    if (snap.empty) {
      snap = await adminDb
        .collection('dealInvitations')
        .where('token', '==', token)
        .limit(1)
        .get();
      if (!snap.empty) {
        isDealInvitation = true;
      }
    }

    if (snap.empty) {
      return NextResponse.json({ error: 'Invitation not found.' }, { status: 404 });
    }

    const invRef = snap.docs[0].ref;
    const rawInv = snap.docs[0].data();
    const inv = isDealInvitation
      ? {
          id: rawInv.id,
          token: rawInv.token,
          email: rawInv.inviteeEmail,
          name: rawInv.inviteeName || 'Anonymous Investor',
          projectId: rawInv.projectId,
          invitedByUid: rawInv.inviterUid || 'system',
          status: rawInv.status,
          createdAt: rawInv.createdAt,
          expiresAt: rawInv.expiresAt || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          version: rawInv.version || 1,
          visibilityMode: rawInv.visibilityMode || 'PRIVATE',
          listingId: rawInv.listingId || '',
        }
      : rawInv;

    const expiresAt: Date = inv.expiresAt?.toDate ? inv.expiresAt.toDate() : new Date(inv.expiresAt);
    if (expiresAt < new Date()) {
      return NextResponse.json({ error: 'This invitation link has expired.' }, { status: 410 });
    }

    const existingSnap = await adminDb
      .collection('projects')
      .doc(inv.projectId)
      .collection('investorInquiries')
      .where('invitationId', '==', invRef.id)
      .get();

    // ── Thread creation or message append ───────────────────
    const now = FieldValue.serverTimestamp();
    const newMessage = {
      id: `msg_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
      sender: 'investor',
      text: message,
      createdAt: new Date().toISOString(),
    };

    if (!existingSnap.empty) {
      const threadDoc = existingSnap.docs[0];
      const data = threadDoc.data();
      const messagesList = data.messages || [];

      // Check if thread has too many messages
      if (messagesList.length >= 20) {
        return NextResponse.json(
          { error: 'Message thread limit reached. Please wait for a response or contact support.' },
          { status: 429 }
        );
      }

      await threadDoc.ref.update({
        messages: FieldValue.arrayUnion(newMessage),
        status: 'open',
        updatedAt: now,
      });
    } else {
      await adminDb
        .collection('projects')
        .doc(inv.projectId)
        .collection('investorInquiries')
        .add({
          projectId: inv.projectId,
          invitationId: invRef.id,
          investorName: inv.name || 'Anonymous Investor',
          investorEmail: inv.email || null,
          message, // keep for backward compatibility
          status: 'open',
          isShared: false,
          messages: [newMessage],
          createdAt: now,
          updatedAt: now,
        });
    }

    // ── Write to dealLedger ──────────────────────────────────
    const ledgerRef = adminDb.collection('projects').doc(inv.projectId)
      .collection('dealLedger').doc();
    await ledgerRef.set({
      id: ledgerRef.id,
      projectId: inv.projectId,
      listingId: inv.listingId || '',
      eventType: 'INVITATION_RESPONSE',
      performedBy: inv.invitedByUid || 'system',
      inviteeEmail: inv.email || 'unknown',
      version: inv.version || 1,
      visibilityMode: inv.visibilityMode || 'PRIVATE',
      timestamp: new Date().toISOString(),
      metadata: {
        invitationId: invRef.id,
        status: 'question',
        question: message,
      },
    });

    // ── Track timeline activity ─────────────────────────────
    const { trackDealActivity } = require('@/lib/invitations/activityTimeline');
    await trackDealActivity(
      inv.projectId,
      inv.projectId,
      inv.invitedByUid || 'system',
      'question',
      {
        inviteeEmail: inv.email,
        questionText: message,
      }
    ).catch((e: any) => console.error('Failed to log question event:', e));

    // ── Notify the deal owner ───────────────────────────────
    const [projectSnap, ownerSnap] = await Promise.all([
      adminDb.collection('projects').doc(inv.projectId).get(),
      inv.invitedByUid && inv.invitedByUid !== 'system'
        ? adminDb.collection('users').doc(inv.invitedByUid).get()
        : Promise.resolve(null),
    ]);

    const dealName = projectSnap.data()?.propertyName ?? inv.dealName ?? 'Untitled Deal';
    const ownerEmail: string | null = ownerSnap?.data()?.email ?? null;

    if (ownerEmail) {
      const { subject, html, text } = generateInvestorInquiryEmail({
        investorName: inv.name || 'Anonymous Investor',
        investorEmail: inv.email || 'unknown',
        projectName: dealName,
        projectId: inv.projectId,
        message,
      });

      const emailProvider = getEmailProvider();
      await emailProvider.sendEmail({
        from: 'notifications@mail.paperworking.co',
        replyTo: inv.email || 'hi@paperworking.co',
        to: [ownerEmail],
        subject,
        templateKey: 'DEAL-MKT-INTEREST-RECEIVED',
        messageClass: 'O',
        html,
        text,
      });
    }

    // ── Audit log ────────────────────────────────────────────
    await adminDb.collection('auditLog').add({
      type: 'investor_inquiry',
      invitationId: invRef.id,
      projectId: inv.projectId,
      investorEmail: inv.email,
      investorName: inv.name,
      at: now,
    });

    return NextResponse.json({ success: true });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    console.error('[Invitations/Ask] Error:', msg);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminAuth } from '@/lib/firebase/admin';
import { getEmailProvider } from '@/lib/email/getEmailProvider';
import { renderEmailLayout } from '@/lib/emails/templates/BaseLayout';
import { trackDealActivity } from '@/lib/invitations/activityTimeline';
import { NON_BINDING_DISCLOSURE } from '@/lib/constants/disclosure';

export const dynamic = 'force-dynamic';

async function blockVendor(request: NextRequest) {
  const authHeader = request.headers.get('authorization') ?? request.headers.get('Authorization');
  let callerUid: string | null = null;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const idToken = authHeader.slice(7);
    try {
      const decoded = await adminDb.collection('users').doc(idToken).get();
      if (decoded.exists) callerUid = decoded.id;
      else {
        const decodedToken = await adminAuth.verifyIdToken(idToken);
        callerUid = decodedToken.uid;
      }
    } catch (e) {
      if ((idToken === 'mock_token' || idToken === 'mock_token_123' || idToken === 'mock_session_token_123') && process.env.ENABLE_MOCK_AUTH === 'true') {
        callerUid = request.cookies.get('mock_user_uid')?.value || null;
      }
    }
  } else if (process.env.ENABLE_MOCK_AUTH === 'true') {
    callerUid = request.cookies.get('mock_user_uid')?.value || null;
  }

  if (callerUid) {
    const userSnap = await adminDb.collection('users').doc(callerUid).get();
    const userData = userSnap.exists ? userSnap.data() : null;
    if (userData && (userData.role === 'Vendor' || userData.accountType === 'vendor')) {
      return true;
    }
  }
  return false;
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ token: string }> }
) {
  try {
    if (await blockVendor(request)) {
      return NextResponse.json({ error: 'Not Found' }, { status: 404 });
    }
    const { token } = await params;
    const body = await request.json();
    const { type, value, currency } = body;

    // Validate request inputs
    if (type !== 'percentage' && type !== 'amount') {
      return NextResponse.json(
        { error: 'Indication type must be "percentage" or "amount".' },
        { status: 400 }
      );
    }

    if (typeof value !== 'number' || value <= 0) {
      return NextResponse.json(
        { error: 'Indication value must be a positive number.' },
        { status: 400 }
      );
    }

    if (type === 'percentage' && value > 100) {
      return NextResponse.json(
        { error: 'Percentage value cannot exceed 100.' },
        { status: 400 }
      );
    }

    if (type === 'amount' && (!currency || typeof currency !== 'string' || currency.length !== 3)) {
      return NextResponse.json(
        { error: 'Indication amount requires a valid 3-letter currency code.' },
        { status: 400 }
      );
    }

    // Resolve invitation
    let isDealInvitation = false;
    let snap = await adminDb
      .collection('invitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    if (snap.empty) {
      snap = await adminDb
        .collection('dealInvitations')
        .where('token', '==', token)
        .limit(1)
        .get();
      if (!snap.empty) {
        isDealInvitation = true;
      }
    }

    if (snap.empty) {
      return NextResponse.json({ error: 'Invitation not found.' }, { status: 404 });
    }

    const invRef = snap.docs[0].ref;
    const inv = snap.docs[0].data();

    // Check expiration
    const expiresAt = inv.expiresAt?.toDate ? inv.expiresAt.toDate() : new Date(inv.expiresAt);
    if (expiresAt < new Date()) {
      return NextResponse.json({ error: 'This invitation has expired.' }, { status: 410 });
    }

    const cleanCurrency = type === 'amount' ? currency.toUpperCase().trim() : null;

    // Save to Firestore
    await invRef.update({
      indication: {
        type,
        value,
        currency: cleanCurrency,
        updatedAt: new Date().toISOString(),
      },
    });

    // Notify Lead Investor
    const inviterId = inv.inviterUid || inv.invitedByUid || 'system';
    const [projectSnap, ownerSnap] = await Promise.all([
      adminDb.collection('projects').doc(inv.projectId).get(),
      inviterId !== 'system'
        ? adminDb.collection('users').doc(inviterId).get()
        : Promise.resolve(null),
    ]);

    const dealName = projectSnap.exists
      ? (projectSnap.data()?.propertyName ?? 'Untitled Deal')
      : (inv.dealName ?? 'Untitled Deal');
    const ownerEmail = ownerSnap?.exists ? ownerSnap.data()?.email : null;

    const inviteeName = inv.inviteeName || inv.name || 'Anonymous Investor';
    const inviteeEmail = inv.inviteeEmail || inv.email;

    if (ownerEmail) {
      const formattedValue =
        type === 'amount'
          ? `${cleanCurrency} ${Number(value).toLocaleString()}`
          : `${value}%`;

      const emailBody = `
        <div style="font-family: sans-serif; line-height: 1.6; color: #333;">
          <h2 style="color: #0d0d0d;">Soft Commit Updated</h2>
          <p>An invitee has submitted or updated their non-binding indication of interest for the deal <strong>${dealName}</strong>.</p>
          <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
          <p><strong>Invitee Details:</strong></p>
          <ul style="list-style: none; padding: 0; margin: 0 0 20px 0;">
            <li><strong>Name:</strong> ${inviteeName}</li>
            <li><strong>Email:</strong> ${inviteeEmail}</li>
          </ul>
          <p><strong>Indicated Amount / Share:</strong></p>
          <p style="font-size: 20px; font-weight: bold; color: #10b981; margin: 0 0 20px 0;">
            ${formattedValue}
          </p>
          <p style="font-size: 11px; color: #666; margin-top: 20px; border-top: 1px solid #eee; padding-top: 10px;">
            * Note: ${NON_BINDING_DISCLOSURE}
          </p>
        </div>
      `;

      const html = renderEmailLayout({
        title: 'Soft Commit Updated',
        bodyHtml: emailBody,
        appUrl: process.env.NEXT_PUBLIC_APP_URL,
      });

      const plainText = `Soft Commit Updated\nAn invitee has submitted or updated their non-binding indication of interest for ${dealName}.\n\nInvitee: ${inviteeName} (${inviteeEmail})\nIndicated Amount/Share: ${formattedValue}\n\nNote: ${NON_BINDING_DISCLOSURE}`;

      const emailProvider = getEmailProvider();
      await emailProvider.sendEmail({
        from: 'notifications@mail.paperworking.co',
        replyTo: inviteeEmail || 'hi@paperworking.co',
        to: [ownerEmail],
        subject: `[Soft Commit] Indication of Interest update for ${dealName}`,
        templateKey: 'DEAL-MKT-INDICATION-UPDATED',
        messageClass: 'O',
        html,
        text: plainText,
      }).catch((e: any) => console.error('Failed to dispatch notification email:', e.message));
    }

    // Log timeline activity
    await trackDealActivity(
      inv.projectId,
      inv.projectId,
      inviterId,
      'interest',
      {
        inviteeEmail,
        indicatedType: type,
        indicatedValue: value,
        indicatedCurrency: cleanCurrency,
      }
    ).catch((e: any) => console.error('Failed to log indication timeline event:', e));

    // Track event via Event Taxonomy
    try {
      const { trackEvent } = require('@/actions/telemetry');
      await trackEvent('deal_interest_indicated', {
        listingId: inv.listingId || null,
        projectId: inv.projectId,
        type,
        currency: cleanCurrency,
        value,
      }, token);
    } catch (e) {
      console.error('Failed to log indication telemetry event:', e);
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[Indication POST Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

