        to: [ownerEmail],
        subject: `[Soft Commit] Indication of Interest withdrawn for ${dealName}`,
        templateKey: 'DEAL-MKT-INDICATION-WITHDRAWN',
        messageClass: 'O',
        html,
        text: plainText,
      }).catch((e: any) => console.error('Failed to dispatch notification email:', e.message));
    }

    // Log timeline activity
    await trackDealActivity(
      inv.projectId,
      inv.projectId,
      inviterId,
      'decline',
      {
        inviteeEmail,
        withdrawnIndication: true,
      }
    ).catch((e: any) => console.error('Failed to log indication timeline event:', e));

    // Track event via Event Taxonomy
    try {
      const { trackEvent } = require('@/actions/telemetry');
      await trackEvent('deal_interest_indicated', {
        listingId: inv.listingId || null,
        projectId: inv.projectId,
        type: 'amount',
        currency: null,
        value: 0,
      }, token);
    } catch (e) {
      console.error('Failed to log indication telemetry event:', e);
    }

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[Indication DELETE Error]', err.message);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminAuth } from '@/lib/firebase/admin';
import { fetchPropertyMetricHistory, computeRaiseCountdown, computeRaiseProgress } from '@/lib/reporting/propertyMetricHistory';

/* ═══════════════════════════════════════════════════════
   GET /api/invitations/[token]

   Public endpoint (no auth required — accessed by the investor
   before they have a PaperWorking account).

   Resolves an invitation token to the safe subset of deal data
   required to render the Guest Portal (LOI terms + property metrics).

   Security model:
     - Token is a 32-char opaque random string — not guessable.
     - Only returns fields explicitly allowlisted below.
     - Expired or used invitations are rejected.
     - No internal IDs (orgId, Firestore docIds) are exposed to the client.
   ═══════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';
export async function GET(
  _request: NextRequest,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;

  // Verify caller is not a Vendor
  const authHeader = _request.headers.get('authorization') ?? _request.headers.get('Authorization');
  let callerUid: string | null = null;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const idToken = authHeader.slice(7);
    try {
      const decoded = await adminDb.collection('users').doc(idToken).get(); // standard decode fallback
      if (decoded.exists) callerUid = decoded.id;
      else {
        const decodedToken = await adminAuth.verifyIdToken(idToken);
        callerUid = decodedToken.uid;
      }
    } catch (e) {
      // If verifyIdToken fails but it starts with mock_token_
      if ((idToken === 'mock_token' || idToken === 'mock_token_123' || idToken === 'mock_session_token_123') && process.env.ENABLE_MOCK_AUTH === 'true') {
        callerUid = _request.cookies.get('mock_user_uid')?.value || null;
      }
    }
  } else if (process.env.ENABLE_MOCK_AUTH === 'true') {
    callerUid = _request.cookies.get('mock_user_uid')?.value || null;
  }

  if (callerUid) {
    const userSnap = await adminDb.collection('users').doc(callerUid).get();
    const userData = userSnap.exists ? userSnap.data() : null;
    if (userData && (userData.role === 'Vendor' || userData.accountType === 'vendor')) {
      return NextResponse.json({ error: 'Not Found' }, { status: 404 });
    }
  }

  if (!token || typeof token !== 'string' || token.length < 16) {
    return NextResponse.json({ error: 'Invalid token format' }, { status: 400 });
  }

  try {
    // 1. Look up the invitation by its opaque token field
    let invSnap = await adminDb
      .collection('invitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    let isDealInvitation = false;
    if (invSnap.empty) {
      invSnap = await adminDb
        .collection('dealInvitations')
        .where('token', '==', token)
        .limit(1)
        .get();
      if (!invSnap.empty) {
        isDealInvitation = true;
      }
    }

    if (invSnap.empty) {
      return NextResponse.json({ error: 'Invitation not found' }, { status: 404 });
    }

    const rawInv = invSnap.docs[0].data();
    const inv = isDealInvitation
      ? {
          id: rawInv.id,
          token: rawInv.token,
          email: rawInv.inviteeEmail,
          name: rawInv.inviteeName || 'Anonymous Investor',
          projectId: rawInv.projectId,
          invitedByUid: rawInv.inviterUid || 'system',
          status: rawInv.status === 'sent' || rawInv.status === 'opened' ? 'pending' : rawInv.status,
          proposedAmount: rawInv.proposedAmount || 0,
          proposedEquityPercent: rawInv.proposedEquityPercent || 0,
          createdAt: rawInv.createdAt,
          expiresAt: rawInv.expiresAt || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          cardExchangeStatus: rawInv.cardExchangeStatus,
          inviteeBusinessCard: rawInv.inviteeBusinessCard,
          leadInvestorBusinessCard: rawInv.leadInvestorBusinessCard,
        }
      : rawInv;

    // 2. Validate lifecycle state.
    //    'accepted'/'declined' invitations are still returned (with their status)
    //    so the Guest Portal can render an "already responded" screen rather
    //    than erroring out — only expiry is a hard rejection.
    const now = new Date();
    const expiresAt: Date = inv.expiresAt?.toDate ? inv.expiresAt.toDate() : new Date(inv.expiresAt);

    if (inv.status === 'expired' || expiresAt < now) {
      // Mark as expired in Firestore lazily
      const ref = invSnap.docs[0].ref;
      if (ref && typeof ref.update === 'function') {
        await ref.update({ status: 'expired' }).catch(() => {});
      }
      return NextResponse.json({ error: 'This invitation has expired.' }, { status: 410 });
    }

    if (inv.status === 'sent' || inv.status === 'pending') {
      const ref = invSnap.docs[0].ref;
      if (ref && typeof ref.update === 'function') {
        await ref.update({ status: 'opened', openedAt: new Date().toISOString() }).catch(() => {});
      }
      const { trackDealActivity } = require('@/lib/invitations/activityTimeline');
      await trackDealActivity(
        inv.projectId,
        inv.projectId,
        inv.invitedByUid || 'system',
        'open',
        { inviteeEmail: inv.email }
      ).catch((e: any) => console.error('Failed to log open event:', e));
    }

    // 3. Fetch the associated project for property metrics
    const projectSnap = await adminDb.collection('projects').doc(inv.projectId).get();

    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Associated deal no longer exists.' }, { status: 404 });
    }

    const project = projectSnap.data()!;
    const fin = project.financials ?? {};

    // 4. Additional computed fields for the Guest Portal's thesis/charts/raise sections.
    //    Raise progress is computed from the real commitments subcollection (status-aware),
    //    never from the legacy fractionalInvestors array.
    const raiseTarget = fin.capitalRaiseTarget || fin.projectedRehabCost || 0;
    const [metricHistory, raiseProgress, commitmentsSnap] = await Promise.all([
      fetchPropertyMetricHistory(inv.projectId),
      computeRaiseProgress(inv.projectId, raiseTarget),
      adminDb
        .collection('projects')
        .doc(inv.projectId)
        .collection('commitments')
        .where('email', '==', inv.email)
        .limit(1)
        .get()
    ]);

    let inquiriesSnap = null;
    try {
      inquiriesSnap = await adminDb
        .collection('projects')
        .doc(inv.projectId)
        .collection('investorInquiries')
        .get();
    } catch (e) {
      console.warn('[GuestPortal] Failed to query investorInquiries:', e);
    }

    const { daysLeft, hoursLeft } = computeRaiseCountdown(project.createdAt);

    let commitmentStatus = 'pending';
    let commitmentId = null;
    if (!commitmentsSnap.empty) {
      commitmentStatus = commitmentsSnap.docs[0].data().status;
      commitmentId = commitmentsSnap.docs[0].id;
    }

    const inquiries = inquiriesSnap ? inquiriesSnap.docs
      .map((doc) => {
        const data = doc.data();
        const isOwn = data.invitationId === invSnap.docs[0].id;
        if (!isOwn && !data.isShared) {
          return null;
        }
        return {
          id: doc.id,
          projectId: data.projectId,
          invitationId: data.invitationId,
          isOwn,
          investorName: isOwn ? data.investorName : 'Anonymous Investor',
          investorEmail: isOwn ? data.investorEmail : null,
          status: data.status,
          isShared: data.isShared || false,
          messages: data.messages || [],
          createdAt: data.createdAt?.toDate ? data.createdAt.toDate().toISOString() : data.createdAt,
          updatedAt: data.updatedAt?.toDate ? data.updatedAt.toDate().toISOString() : data.updatedAt,
        };
      })
      .filter((i): i is NonNullable<typeof i> => i !== null) : [];

    // 5. Return only the allowlisted fields needed by the Guest Portal
    //    — no internal IDs, no organizationId, no Firestore doc references
    return NextResponse.json({
      // Investor identity
      investorName: inv.name,
      investorEmail: inv.email,

      // Property info
      dealName: inv.dealName || project.propertyName || 'Untitled Deal',
      propertyAddress: [
        project.address?.street,
        project.address?.city,
        project.address?.state,
        project.address?.zip,
      ]
        .filter(Boolean)
        .join(', ') || project.propertyAddress || '',
      strategy: project.subStrategy || project.dispositionType || 'Value-Add',
      assetClass: project.assetClass || 'Multi-Family',
      opportunitySummary: project.vision || inv.opportunitySummary || project.description || '',

      // Key metrics
      purchasePrice: fin.purchasePrice ?? 0,
      estimatedARV: fin.estimatedARV ?? fin.estimatedCurrentValue ?? 0,
      expectedROI: fin.expectedROI ?? fin.expectedIRR ?? fin.roi ?? 0,

      // LOI Terms (from invitation record — source of truth)
      investmentAmount: inv.proposedAmount ?? 0,
      equitySplit: inv.proposedEquityPercent ?? 0,
      interestRate: fin.interestRate ?? 0,
      termMonths: fin.termMonths ?? (fin.loanTermYears ? fin.loanTermYears * 12 : 12),
      legalEntity: project.legalEntity || inv.legalEntity || '',

      // Raise progress (from commitments, status-aware)
      raiseTarget,
      raiseRaised: raiseProgress.raiseRaised,
      raisePercentage: raiseProgress.raisePercentage,
      daysLeft,
      hoursLeft,

      // Financial history for charts
      noiHistory: metricHistory.noiHistory,
      capRateHistory: metricHistory.capRateHistory,
      cashFlowHistory: metricHistory.cashFlowHistory,
      burnRateHistory: [] as { date: string; value: number }[],

      // Meta
      expiresAt: expiresAt.toISOString(),
      status: inv.status as 'pending' | 'accepted' | 'declined' | 'expired' | 'interested',
      commitmentStatus,
      commitmentId,
      subscriptionAgreementTemplate: fin.subscriptionAgreementTemplate || null,
      projectId: inv.projectId,
      inquiries,
      cardExchangeStatus: inv.cardExchangeStatus || 'none',
      inviteeBusinessCard: inv.inviteeBusinessCard || null,
      leadInvestorBusinessCard: inv.cardExchangeStatus === 'accepted' ? inv.leadInvestorBusinessCard || null : null,
      indication: inv.indication || null,
    });
  } catch (error) {
    console.error('[GuestPortal] Token lookup failed:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminAuth } from '@/lib/firebase/admin';
import { logger } from '@/lib/logger';

async function blockVendor(request: NextRequest) {
  const authHeader = request.headers.get('authorization') ?? request.headers.get('Authorization');
  let callerUid: string | null = null;
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const idToken = authHeader.slice(7);
    try {
      const decoded = await adminDb.collection('users').doc(idToken).get();
      if (decoded.exists) callerUid = decoded.id;
      else {
        const decodedToken = await adminAuth.verifyIdToken(idToken);
        callerUid = decodedToken.uid;
      }
    } catch (e) {
      if ((idToken === 'mock_token' || idToken === 'mock_token_123' || idToken === 'mock_session_token_123') && process.env.ENABLE_MOCK_AUTH === 'true') {
        callerUid = request.cookies.get('mock_user_uid')?.value || null;
      }
    }
  } else if (process.env.ENABLE_MOCK_AUTH === 'true') {
    callerUid = request.cookies.get('mock_user_uid')?.value || null;
  }

  if (callerUid) {
    const userSnap = await adminDb.collection('users').doc(callerUid).get();
    const userData = userSnap.exists ? userSnap.data() : null;
    if (userData && (userData.role === 'Vendor' || userData.accountType === 'vendor')) {
      return true;
    }
  }
  return false;
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;
  try {
    if (await blockVendor(request)) {
      return NextResponse.json({ error: 'Not Found' }, { status: 404 });
    }
    const body = await request.json();
    const { name, email } = body;

    if (!token) {
      return NextResponse.json({ error: 'Token missing.' }, { status: 400 });
    }

    // 1. Resolve invitation
    const snap = await adminDb
      .collection('invitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    if (snap.empty) {
      return NextResponse.json({ error: 'Invitation not found.' }, { status: 404 });
    }

    const invDoc = snap.docs[0];
    const inv = invDoc.data();
    const projectId = inv.projectId;

    const emailLower = (email || inv.email || '').trim().toLowerCase();

    // 2. Update investor_contacts
    const contactsRef = adminDb.collection('projects').doc(projectId).collection('investor_contacts');
    const contactsSnap = await contactsRef.where('email', '==', emailLower).get();
    for (const doc of contactsSnap.docs) {
      await doc.ref.update({ emailConsent: true, inAppConsent: true });
    }

    // 3. Update followers
    const followersRef = adminDb.collection('projects').doc(projectId).collection('followers');
    const followersSnap = await followersRef.where('email', '==', emailLower).get();
    for (const doc of followersSnap.docs) {
      await doc.ref.update({ emailConsent: true, inAppConsent: true });
    }

    // If they aren't in either, create them as follower or contact so consent is tracked
    if (followersSnap.empty && contactsSnap.empty) {
      const newContactId = `contact_${Date.now()}`;
      await contactsRef.doc(newContactId).set({
        id: newContactId,
        name: name || inv.name || 'Unnamed Investor',
        email: emailLower,
        emailConsent: true,
        inAppConsent: true,
        createdAt: new Date().toISOString(),
        relationship: 'Subscriber',
        type: 'Individual',
        potentialTicket: 0,
      });
    }

    logger.info('[Subscribe] Subscribed & unlocked deal', { email: emailLower, projectId });

    return NextResponse.json({ success: true, message: 'Successfully subscribed. Deal unlocked.' });
  } catch (error) {
    logger.error('[Subscribe] Error:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { syncFractionalInvestorFromCommitment } from '@/lib/firebase/syncFractionalInvestors';
import { CommitmentStatus } from '@/types/schema';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ token: string }> }
) {
  const { token } = await params;

  if (!token || typeof token !== 'string' || token.length < 16) {
    return NextResponse.json({ error: 'Invalid token format' }, { status: 400 });
  }

  try {
    // 1. Resolve invitation by token
    const invSnap = await adminDb
      .collection('invitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    if (invSnap.empty) {
      return NextResponse.json({ error: 'Invitation not found' }, { status: 404 });
    }

    const inv = invSnap.docs[0].data();
    const expiresAt = inv.expiresAt?.toDate ? inv.expiresAt.toDate() : new Date(inv.expiresAt);
    if (expiresAt < new Date()) {
      return NextResponse.json({ error: 'Invitation has expired.' }, { status: 410 });
    }

    // 2. Load the corresponding commitment in the project's commitments subcollection
    const commitmentsCol = adminDb
      .collection('projects')
      .doc(inv.projectId)
      .collection('commitments');

    const commitmentsSnap = await commitmentsCol
      .where('email', '==', inv.email)
      .limit(1)
      .get();

    if (commitmentsSnap.empty) {
      return NextResponse.json({ error: 'No active commitment record found for this investor.' }, { status: 404 });
    }

    const commitmentDoc = commitmentsSnap.docs[0];
    const commitmentData = commitmentDoc.data();

    // 3. Update status to 'signed' and append transition log
    const body = await request.json();
    const { action, evidence } = body;

    const transitionEvidence = evidence || (action === 'esign' ? 'E-Signed via DocuSign in Guest Portal' : 'Manually signed copy uploaded');
    const transition = {
      fromStatus: commitmentData.status || null,
      toStatus: 'signed' as const,
      timestamp: new Date().toISOString(),
      actor: inv.email || 'Guest Investor',
      evidence: transitionEvidence,
    };

    const updates: Record<string, any> = {
      status: 'signed',
      updatedAt: FieldValue.serverTimestamp(),
      transitions: FieldValue.arrayUnion
        ? FieldValue.arrayUnion(transition)
        : [...(commitmentData.transitions || []), transition],
    };

    await commitmentDoc.ref.update(updates);

    // 4. Synchronize legacy fractionalInvestors and new contributions arrays
    await syncFractionalInvestorFromCommitment(inv.projectId, {
      id: commitmentDoc.id,
      name: commitmentData.name,
      email: commitmentData.email,
      amountCents: commitmentData.amountCents,
      status: 'signed',
      partyType: commitmentData.partyType || 'Investor',
    });

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error('[GuestSubscriptionSign]', error);
    return NextResponse.json({ error: 'Internal server error: ' + error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { logger } from '@/lib/logger';
import { CommunicationEngine } from '@/lib/engine/CommunicationEngine';
import {
  checkUserInvitationSuspended,
  checkInvitationRateLimits,
  detectPurchasedListPattern
} from '@/lib/invitations/abuseCheckers';

const INVITE_ROLES = new Set(['Lead Investor', 'Admin', 'Platform Admin']);

function generateToken(): string {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  return Buffer.from(bytes).toString('base64url');
}

export async function POST(request: NextRequest) {
  // 1. Authenticate
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  const callerUid = auth.uid;

  try {
    const body = await request.json();
    const { projectId, subject, bodyTemplate, termsVersion } = body;

    if (!projectId || !subject || !bodyTemplate) {
      return NextResponse.json(
        { success: false, error: 'Missing required fields: projectId, subject, bodyTemplate' },
        { status: 400 }
      );
    }

    // 2. Load the project
    const dealSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!dealSnap.exists) {
      return NextResponse.json({ success: false, error: 'Deal not found' }, { status: 404 });
    }
    const deal = dealSnap.data()!;
    const organizationId = deal.organizationId;
    const dealName = deal.propertyName || 'Untitled Deal';

    if (!organizationId) {
      return NextResponse.json(
        { success: false, error: 'Organization context missing from deal' },
        { status: 422 }
      );
    }

    // 3. Authorize caller
    const members = deal.members ?? {};
    const member = members[callerUid];
    let authorized = false;

    if (member) {
      const hasInviteRole = INVITE_ROLES.has(member.role ?? '');
      const hasInvitePermission = Array.isArray(member.projectPermissions) && member.projectPermissions.includes('team.invite');
      authorized = hasInviteRole || hasInvitePermission;
    } else {
      const callerSnap = await adminDb.collection('users').doc(callerUid).get();
      const callerData = callerSnap.data();
      const callerOrgId = callerData?.organizationId;
      const callerRole = callerData?.role ?? '';

      if (callerOrgId && callerOrgId === organizationId && INVITE_ROLES.has(callerRole)) {
        authorized = true;
      }
    }

    if (!authorized) {
      logger.warn('[Invitations/Broadcast] Unauthorized send attempt', { callerUid, projectId });
      return NextResponse.json(
        { success: false, error: 'Forbidden: insufficient permissions' },
        { status: 403 }
      );
    }

    // 4. Rate sanity guard: one send per Deal per 24 hours
    const last24h = new Date(Date.now() - 24 * 60 * 60 * 1000);
    const historySnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('invitation_history')
      .where('sentAt', '>=', last24h)
      .limit(1)
      .get();

    if (!historySnap.empty) {
      return NextResponse.json(
        { success: false, error: 'Rate limit: An invitation has already been sent for this deal in the last 24 hours.' },
        { status: 429 }
      );
    }

    // 5. Load Audience & Deduplicate
    const contactsSnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('investor_contacts')
      .get();

    const followersSnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('followers')
      .get();

    interface DeduplicatedRecipient {
      email: string;
      name: string;
      potentialTicket: number; // in cents
      emailConsent: boolean;
      inAppConsent: boolean;
    }

    const deduplicated: Record<string, DeduplicatedRecipient> = {};

    for (const doc of contactsSnap.docs) {
      const c = doc.data();
      const email = (c.email || '').trim().toLowerCase();
      if (!email || !email.includes('@')) continue;
      deduplicated[email] = {
        email: c.email.trim(),
        name: c.name || 'Unnamed Investor',
        potentialTicket: c.potentialTicket || 0,
        emailConsent: c.emailConsent !== false,
        inAppConsent: c.inAppConsent !== false,
      };
    }

    for (const doc of followersSnap.docs) {
      const f = doc.data();
      const email = (f.email || '').trim().toLowerCase();
      if (!email || !email.includes('@')) continue;
      if (deduplicated[email]) {
        deduplicated[email].emailConsent = deduplicated[email].emailConsent && (f.emailConsent !== false);
        deduplicated[email].inAppConsent = deduplicated[email].inAppConsent || (f.inAppConsent !== false);
      } else {
        deduplicated[email] = {
          email: f.email.trim(),
          name: f.name || 'Unnamed Investor',
          potentialTicket: 0,
          emailConsent: f.emailConsent !== false,
          inAppConsent: f.inAppConsent !== false,
        };
      }
    }

    const recipients = Object.values(deduplicated);
    const activeRecipients = recipients.filter(r => r.emailConsent || r.inAppConsent);

    if (activeRecipients.length === 0) {
      return NextResponse.json(
        { success: false, error: 'No consented recipients found in the audience.' },
        { status: 400 }
      );
    }

    // Enforce rate limits and suspension check
    try {
      await checkUserInvitationSuspended(callerUid);
      await checkInvitationRateLimits(callerUid, projectId, activeRecipients.length);
    } catch (err: any) {
      return NextResponse.json({ success: false, error: err.message }, { status: 400 });
    }

    // Purchased list check
    try {
      const emails = activeRecipients.map(r => r.email);
      const purchasedCheck = await detectPurchasedListPattern(callerUid, projectId, emails);
      if (purchasedCheck.isSuspicious && purchasedCheck.strangersCount > 15 && deal.visibilityMode === 'PRIVATE') {
        return NextResponse.json({
          success: false,
          error: 'Your invitation batch was flagged as non-relational. To protect platform integrity, mass invites to unverified contacts are restricted.'
        }, { status: 400 });
      }
    } catch (err: any) {
      // non-blocking
    }

    // Resolve inviter branding
    const callerProfileSnap = await adminDb.collection('users').doc(callerUid).get();
    const callerProfile = callerProfileSnap.data();
    const invitedByName = callerProfile?.displayName || callerProfile?.companyName || 'Lead Investor';

    const APP_URL = process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co';
    const fin = deal.financials ?? {};
    const fundingTarget = fin.equityTerms?.funding_target ?? 0;
    const equityOfferedPct = fin.equityTerms?.equity_offered_pct ?? 0;
    const minTicket = fin.equityTerms?.min_ticket ?? 0;

    const recipientsLogged: any[] = [];
    let emailSentCount = 0;
    let inAppSentCount = 0;

    // 6. Iterate and Process each recipient
    for (const r of activeRecipients) {
      const token = generateToken();
      const invitationId = `inv_${Date.now()}_${crypto.randomUUID().replace(/-/g, '').slice(0, 9)}`;

      // Calculate personal proposed investment terms
      const proposedAmount = r.potentialTicket > 0 ? r.potentialTicket / 100 : minTicket;
      const proposedEquityPercent = fundingTarget > 0 ? (proposedAmount / fundingTarget) * equityOfferedPct : 0;

      const invitation = {
        id: invitationId,
        projectId,
        dealName,
        organizationId,
        email: r.email,
        name: r.name,
        proposedEquityPercent,
        proposedAmount,
        invitedByUid: callerUid,
        invitedByName,
        token,
        status: 'pending',
        createdAt: new Date(),
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days
        termsVersion: termsVersion || 1,
      };

      // Set invitation document
      await adminDb.collection('invitations').doc(invitationId).set(invitation);

      const channelsSent: string[] = [];

      // A. Process In-App Invitation
      if (r.inAppConsent) {
        // Resolve UID by email
        const userQuery = await adminDb.collection('users').where('email', '==', r.email).limit(1).get();
        if (!userQuery.empty) {
          const userDoc = userQuery.docs[0];
          const notificationId = `not_${Date.now()}_${crypto.randomUUID().replace(/-/g, '').slice(0, 9)}`;

          await adminDb.collection('notifications').doc(notificationId).set({
            id: notificationId,
            recipientId: userDoc.id,
            type: 'INVEST_INVITE',
            title: `Investment Invitation — ${dealName}`,
            body: `${invitedByName} has invited you to co-invest in the project at ${deal.propertyAddress || dealName}.`,
            actor: {
              uid: callerUid,
              name: invitedByName,
            },
            objectReference: {
              projectId,
              dealAddress: deal.propertyAddress || dealName,
              amount: `$${proposedAmount.toLocaleString()}`,
              token,
            },
            urgencyLevel: 'normal',
            channels: ['in-app'],
            read: false,
            archived: false,
            createdAt: new Date(),
            deepLinkUrl: `/invest/${token}`,
            expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
          });

          channelsSent.push('in-app');
          inAppSentCount++;
        }
      }

      // B. Process External Email Invitation
      if (r.emailConsent) {
        // Format Prose and inject variables
        let formattedBody = bodyTemplate
          .replaceAll('{{PROPERTY_ADDRESS}}', deal.propertyAddress || dealName)
          .replaceAll('{{TARGET_PRICE}}', fin.finalAgreedPrice ? `$${(fin.finalAgreedPrice / 100).toLocaleString()}` : fin.purchasePrice ? `$${(fin.purchasePrice / 100).toLocaleString()}` : '$0')
          .replaceAll('{{PROJECTED_NOI}}', fin.projectedNOI ? `$${(fin.projectedNOI / 100).toLocaleString()}` : '$0')
          .replaceAll('{{PROJECTED_CAP_RATE}}', fin.projectedCapRate ? `${fin.projectedCapRate}%` : '0%')
          .replaceAll('{{PROJECTED_COC}}', fin.projectedCashOnCash ? `${fin.projectedCashOnCash}%` : '0%')
          .replaceAll('{{STRATEGY}}', deal.subStrategy || deal.dispositionType || 'Value-Add')
          .replaceAll('{{HOLD_HORIZON}}', fin.holdPeriodYears ? `${fin.holdPeriodYears} Years` : '5 Years')
          .replaceAll('{{FUNDING_TARGET}}', `$${fundingTarget.toLocaleString()}`)
          .replaceAll('{{EQUITY_PERCENT}}', `${equityOfferedPct}%`)
          .replaceAll('{{MIN_TICKET}}', `$${minTicket.toLocaleString()}`);

        // Append non-binding disclosure & unsubscribe link
        const emailHtml = `
          <div style="font-family:sans-serif;line-height:1.6;color:#e8e6ea;background-color:#0d0a0b;padding:24px;border-radius:16px;">
            <div style="margin-bottom:20px;">
              <h2 style="font-weight:bold;color:#ffffff;margin-top:0;">${subject}</h2>
            </div>
            <div style="white-space:pre-wrap;font-size:14px;color:#9e9da0;">${formattedBody}</div>

            <div style="margin-top:30px;padding-top:12px;border-top:1px solid rgba(255,255,255,0.1);text-align:center;">
              <a href="${APP_URL}/invest/${token}" style="display:inline-block;padding:12px 24px;background-color:#454955;color:#0d0a0b;font-weight:bold;text-decoration:none;border-radius:8px;font-size:14px;">Review Deal & Respond</a>
            </div>

            <div style="margin-top:40px;padding-top:16px;border-top:1px solid rgba(255,255,255,0.05);font-size:11px;color:#6b6a6d;line-height:1.4;">
              <p>Disclosure: This invitation and any associated materials are for informational purposes only and do not constitute an offer to sell or a solicitation of an offer to buy any securities. Any investment commitment made hereunder is non-binding.</p>
              <p>If you no longer wish to receive invitations for this project, you can <a href="${APP_URL}/unsubscribe?email=${encodeURIComponent(r.email)}&projectId=${projectId}" style="color:#454955;text-decoration:underline;">unsubscribe here</a>.</p>
            </div>
          </div>
        `;

        await CommunicationEngine.sendRawEmail([r.email], subject, emailHtml);
        channelsSent.push('email');
        emailSentCount++;
      }

      recipientsLogged.push({
        email: r.email,
        name: r.name,
        channels: channelsSent,
        status: 'not tracked', // defaults to not tracked since webhook isn't configured in test
      });
    }

    // 7. Write history log document
    const historyDocId = `hist_${Date.now()}`;
    await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('invitation_history')
      .doc(historyDocId)
      .set({
        id: historyDocId,
        sentAt: new Date(),
        subject,
        bodyTemplate,
        termsVersion: termsVersion || 1,
        recipients: recipientsLogged,
      });

    return NextResponse.json({
      success: true,
      emailSentCount,
      inAppSentCount,
      totalCount: activeRecipients.length,
    });
  } catch (error) {
    logger.error('[Invitations/Broadcast] General Error:', error);
    return NextResponse.json(
      { success: false, error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { FieldValue } from 'firebase-admin/firestore';
import { adminDb } from '@/lib/firebase/admin';
import { getEmailProvider } from '@/lib/email/getEmailProvider';
import { generateInvestorResponseEmail } from '@/lib/emails/templates/InvestorResponseEmail';
import { logOrgActivity } from '@/lib/firebase/orgActivityWriter';
import { syncFractionalInvestorFromCommitment, removeFractionalInvestorForCommitment } from '@/lib/firebase/syncFractionalInvestors';
import { checkRateLimit, rateLimitResponse } from '@/lib/places/placesRateLimit';

/* ═══════════════════════════════════════════════════════════════
   POST /api/invitations/respond

   Unauthenticated (investor-facing) — token is the credential.

   Body: {
     token:            string             // URL-safe token from invite link
     action:           'accept'|'decline'|'interested'|'reopen'
     signatureDataUrl?: string            // required for accept
     disclosedCard?:   object             // optional for interested
   }

   Flow:
     1. Resolve invitation by token
     2. Validate: not expired, status in [pending, active]
     3. Write status update via Admin SDK (atomic, bypasses client rules)
     4. Notify deal owner + invitedBy via SendGrid
     5. Append audit log entry
   ═══════════════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';

const APP_URL = process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co';

interface RespondBody {
  token: string;
  action: 'accept' | 'decline' | 'interested' | 'reopen';
  signatureDataUrl?: string;
  declineReason?: string;
  disclosedCard?: {
    name: string;
    email: string;
    phone: string;
    company: string;
  };
}

export async function POST(request: NextRequest) {
  try {
    const body: RespondBody = await request.json();
    const { token, action, signatureDataUrl } = body;

    // ── Input validation ────────────────────────────────────
    if (!token || typeof token !== 'string' || token.length < 16) {
      return NextResponse.json({ error: 'Invalid or missing invitation token.' }, { status: 400 });
    }
    if (action !== 'accept' && action !== 'decline' && action !== 'interested' && action !== 'reopen') {
      return NextResponse.json({ error: 'action must be "accept", "decline", "interested", or "reopen".' }, { status: 400 });
    }
    if (action === 'accept' && !signatureDataUrl) {
      return NextResponse.json({ error: 'signatureDataUrl is required when accepting.' }, { status: 400 });
    }

    // ── Rate Limiting ────────────────────────────────────────
    const rateCheck = await checkRateLimit(token, 'cardExchange');
    if (!rateCheck.allowed) {
      return rateLimitResponse(rateCheck);
    }

    // ── Resolve invitation from both collections ──────────────
    let isDealInvitation = false;
    let snap = await adminDb
      .collection('invitations')
      .where('token', '==', token)
      .limit(1)
      .get();

    if (snap.empty) {
      snap = await adminDb
        .collection('dealInvitations')
        .where('token', '==', token)
        .limit(1)
        .get();
      if (!snap.empty) {
        isDealInvitation = true;
      }
    }

    if (snap.empty) {
      return NextResponse.json({ error: 'Invitation not found.' }, { status: 404 });
    }

    const invRef = snap.docs[0].ref;
    const rawInv = snap.docs[0].data();
    const inv = isDealInvitation
      ? {
          id: rawInv.id,
          token: rawInv.token,
          email: rawInv.inviteeEmail,
          name: rawInv.inviteeName || 'Anonymous Investor',
          projectId: rawInv.projectId,
          invitedByUid: rawInv.inviterUid || 'system',
          status: rawInv.status,
          proposedAmount: rawInv.proposedAmount || 0,
          proposedEquityPercent: rawInv.proposedEquityPercent || 0,
          createdAt: rawInv.createdAt,
          expiresAt: rawInv.expiresAt || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
          version: rawInv.version || 1,
          visibilityMode: rawInv.visibilityMode || 'PRIVATE',
          listingId: rawInv.listingId || '',
        }
      : rawInv;

    // ── Guard: expiry ───────────────────────────────────────
    const expiresAt: Date = inv.expiresAt?.toDate
      ? inv.expiresAt.toDate()
      : new Date(inv.expiresAt);

    if (expiresAt < new Date()) {
      return NextResponse.json({ error: 'This invitation link has expired.' }, { status: 410 });
    }

    // ── Guard: Reversibility / Lock status ───────────────────
    const emailLower = inv.email.toLowerCase();
    const commitmentsSnap = await adminDb
      .collection('projects')
      .doc(inv.projectId)
      .collection('commitments')
      .where('email', '==', emailLower)
      .get();

    let isLocked = false;
    for (const doc of commitmentsSnap.docs) {
      const cStatus = doc.data().status;
      if (['signed', 'funds-confirmed', 'cleared'].includes(cStatus)) {
        isLocked = true;
        break;
      }
    }

    if (isLocked) {
      return NextResponse.json({ error: 'Cannot change response: The Lead Investor has already acted on this commitment.' }, { status: 403 });
    }

    // ── Tear down unconfirmed pledged commitments on decline/reopen ──
    if (action === 'decline' || action === 'reopen') {
      for (const doc of commitmentsSnap.docs) {
        if (doc.data().status === 'pledged') {
          await doc.ref.delete();
          await removeFractionalInvestorForCommitment(inv.projectId, doc.id);
        }
      }
    }

    // ── Write to Firestore (Admin SDK) ──────────────────────
    const now = FieldValue.serverTimestamp();
    let update: Record<string, unknown> = {};

    if (action === 'accept') {
      update = { status: 'accepted', acceptedAt: now, signatureDataUrl };
    } else if (action === 'decline') {
      update = { status: 'declined', declinedAt: now, declineReason: body.declineReason || null };
    } else if (action === 'interested') {
      const disclosedCard = body.disclosedCard || {
        name: inv.name || 'Anonymous Investor',
        email: inv.email || '',
        phone: '',
        company: '',
      };
      update = {
        status: 'interested',
        interestedAt: now,
        inviteeBusinessCard: disclosedCard,
        cardExchangeStatus: 'pending',
      };
    } else if (action === 'reopen') {
      update = { status: 'opened', reopenedAt: now };
    }

    await invRef.update(update);

    // ── Create commitment on acceptance ─────────────────────
    if (action === 'accept') {
      const commitmentRef = adminDb
        .collection('projects')
        .doc(inv.projectId)
        .collection('commitments')
        .doc();

      const amountCents = Math.round((inv.proposedAmount || 0) * 100);
      const commitmentName = inv.name || 'Anonymous Investor';

      await commitmentRef.set({
        projectId: inv.projectId,
        name: commitmentName,
        amountCents,
        status: 'pledged',
        email: inv.email || null,
        notes: 'Crowdfund invitation accepted via Inbox',
        createdByUid: inv.invitedByUid || 'system',
        createdAt: now,
        updatedAt: now,
      });

      // Keep fractional investors view in sync
      await syncFractionalInvestorFromCommitment(inv.projectId, {
        id: commitmentRef.id,
        name: commitmentName,
        email: inv.email || null,
        amountCents,
        status: 'pledged',
      });
    }

    // ── Notify deal owner ───────────────────────────────────
    const [projectSnap, ownerSnap] = await Promise.all([
      adminDb.collection('projects').doc(inv.projectId).get(),
      inv.invitedByUid !== 'system'
        ? adminDb.collection('users').doc(inv.invitedByUid).get()
        : Promise.resolve(null),
    ]);

    const dealName = projectSnap.data()?.propertyName ?? inv.dealName ?? 'Untitled Deal';
    const ownerEmail: string | null = ownerSnap?.data()?.email ?? null;

    if (ownerEmail && action !== 'reopen') {
      const { subject, html, text } = generateInvestorResponseEmail({
        action: action === 'accept' ? 'accepted' : (action === 'interested' ? 'interested' : 'declined'),
        investorName: inv.name,
        investorEmail: inv.email,
        projectName: dealName,
        projectId: inv.projectId,
        proposedEquityPercent: inv.proposedEquityPercent ?? 0,
        proposedAmount: inv.proposedAmount ?? 0,
        appUrl: APP_URL,
      });

      const emailProvider = getEmailProvider();
      await emailProvider.sendEmail({
        from: 'notifications@mail.paperworking.co',
        replyTo: inv.email || 'hi@paperworking.co',
        to: [ownerEmail],
        subject,
        templateKey: action === 'accept' ? 'DEAL-MKT-DEAL-UPDATE' : 'DEAL-MKT-RESPONSE',
        messageClass: 'O',
        html,
        text,
      });
    }

    // ── Write to dealLedger timeline ────────────────────────
    const ledgerRef = adminDb.collection('projects').doc(inv.projectId)
      .collection('dealLedger').doc();
    await ledgerRef.set({
      id: ledgerRef.id,
      projectId: inv.projectId,
      listingId: inv.listingId || '',
      eventType: 'INVITATION_RESPONSE',
      performedBy: inv.invitedByUid || 'system',
      inviteeEmail: emailLower,
      version: inv.version || 1,
      visibilityMode: inv.visibilityMode || 'PRIVATE',
      timestamp: new Date().toISOString(),
      metadata: {
        invitationId: invRef.id,
        status: action === 'reopen' ? 'opened' : (action === 'accept' ? 'accepted' : action),
        declineReason: body.declineReason || null,
      },
    });

    const { trackDealActivity } = require('@/lib/invitations/activityTimeline');
    let timelineType: any = null;
    let timelineMeta: any = { inviteeEmail: emailLower };
    if (action === 'accept') {
      timelineType = 'interest';
      timelineMeta.status = 'accepted';
    } else if (action === 'decline') {
      timelineType = 'decline';
      timelineMeta.declineReason = body.declineReason || null;
    } else if (action === 'interested') {
      timelineType = 'interest';
      timelineMeta.cardExchangeStatus = 'pending';
    }
    if (timelineType) {
      await trackDealActivity(
        inv.projectId,
        inv.projectId,
        inv.invitedByUid || 'system',
        timelineType,
        timelineMeta
      ).catch((e: any) => console.error('Failed to log respond timeline event:', e));
    }

    // ── Telemetry Taxonomy tracking ─────────────────────────
    try {
      const { trackEvent } = require('@/actions/telemetry');
      if (action === 'accept' || action === 'decline') {
        await trackEvent('deal_terms_responded', {
          listingId: inv.listingId || '',
          projectId: inv.projectId,
          isCounter: false,
          amountCents: inv.investmentAmount ? Math.round(inv.investmentAmount * 100) : 0,
        }, token);
      } else if (action === 'interested') {
        await trackEvent('contact_details_exchanged', {
          listingId: inv.listingId || null,
          projectId: inv.projectId,
          recipientUid: inv.invitedByUid || null,
        }, token);
      }
    } catch (e) {
      console.error('Failed to log respond taxonomy event:', e);
    }

    // ── Audit log ───────────────────────────────────────────
    await adminDb.collection('auditLog').add({
      type: `invitation_${action}ed`,
      invitationId: invRef.id,
      projectId: inv.projectId,
      organizationId: inv.organizationId || null,
      investorEmail: inv.email,
      investorName: inv.name,
      at: now,
    });

    // ── Org activity feed (non-blocking) ────────────────────
    if (action === 'accept' && inv.organizationId) {
      logOrgActivity({
        organizationId: inv.organizationId,
        type: 'member_joined',
        actorId: inv.invitedByUid || 'system',
        actorName: inv.name || 'An investor',
        summary: `${inv.name || 'An investor'} accepted the investment invitation for ${dealName}`,
        projectId: inv.projectId,
        projectName: dealName,
      });
    }

    return NextResponse.json({ success: true, action, invitationId: invRef.id });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    console.error('[Invitations/Respond] Error:', msg);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';

export const dynamic = "force-dynamic";

const MAX_RESULTS = 50;

export async function GET(request: Request) {
  // ── Auth Guard ───────────────────────────────────────
  const authHeader = request.headers.get('Authorization');
  if (!authHeader?.startsWith('Bearer ')) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const idToken = authHeader.split('Bearer ')[1];
  let uid = '';
  try {
    const { adminAuth } = await import('@/lib/firebase/admin');
    const decoded = await adminAuth.verifyIdToken(idToken);
    uid = decoded.uid;
  } catch (err) {
    console.error('[lawyers API] Auth token verification failed:', err);
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const stateCode = searchParams.get('state');

  if (!stateCode) {
    return NextResponse.json({ error: 'State code is required' }, { status: 400 });
  }

  const normalizedState = stateCode.trim().toUpperCase();
  if (!/^[A-Z]{2}$/.test(normalizedState)) {
    return NextResponse.json({ error: 'Invalid state code. Must be a 2-letter US state abbreviation.' }, { status: 400 });
  }

  try {
    const { adminDb } = await import('@/lib/firebase/admin');

    // Query Vendor Marketplace subscribers with a lawyer vendorType in the requested state
    const vendorSnapshot = await adminDb
      .collection('users')
      .where('subscriptionPlan', '==', 'Vendor Network')
      .where('subscriptionStatus', '==', 'active')
      .where('vendorType', '==', 'lawyer')
      .where('stateCode', '==', normalizedState)
      .limit(MAX_RESULTS)
      .get();

    // Legacy fallback: users who subscribed under the old "Lawyer Lead-Gen" plan in the requested state
    const remainingSlots = MAX_RESULTS - vendorSnapshot.size;
    let legacyDocs: FirebaseFirestore.QueryDocumentSnapshot[] = [];

    if (remainingSlots > 0) {
      const legacySnapshot = await adminDb
        .collection('users')
        .where('subscriptionPlan', '==', 'Lawyer Lead-Gen')
        .where('subscriptionStatus', '==', 'active')
        .where('stateCode', '==', normalizedState)
        .limit(remainingSlots)
        .get();
      legacyDocs = legacySnapshot.docs;
    }

    // Deduplicate across both queries (shouldn't overlap, but safety first)
    const seen = new Set<string>();
    const lawyers = [
      ...vendorSnapshot.docs,
      ...legacyDocs,
    ]
      .filter((doc) => {
        if (seen.has(doc.id)) return false;
        seen.add(doc.id);
        return true;
      })
      .map((doc) => ({ uid: doc.id, ...doc.data() }));

    // Always return success with an array — empty array for no matches
    return NextResponse.json({ success: true, lawyers, count: lawyers.length });
  } catch (error) {
    console.error('Lawyer query failed:', error);
    return NextResponse.json({ error: 'Failed to query lawyers' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb, adminAuth } from '@/lib/firebase/admin';
import { generateLOIPDF } from '@/lib/reports/loiGenerator';

export const dynamic = 'force-dynamic';

export async function POST(req: NextRequest) {
  try {
    // 1. Auth check
    const auth = await requireAuth(req);
    if (isAuthError(auth)) return auth;

    const { uid, token } = auth;

    // 2. Body inputs parsing
    const body = await req.json().catch(() => ({}));
    const { projectId, offerAmount = 250000, earnestMoney = 2500, closingDate, contingencies = [], buyerEntity = '' } = body;

    if (!projectId) {
      return NextResponse.json({ success: false, error: 'projectId is required' }, { status: 400 });
    }

    // 3. Fetch project to ensure ownership/access
    const projectRef = adminDb.collection('projects').doc(projectId);
    const projectSnap = await projectRef.get();
    if (!projectSnap.exists) {
      return NextResponse.json({ success: false, error: 'Project not found' }, { status: 404 });
    }

    const project = projectSnap.data()!;
    const userSnap = await adminDb.collection('users').doc(uid).get();
    const userData = userSnap.exists ? userSnap.data() || {} : {};
    const buyerName = userData.displayName || userData.name || token.email || 'Investor';
    const buyerEmail = token.email || userData.email || 'investor@paperworking.com';

    // 4. Generate LOI PDF buffer
    const pdfBuffer = await generateLOIPDF({
      buyerName,
      buyerEmail,
      buyerEntity,
      propertyName: project.propertyName || project.addressLine || 'Unnamed Property',
      offerAmount,
      earnestMoney,
      closingDate,
      contingencies,
    });

    const nowStr = new Date().toISOString();
    const docId = `loi_${Math.random().toString(36).substring(2, 11)}`;

    // 5. Store LOI Document in the project documents sub-collection
    const docRef = projectRef.collection('documents').doc(docId);
    await docRef.set({
      id: docId,
      projectId,
      category: 'Purchase Agreement', // categorizes correctly under due diligence
      fileName: 'Letter_of_Intent.pdf',
      fileUrl: `/api/loi/download?id=${docId}`, // download URL endpoint
      uploadedByUid: uid,
      uploadedByName: buyerName,
      uploadedAt: nowStr,
      eSignStatus: 'Not Required',
      notes: 'Generated Letter of Intent (LOI)',
    });

    // 6. Return response attachment stream
    return new NextResponse(new Uint8Array(pdfBuffer), {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="loi_${projectId}.pdf"`,
      },
    });

  } catch (err: any) {
    console.error('[LOI Generation API] Error:', err);
    return NextResponse.json({ success: false, error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';

export async function GET(req: NextRequest) {
  try {
    let isAuthenticated = false;

    // Check if auth token or cookie is present
    const authHeader = req.headers.get('authorization') || req.headers.get('Authorization');
    const sessionCookie = req.cookies.get('__session')?.value;

    if (authHeader || sessionCookie) {
      try {
        const auth = await requireAuth(req);
        if (!isAuthError(auth)) {
          isAuthenticated = true;
        }
      } catch (err) {
        isAuthenticated = false;
      }
    }

    // Fetch listings from Firestore
    const snap = await adminDb.collection('dealListings').get();
    let listings = snap.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    })) as any[];

    // Filter by visibility mode
    if (!isAuthenticated) {
      listings = listings.filter((l) => l.visibility === 'PUBLIC' || l.visibilityMode === 'PUBLIC');
    }

    // Sort listings: New listings first, then by createdAt descending
    listings.sort((a, b) => {
      if (a.isNewListing && !b.isNewListing) return -1;
      if (!a.isNewListing && b.isNewListing) return 1;

      const timeA = new Date(a.createdAt || 0).getTime();
      const timeB = new Date(b.createdAt || 0).getTime();
      return timeB - timeA;
    });

    return NextResponse.json({
      success: true,
      isAuthenticated,
      count: listings.length,
      listings,
    });
  } catch (err: any) {
    console.error('[MarketplaceListings GET]', err);
    return NextResponse.json(
      { error: 'Failed to fetch marketplace listings', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';

/**
 * Catch-all MCP Route Handler
 *
 * Gated by MCP_API_KEY bearer token — every caller (agent, script, etc.)
 * must supply `Authorization: Bearer <MCP_API_KEY>` to reach any tool.
 *
 * Tools exposed: list_active_projects, get_deal_metrics, query_ledger,
 *                verify_subscription
 *
 * Uses lazy initialization to avoid build-time crashes.
 */

let _handler: ((req: NextRequest) => Promise<Response>) | null = null;

async function getHandler() {
  if (!_handler) {
    // Use `mcp-handler` — the maintained successor to `@vercel/mcp-adapter`.
    // The old 0.3.x adapter ships no `exports` map and Turbopack cannot resolve
    // it under the production build, which broke Firebase App Hosting CI.
    const { createMcpHandler } = await import("mcp-handler");
    const { McpServer } = await import("@modelcontextprotocol/sdk/server/mcp.js");
    const {
      list_active_projects,
      get_deal_metrics,
      query_ledger,
    } = await import("@/lib/mcp/firestore-tools");
    const { verify_subscription } = await import("@/lib/mcp/stripe-tools");

    const tools = [list_active_projects, get_deal_metrics, query_ledger, verify_subscription];

    _handler = createMcpHandler((server: InstanceType<typeof McpServer>) => {
      for (const tool of tools) {
        server.tool(tool.name, tool.description, tool.schema.shape, tool.handler as any);
      }
    });
  }
  return _handler;
}

function checkAuth(req: NextRequest): NextResponse | null {
  const mcpApiKey = process.env.MCP_API_KEY;
  if (!mcpApiKey) {
    // Key not configured — block all access rather than allow by default.
    return NextResponse.json({ error: 'MCP endpoint not configured' }, { status: 503 });
  }

  const authHeader = req.headers.get('Authorization') ?? '';
  if (authHeader !== `Bearer ${mcpApiKey}`) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  return null; // auth passed
}

export async function GET(req: NextRequest) {
  const deny = checkAuth(req);
  if (deny) return deny;
  const handler = await getHandler();
  return handler(req);
}

export async function POST(req: NextRequest) {
  const deny = checkAuth(req);
  if (deny) return deny;
  const handler = await getHandler();
  return handler(req);
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { adminDb } from '@/lib/firebase/admin';

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await params;
    let readState = true;

    try {
      const body = await req.json();
      if (body && typeof body.read === 'boolean') {
        readState = body.read;
      }
    } catch {
      // default to read = true if no body provided
    }

    if (!id) {
      return NextResponse.json({ error: 'Message ID is required' }, { status: 400 });
    }

    // 1. Update Prisma
    const updated = await prisma.message.update({
      where: { id },
      data: { read: readState },
    });

    // 2. Update Firestore
    try {
      await adminDb.collection('messages').doc(id).set({ read: readState }, { merge: true });
      await adminDb.collection('inboxItems').doc(`inb_${id}`).set({ read: readState }, { merge: true });
    } catch (e) {
      console.warn(`[Messages PATCH read] Firestore update skipped for ${id}:`, e);
    }

    return NextResponse.json({
      success: true,
      message: updated,
    });
  } catch (err: any) {
    console.error('[Messages PATCH read Error]', err);
    return NextResponse.json(
      { error: 'Failed to update message read status', message: err.message },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { adminDb } from '@/lib/firebase/admin';

export async function GET(req: NextRequest) {
  try {
    const { searchParams } = new URL(req.url);
    const userId = searchParams.get('userId') || searchParams.get('user') || searchParams.get('handle');
    const threadId = searchParams.get('threadId');

    // 1. Thread filter
    if (threadId) {
      const dbMessages = await prisma.message.findMany({
        where: { threadId },
        include: {
          sender: { select: { id: true, name: true, email: true, agentPersona: true } },
          recipient: { select: { id: true, name: true, email: true, agentPersona: true } },
        },
        orderBy: { createdAt: 'asc' },
      });

      return NextResponse.json({
        success: true,
        threadId,
        messages: dbMessages,
      });
    }

    // 2. Inbox for userId (where recipientId = userId)
    let whereCondition: any = {};
    if (userId) {
      whereCondition = { recipientId: userId };
    }

    const messages = await prisma.message.findMany({
      where: whereCondition,
      include: {
        sender: { select: { id: true, name: true, email: true, agentPersona: true } },
        recipient: { select: { id: true, name: true, email: true, agentPersona: true } },
      },
      orderBy: { createdAt: 'desc' },
    });

    const unreadCount = messages.filter((m) => !m.read).length;

    // Group into threads
    const threadsMap = new Map<string, any[]>();
    for (const msg of messages) {
      const tid = msg.threadId;
      if (!threadsMap.has(tid)) {
        threadsMap.set(tid, []);
      }
      threadsMap.get(tid)!.push(msg);
    }

    const threads = Array.from(threadsMap.entries()).map(([tid, msgs]) => {
      const latestMsg = msgs[0];
      const threadUnreadCount = msgs.filter((m) => !m.read).length;

      return {
        threadId: tid,
        subject: latestMsg.subject,
        latestMessage: latestMsg,
        unreadCount: threadUnreadCount,
        messages: msgs,
      };
    });

    return NextResponse.json({
      success: true,
      count: messages.length,
      unreadCount,
      threads,
      messages,
    });
  } catch (err: any) {
    console.error('[Messages GET Error]', err);
    return NextResponse.json(
      { error: 'Failed to fetch messages', message: err.message },
      { status: 500 }
    );
  }
}

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { threadId, senderId, recipientId, subject, body: contentBody, content, attachmentProjectId, projectId } = body;

    const effectiveBody = contentBody || content;
    if (!senderId || !recipientId || !effectiveBody) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    const msgId = `msg_${Date.now()}_${Math.random().toString(36).substring(2, 8)}`;
    const effectiveThreadId = threadId || `thread_${Date.now()}`;
    const effectiveAttachmentId = attachmentProjectId || projectId || null;
    const now = new Date();

    // 1. Write to Prisma
    const createdMessage = await prisma.message.create({
      data: {
        id: msgId,
        threadId: effectiveThreadId,
        senderId,
        recipientId,
        subject: subject || 'Re: Message',
        body: effectiveBody,
        attachmentProjectId: effectiveAttachmentId,
        read: false,
        syntheticAgent: true,
        createdAt: now,
      },
      include: {
        sender: { select: { id: true, name: true, email: true, agentPersona: true } },
        recipient: { select: { id: true, name: true, email: true, agentPersona: true } },
      },
    });

    // 2. Write to Firestore
    await adminDb.collection('messages').doc(msgId).set({
      id: msgId,
      threadId: effectiveThreadId,
      senderId,
      recipientId,
      subject: subject || 'Re: Message',
      body: effectiveBody,
      content: effectiveBody,
      attachmentProjectId: effectiveAttachmentId,
      projectId: effectiveAttachmentId,
      read: false,
      syntheticAgent: true,
      createdAt: now.toISOString(),
    });

    const inboxId = `inb_${msgId}`;
    await adminDb.collection('inboxItems').doc(inboxId).set({
      id: inboxId,
      recipientUid: recipientId,
      senderUid: senderId,
      organizationId: 'org_paperworking_seed',
      type: 'message',
      category: 'message',
      title: subject || 'Re: Message',
      body: effectiveBody,
      attachmentProjectId: effectiveAttachmentId,
      projectId: effectiveAttachmentId,
      threadId: effectiveThreadId,
      read: false,
      syntheticAgent: true,
      createdAt: now.toISOString(),
    });

    return NextResponse.json({
      success: true,
      message: createdMessage,
    });
  } catch (err: any) {
    console.error('[Messages POST Error]', err);
    return NextResponse.json(
      { error: 'Failed to create message', message: err.message },
      { status: 500 }
    );
  }
}

