import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';

export const dynamic = 'force-dynamic';

/** Mirrors the shape expected by PropertyDiscovery.tsx */
interface PropertyResult {
  id: string;
  address: string;
  city: string;
  state: string;
  zip: string;
  beds: number;
  baths: number;
  sqft: number;
  askingPrice: number;
  yearBuilt: number;
  imageUrl?: string;
}

/**
 * Escapes a string value for safe embedding in an OData $filter expression.
 * Single quotes are doubled; the string is percent-encoded per RESO convention.
 */
function oDataString(value: string): string {
  const escaped = value.replace(/'/g, "''");
  return `'${encodeURIComponent(escaped).replace(/'/g, '%27')}'`;
}

/**
 * GET /api/mls/search?q=<query>
 *
 * Proxies a typeahead search to the Bridge Interactive RESO API.
 * Searches UnparsedAddress, City, and PostalCode with OR logic.
 * Returns up to 8 simplified PropertyResult objects.
 */
export async function GET(request: NextRequest) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  const q = request.nextUrl.searchParams.get('q')?.trim() ?? '';

  if (q.length < 2) {
    return NextResponse.json([]);
  }

  try {
    const { bridgeWorkerService } = await import('@/lib/services/bridgeWorkerService');
    if (await bridgeWorkerService.isPaused()) {
      return NextResponse.json(
        { error: 'MLS service is temporarily unavailable.' },
        { status: 503 }
      );
    }

    const apiClient = (await import('@/lib/apiClient')).default;

    const sv = oDataString(q);
    // ODataFilter only supports AND at the top level, so we hand-craft the OR clause here.
    const filter = `StandardStatus eq 'Active' and (contains(UnparsedAddress,${sv}) or contains(City,${sv}) or contains(PostalCode,${sv}))`;
    const select = [
      'ListingKey', 'ListingId', 'UnparsedAddress', 'FullAddress',
      'City', 'StateOrProvince', 'PostalCode',
      'BedroomsTotal', 'BathroomsFull', 'LivingArea',
      'ListPrice', 'YearBuilt', 'Media',
    ].join(',');

    const { data } = await apiClient.get(
      `Property?$top=8&$select=${select}&$filter=${filter}`
    );

    const raw: any[] = data?.value ?? [];

    const results: PropertyResult[] = raw.map((p) => ({
      id: p.ListingKey ?? p.ListingId ?? '',
      address: p.UnparsedAddress ?? p.FullAddress ?? '',
      city: p.City ?? '',
      state: p.StateOrProvince ?? '',
      zip: p.PostalCode ?? '',
      beds: p.BedroomsTotal ?? 0,
      baths: p.BathroomsFull ?? 0,
      sqft: p.LivingArea ?? 0,
      askingPrice: p.ListPrice ?? 0,
      yearBuilt: p.YearBuilt ?? 0,
      imageUrl: p.Media?.[0]?.MediaURL,
    }));

    return NextResponse.json(results);
  } catch (error: any) {
    console.error('[MLS SEARCH] Query failed:', error?.message ?? error);
    return NextResponse.json(
      { error: 'Property search failed. Please try again.' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth } from '@/lib/firebase/admin';
import { NotificationService } from '@/lib/services/notificationService';

export const dynamic = 'force-dynamic';

/* ═══════════════════════════════════════════════════════
   POST /api/notifications/deadline-alert

   Fires a DEADLINE_ALERT notification for a contingency
   deadline. Called by PurchaseInterview when contingency
   dates are saved. Auth via Bearer token.
   ═══════════════════════════════════════════════════════ */

interface DeadlineAlertBody {
  recipientId: string;
  projectId: string;
  dealAddress: string;
  contingencyType: string; // 'Inspection' | 'Financing' | 'Appraisal'
  deadlineDate: string;    // ISO string
  daysUntil: number;
}

export async function POST(request: NextRequest) {
  try {
    // ── Auth ──────────────────────────────────────────
    const authHeader = request.headers.get('Authorization');
    if (!authHeader?.startsWith('Bearer ')) {
      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    }

    const idToken = authHeader.split('Bearer ')[1];
    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    // ── Body validation ──────────────────────────────
    const body: DeadlineAlertBody = await request.json();
    const { recipientId, projectId, dealAddress, contingencyType, deadlineDate, daysUntil } = body;

    if (!recipientId || !projectId || !dealAddress || !contingencyType || !deadlineDate) {
      return NextResponse.json(
        { success: false, error: 'Missing required fields: recipientId, projectId, dealAddress, contingencyType, deadlineDate' },
        { status: 400 },
      );
    }

    // ── Derive the human-readable time string ────────
    const timeLabel = daysUntil <= 1
      ? `${daysUntil} day`
      : `${daysUntil} days`;

    // ── Idempotency: don't re-fire for the same contingency+date ──
    // The notification service handles deduplication at the inbox level,
    // but we generate a stable actor to avoid spamming.

    const notificationId = await NotificationService.createNotification({
      recipientId,
      type: 'DEADLINE_ALERT',
      actor: {
        uid,
        name: 'PaperWorking System',
        role: 'System',
      },
      objectReference: {
        projectId,
        dealAddress,
        time: timeLabel,
        task: `${contingencyType} contingency`,
      },
      deepLinkUrl: `/dashboard/projects/${projectId}`,
      expiresAt: new Date(deadlineDate),
    });

    console.log(`[DeadlineAlert] Created DEADLINE_ALERT ${notificationId} for ${contingencyType} on ${dealAddress} (${timeLabel})`);

    return NextResponse.json({ success: true, notificationId });
  } catch (error: any) {
    console.error('[DeadlineAlert] Error:', error);
    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ success: false, error: 'Session expired.' }, { status: 401 });
    }
    return NextResponse.json(
      { success: false, error: 'Internal server error' },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { telemetry } from '@/lib/telemetry';

const VALIDATION_API_KEY = process.env.GOOGLE_MAPS_API_KEY;

export async function POST(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  if (!VALIDATION_API_KEY) {
    return NextResponse.json(
      { error: 'Google Maps API key not configured' },
      { status: 500 }
    );
  }

  const { address } = await req.json().catch(() => ({ address: '' }));

  if (!address || typeof address !== 'string') {
    return NextResponse.json({ error: 'address is required' }, { status: 400 });
  }

  // TODO: Consider implementing rate limiting to prevent abuse of the Address Validation API

  telemetry.capture({
    distinctId: auth.uid,
    event: 'address_validation_called',
    properties: { sku: 'address-validation' }
  });

  try {
    const url = `https://addressvalidation.googleapis.com/v1:validateAddress?key=${VALIDATION_API_KEY}`;

    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        address: { addressLines: [address] },
        enableUspsCass: true
      })
    });

    if (!response.ok) {
      throw new Error(`Address Validation API returned ${response.status}`);
    }

    const data = await response.json();
    const result = data.result;

    if (!result || !result.address) {
      throw new Error('Invalid response from Address Validation API');
    }

    const postalAddress = result.address.postalAddress;
    const components = result.address.addressComponents || [];
    const verdict = result.verdict;
    const placeId = result.geocode?.placeId;

    const getComponent = (type: string) => {
      const comp = components.find((c: any) => c.componentType === type);
      return comp ? comp.componentName.text : '';
    };

    const streetNumber = getComponent('street_number');
    const route = getComponent('route');
    const unitNumber = getComponent('subpremise');
    const city = getComponent('locality');
    const state = getComponent('administrative_area_level_1');
    const zip = getComponent('postal_code');

    const canonicalAddress = postalAddress.addressLines?.join(', ') || address;

    return NextResponse.json({
      canonicalAddress,
      components: {
        streetNumber,
        route,
        unitNumber,
        city,
        state,
        zip
      },
      placeId,
      verdict
    });

  } catch (error) {
    console.warn('[Places Validate] Address Validation API failed, using fallback parsing:', error);

    // Fallback logic
    const parts = address.split(',').map(s => s.trim());
    let street = parts[0] || '';
    let city = parts[1] || '';
    let stateZip = parts[2] || '';

    let state = '';
    let zip = '';
    const stateZipParts = stateZip.split(' ').map(s => s.trim()).filter(Boolean);
    if (stateZipParts.length >= 2) {
      state = stateZipParts[0];
      zip = stateZipParts[1];
    }

    const streetParts = street.split(' ');
    const streetNumber = streetParts.shift() || '';
    const route = streetParts.join(' ');

    return NextResponse.json({
      canonicalAddress: address,
      components: {
        streetNumber,
        route,
        unitNumber: '',
        city,
        state,
        zip
      },
      placeId: null,
      verdict: { fallback: true }
    });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { getBankingProvider } from '@/lib/banking';
import { decryptToken } from '@/lib/encryption/tokenVault';
import { prisma } from '@/lib/prisma';

/**
 * DELETE /api/plaid/connections/[connectionId]
 *
 * Disconnects a Plaid bank connection:
 *   1. Auth-guard + ownership check
 *   2. Decrypt access_token
 *   3. Revoke item with Plaid (best-effort — proceeds even if Plaid call fails)
 *   4. Delete from Prisma (cascades to BankAccount + Transaction rows)
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 */
export async function DELETE(
  req: NextRequest,
  { params }: { params: { connectionId: string } }
): Promise<NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { uid } = auth;
  const { connectionId } = params;

  if (!connectionId) {
    return NextResponse.json({ success: false, error: 'connectionId is required' }, { status: 400 });
  }

  // 1. Load the connection and verify ownership
  const connection = await prisma.bankConnection.findUnique({
    where: { id: connectionId },
  });

  if (!connection) {
    return NextResponse.json({ success: false, error: 'Connection not found' }, { status: 404 });
  }

  if (connection.userId !== uid) {
    return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
  }

  // 2. Revoke Plaid item (best-effort — don't fail the disconnect if Plaid is unreachable)
  try {
    if (process.env.BANKING_PROVIDER === 'plaid') {
      const decryptedToken = decryptToken(connection.accessToken);
      const provider = getBankingProvider();
      // PlaidProvider.revokeItem is optional; only call if method exists
      if (typeof (provider as any).revokeItem === 'function') {
        await (provider as any).revokeItem(decryptedToken);
      }
    }
  } catch (err) {
    // Log but do not block the disconnect
    console.error('[DELETE /api/plaid/connections] Plaid item revocation failed (continuing):', err);
  }

  // 3. Delete from Prisma — cascades to BankAccount + Transaction via schema relations
  try {
    await prisma.bankConnection.delete({ where: { id: connectionId } });
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    console.error('[DELETE /api/plaid/connections] Failed to delete connection:', message);
    return NextResponse.json(
      { success: false, error: 'Failed to disconnect bank account' },
      { status: 500 }
    );
  }

  // 4. Emit PostHog telemetry (fire-and-forget)
  const posthogKey = process.env.NEXT_PUBLIC_POSTHOG_KEY;
  if (posthogKey) {
    fetch('https://app.posthog.com/capture/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        api_key: posthogKey,
        event: 'plaid_connection_disconnected',
        distinct_id: uid,
        properties: { connectionId, provider: 'plaid' },
      }),
    }).catch(() => {/* ignore telemetry errors */});
  }

  return NextResponse.json({ success: true });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { prisma } from '@/lib/prisma';
import { decryptToken } from '@/lib/encryption/tokenVault';
import { Configuration, PlaidApi, PlaidEnvironments, Products, CountryCode } from 'plaid';

/**
 * POST /api/plaid/create-link-token
 *
 * Creates a Plaid Link token for initializing Plaid Link in the browser.
 * Supports both new connections and update mode (re-link / reconnect).
 *
 * Request body:
 *   projectId?          string   — scopes the connection to a project
 *   connectionPurpose?  string   — e.g. 'RENT_COLLECTION'
 *   connectionId?       string   — if set → update mode (look up + decrypt access_token)
 *   products?           string[] — override default ['transactions', 'liabilities']
 *   additionalConsentedProducts? string[] — products for future consent
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 */
export const dynamic = 'force-dynamic';

const PLAID_PRODUCT_MAP: Record<string, Products> = {
  transactions: Products.Transactions,
  liabilities:  Products.Liabilities,
  auth:         Products.Auth,
  balance:      Products.Balance,
  identity:     Products.Identity,
};

function buildPlaidClient(): PlaidApi {
  const clientId = process.env.PLAID_CLIENT_ID;
  const secret   = process.env.PLAID_SECRET;
  const env      = process.env.PLAID_ENV ?? 'sandbox';

  if (!clientId || !secret) {
    throw new Error('PLAID_CLIENT_ID and PLAID_SECRET are required');
  }

  const basePath = PlaidEnvironments[env];
  if (!basePath) throw new Error(`Invalid PLAID_ENV: ${env}`);

  return new PlaidApi(
    new Configuration({
      basePath,
      baseOptions: {
        headers: { 'PLAID-CLIENT-ID': clientId, 'PLAID-SECRET': secret },
      },
    })
  );
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { uid } = auth;

  let body: {
    projectId?: string;
    connectionPurpose?: string;
    connectionId?: string;
    products?: string[];
    additionalConsentedProducts?: string[];
  };

  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  const {
    projectId,
    connectionPurpose,
    connectionId,
    products: requestedProducts,
    additionalConsentedProducts: requestedAdditional,
  } = body;

  const appUrl     = process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000';
  const webhookUrl = `${appUrl}/api/webhooks/plaid`;

  // ── Mock provider shortcut ─────────────────────────────────────────────────
  if (process.env.BANKING_PROVIDER !== 'plaid') {
    const mockToken = `link-sandbox-mock-${Math.random().toString(36).substring(7)}`;
    return NextResponse.json({ success: true, link_token: mockToken, mock: true });
  }

  try {
    const client = buildPlaidClient();

    // ── Resolve products ──────────────────────────────────────────────────────
    const productList = (requestedProducts ?? ['transactions', 'liabilities'])
      .map((p) => PLAID_PRODUCT_MAP[p])
      .filter(Boolean) as Products[];

    const additionalList = (requestedAdditional ?? ['auth', 'balance'])
      .map((p) => PLAID_PRODUCT_MAP[p])
      .filter(Boolean) as Products[];

    // ── Update mode: look up the PlaidConnection access_token ─────────────────
    let accessToken: string | undefined;
    if (connectionId) {
      const conn = await prisma.plaidConnection.findUnique({
        where: { id: connectionId },
        select: { userId: true, accessToken: true, status: true },
      });

      if (!conn) {
        return NextResponse.json({ success: false, error: 'Connection not found' }, { status: 404 });
      }
      if (conn.userId !== uid) {
        return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
      }

      try {
        accessToken = decryptToken(conn.accessToken);
      } catch {
        return NextResponse.json({ success: false, error: 'Could not decrypt access token — contact support' }, { status: 500 });
      }
    }

    // ── Build link token payload ──────────────────────────────────────────────
    const payload: Parameters<PlaidApi['linkTokenCreate']>[0] = {
      user: { client_user_id: uid },
      client_name: 'PaperWorking',
      country_codes: [CountryCode.Us],
      language: 'en',
      webhook: webhookUrl,
      ...(projectId
        ? { redirect_uri: `${appUrl}/dashboard/projects/${projectId}/financials/callback` }
        : {}),
      ...(accessToken
        ? {
            // Update mode — no products array required; they come from the existing item
            access_token: accessToken,
          }
        : {
            products: productList,
            additional_consented_products: additionalList,
          }),
    };

    const response = await client.linkTokenCreate(payload);
    const token = response.data.link_token;

    return NextResponse.json({ success: true, link_token: token });
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Failed to create link token';
    const plaidErr = (error as any)?.response?.data;
    console.error('[create-link-token] Failed:', plaidErr ?? msg);
    return NextResponse.json(
      { success: false, error: plaidErr?.error_message ?? msg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { getBankingProvider } from '@/lib/banking';
import { encryptToken } from '@/lib/encryption/tokenVault';
import { adminDb } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';
import { Configuration, PlaidApi, PlaidEnvironments } from 'plaid';

/**
 * POST /api/plaid/exchange-v2
 *
 * DTM-compliant token exchange implementing the full spec:
 *   1. Exchange public_token → access_token + item_id
 *   2. Encrypt access_token (AES-256-GCM) — never logged
 *   3. /item/get  → authoritative consentedProducts + consentedDataScopes (DTM)
 *   4. /accounts/get → account details (name, mask, subtype)
 *   5. If connectionPurpose === MORTGAGE_LIABILITY:
 *        /liabilities/get → fetch mortgage data
 *   6. Upsert PlaidConnection with DTM consent fields + consentTimestamp
 *   7. Record PlaidConsentEvent (INITIAL_CONSENT or RE_LINK) — immutable audit
 *   8. Mirror minimal metadata to Firestore for backward-compat
 *   9. PostHog telemetry (fire-and-forget)
 *
 * Accepts BOTH camelCase (from PlaidLinkButton client) and snake_case (legacy) field names.
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 * Security: access_token encrypted before any persistence. Never returned to client.
 */

export const dynamic = 'force-dynamic';

const VALID_PURPOSES = [
  'RENT_COLLECTION',
  'OPERATING_EXPENSES',
  'MORTGAGE_LIABILITY',
  'RESERVE_ACCOUNT',
  'CAPX_ACCOUNT',
] as const;

type ConnectionPurpose = (typeof VALID_PURPOSES)[number];

interface MortgageItem {
  accountId: string;
  lender: string | null;
  balance: number;
  originalBalance: number | null;
  interestRatePct: number | null;
  apr: number | null;
  nextPaymentDueDate: string | null;
  nextPaymentAmount: number | null;
  ytdInterestPaid: number | null;
  escrowBalance: number | null;
  lastPaymentAmount: number | null;
  lastPaymentDate: string | null;
}

function buildPlaidClient(): PlaidApi | null {
  const clientId = process.env.PLAID_CLIENT_ID;
  const secret   = process.env.PLAID_SECRET;
  const env      = process.env.PLAID_ENV ?? 'sandbox';
  if (!clientId || !secret) return null;
  return new PlaidApi(
    new Configuration({
      basePath: PlaidEnvironments[env],
      baseOptions: { headers: { 'PLAID-CLIENT-ID': clientId, 'PLAID-SECRET': secret } },
    })
  );
}

export async function POST(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { uid } = auth;

  let rawBody: Record<string, unknown>;
  try {
    rawBody = await req.json();
  } catch {
    return NextResponse.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  // Accept camelCase (PlaidLinkButton) or snake_case (legacy)
  const publicToken       = (rawBody.publicToken  ?? rawBody.public_token)       as string | undefined;
  const projectId         = (rawBody.projectId    ?? rawBody.project_id)         as string | undefined;
  const rawPurpose        = (rawBody.connectionPurpose ?? rawBody.connection_purpose) as string | undefined;
  const clientConsentedProducts  = (rawBody.consentedProducts  ?? rawBody.consented_products  ?? []) as string[];
  const clientConsentedScopes    = (rawBody.consentedScopes    ?? rawBody.consented_scopes    ?? []) as string[];
  const clientConsentedUseCases  = (rawBody.consentedUseCases  ?? rawBody.consented_use_cases ?? []) as string[];
  const consentVersion    = (rawBody.consentVersion ?? rawBody.consent_version)   as string | undefined;
  const linkMetadata      = (rawBody.metadata ?? {}) as Record<string, unknown>;

  if (!publicToken) {
    return NextResponse.json({ success: false, error: 'publicToken is required' }, { status: 400 });
  }

  const connectionPurpose: ConnectionPurpose =
    VALID_PURPOSES.includes(rawPurpose as ConnectionPurpose)
      ? (rawPurpose as ConnectionPurpose)
      : 'OPERATING_EXPENSES';

  const webhookUrl      = `${process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000'}/api/webhooks/plaid`;
  const consentTimestamp= new Date();
  const isMock          = process.env.BANKING_PROVIDER !== 'plaid';

  try {
    const bankingProvider = getBankingProvider();

    // ── Step 1: Exchange public_token → access_token + item_id ───────────────
    const { accessToken, itemId } = await bankingProvider.exchangePublicToken(uid, publicToken);

    // ── Step 2: Encrypt access_token before any persistence ──────────────────
    const encryptedAccessToken = encryptToken(accessToken);

    // ── Step 3: /item/get → authoritative DTM metadata ───────────────────────
    let authoritativeConsentedProducts: string[] = clientConsentedProducts;
    let authoritativeConsentedScopes: string[]   = clientConsentedScopes;
    let institutionName:    string | null = null;
    let institutionId:      string | null = null;
    let institutionLogoUrl: string | null = null;

    // ── Step 4: /accounts/get → account details ───────────────────────────────
    let accountId:      string | null = null;
    let accountName:    string | null = null;
    let accountMask:    string | null = null;
    let accountSubtype: string | null = null;

    const plaidClient = buildPlaidClient();

    if (isMock) {
      institutionName = (linkMetadata?.institution as any)?.name ?? 'Mock Bank';
      institutionId   = (linkMetadata?.institution as any)?.institution_id ?? 'ins_mock';
      accountId       = 'mock-plaid-account-id';
      accountName     = 'Business Checking';
      accountMask     = '0000';
      accountSubtype  = 'checking';
      authoritativeConsentedProducts = ['transactions', 'liabilities', 'auth'];
    } else if (plaidClient) {
      try {
        const [itemRes, accountsRes] = await Promise.all([
          plaidClient.itemGet({ access_token: accessToken }),
          plaidClient.accountsGet({ access_token: accessToken }),
        ]);

        const item        = itemRes.data.item;
        const institution = itemRes.data.status as any;
        institutionId     = item.institution_id ?? null;
        institutionName   = (linkMetadata?.institution as any)?.name
                          ?? (institution?.name as string ?? null);
        authoritativeConsentedProducts = item.consented_products ?? item.available_products ?? clientConsentedProducts;
        authoritativeConsentedScopes   = clientConsentedScopes;

        const accounts = accountsRes.data.accounts;
        let preferred   = accounts[0];
        if (connectionPurpose === 'MORTGAGE_LIABILITY') {
          preferred = accounts.find((a) => a.type === 'loan') ?? accounts[0];
        } else if (connectionPurpose === 'RENT_COLLECTION' || connectionPurpose === 'OPERATING_EXPENSES') {
          preferred = accounts.find((a) => a.type === 'depository') ?? accounts[0];
        }
        accountId      = preferred?.account_id ?? null;
        accountName    = preferred?.name ?? null;
        accountMask    = preferred?.mask ?? null;
        accountSubtype = preferred?.subtype ?? null;
      } catch (itemErr) {
        console.warn('[exchange-v2] /item/get or /accounts/get failed (non-fatal):', itemErr);
        institutionName = (linkMetadata?.institution as any)?.name ?? null;
        institutionId   = (linkMetadata?.institution as any)?.institution_id ?? null;
        const firstAcct = (linkMetadata?.accounts as any[])?.[0];
        accountId       = firstAcct?.id ?? null;
        accountName     = firstAcct?.name ?? null;
        accountMask     = firstAcct?.mask ?? null;
        accountSubtype  = firstAcct?.subtype ?? null;
      }
    }

    // ── Step 5: If MORTGAGE_LIABILITY → /liabilities/get ─────────────────────
    let pendingMortgages: MortgageItem[] = [];
    if (connectionPurpose === 'MORTGAGE_LIABILITY') {
      if (isMock && typeof (bankingProvider as any).getLiabilities === 'function') {
        pendingMortgages = await (bankingProvider as any).getLiabilities(accessToken);
      } else if (!isMock && plaidClient) {
        try {
          const liabRes = await plaidClient.liabilitiesGet({ access_token: accessToken });
          const mortgageList = liabRes.data.liabilities?.mortgage ?? [];
          pendingMortgages = mortgageList.map((m: any) => ({
            accountId:         m.account_id,
            lender:            m.originator_name ?? null,
            balance:           Math.round(((m.current_late_fee ?? 0) + (m.outstanding_principal_balance ?? 0)) * 100),
            originalBalance:   m.original_principal_balance ? Math.round(m.original_principal_balance * 100) : null,
            interestRatePct:   m.interest_rate?.percentage ?? null,
            apr:               m.interest_rate?.type === 'fixed' ? m.interest_rate?.percentage ?? null : null,
            nextPaymentDueDate:m.next_payment_due_date ?? null,
            nextPaymentAmount: m.next_monthly_payment ? Math.round(m.next_monthly_payment * 100) : null,
            ytdInterestPaid:   m.ytd_interest_paid ? Math.round(m.ytd_interest_paid * 100) : null,
            escrowBalance:     m.escrow_balance ? Math.round(m.escrow_balance * 100) : null,
            lastPaymentAmount: m.last_payment_amount ? Math.round(m.last_payment_amount * 100) : null,
            lastPaymentDate:   m.last_payment_date ?? null,
          }));
        } catch (liabErr) {
          console.warn('[exchange-v2] /liabilities/get failed (non-fatal):', liabErr);
        }
      }
    }

    // ── Step 6: Upsert PlaidConnection ───────────────────────────────────────
    const plaidConnection = await prisma.plaidConnection.upsert({
      where: { itemId },
      update: {
        accessToken: encryptedAccessToken,
        status: 'ACTIVE',
        institutionName,
        institutionId,
        institutionLogoUrl,
        accountId,
        accountName,
        accountMask,
        accountSubtype,
        webhookUrl,
        consentedProducts:   authoritativeConsentedProducts,
        consentedDataScopes: authoritativeConsentedScopes,
        consentedUseCases:   clientConsentedUseCases,
        consentTimestamp,
        consentVersion: consentVersion ?? null,
        lastSyncAt: null,
        lastSyncCursor: null,
        syncErrorCount: 0,
        lastSyncErrorMessage: null,
        updatedAt: new Date(),
      },
      create: {
        userId: uid,
        projectId: projectId ?? null,
        accessToken: encryptedAccessToken,
        itemId,
        status: 'ACTIVE',
        connectionPurpose,
        institutionName,
        institutionId,
        institutionLogoUrl,
        accountId,
        accountName,
        accountMask,
        accountSubtype,
        webhookUrl,
        consentedProducts:   authoritativeConsentedProducts,
        consentedDataScopes: authoritativeConsentedScopes,
        consentedUseCases:   clientConsentedUseCases,
        consentTimestamp,
        consentVersion: consentVersion ?? null,
      },
    });

    // ── Step 5b: Persist MortgageLiability records ────────────────────────────
    if (pendingMortgages.length > 0) {
      await Promise.all(
        pendingMortgages.map(async (m) => {
          const existing = await prisma.mortgageLiability.findFirst({
            where: { accountId: m.accountId, connectionId: plaidConnection.id },
            select: { id: true },
          });

          const data = {
            lender:            m.lender,
            balance:           BigInt(m.balance),
            originalBalance:   m.originalBalance !== null ? BigInt(m.originalBalance) : null,
            interestRatePct:   m.interestRatePct,
            apr:               m.apr,
            nextPaymentDueDate:m.nextPaymentDueDate ? new Date(m.nextPaymentDueDate) : null,
            nextPaymentAmount: m.nextPaymentAmount !== null ? BigInt(m.nextPaymentAmount) : null,
            ytdInterestPaid:   m.ytdInterestPaid !== null ? BigInt(m.ytdInterestPaid) : null,
            escrowBalance:     m.escrowBalance !== null ? BigInt(m.escrowBalance) : null,
            lastPaymentAmount: m.lastPaymentAmount !== null ? BigInt(m.lastPaymentAmount) : null,
            lastPaymentDate:   m.lastPaymentDate ? new Date(m.lastPaymentDate) : null,
            fetchedAt:         new Date(),
            updatedAt:         new Date(),
          };

          if (existing) {
            await prisma.mortgageLiability.update({ where: { id: existing.id }, data });
          } else {
            console.info('[exchange-v2] MortgageLiability create skipped — no BankConnection FK for PlaidConnection', plaidConnection.id);
          }
        })
      );
    }

    // ── Step 7: Record DTM consent event ─────────────────────────────────────
    await prisma.plaidConsentEvent.create({
      data: {
        plaidConnectionId:  plaidConnection.id,
        eventType:          'INITIAL_CONSENT',
        productsAfter:      authoritativeConsentedProducts,
        dataScopesAfter:    authoritativeConsentedScopes,
        useCasesAfter:      clientConsentedUseCases,
        triggeredBy:        uid,
        timestamp:          consentTimestamp,
      },
    });

    // ── Step 8: Mirror to Firestore ───────────────────────────────────────────
    const connectionRef = adminDb
      .collection('users')
      .doc(uid)
      .collection('plaidConnections')
      .doc(itemId);

    await connectionRef.set({
      itemId,
      plaidConnectionId:  plaidConnection.id,
      projectId:          projectId ?? null,
      connectionPurpose,
      institutionName,
      accountMask,
      status:             'ACTIVE',
      createdAt:          consentTimestamp.toISOString(),
    }, { merge: true });

    // ── Step 9: PostHog telemetry ─────────────────────────────────────────────
    const posthogKey = process.env.NEXT_PUBLIC_POSTHOG_KEY;
    if (posthogKey) {
      fetch('https://app.posthog.com/capture/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          api_key: posthogKey,
          event:   'plaid_connection_v2_created',
          distinct_id: uid,
          properties: {
            plaidConnectionId:   plaidConnection.id,
            connectionPurpose,
            institutionName,
            hasProject:          !!projectId,
            consentedProducts:   authoritativeConsentedProducts,
            hasMortgageLiability:pendingMortgages.length > 0,
          },
        }),
      }).catch(() => {/* ignore */});
    }

    return NextResponse.json({
      success:           true,
      itemId,
      plaidConnectionId: plaidConnection.id,
      connectionPurpose,
      institutionName,
      accountMask,
    });
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Failed to exchange Plaid token';
    console.error('[PlaidExchangeV2] Failed:', msg);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { getBankingProvider } from '@/lib/banking';
import { encryptToken } from '@/lib/encryption/tokenVault';
import { adminDb } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';

/**
 * POST /api/plaid/exchange
 *
 * Exchanges a Plaid public_token for an access_token + item_id, then:
 *   1. Encrypts the access_token (AES-256-GCM via tokenVault)
 *   2. Fetches institution metadata from Plaid
 *   3. Writes/upserts a BankConnection row in Prisma with all new columns
 *   4. Mirrors minimal metadata to Firestore (for backward-compat with collectionGroup queries)
 *
 * Request body:
 *   public_token    string   — from Plaid Link onSuccess
 *   project_id?     string   — optional: scope this connection to a project
 *   connection_type? string  — 'rent_deposits' | 'operating_expenses' (default: 'rent_deposits')
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 * Security: access_token never logged; encrypted before any persistence.
 */

export const dynamic = 'force-dynamic';

type ConnectionType = 'rent_deposits' | 'operating_expenses';

const VALID_CONNECTION_TYPES: ConnectionType[] = ['rent_deposits', 'operating_expenses'];

export async function POST(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { uid } = auth;

  let body: {
    public_token?: string;
    project_id?: string;
    connection_type?: string;
  };

  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  const { public_token: publicToken, project_id: projectId, connection_type: rawConnectionType } = body;

  if (!publicToken) {
    return NextResponse.json({ success: false, error: 'public_token is required' }, { status: 400 });
  }

  // Validate and normalise connection_type
  const connectionType: ConnectionType =
    VALID_CONNECTION_TYPES.includes(rawConnectionType as ConnectionType)
      ? (rawConnectionType as ConnectionType)
      : 'rent_deposits';

  const webhookUrl = `${process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3000'}/api/webhooks/plaid`;

  try {
    const bankingProvider = getBankingProvider();

    // 1. Exchange public_token → access_token + item_id
    const { accessToken, itemId } = await bankingProvider.exchangePublicToken(uid, publicToken);

    // 2. Encrypt access_token before any persistence
    const encryptedAccessToken = encryptToken(accessToken);

    // 3. Fetch institution metadata (best-effort — don't fail the exchange if this errors)
    let institutionName: string | null = null;
    let institutionId: string | null = null;
    let accountId: string | null = null;
    let accountName: string | null = null;
    let accountMask: string | null = null;

    try {
      // PlaidProvider exposes getInstitution; MockProvider returns stub data
      if (typeof (bankingProvider as any).getItemMetadata === 'function') {
        const meta = await (bankingProvider as any).getItemMetadata(accessToken);
        institutionName = meta?.institutionName ?? null;
        institutionId = meta?.institutionId ?? null;
        // First account details (denormalized for quick display)
        accountId = meta?.accounts?.[0]?.accountId ?? null;
        accountName = meta?.accounts?.[0]?.name ?? null;
        accountMask = meta?.accounts?.[0]?.mask ?? null;
      } else if (process.env.BANKING_PROVIDER === 'mock') {
        // Mock stub for dev/test
        institutionName = 'Mock Bank';
        institutionId = 'ins_mock';
        accountId = 'mock-plaid-account-id';
        accountName = 'Business Checking';
        accountMask = '0000';
      }
    } catch (metaErr) {
      console.warn('[Plaid Exchange] Institution metadata fetch failed (non-fatal):', metaErr);
    }

    // 4. Upsert BankConnection in Prisma — keyed on itemId for idempotency
    const prismaConnection = await prisma.bankConnection.upsert({
      where: { itemId },
      update: {
        // On re-link: update token + status, preserve user's project/type choice
        accessToken: encryptedAccessToken,
        status: 'active',
        institutionName,
        institutionId,
        accountId,
        accountName,
        accountMask,
        webhookUrl,
        lastSyncAt: null,
        lastSyncCursor: null,
      },
      create: {
        userId: uid,
        projectId: projectId ?? null,
        accessToken: encryptedAccessToken,
        itemId,
        status: 'active',
        connectionType,
        institutionName,
        institutionId,
        accountId,
        accountName,
        accountMask,
        webhookUrl,
      },
    });

    // 5. Mirror to Firestore for backward-compat with collectionGroup('bankConnections') queries
    const connectionRef = adminDb
      .collection('users')
      .doc(uid)
      .collection('bankConnections')
      .doc(itemId);

    await connectionRef.set({
      itemId,
      prismaConnectionId: prismaConnection.id,
      projectId: projectId ?? null,
      connectionType,
      institutionName,
      status: 'active',
      createdAt: new Date().toISOString(),
    }, { merge: true });

    // 6. PostHog telemetry (fire-and-forget)
    const posthogKey = process.env.NEXT_PUBLIC_POSTHOG_KEY;
    if (posthogKey) {
      fetch('https://app.posthog.com/capture/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          api_key: posthogKey,
          event: 'plaid_connection_created',
          distinct_id: uid,
          properties: {
            connectionId: prismaConnection.id,
            connectionType,
            institutionName,
            hasProject: !!projectId,
          },
        }),
      }).catch(() => {/* ignore */});
    }

    return NextResponse.json({
      success: true,
      itemId,
      connectionId: prismaConnection.id,
      connectionType,
      institutionName,
    });
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : 'Failed to exchange Plaid token';
    console.error('[Plaid Exchange] Failed:', msg);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}

// src/app/api/presence/heartbeat/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { adminAuth } from '@/lib/firebase/admin';
import { PresenceService } from '@/lib/services/PresenceService';

/**
 * Presence Heartbeat API
 * 
 * POST /api/presence/heartbeat
 * 
 * Authenticated users ping this endpoint every 30-45 seconds to maintain 
 * their 'online' status in Redis.
 */

export async function POST(req: NextRequest) {
  try {
    const authHeader = req.headers.get('Authorization');
    if (!authHeader?.startsWith('Bearer ')) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const idToken = authHeader.split('Bearer ')[1];
    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    await PresenceService.markUserOnline(uid);

    return NextResponse.json({ success: true, status: 'online' });
  } catch (error: any) {
    console.error('[Presence Heartbeat] Error:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { jsPDF } from 'jspdf';
import { telemetry } from '@/lib/telemetry';

export const dynamic = 'force-dynamic';

type Params = { params: Promise<{ id: string }> };

const BRAND_DARK   = [18, 16, 20] as [number, number, number];
const BRAND_WHITE  = [253, 255, 252] as [number, number, number];
const MID_GRAY     = [127, 127, 127] as [number, number, number];
const LIGHT_GRAY   = [220, 220, 220] as [number, number, number];
const ACCENT_BLUE  = [122, 158, 170] as [number, number, number];

function fmtDollar(n: number): string {
  return `$${n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function buildPdf(
  projectData: any,
  commitments: any[],
  address: string,
  date: string
): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const margin = 15;
  let y = 38;

  // Header banner
  doc.setFillColor(...BRAND_DARK);
  doc.rect(0, 0, 210, 28, 'F');

  const fs = require('fs');
  const path = require('path');
  let logoBase64 = '';
  try {
    const logoPath = path.join(process.cwd(), 'public/brand/PaperWorking_White_full_Logo_.png');
    logoBase64 = `data:image/png;base64,${fs.readFileSync(logoPath).toString('base64')}`;
  } catch {}

  if (logoBase64) {
    doc.addImage(logoBase64, 'PNG', margin, 7, 24.3, 4);
  } else {
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(...BRAND_WHITE);
    doc.text('PAPERWORKING', margin, 11);
  }

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7);
  doc.setTextColor(...MID_GRAY);
  doc.text('CAPITAL STACK STATEMENT', margin, 17);

  // Footer
  doc.setDrawColor(...LIGHT_GRAY);
  doc.line(margin, 275, 210 - margin, 275);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6);
  doc.setTextColor(...MID_GRAY);
  doc.text(`Generated ${date} · PaperWorking Capital Stack Ledger · Verified Statement`, margin, 279);

  // Title
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.setTextColor(18, 16, 20);
  doc.text('Capital Stack Statement', margin, y);
  y += 6;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.setTextColor(...MID_GRAY);
  doc.text(address, margin, y);
  y += 12;

  // Summary figures
  const financials = projectData.financials ?? {};
  const capitalStack = financials.capitalStack ?? [];
  const raiseTarget = financials.capitalRaiseTarget ?? 0;

  // Sum confirmed contributions
  const confirmedInvestorEquity = commitments
    .filter((c: any) => (c.status === 'funds-confirmed' || c.status === 'cleared') && c.partyType === 'Investor')
    .reduce((sum: number, c: any) => sum + ((c.amountCents || 0) / 100), 0);

  const confirmedLeadInvestorEquity = commitments
    .filter((c: any) => (c.status === 'funds-confirmed' || c.status === 'cleared') && (c.partyType === 'LeadInvestor' || c.partyType === 'Co-GP'))
    .reduce((sum: number, c: any) => sum + ((c.amountCents || 0) / 100), 0);

  const updatedCapitalStack = capitalStack.map((s: any) => {
    if (s.category === 'Co-buying Equity') {
      return { ...s, amount: confirmedInvestorEquity, status: 'Funded' };
    }
    if (s.category === 'Syndication Equity') {
      return { ...s, amount: confirmedInvestorEquity, status: 'Funded' };
    }
    if (s.category === 'GP Co-investment') {
      return { ...s, amount: confirmedLeadInvestorEquity, status: 'Funded' };
    }
    return s;
  });

  // Rollups
  const totalDebt = updatedCapitalStack.reduce((sum: number, src: any) => sum + (src.amount ?? 0), 0);
  const totalCommitted = commitments.reduce((sum: number, c: any) => sum + ((c.amountCents ?? 0) / 100), 0);
  const totalConfirmed = commitments.reduce((sum: number, c: any) => {
    const isFunded = c.status === 'funds-confirmed' || c.status === 'cleared';
    return sum + (isFunded ? ((c.amountCents ?? 0) / 100) : 0);
  }, 0);

  // Summary box
  doc.setFillColor(248, 249, 250);
  doc.rect(margin, y, 210 - margin * 2, 22, 'F');
  doc.setDrawColor(...LIGHT_GRAY);
  doc.rect(margin, y, 210 - margin * 2, 22, 'S');

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(100, 100, 100);
  doc.text('TOTAL DEBT', margin + 8, y + 6);
  doc.text('TOTAL EQUITY TARGET', margin + 55, y + 6);
  doc.text('CONFIRMED / FUNDED', margin + 110, y + 6);

  doc.setFontSize(11);
  doc.setTextColor(18, 16, 20);
  doc.text(fmtDollar(totalDebt), margin + 8, y + 14);
  doc.text(fmtDollar(raiseTarget), margin + 55, y + 14);
  doc.setTextColor(...ACCENT_BLUE);
  doc.text(fmtDollar(totalConfirmed), margin + 110, y + 14);
  y += 30;

  // 1. Debt Stack Table
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(18, 16, 20);
  doc.text('1. Debt Tranches', margin, y);
  y += 6;

  const colX = [margin, margin + 50, margin + 95, margin + 125];
  doc.setFontSize(7.5);
  doc.setTextColor(120, 120, 120);
  doc.text('Lender / Source', colX[0], y);
  doc.text('Category', colX[1], y);
  doc.text('Interest Rate', colX[2], y, { align: 'right' });
  doc.text('Amount', 210 - margin, y, { align: 'right' });
  y += 2;

  doc.line(margin, y, 210 - margin, y);
  y += 4.5;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8.5);
  doc.setTextColor(50, 50, 50);

  if (updatedCapitalStack.length === 0) {
    doc.setFont('helvetica', 'italic');
    doc.setTextColor(...MID_GRAY);
    doc.text('No active debt sources configured.', margin, y);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(50, 50, 50);
    y += 6;
  } else {
    for (const src of updatedCapitalStack) {
      doc.text(src.lenderName || 'Unnamed Lender', colX[0], y);
      doc.text(src.category || 'Debt', colX[1], y);
      doc.text(src.interestRate ? `${src.interestRate}%` : '--', colX[2], y, { align: 'right' });
      doc.text(fmtDollar(src.amount ?? 0), 210 - margin, y, { align: 'right' });
      y += 6;
    }
  }
  y += 6;

  // 2. Equity Ledger Table
  if (y > 200) {
    doc.addPage();
    y = 25;
  }

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(18, 16, 20);
  doc.text('2. Contribution Ledger (Equity Stack)', margin, y);
  y += 6;

  const eColX = [margin, margin + 45, margin + 70, margin + 105, margin + 135];
  doc.setFontSize(7.5);
  doc.setTextColor(120, 120, 120);
  doc.text('Party', eColX[0], y);
  doc.text('Role', eColX[1], y);
  doc.text('Status', eColX[2], y);
  doc.text('Committed', eColX[3], y, { align: 'right' });
  doc.text('Confirmed', eColX[4], y, { align: 'right' });
  doc.text('Equity %', 210 - margin, y, { align: 'right' });
  y += 2;

  doc.line(margin, y, 210 - margin, y);
  y += 4.5;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8.5);
  doc.setTextColor(50, 50, 50);

  if (commitments.length === 0) {
    doc.setFont('helvetica', 'italic');
    doc.setTextColor(...MID_GRAY);
    doc.text('No active equity contributions recorded.', margin, y);
    doc.setFont('helvetica', 'normal');
    doc.setTextColor(50, 50, 50);
    y += 6;
  } else {
    for (const c of commitments) {
      if (y > 260) {
        doc.addPage();
        y = 25;
      }
      const isFunded = c.status === 'funds-confirmed' || c.status === 'cleared';
      const commAmount = (c.amountCents ?? 0) / 100;
      const confAmount = isFunded ? commAmount : 0;
      const eqPct = raiseTarget > 0 ? (commAmount / raiseTarget) * 100 : 0;

      // Name & Email
      doc.setFont('helvetica', 'bold');
      doc.text(c.name, eColX[0], y);
      doc.setFont('helvetica', 'normal');

      // Role & Status
      doc.text(c.partyType || 'Investor', eColX[1], y);
      doc.text(c.status, eColX[2], y);

      // Amounts
      doc.text(fmtDollar(commAmount), eColX[3], y, { align: 'right' });
      doc.setTextColor(isFunded ? 40 : 120, isFunded ? 120 : 120, isFunded ? 40 : 120);
      doc.text(fmtDollar(confAmount), eColX[4], y, { align: 'right' });
      doc.setTextColor(50, 50, 50);

      // Equity Percentage
      doc.text(`${eqPct.toFixed(2)}%`, 210 - margin, y, { align: 'right' });

      // Evidence string if exists
      if (c.transitions && c.transitions.length > 0) {
        const lastTransition = c.transitions[c.transitions.length - 1];
        if (lastTransition.evidence) {
          y += 4;
          doc.setFontSize(6.5);
          doc.setTextColor(...MID_GRAY);
          doc.text(`Evidence: ${lastTransition.evidence}`, eColX[0], y);
          doc.setFontSize(8.5);
          doc.setTextColor(50, 50, 50);
        }
      }

      y += 6;
    }
  }

  // Totals line
  y += 2;
  doc.line(margin, y, 210 - margin, y);
  y += 5;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(9);
  doc.setTextColor(18, 16, 20);
  doc.text('Total Raised', eColX[0], y);
  doc.text(fmtDollar(totalCommitted), eColX[3], y, { align: 'right' });
  doc.text(fmtDollar(totalConfirmed), eColX[4], y, { align: 'right' });

  const totalEq = raiseTarget > 0 ? (totalCommitted / raiseTarget) * 100 : 0;
  doc.text(`${totalEq.toFixed(2)}%`, 210 - margin, y, { align: 'right' });

  return doc.output('arraybuffer') as unknown as Uint8Array;
}

export async function GET(req: NextRequest, { params }: Params) {
  try {
    // 1. Authenticate user
    const auth = await requireAuth(req);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 2. Resolve project from Firestore
    const { id } = await params;
    const projectSnap = await adminDb.collection('projects').doc(id).get();
    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }
    const projectData = projectSnap.data()!;

    // 3. Verify membership
    const isOwner  = projectData.ownerUid === uid;
    const isMember = !!projectData.members?.[uid];
    if (!isOwner && !isMember) {
      return NextResponse.json({ error: 'Access denied' }, { status: 403 });
    }

    // 3.5 Emit telemetry event
    try {
      await telemetry.capture({
        distinctId: uid,
        event: 'capital_stack_exported',
        properties: {
          projectId: id,
          timestamp: new Date().toISOString(),
        }
      });
    } catch (telemetryErr) {
      console.error('[Export Stack] Telemetry failed:', telemetryErr);
    }

    // 4. Fetch all commitments (contributions ledger)
    const commSnap = await adminDb
      .collection('projects')
      .doc(id)
      .collection('commitments')
      .orderBy('createdAt', 'asc')
      .get();

    const commitments = commSnap.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));

    // 5. Filename & date
    const address = (projectData.address as string | undefined ?? id)
      .replace(/[^a-zA-Z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .toLowerCase()
      .slice(0, 60);
    const dateStr = new Date().toISOString().split('T')[0];
    const filename = `capital-stack-statement-${address}-${dateStr}.pdf`;

    const displayAddress = (projectData.address as string | undefined) ?? id;

    // 6. Generate PDF bytes
    const pdfBytes = buildPdf(projectData, commitments, displayAddress, dateStr);

    return new NextResponse(pdfBytes as unknown as BodyInit, {
      status: 200,
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-store',
      },
    });
  } catch (err: any) {
    console.error('[Capital Stack Export] Failed:', err.message);
    return NextResponse.json({ error: 'Failed to export capital stack' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { syncFractionalInvestorFromCommitment, removeFractionalInvestorForCommitment } from '@/lib/firebase/syncFractionalInvestors';

/* ═══════════════════════════════════════════════════════════════
   PATCH /api/projects/[id]/commitments/[cId]
     Body: { status?, amountCents?, name?, email?, notes? }
     Updates a commitment. Only the fields present in the body
     are written; absent fields are left unchanged.

   DELETE /api/projects/[id]/commitments/[cId]
     Removes the commitment document.

   Auth: Firebase ID Token (Bearer header)
   Membership: caller must be project owner or member
   ═══════════════════════════════════════════════════════════════ */

import { CommitmentStatus } from '@/types/schema';

const VALID_STATUSES: CommitmentStatus[] = [
  'pledged',
  'transferred',
  'cleared',
  'soft-committed',
  'docs-out',
  'signed',
  'funds-confirmed'
];
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; cId: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;
    const email = auth.token.email;

    const { id: projectId, cId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const docRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('commitments')
      .doc(cId);

    const existing = await docRef.get();
    if (!existing.exists) {
      return NextResponse.json({ error: 'Commitment not found' }, { status: 404 });
    }

    const updated = existing.data()!;

    // Enforce LP/co-buyer permissions and ownership checks
    if (access.role !== 'Lead Investor') {
      const lowerEmail = email?.toLowerCase();
      const userSnap = await adminDb.collection('users').doc(uid).get();
      const userData = userSnap.exists ? userSnap.data() : null;
      const claimedEmails: string[] = userData?.claimedEmails || [];
      const allUserEmails = [lowerEmail, ...claimedEmails.map(e => e.toLowerCase())].filter(Boolean) as string[];

      const isOwner = (existing.data()?.email && allUserEmails.includes(existing.data()?.email.toLowerCase())) ||
                      existing.data()?.uid === uid ||
                      existing.data()?.createdByUid === uid;
      if (!isOwner) {
        return NextResponse.json({ error: 'Access denied: cannot modify another investor\'s commitment' }, { status: 403 });
      }

      const canEdit = access.phasePermissions?.['phase-2']?.canEdit ?? true;
      if (!canEdit) {
        return NextResponse.json({ error: 'Edit permission denied for this phase' }, { status: 403 });
      }
    }

    const body = await request.json();

    // Prevent LPs/co-buyers from updating/transferring the email or changing partyType
    if (access.role !== 'Lead Investor') {
      if (body.email !== undefined && body.email !== updated.email) {
        return NextResponse.json({ error: 'Cannot change email on an existing commitment' }, { status: 403 });
      }
      if (body.partyType !== undefined && body.partyType !== updated.partyType) {
        return NextResponse.json({ error: 'Cannot change partyType on an existing commitment' }, { status: 403 });
      }
    }

    const updates: Record<string, any> = { updatedAt: FieldValue.serverTimestamp() };

    if (body.status !== undefined) {
      if (!VALID_STATUSES.includes(body.status)) {
        return NextResponse.json(
          { error: `status must be one of: ${VALID_STATUSES.join(', ')}` },
          { status: 422 }
        );
      }
      if (access.role !== 'Lead Investor') {
        const PRIVILEGED_STATUSES = ['transferred', 'cleared', 'docs-out', 'funds-confirmed'];
        if (PRIVILEGED_STATUSES.includes(body.status)) {
          return NextResponse.json({ error: 'Cannot self-clear or self-verify commitments' }, { status: 403 });
        }
      }
      updates.status = body.status;

      if (body.status !== updated.status) {
        const transition = {
          fromStatus: updated.status || null,
          toStatus: body.status,
          timestamp: new Date().toISOString(),
          actor: auth.token.email || auth.token.name || auth.uid,
          evidence: body.evidence || null,
        };
        if (typeof FieldValue.arrayUnion === 'function') {
          updates.transitions = FieldValue.arrayUnion(transition);
        } else {
          const existingTransitions = updated.transitions || [];
          updates.transitions = [...existingTransitions, transition];
        }
      }
    }
    if (body.amountCents !== undefined) {
      if (typeof body.amountCents !== 'number' || body.amountCents <= 0) {
        return NextResponse.json({ error: 'amountCents must be a positive number' }, { status: 422 });
      }
      updates.amountCents = Math.round(body.amountCents);
    }
    if (body.name !== undefined) updates.name = String(body.name).trim();
    if (body.email !== undefined && access.role === 'Lead Investor') {
      updates.email = body.email ? String(body.email).trim() : null;
    }
    if (body.notes !== undefined) updates.notes = body.notes ? String(body.notes).trim() : null;
    if (body.partyType !== undefined && access.role === 'Lead Investor') {
      const VALID_PARTY_TYPES = ['LeadInvestor', 'Investor', 'Co-GP', 'Preferred Equity'];
      if (!VALID_PARTY_TYPES.includes(body.partyType)) {
        return NextResponse.json({ error: `partyType must be one of: ${VALID_PARTY_TYPES.join(', ')}` }, { status: 422 });
      }
      updates.partyType = body.partyType;
    }

    if (body.status === 'docs-out' && updated.status !== 'docs-out') {
      const dealDocRef = adminDb
        .collection('projects')
        .doc(projectId)
        .collection('documents')
        .doc(`sub_agreement_${cId}`);

      const docSnap = await dealDocRef.get();
      if (!docSnap.exists) {
        await dealDocRef.set({
          id: `sub_agreement_${cId}`,
          projectId,
          category: 'Other',
          fileName: `Subscription_Agreement_${(updates.name ?? updated.name).replace(/\s+/g, '_')}.pdf`,
          fileUrl: 'https://example.com/mock-subscription-agreement.pdf',
          uploadedByUid: uid,
          uploadedByName: auth.token.name || 'LeadInvestor',
          uploadedAt: new Date(),
          eSignStatus: 'Not Required',
          recipientEmail: updates.email ?? updated.email ?? null,
          recipientUid: updates.createdByUid ?? updated.createdByUid ?? null,
        });
      }
    }

    if (body.status === 'funds-confirmed' && updated.status !== 'funds-confirmed' && updated.status !== 'cleared') {
      const ledgerItemRef = adminDb
        .collection('projects')
        .doc(projectId)
        .collection('ledgerItems')
        .doc();
      await ledgerItemRef.set({
        id: ledgerItemRef.id,
        projectId,
        organizationId: access.project.organizationId || '',
        type: 'receipt',
        category: 'Other',
        description: `Capital Contribution: ${updates.name ?? updated.name}`,
        amount: (updates.amountCents ?? updated.amountCents) / 100,
        status: 'Approved',
        submittedByUid: uid,
        createdAt: new Date(),
        updatedAt: new Date(),
      });
    }

    await docRef.update(updates);

    // Keep the legacy fractionalInvestors[] view (read by equity/distribution
    // calculators) in sync with this commitment's latest status/amount.
    await syncFractionalInvestorFromCommitment(projectId, {
      id: cId,
      name: updates.name ?? updated.name,
      email: updates.email !== undefined ? updates.email : updated.email,
      amountCents: updates.amountCents ?? updated.amountCents,
      status: (updates.status ?? updated.status) as CommitmentStatus,
      partyType: updates.partyType !== undefined ? updates.partyType : updated.partyType,
    });

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[Commitments PATCH]', err.message);
    return NextResponse.json({ error: 'Failed to update commitment' }, { status: 500 });
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; cId: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;
    const email = auth.token.email;

    const { id: projectId, cId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    // Only Lead Investors can delete commitments
    if (access.role !== 'Lead Investor') {
      return NextResponse.json({ error: 'Forbidden: only Lead Investors can delete commitments' }, { status: 403 });
    }

    const docRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('commitments')
      .doc(cId);

    const existing = await docRef.get();
    if (!existing.exists) {
      return NextResponse.json({ error: 'Commitment not found' }, { status: 404 });
    }

    await docRef.delete();
    await removeFractionalInvestorForCommitment(projectId, cId);

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[Commitments DELETE]', err.message);
    return NextResponse.json({ error: 'Failed to delete commitment' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { syncFractionalInvestorFromCommitment } from '@/lib/firebase/syncFractionalInvestors';

/* ═══════════════════════════════════════════════════════════════
   Capital Raise Commitments — collection under projects/{id}

   GET  /api/projects/[id]/commitments
     Returns all commitments for the project, ordered by createdAt.
     LPs and co-buyers only see their own commitments.

   POST /api/projects/[id]/commitments
     Body: { name, amountCents, status?, email?, notes? }
     Creates a new commitment document.
     For LPs/co-buyers, forces email = auth email to prevent spoofing.

   Auth: Firebase ID Token (Bearer header)
   ═══════════════════════════════════════════════════════════════ */

import { CommitmentStatus } from '@/types/schema';

const VALID_STATUSES: CommitmentStatus[] = [
  'pledged',
  'transferred',
  'cleared',
  'soft-committed',
  'docs-out',
  'signed',
  'funds-confirmed'
];

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;
    const email = auth.token.email;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const snap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('commitments')
      .orderBy('createdAt', 'asc')
      .get();

    const commitments = snap.docs.map((d) => ({
      id: d.id,
      ...d.data(),
      createdAt: d.data().createdAt?.toDate?.()?.toISOString() ?? null,
      updatedAt: d.data().updatedAt?.toDate?.()?.toISOString() ?? null,
    }));

    let filteredCommitments = commitments;
    if (access.role !== 'Lead Investor') {
      const lowerEmail = email?.toLowerCase();
      const userSnap = await adminDb.collection('users').doc(uid).get();
      const userData = userSnap.exists ? userSnap.data() : null;
      const claimedEmails: string[] = userData?.claimedEmails || [];
      const allUserEmails = [lowerEmail, ...claimedEmails.map(e => e.toLowerCase())].filter(Boolean) as string[];

      filteredCommitments = commitments.filter((c: any) => 
        (c.email && allUserEmails.includes(c.email.toLowerCase())) || 
        c.uid === uid ||
        c.createdByUid === uid
      );
    }

    return NextResponse.json({ commitments: filteredCommitments });
  } catch (err: any) {
    console.error('[Commitments GET]', err.message);
    return NextResponse.json({ error: 'Failed to fetch commitments' }, { status: 500 });
  }
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;
    const email = auth.token.email;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    // Enforce phase-2 edit permissions for LPs/co-buyers
    if (access.role !== 'Lead Investor') {
      const canEdit = access.phasePermissions?.['phase-2']?.canEdit ?? true;
      if (!canEdit) {
        return NextResponse.json({ error: 'Edit permission denied for this phase' }, { status: 403 });
      }
    }

    const body = await request.json();
    const { name, amountCents, status = 'pledged', notes, partyType = 'Investor' } = body;

    let targetStatus = status;
    if (access.role !== 'Lead Investor') {
      targetStatus = 'pledged';
    }

    // Overwrite input email and createdByUid with verified auth values for LPs/co-buyers
    const targetEmail = access.role === 'Lead Investor' ? (body.email?.trim() || null) : (email || null);

    if (!name || typeof name !== 'string' || !name.trim()) {
      return NextResponse.json({ error: 'name is required' }, { status: 422 });
    }
    if (!amountCents || typeof amountCents !== 'number' || amountCents <= 0) {
      return NextResponse.json({ error: 'amountCents must be a positive number' }, { status: 422 });
    }
    if (!VALID_STATUSES.includes(targetStatus)) {
      return NextResponse.json({ error: `status must be one of: ${VALID_STATUSES.join(', ')}` }, { status: 422 });
    }
    const VALID_PARTY_TYPES = ['LeadInvestor', 'Investor', 'Co-GP', 'Preferred Equity'];
    if (!VALID_PARTY_TYPES.includes(partyType)) {
      return NextResponse.json({ error: `partyType must be one of: ${VALID_PARTY_TYPES.join(', ')}` }, { status: 422 });
    }

    const docRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('commitments')
      .doc();

    const doc = {
      projectId,
      name: name.trim(),
      amountCents: Math.round(amountCents),
      status: targetStatus,
      email: targetEmail,
      notes: notes?.trim() ?? null,
      partyType,
      createdByUid: uid,
      createdAt: FieldValue.serverTimestamp(),
      updatedAt: FieldValue.serverTimestamp(),
      transitions: [
        {
          fromStatus: null,
          toStatus: targetStatus,
          timestamp: new Date().toISOString(),
          actor: auth.token.email || auth.token.name || auth.uid,
          evidence: 'Initial Commitment recorded'
        }
      ]
    };

    await docRef.set(doc);

    await syncFractionalInvestorFromCommitment(projectId, {
      id: docRef.id,
      name: doc.name,
      email: doc.email,
      amountCents: doc.amountCents,
      status: doc.status,
      partyType: doc.partyType as any,
    });

    const { trackDealActivity } = require('@/lib/invitations/activityTimeline');
    await trackDealActivity(
      projectId,
      projectId,
      uid,
      'indication',
      {
        inviteeEmail: targetEmail || '',
        inviteeName: name,
        amountCents: Math.round(amountCents),
        status: targetStatus,
      }
    ).catch((e: any) => console.error('Failed to log indication event:', e));

    return NextResponse.json({ id: docRef.id, ...doc }, { status: 201 });
  } catch (err: any) {
    console.error('[Commitments POST]', err.message);
    return NextResponse.json({ error: 'Failed to create commitment' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';

/* ═══════════════════════════════════════════════════════════════
   DELETE /api/projects/[id]/dealUpdates/[updateId]
     Removes a deal update document.

   Auth: Firebase ID Token (Bearer header)
   Membership: caller must be project owner or member
   ═══════════════════════════════════════════════════════════════ */

async function verifyProjectMembership(projectId: string, uid: string) {
  const snap = await adminDb.collection('projects').doc(projectId).get();
  if (!snap.exists) return null;
  const data = snap.data()!;
  const isOwner = data.ownerUid === uid;
  const isMember = !!data.members?.[uid] || data.teamMemberIds?.includes(uid);
  const isOrgMember = data.organizationId
    ? await adminDb.collection('organizations').doc(data.organizationId).get().then((o) => {
        if (!o.exists) return false;
        const od = o.data()!;
        return od.ownerUid === uid || od.teamMembers?.some((m: any) => m.id === uid && m.status === 'active');
      })
    : false;
  if (!isOwner && !isMember && !isOrgMember) return null;
  return data;
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; updateId: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId, updateId } = await params;

    const project = await verifyProjectMembership(projectId, uid);
    if (!project) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const docRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('dealUpdates')
      .doc(updateId);

    const existing = await docRef.get();
    if (!existing.exists) {
      return NextResponse.json({ error: 'Deal update not found' }, { status: 404 });
    }

    await docRef.delete();

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[DealUpdates DELETE]', err.message);
    return NextResponse.json({ error: 'Failed to delete deal update' }, { status: 500 });
  }
}

