import { NextRequest, NextResponse } from 'next/server';
import { adminDb, adminStorage } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';
import { VENDOR_SLOT_FOLDER_MAPPING, getFolderForDocument, getPhaseForDocument } from '../../route';

export const dynamic = 'force-dynamic';

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string; docId: string }> }
) {
  try {
    const { id: projectId, docId } = await params;
    if (!projectId || !docId) {
      return NextResponse.json({ error: 'Missing projectId or docId' }, { status: 400 });
    }

    // Try optional auth first (for public solicited deals)
    let auth: any = null;
    try {
      auth = await requireAuth(req);
    } catch {
      // Ignored for potential anonymous public access
    }

    const isAuthenticated = auth && !isAuthError(auth);
    const uid = isAuthenticated ? auth.uid : null;
    const email = isAuthenticated ? auth.token.email : null;

    // 1. Fetch file record from Firestore or resolve direct path (DM-20)
    let fileRecord: any = null;
    if (docId === 'download') {
      const searchParams = req.nextUrl.searchParams;
      const pathParam = searchParams.get('path');
      if (!pathParam) {
        return NextResponse.json({ error: 'Missing path parameter' }, { status: 400 });
      }
      // Ensure path is restricted to the specific project directory to prevent path traversal
      if (!pathParam.startsWith(`projects/${projectId}/`)) {
        return NextResponse.json({ error: 'Access denied: path outside project directory' }, { status: 403 });
      }
      const nameParam = searchParams.get('name') || 'document';
      fileRecord = {
        projectId,
        storagePath: pathParam,
        name: nameParam,
        fileType: pathParam.toLowerCase().endsWith('.pdf') ? 'application/pdf' : 'application/octet-stream',
      };
    } else {
      const docRef = adminDb.collection('projectFiles').doc(docId);
      const docSnap = await docRef.get();
      if (docSnap.exists) {
        fileRecord = docSnap.data();
      } else {
        const subDocRef = adminDb
          .collection('projects')
          .doc(projectId)
          .collection('documents')
          .doc(docId);
        const subDocSnap = await subDocRef.get();
        if (subDocSnap.exists) {
          fileRecord = subDocSnap.data();
        }
      }
    }

    if (!fileRecord) {
      return NextResponse.json({ error: 'Document not found' }, { status: 404 });
    }

    // Verify file matches the project ID requested
    if (fileRecord.projectId !== projectId) {
      return NextResponse.json({ error: 'Invalid project ID for file' }, { status: 400 });
    }

    // 2. Check deal visibility mode (DM-20)
    let listingSnap: any = { empty: true, docs: [] };
    const dealListingsColl = adminDb.collection('dealListings');
    if (dealListingsColl && typeof dealListingsColl.where === 'function') {
      listingSnap = await dealListingsColl
        .where('projectId', '==', projectId)
        .where('status', '==', 'published')
        .limit(1)
        .get();
    }

    let isAuthorized = false;
    let userRole = 'Anonymous';
    let assignedFolder = '';
    let partyId = '';

    // Direct project membership authorization
    if (isAuthenticated && uid && email) {
      const access = await verifyProjectAccessAndRole(projectId, uid, email);
      if (access) {
        isAuthorized = true;
        userRole = access.role;
        partyId = access.partyId || '';
        assignedFolder = VENDOR_SLOT_FOLDER_MAPPING[partyId] || '';
      }
    }

    // Check visibility mode if active listing exists
    let visibilityMode = 'PRIVATE';
    let exposedDocumentIds: string[] = [];
    if (!listingSnap.empty) {
      const listingData = listingSnap.docs[0].data();
      visibilityMode = listingData.visibilityMode || 'PRIVATE';
      exposedDocumentIds = listingData.exposedDocumentIds || [];

      if (visibilityMode === 'PUBLIC_SOLICITED' || visibilityMode === 'MARKETPLACE') {
        if (isAuthenticated && uid) {
          const userDoc = await adminDb.collection('users').doc(uid).get();
          const userProfile = userDoc.exists ? userDoc.data() : null;
          const plan = userProfile?.subscriptionPlan;
          const status = userProfile?.subscriptionStatus;
          if (
            plan &&
            plan !== 'None' &&
            plan !== 'Vendor Network' &&
            status === 'active' &&
            userProfile?.accountType !== 'vendor'
          ) {
            isAuthorized = true;
            userRole = 'Subscriber';
          }
        }
      }
    }

    if (userRole === 'Vendor') {
      return NextResponse.json({ error: 'Not found' }, { status: 404 });
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'Access denied' }, { status: 403 });
    }

    if (userRole === 'Subscriber') {
      if (docId === 'download' || !exposedDocumentIds.includes(docId)) {
        return NextResponse.json({ error: 'Access denied' }, { status: 403 });
      }
    }

    // Check phase view permission
    const docPhase = fileRecord.phase || getPhaseForDocument(fileRecord);
    if (isAuthenticated && uid && email && userRole !== 'Lead Investor' && userRole !== 'Subscriber') {
      const access = await verifyProjectAccessAndRole(projectId, uid, email);
      if (access && access.phasePermissions) {
        const canView = access.phasePermissions[docPhase]?.canView;
        if (canView === false) {
          return NextResponse.json(
            { error: `Access denied: View permission disabled for ${docPhase}.` },
            { status: 403 }
          );
        }
      }
    }

    // 3. Fine-grained permission checks (vendors, file recipients, etc.)
    if (userRole === 'Vendor') {
      const assignedFolder = VENDOR_SLOT_FOLDER_MAPPING[partyId || ''];
      if (!assignedFolder) {
        return NextResponse.json({ error: 'Access denied' }, { status: 403 });
      }
      const docFolder = getFolderForDocument(fileRecord);
      if (docFolder !== assignedFolder) {
        return NextResponse.json({ error: 'Access denied' }, { status: 403 });
      }
    } else if (userRole !== 'Lead Investor' && userRole !== 'Subscriber' && visibilityMode === 'PRIVATE') {
      // Direct project members checking uploadedBy / recipient
      const lowerEmail = email?.toLowerCase();
      const isUploader = fileRecord.uploadedByUid === uid || (fileRecord.uploadedByEmail && lowerEmail && fileRecord.uploadedByEmail.toLowerCase() === lowerEmail);
      const isRecipient = fileRecord.recipientUid === uid || (fileRecord.recipientEmail && lowerEmail && fileRecord.recipientEmail.toLowerCase() === lowerEmail);
      const isOwnSubAgreement = fileRecord.id === `sub_agreement_${partyId}`;
      const isPublic = fileRecord.isPublic === true || fileRecord.category === 'Deal identity';

      if (!isUploader && !isRecipient && !isOwnSubAgreement && !isPublic) {
        return NextResponse.json({ error: 'Access denied' }, { status: 403 });
      }
    }

    // 4. Download and stream the file from Cloud Storage
    const bucket = adminStorage.bucket();
    const fileRef = bucket.file(fileRecord.storagePath);
    const [exists] = await fileRef.exists();

    if (!exists) {
      return NextResponse.json({ error: 'File not found in storage' }, { status: 404 });
    }

    const [content] = await fileRef.download();

    return new NextResponse(new Uint8Array(content), {
      status: 200,
      headers: {
        'Content-Type': fileRecord.fileType || 'application/octet-stream',
        'Content-Disposition': `inline; filename="${fileRecord.name}"`,
        'Cache-Control': 'private, max-age=3600',
      },
    });
  } catch (error: any) {
    console.error('[API/documents download GET] failed:', error?.message ?? error);
    return NextResponse.json({ error: 'Failed to download document' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';
import { adminDb, adminStorage } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { logOrgActivity } from '@/lib/firebase/orgActivityWriter';

/* ═══════════════════════════════════════════════════════
   POST /api/projects/[id]/documents

   Upload a document to a project's filing cabinet.

   Accepts: multipart/form-data
     - file: File (PDF, JPG, PNG) — max 25 MB
     - documentType: DocumentType enum value
     - category: DocumentCategory (optional, defaults to 'Other')
     - folderId: string (optional — parent folder)

   Actions:
     1. Validate file type, size, auth
     2. Upload to Firebase Storage: projects/{id}/documents/{docId}/{filename}
     3. Create projectFiles record in Firestore with status: 'Uploaded'
     4. Return { docId, downloadUrl, status: 'Uploaded' }

   NO Cloud Functions — this is a Next.js API route.
   ═══════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';

const ALLOWED_MIMES = [
  'application/pdf',
  'image/jpeg',
  'image/png',
] as const;

const MAX_FILE_BYTES = 25 * 1024 * 1024; // 25 MB

const VALID_DOCUMENT_TYPES = [
  'closing_disclosure',
  'receipt',
  'lease',
  'inspection',
  'appraisal',
  'contractor_bid',
  'title_report',
  'purchase_agreement',
  'other',
] as const;

export const VENDOR_SLOT_FOLDER_MAPPING: Record<string, string> = {
  f4TitleEscrowVendor: 'Title & Insurance',
  f4ClosingAttorneyVendor: 'Closing',
  f4AppraiserVendor: 'Debt',
  f4EnvironmentalVendor: 'Title & Insurance',
  f4SurveyorVendor: 'Title & Insurance',
  f4InsuranceBrokerVendor: 'Title & Insurance',
  f4CdcVendor: 'Debt',
  f4HardMoneyLenderVendor: 'Debt',
};

export function getFolderForDocument(doc: any): 'Capital Plan' | 'Equity' | 'Debt' | 'Title & Insurance' | 'Closing' {
  if (doc.folderName) {
    const name = String(doc.folderName).trim();
    if (['Capital Plan', 'Equity', 'Debt', 'Title & Insurance', 'Closing'].includes(name)) {
      return name as any;
    }
  }

  const docType = (doc.documentType || '').toLowerCase();
  const category = (doc.category || '').toLowerCase();
  const name = (doc.name || doc.fileName || '').toLowerCase();
  const notes = (doc.notes || '').toLowerCase();

  // Debt (lender package, estimates, appraisal, commitment)
  if (
    docType === 'appraisal' ||
    category === 'appraisal' ||
    name.includes('appraisal') ||
    name.includes('lender') ||
    name.includes('loan_estimate') ||
    name.includes('loan estimate') ||
    name.includes('debt') ||
    name.includes('commitment') ||
    category === 'debt'
  ) {
    return 'Debt';
  }

  // Title & Insurance
  if (
    docType === 'title_report' ||
    category === 'title report' ||
    category === 'inspection report' ||
    docType === 'inspection' ||
    category === 'permit' ||
    docType === 'permit' ||
    name.includes('title') ||
    name.includes('survey') ||
    name.includes('environmental') ||
    name.includes('phase_i') ||
    name.includes('insurance') ||
    name.includes('zoning') ||
    name.includes('hoa') ||
    category === 'title & insurance' ||
    category === 'title search' ||
    category === 'compliance & operations'
  ) {
    return 'Title & Insurance';
  }

  // Equity (agreements, subscriptions)
  if (
    category === 'equity' ||
    category === 'subscription' ||
    doc.id?.startsWith('sub_agreement_') ||
    name.includes('subscription') ||
    name.includes('partnership')
  ) {
    return 'Equity';
  }

  // Capital Plan (proof of funds)
  if (
    category === 'capital plan' ||
    category === 'proof of funds' ||
    notes.includes('capital stack') ||
    name.includes('capital-stack') ||
    name.includes('proof-of-funds') ||
    name.includes('capital_stack') ||
    category === 'proof_of_funds'
  ) {
    return 'Capital Plan';
  }

  // Closing (CD, executed set, recording)
  if (
    docType === 'closing_disclosure' ||
    category === 'hud-1 settlement statement' ||
    name.includes('closing') ||
    name.includes('deed') ||
    name.includes('executed') ||
    name.includes('recording') ||
    name.includes('disbursement') ||
    notes.includes('dossier snapshot') ||
    category === 'dossier snapshot' ||
    doc.id?.startsWith('closing_') ||
    name.includes('psa') ||
    name.includes('purchase_and_sale') ||
    name.includes('emd') ||
    category === 'transaction & escrow'
  ) {
    return 'Closing';
  }

  return 'Closing'; // Fallback
}

export function getPhaseForDocument(doc: any): 'phase-1' | 'phase-2' | 'phase-3' | 'phase-4' | 'founder_review' {
  if (doc.phase) {
    if (['phase-1', 'phase-2', 'phase-3', 'phase-4', 'founder_review'].includes(doc.phase)) {
      return doc.phase as any;
    }
  }

  const docType = (doc.documentType || '').toLowerCase();
  const category = (doc.category || '').toLowerCase();
  const name = (doc.name || doc.fileName || '').toLowerCase();

  // Phase 1: Acquisition (LOI, PSA/Purchase Agreement, Due Diligence checklists)
  if (
    category === 'loi' ||
    docType === 'loi' ||
    category === 'purchase agreement' ||
    docType === 'purchase_agreement' ||
    name.includes('loi') ||
    name.includes('psa') ||
    name.includes('purchase_agreement') ||
    name.includes('emd') ||
    name.includes('due_diligence')
  ) {
    return 'phase-1';
  }

  // Phase 3: Hold (Rehab bids, rehab invoices, leasing, rent setup, operations, contractor)
  if (
    category === 'contractor bid' ||
    name.includes('rehab') ||
    name.includes('bid') ||
    name.includes('invoice') ||
    name.includes('lease') ||
    name.includes('tenant') ||
    name.includes('rent_roll')
  ) {
    return 'phase-3';
  }

  // Phase 4: Exit (Sold, Listed, final gains waterfall tax packets)
  if (
    name.includes('taxpacket') ||
    name.includes('sold') ||
    name.includes('exit_waterfall')
  ) {
    return 'phase-4';
  }

  // Phase 2: Fund (Lender packages, loans, commitments, appraisals, subscriptions, capital plan, proof of funds, etc.)
  return 'phase-2';
}

async function ensureFolder(
  projectId: string,
  folderName: string,
  organizationId: string,
  ownerUid: string
): Promise<string> {
  const foldersColl = adminDb.collection('projectFolders');
  const snap = await foldersColl
    .where('projectId', '==', projectId)
    .where('name', '==', folderName)
    .limit(1)
    .get();

  if (!snap.empty) {
    return snap.docs[0].id;
  }

  const folderRef = foldersColl.doc();
  const folderId = folderRef.id;
  await folderRef.set({
    id: folderId,
    projectId,
    organizationId,
    name: folderName,
    phase: folderName,
    ownerUid,
    fileCount: 0,
    createdAt: FieldValue.serverTimestamp(),
  });

  return folderId;
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  // ── Auth ────────────────────────────────────────────
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;
  const { uid } = auth;

  const { id: projectId } = await params;
  if (!projectId) {
    return NextResponse.json({ error: 'Missing project ID' }, { status: 400 });
  }

  const access = await verifyProjectAccessAndRole(projectId, uid, auth.token.email);
  if (!access) {
    return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
  }

  if (access.role !== 'Lead Investor') {
    const canEdit = access.phasePermissions?.['phase-2']?.canEdit ?? true;
    if (!canEdit) {
      return NextResponse.json({ error: 'Edit permission denied for this phase' }, { status: 403 });
    }
  }
  const projectData = access.project;

  let formData: FormData;
  try {
    formData = await req.formData();
  } catch {
    return NextResponse.json({ error: 'Invalid form data. Expected multipart/form-data.' }, { status: 400 });
  }

  const file = formData.get('file') as File | null;
  if (!file || !(file instanceof File)) {
    return NextResponse.json({ error: 'No file provided. Include a "file" field.' }, { status: 400 });
  }

  // ── Validate file type ─────────────────────────────
  const mimeType = file.type;
  if (!(ALLOWED_MIMES as readonly string[]).includes(mimeType)) {
    return NextResponse.json(
      { error: `Unsupported file type "${mimeType}". Accepted: ${ALLOWED_MIMES.join(', ')}` },
      { status: 415 }
    );
  }

  // ── Validate file size ─────────────────────────────
  if (file.size > MAX_FILE_BYTES) {
    return NextResponse.json(
      { error: `File exceeds 25 MB limit (${(file.size / 1024 / 1024).toFixed(1)} MB)` },
      { status: 413 }
    );
  }

  // ── Read form fields ───────────────────────────────
  const documentType = (formData.get('documentType') as string) || 'other';
  if (!VALID_DOCUMENT_TYPES.includes(documentType as typeof VALID_DOCUMENT_TYPES[number])) {
    return NextResponse.json(
      { error: `Invalid documentType "${documentType}". Valid: ${VALID_DOCUMENT_TYPES.join(', ')}` },
      { status: 400 }
    );
  }

  const category = (formData.get('category') as string) || 'Other';

  let phase = (formData.get('phase') as string) || '';
  if (phase && !['phase-1', 'phase-2', 'phase-3', 'phase-4', 'founder_review'].includes(phase)) {
    return NextResponse.json(
      { error: `Invalid phase "${phase}". Valid values: phase-1, phase-2, phase-3, phase-4, founder_review` },
      { status: 400 }
    );
  }

  if (!phase) {
    phase = getPhaseForDocument({
      name: file.name,
      fileName: file.name,
      category,
      documentType,
    });
  }

  // Auto-resolve folder taxonomy name and folder ID
  const resolvedFolder = getFolderForDocument({
    name: file.name,
    fileName: file.name,
    category,
    documentType,
  });

  if (access.role === 'Vendor') {
    const assignedFolder = VENDOR_SLOT_FOLDER_MAPPING[access.partyId || ''];
    if (!assignedFolder || resolvedFolder !== assignedFolder) {
      return NextResponse.json(
        { error: `Vendor is only authorized to upload documents to the "${assignedFolder}" folder` },
        { status: 403 }
      );
    }
  }



  const folderId = await ensureFolder(
    projectId,
    resolvedFolder,
    projectData.organizationId || '',
    projectData.ownerUid || uid
  );

  // ── Generate document ID and upload ────────────────
  const docId = crypto.randomUUID();
  const sanitizedFilename = file.name.replace(/[^a-zA-Z0-9._-]/g, '_');
  const storagePath = `projects/${projectId}/documents/${docId}/${sanitizedFilename}`;

  try {
    // Read file buffer
    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);

    // Upload to Firebase Storage via Admin SDK
    const bucket = adminStorage.bucket();
    const storageFile = bucket.file(storagePath);

    await storageFile.save(buffer, {
      metadata: {
        contentType: mimeType,
        metadata: {
          projectId,
          docId,
          uploadedBy: uid,
          documentType,
        },
      },
    });

    // DO NOT call makePublic() — keep the GCS file private (DM-20)
    const downloadUrl = `/api/projects/${projectId}/documents/${docId}/download`;

    // ── Create Firestore record ────────────────────────
    const fileRecord = {
      id: docId,
      folderId,
      projectId,
      organizationId: projectData.organizationId || '',
      name: file.name,
      category,
      storageUrl: downloadUrl,
      storagePath,
      fileType: mimeType,
      sizeBytes: file.size,
      uploadedByUid: uid,
      uploadedByEmail: auth.token.email || '',
      isVerified: false,
      uploadedAt: FieldValue.serverTimestamp(),
      status: 'Uploaded',
      isControlEvidence: true,
      purpose: 'control_evidence' as const,
      phase,
    };

    await adminDb.collection('projectFiles').doc(docId).set(fileRecord);

    // Update folder file count
    const folderRef = adminDb.collection('projectFolders').doc(folderId);
    await folderRef.update({ fileCount: FieldValue.increment(1) }).catch(() => {
      // Non-critical
    });

    // Emit activity event — failure-isolated, never blocks the response
    if (projectData.organizationId) {
      const actorName = auth.token.name || auth.token.email || 'Unknown';
      const projectLabel = projectData.propertyName || projectData.address || projectId;
      logOrgActivity({
        organizationId: projectData.organizationId,
        type: 'doc_uploaded',
        actorId: uid,
        actorName,
        summary: `Uploaded "${file.name}" to ${projectLabel}`,
        targetRef: `projects/${projectId}/documents/${docId}`,
        projectId,
        projectName: projectLabel,
      });
    }

    return NextResponse.json(
      {
        docId,
        downloadUrl,
        storagePath,
        status: 'Uploaded',
        phase,
      },
      { status: 201 }
    );
  } catch (error: any) {
    console.error('[API/documents] Upload failed:', error?.message ?? error);
    return NextResponse.json(
      { error: 'Document upload failed', details: error?.message },
      { status: 500 }
    );
  }
}

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const { id: projectId } = await params;
    if (!projectId) {
      return NextResponse.json({ error: 'Missing project ID' }, { status: 400 });
    }

    // Try optional auth first (for public solicited deals)
    let auth: any = null;
    try {
      auth = await requireAuth(req);
    } catch {
      // Ignored for potential anonymous public access
    }

    const isAuthenticated = auth && !isAuthError(auth);
    const uid = isAuthenticated ? auth.uid : null;
    const email = isAuthenticated ? auth.token.email : null;

    // Check deal visibility mode (DM-20)
    let listingSnap: any = { empty: true, docs: [] };
    const dealListingsColl = adminDb.collection('dealListings');
    if (dealListingsColl && typeof dealListingsColl.where === 'function') {
      listingSnap = await dealListingsColl
        .where('projectId', '==', projectId)
        .where('status', '==', 'published')
        .limit(1)
        .get();
    }

    let isAuthorized = false;
    let projectData: any = null;
    let userRole = 'Anonymous';
    let assignedFolder = '';
    let partyId = '';
    let access: any = null;

    // Direct project membership authorization
    if (isAuthenticated && uid && email) {
      access = await verifyProjectAccessAndRole(projectId, uid, email);
      if (access) {
        isAuthorized = true;
        projectData = access.project;
        userRole = access.role;
        partyId = access.partyId || '';
        assignedFolder = VENDOR_SLOT_FOLDER_MAPPING[partyId] || '';
      }
    }

    // Check visibility mode if active listing exists
    let visibilityMode = 'PRIVATE';
    let exposedDocumentIds: string[] = [];
    if (!listingSnap.empty) {
      const listingData = listingSnap.docs[0].data();
      visibilityMode = listingData.visibilityMode || 'PRIVATE';
      exposedDocumentIds = listingData.exposedDocumentIds || [];

      if (visibilityMode === 'PUBLIC_SOLICITED' || visibilityMode === 'MARKETPLACE') {
        if (isAuthenticated && uid) {
          const userDoc = await adminDb.collection('users').doc(uid).get();
          const userProfile = userDoc.exists ? userDoc.data() : null;
          const plan = userProfile?.subscriptionPlan;
          const status = userProfile?.subscriptionStatus;
          if (
            plan &&
            plan !== 'None' &&
            plan !== 'Vendor Network' &&
            status === 'active' &&
            userProfile?.accountType !== 'vendor'
          ) {
            isAuthorized = true;
            userRole = 'Subscriber';
          }
        }
      }
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'Access denied' }, { status: 403 });
    }

    if (!projectData) {
      const projectSnap = await adminDb.collection('projects').doc(projectId).get();
      if (!projectSnap.exists) {
        return NextResponse.json({ error: 'Project not found' }, { status: 404 });
      }
      projectData = projectSnap.data();
    }

    // 1. Fetch files
    const filesSnap = await adminDb
      .collection('projectFiles')
      .where('projectId', '==', projectId)
      .get();

    const files = filesSnap.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
      uploadedAt: doc.data().uploadedAt?.toDate?.()?.toISOString() ?? doc.data().uploadedAt ?? null,
    }));

    // 2. Fetch Sub Agreements
    const subSnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('subAgreements')
      .get();

    const subDocs = subSnap.docs.map(doc => ({
      id: doc.id,
      ...doc.data(),
      uploadedAt: doc.data().uploadedAt?.toDate?.()?.toISOString() ?? doc.data().uploadedAt ?? null,
    }));

    const allDocs = [...files, ...subDocs];

    // 3. Filter if not Lead Investor
    let filteredDocs = allDocs;
    if (userRole !== 'Lead Investor') {
      const lowerEmail = email?.toLowerCase();
      filteredDocs = allDocs.filter((d: any) => {
        // Check phase view permission
        const docPhase = d.phase || getPhaseForDocument(d);
        if (access && access.phasePermissions) {
          const canView = access.phasePermissions[docPhase]?.canView;
          if (canView === false) {
            return false;
          }
        }

        // If the user is a Vendor, they can ONLY see documents in their assigned folder!
        if (userRole === 'Vendor') {
          const assignedFolder = VENDOR_SLOT_FOLDER_MAPPING[partyId || ''];
          if (!assignedFolder) return false;
          const docFolder = getFolderForDocument(d);
          return docFolder === assignedFolder;
        }

        // Subscribers and public users see public documents (or the ones where they are recipients, etc.)
        const isUploader = d.uploadedByUid === uid || (d.uploadedByEmail && lowerEmail && d.uploadedByEmail.toLowerCase() === lowerEmail);
        const isRecipient = d.recipientUid === uid || (d.recipientEmail && lowerEmail && d.recipientEmail.toLowerCase() === lowerEmail);
        const isOwnSubAgreement = d.id === `sub_agreement_${partyId}`;

        // For marketplace / public_solicited, allow viewing public documents
        const isPublic = d.isPublic === true || d.category === 'Deal identity' || visibilityMode === 'MARKETPLACE' || visibilityMode === 'PUBLIC_SOLICITED';

        return isUploader || isRecipient || isOwnSubAgreement || isPublic;
      });
    }

    // Fetch existing folders for the project
    const foldersSnap = await adminDb
      .collection('projectFolders')
      .where('projectId', '==', projectId)
      .get();

    const foldersMap = new Map<string, string>();
    foldersSnap.docs.forEach(doc => {
      foldersMap.set(doc.data().name, doc.id);
    });

    // Populate resolved folderName and folderId
    const mappedDocs = filteredDocs.map((d: any) => {
      const resolvedFolder = getFolderForDocument(d);
      const resolvedFolderId = foldersMap.get(resolvedFolder) || `${projectId}_default`;

      const isExposed = exposedDocumentIds.includes(d.id);

      const baseDoc: any = {
        id: d.id,
        name: d.name,
        type: d.type || null,
        category: d.category || null,
        phase: d.phase || null,
        uploadedAt: d.uploadedAt || null,
        folderName: resolvedFolder,
        folderId: resolvedFolderId,
      };

      if (userRole !== 'Subscriber' && userRole !== 'Anonymous') {
        return {
          ...d,
          ...baseDoc,
          storageUrl: `/api/projects/${projectId}/documents/${d.id}/download`,
          documentUrl: `/api/projects/${projectId}/documents/${d.id}/download`,
        };
      } else {
        if (isExposed) {
          return {
            ...d,
            ...baseDoc,
            storageUrl: `/api/projects/${projectId}/documents/${d.id}/download`,
            documentUrl: `/api/projects/${projectId}/documents/${d.id}/download`,
          };
        } else {
          return baseDoc;
        }
      }
    });

    return NextResponse.json({ documents: mappedDocs });
  } catch (error: any) {
    console.error('[API/documents GET] failed:', error?.message ?? error);
    return NextResponse.json({ error: 'Failed to fetch documents' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import type { CapitalSource } from '@/types/schema';

/* ═══════════════════════════════════════════════════════
   PATCH /api/projects/[id]/funding-sources

   Replaces the full capitalStack array on a project's
   financials with the caller-provided sources.

   Security:
   - Requires Firebase ID token (Authorization: Bearer)
   - No source of truth is client-provided identity
   - All writes use firebase-admin (server-side credentials)
   ═══════════════════════════════════════════════════════ */

interface Params { params: Promise<{ id: string }> }

export async function PATCH(req: NextRequest, { params }: Params) {
  // ── Auth ──────────────────────────────────────────────────
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id: projectId } = await params;

  if (!projectId) {
    return NextResponse.json(
      { success: false, error: 'projectId is required' },
      { status: 400 }
    );
  }

  let body: { sources: CapitalSource[] };
  try {
    body = await req.json();
  } catch {
    return NextResponse.json(
      { success: false, error: 'Invalid JSON body' },
      { status: 400 }
    );
  }

  const { sources } = body;
  if (!Array.isArray(sources)) {
    return NextResponse.json(
      { success: false, error: 'sources must be an array' },
      { status: 400 }
    );
  }

  // ── Load project and user profile ────────────────────────
  const projectSnap = await adminDb.collection('projects').doc(projectId).get();
  if (!projectSnap.exists) {
    return NextResponse.json(
      { success: false, error: 'Project not found' },
      { status: 404 }
    );
  }
  const projectData = projectSnap.data();
  const orgId = projectData?.organizationId;

  const userSnap = await adminDb.collection('users').doc(auth.uid).get();
  if (!userSnap.exists) {
    return NextResponse.json({ error: 'Access denied' }, { status: 403 });
  }
  const profile = userSnap.data();

  // Helper to check project scoped access
  function hasProjectAccess(
    profile: any,
    targetOrgId: string | undefined,
    projectId?: string
  ): boolean {
    if (!targetOrgId) return false;
    const orgMember =
      profile.personalOrganizationId === targetOrgId ||
      profile.organizationId === targetOrgId ||
      (profile.memberships != null && Boolean(profile.memberships[targetOrgId]));

    if (!orgMember) return false;

    if (projectId && profile.membershipScopes) {
      const scope = profile.membershipScopes[targetOrgId];
      if (scope?.isScoped) {
        return Array.isArray(scope.scopedProjectIds) && scope.scopedProjectIds.includes(projectId);
      }
    }
    return true;
  }

  if (!hasProjectAccess(profile, orgId, projectId)) {
    return NextResponse.json({ error: 'Access denied' }, { status: 403 });
  }

  // ── Persist to Firestore ─────────────────────────────────
  try {
    await adminDb
      .collection('projects')
      .doc(projectId)
      .update({
        'financials.capitalStack': sources,
        updatedAt: FieldValue.serverTimestamp(),
      });
  } catch (err: any) {
    console.error('[funding-sources] Firestore write failed:', err);
    return NextResponse.json(
      { success: false, error: 'Failed to persist funding sources' },
      { status: 500 }
    );
  }

  return NextResponse.json({
    success: true,
    data: { projectId, sources, updatedAt: new Date().toISOString() },
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { NotificationService } from '@/lib/services/notificationService';
import { determineAccessAndRole, authorizeProjectMutation } from '@/lib/firebase-admin/project-guard';
import { z } from 'zod';

const advanceBodySchema = z.object({
  costBasis: z.number(),
  capitalizedImprovements: z.number(),
  holdingCosts: z.number(),
  outcome: z.string()
});

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // 1. Verify auth
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    if (!projectId) {
      return NextResponse.json({ error: 'Missing project ID' }, { status: 400 });
    }

    // 2. Parse and validate body
    const body = await request.json();
    const validationResult = advanceBodySchema.safeParse(body);
    if (!validationResult.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: validationResult.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { costBasis, capitalizedImprovements, holdingCosts, outcome } = validationResult.data;

    // 3. Verify access
    const projectRef = adminDb.collection('projects').doc(projectId);
    const projectSnap = await projectRef.get();
    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }
    const projectData = projectSnap.data()!;
    const targetOrgId = projectData.organizationId;

    let orgData: any = null;
    if (targetOrgId) {
      const orgSnap = await adminDb.collection('organizations').doc(targetOrgId).get();
      if (orgSnap.exists) {
        orgData = orgSnap.data();
      }
    }

    const access = determineAccessAndRole(projectData, uid, auth.token?.email, orgData);
    if (!access) {
      return NextResponse.json({ error: 'Access denied' }, { status: 403 });
    }

    const authCheck = authorizeProjectMutation(access, 'phase-3');
    if (!authCheck.authorized) {
      return NextResponse.json({ error: authCheck.error }, { status: authCheck.status || 403 });
    }

    const financials = projectData.financials || {};

    // Enforce Rule 14 event-triggered gating verification
    const tenantRegistry = financials.tenantRegistry || [];
    const hasActiveLease = Array.isArray(tenantRegistry) && tenantRegistry.some((t: any) => t.status === 'active');

    const incomeLedger = financials.incomeLedger || [];
    const hasRentPayment = Array.isArray(incomeLedger) && incomeLedger.some((i: any) => i.amount > 0);

    const hasSaleContract = financials.sale_under_contract === true;

    if (!hasActiveLease && !hasRentPayment && !hasSaleContract) {
      return NextResponse.json(
        { error: 'Gating violation: Hold to Exit transition requires a verified event (active lease, rent payment, or sale under contract).' },
        { status: 400 }
      );
    }

    const userSnap = await adminDb.collection('users').doc(uid).get();
    const profile = userSnap.exists ? userSnap.data() : null;

    // 4. Update project to Phase 4 & write baseline
    const existingFinancials = projectData?.financials || {};
    const financialsUpdates = {
      ...existingFinancials,
      exit_cost_basis: costBasis,
      exit_capitalized_improvements: capitalizedImprovements,
      exit_holding_cost_total: holdingCosts,
      exit_marketing_outcome: outcome
    };

    const dealRef = adminDb.collection('projects').doc(projectId);
    await dealRef.update({
      phaseStatus: 'Phase 4: Exit',
      currentPhase: 4,
      status: 'exit',
      financials: financialsUpdates,
      updatedAt: new Date()
    });

    // 5. Send Notification to Lead Investor (ownerUid or current user)
    const recipient = projectData?.ownerUid || uid;
    const actorName = profile?.displayName || profile?.email || 'Lead Investor';
    const dealAddress = projectData?.propertyName || projectData?.address?.street || 'the project';

    try {
      await NotificationService.createNotification({
        recipientId: recipient,
        type: 'PHASE_TRANSITION',
        actor: { uid, name: actorName },
        objectReference: {
          projectId,
          dealAddress,
          phase: 'Exit'
        },
        deepLinkUrl: `/dashboard/projects/${projectId}/phase-4`
      });
    } catch (notifErr: any) {
      console.error('[AutoAdvance Notification] Failed to trigger notification:', notifErr.message);
    }

    return NextResponse.json({ success: true });
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Hold AutoAdvance POST] Error:', errMsg);
    return NextResponse.json(
      { error: 'Failed to auto-advance hold phase', details: errMsg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { FieldValue } from 'firebase-admin/firestore';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { getEmailProvider } from '@/lib/email/getEmailProvider';
import { renderEmailLayout } from '@/lib/emails/templates/BaseLayout';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; inquiryId: string }> }
) {
  const { id: projectId, inquiryId } = await params;

  try {
    // 1. Authenticate Lead Investor
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 2. Fetch Project & Verify Access
    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }

    const projectData = projectSnap.data()!;
    const isOwner = projectData.ownerUid === uid;
    let isAuthorized = isOwner;

    if (!isAuthorized && projectData.organizationId) {
      const userSnap = await adminDb.collection('users').doc(uid).get();
      if (userSnap.exists && userSnap.data()?.organizationId === projectData.organizationId) {
        isAuthorized = true;
      }
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'Access denied.' }, { status: 403 });
    }

    // 3. Parse Body
    const body = await request.json();
    const text: string = typeof body?.text === 'string' ? body.text.trim() : '';

    if (!text) {
      return NextResponse.json({ error: 'Reply text is required.' }, { status: 400 });
    }

    // 4. Retrieve & Update Inquiry Thread
    const inquiryRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('investorInquiries')
      .doc(inquiryId);

    const inquirySnap = await inquiryRef.get();
    if (!inquirySnap.exists) {
      return NextResponse.json({ error: 'Inquiry thread not found.' }, { status: 404 });
    }

    const inquiryData = inquirySnap.data()!;
    const invitationId = inquiryData.invitationId;

    // Verify invitation still exists and asker can view
    let invSnap = await adminDb.collection('dealInvitations').doc(invitationId).get();
    if (!invSnap.exists) {
      invSnap = await adminDb.collection('invitations').doc(invitationId).get();
    }

    if (!invSnap.exists) {
      return NextResponse.json({ error: 'Asker no longer has access to this deal.' }, { status: 410 });
    }

    const invData = invSnap.data()!;
    const token = invData.token;

    // Expiry check
    const expiresAt = invData.expiresAt?.toDate ? invData.expiresAt.toDate() : new Date(invData.expiresAt);
    if (expiresAt < new Date()) {
      return NextResponse.json({ error: 'Asker invitation has expired.' }, { status: 410 });
    }

    const newMessage = {
      id: `msg_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
      sender: 'leadInvestor',
      text,
      createdAt: new Date().toISOString(),
    };

    await inquiryRef.update({
      messages: FieldValue.arrayUnion(newMessage),
      status: 'answered',
      updatedAt: FieldValue.serverTimestamp(),
