import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';

export const dynamic = 'force-dynamic';

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; inquiryId: string }> }
) {
  const { id: projectId, inquiryId } = await params;

  try {
    // 1. Authenticate Lead Investor
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 2. Fetch Project & Verify Access
    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }

    const projectData = projectSnap.data()!;
    const isOwner = projectData.ownerUid === uid;
    let isAuthorized = isOwner;

    if (!isAuthorized && projectData.organizationId) {
      const userSnap = await adminDb.collection('users').doc(uid).get();
      if (userSnap.exists && userSnap.data()?.organizationId === projectData.organizationId) {
        isAuthorized = true;
      }
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'Access denied.' }, { status: 403 });
    }

    // 3. Parse Body
    const body = await request.json();
    const { isShared, status } = body;

    const inquiryRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('investorInquiries')
      .doc(inquiryId);

    const inquirySnap = await inquiryRef.get();
    if (!inquirySnap.exists) {
      return NextResponse.json({ error: 'Inquiry thread not found.' }, { status: 404 });
    }

    const inquiryData = inquirySnap.data()!;
    const oldShared = !!inquiryData.isShared;

    const update: any = {};
    if (typeof isShared === 'boolean') update.isShared = isShared;
    if (status === 'open' || status === 'answered') update.status = status;

    if (Object.keys(update).length === 0) {
      return NextResponse.json({ error: 'No updates provided.' }, { status: 400 });
    }

    const batch = adminDb.batch();
    batch.update(inquiryRef, update);

    // 4. If toggling isShared from false to true → Write QNA_SHARED Ledger event
    if (update.isShared === true && !oldShared) {
      const firstQuestion = inquiryData.message || (inquiryData.messages?.[0]?.text) || '';
      const firstAnswer = (inquiryData.messages || []).find((m: any) => m.sender === 'leadInvestor')?.text || '';

      const ledgerRef = adminDb.collection('projects').doc(projectId)
        .collection('dealLedger').doc();

      batch.set(ledgerRef, {
        id: ledgerRef.id,
        projectId,
        listingId: projectData.activeListingId || '',
        eventType: 'QNA_SHARED',
        performedBy: uid, // LeadInvestor who shared it
        timestamp: new Date().toISOString(),
        version: projectData.version || 1,
        visibilityMode: projectData.visibilityMode || 'PRIVATE',
        metadata: {
          inquiryId,
          question: firstQuestion,
          answer: firstAnswer,
        },
      });
    }

    await batch.commit();

    return NextResponse.json({ success: true });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    console.error('[Projects/Inquiries/Patch] Error:', msg);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { checkRateLimit, rateLimitResponse } from '@/lib/places/placesRateLimit';
import { FieldValue } from 'firebase-admin/firestore';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; invitationId: string }> }
) {
  const { id: projectId, invitationId } = await params;

  try {
    // 1. Authenticate Lead Investor
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 2. Fetch Project & Verify Access
    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }

    const projectData = projectSnap.data()!;
    const isOwner = projectData.ownerUid === uid;
    let isAuthorized = isOwner;

    if (!isAuthorized && projectData.organizationId) {
      const userSnap = await adminDb.collection('users').doc(uid).get();
      if (userSnap.exists && userSnap.data()?.organizationId === projectData.organizationId) {
        isAuthorized = true;
      }
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'Access denied.' }, { status: 403 });
    }

    // 3. Rate Limit
    const rateCheck = await checkRateLimit(uid, 'cardExchange');
    if (!rateCheck.allowed) {
      return rateLimitResponse(rateCheck);
    }

    // 4. Retrieve Invitation
    let invRef = adminDb.collection('dealInvitations').doc(invitationId);
    let invSnap = await invRef.get();
    if (!invSnap.exists) {
      invRef = adminDb.collection('invitations').doc(invitationId);
      invSnap = await invRef.get();
    }

    if (!invSnap.exists) {
      return NextResponse.json({ error: 'Invitation not found.' }, { status: 404 });
    }

    const invData = invSnap.data()!;
    if (invData.projectId !== projectId) {
      return NextResponse.json({ error: 'Invitation does not belong to this project.' }, { status: 400 });
    }

    if (invData.status !== 'interested' || invData.cardExchangeStatus !== 'pending') {
      return NextResponse.json({ error: 'No pending exchange request found.' }, { status: 400 });
    }

    // 5. Parse Body
    const body = await request.json();
    const { action, disclosedCard } = body;

    if (action !== 'accept' && action !== 'decline') {
      return NextResponse.json({ error: 'Action must be "accept" or "decline".' }, { status: 400 });
    }

    if (action === 'decline') {
      // Silent decline
      await invRef.update({
        cardExchangeStatus: 'declined',
      });
      return NextResponse.json({ success: true });
    }

    // accept
    if (!disclosedCard || !disclosedCard.name || !disclosedCard.email) {
      return NextResponse.json({ error: 'LeadInvestor business card details are required.' }, { status: 400 });
    }

    const inviteeCard = invData.inviteeBusinessCard;
    if (!inviteeCard || !inviteeCard.name || !inviteeCard.email) {
      return NextResponse.json({ error: 'Invitee business card details are missing.' }, { status: 400 });
    }

    const leadInvestorCard = {
      name: disclosedCard.name,
      email: disclosedCard.email,
      phone: disclosedCard.phone || '',
      company: disclosedCard.company || '',
      uid,
    };

    // Update invitation
    await invRef.update({
      cardExchangeStatus: 'accepted',
      leadInvestorBusinessCard: leadInvestorCard,
    });

    // Write Invitee's card to LeadInvestor's project files in 'Equity' folder:
    const leadInvestorFolderId = await ensureFolder(
      projectId,
      'Equity',
      projectData.organizationId || '',
      projectData.ownerUid || uid
    );

    const inviteeDocId = adminDb.collection('projectFiles').doc().id || `auto_${Math.random().toString(36).substring(2, 11)}`;
    const docInviteeRef = adminDb.collection('projectFiles').doc(inviteeDocId);
    await docInviteeRef.set({
      id: inviteeDocId,
      folderId: leadInvestorFolderId,
      projectId,
      organizationId: projectData.organizationId || '',
      name: `Business_Card_${inviteeCard.name.replace(/\s+/g, '_')}.json`,
      category: 'Business Card',
      storageUrl: `/api/projects/${projectId}/documents/${inviteeDocId}/download`,
      storagePath: `projects/${projectId}/documents/${inviteeDocId}/Business_Card_${inviteeCard.name.replace(/\s+/g, '_')}.json`,
      fileType: 'application/json',
      sizeBytes: JSON.stringify(inviteeCard).length,
      uploadedByUid: inviteeCard.uid || '',
      uploadedByEmail: inviteeCard.email || '',
      isVerified: true,
      uploadedAt: FieldValue?.serverTimestamp ? FieldValue.serverTimestamp() : new Date(),
      isControlEvidence: true,
      purpose: 'control_evidence' as const,
      phase: 'phase-1',
    });

    // Write LeadInvestor's card to Invitee's project files or contacts:
    const responderUid = inviteeCard.uid || invData.inviteeUid;
    let responderProjectId = '';
    let responderProjectData: any = null;

    if (responderUid) {
      const respProjSnap = await adminDb.collection('projects')
        .where('ownerUid', '==', responderUid)
        .where('activeListingId', '==', projectData.activeListingId || '')
        .limit(1)
        .get();

      if (!respProjSnap.empty) {
        responderProjectId = respProjSnap.docs[0].id;
        responderProjectData = respProjSnap.docs[0].data();
      }
    }

    if (responderProjectId && responderProjectData) {
      const responderFolderId = await ensureFolder(
        responderProjectId,
        'Equity',
        responderProjectData.organizationId || '',
        responderProjectData.ownerUid || responderUid
      );

      const leadInvestorDocId = adminDb.collection('projectFiles').doc().id || `auto_${Math.random().toString(36).substring(2, 11)}`;
      const docLeadInvestorRef = adminDb.collection('projectFiles').doc(leadInvestorDocId);
      await docLeadInvestorRef.set({
        id: leadInvestorDocId,
        folderId: responderFolderId,
        projectId: responderProjectId,
        organizationId: responderProjectData.organizationId || '',
        name: `Business_Card_LeadInvestor_${leadInvestorCard.name.replace(/\s+/g, '_')}.json`,
        category: 'Business Card',
        storageUrl: `/api/projects/${responderProjectId}/documents/${leadInvestorDocId}/download`,
        storagePath: `projects/${responderProjectId}/documents/${leadInvestorDocId}/Business_Card_LeadInvestor_${leadInvestorCard.name.replace(/\s+/g, '_')}.json`,
        fileType: 'application/json',
        sizeBytes: JSON.stringify(leadInvestorCard).length,
        uploadedByUid: uid,
        uploadedByEmail: leadInvestorCard.email || '',
        isVerified: true,
        uploadedAt: FieldValue?.serverTimestamp ? FieldValue.serverTimestamp() : new Date(),
        isControlEvidence: true,
        purpose: 'control_evidence' as const,
        phase: 'phase-1',
      });
    } else {
      // Fallback: Write LeadInvestor's card to Invitee's account-level contacts
      let responderOrgId = '';
      if (responderUid) {
        const respUserSnap = await adminDb.collection('users').doc(responderUid).get();
        if (respUserSnap.exists) {
          responderOrgId = respUserSnap.data()?.organizationId || '';
        }
      }

      const nameParts = (leadInvestorCard.name || '').split(/\s+/);
      const firstName = nameParts[0] || '';
      const lastName = nameParts.slice(1).join(' ') || '';

      if (responderOrgId) {
        const contactDocId = adminDb.collection('organizations').doc(responderOrgId).collection('contacts').doc().id || `contact_${Math.random().toString(36).substring(2, 11)}`;
        const orgContactRef = adminDb.collection('organizations').doc(responderOrgId).collection('contacts').doc(contactDocId);
        await orgContactRef.set({
          id: contactDocId,
          organizationId: responderOrgId,
          role: 'Other',
          firstName,
          lastName,
          email: leadInvestorCard.email,
          phone: leadInvestorCard.phone || '',
          companyName: leadInvestorCard.company || '',
          assignedProjectIds: [],
          notes: `Exchanged business card via Marketplace double opt-in on deal: ${projectData.propertyName || 'Project'}`,
          createdAt: new Date(),
          updatedAt: new Date(),
        });
      }

      if (responderUid) {
        const userContactDocId = adminDb.collection('users').doc(responderUid).collection('contacts').doc().id || `contact_${Math.random().toString(36).substring(2, 11)}`;
        const userContactRef = adminDb.collection('users').doc(responderUid).collection('contacts').doc(userContactDocId);
        await userContactRef.set({
          id: userContactDocId,
          organizationId: responderOrgId || '',
          role: 'Other',
          firstName,
          lastName,
          email: leadInvestorCard.email,
          phone: leadInvestorCard.phone || '',
          companyName: leadInvestorCard.company || '',
          assignedProjectIds: [],
          notes: `Exchanged business card via Marketplace double opt-in on deal: ${projectData.propertyName || 'Project'}`,
          createdAt: new Date(),
          updatedAt: new Date(),
        });
      }
    }

    // Commit to dealLedger timeline
    const ledgerDocId = adminDb.collection('projects').doc(projectId).collection('dealLedger').doc().id || `ledger_${Math.random().toString(36).substring(2, 11)}`;
    const ledgerRef = adminDb.collection('projects').doc(projectId).collection('dealLedger').doc(ledgerDocId);
    await ledgerRef.set({
      id: ledgerDocId,
      projectId,
      eventType: 'BUSINESS_CARD_EXCHANGED',
      performedBy: uid,
      timestamp: new Date().toISOString(),
      metadata: {
        invitationId,
        inviteeName: inviteeCard.name,
        leadInvestorName: leadInvestorCard.name,
      },
    });

    const { trackDealActivity } = require('@/lib/invitations/activityTimeline');
    await trackDealActivity(
      projectId,
      projectId,
      uid,
      'exchange',
      {
        inviteeEmail: inviteeCard.email || '',
        inviteeName: inviteeCard.name || '',
        leadInvestorName: leadInvestorCard.name || '',
      }
    ).catch((e: any) => console.error('Failed to log exchange event:', e));

    return NextResponse.json({ success: true });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    console.error('[CardExchange/API] Error:', msg);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

async function ensureFolder(
  projectId: string,
  folderName: string,
  organizationId: string,
  ownerUid: string
): Promise<string> {
  const foldersColl = adminDb.collection('projectFolders');
  const snap = await foldersColl
    .where('projectId', '==', projectId)
    .where('name', '==', folderName)
    .limit(1)
    .get();

  if (!snap.empty) {
    return snap.docs[0].id;
  }

  const folderId = foldersColl.doc().id || `folder_${Math.random().toString(36).substring(2, 11)}`;
  const folderRef = foldersColl.doc(folderId);
  await folderRef.set({
    id: folderId,
    projectId,
    organizationId,
    name: folderName,
    phase: folderName,
    ownerUid,
    fileCount: 0,
    createdAt: FieldValue?.serverTimestamp ? FieldValue.serverTimestamp() : new Date(),
  });

  return folderId;
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';

export const dynamic = 'force-dynamic';

async function verifyProjectMembership(projectId: string, uid: string) {
  const snap = await adminDb.collection('projects').doc(projectId).get();
  if (!snap.exists) return null;
  const data = snap.data()!;
  const isOwner = data.ownerUid === uid;
  const isMember = !!data.members?.[uid] || data.teamMemberIds?.includes(uid);
  const isOrgMember = data.organizationId
    ? await adminDb.collection('organizations').doc(data.organizationId).get().then((o) => {
        if (!o.exists) return false;
        const od = o.data()!;
        return od.ownerUid === uid || od.teamMembers?.some((m: any) => m.id === uid && m.status === 'active');
      })
    : false;
  if (!isOwner && !isMember && !isOrgMember) return null;
  return data;
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; itemId: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId, itemId } = await params;

    const project = await verifyProjectMembership(projectId, uid);
    if (!project) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const itemRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('lenderPackage')
      .doc(itemId);

    const itemSnap = await itemRef.get();
    if (!itemSnap.exists) {
      return NextResponse.json({ error: 'Checklist item not found' }, { status: 404 });
    }

    const body = await request.json();
    const updateData: any = {};

    if ('reminderCadence' in body) {
      const val = body.reminderCadence;
      if (val !== 'daily' && val !== 'weekly' && val !== 'none') {
        return NextResponse.json({ error: 'Invalid reminder cadence' }, { status: 400 });
      }
      updateData.reminderCadence = val;
    }

    if ('status' in body) {
      const val = body.status;
      if (val !== 'Pending' && val !== 'Uploaded') {
        return NextResponse.json({ error: 'Invalid status' }, { status: 400 });
      }
      updateData.status = val;
    }

    if ('fileId' in body) updateData.fileId = body.fileId;
    if ('fileName' in body) updateData.fileName = body.fileName;
    if ('fileUrl' in body) updateData.fileUrl = body.fileUrl;

    if (Object.keys(updateData).length === 0) {
      return NextResponse.json({ error: 'No update data provided' }, { status: 400 });
    }

    await itemRef.update(updateData);

    const updatedSnap = await itemRef.get();
    return NextResponse.json({ item: { id: itemId, ...updatedSnap.data() } });
  } catch (err: any) {
    console.error('[Lender Package Item PATCH]', err.message);
    return NextResponse.json({ error: 'Failed to update checklist item' }, { status: 500 });
  }
}

export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string; itemId: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId, itemId } = await params;

    const project = await verifyProjectMembership(projectId, uid);
    if (!project) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const itemRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('lenderPackage')
      .doc(itemId);

    const itemSnap = await itemRef.get();
    if (!itemSnap.exists) {
      return NextResponse.json({ error: 'Checklist item not found' }, { status: 404 });
    }

    await itemRef.delete();

    return NextResponse.json({ success: true, message: 'Checklist item deleted.' });
  } catch (err: any) {
    console.error('[Lender Package Item DELETE]', err.message);
    return NextResponse.json({ error: 'Failed to delete checklist item' }, { status: 500 });
  }
}

