import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';

export const dynamic = 'force-dynamic';

/**
 * PATCH /api/projects/[id]/loans/hard-money-terms
 *
 * Configures Hard Money or Bridge loan terms on the route's existing loan record.
 * Reads dispositionType from the project — never re-asks it.
 *
 * Guarded: updates only the identified loan doc fields; never touches
 * other subcollection documents or unrelated financials fields.
 */

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, auth.token?.email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    // Only Lead Investors can configure loan terms
    if (access.role !== 'Lead Investor') {
      return NextResponse.json({ error: 'Forbidden: only Lead Investors can configure loan terms' }, { status: 403 });
    }

    const project = access.project;

    const body = await request.json();
    const {
      loanId,
      arvCents,
      arvSource,
      interestRate,
      termMonths,
      points,
      interestOnly,
      amountCents,
    } = body;

    // ── Validation ───────────────────────────────────────────────────────
    if (!loanId || typeof loanId !== 'string') {
      return NextResponse.json({ error: 'loanId is required' }, { status: 422 });
    }

    // Fetch the specific loan doc
    const loanRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('loans')
      .doc(loanId);
    const loanSnap = await loanRef.get();

    if (!loanSnap.exists) {
      return NextResponse.json({ error: 'Loan record not found' }, { status: 404 });
    }

    const existingLoan = loanSnap.data()!;
    const instrument = existingLoan.instrument;

    if (instrument !== 'Hard Money' && instrument !== 'Bridge') {
      return NextResponse.json(
        { error: 'This endpoint only accepts Hard Money or Bridge loan records' },
        { status: 422 }
      );
    }

    if (arvCents != null && (typeof arvCents !== 'number' || arvCents < 0)) {
      return NextResponse.json({ error: 'arvCents must be a non-negative number' }, { status: 422 });
    }

    if (arvSource != null && !['user_assumption', 'arv_appraisal'].includes(arvSource)) {
      return NextResponse.json(
        { error: 'arvSource must be user_assumption or arv_appraisal' },
        { status: 422 }
      );
    }

    if (interestRate != null && (typeof interestRate !== 'number' || interestRate < 0 || interestRate > 100)) {
      return NextResponse.json({ error: 'interestRate must be 0-100' }, { status: 422 });
    }

    if (termMonths != null && (typeof termMonths !== 'number' || termMonths < 1 || termMonths > 360)) {
      return NextResponse.json({ error: 'termMonths must be 1-360' }, { status: 422 });
    }

    if (points != null && (typeof points !== 'number' || points < 0 || points > 20)) {
      return NextResponse.json({ error: 'points must be 0-20' }, { status: 422 });
    }

    if (amountCents != null && (typeof amountCents !== 'number' || amountCents < 0)) {
      return NextResponse.json({ error: 'amountCents must be a non-negative number' }, { status: 422 });
    }

    // ── Read dispositionType from project — never re-ask ─────────────────
    const exitPlan = project.dispositionType || null; // 'SALE' | 'LEASE' | 'RENT' | null

    // ── Compute LTARV % ──────────────────────────────────────────────────
    const finalAmountCents = amountCents ?? existingLoan.amountCents ?? 0;
    const finalArvCents = arvCents ?? existingLoan.arvCents ?? 0;
    const ltarvPercent =
      finalArvCents > 0
        ? parseFloat(((finalAmountCents / finalArvCents) * 100).toFixed(2))
        : null;

    // ── Compute debt service via shared amortization utility ──────────────
    const finalRate = interestRate ?? existingLoan.interestRate ?? 0;
    const finalTermMonths = termMonths ?? existingLoan.termMonths ?? 12;
    const isIO = interestOnly ?? existingLoan.interestOnly ?? false;
    const amtDollars = finalAmountCents / 100;

    const amort = calculateAmortization(amtDollars, finalRate, finalTermMonths, isIO);

    // ── Build update payload (guarded — only touch loan doc fields) ───────
    const now = new Date().toISOString();
    const update: Record<string, any> = {
      exitPlan,
      interestOnly: isIO,
      ltarvPercent,
      updatedAt: now,
    };

    if (arvCents != null) update.arvCents = arvCents;
    if (arvSource != null) update.arvSource = arvSource;
    if (interestRate != null) update.interestRate = interestRate;
    if (termMonths != null) update.termMonths = termMonths;
    if (points != null) update.points = points;
    if (amountCents != null) update.amountCents = amountCents;

    await loanRef.update(update);

    // ── Set compressed timeline template on project financials ────────────
    const currentFinancials = project.financials || {};
    const financialUpdates: Record<string, any> = {
      'financials.timelineTemplate': 'compressed',
    };

    // Write annual debt service so locked terms can pick it up
    financialUpdates['financials.annualDebtService'] = parseFloat(amort.annualDebtService.toFixed(2));

    await adminDb.collection('projects').doc(projectId).update(financialUpdates);

    // ── Timeline + Notification ──────────────────────────────────────────
    await writeActivityLog(
      projectId,
      uid,
      [{
        fieldPath: `loans.${loanId}.termMonths`,
        oldValue: existingLoan.termMonths || null,
        newValue: finalTermMonths,
      }],
      'manual'
    );

    const dealAddress = project.propertyName || project.address?.street || 'the project';
    try {
      const actorName = auth.token.name || auth.token.email || 'A teammate';
      const recipient = project.ownerUid || uid;

      if (typeof NotificationService.broadcastProjectNotification === 'function') {
        await NotificationService.broadcastProjectNotification(projectId, {
          type: 'LOAN_STATUS_UPDATE',
          actor: { uid, name: actorName },
          objectReference: {
            projectId,
            dealAddress,
            task: `${instrument} terms configured: ${finalRate}% ${isIO ? 'I/O' : 'amort'}, ${finalTermMonths}mo`,
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`,
        });
      } else {
        await NotificationService.createNotification({
          recipientId: recipient,
          type: 'LOAN_STATUS_UPDATE',
          actor: { uid, name: actorName },
          objectReference: {
            projectId,
            dealAddress,
            task: `${instrument} terms configured: ${finalRate}% ${isIO ? 'I/O' : 'amort'}, ${finalTermMonths}mo`,
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`,
        });
      }
    } catch (err: any) {
      console.error('Failed to trigger hard money terms notification:', err.message);
    }

    return NextResponse.json({
      success: true,
      loan: {
        id: loanId,
        instrument,
        amountCents: finalAmountCents,
        arvCents: finalArvCents,
        ltarvPercent,
        interestRate: finalRate,
        termMonths: finalTermMonths,
        points: points ?? existingLoan.points ?? 0,
        interestOnly: isIO,
        exitPlan,
      },
      debtService: {
        monthlyPayment: parseFloat(amort.monthlyPayment.toFixed(2)),
        annualDebtService: parseFloat(amort.annualDebtService.toFixed(2)),
        firstYearInterest: parseFloat(amort.firstYearInterest.toFixed(2)),
        firstYearPrincipal: parseFloat(amort.firstYearPrincipal.toFixed(2)),
      },
    });
  } catch (err: any) {
    console.error('[Hard Money Terms API]', err.message);
    return NextResponse.json({ error: 'Failed to configure hard money terms' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { writeActivityLog } from '@/lib/firebase/activityLogWriter';
import { NotificationService } from '@/lib/services/notificationService';
import { calculateAmortization } from '@/lib/utils/reiCalculators';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';

export const dynamic = 'force-dynamic';

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, auth.token?.email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    // Only Lead Investors can lock terms
    if (access.role !== 'Lead Investor') {
      return NextResponse.json({ error: 'Forbidden: only Lead Investors can lock terms' }, { status: 403 });
    }

    const project = access.project;

    const loansSnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('loans')
      .get();

    const loans = loansSnap.docs.map((d) => ({
      id: d.id,
      ...d.data()
    })) as any[];

    if (loans.length === 0) {
      return NextResponse.json({ error: 'No active loans found to lock.' }, { status: 400 });
    }

    let totalAmountCents = 0;
    let totalAnnualDebtService = 0;
    let interestProductSum = 0;
    let termProductSum = 0;
    let pointsProductSum = 0;

    for (const loan of loans) {
      const amtCents = loan.amountCents || 0;
      totalAmountCents += amtCents;

      // Amortization output is in dollars
      const amtDollars = amtCents / 100;
      const rate = loan.interestRate || 0;
      const termMonths = loan.termMonths || 360;
      const points = loan.points || 0;

      const amort = calculateAmortization(amtDollars, rate, termMonths);
      totalAnnualDebtService += amort.annualDebtService;

      interestProductSum += rate * amtCents;
      termProductSum += (termMonths / 12) * amtCents;
      pointsProductSum += points * amtCents;
    }

    if (totalAmountCents === 0) {
      return NextResponse.json({ error: 'Configure loan amounts before locking terms.' }, { status: 400 });
    }

    const finalAmount = totalAmountCents / 100;
    const finalRate = parseFloat((interestProductSum / totalAmountCents).toFixed(4));
    const finalTermYears = parseFloat((termProductSum / totalAmountCents).toFixed(4));
    const finalPoints = parseFloat((pointsProductSum / totalAmountCents).toFixed(4));
    const finalAnnualDebtService = parseFloat(totalAnnualDebtService.toFixed(2));

    const currentFinancials = project.financials || {};
    const oldAmount = currentFinancials.loanAmount || 0;

    const activeLoan = loans[0];
    const sourceTags = {
      ...(currentFinancials.sourceTags || {}),
      loan_amount: activeLoan?.sourceTags?.amountCents || (activeLoan?.fileId ? 'document' : 'manual'),
      loan_interest_rate: activeLoan?.sourceTags?.interestRate || (activeLoan?.fileId ? 'document' : 'manual'),
      loan_term: activeLoan?.sourceTags?.termMonths || (activeLoan?.fileId ? 'document' : 'manual'),
      loanOriginationPoints: activeLoan?.sourceTags?.points || (activeLoan?.fileId ? 'document' : 'manual'),
    };

    const updatedFinancials = {
      ...currentFinancials,
      loanAmount: finalAmount,
      loanInterestRate: finalRate,
      loanTermYears: finalTermYears,
      loanOriginationPoints: finalPoints,
      annualDebtService: finalAnnualDebtService,
      sourceTags
    };

    await adminDb.collection('projects').doc(projectId).update({
      financials: updatedFinancials,
      termsLocked: true,
      termsLockedAt: new Date().toISOString(),
      termsLockedBy: uid
    });

    // Write to timeline activityLog
    await writeActivityLog(
      projectId,
      uid,
      [{
        fieldPath: 'financials.loanAmount',
        oldValue: oldAmount,
        newValue: finalAmount
      }],
      'manual'
    );

    // Fire notification to project members
    const dealAddress = project.propertyName || project.address?.street || 'the project';
    try {
      const actorName = auth.token.name || auth.token.email || 'A teammate';
      const recipient = project.ownerUid || uid;

      if (typeof NotificationService.broadcastProjectNotification === 'function') {
        await NotificationService.broadcastProjectNotification(projectId, {
          type: 'LOAN_STATUS_UPDATE',
          actor: { uid, name: actorName },
          objectReference: {
            projectId,
            dealAddress,
            task: `Locked loan terms: $${finalAmount.toLocaleString()} at ${finalRate}%`
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`
        });
      } else {
        await NotificationService.createNotification({
          recipientId: recipient,
          type: 'LOAN_STATUS_UPDATE',
          actor: { uid, name: actorName },
          objectReference: {
            projectId,
            dealAddress,
            task: `Locked loan terms: $${finalAmount.toLocaleString()} at ${finalRate}%`
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`
        });
      }
    } catch (err: any) {
      console.error('Failed to trigger lock terms notification:', err.message);
    }

    return NextResponse.json({
      success: true,
      lockedTerms: {
        loanAmount: finalAmount,
        loanInterestRate: finalRate,
        loanTermYears: finalTermYears,
        loanOriginationPoints: finalPoints,
        annualDebtService: finalAnnualDebtService
      }
    });
  } catch (err: any) {
    console.error('[Lock Terms API]', err.message);
    return NextResponse.json({ error: 'Failed to lock terms' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { telemetry } from '@/lib/telemetry';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';

export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, auth.token.email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const loansSnap = await adminDb
      .collection('projects')
      .doc(projectId)
      .collection('loans')
      .orderBy('createdAt', 'asc')
      .get();

    const loans = loansSnap.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));

    return NextResponse.json({ loans });
  } catch (err: any) {
    console.error('[Loans GET]', err.message);
    return NextResponse.json({ error: 'Failed to fetch loans' }, { status: 500 });
  }
}

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, auth.token?.email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    // Only Lead Investors can select/reset financing routes
    if (access.role !== 'Lead Investor') {
      return NextResponse.json({ error: 'Forbidden: only Lead Investors can select financing routes' }, { status: 403 });
    }

    const project = access.project;

    const body = await request.json();
    const { instrument, instruments, reset = false } = body;

    const projectRef = adminDb.collection('projects').doc(projectId);
    const loansColl = projectRef.collection('loans');

    // 1. Clear any existing loan records first
    const existingSnap = await loansColl.get();
    const batch = adminDb.batch();
    existingSnap.docs.forEach((doc) => {
      batch.delete(doc.ref);
    });
    await batch.commit();

    // 2. Handle Reset / All Cash
    if (reset || (!instrument && (!instruments || (Array.isArray(instruments) && instruments.length === 0)))) {
      const updateData: any = {
        'financials.financingType': 'All Cash',
        loanStatus: FieldValue.delete(),
      };
      if (project.fundingPlan?.modality) {
        const currentModality: string[] = project.fundingPlan.modality || [];
        const nextModality = currentModality.filter(m => m !== 'conventional_loan' && m !== 'hard_money' && m !== 'bridge' && m !== 'sba_504_bank' && m !== 'sba_504_cdc');
        updateData['fundingPlan.modality'] = nextModality;
      }

      await projectRef.update(updateData);

      try {
        await telemetry.capture({
          distinctId: uid,
          event: 'financing_route_reset',
          properties: { projectId, timestamp: new Date().toISOString() }
        });
      } catch {}

      return NextResponse.json({ success: true, message: 'Financing route reset to All Cash.' });
    }

    // Normalize to array of selected instruments
    let selectedInstruments: string[] = [];
    if (Array.isArray(instruments)) {
      selectedInstruments = instruments;
    } else if (typeof instrument === 'string' && instrument) {
      selectedInstruments = [instrument];
    }

    // Validate selected instruments
    const VALID_INSTRUMENTS = ['Conventional', 'Hard Money', 'Bridge', 'SBA 504'];
    for (const inst of selectedInstruments) {
      if (!VALID_INSTRUMENTS.includes(inst)) {
        return NextResponse.json({ error: `instrument must be one of: ${VALID_INSTRUMENTS.join(', ')}` }, { status: 422 });
      }
    }

    // 3. Create new loan record(s) sequentially (so mock subDoc.set works in Jest)
    const newLoans: any[] = [];

    for (const inst of selectedInstruments) {
      if (inst === 'SBA 504') {
        const docRef1 = loansColl.doc();
        const doc1 = {
          id: docRef1.id,
          projectId,
          instrument: inst,
          lenderName: 'SBA 504 First Lien Bank',
          amountCents: 0,
          interestRate: 0,
          termMonths: 120,
          points: 0,
          status: 'Application-Submitted',
          notes: 'Bank 50% First Lien Loan',
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };
        await docRef1.set(doc1);
        newLoans.push(doc1);

        const docRef2 = loansColl.doc();
        const doc2 = {
          id: docRef2.id,
          projectId,
          instrument: inst,
          lenderName: 'CDC Debenture Second Lien',
          amountCents: 0,
          interestRate: 0,
          termMonths: 240,
          points: 0,
          status: 'Application-Submitted',
          notes: 'CDC 35-40% Debenture Second Lien',
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };
        await docRef2.set(doc2);
        newLoans.push(doc2);
      } else {
        const docRef = loansColl.doc();
        const doc = {
          id: docRef.id,
          projectId,
          instrument: inst,
          lenderName: `${inst} Lender`,
          amountCents: 0,
          interestRate: 0,
          termMonths: inst === 'Conventional' ? 360 : 12,
          points: 0,
          status: 'Application-Submitted',
          notes: `${inst} loan record`,
          createdAt: new Date().toISOString(),
          updatedAt: new Date().toISOString(),
        };
        await docRef.set(doc);
        newLoans.push(doc);
      }
    }

    // 4. Update project modality / financingType
    const updateData: any = {
      'financials.financingType': 'Financed',
      loanStatus: 'Application-Submitted',
    };

    if (project.fundingPlan?.modality) {
      const currentModality: string[] = project.fundingPlan.modality || [];
      const nextModality = currentModality.filter(m => m !== 'conventional_loan' && m !== 'hard_money' && m !== 'bridge' && m !== 'sba_504_bank' && m !== 'sba_504_cdc');

      if (selectedInstruments.includes('Conventional')) nextModality.push('conventional_loan');
      if (selectedInstruments.includes('Hard Money')) nextModality.push('hard_money');
      if (selectedInstruments.includes('Bridge')) nextModality.push('bridge');
      if (selectedInstruments.includes('SBA 504')) {
        nextModality.push('sba_504_bank');
        nextModality.push('sba_504_cdc');
      }
      updateData['fundingPlan.modality'] = nextModality;
    }

    await projectRef.update(updateData);

    try {
      await telemetry.capture({
        distinctId: uid,
        event: 'financing_route_selected',
        properties: { projectId, instruments: selectedInstruments, timestamp: new Date().toISOString() }
      });
    } catch {}

    return NextResponse.json({ success: true, loans: newLoans }, { status: 201 });
  } catch (err: any) {
    console.error('[Loans POST]', err.message);
    return NextResponse.json({ error: 'Failed to configure financing route' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { writeActivityLog } from '@/lib/firebase/activityLogWriter';
import { NotificationService } from '@/lib/services/notificationService';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';

export const dynamic = 'force-dynamic';

/**
 * POST /api/projects/[id]/loans/sba504
 *
 * Records SBA 504 eligibility inputs and applies the FX-7 structure:
 *   Bank 50% First Lien + CDC Debenture + Borrower Equity Injection = 100%.
 *
 * Guarded reconciliation:
 *   - Updates existing Bank and CDC loan records in the `loans` subcollection
 *     (identified by lenderName) — never deletes unrelated records.
 *   - Upserts the borrower injection into `financials.capitalStack` without
 *     overwriting other equity sources.
 */

const VALID_OCCUPANCY_TYPES = ['existing', 'new_construction'] as const;
const VALID_INJECTION_TIERS = [10, 15, 20] as const;

export async function POST(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, auth.token?.email);
    if (!access) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    // Only Lead Investors can configure SBA 504 structure
    if (access.role !== 'Lead Investor') {
      return NextResponse.json({ error: 'Forbidden: only Lead Investors can configure SBA 504 structure' }, { status: 403 });
    }

    const project = access.project;

    const body = await request.json();
    const {
      occupancyType,
      occupancyRate,
      occupancyRateTenYears,
      paydexScore,
      paydexSource,
      sbssScore,
      sbssSource,
      intelliscoreScore,
      intelliscoreSource,
      injectionTier,
    } = body;

    // ── Validation ───────────────────────────────────────────────────────
    if (!occupancyType || !VALID_OCCUPANCY_TYPES.includes(occupancyType)) {
      return NextResponse.json(
        { error: `occupancyType must be one of: ${VALID_OCCUPANCY_TYPES.join(', ')}` },
        { status: 422 }
      );
    }

    if (occupancyRate == null || typeof occupancyRate !== 'number' || occupancyRate < 0 || occupancyRate > 100) {
      return NextResponse.json(
        { error: 'occupancyRate must be a number between 0 and 100' },
        { status: 422 }
      );
    }

    if (occupancyType === 'new_construction') {
      if (occupancyRateTenYears == null || typeof occupancyRateTenYears !== 'number' || occupancyRateTenYears < 0 || occupancyRateTenYears > 100) {
        return NextResponse.json(
          { error: 'occupancyRateTenYears is required for new_construction and must be 0-100' },
          { status: 422 }
        );
      }
    }

    if (!injectionTier || !VALID_INJECTION_TIERS.includes(injectionTier)) {
      return NextResponse.json(
        { error: `injectionTier must be one of: ${VALID_INJECTION_TIERS.join(', ')}` },
        { status: 422 }
      );
    }

    // ── FX-7 Structure Calculation ───────────────────────────────────────
    const purchasePrice = project.financials?.purchasePrice || 0;
    if (purchasePrice <= 0) {
      return NextResponse.json(
        { error: 'Purchase price must be set before configuring SBA 504 structure.' },
        { status: 400 }
      );
    }

    const bankPct = 50;
    const injectionPct = injectionTier as number;
    const cdcPct = 100 - bankPct - injectionPct; // 40%, 35%, or 30%

    const bankAmountCents = Math.round(purchasePrice * (bankPct / 100) * 100);
    const cdcAmountCents = Math.round(purchasePrice * (cdcPct / 100) * 100);
    const injectionAmountCents = Math.round(purchasePrice * (injectionPct / 100) * 100);

    // ── Guarded Loan Record Updates ──────────────────────────────────────
    const loansColl = adminDb.collection('projects').doc(projectId).collection('loans');
    const loansSnap = await loansColl.get();

    let bankDocRef: FirebaseFirestore.DocumentReference | null = null;
    let cdcDocRef: FirebaseFirestore.DocumentReference | null = null;

    for (const doc of loansSnap.docs) {
      const data = doc.data();
      if (data.lenderName === 'SBA 504 First Lien Bank') {
        bankDocRef = doc.ref;
      } else if (data.lenderName === 'CDC Debenture Second Lien') {
        cdcDocRef = doc.ref;
      }
    }

    const now = new Date().toISOString();

    if (bankDocRef) {
      await bankDocRef.update({
        amountCents: bankAmountCents,
        notes: `Bank 50% First Lien Loan — $${(bankAmountCents / 100).toLocaleString()}`,
        updatedAt: now,
      });
    }

    if (cdcDocRef) {
      await cdcDocRef.update({
        amountCents: cdcAmountCents,
        notes: `CDC ${cdcPct}% Debenture Second Lien — $${(cdcAmountCents / 100).toLocaleString()}`,
        updatedAt: now,
      });
    }

    // ── Guarded Capital Stack Update (Borrower Injection) ────────────────
    const currentFinancials = project.financials || {};
    const existingStack: any[] = currentFinancials.capitalStack || [];

    const INJECTION_SOURCE_ID = 'sba504-borrower-injection';
    const injectionSource = {
      id: INJECTION_SOURCE_ID,
      category: 'Borrower Equity',
      amount: injectionAmountCents / 100,
      interestRate: 0,
      lenderName: 'Borrower Equity Injection (SBA 504)',
      status: 'Active',
      notes: `${injectionPct}% borrower injection — SBA 504 requirement`,
    };

    // Replace existing injection entry or append — never touch other sources
    const stackIdx = existingStack.findIndex((s: any) => s.id === INJECTION_SOURCE_ID);
    const updatedStack = [...existingStack];
    if (stackIdx >= 0) {
      updatedStack[stackIdx] = injectionSource;
    } else {
      updatedStack.push(injectionSource);
    }

    // ── Save Eligibility + Vendor Slots to Financials ────────────────────
    const sbaFields: Record<string, any> = {
      'financials.sbaOccupancyType': occupancyType,
      'financials.sbaOccupancyRate': occupancyRate,
      'financials.sbaInjectionTier': injectionTier,
      'financials.capitalStack': updatedStack,
    };

    if (occupancyType === 'new_construction') {
      sbaFields['financials.sbaOccupancyRateTenYears'] = occupancyRateTenYears;
    }

    // Credit scores — store only if provided
    if (paydexScore != null) {
      sbaFields['financials.sbaPaydexScore'] = paydexScore;
      sbaFields['financials.sbaPaydexSource'] = paydexSource || null;
    }
    if (sbssScore != null) {
      sbaFields['financials.sbaSbssScore'] = sbssScore;
      sbaFields['financials.sbaSbssSource'] = sbssSource || null;
    }
    if (intelliscoreScore != null) {
      sbaFields['financials.sbaIntelliscoreScore'] = intelliscoreScore;
      sbaFields['financials.sbaIntelliscoreSource'] = intelliscoreSource || null;
    }

    await adminDb.collection('projects').doc(projectId).update(sbaFields);

    // ── Timeline + Notification ──────────────────────────────────────────
    await writeActivityLog(
      projectId,
      uid,
      [{
        fieldPath: 'financials.sbaInjectionTier',
        oldValue: currentFinancials.sbaInjectionTier || null,
        newValue: injectionTier,
      }],
      'manual'
    );

    const dealAddress = project.propertyName || project.address?.street || 'the project';
    try {
      const actorName = auth.token.name || auth.token.email || 'A teammate';
      const recipient = project.ownerUid || uid;

      if (typeof NotificationService.broadcastProjectNotification === 'function') {
        await NotificationService.broadcastProjectNotification(projectId, {
          type: 'LOAN_STATUS_UPDATE',
          actor: { uid, name: actorName },
          objectReference: {
            projectId,
            dealAddress,
            task: `SBA 504 structure configured: ${bankPct}/${cdcPct}/${injectionPct} on $${purchasePrice.toLocaleString()}`,
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`,
        });
      } else {
        await NotificationService.createNotification({
          recipientId: recipient,
          type: 'LOAN_STATUS_UPDATE',
          actor: { uid, name: actorName },
          objectReference: {
            projectId,
            dealAddress,
            task: `SBA 504 structure configured: ${bankPct}/${cdcPct}/${injectionPct} on $${purchasePrice.toLocaleString()}`,
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`,
        });
      }
    } catch (err: any) {
      console.error('Failed to trigger SBA 504 notification:', err.message);
    }

    return NextResponse.json({
      success: true,
      structure: {
        bankPct,
        cdcPct,
        injectionPct,
        bankAmountCents,
        cdcAmountCents,
        injectionAmountCents,
        purchasePrice,
      },
    });
  } catch (err: any) {
    console.error('[SBA 504 API]', err.message);
    return NextResponse.json({ error: 'Failed to configure SBA 504 structure' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import type { ProofOfFundsStatus, ProofOfFundsStatusLog } from '@/types/schema';
import { getBankingProvider } from '@/lib/banking';
import { decryptToken } from '@/lib/encryption/tokenVault';

interface Params { params: Promise<{ id: string }> }

export async function POST(req: NextRequest, { params }: Params) {
  // ── 1. Authenticate Caller ────────────────────────────────
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;
  const { uid } = auth;

  const { id: projectId } = await params;
  if (!projectId) {
    return NextResponse.json({ success: false, error: 'projectId is required' }, { status: 400 });
  }

  let body: {
    sourceId: string;
    action: 'request' | 'upload' | 'verify' | 'plaid_sync';
    documentId?: string | null;
    documentName?: string | null;
    documentUrl?: string | null;
    plaidAccountName?: string | null;
    plaidBalance?: number | null;
  };

  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  const { sourceId, action, documentId, documentName, documentUrl, plaidAccountName, plaidBalance } = body;

  if (!sourceId && action !== 'plaid_sync') {
    return NextResponse.json({ success: false, error: 'sourceId is required' }, { status: 400 });
  }

  // ── 2. Load Project & Verify Access ────────────────────────
  const projectRef = adminDb.collection('projects').doc(projectId);
  const projectSnap = await projectRef.get();
  if (!projectSnap.exists) {
    return NextResponse.json({ success: false, error: 'Project not found' }, { status: 404 });
  }
  const projectData = projectSnap.data()!;
  const orgId = projectData.organizationId;

  const userSnap = await adminDb.collection('users').doc(uid).get();
  if (!userSnap.exists) {
    return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
  }
  const profile = userSnap.data()!;

  // Project access check helper
  const hasAccess =
    profile.personalOrganizationId === orgId ||
    profile.organizationId === orgId ||
    (profile.memberships != null && Boolean(profile.memberships[orgId]));

  if (!hasAccess) {
    return NextResponse.json({ success: false, error: 'Access denied' }, { status: 403 });
  }

  // ── 3. Check Lead Investor Authorization ───────────────────
  const isLead =
    projectData.ownerUid === uid ||
    projectData.members?.[uid]?.role === 'Lead Investor';

  // ── 4. Initialize Equity Sources list if empty ─────────────
  let proofOfFunds: ProofOfFundsStatus[] = projectData.proofOfFunds || [];

  const capitalStack = projectData.financials?.capitalStack || [];
  const equitySources = capitalStack.filter((s: any) =>
    s.category === 'Borrower Injection' ||
    s.category === 'Co-buying Equity' ||
    s.category === 'Syndication Equity'
  );

  // If no equity sources exist in capitalStack, fallback to a default solo cash source
  if (equitySources.length === 0) {
    const defaultId = 'default_solo_equity';
    if (!proofOfFunds.some((pof) => pof.id === defaultId)) {
      proofOfFunds.push({
        id: defaultId,
        sourceName: 'Borrower Injection (Solo Cash)',
        amount: projectData.financials?.purchasePrice || 0,
        status: 'requested',
        history: [{
          status: 'requested',
          updatedAt: new Date().toISOString(),
          updatedByUid: 'system',
          updatedByName: 'System Initialization',
        }],
      });
    }
  } else {
    // Populate missing items in proofOfFunds from capitalStack
    for (const source of equitySources) {
      if (!proofOfFunds.some((pof) => pof.id === source.id)) {
        proofOfFunds.push({
          id: source.id,
          sourceName: source.category,
          amount: source.amount || 0,
          status: 'requested',
          history: [{
            status: 'requested',
            updatedAt: new Date().toISOString(),
            updatedByUid: 'system',
            updatedByName: 'System Initialization',
          }],
        });
      }
    }
  }

  // ── 5. Perform Action ─────────────────────────────────────
  const now = new Date().toISOString();
  const userName = profile.name || profile.email || uid;

  if (action === 'plaid_sync') {
    const bankingProvider = getBankingProvider();
    let accountName = plaidAccountName || 'Business Premier Savings (*8892)';
    let balance = plaidBalance !== undefined && plaidBalance !== null ? plaidBalance : 75000_00;

    if (process.env.BANKING_PROVIDER === 'plaid') {
      const connectionsSnap = await adminDb
        .collection('users')
        .doc(uid)
        .collection('bankConnections')
        .orderBy('createdAt', 'desc')
        .limit(1)
        .get();

      if (connectionsSnap.empty) {
        return NextResponse.json({
          success: false,
          error: 'No linked bank accounts found. Please link your bank account first.',
        }, { status: 400 });
      }

      const connectionDoc = connectionsSnap.docs[0].data();
      const encryptedAccessToken = connectionDoc.accessToken;
      if (!encryptedAccessToken) {
        return NextResponse.json({
          success: false,
          error: 'Bank connection is invalid. Please relink your bank account.',
        }, { status: 400 });
      }

      try {
        const decryptedAccessToken = decryptToken(encryptedAccessToken);
        const plaidBalanceInfo = await bankingProvider.getAccountBalance(decryptedAccessToken);
        accountName = plaidBalanceInfo.accountName;
        balance = plaidBalanceInfo.balance;
      } catch (err: any) {
        console.error('[Plaid Sync Action] Failed to fetch real Plaid balance:', err);
        return NextResponse.json({
          success: false,
          error: `Failed to fetch Plaid balance: ${err.message}`,
        }, { status: 500 });
      }
    }

    const targetPoF = proofOfFunds.find((p) => p.id === sourceId) || proofOfFunds[0];
    if (targetPoF) {
      targetPoF.plaidAccountName = accountName;
      targetPoF.plaidBalance = balance;
      targetPoF.plaidLastSync = now;
    }
  } else {
    const targetPoF = proofOfFunds.find((p) => p.id === sourceId);
    if (!targetPoF) {
      return NextResponse.json({ success: false, error: 'Equity source not found' }, { status: 404 });
    }

    if (action === 'request') {
      targetPoF.status = 'requested';
      targetPoF.documentId = null;
      targetPoF.documentName = null;
      targetPoF.documentUrl = null;
      targetPoF.verifiedByUid = null;
      targetPoF.verifiedByName = null;
      targetPoF.verifiedAt = null;

      targetPoF.history.push({
        status: 'requested',
        updatedAt: now,
        updatedByUid: uid,
        updatedByName: userName,
      });
    } else if (action === 'upload') {
      if (!documentUrl) {
        return NextResponse.json({ success: false, error: 'documentUrl is required for upload action' }, { status: 400 });
      }
      targetPoF.status = 'received';
      targetPoF.documentId = documentId || crypto.randomUUID();
      targetPoF.documentName = documentName || 'proof_of_funds.pdf';
      targetPoF.documentUrl = documentUrl;
      targetPoF.verifiedByUid = null;
      targetPoF.verifiedByName = null;
      targetPoF.verifiedAt = null;

      targetPoF.history.push({
        status: 'received',
        updatedAt: now,
        updatedByUid: uid,
        updatedByName: userName,
      });
    } else if (action === 'verify') {
      // ONLY Lead Investor is authorized to verify
      if (!isLead) {
        return NextResponse.json({ success: false, error: 'Unauthorized. Only the Lead Investor can verify proof of funds.' }, { status: 403 });
      }

      targetPoF.status = 'verified';
      targetPoF.verifiedByUid = uid;
      targetPoF.verifiedByName = userName;
      targetPoF.verifiedAt = now;

      targetPoF.history.push({
        status: 'verified',
        updatedAt: now,
        updatedByUid: uid,
        updatedByName: userName,
      });
    }
  }

  // ── 6. Sync card F1.4 complete state ───────────────────────
  // card F1.4 is complete if all items in proofOfFunds are verified
  const allVerified = proofOfFunds.length > 0 && proofOfFunds.every((pof) => pof.status === 'verified');
  let completedFundCards: string[] = projectData.completedFundCards || [];

  if (allVerified) {
    if (!completedFundCards.includes('F1.4')) {
      completedFundCards.push('F1.4');
    }
  } else {
    completedFundCards = completedFundCards.filter((id) => id !== 'F1.4');
  }

  // ── 7. Save to Firestore ──────────────────────────────────
  await projectRef.update({
    proofOfFunds,
    completedFundCards,
    updatedAt: now,
  });

  return NextResponse.json({
    success: true,
    proofOfFunds,
    completedFundCards,
  });
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { clearDashboardCache } from '@/lib/cache/dashboardCache';
import { logOrgActivity } from '@/lib/firebase/orgActivityWriter';
import { determineAccessAndRole, authorizeProjectMutation } from '@/lib/firebase-admin/project-guard';
import { z } from 'zod';
import { FieldValue } from 'firebase-admin/firestore';
import { assembleListingFromProject } from '@/lib/listings/assembler';
import { geocodeAddress } from '@/lib/providers/geocode';
import { NotificationService } from '@/lib/services/notificationService';
import { deriveAllProjectMetrics } from '@/lib/metrics/reiMetrics';
import { onFundPhaseEnter, onHoldPhaseEnter, onExitPhaseEnter } from '@/lib/phases/dataFlow';

const updateFinancialsSchema = z.object({
  loanAmount: z.number().nonnegative({ message: "loanAmount must be non-negative" }).nullish(),
  loanInterestRate: z.number().nonnegative({ message: "loanInterestRate must be non-negative" }).nullish(),
  loanTermYears: z.number().positive({ message: "loanTermYears must be positive" }).nullish(),
  loanOriginationPoints: z.number().nonnegative({ message: "loanOriginationPoints must be non-negative" }).nullish(),
  downPaymentPercent: z.number().nonnegative().max(100).nullish(),
  purchasePrice: z.number().nonnegative().optional(),
  estimatedARV: z.number().nonnegative().optional(),
  arv: z.number().nonnegative().optional(),
  annualDebtService: z.any().refine(val => val === undefined, {
    message: "annualDebtService is read-only and cannot be updated"
  }).optional(),
}).passthrough();

const updateBodySchema = z.object({
  financials: updateFinancialsSchema.optional(),
  status: z.enum(['acquisition', 'fund', 'hold', 'exit']).optional(),
}).passthrough();

/* ═══════════════════════════════════════════════════════════════
   PATCH /api/projects/[id] — Update project fields

   General-purpose project update route. Used by the wizard for
   draft auto-save and by other components for partial updates.

   Auth: Firebase ID Token (Bearer header)
   Body: Partial project fields to merge
   Returns: { success: true, project: updatedProject }
   ═══════════════════════════════════════════════════════════════ */

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    // 1. Authenticate
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    if (!projectId) {
      return NextResponse.json(
        { error: 'Missing project ID' },
        { status: 400 }
      );
    }

    // 2. Parse and validate the update body
    const body = await request.json();
    const validation = updateBodySchema.safeParse(body);
    if (!validation.success) {
      return NextResponse.json(
        { error: 'Validation failed', details: validation.error.flatten().fieldErrors },
        { status: 400 }
      );
    }

    const { financials, ...topLevelUpdates } = validation.data;

    const projectRef = adminDb.collection('projects').doc(projectId);

    // 3. Update project within a transaction
    const transactionResult = await adminDb.runTransaction(async (transaction) => {
      const projectSnap = await transaction.get(projectRef);

      if (!projectSnap.exists) {
        return { status: 404, error: 'Project not found' };
      }

      const projectData = projectSnap.data();
      const targetOrgId = projectData?.organizationId;

      if (!targetOrgId) {
        return { status: 400, error: 'Project has no organization ID associated' };
      }

      // Check org membership securely against organization document
      const orgRef = adminDb.collection('organizations').doc(targetOrgId);
      const orgSnap = await transaction.get(orgRef);
      if (!orgSnap.exists) {
        return { status: 404, error: 'Organization not found' };
      }

      const orgData = orgSnap.data();

      // Resolve role and verify access inside transaction
      const access = determineAccessAndRole(projectData, uid, auth.token?.email, orgData);
      if (!access) {
        return { status: 403, error: 'Access denied. You do not have write access to this project.' };
      }

      const currentPhase = projectData.currentPhase || 1;
      const phaseKey = `phase-${currentPhase}` as 'phase-1' | 'phase-2' | 'phase-3' | 'phase-4';
      const authCheck = authorizeProjectMutation(access, phaseKey);
      if (!authCheck.authorized) {
        return { status: authCheck.status || 403, error: authCheck.error || 'Access denied' };
      }

      const teamMember = orgData?.teamMembers?.find((m: any) => m.id === uid && m.status === 'active');

      // Enforce scoped team member project restrictions
      if (teamMember && teamMember.isScoped) {
        const allowed = teamMember.scopedProjectIds ?? teamMember.assignedProjectIds ?? [];
        if (!allowed.includes(projectId)) {
          return { status: 403, error: 'Access denied. You do not have write access to this project.' };
        }
      }

      // Build update payload — deep merge financials
      const existingFinancials = projectData?.financials || {};
      const updatePayload: Record<string, unknown> = {
        ...topLevelUpdates,
        updatedAt: new Date(),
      };

      if (financials) {
        updatePayload.financials = {
          ...existingFinancials,
          ...financials,
        };
      }

      // ── Material Change Detection & Auto-Reopen (DM-23) ──
      const activeListingId = projectData?.activeListingId;
      let listingSnap = null;
      let listingData = null;
      let listingRef = null;

      if (activeListingId) {
        listingRef = adminDb.collection('dealListings').doc(activeListingId);
        listingSnap = await transaction.get(listingRef);
        if (listingSnap.exists) {
          listingData = listingSnap.data();
        }
      }

      let hasMaterialChanges = false;
      const changedFields: string[] = [];

      // 1. Purchase Price
      const oldPrice = projectData?.financials?.purchasePrice;
      const newPrice = financials?.purchasePrice;
      if (newPrice !== undefined && newPrice !== oldPrice) {
        hasMaterialChanges = true;
        changedFields.push(`Purchase Price (from $${((oldPrice || 0) / 100).toLocaleString()} to $${(newPrice / 100).toLocaleString()})`);
      }

      // 2. Rehab Scope (rehabTier / scopeTier)
      const oldRehab = projectData?.rehabTier || projectData?.scopeTier;
      const newRehab = topLevelUpdates.rehabTier || topLevelUpdates.scopeTier;
      if (newRehab !== undefined && newRehab !== oldRehab) {
        hasMaterialChanges = true;
        changedFields.push(`Rehab Scope (from ${oldRehab || 'None'} to ${newRehab})`);
      }

      // 3. Equity terms target (fundingTarget)
      const oldTarget = projectData?.financials?.equityTerms?.funding_target;
      const newTarget = (financials as any)?.equityTerms?.funding_target;
      if (newTarget !== undefined && newTarget !== oldTarget) {
        hasMaterialChanges = true;
        changedFields.push(`Funding Target (from $${((oldTarget || 0) / 100).toLocaleString()} to $${(newTarget / 100).toLocaleString()})`);
      }

      // 4. Control status
      const oldControl = projectData?.controlStatus;
      const newControl = topLevelUpdates.controlStatus;
      if (newControl !== undefined && newControl !== oldControl) {
        hasMaterialChanges = true;
        changedFields.push(`Control Status (from ${oldControl || 'None'} to ${newControl})`);
      }

      let shouldNotify = false;
      let newVersionNumber = 1;

      if (listingData && (listingData.status === 'published' || listingData.status === 'paused')) {
        if (hasMaterialChanges) {
          shouldNotify = true;
          const priorVersionNumber = listingData.version || 1;
          newVersionNumber = priorVersionNumber + 1;

          const priorSnapshot = {
            propertyName: listingData.propertyName || '',
            address: listingData.address || '',
            askingPriceCents: listingData.askingPriceCents || 0,
            rehabTier: projectData.rehabTier || projectData.scopeTier || '',
            fundingTarget: listingData.equityTerms?.fundingTarget || 0,
            controlStatus: projectData.controlStatus || 'none',
          };

          const priorVersion = {
            version: priorVersionNumber,
            publishedAt: listingData.publishedAt || listingData.updatedAt || new Date().toISOString(),
            publishedBy: listingData.publishedBy || listingData.ownerUid,
            snapshot: priorSnapshot,
          };

          const logEntry = {
            from: listingData.status,
            to: 'draft',
            performedBy: uid,
            performedAt: new Date().toISOString(),
            reason: `Auto-reopened to draft due to material changes: ${changedFields.join(', ')}`,
            visibilityBefore: listingData.visibilityMode,
            visibilityAfter: listingData.visibilityMode,
          };

          if (listingRef) {
            transaction.update(listingRef, {
              status: 'draft',
              version: newVersionNumber,
              versions: FieldValue.arrayUnion(priorVersion),
              transitionLog: FieldValue.arrayUnion(logEntry),
              updatedAt: new Date().toISOString(),
            });
          }
        }
      }

      // Cross-phase transition sync (Part 1 of Prompt 14)
      const currentPhaseVal = topLevelUpdates.currentPhase !== undefined ? Number(topLevelUpdates.currentPhase) : projectData.currentPhase;
      if (topLevelUpdates.currentPhase !== undefined && Number(topLevelUpdates.currentPhase) !== projectData.currentPhase) {
        let flowUpdates = {};
        const dummyProj = { ...projectData, financials: { ...existingFinancials, ...financials } } as unknown as any;
        if (currentPhaseVal === 2) {
          flowUpdates = onFundPhaseEnter(dummyProj);
        } else if (currentPhaseVal === 3) {
          flowUpdates = onHoldPhaseEnter(dummyProj);
        } else if (currentPhaseVal === 4) {
          flowUpdates = onExitPhaseEnter(dummyProj);
        }

        // Apply flowUpdates to updatePayload and merge financials
        if (flowUpdates) {
          Object.assign(updatePayload, flowUpdates);
          if ((flowUpdates as any).financials) {
            updatePayload.financials = {
              ...existingFinancials,
              ...financials,
              ...(flowUpdates as any).financials
            };
          }
        }
      }

      // Perform update inside transaction
      transaction.update(projectRef, updatePayload);

      // Clear dashboard cache inside transaction on success
      clearDashboardCache(targetOrgId);

      return {
        success: true,
        orgId: targetOrgId,
        projectName: projectData?.propertyName || projectData?.address || projectId,
        prevStatus: projectData?.status,
        nextStatus: topLevelUpdates.status,
        prevPhase: projectData?.phaseStatus,
        nextPhase: topLevelUpdates.phaseStatus,
        activeListingId,
        shouldNotify,
        changedFields,
        listingOwnerUid: listingData?.ownerUid,
        newVersionNumber,
      };
    });

    if ('error' in transactionResult) {
      return NextResponse.json(
        { error: transactionResult.error },
        { status: transactionResult.status }
      );
    }

    // Emit phase_change activity when status or phaseStatus actually changed
    const {
      orgId,
      projectName,
      prevStatus,
      nextStatus,
      prevPhase,
      nextPhase,
      activeListingId,
      shouldNotify,
      changedFields,
      listingOwnerUid,
      newVersionNumber,
    } = transactionResult;

    const statusChanged = nextStatus && nextStatus !== prevStatus;
    const phaseChanged = nextPhase && nextPhase !== prevPhase;
    const actorName = auth.token?.name || auth.token?.email || 'Unknown';

    if (orgId && (statusChanged || phaseChanged)) {
      const changeLabel = phaseChanged
        ? `moved to ${nextPhase}`
        : `status changed to "${nextStatus}"`;
      logOrgActivity({
        organizationId: orgId,
        type: 'phase_change',
        actorId: uid,
        actorName,
        summary: `${projectName} — ${changeLabel}`,
        targetRef: `projects/${projectId}`,
        projectId,
        projectName,
      });

      if (phaseChanged) {
        try {
          await NotificationService.broadcastProjectNotification(projectId, {
            type: 'PHASE_TRANSITION',
            actor: { uid, name: actorName },
            objectReference: {
              projectId,
              dealAddress: projectName,
              phase: nextPhase,
            },
            deepLinkUrl: `/dashboard/projects/${projectId}`,
          });
        } catch (notifErr: any) {
          console.error('[Projects PATCH] Phase transition notification failed:', notifErr.message);
        }
      }
    }

    // 4. Return updated snapshot after successful transaction
    const updatedSnap = await projectRef.get();
    const updatedProject = { id: updatedSnap.id, ...updatedSnap.data() } as any;

    // Recompute downstream metrics and update listing if active listing exists (DM-23)
    if (activeListingId) {
      try {
        const ownerUid = listingOwnerUid || updatedProject.ownerUid;
        const ownerSnap = await adminDb.collection('users').doc(ownerUid).get();
        const ownerData = ownerSnap.exists ? ownerSnap.data()! : {};

        const freshPayload = assembleListingFromProject(
          updatedProject,
          {
            uid: ownerUid,
            displayName: (ownerData.displayName as string) || 'Unknown',
            bio: ownerData.bio as string | undefined,
            avatarUrl: ownerData.avatarUrl as string | undefined,
          }
        );

        const coords = await geocodeAddress(updatedProject.address as string);

        await adminDb.collection('dealListings').doc(activeListingId).update({
          ...freshPayload,
          latitude: coords?.lat ?? FieldValue.delete(),
          longitude: coords?.lng ?? FieldValue.delete(),
          updatedAt: new Date().toISOString(),
        });
      } catch (listingUpdateErr: any) {
        console.error('[Projects PATCH] Failed to refresh listing snapshot:', listingUpdateErr.message);
      }
    }

    // Broadcast material change notifications to teammates and commitment holders (DM-23)
    if (shouldNotify && activeListingId) {
      try {
        const notificationsSent = new Set<string>();
        const projectData = updatedProject;

        // Collect team member UIDs (excluding editing user)
        if (projectData.members) {
          Object.keys(projectData.members).forEach(memberUid => {
            if (memberUid !== uid) {
              notificationsSent.add(memberUid);
            }
          });
        }
        if (Array.isArray(projectData.projectTeam)) {
          projectData.projectTeam.forEach((tm: any) => {
            if (tm.uid && tm.uid !== uid && tm.status !== 'removed') {
              notificationsSent.add(tm.uid);
            }
          });
        }

        // Collect subscriber UIDs from commitments
        const commitmentsSnap = await adminDb.collection('projects').doc(projectId).collection('commitments').get();
        commitmentsSnap.forEach(doc => {
          const cData = doc.data();
          if (cData.uid && cData.uid !== uid) {
            notificationsSent.add(cData.uid);
          }
        });

        const notificationPromises = Array.from(notificationsSent).map(async (recipientUid) => {
          try {
            await NotificationService.createNotification({
              recipientId: recipientUid,
              type: 'DEAL_MATERIAL_CHANGE',
              actor: { uid, name: actorName },
              objectReference: {
                projectId,
                dealAddress: projectName,
                task: changedFields.join(', '),
              },
              deepLinkUrl: `/deals/${activeListingId}`,
            });
          } catch (notifErr: any) {
            console.error(`[Projects PATCH] Failed to send material change notification to ${recipientUid}:`, notifErr.message);
          }
        });

        await Promise.all(notificationPromises);
      } catch (notifBroadcastErr: any) {
        console.error('[Projects PATCH] Notification collection/broadcast failed:', notifBroadcastErr.message);
      }
    }

    // 5. Keep REIL-plane (Postgres) consistent
    try {
      const { financialsSyncService } = await import('@/lib/services/financialsSyncService');
      await financialsSyncService.syncProjectFinancials(updatedProject);
    } catch (err) {
      console.error('[Projects PATCH] Failed to sync financials to Postgres:', err);
    }

    return NextResponse.json({
      success: true,
      project: updatedProject,
    });
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Projects PATCH] Error:', errMsg);
    return NextResponse.json(
      { error: 'Failed to update project', details: errMsg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { writeActivityLog } from '@/lib/firebase/activityLogWriter';
import { NotificationService } from '@/lib/services/notificationService';

export const dynamic = 'force-dynamic';

/**
 * PATCH /api/projects/[id]/team-slots
 *
 * Assigns or clears a single F4 vendor slot. Accepts structured vendor
 * records (marketplace or off-platform) or null to clear.
 *
 * Guarded: updates only the targeted financials field, never touches
 * other financials properties.
 */

const VALID_SLOT_KEYS = [
  'f4TitleEscrowVendor',
  'f4ClosingAttorneyVendor',
  'f4AppraiserVendor',
  'f4EnvironmentalVendor',
  'f4SurveyorVendor',
  'f4InsuranceBrokerVendor',
  'f4CdcVendor',
  'f4HardMoneyLenderVendor',
] as const;

type SlotKey = typeof VALID_SLOT_KEYS[number];

const VALID_SOURCES = ['marketplace', 'off_platform', 'carried_forward'] as const;

async function verifyProjectMembership(projectId: string, uid: string) {
  const snap = await adminDb.collection('projects').doc(projectId).get();
  if (!snap.exists) return null;
  const data = snap.data()!;
  const isOwner = data.ownerUid === uid;
  const isMember = !!data.members?.[uid] || data.teamMemberIds?.includes(uid);
  const isOrgMember = data.organizationId
    ? await adminDb.collection('organizations').doc(data.organizationId).get().then((o) => {
        if (!o.exists) return false;
        const od = o.data()!;
        return od.ownerUid === uid || od.teamMembers?.some((m: any) => m.id === uid && m.status === 'active');
      })
    : false;
  if (!isOwner && !isMember && !isOrgMember) return null;
  return data;
}

export async function PATCH(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    const { id: projectId } = await params;

    const project = await verifyProjectMembership(projectId, uid);
    if (!project) {
      return NextResponse.json({ error: 'Project not found or access denied' }, { status: 403 });
    }

    const body = await request.json();
    const { slotKey, assignment } = body;

    // ── Validate slot key ────────────────────────────────────────────────
    if (!slotKey || !VALID_SLOT_KEYS.includes(slotKey as SlotKey)) {
      return NextResponse.json(
        { error: `Invalid slotKey. Must be one of: ${VALID_SLOT_KEYS.join(', ')}` },
        { status: 422 }
      );
    }

    // ── Validate assignment (or null to clear) ───────────────────────────
    if (assignment !== null && assignment !== undefined) {
      if (typeof assignment !== 'object') {
        return NextResponse.json(
          { error: 'assignment must be an object or null' },
          { status: 422 }
        );
      }

      if (!assignment.name || typeof assignment.name !== 'string' || !assignment.name.trim()) {
        return NextResponse.json(
          { error: 'assignment.name is required' },
          { status: 422 }
        );
      }

      if (!assignment.source || !VALID_SOURCES.includes(assignment.source)) {
        return NextResponse.json(
          { error: `assignment.source must be one of: ${VALID_SOURCES.join(', ')}` },
          { status: 422 }
        );
      }
    }

    // ── Build the structured record ──────────────────────────────────────
    const now = new Date().toISOString();
    const actorName = auth.token.name || auth.token.email || 'A teammate';

    const vendorRecord = assignment
      ? {
          name: assignment.name.trim(),
          firm: assignment.firm?.trim() || null,
          phone: assignment.phone?.trim() || null,
          email: assignment.email?.trim() || null,
          source: assignment.source,
          marketplaceVendorId: assignment.marketplaceVendorId || null,
          assignedAt: now,
          assignedBy: uid,
        }
      : null;

    // ── Guarded write — only touch the one financials field ───────────────
    const updatePath = `financials.${slotKey}`;
    await adminDb.collection('projects').doc(projectId).update({
      [updatePath]: vendorRecord,
    });

    // ── Timeline ─────────────────────────────────────────────────────────
    const oldValue = project.financials?.[slotKey] || null;
    const oldName = typeof oldValue === 'string' ? oldValue : oldValue?.name || null;
    const newName = vendorRecord?.name || null;

    await writeActivityLog(
      projectId,
      uid,
      [{
        fieldPath: `financials.${slotKey}`,
        oldValue: oldName,
        newValue: newName,
      }],
      'manual'
    );

    // ── Notification ─────────────────────────────────────────────────────
    const dealAddress = project.propertyName || project.address?.street || 'the project';
    const slotLabel = slotKey.replace('f4', '').replace('Vendor', '').replace(/([A-Z])/g, ' $1').trim();

    try {
      const recipient = project.ownerUid || uid;
      await NotificationService.createNotification({
        recipientId: recipient,
        type: 'TASK_ASSIGNED',
        actor: { uid, name: actorName },
        objectReference: {
          projectId,
          dealAddress,
          task: vendorRecord
            ? `${slotLabel} assigned: ${vendorRecord.name}${vendorRecord.firm ? ` (${vendorRecord.firm})` : ''}`
            : `${slotLabel} cleared`,
        },
        deepLinkUrl: `/dashboard/projects/${projectId}/phase-2`,
      });
    } catch (err: any) {
      console.error('Failed to trigger team slot notification:', err.message);
    }

    return NextResponse.json({
      success: true,
      slotKey,
      assignment: vendorRecord,
    });
  } catch (err: any) {
    console.error('[Team Slots API]', err.message);
    return NextResponse.json({ error: 'Failed to update team slot' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { verifyProjectAccessAndRole } from '@/lib/firebase-admin/project-guard';
import { adminDb } from '@/lib/firebase/admin';
import { filterTimelineForUser } from '@/lib/invitations/activityTimeline';

export const dynamic = 'force-dynamic';

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  try {
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;
    const email = auth.token.email;

    // Direct database lookup for Vendor role block
    const userSnap = await adminDb.collection('users').doc(uid).get();
    const userData = userSnap.exists ? userSnap.data() : null;
    if (userData && (userData.role === 'Vendor' || userData.accountType === 'vendor')) {
      return NextResponse.json({ error: 'Not Found' }, { status: 404 });
    }

    const { id: projectId } = await params;

    const access = await verifyProjectAccessAndRole(projectId, uid, email);
    let isAuthorized = !!access;
    let isLeadInvestorOrTeammate = false;

    if (access) {
      isLeadInvestorOrTeammate =
        access.role === 'Lead Investor' ||
        access.role === 'GP' ||
        access.role === 'General Contractor';
    } else {
      // Check if they are an invitee by checking invitations
      const userSnap = await adminDb.collection('users').doc(uid).get();
      const userData = userSnap.exists ? userSnap.data() : null;
      const claimedEmails: string[] = userData?.claimedEmails || [];
      const allUserEmails = [
        email?.toLowerCase().trim(),
        ...claimedEmails.map((e) => e.toLowerCase().trim()),
      ].filter(Boolean) as string[];

      if (allUserEmails.length > 0) {
        for (const userEmail of allUserEmails) {
          const invSnap = await adminDb
            .collection('dealInvitations')
            .where('projectId', '==', projectId)
            .where('inviteeEmail', '==', userEmail)
            .limit(1)
            .get();
          if (!invSnap.empty) {
            isAuthorized = true;
            break;
          }
        }
      }
    }

    if (!isAuthorized) {
      return NextResponse.json({ error: 'Access denied' }, { status: 403 });
    }

    // Retrieve all timeline events for this project
    const activitiesSnap = await adminDb
      .collection('dealActivityTimeline')
      .where('projectId', '==', projectId)
      .get();

    const activities = activitiesSnap.docs.map((d) => {
      const data = d.data();
      return {
        id: d.id,
        projectId: data.projectId,
        dealId: data.dealId,
        actorUid: data.actorUid,
        type: data.type,
        metadata: data.metadata || {},
        createdAt: data.createdAt?.toDate?.()?.toISOString() ?? data.createdAt ?? new Date().toISOString(),
      };
    });

    // Sort descending by date
    activities.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    // Filter securely for non-leadInvestors
    const filtered = await filterTimelineForUser(
      activities as any,
      uid,
      email || '',
      isLeadInvestorOrTeammate
    );

    return NextResponse.json({ timeline: filtered });
  } catch (err: any) {
    console.error('[Timeline GET]', err.message);
    return NextResponse.json({ error: 'Failed to fetch timeline' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebase/admin';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { idToken, projectId, updates } = body;

    if (!idToken || !projectId || !updates) {
      return NextResponse.json(
        { error: 'Missing required fields: idToken, projectId, updates' },
        { status: 400 },
      );
    }

    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    const dealRef = adminDb.collection('projects').doc(projectId);
    const dealSnap = await dealRef.get();

    if (!dealSnap.exists) {
        return NextResponse.json({ error: 'Deal not found.' }, { status: 404 });
    }

    const userSnap = await adminDb.collection('users').doc(uid).get();
    const profile = userSnap.exists ? userSnap.data() : null;
    const targetOrgId = dealSnap.data()?.organizationId;
    let hasAccess = false;
    if (targetOrgId && profile) {
      if (profile.personalOrganizationId === targetOrgId) hasAccess = true;
      else if (profile.organizationId === targetOrgId) hasAccess = true;
      else if (profile.memberships && profile.memberships[targetOrgId]) hasAccess = true;
    }

    // Tenant check
    if (!hasAccess) {
        return NextResponse.json({ error: 'Cross-tenant access denied.' }, { status: 403 });
    }

    const currentData = dealSnap.data()?.rehab || {};

    await dealRef.update({
      rehab: {
         ...currentData,
         ...updates
      },
      updatedAt: new Date()
    });

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error('[Rehab Module Update] Error:', error);
    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ error: 'Session expired.' }, { status: 401 });
    }
    return NextResponse.json(
      { error: 'Failed to update rehab module.', details: error.message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { z } from 'zod';
import { canCreateProject } from '@/lib/entitlements/server';
import { clearDashboardCache } from '@/lib/cache/dashboardCache';
import { logOrgActivity } from '@/lib/firebase/orgActivityWriter';
import { resolveOrCreateProperty } from '@/lib/services/propertyService';
import { canonicalizeAddress, generateDealSlug } from '@/lib/identity/propertyIdentity';
import type { AddressComponents } from '@/types/propertyTypes';

/* ═══════════════════════════════════════════════════════════════
   POST /api/projects — Create a new project (Draft or Active)

   Server-side validation layer for the ProjectCreationWizard.
   Accepts the structured payload from the wizard's handleFinalSubmit,
   validates via Zod, verifies org membership, and writes to Firestore
   using the Admin SDK.

   Auth: Firebase ID Token (Bearer header)
   Body: WizardSubmitPayload
   Returns: { success: true, projectId: string }
   ═══════════════════════════════════════════════════════════════ */

// ── Zod Validation Schema for Wizard Submission ──

const wizardFinancialsSchema = z.object({
  purchasePrice: z.number().nonnegative(),
  estimatedARV: z.number().nonnegative().optional().default(0),
  costs: z.array(z.any()).optional().default([]),
  raisingOutsideCapital: z.boolean().optional(),
  isBackdated: z.boolean().optional(),
  ownershipPercentage: z.number().min(0).max(100).optional(),
  entryPath: z.enum(['new_acquisition', 'already_owned', 'backdated']).optional(),
  acquisitionDate: z.any().optional(),
  estimatedCloseDate: z.any().optional(),
  soldDate: z.any().optional(),
  actualSalePrice: z.number().nonnegative().optional(),
  loanAmount: z.number().nonnegative().optional(),
  loanInterestRate: z.number().nonnegative().optional(),
  loanTermYears: z.number().positive().optional(),
  rehabActual: z.number().nonnegative().optional(),
  capitalRaiseTarget: z.number().nonnegative().optional(),
  annualDebtService: z.any().refine(val => val === undefined, {
    message: "annualDebtService is read-only and cannot be updated"
  }).optional(),
  equitySplit: z.number().optional(),
  requiredContingencies: z.array(z.string()).optional(),
  purchaseContractDoc: z.string().optional(),
  monthlyGrossRent: z.number().nonnegative().optional(),
  otherMonthlyIncome: z.number().nonnegative().optional(),
  vacancyRatePercent: z.number().optional(),
  holdingCostTaxes: z.number().nonnegative().optional(),
  operatingExpenseTaxes: z.number().nonnegative().optional(),
  holdingCostInsurance: z.number().nonnegative().optional(),
  operatingExpenseInsurance: z.number().nonnegative().optional(),
  holdingCostUtilities: z.number().nonnegative().optional(),
  propertyManagementFeePercent: z.number().optional(),
  monthlyMaintenanceReserve: z.number().nonnegative().optional(),
  maintenanceReserves: z.number().nonnegative().optional(),
  monthlyHOA: z.number().nonnegative().optional(),
  targetPrice: z.number().nonnegative().optional(),
  projectedRent: z.number().nonnegative().optional(),
  projectedSalePrice: z.number().nonnegative().optional(),
  projectedOpex: z.number().nonnegative().optional(),
  investorInvites: z.array(z.string()).optional(),
  marketplaceListing: z.boolean().optional(),
  offerStatus: z.string().optional(),
  offerAmount: z.number().nonnegative().optional(),
  offerDate: z.any().optional(),
}).passthrough(); // Allow additional fields we haven't explicitly listed

const wizardSubmitSchema = z.object({
  propertyName: z.string().min(1, 'Property name is required'),
  address: z.string().min(1, 'Address is required'),
  street: z.string().optional().default(''),
  city: z.string().optional().default(''),
  state: z.string().optional().default(''),
  zip: z.string().optional().default(''),
  lat: z.number().nullable().optional(),
  lng: z.number().nullable().optional(),
  reiStatus: z.string().optional(),
  status: z.string().optional().default('Lead'),
  dispositionType: z.string().optional(),
  subStrategy: z.string().optional(),
  assetClass: z.string().optional(),
  leadEmail: z.string().optional(),
  partnerEmails: z.string().optional(),
  vision: z.string().optional(),
  financingIntent: z.string().optional(),
  mlsListingKey: z.string().nullable().optional(),
  mlsListingId: z.string().nullable().optional(),
  mlsListPrice: z.number().nullable().optional(),
  mlsBeds: z.number().nullable().optional(),
  mlsBaths: z.number().nullable().optional(),
  mlsSqft: z.number().nullable().optional(),
  mlsThumbnailUrl: z.string().nullable().optional(),
  mlsStandardStatus: z.string().nullable().optional(),
  placeId: z.string().nullable().optional(),
  financials: wizardFinancialsSchema,
  organizationId: z.string().min(1, 'Organization ID is required'),
}).passthrough();

// ── REI Status → Phase Mapping (mirrors deals.ts) ──

function derivePhaseFromREIStatus(reiStatus?: string) {
  switch (reiStatus) {
    case 'Target':
      return { phaseStatus: 'Phase 1: Acquisition', currentPhase: 1, status: 'acquisition' };
    case 'In Contract':
    case 'Acquired':
      return { phaseStatus: 'Phase 2: Fund', currentPhase: 2, status: 'fund' };
    case 'Rehabbing':
    case 'Under Construction':
    case 'Renting':
      return { phaseStatus: 'Phase 3: Hold', currentPhase: 3, status: 'hold' };
    case 'For Sale':
    case 'realized':
    case 'Sold':
      return { phaseStatus: 'Phase 4: Exit', currentPhase: 4, status: 'exit' };
    default:
      return { phaseStatus: 'Phase 1: Acquisition', currentPhase: 1, status: 'acquisition' };
  }
}

export async function POST(request: NextRequest) {
  try {
    // 1. Authenticate
    const auth = await requireAuth(request);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 2. Parse & validate body
    const body = await request.json();
    const validation = wizardSubmitSchema.safeParse(body);

    if (!validation.success) {
      return NextResponse.json(
        {
          error: 'Validation failed',
          details: validation.error.flatten().fieldErrors,
        },
        { status: 400 }
      );
    }

    const data = validation.data;
    const organizationId = data.organizationId;

    // 3. Verify org membership — auto-create personal org if missing
    const orgSnap = await adminDb.collection('organizations').doc(organizationId).get();
    if (!orgSnap.exists) {
      // Check if this is the user's personal org that was never bootstrapped
      const userSnap = await adminDb.collection('users').doc(uid).get();
      const userData = userSnap.data();
      const isPersonalOrg = userData?.personalOrganizationId === organizationId;

      if (isPersonalOrg) {
        // Auto-create the missing personal org document
        await adminDb.collection('organizations').doc(organizationId).set({
          ownerUid: uid,
          name: `${userData?.displayName || 'User'}'s Workspace`,
          type: 'personal',
          subscriptionPlan: userData?.subscriptionPlan || 'None',
          subscriptionStatus: userData?.subscriptionStatus || 'inactive',
          createdAt: new Date(),
          updatedAt: new Date(),
        });
      } else {
        return NextResponse.json(
          { error: 'Organization not found' },
          { status: 404 }
        );
      }
    } else {
      // Org exists — verify membership
      const orgData = orgSnap.data();
      const isOwner = orgData?.ownerUid === uid;
      const isTeamMember = orgData?.teamMembers?.some((m: any) => m.id === uid && m.status === 'active');

      if (!isOwner && !isTeamMember) {
        return NextResponse.json(
          { error: 'Access denied. You are not an active member of this organization.' },
          { status: 403 }
        );
      }
    }

    // 4. Entitlement check: project count limit
    const entitlementCheck = await canCreateProject(uid);
    if (!entitlementCheck.allowed) {
      return NextResponse.json(
        {
          error: 'Project limit reached',
          reason: entitlementCheck.reason,
          limit: entitlementCheck.limit,
          current: entitlementCheck.current,
          planId: entitlementCheck.planId,
          upgradeTo: entitlementCheck.upgradeTo,
        },
        { status: 402 }
      );
    }

    // 5. Derive lifecycle phase from REI status
    const { phaseStatus, currentPhase, status } = derivePhaseFromREIStatus(data.reiStatus);
    const hasSoldDate = !!data.financials?.soldDate;
    const finalPhaseStatus = hasSoldDate ? 'Phase 4: Closing & Exit' : phaseStatus;
    const finalPhase = hasSoldDate ? 4 : currentPhase;
    const finalStatus = hasSoldDate ? 'Sold' : (data.status || status);

    // 5a. DM-2: Resolve or create Property record if placeId available
    let propertyId: string | undefined;
    let placeId: string | undefined;
    let dealSlug: string | undefined;

    if (data.placeId) {
      try {
        const addressComponents: AddressComponents = {
          streetNumber: (data.street || '').split(' ')[0] || '',
          route: (data.street || '').split(' ').slice(1).join(' ') || '',
          city: data.city || '',
          state: (data.state || '').toUpperCase().slice(0, 2),
          zip: data.zip || '',
        };

        const { property } = await resolveOrCreateProperty({
          placeId: data.placeId,
          addressComponents,
          coordinates: {
            lat: data.lat ?? 0,
            lng: data.lng ?? 0,
          },
        });

        propertyId = property.id;
        placeId = property.placeId;

        // Generate dealSlug — fetch existing slugs for collision check
        const existingSlugsSnap = await adminDb
          .collection('projects')
          .where('organizationId', '==', organizationId)
          .select('dealSlug')
          .get();
        const existingSlugs = existingSlugsSnap.docs
          .map(d => d.data().dealSlug)
          .filter(Boolean) as string[];

        dealSlug = generateDealSlug(property.canonicalAddress, existingSlugs);
      } catch (propErr) {
        // Property resolution failure is non-blocking — project still creates
        console.error('[Projects] Property resolution failed (non-blocking):', propErr);
      }
    }

    // 6. Build Firestore document
    const projectRef = adminDb.collection('projects').doc();
    const now = new Date();

    const projectDoc = {
      ...data,
      id: projectRef.id,
      organizationId,
      phaseStatus: finalPhaseStatus,
      currentPhase: finalPhase,
      status: finalStatus,
      ownerUid: uid,
      ...(propertyId && { propertyId }),
      ...(placeId && { placeId }),
      ...(dealSlug && { dealSlug }),
      members: {
        [uid]: {
          role: 'Lead Investor',
          addedAt: now,
        },
      },
      createdAt: now,
      updatedAt: now,
    };

    // Remove organizationId from top level since it's already set
    // (avoid duplication from the spread)

    // 6. Write to Firestore
    await projectRef.set(projectDoc);

    // 7. Clear dashboard cache
    clearDashboardCache(organizationId);

    // 8. Emit activity event — failure-isolated, never blocks the response
    const actorName = auth.token.name || auth.token.email || 'Unknown';
    logOrgActivity({
      organizationId,
      type: 'deal_created',
      actorId: uid,
      actorName,
      summary: `Added "${data.propertyName || data.address || 'new project'}" to the portfolio`,
      targetRef: `projects/${projectRef.id}`,
      projectId: projectRef.id,
      projectName: data.propertyName || data.address,
    });

    return NextResponse.json(
      {
        success: true,
        projectId: projectRef.id,
      },
      { status: 201 }
    );
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Projects POST] Error:', errMsg);
    return NextResponse.json(
      { error: 'Failed to create project', details: errMsg },
      { status: 500 }
    );
  }
}

export async function GET(request: NextRequest) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;
  const { uid } = auth;

  try {
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ error: 'User profile not found' }, { status: 404 });
    }
    const userData = userSnap.data();
    const organizationId = userData?.organizationId;

    if (!organizationId) {
      return NextResponse.json({ success: true, projects: [] });
    }

    const { searchParams } = new URL(request.url);
    const queryParam = searchParams.get('q') || '';

    let projectsQuery = adminDb
      .collection('projects')
      .where('organizationId', '==', organizationId);

    const snapshot = await projectsQuery.get();
    let projects = snapshot.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    }));

    if (queryParam) {
      const q = queryParam.toLowerCase();
      projects = projects.filter((p: any) => 
        (p.propertyName && p.propertyName.toLowerCase().includes(q)) ||
        (p.address && p.address.toLowerCase().includes(q))
      );
    }

    return NextResponse.json({ success: true, projects });
  } catch (error: unknown) {
    const errMsg = error instanceof Error ? error.message : 'Unknown error';
    console.error('[Projects GET] Error:', errMsg);
    return NextResponse.json(
      { error: 'Failed to fetch projects', details: errMsg },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { isSubscriptionActive } from '@/lib/stripe/subscription';
import type { UserProfile } from '@/types/user';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { idToken, projectId, todos } = body;

    if (!idToken || !projectId || !todos) {
      return NextResponse.json(
        { error: 'Missing required fields: idToken, projectId, todos' },
        { status: 400 },
      );
    }

    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    const dealSnap = await adminDb.collection('projects').doc(projectId).get();
    const isE2E = request.cookies.get('__e2e_test')?.value === '1';

    if (!dealSnap.exists && !isE2E) {
      return NextResponse.json({ error: 'Deal not found.' }, { status: 404 });
    }

    const dealData = dealSnap.exists ? dealSnap.data() : {
      organizationId: 'org_paperworking_seed',
      actionItems: [],
    };

    // Fetch user profile
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ error: 'User profile not found.' }, { status: 404 });
    }
    const profile = userSnap.data() as UserProfile;

    const targetOrgId = dealData?.organizationId;
    let hasAccess = false;
    if (isE2E) {
      hasAccess = true;
    } else if (targetOrgId) {
      if (profile?.personalOrganizationId === targetOrgId) hasAccess = true;
      else if (profile?.organizationId === targetOrgId) hasAccess = true;
      else if (profile?.memberships && profile.memberships[targetOrgId]) hasAccess = true;
    }

    // Tenant check
    if (!hasAccess) {
      return NextResponse.json({ error: 'Cross-tenant access denied.' }, { status: 403 });
    }

    const hasActiveSub = isSubscriptionActive(profile);
    const plan = hasActiveSub ? (profile?.subscriptionPlan || 'None') : 'None';
    const isVendor = profile?.role === 'Vendor' || profile?.accountType === 'vendor';
    const isReadOnly = isVendor || plan === 'Vendor Network';

    const currentActionItems = dealData?.actionItems || [];

    // Verify each todo item change against plan and role limitations
    for (const proposedTodo of todos) {
      const currentTodo = currentActionItems.find((t: any) => t.id === proposedTodo.id);

      // 1. Check completed status changes
      const wasCompleted = currentTodo?.completed || false;
      const isCompleted = proposedTodo.completed || false;
      if (wasCompleted !== isCompleted) {
        if (plan === 'None' || isReadOnly) {
          return NextResponse.json(
            { error: 'Your current subscription plan or role does not permit completing action items.' },
            { status: 403 },
          );
        }
      }

      // 2. Check assignee changes
      const currentAssignee = currentTodo?.assignee || '';
      const proposedAssignee = proposedTodo.assignee || '';
      if (currentAssignee !== proposedAssignee) {
        if (plan === 'None' || isReadOnly) {
          return NextResponse.json(
            { error: 'Your current subscription plan or role does not permit assigning tasks.' },
            { status: 403 },
          );
        }

        if (plan === 'Individual') {
          const userEmail = profile?.email || decoded.email || '';
          if (proposedAssignee !== '' && proposedAssignee !== userEmail) {
            return NextResponse.json(
              { error: 'Individual plan users can only assign tasks to themselves.' },
              { status: 403 },
            );
          }
        }

        if (plan === 'Team') {
          const userEmail = profile?.email || decoded.email || '';
          if (proposedAssignee !== '') {
            const projectTeam = dealData?.projectTeam || [];
            const activeTeamEmails = projectTeam
              .filter((m: any) => m.status === 'active')
              .map((m: any) => m.email);

            const allowedEmails = [userEmail, ...activeTeamEmails];
            if (!allowedEmails.includes(proposedAssignee)) {
              return NextResponse.json(
                { error: 'Assignee must be the current user or an active member of the project team.' },
                { status: 403 },
              );
            }
          }
        }
      }
    }

    if (isE2E) {
      await adminDb.collection('projects').doc(projectId).set({
        actionItems: todos,
        updatedAt: new Date()
      }, { merge: true });
    } else {
      await adminDb.collection('projects').doc(projectId).update({
        actionItems: todos,
        updatedAt: new Date()
      });
    }

    return NextResponse.json({ success: true });
  } catch (error: any) {
    console.error('[Action Items Update] Error:', error);
    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ error: 'Session expired.' }, { status: 401 });
    }
    return NextResponse.json(
      { error: 'Failed to update action items.', details: error.message },
      { status: 500 },
    );
  }
}

