    console.error('[GET /api/reconciliations] Error:', error);
    return NextResponse.json(
      { success: false, error: error.message || 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError } from "@/lib/firebase-admin/auth-guard";
import prisma from "@/lib/prisma";
import { updateProjectSync, upsertPropertyFacts, appendValuationSnapshot } from "@/lib/db/projects";
import { getRentCastClient } from "@/lib/providers/rentcast";
import { adminDb } from "@/lib/firebase/admin";
import telemetry from "@/lib/telemetry";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

// Capped requests per cron run (Budget Guard)
const BUDGET_LIMIT = 10;

export async function POST(req: NextRequest) {
  let isAuthenticated = false;
  let userUid = "cron-job";

  // 1. Check CRON_SECRET from header or query param
  const cronSecret = process.env.CRON_SECRET;
  const authHeader = req.headers.get("Authorization");
  const queryToken = req.nextUrl.searchParams.get("token");

  if (cronSecret) {
    if (
      (authHeader && authHeader === `Bearer ${cronSecret}`) ||
      (queryToken && queryToken === cronSecret)
    ) {
      isAuthenticated = true;
    }
  }

  // 2. If not authenticated via CRON_SECRET, require admin Firebase ID Token
  if (!isAuthenticated) {
    const auth = await requireAuth(req);
    if (!isAuthError(auth)) {
      const isAdmin = (auth.token as Record<string, unknown>)?.['admin'] === true;
      if (isAdmin) {
        isAuthenticated = true;
        userUid = auth.uid;
      }
    }
  }

  if (!isAuthenticated) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  // Fetch all active projects (exclude CLOSED and DEAD)
  const projects = await prisma.reilProject.findMany({
    where: {
      NOT: [
        { acquisitionStatus: "CLOSED" },
        { acquisitionStatus: "DEAD" },
      ],
    },
    include: {
      propertyFacts: true,
    },
  });

  const now = new Date();
  const ONE_DAY_MS = 24 * 60 * 60 * 1000;
  const SEVEN_DAYS_MS = 7 * ONE_DAY_MS;
  const THIRTY_DAYS_MS = 30 * ONE_DAY_MS;

  const providerType = (process.env.PROPERTY_DATA_PROVIDER || "mock").toLowerCase();
  const client = getRentCastClient(); // null when RENTCAST_API_KEY is absent

  let apiCallsMade = 0;
  const syncedProjects: string[] = [];

  for (const project of projects) {
    // Stop if we hit the budget cap
    if (apiCallsMade >= BUDGET_LIMIT) {
      logger.info("[Cron Refresh] Budget limit of 10 API calls reached. Stopping current run.");
      break;
    }

    const address = project.addressLine;
    const zip = project.zip;
    if (!address) continue;

    const valueExpired = !project.valueSyncedAt || (now.getTime() - new Date(project.valueSyncedAt).getTime() > SEVEN_DAYS_MS);
    const rentExpired = !project.rentSyncedAt || (now.getTime() - new Date(project.rentSyncedAt).getTime() > SEVEN_DAYS_MS);
    const marketExpired = !project.marketSyncedAt || (now.getTime() - new Date(project.marketSyncedAt).getTime() > THIRTY_DAYS_MS);

    let needsDbUpdate = false;
    const updateData: {
      lastSyncedAt: Date;
      valueSyncedAt?: Date;
      rentSyncedAt?: Date;
      marketSyncedAt?: Date;
    } = {
      lastSyncedAt: now,
    };

    const firestoreUpdates: Record<string, any> = {
      lastSyncedAt: now.toISOString(),
    };

    try {
      // 1. Refresh Value AVM
      if (valueExpired && apiCallsMade < BUDGET_LIMIT) {
        logger.info(`[Cron Refresh] Refreshing Value AVM for project ${project.id} (${address})`);

        let avmPriceCents = 0;
        let avmPriceLowCents = 0;
        let avmPriceHighCents = 0;

        if (providerType === "rentcast" && client) {
          apiCallsMade++;
          const valueData = await client.getValueEstimate({ address }, true);
          avmPriceCents = Math.round(valueData.price * 100);
          avmPriceLowCents = Math.round(valueData.priceRangeLow * 100);
          avmPriceHighCents = Math.round(valueData.priceRangeHigh * 100);
        } else {
          // Mock generation (±15% range matches MockPropertyDataProvider)
          const price = 250000 + (project.id.charCodeAt(0) * 1500) % 500000;
          avmPriceCents = price * 100;
          avmPriceLowCents = Math.round(price * 0.85) * 100;
          avmPriceHighCents = Math.round(price * 1.15) * 100;
        }

        // Save Value AVM to Prisma PropertyFacts
        await upsertPropertyFacts({
          projectId: project.id,
          avmPriceCents: BigInt(avmPriceCents),
          avmPriceLowCents: BigInt(avmPriceLowCents),
          avmPriceHighCents: BigInt(avmPriceHighCents),
          sourceProvider: providerType === "rentcast" ? "RentCast API" : "MockPropertyProvider v1",
          fetchedAt: now,
        });

        // Append new valuation snapshot
        await appendValuationSnapshot({
          projectId: project.id,
          valueCents: BigInt(avmPriceCents),
          valueLowCents: BigInt(avmPriceLowCents),
          valueHighCents: BigInt(avmPriceHighCents),
          source: providerType === "rentcast" ? "rentcast" : "mock",
          fetchedAt: now,
        });

        // Replicate to Firestore
        firestoreUpdates["financials.estimatedCurrentValue"] = Math.round(avmPriceCents / 100);
        firestoreUpdates["financials.estimatedCurrentValueSource"] = providerType === "rentcast" ? "rentcast" : "mock";
        firestoreUpdates["financials.estimatedCurrentValueAsOf"] = now.toISOString();

        updateData.valueSyncedAt = now;
        firestoreUpdates.valueSyncedAt = now.toISOString();
        needsDbUpdate = true;
      }

      // 2. Refresh Rent AVM
      if (rentExpired && apiCallsMade < BUDGET_LIMIT) {
        logger.info(`[Cron Refresh] Refreshing Rent AVM for project ${project.id} (${address})`);

        let estRentCents = 0;
        let estRentLowCents = 0;
        let estRentHighCents = 0;

        if (providerType === "rentcast" && client) {
          apiCallsMade++;
          const rentData = await client.getRentEstimate({ address }, true);
          estRentCents = Math.round(rentData.rent * 100);
          estRentLowCents = Math.round(rentData.rentRangeLow * 100);
          estRentHighCents = Math.round(rentData.rentRangeHigh * 100);
        } else {
          // Mock generation (±15% range matches MockPropertyDataProvider)
          const rent = 1200 + (project.id.charCodeAt(0) * 10) % 2500;
          estRentCents = rent * 100;
          estRentLowCents = Math.round(rent * 0.85) * 100;
          estRentHighCents = Math.round(rent * 1.15) * 100;
        }

        // Save Rent AVM to Prisma PropertyFacts
        await upsertPropertyFacts({
          projectId: project.id,
          estRentCents: BigInt(estRentCents),
          estRentLowCents: BigInt(estRentLowCents),
          estRentHighCents: BigInt(estRentHighCents),
          sourceProvider: providerType === "rentcast" ? "RentCast API" : "MockPropertyProvider v1",
          fetchedAt: now,
        });

        // Replicate to Firestore financials
        firestoreUpdates["financials.projectedMonthlyRent"] = Math.round(estRentCents / 100);
        firestoreUpdates["financials.projectedMonthlyRentSource"] = providerType === "rentcast" ? "rentcast" : "mock";

        updateData.rentSyncedAt = now;
        firestoreUpdates.rentSyncedAt = now.toISOString();
        needsDbUpdate = true;
      }

      // 3. Refresh Market Stats
      if (marketExpired && zip && apiCallsMade < BUDGET_LIMIT) {
        logger.info(`[Cron Refresh] Refreshing Market Stats for zip ${zip} (project ${project.id})`);

        if (providerType === "rentcast" && client) {
          apiCallsMade++;
          // Fetch market stats (updates vendor cache in Firestore)
          await client.getMarketStats({ zipCode: zip }, true);
        }

        updateData.marketSyncedAt = now;
        firestoreUpdates.marketSyncedAt = now.toISOString();
        needsDbUpdate = true;
      }

      // Write updates to DBs if any sync occurred
      if (needsDbUpdate) {
        // Update Prisma
        await updateProjectSync(project.id, updateData);

        // Replicate to Firestore
        const projectRef = adminDb.collection("projects").doc(project.id);
        const snap = await projectRef.get();
        if (snap.exists) {
          await projectRef.update(firestoreUpdates);
        }

        syncedProjects.push(project.id);
      }
    } catch (err) {
      logger.error(`[Cron Refresh] Error syncing project ${project.id}`, err);
    }
  }

  // Telemetry event
  try {
    await telemetry.capture({
      distinctId: userUid,
      event: "cron_refresh_run",
      properties: {
        projectsScanned: projects.length,
        projectsSyncedCount: syncedProjects.length,
        apiCallsMade,
        providerType,
      },
    });
    await telemetry.flush();
  } catch (err) {
    logger.warn("[Cron Refresh] Telemetry failure (non-fatal)", {
      error: err instanceof Error ? err.message : String(err)
    });
  }

  return NextResponse.json({
    success: true,
    scanned: projects.length,
    refreshed: syncedProjects.length,
    apiCallsMade,
  });
}

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError } from "@/lib/firebase-admin/auth-guard";
import { defaultListingsProvider } from "@/lib/providers/listings";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

// GET /api/reil/listings
// Search active listings (sale or rental) with caching
export async function GET(req: NextRequest) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const url = new URL(req.url);
  const zipCode = url.searchParams.get("zipCode") || undefined;
  const city = url.searchParams.get("city") || undefined;
  const state = url.searchParams.get("state") || undefined;
  const listingType = (url.searchParams.get("listingType") || "sale").toLowerCase();

  const minPriceStr = url.searchParams.get("minPrice");
  const maxPriceStr = url.searchParams.get("maxPrice");
  const bedroomsStr = url.searchParams.get("bedrooms");
  const propertyType = url.searchParams.get("propertyType") || undefined;
  const limitStr = url.searchParams.get("limit");
  const offsetStr = url.searchParams.get("offset");

  const minPrice = minPriceStr ? Number(minPriceStr) : undefined;
  const maxPrice = maxPriceStr ? Number(maxPriceStr) : undefined;
  const bedrooms = bedroomsStr ? Number(bedroomsStr) : undefined;
  const limit = limitStr ? Number(limitStr) : 20;
  const offset = offsetStr ? Number(offsetStr) : 0;

  // Validate that we have at least location coordinates or a zip/city/state
  if (!zipCode && !city && !state) {
    return NextResponse.json(
      { error: "Must specify a zipCode, city, or state to search active listings." },
      { status: 400 }
    );
  }

  const params = {
    zipCode,
    city,
    state,
    limit,
    offset,
    bedrooms,
    propertyType,
    minPrice,
    maxPrice,
    status: "Active",
  };

  try {
    logger.info(`[Listings Route] Searching active listings`, { listingType, params });

    let listings = [];
    if (listingType === "rental") {
      listings = await defaultListingsProvider.getRentalListings(params);
    } else {
      listings = await defaultListingsProvider.getSaleListings(params);
    }

    return NextResponse.json({
      success: true,
      listings,
      count: listings.length,
    });
  } catch (err: any) {
    logger.error("[Listings Route] Error searching listings", err);
    return NextResponse.json(
      { error: "Failed to search active listings. Please try again." },
      { status: 502 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError } from "@/lib/firebase-admin/auth-guard";
import { defaultMarketProvider, MarketStatsNotFoundError } from "@/lib/providers/market";
import { logger } from "@/lib/logger";

export const dynamic = "force-dynamic";

export async function GET(req: NextRequest) {
  // Auth Guard Verification
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const url = new URL(req.url);
  const zipCode = url.searchParams.get("zipCode");

  if (!zipCode || zipCode.trim().length !== 5) {
    return NextResponse.json(
      { error: "Invalid or missing zipCode query parameter. Expected a 5-digit US ZIP code." },
      { status: 400 },
    );
  }

  try {
    const stats = await defaultMarketProvider.getMarketStats(zipCode);
    return NextResponse.json({ stats });
  } catch (err: any) {
    if (err instanceof MarketStatsNotFoundError) {
      logger.info(`[Market Stats Route] No statistics found for ZIP: ${zipCode}`);
      return NextResponse.json(
        { error: `No market statistics available for zip code: ${zipCode}` },
        { status: 404 },
      );
    }
    logger.error("[Market Stats Route] Failed to fetch market statistics", err, { zipCode });
    return NextResponse.json(
      { error: err.message || "Failed to fetch market statistics" },
      { status: 502 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import {
  computeClosingCostLines,
  totalClosingCosts,
  type ClosingCostOverrides,
  type ClosingCostInputs,
  type ClosingCostLine,
} from '@/lib/math/closingCosts';
import { jsPDF } from 'jspdf';
import { telemetry } from '@/lib/telemetry';

export const dynamic = 'force-dynamic';

type Params = { params: Promise<{ id: string }> };

const BRAND_DARK  = [18, 16, 20] as [number, number, number];
const BRAND_WHITE = [253, 255, 252] as [number, number, number];
const MID_GRAY    = [127, 127, 127] as [number, number, number];
const LIGHT_GRAY  = [220, 220, 220] as [number, number, number];

function fmtDollar(n: number): string {
  return `$${n.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
}

function csvEscape(v: string | number): string {
  const s = String(v);
  return `"${s.replace(/"/g, '""')}"`;
}

function buildCsv(lines: ClosingCostLine[], total: number, address: string, date: string): string {
  const rows: string[] = [
    `"Closing Ledger — ${address}"`,
    `"Generated","${date}"`,
    '',
    '"Line Item","Type","Computed ($)","Override ($)","Amount ($)"',
  ];

  for (const l of lines) {
    rows.push(
      [
        csvEscape(l.label),
        csvEscape(l.isOverridden ? 'Overridden' : 'Computed'),
        csvEscape(l.computed.toFixed(2)),
        csvEscape(l.isOverridden && l.override !== undefined ? l.override.toFixed(2) : ''),
        csvEscape(l.amount.toFixed(2)),
      ].join(','),
    );
  }

  rows.push('', `"","","","TOTAL",${csvEscape(total.toFixed(2))}`);
  return rows.join('\r\n');
}

function buildPdf(lines: ClosingCostLine[], total: number, address: string, date: string): Uint8Array {
  const doc = new jsPDF({ orientation: 'portrait', unit: 'mm', format: 'a4' });
  const margin = 15;
  const cw = 210 - margin * 2;
  let y = 38;

  // Header banner
  doc.setFillColor(...BRAND_DARK);
  doc.rect(0, 0, 210, 28, 'F');

  const fs = require('fs');
  const path = require('path');
  let logoBase64 = '';
  try {
    const logoPath = path.join(process.cwd(), 'public/brand/PaperWorking_White_full_Logo_.png');
    logoBase64 = `data:image/png;base64,${fs.readFileSync(logoPath).toString('base64')}`;
  } catch {}

  if (logoBase64) {
    doc.addImage(logoBase64, 'PNG', margin, 7, 24.3, 4);
  } else {
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(10);
    doc.setTextColor(...BRAND_WHITE);
    doc.text('PAPERWORKING', margin, 11);
  }

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(7);
  doc.setTextColor(...MID_GRAY);
  doc.text('CLOSING LEDGER EXPORT', margin, 17);

  // Footer
  doc.setDrawColor(...LIGHT_GRAY);
  doc.line(margin, 275, 210 - margin, 275);
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(6);
  doc.setTextColor(...MID_GRAY);
  doc.text(`Generated ${date} · PaperWorking Closing Ledger · Read-only snapshot`, margin, 279);

  // Title
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(14);
  doc.setTextColor(18, 16, 20);
  doc.text('Closing Cost Ledger', margin, y);
  y += 6;

  doc.setFont('helvetica', 'normal');
  doc.setFontSize(9);
  doc.setTextColor(...MID_GRAY);
  doc.text(address, margin, y);
  y += 10;

  // Column headers
  const colX = [margin, margin + 70, margin + 110, margin + 145];
  doc.setFont('helvetica', 'bold');
  doc.setFontSize(7.5);
  doc.setTextColor(80, 80, 80);
  doc.text('Line Item', colX[0], y);
  doc.text('Type', colX[1], y);
  doc.text('Computed', colX[2], y, { align: 'right' });
  doc.text('Amount', 210 - margin, y, { align: 'right' });
  y += 2;

  doc.setDrawColor(...LIGHT_GRAY);
  doc.line(margin, y, 210 - margin, y);
  y += 4;

  // Line items
  doc.setFont('helvetica', 'normal');
  doc.setFontSize(8);

  for (const l of lines) {
    if (y > 265) {
      doc.addPage();
      y = 20;
    }

    const rowColor = l.isOverridden ? ([90, 60, 10] as [number, number, number]) : ([40, 40, 40] as [number, number, number]);
    doc.setTextColor(...rowColor);
    doc.text(l.label, colX[0], y);

    doc.setTextColor(...MID_GRAY);
    doc.text(l.isOverridden ? 'Override' : 'Computed', colX[1], y);

    doc.setTextColor(60, 60, 60);
    doc.text(fmtDollar(l.computed), colX[2], y, { align: 'right' });

    doc.setFont('helvetica', l.isOverridden ? 'bold' : 'normal');
    doc.setTextColor(l.isOverridden ? 200 : 30, l.isOverridden ? 120 : 30, l.isOverridden ? 20 : 30);
    doc.text(fmtDollar(l.amount), 210 - margin, y, { align: 'right' });
    doc.setFont('helvetica', 'normal');

    // basis hint
    y += 4;
    doc.setFontSize(6);
    doc.setTextColor(...LIGHT_GRAY);
    const basisStr = l.basis.length > 70 ? l.basis.slice(0, 67) + '…' : l.basis;
    doc.text(basisStr, colX[0], y);
    doc.setFontSize(8);
    y += 5;
  }

  // Total row
  y += 2;
  doc.setDrawColor(...LIGHT_GRAY);
  doc.line(margin, y, 210 - margin, y);
  y += 5;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(10);
  doc.setTextColor(18, 16, 20);
  doc.text('Total Closing Costs', colX[0], y);
  doc.text(fmtDollar(total), 210 - margin, y, { align: 'right' });

  return doc.output('arraybuffer') as unknown as Uint8Array;
}

export async function GET(req: NextRequest, { params }: Params) {
  // 1. Auth
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;
  const { uid } = auth;

  // 2. Resolve project from Firestore
  const { id } = await params;
  const projectSnap = await adminDb.collection('projects').doc(id).get();
  if (!projectSnap.exists) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 });
  }
  const projectData = projectSnap.data()!;

  // 3. Membership check — no writes; read-only snapshot
  const isOwner  = projectData.ownerUid === uid;
  const isMember = !!projectData.members?.[uid];
  if (!isOwner && !isMember) {
    return NextResponse.json({ error: 'Access denied: not a project member' }, { status: 403 });
  }

  // 3.5 Telemetry
  try {
    const format = new URL(req.url).searchParams.get('format') === 'pdf' ? 'pdf' : 'csv';
    await telemetry.capture({
      distinctId: uid,
      event: 'closing_ledger_exported',
      properties: {
        projectId: id,
        format,
        timestamp: new Date().toISOString(),
      }
    });
  } catch (telemetryErr) {
    console.error('[Export Ledger] Telemetry failed:', telemetryErr);
  }

  // 4. Extract financials — no recomputation, just render what's persisted
  const f: ClosingCostInputs = projectData.financials ?? {};
  const overrides: ClosingCostOverrides = (projectData.financials?.closingCostOverrides as ClosingCostOverrides | undefined) ?? {};
  const lines = computeClosingCostLines(f, overrides);
  const total = totalClosingCosts(lines);

  // 5. Filename helpers
  const address = (projectData.address as string | undefined ?? id)
    .replace(/[^a-zA-Z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .toLowerCase()
    .slice(0, 60);
  const dateStr = new Date().toISOString().split('T')[0];
  const basename = `closing-ledger-${address}-${dateStr}`;

  // 6. Format
  const format = new URL(req.url).searchParams.get('format') === 'pdf' ? 'pdf' : 'csv';
  const displayAddress = (projectData.address as string | undefined) ?? id;

  if (format === 'csv') {
    const csv = buildCsv(lines, total, displayAddress, dateStr);
    return new NextResponse(csv, {
      status: 200,
      headers: {
        'Content-Type': 'text/csv; charset=utf-8',
        'Content-Disposition': `attachment; filename="${basename}.csv"`,
        'Cache-Control': 'no-store',
      },
    });
  }

  // PDF
  const pdfBytes = buildPdf(lines, total, displayAddress, dateStr);
  return new NextResponse(pdfBytes as unknown as BodyInit, {
    status: 200,
    headers: {
      'Content-Type': 'application/pdf',
      'Content-Disposition': `attachment; filename="${basename}.pdf"`,
      'Cache-Control': 'no-store',
    },
  });
}

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError } from "@/lib/firebase-admin/auth-guard";
import { getProject, upsertPropertyFacts, replaceComps, replaceRentalComps, appendValuationSnapshot } from "@/lib/db/projects";
import { defaultPropertyProvider, PropertyNotFoundError } from "@/lib/providers/property";
import { logger } from "@/lib/logger";
import telemetry from "@/lib/telemetry";

export const dynamic = "force-dynamic";

type Params = { params: Promise<{ id: string }> };

// POST /api/reil/projects/:id/property
// Fetches fresh property facts + comps and persists them to the DB.
// Body: { placeId?: string } — if omitted, falls back to project.placeId
export async function POST(req: NextRequest, { params }: Params) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id } = await params;
  const project = await getProject(id);

  if (!project) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  if (project.createdById !== auth.uid) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const body = await req.json().catch(() => ({}));

  // ── forceRefresh guard ─────────────────────────────────────────────────────
  // Without forceRefresh, skip a re-fetch when data was synced within the last hour.
  // forceRefresh=true is admin-only to prevent accidental/abusive API spend.
  const STALE_THRESHOLD_MS = 60 * 60 * 1000; // 1 hour
  const forceRefresh: boolean = body.forceRefresh === true;
  if (forceRefresh) {
    const isAdmin = (auth.token as Record<string, unknown>)?.['admin'] === true;
    if (!isAdmin) {
      return NextResponse.json({ error: 'forceRefresh requires admin claim' }, { status: 403 });
    }
  }
  if (!forceRefresh && project.lastSyncedAt) {
    const age = Date.now() - new Date(project.lastSyncedAt).getTime();
    if (age < STALE_THRESHOLD_MS) {
      return NextResponse.json({
        cached: true,
        lastSyncedAt: project.lastSyncedAt,
        message: 'Property data is fresh (< 1 hour old). Pass forceRefresh: true with admin claim to override.',
      });
    }
  }

  const providerType = (process.env.PROPERTY_DATA_PROVIDER || "mock").toLowerCase();

  let lookupKey: string | undefined | null;
  if (providerType === "rentcast" || providerType === "attom" || providerType === "mashvisor") {
    // External APIs require a full address string, not a Google Maps placeId
    lookupKey = project.addressLine || body.placeId || project.placeId;
  } else {
    // Mock provider hashes the input, prioritizing placeId works fine
    lookupKey = body.placeId ?? project.placeId ?? project.addressLine;
  }

  if (!lookupKey) {
    return NextResponse.json(
      { error: "No address or placeId available to look up property data." },
      { status: 422 },
    );
  }

  // ── Fetch from provider ─────────────────────────────────────────────────────
  // RentCastNotFoundError is thrown when the address has no RentCast record.
  // In that case, return a 200 with { facts: null, manualEntryRequired: true }
  // so the UI can degrade gracefully to manual entry.
  let facts;
  let comps;
  let rentalComps;
  try {
    [facts, comps, rentalComps] = await Promise.all([
      defaultPropertyProvider.getFacts(lookupKey),
      defaultPropertyProvider.getComps(lookupKey),
      defaultPropertyProvider.getRentalComps(lookupKey),
    ]);
  } catch (err: any) {
    if (err instanceof PropertyNotFoundError || err?.name === "PropertyNotFoundError") {
      logger.info("[Property Route] Property not found — degrading to manual entry", {
        projectId: id,
        address: lookupKey,
      });
      // Telemetry: non-fatal, track manual-entry fallback
      try {
        await telemetry.capture({
          distinctId: auth.uid,
          event: "property_enrichment_not_found",
          properties: { projectId: id, provider: providerType, address: lookupKey },
        });
        await telemetry.flush();
      } catch { /* telemetry failures are non-fatal */ }

      return NextResponse.json({
        facts: null,
        compsCount: 0,
        rentalCompsCount: 0,
        manualEntryRequired: true,
        sourceProvider: providerType,
        message: "No property record found for this address. You can enter details manually.",
      });
    }
    // All other errors — log and rethrow as 502
    logger.error("[Property Route] Provider error", err, { projectId: id });
    return NextResponse.json(
      { error: "Property data provider error. Please try again." },
      { status: 502 },
    );
  }

  // ── Persist facts ───────────────────────────────────────────────────────────
  const savedFacts = await upsertPropertyFacts({
    projectId:              id,
    photoUrl:               facts.photoUrl ?? null,
    beds:                   facts.beds ?? null,
    baths:                  facts.baths ?? null,
    sqft:                   facts.sqft ?? null,
    yearBuilt:              facts.yearBuilt ?? null,
    lotSqft:                facts.lotSqft ?? null,
    propertyType:           facts.propertyType ?? null,
    listPriceCents:         facts.listPriceCents  ? BigInt(Math.round(facts.listPriceCents))  : null,
    estRentCents:           facts.estRentCents    ? BigInt(Math.round(facts.estRentCents))    : null,
    lastSoldPriceCents:     typeof facts.lastSoldPriceCents === "number" ? BigInt(Math.round(facts.lastSoldPriceCents)) : null,
    lastSoldDate:           facts.lastSoldDate ?? null,
    // Tax & HOA (Prompt 2)
    annualPropertyTaxCents: typeof facts.annualPropertyTaxCents === "number" ? BigInt(Math.round(facts.annualPropertyTaxCents)) : null,
    taxAssessedValueCents:  typeof facts.taxAssessedValueCents === "number" ? BigInt(Math.round(facts.taxAssessedValueCents)) : null,
    taxAssessedLandValCents: typeof facts.taxAssessedLandValCents === "number" ? BigInt(Math.round(facts.taxAssessedLandValCents)) : null,
    taxAssessedImprovementsValCents: typeof facts.taxAssessedImprovementsValCents === "number" ? BigInt(Math.round(facts.taxAssessedImprovementsValCents)) : null,
    taxYear:                facts.taxYear ?? null,
    hoaMonthlyCents:        typeof facts.hoaMonthlyCents === "number" ? BigInt(Math.round(facts.hoaMonthlyCents)) : null,
    taxSource:              facts.taxSource ?? null,
    // Rent AVM (Prompt 3)
    estRentLowCents:        typeof facts.estRentLowCents === "number" ? BigInt(Math.round(facts.estRentLowCents)) : null,
    estRentHighCents:       typeof facts.estRentHighCents === "number" ? BigInt(Math.round(facts.estRentHighCents)) : null,
    // Value AVM (Prompt 4)
    avmPriceCents:          typeof facts.avmPriceCents === "number" ? BigInt(Math.round(facts.avmPriceCents)) : null,
    avmPriceLowCents:       typeof facts.avmPriceLowCents === "number" ? BigInt(Math.round(facts.avmPriceLowCents)) : null,
    avmPriceHighCents:      typeof facts.avmPriceHighCents === "number" ? BigInt(Math.round(facts.avmPriceHighCents)) : null,
    sourceProvider:         facts.sourceProvider,
    fetchedAt:              facts.fetchedAt,
  });

  // ── Persist comps (replace all sale comps) ──────────────────────────────────
  await replaceComps(
    id,
    comps.map(c => ({
      addressLine:    c.addressLine,
      soldPriceCents: typeof c.soldPriceCents === "number" ? BigInt(Math.round(c.soldPriceCents)) : null,
      soldDate:       c.soldDate ?? null,
      beds:           c.beds ?? null,
      baths:          c.baths ?? null,
      sqft:           c.sqft ?? null,
      distanceMiles:  c.distanceMiles ?? null,
      compType:       "SALE",
      priceCents:     typeof c.priceCents === "number" ? BigInt(Math.round(c.priceCents)) : null,
      correlation:    c.correlation ?? null,
      daysOnMarket:   c.daysOnMarket ?? null,
      status:         c.status ?? null,
      listedDate:     c.listedDate ?? null,
    })),
  );

  // ── Persist rental comps (replace all rental comps) ─────────────────────────
  await replaceRentalComps(
    id,
    rentalComps.map(c => ({
      addressLine:    c.addressLine,
      beds:           c.beds ?? null,
      baths:          c.baths ?? null,
      sqft:           c.sqft ?? null,
      distanceMiles:  c.distanceMiles ?? null,
      compType:       "RENTAL",
      priceCents:     typeof c.rentPriceCents === "number" ? BigInt(Math.round(c.rentPriceCents)) : null,
      correlation:    c.correlation ?? null,
      daysOnMarket:   c.daysOnMarket ?? null,
      status:         c.status ?? null,
      listedDate:     c.listedDate ?? null,
    })),
  );

  // ── Append valuation snapshot (Prompt 4) ───────────────────────────────────
  if (facts.avmPriceCents) {
    try {
      await appendValuationSnapshot({
        projectId: id,
        valueCents: BigInt(Math.round(facts.avmPriceCents)),
        valueLowCents: facts.avmPriceLowCents ? BigInt(Math.round(facts.avmPriceLowCents)) : BigInt(0),
        valueHighCents: facts.avmPriceHighCents ? BigInt(Math.round(facts.avmPriceHighCents)) : BigInt(0),
        source: facts.sourceProvider,
        fetchedAt: facts.fetchedAt,
      });
      logger.info("[Property Route] Appended valuation snapshot", { projectId: id, value: facts.avmPriceCents });
    } catch (err) {
      logger.warn("[Property Route] Failed to append valuation snapshot (non-fatal)", { projectId: id, err });
    }
  }

  // ── Seed Firestore underwriting default with RentCast tax data ──────────────
  // If we got annualPropertyTaxCents from RentCast, write it as the default
  // monthly holding-cost tax into the Firestore project's financials.
  // The user can edit this later in the Hold Interview (Phase 3).
  if (facts.annualPropertyTaxCents) {
    try {
      const { adminDb } = await import("@/lib/firebase/admin");
      const monthlyTax = Math.round(facts.annualPropertyTaxCents / 100 / 12); // cents→dollars, annual→monthly
      const projectRef = adminDb.collection("projects").doc(id);
      const snap = await projectRef.get();
      if (snap.exists) {
        const existing = snap.data();
        const financials = existing?.financials ?? {};
        // Only set if user hasn't already entered a custom value
        if (!financials.holdingCostTaxes || financials.holdingCostTaxes === 0) {
          await projectRef.update({
            "financials.holdingCostTaxes": monthlyTax,
            "financials.operatingExpenseTaxes": monthlyTax,
            "financials.holdingCostTaxesSource": facts.taxSource ?? "rentcast",
            "financials.holdingCostTaxesYear": facts.taxYear ?? null,
          });
          logger.info("[Property Route] Seeded Firestore tax default from RentCast", {
            projectId: id,
            monthlyTax,
            taxYear: facts.taxYear,
          });
        }
      }
    } catch (err) {
      // Non-fatal: Firestore seeding failure shouldn't break property enrichment
      logger.warn("[Property Route] Failed to seed Firestore tax default (non-fatal)", { projectId: id });
    }
  }

  // ── Seed assessed land and improvement values into Firestore (Prompt 18) ─────
  if (facts.taxAssessedValueCents) {
    try {
      const { adminDb } = await import("@/lib/firebase/admin");
      const projectRef = adminDb.collection("projects").doc(id);
      const snap = await projectRef.get();
      if (snap.exists) {
        const existing = snap.data();
        const financials = existing?.financials ?? {};
        const updates: Record<string, any> = {};
        if (financials.taxAssessedLandValue === undefined || financials.taxAssessedLandValue === null) {
          if (facts.taxAssessedLandValCents) {
            updates["financials.taxAssessedLandValue"] = Math.round(facts.taxAssessedLandValCents / 100);
          }
        }
        if (financials.taxAssessedImprovementValue === undefined || financials.taxAssessedImprovementValue === null) {
          if (facts.taxAssessedImprovementsValCents) {
            updates["financials.taxAssessedImprovementValue"] = Math.round(facts.taxAssessedImprovementsValCents / 100);
          }
        }
        if (Object.keys(updates).length > 0) {
          await projectRef.update(updates);
          logger.info("[Property Route] Seeded assessed values to Firestore", { projectId: id, updates });
        }
      }
    } catch (err) {
      logger.warn("[Property Route] Failed to seed assessed values (non-fatal)", { projectId: id, err });
    }
  }

  // ── Seed Rent estimate default into underwriting (Prompt 3) ────────────────
  if (facts.estRentCents) {
    try {
      const { adminDb } = await import("@/lib/firebase/admin");
      const monthlyRent = Math.round(facts.estRentCents / 100);
      const projectRef = adminDb.collection("projects").doc(id);
      const snap = await projectRef.get();
      if (snap.exists) {
        const existing = snap.data();
        const financials = existing?.financials ?? {};
        // Seed grossMonthlyRent if not set
        if (!financials.projectedMonthlyRent || financials.projectedMonthlyRent === 0) {
          await projectRef.update({
            "financials.projectedMonthlyRent": monthlyRent,
            "financials.projectedMonthlyRentSource": "rentcast",
          });
          logger.info("[Property Route] Seeded Firestore projectedMonthlyRent default from RentCast", {
            projectId: id,
            monthlyRent,
          });
        }
      }
    } catch (err) {
      logger.warn("[Property Route] Failed to seed Firestore rent default (non-fatal)", { projectId: id });
    }
  }

  // ── Seed AVM value into financials (Prompt 4) ──────────────────────────────
  if (facts.avmPriceCents) {
    try {
      const { adminDb } = await import("@/lib/firebase/admin");
      const estValue = Math.round(facts.avmPriceCents / 100);
      const projectRef = adminDb.collection("projects").doc(id);
      const snap = await projectRef.get();
      if (snap.exists) {
        await projectRef.update({
          "financials.estimatedCurrentValue": estValue,
          "financials.estimatedCurrentValueSource": "rentcast",
          "financials.estimatedCurrentValueAsOf": facts.fetchedAt.toISOString(),
        });
        logger.info("[Property Route] Seeded Firestore estimatedCurrentValue from RentCast", {
          projectId: id,
          estValue,
        });
      }
    } catch (err) {
      logger.warn("[Property Route] Failed to seed Firestore estimated value (non-fatal)", { projectId: id });
    }
  }

  // ── Telemetry ───────────────────────────────────────────────────────────────
  try {
    await telemetry.capture({
      distinctId: auth.uid,
      event: "property_enrichment_success",
      properties: {
        projectId: id,
        provider: facts.sourceProvider,
        hasTaxData: !!facts.annualPropertyTaxCents,
        hasRentEstimate: !!facts.estRentCents,
        hasValueEstimate: !!facts.avmPriceCents,
        compsCount: comps.length,
        rentalCompsCount: rentalComps.length,
      },
    });
    await telemetry.flush();
  } catch (err) {
    logger.warn("[Property Route] Failed to emit telemetry success (non-fatal)", { projectId: id });
  }

  // ── Update sync timestamps ──────────────────────────────────────────────────
  try {
    const prismaModule = await import("@/lib/prisma");
    await prismaModule.default.reilProject.update({
      where: { id },
      data: {
        lastSyncedAt: facts.fetchedAt,
        valueSyncedAt: facts.fetchedAt,
        rentSyncedAt: facts.fetchedAt,
      },
    });

    const { adminDb } = await import("@/lib/firebase/admin");
    const projectRef = adminDb.collection("projects").doc(id);
    await projectRef.update({
      lastSyncedAt: facts.fetchedAt.toISOString(),
      valueSyncedAt: facts.fetchedAt.toISOString(),
      rentSyncedAt: facts.fetchedAt.toISOString(),
    });
  } catch (err) {
    logger.warn("[Property Route] Failed to update sync timestamps (non-fatal)", { projectId: id, err });
  }

  const serializedFacts = savedFacts ? {
    ...savedFacts,
    listPriceCents: savedFacts.listPriceCents ? Number(savedFacts.listPriceCents) : null,
    estRentCents: savedFacts.estRentCents ? Number(savedFacts.estRentCents) : null,
    lastSoldPriceCents: savedFacts.lastSoldPriceCents ? Number(savedFacts.lastSoldPriceCents) : null,
    annualPropertyTaxCents: savedFacts.annualPropertyTaxCents ? Number(savedFacts.annualPropertyTaxCents) : null,
    hoaMonthlyCents: savedFacts.hoaMonthlyCents ? Number(savedFacts.hoaMonthlyCents) : null,
    taxAssessedValueCents: savedFacts.taxAssessedValueCents ? Number(savedFacts.taxAssessedValueCents) : null,
    taxAssessedLandValCents: savedFacts.taxAssessedLandValCents ? Number(savedFacts.taxAssessedLandValCents) : null,
    taxAssessedImprovementsValCents: savedFacts.taxAssessedImprovementsValCents ? Number(savedFacts.taxAssessedImprovementsValCents) : null,
    avmPriceCents: savedFacts.avmPriceCents ? Number(savedFacts.avmPriceCents) : null,
    avmPriceLowCents: savedFacts.avmPriceLowCents ? Number(savedFacts.avmPriceLowCents) : null,
    avmPriceHighCents: savedFacts.avmPriceHighCents ? Number(savedFacts.avmPriceHighCents) : null,
    estRentLowCents: savedFacts.estRentLowCents ? Number(savedFacts.estRentLowCents) : null,
    estRentHighCents: savedFacts.estRentHighCents ? Number(savedFacts.estRentHighCents) : null,
  } : null;

  return NextResponse.json({
    facts: serializedFacts,
    compsCount: comps.length,
    rentalCompsCount: rentalComps.length,
    sourceProvider: facts.sourceProvider,
    fetchedAt: facts.fetchedAt,
    // Signal to the UI that tax data was sourced
    taxData: facts.annualPropertyTaxCents ? {
      annualPropertyTaxCents: Number(facts.annualPropertyTaxCents),
      taxAssessedValueCents: facts.taxAssessedValueCents ? Number(facts.taxAssessedValueCents) : null,
      taxYear: facts.taxYear,
      hoaMonthlyCents: facts.hoaMonthlyCents ? Number(facts.hoaMonthlyCents) : null,
      source: facts.taxSource,
    } : null,
    rentEstimate: facts.estRentCents ? {
      rent: Number(facts.estRentCents),
      rangeLow: facts.estRentLowCents ? Number(facts.estRentLowCents) : null,
      rangeHigh: facts.estRentHighCents ? Number(facts.estRentHighCents) : null,
      source: 'rentcast',
    } : null,
    valueEstimate: facts.avmPriceCents ? {
      price: Number(facts.avmPriceCents),
      rangeLow: facts.avmPriceLowCents ? Number(facts.avmPriceLowCents) : null,
      rangeHigh: facts.avmPriceHighCents ? Number(facts.avmPriceHighCents) : null,
      source: 'rentcast',
      asOf: facts.fetchedAt,
    } : null,
  });
}

import { NextRequest, NextResponse } from "next/server";
import { requireAuth, isAuthError } from "@/lib/firebase-admin/auth-guard";
import { getProject, appendValuationSnapshot, getValuationSnapshots } from "@/lib/db/projects";
import { defaultPropertyProvider } from "@/lib/providers/property";
import { logger } from "@/lib/logger";
import telemetry from "@/lib/telemetry";

export const dynamic = "force-dynamic";

type Params = { params: Promise<{ id: string }> };

export async function GET(req: NextRequest, { params }: Params) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id } = await params;
  const project = await getProject(id);

  if (!project) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  if (project.createdById !== auth.uid) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const snapshots = await getValuationSnapshots(id);

  // BigInt serialization to number for JSON response
  const serialized = snapshots.map(s => ({
    id: s.id,
    projectId: s.projectId,
    valueCents: Number(s.valueCents),
    valueLowCents: Number(s.valueLowCents),
    valueHighCents: Number(s.valueHighCents),
    source: s.source,
    fetchedAt: s.fetchedAt,
    createdAt: s.createdAt,
  }));

  return NextResponse.json({ snapshots: serialized });
}

export async function POST(req: NextRequest, { params }: Params) {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id } = await params;
  const project = await getProject(id);

  if (!project) {
    return NextResponse.json({ error: "Not found" }, { status: 404 });
  }
  if (project.createdById !== auth.uid) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 });
  }

  const providerType = (process.env.PROPERTY_DATA_PROVIDER || "mock").toLowerCase();
  const lookupKey = project.addressLine || project.placeId;

  if (!lookupKey) {
    return NextResponse.json(
      { error: "No address available to look up valuation." },
      { status: 422 },
    );
  }

  try {
    const avm = await defaultPropertyProvider.getValueEstimate(lookupKey);
    const snapshot = await appendValuationSnapshot({
      projectId: id,
      valueCents: BigInt(avm.priceCents),
      valueLowCents: BigInt(avm.priceLowCents),
      valueHighCents: BigInt(avm.priceHighCents),
      source: avm.source,
      fetchedAt: avm.fetchedAt,
    });

    // Seed/update Firestore estimatedCurrentValue
    try {
      const { adminDb } = await import("@/lib/firebase/admin");
      const estValue = Math.round(avm.priceCents / 100);
      const projectRef = adminDb.collection("projects").doc(id);
      await projectRef.update({
        "financials.estimatedCurrentValue": estValue,
        "financials.estimatedCurrentValueSource": avm.source,
        "financials.estimatedCurrentValueAsOf": avm.fetchedAt.toISOString(),
      });
    } catch (err) {
      logger.warn("[Valuation Route] Failed to update Firestore estimated value (non-fatal)", { projectId: id });
    }

    // Telemetry
    try {
      await telemetry.capture({
        distinctId: auth.uid,
        event: "valuation_snapshot_created",
        properties: {
          projectId: id,
          value: avm.priceCents,
          source: avm.source,
        },
      });
      await telemetry.flush();
    } catch {}

    return NextResponse.json({
      snapshot: {
        id: snapshot.id,
        projectId: snapshot.projectId,
        valueCents: Number(snapshot.valueCents),
        valueLowCents: Number(snapshot.valueLowCents),
        valueHighCents: Number(snapshot.valueHighCents),
        source: snapshot.source,
        fetchedAt: snapshot.fetchedAt,
        createdAt: snapshot.createdAt,
      }
    });
  } catch (err: any) {
    logger.error("[Valuation Route] Failed to fetch value AVM", err, { projectId: id });
    return NextResponse.json(
      { error: err.message || "Failed to trigger valuation update" },
      { status: 502 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { getRentHistoryProvider } from '@/lib/providers/rentHistory';
import telemetry from '@/lib/telemetry';
import { logger } from '@/lib/logger';

export const dynamic = 'force-dynamic';

export async function POST(req: NextRequest) {
  try {
    // 1. Authenticate user
    const auth = await requireAuth(req);
    if (isAuthError(auth)) {
      return auth;
    }
    const { uid } = auth;

    // 2. Parse request body
    let body: { projectId?: string; address?: string };
    try {
      body = await req.json();
    } catch {
      return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    }

    const { projectId, address: customAddress } = body;

    if (!projectId) {
      return NextResponse.json({ error: 'Missing projectId parameter' }, { status: 400 });
    }

    // 3. Fetch project and verify access (B2B isolation check)
    const projectRef = adminDb.collection('projects').doc(projectId);
    const projectSnap = await projectRef.get();

    if (!projectSnap.exists) {
      return NextResponse.json({ error: 'Project not found' }, { status: 404 });
    }

    const projectData = projectSnap.data();
    const targetOrgId = projectData?.organizationId;

    if (!targetOrgId) {
      return NextResponse.json({ error: 'Project has no organization associated' }, { status: 400 });
    }

    // Check organization membership
    const orgRef = adminDb.collection('organizations').doc(targetOrgId);
    const orgSnap = await orgRef.get();
    if (!orgSnap.exists) {
      return NextResponse.json({ error: 'Organization not found' }, { status: 404 });
    }

    const orgData = orgSnap.data();
    const isOwner = orgData?.ownerUid === uid;
    const isTeamMember = orgData?.teamMembers?.some((m: any) => m.id === uid && m.status === 'active');
    const isProjectMember = !!projectData?.members?.[uid];

    if (!isOwner && !isTeamMember && !isProjectMember) {
      return NextResponse.json(
        { error: 'Access denied. You do not have write access to this project.' },
        { status: 403 }
      );
    }

    // 4. Resolve address
    const address = customAddress || projectData?.address;
    if (!address) {
      return NextResponse.json(
        { error: 'No address associated with this project. Please provide an address.' },
        { status: 400 }
      );
    }

    // 5. Query Rent History Provider
    const provider = getRentHistoryProvider();
    let listings = [];
    try {
      listings = await provider.getRentalHistory(address);
    } catch (apiErr: any) {
      logger.error('[RentCast Import] Failed to get rental history', apiErr);

      // Emit failure event
      try {
        await telemetry.capture({
          distinctId: uid,
          event: 'rent_history_imported_failure',
          properties: {
            projectId,
            address,
            error: apiErr.message || String(apiErr),
          },
        });
        await telemetry.flush();
      } catch (telErr) {
        logger.error('Failed to log telemetry', telErr);
      }

      return NextResponse.json(
        { error: 'Failed to retrieve rental history from RentCast API.' },
        { status: 502 }
      );
    }

    // 6. Expand listings into month-by-month rent payments
    // If a property was listed, we assume a tenant was paying that rate from listedDate to removedDate (or present)
    const paymentsMap: Record<string, { period: string; modality: string; grossRevenue: number }> = {};

    for (const listing of listings) {
      if (!listing.price || !listing.listedDate) continue;

      const start = new Date(listing.listedDate);
      const end = listing.removedDate ? new Date(listing.removedDate) : new Date();

      // Loop month by month
      let current = new Date(start.getFullYear(), start.getMonth(), 1);
      const endLimit = new Date(end.getFullYear(), end.getMonth(), 1);

      while (current <= endLimit) {
        const year = current.getFullYear();
        const month = String(current.getMonth() + 1).padStart(2, '0');
        const period = `${year}-${month}`;

        // Deduplicate or overwrite (more recent listings take precedence)
        paymentsMap[period] = {
          period,
          modality: 'long_term_rental',
          grossRevenue: listing.price,
        };

        // Move to next month
        current.setMonth(current.getMonth() + 1);
      }
    }

    // Convert map to sorted array (newest month first)
    const rentPayments = Object.values(paymentsMap).sort((a, b) => b.period.localeCompare(a.period));

    // 7. Emit success event
    try {
      await telemetry.capture({
        distinctId: uid,
        event: 'rent_history_imported_success',
        properties: {
          projectId,
          address,
          count: rentPayments.length,
        },
      });
      await telemetry.flush();
    } catch (telErr) {
      logger.error('Failed to log telemetry', telErr);
    }

    return NextResponse.json({
      success: true,
      rentPayments,
    });

  } catch (error: any) {
    logger.error('[RentCast Import] Handler error', error);
    return NextResponse.json(
      { error: 'Internal server error', details: error.message || String(error) },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { parseDateSafe } from '@/lib/utils/taxService';

export const dynamic = 'force-dynamic';

const DEFAULT_PAGE_SIZE = 100;

export interface ReportTransaction {
  date: string;
  label: string;
  category: string;
  amount: number;
  projectId: string;
  project: string;
  source: 'ledger' | 'legacy';
}

export interface ReportTotals {
  totalTransactions: number;
  totalExpenses: number;
  totalRevenue: number;
  netFlow: number;
}

export async function GET(
  request: NextRequest,
  { params }: { params: Promise<{ period: string }> }
) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  const { period } = await params;
  const searchParams = request.nextUrl.searchParams;
  const orgId = searchParams.get('organizationId');

  if (!orgId) {
    return NextResponse.json({ error: 'Organization ID required' }, { status: 400 });
  }

  // Membership-scoped access check: only members of the org may read its reports
  const userSnap = await adminDb.collection('users').doc(auth.uid).get();
  const profile = userSnap.exists ? userSnap.data() : null;
  let hasAccess = false;
  if (profile) {
    if (profile.personalOrganizationId === orgId) hasAccess = true;
    else if (profile.organizationId === orgId) hasAccess = true;
    else if (profile.memberships?.[orgId]) hasAccess = true;
  }
  if (!hasAccess) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
  }

  const now = new Date();
  let startDate: Date;

  switch (period) {
    case 'monthly':
      startDate = new Date(now);
      startDate.setMonth(now.getMonth() - 1);
      break;
    case 'quarterly':
      startDate = new Date(now);
      startDate.setMonth(now.getMonth() - 3);
      break;
    case 'yearly':
      startDate = new Date(now);
      startDate.setFullYear(now.getFullYear() - 1);
      break;
    default:
      return NextResponse.json(
        { error: 'Invalid period. Use monthly, quarterly, or yearly.' },
        { status: 400 }
      );
  }

  const page = Math.max(1, parseInt(searchParams.get('page') || '1'));
  const limit = Math.min(500, Math.max(1, parseInt(searchParams.get('limit') || String(DEFAULT_PAGE_SIZE))));

  try {
    // Fetch all org projects; no date filter on the project itself — ledger items
    // carry their own dates and a project created before the window can still have
    // transactions inside it.
    const projectsSnap = await adminDb
      .collection('projects')
      .where('organizationId', '==', orgId)
      .get();

    const allTransactions: ReportTransaction[] = [];

    for (const projectDoc of projectsSnap.docs) {
      const projectData = projectDoc.data();
      const projectId = projectDoc.id;
      const projectName = projectData.propertyName || projectData.address || projectId;

      // ── Source 1: ledgerItems sub-collection (Approved items in the window) ──
      const ledgerSnap = await adminDb
        .collection('projects')
        .doc(projectId)
        .collection('ledgerItems')
        .where('createdAt', '>=', startDate)
        .where('createdAt', '<=', now)
        .get();

      for (const doc of ledgerSnap.docs) {
        const item = doc.data();
        if (item.status !== 'Approved') continue;

        const itemDate: Date | null = item.createdAt?.toDate
          ? item.createdAt.toDate()
          : parseDateSafe(item.createdAt);
        if (!itemDate) continue;

        allTransactions.push({
          date: itemDate.toISOString(),
          label: item.description || item.name || 'Unlabeled',
          category: item.category || 'Other',
          amount: item.amount ?? 0,
          projectId,
          project: projectName,
          source: 'ledger',
        });
      }

      // ── Source 2: legacy financials.costs array (approved items in the window) ──
      const legacyCosts: any[] = projectData.financials?.costs ?? [];
      for (const cost of legacyCosts) {
        if (!cost.approved) continue;
        const costDate = parseDateSafe(cost.createdAt);
        if (!costDate || costDate < startDate || costDate > now) continue;

        allTransactions.push({
          date: costDate.toISOString(),
          label: cost.description || cost.name || 'Unlabeled',
          category: cost.category || 'Other',
          amount: cost.amount ?? 0,
          projectId,
          project: projectName,
          source: 'legacy',
        });
      }
    }

    // Most-recent first
    allTransactions.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    // Compute totals from the full untruncated set
    const totalExpenses = allTransactions.reduce((sum, t) => sum + t.amount, 0);
    const totals: ReportTotals = {
      totalTransactions: allTransactions.length,
      totalExpenses,
      totalRevenue: 0,
      netFlow: -totalExpenses,
    };

    // Paginate transaction lines only — totals always reflect the full period
    const totalCount = allTransactions.length;
    const pages = totalCount === 0 ? 0 : Math.ceil(totalCount / limit);
    const offset = (page - 1) * limit;
    const transactions = allTransactions.slice(offset, offset + limit);

    return NextResponse.json({
      period,
      periodStart: startDate.toISOString(),
      periodEnd: now.toISOString(),
      totals,
      transactions,
      count: totalCount,
      page,
      pages,
      timestamp: now.toISOString(),
    });
  } catch (error: any) {
    console.error('[reports] Report generation failure:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import prisma from '@/lib/prisma';
import { generateReportPDF } from '@/lib/reports/pdfGenerator';
import { generatePortfolioCSV, generateTransactionCSV } from '@/lib/reports/csvBuilder';

export async function POST(req: NextRequest) {
  try {
    // 1. Authenticate user
    const auth = await requireAuth(req);
    if (isAuthError(auth)) return auth;
    const { uid } = auth;

    // 2. Fetch user's subscription profile
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ success: false, error: 'User profile not found' }, { status: 404 });
    }
    const userData = userSnap.data() || {};
    const isPremium = userData.subscriptionStatus === 'active' || userData.subscriptionStatus === 'trialing';
    const investorName = userData.displayName || userData.name || 'Valued Investor';
    const orgId = userData.organizationId || 'org_paperworking_seed';

    // 3. Parse & validate request body
    const body = await req.json();
    const { scope = 'portfolio', projectId, format = 'pdf', type = 'portfolio' } = body;

    // 4. Fetch projects for this organization
    const projectsSnap = await adminDb.collection('projects')
      .where('organizationId', '==', orgId)
      .get();

    const projects = projectsSnap.docs.map(doc => ({
      id: doc.id,
      ...doc.data()
    } as any));

    const projectIds = projects.map(p => p.id);

    // Ensure requested project belongs to the user's organization
    if (scope === 'project' && projectId) {
      if (!projectIds.includes(projectId)) {
        return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
      }
    }

    const dateStr = new Date().toISOString().split('T')[0];

    // ────────────────────────────────────────────────────────────────────────
    // CSV FORMAT EXPORT
    // ────────────────────────────────────────────────────────────────────────
    if (format === 'csv') {
      if (type === 'portfolio') {
        const csvContent = generatePortfolioCSV(projects, isPremium);
        return new NextResponse(csvContent, {
          headers: {
            'Content-Type': 'text/csv; charset=utf-8',
            'Content-Disposition': `attachment; filename="paperworking_portfolio_${dateStr}.csv"`,
          }
        });
      } else {
        // Fetch all transactions for this organization's projects (last 90 days)
        const ninetyDaysAgo = new Date();
        ninetyDaysAgo.setDate(ninetyDaysAgo.getDate() - 90);

        const txList = await prisma.transaction.findMany({
          where: {
            projectId: { in: projectIds },
            date: { gte: ninetyDaysAgo }
          },
          orderBy: { date: 'desc' }
        });

        // Map Firestore project propertyNames onto transaction objects
        const projectsMap = new Map<string, string>();
        projects.forEach(p => {
          projectsMap.set(p.id, p.propertyName || p.name || 'Unnamed Project');
        });

        const txListWithProjects = txList.map(t => ({
          ...t,
          project: {
            propertyName: t.projectId ? projectsMap.get(t.projectId) : ''
          }
        }));

        const csvContent = generateTransactionCSV(txListWithProjects, isPremium);
        return new NextResponse(csvContent, {
          headers: {
            'Content-Type': 'text/csv; charset=utf-8',
            'Content-Disposition': `attachment; filename="paperworking_transactions_${dateStr}.csv"`,
          }
        });
      }
    }

    // ────────────────────────────────────────────────────────────────────────
    // PDF FORMAT REPORT
    // ────────────────────────────────────────────────────────────────────────
    // Fetch last 90 days of transactions for PDF inclusion
    const ninetyDaysAgo = new Date();
    ninetyDaysAgo.setDate(ninetyDaysAgo.getDate() - 90);

    const txList = await prisma.transaction.findMany({
      where: {
        projectId: { in: projectIds },
        date: { gte: ninetyDaysAgo }
      },
      orderBy: { date: 'desc' }
    });

    const projectsMap = new Map<string, string>();
    projects.forEach(p => {
      projectsMap.set(p.id, p.propertyName || p.name || 'Unnamed Project');
    });

    const txListWithProjects = txList.map(t => ({
      ...t,
      project: {
        propertyName: t.projectId ? projectsMap.get(t.projectId) : ''
      }
    }));

    const pdfBuffer = await generateReportPDF(
      scope,
      projects,
      txListWithProjects,
      investorName,
      isPremium,
      projectId
    );

    return new NextResponse(new Uint8Array(pdfBuffer), {
      headers: {
        'Content-Type': 'application/pdf',
        'Content-Disposition': `attachment; filename="paperworking_${scope === 'portfolio' ? 'portfolio' : 'project'}_${dateStr}.pdf"`,
      }
    });

  } catch (err: any) {
    console.error('[Generate Report Route] Error:', err);
    return NextResponse.json({ success: false, error: err.message || 'Internal Server Error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { prisma } from '@/lib/prisma';
import { RulesEngine } from '@/lib/banking/rulesEngine';

/**
 * PUT /api/rules/:ruleId — Updates a rule and re-applies it.
 * DELETE /api/rules/:ruleId — Deactivates/deletes a rule.
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 */
export const dynamic = 'force-dynamic';

export async function PUT(
  req: NextRequest,
  { params }: { params: { id: string } }
): Promise<NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id } = params;
  if (!id) {
    return NextResponse.json({ success: false, error: 'id is required' }, { status: 400 });
  }

  let body: Record<string, unknown>;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ success: false, error: 'Invalid JSON body' }, { status: 400 });
  }

  try {
    const updated = await prisma.transactionRule.update({
      where: { id: id },
      data: {
        name: body.name ? String(body.name) : undefined,
        conditions: body.conditions ? (body.conditions as any) : undefined,
        action: body.action ? (body.action as any) : undefined,
        isActive: body.isActive !== undefined ? Boolean(body.isActive) : undefined,
        priority: body.priority !== undefined ? Number(body.priority) : undefined,
        updatedAt: new Date(),
      },
    });

    // Re-apply updated rule
    const applyResults = await RulesEngine.applyRule(id);

    return NextResponse.json({ success: true, rule: updated, applyResults });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[PUT /api/rules/${id}] Failed:`, msg);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}

export async function DELETE(
  req: NextRequest,
  { params }: { params: { id: string } }
): Promise<NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id } = params;
  if (!id) {
    return NextResponse.json({ success: false, error: 'id is required' }, { status: 400 });
  }

  try {
    await prisma.transactionRule.update({
      where: { id: id },
      data: { isActive: false, updatedAt: new Date() },
    });

    return NextResponse.json({ success: true, message: 'Rule deactivated' });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[DELETE /api/rules/${id}] Failed:`, msg);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}

