import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';

export const dynamic = 'force-dynamic';

const PLACES_API_KEY = process.env.GOOGLE_PLACES_API_KEY;

/**
 * GET /api/street-view?lat=<lat>&lng=<lng>&fov=<fov>&heading=<heading>&pitch=<pitch>&w=<w>&h=<h>&metadata=true|false
 *
 * Proxies Google Street View Static API & Metadata requests server-side.
 * GOOGLE_PLACES_API_KEY remains server-side only.
 */
export async function GET(request: NextRequest) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  const placesApiKey = process.env.GOOGLE_PLACES_API_KEY;

  const { searchParams } = request.nextUrl;

  const lat = parseFloat(searchParams.get('lat') ?? '');
  const lng = parseFloat(searchParams.get('lng') ?? '');
  const metadataOnly = searchParams.get('metadata') === 'true';

  if (!isFinite(lat) || !isFinite(lng)) {
    return new NextResponse('lat and lng are required numeric parameters', { status: 400 });
  }

  if (!placesApiKey) {
    return new NextResponse('Street View service not configured', { status: 503 });
  }

  if (metadataOnly) {
    const url = new URL('https://maps.googleapis.com/maps/api/streetview/metadata');
    url.searchParams.set('location', `${lat},${lng}`);
    url.searchParams.set('key', placesApiKey);

    try {
      const res = await fetch(url.toString());
      const data = await res.json();
      return NextResponse.json(data);
    } catch (err) {
      console.error('[street-view] Metadata error:', err);
      return NextResponse.json({ status: 'ZERO_RESULTS' });
    }
  }

  const fov = Math.min(Math.max(parseInt(searchParams.get('fov') ?? '90', 10), 10), 120);
  const heading = searchParams.get('heading') ? parseInt(searchParams.get('heading')!, 10) : undefined;
  const pitch = Math.min(Math.max(parseInt(searchParams.get('pitch') ?? '0', 10), -90), 90);
  const w = Math.min(Math.max(parseInt(searchParams.get('w') ?? '600', 10), 64), 1280);
  const h = Math.min(Math.max(parseInt(searchParams.get('h') ?? '400', 10), 64), 800);

  const url = new URL('https://maps.googleapis.com/maps/api/streetview');
  url.searchParams.set('size', `${w}x${h}`);
  url.searchParams.set('location', `${lat},${lng}`);
  url.searchParams.set('fov', String(fov));
  url.searchParams.set('pitch', String(pitch));
  if (heading !== undefined) {
    url.searchParams.set('heading', String(heading));
  }
  url.searchParams.set('return_error_code', 'true');
  url.searchParams.set('key', placesApiKey);

  try {
    const upstream = await fetch(url.toString(), { cache: 'no-store' });
    if (!upstream.ok) {
      return new NextResponse('Street View unavailable for location', { status: upstream.status });
    }

    const buffer = await upstream.arrayBuffer();
    const contentType = upstream.headers.get('content-type') ?? 'image/jpeg';

    return new NextResponse(buffer, {
      status: 200,
      headers: {
        'Content-Type': contentType,
        'Cache-Control': 'public, max-age=86400, stale-while-revalidate=604800',
        'X-StreetView-Source': 'google-street-view-static',
      },
    });
  } catch (err) {
    console.error('[street-view] Proxy error:', err);
    return new NextResponse('Internal server error', { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import Stripe from 'stripe';
import { adminAuth } from '@/lib/firebase/admin';
import {
  resolvePlanId,
  resolveStripePriceId,
  getCanonicalPlanName,
  PLAN_CATALOG,
  type BillingInterval,
} from '@/lib/stripe/plans';
import { shouldUseMockCheckout, createMockCheckoutSession } from '@/lib/stripe/mockCheckout';

export const dynamic = 'force-dynamic';

function getStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY is not set');
  // @ts-ignore - using latest api version locally
  return new Stripe(key, { apiVersion: '2026-04-22.dahlia' as any });
}

/**
 * POST /api/stripe/checkout
 *
 * Creates a Stripe Checkout Session for subscription sign-up.
 * Supports guest checkout (no auth required) and authenticated checkout.
 *
 * Body: { plan, billingInterval?, userEmail?, idToken? }
 * Returns: { url: string }
 */
export async function POST(request: Request) {
  try {
    const { plan, billingInterval = 'monthly', userEmail, idToken } = await request.json();

    if (!plan) {
      return NextResponse.json({ error: 'Missing required `plan` field.' }, { status: 400 });
    }

    // ── Plan Resolution ──────────────────────────────────
    // Accept any known display name, alias, or canonical ID
    const planId = resolvePlanId(plan);
    if (!planId) {
      const validNames = Object.values(PLAN_CATALOG).map((p) => p.displayName).join(', ');
      return NextResponse.json(
        { error: `Unrecognized plan "${plan}". Valid plans: ${validNames}` },
        { status: 400 }
      );
    }

    const interval: BillingInterval = billingInterval === 'annual' ? 'annual' : 'monthly';
    const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3000';

    // ── Mock Fallback (no Stripe credentials) ────────────
    // Keeps the app runnable without a real Stripe key: simulate a completed
    // Checkout Session and route to the success page, which resolves the mock
    // session id via /api/stripe/session-status. See mockCheckout.ts.
    if (shouldUseMockCheckout()) {
      const { id } = createMockCheckoutSession({ planId, interval, email: userEmail });
      return NextResponse.json({ url: `${appUrl}/checkout/success?session_id=${id}` });
    }

    const stripe = getStripe();

    // ── Auth Verification & Identity Derivation ──
    // A real Stripe Checkout session always requires a signed-in account: the
    // subscription must attach to a Firebase uid, not an email guessed later.
    // (The mock branch above is the only unauthenticated path, and only exists
    // when Stripe itself is unconfigured.)
    if (!idToken) {
      return NextResponse.json({ error: 'Sign in required before checkout.' }, { status: 401 });
    }
    let verifiedUserId: string;
    try {
      const decoded = await adminAuth.verifyIdToken(idToken, true);
      verifiedUserId = decoded.uid;
    } catch {
      return NextResponse.json({ error: 'Invalid auth token.' }, { status: 401 });
    }

    // ── Price ID Resolution ──────────────────────────────
    const priceId = resolveStripePriceId(planId, interval);

    if (!priceId) {
      const planConfig = PLAN_CATALOG[planId];
      const envVarHint = planConfig.envVars[interval].join(' or ');
      return NextResponse.json(
        { error: `No Stripe Price ID configured for "${planConfig.displayName}" (${interval}). Set ${envVarHint} in your environment.` },
        { status: 400 }
      );
    }

    // ── Session Creation ─────────────────────────────────
    const canonicalPlan = getCanonicalPlanName(planId);
    const trialDays = PLAN_CATALOG[planId].trialDays;

    const session = await stripe.checkout.sessions.create({
      line_items: [{ price: priceId, quantity: 1 }],
      mode: 'subscription',

      // Always collect a payment method — even during a free trial.
      // The card is saved and authorised but NOT charged until the trial ends.
      payment_method_collection: 'always',

      success_url: `${appUrl}/checkout/success?session_id={CHECKOUT_SESSION_ID}`,
      cancel_url: `${appUrl}/pricing`,
      customer_email: userEmail ?? undefined,
      client_reference_id: verifiedUserId ?? undefined,
      allow_promotion_codes: true,
      billing_address_collection: 'auto',
      automatic_tax: { enabled: true },
      tax_id_collection: { enabled: true },

      // Cast to any: `trial_settings` isn't in the pinned @types/stripe yet.
      // NOTE: do NOT add `payment_settings` here — it is a Subscriptions API
      // field, not a valid `subscription_data` param, and Stripe rejects it
      // ("Received unknown parameter: subscription_data[payment_settings]"),
      // failing the whole request. In Checkout `mode: 'subscription'` the card
      // collected is already saved as the subscription's default payment method
      // and auto-charged when the trial converts on day 15.
      subscription_data: {
        // 14-day free trial — card collected but not charged until day 15.
        trial_period_days: trialDays > 0 ? trialDays : undefined,

        // Cancel if the card fails at trial end (no silent free-ride).
        ...(trialDays > 0 && {
          trial_settings: {
            end_behavior: { missing_payment_method: 'cancel' },
          },
        }),

        metadata: {
          userId: verifiedUserId || 'guest',
          plan: canonicalPlan,
          planId,
        },
      } as any,

      metadata: {
        userId: verifiedUserId || 'guest',
        plan: canonicalPlan,
        planId,
        billingInterval: interval,
      },
    });

    return NextResponse.json({ url: session.url });
  } catch (error: any) {
    // Stripe SDK errors carry structured, NON-secret identifiers (type/code/param).
    // Log them fully so the cause is visible in server logs (App Hosting) even in prod.
    const isStripeError = typeof error?.type === 'string' && error.type.startsWith('Stripe');
    console.error('[Stripe Checkout] Session creation failed', {
      name: error?.name,
      type: error?.type,
      code: error?.code,
      param: error?.param,
      statusCode: error?.statusCode,
      message: error?.message,
    });

    // Return the actionable reason to the caller. A Stripe config error
    // (e.g. automatic_tax not set up, or a live/test price-vs-key mismatch)
    // is safe to surface — it contains no secret keys. Unexpected errors are
    // only detailed outside production.
    const showDetail = isStripeError || process.env.NODE_ENV !== 'production';
    return NextResponse.json(
      {
        error: 'An error occurred while creating the checkout session. Please try again.',
        ...(showDetail && error?.message ? { detail: error.message } : {}),
        ...(isStripeError ? { type: error.type, code: error.code ?? null, param: error.param ?? null } : {}),
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import Stripe from 'stripe';
import { adminAuth, adminDb } from '@/lib/firebase/admin';

/* ═══════════════════════════════════════════════════════
   POST /api/stripe/invoices

   Authenticated (idToken in body). Returns the user's
   last 24 Stripe invoices, formatted for the billing UI.

   Body:  { idToken: string }
   200:   { invoices: Invoice[] }
   400:   missing idToken / no billing account
   401:   invalid token
   500:   internal error
   ═══════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';

export interface BillingInvoice {
  id: string;
  number: string | null;
  date: string;
  amount: string;
  status: string;
  pdfUrl: string | null;
  hostedUrl: string | null;
}

function getStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY is not set');
  return new Stripe(key, { apiVersion: '2026-04-22.dahlia' as any });
}

function fmtAmount(amount: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency.toUpperCase(),
    minimumFractionDigits: 2,
  }).format(amount / 100);
}

export async function POST(request: Request) {
  try {
    const { idToken } = await request.json();

    if (!idToken) {
      return NextResponse.json({ error: 'Missing idToken.' }, { status: 400 });
    }

    const decoded = await adminAuth.verifyIdToken(idToken).catch(() => null);
    if (!decoded) {
      return NextResponse.json({ error: 'Invalid or expired token.' }, { status: 401 });
    }

    const userSnap = await adminDb.collection('users').doc(decoded.uid).get();
    const stripeCustomerId = userSnap.data()?.stripeCustomerId as string | undefined;

    if (!stripeCustomerId) {
      return NextResponse.json({ invoices: [] }, { status: 200 });
    }

    const stripe = getStripe();
    const [invoiceList, subscriptions] = await Promise.all([
      stripe.invoices.list({ customer: stripeCustomerId, limit: 24, status: undefined }),
      stripe.subscriptions.list({ customer: stripeCustomerId, status: 'active', limit: 1 }),
    ]);

    const invoices: BillingInvoice[] = invoiceList.data.map((inv) => ({
      id: inv.id,
      number: inv.number,
      date: new Date(inv.created * 1000).toLocaleDateString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
      }),
      amount: fmtAmount(inv.amount_due, inv.currency),
      status: inv.status ?? 'unknown',
      pdfUrl: inv.invoice_pdf ?? null,
      hostedUrl: inv.hosted_invoice_url ?? null,
    }));

    const activeSub = subscriptions.data[0] ?? null;
    const currentPeriodEnd: number | null = activeSub
      ? (activeSub as any).current_period_end ?? null
      : null;

    return NextResponse.json({ invoices, currentPeriodEnd }, { status: 200 });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    console.error('[Stripe/Invoices] Error:', msg);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import Stripe from 'stripe';
import { adminAuth, adminDb } from '@/lib/firebase/admin';

/* ═══════════════════════════════════════════════════════
   POST /api/stripe/payment-method

   Authenticated (idToken in body). Returns the user's
   default payment method details from Stripe.

   Body:  { idToken: string }
   200:   { brand, last4, expMonth, expYear, funding } | { paymentMethod: null }
   400:   missing idToken
   401:   invalid token
   500:   internal error
   ═══════════════════════════════════════════════════════ */

export const dynamic = 'force-dynamic';

function getStripe() {
  const key = process.env.STRIPE_SECRET_KEY;
  if (!key) throw new Error('STRIPE_SECRET_KEY is not set');
  return new Stripe(key, { apiVersion: '2026-04-22.dahlia' as any });
}

export async function POST(request: Request) {
  try {
    const { idToken } = await request.json();

    if (!idToken) {
      return NextResponse.json({ error: 'Missing idToken.' }, { status: 400 });
    }

    const decoded = await adminAuth.verifyIdToken(idToken).catch(() => null);
    if (!decoded) {
      return NextResponse.json({ error: 'Invalid or expired token.' }, { status: 401 });
    }

    const userSnap = await adminDb.collection('users').doc(decoded.uid).get();
    const stripeCustomerId = userSnap.data()?.stripeCustomerId as string | undefined;

    if (!stripeCustomerId) {
      return NextResponse.json({ paymentMethod: null }, { status: 200 });
    }

    const stripe = getStripe();

    // Retrieve customer with default payment method expanded
    const customer = await stripe.customers.retrieve(stripeCustomerId, {
      expand: ['invoice_settings.default_payment_method'],
    });

    if ((customer as any).deleted) {
      return NextResponse.json({ paymentMethod: null }, { status: 200 });
    }

    const cust = customer as Stripe.Customer;
    const defaultPM = cust.invoice_settings?.default_payment_method;

    // If the default PM is already expanded as an object, use it directly.
    // Otherwise, try to retrieve it by ID.
    let pm: Stripe.PaymentMethod | null = null;

    if (defaultPM && typeof defaultPM === 'object') {
      pm = defaultPM as Stripe.PaymentMethod;
    } else if (typeof defaultPM === 'string') {
      pm = await stripe.paymentMethods.retrieve(defaultPM);
    }

    // Fallback: list payment methods attached to the customer
    if (!pm) {
      const methods = await stripe.paymentMethods.list({
        customer: stripeCustomerId,
        type: 'card',
        limit: 1,
      });
      if (methods.data.length > 0) {
        pm = methods.data[0];
      }
    }

    if (!pm || !pm.card) {
      return NextResponse.json({ paymentMethod: null }, { status: 200 });
    }

    return NextResponse.json({
      paymentMethod: {
        brand: pm.card.brand,
        last4: pm.card.last4,
        expMonth: pm.card.exp_month,
        expYear: pm.card.exp_year,
        funding: pm.card.funding,
      },
    }, { status: 200 });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : 'Unknown error';
    console.error('[Stripe/PaymentMethod] Error:', msg);
    return NextResponse.json({ error: 'Internal server error.' }, { status: 500 });
  }
}

