import { NextRequest, NextResponse } from 'next/server';
import prisma from '@/lib/prisma';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { attributeTransaction } from '@/lib/banking/attributor';
import { financialsSyncService } from '@/lib/services/financialsSyncService';
import { clearDashboardCache } from '@/lib/cache/dashboardCache';

// Helper to verify ID token and get userId
async function getUserIdFromRequest(req: NextRequest): Promise<string | null> {
  const authHeader = req.headers.get('Authorization');
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return null;
  }
  const idToken = authHeader.split('Bearer ')[1];
  try {
    const decoded = await adminAuth.verifyIdToken(idToken);
    return decoded.uid;
  } catch (error) {
    console.error('[Attribution API] Token verification failed:', error);
    return null;
  }
}

/**
 * PATCH /api/transactions/[plaidId]/attribution
 * Manually attributes a transaction to a project or ignores it.
 */
export async function PATCH(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  const { id } = params;
  const userId = await getUserIdFromRequest(req);
  if (!userId) {
    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const body = await req.json();
    const { projectId, ignore } = body;

    // Verify transaction exists and belongs to the user
    const tx = await prisma.transaction.findUnique({
      where: { id },
    });

    if (!tx) {
      return NextResponse.json({ success: false, error: 'Transaction not found' }, { status: 404 });
    }

    if (tx.userId !== userId) {
      return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
    }

    // Keep track of old projectId to recalculate its KPIs if it changed
    const oldProjectId = tx.projectId;

    // Update the transaction in Postgres
    const updatedTx = await prisma.transaction.update({
      where: { id },
      data: {
        projectId: ignore ? null : projectId,
        reviewedByUser: true,
        attributedAt: (ignore || !projectId) ? null : new Date(),
      },
    });

    // Dismiss active unarchived inbox items for this transaction
    const inboxItemsSnap = await adminDb
      .collection('inboxItems')
      .where('recipientUid', '==', userId)
      .where('metadata.plaidId', '==', id)
      .where('archived', '==', false)
      .get();

    const batch = adminDb.batch();
    inboxItemsSnap.docs.forEach((doc) => {
      batch.update(doc.ref, {
        archived: true,
        read: true,
        actionTaken: 'dismissed',
      });
    });
    await batch.commit();

    // Recalculate KPIs for affected projects
    const affectedProjectIds = new Set<string>();
    if (oldProjectId) affectedProjectIds.add(oldProjectId);
    if (projectId && !ignore) affectedProjectIds.add(projectId);

    for (const projId of affectedProjectIds) {
      await recalculateAndSyncProjectKPIs(projId);
    }

    return NextResponse.json({ success: true, transaction: updatedTx });
  } catch (error: any) {
    console.error('[Attribution API] PATCH Error:', error);
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

/**
 * POST /api/transactions/[plaidId]/attribution/search
 * Re-runs attribution matching engine and returns suggested project.
 */
export async function POST(
  req: NextRequest,
  { params }: { params: { id: string } }
) {
  const { id } = params;
  const userId = await getUserIdFromRequest(req);
  if (!userId) {
    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const tx = await prisma.transaction.findUnique({
      where: { id },
    });

    if (!tx) {
      return NextResponse.json({ success: false, error: 'Transaction not found' }, { status: 404 });
    }

    if (tx.userId !== userId) {
      return NextResponse.json({ success: false, error: 'Forbidden' }, { status: 403 });
    }

    // Call attributeTransaction to find a match
    const attribution = await attributeTransaction(
      {
        plaidId: tx.plaidId,
        name: tx.merchantName || 'Plaid Transaction',
        amount: Number(tx.amount),
        date: tx.date,
        reiCategory: tx.reiCategory || 'unknown',
        merchantName: tx.merchantName,
      },
      userId
    );

    let projectName = null;
    if (attribution.projectId) {
      const projSnap = await adminDb.collection('projects').doc(attribution.projectId).get();
      if (projSnap.exists) {
        projectName = projSnap.data()?.propertyName || projSnap.data()?.address;
      }
    }

    return NextResponse.json({
      success: true,
      projectId: attribution.projectId,
      projectName,
      matchType: attribution.matchType,
      confidence: attribution.confidence,
    });
  } catch (error: any) {
    console.error('[Attribution API] POST Error:', error);
    return NextResponse.json({ success: false, error: error.message }, { status: 500 });
  }
}

/**
 * Recalculates rent and cost actuals in Firestore, updates Postgres financials, and invalidates cache.
 */
async function recalculateAndSyncProjectKPIs(projectId: string) {
  try {
    const projectRef = adminDb.collection('projects').doc(projectId);
    const projectSnap = await projectRef.get();
    if (!projectSnap.exists) return;

    const projectData = projectSnap.data();
    const orgId = projectData?.organizationId;

    // Query all attributed transactions in Postgres
    const txs = await prisma.transaction.findMany({
      where: { projectId },
    });

    // 1. Rent actuals (sum of rental_income)
    const rentTxs = txs.filter((t) => t.reiCategory === 'rental_income');
    const totalRentCents = rentTxs.reduce((sum, t) => sum + Number(t.amount), 0);
    const actualRentalIncome = totalRentCents / 100;

    // 2. Costs (non-income actuals)
    const existingCosts = projectData?.financials?.costs || [];
    // Keep manual entries, filter out Plaid items
    const nonPlaidCosts = existingCosts.filter((c: any) => !c.id.startsWith('tx_') && c.addedBy !== 'system');

    const plaidCosts = txs
      .filter((t) => t.reiCategory !== 'rental_income')
      .map((t) => ({
        id: t.plaidId,
        description: t.merchantName || 'Plaid Transaction',
        amount: Math.abs(Number(t.amount)) / 100,
        approved: true,
        addedBy: 'system',
        createdAt: t.date,
        category: 'Other',
        status: 'Approved',
      }));

    const mergedCosts = [...nonPlaidCosts, ...plaidCosts];
    const actualRehabCost = mergedCosts.reduce((sum, c) => sum + (c.amount || 0), 0);

    const financialsUpdate = {
      ...projectData?.financials,
      actualRentalIncome,
      actualRehabCost,
      costs: mergedCosts,
    };

    // Update Firestore
    await projectRef.update({
      financials: financialsUpdate,
    });

    // Clear dashboard cache
    if (orgId) {
      clearDashboardCache(orgId);
    }

    // Sync to Postgres dealFinancials
    await financialsSyncService.syncProjectFinancials({
      ...projectData,
      id: projectId,
      financials: financialsUpdate,
    } as any);
  } catch (err) {
    console.error(`[KPI Recalculator] Failed to update project ${projectId}:`, err);
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { prisma } from '@/lib/prisma';
import { TransactionIdentificationEngine } from '@/lib/banking/transactionIdentificationEngine';

/**
 * POST /api/transactions/:id/identify
 *
 * Runs the TransactionIdentificationEngine on a specific PlaidRawTransaction or FinancialTransaction ID.
 * Updates the database record with the new classification and returns the IdentificationResult.
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 */
export const dynamic = 'force-dynamic';

export async function POST(
  req: NextRequest,
  { params }: { params: { id: string } }
): Promise<NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { id } = params;
  if (!id) {
    return NextResponse.json({ success: false, error: 'Transaction ID is required' }, { status: 400 });
  }

  try {
    // 1. Fetch raw transaction or financial transaction
    let rawTx = await prisma.plaidRawTransaction.findUnique({
      where: { id },
    });

    if (!rawTx) {
      // Try by plaidTransactionId
      rawTx = await prisma.plaidRawTransaction.findUnique({
        where: { plaidTransactionId: id },
      });
    }

    if (!rawTx) {
      return NextResponse.json({ success: false, error: 'Transaction not found' }, { status: 404 });
    }

    // 2. Fetch associated connection for projectId
    const conn = await prisma.plaidConnection.findUnique({
      where: { id: rawTx.plaidConnectionId },
    });

    // 3. Run identification engine
    const result = await TransactionIdentificationEngine.identify(
      {
        name: rawTx.name,
        amount: Number(rawTx.amount),
        category: rawTx.category,
        personalFinanceCategory: rawTx.personalFinanceCategory as any,
        postedDate: rawTx.postedDate,
        merchantName: rawTx.merchantName,
        direction: rawTx.direction,
      },
      conn?.projectId ?? undefined
    );

    // 4. Update FinancialTransaction if exists
    const ft = await prisma.financialTransaction.findFirst({
      where: { plaidTransactionId: rawTx.id },
    });

    if (ft) {
      await prisma.financialTransaction.update({
        where: { id: ft.id },
        data: {
          category: result.paperWorkingCategory,
          confidenceScore: result.confidenceScore,
          status: result.confidenceScore >= 0.85 ? 'AUTO_APPROVED' : 'PENDING_REVIEW',
          matchedLeaseId: result.suggestedLeaseId ?? null,
          isRecurring: result.isRecurring,
          isSplit: result.isSplitSuggested,
          updatedAt: new Date(),
        },
      });
    }

    return NextResponse.json({
      success: true,
      transactionId: id,
      result,
    });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[POST /api/transactions/${id}/identify] Failed:`, msg);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { prisma } from '@/lib/prisma';
import { TransactionIdentificationEngine } from '@/lib/banking/transactionIdentificationEngine';

/**
 * GET /api/transactions/:projectId/identification-suggestions
 *
 * Retrieves all transactions in PENDING_REVIEW status for a project,
 * runs the TransactionIdentificationEngine on each, and returns suggestions.
 *
 * Auth: Firebase ID token via Authorization: Bearer header
 */
export const dynamic = 'force-dynamic';

export async function GET(
  req: NextRequest,
  { params }: { params: { projectId: string } }
): Promise<NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { projectId } = params;
  if (!projectId) {
    return NextResponse.json({ success: false, error: 'projectId is required' }, { status: 400 });
  }

  try {
    // Fetch all PENDING_REVIEW transactions for this project
    const pendingTransactions = await prisma.financialTransaction.findMany({
      where: {
        projectId,
        status: 'PENDING_REVIEW',
      },
      include: {
        plaidTransaction: true,
      },
      orderBy: { transactionDate: 'desc' },
      take: 50,
    });

    const suggestions = await Promise.all(
      pendingTransactions.map(async (ft) => {
        const rawTx = ft.plaidTransaction;
        const identification = await TransactionIdentificationEngine.identify(
          {
            name: rawTx?.name ?? ft.description ?? ft.payee,
            amount: Number(ft.amount),
            category: rawTx?.category ?? [],
            personalFinanceCategory: rawTx?.personalFinanceCategory as any,
            postedDate: ft.transactionDate,
            merchantName: rawTx?.merchantName ?? ft.payee,
            direction: ft.direction,
          },
          projectId
        );

        return {
          financialTransactionId: ft.id,
          date: ft.transactionDate.toISOString(),
          payee: ft.payee,
          amount: Number(ft.amount),
          direction: ft.direction,
          currentCategory: ft.category,
          identification,
        };
      })
    );

    return NextResponse.json({
      success: true,
      projectId,
      count: suggestions.length,
      suggestions,
    });
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    console.error(`[GET /api/transactions/${projectId}/identification-suggestions] Failed:`, msg);
    return NextResponse.json({ success: false, error: msg }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';

export const dynamic = 'force-dynamic';

const DEFAULT_CATEGORY_PREFERENCES = {
  syndication: { inbox: true, email: true, push: true },
  bids: { inbox: true, email: true, push: false },
  tasks: { inbox: true, email: true, push: false },
  deadlines: { inbox: true, email: true, push: true },
  billing: { inbox: true, email: true, push: false },
  alerts: { inbox: true, email: true, push: true },
};

const DEFAULT_QUIET_HOURS = {
  enabled: false,
  start: '22:00',
  end: '08:00',
  timezone: 'America/New_York',
};

// Helper to authenticate request and return UID
async function authenticateRequest(request: NextRequest): Promise<string | null> {
  const authHeader = request.headers.get('Authorization');
  if (!authHeader?.startsWith('Bearer ')) {
    return null;
  }
  const idToken = authHeader.split('Bearer ')[1];
  try {
    const decoded = await adminAuth.verifyIdToken(idToken);
    return decoded.uid;
  } catch (err) {
    console.error('[GDPR] Token verification failed:', err);
    return null;
  }
}

/**
 * GET /api/user/gdpr
 * Exports all user notification data, preferences, and queued items.
 */
export async function GET(request: NextRequest) {
  try {
    const uid = await authenticateRequest(request);
    if (!uid) {
      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    }

    // 1. Fetch user profile preferences
    const userDoc = await adminDb.collection('users').doc(uid).get();
    const userData = userDoc.exists ? userDoc.data() : null;
    const preferences = userData?.preferences || {};

    // 2. Query all user notifications
    const notificationsSnap = await adminDb
      .collection('notifications')
      .where('recipientId', '==', uid)
      .get();
    const notifications = notificationsSnap.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));

    // 3. Query all user queued emails
    const queuedEmailsSnap = await adminDb
      .collection('queued_emails')
      .where('recipientId', '==', uid)
      .get();
    const queuedEmails = queuedEmailsSnap.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));

    // 4. Log GDPR Export action to auditLog
    await adminDb.collection('auditLog').add({
      type: 'gdpr_export',
      userId: uid,
      at: FieldValue.serverTimestamp(),
    });

    return NextResponse.json({
      success: true,
      export: {
        profile: {
          email: userData?.email || null,
          displayName: userData?.displayName || '',
          preferences,
        },
        notifications,
        queuedEmails,
      },
    });
  } catch (err: any) {
    console.error('[GDPR] GET Export failed:', err);
    return NextResponse.json({ success: false, error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * DELETE /api/user/gdpr
 * Deletes all notification and email records for the user, clears push tokens,
 * and resets preferences to default values.
 */
export async function DELETE(request: NextRequest) {
  try {
    const uid = await authenticateRequest(request);
    if (!uid) {
      return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    }

    const batch = adminDb.batch();

    // 1. Delete notifications in batches
    const notificationsSnap = await adminDb
      .collection('notifications')
      .where('recipientId', '==', uid)
      .get();
    notificationsSnap.docs.forEach((doc) => {
      batch.delete(doc.ref);
    });

    // 2. Delete queued emails in batches
    const queuedEmailsSnap = await adminDb
      .collection('queued_emails')
      .where('recipientId', '==', uid)
      .get();
    queuedEmailsSnap.docs.forEach((doc) => {
      batch.delete(doc.ref);
    });

    // 3. Reset user profile preferences & clear FCM tokens
    const userRef = adminDb.collection('users').doc(uid);
    batch.update(userRef, {
      fcmTokens: [],
      'preferences.pushEnabled': true,
      'preferences.emailEnabled': true,
      'preferences.autoArchiveDays': 30,
      'preferences.quietHours': DEFAULT_QUIET_HOURS,
      'preferences.categories': DEFAULT_CATEGORY_PREFERENCES,
    });

    // 4. Log GDPR Deletion action to auditLog
    const auditRef = adminDb.collection('auditLog').doc();
    batch.set(auditRef, {
      type: 'gdpr_deletion',
      userId: uid,
      at: FieldValue.serverTimestamp(),
    });

    // Commit all deletions and updates atomically
    await batch.commit();

    console.log(`[GDPR] Successfully executed deletion workflow for user: ${uid}`);

    return NextResponse.json({ success: true });
  } catch (err: any) {
    console.error('[GDPR] DELETE Deletion failed:', err);
    return NextResponse.json({ success: false, error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { NotificationService } from '@/lib/services/notificationService';

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  try {
    // collectionGroup query aggregates 'vendorRequests' across all parent projects
    const snapshot = await adminDb
      .collectionGroup('vendorRequests')
      .where('vendorUid', '==', auth.uid)
      .get();

    const requests: any[] = snapshot.docs.map(doc => {
      const data = doc.data();
      return {
        id: doc.id,
        ...data,
        requestedAt: data.requestedAt?.toDate 
          ? data.requestedAt.toDate().toISOString() 
          : (data.requestedAt || new Date().toISOString()),
      };
    });

    // Enrich requests with their parent project data
    const projectIds = Array.from(new Set(requests.map(r => r.projectId).filter(Boolean)));
    const projectDocs = await Promise.all(
      projectIds.map(id => adminDb.collection('projects').doc(id).get())
    );

    const projectsMap: Record<string, any> = {};
    projectDocs.forEach(doc => {
      if (doc.exists) {
        projectsMap[doc.id] = doc.data();
      }
    });

    const enrichedRequests = requests.map(req => {
      const project = projectsMap[req.projectId];
      return {
        ...req,
        dealName: project?.propertyName || 'Unknown Project',
        location: project?.address || 'Unknown Location',
        dealPhase: project?.status || 'Sourcing',
        investor: project?.leadEmail || 'Lead Investor',
        actionItems: project?.actionItems || [],
      };
    });

    // Sort by requestedAt descending
    enrichedRequests.sort((a: any, b: any) => {
      const dateA = new Date(a.requestedAt).getTime();
      const dateB = new Date(b.requestedAt).getTime();
      return dateB - dateA;
    });

    return NextResponse.json({ success: true, requests: enrichedRequests });
  } catch (error) {
    console.error('Vendor requests query failed:', error);
    return NextResponse.json({ error: 'Failed to load requests' }, { status: 500 });
  }
}

export async function PUT(request: NextRequest) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  try {
    const body = await request.json();
    const { requestId, projectId, quotedFee, message, status } = body;

    // Support DECLINED status (no quotedFee required) or QUOTED status (quotedFee required)
    const targetStatus = status === 'DECLINED' ? 'DECLINED' : 'QUOTED';

    if (!requestId || !projectId) {
      return NextResponse.json({ error: 'Missing required fields' }, { status: 400 });
    }

    if (targetStatus === 'QUOTED' && !quotedFee) {
      return NextResponse.json({ error: 'quotedFee is required when submitting a quote' }, { status: 400 });
    }

    const docRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('vendorRequests')
      .doc(requestId);

    const docSnap = await docRef.get();
    if (!docSnap.exists) {
      return NextResponse.json({ error: 'Request not found' }, { status: 404 });
    }

    const requestData = docSnap.data();
    if (requestData?.vendorUid !== auth.uid) {
      return NextResponse.json({ error: 'Unauthorized to update this request' }, { status: 403 });
    }

    // Build update payload
    const updatePayload: Record<string, any> = {
      status: targetStatus,
      ...(targetStatus === 'QUOTED'
        ? { quotedFee: Number(quotedFee), message: message || '', quotedAt: new Date() }
        : { declinedAt: new Date() }),
    };

    const batch = adminDb.batch();

    // 1. Update vendorRequest
    batch.update(docRef, updatePayload);

    // 2. Update vendorAssignment
    const assignmentRef = adminDb
      .collection('projects')
      .doc(projectId)
      .collection('vendorAssignments')
      .doc(requestId);

    const assignmentSnap = await assignmentRef.get();
    if (assignmentSnap.exists) {
      batch.update(assignmentRef, {
        status: targetStatus === 'QUOTED' ? 'ACCEPTED' : 'DECLINED',
        ...(targetStatus === 'QUOTED' ? { quotedFee: Number(quotedFee) } : {}),
        updatedAt: new Date(),
      });
    }

    // 3. Update vendorInbox
    const inboxRef = adminDb
      .collection('users')
      .doc(auth.uid)
      .collection('vendorInbox')
      .doc(requestId);

    const inboxSnap = await inboxRef.get();
    if (inboxSnap.exists) {
      batch.update(inboxRef, {
        status: targetStatus === 'QUOTED' ? 'ACCEPTED' : 'DECLINED',
      });
    }

    await batch.commit();

    // Notify investor
    const projectSnap = await adminDb.collection('projects').doc(projectId).get();
    if (projectSnap.exists) {
      const projectData = projectSnap.data();
      const ownerUid = projectData?.ownerUid || projectData?.createdBy;

      if (ownerUid) {
        await NotificationService.createNotification({
          type: targetStatus === 'QUOTED' ? 'VENDOR_BID' : 'VENDOR_BID',
          recipientId: ownerUid,
          actor: { uid: auth.uid, name: auth.token.name || auth.token.email || 'A vendor' },
          objectReference: { 
            projectId, 
            task: targetStatus === 'QUOTED' ? 'Quote Proposal' : 'Request Declined', 
            dealAddress: projectData?.propertyName || 'the project',
            ...(targetStatus === 'QUOTED' ? { amount: `$${Number(quotedFee).toLocaleString()}` } : {}),
            vendor: auth.token.name || auth.token.email || 'A vendor'
          },
          deepLinkUrl: `/dashboard/projects/${projectId}/vendors`,
        });
      }
    }

    return NextResponse.json({ success: true });
  } catch (error) {
    console.error('Failed to update vendor request:', error);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { isSubscriptionActive } from '@/lib/stripe/subscription';
import type { UserProfile } from '@/types/user';
import { NotificationService } from '@/lib/services/notificationService';

export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { idToken, projectId, vendorUid, message } = body;

    if (!idToken || !projectId || !vendorUid || !message) {
      return NextResponse.json(
        { error: 'Missing required fields: idToken, projectId, vendorUid, message' },
        { status: 400 },
      );
    }

    // Authenticate user
    const decoded = await adminAuth.verifyIdToken(idToken);
    const uid = decoded.uid;

    // Fetch user profile
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (!userSnap.exists) {
      return NextResponse.json({ error: 'User profile not found.' }, { status: 404 });
    }
    const profile = userSnap.data() as UserProfile;

    // Verify subscription access
    const hasActiveSub = isSubscriptionActive(profile);
    if (!hasActiveSub) {
      return NextResponse.json(
        { error: 'An active subscription is required to request vendor quotes.' },
        { status: 403 },
      );
    }

    // Verify project exists and user has access
    const dealSnap = await adminDb.collection('projects').doc(projectId).get();
    if (!dealSnap.exists) {
      return NextResponse.json({ error: 'Project not found.' }, { status: 404 });
    }
    const dealData = dealSnap.data();

    const targetOrgId = dealData?.organizationId;
    let hasAccess = false;
    if (targetOrgId) {
      if (profile?.personalOrganizationId === targetOrgId) hasAccess = true;
      else if (profile?.organizationId === targetOrgId) hasAccess = true;
      else if (profile?.memberships && profile.memberships[targetOrgId]) hasAccess = true;
    }

    if (!hasAccess) {
      return NextResponse.json({ error: 'Access denied for this project.' }, { status: 403 });
    }

    // Verify vendor exists
    const vendorSnap = await adminDb.collection('users').doc(vendorUid).get();
    if (!vendorSnap.exists) {
      return NextResponse.json({ error: 'Vendor not found.' }, { status: 404 });
    }
    const vendorData = vendorSnap.data();

    // Create the vendor request
    const requestsRef = adminDb.collection('projects').doc(projectId).collection('vendorRequests');
    const newRequestDoc = await requestsRef.add({
      projectId,
      vendorUid,
      message,
      status: 'PENDING',
      requestedAt: new Date(),
      requestedBy: uid,
    });

    // Send notification to the vendor
    await NotificationService.createNotification({
      type: 'VENDOR_LEAD',
      recipientId: vendorUid,
      actor: { uid: uid, name: profile.displayName || profile.email || 'A user' },
      objectReference: { projectId, task: 'Quote Request', dealAddress: dealData?.address?.street || 'the project' },
      deepLinkUrl: `/dashboard/projects/${projectId}/vendors`,
    });

    return NextResponse.json({ success: true, requestId: newRequestDoc.id });
  } catch (error: any) {
    console.error('[Vendor Request] Error:', error);
    if (error.code === 'auth/id-token-expired') {
      return NextResponse.json({ error: 'Session expired.' }, { status: 401 });
    }
    return NextResponse.json(
      { error: 'Failed to submit vendor request.', details: error.message },
      { status: 500 },
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError } from '@/lib/firebase-admin/auth-guard';
import { adminDb } from '@/lib/firebase/admin';

export const dynamic = "force-dynamic";

export async function GET(request: NextRequest) {
  const auth = await requireAuth(request);
  if (isAuthError(auth)) return auth;

  const { searchParams } = new URL(request.url);
  const stateCode = searchParams.get('state');
  const type = searchParams.get('type');
  const zip = searchParams.get('zip');
  const id = searchParams.get('id');

  try {
    if (id) {
      const doc = await adminDb.collection('users').doc(id).get();
      if (doc.exists) {
        const data = doc.data();
        if (data && data.accountType === 'vendor' && data.subscriptionStatus === 'active') {
          return NextResponse.json({ success: true, vendors: [{ id: doc.id, ...data }] });
        }
      }
      return NextResponse.json({ success: true, vendors: [] });
    }

    let query = adminDb
      .collection('users')
      .where('accountType', '==', 'vendor')
      .where('subscriptionStatus', '==', 'active');

    if (stateCode && stateCode !== 'All') {
      query = query.where('licensingStates', 'array-contains', stateCode);
    }

    if (type && type !== 'All') {
      query = query.where('type', '==', type);
    }

    const snapshot = await query.get();

    let vendors = snapshot.docs.map(doc => {
      const data = doc.data();
      return {
        id: doc.id,
        ...data
      };
    });

    if (zip) {
      vendors = vendors.filter((v: any) => v.serviceAreas && v.serviceAreas.includes(zip));
    }

    return NextResponse.json({ success: true, vendors });
  } catch (error) {
    console.error('Vendor query failed:', error);
    return NextResponse.json({ error: 'Failed to query vendors' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { createHmac, timingSafeEqual } from 'crypto';
import { logger } from '@/lib/logger';

export const dynamic = 'force-dynamic';

/**
 * POST /api/webhooks/bridge
 *
 * Ingests Bridge Interactive RESO status-change webhooks.
 *
 * Fast-path design: validates the HMAC signature, enqueues the payload, and
 * returns 200 within milliseconds. Heavy processing (Firestore queries + deal
 * transitions) is deferred to the /api/worker/drain consumer.
 *
 * Bridge retries on non-2xx with exponential back-off, so keeping this handler
 * fast prevents duplicate delivery under load.
 *
 * Set BRIDGE_WEBHOOK_SECRET to enable HMAC verification (recommended in prod).
 */

function verifyHmacSignature(body: string, signature: string | null, secret: string): boolean {
  if (!signature) return false;
  const expected = createHmac('sha256', secret).update(body).digest('hex');
  try {
    return timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
  } catch {
    return false;
  }
}

export async function POST(request: Request) {
  const webhookSecret = process.env.BRIDGE_WEBHOOK_SECRET;
  if (!webhookSecret) {
    logger.error('[Bridge Webhook] BRIDGE_WEBHOOK_SECRET not configured — rejecting request');
    return NextResponse.json({ error: 'Webhook endpoint not configured' }, { status: 503 });
  }

  const rawBody = await request.text();
  const sig =
    request.headers.get('x-bridge-signature') ??
    request.headers.get('x-hub-signature-256');
  if (!verifyHmacSignature(rawBody, sig, webhookSecret)) {
    logger.warn('[Bridge Webhook] HMAC signature mismatch — rejecting payload');
    return NextResponse.json({ error: 'invalid_signature' }, { status: 401 });
  }

  let payload: unknown;
  try {
    payload = JSON.parse(rawBody);
  } catch {
    return NextResponse.json({ error: 'invalid_json' }, { status: 400 });
  }

  try {
    const { jobQueue } = await import('@/lib/queue/jobQueue');
    const jobId = await jobQueue.enqueue('webhook_process', payload);
    logger.info('[Bridge Webhook] Payload accepted', { jobId });
    return NextResponse.json({ accepted: true, jobId });
  } catch (queueError: any) {
    // Redis unavailable — fall back to inline processing so we never silently drop events.
    logger.warn('[Bridge Webhook] Queue unavailable — falling back to sync processing', { detail: queueError.message });
    try {
      const { processWebhookPayload } = await import('@/lib/services/webhookProcessor');
      const result = await processWebhookPayload(payload);
      if (!result.success) {
        return NextResponse.json({ error: result.reason ?? 'processing_failed' }, { status: 422 });
      }
      return NextResponse.json({ processed: true, affectedDeals: result.count });
    } catch (syncError) {
      logger.error('[Bridge Webhook] Sync fallback failed', syncError);
      return NextResponse.json({ error: 'internal_server_error' }, { status: 500 });
    }
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { adminDb } from '@/lib/firebase/admin';
import { logger } from '@/lib/logger';
import { createHmac, timingSafeEqual } from 'crypto';
import { FieldValue } from 'firebase-admin/firestore';
import { syncFractionalInvestorFromCommitment } from '@/lib/firebase/syncFractionalInvestors';
import { CommitmentStatus } from '@/types/schema';

/**
 * POST /api/webhooks/docusign
 *
 * DocuSign Connect webhook — receives real-time envelope status updates.
 *
 * Security: HMAC-SHA256 signature verified against DOCUSIGN_WEBHOOK_HMAC_KEY.
 * DocuSign sets the signature in the X-DocuSign-Signature-1 header.
 *
 * Registration:
 *   DocuSign Admin → Integrations → Connect → Add Configuration
 *   URL: {NEXT_PUBLIC_APP_URL}/api/webhooks/docusign
 *   Events: envelope-completed, envelope-declined, envelope-voided
 *
 * This route is the async reconciliation path. The polling route
 * /api/esign/status/[envelopeId] handles synchronous status checks.
 */

function verifySignature(body: string, signature: string | null, hmacKey: string): boolean {
  if (!signature) return false;
  const expected = createHmac('sha256', hmacKey).update(body).digest('base64');
  try {
    return timingSafeEqual(Buffer.from(expected), Buffer.from(signature));
  } catch {
    return false;
  }
}

export async function POST(req: NextRequest) {
  const hmacKey = process.env.DOCUSIGN_WEBHOOK_HMAC_KEY;
  if (!hmacKey) {
    logger.error('[DocuSign Webhook] DOCUSIGN_WEBHOOK_HMAC_KEY not configured — rejecting request');
    return NextResponse.json({ error: 'Webhook endpoint not configured' }, { status: 503 });
  }

  const rawBody = await req.text();
  const signature = req.headers.get('X-DocuSign-Signature-1');

  if (!verifySignature(rawBody, signature, hmacKey)) {
    logger.warn('[webhooks/docusign] Invalid HMAC signature');
    return NextResponse.json({ error: 'Invalid signature' }, { status: 401 });
  }

  let event: Record<string, unknown>;
  try {
    event = JSON.parse(rawBody);
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 });
  }

  // DocuSign Connect sends the envelope status in different shapes depending on
  // the configuration (JSON vs XML). We handle the JSON format.
  const envelopeId  = (event.envelopeId ?? (event as any).data?.envelopeId) as string | undefined;
  const rawStatus   = (event.status ?? (event as any).data?.envelopeSummary?.status) as string | undefined;
  const completedAt = (event.completedDateTime ?? (event as any).data?.envelopeSummary?.completedDateTime) as string | undefined;

  if (!envelopeId || !rawStatus) {
    logger.warn('[webhooks/docusign] Missing envelopeId or status in payload');
    return NextResponse.json({ received: true }); // Return 200 to prevent DocuSign retries for malformed events
  }

  const status = rawStatus.toLowerCase();
  const isFinal = status === 'completed' || status === 'declined' || status === 'voided';

  if (!isFinal) {
    // Non-terminal events (sent, delivered) — acknowledge and ignore
    return NextResponse.json({ received: true });
  }

  try {
    // Find the envelope across all projects
    const snap = await adminDb
      .collectionGroup('esign_envelopes')
      .where('envelopeId', '==', envelopeId)
      .limit(1)
      .get();

    if (snap.empty) {
      logger.warn('[webhooks/docusign] Envelope not found in Firestore', { envelopeId });
      return NextResponse.json({ received: true });
    }

    const envDoc = snap.docs[0];
    const envData = envDoc.data();
    const now = new Date().toISOString();

    // Update envelope record
    const envelopeUpdate: Record<string, unknown> = {
      status:    status,
      updatedAt: now,
    };
    if (completedAt) envelopeUpdate.completedAt = completedAt;

    await envDoc.ref.update(envelopeUpdate);

    // Update parent DealDocument
    if (envData.projectId && envData.documentId) {
      let eSignStatus: string;
      if (status === 'completed') eSignStatus = 'Signed';
      else if (status === 'declined') eSignStatus = 'Declined';
      else eSignStatus = 'Not Required';

      const docUpdates: Record<string, unknown> = { eSignStatus };
      if (status === 'completed') {
        docUpdates.eSignedAt = completedAt ? new Date(completedAt) : new Date();
      }

      await adminDb
        .collection('projects')
        .doc(envData.projectId as string)
        .collection('documents')
        .doc(envData.documentId as string)
        .update(docUpdates);

      // Card F2.5 Subscriptions — if the document is a subscription agreement, reconcile the commitment status
      const docIdStr = String(envData.documentId);
      if (docIdStr.startsWith('sub_agreement_')) {
        const commitmentId = docIdStr.replace('sub_agreement_', '');
        const commitmentRef = adminDb
          .collection('projects')
          .doc(envData.projectId as string)
          .collection('commitments')
          .doc(commitmentId);

        const commitmentSnap = await commitmentRef.get();
        if (commitmentSnap.exists) {
          const commitmentData = commitmentSnap.data()!;
          const currentStatus = commitmentData.status;
          const nextStatus = status === 'completed' ? 'signed' : (status === 'declined' ? 'soft-committed' : currentStatus);

          if (nextStatus !== currentStatus) {
            const transition = {
              fromStatus: currentStatus || null,
              toStatus: nextStatus,
              timestamp: new Date().toISOString(),
              actor: 'DocuSign Connect Webhook',
              evidence: `Envelope ${envelopeId} reconciled with status ${status}`,
            };

            await commitmentRef.update({
              status: nextStatus,
              updatedAt: new Date(),
              transitions: FieldValue.arrayUnion(transition),
            });

            await syncFractionalInvestorFromCommitment(envData.projectId as string, {
              id: commitmentId,
              name: commitmentData.name,
              email: commitmentData.email ?? null,
              amountCents: commitmentData.amountCents,
              status: nextStatus as CommitmentStatus,
            });
          }
        }
      }
    }

    // Send signature completion notification (failure-isolated)
    try {
      const { NotificationService } = await import('@/lib/services/notificationService');
      const { adminAuth } = await import('@/lib/firebase/admin');

      const projectSnap = await adminDb.collection('projects').doc(envData.projectId as string).get();
      if (projectSnap.exists) {
        const projectData = projectSnap.data()!;
        const dealAddress = projectData.propertyName || projectData.address?.street || 'the project';
        const ownerUid = projectData.ownerUid || projectData.createdBy;

        const signerUser = await adminAuth.getUserByEmail(envData.signerEmail as string).catch(() => null);

        // Notify Lead Investor
        if (ownerUid) {
          await NotificationService.createNotification({
            recipientId: ownerUid,
            type: 'DOCUMENT_SIGNED',
            actor: { uid: signerUser?.uid || 'external', name: envData.signerName as string },
            objectReference: {
              projectId: envData.projectId as string,
              dealAddress,
              documentName: envData.documentName as string,
              task: `${envData.signerName} has signed the document '${envData.documentName}'`
            },
            deepLinkUrl: `/dashboard/projects/${envData.projectId}`
          });
        }

        // Notify Signer if they are a registered user
        if (signerUser?.uid && signerUser.uid !== ownerUid) {
          await NotificationService.createNotification({
            recipientId: signerUser.uid,
            type: 'DOCUMENT_SIGNED',
            actor: { uid: ownerUid || 'system', name: 'PaperWorking' },
            objectReference: {
              projectId: envData.projectId as string,
              dealAddress,
              documentName: envData.documentName as string,
              task: `You have successfully signed the document '${envData.documentName}'`
            },
            deepLinkUrl: `/dashboard/projects/${envData.projectId}`
          });
        }
      }
    } catch (notifErr: any) {
      logger.error('[webhooks/docusign] Failed to send signature completion notifications:', notifErr.message);
    }

    logger.info('[webhooks/docusign] Envelope reconciled', { envelopeId, status });
    return NextResponse.json({ received: true });
  } catch (error) {
    logger.error('[webhooks/docusign] Error reconciling envelope', error instanceof Error ? error : undefined);
    // Return 500 so DocuSign retries
    return NextResponse.json({ error: 'Internal error' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { verifyDealInviteToken } from '@/lib/email/dealInvite';

export interface DealMessagePayload {
  id: string;
  dealId: string;
  senderEmail: string;
  senderName: string;
  text: string;
  source: 'platform' | 'email_inbound';
  createdAt: string;
}

// In-memory messages store for testing/demo
const MESSAGES_STORE: DealMessagePayload[] = [];

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { from, token, text, slug } = body;

    if (!text || (!token && !slug)) {
      return NextResponse.json(
        { error: 'Missing required email payload fields (text, token/slug).' },
        { status: 400 }
      );
    }

    let dealId = slug || 'deal_123mainst';
    let senderEmail = from || 'external_sender@example.com';
    let senderName = senderEmail.split('@')[0];

    if (token) {
      const verified = verifyDealInviteToken(token);
      if (verified) {
        dealId = verified.dealId || verified.slug;
        senderEmail = verified.inviteeEmail || senderEmail;
        senderName = senderEmail.split('@')[0];
      }
    }

    const newMessage: DealMessagePayload = {
      id: `msg_${Date.now()}`,
      dealId,
      senderEmail,
      senderName,
      text,
      source: 'email_inbound',
      createdAt: new Date().toISOString(),
    };

    MESSAGES_STORE.push(newMessage);

    return NextResponse.json({
      success: true,
      message: 'Inbound email message recorded successfully.',
      record: newMessage,
    });
  } catch (err: any) {
    return NextResponse.json(
      { error: err.message || 'Internal server error processing inbound email webhook.' },
      { status: 500 }
    );
  }
}

export async function GET(req: NextRequest) {
  const { searchParams } = new URL(req.url);
  const dealId = searchParams.get('dealId') || searchParams.get('slug');

  let filtered = MESSAGES_STORE;
  if (dealId) {
    filtered = MESSAGES_STORE.filter((m) => m.dealId === dealId);
  }

  return NextResponse.json({
    success: true,
    total: filtered.length,
    messages: filtered,
  });
}

