'use client';

import { useEffect, useState, useRef, Suspense } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import Logo from '@/components/brand/Logo';
import {
  CheckCircle2,
  Sparkles,
  ArrowRight,
  Loader2,
  AlertCircle,
  Shield,
} from 'lucide-react';
import { auth } from '@/lib/firebase/config';
import { onAuthStateChanged } from 'firebase/auth';

/* ═══════════════════════════════════════════════════════
   Checkout Success Page

   This is a STANDALONE page (not behind dashboard auth)
   so it works for both:
     • Authenticated users returning from Stripe
     • Guest checkouts who haven't created an account yet

   Flow:
     1. Stripe redirects here with ?session_id=cs_xxx
     2. We verify the session status via /api/stripe/session-status
     3. If user is logged in → refresh token + show "Go to Dashboard"
     4. If user is NOT logged in → show "Create your account" CTA
        (links to /register with plan context)
   ═══════════════════════════════════════════════════════ */

export default function CheckoutSuccessPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">
          <Loader2 className="w-8 h-8 animate-spin text-[#555]" />
        </div>
      }
    >
      <CheckoutSuccessInner />
    </Suspense>
  );
}

interface SessionData {
  status: string;
  paymentStatus: string;
  plan: string | null;
  planId: string | null;
  billingInterval: string | null;
  customerEmail: string | null;
  subscriptionStatus: string | null;
  trialEnd: string | null;
}

function CheckoutSuccessInner() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const sessionId = searchParams?.get('session_id');

  const [sessionData, setSessionData] = useState<SessionData | null>(null);
  const [phase, setPhase] = useState<'loading' | 'success' | 'error'>('loading');
  const [isLoggedIn, setIsLoggedIn] = useState<boolean | null>(null);
  const [tokenRefreshed, setTokenRefreshed] = useState(false);
  const hasResolved = useRef(false);

  const [dest, setDest] = useState('/dashboard');

  // Check auth state without blocking
  useEffect(() => {
    const unsub = onAuthStateChanged(auth, (user) => {
      setIsLoggedIn(!!user);
    });

    // Catch pending project address redirects
    if (typeof window !== 'undefined' && sessionStorage.getItem('pw_pending_project_address')) {
      setDest('/dashboard/projects/new');
    }

    return () => unsub();
  }, []);

  // Verify the checkout session
  useEffect(() => {
    if (!sessionId || hasResolved.current) return;
    hasResolved.current = true;

    (async () => {
      try {
        const res = await fetch(`/api/stripe/session-status?session_id=${sessionId}`);
        const data = await res.json();

        if (res.ok && data.status === 'complete') {
          setSessionData(data);
          setPhase('success');
        } else {
          setPhase('error');
        }
      } catch {
        setPhase('error');
      }
    })();
  }, [sessionId]);

  // For logged-in users: refresh token + sync session cookie
  useEffect(() => {
    if (phase !== 'success' || !isLoggedIn || tokenRefreshed) return;

    (async () => {
      try {
        const currentUser = auth.currentUser;
        if (currentUser) {
          const freshToken = await currentUser.getIdToken(true);
          await fetch('/api/auth/session', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ idToken: freshToken }),
          });
          setTokenRefreshed(true);
        }
      } catch (err) {
        console.warn('[CheckoutSuccess] Token refresh failed (non-fatal):', err);
      }
    })();
  }, [phase, isLoggedIn, tokenRefreshed]);

  // No session_id — redirect to pricing
  if (!sessionId) {
    return (
      <PageShell>
        <div className="text-center">
          <AlertCircle className="w-12 h-12 text-[#555] mx-auto mb-4" />
          <h2 className="text-xl font-semibold text-white mb-2">No session found</h2>
          <p className="text-sm text-[#888] mb-6">
            It looks like you got here without completing a checkout.
          </p>
          <Link href="/pricing" className="inline-flex items-center gap-2 px-6 py-3 bg-white text-black text-sm font-semibold rounded-xl hover:bg-gray-100 transition-colors">
            View Plans
            <ArrowRight className="w-4 h-4" />
          </Link>
        </div>
      </PageShell>
    );
  }

  return (
    <PageShell>
      {/* Loading State */}
      {phase === 'loading' && (
        <div className="text-center animate-in fade-in duration-300">
          <div className="w-16 h-16 mx-auto mb-6 flex items-center justify-center">
            <Loader2 className="w-10 h-10 text-white animate-spin" />
          </div>
          <h2 className="text-xl font-semibold text-white mb-2">
            Confirming your subscription…
          </h2>
          <p className="text-sm text-[#888]">
            Please wait while we verify your payment.
          </p>
        </div>
      )}

      {/* Error State */}
      {phase === 'error' && (
        <div className="text-center animate-in fade-in duration-300">
          <div className="w-16 h-16 mx-auto mb-6 rounded-full bg-red-950/60 flex items-center justify-center">
            <AlertCircle className="w-8 h-8 text-red-400" />
          </div>
          <h2 className="text-xl font-semibold text-white mb-2">
            Something went wrong
          </h2>
          <p className="text-sm text-[#888] mb-6">
            We couldn&apos;t verify your checkout session. If you were charged, your subscription will still be activated automatically.
          </p>
          <div className="flex flex-col gap-3">
            <Link
              href="/dashboard"
              className="inline-flex items-center justify-center gap-2 px-6 py-3 bg-white text-black text-sm font-semibold rounded-xl hover:bg-gray-100 transition-colors"
            >
              Go to Dashboard
              <ArrowRight className="w-4 h-4" />
            </Link>
            <Link
              href="/support"
              className="text-sm text-[#555] hover:text-[#aaa] transition-colors"
            >
              Contact Support
            </Link>
          </div>
        </div>
      )}

      {/* Success State */}
      {phase === 'success' && sessionData && (
        <div className="text-center animate-in fade-in zoom-in-95 duration-500">
          {/* Celebration icon */}
          <div className="w-20 h-20 mx-auto mb-6 rounded-full bg-green-950/40 border border-green-800/30 flex items-center justify-center">
            <CheckCircle2 className="w-10 h-10 text-green-400" />
          </div>

          <h2 className="text-2xl font-bold text-white mb-3">
            Welcome to PaperWorking!
          </h2>

          {/* Plan details */}
          <div className="inline-flex items-center gap-2 px-4 py-2 bg-[#141414] border border-[#2a2a2a] rounded-lg mb-4">
            <Sparkles className="w-4 h-4 text-green-400" />
            <span className="text-sm font-medium text-white">
              {sessionData.plan ?? 'Subscription'}{' '}
              {sessionData.billingInterval === 'annual' ? '(Annual)' : '(Monthly)'}
            </span>
          </div>

          <p className="text-sm text-[#888] mb-8 leading-relaxed max-w-sm mx-auto">
            {sessionData.subscriptionStatus === 'trialing' ? (
              <>
                Your free trial is active.
                {sessionData.trialEnd && (
                  <>
                    {' '}Full access until{' '}
                    <strong className="text-white">
                      {new Date(sessionData.trialEnd).toLocaleDateString('en-US', {
                        month: 'long',
                        day: 'numeric',
                        year: 'numeric',
                      })}
                    </strong>.
                  </>
                )}
              </>
            ) : (
              <>Your subscription is now active. You have full access to all features.</>
            )}
          </p>

          {/* CTA — different for logged-in vs guest */}
          <div className="flex flex-col gap-3 max-w-xs mx-auto">
            {isLoggedIn === null ? (
              /* Firebase auth still resolving */
              <div className="flex justify-center py-3">
                <Loader2 className="w-5 h-5 animate-spin text-[#555]" />
              </div>
            ) : isLoggedIn ? (
              /* Authenticated user → go straight to dashboard or creation */
              <button
                onClick={() => { window.location.href = dest; }}
                className="w-full inline-flex items-center justify-center gap-2 py-3.5 px-6 bg-white text-black text-sm font-semibold rounded-xl hover:bg-gray-100 transition-all active:scale-[0.97]"
              >
                <Sparkles className="w-4 h-4" />
                Go to Dashboard
                <ArrowRight className="w-4 h-4" />
              </button>
            ) : (
              /* Guest → sign in / create account to claim subscription */
              <>
                <Link
                  href={`/login?redirectTo=${encodeURIComponent(dest)}`}
                  className="w-full inline-flex items-center justify-center gap-2 py-3.5 px-6 bg-white text-black text-sm font-semibold rounded-xl hover:bg-gray-100 transition-all active:scale-[0.97]"
                >
                  Sign In / Create Account
                  <ArrowRight className="w-4 h-4" />
                </Link>
                <p className="text-xs text-[#555] leading-relaxed">
                  Use Google, Facebook, or a magic link to access your dashboard.
                </p>
              </>
            )}
          </div>

          {/* Security badge */}
          <div className="mt-8 flex items-center justify-center gap-2 text-[11px] text-[#444]">
            <Shield className="w-3.5 h-3.5" />
            <span>Secured by Stripe · 256-bit encryption</span>
          </div>
        </div>
      )}
    </PageShell>
  );
}

/* ─── Page Shell (reuses auth layout aesthetic) ─── */
function PageShell({ children }: { children: React.ReactNode }) {
  return (
    <div className="relative min-h-screen bg-[#0a0a0a] flex flex-col items-center justify-center overflow-hidden">
      {/* Dot-grid texture */}
      <div
        aria-hidden
        className="pointer-events-none absolute inset-0"
        style={{
          backgroundImage: 'radial-gradient(circle, #2b2b2b 1px, transparent 1px)',
          backgroundSize: '24px 24px',
        }}
      />

      {/* Logo — top-left */}
      <div className="absolute top-6 left-8 z-20">
        <Logo href="/" surface="auth" size="sm" />
      </div>

      {/* Content */}
      <div className="relative z-10 w-full max-w-md px-6">
        {children}
      </div>

      {/* Footer */}
      <div className="absolute bottom-6 left-0 right-0 text-center text-[11px] text-[#4a4a4a]">
        <Link href="/terms" className="hover:text-[#888] transition-colors">Terms of service</Link>
        <span className="mx-2">·</span>
        <Link href="/privacy" className="hover:text-[#888] transition-colors">Privacy policy</Link>
        <span className="mx-2">·</span>
        <span>©{new Date().getFullYear()} PaperWorking</span>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import ReactECharts from 'echarts-for-react';
import {
  TrendingUp,
  PieChart,
  BarChart3,
  Activity,
  DollarSign,
  ArrowUpRight,
  Download,
} from 'lucide-react';
import { useAllDealsSync } from '@/hooks/useAllProjectsSync';
import { useProjectStore } from '@/store/projectStore';
import { usePortfolioMetricSnapshots } from '@/hooks/usePortfolioMetricSnapshots';
import type { Project } from '@/types/schema';

// ─── Design tokens ────────────────────────────────────────────
const T = {
  teal: '#454955',
  brandPrimary: '#454955',
  amber: '#fbbf24',
  red: '#F06543',
  canvas: '#0d0a0b',
  surface: 'rgba(24,33,39,0.7)',
  border: 'rgba(255,255,255,0.08)',
  textPrimary: '#9E9DA0',
  textMuted: '#64748b',
  textVariant: '#9E9DA0',
  tooltipBg: '#1e1b20',
  tooltipBorder: 'rgba(69,73,85,0.2)',
} as const;

const PERIOD_TABS = [
  { id: 'ytd', label: 'YTD' },
  { id: '6m', label: '6M' },
  { id: '3m', label: '3M' },
  { id: '30d', label: '30D' },
  { id: '12m', label: '12M' },
  { id: 'all', label: 'All Time' },
] as const;

type PeriodId = typeof PERIOD_TABS[number]['id'];
type Scope = 'property' | 'myShare';

// ─── Shared ECharts defaults ──────────────────────────────────
const TOOLTIP_BASE = {
  backgroundColor: T.tooltipBg,
  borderColor: T.tooltipBorder,
  borderWidth: 1,
  textStyle: { color: T.textPrimary, fontSize: 12, fontFamily: 'JetBrains Mono, monospace' },
  extraCssText: 'border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,0.4)',
};

const AXIS_LABEL_STYLE = { color: T.textMuted, fontSize: 11, fontFamily: 'JetBrains Mono, monospace' };

// ─── Formatters ───────────────────────────────────────────────
function fmtK(v: number): string {
  if (Math.abs(v) >= 1_000_000) return `$${(v / 1_000_000).toFixed(1)}M`;
  if (Math.abs(v) >= 1_000) return `$${(v / 1_000).toFixed(0)}k`;
  return `$${v.toFixed(0)}`;
}

function fmtPct(v: number | null, decimals = 2): string {
  if (v === null) return '—';
  return `${v.toFixed(decimals)}%`;
}

function toDate(v: any): Date | null {
  if (!v) return null;
  if (v instanceof Date) return v;
  if (typeof v === 'object' && 'seconds' in v) return new Date(v.seconds * 1000);
  try { return new Date(v); } catch { return null; }
}

// ─── Loading skeleton ─────────────────────────────────────────
function ChartSkeleton({ height }: { height: number }) {
  return <div className="animate-pulse rounded-xl bg-white/5" style={{ height }} />;
}

// ─── Honest empty state ───────────────────────────────────────
function EmptyChart({ message, height }: { message: string; height: number }) {
  return (
    <div
      className="flex items-center justify-center text-center px-6"
      style={{ height, color: T.textMuted, fontSize: 13 }}
    >
      {message}
    </div>
  );
}

// ─── Glass card wrapper ───────────────────────────────────────
function GlassCard({ children, className = '' }: { children: React.ReactNode; className?: string }) {
  return (
    <div
      className={`rounded-2xl border border-white/10 overflow-hidden ${className}`}
      style={{ background: T.surface, backdropFilter: 'blur(24px)' }}
    >
      {children}
    </div>
  );
}

// ─── Card header ──────────────────────────────────────────────
function CardHeader({
  icon,
  title,
  badge,
}: {
  icon: React.ReactNode;
  title: string;
  badge?: React.ReactNode;
}) {
  return (
    <div className="flex items-center justify-between px-5 py-4 border-b border-white/8">
      <div className="flex items-center gap-3">
        <div className="w-7 h-7 rounded-lg flex items-center justify-center" style={{ background: 'rgba(69,73,85,0.12)' }}>
          {icon}
        </div>
        <span className="text-xs font-bold uppercase tracking-widest" style={{ color: T.textVariant }}>
          {title}
        </span>
      </div>
      {badge && <div>{badge}</div>}
    </div>
  );
}

// ─── KPI card ─────────────────────────────────────────────────
function KpiCard({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <GlassCard className="flex flex-col gap-1 px-5 py-5">
      <span className="text-[10px] font-bold uppercase tracking-[0.18em]" style={{ color: T.textMuted }}>
        {label}
      </span>
      <span className="text-2xl font-mono font-semibold tracking-tight" style={{ color: T.textPrimary }}>
        {value}
      </span>
      {sub && <span className="text-[10px] font-mono" style={{ color: T.textMuted }}>{sub}</span>}
    </GlassCard>
  );
}

// ─── ROI Trend chart ──────────────────────────────────────────
function RoiTrendChart({
  snapshots,
  loading,
}: {
  snapshots: ReturnType<typeof usePortfolioMetricSnapshots>['snapshots'];
  loading: boolean;
}) {
  const { xLabels, values } = useMemo(() => {
    const valid = snapshots.filter((s) => s.propertyValue !== null);
    if (valid.length >= 3) {
      return {
        xLabels: valid.map((s) =>
          new Date(s.date).toLocaleDateString('en-US', { month: 'short', year: '2-digit' })
        ),
        values: valid.map((s) => s.propertyValue as number),
      };
    }
    return { xLabels: [] as string[], values: [] as number[] };
  }, [snapshots]);

  const option = {
    backgroundColor: 'transparent',
    grid: { top: 24, right: 24, bottom: 40, left: 64 },
    tooltip: { ...TOOLTIP_BASE, trigger: 'axis', formatter: (params: { dataIndex: number; value: number }[]) => `${xLabels[params[0].dataIndex]}<br/><b>${fmtK(params[0].value)}</b>` },
    xAxis: {
      type: 'category',
      data: xLabels,
      axisLabel: AXIS_LABEL_STYLE,
      axisLine: { lineStyle: { color: T.textMuted } },
      axisTick: { show: false },
      boundaryGap: false,
    },
    yAxis: {
      type: 'value',
      axisLabel: { ...AXIS_LABEL_STYLE, formatter: (v: number) => fmtK(v) },
      splitLine: { lineStyle: { color: 'rgba(255,255,255,0.05)' } },
    },
    series: [
      {
        type: 'line',
        data: values,
        smooth: 0.35,
        symbol: 'none',
        lineStyle: { color: T.teal, width: 2.5, shadowColor: 'rgba(69,73,85,0.5)', shadowBlur: 8 },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(69,73,85,0.28)' },
              { offset: 1, color: 'rgba(69,73,85,0.01)' },
            ],
          },
        },
      },
    ],
  };

  return (
    <GlassCard className="col-span-12 lg:col-span-8">
      <CardHeader
        icon={<TrendingUp className="w-3.5 h-3.5" style={{ color: T.teal }} />}
        title="Portfolio Value Trend"
      />
      <div className="p-4">
        {loading ? (
          <ChartSkeleton height={280} />
        ) : xLabels.length === 0 ? (
          <EmptyChart message="No portfolio snapshots yet — add properties with values to start tracking." height={280} />
        ) : (
          <ReactECharts option={option} style={{ height: 280 }} opts={{ renderer: 'canvas' }} />
        )}
      </div>
    </GlassCard>
  );
}

// ─── Portfolio Allocation donut ───────────────────────────────
function AllocationChart({
  projects,
  loading,
}: {
  projects: Project[];
  loading: boolean;
}) {
  const { data, totalDeals } = useMemo(() => {
    if (projects.length === 0) return { data: [] as { value: number; name: string; itemStyle: { color: string } }[], totalDeals: 0 };
    const counts: Record<string, number> = {};
    for (const p of projects) {
      const type = p.dispositionType === 'RENT'
        ? (p.subStrategy === 'BRRRR' ? 'BRRRR' : 'Rent')
        : p.dispositionType === 'LEASE' ? 'Lease' : 'Fix & Flip';
      counts[type] = (counts[type] ?? 0) + 1;
    }
    const palette = [T.teal, T.brandPrimary, T.amber, '#fb923c', '#454955'];
    const entries = Object.entries(counts).map(([name, value], i) => ({
      name,
      value,
      itemStyle: { color: palette[i % palette.length] },
    }));
    return { data: entries, totalDeals: projects.length };
  }, [projects]);

