// ── Helper: Format currency ────────────────────────────────────
function formatCurrency(v: number): string {
  const abs = Math.abs(v);
  const formatted = abs.toLocaleString('en-US', {
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  });
  return v < 0 ? `-$${formatted}` : `$${formatted}`;
}

