export default function DealsMarketplacePage() {
  const { user } = useAuth();
  const router = useRouter();
  const searchParams = useSearchParams();

  const [activeTab, setActiveTab] = useState<MarketplaceTab>('discover');
  const [viewMode, setViewMode] = useState<ViewMode>('list');
  const [sortOption, setSortOption] = useState<SortOption>('newest');
  const [isCreateSheetOpen, setIsCreateSheetOpen] = useState(false);

  // Compare Mode State
  const [isCompareMode, setIsCompareMode] = useState(false);
  const [selectedCompareIds, setSelectedCompareIds] = useState<string[]>([]);

  const [filters, setFilters] = useState<FilterState>({
    propertyType: 'All',
    strategy: 'All',
    status: 'All',
    priceRange: 'All',
  });

  const [deals, setDeals] = useState<any[]>(DEFAULT_SAMPLE_DEALS);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    async function fetchDeals() {
      setLoading(true);
      try {
        const queryParams = new URLSearchParams();
        if (filters.propertyType !== 'All') queryParams.set('propertyType', filters.propertyType);
        if (filters.strategy !== 'All') queryParams.set('strategy', filters.strategy);
        if (filters.status !== 'All') queryParams.set('status', filters.status);
        if (filters.priceRange !== 'All') queryParams.set('priceRange', filters.priceRange);
        if (sortOption) queryParams.set('sort', sortOption);
        queryParams.set('tab', activeTab);

        const res = await fetch(`/api/deals?${queryParams.toString()}`);
        if (res.ok) {
          const data = await res.json();
          if (data.deals && data.deals.length > 0) {
            setDeals(data.deals);
          }
        }
      } catch (err) {
        console.error('Failed to load deals from API:', err);
      } finally {
        setLoading(false);
      }
    }

    fetchDeals();
  }, [filters, sortOption, activeTab]);

  const toggleSelectDealForCompare = (dealId: string) => {
    setSelectedCompareIds((prev) => {
      if (prev.includes(dealId)) {
        return prev.filter((id) => id !== dealId);
      }
      if (prev.length >= 4) {
        return prev;
      }
      return [...prev, dealId];
    });
  };

  const filteredDeals = deals.filter((deal) => {
    if (filters.propertyType !== 'All' && deal.assetClass?.toLowerCase() !== filters.propertyType.toLowerCase()) {
      return false;
    }
    if (filters.strategy !== 'All' && deal.subStrategy?.toLowerCase() !== filters.strategy.toLowerCase()) {
      return false;
    }
    if (filters.status !== 'All' && deal.status?.toLowerCase() !== filters.status.toLowerCase()) {
      return false;
    }
    return true;
  });

  const handleResetFilters = () => {
    setFilters({
      propertyType: 'All',
      strategy: 'All',
      status: 'All',
      priceRange: 'All',
    });
  };

  return (
    <div className="bg-[#0a0a0f] min-h-screen space-y-8 pb-28 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-4 text-slate-100">
      {/* Top Header Subnav */}
      <MarketplaceSubnav />

      {/* Sticky Hero Address Search Bar (Luminous Glass: backdrop-blur-md) */}
      <div className="sticky top-0 z-40 bg-[#0a0a0f]/80 backdrop-blur-[12px] pt-2 pb-4">
        <AddressSearch onListDealClick={() => setIsCreateSheetOpen(true)} />
      </div>

      {/* Progressive Filter Panel */}
      <FilterPanel filters={filters} onFilterChange={setFilters} />

      {/* Marketplace Tabs & Controls Bar */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-white/[0.06] pb-4">
        {/* Discover vs My Activity Glass Pill Tabs */}
        <MarketplaceTabs activeTab={activeTab} onTabChange={setActiveTab} />

        {/* Controls: Compare Toggle, View Toggle (List/Map) & Sort Control */}
        {activeTab === 'discover' && (
          <div className="flex items-center gap-3 self-end md:self-auto flex-wrap">
            <button
              type="button"
              data-testid="compare-mode-toggle"
              onClick={() => {
                setIsCompareMode(!isCompareMode);
                if (isCompareMode) setSelectedCompareIds([]);
              }}
              className={`px-3.5 py-1.5 rounded-[10px] text-xs font-bold transition-all min-h-[36px] cursor-pointer flex items-center gap-1.5 ${
                isCompareMode
                  ? 'bg-[#34d399] text-slate-950 shadow-md font-extrabold'
                  : 'bg-[#34d399]/[0.08] border border-[#34d399]/25 hover:bg-[#34d399]/15 text-[#34d399]'
              }`}
            >
              <SlidersHorizontal className="w-3.5 h-3.5" />
              <span>{isCompareMode ? 'Exit Compare' : 'Compare'}</span>
            </button>

            <ViewToggle view={viewMode} onViewChange={setViewMode} />
            <SortControl sort={sortOption} onSortChange={setSortOption} />
          </div>
        )}
      </div>

      {/* Tab Content */}
      {activeTab === 'my-activity' ? (
        <MyDealsHistoryTab allDeals={deals} />
      ) : (
        <>
          {loading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              <SkeletonCard />
              <SkeletonCard />
              <SkeletonCard />
            </div>
          ) : viewMode === 'map' ? (
            <div className="rounded-[14px] border border-white/10 p-4 bg-[#0a0a0f]/90 backdrop-blur-[14px] h-[550px] relative overflow-hidden shadow-2xl">
              <DealMap deals={filteredDeals} />
            </div>
          ) : filteredDeals.length > 0 ? (
            <div data-testid="discover-deals-grid" className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredDeals.map((deal) => (
                <DealCard
                  key={deal.id}
                  deal={deal}
                  isCompareMode={isCompareMode}
                  isSelected={selectedCompareIds.includes(deal.id)}
                  onToggleSelect={toggleSelectDealForCompare}
                />
              ))}
            </div>
          ) : (
            <EmptyState onResetFilters={handleResetFilters} />
          )}
        </>
      )}

      {/* Sticky Glass Bottom Bar for Compare Mode (when >= 2 deals selected) */}
      {isCompareMode && selectedCompareIds.length >= 2 && (
        <div
          data-testid="sticky-compare-bar"
          className="fixed bottom-6 left-1/2 -translate-x-1/2 z-50 px-6 py-3.5 rounded-[16px] bg-[#0a0a0f]/95 border border-[#34d399]/40 backdrop-blur-[20px] shadow-2xl flex items-center gap-4 animate-fade-in"
        >
          <span className="text-xs font-bold text-white">
            <strong className="text-[#34d399] font-mono text-sm">{selectedCompareIds.length}</strong> deals selected for comparison
          </span>

          <button
            type="button"
            data-testid="compare-deals-btn"
            onClick={() => router.push(`/deals/compare?ids=${selectedCompareIds.join(',')}`)}
            className="px-5 py-2.5 rounded-[10px] bg-[#34d399] hover:bg-[#34d399]/90 text-slate-950 font-black text-xs uppercase tracking-wider flex items-center gap-1.5 shadow-lg min-h-[40px] cursor-pointer"
          >
            <span>Compare {selectedCompareIds.length} Deals</span>
            <ArrowRight className="w-4 h-4 text-slate-950" />
          </button>
        </div>
      )}

      {/* Mobile Sticky Glass Bottom Bar CTA (<640px, backdrop-blur: 20px) */}
      <div className="sm:hidden fixed bottom-18 left-0 right-0 p-4 bg-[#0a0a0f]/90 backdrop-blur-[20px] border-t border-white/10 z-40 flex items-center justify-center">
        <button
          type="button"
          onClick={() => setIsCreateSheetOpen(true)}
          className="w-full h-12 rounded-[10px] bg-[#34d399] hover:bg-[#34d399]/90 text-slate-950 font-extrabold text-xs uppercase tracking-wider flex items-center justify-center gap-2 shadow-2xl min-h-[48px] cursor-pointer"
        >
          <Plus className="w-4 h-4 text-slate-950" />
          <span>List a Deal</span>
        </button>
      </div>

      {/* Compliance Disclaimer Bar */}
      <div className="pt-8 border-t border-white/[0.04]">
        <p className="text-xs text-slate-500 leading-relaxed font-mono">
          PaperWorking facilitates introductions and interest tracking only. No funds, securities, or ownership interests are offered, sold, or transferred through the platform. All transactions occur outside PaperWorking, directly between the parties.
        </p>
      </div>

      {/* Deal Creation Sheet */}
      <CreateDealSheet
        isOpen={isCreateSheetOpen}
        onClose={() => setIsCreateSheetOpen(false)}
        initialAddress={null}
        existingDeals={deals}
        onDealCreated={(newDeal) => setDeals((prev) => [newDeal, ...prev])}
      />
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { CheckCircle, UploadCloud, ClipboardList, Camera, AlertCircle, ArrowLeft, Send } from 'lucide-react';
import toast from 'react-hot-toast';
import Link from 'next/link';

export default function FieldManagerPage() {
  const projects = useProjectStore(state => state.projects);
  const currentProject = useProjectStore(state => state.currentProject);
  const setDeal = useProjectStore(state => state.setDeal);
  const updateProjectFinancials = useProjectStore(state => state.updateProjectFinancials);

  const [receiptAmount, setReceiptAmount] = useState('');
  const [receiptCategory, setReceiptCategory] = useState<any>('Plumbing');
  const [isUploading, setIsUploading] = useState(false);

  // Auto-select a renovating deal if possible
  useEffect(() => {
    if (projects.length > 0 && !currentProject) {
      const activeRehab = projects.find(d => d.status === 'hold') || projects[0];
      setDeal(activeRehab);
    }
  }, [projects, currentProject, setDeal]);

  if (!currentProject) {
    return <div className="p-8 text-center text-text-secondary">No active properties available for Field Management.</div>;
  }

  const rehabTasks = currentProject.financials.rehabTasks || [];

  const handleReceiptUpload = (e: React.FormEvent) => {
    e.preventDefault();
    if (!receiptAmount || isNaN(Number(receiptAmount))) {
      toast.error('Please enter a valid numeric amount.');
      return;
    }

    setIsUploading(true);
    const newCostEntry = {
      id: `cost_${Date.now()}`,
      description: `Field Receipt - ${receiptCategory}`,
      amount: Number(receiptAmount),
      approved: false,
      addedBy: 'General Contractor',
      createdAt: new Date(),
      category: receiptCategory,
      receiptUrl: undefined,
      status: 'Pending Triage' as any
    };

    const currentCosts = currentProject.financials.costs || [];
    updateProjectFinancials(currentProject.id, {
      costs: [...currentCosts, newCostEntry]
    });

    setReceiptAmount('');
    setIsUploading(false);
    toast.success('Receipt transmitted to Engine Room Triage!');
  };

  const handleTaskCompletion = (taskId: string) => {
    const updatedTasks = rehabTasks.map(t => {
      if (t.id === taskId) {
        return {
          ...t,
          status: 'Complete' as any,
          afterPhotoUrl: undefined,
          escrowDrawRequested: true
        };
      }
      return t;
    });

    updateProjectFinancials(currentProject.id, { rehabTasks: updatedTasks });
    toast.success('Task finished! After-photo attached. Escrow Draw Request sent to Lender.', { duration: 4000, icon: '🏦' });
  };

  return (
    <div className="max-w-md mx-auto space-y-6 pb-24 bg-bg-primary min-h-screen">
      {/* Mobile-centric Header */}
      <div className="bg-bg-surface border-b px-4 py-4 sticky top-0 z-10 flex items-center shadow-sm">
        <Link href="/dashboard" className="mr-3 p-2 rounded-full bg-bg-primary hover:bg-gray-200">
          <ArrowLeft className="w-5 h-5 text-text-primary" />
        </Link>
        <div>
          <h1 className="text-xl font-bold tracking-tight text-text-primary">Field Manager</h1>
          <p className="text-xs text-text-secondary font-medium truncate w-[250px]">{currentProject.address}</p>
        </div>
      </div>

      <div className="px-4 space-y-6">

        {/* Receipt Upload Zone */}
        <div className="bg-bg-surface rounded-2xl shadow-sm border border-border-accent p-5">
          <div className="flex items-center space-x-2 mb-4">
            <UploadCloud className="w-5 h-5 text-blue-600" />
            <h2 className="text-lg font-semibold text-text-primary">Scan Receipt</h2>
          </div>

          <form onSubmit={handleReceiptUpload} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-text-secondary mb-1 border-b pb-1">Budget Category</label>
              <select 
                value={receiptCategory}
                onChange={(e) => setReceiptCategory(e.target.value)}
                className="w-full bg-bg-primary border border-border-accent rounded-lg p-3 text-sm focus:ring-2 focus:ring-blue-500"
              >
                <option value="Plumbing">Plumbing</option>
                <option value="Electrical">Electrical</option>
                <option value="Framing">Framing</option>
                <option value="HVAC">HVAC</option>
                <option value="Foundation">Foundation</option>
                <option value="Other">Other</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-text-secondary mb-1 border-b pb-1">Total Amount ($)</label>
              <input 
                type="number" 
                required
                placeholder="e.g. 542.50"
                value={receiptAmount}
                onChange={(e) => setReceiptAmount(e.target.value)}
                className="w-full bg-bg-primary border border-border-accent rounded-lg p-3 text-lg font-mono placeholder-gray-300 focus:ring-2 focus:ring-blue-500"
              />
            </div>

            <div className="border-2 border-dashed border-border-accent rounded-lg p-6 flex flex-col items-center justify-center bg-bg-primary text-text-secondary cursor-pointer hover:bg-bg-primary transition">
              <Camera className="w-8 h-8 mb-2" />
              <span className="text-xs font-medium text-center">Tap to snap photo<br/>or select PDF</span>
            </div>

            <button 
              type="submit"
              disabled={isUploading}
              className={`w-full py-3.5 rounded-xl text-white font-bold text-sm shadow-md transition flex items-center justify-center space-x-2 ${isUploading ? 'bg-blue-400 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-700 active:scale-95'}`}
            >
              <Send className="w-4 h-4" />
              <span>{isUploading ? 'Transmitting...' : 'Submit to Engine Room'}</span>
            </button>
          </form>
        </div>

        {/* Linear Gantt/Task View */}
        <div className="bg-bg-surface rounded-2xl shadow-sm border border-border-accent p-5 mt-6">
          <div className="flex items-center justify-between mb-4">
             <div className="flex items-center space-x-2">
               <ClipboardList className="w-5 h-5 text-text-primary" />
               <h2 className="text-lg font-semibold text-text-primary">Rehab Timeline</h2>
             </div>
             {rehabTasks.some(t => t.escrowDrawRequested) && (
               <span className="px-2 py-1 bg-green-100 text-green-700 text-xs font-bold rounded-full border border-green-200">
                 ACTIVE ESCROW DRAWS
               </span>
             )}
          </div>

          {rehabTasks.length === 0 && (
            <p className="text-sm text-text-secondary text-center py-4">No rehab tasks yet. Add tasks to this project to track progress.</p>
          )}
          <div className="space-y-4 relative before:absolute before:inset-0 before:ml-5 before:-translate-x-px md:before:mx-auto md:before:translate-x-0 before:h-full before:w-0.5 before:bg-gradient-to-b before:from-transparent before:via-gray-300 before:to-transparent">
            {rehabTasks.map((task, idx) => (
              <div key={task.id} className="relative flex items-center justify-between z-10 p-3 bg-bg-surface border rounded-xl shadow-sm">
                 <div className="flex items-center space-x-3">
                   {task.status === 'Complete' ? (
                     <CheckCircle className="w-6 h-6 text-green-500 flex-shrink-0 bg-bg-surface" />
                   ) : task.status === 'In Progress' ? (
                     <div className="w-6 h-6 rounded-full border-2 border-blue-500 border-t-blue-200 animate-spin flex-shrink-0 bg-bg-surface"></div>
                   ) : (
                     <div className="w-6 h-6 rounded-full border-[3px] border-border-accent flex-shrink-0 bg-bg-surface"></div>
                   )}

                   <div>
                     <p className={`text-sm font-semibold ${task.status === 'Complete' ? 'text-text-secondary line-through' : 'text-text-primary'}`}>{task.title}</p>
                     <p className="text-xs uppercase tracking-wider text-text-secondary font-mono">${task.estimatedCost.toLocaleString()} • {task.category}</p>
                   </div>
                 </div>

                 {task.status !== 'Complete' && (
                    <button 
                      onClick={() => handleTaskCompletion(task.id)}
                      className="ml-2 text-xs px-3 py-1.5 bg-gray-900 text-white font-bold rounded hover:bg-gray-800 active:scale-95 shadow-sm"
                    >
                      MARK DONE
                    </button>
                 )}
              </div>
            ))}
          </div>

          <div className="mt-4 p-3 bg-yellow-50 border border-yellow-200 rounded-lg flex items-start space-x-2">
            <AlertCircle className="w-4 h-4 text-yellow-600 mt-0.5 flex-shrink-0" />
            <p className="text-xs text-yellow-800 leading-relaxed">
              Marking a task "Done" requires an "After" photo. This automatically pings the Lead Investor to organize an Escrow Draw Request for your milestone payment.
            </p>
          </div>

        </div>
      </div>
    </div>
  );
}

messages.message:
Error: Calling setState synchronously within an effect can trigger cascading renders

Effects are intended to synchronize state between React and external systems such as manually updating the DOM, state management libraries, or other platform APIs. In general, the body of an effect should do one or both of the following:
* Update external systems with the latest state from React.
