"use client";

import React, { useState, useEffect, useCallback, useRef } from "react";
import { useAuth } from "@/context/AuthContext";
import { useProjectStore } from "@/store/projectStore";
import { saveFinancials, loadFinancials } from "@/actions/financials";
import type { FinancialsPayload } from "@/actions/financials";
import NOIInputTerminal from "@/components/dashboard/financials/NOIInputTerminal";
import NOIWaterfallChart from "@/components/dashboard/financials/NOIWaterfallChart";
import CashFlowInputTerminal from "@/components/dashboard/financials/CashFlowInputTerminal";
import CashFlowDeepDive from "@/components/dashboard/financials/CashFlowDeepDive";

function computeMonthlyPayment(principal: number, annualRatePercent: number, years: number) {
  if (principal <= 0 || years <= 0) return 0;
  if (annualRatePercent <= 0) return principal / (years * 12);

  const monthlyRate = annualRatePercent / 100 / 12;
  const numPayments = years * 12;

  const payment = principal * (monthlyRate * Math.pow(1 + monthlyRate, numPayments)) / (Math.pow(1 + monthlyRate, numPayments) - 1);
  return payment;
}

type SaveStatus = "idle" | "saving" | "saved" | "error";
type LoadStatus = "loading" | "ready" | "no-project";

export default function FinancialsTerminal() {
  const { user } = useAuth();
  const projects = useProjectStore((s) => s.projects);
  const currentProject = useProjectStore((s) => s.currentProject);
  const setDeal = useProjectStore((s) => s.setDeal);

  // --- Project Selector ---
  const [selectedProjectId, setSelectedProjectId] = useState<string>("");
  const selectedProject = projects.find((p) => p.id === selectedProjectId) || null;

  // --- Load Status ---
  const [loadStatus, setLoadStatus] = useState<LoadStatus>("loading");
  const [saveStatus, setSaveStatus] = useState<SaveStatus>("idle");
  const [toastMessage, setToastMessage] = useState("");
  const toastTimeout = useRef<NodeJS.Timeout | null>(null);

  // --- NOI State (empty = undefined until loaded) ---
  const [gri, setGri] = useState<number | undefined>(undefined);
  const [otherIncome, setOtherIncome] = useState<number | undefined>(undefined);
  const [vacancyPct, setVacancyPct] = useState<number | undefined>(undefined);
  const [opex, setOpex] = useState<number | undefined>(undefined);

  // --- Cash Flow State ---
  const [loanAmount, setLoanAmount] = useState<number | undefined>(undefined);
  const [interestRate, setInterestRate] = useState<number | undefined>(undefined);
  const [loanTerm, setLoanTerm] = useState<number | undefined>(undefined);
  const [otherDebt, setOtherDebt] = useState<number | undefined>(undefined);

  // Auto-save tracking
  const autoSaveTimer = useRef<NodeJS.Timeout | null>(null);
  const hasLoadedData = useRef(false);

  // --- Initialize project selection ---
  useEffect(() => {
    if (currentProject) {
      setSelectedProjectId(currentProject.id);
    } else if (projects.length > 0 && !selectedProjectId) {
      setSelectedProjectId(projects[0].id);
    }
    if (projects.length === 0) {
      setLoadStatus("no-project");
    }
  }, [currentProject, projects, selectedProjectId]);

  // --- Load financials from Firestore when project changes ---
  useEffect(() => {
    if (!selectedProjectId || !user) {
      if (projects.length === 0) setLoadStatus("no-project");
      return;
    }

    hasLoadedData.current = false;
    setLoadStatus("loading");
    setSaveStatus("idle");

    (async () => {
      try {
        const idToken = await user.getIdToken();
        const data = await loadFinancials(idToken, selectedProjectId);

        if (data) {
          // Hydrate from Firestore
          setGri(data.income.grossRent);
          setOtherIncome(data.income.otherIncome);
          setVacancyPct(data.income.vacancyRate);
          setOpex(data.expenses.opex);
          setLoanAmount(data.financing.loanAmount);
          setInterestRate(data.financing.interestRate);
          setLoanTerm(data.financing.loanTermYears);
          setOtherDebt(data.financing.otherMonthlyDebt);
        } else {
          // First visit — show empty fields (undefined triggers placeholder text)
          setGri(undefined);
          setOtherIncome(undefined);
          setVacancyPct(undefined);
          setOpex(undefined);
          setLoanAmount(undefined);
          setInterestRate(undefined);
          setLoanTerm(undefined);
          setOtherDebt(undefined);
        }

        setLoadStatus("ready");
        // Small delay so the first render with data doesn't trigger auto-save
        setTimeout(() => { hasLoadedData.current = true; }, 200);
      } catch (err) {
        console.error("[FinancialsTerminal] Load error:", err);
        setLoadStatus("ready");
        hasLoadedData.current = true;
      }
    })();
  }, [selectedProjectId, user, projects.length]);

  // --- Also set the project in the store when switching ---
  useEffect(() => {
    if (selectedProject && selectedProject.id !== currentProject?.id) {
      setDeal(selectedProject);
    }
  }, [selectedProject, currentProject?.id, setDeal]);

  // --- Derived NOI ---
  const griVal = gri ?? 0;
  const otherIncomeVal = otherIncome ?? 0;
  const vacancyPctVal = vacancyPct ?? 0;
  const opexVal = opex ?? 0;
  const grossIncome = griVal + otherIncomeVal;
  const vacancyLoss = grossIncome * (vacancyPctVal / 100);
  const noi = grossIncome - vacancyLoss - opexVal;

  // --- Derived Cash Flow ---
  const loanAmountVal = loanAmount ?? 0;
  const interestRateVal = interestRate ?? 0;
  const loanTermVal = loanTerm ?? 0;
  const otherDebtVal = otherDebt ?? 0;
  const monthlyPI = computeMonthlyPayment(loanAmountVal, interestRateVal, loanTermVal);
  const annualDebtService = (monthlyPI + otherDebtVal) * 12;
  const cashFlow = noi - annualDebtService;
  const dscr = annualDebtService > 0 ? noi / annualDebtService : 0;

  const formatCur = (val: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 }).format(val);

  // --- Show toast ---
  const showToast = useCallback((message: string) => {
    setToastMessage(message);
    if (toastTimeout.current) clearTimeout(toastTimeout.current);
    toastTimeout.current = setTimeout(() => setToastMessage(""), 3000);
  }, []);

  // --- Save handler ---
  const handleSave = useCallback(async () => {
    if (!user || !selectedProjectId) return;
    setSaveStatus("saving");

    try {
      const idToken = await user.getIdToken();
      const payload: FinancialsPayload = {
        income: {
          grossRent: griVal,
          otherIncome: otherIncomeVal,
          vacancyRate: vacancyPctVal,
        },
        expenses: {
          opex: opexVal,
        },
        financing: {
          loanAmount: loanAmountVal,
          interestRate: interestRateVal,
          loanTermYears: loanTermVal,
          otherMonthlyDebt: otherDebtVal,
        },
      };

      await saveFinancials(idToken, selectedProjectId, payload);
      setSaveStatus("saved");
      showToast("Financials saved.");
      setTimeout(() => setSaveStatus("idle"), 2000);
    } catch (err: any) {
      console.error("[FinancialsTerminal] Save error:", err);
      setSaveStatus("error");
      showToast("Save failed — please try again.");
      setTimeout(() => setSaveStatus("idle"), 3000);
    }
  }, [user, selectedProjectId, griVal, otherIncomeVal, vacancyPctVal, opexVal, loanAmountVal, interestRateVal, loanTermVal, otherDebtVal, showToast]);

  // --- Debounced auto-save (1500ms after any field change) ---
  useEffect(() => {
    if (!hasLoadedData.current || loadStatus !== "ready") return;
    if (!selectedProjectId || !user) return;

    setSaveStatus("saving");
    if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);

    autoSaveTimer.current = setTimeout(() => {
      handleSave();
    }, 1500);

    return () => {
      if (autoSaveTimer.current) clearTimeout(autoSaveTimer.current);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [griVal, otherIncomeVal, vacancyPctVal, opexVal, loanAmountVal, interestRateVal, loanTermVal, otherDebtVal]);

  // --- No-project state ---
  if (loadStatus === "no-project") {
    return (
      <div className="min-h-screen bg-transparent text-on-surface font-body-md flex flex-col items-center justify-center gap-6">
        <span className="material-symbols-outlined text-white/40 text-5xl">apartment</span>
        <h2 className="font-headline-md text-xl text-on-surface">No projects yet</h2>
        <p className="text-on-surface-variant text-center max-w-md">
          Create your first investment project to start tracking financials.
        </p>
        <a href="/dashboard/projects/new" className="bg-primary text-on-primary px-6 py-3 rounded-lg font-bold hover:shadow-[0_0_20px_rgba(69,73,85,0.4)] transition-all">
          Create Project
        </a>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-transparent text-on-surface font-body-md pb-32">
      {/* TopAppBar */}
      <header className="sticky top-0 w-full z-50 bg-surface-container-lowest/80 backdrop-blur-xl border-b border-white/10 shadow-sm flex items-center justify-between px-6 h-20">
        <div className="flex items-center gap-4">
          <span className="material-symbols-outlined text-white/40 text-2xl">terminal</span>
          <h1 className="font-headline-md text-headline-md font-bold tracking-tighter text-white">Financial Terminal</h1>
        </div>

        {/* Project Selector + Auto-save Indicator */}
        <div className="flex items-center gap-4">
          {/* Auto-save status */}
          <div className="hidden md:flex items-center gap-2 text-xs font-mono">
            {saveStatus === "saving" && (
              <><span className="inline-block w-2 h-2 rounded-full bg-yellow-400 animate-pulse" /><span className="text-on-surface-variant">Saving…</span></>
            )}
            {saveStatus === "saved" && (
              <><span className="inline-block w-2 h-2 rounded-full bg-pw-success" /><span className="text-pw-success">Saved</span></>
            )}
            {saveStatus === "error" && (
              <><span className="inline-block w-2 h-2 rounded-full bg-error" /><span className="text-error">Error</span></>
            )}
          </div>

          {/* Project Dropdown */}
          <select
            value={selectedProjectId}
            onChange={(e) => setSelectedProjectId(e.target.value)}
            className="bg-surface-container-high border border-white/10 rounded-lg px-3 py-2 text-sm text-on-surface font-mono focus:border-primary focus:ring-1 focus:ring-primary outline-none max-w-[220px] truncate"
          >
            {projects.map((p) => (
              <option key={p.id} value={p.id}>
                {p.propertyName || p.address || `Project ${p.id.slice(0, 6)}`}
              </option>
            ))}
          </select>
        </div>
      </header>

      {/* Loading Skeleton */}
      {loadStatus === "loading" ? (
        <main className="w-full max-w-5xl mx-auto px-4 md:px-6 py-10 space-y-8">
          {[1, 2, 3].map((i) => (
            <div key={i} className="glass-card rounded-xl p-8 animate-pulse" style={{ background: "rgba(13, 10, 11, 0.6)", border: "1px solid rgba(255, 255, 255, 0.08)" }}>
              <div className="h-4 bg-white/10 rounded w-1/3 mb-6" />
              <div className="grid grid-cols-2 gap-4">
                <div className="h-10 bg-white/5 rounded" />
                <div className="h-10 bg-white/5 rounded" />
              </div>
            </div>
          ))}
        </main>
      ) : (
        <main className="w-full max-w-5xl mx-auto px-4 md:px-gutter-desktop py-stack-lg space-y-stack-lg">

          {/* --- NOI TERMINAL --- */}
          <div className="space-y-6">
            <h2 className="text-xl font-bold uppercase tracking-widest text-on-surface-variant flex items-center gap-2 border-b border-white/10 pb-2">
              1. NOI Input Terminal
            </h2>

            <NOIInputTerminal 
              gri={griVal} setGri={(v) => setGri(v)}
              otherIncome={otherIncomeVal} setOtherIncome={(v) => setOtherIncome(v)}
              vacancyPct={vacancyPctVal} setVacancyPct={(v) => setVacancyPct(v)}
              opex={opexVal} setOpex={(v) => setOpex(v)}
              vacancyLoss={vacancyLoss}
            />

            <div className="pt-4">
              <h3 className="text-sm font-bold uppercase tracking-widest text-on-surface-variant mb-4">NOI Analysis</h3>
              <div className="glass-card rounded-xl p-6 relative overflow-hidden" style={{ background: "rgba(13, 10, 11, 0.6)", backdropFilter: "blur(20px)", border: "1px solid rgba(255, 255, 255, 0.08)" }}>
                <NOIWaterfallChart 
                  grossIncome={grossIncome}
                  vacancyLoss={vacancyLoss}
                  opex={opexVal}
                  noi={noi}
                />
              </div>
            </div>
          </div>

          {/* --- CASH FLOW TERMINAL --- */}
          <div className="space-y-6 pt-8">
            <h2 className="text-xl font-bold uppercase tracking-widest text-on-surface-variant flex items-center gap-2 border-b border-white/10 pb-2">
              2. Cash Flow Datapoint Agent
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <CashFlowInputTerminal 
                loanAmount={loanAmountVal} setLoanAmount={(v) => setLoanAmount(v)}
                interestRate={interestRateVal} setInterestRate={(v) => setInterestRate(v)}
                loanTerm={loanTermVal} setLoanTerm={(v) => setLoanTerm(v)}
                otherDebt={otherDebtVal} setOtherDebt={(v) => setOtherDebt(v)}
              />

              <CashFlowDeepDive 
                annualDebtService={annualDebtService}
                monthlyPI={monthlyPI}
                dscr={dscr}
                cashFlow={cashFlow}
              />
            </div>
          </div>
        </main>
      )}

      {/* Sticky Footer */}
      <footer className="fixed bottom-0 w-full h-20 bg-surface-container-highest/90 backdrop-blur-2xl border-t border-primary/20 shadow-[0_-4px_20px_rgba(69,73,85,0.15)] z-[60]">
        <div className="h-full max-w-5xl mx-auto px-4 md:px-gutter-desktop flex items-center justify-between">
          <div className="flex-1 flex items-center gap-2 overflow-hidden">
            <div className="hidden lg:flex items-center gap-1 font-mono text-[10px] text-on-surface-variant font-bold uppercase truncate">
              NOI <span className="text-on-surface">{formatCur(noi)}</span>
              <span className="mx-1 opacity-20">|</span> 
              Debt Service <span className="text-error">{formatCur(annualDebtService)}</span>
              <span className="mx-2">=</span>
            </div>
            <div className="flex flex-col">
              <span className="text-[10px] uppercase tracking-widest text-on-surface-variant font-bold leading-none mb-1">Cash Flow</span>
              <div className={`font-mono text-xl md:text-[22px] font-bold whitespace-nowrap leading-none ${cashFlow > 0 ? 'text-primary' : 'text-error'}`}>
                {formatCur(cashFlow)}/yr <span className="text-sm font-sans font-medium text-on-surface-variant">({formatCur(cashFlow / 12)}/mo)</span>
              </div>
            </div>
          </div>
          <button
            onClick={handleSave}
            disabled={saveStatus === "saving" || loadStatus === "loading" || !selectedProjectId}
            className="bg-primary text-on-primary px-6 h-10 md:h-12 rounded-lg font-bold flex items-center gap-2 hover:shadow-[0_0_20px_rgba(69,73,85,0.4)] active:scale-95 transition-all duration-150 whitespace-nowrap ml-4 disabled:opacity-50 disabled:cursor-not-allowed"
          >
            {saveStatus === "saving" ? (
              <><span className="material-symbols-outlined animate-spin text-lg">progress_activity</span> Saving…</>
            ) : saveStatus === "saved" ? (
              <><span className="material-symbols-outlined text-lg">check_circle</span> Saved</>
            ) : (
              <>Save Financials <span className="material-symbols-outlined">arrow_forward</span></>
            )}
          </button>
        </div>
      </footer>

      {/* Toast */}
      {toastMessage && (
        <div className={`fixed bottom-24 left-1/2 -translate-x-1/2 z-[70] px-6 py-3 rounded-lg font-bold text-sm backdrop-blur-xl border transition-all duration-300 ${
          saveStatus === "error"
            ? "bg-error/20 border-error/30 text-error"
            : "bg-primary/20 border-primary/30 text-primary"
        }`}>
          {toastMessage}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { Suspense, useState, useCallback, useEffect, useRef } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import { Search, Plus, Loader2, CheckCheck, ArrowLeft, Settings } from 'lucide-react';
import { useInboxFeed } from '@/hooks/useInboxFeed';
import { useInboxThreads } from '@/hooks/useInboxThreads';
import { useAuth } from '@/context/AuthContext';
import { useProjectStore } from '@/store/projectStore';
import InboxTabs from '@/components/inbox/InboxTabs';
import InboxFeed from '@/components/inbox/InboxFeed';
import ThreadDetail from '@/components/inbox/ThreadDetail';
import NegotiationThreadDetail from '@/components/inbox/NegotiationThreadDetail';
import ComposeEmailModal from '@/components/inbox/ComposeEmailModal';
import toast from 'react-hot-toast';
import { executeInboxAction } from '@/lib/services/inboxActionExecutor';

/* ═══════════════════════════════════════════════════════
   Inbox — Unified Notification Center

   Combines notifications, team invitations, system alerts,
   and email threads into a single tabbed feed.

   Layout:
   ┌──────────────────────────────────────────────┐
   │  Header:  "Inbox" + badge + actions          │
   ├──────────────────────────────────────────────┤
   │  Tabs:  All │ Messages │ Invitations │ ...   │
   ├──────────────────────────────────────────────┤
   │  Feed:  Scrollable InboxItemCard list        │
   │  — OR —                                      │
   │  ThreadDetail:  Email thread view (slide-in) │
   └──────────────────────────────────────────────┘
   ═══════════════════════════════════════════════════════ */

/* ── Notification detail MoreMenu ───────────────────────
   Renders a ⋮ button in the reading pane header with three
   real, persisted actions. No action is rendered without
   an onClick handler.
   ─────────────────────────────────────────────────────── */
interface NotifMoreMenuProps {
  item: import('@/types/notification').Notification;
  onMarkUnread: () => void;
  onArchive: () => void;
  onDelete: () => void;
}

function NotifMoreMenu({ item, onMarkUnread, onArchive, onDelete }: NotifMoreMenuProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  return (
    <div ref={ref} className="relative">
      <button
        id="notif-more-menu-trigger"
        onClick={() => setOpen((v) => !v)}
        className="p-2 rounded-lg hover:bg-white/5 text-[#9E9DA0] transition-colors"
        aria-label="Notification actions"
        aria-expanded={open}
        aria-haspopup="true"
      >
        <span className="material-symbols-outlined" style={{ fontVariationSettings: "'FILL' 0" }}>more_vert</span>
      </button>

      {open && (
        <div
          id="notif-more-menu"
          role="menu"
          className="absolute right-0 top-full mt-1 w-52 rounded-xl border border-white/10 bg-[#161318] shadow-[0_8px_32px_-4px_rgba(0,0,0,0.6)] z-50 py-1 overflow-hidden"
        >
          <button
            id="notif-menu-mark-unread"
            role="menuitem"
            onClick={() => { onMarkUnread(); setOpen(false); }}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-[#9E9DA0] hover:bg-white/5 hover:text-white transition-colors text-left"
          >
            <span className="material-symbols-outlined text-base" style={{ fontVariationSettings: "'FILL' 0" }}>
              {item.read ? 'mark_email_unread' : 'drafts'}
            </span>
            {item.read ? 'Mark as Unread' : 'Mark as Read'}
          </button>
          <div className="my-1 border-t border-white/5" />
          <button
            id="notif-menu-archive"
            role="menuitem"
            onClick={() => { onArchive(); setOpen(false); }}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-[#9E9DA0] hover:bg-white/5 hover:text-white transition-colors text-left"
          >
            <span className="material-symbols-outlined text-base" style={{ fontVariationSettings: "'FILL' 0" }}>archive</span>
            Archive
          </button>
          <button
            id="notif-menu-delete"
            role="menuitem"
            onClick={() => { onDelete(); setOpen(false); }}
            className="w-full flex items-center gap-3 px-4 py-2.5 text-sm hover:bg-white/5 text-red-400/80 hover:text-red-400 transition-colors text-left"
          >
            <span className="material-symbols-outlined text-base" style={{ fontVariationSettings: "'FILL' 0" }}>delete</span>
            Delete
          </button>
        </div>
      )}
    </div>
  );
}

function InboxNotificationCenter() {
  useEffect(() => {
    document.title = "PaperWorking — Inbox";
  }, []);
  const searchParams = useSearchParams();
  const router = useRouter();
  const { user } = useAuth();
  const deals = useProjectStore((state) => state.projects);

  // ── Unified inbox feed (notifications, invitations, system) ──
  const {
    items,
    loading,
    loadingMore,
    error,
    unreadCounts,
    unreadTotal,
    activeTab,
    setActiveTab,
    markAsRead,
    markAsUnread,
    markAllRead,
    archiveItem,
    deleteItem,
    bulkArchive,
    bulkMarkRead,
    fetchMore,
    hasMore,
  } = useInboxFeed();

  // ── Legacy email threads (for the ThreadDetail slide-in) ──
  const {
    threads,
    markAsRead: markThreadAsRead,
    markAsUnread: markThreadAsUnread,
  } = useInboxThreads();

  const threadId = searchParams?.get('threadId') || searchParams?.get('thread') || null;
  const [searchQuery, setSearchQuery] = useState('');
  const [composeOpen, setComposeOpen] = useState(false);

  const activeThread = threadId
    ? threads.find((t) => t.projectId === threadId) || null
    : null;

  const activeProjectName = activeThread
    ? deals.find((d) => d.id === activeThread.projectId)?.propertyName || 'Project'
    : '';

  // Mark thread as read when entering detail view
  React.useEffect(() => {
    if (threadId && activeThread && activeThread.unreadCount > 0) {
      markThreadAsRead(threadId);
    }
  }, [threadId, activeThread?.unreadCount, markThreadAsRead]);

  /* ── Send reply in thread view ── */
  const handleSendReply = useCallback(
    async (body: string) => {
      if (!user || !threadId) return;

      try {
        const idToken = await user.getIdToken();
        const res = await fetch('/api/emails/send', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            idToken,
            projectId: threadId,
            to: activeThread?.messages
              .filter((m) => m.senderEmail && m.senderUid !== user.uid)
              .map((m) => m.senderEmail)
              .filter((v, i, a) => a.indexOf(v) === i)
              .slice(0, 10) || [],
            subject: activeThread?.lastMessage.subject || 'Re: Conversation',
            html: `<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;line-height:1.6;color:#333;white-space:pre-wrap;">${body}</div>`,
            text: body,
          }),
        });

        if (res.ok) {
          toast.success('Reply sent.', {
            icon: '✉️',
            style: { background: '#0d0d0d', color: '#fff' },
          });
        } else {
          const err = await res.json();
          toast.error(err.error || 'Failed to send.', {
            style: { background: '#0d0d0d', color: '#fff' },
          });
        }
      } catch (err) {
        console.error('[Inbox] Reply error:', err);
        toast.error('Network error.', {
          style: { background: '#0d0d0d', color: '#fff' },
        });
      }
    },
    [user, threadId, activeThread],
  );

  /* ── Handle "Mark All Read" ── */
  const handleMarkAllRead = async () => {
    await markAllRead();
    toast.success('All marked as read.', {
      icon: '✓',
      style: { background: '#0d0d0d', color: '#fff' },
    });
  };

  const [selectedNotificationId, setSelectedNotificationId] = useState<string | null>(null);
  const [isExecutingAction, setIsExecutingAction] = useState(false);

  /* ── Auto-mark-as-read when a notification is selected ── */
  // Mirrors the thread-view pattern above (markThreadAsRead on unreadCount change).
  useEffect(() => {
    if (selectedNotificationId) {
      const item = items.find((n) => n.id === selectedNotificationId);
      if (item && !item.read) {
        markAsRead(selectedNotificationId);
      }
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedNotificationId]);

  // If we have an active thread from URL, use that, otherwise use selected notification
  const selectedItem = items.find(item => item.id === selectedNotificationId) || null;

  const negotiationParamId = searchParams?.get('negotiationId') || searchParams?.get('negotiation') || null;
  const activeNegotiationId = negotiationParamId || 
    (selectedItem?.type === 'NEGOTIATION_UPDATE' ? (selectedItem.objectReference.metadata?.negotiationId as string) : null);

  const handleExecuteAction = async () => {
    if (!user || !selectedItem) return;
    setIsExecutingAction(true);
    const actionPromise = (async () => {
      const idToken = await user.getIdToken();
      const res = await executeInboxAction(selectedItem, idToken, user.email || '');
      if (res.success) {
        if (!selectedItem.read) {
          await markAsRead(selectedItem.id);
        }
      }
      return res.message;
    })();

    toast.promise(actionPromise, {
      loading: 'Executing action...',
      success: (msg) => msg,
      error: (err) => err.message || 'Action execution failed.',
    });

    try {
      await actionPromise;
    } catch (err) {
      console.error('[Inbox] Action execution error:', err);
    } finally {
      setIsExecutingAction(false);
    }
  };

  return (
    <>
      <div className="flex w-full h-[calc(100vh-64px)] bg-[#0d0a0b] text-[#9E9DA0] overflow-hidden">

        {/* ═══ List Pane (Left) ═══ */}
        <section className={`w-full md:w-[420px] border-r border-white/10 flex flex-col bg-[#161318]/50 shrink-0 ${ (activeThread || activeNegotiationId || selectedItem) ? 'hidden md:flex' : 'flex' }`}>
          <div className="p-6 space-y-4">
            <div className="flex items-center justify-between">
              <h3 className="text-2xl font-bold text-[#9E9DA0]">Inbox</h3>
              <div className="flex items-center gap-2">
                {unreadTotal > 0 && (
                  <span className="px-2 py-0.5 bg-[#454955]/10 text-[#454955] border border-[#454955]/20 rounded font-mono text-[10px] font-bold">
                    {unreadTotal} UNREAD
                  </span>
                )}
                {unreadTotal > 0 && (
                  <button
                    onClick={handleMarkAllRead}
                    className="p-1.5 rounded-lg hover:bg-white/5 text-[#9E9DA0] hover:text-[#454955] transition-colors"
                    title="Mark all as read"
                  >
                    <CheckCheck className="w-4 h-4" />
                  </button>
                )}
                <button
                  onClick={() => setComposeOpen(true)}
                  className="p-1.5 rounded-lg hover:bg-white/5 text-[#9E9DA0] hover:text-[#454955] transition-colors"
                  title="Compose email"
                >
                  <Plus className="w-4 h-4" />
                </button>
              </div>
            </div>

            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#9E9DA0] w-4 h-4" />
              <input 
                type="text"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Search logs..." 
                className="w-full bg-[#0d0a0b] border border-[#3c4a46] rounded-lg py-2 pl-10 pr-4 text-sm focus:border-[#454955] focus:ring-1 focus:ring-[#454955] outline-none transition-all placeholder:text-[#9E9DA0]/40 text-[#9E9DA0]"
              />
            </div>
          </div>

          {/* Tab filter bar */}
          <InboxTabs
            activeTab={activeTab}
            onTabChange={setActiveTab}
            unreadCounts={unreadCounts}
          />

          <div className="flex-1 overflow-y-auto no-scrollbar relative">
            <InboxFeed
              items={items.filter(item => item.title.toLowerCase().includes(searchQuery.toLowerCase()) || item.body.toLowerCase().includes(searchQuery.toLowerCase()))}
              loading={loading}
              loadingMore={loadingMore}
              error={error}
              activeTab={activeTab}
              onMarkRead={markAsRead}
              onArchive={archiveItem}
              onDelete={deleteItem}
              onBulkArchive={bulkArchive}
              onBulkMarkRead={bulkMarkRead}
              fetchMore={fetchMore}
              hasMore={hasMore}
              selectedItemId={selectedNotificationId}
              onSelectItem={setSelectedNotificationId}
            />
          </div>
        </section>

        {/* ═══ Reading/Action Pane (Right) ═══ */}
        <section className={`flex-1 flex flex-col bg-[#0d0a0b] relative overflow-hidden ${ (activeThread || activeNegotiationId || selectedItem) ? 'flex' : 'hidden md:flex' }`}>
          {/* Background Decorative Elements */}
          <div className="absolute -top-40 -right-40 w-96 h-96 bg-[#454955]/5 rounded-full blur-[100px] pointer-events-none"></div>
          <div className="absolute bottom-20 left-20 w-64 h-64 bg-[#7A9EAA]/5 rounded-full blur-[80px] pointer-events-none"></div>

          {activeThread ? (
            <ThreadDetail
              thread={activeThread}
              projectName={activeProjectName}
              onSendReply={handleSendReply}
              onBack={() => router.push('/dashboard/inbox')}
              onMarkThreadUnread={() => markThreadAsUnread(activeThread.projectId)}
            />
          ) : activeNegotiationId ? (
            <NegotiationThreadDetail
              negotiationId={activeNegotiationId}
              onBack={() => {
                setSelectedNotificationId(null);
                router.push('/dashboard/inbox');
              }}
            />
          ) : selectedItem ? (
            <div className="flex-1 overflow-y-auto z-10 flex flex-col">
               {/* Header Actions */}
                <div className="px-8 py-6 flex items-center justify-between border-b border-white/10 shrink-0 bg-[#0d0a0b]/50 backdrop-blur-sm">
                  <div className="flex items-center gap-4">
                    <button onClick={() => setSelectedNotificationId(null)} className="md:hidden p-2 -ml-2 rounded-lg hover:bg-white/5 text-[#9E9DA0] transition-colors">
                      <ArrowLeft className="w-5 h-5" />
                    </button>
                    <div className="h-12 w-12 rounded-xl bg-[#0d0a0b]/60 backdrop-blur-xl border border-white/10 shadow-[inset_1px_1px_0px_rgba(255,255,255,0.05)] flex items-center justify-center text-[#454955]">
                      <CheckCheck className="w-6 h-6" />
                    </div>
                    <div>
                      <h3 className="text-2xl font-bold text-[#9E9DA0]">{selectedItem.title}</h3>
                      <p className="text-[10px] font-mono text-[#454955] uppercase">
                        ID: {selectedItem.id.slice(0, 8)} • STATUS: {selectedItem.read ? 'READ' : 'UNREAD'}
                      </p>
                    </div>
                  </div>
                   <div className="flex gap-2">
                     <button onClick={() => archiveItem(selectedItem.id)} className="p-2 rounded-lg hover:bg-white/5 text-[#9E9DA0] transition-colors" title="Archive">
                       <span className="material-symbols-outlined" style={{ fontVariationSettings: "'FILL' 0" }}>archive</span>
                     </button>
                     <button onClick={() => deleteItem(selectedItem.id)} className="p-2 rounded-lg hover:bg-white/5 text-[#9E9DA0] transition-colors" title="Delete">
                       <span className="material-symbols-outlined" style={{ fontVariationSettings: "'FILL' 0" }}>delete</span>
