                    <div className="flex items-center justify-center gap-4 py-8">
                      {['VENDOR_BID', 'RECEIPT_APPROVAL', 'INVEST_INVITE', 'TEAM_INVITE', 'TEAM_INVITE_REMINDER'].includes(selectedItem.type) ? (
                        <button 
