        {/* Risk Strip Terminal */}
        <DSCRRiskStripTerminal
          defaultAnnualNOI={portfolioNOI}
          defaultMonthlyDebtService={portfolioDebtService}
          lenderMinDSCR={1.25}
          onValuesChange={handleValuesChange}
        />
