        itemStyle: { color: 'rgba(148,163,184,0.6)' },
        symbol: 'none',
      },
    ],
  };
  return <ReactECharts option={option} style={{ height: 260, width: '100%' }} opts={{ renderer: 'canvas' }} />;
}

