                <td colSpan={4} className="py-2 px-3 text-[10px] font-bold uppercase tracking-widest text-[#6E7480]/70 border-b border-white/[0.04]">
                  Income Sources
                </td>
              </tr>
              {incomeRows.map((row) => {
