const fallbackMonths = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const fallbackValues = [920 * 1000, 940 * 1000, 910 * 1000, 970 * 1000, 985 * 1000, 1020000, 1050000, 1080000, 1100000, 1150000, 1190000, 1240000];

