'use client';

import React, { useCallback, useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { getAuth } from 'firebase/auth';
import {
  Building2,
  TrendingUp,
  Landmark,
  PiggyBank,
  Wrench,
  RefreshCw,
  Unlink,
  Clock,
  CheckCircle2,
  AlertTriangle,
  WifiOff,
  PenLine,
  UploadCloud,
  ShieldCheck,
  ExternalLink,
  ChevronDown,
  ChevronUp,
  Zap,
} from 'lucide-react';
import { PlaidLinkButton } from '@/components/plaid/PlaidLinkButton';
import type { ConnectionPurpose, PlaidSuccessData } from '@/components/plaid/PlaidLinkButton';

/* ─── Types ──────────────────────────────────────────────────── */
type ConnectionStatus = 'NOT_CONNECTED' | 'ACTIVE' | 'PENDING_AUTH' | 'ERROR' | 'DISCONNECTED' | 'EXPIRED';

interface PlaidConnection {
  id: string;
  connectionPurpose: ConnectionPurpose;
  status: ConnectionStatus;
  institutionName: string | null;
  accountName: string | null;
  accountMask: string | null;
  lastSyncAt: string | null;
  lastSuccessfulSyncAt: string | null;
  syncErrorCount: number;
  lastSyncErrorMessage: string | null;
  consentTimestamp: string | null;
  consentedProducts: string[];
}

/* ─── Purpose metadata ───────────────────────────────────────── */
interface PurposeMeta {
  purpose: ConnectionPurpose;
  label: string;
  description: string;
  icon: React.ElementType;
  color: string;
  bg: string;
  optional?: boolean;
}

const PURPOSES: PurposeMeta[] = [
  {
    purpose: 'RENT_COLLECTION',
    label: 'Rent Collection',
