interface KpiData {
  grossRent: number;
  otherIncome: number;
  vacancyLoss: number;
  egi: number;
  opex: number;
  noi: number;
  debtService: number;
  annualCashFlow: number;
  monthlyCashFlow: number;
  propertyValue: number;
  totalCashInvested: number;
  cashOnCashReturn: number;
  dscr: number;
  capRate: number;
  oer: number;
  occupancyRate: number;
  vacancyRate: number;
  grossYield: number;
  rentPerUnit: number;
  expensePerUnit: number;
  capexReserve: number;
  ytdInterestPaid: number;
  loanBalance: number;
  equity: number;
  cashPosition: number;
}

interface ActivityItem {
  id: string;
  payee: string;
  category: string;
  amount: number;
  date: string;
  impactNote: string;
}

interface TrendItem {
  month: string;
  cashOnCash: number;
  dscr: number;
  capRate: number;
  noi: number;
  cashFlow: number;
  occupancy: number;
}

async function getIdToken(): Promise<string | null> {
  const user = getAuth().currentUser;
  if (!user) return null;
  return user.getIdToken();
}

export default function ExitInsightsPage() {
  const params = useParams();
  const router = useRouter();
  const projectId = params?.id as string;

  const [kpis, setKpis] = useState<KpiData | null>(null);
  const [recentActivity, setRecentActivity] = useState<ActivityItem[]>([]);
  const [trends, setTrends] = useState<TrendItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [isPulsing, setIsPulsing] = useState(false);
  const [selectedKpiModal, setSelectedKpiModal] = useState<{ name: string; key: keyof TrendItem } | null>(null);

  /* ── Fetch Current Snapshot ── */
  const loadKpis = useCallback(async () => {
    if (!projectId) return;
    try {
      const token = await getIdToken();
      const res = await fetch(`/api/projects/${projectId}/kpis/current`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (!res.ok) throw new Error('Failed to load KPIs');
      const data = await res.json();
      setKpis(data.kpis);
      setRecentActivity(data.recentActivity ?? []);
      setTrends(data.trends ?? []);
    } catch (err) {
      console.error('[ExitInsights] Error loading KPIs:', err);
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  useEffect(() => {
    void loadKpis();
  }, [loadKpis]);

  /* ── SSE Event Stream Integration ── */
  useEffect(() => {
    if (!projectId) return;
    const es = new EventSource(`/api/events/stream?projectId=${projectId}`);

    es.addEventListener(`kpi:updated:${projectId}`, () => {
      void loadKpis();
      setIsPulsing(true);
      setTimeout(() => setIsPulsing(false), 2000);
    });

    es.addEventListener(`kpi:significant-change:${projectId}`, () => {
      void loadKpis();
      setIsPulsing(true);
      setTimeout(() => setIsPulsing(false), 3500);
    });

    return () => {
      es.close();
    };
  }, [projectId, loadKpis]);

  if (loading) {
    return (
      <div className="min-h-screen p-12 flex flex-col items-center justify-center gap-3">
        <RefreshCw size={28} className="animate-spin text-slate-300" />
        <span className="text-xs text-slate-400 font-mono">Recalculating 33 Investment KPIs…</span>
      </div>
    );
  }

  const activeKpis = kpis ?? {
    grossRent: 12000,
