                          )}
                          {!s.isBase && s.id !== 'base' && s.id !== 'upside' && s.id !== 'downside' && (
                            <button
                              onClick={() => handleDeleteScenario(s.id)}
                              className="p-1 rounded text-rose-500 hover:bg-rose-500/10 transition-colors"
