async function fetchProject(id: string, token: string) {
  const res = await fetch(`/api/reil/projects/${id}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) throw new Error("Project not found.");
  return res.json();
}

