                          </div>
                        </td>
                      </tr>
                    );
                  })
                )}
              </tbody>
            </table>
          </div>
        </div>

        {/* Right Column: Pending Invites (lg:col-span-4) */}
        <aside className="lg:col-span-4 flex flex-col gap-6">

