                <button
                  type="submit"
                  className="px-5 py-2 bg-neutral-900 text-neutral-50 dark:bg-neutral-50 dark:text-neutral-900 hover:opacity-90 rounded-md text-xs font-semibold transition-all cursor-pointer"
                >
                  Send Invitations
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
