          {/* Broadcast Sender Message */}
          {isBroadcast && tokenData?.message && (
            <div data-testid="sender-broadcast-message" className="p-4 rounded-[12px] bg-white/[0.03] border border-white/10 text-xs text-slate-300 space-y-1">
