          {/* Sender Business Card if included */}
          {isBroadcast && (tokenData?.includeBusinessCard !== false) && (
            <div data-testid="sender-business-card" className="p-4 rounded-[12px] bg-white/[0.04] border border-white/10 space-y-2">
