                >
                  Remove from comparison
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { doc, getDoc } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { useProjectStore } from '@/store/projectStore';
import { usePropertyStore } from '@/store/propertyStore';
import { Sidebar } from '@/components/layout/Sidebar';
import { BottomNav } from '@/components/layout/BottomNav';
import { TopAppBar } from '@/components/layout/TopAppBar';
import { CommandCenter } from '@/components/dashboard/command-center/CommandCenter';
import { NotificationProvider } from '@/context/NotificationContext';
import { Loader2, ShieldAlert } from 'lucide-react';
import toast from 'react-hot-toast';

export default function DemoPage() {
  const setDeals = useProjectStore((s) => s.setDeals);
  const setLedgerItems = useProjectStore((s) => s.setLedgerItems);
  const setProperties = usePropertyStore((s) => s.setProperties);
  const setTransactions = usePropertyStore((s) => s.setTransactions);
  const setPropertyLoading = usePropertyStore((s) => s.setIsLoading);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function loadDemoData() {
      try {
        setLoading(true);
        setError(null);
        setPropertyLoading(true);

        const docRef = doc(db, 'demo', 'default');
        const snap = await getDoc(docRef);

        if (!snap.exists()) {
          throw new Error('Demo data not found in Firestore. Make sure to run seed-demo script.');
        }

        const data = snap.data();

        // Hydrate Project Store
        if (data.projects) {
          setDeals(data.projects);
          // Auto select first project
          if (data.projects.length > 0) {
            useProjectStore.setState({ currentProject: data.projects[0] });
          }
        }

        // Hydrate Ledger Items
        if (data.ledgerItems) {
          Object.entries(data.ledgerItems).forEach(([projId, items]: [string, any]) => {
            // Convert strings back to Dates if necessary
            const formattedItems = items.map((item: any) => ({
              ...item,
              createdAt: item.createdAt ? new Date(item.createdAt) : new Date(),
              updatedAt: item.updatedAt ? new Date(item.updatedAt) : undefined,
            }));
            setLedgerItems(projId, formattedItems);
          });
        }

        // Hydrate Property Store
        if (data.properties) {
          const formattedProps = data.properties.map((prop: any) => ({
            ...prop,
            purchaseDate: prop.purchaseDate ? new Date(prop.purchaseDate) : new Date(),
            createdAt: prop.createdAt ? new Date(prop.createdAt) : new Date(),
            updatedAt: prop.updatedAt ? new Date(prop.updatedAt) : new Date(),
          }));
          setProperties(formattedProps);
        }

        if (data.transactions) {
          const formattedTxs = data.transactions.map((tx: any) => ({
            ...tx,
            date: tx.date ? new Date(tx.date) : new Date(),
          }));
          setTransactions(formattedTxs);
        }

        toast.success('Loaded read-only demo dataset!', {
          icon: '✨',
          style: { background: '#111', color: '#fff', border: '1px solid #333' }
        });
      } catch (err: any) {
        console.error('Error fetching demo data:', err);
        setError(err.message || 'Failed to load demo data.');
      } finally {
        setLoading(false);
        setPropertyLoading(false);
      }
    }

    loadDemoData();

    return () => {
      useProjectStore.getState().clearStore();
      usePropertyStore.getState().clearStore();
    };
  }, [setDeals, setLedgerItems, setProperties, setTransactions, setPropertyLoading]);

  if (loading) {
    return (
      <div 
        className="flex flex-col items-center justify-center min-h-screen text-on-surface"
        style={{
          background: 'linear-gradient(135deg, #0d0a0b 0%, #0f1922 40%, #0d0a0b 100%)',
        }}
      >
        <Loader2 className="w-10 h-10 animate-spin text-pw-primary mb-4" />
        <p className="text-sm text-pw-muted uppercase tracking-widest font-semibold animate-pulse">Initializing Demo Workspace...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div 
        className="flex flex-col items-center justify-center min-h-screen text-on-surface p-6 text-center"
        style={{
          background: 'linear-gradient(135deg, #0d0a0b 0%, #0f1922 40%, #0d0a0b 100%)',
        }}
      >
        <ShieldAlert className="w-12 h-12 text-error mb-4 animate-bounce" />
        <h1 className="text-xl font-bold mb-2">Failed to Load Demo Mode</h1>
        <p className="text-sm text-pw-muted mb-6 max-w-md">{error}</p>
        <Link href="/" className="px-5 py-2.5 bg-pw-glass-bg border border-pw-border rounded-xl text-xs font-bold uppercase tracking-wider hover:bg-white/5 transition-colors">
          Return to Home
        </Link>
      </div>
    );
  }

  return (
    <NotificationProvider>
      <div 
        className="dashboard-context flex flex-col md:flex-row h-screen overflow-hidden text-on-surface"
        style={{
          background: 'linear-gradient(135deg, #0d0a0b 0%, #0f1922 40%, #0d0a0b 100%)',
        }}
      >
        {/* Sidebar (Desktop) */}
        <Sidebar />

        {/* Main Content Area */}
        <div className="flex-1 flex flex-col h-screen relative overflow-hidden">
          {/* Top App Bar (Mobile & Desktop) */}
          <TopAppBar />

          {/* Persistent Glassmorphic Demo Banner */}
          <div 
            className="flex flex-col sm:flex-row items-center justify-center gap-2 sm:gap-4 px-6 py-3 text-center text-xs font-semibold select-none z-10 shrink-0"
            style={{
              background: 'linear-gradient(90deg, rgba(69, 73, 85,0.08) 0%, rgba(69, 73, 85,0.04) 50%, rgba(69, 73, 85,0.08) 100%)',
              borderBottom: '1px solid rgba(69, 73, 85,0.15)',
              backdropFilter: 'blur(12px)',
              color: 'rgba(253, 255, 252, 0.95)',
            }}
          >
            <span className="flex items-center gap-1.5 text-pw-primary">
              <span className="relative flex h-2 w-2">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-75 bg-pw-primary" />
                <span className="relative inline-flex rounded-full h-2 w-2 bg-pw-primary" />
              </span>
              Demo Mode Active
            </span>
            <span className="opacity-80">You are viewing a read-only example account.</span>
            <Link 
              href="/register" 
              className="inline-flex items-center gap-1 text-[#454955] hover:text-[#454955]/80 underline transition-all font-bold"
            >
              Sign up to start your own portfolio
              <span className="material-symbols-outlined text-[14px]">arrow_forward</span>
            </Link>
          </div>

          {/* Scrollable Content Canvas */}
          <div className="flex-1 overflow-y-auto pb-24 md:pb-8 custom-scrollbar">
            <CommandCenter />
          </div>
        </div>

        {/* Bottom Nav (Mobile) */}
        <BottomNav />
      </div>
    </NotificationProvider>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import Link from 'next/link';
import { Search, BookOpen, Compass, ChevronRight, HelpCircle, ArrowRight } from 'lucide-react';
import type { HelpArticle } from '@/lib/help/loader';

interface HelpCenterClientProps {
  initialArticles: HelpArticle[];
}

export default function HelpCenterClient({ initialArticles }: HelpCenterClientProps) {
  const [searchQuery, setSearchQuery] = useState('');

  // Client-side search filtering
  const filteredArticles = useMemo(() => {
    if (!searchQuery.trim()) return initialArticles;
    const query = searchQuery.toLowerCase().trim();
    return initialArticles.filter(
      (a) =>
        a.title.toLowerCase().includes(query) ||
        a.excerpt.toLowerCase().includes(query) ||
        a.slug.toLowerCase().includes(query) ||
        a.rawContent.toLowerCase().includes(query)
    );
  }, [searchQuery, initialArticles]);

  const screensArticles = useMemo(() => {
    return filteredArticles.filter((a) => a.category === 'screens');
  }, [filteredArticles]);

  const metricsArticles = useMemo(() => {
    return filteredArticles.filter((a) => a.category === 'metrics');
  }, [filteredArticles]);

  return (
    <div className="w-full max-w-4xl mx-auto py-8 px-6">
      {/* Hero Header */}
      <div className="text-center mb-10">
        <span className="uppercase tracking-widest text-xs font-black text-pw-success mb-3 block">
          Support & Knowledge Base
        </span>
        <h1 className="font-light tracking-tighter text-[var(--pw-black)] mb-6 type-display font-semibold">
          How can we help you build?
        </h1>
        <p className="text-sm text-[var(--pw-muted)] max-w-xl mx-auto mb-8">
          Detailed screen guides, walkthroughs, and clear metrics explainers with formulas to help you manage your real estate portfolio.
        </p>

        {/* Big Search Input */}
        <div className="max-w-2xl mx-auto relative group">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[var(--pw-muted)] group-focus-within:text-pw-success transition-colors" />
          <input
            id="help-center-search"
            type="search"
            placeholder="Search NOI, Cash Flow, first project..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full pl-12 pr-6 py-4 bg-white/5 backdrop-blur-xl border border-[var(--pw-border)] rounded-2xl text-sm focus:outline-none focus:border-pw-success focus:ring-pw-success transition-all text-[var(--pw-black)] placeholder:text-[var(--pw-muted)]"
          />
        </div>
      </div>

      {/* Grid of Results */}
      {filteredArticles.length === 0 ? (
        <div className="text-center py-12 border border-dashed border-[var(--pw-border)] rounded-2xl bg-white/5">
          <HelpCircle className="w-12 h-12 text-[var(--pw-muted)] mx-auto mb-4" />
          <p className="text-sm font-medium text-[var(--pw-black)]">No articles found matching "{searchQuery}"</p>
          <p className="text-xs text-[var(--pw-muted)] mt-1">Try checking your spelling or searching for metrics like "Cap Rate"</p>
        </div>
      ) : (
        <div className="space-y-16">
          {/* Screens Section */}
          {screensArticles.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-6 border-b border-[var(--pw-border)] pb-3">
                <Compass className="w-5 h-5 text-pw-success" />
                <h2 className="text-xs uppercase tracking-widest font-black text-[var(--pw-black)]">
                  Platform Screen Guides ({screensArticles.length})
                </h2>
              </div>
              <div className="grid md:grid-cols-2 gap-4">
                {screensArticles.map((article) => (
                  <Link
                    key={article.slug}
                    href={`/help/${article.slug}`}
                    className="p-5 rounded-xl border border-[var(--pw-border)] bg-white/5 hover:bg-white/10 transition-all flex flex-col justify-between group"
                  >
                    <div>
                      <h3 className="text-base font-bold text-[var(--pw-black)] mb-2 group-hover:text-pw-success transition-colors">
                        {article.title}
                      </h3>
                      <p className="text-xs text-[var(--pw-muted)] leading-relaxed line-clamp-2">
                        {article.excerpt}
                      </p>
                    </div>
                    <div className="mt-4 flex items-center gap-1 text-[10px] uppercase tracking-widest font-black text-pw-success">
                      Read Guide <ArrowRight className="w-3.5 h-3.5 group-hover:translate-x-1 transition-transform" />
                    </div>
                  </Link>
                ))}
              </div>
            </div>
          )}

          {/* Metrics Section */}
          {metricsArticles.length > 0 && (
            <div>
              <div className="flex items-center gap-2 mb-6 border-b border-[var(--pw-border)] pb-3">
                <BookOpen className="w-5 h-5 text-pw-success" />
                <h2 className="text-xs uppercase tracking-widest font-black text-[var(--pw-black)]">
                  Metric Explainers ({metricsArticles.length})
                </h2>
              </div>
              <div className="grid md:grid-cols-2 gap-4">
                {metricsArticles.map((article) => (
                  <Link
                    key={article.slug}
                    href={`/help/${article.slug}`}
                    className="p-5 rounded-xl border border-[var(--pw-border)] bg-white/5 hover:bg-white/10 transition-all flex flex-col justify-between group"
                  >
                    <div>
                      <h3 className="text-base font-bold text-[var(--pw-black)] mb-2 group-hover:text-pw-success transition-colors">
                        {article.title}
                      </h3>
                      <p className="text-xs text-[var(--pw-muted)] leading-relaxed line-clamp-2">
                        {article.excerpt}
                      </p>
                    </div>
                    <div className="mt-4 flex items-center gap-1 text-[10px] uppercase tracking-widest font-black text-pw-success">
