            {step < 3 ? (
              <button
                type="button"
                onClick={handleNext}
                className="px-5 py-2.5 bg-primary text-black rounded-lg text-sm font-semibold hover:opacity-90 shadow-lg shadow-primary/10 transition-all flex items-center gap-1.5"
