            Project Creation Wizard
          </span>
          <span className="text-xs font-mono text-slate-400">Step {currentStep} of 3</span>
        </div>
        <h1 className="text-2xl font-bold text-white">Create New Real Estate Project</h1>
      </div>

      {/* Wizard Progress Indicator */}
