      </main>

      {/* Footer */}
      <footer className="px-8 py-6 text-center border-t border-white/5 text-[11px] text-pw-muted">
        &copy; {new Date().getFullYear()} PaperWorking Inc. All rights reserved. 
        Read our terms of service and compliance rules.
      </footer>
    </div>
  );
}

