  const baselineTimeline = currentProject.financials.estimatedTimelineDays || 0;

  // Compute naive margin diff for presentation
  // Because 'metrics' represents the aggregated state, changing 'offset' instantly
  // recompiles 'projectedProfit' on the dealStore directly. We just show it.

  return (
    <div className="bg-gradient-to-br from-[#1e1b20]/60 to-[#0d0a0b]/80 border border-white/10 rounded-xl p-6 shadow-xl text-white backdrop-blur-md">
      <div className="flex items-center justify-between border-b border-white/10 pb-4 mb-6">
        <div className="flex items-center space-x-2">
          <SlidersHorizontal className="w-5 h-5 text-[#454955]" />
          <h3 className="text-lg font-semibold tracking-wide">"What-If" Stress Test</h3>
        </div>
        <span className="text-xs bg-[#454955]/20 text-[#454955] px-2 flex items-center py-1 rounded">
           <AlertCircle className="w-3 h-3 mr-1" /> Memory Only
        </span>
      </div>

      <div className="mb-8">
        <div className="flex justify-between items-end mb-2">
           <label className="text-sm font-medium text-[#C0BEC2]">Timeline Delay Simulator</label>
           <span className="text-2xl font-normal text-white">+{offset} mo</span>
        </div>

        <input 
           type="range" 
           min="0" 
           max="12" 
           step="1"
           value={offset}
           onChange={(e) => setOffset(parseInt(e.target.value))}
           className="w-full h-2 bg-[#0d0a0b] rounded-lg appearance-none cursor-pointer accent-[#454955]"
        />
        <div className="flex justify-between text-xs text-[#9E9DA0] mt-2">
           <span>Base: {baselineTimeline} mo</span>
           <span>Severe Delay (+12 mo)</span>
        </div>
      </div>

      <div className="bg-black/20 rounded-lg p-4 border border-white/5">
         <p className="text-xs text-[#9E9DA0] uppercase tracking-widest mb-1 flex items-center">
            <TrendingDown className="w-3 h-3 mr-1 text-[#F06543]" /> Projected Net Margin
         </p>
         <p className={`text-4xl font-mono ${metrics.projectedProfit < 0 ? 'text-[#F06543]' : 'text-[#3f7d20]'}`}>
            ${metrics.projectedProfit.toLocaleString()}
         </p>
         <p className="text-xs text-[#9E9DA0] mt-2">
            Total active holding costs calculated across portfolio: <span className="text-[#F06543]">${metrics.totalHoldingCosts.toLocaleString(undefined, { maximumFractionDigits: 0 })}</span>
         </p>
      </div>
    </div>
  );
}

