import React from 'react';
import ReactECharts from 'echarts-for-react';

interface NOIWaterfallPoint {
  name: string;
  value: number;
  fill: string;
  type: string;
}

interface NOIWaterfallChartProps {
  data: NOIWaterfallPoint[];
  height?: number | string;
}

const fmtUSD = (v: number) =>
  v < 0
    ? `-$${Math.abs(v).toLocaleString('en-US', { maximumFractionDigits: 0 })}`
    : `$${v.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;

export default function NOIWaterfallChart({ data, height = 300 }: NOIWaterfallChartProps) {
  // Compute ECharts Waterfall series data
  let runningSum = 0;
  const helperData: number[] = [];
  const valueData: number[] = [];
  const colors: string[] = [];

  data.forEach((item, index) => {
    if (index === 0) {
      // First is starting Gross Rent (represented as total column starting at 0)
      helperData.push(0);
      valueData.push(item.value);
      runningSum = item.value;
    } else if (index === data.length - 1) {
      // Last column is final NOI (represented as total column starting at 0)
      helperData.push(0);
      valueData.push(item.value);
    } else {
      // Intermediate delta columns
      if (item.value >= 0) {
        helperData.push(runningSum);
        valueData.push(item.value);
        runningSum += item.value;
      } else {
        runningSum += item.value; // item.value is negative
        helperData.push(runningSum);
        valueData.push(Math.abs(item.value));
      }
    }
    colors.push(item.fill);
  });

  const option = {
    tooltip: {
      trigger: 'axis',
      backgroundColor: '#1e1b20', // var(--color-surface-container)
      borderColor: 'rgba(255, 255, 255, 0.1)',
      textStyle: {
        color: '#9E9DA0', // var(--color-on-surface)
        fontSize: 12,
        fontFamily: 'Plus Jakarta Sans, sans-serif'
      },
      formatter: (params: any[]) => {
        // Find the visible bar parameter
        const visibleParam = params.find(p => p.seriesName === 'Value');
        if (!visibleParam) return '';
        const idx = visibleParam.dataIndex;
        const item = data[idx];
        if (!item) return '';

        return `
          <div style="font-family: inherit; font-size: 12px; padding: 4px;">
            <strong style="color: #9E9DA0; display: block; margin-bottom: 4px;">${item.name}</strong>
            <span style="color: #9E9DA0">Amount:</span> <strong style="color: ${item.value >= 0 ? '#454955' : '#ffb4ab'}">${fmtUSD(item.value)}</strong>
          </div>
        `;
      }
    },
    grid: {
      top: 20,
      right: 20,
      bottom: 40,
      left: 60,
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: data.map(d => d.name),
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: {
        color: '#9E9DA0',
        fontSize: 9,
        fontFamily: 'Plus Jakarta Sans, sans-serif',
        interval: 0,
        rotate: -30
      }
    },
    yAxis: {
      type: 'value',
      splitLine: {
        lineStyle: {
          type: 'dashed',
          color: 'rgba(255, 255, 255, 0.05)'
        }
      },
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: {
        color: '#9E9DA0',
        fontSize: 9,
        fontFamily: 'Plus Jakarta Sans, sans-serif',
        formatter: (v: number) => {
          if (Math.abs(v) >= 1000) return `$${(v / 1000).toFixed(0)}k`;
          return `$${v}`;
        }
      }
    },
    series: [
      {
        name: 'Placeholder',
        type: 'bar',
        stack: 'Total',
        silent: true,
        itemStyle: {
          borderColor: 'transparent',
          color: 'transparent'
        },
        data: helperData
      },
      {
        name: 'Value',
        type: 'bar',
        stack: 'Total',
        data: valueData.map((val, idx) => ({
          value: val,
          itemStyle: {
            color: colors[idx]
          }
        })),
        barMaxWidth: 30,
        label: {
          show: true,
          position: 'inside',
          formatter: (params: any) => {
            const idx = params.dataIndex;
            const item = data[idx];
            if (!item || Math.abs(item.value) < 100) return '';
            return fmtUSD(item.value);
          },
          fontSize: 9,
          fontFamily: 'Plus Jakarta Sans, sans-serif',
          color: '#ffffff'
        }
      }
    ]
  };

  return <ReactECharts option={option} style={{ height, width: '100%' }} opts={{ renderer: 'svg' }} />;
}

import React from 'react';
import ReactECharts from 'echarts-for-react';

interface OccupancyData {
  name: string;
  occupancyRate: number;
}

interface OccupancyChartProps {
  data: OccupancyData[];
  height?: number | string;
}

export default function OccupancyChart({ data, height = 300 }: OccupancyChartProps) {
  const options = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      formatter: (params: any) => {
        const item = params[0];
        const val = item.value;
        return `
          <div style="font-family: inherit; font-size: 12px;">
            <strong>${item.name}</strong><br/>
            <span style="color: #7F7F7F">Occupancy:</span> <strong style="color: #595959">${val.toFixed(1)}%</strong><br/>
            <span style="color: #F06543">Vacancy:</span> <strong>${(100 - val).toFixed(1)}%</strong>
          </div>
        `;
      }
    },
    grid: {
      top: 30,
      right: 20,
      bottom: 60,
      left: 40,
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: data.map(d => d.name),
      axisLabel: {
        rotate: 30,
        interval: 0,
        fontSize: 10,
        color: '#A5A5A5',
        margin: 15
      },
      axisTick: { show: false },
      axisLine: { show: false }
    },
    yAxis: {
      type: 'value',
      max: 100,
      min: 0,
      interval: 20,
      axisLabel: {
        formatter: '{value}%',
        fontSize: 10,
        color: '#A5A5A5'
      },
      splitLine: {
        lineStyle: {
          type: 'dashed',
          color: '#F2F2F2'
        }
      }
    },
    series: [
      {
        type: 'bar',
        data: data.map(d => {
          let color = '#595959';
          if (d.occupancyRate < 80) color = '#DC2626';
          else if (d.occupancyRate < 90) color = '#F06543';
          else if (d.occupancyRate >= 97) color = '#595959';
          else if (d.occupancyRate >= 93) color = '#7F7F7F';
          else color = '#A5A5A5';

          return {
            value: d.occupancyRate,
            itemStyle: {
              color,
              borderRadius: [4, 4, 0, 0]
            }
          };
        }),
        barMaxWidth: 40,
        markArea: {
          silent: true,
          data: [
            [
              {
                yAxis: 88,
                itemStyle: {
                  color: 'rgba(89,89,89,0.06)'
                },
                label: {
                  show: true,
                  formatter: 'U.S. Norm (88%-92%)',
                  position: 'insideLeft',
                  color: '#A5A5A5',
                  fontSize: 8
                }
              },
              {
                yAxis: 92
              }
            ]
          ]
        },
        markLine: {
          symbol: 'none',
          data: [
            {
              yAxis: 90,
              label: {
                formatter: '90% U.S. avg',
                position: 'insideEndTop',
                color: '#6B7280',
                fontSize: 9
              },
              lineStyle: {
                color: '#6B7280',
                type: 'dashed'
              }
            }
          ]
        }
      }
    ]
  };

  return <ReactECharts option={options} style={{ height, width: '100%' }} />;
}

'use client';

import React from 'react';
import ReactECharts from 'echarts-for-react';

interface ProjectComparisonPoint {
  projectId: string;
  projectName: string;
  value: number;
}

interface PortfolioComparisonChartProps {
  data: ProjectComparisonPoint[];
  metricId: string;
  averageValue: number | null;
  height?: number | string;
}

export function PortfolioComparisonChart({
  data,
  metricId,
  averageValue,
  height = 320
}: PortfolioComparisonChartProps) {

  // Truncate name helper
  const truncateName = (name: string) => {
    if (name.length > 15) {
      return `${name.substring(0, 12)}...`;
    }
    return name;
  };

  const lowerIsBetter = [
    'grm',
    'ltv',
    'oer',
    'tenant_turnover',
    'days_on_market',
    'maintenance_per_unit',
    'risk_score'
  ].includes(metricId.toLowerCase());

  // Determine top 3 and bottom 3 indices
  // 1. Pair value with original index
  const indexedData = data.map((d, index) => ({ ...d, originalIndex: index }));

  // 2. Sort by value ascending
  const sorted = [...indexedData].sort((a, b) => a.value - b.value);

  const top3OriginalIdxs = new Set<number>();
  const bottom3OriginalIdxs = new Set<number>();

  if (sorted.length > 0) {
    if (lowerIsBetter) {
      // Lower values are better (Top)
      // Top 3: first 3 items in sorted array
      sorted.slice(0, 3).forEach(item => top3OriginalIdxs.add(item.originalIndex));
      // Bottom 3: last 3 items in sorted array
      sorted.slice(Math.max(3, sorted.length - 3)).forEach(item => bottom3OriginalIdxs.add(item.originalIndex));
    } else {
      // Higher values are better (Top)
      // Top 3: last 3 items in sorted array
      sorted.slice(Math.max(0, sorted.length - 3)).forEach(item => top3OriginalIdxs.add(item.originalIndex));
      // Bottom 3: first 3 items in sorted array
      sorted.slice(0, Math.min(sorted.length - 3, 3)).forEach(item => bottom3OriginalIdxs.add(item.originalIndex));
    }
  }

  // Format value display based on metric type
  const formatVal = (v: number) => {
    const mId = metricId.toLowerCase();
    if (mId.includes('rate') || mId === 'coc' || mId === 'oer' || mId === 'ltv' || mId === 'tenant_turnover' || mId === 'lease_renewal' || mId === 'roi') {
      return `${v.toFixed(1)}%`;
    }
    if (mId === 'dscr' || mId === 'grm' || mId === 'equity_multiple' || mId === 'listing_to_meeting' || mId === 'interest_coverage') {
      return `${v.toFixed(2)}`;
    }
    if (mId === 'days_on_market' || mId === 'payback_period') {
      return `${Math.round(v)} days`;
    }
    if (mId.includes('price') || mId === 'noi' || mId === 'cash_flow' || mId === 'capex' || mId === 'goi' || mId === 'maintenance_per_unit' || mId === 'construction_per_sqft' || mId === 'avg_commission') {
      return `$${v.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;
    }
    return `${v}`;
  };

  const option = {
    tooltip: {
      trigger: 'axis',
      axisPointer: { type: 'shadow' },
      backgroundColor: 'rgba(30, 27, 32, 0.95)',
      borderColor: 'rgba(255, 255, 255, 0.1)',
      textStyle: {
        color: '#E2E8F0',
        fontSize: 12,
        fontFamily: 'Inter, sans-serif'
      },
      formatter: (params: any[]) => {
        const item = params[0];
        if (!item) return '';
        const name = data[item.dataIndex]?.projectName || '';
        const rawVal = Number(item.value);
        return `
          <div style="font-family: inherit; font-size: 12px; padding: 4px;">
            <strong style="color: #94A3B8; display: block; margin-bottom: 4px;">${name}</strong>
            <span style="color: #E2E8F0">Value:</span> 
            <strong style="color: ${item.color}">${formatVal(rawVal)}</strong>
          </div>
        `;
      }
    },
    grid: {
      top: 30,
      right: 20,
      bottom: 40,
      left: 15,
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: data.map(d => truncateName(d.projectName)),
      axisLine: {
        lineStyle: {
          color: 'rgba(255, 255, 255, 0.1)'
        }
      },
      axisTick: { show: false },
      axisLabel: {
        color: '#94A3B8',
        fontSize: 10,
        fontFamily: 'Inter, sans-serif',
        interval: 0,
        rotate: data.length > 5 ? -15 : 0
      }
    },
    yAxis: {
      type: 'value',
      splitLine: {
        lineStyle: {
          type: 'dashed',
          color: 'rgba(255, 255, 255, 0.05)'
        }
      },
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: {
        color: '#94A3B8',
        fontSize: 10,
        fontFamily: 'Inter, sans-serif'
      }
    },
    series: [
      {
        type: 'bar',
        barWidth: '40%',
        data: data.map((d, index) => {
          let color = '#6366f1'; // Default Indigo
          if (top3OriginalIdxs.has(index)) {
            color = '#10b981'; // Green for top 3
          } else if (bottom3OriginalIdxs.has(index)) {
            color = '#ef4444'; // Red for bottom 3
          }

          return {
            value: d.value,
            itemStyle: {
              color: color,
              borderRadius: [4, 4, 0, 0]
            }
          };
        }),
        // Add Reference Line for average
        markLine: averageValue !== null ? {
          silent: true,
          symbol: 'none',
          lineStyle: {
            type: 'dashed',
            color: '#f59e0b', // Amber reference line
            width: 1.5
          },
          label: {
            show: true,
            position: 'end',
            formatter: `Avg: ${formatVal(averageValue)}`,
            color: '#f59e0b',
            fontSize: 9,
            fontFamily: 'Inter, sans-serif'
          },
          data: [
            { yAxis: averageValue }
          ]
        } : undefined
      }
    ]
  };

  if (data.length === 0) {
    return (
      <div 
        style={{ height }} 
        className="flex flex-col items-center justify-center border border-slate-200 dark:border-white/10 rounded-2xl bg-white dark:bg-[#121014]/40 text-center"
      >
        <p className="text-sm text-slate-400 dark:text-slate-500 font-medium">No Data Available</p>
      </div>
    );
  }

  return (
    <div style={{ height }}>
      <ReactECharts 
        option={option} 
        style={{ height: '100%', width: '100%' }}
        opts={{ renderer: 'svg' }}
      />
    </div>
  );
}

'use client';

import React from 'react';
import ReactECharts from 'echarts-for-react';

interface TimeSeriesPoint {
  date: string;
  value: number;
}

interface TimeSeriesChartProps {
  data: TimeSeriesPoint[];
  title: string;
  color?: string; // Hex color code (default: #10b981)
  unit?: 'currency' | 'percent' | 'ratio' | 'days' | 'count' | string;
  height?: number | string;
}

export function TimeSeriesChart({
  data,
  title,
  color = '#10b981',
  unit = 'count',
  height = 280
}: TimeSeriesChartProps) {

  const formatValue = (v: number) => {
    switch (unit) {
      case 'currency':
        return v < 0
          ? `-$${Math.abs(v).toLocaleString('en-US', { maximumFractionDigits: 0 })}`
          : `$${v.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;
      case 'percent':
        return `${v.toFixed(1)}%`;
      case 'ratio':
        return `${v.toFixed(2)}`;
      case 'days':
        return `${Math.round(v)} days`;
      default:
        return `${v}`;
    }
  };

  const option = {
    title: {
      text: title,
      show: false, // Title will be rendered in the HTML card header instead
    },
    tooltip: {
      trigger: 'axis',
      backgroundColor: 'rgba(30, 27, 32, 0.95)',
      borderColor: 'rgba(255, 255, 255, 0.1)',
      textStyle: {
        color: '#E2E8F0',
        fontSize: 12,
        fontFamily: 'Inter, sans-serif'
      },
      formatter: (params: any[]) => {
        const item = params[0];
        if (!item) return '';
        const date = item.name;
        const val = Number(item.value);
        return `
          <div style="font-family: inherit; font-size: 12px; padding: 4px;">
            <strong style="color: #94A3B8; display: block; margin-bottom: 4px;">${date}</strong>
            <span style="color: #E2E8F0">${title}:</span> 
            <strong style="color: ${color}">${formatValue(val)}</strong>
          </div>
        `;
      }
    },
    grid: {
      top: 20,
      right: 15,
      bottom: 50,
      left: 15,
      containLabel: true
    },
    xAxis: {
      type: 'category',
      data: data.map(d => d.date),
      axisLine: {
        lineStyle: {
          color: 'rgba(255, 255, 255, 0.1)'
        }
      },
      axisTick: { show: false },
      axisLabel: {
        color: '#94A3B8',
        fontSize: 10,
        fontFamily: 'Inter, sans-serif',
        margin: 12
      }
    },
    yAxis: {
      type: 'value',
      scale: true, // auto-scale Y-axis
      splitLine: {
        lineStyle: {
          type: 'dashed',
          color: 'rgba(255, 255, 255, 0.05)'
        }
      },
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: {
        color: '#94A3B8',
        fontSize: 10,
        fontFamily: 'Inter, sans-serif',
        formatter: (v: number) => {
          if (unit === 'currency') {
            if (Math.abs(v) >= 1000) return `$${(v / 1000).toFixed(0)}k`;
            return `$${v}`;
          }
          if (unit === 'percent') {
            return `${v}%`;
          }
          return `${v}`;
        }
      }
    },
    dataZoom: [
      {
        type: 'slider',
        show: true,
        height: 14,
        bottom: 10,
        borderColor: 'rgba(255, 255, 255, 0.05)',
        backgroundColor: 'rgba(0, 0, 0, 0.05)',
        fillerColor: 'rgba(16, 185, 129, 0.1)',
        dataBackground: {
          lineStyle: { color: 'rgba(255, 255, 255, 0.1)' },
          areaStyle: { color: 'rgba(255, 255, 255, 0.02)' }
        },
        selectedDataBackground: {
          lineStyle: { color: color },
          areaStyle: { color: `${color}33` }
        },
        handleSize: '100%',
        handleStyle: {
          color: '#cbd5e1',
          borderColor: '#94a3b8'
        },
        textStyle: {
          color: '#94A3B8',
          fontSize: 8,
          fontFamily: 'Inter, sans-serif'
        }
      }
    ],
    series: [
      {
        name: title,
        type: 'line',
        data: data.map(d => d.value),
        smooth: true, // spline curve
        symbol: 'circle',
        symbolSize: 6,
        showSymbol: false,
        itemStyle: {
          color: color
        },
        lineStyle: {
          width: 2.5,
          color: color
        },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0,
            y: 0,
            x2: 0,
            y2: 1,
            colorStops: [
              { offset: 0, color: `${color}33` }, // color with 20% opacity
              { offset: 1, color: `${color}00` }  // fully transparent
            ]
          }
        }
      }
    ]
  };

  if (data.length === 0) {
    return (
      <div 
        style={{ height }} 
        className="flex flex-col items-center justify-center border border-slate-200 dark:border-white/10 rounded-2xl bg-white dark:bg-[#121014]/40 text-center"
      >
        <p className="text-sm text-slate-400 dark:text-slate-500 font-medium">No Data Available</p>
      </div>
    );
  }

  return (
    <div style={{ height }}>
      <ReactECharts 
        option={option} 
        style={{ height: '100%', width: '100%' }}
        opts={{ renderer: 'svg' }}
      />
    </div>
  );
}

