      field: 'subStrategy',
      type: 'select',
      options: [
        { label: 'Triple Net (NNN)', value: 'NNN' },
        { label: 'Ground Lease', value: 'GROUND' },
        { label: 'Lease Option', value: 'LEASE_OPTION' },
      ],
