    // Rehab Completion Date (Phase 3+)
    {
      id: 'rehabDoneDate',
      question: "When was the rehab completed?",
      description: "The date all renovation work was finished. Leave blank if still in progress.",
      field: 'financials.rehabDoneDate',
      type: 'date',
