        <StepRail
          currentStep={currentStep}
          completion={completion}
          onStepClick={(s) => { goToStep(s); setRailOpen(false); }}
          savedAt={savedAt}
          isSaving={isSaving}
          projectId={projectId}
          projectName={projectName || undefined}
        />
