"use client";

import { useState, useEffect, useCallback } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useAuth } from "@/context/AuthContext";
import { useAcquisitionWizard } from "@/store/acquisitionWizardStore";
import toast from "react-hot-toast";

// ─── Types ────────────────────────────────────────────────────────────────────

interface Collaborator {
  userId: string;
  role:   string;
  user:   { id: string; email: string; name: string | null };
}

interface Assignment {
  id:        string;
  fieldKey:  string;
  status:    "OPEN" | "FILLED";
  assignedTo:{ id: string; email: string; name: string | null };
}

// ─── API ──────────────────────────────────────────────────────────────────────

async function fetchProjectCollaborators(projectId: string, token: string): Promise<Collaborator[]> {
  const res = await fetch(`/api/reil/projects/${projectId}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) return [];
  const data = await res.json();
  return data.collaborators ?? [];
}

async function createAssignment(
  projectId: string,
  fieldKey:  string,
  assignedToId: string,
  token: string,
): Promise<Assignment> {
  const res = await fetch(`/api/reil/projects/${projectId}/assignments`, {
    method:  "POST",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body:    JSON.stringify({ fieldKey, assignedToId }),
  });
  if (!res.ok) throw new Error("Failed to create assignment.");
  return res.json();
}

async function resolveAssignment(
  projectId:    string,
  assignmentId: string,
  token: string,
) {
  const res = await fetch(`/api/reil/projects/${projectId}/assignments/${assignmentId}`, {
    method:  "PATCH",
    headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}` },
    body:    JSON.stringify({ status: "FILLED" }),
  });
  if (!res.ok) throw new Error("Failed to resolve assignment.");
  return res.json();
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function displayName(u: { email: string; name: string | null }): string {
  return u.name ?? u.email.split("@")[0];
}

// ─── Component ────────────────────────────────────────────────────────────────

interface AssignableFieldProps {
  /** Dot-separated field key, e.g. "terms.offerMadeCents" */
  fieldKey:    string;
  label:       string;
  /** Whether the field currently has a value (truthy = filled) */
  hasValue:    boolean;
  children:    React.ReactNode;
}

export function AssignableField({ fieldKey, label, hasValue, children }: AssignableFieldProps) {
  const { projectId } = useAcquisitionWizard();
  const { user } = useAuth();
  const qc = useQueryClient();

  const [showPicker, setShowPicker] = useState(false);

  // Current assignment for this field
  const { data: assignments = [] } = useQuery({
    queryKey: ["assignments", projectId],
    queryFn:  async () => {
      const token = await user?.getIdToken();
      if (!token || !projectId) return [];
      const res = await fetch(`/api/reil/projects/${projectId}/assignments`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) return [];
      return res.json() as Promise<Assignment[]>;
    },
    enabled:   !!projectId && !!user,
    staleTime: 15_000,
  });

  const openAssignment = assignments.find(
    a => a.fieldKey === fieldKey && a.status === "OPEN",
  ) ?? null;

  // Fetch collaborators for the assignee picker
  const { data: collaborators = [] } = useQuery({
    queryKey: ["collaborators", projectId],
    queryFn:  async () => {
      const token = await user?.getIdToken();
      if (!token || !projectId) return [];
      return fetchProjectCollaborators(projectId, token);
    },
    enabled:   !!projectId && !!user && showPicker,
    staleTime: 30_000,
  });

  // Auto-resolve when the field gets a value
  useEffect(() => {
    if (!hasValue || !openAssignment || !projectId || !user) return;
    let cancelled = false;
    user.getIdToken().then((token: string) => {
      if (cancelled) return;
      resolveAssignment(projectId, openAssignment.id, token)
        .then(() => qc.invalidateQueries({ queryKey: ["assignments", projectId] }))
        .catch(() => {}); // silent — best effort
    });
    return () => { cancelled = true; };
  }, [hasValue, openAssignment, projectId, user, qc]);

  // Assign mutation
  const assignMutation = useMutation({
    mutationFn: async (assignedToId: string) => {
      const token = await user?.getIdToken();
      if (!token || !projectId) throw new Error("Not ready.");
      return createAssignment(projectId, fieldKey, assignedToId, token);
    },
    onSuccess: (_, assignedToId) => {
      const c = collaborators.find(c => c.userId === assignedToId);
      const name = c ? displayName(c.user) : "teammate";
      toast.success(`"${label}" assigned to ${name}`);
      qc.invalidateQueries({ queryKey: ["assignments", projectId] });
      setShowPicker(false);
    },
    onError: () => toast.error("Failed to assign field."),
  });

  const isAssigned = !!openAssignment;
  const assigneeName = openAssignment ? displayName(openAssignment.assignedTo) : null;
  const canAssign = !!projectId;

  return (
    <div className="relative group">
      {/* ── Waiting state overlay ── */}
      {isAssigned && !hasValue && (
        <div
          className="absolute inset-0 z-10 flex flex-col items-center justify-center rounded-xl"
          style={{
            background: "rgba(14,22,28,0.85)",
            border:     "1px solid rgba(255,209,170,0.2)",
            backdropFilter: "blur(4px)",
          }}
        >
          <span className="material-symbols-outlined text-[22px] mb-1" style={{ color: "#ffd1aa" }}>
            pending
          </span>
          <p className="text-[12px] font-semibold" style={{ color: "rgba(253,255,252,0.7)" }}>
            Waiting on {assigneeName}
          </p>
          <p className="text-[10px]" style={{ color: "rgba(253,255,252,0.3)" }}>
            {label}
          </p>
        </div>
      )}

      {/* The actual field */}
      <div className={isAssigned && !hasValue ? "pointer-events-none opacity-30" : ""}>
        {children}
      </div>

      {/* ── Assign affordance ── */}
      {!isAssigned && canAssign && (
        <div className="absolute -top-1 -right-1 z-20">
          <button
            onClick={() => setShowPicker(v => !v)}
            className="w-5 h-5 rounded-full flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-150"
            style={{
              background: "rgba(69,73,85,0.12)",
              border:     "1px solid rgba(69,73,85,0.25)",
            }}
            title={`Ask a teammate to fill in "${label}"`}
          >
            <span className="material-symbols-outlined text-[11px]" style={{ color: "#454955" }}>
              person_add
            </span>
          </button>
        </div>
      )}

      {/* ── Assignee picker dropdown ── */}
      {showPicker && (
        <div
          className="absolute right-0 top-full mt-1 z-30 min-w-[200px] rounded-xl overflow-hidden"
          style={{
            background:    "rgba(18,27,34,0.98)",
            border:        "1px solid rgba(255,255,255,0.1)",
            backdropFilter: "blur(24px)",
            boxShadow:     "0 16px 40px rgba(0,0,0,0.5)",
          }}
        >
          <div className="px-3 py-2" style={{ borderBottom: "1px solid rgba(255,255,255,0.06)" }}>
            <p className="text-[10px] font-bold uppercase tracking-widest" style={{ color: "rgba(253,255,252,0.3)" }}>
              Assign "{label}"
            </p>
          </div>

          {collaborators.length === 0 ? (
            <div className="px-3 py-3 text-center">
              <p className="text-[11px]" style={{ color: "rgba(253,255,252,0.3)" }}>
                No teammates yet. Invite from the Team panel.
              </p>
            </div>
          ) : (
            collaborators.map(c => (
              <button
                key={c.userId}
                onClick={() => assignMutation.mutate(c.userId)}
                disabled={assignMutation.isPending}
                className="w-full flex items-center gap-3 px-3 py-2.5 text-left transition-colors"
                onMouseEnter={e => (e.currentTarget.style.background = "rgba(69,73,85,0.06)")}
                onMouseLeave={e => (e.currentTarget.style.background = "transparent")}
              >
                <div
                  className="w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 text-[9px] font-bold"
                  style={{ background: "rgba(69,73,85,0.12)", color: "#454955" }}
                >
                  {displayName(c.user).slice(0, 2).toUpperCase()}
                </div>
                <div className="min-w-0">
                  <p className="text-[12px] font-medium truncate" style={{ color: "rgba(253,255,252,0.85)" }}>
                    {displayName(c.user)}
                  </p>
                  <p className="text-[10px] truncate" style={{ color: "rgba(253,255,252,0.3)" }}>
                    {c.role.charAt(0) + c.role.slice(1).toLowerCase()}
                  </p>
                </div>
              </button>
            ))
          )}

          <button
            onClick={() => setShowPicker(false)}
            className="w-full py-2 text-[11px]"
            style={{ borderTop: "1px solid rgba(255,255,255,0.05)", color: "rgba(253,255,252,0.25)" }}
          >
            Cancel
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { DollarSign, Activity, Percent, ArrowUpRight, CheckCircle2 } from 'lucide-react';
import toast from 'react-hot-toast';

interface DealAnalysisStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

// Local helper to calculate the exact hash to pass the phase gate
function getScorecardInputsHash(project: any): string {
  if (!project) return '';
  const f = (project.financials || {}) as any;
  const values = [
    f.purchasePrice ?? 0,
    f.listedPrice ?? 0,
    f.projectedRehabCost ?? 0,
    f.estimatedARV ?? 0,
    f.arv ?? 0,
    f.targetCapRate ?? 0,
    f.targetCoc ?? f.targetCoCReturn ?? 0,
    f.minDscr ?? f.targetMinDSCR ?? 0,
    f.maxPurchasePrice ?? f.targetMaxPurchasePrice ?? 0,
    f.gross_rent_per_unit ?? f.monthlyGrossRent ?? f.grossRent ?? 0,
    f.vacancy_pct ?? f.vacancyRatePercent ?? f.vacancyRate ?? 0,
    f.other_income ?? f.otherIncome ?? 0,
    f.tax ?? f.taxes ?? 0,
    f.insurance ?? 0,
    f.utilities ?? 0,
    f.management ?? 0,
    f.management_pct ?? 0,
    f.maintenance ?? 0,
    f.maintenance_pct ?? f.monthlyMaintenanceReserve ?? 0,
    f.otherExpenses ?? 0,
    f.downPaymentPercent ?? 0,
    f.loanInterestRate ?? f.interestRate ?? 0,
    f.loanTermYears ?? 0,
    project.dispositionType || '',
    project.subStrategy || '',
  ];
  return values.join('|');
}

export default function DealAnalysisStep({
  initialData,
  onSave,
}: DealAnalysisStepProps) {
  const f = initialData?.financials || {};
  const m = f.marketStatsSnapshot || {};

  // Input States
  const [purchasePrice, setPurchasePrice] = useState<number>(f.purchasePrice ? f.purchasePrice / 100 : 250000);
  const [rehabBudget, setRehabBudget] = useState<number>(f.projectedRehabCost ? f.projectedRehabCost / 100 : 25000);
  const [arv, setArv] = useState<number>(f.estimatedARV ? f.estimatedARV / 100 : 310000);
  const [monthlyRent, setMonthlyRent] = useState<number>(f.grossRent || 1800);

  // Operating Expenses (Monthly)
  const [propertyTax, setPropertyTax] = useState<number>(f.tax !== undefined ? f.tax : 150);
  const [insurance, setInsurance] = useState<number>(f.insurance !== undefined ? f.insurance : 80);
  const [hoa, setHoa] = useState<number>(f.hoa !== undefined ? f.hoa : 0);
  const [maintenance, setMaintenance] = useState<number>(f.maintenance !== undefined ? f.maintenance : 100);
  const [management, setManagement] = useState<number>(f.management !== undefined ? f.management : 140);
  const [utilities, setUtilities] = useState<number>(f.utilities !== undefined ? f.utilities : 0);

  // Live KPI Calculations
  const calculatedMetrics = useMemo(() => {
    // 1. NOI = (Monthly Gross Rent - Monthly Expenses) * 12
    const monthlyExpenses = propertyTax + insurance + hoa + maintenance + management + utilities;
    const monthlyNoi = monthlyRent - monthlyExpenses;
    const annualNoi = monthlyNoi * 12;

    // 2. Cap Rate = NOI / Purchase Price
    const capRate = purchasePrice > 0 ? (annualNoi / purchasePrice) * 100 : 0;

    // 3. Debt Service (Assuming 75% LTV, 30-year amortization, interest rate of 6.5%)
    const loanAmount = purchasePrice * 0.75;
    const interestRate = 0.065;
    const monthlyRate = interestRate / 12;
    const nPayments = 360;
    const monthlyDebtService = loanAmount > 0
      ? (loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, nPayments))) / (Math.pow(1 + monthlyRate, nPayments) - 1)
      : 0;
    const annualDebtService = monthlyDebtService * 12;

    // 4. Cash Flow = NOI - Debt Service
    const annualCashFlow = annualNoi - annualDebtService;
    const monthlyCashFlow = annualCashFlow / 12;

    // 5. Cash on Cash = Annual Cash Flow / Total Cash Invested
    // Total cash invested = Down Payment (25%) + Rehab + Closing Costs (Estimated 3% of purchase price)
    const closingCosts = purchasePrice * 0.03;
    const totalCashInvested = (purchasePrice * 0.25) + rehabBudget + closingCosts;
    const coc = totalCashInvested > 0 ? (annualCashFlow / totalCashInvested) * 100 : 0;

    // 6. GRM = Purchase Price / Gross Annual Rent
    const annualGrossRent = monthlyRent * 12;
    const grm = annualGrossRent > 0 ? purchasePrice / annualGrossRent : 0;

    // 7. DSCR = NOI / Debt Service
    const dscr = annualDebtService > 0 ? annualNoi / annualDebtService : 0;

    return {
      monthlyExpenses,
      annualNoi,
      capRate,
      annualDebtService,
      annualCashFlow,
      monthlyCashFlow,
      totalCashInvested,
      coc,
      grm,
      dscr,
    };
  }, [purchasePrice, rehabBudget, monthlyRent, propertyTax, insurance, hoa, maintenance, management, utilities]);

  // Color coding thresholds
  const getColorClass = (val: number, type: 'cap' | 'dscr' | 'coc') => {
    if (type === 'cap') {
      if (val > 6) return 'text-emerald-400 border-emerald-500/20 bg-emerald-500/5';
      if (val >= 4) return 'text-amber-400 border-amber-500/20 bg-amber-500/5';
      return 'text-rose-400 border-rose-500/20 bg-rose-500/5';
    }
    if (type === 'dscr') {
      if (val > 1.25) return 'text-emerald-400 border-emerald-500/20 bg-emerald-500/5';
      if (val >= 1.0) return 'text-amber-400 border-amber-500/20 bg-amber-500/5';
      return 'text-rose-400 border-rose-500/20 bg-rose-500/5';
    }
    // coc
    if (val > 10) return 'text-emerald-400 border-emerald-500/20 bg-emerald-500/5';
    if (val >= 5) return 'text-amber-400 border-amber-500/20 bg-amber-500/5';
    return 'text-rose-400 border-rose-500/20 bg-rose-500/5';
  };

  const handleContinue = async () => {
    // 1. First build the intermediate financials object
    const newFinancials = {
      ...f,
      purchasePrice: purchasePrice * 100,
      projectedRehabCost: rehabBudget * 100,
      rehabBudget: rehabBudget * 100,
      estimatedARV: arv * 100,
      arv: arv * 100,
      grossRent: monthlyRent,
      monthlyGrossRent: monthlyRent,
      // Expenses
      tax: propertyTax,
      insurance,
      hoa,
      maintenance,
      management,
      utilities,
      // Loan pre-fill
      loanAmount: purchasePrice * 0.75 * 100,
      loanInterestRate: 6.5,
      loanTermYears: 30,
      downPaymentPercent: 25,
      // Evaluation
      scorecardAcknowledged: true,
      decision: f.decision || 'proceed',
    };

    // 2. Derive the inputs hash matching the scorecard validation rule
    const projectDummy = {
      ...initialData,
      dispositionType: initialData.dispositionType || 'RENT',
      subStrategy: initialData.subStrategy || 'LONG_TERM',
      financials: newFinancials,
    };

    const hash = getScorecardInputsHash(projectDummy);
    newFinancials.acknowledgedInputsHash = hash;

    const payload = {
      financials: newFinancials,
    };

    await onSave(payload);
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 4: Underwriting & Deal Analysis</h3>
        <p className="text-xs text-slate-400">Model your deal financials, cash flow, and operating metrics side-by-side with market stats.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
        {/* Left Side: Inputs */}
        <div className="md:col-span-2 space-y-4">
