        </div>
      </div>

      {/* Rental Comps */}
      <div>
        <h3 className="text-[11px] font-bold uppercase tracking-widest mb-4 mt-2" style={{ color: "rgba(253,255,252,0.4)", letterSpacing: "0.08em" }}>
