"use client";

import { useQuery } from "@tanstack/react-query";
import { useAuth } from "@/context/AuthContext";
import { useAcquisitionWizard, type WizardStepKey } from "@/store/acquisitionWizardStore";
import {
  ACQUISITION_STATUS_LABELS,
