'use client';

import React, { useEffect, useState, useCallback } from 'react';
import {
  X,
  User,
  Shield,
  CreditCard,
  Building,
  Activity,
  Key,
  Mail,
  Lock,
  Eye,
  EyeOff,
  AlertTriangle,
  CheckCircle,
  Clock,
  Landmark,
} from 'lucide-react';
import StatusBadge from '@/components/admin/StatusBadge';
import {
  getUser360,
  requestSensitiveUserAction,
  confirmSensitiveUserAction,
  toggleUserAccountStatus,
} from '@/actions/adminUserManagement';
import type { User360Data } from '@/lib/admin/user360';
import type { SensitiveActionType } from '@/lib/admin/verificationGate';
import { maskEmail, maskPhone, maskAccount } from '@/lib/utils';

interface User360DrawerProps {
  targetUid: string | null;
  onClose: () => void;
  onRefreshParent?: () => void;
}

export default function User360Drawer({ targetUid, onClose, onRefreshParent }: User360DrawerProps) {
  const [data, setData] = useState<User360Data | null>(null);
  const [loading, setLoading] = useState(false);
  const [activeTab, setActiveTab] = useState<'identity' | 'billing' | 'plaid' | 'org' | 'activity'>('identity');
  const [isMasked, setIsMasked] = useState(true);

  // Verification Gate State
  const [verifyingAction, setVerifyingAction] = useState<SensitiveActionType | null>(null);
  const [verificationId, setVerificationId] = useState<string | null>(null);
  const [inputCode, setInputCode] = useState('');
  const [newEmailInput, setNewEmailInput] = useState('');
  const [verificationError, setVerificationError] = useState('');
  const [verificationSuccess, setVerificationSuccess] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const fetchUser = useCallback(async () => {
    if (!targetUid) return;
    setLoading(true);
    try {
      const u360 = await getUser360(targetUid);
      setData(u360);
    } catch (err) {
      console.error('[User360Drawer] Fetch failed:', err);
    } finally {
      setLoading(false);
    }
  }, [targetUid]);

  useEffect(() => {
    if (targetUid) {
      fetchUser();
      setVerifyingAction(null);
      setVerificationId(null);
      setInputCode('');
      setVerificationError('');
      setVerificationSuccess('');
    }
  }, [targetUid, fetchUser]);

  if (!targetUid) return null;

  const handleInitiateAction = async (actionType: SensitiveActionType) => {
    if (actionType === 'EMAIL_CHANGE' && !newEmailInput) {
      setVerificationError('Please enter the new email address.');
      return;
    }

    setSubmitting(true);
    setVerificationError('');
    setVerificationSuccess('');
    try {
      const res = await requestSensitiveUserAction({
        targetUid,
        actionType,
        newEmail: actionType === 'EMAIL_CHANGE' ? newEmailInput : undefined,
      });

      if (res.success && res.verificationId) {
        setVerifyingAction(actionType);
        setVerificationId(res.verificationId);
        setVerificationSuccess('Verification code sent to user email via Resend.');
      } else {
        setVerificationError(res.error || 'Failed to initiate verification.');
      }
    } catch (err: any) {
      setVerificationError(err?.message || 'Initiation error');
    } finally {
      setSubmitting(false);
    }
  };

  const handleConfirmAction = async () => {
    if (!verificationId || !inputCode) {
      setVerificationError('Please enter the 6-digit code.');
      return;
    }

    setSubmitting(true);
    setVerificationError('');
    try {
      const res = await confirmSensitiveUserAction({
        verificationId,
        code: inputCode,
      });

      if (res.success) {
        setVerificationSuccess(res.message || 'Action completed successfully.');
        setVerifyingAction(null);
        setVerificationId(null);
        setInputCode('');
        fetchUser();
        if (onRefreshParent) onRefreshParent();
      } else {
        setVerificationError(res.error || 'Invalid verification code.');
      }
    } catch (err: any) {
      setVerificationError(err?.message || 'Confirmation error');
    } finally {
      setSubmitting(false);
    }
  };

  const handleToggleAccount = async (disabled: boolean) => {
    if (!confirm(`Are you sure you want to ${disabled ? 'disable' : 'enable'} this account?`)) return;
    setSubmitting(true);
    try {
      const res = await toggleUserAccountStatus({ targetUid, disabled });
      if (res.success) {
        fetchUser();
        if (onRefreshParent) onRefreshParent();
      } else {
        alert(`Failed: ${res.error}`);
      }
    } finally {
      setSubmitting(false);
    }
  };

  const identity = data?.identity;
  const billing = data?.billing;

  return (
    <div className="fixed inset-0 z-50 overflow-hidden bg-black/50 backdrop-blur-xs flex justify-end">
      <div
        className="w-full max-w-2xl min-h-screen flex flex-col shadow-2xl transition-transform"
        style={{ background: 'var(--bg-canvas)', borderLeft: '1px solid var(--border-ui)' }}
      >
        {/* Drawer Header */}
        <div className="px-6 py-5 flex items-center justify-between border-b" style={{ borderColor: 'var(--border-ui)', background: 'var(--bg-surface)' }}>
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-full flex items-center justify-center font-bold text-sm bg-black text-white shrink-0">
              {identity?.displayName?.charAt(0) || 'U'}
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>
                  {identity?.displayName || 'User 360 Profile'}
                </h2>
                <span className="text-xs uppercase font-bold tracking-wider px-2 py-0.5 rounded bg-gray-100 dark:bg-gray-800" style={{ color: 'var(--text-secondary)' }}>
                  {identity?.role}
                </span>
              </div>
              <p className="text-xs font-mono" style={{ color: 'var(--text-secondary)' }}>
                UID: {identity?.uid}
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setIsMasked(!isMasked)}
              className="p-2 rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors text-xs flex items-center gap-1.5"
              title={isMasked ? 'Click to unmask PII data' : 'Click to mask PII data'}
              style={{ color: 'var(--text-secondary)' }}
            >
              {isMasked ? <Eye className="w-4 h-4" /> : <EyeOff className="w-4 h-4 text-amber-500" />}
              <span>{isMasked ? 'Unmask' : 'Masked'}</span>
            </button>
            <button
              onClick={onClose}
              className="p-2 rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
              style={{ color: 'var(--text-primary)' }}
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {/* Tab Navigation */}
        <div className="flex border-b px-6 text-xs font-semibold overflow-x-auto shrink-0" style={{ borderColor: 'var(--border-ui)', background: 'var(--bg-surface)' }}>
          {[
            { id: 'identity', label: 'Identity & Auth', icon: User },
            { id: 'billing', label: 'Billing & Stripe', icon: CreditCard },
            { id: 'plaid', label: 'Banks (Plaid)', icon: Landmark },
            { id: 'org', label: 'Organizations', icon: Building },
            { id: 'activity', label: 'Activity Log', icon: Activity },
          ].map((t) => {
            const Icon = t.icon;
            const active = activeTab === t.id;
            return (
              <button
                key={t.id}
                onClick={() => setActiveTab(t.id as any)}
                className={`flex items-center gap-2 px-4 py-3 border-b-2 transition-colors whitespace-nowrap ${
                  active ? 'border-black text-black dark:border-white dark:text-white font-bold' : 'border-transparent text-gray-500 hover:text-gray-900'
                }`}
              >
                <Icon className="w-4 h-4" />
                {t.label}
              </button>
            );
          })}
        </div>

        {/* Drawer Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {loading ? (
            <div className="space-y-4">
              {[...Array(4)].map((_, i) => (
                <div key={i} className="h-16 animate-shimmer rounded" style={{ border: '1px solid var(--border-ui)' }} />
              ))}
            </div>
          ) : !data ? (
            <p className="text-center py-12 text-sm text-gray-500">Failed to load User 360 data.</p>
          ) : (
            <>
              {/* TAB 1: Identity & Auth */}
              {activeTab === 'identity' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-2 gap-4 p-4 rounded-lg border" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Email Address</p>
                      <p className="text-sm font-semibold mt-1" style={{ color: 'var(--text-primary)' }}>
                        {isMasked ? maskEmail(identity?.email) : identity?.email}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Email Verification</p>
                      <div className="mt-1">
                        <StatusBadge
                          label={identity?.emailVerified ? 'VERIFIED' : 'UNVERIFIED'}
                          variant={identity?.emailVerified ? 'success' : 'warning'}
                        />
                      </div>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Account Type</p>
                      <p className="text-sm capitalize mt-1" style={{ color: 'var(--text-primary)' }}>
                        {identity?.accountType}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Account Status</p>
                      <div className="mt-1">
                        <StatusBadge
                          label={identity?.disabled ? 'DISABLED' : 'ACTIVE'}
                          variant={identity?.disabled ? 'danger' : 'success'}
                        />
                      </div>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Joined Date</p>
                      <p className="text-xs font-mono mt-1" style={{ color: 'var(--text-secondary)' }}>
                        {new Date(identity?.createdAt || '').toLocaleString()}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Last Sign-In</p>
                      <p className="text-xs font-mono mt-1" style={{ color: 'var(--text-secondary)' }}>
                        {new Date(identity?.lastLoginAt || '').toLocaleString()}
                      </p>
                    </div>
                  </div>

                  {/* Verification-Before-Change Actions Panel (Amendment E) */}
                  <div className="p-4 rounded-lg border bg-amber-500/5 border-amber-500/20 space-y-4">
                    <div className="flex items-center gap-2">
                      <Shield className="w-4 h-4 text-amber-600" />
                      <h3 className="text-sm font-semibold text-amber-900 dark:text-amber-300">
                        Verification-Gated Sensitive Actions
                      </h3>
                    </div>
                    <p className="text-xs text-gray-600 dark:text-gray-400">
                      Modifying sensitive credentials sends a 6-digit confirmation code via Resend to the user before executing the change.
                    </p>

                    {verificationError && (
                      <div className="p-3 text-xs bg-red-50 text-red-600 rounded border border-red-200">
                        {verificationError}
                      </div>
                    )}
                    {verificationSuccess && (
                      <div className="p-3 text-xs bg-emerald-50 text-emerald-700 rounded border border-emerald-200">
                        {verificationSuccess}
                      </div>
                    )}

                    {verifyingAction ? (
                      <div className="space-y-3 p-3 bg-white dark:bg-gray-900 rounded border">
                        <p className="text-xs font-bold uppercase text-gray-700 dark:text-gray-300">
                          Confirming {verifyingAction}
                        </p>
                        <input
                          type="text"
                          maxLength={6}
                          placeholder="Enter 6-digit code"
                          value={inputCode}
                          onChange={(e) => setInputCode(e.target.value)}
                          className="w-full text-center tracking-widest font-mono text-lg py-2 border rounded"
                        />
                        <div className="flex gap-2">
                          <button
                            onClick={handleConfirmAction}
                            disabled={submitting || inputCode.length !== 6}
                            className="ag-button flex-1 text-xs"
                          >
                            {submitting ? 'Verifying...' : 'Confirm & Execute'}
                          </button>
                          <button
                            onClick={() => { setVerifyingAction(null); setVerificationId(null); }}
                            className="px-3 py-1.5 text-xs border rounded hover:bg-gray-100"
                          >
                            Cancel
                          </button>
                        </div>
                      </div>
                    ) : (
                      <div className="grid grid-cols-2 gap-2">
                        <button
                          onClick={() => {
                            const email = prompt('Enter new email address:');
                            if (email) {
                              setNewEmailInput(email);
                              handleInitiateAction('EMAIL_CHANGE');
                            }
                          }}
                          disabled={submitting}
                          className="flex items-center justify-center gap-2 p-2.5 text-xs border rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors font-semibold"
                        >
                          <Mail className="w-3.5 h-3.5" />
                          Change Email
                        </button>

                        <button
                          onClick={() => handleInitiateAction('PASSWORD_RESET')}
                          disabled={submitting}
                          className="flex items-center justify-center gap-2 p-2.5 text-xs border rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors font-semibold"
                        >
                          <Key className="w-3.5 h-3.5" />
                          Send Password Reset
                        </button>

                        <button
                          onClick={() => handleInitiateAction('MFA_RESET')}
                          disabled={submitting}
                          className="flex items-center justify-center gap-2 p-2.5 text-xs border rounded hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors font-semibold"
                        >
                          <Lock className="w-3.5 h-3.5" />
                          Reset MFA Factors
                        </button>

                        <button
                          onClick={() => handleToggleAccount(!identity?.disabled)}
                          disabled={submitting}
                          className={`flex items-center justify-center gap-2 p-2.5 text-xs border rounded font-semibold ${
                            identity?.disabled ? 'bg-emerald-50 text-emerald-700 border-emerald-200' : 'bg-red-50 text-red-700 border-red-200'
                          }`}
                        >
                          <AlertTriangle className="w-3.5 h-3.5" />
                          {identity?.disabled ? 'Enable Account' : 'Disable Account'}
                        </button>
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* TAB 2: Billing & Stripe */}
              {activeTab === 'billing' && (
                <div className="space-y-4">
                  <div className="grid grid-cols-2 gap-4 p-4 rounded-lg border" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Subscription Plan</p>
                      <p className="text-base font-semibold mt-1" style={{ color: 'var(--text-primary)' }}>
                        {billing?.subscriptionPlan}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Subscription Status</p>
                      <div className="mt-1">
                        <StatusBadge
                          label={(billing?.subscriptionStatus || 'inactive').replace('_', ' ')}
                          variant={billing?.subscriptionStatus === 'active' ? 'success' : 'warning'}
                        />
                      </div>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Stripe Customer ID</p>
                      <p className="text-xs font-mono mt-1" style={{ color: 'var(--text-secondary)' }}>
                        {billing?.stripeCustomerId || 'No Stripe Customer'}
                      </p>
                    </div>
                    <div>
                      <p className="text-xs uppercase font-bold text-gray-500">Estimated MRR</p>
                      <p className="text-base font-bold mt-1 text-emerald-600">
                        ${billing?.mrr}/mo
                      </p>
                    </div>
                  </div>
                </div>
              )}

              {/* TAB 3: Banks (Plaid) */}
              {activeTab === 'plaid' && (
                <div className="space-y-4">
                  {data.plaidConnections.length === 0 ? (
                    <div className="p-8 text-center border rounded-lg" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                      <Landmark className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                      <p className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>No Plaid Bank Connections</p>
                      <p className="text-xs text-gray-500 mt-1">This user has not connected any external bank accounts.</p>
                    </div>
                  ) : (
                    data.plaidConnections.map((c) => (
                      <div key={c.id} className="p-4 rounded-lg border space-y-2" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                        <div className="flex items-center justify-between">
                          <h4 className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
                            {c.institutionName}
                          </h4>
                          <StatusBadge label={c.status} variant={c.status === 'OK' ? 'success' : 'warning'} />
                        </div>
                        <div className="flex justify-between text-xs text-gray-500">
                          <span>Account: {maskAccount(c.accountMask)}</span>
                          <span>Sync Errors: {c.syncErrorCount}</span>
                        </div>
                        {c.lastSyncErrorMessage && (
                          <p className="text-xs text-red-500 bg-red-50 p-2 rounded border border-red-100">
                            Error: {c.lastSyncErrorMessage}
                          </p>
                        )}
                      </div>
                    ))
                  )}
                </div>
              )}

              {/* TAB 4: Organizations */}
              {activeTab === 'org' && (
                <div className="space-y-4">
                  {data.organizations.length === 0 ? (
                    <div className="p-8 text-center border rounded-lg" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                      <Building className="w-8 h-8 mx-auto text-gray-400 mb-2" />
                      <p className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>Single-Tenant Account</p>
                      <p className="text-xs text-gray-500 mt-1">User has no active organization collaborations.</p>
                    </div>
                  ) : (
                    data.organizations.map((org, i) => (
                      <div key={i} className="p-4 rounded-lg border space-y-2" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                        <div className="flex items-center justify-between">
                          <h4 className="text-sm font-semibold" style={{ color: 'var(--text-primary)' }}>
                            {org.projectDisplayName}
                          </h4>
                          <span className="text-xs uppercase font-bold px-2 py-0.5 rounded bg-blue-50 text-blue-700">
                            {org.role}
                          </span>
                        </div>
                        <p className="text-xs font-mono text-gray-500">
                          Org ID: {org.organizationId}
                        </p>
                      </div>
                    ))
                  )}
                </div>
              )}

              {/* TAB 5: Activity Log */}
              {activeTab === 'activity' && (
                <div className="space-y-3">
                  {data.activityTimeline.length === 0 ? (
                    <p className="text-center py-8 text-xs text-gray-500">No activity events recorded.</p>
                  ) : (
                    data.activityTimeline.map((item) => (
                      <div key={item.id} className="p-3 rounded border text-xs space-y-1" style={{ background: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
                        <div className="flex items-center justify-between">
                          <span className="font-semibold" style={{ color: 'var(--text-primary)' }}>
                            {item.action}
                          </span>
                          <span className="text-[10px] text-gray-400 font-mono">
                            {new Date(item.timestamp).toLocaleString()}
                          </span>
                        </div>
                        <p className="text-gray-500">{item.details}</p>
                      </div>
                    ))
                  )}
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';
import React, { useState, useCallback } from 'react';
import { MultiFactorResolver, TotpMultiFactorGenerator } from 'firebase/auth';
import posthog from 'posthog-js';

interface Props {
  resolver: MultiFactorResolver;
  onResolved: () => void;
  onCancel: () => void;
}

export default function MFAChallengeModal({ resolver, onResolved, onCancel }: Props) {
  const [code, setCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [attempts, setAttempts] = useState(0);

  // Find the TOTP hint from the resolver
  const totpHint = resolver.hints.find((h) => h.factorId === 'totp');

  const handleSubmit = useCallback(async () => {
    if (!totpHint || code.length !== 6) return;
    setError(null);
    setLoading(true);
    try {
      const assertion = TotpMultiFactorGenerator.assertionForSignIn(totpHint.uid, code);
      await resolver.resolveSignIn(assertion);
      try { posthog.capture('mfa_challenge_success', { factorId: 'totp' }); } catch { /* non-fatal */ }
      onResolved();
    } catch (err: any) {
      const next = attempts + 1;
      setAttempts(next);
      setCode('');

      if (err.code === 'auth/invalid-verification-code') {
        setError('Incorrect code. Check your authenticator app and try again.');
      } else if (err.code === 'auth/code-expired') {
        setError('Code expired — wait for the next rotation.');
      } else if (err.code === 'auth/too-many-requests') {
        setError('Too many failed attempts. Please wait before trying again.');
        try { posthog.capture('mfa_challenge_failed', { reason: 'too_many_requests', attempts: next }); } catch { /* non-fatal */ }
      } else {
        setError(err.message || 'Verification failed.');
      }
      try { posthog.capture('mfa_challenge_failed', { reason: err.code, attempts: next }); } catch { /* non-fatal */ }
    } finally {
      setLoading(false);
    }
  }, [totpHint, code, resolver, attempts, onResolved]);

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/70 backdrop-blur-sm">
      <div className="w-full max-w-sm glass-card rounded-2xl p-8 shadow-2xl">
        {/* Header */}
        <div className="flex items-center gap-3 mb-6">
          <span className="material-symbols-outlined text-pw-primary text-2xl select-none">shield_lock</span>
          <h2 className="text-xl font-bold text-pw-black">Two-Factor Authentication</h2>
        </div>

        <p className="text-sm text-pw-muted mb-6 leading-relaxed">
          Enter the 6-digit code from your authenticator app to sign in.
        </p>

        <input
          type="text"
          inputMode="numeric"
          pattern="[0-9]*"
          maxLength={6}
          value={code}
          onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
          onKeyDown={(e) => e.key === 'Enter' && handleSubmit()}
          placeholder="000000"
          autoFocus
          className="glass-input w-full text-center font-mono text-2xl tracking-[0.4em] py-4 mb-4 text-pw-black"
        />

        {error && (
          <p className="text-xs text-red-400 mb-4 text-center leading-relaxed">{error}</p>
        )}

        <button
          onClick={handleSubmit}
          disabled={loading || code.length !== 6}
          className="w-full py-3 rounded-xl bg-pw-primary text-white font-semibold text-sm hover:bg-pw-primary/90 transition-colors disabled:opacity-50 mb-3"
        >
          {loading ? 'Verifying…' : 'Verify'}
        </button>

        <button
          onClick={onCancel}
          className="w-full py-2 text-xs text-pw-muted hover:text-pw-black transition-colors"
        >
          Cancel sign-in
        </button>

        {attempts >= 3 && (
          <p className="text-[11px] text-pw-muted text-center mt-4 leading-relaxed">
            Lost access to your authenticator? Contact{' '}
            <a href="mailto:hi@paperworking.co" className="text-pw-primary underline">
              hi@paperworking.co
            </a>{' '}
            with proof of identity.
          </p>
        )}
      </div>
    </div>
  );
}

'use client';
import React, { useState, useCallback } from 'react';
import QRCode from 'react-qr-code';
import {
  multiFactor,
  TotpMultiFactorGenerator,
  TotpSecret,
  reauthenticateWithCredential,
  EmailAuthProvider,
} from 'firebase/auth';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';
import posthog from 'posthog-js';

type Step = 'reauth' | 'qr' | 'verify' | 'success';

interface Props {
  onClose: () => void;
  onEnrolled: () => void;
}

export default function MFAEnrollmentModal({ onClose, onEnrolled }: Props) {
  const { user } = useAuth();
  const [step, setStep] = useState<Step>('reauth');
  const [password, setPassword] = useState('');
  const [totpSecret, setTotpSecret] = useState<TotpSecret | null>(null);
  const [qrUrl, setQrUrl] = useState('');
  const [secretKey, setSecretKey] = useState('');
  const [code, setCode] = useState('');
  const [recoveryAcked, setRecoveryAcked] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const stepIndex = (['reauth', 'qr', 'verify', 'success'] as Step[]).indexOf(step);

  const handleReauth = useCallback(async () => {
    if (!user?.email) return;
    setError(null);
    setLoading(true);
    try {
      const credential = EmailAuthProvider.credential(user.email, password);
      await reauthenticateWithCredential(user, credential);

      const session = await multiFactor(user).getSession();
      const secret = await TotpMultiFactorGenerator.generateSecret(session);
      setTotpSecret(secret);
      setQrUrl(secret.generateQrCodeUrl(user.email, 'PaperWorking'));
      setSecretKey(secret.secretKey);
      setStep('qr');
    } catch (err: any) {
      if (err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
        setError('Incorrect password.');
      } else {
        setError(err.message || 'Re-authentication failed.');
      }
    } finally {
      setLoading(false);
    }
  }, [user, password]);

  const handleVerify = useCallback(async () => {
    if (!user || !totpSecret) return;
    if (!recoveryAcked) {
      setError('Please acknowledge the recovery notice before continuing.');
      return;
    }
    setError(null);
    setLoading(true);
    try {
      const assertion = TotpMultiFactorGenerator.assertionForEnrollment(totpSecret, code);
      await multiFactor(user).enroll(assertion, 'TOTP Authenticator');
      try { posthog.capture('mfa_enrolled', { factorId: 'totp' }); } catch { /* non-fatal */ }
      setStep('success');
    } catch (err: any) {
      if (err.code === 'auth/invalid-verification-code') {
        setError('Incorrect code. Check your authenticator app and try again.');
      } else if (err.code === 'auth/code-expired') {
        setError('Code expired. Wait for the next rotation in your authenticator app.');
      } else {
        setError(err.message || 'Enrollment failed.');
      }
      try { posthog.capture('mfa_enrollment_failed', { error: err.code }); } catch { /* non-fatal */ }
    } finally {
      setLoading(false);
    }
  }, [user, totpSecret, code, recoveryAcked]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm"
      onClick={step === 'success' ? undefined : onClose}
    >
      <div
        className="w-full max-w-md glass-card rounded-2xl p-8 shadow-2xl relative overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <span className="material-symbols-outlined text-pw-primary text-2xl select-none">security</span>
            <h2 className="text-xl font-bold text-pw-black">Enable Two-Factor Auth</h2>
          </div>
          {step !== 'success' && (
            <button
              onClick={onClose}
              className="p-1 rounded-lg hover:bg-pw-glass-bg text-pw-muted hover:text-pw-black transition-colors"
            >
              <span className="material-symbols-outlined text-xl select-none">close</span>
            </button>
          )}
        </div>

        {/* Progress bar */}
        <div className="flex items-center gap-1 mb-8">
          {(['reauth', 'qr', 'verify', 'success'] as Step[]).map((s, i) => (
            <div
              key={s}
              className={`h-1 flex-1 rounded-full transition-colors duration-300 ${
                stepIndex >= i ? 'bg-pw-primary' : 'bg-pw-border'
              }`}
            />
          ))}
        </div>

        {/* ── Step 1: Re-authenticate ── */}
        {step === 'reauth' && (
          <div className="space-y-5">
            <div>
              <p className="text-sm font-semibold text-pw-black mb-1">Confirm your password</p>
              <p className="text-xs text-pw-muted mb-4">
                Security requires re-verification before enrolling a second factor.
              </p>
              <input
                type="password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleReauth()}
                placeholder="Current password"
                autoFocus
                className="glass-input w-full text-sm px-4 py-3 text-pw-black"
              />
            </div>
            {error && <p className="text-xs text-red-400">{error}</p>}
            <button
              onClick={handleReauth}
              disabled={loading || !password}
              className="w-full py-3 rounded-xl bg-pw-primary text-white font-semibold text-sm hover:bg-pw-primary/90 transition-colors disabled:opacity-50"
            >
              {loading ? 'Verifying…' : 'Continue'}
            </button>
          </div>
        )}

        {/* ── Step 2: QR Code + manual key ── */}
        {step === 'qr' && (
          <div className="space-y-5">
            <div>
              <p className="text-sm font-semibold text-pw-black mb-1">Scan with your authenticator app</p>
              <p className="text-xs text-pw-muted">
                Use Google Authenticator, Authy, 1Password, or any TOTP-compatible app.
              </p>
            </div>

            <div className="flex justify-center p-5 bg-white rounded-xl border border-pw-border">
              <QRCode value={qrUrl} size={180} />
            </div>

            <div className="space-y-1.5">
              <p className="text-xs font-semibold text-pw-muted uppercase tracking-wider">Can&apos;t scan? Enter manually</p>
              <div
                className="font-mono text-sm text-pw-black bg-pw-glass-bg rounded-lg px-4 py-3 border border-pw-border select-all break-all leading-relaxed cursor-pointer hover:border-pw-primary/40 transition-colors"
                onClick={() => {
                  navigator.clipboard.writeText(secretKey);
                  toast.success('Secret key copied');
                }}
              >
                {secretKey}
              </div>
              <p className="text-[11px] text-pw-muted">Click to copy. Enter as the account key in your authenticator app.</p>
            </div>

            <button
              onClick={() => setStep('verify')}
              className="w-full py-3 rounded-xl bg-pw-primary text-white font-semibold text-sm hover:bg-pw-primary/90 transition-colors"
            >
              I&apos;ve added the account →
            </button>
          </div>
        )}

        {/* ── Step 3: Verify code + recovery acknowledgment ── */}
        {step === 'verify' && (
          <div className="space-y-5">
            <div>
              <p className="text-sm font-semibold text-pw-black mb-1">Enter the 6-digit code</p>
              <p className="text-xs text-pw-muted mb-4">
                Open your authenticator app and enter the current code for PaperWorking.
              </p>
              <input
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={6}
                value={code}
                onChange={(e) => setCode(e.target.value.replace(/\D/g, ''))}
                onKeyDown={(e) => e.key === 'Enter' && handleVerify()}
                placeholder="000000"
                autoFocus
                className="glass-input w-full text-center font-mono text-xl tracking-[0.4em] py-4 text-pw-black"
              />
            </div>

            {/* Recovery guidance — must be acknowledged */}
            <div className="p-4 rounded-xl border border-amber-400/30 bg-amber-400/5 space-y-3">
              <div className="flex items-center gap-2">
                <span className="material-symbols-outlined text-amber-500 text-lg select-none">warning</span>
                <p className="text-xs font-bold text-amber-500 uppercase tracking-wider">Recovery Notice</p>
              </div>
              <p className="text-[11px] text-pw-muted leading-relaxed">
                Firebase Identity Platform does not generate backup recovery codes for TOTP.
                If you lose access to your authenticator app, account recovery requires contacting
                PaperWorking support with proof of identity — there is no self-service recovery path.
              </p>
              <p className="text-[11px] text-pw-muted leading-relaxed">
                <strong className="text-pw-black">Recommendation:</strong> save the secret key shown
                in the previous step in a secure password manager as a TOTP seed backup.
              </p>
              <label className="flex items-start gap-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={recoveryAcked}
                  onChange={(e) => setRecoveryAcked(e.target.checked)}
                  className="mt-0.5 accent-pw-primary flex-shrink-0"
                />
                <span className="text-xs text-pw-black font-medium leading-relaxed">
                  I understand that losing my authenticator app requires identity-verified support to recover my account.
                </span>
              </label>
            </div>

            {error && <p className="text-xs text-red-400">{error}</p>}

            <div className="flex gap-3">
              <button
                onClick={() => { setCode(''); setError(null); setStep('qr'); }}
                className="flex-1 py-3 rounded-xl border border-pw-border text-sm font-semibold text-pw-muted hover:text-pw-black transition-colors"
              >
                ← Back
              </button>
              <button
                onClick={handleVerify}
                disabled={loading || code.length !== 6 || !recoveryAcked}
                className="flex-1 py-3 rounded-xl bg-pw-primary text-white font-semibold text-sm hover:bg-pw-primary/90 transition-colors disabled:opacity-50"
              >
                {loading ? 'Enrolling…' : 'Enable 2FA'}
              </button>
            </div>
          </div>
        )}

        {/* ── Step 4: Success ── */}
        {step === 'success' && (
          <div className="space-y-6 text-center">
            <div className="w-16 h-16 mx-auto rounded-full bg-pw-primary/15 border border-pw-primary/30 flex items-center justify-center">
              <span className="material-symbols-outlined text-pw-primary text-3xl select-none">check_circle</span>
            </div>
            <div>
              <p className="text-lg font-bold text-pw-black mb-2">2FA Enabled</p>
              <p className="text-sm text-pw-muted leading-relaxed">
                Your account is now protected with TOTP two-factor authentication.
                You&apos;ll be asked for a code from your authenticator app on every sign-in.
              </p>
            </div>
            <button
              onClick={() => { onEnrolled(); onClose(); }}
              className="w-full py-3 rounded-xl bg-pw-primary text-white font-semibold text-sm hover:bg-pw-primary/90 transition-colors"
            >
              Done
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';
import React, { useState, useCallback } from 'react';
import {
  multiFactor,
  reauthenticateWithCredential,
  EmailAuthProvider,
  MultiFactorInfo,
} from 'firebase/auth';
import { useAuth } from '@/context/AuthContext';
import posthog from 'posthog-js';

interface Props {
  totpFactor: MultiFactorInfo;
  onClose: () => void;
  onUnenrolled: () => void;
}

export default function MFAUnenrollModal({ totpFactor, onClose, onUnenrolled }: Props) {
  const { user } = useAuth();
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleUnenroll = useCallback(async () => {
    if (!user?.email) return;
    setError(null);
    setLoading(true);
    try {
      const credential = EmailAuthProvider.credential(user.email, password);
      await reauthenticateWithCredential(user, credential);
      await multiFactor(user).unenroll(totpFactor);
      try { posthog.capture('mfa_unenrolled', { factorId: 'totp' }); } catch { /* non-fatal */ }
      onUnenrolled();
      onClose();
    } catch (err: any) {
      if (err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
        setError('Incorrect password.');
      } else {
        setError(err.message || 'Failed to disable 2FA.');
      }
    } finally {
      setLoading(false);
    }
  }, [user, password, totpFactor, onClose, onUnenrolled]);

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        className="w-full max-w-sm glass-card rounded-2xl p-8 shadow-2xl"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center gap-3 mb-6">
          <span className="material-symbols-outlined text-red-400 text-2xl select-none">shield_lock</span>
          <h2 className="text-xl font-bold text-pw-black">Disable Two-Factor Auth</h2>
        </div>

        <p className="text-sm text-pw-muted mb-1">
          Disabling 2FA removes the extra security layer from your account.
        </p>
        <p className="text-xs text-pw-muted mb-6 leading-relaxed">
          Enter your password to confirm. This action takes effect immediately.
        </p>

        <input
          type="password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && handleUnenroll()}
          placeholder="Current password"
          autoFocus
          className="glass-input w-full text-sm px-4 py-3 text-pw-black mb-4"
        />

        {error && <p className="text-xs text-red-400 mb-4">{error}</p>}

        <div className="flex gap-3">
          <button
            onClick={onClose}
            className="flex-1 py-3 rounded-xl border border-pw-border text-sm font-semibold text-pw-muted hover:text-pw-black transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={handleUnenroll}
            disabled={loading || !password}
            className="flex-1 py-3 rounded-xl bg-red-500 text-white font-semibold text-sm hover:bg-red-600 transition-colors disabled:opacity-50"
          >
            {loading ? 'Disabling…' : 'Disable 2FA'}
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useCallback, useMemo } from 'react';
import { useProjectStore } from '@/store/projectStore';
import {
  ShieldCheck,
  CheckCircle2,
  Circle,
  FileText,
  Banknote,
  FileSignature,
  Building2,
  Landmark,
  ChevronDown,
  ChevronRight,
  AlertTriangle,
  Upload,
  Lock,
} from 'lucide-react';
import type { ClosingChecklistItem, ClosingChecklistItemType } from '@/types/schema';
import toast from 'react-hot-toast';
import FileDropzone from '@/components/shared/FileDropzone';

/* ═══════════════════════════════════════════════════════
   Closing Checklist — Final Settlement Validation
   Must be 100% complete before a deal is marked "Closed"

   Items:
     1. Proof of Funds / Hard Money Payoff
     2. Signed Purchase Contract
     3. Closing Disclosure
     4. Title / Deed Transfer
     5. Entity Documents (LLC/Inc)
   ═══════════════════════════════════════════════════════ */

const CHECKLIST_META: Record<ClosingChecklistItemType, { icon: React.ReactNode; description: string }> = {
  'Proof of Funds / Hard Money Payoff': {
    icon: <Banknote className="w-5 h-5" />,
    description: 'Verified proof of funds or documentation of hard money loan payoff',
  },
  'Signed Purchase Contract': {
    icon: <FileSignature className="w-5 h-5" />,
    description: 'Fully executed purchase agreement with all addenda',
  },
  'Closing Disclosure': {
    icon: <FileText className="w-5 h-5" />,
    description: 'Final closing disclosure reviewed and signed by all parties',
  },
  'Title / Deed Transfer': {
    icon: <Landmark className="w-5 h-5" />,
    description: 'Clean title with deed transfer recorded at county level',
  },
  'Entity Documents (LLC/Inc)': {
    icon: <Building2 className="w-5 h-5" />,
    description: 'Operating agreement, articles of organization, or corporate docs',
  },
};

const DEFAULT_CHECKLIST: ClosingChecklistItem[] = [
  { id: 'cc-1', type: 'Proof of Funds / Hard Money Payoff', completed: false, notes: '' },
  { id: 'cc-2', type: 'Signed Purchase Contract', completed: false, notes: '' },
  { id: 'cc-3', type: 'Closing Disclosure', completed: false, notes: '' },
  { id: 'cc-4', type: 'Title / Deed Transfer', completed: false, notes: '' },
  { id: 'cc-5', type: 'Entity Documents (LLC/Inc)', completed: false, notes: '' },
];

export default function ClosingChecklist() {
  const currentProject = useProjectStore(s => s.currentProject);
  const updateClosingChecklist = useProjectStore(s => s.updateClosingChecklist);

  const [items, setItems] = useState<ClosingChecklistItem[]>(
    () => currentProject?.closingChecklist ?? DEFAULT_CHECKLIST.map(c => ({ ...c }))
  );
  const [expanded, setExpanded] = useState(true);
  const [activeUploadId, setActiveUploadId] = useState<string | null>(null);

  const persist = useCallback(
    (next: ClosingChecklistItem[]) => {
      setItems(next);
      if (currentProject) updateClosingChecklist(currentProject.id, next);
    },
    [currentProject, updateClosingChecklist]
  );

  const toggleComplete = (id: string) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    const completed = !item.completed;
    persist(
      items.map(item =>
        item.id === id
          ? {
              ...item,
              completed,
              completedAt: completed ? new Date() : undefined,
            }
          : item
      )
    );
    toast.success(completed ? `${item.type} completed` : `${item.type} marked incomplete`);
  };

  const updateNotes = (id: string, notes: string) => {
    persist(items.map(item => (item.id === id ? { ...item, notes } : item)));
  };

  const handleUploadComplete = (id: string, url: string) => {
    const item = items.find(i => i.id === id);
    if (!item) return;
    persist(
      items.map(item =>
        item.id === id
          ? {
              ...item,
              documentUrl: url,
              completed: true,
              completedAt: new Date(),
            }
          : item
      )
    );
    toast.success(`${item.type} document uploaded`);
  };

  const completedCount = items.filter(i => i.completed).length;
  const totalCount = items.length;
  const allComplete = completedCount === totalCount;
  const progress = totalCount > 0 ? (completedCount / totalCount) * 100 : 0;

  // Can we close the deal?
  const canClose = allComplete && items.every(i => i.documentUrl);

  return (
    <div className="bg-bg-surface rounded-xl shadow-sm border border-border-accent overflow-hidden">
      {/* Header */}
      <button
        onClick={() => setExpanded(!expanded)}
        className="w-full flex items-center justify-between p-6 hover:bg-bg-primary transition"
      >
        <div className="flex items-center gap-2 text-left">
          {expanded ? <ChevronDown className="w-4 h-4 text-text-secondary" /> : <ChevronRight className="w-4 h-4 text-text-secondary" />}
          <ShieldCheck className="w-5 h-5 text-text-secondary" />
          <div>
            <h3 className="text-lg font-medium tracking-tight text-text-primary">Closing Checklist</h3>
            <p className="text-xs text-text-secondary mt-0.5">All items must be completed before deal can be marked &ldquo;Closed&rdquo;</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <span className={`text-sm font-mono font-medium ${allComplete ? 'text-green-600' : 'text-text-primary'}`}>
            {completedCount}/{totalCount}
          </span>
          {allComplete ? (
            <span className="bg-green-100 text-green-700 text-xs font-bold uppercase px-2 py-0.5 rounded-full">Ready</span>
          ) : (
            <span className="bg-amber-100 text-amber-700 text-xs font-bold uppercase px-2 py-0.5 rounded-full">Incomplete</span>
          )}
        </div>
      </button>

      {expanded && (
        <>
          {/* Progress bar */}
          <div className="px-6 pb-4">
            <div className="h-2 bg-bg-primary rounded-full overflow-hidden">
              <div
                className={`h-full rounded-full transition-all duration-500 ${
                  allComplete ? 'bg-green-500' : 'bg-gradient-to-r from-[#a5a5a5] to-[#7f7f7f]'
                }`}
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>

          {/* Checklist items */}
          <div className="px-6 pb-4 space-y-3">
            {items.map(item => {
              const meta = CHECKLIST_META[item.type];
              return (
                <div
                  key={item.id}
                  className={`rounded-lg border transition ${
                    item.completed
                      ? 'bg-green-50 border-green-200'
                      : 'border-border-accent hover:border-border-accent'
                  }`}
                >
                  <div className="p-4 flex items-start gap-3">
                    {/* Checkbox */}
                    <button
                      onClick={() => toggleComplete(item.id)}
                      className={`mt-0.5 flex-shrink-0 transition ${
                        item.completed ? 'text-green-500' : 'text-gray-300 hover:text-text-secondary'
                      }`}
                    >
                      {item.completed ? (
                        <CheckCircle2 className="w-5 h-5" />
                      ) : (
                        <Circle className="w-5 h-5" />
                      )}
                    </button>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2">
                        <span className={item.completed ? 'text-green-600' : 'text-text-secondary'}>
                          {meta.icon}
                        </span>
                        <h4
                          className={`text-sm font-semibold ${
                            item.completed ? 'text-green-800 line-through' : 'text-text-primary'
                          }`}
                        >
                          {item.type}
                        </h4>
                      </div>
                      <p className="text-xs text-text-secondary mt-1">{meta.description}</p>

                      {/* Document status */}
                      <div className="flex flex-col gap-2 mt-2 w-full">
                        {item.documentUrl ? (
                          <div className="flex items-center gap-3">
                            <span className="flex items-center gap-1 text-xs text-green-600 bg-green-50 border border-green-200 px-2 py-0.5 rounded">
                              <FileText className="w-3 h-3" /> Document Uploaded
                            </span>
                            <button
                              onClick={() => {
                                persist(
                                  items.map(i =>
                                    i.id === item.id
                                      ? { ...i, documentUrl: undefined, completed: false, completedAt: undefined }
                                      : i
                                  )
                                );
                                toast.success(`${item.type} document removed`);
                              }}
                              className="text-xs text-red-500 hover:text-red-400 hover:underline cursor-pointer"
                            >
                              Remove
                            </button>
                            {item.documentUrl && (
                              <a
                                href={item.documentUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-xs text-blue-500 hover:underline flex items-center gap-0.5"
                              >
                                View File
                              </a>
                            )}
                          </div>
                        ) : activeUploadId === item.id ? (
                          <div className="w-full max-w-md bg-surface-container/10 p-4 rounded-xl border border-border-accent">
                            <FileDropzone
                              projectId={currentProject?.id || 'unknown'}
                              path="closing_docs"
                              onUploadComplete={(res) => {
                                const secureUrl = `/api/projects/${currentProject?.id || 'unknown'}/documents/download?path=${encodeURIComponent(res.storagePath)}&name=${encodeURIComponent(item.type)}`;
                                handleUploadComplete(item.id, secureUrl);
                                setActiveUploadId(null);
                              }}
                            />
                            <div className="flex justify-end mt-2">
                              <button
                                onClick={() => setActiveUploadId(null)}
                                className="text-xs text-text-secondary hover:text-text-primary transition px-2 py-1 rounded"
                              >
                                Cancel
                              </button>
                            </div>
                          </div>
                        ) : (
                          <div className="flex items-center">
                            <button
                              onClick={() => setActiveUploadId(item.id)}
                              className="flex items-center gap-1 text-xs text-text-secondary bg-bg-primary border border-border-accent px-2 py-0.5 rounded hover:bg-bg-primary transition"
                            >
                              <Upload className="w-3 h-3" /> Upload Document
                            </button>
                          </div>
                        )}
                        {item.completedAt && (
                          <span className="text-xs text-text-secondary">
                            Completed {new Date(item.completedAt).toLocaleDateString()}
                          </span>
                        )}
                      </div>

                      {/* Notes */}
                      <input
                        type="text"
                        value={item.notes}
                        onChange={e => updateNotes(item.id, e.target.value)}
                        placeholder="Add notes..."
                        className="mt-2 w-full text-xs bg-transparent border-b border-border-accent focus:border-gray-400 outline-none py-1 text-text-secondary placeholder:text-gray-300"
                      />
                    </div>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Close Deal Gate */}
          <div className="px-6 py-4 border-t border-border-accent">
            {canClose ? (
              <div className="p-4 bg-green-50 border border-green-200 rounded-lg flex items-center gap-3">
                <ShieldCheck className="w-6 h-6 text-green-600 flex-shrink-0" />
                <div>
                  <p className="text-sm font-semibold text-green-900">All settlement requirements met</p>
                  <p className="text-xs text-green-700 mt-0.5">This deal is ready to be marked as &ldquo;Closed.&rdquo;</p>
                </div>
              </div>
            ) : (
              <div className="p-4 bg-bg-primary border border-border-accent rounded-lg flex items-center gap-3">
                <Lock className="w-5 h-5 text-text-secondary flex-shrink-0" />
                <div>
                  <p className="text-sm font-medium text-text-primary">
                    {totalCount - completedCount} item{totalCount - completedCount !== 1 ? 's' : ''} remaining
                  </p>
                  <p className="text-xs text-text-secondary mt-0.5">
                    Complete all checklist items and upload supporting documents to close this deal.
                  </p>
                </div>
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

