              <div className="flex gap-4 items-center">
                {/* Active filter badge */}
                {isFilterActive && (
                  <span className="text-xs font-black text-pw-accent uppercase tracking-widest border border-pw-accent/40 px-3 py-1">
                    {FILTER_LABELS[filterType]}
                    <button
