'use client';

import React, {
  useState,
  useEffect,
  useCallback,
  useRef,
  useId,
} from 'react';
import { ArrowRight, ArrowLeft, CheckCircle2 } from 'lucide-react';
import ConvCurrencyInput from './ConvCurrencyInput';
import type {
  QuestionDef,
  FormAnswers,
  SlideDirection,
  SelectOption,
} from './types';

/* ═══════════════════════════════════════════════════════════════
   ConversationalForm — Sequential Question Engine

   Renders one question at a time with horizontal slide transitions.
   Schema-driven: accepts any array of QuestionDef objects.

   Data flow:
     • Each answer is stored in `answers` state (key → value map)
     • On Next: validates → calls onStepSave(partialAnswers) → advances
     • On final step Next: calls onComplete(allAnswers)
     • Enter key = Next, Escape = Back (when not on step 0)

   Used in Phase 1 (and future phases) to replace static form grids.
   ═══════════════════════════════════════════════════════════════ */

// ── Animation duration (ms) ──────────────────────────────────────────────────
const TRANSITION_MS = 220;

// ── Slide keyframe helpers (inline style approach — no Tailwind needed) ───────
function getSlideStyle(
  direction: SlideDirection,
  phase: 'enter' | 'active' | 'exit',
): React.CSSProperties {
  // "enter" = the incoming slide starting position
  // "active" = the resting, fully-visible position
  // "exit"  = the outgoing slide ending position

  if (direction === 'idle') {
    return { opacity: 1, transform: 'translateX(0)' };
  }

  const exitX  = direction === 'forward' ? '-64px' : '64px';
  const enterX = direction === 'forward' ? '64px'  : '-64px';

  if (phase === 'enter')  return { opacity: 0, transform: `translateX(${enterX})` };
  if (phase === 'active') return { opacity: 1, transform: 'translateX(0)' };
  if (phase === 'exit')   return { opacity: 0, transform: `translateX(${exitX})` };
  return {};
}

// ── Props ─────────────────────────────────────────────────────────────────────
export interface ConversationalFormProps {
  questions:       QuestionDef[];
  initialAnswers?: Partial<FormAnswers>;
  phaseColor:      string;
  readOnly?:       boolean;
  /** Called on each Next step — persist partial state to Firestore */
  onStepSave?:     (answers: Partial<FormAnswers>) => Promise<void>;
  /** Called when the user completes the final step */
  onComplete?:     (answers: FormAnswers) => void;
}

// ── Select Input component (inline) ──────────────────────────────────────────
function ConvSelectInput({
  options,
  value,
  onChange,
  phaseColor,
  readOnly,
}: {
  options:    SelectOption[];
  value:      string | undefined;
  onChange:   (v: string) => void;
  phaseColor: string;
  readOnly?:  boolean;
}) {
  return (
    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '12px', paddingTop: '8px' }}>
      {options.map((opt) => {
        const selected = value === opt.value;
        return (
          <button
            key={opt.value}
            type="button"
            disabled={readOnly}
            onClick={() => onChange(opt.value)}
            style={{
              padding:       '14px 28px',
              borderRadius:  '100px',
              border:        `2px solid ${selected ? phaseColor : 'var(--border-ui)'}`,
              background:    selected ? phaseColor : 'var(--bg-surface)',
              color:         selected ? '#FFFFFF' : 'var(--text-primary)',
              fontSize:      '15px',
              fontWeight:    700,
              letterSpacing: '0.02em',
              cursor:        readOnly ? 'not-allowed' : 'pointer',
              transition:    `all ${TRANSITION_MS}ms ease`,
              display:       'flex',
              flexDirection: 'column',
              alignItems:    'center',
              gap:           '4px',
            }}
          >
            {opt.label}
            {opt.description && (
              <span
                style={{
                  fontSize:   '11px',
                  fontWeight: 400,
                  opacity:    0.7,
                }}
              >
                {opt.description}
              </span>
            )}
          </button>
        );
      })}
    </div>
  );
}

// ── Number/Percent input component (inline) ────────────────────────────────
function ConvNumberInput({
  value,
  onChange,
  phaseColor,
  unit,
  placeholder,
  readOnly,
  precision: _precision = 0,
}: {
  value:       number | undefined;
  onChange:    (v: number) => void;
  phaseColor:  string;
  unit?:       string;
  placeholder?: string;
  readOnly?:   boolean;
  precision?:  number;
}) {
  const inputRef = useRef<HTMLInputElement>(null);
  const inputId  = useId();

  const [display, setDisplay] = useState(
    value !== undefined && value !== 0 ? String(value) : '',
  );

  useEffect(() => {
    setDisplay(value !== undefined && value !== 0 ? String(value) : '');
  }, [value]);

  useEffect(() => {
    const t = setTimeout(() => inputRef.current?.focus(), 180);
    return () => clearTimeout(t);
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (readOnly) return;
    const raw = e.target.value.replace(/[^0-9.]/g, '');
    setDisplay(raw);
    const parsed = parseFloat(raw);
    if (!isNaN(parsed)) onChange(parsed);
    else if (raw === '' || raw === '.') onChange(0);
  };

  return (
    <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px', maxWidth: '420px' }}>
      <input
        id={inputId}
        ref={inputRef}
        type="text"
        inputMode="decimal"
        value={display}
        onChange={handleChange}
        readOnly={readOnly}
        placeholder={placeholder ?? '0'}
        autoComplete="off"
        style={{
          flex:            1,
          fontSize:        '52px',
          fontWeight:      800,
          fontVariantNumeric: 'tabular-nums',
          letterSpacing:   '-0.02em',
          lineHeight:      1,
          color:           readOnly ? phaseColor : 'var(--text-primary)',
          background:      'transparent',
          border:          'none',
          borderBottom:    `2px solid ${phaseColor}`,
          outline:         'none',
          padding:         '0 0 8px 0',
          caretColor:      phaseColor,
          cursor:          readOnly ? 'not-allowed' : 'text',
        }}
        aria-label={unit}
      />
      {unit && (
        <span
          style={{
            fontSize:   '22px',
            fontWeight: 600,
            color:      'var(--text-secondary)',
            opacity:    0.5,
            whiteSpace: 'nowrap',
          }}
        >
          {unit}
        </span>
      )}
    </div>
  );
}

// ── Main ConversationalForm component ─────────────────────────────────────────
export default function ConversationalForm({
  questions,
  initialAnswers = {},
  phaseColor,
  readOnly = false,
  onStepSave,
  onComplete,
}: ConversationalFormProps) {
  const [step, setStep]         = useState(0);
  const [answers, setAnswers]   = useState<Partial<FormAnswers>>(initialAnswers);
  const [direction, setDirection] = useState<SlideDirection>('idle');
  const [visible, setVisible]   = useState(true); // drives enter/exit phase
  const [saving, setSaving]     = useState(false);
  const [error, setError]       = useState('');
  const [completed, setCompleted] = useState(false);

  const total   = questions.length;
  const current = questions[step];
  const isLast  = step === total - 1;
  const isFirst = step === 0;

  // ── Get/set answer for the current question ────────────────────────────────
  const currentValue = answers[current.key];

  const setCurrentValue = useCallback(
    (val: number | string | undefined) => {
      setAnswers((prev) => ({ ...prev, [current.key]: val }));
      setError('');
    },
    [current.key],
  );

  // ── Validation ─────────────────────────────────────────────────────────────
  const validate = (): boolean => {
    if (current.optional) return true;
    if (current.type === 'info') return true;

    const val = currentValue;

    if (val === undefined || val === '' || val === null) {
      setError('This field is required.');
      return false;
    }

    // Numeric fields (currency, percent, integer): 0 is never a valid required
    // financial input (purchasePrice, loanAmount, etc.). Prevents division-by-zero.
    const isNumericType = current.type === 'currency' || current.type === 'percent' || current.type === 'integer';
    if (isNumericType && Number(val) === 0) {
      setError('Please enter a value greater than 0.');
      return false;
    }

    setError('');
    return true;
  };

  // ── Animated transition helper ─────────────────────────────────────────────
  const animateTo = useCallback(
    async (targetStep: number, dir: SlideDirection) => {
      setDirection(dir);
      setVisible(false);                          // exit current
      await new Promise((r) => setTimeout(r, TRANSITION_MS));
      setStep(targetStep);
      setVisible(true);                           // enter next
      await new Promise((r) => setTimeout(r, TRANSITION_MS));
      setDirection('idle');
    },
    [],
  );

  // ── Next ───────────────────────────────────────────────────────────────────
  const handleNext = useCallback(async () => {
    if (saving || readOnly) return;
    if (!validate()) return;

    // Persist the current partial state on each step
    if (onStepSave) {
      setSaving(true);
      try {
        await onStepSave({ ...answers });
      } catch {
        setError('Auto-save failed — please try again.');
        setSaving(false);
        return;
      }
      setSaving(false);
    }

    if (isLast) {
      setCompleted(true);
      onComplete?.({ ...answers } as FormAnswers);
      return;
    }

    await animateTo(step + 1, 'forward');
  }, [saving, readOnly, validate, onStepSave, answers, isLast, animateTo, step, onComplete]);

  // ── Back ───────────────────────────────────────────────────────────────────
  const handleBack = useCallback(async () => {
    if (isFirst || saving) return;
    await animateTo(step - 1, 'backward');
  }, [isFirst, saving, animateTo, step]);

  // ── Keyboard ───────────────────────────────────────────────────────────────
  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      // Enter advances — but only if the target is not a textarea
      if (e.key === 'Enter' && !(e.target instanceof HTMLTextAreaElement)) {
        e.preventDefault();
        handleNext();
      }
      // Escape goes back
      if (e.key === 'Escape') handleBack();
    };
    window.addEventListener('keydown', handler);
    return () => window.removeEventListener('keydown', handler);
  }, [handleNext, handleBack]);

  // ── Completed state ────────────────────────────────────────────────────────
  if (completed) {
    return (
      <div
        style={{
          display:        'flex',
          flexDirection:  'column',
          alignItems:     'center',
          justifyContent: 'center',
          minHeight:      '420px',
          gap:            '20px',
          padding:        '48px 32px',
          textAlign:      'center',
          animation:      `conv-fadein ${TRANSITION_MS * 2}ms ease`,
        }}
      >
        <div
          style={{
            width:          '64px',
            height:         '64px',
            borderRadius:   '50%',
            background:     `${phaseColor}18`,
            display:        'flex',
            alignItems:     'center',
            justifyContent: 'center',
          }}
        >
          <CheckCircle2 size={28} color={phaseColor} strokeWidth={2} />
        </div>
        <div>
          <p
            style={{
              fontSize:   '22px',
              fontWeight: 800,
              color:      'var(--text-primary)',
              margin:     0,
            }}
          >
            Phase inputs complete
          </p>
          <p
            style={{
              fontSize:  '13px',
              color:     'var(--text-secondary)',
              marginTop: '8px',
            }}
          >
            Your deal data has been saved. Review below or advance to Phase 2.
          </p>
        </div>
      </div>
    );
  }

  // ── Slide style (current card) ─────────────────────────────────────────────
  const slideStyle: React.CSSProperties = {
    transition: `opacity ${TRANSITION_MS}ms ease, transform ${TRANSITION_MS}ms ease`,
    ...(visible
      ? getSlideStyle('idle', 'active')
      : getSlideStyle(direction, 'exit')),
  };

  // ── Dot progress indicators (max 10 dots, then collapse to counter) ────────
  const showDots = total <= 10;

  return (
    <>
      {/* ── Global keyframe for completed state fade-in ── */}
      <style>{`
        @keyframes conv-fadein {
          from { opacity: 0; transform: translateY(12px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>

      <div
        style={{
          display:       'flex',
          flexDirection: 'column',
          minHeight:     '520px',
          background:    'var(--bg-surface)',
          borderRadius:  '12px',
          border:        '1px solid var(--border-ui)',
          overflow:      'hidden',
          position:      'relative',
        }}
      >
        {/* ── Top accent bar ───────────────────────────────────────────── */}
        <div style={{ height: '3px', background: phaseColor, width: '100%' }} />

        {/* ── Phase label ──────────────────────────────────────────────── */}
        <div
          style={{
            padding:      '16px 32px 0',
            display:      'flex',
            alignItems:   'center',
            justifyContent: 'space-between',
          }}
        >
          <span
            style={{
              fontSize:      '10px',
              fontWeight:    700,
              letterSpacing: '0.18em',
              textTransform: 'uppercase',
              color:         phaseColor,
              opacity:       0.7,
            }}
          >
            Deal Inputs
          </span>
          {saving && (
            <span
              style={{
                fontSize:  '10px',
                fontWeight: 600,
                color:     'var(--text-secondary)',
                opacity:   0.5,
              }}
            >
              Saving…
            </span>
          )}
        </div>

        {/* ── Animated question card ───────────────────────────────────── */}
        <div
          style={{
            flex:    1,
            padding: '32px 32px 24px',
            ...slideStyle,
          }}
        >
          {/* Question heading */}
          <p
            style={{
              fontSize:    '28px',
              fontWeight:  800,
              lineHeight:  1.25,
              color:       'var(--text-primary)',
              margin:      '0 0 8px 0',
              maxWidth:    '540px',
            }}
          >
            {current.question}
          </p>

          {/* Hint text */}
          {current.hint && (
            <p
              style={{
                fontSize:  '14px',
                color:     'var(--text-secondary)',
                margin:    '0 0 32px 0',
                lineHeight: 1.6,
                maxWidth:  '480px',
              }}
            >
              {current.hint}
            </p>
          )}
          {!current.hint && <div style={{ marginBottom: '32px' }} />}

          {/* ── Input switcher ── */}
          {current.type === 'currency' && (
            <ConvCurrencyInput
              label={current.question}
              value={(currentValue as number) ?? 0}
              onChange={(cents) => setCurrentValue(cents)}
              phaseColor={phaseColor}
              placeholder={current.placeholder}
              readOnly={readOnly}
            />
          )}

          {current.type === 'percent' && (
            <ConvNumberInput
              value={(currentValue as number) ?? undefined}
              onChange={(v) => setCurrentValue(v)}
              phaseColor={phaseColor}
              unit="%"
              placeholder={current.placeholder}
              readOnly={readOnly}
              precision={current.precision ?? 2}
            />
          )}

          {current.type === 'integer' && (
            <ConvNumberInput
              value={(currentValue as number) ?? undefined}
              onChange={(v) => setCurrentValue(Math.round(v))}
              phaseColor={phaseColor}
              unit={current.unit}
              placeholder={current.placeholder}
              readOnly={readOnly}
            />
          )}

          {current.type === 'select' && (
            <ConvSelectInput
              options={current.options}
              value={(currentValue as string) ?? undefined}
              onChange={(v) => setCurrentValue(v)}
              phaseColor={phaseColor}
              readOnly={readOnly}
            />
          )}

          {current.type === 'info' && (
            <p
              style={{
                fontSize:   '52px',
                fontWeight: 800,
                color:      phaseColor,
                lineHeight: 1,
                margin:     0,
                fontVariantNumeric: 'tabular-nums',
                letterSpacing: '-0.02em',
              }}
            >
              {current.renderValue(answers)}
            </p>
          )}

          {/* Inline error */}
          {error && (
            <p
              style={{
                marginTop:  '12px',
                fontSize:   '12px',
                fontWeight: 600,
                color:      '#DC2626',
              }}
            >
              {error}
            </p>
          )}
        </div>

        {/* ── Footer bar: Back | Progress | Next ───────────────────────── */}
        <div
          style={{
            display:       'flex',
            alignItems:    'center',
            justifyContent: 'space-between',
            padding:       '16px 32px 24px',
            borderTop:     '1px solid var(--border-ui)',
            gap:           '16px',
          }}
        >
          {/* Back button */}
          <button
            type="button"
            onClick={handleBack}
            disabled={isFirst || saving}
            style={{
              display:     'flex',
              alignItems:  'center',
              gap:         '6px',
              padding:     '10px 20px',
              borderRadius: '8px',
              border:      '1px solid var(--border-ui)',
              background:  'transparent',
              color:       isFirst ? 'transparent' : 'var(--text-secondary)',
              fontSize:    '12px',
              fontWeight:  700,
              letterSpacing: '0.1em',
              textTransform: 'uppercase',
              cursor:      isFirst ? 'default' : 'pointer',
              transition:  'all 150ms ease',
              pointerEvents: isFirst ? 'none' : 'auto',
            }}
            aria-label="Previous question"
          >
            <ArrowLeft size={13} strokeWidth={2.5} />
            Back
          </button>

          {/* Progress indicator */}
          <div
            style={{
              display:    'flex',
              flexDirection: 'column',
              alignItems: 'center',
              gap:        '8px',
              flex:       1,
            }}
          >
            {/* Dot indicators */}
            {showDots && (
              <div style={{ display: 'flex', gap: '6px' }}>
                {questions.map((_, i) => (
                  <div
                    key={i}
                    style={{
                      width:        i === step ? '20px' : '7px',
                      height:       '7px',
                      borderRadius: '100px',
                      background:   i <= step ? phaseColor : 'var(--border-ui)',
                      transition:   `all ${TRANSITION_MS}ms ease`,
                      opacity:      i < step ? 0.4 : 1,
                    }}
                  />
                ))}
              </div>
            )}

            {/* Counter label */}
            <span
              style={{
                fontSize:      '10px',
                fontWeight:    700,
                letterSpacing: '0.15em',
                textTransform: 'uppercase',
                color:         'var(--text-secondary)',
                opacity:       0.5,
              }}
            >
              Question {step + 1} of {total}
            </span>
          </div>

          {/* Next / Finish button */}
          <button
            type="button"
            id={`conv-next-step-${step}`}
            onClick={handleNext}
            disabled={saving}
            style={{
              display:      'flex',
              alignItems:   'center',
              gap:          '8px',
              padding:      '10px 24px',
              borderRadius: '8px',
              border:       'none',
              background:   saving ? `${phaseColor}80` : phaseColor,
              color:        '#FFFFFF',
              fontSize:     '12px',
              fontWeight:   700,
              letterSpacing: '0.1em',
              textTransform: 'uppercase',
              cursor:       saving ? 'not-allowed' : 'pointer',
              transition:   'all 150ms ease',
              whiteSpace:   'nowrap',
            }}
            aria-label={isLast ? 'Complete phase inputs' : 'Next question'}
          >
            {isLast ? 'Complete' : 'Next'}
            {!isLast && <ArrowRight size={13} strokeWidth={2.5} />}
            {isLast  && <CheckCircle2 size={13} strokeWidth={2.5} />}
          </button>
        </div>
      </div>
    </>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Project } from '@/types/schema';
import { DealFolderIcon } from './DealFolder';
import {
  AlertCircle, AlertTriangle, Info,
  DollarSign, Clock, FileWarning, Users, Receipt, ArrowRight,
} from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   DealGroomingAlerts — Logic-Based Deal Health Monitor

   Scans all active projects against a ruleset and emits alerts
   for projects that need attention ("grooming"). Each alert maps
   to a specific corrective action and links to the deal.

   Rules:
     🔴 Critical   — Missing financials, incomplete closing docs
     🟠 Action     — Pending receipts, budget overruns
     🟡 Warning    — Stale phases, no team assigned, unverified docs
   ═══════════════════════════════════════════════════════════════ */

type AlertSeverity = 'critical' | 'action' | 'warning';

interface GroomingAlert {
  id: string;
  projectId: string;
  dealAddress: string;
  dealStatus: string;
  title: string;
  description: string;
  severity: AlertSeverity;
  icon: React.ReactNode;
}

function shortAddress(address: string): string {
  const comma = address.indexOf(',');
  return comma > 0 ? address.slice(0, comma) : address;
}

/**
 * Core grooming rules — each rule scans a deal and may push alerts.
 */
function evaluateDeal(deal: Project, alerts: GroomingAlert[]): void {
  const addr = shortAddress(deal.address || deal.propertyName);
  const base = { projectId: deal.id, dealAddress: addr, dealStatus: deal.status };

  // ── Rule 1: Missing Financials ──────────────────────────
  // Purchase price is 0 and the deal has moved past Lead
  if (
    (!deal.financials?.purchasePrice || deal.financials.purchasePrice === 0) &&
    deal.status !== 'acquisition'
  ) {
    alerts.push({
      ...base,
      id: `groom-fin-${deal.id}`,
      title: 'Missing Purchase Price',
      description: `${addr} has no purchase price set. Financial projections cannot calculate.`,
      severity: 'critical',
      icon: <DollarSign className="w-4 h-4" />,
    });
  }

  // ── Rule 2: Stale Phase ─────────────────────────────────
  // Deal hasn't been updated in 14+ days
  const now = new Date();
  const updatedAt = deal.updatedAt ? new Date(deal.updatedAt) : new Date(deal.createdAt || now);
  const daysSinceUpdate = Math.floor((now.getTime() - updatedAt.getTime()) / (1000 * 60 * 60 * 24));
  if (daysSinceUpdate >= 14 && deal.status !== 'exit') {
    alerts.push({
      ...base,
      id: `groom-stale-${deal.id}`,
      title: 'Stale — No Activity',
      description: `${addr} hasn't been updated in ${daysSinceUpdate} days. Is this deal still active?`,
      severity: 'warning',
      icon: <Clock className="w-4 h-4" />,
    });
  }

  // ── Rule 3: Incomplete Closing Docs ─────────────────────
  // Status is Under Contract but closing checklist has uncompleted items
  if (deal.status === 'fund') {
    const uncompleted = deal.closingChecklist?.filter(i => !i.completed)?.length || 0;
    if (uncompleted > 0) {
      alerts.push({
        ...base,
        id: `groom-closing-${deal.id}`,
        title: 'Closing Docs Incomplete',
        description: `${uncompleted} closing checklist item${uncompleted > 1 ? 's' : ''} still incomplete.`,
        severity: 'critical',
        icon: <FileWarning className="w-4 h-4" />,
      });
    }
  }

  // ── Rule 4: Unverified Documents ────────────────────────
  const unverifiedDocs = deal.roleLinkedDocuments?.filter(d => !d.verified)?.length || 0;
  if (unverifiedDocs > 0) {
    alerts.push({
      ...base,
      id: `groom-docs-${deal.id}`,
      title: 'Unverified Documents',
      description: `${unverifiedDocs} document${unverifiedDocs > 1 ? 's' : ''} awaiting verification.`,
      severity: 'warning',
      icon: <FileWarning className="w-4 h-4" />,
    });
  }

  // ── Rule 5: Budget Overrun ──────────────────────────────
  // Approved costs exceed 90% of the rehab base budget
  if (deal.rehab?.baseBudget && deal.rehab.baseBudget > 0) {
    const approvedSum = deal.financials?.costs
      ?.filter(c => c.approved)
      .reduce((sum, c) => sum + c.amount, 0) || 0;
    const utilization = approvedSum / deal.rehab.baseBudget;
    if (utilization >= 0.9) {
      alerts.push({
        ...base,
        id: `groom-budget-${deal.id}`,
        title: 'Budget Overrun Risk',
        description: `Rehab spending at ${Math.round(utilization * 100)}% of the $${deal.rehab.baseBudget.toLocaleString()} base budget.`,
        severity: 'critical',
        icon: <DollarSign className="w-4 h-4" />,
      });
    }
  }

  // ── Rule 6: No Team Assigned ────────────────────────────
  if ((!deal.projectTeam || deal.projectTeam.length === 0) && deal.status !== 'acquisition') {
    alerts.push({
      ...base,
      id: `groom-team-${deal.id}`,
      title: 'No Team Assigned',
      description: `${addr} has no team members. Assign roles for accountability.`,
      severity: 'warning',
      icon: <Users className="w-4 h-4" />,
    });
  }

  // ── Rule 7: Pending Receipts ────────────────────────────
  const pendingReceipts = deal.rehab?.pendingReceipts?.filter(r => r.status === 'pending')?.length || 0;
  if (pendingReceipts > 0) {
    alerts.push({
      ...base,
      id: `groom-receipts-${deal.id}`,
      title: 'Pending Receipt Triage',
      description: `${pendingReceipts} receipt${pendingReceipts > 1 ? 's' : ''} queued for review.`,
      severity: 'action',
      icon: <Receipt className="w-4 h-4" />,
    });
  }
}

/* ─── Severity styling ─── */
const SEVERITY_CONFIG: Record<AlertSeverity, { border: string; bg: string; text: string; dot: string; label: string }> = {
  critical: { border: 'border-pw-border', bg: 'bg-pw-black text-white', text: 'text-white', dot: 'bg-bg-surface', label: 'Priority' },
  action:   { border: 'border-border-accent/50', bg: 'bg-bg-primary text-text-primary', text: 'text-text-primary', dot: 'bg-pw-black', label: 'Required' },
  warning:  { border: 'border-border-accent/20', bg: 'bg-bg-primary/50 text-text-secondary', text: 'text-text-secondary', dot: 'bg-pw-muted', label: 'Monitor' },
};

interface DealGroomingAlertsProps {
  projects: Project[];
  onNavigateToDeal: (projectId: string) => void;
}

export default function DealGroomingAlerts({ projects, onNavigateToDeal }: DealGroomingAlertsProps) {
  const alerts = useMemo(() => {
    const collected: GroomingAlert[] = [];
    projects.forEach(d => evaluateDeal(d, collected));
    const order: Record<AlertSeverity, number> = { critical: 0, action: 1, warning: 2 };
    collected.sort((a, b) => order[a.severity] - order[b.severity]);
    return collected;
  }, [projects]);

  const criticalCt = alerts.filter(a => a.severity === 'critical').length;

  return (
    <div className="ag-card bg-bg-surface shadow-[0_30px_60px_rgba(0,0,0,0.02)] border border-border-accent/10 flex flex-col h-full min-h-[500px]">
      {/* Header */}
      <div className="px-8 py-10 flex items-center justify-between border-b border-border-accent/10">
          <div className="space-y-1">
            <div className="flex items-center gap-3">
              <AlertCircle className="w-5 h-5 text-text-primary" />
              <p className="ag-label opacity-60">Deal Hygiene</p>
            </div>
            <h3 className="text-3xl font-normal text-text-primary tracking-tighter">Grooming Portal</h3>
          </div>
          {criticalCt > 0 && (
            <div className="bg-pw-black px-4 py-2 rounded-full flex items-center gap-2">
              <span className="w-1.5 h-1.5 rounded-full bg-bg-surface animate-pulse" />
              <span className="text-[10px] font-bold text-white tracking-widest uppercase">
                {criticalCt} Critical
              </span>
            </div>
          )}
      </div>

      <div className="px-8 py-5 border-b border-border-accent/10 bg-bg-primary/20">
        <p className="text-[10px] font-bold text-text-secondary/60 uppercase tracking-[0.2em] leading-none">
          {alerts.length === 0 ? 'System State: Optimal' : `${alerts.length} Anomalies Resolved`}
        </p>
      </div>

      {/* Alerts list */}
      <div className="flex-1 overflow-y-auto px-6 py-8 space-y-4">
        {alerts.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 text-text-secondary opacity-40">
            <Info className="w-12 h-12 mb-4 stroke-[1px]" />
            <p className="text-sm font-medium">Protocol Nominal.</p>
          </div>
        ) : (
          alerts.map(alert => {
            const sev = SEVERITY_CONFIG[alert.severity];
            return (
              <button
                key={alert.id}
                onClick={() => onNavigateToDeal(alert.projectId)}
                className={`w-full flex items-start gap-6 p-6 rounded-3xl border transition-all duration-300 group hover:scale-[1.01] hover:shadow-lg shadow-pw-black/5 ${sev.border} ${alert.severity === 'critical' ? 'bg-pw-black text-white' : 'bg-bg-surface'}`}
              >
                {/* Severity icon */}
                <div className={`shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all duration-500 ${alert.severity === 'critical' ? 'bg-bg-surface/10 text-white' : 'bg-bg-primary text-text-primary group-hover:bg-pw-black group-hover:text-white'}`}>
                  {alert.icon}
                </div>

                {/* Alert content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-3 mb-2">
                    <span className={`text-[9px] font-bold uppercase tracking-[0.2em] px-3 py-1 rounded-full border ${alert.severity === 'critical' ? 'border-white/20 text-white' : 'border-border-accent/50 text-text-secondary'}`}>
                      {sev.label}
                    </span>
                    <span className={`text-[10px] font-medium uppercase tracking-widest truncate opacity-40`}>
                      {alert.dealAddress}
                    </span>
                  </div>
                  <p className={`text-lg font-medium tracking-tight leading-tight`}>
                    {alert.title}
                  </p>
                  <p className={`text-xs mt-2 font-normal leading-relaxed opacity-60 line-clamp-2`}>
                    {alert.description}
                  </p>
                </div>

                <div className="shrink-0 opacity-0 group-hover:opacity-40 transition-opacity self-center">
                   <ArrowRight className="w-5 h-5" />
                </div>
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

