'use client';

import React, { useMemo, useState } from 'react';
import { Project } from '@/types/schema';
import { DealFolderIcon } from './DealFolder';
import {
  CheckCircle2, Circle, Clock, AlertTriangle,
  FileText, Receipt, ClipboardCheck, User2,
} from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   GlobalTodoEngine — Unified Cross-Deal Task Aggregator

   Scans every active deal and rolls up actionable items into a
   single prioritized list. Each row attributes the responsible
   team member based on deal role assignments.

   Data Sources:
     • rehabTasks (Pending/In Progress)
     • closingChecklist (incomplete items)
     • rehab.pendingReceipts (pending review)
     • roleLinkedDocuments (unverified)
     • prospects with active offers
   ═══════════════════════════════════════════════════════════════ */

type TaskUrgency = 'overdue' | 'action' | 'upcoming';
type FilterTab = 'all' | 'overdue' | 'action';

interface AggregatedTask {
  id: string;
  projectId: string;
  dealAddress: string;
  dealStatus: string;
  label: string;
  category: string;
  urgency: TaskUrgency;
  assignee: string | null;
  icon: React.ReactNode;
}

/**
 * Extracts the street portion of an address for compact display.
 */
function shortAddress(address: string): string {
  const comma = address.indexOf(',');
  return comma > 0 ? address.slice(0, comma) : address;
}

/**
 * Resolves the most relevant team member name for a given task type.
 */
function resolveAssignee(deal: Project, taskType: string): string | null {
  // Check deal team first
  if (deal.projectTeam?.length) {
    const roleMap: Record<string, string[]> = {
      'rehab':     ['General Contractor'],
      'receipt':   ['General Contractor'],
      'closing':   ['Closing Agent', 'Title Company/Escrow Officer'],
      'document':  ['Loan Officer/Broker', 'Appraiser', 'Title Company/Escrow Officer'],
      'offer':     ['Real Estate Agent'],
    };
    const targetRoles = roleMap[taskType] || [];
    for (const role of targetRoles) {
      const member = deal.projectTeam.find((m: { projectRole: string; status: string; displayName: string }) => m.projectRole === role && m.status === 'active');
      if (member) return member.displayName;
    }
  }
  // Fallback to deal owner via members map
  if (deal.members) {
    const ownerEntry = Object.values(deal.members).find(m => m.role === 'Lead Investor');
    if (ownerEntry) return 'Lead Investor';
  }
  return null;
}

/**
 * Core aggregation: scan all projects and emit tasks.
 */
function aggregateTasks(projects: Project[]): AggregatedTask[] {
  const tasks: AggregatedTask[] = [];

  projects.forEach(deal => {
    const addr = shortAddress(deal.address || deal.propertyName);
    const base = { projectId: deal.id, dealAddress: addr, dealStatus: deal.status };

    // ── Rehab Tasks (Pending / In Progress) ──
    deal.financials?.rehabTasks?.forEach(task => {
      if (task.status === 'Complete') return;
      tasks.push({
        ...base,
        id: `rehab-${deal.id}-${task.id}`,
        label: `${task.title} — ${task.category}`,
        category: 'Rehab',
        urgency: task.status === 'In Progress' ? 'action' : 'upcoming',
        assignee: resolveAssignee(deal, 'rehab'),
        icon: <ClipboardCheck className="w-3.5 h-3.5 text-[#595959]" />,
      });
    });

    // ── Closing Checklist (incomplete) ──
    deal.closingChecklist?.forEach(item => {
      if (item.completed) return;
      tasks.push({
        ...base,
        id: `closing-${deal.id}-${item.id}`,
        label: `${item.type}`,
        category: 'Closing',
        urgency: deal.status === 'fund' ? 'overdue' : 'action',
        assignee: resolveAssignee(deal, 'closing'),
        icon: <FileText className="w-3.5 h-3.5 text-[#595959]" />,
      });
    });

    // ── Pending Receipts (triage queue) ──
    deal.rehab?.pendingReceipts?.forEach(receipt => {
      if (receipt.status !== 'pending') return;
      tasks.push({
        ...base,
        id: `receipt-${deal.id}-${receipt.id}`,
        label: `Review $${receipt.amount.toLocaleString()} receipt — ${receipt.budgetLineItem}`,
        category: 'Triage',
        urgency: 'action',
        assignee: resolveAssignee(deal, 'receipt'),
        icon: <Receipt className="w-3.5 h-3.5 text-[#595959]" />,
      });
    });

    // ── Unverified Documents ──
    deal.roleLinkedDocuments?.forEach(doc => {
      if (doc.verified) return;
      tasks.push({
        ...base,
        id: `doc-${deal.id}-${doc.id}`,
        label: `Verify ${doc.category} — ${doc.fileName}`,
        category: 'Documents',
        urgency: 'action',
        assignee: resolveAssignee(deal, 'document'),
        icon: <FileText className="w-3.5 h-3.5 text-[#7F7F7F]" />,
      });
    });

    // ── Active Offers (follow-up needed) ──
    deal.prospects?.forEach(prospect => {
      if (prospect.status !== 'Offer Sent') return;
      prospect.offerLetters?.forEach(letter => {
        if (letter.status !== 'Sent') return;
        const isExpired = new Date(letter.expiresDate) < new Date();
        tasks.push({
          ...base,
          id: `offer-${deal.id}-${letter.id}`,
          label: `Follow up: $${letter.offerAmount.toLocaleString()} offer to ${letter.recipientName}`,
          category: 'Offers',
          urgency: isExpired ? 'overdue' : 'upcoming',
          assignee: resolveAssignee(deal, 'offer'),
          icon: <AlertTriangle className="w-3.5 h-3.5 text-[#595959]" />,
        });
      });
    });
  });

  // Sort: overdue first, then action, then upcoming
  const urgencyOrder: Record<TaskUrgency, number> = { overdue: 0, action: 1, upcoming: 2 };
  tasks.sort((a, b) => urgencyOrder[a.urgency] - urgencyOrder[b.urgency]);

  return tasks;
}

/* ─── Urgency badge style ─── */
const URGENCY_STYLE: Record<TaskUrgency, string> = {
  overdue:  'bg-pw-black text-white shadow-sm',
  action:   'bg-bg-primary text-text-primary border border-border-accent/50 shadow-sm',
  upcoming: 'bg-bg-primary text-text-secondary border border-border-accent/20',
};

const URGENCY_LABEL: Record<TaskUrgency, string> = {
  overdue:  'Urgent',
  action:   'Ready',
  upcoming: 'Queued',
};

interface GlobalTodoEngineProps {
  projects: Project[];
  onNavigateToDeal: (projectId: string) => void;
}

export default function GlobalTodoEngine({ projects, onNavigateToDeal }: GlobalTodoEngineProps) {
  const [activeFilter, setActiveFilter] = useState<FilterTab>('all');
  const tasks = useMemo(() => aggregateTasks(projects), [projects]);

  const filtered = useMemo(() => {
    if (activeFilter === 'all') return tasks;
    return tasks.filter(t => t.urgency === activeFilter);
  }, [tasks, activeFilter]);

  const overdueCt = tasks.filter(t => t.urgency === 'overdue').length;
  const actionCt = tasks.filter(t => t.urgency === 'action').length;

  return (
    <div className="ag-card bg-bg-surface shadow-[0_30px_60px_rgba(0,0,0,0.02)] border border-border-accent/10 flex flex-col h-full min-h-[500px]">
      {/* Header */}
      <div className="px-8 py-10 flex items-center justify-between border-b border-border-accent/10">
          <div className="space-y-1">
            <div className="flex items-center gap-3">
              <CheckCircle2 className="w-5 h-5 text-text-primary" />
              <p className="ag-label opacity-60">Task Rollup</p>
            </div>
            <h3 className="text-3xl font-normal text-text-primary tracking-tighter">Action Engine</h3>
          </div>
          <div className="bg-bg-primary px-4 py-2 rounded-full border border-border-accent/50">
            <span className="text-[10px] font-bold text-text-primary tracking-widest uppercase">
              {tasks.length} Active Nodes
            </span>
          </div>
      </div>

      <div className="px-8 py-6">
        {/* Filter tabs */}
        <div className="flex gap-3">
          {[
            { key: 'all' as FilterTab, label: 'Full Stream', count: tasks.length },
            { key: 'overdue' as FilterTab, label: 'Urgent', count: overdueCt },
            { key: 'action' as FilterTab, label: 'Pending', count: actionCt },
          ].map(tab => (
            <button
              key={tab.key}
              onClick={() => setActiveFilter(tab.key)}
              className={`px-5 py-2 text-[10px] font-bold uppercase tracking-widest rounded-full border transition-all duration-300 ${
                activeFilter === tab.key
                  ? 'bg-pw-black text-pw-white border-pw-border shadow-lg shadow-pw-black/10'
                  : 'bg-bg-primary text-text-secondary border-border-accent/30 hover:border-pw-border hover:text-text-primary'
              }`}
            >
              {tab.label}
              {tab.count > 0 && (
                <span className={`ml-2 font-medium opacity-60 ${
                  activeFilter === tab.key ? 'text-pw-white' : 'text-text-primary'
                }`}>
                  {tab.count}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Task list */}
      <div className="flex-1 overflow-y-auto px-4 pb-8">
        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 text-text-secondary opacity-40">
            <Circle className="w-12 h-12 mb-4 stroke-[1px]" />
            <p className="text-sm font-medium">All tasks verified.</p>
          </div>
        ) : (
          <div className="space-y-2">
            {filtered.map(task => (
              <button
                key={task.id}
                onClick={() => onNavigateToDeal(task.projectId)}
                className="w-full flex items-center gap-6 px-4 py-6 text-left rounded-2xl hover:bg-bg-primary/50 transition-all duration-300 group border border-transparent hover:border-border-accent/10"
              >
                {/* Folder icon */}
                <div className="shrink-0 transition-transform group-hover:scale-110 duration-500">
                  <DealFolderIcon status={task.dealStatus} size={22} />
                </div>

                {/* Task content */}
                <div className="flex-1 min-w-0">
                  <p className="text-base font-medium text-text-primary tracking-tight group-hover:text-text-primary transition-colors">
                    {task.label}
                  </p>
                  <div className="flex items-center gap-4 mt-1.5">
                    <span className="text-xs text-text-secondary font-normal truncate opacity-60">
                      {task.dealAddress}
                    </span>
                    {task.assignee && (
                      <span className="flex items-center gap-1.5 text-xs text-text-secondary font-medium opacity-40 bg-bg-primary px-2 py-0.5 rounded-full">
                        <User2 className="w-3 h-3" />
                        {task.assignee}
                      </span>
                    )}
                  </div>
                </div>

                {/* Urgency badge */}
                <span className={`text-[10px] font-bold uppercase tracking-widest px-4 py-1.5 rounded-full flex-shrink-0 transition-all ${URGENCY_STYLE[task.urgency]}`}>
                  {URGENCY_LABEL[task.urgency]}
                </span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, {
  createContext,
  useContext,
  useState,
  useCallback,
  useEffect,
} from 'react';
import { motion, useMotionValue, animate, PanInfo, MotionValue } from 'framer-motion';
import toast from 'react-hot-toast';
import { PHASE_BACKGROUNDS } from '@/lib/constants/phaseMessages';

/* ═══════════════════════════════════════════════════════
   HorizontalPanelShell — Gesture-Driven Kanban Engine

   Architecture:
   1. PanelProvider — wraps the entire dashboard (layout level)
      to expose context to header, overlays, and bottom nav.
   2. PanelTrack — the draggable horizontal strip of lane panels.

   Features:
   • framer-motion drag for touch-responsive swipe navigation
   • Spring-physics panel snapping with velocity threshold
   • viewMode toggle: 'expanded' (full workspace) | 'minimized' (board)
   • Keyboard navigation (← →)
   ═══════════════════════════════════════════════════════ */

export interface LaneDef {
  id: string;
  label: string;
  shortLabel: string;
}

export type ViewMode = 'expanded' | 'minimized';

interface PanelContextValue {
  activeIndex: number;
  laneCount: number;
  scrollToPanel: (index: number) => void;
  lanes: LaneDef[];
  viewMode: ViewMode;
  toggleViewMode: () => void;
  setViewMode: (mode: ViewMode) => void;
  /** Lane IDs that are currently locked by the PhaseGate. */
  lockedLanes: Set<string>;
  setLockedLanes: (s: Set<string>) => void;
  /** Callback for when a locked lane is attempted — shows gate message. */
  onLockedLaneAttempt?: (laneId: string) => void;
  setOnLockedLaneAttempt: (fn: (laneId: string) => void) => void;
}

const PanelContext = createContext<PanelContextValue>({
  activeIndex: 0,
  laneCount: 0,
  scrollToPanel: () => {},
  lanes: [],
  viewMode: 'expanded',
  toggleViewMode: () => {},
  setViewMode: () => {},
  lockedLanes: new Set(),
  setLockedLanes: () => {},
  onLockedLaneAttempt: undefined,
  setOnLockedLaneAttempt: () => {},
});

export function usePanelContext() {
  return useContext(PanelContext);
}

/* ─── Gesture Config ─── */
const SWIPE_VELOCITY_THRESHOLD = 300;
const SWIPE_OFFSET_THRESHOLD = 80;

/* ═══════════════════════════════════════════
   PanelProvider — Context wrapper (layout level)
   ═══════════════════════════════════════════ */

interface PanelProviderProps {
  lanes: LaneDef[];
  initialLane?: number;
  children: React.ReactNode;
}

export function PanelProvider({
  lanes,
  initialLane = 0,
  children,
}: PanelProviderProps) {
  const [activeIndex, setActiveIndex] = useState(initialLane);
  const [viewMode, setViewMode] = useState<ViewMode>('expanded');
  const [containerWidth, setContainerWidth] = useState(
    typeof window !== 'undefined' ? window.innerWidth : 1440
  );
  const [lockedLanes, setLockedLanes] = useState<Set<string>>(new Set());
  const [onLockedLaneAttempt, setOnLockedLaneAttempt] = useState<((laneId: string) => void) | undefined>(undefined);

  useEffect(() => {
    const handleResize = () => setContainerWidth(window.innerWidth);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const x = useMotionValue(-(initialLane * containerWidth));

  const scrollToPanel = useCallback(
    (index: number) => {
      const clamped = Math.max(0, Math.min(index, lanes.length - 1));
      const targetLane = lanes[clamped];
      if (targetLane && lockedLanes.has(targetLane.id)) {
        onLockedLaneAttempt?.(targetLane.id);
        return;
      }
      setActiveIndex(clamped);
      animate(x, -(clamped * containerWidth), {
        type: 'spring',
        stiffness: 300,
        damping: 35,
        mass: 0.8,
      });
    },
    [x, containerWidth, lanes, lockedLanes, onLockedLaneAttempt]
  );

  const toggleViewMode = useCallback(() => {
    setViewMode((prev) => (prev === 'expanded' ? 'minimized' : 'expanded'));
  }, []);

  /* Keyboard navigation */
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const tag = (e.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT') return;

      if (e.key === 'ArrowRight') {
        e.preventDefault();
        scrollToPanel(activeIndex + 1);
      } else if (e.key === 'ArrowLeft') {
        e.preventDefault();
        scrollToPanel(activeIndex - 1);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeIndex, scrollToPanel]);

  /* Sync transform on resize */
  useEffect(() => {
    x.set(-(activeIndex * containerWidth));
  }, [containerWidth, activeIndex, x]);

  const setOnLockedLaneAttemptWrapped = useCallback((fn: (laneId: string) => void) => {
    setOnLockedLaneAttempt(() => fn);
  }, []);

  return (
    <PanelContext.Provider
      value={{
        activeIndex,
        laneCount: lanes.length,
        scrollToPanel,
        lanes,
        viewMode,
        toggleViewMode,
        setViewMode,
        lockedLanes,
        setLockedLanes,
        onLockedLaneAttempt,
        setOnLockedLaneAttempt: setOnLockedLaneAttemptWrapped,
      }}
    >
      {/* Store motion value reference for child PanelTrack */}
      <MotionXContext.Provider value={{ x, containerWidth, lanes }}>
        {children}
      </MotionXContext.Provider>
    </PanelContext.Provider>
  );
}

/* ─── Internal context for motion value ─── */
const MotionXContext = createContext<{
  x: MotionValue<number>;
  containerWidth: number;
  lanes: LaneDef[];
}>({
  x: null as any,
  containerWidth: 1440,
  lanes: [],
});

/* ═══════════════════════════════════════════
   PanelTrack — Draggable horizontal strip
   ═══════════════════════════════════════════ */

/**
 * Returns the correct header offset in px for the panel height calculation.
 * Desktop (≥1024px): only TopHeader (64px) — PhaseRailVertical is horizontal space.
 * Mobile / Tablet (<1024px): TopHeader (64) + PhaseNavRail horizontal bar (44).
 */
function useResponsiveHeaderHeight(): number {
  const [height, setHeight] = useState(() => {
    if (typeof window === 'undefined') return 108;
    return window.innerWidth >= 1024 ? 64 : 108;
  });

  useEffect(() => {
    const update = () => setHeight(window.innerWidth >= 1024 ? 64 : 108);
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);

  return height;
}

interface PanelTrackProps {
  /** @deprecated Pass nothing — PanelTrack computes this responsively. */
  headerHeight?: number;
  children: React.ReactNode[];
}

export function PanelTrack({ children }: PanelTrackProps) {
  const { activeIndex, scrollToPanel, lanes } = usePanelContext();
  const { x, containerWidth } = useContext(MotionXContext);
  const headerHeight = useResponsiveHeaderHeight();

  const handleDragEnd = useCallback(
    (_: any, info: PanInfo) => {
      const velocity = info.velocity.x;
      const offset = info.offset.x;
      let nextIndex = activeIndex;

      if (Math.abs(velocity) > SWIPE_VELOCITY_THRESHOLD) {
        nextIndex = velocity < 0
          ? Math.min(activeIndex + 1, lanes.length - 1)
          : Math.max(activeIndex - 1, 0);
      } else if (Math.abs(offset) > SWIPE_OFFSET_THRESHOLD) {
        nextIndex = offset < 0
          ? Math.min(activeIndex + 1, lanes.length - 1)
          : Math.max(activeIndex - 1, 0);
      }
      scrollToPanel(nextIndex);
    },
    [activeIndex, lanes.length, scrollToPanel]
  );

  const panelHeight = `calc(100vh - ${headerHeight}px)`;

  const activeLaneId = lanes[activeIndex]?.id;
  const laneBackground = PHASE_BACKGROUNDS[activeLaneId ?? ''] ?? 'var(--pw-bg)';

  return (
    <div
      className="lane-shell"
      style={{
        height: panelHeight,
        overflow: 'hidden',
        position: 'relative',
        touchAction: 'pan-y',
        backgroundColor: laneBackground,
        transition: 'background-color 400ms ease',
      }}
    >
      <motion.div
        className="lane-track"
        style={{
          display: 'flex',
          width: lanes.length * containerWidth,
          height: '100%',
          x,
          cursor: 'grab',
        }}
        drag="x"
        dragConstraints={{
          left: -((lanes.length - 1) * containerWidth),
          right: 0,
        }}
        dragElastic={0.1}
        dragMomentum={false}
        onDragEnd={handleDragEnd}
      >
        {React.Children.map(children, (child, i) => (
          <section
            key={lanes[i]?.id || i}
            className="lane-panel"
            style={{ 
              height: '100%', 
              width: containerWidth, 
              flexShrink: 0,
              overflowY: 'auto', 
              overflowX: 'hidden' 
            }}
            data-lane={lanes[i]?.id}
            aria-label={lanes[i]?.label}
          >
            {child}
          </section>
        ))}
      </motion.div>

      {/* Swipe edge affordances */}
      {activeIndex > 0 && (
        <div className="swipe-hint swipe-hint-left" aria-hidden="true" />
      )}
      {activeIndex < lanes.length - 1 && (
        <div className="swipe-hint swipe-hint-right" aria-hidden="true" />
      )}
    </div>
  );
}

/* ─── Legacy default export for backward compat ─── */
export default function HorizontalPanelShell({
  lanes,
  initialLane = 0,
  headerHeight = 64,
  children,
}: {
  lanes: LaneDef[];
  initialLane?: number;
  headerHeight?: number;
  children: React.ReactNode[];
}) {
  return (
    <PanelProvider lanes={lanes} initialLane={initialLane}>
      <PanelTrack headerHeight={headerHeight}>
        {children}
      </PanelTrack>
    </PanelProvider>
  );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, UserPlus, Mail, Shield, ChevronRight, Check, AlertCircle, Loader2 } from 'lucide-react';
import { useProjectStore } from '@/store/projectStore';
import { useAuth } from '@/context/AuthContext';

type Role = 'OWNER' | 'PARTNER' | 'ANALYST' | 'VIEWER';

interface InvestorInviteModalProps {
  isOpen: boolean;
  onClose: () => void;
  projectId?: string;
  propertyName?: string;
}

export default function InvestorInviteModal({ isOpen, onClose, projectId, propertyName }: InvestorInviteModalProps) {
  const { user } = useAuth();
  const projects = useProjectStore(state => state.projects);
  const [email, setEmail] = useState('');
  const [role, setRole] = useState<Role>('VIEWER');
  const [selectedProjectId, setSelectedProjectId] = useState(projectId ?? '');
  const [isSent, setIsSent] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const effectiveProjectId = projectId ?? selectedProjectId;

  const handleSend = async () => {
    if (!email || !effectiveProjectId) return;
    setIsLoading(true);
    setError(null);
    try {
      const headers: Record<string, string> = { 'Content-Type': 'application/json' };
      if (user) {
        const token = await user.getIdToken();
        headers['Authorization'] = `Bearer ${token}`;
      }
      const res = await fetch(`/api/reil/projects/${effectiveProjectId}/invite`, {
        method: 'POST',
        headers,
        body: JSON.stringify({ email: email.trim(), role }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || `Request failed (${res.status})`);
      }
      setIsSent(true);
      setTimeout(() => {
        onClose();
        setIsSent(false);
        setEmail('');
        setRole('VIEWER');
        setSelectedProjectId('');
        setError(null);
      }, 2000);
    } catch (err: any) {
      setError(err.message || 'Failed to send invitation. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/80 backdrop-blur-sm"
          />

          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
