export default function KPIGrid() {
  const { activeTenantId } = useTenant();
  const { loading: authLoading } = useAuth();
  const projects = useProjectStore((s) => s.projects);
  const projectsSynced = useProjectStore((s) => s.projectsSynced);

  const isLoading =
    authLoading || (!!activeTenantId && activeTenantId !== 'org_placeholder' && !projectsSynced);
  const isEmpty = projectsSynced && projects.length === 0;

  if (isLoading) {
    return (
      <section
        aria-label="Portfolio performance metrics loading"
        className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-5"
      >
        <KPICardSkeleton />
        <KPICardSkeleton />
        <KPICardSkeleton />
      </section>
    );
  }

  if (isEmpty) {
    return (
      <section aria-label="Portfolio performance metrics" className="grid grid-cols-1 gap-4 sm:gap-5 font-sans">
        <EmptyState
          title="No portfolio data yet"
          description="Add your first project to start tracking realized profit, ROI, and closed deals."
          action={{
            label: "Create First Project",
            href: "/dashboard/projects/new",
          }}
          icon={<FolderOpen className="w-6 h-6" />}
          variant="default"
        />
      </section>
    );
  }

  const summary = calculatePortfolioSummary(projects);
  const totalNetProfit = summary.avgGrossProfit * summary.soldCount;

  const formattedProfit =
    totalNetProfit !== 0 ? `$${Math.round(totalNetProfit).toLocaleString()}` : '$0';
  const formattedROI = summary.avgROI !== 0 ? `${summary.avgROI.toFixed(1)}%` : '0%';
  const profitTrend =
    summary.soldCount > 0 && totalNetProfit > 0
      ? `+${summary.avgROI.toFixed(1)}%`
      : totalNetProfit < 0
        ? `${summary.avgROI.toFixed(1)}%`
        : '—';

  return (
    <section
      aria-label="Portfolio performance metrics"
      className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4 sm:gap-5"
    >
      <KPICard
        title="Total Net Realized Profit"
        value={formattedProfit}
        trend={profitTrend}
        icon={<DollarSign className="w-4 h-4" />}
      />
      <KPICard
        title="Average Portfolio ROI"
        value={formattedROI}
        trend="—"
        icon={<TrendingUp className="w-4 h-4" />}
      />
      <KPICard
        title="Closed Deal Count"
        value={summary.soldCount.toString()}
        trend="—"
        icon={<FolderOpen className="w-4 h-4" />}
      />
    </section>
  );
}

