/* ═══════════════════════════════════════════════════════
   Market Heat Map Widget

   A high-tech visualization of market velocity and demand.
   Uses Antigravity dark aesthetics (obsidian panels, 
   tactical glows, mathematical typography).
   ═══════════════════════════════════════════════════════ */

export default function MarketHeatMap() {
  const projects = useProjectStore(state => state.projects);

  // Derive "Heat" metrics from existing projects
  const heatData = useMemo(() => {
    const total = projects.length;
    if (total === 0) return { velocity: 0, demand: 0, liquidity: 0 };

    const active = projects.filter(d => d.status === 'hold' || d.status === 'fund').length;
    const sold = projects.filter(d => d.status === 'exit').length;

    // Abstracted calculation for "Market Temperature"
    const velocity = (sold / total) * 100;
    const demand = (active / total) * 100;
    const liquidity = ((sold + active) / total) * 100;

    return { velocity, demand, liquidity };
  }, [projects]);

  const sectors = [
    { name: 'Absorption Rate', value: heatData.velocity, icon: Activity, label: 'Velocity Drift' },
    { name: 'Buyer Inertia', value: heatData.demand, icon: Flame, label: 'Demand Vector' },
    { name: 'Capital Velocity', value: heatData.liquidity, icon: TrendingUp, label: 'Liquidity Sync' },
  ];

  return (
    <div className="ag-card bg-bg-surface shadow-[0_30px_60px_rgba(0,0,0,0.02)] border border-border-accent/10 flex flex-col h-full min-h-[500px]">
      <div className="px-8 py-10 flex items-center justify-between border-b border-border-accent/10">
          <div className="space-y-1">
            <p className="ag-label opacity-60">Market Telemetry</p>
            <h3 className="text-3xl font-normal text-text-primary tracking-tighter">Heat Vectors</h3>
          </div>
          <div className="flex gap-2">
            {[...Array(3)].map((_, i) => (
              <div key={i} className="w-1.5 h-1.5 rounded-full bg-pw-black/10"></div>
            ))}
          </div>
      </div>

      <div className="flex-1 px-8 py-10 space-y-12">
         {sectors.map((sector) => (
           <div key={sector.name} className="relative group/sector">
              <div className="flex items-end justify-between mb-4">
                 <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-full bg-bg-primary flex items-center justify-center text-text-secondary group-hover/sector:bg-pw-black group-hover/sector:text-pw-white transition-all duration-500">
                      <sector.icon className="w-4 h-4" />
                    </div>
                    <div>
                      <p className="text-base font-medium text-text-primary tracking-tight">{sector.name}</p>
                      <p className="text-[10px] font-bold text-text-secondary uppercase tracking-widest opacity-40">{sector.label}</p>
                    </div>
                 </div>
                 <div className="text-right">
                    <span className="text-2xl font-normal text-text-primary tracking-tighter">
                      {sector.value.toFixed(1)}%
                    </span>
                 </div>
              </div>

              {/* Minimalist Progress Bar */}
              <div className="h-1.5 w-full bg-bg-primary rounded-full overflow-hidden">
                 <div 
                    className="h-full bg-pw-black transition-all duration-1000 ease-in-out"
                    style={{ width: `${Math.max(15, sector.value)}%` }}
                 />
              </div>

              <div className="mt-3 flex justify-between">
                <p className="text-[9px] font-bold text-text-secondary uppercase tracking-[0.1em] opacity-30 italic">
                  Index Normalized: {(sector.value / 1.42).toFixed(2)}
                </p>
                <p className="text-[9px] font-bold text-text-primary uppercase tracking-[0.1em] opacity-80">
                  Status: Optimal
                </p>
              </div>
           </div>
         ))}
      </div>

      {/* Aggregate Heat Index */}
      <div className="p-10 bg-bg-primary/30 border-t border-border-accent/10 flex items-center justify-between mt-auto">
         <div className="flex items-center gap-5">
            <div className="w-12 h-12 rounded-full bg-bg-surface border border-border-accent/20 flex items-center justify-center shadow-sm">
               <Wind className="w-5 h-5 text-text-primary" />
            </div>
            <div>
               <p className="ag-label opacity-40 mb-1">Global Fluidity</p>
               <p className="text-xl font-medium text-text-primary tracking-tighter">Equilibrium_0.82</p>
            </div>
         </div>

         <div className="text-right">
            <p className="text-[10px] font-bold text-text-secondary uppercase tracking-[0.2em] opacity-40 mb-1">Alpha Signal</p>
            <div className="flex items-center gap-2">
               <div className="w-2 h-2 rounded-full bg-pw-black animate-pulse"></div>
               <span className="text-sm font-bold text-text-primary tracking-wider uppercase">Live</span>
            </div>
         </div>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Project } from '@/types/schema';
import { usePanelContext, LaneDef } from './HorizontalPanelShell';
import {
  Search, FileSignature, HardHat, LogOut, Building2,
  X,
} from 'lucide-react';
import DealFolder from './DealFolder';
import { usePermissions } from '@/hooks/usePermissions';
import toast from 'react-hot-toast';
import { EmptyState } from '../ui/empty-states/EmptyState';

/* ═══════════════════════════════════════════════════════
   MinimizedDashboardView — Board Overlay

   Full-screen bird's-eye overlay showing all property projects
   distributed across the 5 Kanban phase columns.

   • Desktop: 5-column grid (one per phase)
   • Mobile:  vertically-stacked accordion columns
   • Tapping a deal → expanded mode at the relevant lane
   ═══════════════════════════════════════════════════════ */

interface MinimizedDashboardViewProps {
  projects: Project[];
  onSelectDeal: (projectId: string) => void;
}

/* ─── Map deal status → lane index ─── */
function statusToLaneIndex(status: string): number {
  switch (status) {
    case 'Lead':             return 0; // Pipeline
    case 'Under Contract':   return 1; // Evaluation
    case 'Renovating':       return 2; // Closing
    case 'Listed':           return 3; // Engine
    case 'Sold':             return 4; // Exit
    default:                 return 0;
  }
}

function getPhaseIcon(status: string) {
  switch (status) {
    case 'Lead':           return <Search className="w-3.5 h-3.5" />;
    case 'Under Contract': return <FileSignature className="w-3.5 h-3.5" />;
    case 'Renovating':     return <HardHat className="w-3.5 h-3.5" />;
    case 'Listed':         return <LogOut className="w-3.5 h-3.5" />;
    case 'Sold':           return <LogOut className="w-3.5 h-3.5 text-[#595959]" />;
    default:               return <Building2 className="w-3.5 h-3.5" />;
  }
}

/* ─── Phase accent colors for column headers ───
   Monochromatic ramp: Dashboard → Phase 1 → Phase 2 → Phase 3 → Phase 4 */
const PHASE_ACCENTS = [
  'bg-dashboard text-phase-4 border-phase-1',     // Pipeline  (#f2f2f2)
  'bg-phase-1 text-phase-4 border-phase-2',       // Evaluation (#cccccc)
  'bg-phase-2 text-white border-phase-3',          // Closing   (#a5a5a5)
  'bg-phase-3 text-white border-phase-4',          // Engine    (#7f7f7f)
  'bg-phase-4 text-white border-phase-4',          // Exit      (#595959)
];

export default function MinimizedDashboardView({ projects, onSelectDeal }: MinimizedDashboardViewProps) {
  const { lanes, scrollToPanel, setViewMode } = usePanelContext();

  /* Bucket projects into lanes */
  const buckets: Project[][] = lanes.map(() => []);
  projects.forEach((deal) => {
    const idx = statusToLaneIndex(deal.status);
    buckets[idx].push(deal);
  });

  const handleDealClick = (deal: Project) => {
    const laneIdx = statusToLaneIndex(deal.status);
    scrollToPanel(laneIdx);
    setViewMode('expanded');
    onSelectDeal(deal.id);
  };

  const handleClose = () => {
    setViewMode('expanded');
  };

  return (
    <motion.div
      className="board-overlay pt-20 px-4 sm:px-6 lg:px-8 pb-8"
      initial={{ opacity: 0, scale: 0.97 }}
      animate={{ opacity: 1, scale: 1 }}
      exit={{ opacity: 0, scale: 0.97 }}
      transition={{ duration: 0.25, ease: 'easeOut' }}
    >
      {/* Header */}
      <div className="max-w-7xl mx-auto mb-6 flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-normal tracking-tight text-text-primary">Board View</h2>
          <p className="text-sm text-text-secondary mt-0.5">
            All {projects.length} deal{projects.length !== 1 ? 's' : ''} across your workflow
          </p>
        </div>
        <button
          onClick={handleClose}
          className="p-2 rounded-lg hover:bg-[#F2F2F2] text-text-secondary hover:text-text-primary transition"
          aria-label="Close board view"
        >
          <X className="w-5 h-5" />
        </button>
      </div>

      {/* ── Desktop: 5-column grid ── */}
      <div className="hidden md:grid max-w-7xl mx-auto grid-cols-5 gap-3">
        {lanes.map((lane, colIdx) => (
          <BoardColumn
            key={lane.id}
            lane={lane}
            projects={buckets[colIdx]}
            accent={PHASE_ACCENTS[colIdx]}
            onDealClick={handleDealClick}
          />
        ))}
      </div>

      {/* ── Mobile: stacked accordion ── */}
      <div className="md:hidden max-w-lg mx-auto space-y-3">
        {lanes.map((lane, colIdx) => (
          <MobileColumn
            key={lane.id}
            lane={lane}
            projects={buckets[colIdx]}
            accent={PHASE_ACCENTS[colIdx]}
            onDealClick={handleDealClick}
          />
        ))}
      </div>
    </motion.div>
  );
}

/* ─── Desktop Column ─── */
function BoardColumn({
  lane,
  projects,
  accent,
  onDealClick,
}: {
  lane: LaneDef;
  projects: Project[];
  accent: string;
  onDealClick: (deal: Project) => void;
}) {
  return (
    <div className="flex flex-col rounded-xl border border-border-accent bg-bg-surface overflow-hidden">
      {/* Column header */}
      <div className={`px-4 py-3 border-b ${accent}`}>
        <div className="flex items-center justify-between">
          <span className="text-sm font-bold uppercase tracking-widest">
            {lane.shortLabel}
          </span>
          <span className="text-xs font-mono bg-bg-surface/60 px-2 py-0.5 rounded-full">
            {projects.length}
          </span>
        </div>
      </div>

      {/* Deal cards */}
      <div className="flex-1 p-2.5 space-y-2 min-h-[120px] max-h-[calc(100vh-280px)] overflow-y-auto">
        {projects.length === 0 ? (
          <EmptyState
            title="No projects"
            variant="inline"
            className="py-6"
          />
        ) : (
          projects.map((deal) => (
            <DealCard key={deal.id} deal={deal} onClick={() => onDealClick(deal)} />
          ))
        )}
      </div>
    </div>
  );
}

/* ─── Mobile Accordion Column ─── */
function MobileColumn({
  lane,
  projects,
  accent,
  onDealClick,
}: {
  lane: LaneDef;
  projects: Project[];
  accent: string;
  onDealClick: (deal: Project) => void;
}) {
  const [isOpen, setIsOpen] = React.useState(projects.length > 0);

  return (
    <div className="rounded-xl border border-border-accent bg-bg-surface overflow-hidden">
      <button
        onClick={() => setIsOpen(!isOpen)}
        className={`w-full px-4 py-3 flex items-center justify-between text-left border-b ${accent}`}
      >
        <span className="text-sm font-bold uppercase tracking-widest">
          {lane.label}
        </span>
        <div className="flex items-center gap-2">
          <span className="text-xs font-mono bg-bg-surface/60 px-2 py-0.5 rounded-full">
            {projects.length}
          </span>
          <motion.div
            animate={{ rotate: isOpen ? 90 : 0 }}
            transition={{ duration: 0.2 }}
            className="text-current"
          >
            ›
          </motion.div>
        </div>
      </button>

      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.25, ease: 'easeInOut' }}
            className="overflow-hidden"
          >
            <div className="p-3 space-y-2">
              {projects.length === 0 ? (
                <EmptyState
                  title="No projects in this phase"
                  variant="inline"
                  className="py-3"
                />
              ) : (
                projects.map((deal) => (
                  <DealCard key={deal.id} deal={deal} onClick={() => onDealClick(deal)} />
                ))
              )}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

/* ─── Deal Card (delegates to standardized DealFolder) ─── */
function DealCard({ deal, onClick }: { deal: Project; onClick: () => void }) {
  const { can } = usePermissions();

  return (
    <div className={`${!can('projects.view') && 'opacity-60 cursor-not-allowed'}`}>
      <DealFolder
        deal={deal}
        size="sm"
        showPrice
        onClick={() => {
          if (can('projects.view')) {
            onClick();
          } else {
            toast.error('You do not have permission to view this project folder.');
          }
        }}
      />
    </div>
  );
}

