'use client';

import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Lock } from 'lucide-react';
import { usePanelContext } from './HorizontalPanelShell';
import { PHASE_MESSAGES, PHASE_IS_DARK } from '@/lib/constants/phaseMessages';

const STORAGE_KEY = 'pw_phase_banner_dismissed';

function getDismissedSet(): Set<string> {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? new Set(JSON.parse(raw)) : new Set();
  } catch {
    return new Set();
  }
}

function dismissLane(laneId: string) {
  try {
    const set = getDismissedSet();
    set.add(laneId);
    localStorage.setItem(STORAGE_KEY, JSON.stringify([...set]));
  } catch {
    // ignore
  }
}

export default function PhaseContextBanner() {
  const { lanes, activeIndex, lockedLanes } = usePanelContext();
  const activeLane = lanes[activeIndex];
  const [dismissed, setDismissed] = useState<Set<string>>(new Set());

  useEffect(() => {
    setDismissed(getDismissedSet());
  }, []);

  if (!activeLane) return null;

  const laneId = activeLane.id;
  const message = PHASE_MESSAGES[laneId];
  const isDark = PHASE_IS_DARK[laneId] ?? false;
  const isLocked = lockedLanes.has(laneId);
  const isDismissed = dismissed.has(laneId);

  if (!message || isDismissed) return null;

  const textColor = isDark ? 'rgba(255,255,255,0.75)' : 'var(--text-secondary)';
  const borderColor = isDark ? 'rgba(255,255,255,0.12)' : 'var(--border-ui)';
  const dismissColor = isDark ? 'rgba(255,255,255,0.5)' : 'var(--text-secondary)';

  function handleDismiss() {
    dismissLane(laneId);
    setDismissed((prev) => new Set([...prev, laneId]));
  }

  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={laneId}
        initial={{ opacity: 0, y: -6 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: -6 }}
        transition={{ duration: 0.2, ease: 'easeOut' }}
        style={{
          borderBottom: `1px solid ${borderColor}`,
          height: 36,
          flexShrink: 0,
        }}
        className="flex items-center gap-3 px-6"
      >
        {isLocked && (
          <Lock className="w-3 h-3 shrink-0" style={{ color: textColor }} aria-hidden />
        )}
        <p
          className="flex-1 text-[11px] font-medium truncate"
          style={{ color: textColor, letterSpacing: '0.01em' }}
        >
          {message}
        </p>
        <button
          onClick={handleDismiss}
          className="shrink-0 p-0.5 rounded transition-opacity hover:opacity-100 opacity-60"
          aria-label="Dismiss phase message"
        >
          <X className="w-3 h-3" style={{ color: dismissColor }} />
        </button>
      </motion.div>
    </AnimatePresence>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Project } from '@/types/schema';
import { DealFolderIcon } from './DealFolder';
import {
  AlertCircle, AlertTriangle, Info,
  DollarSign, Clock, FileWarning, Users, Receipt, ArrowRight,
} from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   ProjectGroomingAlerts — Logic-Based Deal Health Monitor

   Scans all active projects against a ruleset and emits alerts
   for projects that need attention ("grooming"). Each alert maps
   to a specific corrective action and links to the deal.

   Rules:
     🔴 Critical   — Missing financials, incomplete closing docs
     🟠 Action     — Pending receipts, budget overruns
     🟡 Warning    — Stale phases, no team assigned, unverified docs
   ═══════════════════════════════════════════════════════════════ */

type AlertSeverity = 'critical' | 'action' | 'warning';

interface GroomingAlert {
  id: string;
  projectId: string;
  dealAddress: string;
  dealStatus: string;
  title: string;
  description: string;
  severity: AlertSeverity;
  icon: React.ReactNode;
}

function shortAddress(address: string): string {
  const comma = address.indexOf(',');
  return comma > 0 ? address.slice(0, comma) : address;
}

/**
 * Core grooming rules — each rule scans a deal and may push alerts.
 */
function evaluateDeal(deal: Project, alerts: GroomingAlert[]): void {
  const addr = shortAddress(deal.address || deal.propertyName);
  const base = { projectId: deal.id, dealAddress: addr, dealStatus: deal.status };

  // ── Rule 1: Missing Financials ──────────────────────────
  // Purchase price is 0 and the deal has moved past Lead
  if (
    (!deal.financials?.purchasePrice || deal.financials.purchasePrice === 0) &&
    deal.status !== 'acquisition'
  ) {
    alerts.push({
      ...base,
      id: `groom-fin-${deal.id}`,
      title: 'Missing Purchase Price',
      description: `${addr} has no purchase price set. Financial projections cannot calculate.`,
      severity: 'critical',
      icon: <DollarSign className="w-4 h-4" />,
    });
  }

  // ── Rule 2: Stale Phase ─────────────────────────────────
  // Deal hasn't been updated in 14+ days
  const now = new Date();
  const updatedAt = deal.updatedAt ? new Date(deal.updatedAt) : new Date(deal.createdAt || now);
  const daysSinceUpdate = Math.floor((now.getTime() - updatedAt.getTime()) / (1000 * 60 * 60 * 24));
  if (daysSinceUpdate >= 14 && deal.status !== 'exit') {
    alerts.push({
      ...base,
      id: `groom-stale-${deal.id}`,
      title: 'Stale — No Activity',
      description: `${addr} hasn't been updated in ${daysSinceUpdate} days. Is this project still active?`,
      severity: 'warning',
      icon: <Clock className="w-4 h-4" />,
    });
  }

  // ── Rule 3: Incomplete Closing Docs ─────────────────────
  // Status is Under Contract but closing checklist has uncompleted items
  if (deal.status === 'fund') {
    const uncompleted = deal.closingChecklist?.filter(i => !i.completed)?.length || 0;
    if (uncompleted > 0) {
      alerts.push({
        ...base,
        id: `groom-closing-${deal.id}`,
        title: 'Closing Docs Incomplete',
        description: `${uncompleted} closing checklist item${uncompleted > 1 ? 's' : ''} still incomplete.`,
        severity: 'critical',
        icon: <FileWarning className="w-4 h-4" />,
      });
    }
  }

  // ── Rule 4: Unverified Documents ────────────────────────
  const unverifiedDocs = deal.roleLinkedDocuments?.filter(d => !d.verified)?.length || 0;
  if (unverifiedDocs > 0) {
    alerts.push({
      ...base,
      id: `groom-docs-${deal.id}`,
      title: 'Unverified Documents',
      description: `${unverifiedDocs} document${unverifiedDocs > 1 ? 's' : ''} awaiting verification.`,
      severity: 'warning',
      icon: <FileWarning className="w-4 h-4" />,
    });
  }

  // ── Rule 5: Budget Overrun ──────────────────────────────
  // Approved costs exceed 90% of the rehab base budget
  if (deal.rehab?.baseBudget && deal.rehab.baseBudget > 0) {
    const approvedSum = deal.financials?.costs
      ?.filter(c => c.approved)
      .reduce((sum, c) => sum + c.amount, 0) || 0;
    const utilization = approvedSum / deal.rehab.baseBudget;
    if (utilization >= 0.9) {
      alerts.push({
        ...base,
        id: `groom-budget-${deal.id}`,
        title: 'Budget Overrun Risk',
        description: `Rehab spending at ${Math.round(utilization * 100)}% of the $${deal.rehab.baseBudget.toLocaleString()} base budget.`,
        severity: 'critical',
        icon: <DollarSign className="w-4 h-4" />,
      });
    }
  }

  // ── Rule 6: No Team Assigned ────────────────────────────
  if ((!deal.projectTeam || deal.projectTeam.length === 0) && deal.status !== 'acquisition') {
    alerts.push({
      ...base,
      id: `groom-team-${deal.id}`,
      title: 'No Team Assigned',
      description: `${addr} has no team members. Assign roles for accountability.`,
      severity: 'warning',
      icon: <Users className="w-4 h-4" />,
    });
  }

  // ── Rule 7: Pending Receipts ────────────────────────────
  const pendingReceipts = deal.rehab?.pendingReceipts?.filter(r => r.status === 'pending')?.length || 0;
  if (pendingReceipts > 0) {
    alerts.push({
      ...base,
      id: `groom-receipts-${deal.id}`,
      title: 'Pending Receipt Triage',
      description: `${pendingReceipts} receipt${pendingReceipts > 1 ? 's' : ''} queued for review.`,
      severity: 'action',
      icon: <Receipt className="w-4 h-4" />,
    });
  }
}

/* ─── Severity styling ─── */
const SEVERITY_CONFIG: Record<AlertSeverity, { border: string; bg: string; text: string; dot: string; label: string }> = {
  critical: { border: 'border-pw-border', bg: 'bg-pw-black text-white', text: 'text-white', dot: 'bg-bg-surface', label: 'Priority' },
  action:   { border: 'border-border-accent/50', bg: 'bg-bg-primary text-text-primary', text: 'text-text-primary', dot: 'bg-pw-black', label: 'Required' },
  warning:  { border: 'border-border-accent/20', bg: 'bg-bg-primary/50 text-text-secondary', text: 'text-text-secondary', dot: 'bg-pw-muted', label: 'Monitor' },
};

interface ProjectGroomingAlertsProps {
  projects: Project[];
  onNavigateToDeal: (projectId: string) => void;
}

export default function ProjectGroomingAlerts({ projects, onNavigateToDeal }: ProjectGroomingAlertsProps) {
  const alerts = useMemo(() => {
    const collected: GroomingAlert[] = [];
    projects.forEach(d => evaluateDeal(d, collected));
    const order: Record<AlertSeverity, number> = { critical: 0, action: 1, warning: 2 };
    collected.sort((a, b) => order[a.severity] - order[b.severity]);
    return collected;
  }, [projects]);

  const criticalCt = alerts.filter(a => a.severity === 'critical').length;

  return (
    <div className="ag-card bg-bg-surface shadow-[0_30px_60px_rgba(0,0,0,0.02)] border border-border-accent/10 flex flex-col h-full min-h-[500px]">
      {/* Header */}
      <div className="px-8 py-10 flex items-center justify-between border-b border-border-accent/10">
          <div className="space-y-1">
            <div className="flex items-center gap-3">
              <AlertCircle className="w-5 h-5 text-text-primary" />
              <p className="ag-label opacity-60">Deal Hygiene</p>
            </div>
            <h3 className="text-3xl font-normal text-text-primary tracking-tighter">Grooming Portal</h3>
          </div>
          {criticalCt > 0 && (
            <div className="bg-pw-black px-4 py-2 rounded-full flex items-center gap-2">
              <span className="w-1.5 h-1.5 rounded-full bg-bg-surface animate-pulse" />
              <span className="text-[10px] font-bold text-white tracking-widest uppercase">
                {criticalCt} Critical
              </span>
            </div>
          )}
      </div>

      <div className="px-8 py-5 border-b border-border-accent/10 bg-bg-primary/20">
        <p className="text-[10px] font-bold text-text-secondary/60 uppercase tracking-[0.2em] leading-none">
          {alerts.length === 0 ? 'System State: Optimal' : `${alerts.length} Anomalies Resolved`}
        </p>
      </div>

      {/* Alerts list */}
      <div className="flex-1 overflow-y-auto px-6 py-8 space-y-4">
        {alerts.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-24 text-text-secondary opacity-40">
            <Info className="w-12 h-12 mb-4 stroke-[1px]" />
            <p className="text-sm font-medium">Protocol Nominal.</p>
          </div>
        ) : (
          alerts.map(alert => {
            const sev = SEVERITY_CONFIG[alert.severity];
            return (
              <button
                key={alert.id}
                onClick={() => onNavigateToDeal(alert.projectId)}
                className={`w-full flex items-start gap-6 p-6 rounded-3xl border transition-all duration-300 group hover:scale-[1.01] hover:shadow-lg shadow-pw-black/5 ${sev.border} ${alert.severity === 'critical' ? 'bg-pw-black text-white' : 'bg-bg-surface'}`}
              >
                {/* Severity icon */}
                <div className={`shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-all duration-500 ${alert.severity === 'critical' ? 'bg-bg-surface/10 text-white' : 'bg-bg-primary text-text-primary group-hover:bg-pw-black group-hover:text-white'}`}>
                  {alert.icon}
                </div>

                {/* Alert content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-3 mb-2">
                    <span className={`text-[9px] font-bold uppercase tracking-[0.2em] px-3 py-1 rounded-full border ${alert.severity === 'critical' ? 'border-white/20 text-white' : 'border-border-accent/50 text-text-secondary'}`}>
                      {sev.label}
                    </span>
                    <span className={`text-[10px] font-medium uppercase tracking-widest truncate opacity-40`}>
                      {alert.dealAddress}
                    </span>
                  </div>
                  <p className={`text-lg font-medium tracking-tight leading-tight`}>
                    {alert.title}
                  </p>
                  <p className={`text-xs mt-2 font-normal leading-relaxed opacity-60 line-clamp-2`}>
                    {alert.description}
                  </p>
                </div>

                <div className="shrink-0 opacity-0 group-hover:opacity-40 transition-opacity self-center">
                   <ArrowRight className="w-5 h-5" />
                </div>
              </button>
            );
          })
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { useAuth } from '@/context/AuthContext';
import {
  ArrowDownCircle,
  ArrowUpCircle,
  ArrowLeftRight,
  CreditCard,
  RefreshCw,
  AlertTriangle,
  Search,
  Landmark,
} from 'lucide-react';

export type TransactionBucket = 'REVENUE' | 'EXPENSE' | 'LIABILITY' | 'TRANSFER';

interface LedgerTransaction {
  id: string;
  plaidId: string;
  date: string;
  name: string;
  merchantName: string | null;
  amount: number; // cents
  reiCategory: string | null;
  bucket?: TransactionBucket;
  projectId: string | null;
  confidence: number | null;
  pending: boolean;
}

const BUCKET_CONFIG: Record<TransactionBucket, { label: string; color: string; bg: string; icon: React.FC<{ className?: string }> }> = {
  REVENUE:   { label: 'Revenue',   color: 'text-emerald-700', bg: 'bg-emerald-50 border-emerald-200',  icon: ArrowDownCircle },
  EXPENSE:   { label: 'Expense',   color: 'text-rose-700',    bg: 'bg-rose-50 border-rose-200',        icon: ArrowUpCircle },
  LIABILITY: { label: 'Liability', color: 'text-violet-700',  bg: 'bg-violet-50 border-violet-200',    icon: CreditCard },
  TRANSFER:  { label: 'Transfer',  color: 'text-slate-600',   bg: 'bg-slate-100 border-slate-200',     icon: ArrowLeftRight },
};

const CATEGORY_TO_BUCKET: Record<string, TransactionBucket> = {
  rental_income: 'REVENUE',
  late_fees: 'REVENUE',
  pet_rent: 'REVENUE',
  parking: 'REVENUE',
  application_fees: 'REVENUE',
  laundry_vending: 'REVENUE',
  misc_income: 'REVENUE',
  debt_service: 'LIABILITY',
  escrow: 'LIABILITY',
  security_deposit: 'TRANSFER',
  owner_draw: 'TRANSFER',
  capex_reserve: 'TRANSFER',
  bank_transfer: 'TRANSFER',
};

function getBucket(reiCategory: string | null): TransactionBucket {
  if (!reiCategory || reiCategory === 'unknown') return 'EXPENSE';
  return CATEGORY_TO_BUCKET[reiCategory] ?? 'EXPENSE';
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(Math.abs(cents) / 100);
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

function humanCategory(cat: string | null): string {
  if (!cat || cat === 'unknown') return 'Uncategorized';
  return cat.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase());
}

interface TransactionLedgerProps {
  /** Optional: limit to transactions for a specific project */
  projectId?: string;
  /** Max rows to display */
  limit?: number;
  className?: string;
}

/**
 * TransactionLedger
 *
 * Displays Plaid-synced transactions with 4-bucket badges and confidence scores.
 * Rows are fetched from GET /api/transactions.
 */
export function TransactionLedger({ projectId, limit = 50, className = '' }: TransactionLedgerProps) {
  const { user } = useAuth();
  const [transactions, setTransactions] = useState<LedgerTransaction[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState('');
  const [bucketFilter, setBucketFilter] = useState<TransactionBucket | 'ALL'>('ALL');

  const fetchTransactions = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    setError(null);
    try {
      const idToken = await user.getIdToken();
      const params = new URLSearchParams({ limit: String(limit) });
      if (projectId) params.set('projectId', projectId);
      const res = await fetch(`/api/transactions?${params}`, {
        headers: { Authorization: `Bearer ${idToken}` },
      });
      const data = await res.json();
      if (!data.success) throw new Error(data.error ?? 'Failed to load transactions');
      setTransactions(data.transactions ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load transactions');
    } finally {
      setLoading(false);
    }
  }, [user, projectId, limit]);

  useEffect(() => { fetchTransactions(); }, [fetchTransactions]);

  const filtered = transactions
    .filter((t) => {
      const bucket = getBucket(t.reiCategory);
      if (bucketFilter !== 'ALL' && bucket !== bucketFilter) return false;
      if (search) {
        const s = search.toLowerCase();
        return (
          t.name.toLowerCase().includes(s) ||
          (t.merchantName ?? '').toLowerCase().includes(s) ||
          (t.reiCategory ?? '').toLowerCase().includes(s)
        );
      }
      return true;
    });

  return (
    <div className={`bg-white border border-slate-100 rounded-xl shadow-sm overflow-hidden ${className}`}>
      {/* Header */}
      <div className="flex items-center justify-between px-5 py-4 border-b border-slate-100">
        <div className="flex items-center gap-2.5">
          <div className="w-7 h-7 rounded-lg bg-slate-50 border border-slate-100 flex items-center justify-center">
            <Landmark className="w-3.5 h-3.5 text-slate-500" />
          </div>
          <h3 className="text-sm font-bold text-slate-900">Transaction Ledger</h3>
        </div>
        <button
          onClick={fetchTransactions}
          className="w-7 h-7 rounded-lg hover:bg-slate-100 flex items-center justify-center text-slate-400 transition-colors"
          title="Refresh"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {/* Filters */}
