/* ─── Main Component ─── */

interface VelocityOverheadKPIProps {
  projects: Project[];
}

export default function VelocityOverheadKPI({ projects }: VelocityOverheadKPIProps) {
  const kpis = useMemo(() => computeKPIs(projects), [projects]);

  const ttfStyle = TTF_STYLE[ttfBand(kpis.avgTTF)];

  // Variance direction indicator
  const varianceIcon = kpis.constructionVariance > 0
    ? <TrendingUp className="w-4 h-4 text-text-primary opacity-30" />
    : kpis.constructionVariance < 0
      ? <TrendingDown className="w-4 h-4 text-text-primary opacity-30" />
      : <Minus className="w-4 h-4 text-text-secondary opacity-30" />;

  return (
    <section className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-8">
      {/* ── 1. Average Cycle Time ── */}
      <KPICard
        icon={<Timer className="w-5 h-5" />}
        label="Avg. Time to Exit"
        value={kpis.avgTTF !== null ? `${kpis.avgTTF}d` : '—'}
        subtext={`Based on ${kpis.ttfDeals} completed deals`}
        accent="text-text-primary"
        badge={
          kpis.avgTTF !== null && (
            <div className={`w-2.5 h-2.5 rounded-full ${ttfBand(kpis.avgTTF) === 'green' ? 'bg-pw-black' : ttfBand(kpis.avgTTF) === 'yellow' ? 'bg-pw-muted' : 'border border-pw-border'}`}></div>
          )
        }
      />

      {/* ── 2. Operational Burn ── */}
      <KPICard
        icon={<Flame className="w-5 h-5" />}
        label="Monthly Overhead"
        value={kpis.monthlyOverhead > 0 ? `$${Math.round(kpis.monthlyOverhead).toLocaleString()}` : '$0'}
        subtext="Recurring fixed costs across portfolio"
        accent="text-text-primary"
      />

      {/* ── 3. CapEx Variance ── */}
      <KPICard
        icon={<BarChart3 className="w-5 h-5" />}
        label="Rehab Budget Variance"
        value={kpis.varianceDeals > 0
          ? `${kpis.constructionVariance >= 0 ? '+' : ''}${kpis.constructionVariance.toFixed(1)}%`
          : '—'}
        subtext={`Tracking ${kpis.varianceDeals} active rehab budgets`}
        accent={
          kpis.constructionVariance > 10 ? 'text-text-primary font-medium'
          : 'text-text-primary'
        }
        badge={kpis.varianceDeals > 0 ? varianceIcon : undefined}
      />

      {/* ── 4. Capital Efficiency ── */}
      <KPICard
        icon={<Percent className="w-5 h-5" />}
        label="Cash-on-Cash Return"
        value={kpis.cocDeals > 0 ? `${kpis.cashOnCash.toFixed(1)}%` : '—'}
        subtext="Annualized return on invested capital"
        accent="text-text-primary"
      />

      {/* ── 5. Portfolio Fluidity ── */}
      <KPICard
        icon={<Eye className="w-5 h-5" />}
        label="Pipeline Ratio"
        value={`${Math.round(kpis.activePct)}:${Math.round(kpis.pendingSalePct)}`}
        subtext={`$${Math.round(kpis.totalPortfolioValue / 1000)}k total portfolio value`}
        badge={
          <div className="flex h-1.5 w-16 bg-bg-primary rounded-full overflow-hidden border border-border-accent/20">
            <div
              className="bg-pw-black transition-all duration-1000"
              style={{ width: `${kpis.activePct}%` }}
            />
            <div
              className="bg-pw-muted transition-all duration-1000 opacity-40"
              style={{ width: `${kpis.pendingSalePct}%` }}
            />
          </div>
        }
      />
    </section>
  );
}

