      grossRentalIncome: 0,
      otherIncome: 0,
      vacancyLoss: 0,
      propertyTaxes: 0,
      insurance: 0,
      utilities: 0,
      propertyManagement: 0,
      maintenance: 0,
      hoa: 0,
      totalOperatingExpenses: 0,
      noi: 0,
