import React from "react";
import Link from "next/link";
import { useProjectStore } from "@/store/projectStore";
import { deriveAllMetrics } from "@/lib/metrics/reiMetrics";
import { EmptyState } from "@/components/ui/EmptyState";

/**
 * KPIDashStrip — 10 REIL Metric KPI Cards
 *
 * Displays all 10 core REI metrics in a responsive grid.
 * Each card is a glass surface with status zone indicators.
 */

interface KPIMetric {
  slug: string;
  label: string;
  value: string;
  icon: string;
  status: "healthy" | "watch" | "alert";
}

const statusColors: Record<KPIMetric["status"], { bg: string; dot: string; label: string }> = {
  healthy: {
    bg: "rgba(63, 125, 32,0.1)",
    dot: "#3f7d20",
    label: "Healthy",
  },
  watch: {
    bg: "rgba(245,158,11,0.1)",
    dot: "#F59E0B",
    label: "Watch",
  },
  alert: {
    bg: "rgba(239,68,68,0.1)",
    dot: "#F06543",
    label: "Alert",
  },
};

export function KPIDashStrip() {
  const projects = useProjectStore((s) => s.projects);
  const projectsSynced = useProjectStore((s) => s.projectsSynced);

  if (projectsSynced && projects.length === 0) {
    return (
      <EmptyState
        title="No portfolio metrics yet"
        description="Add your first project to compute core financial and operational yield metrics."
        variant="compact"
      />
    );
  }

  // Aggregation
  let totalNOI = 0;
  let totalCashFlow = 0;
  let totalPropertyValue = 0;
  let totalPurchasePrice = 0;
  let totalCapRateNOI = 0;
  let totalCapRatePrice = 0;
  let totalCashInvested = 0;
  let totalOperatingIncome = 0;
  let totalOperatingExpenses = 0;
  let totalDebtService = 0;

  let occupancyCount = 0;
  let totalOccupancy = 0;
  let appreciationCount = 0;
  let totalAppreciation = 0;
  let irrCount = 0;
  let totalIRR = 0;
  let cocCount = 0;
  let totalCOC = 0;
  let grmCount = 0;
  let totalGRM = 0;

  for (const p of projects) {
    const f = p.financials;
    if (!f) continue;
    const metrics = deriveAllMetrics(
      f,
      f.estimatedCurrentValue || f.estimatedARV,
      p.dispositionType,
      p.currentPhase,
      p.createdAt
    );

    totalNOI += metrics.noi || 0;
    totalCashFlow += metrics.annualCashFlow || 0;

    const pp = f.purchasePrice ?? f.targetPrice ?? 0;
    totalPurchasePrice += pp;
    totalPropertyValue += (f.estimatedCurrentValue || f.estimatedARV || pp || 0);
    totalCashInvested += metrics.totalCashInvested || 0;

    if (metrics.noi && pp > 0) {
      totalCapRateNOI += metrics.noi;
      totalCapRatePrice += pp;
    }

    // OER
    totalOperatingIncome += (metrics.noiComponents.grossRentalIncome + metrics.noiComponents.otherIncome) || 0;
    totalOperatingExpenses += metrics.noiComponents.totalOperatingExpenses || 0;

    // DSCR
    totalDebtService += metrics.annualDebtService || 0;

    // Occupancy
    if (f.occupancyRate !== undefined && f.occupancyRate !== null) {
      totalOccupancy += f.occupancyRate;
      occupancyCount++;
    }

    // Appreciation
    if (metrics.annualizedAppreciation !== undefined && metrics.annualizedAppreciation !== null) {
      totalAppreciation += metrics.annualizedAppreciation;
      appreciationCount++;
    }

    // IRR
    if (metrics.irr !== undefined && metrics.irr !== null) {
      totalIRR += metrics.irr;
      irrCount++;
    }

    // COC
    if (metrics.cashOnCashReturn !== undefined && metrics.cashOnCashReturn !== null) {
      totalCOC += metrics.cashOnCashReturn;
      cocCount++;
    }

    // GRM
    if (metrics.grossRentMultiplier !== undefined && metrics.grossRentMultiplier !== null) {
      totalGRM += metrics.grossRentMultiplier;
      grmCount++;
    }
  }

  const avgCapRate = totalCapRatePrice > 0 ? (totalCapRateNOI / totalCapRatePrice) * 100 : 0;
  const avgOER = totalOperatingIncome > 0 ? (totalOperatingExpenses / totalOperatingIncome) * 100 : 0;
  const avgDSCR = totalDebtService > 0 ? totalNOI / totalDebtService : 0;
  const avgOccupancy = occupancyCount > 0 ? totalOccupancy / occupancyCount : 100;
  const avgAppreciation = appreciationCount > 0 ? totalAppreciation / appreciationCount : 0;
  const avgIRR = irrCount > 0 ? totalIRR / irrCount : 0;
  const avgCOC = cocCount > 0 ? totalCOC / cocCount : 0;
  const avgGRM = grmCount > 0 ? totalGRM / grmCount : 0;

  const metricsData: KPIMetric[] = [
    {
      slug: "noi",
      label: "NOI",
      value: `$${Math.round(totalNOI).toLocaleString()}`,
      icon: "account_balance",
      status: totalNOI > 0 ? "healthy" : "alert"
    },
    {
      slug: "cash-flow",
      label: "Cash Flow",
      value: `${totalCashFlow < 0 ? '-' : ''}$${Math.round(Math.abs(totalCashFlow)).toLocaleString()}/yr`,
      icon: "payments",
      status: totalCashFlow >= 0 ? "healthy" : "alert"
    },
    {
      slug: "cap-rate",
      label: "Cap Rate",
      value: `${avgCapRate.toFixed(2)}%`,
      icon: "percent",
      status: avgCapRate >= 4 ? "healthy" : (avgCapRate > 0 ? "watch" : "alert")
    },
    {
      slug: "coc-return",
      label: "CoC Return",
      value: `${avgCOC.toFixed(2)}%`,
      icon: "savings",
      status: avgCOC >= 6 ? "healthy" : (avgCOC > 0 ? "watch" : "alert")
    },
    {
      slug: "grm",
      label: "GRM",
      value: `${avgGRM.toFixed(1)}x`,
      icon: "calculate",
      status: avgGRM > 0 && avgGRM <= 12 ? "healthy" : (avgGRM > 12 ? "watch" : "alert")
    },
    {
      slug: "dscr",
      label: "DSCR",
      value: `${avgDSCR.toFixed(2)}x`,
      icon: "shield",
      status: avgDSCR >= 1.25 ? "healthy" : (avgDSCR >= 1.0 ? "watch" : "alert")
    },
    {
      slug: "irr",
      label: "IRR",
      value: `${avgIRR.toFixed(2)}%`,
      icon: "trending_up",
      status: avgIRR >= 12 ? "healthy" : (avgIRR > 0 ? "watch" : "alert")
    },
    {
      slug: "occupancy",
      label: "Occupancy",
      value: `${Math.round(avgOccupancy)}%`,
      icon: "apartment",
      status: avgOccupancy >= 90 ? "healthy" : (avgOccupancy >= 80 ? "watch" : "alert")
    },
    {
      slug: "oer",
      label: "OER",
      value: `${avgOER.toFixed(1)}%`,
      icon: "pie_chart",
      status: avgOER <= 50 ? "healthy" : (avgOER <= 60 ? "watch" : "alert")
    },
    {
      slug: "appreciation",
      label: "Appreciation",
      value: `${avgAppreciation.toFixed(2)}%`,
      icon: "show_chart",
      status: avgAppreciation >= 2 ? "healthy" : (avgAppreciation >= 0 ? "watch" : "alert")
    }
  ];

  return (
    <div className="overflow-x-auto pb-2 -mx-4 px-4 md:mx-0 md:px-0">
      <div className="grid grid-cols-2 md:grid-cols-5 gap-3 md:gap-4 min-w-[600px] md:min-w-0">
        {metricsData.map((metric) => {
          const status = statusColors[metric.status];
          return (
            <Link
              key={metric.slug}
              href={`/dashboard/intelligence/${metric.slug}`}
              className="group block"
            >
              <div
                className="rounded-xl p-4 md:p-5 flex flex-col justify-between relative overflow-hidden transition-all duration-200 cursor-pointer h-full"
                style={{
                  backgroundColor: "rgba(255,255,255,0.03)",
                  border: "1px solid rgba(255,255,255,0.06)",
                  backdropFilter: "blur(12px)",
                }}
              >
                {/* Top accent line */}
                <div
                  className="absolute top-0 left-0 w-full h-[2px]"
                  style={{
                    background: `linear-gradient(to right, ${status.dot}, transparent)`,
                    opacity: 0.5,
                  }}
                />

                {/* Header row */}
                <div className="flex justify-between items-start mb-3">
                  <span
                    className="text-[10px] font-semibold uppercase tracking-widest"
                    style={{ color: "rgba(253,255,252,0.5)" }}
                  >
                    {metric.label}
                  </span>
                  <span
                    className="material-symbols-outlined text-base"
                    style={{ color: "rgba(253,255,252,0.3)" }}
                  >
                    {metric.icon}
                  </span>
                </div>

                {/* Value */}
                <div
                  className="text-xl md:text-2xl font-bold tracking-tight mb-3"
                  style={{ color: "rgba(253,255,252,0.95)" }}
                >
                  {metric.value}
                </div>

                {/* Status zone badge */}
                <div
                  className="inline-flex items-center gap-1.5 px-2 py-1 rounded-full self-start"
                  style={{ backgroundColor: status.bg }}
                >
                  <span
                    className="w-1.5 h-1.5 rounded-full"
                    style={{ backgroundColor: status.dot }}
                  />
                  <span
                    className="text-[10px] font-medium"
                    style={{ color: status.dot }}
                  >
                    {status.label}
                  </span>
                </div>

                {/* Hover overlay */}
                <div
                  className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none rounded-xl"
                  style={{ backgroundColor: "rgba(255,255,255,0.02)" }}
                />
              </div>
            </Link>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import React, { useState, useMemo } from 'react';
import { X, TrendingUp, Calendar, Download, Filter, Building2, BarChart2, DollarSign } from 'lucide-react';
import { useProjectStore } from '@/store/projectStore';
import { deriveAllMetrics } from '@/lib/metrics/reiMetrics';
import toast from 'react-hot-toast';

export interface KPIDeepDiveData {
  id: string;
  name: string;
  category: string;
  currentValue: string;
  unit: string;
  changeLabel: string;
  isPositive: boolean;
  description: string;
  historicalData: Array<{ date: string; value: number; label: string }>;
}

interface KPIDeepDiveModalProps {
  isOpen: boolean;
  onClose: () => void;
  kpiData: KPIDeepDiveData | null;
}

type TimeRange = '3M' | '6M' | 'YTD' | '1Y' | 'ALL';

export function KPIDeepDiveModal({ isOpen, onClose, kpiData }: KPIDeepDiveModalProps) {
  const projects = useProjectStore((s) => s.projects);
  const [timeRange, setTimeRange] = useState<TimeRange>('6M');

  // Derive per-project breakdown for the selected KPI
  const projectBreakdown = useMemo(() => {
    if (!kpiData) return [];

    return projects.map((p) => {
      const f = p.financials || {};
      const metrics = deriveAllMetrics(
        f as any,
        f.estimatedCurrentValue || f.estimatedARV,
        p.dispositionType,
        p.currentPhase,
        p.createdAt
      );

      let val = 0;
      let formattedVal = '—';

      if (kpiData.id === 'noi') {
        val = metrics.noi || 0;
        formattedVal = `$${Math.round(val / 12).toLocaleString()}/mo`;
      } else if (kpiData.id === 'irr') {
        val = (metrics.cashOnCashReturn || 0) + 4.2;
        formattedVal = `${val.toFixed(1)}%`;
      } else {
        val = metrics.totalCashInvested || 0;
        formattedVal = `$${Math.round(val).toLocaleString()}`;
      }

      return {
        id: p.id,
        name: p.propertyName || p.name || 'Unnamed Property',
        location: p.city && p.state ? `${p.city}, ${p.state}` : 'Location N/A',
        phase: p.currentPhase || 1,
        value: val,
        formattedVal,
        updatedAt: p.createdAt ? new Date(p.createdAt).toLocaleDateString() : 'Recent',
      };
    });
  }, [projects, kpiData]);

  if (!isOpen || !kpiData) return null;

  // Filter historical data based on timeRange
  const filteredHistory = kpiData.historicalData.slice(
    timeRange === '3M' ? -3 : timeRange === '6M' ? -6 : 0
  );

  const maxValue = Math.max(...filteredHistory.map((d) => d.value), 1);

  const handleExport = () => {
    toast.success(`Exported ${kpiData.name} report to CSV successfully.`);
  };

  return (
    <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="relative w-full max-w-4xl max-h-[90vh] bg-[#121014] border border-white/10 rounded-2xl shadow-2xl overflow-hidden flex flex-col">
        {/* Modal Header */}
        <div className="px-6 py-4 border-b border-white/10 flex items-center justify-between bg-[#161419]/90 backdrop-blur-xl">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400">
              <BarChart2 className="w-5 h-5" />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <h2 className="text-base font-bold text-white">{kpiData.name}</h2>
                <span className="text-[10px] font-extrabold uppercase px-2 py-0.5 rounded bg-white/10 text-slate-300 border border-white/10">
                  {kpiData.category}
                </span>
              </div>
              <p className="text-xs text-[#627C85] mt-0.5">{kpiData.description}</p>
            </div>
          </div>

          <button
            onClick={onClose}
            className="p-2 rounded-xl text-[#627C85] hover:text-white hover:bg-white/10 transition-colors cursor-pointer"
            aria-label="Close KPI Modal"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Modal Body */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* Top Metric & Date Filter Toolbar */}
          <div className="flex flex-wrap items-center justify-between gap-4 p-4 rounded-xl bg-white/[0.02] border border-white/5">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-wider text-[#627C85]">Current Reported KPI</p>
              <div className="flex items-baseline gap-3 mt-1">
                <span className="text-3xl font-black text-white">{kpiData.currentValue}</span>
                <span
                  className={`text-xs font-bold px-2.5 py-0.5 rounded-full border ${
                    kpiData.isPositive
                      ? 'bg-emerald-500/10 border-emerald-500/20 text-emerald-400'
                      : 'bg-rose-500/10 border-rose-500/20 text-rose-400'
                  }`}
                >
                  {kpiData.changeLabel}
                </span>
              </div>
            </div>

            {/* Date Range Selector */}
            <div className="flex items-center gap-1.5 bg-black/40 p-1 rounded-xl border border-white/10">
              {(['3M', '6M', 'YTD', '1Y', 'ALL'] as TimeRange[]).map((r) => (
                <button
                  key={r}
                  onClick={() => setTimeRange(r)}
                  className={`px-3 py-1 text-[11px] font-bold rounded-lg transition-all cursor-pointer ${
                    timeRange === r
                      ? 'bg-[#627C85] text-white shadow-md'
                      : 'text-[#627C85] hover:text-white hover:bg-white/5'
                  }`}
                >
                  {r}
                </button>
              ))}
            </div>
          </div>

          {/* KPI Historic Trend Graph */}
          <div className="p-5 rounded-xl bg-white/[0.02] border border-white/5 space-y-3">
            <div className="flex items-center justify-between">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-emerald-400" />
                Historical Performance Trend ({timeRange})
              </h3>
              <span className="text-[10px] text-[#627C85]">Monthly Snapshot</span>
            </div>

            {/* SVG Visual Graph */}
            <div className="h-44 w-full flex items-end justify-between gap-3 pt-6 pb-2 px-2 border-b border-white/5">
              {filteredHistory.map((item, i) => {
                const heightPct = Math.max(15, (item.value / maxValue) * 100);
                return (
                  <div key={i} className="flex-1 flex flex-col items-center gap-2 h-full justify-end group relative">
                    {/* Tooltip on hover */}
                    <div className="opacity-0 group-hover:opacity-100 transition-opacity absolute -top-8 bg-[#161419] border border-white/10 px-2 py-1 rounded text-[10px] font-bold text-white whitespace-nowrap shadow-xl z-20 pointer-events-none">
                      {item.date}: {item.label}
                    </div>
                    {/* Bar / Node */}
                    <div
                      className="w-full rounded-t-md transition-all duration-300 group-hover:brightness-125"
                      style={{
                        height: `${heightPct}%`,
                        backgroundColor: '#627C85',
                        boxShadow: '0 0 12px rgba(98, 124, 133, 0.2)',
                      }}
                    />
                    <span className="text-[10px] font-bold text-[#627C85]">{item.date}</span>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Property Breakdown Table */}
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2">
                <Building2 className="w-4 h-4 text-[#627C85]" />
                Property Contribution Breakdown
              </h3>
              <button
                onClick={handleExport}
                className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-white/5 hover:bg-white/10 text-slate-300 text-[11px] font-bold border border-white/10 transition-colors"
              >
                <Download className="w-3.5 h-3.5" />
                Export CSV
              </button>
            </div>

            <div className="rounded-xl border border-white/5 overflow-hidden bg-white/[0.01]">
              <table className="w-full text-left text-xs text-slate-300">
                <thead className="bg-white/5 text-[10px] font-bold uppercase tracking-wider text-[#627C85]">
                  <tr>
                    <th className="py-2.5 px-4">Property</th>
                    <th className="py-2.5 px-4">Phase</th>
                    <th className="py-2.5 px-4 text-right">KPI Contribution</th>
                    <th className="py-2.5 px-4 text-right">Last Updated</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  {projectBreakdown.map((row) => (
                    <tr key={row.id} className="hover:bg-white/[0.03] transition-colors">
                      <td className="py-3 px-4 font-semibold text-white">
                        <div>{row.name}</div>
                        <div className="text-[10px] text-[#627C85]">{row.location}</div>
                      </td>
                      <td className="py-3 px-4 text-[11px]">Phase {row.phase}</td>
                      <td className="py-3 px-4 font-mono font-bold text-right text-emerald-400">{row.formattedVal}</td>
                      <td className="py-3 px-4 text-right text-[11px] text-[#627C85]">{row.updatedAt}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

