function calculatePhaseCompletion(status: string | undefined): number {
  if (!status) return 0;
  switch (status.toLowerCase()) {
    case 'lead': return 25;
    case 'under contract': return 50;
    case 'renovating': return 75;
    case 'listed': return 90;
    case 'sold': return 100;
    default: return 0;
  }
}

