import React, { useMemo, useState } from 'react';
import { Project } from '@/types/schema';
import { DealFolderIcon } from '../DealFolder';
import {
  CheckCircle2, Circle, Clock, User2,
  AlertTriangle, FileText, Receipt, ClipboardCheck,
  Filter,
} from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   GlobalTodoWidget — Compact To-Do for Dashboard Home Sidebar

   Reuses task aggregation logic from GlobalTodoEngine but with:
   • "My Tasks" vs "Team Tasks" toggle
   • Compact sidebar format with due dates
   ═══════════════════════════════════════════════════════════════ */

type TaskUrgency = 'overdue' | 'action' | 'upcoming';
type OwnerFilter = 'mine' | 'team';

interface TodoTask {
  id: string;
  projectId: string;
  dealAddress: string;
  dealStatus: string;
  label: string;
  category: string;
  urgency: TaskUrgency;
  assignee: string | null;
  dueDate: string | null;
  icon: React.ReactNode;
}

function shortAddress(address: string): string {
  const comma = address.indexOf(',');
  return comma > 0 ? address.slice(0, comma) : address;
}

function resolveAssignee(deal: Project, taskType: string): string | null {
  if (deal.projectTeam?.length) {
    const roleMap: Record<string, string[]> = {
      'rehab':     ['General Contractor'],
      'receipt':   ['General Contractor'],
      'closing':   ['Closing Agent', 'Title Company/Escrow Officer'],
      'document':  ['Loan Officer/Broker', 'Appraiser', 'Title Company/Escrow Officer'],
      'offer':     ['Real Estate Agent'],
    };
    const targetRoles = roleMap[taskType] || [];
    for (const role of targetRoles) {
      const member = deal.projectTeam.find(
        (m: { projectRole: string; status: string }) => m.projectRole === role && m.status === 'active'
      );
      if (member) return member.displayName;
    }
  }
  if (deal.members) {
    const ownerEntry = Object.values(deal.members).find(m => m.role === 'Lead Investor');
    if (ownerEntry) return 'Lead Investor';
  }
  return null;
}

function aggregateTodos(projects: Project[]): TodoTask[] {
  const tasks: TodoTask[] = [];

  projects.forEach(deal => {
    const addr = shortAddress(deal.address || deal.propertyName);
    const base = { projectId: deal.id, dealAddress: addr, dealStatus: deal.status };

    // Rehab Tasks
    deal.financials?.rehabTasks?.forEach(task => {
      if (task.status === 'Complete') return;
      tasks.push({
        ...base,
        id: `rehab-${deal.id}-${task.id}`,
        label: `${task.title} — ${task.category}`,
        category: 'Rehab',
        urgency: task.status === 'In Progress' ? 'action' : 'upcoming',
        assignee: resolveAssignee(deal, 'rehab'),
        dueDate: null,
        icon: <ClipboardCheck className="w-3.5 h-3.5 text-[#7F7F7F]" />,
      });
    });

    // Closing Checklist
    deal.closingChecklist?.forEach(item => {
      if (item.completed) return;
      tasks.push({
        ...base,
        id: `closing-${deal.id}-${item.id}`,
        label: item.type,
        category: 'Closing',
        urgency: deal.status === 'fund' ? 'overdue' : 'action',
        assignee: resolveAssignee(deal, 'closing'),
        dueDate: null,
        icon: <FileText className="w-3.5 h-3.5 text-[#7F7F7F]" />,
      });
    });

    // Pending Receipts
    deal.rehab?.pendingReceipts?.forEach(receipt => {
      if (receipt.status !== 'pending') return;
      tasks.push({
        ...base,
        id: `receipt-${deal.id}-${receipt.id}`,
        label: `Review $${receipt.amount.toLocaleString()} — ${receipt.budgetLineItem}`,
        category: 'Triage',
        urgency: 'action',
        assignee: resolveAssignee(deal, 'receipt'),
        dueDate: null,
        icon: <Receipt className="w-3.5 h-3.5 text-[#7F7F7F]" />,
      });
    });

    // Unverified Docs
    deal.roleLinkedDocuments?.forEach(doc => {
      if (doc.verified) return;
      tasks.push({
        ...base,
        id: `doc-${deal.id}-${doc.id}`,
        label: `Verify ${doc.category}`,
        category: 'Documents',
        urgency: 'action',
        assignee: resolveAssignee(deal, 'document'),
        dueDate: null,
        icon: <FileText className="w-3.5 h-3.5 text-[#7F7F7F]" />,
      });
    });

    // Active Offers
    deal.prospects?.forEach(prospect => {
      if (prospect.status !== 'Offer Sent') return;
      prospect.offerLetters?.forEach(letter => {
        if (letter.status !== 'Sent') return;
        const isExpired = new Date(letter.expiresDate) < new Date();
        tasks.push({
          ...base,
          id: `offer-${deal.id}-${letter.id}`,
          label: `Follow up: $${letter.offerAmount.toLocaleString()} → ${letter.recipientName}`,
          category: 'Offers',
          urgency: isExpired ? 'overdue' : 'upcoming',
          assignee: resolveAssignee(deal, 'offer'),
          dueDate: new Date(letter.expiresDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
          icon: <AlertTriangle className="w-3.5 h-3.5 text-[#7F7F7F]" />,
        });
      });
    });
  });

  const urgencyOrder: Record<TaskUrgency, number> = { overdue: 0, action: 1, upcoming: 2 };
  tasks.sort((a, b) => urgencyOrder[a.urgency] - urgencyOrder[b.urgency]);
  return tasks;
}

const URGENCY_DOT: Record<TaskUrgency, string> = {
  overdue:  'bg-[#1A1A1A]',
  action:   'bg-[#7F7F7F]',
  upcoming: 'bg-[#CCCCCC]',
};

interface GlobalTodoWidgetProps {
  projects: Project[];
  onNavigateToDeal: (projectId: string) => void;
}

export default function GlobalTodoWidget({ projects, onNavigateToDeal }: GlobalTodoWidgetProps) {
  const [ownerFilter, setOwnerFilter] = useState<OwnerFilter>('mine');
  const tasks = useMemo(() => aggregateTodos(projects), [projects]);

  // "Mine" = tasks with assignee being Lead Investor, "Team" = all
  const filtered = useMemo(() => {
    if (ownerFilter === 'mine') {
      return tasks.filter(t => t.assignee === 'Lead Investor' || !t.assignee);
    }
    return tasks;
  }, [tasks, ownerFilter]);

  return (
    <div className="ag-card bg-[#FFFFFF] border border-[#CCCCCC]/10 shadow-[0_15px_30px_rgba(0,0,0,0.02)] flex flex-col">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-md bg-[#F2F2F2] flex items-center justify-center">
            <CheckCircle2 className="w-5 h-5 text-[#A5A5A5]" />
          </div>
          <div>
            <p className="ag-label opacity-60">Tasks</p>
            <h3 className="text-2xl font-normal text-[#1A1A1A] tracking-tighter">To-Do</h3>
          </div>
        </div>
        <div className="bg-[#F2F2F2] px-3 py-1.5 rounded border border-[#CCCCCC]/30">
          <span className="text-[10px] font-bold text-[#1A1A1A] tracking-widest uppercase">
            {filtered.length} items
          </span>
        </div>
      </div>

      {/* Filter Toggle */}
      <div className="flex gap-2 mb-4">
        {([
          { key: 'mine' as OwnerFilter, label: 'My Tasks' },
          { key: 'team' as OwnerFilter, label: 'Team Tasks' },
        ]).map(tab => (
          <button
            key={tab.key}
            onClick={() => setOwnerFilter(tab.key)}
            className={`flex-1 py-2 text-[10px] font-bold uppercase tracking-widest rounded border transition-all duration-300 ${
              ownerFilter === tab.key
                ? 'bg-[#1A1A1A] text-[#FFFFFF] border-[#1A1A1A]'
                : 'bg-[#F2F2F2] text-[#A5A5A5] border-[#CCCCCC]/30 hover:border-[#1A1A1A] hover:text-[#1A1A1A]'
            }`}
          >
            {tab.label}
          </button>
        ))}
      </div>

      {/* Task List */}
      <div className="flex-1 overflow-y-auto max-h-[400px] space-y-1.5">
        {filtered.length === 0 ? (
          <div className="flex flex-col items-center justify-center py-16 text-[#A5A5A5] opacity-30">
            <Circle className="w-10 h-10 mb-3 stroke-1" />
            <p className="text-xs font-medium">All clear</p>
          </div>
        ) : (
          filtered.slice(0, 12).map(task => (
            <button
              key={task.id}
              onClick={() => onNavigateToDeal(task.projectId)}
              className="w-full flex items-center gap-3 px-3 py-3 text-left rounded-md hover:bg-[#F2F2F2]/60 transition-all duration-200 group border border-transparent hover:border-[#CCCCCC]/10"
            >
              <div className={`w-2 h-2 rounded-full flex-shrink-0 ${URGENCY_DOT[task.urgency]}`} />
              <div className="flex-shrink-0 opacity-60 group-hover:opacity-100 transition-opacity">
                <DealFolderIcon status={task.dealStatus} size={16} />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-[#1A1A1A] tracking-tight truncate">{task.label}</p>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-[10px] text-[#7F7F7F] opacity-50 truncate">{task.dealAddress}</span>
                  {task.assignee && (
                    <span className="flex items-center gap-1 text-[10px] text-[#7F7F7F] opacity-30">
                      <User2 className="w-2.5 h-2.5" /> {task.assignee}
                    </span>
                  )}
                </div>
              </div>
              {task.dueDate && (
                <span className="text-[10px] text-[#7F7F7F] opacity-40 flex-shrink-0 flex items-center gap-1">
                  <Clock className="w-3 h-3" /> {task.dueDate}
                </span>
              )}
            </button>
          ))
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Project } from '@/types/schema';
import { Wallet, ArrowRight, TrendingUp } from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   HoldingCostTicker — Financial Drain Sentinel

   Tracks the non-productive capital leakage per active deal.
   Includes taxes, insurance, utilities, and debt service.
   Aesthetics: Structured list items, high-contrast values, 
   and clean status indicators.
   ═══════════════════════════════════════════════════════════════ */

interface DealHoldingCost {
  id: string;
  address: string;
  monthlyTotal: number;
  dailyRate: number;
  daysHeld: number;
  projectedRemainingCost: number;
  breakdown: { label: string; amount: number }[];
}

function shortAddress(addr: string): string {
  if (!addr) return 'Unnamed Property';
  const comma = addr.indexOf(',');
  return comma > 0 ? addr.slice(0, comma) : addr;
}

function computeHoldingCosts(projects: Project[], maxDOM: number): DealHoldingCost[] {
  const now = new Date();

  return projects
    .filter(d => d.status === 'fund' || d.status === 'hold')
    .map(deal => {
      const baseDate = deal.financials?.listingDate
        ? new Date(deal.financials.listingDate)
        : new Date(deal.createdAt);
      const daysHeld = Math.max(1, Math.floor((now.getTime() - baseDate.getTime()) / (1000 * 60 * 60 * 24)));

      let monthlyTotal = 0;
      const breakdown: { label: string; amount: number }[] = [];

      if (deal.holdingCosts && Array.isArray(deal.holdingCosts)) {
        deal.holdingCosts.forEach(hc => {
          const amt = hc.monthlyAmount || 0;
          monthlyTotal += amt;
          breakdown.push({ label: hc.type || 'Other', amount: amt });
        });
      }

      // Fallback: estimate from deal costs if no explicit holding costs
      if (monthlyTotal === 0 && deal.financials?.costs) {
        deal.financials.costs
          .filter(c => c.approved)
          .forEach(c => {
            const monthly = c.amount / Math.max(1, 6); // rough monthly estimate
            monthlyTotal += monthly;
            breakdown.push({ label: c.description || c.category || 'Holding', amount: monthly });
          });
      }

      const dailyRate = monthlyTotal / 30;
      const daysRemaining = Math.max(0, maxDOM - daysHeld);
      const projectedRemainingCost = dailyRate * daysRemaining;

      return {
        id: deal.id,
        address: shortAddress(deal.address || deal.propertyName),
        monthlyTotal,
        dailyRate,
        daysHeld,
        projectedRemainingCost,
        breakdown,
      };
    })
    .filter(d => d.monthlyTotal > 0)
    .sort((a, b) => b.monthlyTotal - a.monthlyTotal);
}

function formatCurrency(val: number): string {
  if (val < 1) return '—';
  return `$${Math.round(val).toLocaleString()}`;
}

interface HoldingCostTickerProps {
  projects: Project[];
  maxDOM?: number;
}

export default function HoldingCostTicker({ projects, maxDOM = 160 }: HoldingCostTickerProps) {
  const deals = useMemo(() => computeHoldingCosts(projects, maxDOM), [projects, maxDOM]);

  return (
    <div className="space-y-6">
      {deals.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-12 text-[#A5A5A5] opacity-30">
          <Wallet className="w-8 h-8 mb-2 stroke-[1px]" />
          <p className="text-[10px] font-bold uppercase tracking-widest text-center">No Holding Costs Tracked</p>
        </div>
      ) : (
        deals.map(deal => (
          <div key={deal.id} className="group/item p-4 rounded-xl bg-[#FFFFFF] border border-[#CCCCCC]/10 shadow-sm hover:border-[#1A1A1A]/20 transition-all duration-500">
            <div className="flex items-center justify-between mb-4">
              <span className="text-xs font-bold text-[#1A1A1A] tracking-tight truncate max-w-[150px]">
                {deal.address}
              </span>
              <div className="flex flex-col items-end">
                <span className="text-sm font-bold text-[#1A1A1A] tracking-tight font-mono">
                  {formatCurrency(deal.monthlyTotal)}
                </span>
                <span className="text-[9px] uppercase tracking-[0.1em] text-[#7F7F7F] opacity-40 font-black">
                  Monthly Burn
                </span>
              </div>
            </div>

            <div className="flex items-center gap-4 py-3 border-y border-[#CCCCCC]/5">
              <div className="flex-1">
                <p className="text-[9px] uppercase tracking-widest text-[#A5A5A5] opacity-40 mb-0.5">Daily Rate</p>
                <p className="text-xs font-mono text-[#1A1A1A] font-bold">{formatCurrency(deal.dailyRate)}</p>
              </div>
              <div className="flex-1 text-right">
                <p className="text-[9px] uppercase tracking-widest text-[#A5A5A5] opacity-40 mb-0.5">Days Held</p>
                <p className="text-xs font-mono text-[#1A1A1A] font-bold">{deal.daysHeld}d</p>
              </div>
            </div>

            <div className="mt-4 flex items-center justify-between">
              <div className="flex items-center gap-1.5">
                <TrendingUp className="w-3 h-3 text-[#595959]/60" />
                <span className="text-[10px] text-[#7F7F7F] opacity-60">Est. Remaining Exposure</span>
              </div>
              <span className="text-xs font-bold text-[#1A1A1A] font-mono">
                {formatCurrency(deal.projectedRemainingCost)}
              </span>
            </div>
          </div>
        ))
      )}
    </div>
  );
}

'use client';

import React, { useMemo, useState } from 'react';
import { Project } from '@/types/schema';
import { Gauge, ChevronDown, ChevronUp, AlertTriangle, CheckCircle2, AlertCircle, Info } from 'lucide-react';
import { deriveAllMetrics } from '@/lib/metrics/reiMetrics';

/* ═══════════════════════════════════════════════════════════════
   MAOGaugeTracker — Acquisition Strategy Sentinel

   Monitors compliance with the "70% Rule".
   MAO = (ARV × 0.70) − Repair Costs.
   Aesthetics: Status-colored progress bars, mono values, high-contrast labels.
   ═══════════════════════════════════════════════════════════════ */

interface DealMAO {
  id: string;
  address: string;
  arv: number;
  repairCosts: number;
  actualCost: number;
  mao: number;
  delta: number;
  pct: number;
  status: 'within' | 'approaching' | 'exceeded';
}

function shortAddress(addr: string): string {
  if (!addr) return 'Unnamed Property';
  const comma = addr.indexOf(',');
  return comma > 0 ? addr.slice(0, comma) : addr;
}

function formatCurrency(val: number): string {
  if (val === 0) return '—';
  const absVal = Math.abs(val);
  const sign = val < 0 ? '-' : '';
  if (absVal >= 1_000_000) return `${sign}$${(absVal / 1_000_000).toFixed(1)}M`;
  if (absVal >= 1_000) return `${sign}$${(absVal / 1_000).toFixed(0)}k`;
  return `${sign}$${absVal.toLocaleString()}`;
}

const STATUS_CONFIG = {
  within:      { bgBar: 'bg-[#F2F2F2]',   fillBar: 'bg-[#595959]',  icon: CheckCircle2,  color: 'text-[#595959]',  label: 'COMPLIANT' },
  approaching: { bgBar: 'bg-[#F2F2F2]',   fillBar: 'bg-[#7F7F7F]', icon: AlertCircle,    color: 'text-[#7F7F7F]',  label: 'RISK' },
  exceeded:    { bgBar: 'bg-[#CCCCCC]',      fillBar: 'bg-[#1A1A1A]',   icon: AlertTriangle,  color: 'text-[#1A1A1A]',    label: 'VIOLATION' },
};

interface MAOGaugeTrackerProps {
  projects: Project[];
}

export default function MAOGaugeTracker({ projects }: MAOGaugeTrackerProps) {
  const [expanded, setExpanded] = useState(false);
  const [rulePercent, setRulePercent] = useState<70 | 75>(70);

  const deals = useMemo(() => {
    return projects
      .filter(d => d.status !== 'exit' && d.financials?.estimatedARV && d.financials.estimatedARV > 0)
      .map(deal => {
        const metrics = deriveAllMetrics(
          deal.financials!,
          undefined,
          deal.dispositionType,
          deal.currentPhase,
          deal.createdAt,
          undefined,
          { ...deal, rulePercent }
        );

        const arv = deal.financials?.estimatedARV || 0;
        const purchasePrice = deal.financials?.purchasePrice || 0;
        const repairCosts = metrics.rehab?.totalRehab || deal.financials?.projectedRehabCost || 0;

        const mao = metrics.mao ?? 0;
        const actualCost = purchasePrice;
        const delta = mao - actualCost;
        const pct = mao > 0 ? (actualCost / mao) * 100 : 999;

        let status: DealMAO['status'] = 'within';
        if (pct >= 100) status = 'exceeded';
        else if (pct >= 85) status = 'approaching';

        return {
          id: deal.id,
          address: deal.address || deal.propertyName,
          arv,
          repairCosts,
          actualCost,
          mao: Math.max(0, mao),
          delta,
          pct: Math.min(pct, 200),
          status,
        };
      })
      .sort((a, b) => b.pct - a.pct);
  }, [projects, rulePercent]);

  const withinCount = deals.filter(d => d.status === 'within').length;
  const approachingCount = deals.filter(d => d.status === 'approaching').length;
  const exceededCount = deals.filter(d => d.status === 'exceeded').length;

  return (
    <div className="w-full h-full p-6 group">
      {/* Header */}
      <div className="flex items-center justify-between mb-10">
        <div className="flex items-center gap-4">
          <div className="w-12 h-12 rounded-xl bg-[#F2F2F2]/50 flex items-center justify-center text-[#7F7F7F] group-hover:bg-[#1A1A1A] group-hover:text-[#FFFFFF] transition-all duration-500 shadow-sm border border-[#A5A5A5]/5">
            <Gauge className="w-6 h-6" />
          </div>
          <div>
            <p className="ag-label opacity-40 group-hover:opacity-100 transition-opacity font-bold uppercase tracking-[0.25em] text-[9px] text-[#1A1A1A]">
              Acquisition Sentinel
            </p>
            <h3 className="text-2xl font-normal text-[#1A1A1A] tracking-tighter">{rulePercent}% Rule</h3>
          </div>
        </div>

        <div className="flex items-center gap-1 bg-[#F2F2F2]/50 p-1 rounded-xl border border-[#A5A5A5]/5 shadow-inner">
          <button
            onClick={() => setRulePercent(70)}
            className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-widest transition-all ${rulePercent === 70 ? 'bg-[#1A1A1A] text-[#FFFFFF] shadow-lg' : 'text-[#7F7F7F] hover:text-[#1A1A1A]'}`}
          >
            70%
          </button>
          <button
            onClick={() => setRulePercent(75)}
            className={`px-4 py-1.5 rounded-lg text-[9px] font-black tracking-widest transition-all ${rulePercent === 75 ? 'bg-[#1A1A1A] text-[#FFFFFF] shadow-lg' : 'text-[#7F7F7F] hover:text-[#1A1A1A]'}`}
          >
            75%
          </button>
        </div>
      </div>

      {deals.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-12 text-[#7F7F7F] opacity-30">
          <Info className="w-10 h-10 mb-3 stroke-[1px]" />
          <p className="text-sm font-bold uppercase tracking-widest text-[10px]">Insufficient Data</p>
          <p className="text-[10px] mt-1 opacity-50 text-center max-w-[200px]">Add ARV and Purchase Price to track compliance.</p>
        </div>
      ) : (
        <div className="space-y-10">
          {/* Portfolio Summary Summary */}
          <div className="flex gap-4 p-1 bg-[#F2F2F2]/30 rounded-2xl border border-[#A5A5A5]/5">
            <div className="flex-1 text-center py-5 rounded-xl bg-[#FFFFFF]/50 backdrop-blur-sm border border-[#A5A5A5]/10 shadow-sm">
              <p className="text-2xl font-normal text-[#1A1A1A] tracking-tighter font-mono">{withinCount}</p>
              <p className="text-[9px] uppercase tracking-[0.2em] text-[#595959] font-black mt-2">Within</p>
            </div>
            <div className="flex-1 text-center py-5 rounded-xl bg-[#FFFFFF]/50 backdrop-blur-sm border border-[#A5A5A5]/10 shadow-sm">
              <p className="text-2xl font-normal text-[#7F7F7F] tracking-tighter font-mono">{approachingCount}</p>
              <p className="text-[9px] uppercase tracking-[0.2em] text-[#7F7F7F] font-black mt-2">Warning</p>
            </div>
            <div className="flex-1 text-center py-5 rounded-xl bg-[#FFFFFF]/50 backdrop-blur-sm border border-[#A5A5A5]/10 shadow-sm">
              <p className="text-2xl font-normal text-[#1A1A1A] tracking-tighter font-mono">{exceededCount}</p>
              <p className="text-[9px] uppercase tracking-[0.2em] text-[#1A1A1A] font-black mt-2">Over</p>
            </div>
