            {/* Per-Deal Breakdown */}
            {expanded && (
              <div className="space-y-6 animate-in fade-in slide-in-from-top-2 duration-500 max-h-[400px] overflow-y-auto pr-3 custom-scrollbar">
                {deals.map(deal => {
                  const cfg = STATUS_CONFIG[deal.status];
