              <defs>
                <linearGradient id="cumulativeGradient" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#CCCCCC" stopOpacity={0.4}/>
                  <stop offset="95%" stopColor="#CCCCCC" stopOpacity={0}/>
                </linearGradient>
                <filter id="lineShadow" height="200%">
                  <feGaussianBlur in="SourceAlpha" stdDeviation="3" />
                  <feOffset dx="0" dy="6" result="offsetblur" />
                  <feComponentTransfer>
                    <feFuncA type="linear" slope="0.15" />
                  </feComponentTransfer>
                  <feMerge>
                    <feMergeNode />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>
              <CartesianGrid
                strokeDasharray="4 4"
                stroke="#F2F2F2"
                vertical={false}
              />
              <XAxis
                dataKey="month"
                tick={{ fill: '#7F7F7F', fontSize: 10, fontWeight: 700 }}
                axisLine={false}
                tickLine={false}
                dy={10}
              />
              <YAxis
                yAxisId="left"
                tick={{ fill: '#7F7F7F', fontSize: 10, fontWeight: 600, fontFamily: 'monospace' }}
                axisLine={false}
                tickLine={false}
                tickFormatter={formatCurrency}
              />
              <YAxis
                yAxisId="right"
                orientation="right"
                tick={{ fill: '#A5A5A5', fontSize: 10, fontWeight: 600, fontFamily: 'monospace' }}
                axisLine={false}
                tickLine={false}
