        {/* Next Phase Quick Action */}
        {nextPhase && (
          <button
            onClick={(e) => { e.stopPropagation(); onMove?.(nextPhase); }}
            className="absolute top-0 right-0 bg-pw-accent hover:bg-black text-white p-2 shadow-lg transform translate-x-12 group-hover:translate-x-0 transition-transform duration-300"
            title={`Move to ${nextPhase}`}
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        )}

        <div className="absolute bottom-0 right-0 flex items-center bg-bg-surface/90 backdrop-blur-sm px-2 py-1">
          <Calendar className="w-3 h-3 mr-1 text-text-primary" />
          <span className="text-[10px] font-black text-text-primary tracking-tighter">{daysInPhase} DAYS</span>
        </div>
      </div>

      <div className="p-4 space-y-3">
        {/* Header */}
        <div>
          <h4 className="text-xs font-black text-text-primary uppercase tracking-tight truncate">{deal.propertyName}</h4>
          <div className="flex items-center text-text-secondary mt-1">
            <MapPin className="w-3 h-3 mr-1" />
            <p className="text-[10px] uppercase tracking-wide truncate">{deal.address}</p>
          </div>
        </div>

        {/* ARV / MAO chips — always visible */}
        {(flipMetrics.arv > 0 || flipMetrics.mao > 0) && (
          <div className="flex items-center gap-2 flex-wrap">
            {flipMetrics.arv > 0 && (
              <span className="inline-flex items-center px-2 py-0.5 text-[9px] font-black uppercase tracking-[0.15em] bg-bg-primary text-text-primary border border-border-accent/40">
                ARV {`$${flipMetrics.arv.toLocaleString()}`}
              </span>
            )}
            {flipMetrics.mao > 0 && (
              <span className={`inline-flex items-center px-2 py-0.5 text-[9px] font-black uppercase tracking-[0.15em] border ${
                flipMetrics.maoViolated
                  ? 'bg-[#1A1A1A]/5 text-[#1A1A1A] border-[#1A1A1A]/20'
                  : 'bg-bg-primary text-text-secondary border-border-accent/40'
              }`}>
                MAO {`$${flipMetrics.mao.toLocaleString()}`}
                {flipMetrics.maoViolated && (
                  <AlertTriangle className="w-2.5 h-2.5 ml-1 text-[#1A1A1A]" />
                )}
              </span>
            )}
          </div>
        )}

        {/* Dynamic Content */}
        <AnimatePresence mode="wait">
          {trackMode === 'FLIP' ? (
            <motion.div
              key="flip"
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -5 }}
              className="space-y-3"
            >
              <div className="flex justify-between items-end">
                <div>
                  <p className="text-[9px] font-black text-text-secondary uppercase tracking-[0.2em]">Est. Net Profit</p>
                  <p className={`text-xl font-normal tabular-nums ${flipMetrics.netProjectedProfit < 0 ? 'text-[#1A1A1A]' : 'text-text-primary'}`}>
                    ${flipMetrics.netProjectedProfit.toLocaleString(undefined, { maximumFractionDigits: 0 })}
                  </p>
                </div>
                {/* Circular rehab progress */}
                {flipMetrics.rehabBudget > 0 && (
                  <div className="relative flex items-center justify-center flex-shrink-0">
                    <svg className="w-10 h-10 transform -rotate-90">
                      <circle cx="20" cy="20" r="16" stroke="currentColor" strokeWidth="2" fill="transparent" className="text-[#CCCCCC]" />
                      <circle
                        cx="20" cy="20" r="16"
                        stroke="currentColor" strokeWidth="2" fill="transparent"
                        strokeDasharray={100.5}
                        style={{ strokeDashoffset: 100.5 - (Math.min(flipMetrics.rehabPct, 1) * 100.5) }}
                        className={`transition-all duration-1000 ${flipMetrics.rehabPct >= 1 ? 'text-[#1A1A1A]' : 'text-text-primary'}`}
                      />
                    </svg>
                    <span className="absolute text-[9px] font-black text-text-primary">{Math.round(flipMetrics.rehabPct * 100)}%</span>
                  </div>
                )}
              </div>

              {/* Rehab budget bar */}
              {flipMetrics.rehabBudget > 0 && (
                <div className="space-y-1">
                  <div className="flex justify-between items-center">
                    <span className="text-[9px] font-black text-text-secondary uppercase tracking-[0.2em]">Rehab</span>
                    <span className="text-[9px] font-black text-text-primary tabular-nums">
                      ${flipMetrics.rehabActual.toLocaleString()} / ${flipMetrics.rehabBudget.toLocaleString()}
                    </span>
                  </div>
                  <div className="h-0.5 w-full bg-bg-primary">
                    <div
                      className={`h-full transition-all duration-700 ${flipMetrics.rehabPct >= 1 ? 'bg-[#1A1A1A]' : 'bg-pw-black'}`}
                      style={{ width: `${Math.min(flipMetrics.rehabPct * 100, 100)}%` }}
                    />
                  </div>
                  {flipMetrics.rehabDelta < 0 && (
                    <p className="text-[9px] text-[#1A1A1A] font-black">
                      ${Math.abs(flipMetrics.rehabDelta).toLocaleString()} over budget
                    </p>
                  )}
                </div>
              )}

              {/* Daily burn rate */}
              {flipMetrics.hasBurnRate && (
                <div className="flex justify-between items-center">
                  <span className="text-[9px] font-black text-text-secondary uppercase tracking-[0.2em]">Daily Burn</span>
                  <span className="text-[9px] font-black text-text-primary tabular-nums">
                    ${flipMetrics.dailyBurnRate.toFixed(0)}/day
                  </span>
                </div>
              )}
            </motion.div>
          ) : (
            <motion.div
              key="hold"
              initial={{ opacity: 0, y: 5 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -5 }}
              className="space-y-3 p-3 bg-bg-primary border border-border-accent"
            >
              <div className="flex justify-between items-center">
                <div>
                  <p className="text-[9px] font-black text-text-secondary uppercase tracking-[0.2em]">Monthly Rent</p>
                  <p className="text-lg font-normal text-text-primary tabular-nums">
                    ${holdMetrics.monthlyRent.toLocaleString()}
                  </p>
                </div>
                <div className="text-right">
                  <p className="text-[9px] font-black text-text-secondary uppercase tracking-[0.2em]">Cash-on-Cash</p>
                  <p className={`text-sm font-black tabular-nums ${holdMetrics.cashOnCashYield >= 8 ? 'text-[#595959]' : holdMetrics.cashOnCashYield < 0 ? 'text-[#1A1A1A]' : 'text-text-primary'}`}>
                    {holdMetrics.cashOnCashYield.toFixed(1)}%
                  </p>
                </div>
              </div>
              {holdMetrics.monthlyCashFlow !== 0 && (
                <div className="flex justify-between items-center">
                  <span className="text-[9px] font-black text-text-secondary uppercase tracking-[0.2em]">Cash Flow</span>
                  <span className={`text-[9px] font-black tabular-nums ${holdMetrics.monthlyCashFlow >= 0 ? 'text-[#595959]' : 'text-[#1A1A1A]'}`}>
                    {holdMetrics.monthlyCashFlow >= 0 ? '+' : '-'}${Math.abs(holdMetrics.monthlyCashFlow).toLocaleString()}/mo
                  </span>
                </div>
              )}
            </motion.div>
          )}
        </AnimatePresence>

        {/* Footer */}
        <div className="flex justify-between items-center pt-3 border-t border-border-accent">
          <div className="flex -space-x-1.5">
            {[1, 2].map(i => (
              <div key={i} className="w-5 h-5 border border-pw-border bg-[#F2F2F2]" />
            ))}
          </div>
          <div className="flex items-center gap-3">
            <div className="flex items-center text-text-secondary">
              <PieChart className="w-3 h-3 mr-1" />
              <span className="text-[10px] font-bold uppercase tracking-widest">4 Tasks</span>
            </div>
            {/* P&L toggle */}
            <button
              onClick={(e) => { e.stopPropagation(); setIsExpanded(v => !v); }}
              className="flex items-center text-text-secondary hover:text-text-primary transition-colors"
              aria-label="Toggle P&L breakdown"
            >
              <BarChart2 className="w-3 h-3 mr-1" />
              <span className="text-[10px] font-bold uppercase tracking-widest">P&L</span>
              <ChevronDown className={`w-3 h-3 ml-0.5 transition-transform duration-200 ${isExpanded ? 'rotate-180' : ''}`} />
            </button>
          </div>
        </div>
      </div>

      {/* P&L drawer */}
      <AnimatePresence>
        {isExpanded && (
          <motion.div
            key="pnl-drawer"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: 'auto', opacity: 1 }}
            exit={{ height: 0, opacity: 0 }}
            transition={{ duration: 0.25, ease: [0.19, 1, 0.22, 1] }}
            className="overflow-hidden border-t border-border-accent/40"
          >
            <PropertyPnLWidget deal={deal} mode="compact" trackMode={trackMode} />
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

'use client';

import React from 'react';
import { Project } from '@/types/schema';
import KanbanCard from './KanbanCard';
import { motion, AnimatePresence } from 'framer-motion';
import { ErrorBoundary } from '@/components/ui/ErrorBoundary';

interface KanbanColumnProps {
  id: string;
  title: string;
  projects: Project[];
  onCardSelect?: (projectId: string) => void;
  onMoveDeal?: (deal: Project, target: string) => void;
  mobileFullWidth?: boolean;
}

export default function KanbanColumn({ id, title, projects, onCardSelect, onMoveDeal, mobileFullWidth }: KanbanColumnProps) {
  const [shouldThrow, setShouldThrow] = React.useState(false);
  if (shouldThrow) {
    throw new Error('Test Error Boundary');
  }

  const isDarkPhase = ['Rehab', 'Listed', 'Closed'].includes(id);
  const bgColorStyle = {
    'Sourcing': '#f2f2f2',
    'Under Contract': '#cccccc',
    'Rehab': '#a5a5a5',
    'Listed': '#7f7f7f',
    'Closed': '#595959',
  }[id] || '#f2f2f2';

  const textColorClass = isDarkPhase ? 'text-white' : 'text-text-primary';
  const subtextColorClass = isDarkPhase ? 'text-white/60' : 'text-text-secondary';

  return (
    <div
      className={`flex flex-col h-full border-r border-border-accent/20 overflow-hidden shadow-[inset_0_0_40px_rgba(0,0,0,0.01)] ${
        mobileFullWidth
          ? 'w-full'
          : 'w-[85vw] sm:w-[350px] min-w-[300px] sm:min-w-[350px] shrink-0 snap-center'
      }`}
      style={{ backgroundColor: bgColorStyle }}
    >
      {/* Column Header */}
      <div className={`p-6 flex items-center justify-between border-b border-border-accent/10 sticky top-0 z-10 backdrop-blur-sm`}>
        <div className="flex items-center space-x-3">
          <h3 className={`text-xs font-bold ${textColorClass} uppercase tracking-[0.2em]`}>{title}</h3>
          <span className={`${isDarkPhase ? 'bg-bg-surface/10 text-white' : 'bg-black/5 text-text-primary'} px-3 py-1 rounded-full text-[9px] font-bold`}>
            {projects.length}
          </span>
        </div>
        <div className={`w-1.5 h-1.5 rounded-full ${isDarkPhase ? 'bg-bg-surface' : 'bg-black'} opacity-20`} />
      </div>

      <div
        className={`flex-1 p-4 space-y-4 overflow-y-auto custom-scrollbar transition-colors duration-200`}
      >
        <ErrorBoundary name={`${title} Column`}>
          <AnimatePresence>
            <button 
              onClick={() => setShouldThrow(true)} 
              className={`w-full py-2 mb-2 text-xs font-bold rounded ${isDarkPhase ? 'bg-[#1A1A1A]/20 text-white' : 'bg-[#1A1A1A]/10 text-[#1A1A1A]'}`}
            >
              Trigger Error (Test)
            </button>
            {projects.length > 0 ? (
              projects.map((deal) => (
                <motion.div
                  key={deal.id}
                  layout
                  initial={{ opacity: 0, scale: 0.95 }}
                  animate={{ opacity: 1, scale: 1 }}
                  exit={{ opacity: 0, scale: 0.95 }}
                  transition={{ duration: 0.2 }}
                >
                  <KanbanCard 
                    deal={deal} 
                    onSelect={onCardSelect} 
                    onMove={(target) => onMoveDeal?.(deal, target)}
                  />
                </motion.div>
              ))
            ) : (
              <div className={`h-40 flex flex-col items-center justify-center border border-dashed rounded-[32px] ${isDarkPhase ? 'border-white/10' : 'border-black/5'}`}>
                <p className={`text-[10px] font-bold ${isDarkPhase ? 'text-white/50' : 'text-text-secondary/60'} uppercase tracking-[0.2em]`}>
                  Neutral State
                </p>
              </div>
            )}
          </AnimatePresence>
        </ErrorBoundary>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { AlertTriangle, ArrowRight, CheckCircle2, X } from 'lucide-react';

interface TransitionConfirmationModalProps {
  isOpen: boolean;
  onClose: () => void;
  onConfirm: () => void;
  dealName: string;
  targetPhase: string;
}

export default function TransitionConfirmationModal({
  isOpen,
  onClose,
  onConfirm,
  dealName,
  targetPhase,
}: TransitionConfirmationModalProps) {
  return (
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          {/* Backdrop */}
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-black/65 backdrop-blur-md"
          />

          {/* Modal Content */}
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            className="relative w-full max-w-md bg-pw-glass-bg border border-pw-border backdrop-blur-[20px] rounded-2xl shadow-2xl overflow-hidden"
          >
            <div className="p-8">
              <div className="flex justify-between items-start mb-6">
                <div className="bg-amber-500/10 border border-amber-500/30 p-3 rounded-2xl">
                  <AlertTriangle className="w-6 h-6 text-amber-500" />
                </div>
                <button onClick={onClose} className="text-pw-black hover:bg-pw-glass-bg/25 p-2 rounded-full transition-all">
                  <X className="w-5 h-5" />
                </button>
              </div>

              <h2 className="text-2xl font-normal text-pw-black mb-2 tracking-tight">
                Update Asset Status?
              </h2>
              <p className="text-sm text-pw-muted mb-8 leading-relaxed">
                You are about to transition <span className="font-bold text-pw-black">"{dealName}"</span> to the 
                <span className="inline-flex items-center mx-1 px-2 py-0.5 rounded-full bg-pw-glass-bg/50 text-pw-black border border-pw-border font-bold text-xs uppercase tracking-widest">
                  {targetPhase}
                </span> 
                phase. This may trigger automated notifications and update financial projections.
              </p>

              <div className="flex flex-col space-y-3">
                <button
                  onClick={onConfirm}
                  className="pw-btn pw-btn--primary pw-btn--pill w-full flex items-center justify-center py-4 text-xs font-bold uppercase tracking-widest transition-all shadow-lg active:scale-[0.98]"
                >
                  <CheckCircle2 className="w-4 h-4 mr-2" />
                  Confirm Transition
                </button>
                <button
                  onClick={onClose}
                  className="pw-btn pw-btn--secondary pw-btn--pill w-full py-4 text-xs font-bold uppercase tracking-widest transition-all"
                >
                  Cancel
                </button>
              </div>
            </div>

            {/* Visual Footer */}
            <div className="bg-pw-glass-bg/50 px-8 py-4 border-t border-pw-border flex items-center justify-center italic text-xs text-pw-muted">
              <ArrowRight className="w-3 h-3 mr-2" />
              Automated ledger entry will be recorded in the audit trail.
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>
  );
}

