'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { X, Building2, Calculator, ShieldCheck, ArrowRight, Loader2, Lock } from 'lucide-react';
import { generateDealSlug, checkDuplicateDeal, createAnalyzerHandoffPayload, DealData } from '@/lib/deals/slugUtils';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';

interface ResolvedAddressInfo {
  placeId?: string;
  formattedAddress: string;
  streetNumber?: string;
  route?: string;
  city?: string;
  state?: string;
  zip?: string;
  lat?: number;
  lng?: number;
}

interface CreateDealSheetProps {
  isOpen: boolean;
  onClose: () => void;
  initialAddress?: ResolvedAddressInfo | null;
  existingDeals?: DealData[];
  onDealCreated?: (deal: DealData) => void;
}

export default function CreateDealSheet({
  isOpen,
  onClose,
  initialAddress,
  existingDeals = [],
  onDealCreated,
}: CreateDealSheetProps) {
  const router = useRouter();
  const { user, profile } = useAuth();

  const [address, setAddress] = useState(initialAddress?.formattedAddress || '');
  const [placeId, setPlaceId] = useState(initialAddress?.placeId || '');
  const [city, setCity] = useState(initialAddress?.city || '');
  const [state, setState] = useState(initialAddress?.state || '');
  const [zip, setZip] = useState(initialAddress?.zip || '');
  const [lat, setLat] = useState(initialAddress?.lat || 0);
  const [lng, setLng] = useState(initialAddress?.lng || 0);

  const [price, setPrice] = useState<number | ''>(350000);
  const [rehabCost, setRehabCost] = useState<number | ''>(50000);
  const [arv, setArv] = useState<number | ''>(480000);
  const [estimatedRent, setEstimatedRent] = useState<number | ''>(3200);
  const [fundingTarget, setFundingTarget] = useState<number | ''>(200000);

  const [isSubmitting, setIsSubmitting] = useState(false);
  const [duplicateWarning, setDuplicateWarning] = useState<DealData | null>(null);

  useEffect(() => {
    if (initialAddress) {
      setAddress(initialAddress.formattedAddress || '');
      setPlaceId(initialAddress.placeId || '');
      setCity(initialAddress.city || '');
      setState(initialAddress.state || '');
      setZip(initialAddress.zip || '');
      setLat(initialAddress.lat || 0);
      setLng(initialAddress.lng || 0);
    }
  }, [initialAddress]);

  // Check for duplicate on address or placeId change
  useEffect(() => {
    if (!address) {
      setDuplicateWarning(null);
      return;
    }
    const slug = generateDealSlug(address);
    const dupCheck = checkDuplicateDeal(placeId, slug, existingDeals);
    if (dupCheck.isDuplicate && dupCheck.existingDeal) {
      setDuplicateWarning(dupCheck.existingDeal as DealData);
    } else {
      setDuplicateWarning(null);
    }
  }, [address, placeId, existingDeals]);

  if (!isOpen) return null;

  const handleGoToExistingDeal = () => {
    if (!duplicateWarning) return;
    toast.success('Redirecting to existing Deal at this property…', { id: 'dup-deal-redirect' });
    onClose();
    if (duplicateWarning.slug) {
      router.push(`/dashboard/deals?slug=${duplicateWarning.slug}`);
    } else if (duplicateWarning.id) {
      router.push(`/dashboard/deals?id=${duplicateWarning.id}`);
    }
  };

  const handleSubmit = async (targetStatus: 'DRAFT' | 'LISTED') => {
    if (!address.trim()) {
      toast.error('Please enter a valid property address.');
      return;
    }

    const slug = generateDealSlug(address);
    const dupCheck = checkDuplicateDeal(placeId, slug, existingDeals);

    // Prompt 2 requirement: Duplicate attempt -> route to existing Deal instead of erroring dead-end
    if (dupCheck.isDuplicate && dupCheck.existingDeal) {
      toast('A Deal already exists at this property address. Routing to existing Deal…', { icon: 'ℹ️' });
      onClose();
      if (dupCheck.existingDeal.slug) {
        router.push(`/dashboard/deals?slug=${dupCheck.existingDeal.slug}`);
      } else {
        router.push(`/dashboard/deals?id=${dupCheck.existingDeal.id}`);
      }
      return;
    }

    setIsSubmitting(true);

    try {
      const numPrice = Number(price) || 0;
      const numRehab = Number(rehabCost) || 0;
      const numArv = Number(arv) || 0;
      const numRent = Number(estimatedRent) || 0;
      const numTarget = Number(fundingTarget) || 0;

      const dealId = `deal_${Date.now()}`;
      const handoffPayload = createAnalyzerHandoffPayload({
        id: dealId,
        displayAddress: address,
        price: numPrice,
        rehabCost: numRehab,
        arv: numArv,
        estimatedRent: numRent,
        fundingTarget: numTarget,
      });

      const newDeal: DealData = {
        id: dealId,
        placeId: placeId || `place_${Date.now()}`,
        slug,
        displayAddress: address,
        city,
        state,
        zip,
        lat,
        lng,
        ownerId: user?.uid || 'user_demo',
        price: numPrice,
        rehabCost: numRehab,
        arv: numArv,
        estimatedRent: numRent,
        status: targetStatus,
        fundingTarget: numTarget,
        currency: 'USD',
        analyzerSnapshotId: handoffPayload.analyzerSnapshotId,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      };

      // Store analyzer snapshot payload in localStorage / sessionStorage for reciprocal entry
      if (typeof window !== 'undefined') {
        localStorage.setItem(`pw_analyzer_snap_${handoffPayload.analyzerSnapshotId}`, JSON.stringify(handoffPayload));
        sessionStorage.setItem('pw_last_created_deal', JSON.stringify(newDeal));
      }

      if (onDealCreated) {
        onDealCreated(newDeal);
      }

      toast.success(
        targetStatus === 'LISTED'
          ? 'Deal successfully listed to Marketplace!'
          : 'Deal saved as Draft.',
        { id: 'create-deal-success' }
      );

      onClose();
    } catch (err: any) {
      console.error('Failed to create deal:', err);
      toast.error('Failed to create deal. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleOpenInAnalyzer = () => {
    const numPrice = Number(price) || 0;
    const numRehab = Number(rehabCost) || 0;
    const numArv = Number(arv) || 0;
    const numRent = Number(estimatedRent) || 0;

    const queryParams = new URLSearchParams({
      address,
      purchasePrice: numPrice.toString(),
      rehabCost: numRehab.toString(),
      arv: numArv.toString(),
      rent: numRent.toString(),
    });

    onClose();
    router.push(`/dashboard/deal-analyzer?${queryParams.toString()}`);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-end bg-black/60 backdrop-blur-sm p-0 md:p-4 animate-in fade-in duration-200">
      <div className="w-full max-w-xl h-full md:h-[90vh] bg-pw-bg border border-pw-border rounded-none md:rounded-2xl shadow-2xl flex flex-col overflow-hidden">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-pw-border bg-[var(--color-surface)]">
          <div className="flex items-center gap-2">
            <Building2 className="w-5 h-5 text-slate-300" />
            <h2 className="text-base font-bold text-slate-100">Create New Deal Listing</h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg text-slate-400 hover:text-slate-100 hover:bg-white/5 transition-all"
            aria-label="Close creation sheet"
          >
            <X className="w-5 h-5" />
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* Duplicate Warning Alert */}
          {duplicateWarning && (
            <div className="p-4 rounded-xl bg-amber-500/10 border border-amber-500/30 text-amber-300 text-xs space-y-2">
              <div className="flex items-center gap-2 font-bold">
                <ShieldCheck className="w-4 h-4 text-amber-400" />
                <span>Existing Deal Found at this Address</span>
              </div>
              <p className="leading-relaxed">
                A Deal for <strong>{duplicateWarning.displayAddress}</strong> is already active on PaperWorking.
              </p>
              <button
                onClick={handleGoToExistingDeal}
                className="mt-1 px-3 py-1.5 rounded-lg bg-amber-500 text-slate-950 font-bold text-xs hover:bg-amber-400 transition-all flex items-center gap-1"
              >
                <span>View Existing Deal</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </button>
            </div>
          )}

          {/* Address Section */}
          <div className="space-y-2">
            <label className="block text-xs font-bold uppercase tracking-wider text-slate-300">
              Property Address
            </label>
            <input
              type="text"
              value={address}
              onChange={(e) => setAddress(e.target.value)}
              placeholder="e.g. 123 Main St, Austin, TX 78701"
              className="w-full px-4 py-2.5 rounded-xl bg-white/5 border border-pw-border text-slate-100 text-sm focus:border-slate-700 focus:outline-none"
            />
            {address && (
              <p className="text-[11px] text-slate-400">
                Canonical Slug: <code className="text-slate-300 font-mono">{generateDealSlug(address)}</code>
              </p>
            )}
          </div>

          {/* Financial Inputs */}
          <div className="space-y-4 pt-2">
            <div className="flex items-center justify-between border-b border-pw-border pb-2">
              <h3 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2">
                <Calculator className="w-4 h-4 text-slate-300" />
                <span>Investor Decision Metrics</span>
              </h3>
              <button
                onClick={handleOpenInAnalyzer}
                type="button"
                className="text-xs font-bold text-slate-300 hover:text-slate-300 transition-all flex items-center gap-1"
              >
                <span>Open in Deal Analyzer</span>
                <ArrowRight className="w-3.5 h-3.5" />
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1">Purchase Price ($)</label>
                <input
                  type="number"
                  value={price}
                  onChange={(e) => setPrice(e.target.value === '' ? '' : Number(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg bg-white/5 border border-pw-border text-slate-100 text-sm focus:border-slate-700 focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1">Estimated Rehab ($)</label>
                <input
                  type="number"
                  value={rehabCost}
                  onChange={(e) => setRehabCost(e.target.value === '' ? '' : Number(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg bg-white/5 border border-pw-border text-slate-100 text-sm focus:border-slate-700 focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1">After Repair Value - ARV ($)</label>
                <input
                  type="number"
                  value={arv}
                  onChange={(e) => setArv(e.target.value === '' ? '' : Number(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg bg-white/5 border border-pw-border text-slate-100 text-sm focus:border-slate-700 focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-400 mb-1">Monthly Rent ($)</label>
                <input
                  type="number"
                  value={estimatedRent}
                  onChange={(e) => setEstimatedRent(e.target.value === '' ? '' : Number(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg bg-white/5 border border-pw-border text-slate-100 text-sm focus:border-slate-700 focus:outline-none"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-slate-400 mb-1">Funding Target ($)</label>
              <input
                type="number"
                value={fundingTarget}
                onChange={(e) => setFundingTarget(e.target.value === '' ? '' : Number(e.target.value))}
                className="w-full px-3 py-2 rounded-lg bg-white/5 border border-pw-border text-slate-100 text-sm focus:border-slate-700 focus:outline-none"
              />
            </div>
          </div>
        </div>

        {/* Footer Actions */}
        <div className="p-4 border-t border-pw-border bg-[var(--color-surface)] flex flex-wrap items-center justify-between gap-3">
          <button
            type="button"
            onClick={onClose}
            className="px-4 py-2 text-xs font-semibold text-slate-400 hover:text-slate-200 transition-all"
          >
            Cancel
          </button>

          <div className="flex items-center gap-3">
            <button
              type="button"
              disabled={isSubmitting}
              onClick={() => handleSubmit('DRAFT')}
              className="px-4 py-2.5 rounded-xl border border-pw-border text-xs font-bold text-slate-200 hover:bg-white/5 transition-all disabled:opacity-50"
            >
              Save as Draft
            </button>
            <button
              type="button"
              disabled={isSubmitting}
              onClick={() => handleSubmit('LISTED')}
              className="px-5 py-2.5 rounded-xl bg-emerald-500 text-slate-950 hover:bg-emerald-400 font-bold text-xs transition-all shadow-lg flex items-center gap-2 disabled:opacity-50"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" />
                  <span>Publishing…</span>
                </>
              ) : (
                <span>List to Marketplace</span>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { MapPin, Bookmark, Share2, Eye, TrendingUp, Building2, Maximize2 } from 'lucide-react';
import { calculateFundingProgress, formatCurrencyAmount } from '@/lib/deals/fundingUtils';
import ExpandedModal from '@/components/deals/ExpandedModal';

export interface DealCardProps {
  deal: {
    id: string;
    slug: string;
    address: string;
    propertyName?: string;
    city?: string;
    state?: string;
    zipCode?: string;
    assetClass?: string;
    subStrategy?: string;
    status?: string;
    purchasePrice: number | string;
    rehabCost?: number | string;
    arv?: number | string;
    projectedRoi: number | string;
    fundingTarget?: number;
    committedAmount?: number;
    investorCount?: number;
    bookmarkCount?: number;
    viewCount?: number;
    imageUrl?: string;
  };
  isCompareMode?: boolean;
  isSelected?: boolean;
  onToggleSelect?: (dealId: string) => void;
  className?: string;
}

export function formatDealTitle(rawAddressOrSlug: string, fallbackName?: string): string {
  if (fallbackName && !fallbackName.startsWith('The') && fallbackName.trim() !== '') {
    return fallbackName;
  }
  if (!rawAddressOrSlug) return 'Investment Deal Opportunity';

  if (rawAddressOrSlug.includes(',')) {
    return rawAddressOrSlug.split(',')[0].trim();
  }

  return rawAddressOrSlug
    .replace(/([0-9]+)([a-zA-Z]+)/, '$1 $2')
    .replace(/([a-z])([A-Z])/g, '$1 $2')
    .trim();
}

export default function DealCard({
  deal,
  isCompareMode = false,
  isSelected = false,
  onToggleSelect,
  className = '',
}: DealCardProps) {
  const [isBookmarked, setIsBookmarked] = useState(false);
  const [bookmarks, setBookmarks] = useState(deal.bookmarkCount || 12);
  const [isExpandedModalOpen, setIsExpandedModalOpen] = useState(false);

  const displayTitle = formatDealTitle(deal.address || deal.slug, deal.propertyName);
  const displayLocation = deal.city && deal.state ? `${deal.city}, ${deal.state}` : deal.address || 'Austin, TX';

  const priceNum = typeof deal.purchasePrice === 'number' ? deal.purchasePrice : parseFloat(deal.purchasePrice) || 350000;
  const roiNum = typeof deal.projectedRoi === 'number' ? deal.projectedRoi : parseFloat(deal.projectedRoi) || 18.5;

  const target = deal.fundingTarget || 200000;
  const committed = deal.committedAmount || 130000;
  const funding = calculateFundingProgress(target, committed);

  const getProgressBarColor = (pct: number) => {
    if (pct < 50) return 'bg-blue-500';
    if (pct < 90) return 'bg-amber-400';
    return 'bg-[#34d399]';
  };

  const handleBookmark = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (isBookmarked) {
      setIsBookmarked(false);
      setBookmarks((prev) => prev - 1);
    } else {
      setIsBookmarked(true);
      setBookmarks((prev) => prev + 1);
    }
  };

  const handleShare = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (typeof navigator !== 'undefined' && navigator.clipboard) {
      const url = `${window.location.origin}/deals/${deal.slug || deal.id}`;
      navigator.clipboard.writeText(url);
    }
  };

  const handleExpandClick = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsExpandedModalOpen(true);
  };

  return (
    <>
      <Link
        href={`/deals/${deal.slug || deal.id}`}
        data-testid="marketplace-deal-card"
        className={`group relative block rounded-[14px] border border-white/[0.06] bg-[#0a0a0f]/80 backdrop-blur-[8px] overflow-hidden transition-all duration-300 hover:border-[#34d399]/30 hover:-translate-y-[1px] hover:shadow-2xl ${
          isSelected ? 'ring-2 ring-[#34d399] border-[#34d399]' : ''
        } ${className}`}
      >
        {/* ── Image Area ── */}
        <div className="relative h-44 w-full bg-gradient-to-br from-slate-900 via-[#0a0a0f] to-slate-950 overflow-hidden flex items-center justify-center border-b border-white/[0.04]">
          {deal.imageUrl ? (
            <img
              src={deal.imageUrl}
              alt={displayTitle}
              className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
            />
          ) : (
            <div className="flex flex-col items-center justify-center space-y-2 opacity-30 group-hover:opacity-40 transition-opacity">
              <Building2 className="w-10 h-10 text-slate-400" />
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400">
                PaperWorking Listing
              </span>
            </div>
          )}

          {/* Top-Left Glass Badges */}
          <div className="absolute top-3 left-3 flex items-center gap-1.5 z-10 flex-wrap">
            <span className="px-2.5 py-1 rounded-[6px] text-[10px] font-extrabold uppercase tracking-wider bg-[#34d399]/20 text-[#34d399] border border-[#34d399]/30 backdrop-blur-md shadow-sm">
              {deal.assetClass || 'Residential'}
            </span>
            <span className="px-2.5 py-1 rounded-[6px] text-[10px] font-extrabold uppercase tracking-wider bg-slate-900/80 text-slate-300 border border-slate-700/50 backdrop-blur-md shadow-sm">
              {deal.subStrategy || 'FLIP'}
            </span>
          </div>

          {/* Top-Right 32x32px Glass Expand Button (Hover Revealed) */}
          <button
            type="button"
            data-testid="expand-card-btn"
            onClick={handleExpandClick}
            className="absolute top-3 right-3 z-20 w-8 h-8 rounded-[8px] bg-black/60 backdrop-blur-md border border-white/20 text-slate-300 hover:text-white hover:bg-[#34d399]/30 hover:border-[#34d399]/50 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100 cursor-pointer shadow-md"
            title="Expand deal analysis"
          >
            <Maximize2 className="w-4 h-4" />
          </button>

          {/* Compare Checkbox or Status Badge */}
          {isCompareMode ? (
            <div
              className="absolute top-3 right-12 z-20 cursor-pointer p-1 rounded-[6px] bg-black/60 backdrop-blur-md border border-white/10"
              onClick={(e) => {
                e.preventDefault();
                e.stopPropagation();
                if (onToggleSelect) onToggleSelect(deal.id);
              }}
            >
              <input
                type="checkbox"
                data-testid={`compare-checkbox-${deal.id}`}
                checked={isSelected}
                onChange={() => {}}
                className="w-5 h-5 accent-[#34d399] rounded cursor-pointer"
              />
            </div>
          ) : null}
        </div>

        {/* ── Content Body ── */}
        <div className="p-5 space-y-4">
          <div>
            <h3
              data-testid="deal-card-title"
              className="text-[15px] font-medium text-white group-hover:text-[#34d399] transition-colors line-clamp-1"
            >
              {displayTitle}
            </h3>

            <p className="text-xs text-slate-400 flex items-center gap-1 mt-1 font-sans">
              <MapPin className="w-3.5 h-3.5 text-[#34d399] shrink-0" />
              <span className="truncate">{displayLocation}</span>
            </p>
          </div>

          {/* Metrics Row */}
          <div className="grid grid-cols-2 gap-3 pt-3 border-t border-white/[0.06] font-mono">
            <div>
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block font-sans">
                Purchase Price
              </span>
              <span className="text-sm font-bold text-slate-100">
                {formatCurrencyAmount(priceNum)}
              </span>
            </div>

            <div className="text-right">
              <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400 block font-sans">
                Projected ROI
              </span>
              <span className="text-sm font-bold text-[#34d399] flex items-center justify-end gap-1">
                <TrendingUp className="w-3.5 h-3.5 text-[#34d399]" />
                {roiNum}%
              </span>
            </div>
          </div>

          {/* Crowdfunding Progress Bar */}
          <div className="space-y-1.5 pt-2 border-t border-white/[0.06]">
            <div className="flex items-center justify-between text-[11px] font-mono">
              <span className="text-slate-400 font-sans font-medium">Funding Progress</span>
              <span className="font-bold text-[#34d399]">{funding.percentFunded}%</span>
            </div>

            <div className="w-full h-1.5 rounded-full bg-white/10 overflow-hidden">
              <div
                className={`h-full rounded-full transition-all duration-500 ${getProgressBarColor(funding.percentFunded)}`}
                style={{ width: `${funding.percentFunded}%` }}
              />
            </div>

            <div className="flex items-center justify-between text-[10px] text-slate-400 font-mono">
              <span>{funding.formattedCommitted} committed</span>
              <span>{funding.formattedTarget} target</span>
            </div>
          </div>

          {/* Card Footer Actions */}
          <div className="flex items-center justify-between pt-3 border-t border-white/[0.04] text-xs text-slate-400">
            <div className="flex items-center gap-3">
              <span className="flex items-center gap-1 hover:text-slate-200 transition-colors">
                <Eye className="w-3.5 h-3.5 text-slate-400" />
                <span>{deal.viewCount || 142}</span>
              </span>

              <button
                type="button"
                onClick={handleBookmark}
                className={`flex items-center gap-1 transition-colors ${
                  isBookmarked ? 'text-[#34d399]' : 'hover:text-slate-200'
                }`}
              >
                <Bookmark className={`w-3.5 h-3.5 ${isBookmarked ? 'fill-[#34d399]' : ''}`} />
                <span>{bookmarks}</span>
              </button>
            </div>

            <button
              type="button"
              onClick={handleShare}
              className="p-1.5 rounded-[6px] hover:bg-white/5 hover:text-slate-200 transition-colors"
              title="Share deal"
            >
              <Share2 className="w-3.5 h-3.5" />
            </button>
          </div>
        </div>
      </Link>

      {/* Expanded Modal */}
      <ExpandedModal
        isOpen={isExpandedModalOpen}
        onClose={() => setIsExpandedModalOpen(false)}
        deal={deal}
        source="card"
      />
    </>
  );
}

'use client';

import React, { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import {
  CheckCircle2,
  XCircle,
  Clock,
  UserCheck,
  Share2,
  Send,
  Mail,
  ShieldAlert,
  Copy,
  Check,
  ExternalLink,
  DollarSign,
  Percent,
} from 'lucide-react';
import {
  generateInvitationToken,
  validateInvestmentIntent,
  validateInvitationToken,
  revokeInvitation,
  DealInvitation,
  DealInterest,
  BusinessCardSnapshot,
} from '@/lib/deals/engagementUtils';
import { formatCurrencyAmount } from '@/lib/deals/fundingUtils';
import toast from 'react-hot-toast';

interface DealEngagementModuleProps {
  dealId: string;
  dealSlug: string;
  displayAddress: string;
  fundingTarget: number;
  committedAmount: number;
  currency?: string;
  onInterestAdded?: (interest: DealInterest) => void;
  onInvitationCreated?: (invitation: DealInvitation) => void;
}

export default function DealEngagementModule({
  dealId,
  dealSlug,
  displayAddress,
  fundingTarget,
  committedAmount,
  currency = 'USD',
  onInterestAdded,
  onInvitationCreated,
}: DealEngagementModuleProps) {
  const { profile, user } = useAuth();

  // Mode: 'INTENT_FORM' | 'COMMITTED' | 'DECLINED' | 'WAITLIST' | 'WITHDRAWN'
  const [responseMode, setResponseMode] = useState<'INTENT_FORM' | 'COMMITTED' | 'DECLINED' | 'WAITLIST' | 'WITHDRAWN'>('INTENT_FORM');
  const [intentInputType, setIntentInputType] = useState<'AMOUNT' | 'PERCENT'>('AMOUNT');
  const [amountValue, setAmountValue] = useState<string>('25000');
  const [percentValue, setPercentValue] = useState<string>('10');
  const [validationError, setValidationError] = useState<string | null>(null);

  // Invite Modal States
  const [isInviteModalOpen, setIsInviteModalOpen] = useState(false);
  const [inviteEmailInput, setInviteEmailInput] = useState('');
  const [activeInvitations, setActiveInvitations] = useState<DealInvitation[]>([]);

  // Share Modal States
  const [isShareModalOpen, setIsShareModalOpen] = useState(false);
  const [copiedLink, setCopiedLink] = useState(false);

  // Invitee Business Card Snapshot sourced from Profile
  const businessCard: BusinessCardSnapshot = {
    displayName: profile?.displayName || user?.displayName || 'Registered Investor',
    email: profile?.email || user?.email || 'investor@paperworking.co',
    phone: profile?.phoneNumber || '+1 (512) 555-0199',
    company: profile?.company || 'PaperWorking Investor Network',
    title: profile?.role || 'Lead Investor',
  };

  // Flow 1: Handle "I'm Interested" Submission
  const handleExpressInterest = (e: React.FormEvent) => {
    e.preventDefault();
    setValidationError(null);

    const percent = intentInputType === 'PERCENT' ? Number(percentValue) : undefined;
    const amount = intentInputType === 'AMOUNT' ? Number(amountValue) : undefined;

    const validation = validateInvestmentIntent(fundingTarget, committedAmount, currency, percent, amount);

    if (!validation.valid) {
      setValidationError(validation.error || 'Invalid intent inputs.');
      toast.error(validation.error || 'Invalid intent inputs.', { id: 'intent-err' });
      return;
    }

    const newInterest: DealInterest = {
      id: `int_${Math.random().toString(36).substring(2, 9)}`,
      dealId,
      userId: user?.uid || 'user_123',
      percentIntent: percent,
      amountIntent: amount,
      currency,
      businessCardSnapshot: businessCard,
      status: validation.status,
      createdAt: new Date().toISOString(),
    };

    setResponseMode(validation.status);
    if (onInterestAdded) onInterestAdded(newInterest);

    if (validation.status === 'WAITLIST') {
      toast.success(`Funding target reached! You have been placed on the Waitlist for ${formatCurrencyAmount(validation.calculatedAmount, currency)}.`, {
        id: 'waitlist-toast',
      });
    } else {
      toast.success(`Successfully registered interest for ${formatCurrencyAmount(validation.calculatedAmount, currency)}!`, {
        id: 'interest-toast',
      });
    }
  };

  // Flow 1: Handle One-Button "Decline"
  const handleDecline = () => {
    setResponseMode('DECLINED');
    toast('You have declined this deal invitation.', {
      icon: '🚫',
      id: 'decline-toast',
    });
  };

  // Flow 2: Invite Others (External & Existing Users)
  const handleSendInvite = (e: React.FormEvent) => {
    e.preventDefault();
    if (!inviteEmailInput || !inviteEmailInput.includes('@')) {
      toast.error('Please enter a valid email address to send invitation.');
      return;
    }

    const newInvite = generateInvitationToken(
      dealId,
      inviteEmailInput,
      user?.uid || 'sender_123',
      profile?.displayName || 'Deal Owner'
    );

    setActiveInvitations((prev) => [newInvite, ...prev]);
    if (onInvitationCreated) onInvitationCreated(newInvite);

    setInviteEmailInput('');
    toast.success(`Invitation sent to ${newInvite.invitedEmail}! (30-day token generated)`, { id: 'invite-toast' });
  };

  // Revoke Invitation
  const handleRevokeInvite = (invite: DealInvitation) => {
    const revoked = revokeInvitation(invite);
    setActiveInvitations((prev) => prev.map((inv) => (inv.id === invite.id ? revoked : inv)));
    toast.success(`Invitation link for ${invite.invitedEmail} revoked.`, { id: 'revoke-toast' });
  };

  // Flow 4: Social Share Intents
  const shareUrl = typeof window !== 'undefined' ? `${window.location.origin}/deals/${dealSlug}` : `https://paperworking.co/deals/${dealSlug}`;
  const shareText = `Check out this real estate investment opportunity on PaperWorking: ${displayAddress}`;

  const handleCopyShareLink = () => {
    if (typeof navigator !== 'undefined' && navigator.clipboard) {
      navigator.clipboard.writeText(shareUrl);
      setCopiedLink(true);
      setTimeout(() => setCopiedLink(false), 2000);
      toast.success('Public-safe deal share link copied!', { id: 'copy-toast' });
    }
  };

  return (
    <div className="space-y-6">
      {/* ── Flow 1: In-Platform Invitation Response Card ── */}
      <div className="glass-card rounded-2xl border border-pw-border p-6 space-y-5 relative overflow-hidden">
        <div className="flex items-center justify-between border-b border-pw-border pb-4">
          <div>
            <h3 className="text-base font-bold text-slate-100 flex items-center gap-2">
              <UserCheck className="w-5 h-5 text-slate-300" />
              <span>Investment Intent & Invitation Action</span>
            </h3>
            <p className="text-xs text-slate-400">Respond directly or express interest to the Deal Owner</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setIsInviteModalOpen(true)}
              className="px-3 py-1.5 rounded-lg bg-emerald-500/10 border border-emerald-500/30 text-emerald-400 font-bold text-xs hover:bg-emerald-500 hover:text-slate-950 transition-all flex items-center gap-1.5 min-h-[36px]"
            >
              <Send className="w-3.5 h-3.5" />
              <span>Invite Investors</span>
            </button>
            <button
              onClick={() => setIsShareModalOpen(true)}
              className="px-3 py-1.5 rounded-lg border border-pw-border bg-white/5 text-slate-300 font-bold text-xs hover:bg-white/10 transition-all flex items-center gap-1.5 min-h-[36px]"
            >
              <Share2 className="w-3.5 h-3.5 text-slate-300" />
              <span>Share</span>
            </button>
          </div>
        </div>

        {/* State A: Declined State */}
        {responseMode === 'DECLINED' && (
          <div className="p-4 rounded-xl bg-slate-900/60 border border-slate-700/50 flex items-center justify-between animate-fade-in">
            <div className="flex items-center gap-3">
              <XCircle className="w-6 h-6 text-slate-400" />
              <div>
                <p className="text-sm font-bold text-slate-300">You have declined this Deal Invitation</p>
                <p className="text-xs text-slate-400">No further prompts will be shown. Owner sees declined status.</p>
              </div>
            </div>
            <button
              onClick={() => setResponseMode('INTENT_FORM')}
              className="text-xs text-slate-300 font-bold hover:underline"
            >
              Reconsider
            </button>
          </div>
        )}

        {/* State B: Committed State */}
        {responseMode === 'COMMITTED' && (
          <div className="p-5 rounded-xl bg-slate-800/10 border border-slate-700/30 space-y-3 animate-fade-in">
            <div className="flex items-center gap-3">
              <CheckCircle2 className="w-6 h-6 text-emerald-400 shrink-0" />
              <div>
                <h4 className="text-sm font-extrabold text-emerald-400">Interest & Business Card Registered!</h4>
                <p className="text-xs text-slate-300">
                  Your business card snapshot has been shared with the Deal Owner.
                </p>
              </div>
            </div>
            <div className="p-3 rounded-lg bg-black/40 border border-slate-700/20 text-xs font-mono text-slate-300 space-y-1">
              <p>Name: <span className="text-slate-100 font-bold">{businessCard.displayName}</span></p>
              <p>Email: <span className="text-slate-100 font-bold">{businessCard.email}</span></p>
              <p>Company: <span className="text-slate-100 font-bold">{businessCard.company}</span></p>
            </div>
          </div>
        )}

        {/* State C: Waitlist State */}
        {responseMode === 'WAITLIST' && (
          <div className="p-5 rounded-xl bg-amber-500/10 border border-amber-500/30 space-y-3 animate-fade-in">
            <div className="flex items-center gap-3">
              <Clock className="w-6 h-6 text-amber-400 shrink-0" />
              <div>
                <h4 className="text-sm font-extrabold text-amber-400">Placed on Over-Commitment Waitlist</h4>
                <p className="text-xs text-slate-300">
                  The primary target is fully committed. Your interest is logged in the waitlist order.
                </p>
              </div>
            </div>
          </div>
        )}

        {/* State D: Intent Form ("I'm Interested" or "Decline") */}
        {responseMode === 'INTENT_FORM' && (
          <form onSubmit={handleExpressInterest} className="space-y-4">
            <div className="flex items-center gap-3">
              <span className="text-xs font-bold uppercase text-slate-300">Specify Investment Intent:</span>
              <div className="flex items-center p-1 rounded-xl bg-white/5 border border-pw-border">
                <button
                  type="button"
                  onClick={() => setIntentInputType('AMOUNT')}
                  className={`px-3 py-1 rounded-lg text-xs font-bold transition-all ${
                    intentInputType === 'AMOUNT' ? 'bg-emerald-500 text-slate-950 shadow-sm' : 'text-slate-400'
                  }`}
                >
                  <DollarSign className="w-3.5 h-3.5 inline mr-1" />
                  Currency Amount ($)
                </button>
                <button
                  type="button"
                  onClick={() => setIntentInputType('PERCENT')}
                  className={`px-3 py-1 rounded-lg text-xs font-bold transition-all ${
                    intentInputType === 'PERCENT' ? 'bg-emerald-500 text-slate-950 shadow-sm' : 'text-slate-400'
                  }`}
                >
                  <Percent className="w-3.5 h-3.5 inline mr-1" />
                  Target Percentage (%)
                </button>
              </div>
            </div>

            {intentInputType === 'AMOUNT' ? (
              <div className="space-y-1">
                <label className="text-xs text-slate-400">Amount in Deal Currency ({currency})</label>
                <input
                  type="number"
                  value={amountValue}
                  onChange={(e) => setAmountValue(e.target.value)}
                  placeholder="25000"
                  className="w-full px-4 py-2.5 rounded-xl bg-white/5 border border-pw-border text-slate-100 text-sm font-mono focus:border-slate-700 focus:outline-none"
                />
              </div>
            ) : (
              <div className="space-y-1">
                <label className="text-xs text-slate-400">Percentage of Target Funding (1% – 100%)</label>
                <input
                  type="number"
                  value={percentValue}
                  onChange={(e) => setPercentValue(e.target.value)}
                  placeholder="10"
                  min="1"
                  max="100"
                  className="w-full px-4 py-2.5 rounded-xl bg-white/5 border border-pw-border text-slate-100 text-sm font-mono focus:border-slate-700 focus:outline-none"
                />
              </div>
            )}

            {validationError && (
              <p className="text-xs font-bold text-rose-400 flex items-center gap-1.5">
                <ShieldAlert className="w-4 h-4" />
                <span>{validationError}</span>
              </p>
            )}

            {/* Action Buttons: Interested (Green) vs Decline (Slate) */}
            <div className="flex items-center gap-3 pt-2">
              <button
                type="submit"
