    state?: string;
    assetClass?: string;
    subStrategy?: string;
    status?: string;
    purchasePrice: number | string;
    rehabCost?: number | string;
    arv?: number | string;
    holdingCosts?: number | string;
    projectedRoi: number | string;
    fundingTarget?: number;
    committedAmount?: number;
    investorCount?: number;
    description?: string;
    imageUrl?: string;
