  investorId: string;
  investorName?: string;
  amount: number;
  percentage: number;
  currency: 'USD' | 'CAD' | 'EUR' | 'GBP';
  status: 'pending' | 'accepted' | 'declined';
  createdAt?: string;
}

interface InvestmentPanelProps {
  dealId: string;
  fundingTarget: number;
  committedAmount: number;
  existingCommitment?: InvestmentCommitmentData | null;
  onCommitSuccess?: (commitment: InvestmentCommitmentData) => void;
  className?: string;
}

const CURRENCY_SYMBOLS: Record<string, string> = {
  USD: '$',
  CAD: 'CA$',
  EUR: '€',
  GBP: '£',
};

export default function InvestmentPanel({
  dealId,
  fundingTarget = 200000,
  committedAmount = 130000,
  existingCommitment = null,
  onCommitSuccess,
  className = '',
}: InvestmentPanelProps) {
  const [mode, setMode] = useState<'percent' | 'fixed'>('fixed');
  const [amountInput, setAmountInput] = useState<string>('10000');
  const [currency, setCurrency] = useState<'USD' | 'CAD' | 'EUR' | 'GBP'>('USD');
  const [commitment, setCommitment] = useState<InvestmentCommitmentData | null>(existingCommitment);
  const [error, setError] = useState<string | null>(null);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const remaining = Math.max(0, fundingTarget - committedAmount);

  const handleCommit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const val = parseFloat(amountInput);
    if (isNaN(val) || val <= 0) {
      setError('Please enter a valid positive investment amount.');
      return;
    }

    let calculatedAmount = val;
    let calculatedPercent = (val / fundingTarget) * 100;

    if (mode === 'percent') {
      if (val > 100) {
        setError('Percentage commitment cannot exceed 100%.');
        return;
      }
      calculatedPercent = val;
      calculatedAmount = (val / 100) * fundingTarget;
    } else {
      if (calculatedAmount > remaining && remaining > 0) {
        setError(`Fixed amount cannot exceed remaining target (${CURRENCY_SYMBOLS[currency]}${remaining.toLocaleString()}).`);
        return;
      }
    }

    setIsSubmitting(true);

    const newCommitment: InvestmentCommitmentData = {
      id: `commit_${Date.now()}`,
      dealId,
      investorId: 'user_investor_current',
      amount: calculatedAmount,
      percentage: Number(calculatedPercent.toFixed(2)),
      currency,
      status: 'pending',
      createdAt: new Date().toISOString(),
    };

    setTimeout(() => {
      setCommitment(newCommitment);
      setIsSubmitting(false);
      if (onCommitSuccess) onCommitSuccess(newCommitment);
    }, 400);
  };

  return (
    <div
      data-testid="investment-panel"
      className={`rounded-[14px] border border-white/[0.06] p-6 bg-[#0a0a0f]/80 backdrop-blur-[12px] shadow-2xl space-y-5 ${className}`}
    >
      <div className="flex items-center justify-between border-b border-white/5 pb-3">
        <div>
          <h3 className="text-sm font-black uppercase tracking-wider text-white flex items-center gap-2">
            <DollarSign className="w-4 h-4 text-[#34d399]" />
            <span>Submit Investment Commitment</span>
          </h3>
          <p className="text-xs text-slate-400 mt-0.5">
            Indicate your soft commitment to participate in this deal.
          </p>
        </div>
        <span className="text-[10px] font-extrabold uppercase px-2.5 py-1 rounded-[6px] bg-[#34d399]/20 text-[#34d399] border border-[#34d399]/30">
          Non-Binding
        </span>
      </div>

      {commitment ? (
        <div data-testid="existing-commitment-banner" className="p-4 rounded-[12px] bg-[#34d399]/10 border border-[#34d399]/30 text-slate-200 space-y-2">
          <div className="flex items-center gap-2 text-[#34d399] font-bold text-xs uppercase tracking-wider">
            <CheckCircle2 className="w-4 h-4" />
            <span>Commitment Recorded</span>
          </div>
          <p className="text-xs text-slate-300">
            You committed <span className="font-extrabold text-white font-mono">{CURRENCY_SYMBOLS[commitment.currency]}{commitment.amount.toLocaleString()}</span> ({commitment.percentage}% of target).
          </p>
          <div className="pt-2 flex items-center gap-3 text-[11px] text-slate-400">
            <span>Status: <strong className="text-amber-400 capitalize">{commitment.status}</strong></span>
            <button
              type="button"
              onClick={() => setCommitment(null)}
              className="text-xs font-bold text-[#34d399] underline hover:text-[#34d399]/80"
            >
              Modify commitment
            </button>
          </div>
        </div>
      ) : (
        <form onSubmit={handleCommit} className="space-y-4">
          {/* Glass Sliding Pill Toggle */}
          <div className="inline-flex p-1 bg-white/[0.03] backdrop-blur-[8px] border border-white/[0.06] rounded-[10px] w-fit">
            <button
              type="button"
              data-testid="mode-toggle-fixed"
              onClick={() => { setMode('fixed'); setError(null); }}
              className={`px-3.5 py-1.5 rounded-[8px] text-xs font-bold transition-all min-h-[34px] cursor-pointer ${
                mode === 'fixed'
                  ? 'bg-white/15 text-white font-extrabold shadow-sm border border-white/10'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              Fixed Amount ($)
            </button>
            <button
              type="button"
              data-testid="mode-toggle-percent"
              onClick={() => { setMode('percent'); setError(null); }}
              className={`px-3.5 py-1.5 rounded-[8px] text-xs font-bold transition-all min-h-[34px] cursor-pointer ${
                mode === 'percent'
                  ? 'bg-white/15 text-white font-extrabold shadow-sm border border-white/10'
                  : 'text-slate-400 hover:text-slate-200'
              }`}
            >
              % of Deal
            </button>
          </div>

          {/* Amount & Currency Grid */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div className="sm:col-span-2 space-y-1">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider block">
                {mode === 'fixed' ? 'Commitment Amount' : 'Target Percentage (%)'}
              </label>
              <div className="relative flex items-center">
                <span className="absolute left-3 text-slate-400 font-mono text-sm">
                  {mode === 'fixed' ? CURRENCY_SYMBOLS[currency] : '%'}
                </span>
                <input
                  type="number"
                  data-testid="commitment-amount-input"
                  value={amountInput}
                  onChange={(e) => setAmountInput(e.target.value)}
                  placeholder={mode === 'fixed' ? '10000' : '5'}
                  className="w-full pl-8 pr-4 py-2.5 bg-white/[0.03] border border-white/10 rounded-[10px] text-sm font-bold font-mono text-white focus:outline-none focus:border-[#34d399]/40 min-h-[44px]"
                />
              </div>
            </div>

            {/* Glass Currency Selector */}
            <div className="space-y-1">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider block">
                Currency
              </label>
              <select
                data-testid="currency-select"
                value={currency}
                onChange={(e) => setCurrency(e.target.value as any)}
                className="w-full px-3 py-2.5 bg-white/[0.03] border border-white/10 rounded-[10px] text-xs font-bold text-slate-200 focus:outline-none focus:border-[#34d399]/40 appearance-none min-h-[44px] cursor-pointer"
              >
                <option value="USD">USD ($)</option>
                <option value="CAD">CAD (CA$)</option>
                <option value="EUR">EUR (€)</option>
                <option value="GBP">GBP (£)</option>
              </select>
            </div>
          </div>

          {error && (
            <div data-testid="commitment-error-msg" className="p-3 rounded-[10px] bg-red-950/40 border border-red-500/30 text-red-400 text-xs font-bold flex items-center gap-2">
              <AlertCircle className="w-4 h-4 shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {/* Primary Teal Commit Button (rounded 10px, dark text) */}
          <button
            type="submit"
            data-testid="commit-submit-button"
            disabled={isSubmitting}
            className="w-full py-3 rounded-[10px] bg-[#34d399] hover:bg-[#34d399]/90 text-slate-950 font-black text-xs uppercase tracking-wider transition-all flex items-center justify-center gap-2 shadow-lg min-h-[48px] cursor-pointer disabled:opacity-50"
          >
            <span>Commit Investment</span>
            <ArrowRight className="w-4 h-4 text-slate-950" />
          </button>
        </form>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Mail, UserCheck, Send, X, CheckCircle2, AlertCircle } from 'lucide-react';

interface InviteModalProps {
  isOpen: boolean;
  onClose: () => void;
  dealId: string;
  dealAddress: string;
  creatorName?: string;
  onInviteSent?: (invitations: any[]) => void;
}

export default function InviteModal({
  isOpen,
  onClose,
  dealId,
  dealAddress,
  creatorName = 'Current Investor',
  onInviteSent,
}: InviteModalProps) {
  const [emailsInput, setEmailsInput] = useState('');
  const [shareBusinessCard, setShareBusinessCard] = useState(true);
  const [message, setMessage] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sentSuccess, setSentSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    const rawEmails = emailsInput
      .split(',')
      .map((e) => e.trim())
      .filter((e) => e.length > 0);

    if (rawEmails.length === 0) {
      setError('Please enter at least one valid email address.');
      return;
    }

    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const invalidEmails = rawEmails.filter((e) => !emailRegex.test(e));
    if (invalidEmails.length > 0) {
      setError(`Invalid email address: ${invalidEmails.join(', ')}`);
      return;
    }

    setIsSubmitting(true);

    const createdInvitations = rawEmails.map((email, idx) => ({
      id: `inv_${Date.now()}_${idx}`,
      dealId,
      creatorId: 'user_current',
      inviteeEmail: email,
      status: 'pending',
      shareBusinessCard,
      message: message.slice(0, 500),
      createdAt: new Date().toISOString(),
    }));

    setTimeout(() => {
      setIsSubmitting(false);
      setSentSuccess(true);
      if (onInviteSent) onInviteSent(createdInvitations);
      setTimeout(() => {
        setSentSuccess(false);
        onClose();
      }, 1500);
    }, 400);
  };

  return (
    <div
      data-testid="invite-modal-overlay"
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/80 backdrop-blur-[20px] animate-fade-in"
    >
      <div
        data-testid="invite-modal-content"
        className="rounded-[16px] border border-white/10 bg-[#0a0a0f]/95 backdrop-blur-[20px] shadow-2xl w-full max-w-lg p-6 space-y-5 relative"
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-white/5 pb-3">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 rounded-[8px] bg-[#34d399]/15 border border-[#34d399]/30 flex items-center justify-center text-[#34d399]">
              <Mail className="w-4 h-4" />
            </div>
            <h2 className="text-base font-bold text-white">Invite Investors to Deal</h2>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-white p-1.5 rounded-[8px] hover:bg-white/5 transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <p className="text-xs text-slate-400 font-mono">
          Deal: <strong className="text-slate-200">{dealAddress}</strong>
        </p>

        {sentSuccess ? (
          <div data-testid="invite-success-banner" className="p-6 text-center space-y-2 bg-[#34d399]/10 rounded-[12px] border border-[#34d399]/30">
            <CheckCircle2 className="w-8 h-8 text-[#34d399] mx-auto" />
            <h3 className="text-sm font-bold text-white">Invitations Sent!</h3>
            <p className="text-xs text-slate-300">
              Tokenized deal invitation links have been emailed successfully.
            </p>
          </div>
        ) : (
          <form onSubmit={handleSubmit} className="space-y-4">
            {/* Email Input */}
            <div className="space-y-1">
              <label className="text-[11px] font-bold text-slate-400 uppercase tracking-wider block">
                Investor Email Addresses (comma-separated)
              </label>
              <textarea
                data-testid="invite-emails-input"
                rows={2}
                value={emailsInput}
                onChange={(e) => setEmailsInput(e.target.value)}
                placeholder="investor1@example.com, partner@fund.com"
                className="w-full p-3 bg-white/[0.03] border border-white/10 rounded-[10px] text-xs font-mono text-slate-100 focus:outline-none focus:border-[#34d399]/40 resize-none min-h-[44px]"
              />
            </div>

            {/* Glass Switch Component: Share my business card (default ON) */}
            <div className="flex items-center justify-between p-3.5 rounded-[12px] bg-white/[0.03] border border-white/5">
              <div className="flex items-center gap-2.5">
                <UserCheck className="w-4 h-4 text-[#34d399]" />
                <div>
                  <span className="text-xs font-bold text-slate-200 block">Share my business card</span>
                  <span className="text-[10px] text-slate-400">Includes contact info & credentials</span>
                </div>
              </div>
              <button
                type="button"
                data-testid="share-card-toggle"
                onClick={() => setShareBusinessCard(!shareBusinessCard)}
                className={`w-11 h-6 rounded-full transition-colors p-0.5 relative cursor-pointer border ${
                  shareBusinessCard ? 'bg-[#34d399]/30 border-[#34d399]/50' : 'bg-white/10 border-white/10'
                }`}
              >
                <div
                  className={`w-4 h-4 rounded-full transition-transform ${
                    shareBusinessCard ? 'translate-x-5 bg-[#34d399]' : 'translate-x-0 bg-slate-400'
                  }`}
                />
              </button>
            </div>

            {/* Personal Message Textarea (max 500 chars) */}
            <div className="space-y-1">
              <div className="flex justify-between items-center text-[11px] text-slate-400">
                <label className="font-bold uppercase tracking-wider">Personal Message (Optional)</label>
                <span className="font-mono">{message.length}/500</span>
              </div>
              <textarea
                data-testid="invite-message-textarea"
                rows={3}
                maxLength={500}
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Join me in reviewing this high-ROI deal..."
                className="w-full p-3 bg-white/[0.03] border border-white/10 rounded-[10px] text-xs text-slate-100 focus:outline-none focus:border-[#34d399]/40 resize-none"
              />
            </div>

            {error && (
              <div data-testid="invite-error-msg" className="p-3 rounded-[10px] bg-red-950/40 border border-red-500/30 text-red-400 text-xs font-bold flex items-center gap-2">
                <AlertCircle className="w-4 h-4 shrink-0" />
                <span>{error}</span>
              </div>
            )}

            <div className="flex items-center justify-end gap-3 pt-2">
              <button
                type="button"
                onClick={onClose}
                className="px-4 py-2.5 rounded-[10px] bg-[#34d399]/[0.08] border border-[#34d399]/25 hover:bg-[#34d399]/15 text-[#34d399] text-xs font-bold uppercase transition-colors min-h-[44px]"
              >
                Cancel
              </button>

              <button
                type="submit"
                data-testid="send-invites-button"
                disabled={isSubmitting}
                className="px-5 py-2.5 rounded-[10px] bg-[#34d399] hover:bg-[#34d399]/90 text-slate-950 font-black text-xs uppercase tracking-wider transition-all flex items-center gap-2 shadow-lg min-h-[44px] cursor-pointer disabled:opacity-50"
              >
                <Send className="w-4 h-4 text-slate-950" />
                <span>Send Invitations</span>
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { UserCheck, Check, X, ShieldCheck, ExternalLink } from 'lucide-react';
import Link from 'next/link';
import { BusinessCard, BusinessCardShare } from '@/types/deals';

interface InviteeActionsProps {
  dealId: string;
  creatorName?: string;
  inviteeCard?: Partial<BusinessCard>;
  onDecline?: () => void;
  onExpressInterest?: (shareRecord: BusinessCardShare) => void;
  className?: string;
}

const DEFAULT_INVITEE_CARD: BusinessCard = {
  id: 'card_invitee_default',
  userId: 'user_invitee_current',
  name: 'Sarah Jenkins',
  email: 'sarah.j@acme-cap.com',
  phone: '(512) 555-0199',
  company: 'Acme Capital Group',
  title: 'Managing Partner',
  accreditedInvestorStatus: true,
  preferredMarkets: ['Austin, TX', 'Dallas, TX', 'Phoenix, AZ'],
  minInvestment: 25000,
  maxInvestment: 250000,
  isPublic: true,
  createdAt: new Date().toISOString(),
  updatedAt: new Date().toISOString(),
};

export default function InviteeActions({
  dealId,
  creatorName = 'The Deal Creator',
  inviteeCard = DEFAULT_INVITEE_CARD,
  onDecline,
  onExpressInterest,
  className = '',
}: InviteeActionsProps) {
  const [status, setStatus] = useState<'pending' | 'accepted' | 'declined'>('pending');
  const [isConfirmModalOpen, setIsConfirmModalOpen] = useState(false);

  const cardData: BusinessCard = { ...DEFAULT_INVITEE_CARD, ...inviteeCard };

  const handleDecline = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setStatus('declined');
    if (onDecline) onDecline();
  };

  const handleConfirmInterest = () => {
    const shareRecord: BusinessCardShare = {
      id: `share_${Date.now()}`,
      dealId,
      senderUserId: cardData.userId,
      recipientUserId: 'user_creator_id',
      businessCardData: { ...cardData },
      createdAt: new Date().toISOString(),
    };

    setStatus('accepted');
    setIsConfirmModalOpen(false);
    if (onExpressInterest) onExpressInterest(shareRecord);
  };

  if (status === 'declined') {
    return null;
  }

  if (status === 'accepted') {
    return (
      <div data-testid="invite-accepted-badge" className="p-2 rounded-[8px] bg-[#34d399]/15 border border-[#34d399]/30 text-[#34d399] text-xs font-bold flex items-center gap-1.5">
