'use client';

import React, { useState, useEffect, useRef, useCallback } from 'react';
import {
  Upload, FileText, FilePen, Building2, X, CheckCircle2,
  Clock, AlertCircle, Download, ExternalLink, Plus, Folder,
} from 'lucide-react';
import {
  collection, query, where, onSnapshot, addDoc, updateDoc,
  doc, serverTimestamp, deleteDoc,
} from 'firebase/firestore';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { db, storage } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import { useProjectStore } from '@/store/projectStore';
import toast from 'react-hot-toast';
import type { DealDocument, DealDocumentCategory, ESignStatus } from '@/types/schema';

const CATEGORIES: { key: DealDocumentCategory; label: string; icon: React.ReactNode }[] = [
  { key: 'Offer Letter',       label: 'Offer Letters',      icon: <FilePen className="w-4 h-4" /> },
  { key: 'Signed Deed',        label: 'Signed Deeds',       icon: <FileText className="w-4 h-4" /> },
  { key: 'Lender Form',        label: 'Lender Forms',       icon: <Building2 className="w-4 h-4" /> },
  { key: 'Purchase Agreement', label: 'Purchase Agreements', icon: <FileText className="w-4 h-4" /> },
  { key: 'Inspection Report',  label: 'Inspection Reports', icon: <FileText className="w-4 h-4" /> },
  { key: 'Insurance Binder',   label: 'Insurance',          icon: <FileText className="w-4 h-4" /> },
  { key: 'Other',              label: 'Other',              icon: <Folder className="w-4 h-4" /> },
];

const ESIGN_CONFIG: Record<ESignStatus, { label: string; color: string; icon: React.ReactNode }> = {
  'Not Required':       { label: 'No eSign Required', color: 'text-text-secondary bg-bg-primary border-border-accent',       icon: <FileText className="w-3 h-3" /> },
  'Awaiting Signature': { label: 'Awaiting Signature', color: 'text-amber-700 bg-amber-50 border-amber-200',   icon: <Clock className="w-3 h-3" /> },
  'Signed':             { label: 'Signed',             color: 'text-pw-success bg-pw-success-container border-pw-success-border', icon: <CheckCircle2 className="w-3 h-3" /> },
  'Declined':           { label: 'Declined',           color: 'text-red-700 bg-red-50 border-red-200',          icon: <AlertCircle className="w-3 h-3" /> },
};

function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1048576) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1048576).toFixed(1)} MB`;
}

export default function DocumentHub() {
  const { user, profile } = useAuth();
  const projects = useProjectStore(s => s.projects);
  const currentProject = useProjectStore(s => s.currentProject);
  const setDeal = useProjectStore(s => s.setDeal);

  const [selectedProjectId, setSelectedProjectId] = useState<string>(currentProject?.id || projects[0]?.id || '');
  const [activeCategory, setActiveCategory] = useState<DealDocumentCategory>('Offer Letter');
  const [documents, setDocuments] = useState<DealDocument[]>([]);
  const [isDragging, setIsDragging] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [showUploadForm, setShowUploadForm] = useState(false);
  const [uploadForm, setUploadForm] = useState({
    category: 'Offer Letter' as DealDocumentCategory,
    notes: '',
    eSignStatus: 'Not Required' as ESignStatus,
  });
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [pendingFile, setPendingFile] = useState<File | null>(null);

  // Sync selectedProjectId with store's currentProject
  useEffect(() => {
    if (currentProject?.id && currentProject.id !== selectedProjectId) {
      setSelectedProjectId(currentProject.id);
    }
  }, [currentProject]);

  // Firestore real-time subscription
  useEffect(() => {
    if (!selectedProjectId) return;
    const q = query(
      collection(db, 'projects', selectedProjectId, 'documents'),
    );
    const unsub = onSnapshot(q, snap => {
      setDocuments(snap.docs.map(d => ({ id: d.id, ...d.data() })) as DealDocument[]);
    });
    return unsub;
  }, [selectedProjectId]);

  const filtered = documents.filter(d => d.category === activeCategory);

  const handleDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const handleDragLeave = useCallback(() => setIsDragging(false), []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    if (file) {
      setPendingFile(file);
      setUploadForm(f => ({ ...f, category: activeCategory }));
      setShowUploadForm(true);
    }
  }, [activeCategory]);

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setPendingFile(file);
      setUploadForm(f => ({ ...f, category: activeCategory }));
      setShowUploadForm(true);
    }
  };

  const handleUpload = async () => {
    if (!pendingFile || !selectedProjectId || !user) return;
    setUploading(true);
    setUploadProgress(0);
    try {
      // 1. Upload binary to Firebase Storage
      const safeFileName = pendingFile.name.replace(/[^a-zA-Z0-9._-]/g, '_');
      const storagePath = `projects/${selectedProjectId}/documents/${Date.now()}_${safeFileName}`;
      const storageRef = ref(storage, storagePath);
      const uploadTask = uploadBytesResumable(storageRef, pendingFile, {
        contentType: pendingFile.type,
      });

      // Track progress
      await new Promise<void>((resolve, reject) => {
        uploadTask.on(
          'state_changed',
          (snapshot) => {
            const pct = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
            setUploadProgress(pct);
          },
          reject,
          resolve,
        );
      });

      // 2. Get the permanent download URL
      const fileUrl = await getDownloadURL(uploadTask.snapshot.ref);

      // 3. Write Firestore metadata with the real fileUrl
      const docData: Omit<DealDocument, 'id'> = {
        projectId: selectedProjectId,
        category: uploadForm.category,
        fileName: pendingFile.name,
        fileSize: pendingFile.size,
        mimeType: pendingFile.type,
        fileUrl,
        storagePath,
        uploadedByUid: user.uid,
        uploadedByName: user.displayName || user.email || 'User',
        uploadedAt: new Date(),
        eSignStatus: uploadForm.eSignStatus,
        notes: uploadForm.notes,
      };
      await addDoc(collection(db, 'projects', selectedProjectId, 'documents'), {
        ...docData,
        uploadedAt: serverTimestamp(),
      });

      toast.success(`${pendingFile.name} uploaded`);
      setShowUploadForm(false);
      setPendingFile(null);
      setUploadProgress(0);
      setUploadForm({ category: 'Offer Letter', notes: '', eSignStatus: 'Not Required' });
    } catch (err) {
      console.error('[DocumentHub] Upload failed:', err);
      toast.error('Upload failed. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const handleRequestESign = async (docId: string) => {
    if (!selectedProjectId) return;
    try {
      await updateDoc(doc(db, 'projects', selectedProjectId, 'documents', docId), {
        eSignStatus: 'Awaiting Signature',
        eSignRequestedAt: serverTimestamp(),
      });
      toast.success('eSign request sent');
    } catch {
      toast.error('Failed to request eSign');
    }
  };

  const handleMarkSigned = async (docId: string) => {
    if (!selectedProjectId) return;
    try {
      await updateDoc(doc(db, 'projects', selectedProjectId, 'documents', docId), {
        eSignStatus: 'Signed',
        eSignedAt: serverTimestamp(),
        eSignedByName: user?.displayName || user?.email || 'User',
      });
      toast.success('Document marked as signed');
    } catch {
      toast.error('Failed to update signature status');
    }
  };

  const handleDelete = async (docId: string) => {
    if (!selectedProjectId) return;
    try {
      await deleteDoc(doc(db, 'projects', selectedProjectId, 'documents', docId));
      toast.success('Document removed');
    } catch {
      toast.error('Failed to delete document');
    }
  };

  const selectedProject = projects.find(p => p.id === selectedProjectId);

  return (
    <div className="space-y-6">
      {/* Header + Deal Selector */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-medium text-text-primary">Document Hub</h3>
          <p className="text-sm text-text-secondary">Offer letters, deeds, lender forms — with eSign tracking.</p>
        </div>
        <div className="flex items-center gap-3">
          {projects.length > 0 && (
            <select
              className="border border-border-accent rounded-md text-sm py-2 pl-3 pr-8 focus:ring-[#454955] focus:border-[#454955] bg-bg-surface"
              value={selectedProjectId}
              onChange={e => {
                setSelectedProjectId(e.target.value);
                const p = projects.find(x => x.id === e.target.value);
                if (p) setDeal(p);
              }}
            >
              <option value="" disabled>Select property…</option>
              {projects.map(p => (
                <option key={p.id} value={p.id}>{p.propertyName}</option>
              ))}
            </select>
          )}
          {selectedProject?.driveFolders?.parentFolderUrl && (
            <a
              href={selectedProject.driveFolders.parentFolderUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-1.5 text-xs font-medium text-blue-600 hover:text-blue-800 border border-blue-200 rounded-md px-3 py-2 bg-blue-50 hover:bg-blue-100 transition"
            >
              <ExternalLink className="w-3.5 h-3.5" />
              Open Drive Folder
            </a>
          )}
          <button
            onClick={() => { setUploadForm(f => ({ ...f, category: activeCategory })); setShowUploadForm(true); }}
            className="inline-flex items-center gap-2 px-4 py-2 bg-gray-900 text-white text-sm font-medium rounded-lg hover:bg-gray-700 transition"
          >
            <Plus className="w-4 h-4" />
            Upload
          </button>
        </div>
      </div>

      {/* Category Tabs */}
      <div className="border-b border-border-accent overflow-x-auto">
        <nav className="-mb-px flex space-x-6 min-w-max">
          {CATEGORIES.map(cat => (
            <button
              key={cat.key}
              onClick={() => setActiveCategory(cat.key)}
              className={`flex items-center gap-2 whitespace-nowrap border-b-2 py-3 px-1 text-sm font-medium transition ${
                activeCategory === cat.key
                  ? 'border-gray-900 text-text-primary'
                  : 'border-transparent text-text-secondary hover:text-text-primary hover:border-border-accent'
              }`}
            >
              {cat.icon}
              {cat.label}
              {documents.filter(d => d.category === cat.key).length > 0 && (
                <span className="ml-1 bg-bg-primary text-text-secondary text-xs font-semibold px-1.5 py-0.5 rounded-full">
                  {documents.filter(d => d.category === cat.key).length}
                </span>
              )}
            </button>
          ))}
        </nav>
      </div>

      {/* Upload Form Modal */}
      {showUploadForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="bg-bg-surface rounded-xl shadow-2xl border border-border-accent w-full max-w-md mx-4 p-6">
            <div className="flex items-center justify-between mb-5">
              <h4 className="text-base font-semibold text-text-primary">Upload Document</h4>
              <button onClick={() => { setShowUploadForm(false); setPendingFile(null); }} className="text-text-secondary hover:text-text-secondary">
                <X className="w-5 h-5" />
              </button>
            </div>

            {pendingFile ? (
              <div className="mb-4 p-3 bg-bg-primary border border-border-accent rounded-lg flex items-center gap-3">
                <FileText className="w-8 h-8 text-text-secondary flex-shrink-0" />
                <div className="min-w-0">
                  <p className="text-sm font-medium text-text-primary truncate">{pendingFile.name}</p>
                  <p className="text-xs text-text-secondary">{formatBytes(pendingFile.size)}</p>
                </div>
                <button onClick={() => setPendingFile(null)} className="ml-auto text-text-secondary hover:text-red-500">
                  <X className="w-4 h-4" />
                </button>
              </div>
            ) : (
              <label className="block mb-4 cursor-pointer relative group">
                <div className="relative rounded-lg p-6 text-center transition-all bg-surface-container/30 backdrop-blur-xl border-t border-l border-white/10 shadow-md overflow-hidden">
                  <div className={`absolute inset-2 border border-dashed rounded transition-all duration-300 pointer-events-none border-outline-variant/40 group-hover:border-primary/40 group-hover:bg-primary/5`} />
                  <div className="relative z-10">
                    <Upload className="w-6 h-6 text-text-secondary mx-auto mb-2 group-hover:scale-110 transition-transform" />
                    <p className="text-sm text-text-secondary">Click to select a file</p>
                  </div>
                </div>
                <input type="file" className="hidden" onChange={handleFileSelect} />
              </label>
            )}

            <div className="space-y-4">
              <div>
                <label className="block text-xs font-medium text-text-primary mb-1">Category</label>
                <select
                  className="w-full border border-border-accent rounded-md text-sm py-2 px-3 focus:ring-[#454955] focus:border-[#454955]"
                  value={uploadForm.category}
                  onChange={e => setUploadForm(f => ({ ...f, category: e.target.value as DealDocumentCategory }))}
                >
                  {CATEGORIES.map(c => <option key={c.key} value={c.key}>{c.label}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-text-primary mb-1">eSignature Required?</label>
                <select
                  className="w-full border border-border-accent rounded-md text-sm py-2 px-3 focus:ring-[#454955] focus:border-[#454955]"
                  value={uploadForm.eSignStatus}
                  onChange={e => setUploadForm(f => ({ ...f, eSignStatus: e.target.value as ESignStatus }))}
                >
                  <option value="Not Required">Not Required</option>
                  <option value="Awaiting Signature">Needs Signature</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium text-text-primary mb-1">Notes (optional)</label>
                <textarea
                  rows={2}
                  className="w-full border border-border-accent rounded-md text-sm py-2 px-3 focus:ring-[#454955] focus:border-[#454955] resize-none"
                  placeholder="Any additional context…"
                  value={uploadForm.notes}
                  onChange={e => setUploadForm(f => ({ ...f, notes: e.target.value }))}
                />
              </div>
            </div>

            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={() => { setShowUploadForm(false); setPendingFile(null); }}
                className="px-4 py-2 text-sm text-text-primary border border-border-accent rounded-lg hover:bg-bg-primary transition"
              >
                Cancel
              </button>
              <button
                onClick={handleUpload}
                disabled={!pendingFile || uploading}
                className="px-4 py-2 rounded-lg text-sm font-medium disabled:opacity-50 luminous-button min-w-[120px]"
              >
                {uploading ? `${uploadProgress}%` : 'Save Document'}
              </button>
            </div>

            {/* Upload progress bar */}
            {uploading && (
              <div className="mt-3 h-1.5 w-full rounded-full overflow-hidden" style={{ background: 'rgba(255,255,255,0.08)' }}>
                <div
                  className="h-full rounded-full transition-all duration-300"
                  style={{
                    width: `${uploadProgress}%`,
                    background: 'linear-gradient(90deg, #454955, #454955)',
                    boxShadow: '0 0 8px rgba(69,73,85,0.4)',
                  }}
                />
              </div>
            )}
          </div>
        </div>
      )}

      <div
        onDragOver={handleDragOver}
        onDragLeave={handleDragLeave}
        onDrop={handleDrop}
        className="upload-zone relative min-h-[300px] rounded-xl transition-all bg-surface-container/30 backdrop-blur-xl border-t border-l border-white/10 shadow-lg overflow-hidden group"
      >
        {/* Inner border indicator */}
        {(filtered.length === 0 || isDragging) && (
          <div className={`absolute inset-3 border-2 border-dashed rounded-lg transition-all duration-300 pointer-events-none ${
            isDragging 
              ? 'border-primary bg-primary/10 z-20' 
              : 'border-outline-variant/40 group-hover:border-primary/40 group-hover:bg-primary/5'
          }`} />
        )}

        {isDragging && (
          <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-30 bg-surface-container/40 backdrop-blur-sm">
            <div className="w-14 h-14 mb-2 rounded-full bg-surface-container-highest flex items-center justify-center text-primary shadow-lg shadow-primary/10 animate-bounce">
              <Upload className="w-6 h-6" />
            </div>
            <p className="text-sm font-semibold text-text-primary">Drop to upload</p>
          </div>
        )}

        {filtered.length === 0 ? (
          <div className="relative z-10 flex flex-col items-center justify-center min-h-[300px] text-center p-6">
            <div className="w-14 h-14 mb-3 rounded-full bg-surface-container-highest flex items-center justify-center text-text-secondary shadow-md group-hover:scale-110 transition-transform duration-300">
              <FileText className="w-6 h-6" />
            </div>
            <p className="text-sm font-medium text-text-secondary">No {CATEGORIES.find(c => c.key === activeCategory)?.label} uploaded yet</p>
            <p className="text-xs text-text-secondary mt-1">Drag & drop files here or use the Upload button</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-100">
            {filtered.map(doc => {
              const sign = ESIGN_CONFIG[doc.eSignStatus];
              return (
                <div key={doc.id} className="flex items-center gap-4 p-4 hover:bg-bg-surface transition group">
                  <div className="w-10 h-10 rounded-lg bg-bg-primary flex items-center justify-center flex-shrink-0">
                    <FileText className="w-5 h-5 text-text-secondary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-text-primary truncate">{doc.fileName}</p>
                    <div className="flex items-center gap-3 mt-0.5">
                      <span className="text-xs text-text-secondary">
                        {doc.uploadedByName} · {doc.uploadedAt ? new Date((doc.uploadedAt as any)?.seconds ? (doc.uploadedAt as any).seconds * 1000 : doc.uploadedAt).toLocaleDateString() : ''}
                      </span>
                      {doc.fileSize && <span className="text-xs text-text-secondary">{formatBytes(doc.fileSize)}</span>}
                    </div>
                    {doc.notes && <p className="text-xs text-text-secondary mt-1 truncate">{doc.notes}</p>}
                  </div>

                  {/* eSign Status Badge */}
                  <div className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full border text-xs font-medium ${sign.color}`}>
                    {sign.icon}
                    {sign.label}
                  </div>

                  {/* Actions */}
                  <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition">
                    {doc.eSignStatus === 'Not Required' && (
                      <button
                        onClick={() => handleRequestESign(doc.id)}
                        title="Request eSignature"
                        className="p-1.5 text-text-secondary hover:text-[#454955] rounded-md hover:bg-[#454955]/10 transition"
                      >
                        <FilePen className="w-4 h-4" />
                      </button>
                    )}
                    {doc.eSignStatus === 'Awaiting Signature' && (
                      <button
                        onClick={() => handleMarkSigned(doc.id)}
                        title="Mark as Signed"
                        className="p-1.5 text-text-secondary hover:text-pw-success rounded-md hover:bg-pw-success-container transition"
                      >
                        <CheckCircle2 className="w-4 h-4" />
                      </button>
                    )}
                    {doc.fileUrl && (
                      <a
                        href={doc.fileUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                        title="Download"
                        className="p-1.5 text-text-secondary hover:text-blue-600 rounded-md hover:bg-blue-50 transition"
                      >
                        <Download className="w-4 h-4" />
                      </a>
                    )}
                    <button
                      onClick={() => handleDelete(doc.id)}
                      title="Remove"
                      className="p-1.5 text-text-secondary hover:text-red-500 rounded-md hover:bg-red-50 transition"
                    >
                      <X className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* eSign Summary Footer */}
      {documents.length > 0 && (
        <div className="flex items-center gap-6 text-xs text-text-secondary pt-2 border-t border-border-accent">
          <span className="font-medium text-text-primary">{documents.length} total documents</span>
          {(['Awaiting Signature', 'Signed', 'Declined'] as ESignStatus[]).map(s => {
            const count = documents.filter(d => d.eSignStatus === s).length;
            if (!count) return null;
            const cfg = ESIGN_CONFIG[s];
            return (
              <span key={s} className={`inline-flex items-center gap-1 font-medium ${cfg.color.split(' ')[0]}`}>
                {cfg.icon} {count} {s}
              </span>
            );
          })}
        </div>
      )}
    </div>
  );
}

