  Sliders,
  ChevronDown,
  ChevronUp,
  BarChart3,
  Calendar,
  CheckCircle2,
  AlertTriangle,
  ArrowRight,
  Info,
  Layers,
} from 'lucide-react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip as RechartsTooltip,
  Legend,
} from 'recharts';
import toast from 'react-hot-toast';
import {
  calculateRentalDeal,
  calculateFlipDeal,
  calculateBRRRRDeal,
  RentalCalcOutputs,
  FlipCalcOutputs,
  BRRRRCalcOutputs,
} from '@/lib/deal-analyzer/calcEngine';
