                                      className="w-full h-10 px-3 rounded-lg font-mono text-xs bg-white/5 border border-white/10 text-white"
                                    />
                                  </div>
                                  <div>
                                    <label className="text-xs text-slate-300 font-bold block mb-1">CapEx Reserve Fund (%)</label>
                                    <input
