                                    />
                                  </div>
                                </>
                              );
                            })()}
                          </div>
                        </div>
                      )}
                    </div>
                  );
                }

                // ── COMPOSITE FIELD: MONTHLY HOLDING COSTS STACK ──
                if (key === 'monthlyHoldingCosts') {
                  const holdingVal = Number(formData.monthlyHoldingCosts || getFieldDefaultValue('monthlyHoldingCosts', strategy ?? undefined));
