          </div>

          {/* Amount */}
          <div>
            <label className="text-[9px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1 block flex items-center gap-1">
              <DollarSign className="w-3 h-3 text-[#7A9EAA]" /> Amount
            </label>
