'use client';

import React, { useMemo } from 'react';
import { DollarSign, Landmark, RefreshCw, Key, ShieldCheck, Download, CheckCircle } from 'lucide-react';
import toast from 'react-hot-toast';

interface FinalAccountingStepProps {
  initialData: any;
  strategy: string;
  onComplete: () => Promise<void>;
}

export default function FinalAccountingStep({
  initialData,
  strategy,
  onComplete,
}: FinalAccountingStepProps) {
  const f = initialData?.financials || {};

  // Financial values
  const purchasePrice = f.purchasePrice / 100 || 220000;
  const rehabCosts = f.projectedRehabCost / 100 || 45000;
  const holdingCosts = f.annualDebtService / 100 || 12000;

  const salePrice = f.exitListPrice || (initialData?.estimatedARV || f.estimatedARV || 320000);
  const currentLoanPayoff = f.loanAmount / 100 || 180000;

  // Calculators
  const sellSummary = useMemo(() => {
    const grossProfit = salePrice - purchasePrice - rehabCosts - holdingCosts;
    const commission = salePrice * 0.06;
    const closingCosts = salePrice * 0.02;
    const netProfit = grossProfit - commission - closingCosts;

    const cashInvested = f.totalCashInvested / 100 || 80000;
    const totalReturn = (netProfit / cashInvested) * 100;

    // Capital stack waterfall
    const lpReturn = cashInvested * 1.08; // LP gets initial capital + 8% preferred return
    const leadInvestorPromote = Math.max(0, (netProfit - (lpReturn - cashInvested)) * 0.2); // 20% promote
    return {
      grossProfit,
      netProfit,
      totalReturn,
      lpReturn,
      leadInvestorPromote,
      lenderPayoff: currentLoanPayoff,
    };
  }, [salePrice, purchasePrice, rehabCosts, holdingCosts, currentLoanPayoff, f.totalCashInvested]);

  const refiSummary = useMemo(() => {
    const cashOut = f.exitNewLoanAmount || 240000;
    const cashReceived = cashOut - currentLoanPayoff;
    const payment = (cashOut * 0.065) / 12;
    return {
      cashReceived,
      payment,
    };
  }, [f.exitNewLoanAmount, currentLoanPayoff]);

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 4: Final Accounting</h3>
        <p className="text-xs text-slate-400 font-medium">Verify terminal returns distribution waterfall and download tax packet before archiving.</p>
      </div>

      {strategy === 'Sell' && (
        <div className="space-y-4">
          {/* Sale Summary returns cards */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <div className="bg-white/5 p-3 rounded-xl">
              <p className="text-[8px] uppercase tracking-wider text-slate-500">Gross Profit</p>
              <p className="text-sm font-bold text-white">${Math.round(sellSummary.grossProfit).toLocaleString()}</p>
            </div>
            <div className="bg-white/5 p-3 rounded-xl">
              <p className="text-[8px] uppercase tracking-wider text-slate-500">Net Profit</p>
              <p className="text-sm font-bold text-white">${Math.round(sellSummary.netProfit).toLocaleString()}</p>
            </div>
            <div className="bg-white/5 p-3 rounded-xl">
              <p className="text-[8px] uppercase tracking-wider text-slate-500">Total Return</p>
              <p className="text-sm font-bold text-emerald-400">{sellSummary.totalReturn.toFixed(1)}%</p>
            </div>
            <div className="bg-white/5 p-3 rounded-xl">
              <p className="text-[8px] uppercase tracking-wider text-slate-500">Hold Period</p>
              <p className="text-sm font-bold text-white">325 Days</p>
            </div>
          </div>

          {/* Capital Stack Waterfall stacked bar */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-4">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Capital stack Payout Waterfall</h4>
            <div className="w-full h-5 bg-white/5 rounded-md overflow-hidden flex text-[9px] font-bold text-black text-center">
              <div className="bg-slate-400 h-full flex items-center justify-center" style={{ width: '55%' }}>
                Lender Payoff (${Math.round(sellSummary.lenderPayoff / 1000)}k)
              </div>
              <div className="bg-[#7A9EAA] h-full flex items-center justify-center" style={{ width: '30%' }}>
                LP Returns (${Math.round(sellSummary.lpReturn / 1000)}k)
              </div>
              <div className="bg-emerald-400 h-full flex items-center justify-center" style={{ width: '15%' }}>
                LeadInvestor Promote (${Math.round(sellSummary.leadInvestorPromote / 1000)}k)
              </div>
            </div>
          </div>
        </div>
      )}

      {strategy === 'Refinance' && (
        <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
          <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Refinance closing summary</h4>
          <div className="grid grid-cols-2 gap-4 text-xs">
            <div>
              <p className="text-slate-500 uppercase text-[8px]">Cash Received</p>
              <p className="text-sm font-bold text-white">${Math.round(refiSummary.cashReceived).toLocaleString()}</p>
            </div>
            <div>
              <p className="text-slate-500 uppercase text-[8px]">New Payment</p>
              <p className="text-sm font-bold text-white">${Math.round(refiSummary.payment).toLocaleString()}/mo</p>
            </div>
          </div>
          <p className="text-[11px] text-slate-400 mt-2 leading-relaxed">
            Upon complete exit confirmation, this asset continues operations under holding with updated financing variables.
          </p>
        </div>
      )}

      {strategy === 'Hold' && (
        <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-2 text-xs">
          <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Annual Hold review Summary</h4>
          <p className="text-slate-400 leading-relaxed">
            All reviews completed. Compounded metrics will be recalculated annually at the close of the operations cycle.
          </p>
        </div>
      )}

      {/* Tax generation packet block */}
      <div className="p-4 border border-[#7A9EAA]/25 bg-[#7A9EAA]/5 rounded-xl flex items-center justify-between gap-4">
        <div className="space-y-1">
          <p className="text-xs font-bold text-white">Generate CPA Tax packet</p>
          <p className="text-[11px] text-slate-400">Downloads 1099-S info, capitalized basis summary, and estimated short vs. long term capital gains.</p>
        </div>

        <button
          onClick={onComplete}
          className="px-4 py-2 bg-white/10 hover:bg-white/15 text-white font-bold uppercase tracking-wider text-[10px] rounded-lg transition-all flex items-center gap-1 shrink-0"
        >
          <Download className="w-3.5 h-3.5" /> Download Tax Packet
        </button>
      </div>

      <div className="flex justify-between pt-4 border-t border-white/5">
        <span />
        <button
          onClick={onComplete}
          className="px-6 py-2.5 bg-emerald-500 text-black hover:opacity-90 font-extrabold uppercase tracking-wider text-[11px] rounded-lg transition-opacity flex items-center gap-1.5 shadow-[0_0_15px_rgba(16,185,129,0.3)]"
        >
          Complete Exit & Archive <CheckCircle className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { Project } from '@/types/schema';
import { computeAutopsyMetrics } from '@/lib/math/calculatorUtils';
import { TrendingUp, TrendingDown, DollarSign, Activity } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Final Profit Visualization

   Renders the ultimate financial outcome of a sold or to-be-sold
   project. Aggregates "All-In Cost" and visualizes the
   net profit as the largest typographical element, supported
   by a clean, thin-line proportional stacked bar chart.
   ═══════════════════════════════════════════════════════ */

interface FinalProfitVisualizationProps {
  deal: Project;
}

export default function FinalProfitVisualization({ deal }: FinalProfitVisualizationProps) {
  const metrics = useMemo(() => computeAutopsyMetrics(deal), [deal]);

  const allInCost = metrics.totalCostBasis;
  const finalSalePrice = metrics.grossSalePrice;
  const netProfit = metrics.netProfit;
  const isProfit = netProfit >= 0;

  // For visual proportioning:
  // If sale price > all in cost, the full bar is sale price.
  // If sale price < all in cost, the full bar is all in cost.
  const maxBarValue = Math.max(finalSalePrice, allInCost);

  // Percentages for the thin-line bar chart
  const pctPurchase = maxBarValue > 0 ? (metrics.purchasePrice / maxBarValue) * 100 : 0;
  const pctAcquisition = maxBarValue > 0 ? (metrics.acquisitionCosts / maxBarValue) * 100 : 0;
  const pctRehab = maxBarValue > 0 ? (metrics.actualRehabCost / maxBarValue) * 100 : 0;
  const pctHolding = maxBarValue > 0 ? (metrics.holdingCosts / maxBarValue) * 100 : 0;
  const pctSelling = maxBarValue > 0 ? (metrics.sellClosingCosts / maxBarValue) * 100 : 0;
  const pctProfit = maxBarValue > 0 && isProfit ? (netProfit / maxBarValue) * 100 : 0;
  const pctLoss = maxBarValue > 0 && !isProfit ? (Math.abs(netProfit) / maxBarValue) * 100 : 0;

  const fmtCurrency = (val: number) => {
    return val.toLocaleString('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0, maximumFractionDigits: 0 });
  };

  const fmtPercent = (val: number) => {
    return val.toFixed(1) + '%';
  };

  return (
    <div className="glass-card border border-pw-border overflow-hidden bg-bg-surface">
      {/* ── Banner Header ── */}
      <div className="bg-bg-surface/80 px-6 py-4 flex items-center justify-between border-b border-pw-border backdrop-blur-md">
        <div className="flex items-center gap-2 text-text-primary">
          <Activity className="w-5 h-5 text-pw-accent" />
          <h2 className="text-xs font-black uppercase tracking-[0.2em]">Final Project Outcome</h2>
        </div>
        <div className="flex items-center gap-2">
          <span className="text-[10px] font-black text-text-secondary uppercase tracking-[0.15em]">
            Margin: {fmtPercent(metrics.profitMargin)}
          </span>
        </div>
      </div>

      {/* ── Hero Net Profit Display ── */}
      <div className="p-10 flex flex-col items-center justify-center border-b border-pw-border bg-pw-bg/20">
        <p className="text-[10px] font-black text-text-secondary uppercase tracking-[0.3em] mb-2">Net Profit Output</p>
        <div className="flex items-center justify-center gap-4">
          {isProfit ? (
            <TrendingUp className="w-10 h-10 text-pw-accent" />
          ) : (
            <TrendingDown className="w-10 h-10 text-red-500" />
          )}
          <h1 className={`text-6xl md:text-8xl font-black font-mono tracking-tighter ${isProfit ? 'text-pw-accent' : 'text-red-500'}`}>
            {fmtCurrency(netProfit)}
          </h1>
        </div>

        <div className="flex items-center gap-8 mt-8">
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-widest mb-1">Final Sale Price</span>
            <span className="text-xl font-black text-text-primary font-mono">{fmtCurrency(finalSalePrice)}</span>
          </div>
          <div className="h-8 w-px bg-pw-border" />
          <div className="flex flex-col items-center">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-widest mb-1">All-In Cost</span>
            <span className="text-xl font-black text-text-primary font-mono">{fmtCurrency(allInCost)}</span>
          </div>
        </div>
      </div>

      {/* ── Thin-Line Bar Chart ── */}
      <div className="p-8">
        <h3 className="text-[10px] font-black text-text-secondary uppercase tracking-widest mb-4">Capital Stack & Profit Visualization</h3>

        <div className="relative h-4 w-full bg-pw-border/30 overflow-hidden flex mb-6">
          {/* Stacked segments for All-In Cost */}
          {pctPurchase > 0 && <div className="h-full bg-pw-muted/20 transition-all duration-500" style={{ width: `${pctPurchase}%` }} title={`Purchase: ${fmtCurrency(metrics.purchasePrice)}`} />}
          {pctAcquisition > 0 && <div className="h-full bg-pw-muted/40 transition-all duration-500" style={{ width: `${pctAcquisition}%` }} title={`Acq: ${fmtCurrency(metrics.acquisitionCosts)}`} />}
          {pctRehab > 0 && <div className="h-full bg-pw-muted/60 transition-all duration-500" style={{ width: `${pctRehab}%` }} title={`Rehab: ${fmtCurrency(metrics.actualRehabCost)}`} />}
          {pctHolding > 0 && <div className="h-full bg-pw-muted/80 transition-all duration-500" style={{ width: `${pctHolding}%` }} title={`Holding: ${fmtCurrency(metrics.holdingCosts)}`} />}
          {pctSelling > 0 && <div className="h-full bg-pw-muted transition-all duration-500" style={{ width: `${pctSelling}%` }} title={`Marketing/Selling: ${fmtCurrency(metrics.sellClosingCosts)}`} />}

          {/* Net Profit Segment (if profit) */}
          {isProfit && pctProfit > 0 && (
            <div className="h-full bg-pw-accent transition-all duration-500" style={{ width: `${pctProfit}%` }} title={`Net Profit: ${fmtCurrency(netProfit)}`} />
          )}
          {/* Net Loss Segment (if loss) */}
          {!isProfit && pctLoss > 0 && (
            <div className="h-full bg-red-500 transition-all duration-500" style={{ width: `${pctLoss}%` }} title={`Net Loss: ${fmtCurrency(netProfit)}`} />
          )}
        </div>

        {/* Legend Grid */}
        <div className="grid grid-cols-2 md:grid-cols-6 gap-4">
          <div className="flex flex-col gap-1 border-l-2 border-pw-muted/20 pl-3">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-wider">Purchase</span>
            <span className="text-sm font-bold font-mono text-text-primary">{fmtCurrency(metrics.purchasePrice)}</span>
          </div>
          <div className="flex flex-col gap-1 border-l-2 border-pw-muted/40 pl-3">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-wider">Acquisition</span>
            <span className="text-sm font-bold font-mono text-text-primary">{fmtCurrency(metrics.acquisitionCosts)}</span>
          </div>
          <div className="flex flex-col gap-1 border-l-2 border-pw-muted/60 pl-3">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-wider">Rehab</span>
            <span className="text-sm font-bold font-mono text-text-primary">{fmtCurrency(metrics.actualRehabCost)}</span>
          </div>
          <div className="flex flex-col gap-1 border-l-2 border-pw-muted/80 pl-3">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-wider">Holding</span>
            <span className="text-sm font-bold font-mono text-text-primary">{fmtCurrency(metrics.holdingCosts)}</span>
          </div>
          <div className="flex flex-col gap-1 border-l-2 border-pw-muted pl-3">
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-wider">Selling</span>
            <span className="text-sm font-bold font-mono text-text-primary">{fmtCurrency(metrics.sellClosingCosts)}</span>
          </div>
          <div className={`flex flex-col gap-1 border-l-2 pl-3 ${isProfit ? 'border-pw-accent' : 'border-red-500'}`}>
            <span className="text-[9px] font-black text-text-secondary uppercase tracking-wider">{isProfit ? 'Net Profit' : 'Net Loss'}</span>
            <span className={`text-sm font-bold font-mono ${isProfit ? 'text-pw-accent' : 'text-red-500'}`}>{fmtCurrency(netProfit)}</span>
          </div>
        </div>

      </div>
    </div>
  );
}

