'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { Camera, Image as ImageIcon, Trash2, Eye, Film, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';
import FileDropzone from '@/components/shared/FileDropzone';

/* ═══════════════════════════════════════════════════════
   Photography Upload Manager — Phase 4 Module
   Manages professional photography / virtual tour
   uploads for MLS syndication.

   Persistence: Firestore projects/{projectId}/mediaAssets
   ═══════════════════════════════════════════════════════ */

interface PhotoAsset {
  id: string;
  name: string;
  type: 'Photo' | 'Video' | '3D Tour';
  room: string;
  url: string;
  storagePath?: string;
  uploaded: boolean;
}

const TYPE_ICONS: Record<PhotoAsset['type'], React.ReactNode> = {
  Photo: <ImageIcon className="w-4 h-4" />,
  Video: <Film className="w-4 h-4" />,
  '3D Tour': <Eye className="w-4 h-4" />,
};

interface Props {
  projectId: string;
}

export default function PhotographyUploadManager({ projectId }: Props) {
  const [assets, setAssets] = useState<PhotoAsset[]>([]);
  const [loading, setLoading] = useState(true);

  // Load persisted assets from Firestore on mount
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    import('@/lib/firebase/config').then(({ db }) =>
      import('firebase/firestore').then(({ collection, onSnapshot, query, orderBy }) => {
        const q = query(
          collection(db, 'projects', projectId, 'mediaAssets'),
          orderBy('uploadedAt', 'asc'),
        );
        const unsub = onSnapshot(q, snap => {
          if (cancelled) return;
          setAssets(snap.docs.map(doc => ({ id: doc.id, ...(doc.data() as Omit<PhotoAsset, 'id'>) })));
          setLoading(false);
        }, () => {
          if (!cancelled) setLoading(false);
        });
        return unsub;
      })
    ).catch(() => { if (!cancelled) setLoading(false); });
    return () => { cancelled = true; };
  }, [projectId]);

  const uploadedCount = assets.filter(a => a.uploaded).length;
  const photoCount = assets.filter(a => a.type === 'Photo' && a.uploaded).length;
  const videoCount = assets.filter(a => a.type === 'Video' && a.uploaded).length;

  const handleRemove = useCallback(async (id: string) => {
    try {
      const { db } = await import('@/lib/firebase/config');
      const { doc, deleteDoc } = await import('firebase/firestore');
      await deleteDoc(doc(db, 'projects', projectId, 'mediaAssets', id));
    } catch {
      toast.error('Failed to remove asset');
    }
  }, [projectId]);

  const handleAddAsset = () => {
    // Add a pending (not yet uploaded) slot to local state; it gets persisted on upload
    const tempId = Math.random().toString(36).slice(2, 8);
    setAssets(prev => [...prev, { id: tempId, name: '', type: 'Photo', room: '', url: '', uploaded: false }]);
  };

  const handleUploadComplete = useCallback(async (
    tempId: string,
    room: string,
    assetType: PhotoAsset['type'],
    res: { downloadUrl: string; storagePath: string },
  ) => {
    const name = res.storagePath.split('/').pop() || room || 'Asset';
    const record: Omit<PhotoAsset, 'id'> = {
      name,
      type: assetType,
      room,
      url: res.downloadUrl,
      storagePath: res.storagePath,
      uploaded: true,
    };
    try {
      const { db } = await import('@/lib/firebase/config');
      const { collection, addDoc, serverTimestamp } = await import('firebase/firestore');
      await addDoc(collection(db, 'projects', projectId, 'mediaAssets'), {
        ...record,
        uploadedAt: serverTimestamp(),
      });
      // Remove the local pending slot — onSnapshot will repopulate with the persisted doc
      setAssets(prev => prev.filter(a => a.id !== tempId));
      toast.success('Asset uploaded successfully');
    } catch {
      toast.error('Upload succeeded but failed to save — please try again');
    }
  }, [projectId]);

  if (loading) {
    return (
      <div className="glass-card border border-pw-border p-6 flex items-center justify-center py-12">
        <Loader2 className="w-5 h-5 animate-spin text-text-secondary" />
      </div>
    );
  }

  return (
    <div className="glass-card border border-pw-border p-6">
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center space-x-2">
          <Camera className="w-4 h-4 text-pw-accent" />
          <h3 className="text-xs font-black tracking-[0.3em] text-text-primary uppercase">Photography & Media</h3>
        </div>
        <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">{uploadedCount}/{assets.length} ready</span>
      </div>

      {/* Summary Strip */}
      <div className="grid grid-cols-3 gap-2 mb-5">
        <div className="p-2.5 bg-pw-glass-bg/40 border border-pw-border text-center">
          <p className="text-[9px] uppercase tracking-widest text-text-secondary">Photos</p>
          <p className="text-lg font-semibold text-text-primary">{photoCount}</p>
        </div>
        <div className="p-2.5 bg-pw-glass-bg/40 border border-pw-border text-center">
          <p className="text-[9px] uppercase tracking-widest text-text-secondary">Videos</p>
          <p className="text-lg font-semibold text-text-primary">{videoCount}</p>
        </div>
        <div className="p-2.5 bg-pw-glass-bg/40 border border-pw-border text-center">
          <p className="text-[9px] uppercase tracking-widest text-text-secondary">Total</p>
          <p className="text-lg font-semibold text-text-primary">{uploadedCount}</p>
        </div>
      </div>

      {/* Uploaded Thumbnails Preview */}
      {assets.filter(a => a.uploaded && a.url).length > 0 && (
        <div className="grid grid-cols-3 gap-2 mb-5">
          {assets.filter(a => a.uploaded && a.url).map(asset => (
            <div key={asset.id} className="relative group overflow-hidden border border-pw-border aspect-video">
              {asset.type === 'Photo' && asset.url.startsWith('http') ? (
                <img
                  src={asset.url}
                  alt={asset.room}
                  className="w-full h-full object-cover opacity-80 group-hover:opacity-100 transition"
                  loading="lazy"
                />
              ) : (
                <div className="w-full h-full bg-pw-glass-bg/30 flex flex-col items-center justify-center text-text-secondary gap-1 p-2">
                  {TYPE_ICONS[asset.type]}
                  <span className="text-[9px] font-semibold truncate max-w-full">{asset.name}</span>
                </div>
              )}
              <div className="absolute bottom-0 inset-x-0 bg-gradient-to-t from-pw-black/90 to-transparent p-2">
                <p className="text-xs text-pw-white font-medium">{asset.room || 'General'}</p>
              </div>
              <button
                onClick={() => handleRemove(asset.id)}
                className="absolute top-1 right-1 opacity-0 group-hover:opacity-100 p-1 bg-pw-black/60 text-color-error hover:text-color-error/80 transition"
              >
                <Trash2 className="w-3 h-3" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Empty state */}
      {assets.length === 0 && (
        <div className="py-8 text-center text-text-secondary text-xs">
          No media assets yet. Add your first photo or video below.
        </div>
      )}

      {/* Pending Upload Items */}
      <div className="space-y-4">
        {assets.filter(a => !a.uploaded).map(asset => (
          <div key={asset.id} className="p-4 border border-pw-border bg-pw-glass-bg/20 rounded-xl space-y-3">
            <div className="grid grid-cols-2 gap-2">
              <div>
                <label className="text-[10px] uppercase font-bold text-text-secondary">Type</label>
                <select
                  value={asset.type}
                  onChange={e => setAssets(prev => prev.map(a => a.id === asset.id ? { ...a, type: e.target.value as PhotoAsset['type'] } : a))}
                  className="w-full mt-1 text-xs border border-pw-border rounded px-2.5 py-1.5 bg-pw-glass-bg text-text-primary focus:outline-none"
                >
                  <option value="Photo">Photo</option>
                  <option value="Video">Video</option>
                  <option value="3D Tour">3D Tour</option>
                </select>
              </div>
              <div>
                <label className="text-[10px] uppercase font-bold text-text-secondary">Room / Area</label>
                <input
                  type="text"
                  placeholder="e.g. Kitchen, Exterior"
                  value={asset.room}
                  onChange={e => setAssets(prev => prev.map(a => a.id === asset.id ? { ...a, room: e.target.value } : a))}
                  className="w-full mt-1 text-xs border border-pw-border rounded px-2.5 py-1.5 bg-pw-glass-bg text-text-primary focus:outline-none"
                />
              </div>
            </div>

            <FileDropzone
              projectId={projectId}
              path="photography"
              accept={
                asset.type === 'Photo'
                  ? ['image/jpeg', 'image/png', 'image/webp']
                  : asset.type === 'Video'
                  ? ['video/mp4', 'video/quicktime']
                  : ['application/pdf', 'image/jpeg', 'image/png']
              }
              maxSize={asset.type === 'Video' ? 50 * 1024 * 1024 : 10 * 1024 * 1024}
              label={`Upload ${asset.type}`}
              onUploadComplete={(res) => handleUploadComplete(asset.id, asset.room, asset.type, res)}
            />

            <div className="flex justify-end">
              <button
                onClick={() => setAssets(prev => prev.filter(a => a.id !== asset.id))}
                className="text-xs text-color-error hover:text-color-error/80 flex items-center gap-1"
              >
                <Trash2 className="w-3.5 h-3.5" /> Discard
              </button>
            </div>
          </div>
        ))}
      </div>

      {/* Add Asset Button */}
      <button
        onClick={handleAddAsset}
        className="mt-4 w-full flex items-center justify-center gap-2 py-3 border border-dashed border-pw-border text-xs text-text-secondary hover:text-text-primary hover:border-pw-accent transition cursor-pointer"
      >
        <ImageIcon className="w-3.5 h-3.5" /> Add Media Asset
      </button>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { FileText, Percent, Info, ExternalLink, Calendar, CheckSquare, Square } from 'lucide-react';
import toast from 'react-hot-toast';

interface PreparationStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
  strategy: string;
}

export default function PreparationStep({
  initialData,
  onSave,
  strategy,
}: PreparationStepProps) {
  const f = initialData?.financials || {};

  // ── Strategy: Sell preparation states ──
  const [sellChecklist, setSellChecklist] = useState<Record<string, boolean>>(() => {
    return f.exitSellChecklist || {
      repairsDone: false,
      cleaningDone: false,
      stagingArranged: false,
      photosReady: false,
      agentAssigned: false,
    };
  });
  const [listPrice, setListPrice] = useState<number>(f.exitListPrice || (initialData?.estimatedARV || f.estimatedARV || 320000));
  const [mlsNumber, setMlsNumber] = useState<string>(f.exitMlsNumber || '');
  const [listingDate, setListingDate] = useState<string>(f.exitListingDate || '');

  // ── Strategy: Refinance preparation states ──
  const [refiChecklist, setRefiChecklist] = useState<Record<string, boolean>>(() => {
    return f.exitRefiChecklist || {
      appraisalOrdered: false,
      lenderAssigned: false,
      rateLocked: false,
      titleOrdered: false,
      closingScheduled: false,
    };
  });
  const [newLoanAmount, setNewLoanAmount] = useState<number>(f.exitNewLoanAmount || 240000);
  const [newInterestRate, setNewInterestRate] = useState<number>(f.exitNewInterestRate || 6.5);
  const [newLoanTermYears, setNewLoanTermYears] = useState<number>(f.exitNewLoanTermYears || 30);

  const currentLoanBalance = f.loanAmount / 100 || 180000;

  // Calculators
  const computedSellDetails = useMemo(() => {
    const commission = listPrice * 0.06;
    const closingCosts = listPrice * 0.02;
    const netProceeds = listPrice - currentLoanBalance - commission - closingCosts;
    return {
      commission,
      closingCosts,
      netProceeds,
    };
  }, [listPrice, currentLoanBalance]);

  const computedRefiDetails = useMemo(() => {
    const cashOut = newLoanAmount - currentLoanBalance;
    const newMonthlyPayment = (newLoanAmount * (newInterestRate / 100)) / 12;
    const projectedNOI = f.projectedNOI / 100 || 2200;
    const dscr = projectedNOI / (newMonthlyPayment * 12);
    return {
      cashOut,
      newPayment: newMonthlyPayment,
      dscr,
    };
  }, [newLoanAmount, newInterestRate, currentLoanBalance, f.projectedNOI]);

  const handleToggleSellChecklist = (key: string) => {
    setSellChecklist({ ...sellChecklist, [key]: !sellChecklist[key] });
  };

  const handleToggleRefiChecklist = (key: string) => {
    setRefiChecklist({ ...refiChecklist, [key]: !refiChecklist[key] });
  };

  const handleContinue = async () => {
    const payload = {
      financials: {
        ...f,
        exitSellChecklist: sellChecklist,
        exitListPrice: listPrice,
        exitMlsNumber: mlsNumber,
        exitListingDate: listingDate,
        exitRefiChecklist: refiChecklist,
        exitNewLoanAmount: newLoanAmount,
        exitNewInterestRate: newInterestRate,
        exitNewLoanTermYears: newLoanTermYears,
        exitPrepComplete: true,
      },
    };
    await onSave(payload);
  };

  if (strategy === 'Hold') {
    return (
      <div className="space-y-5 text-center py-6">
        <h3 className="text-sm font-bold text-white uppercase tracking-wider">Step 2: Preparation</h3>
        <p className="text-xs text-slate-400 max-w-md mx-auto leading-relaxed">
          Holding long-term does not require pre-marketing staging or lender appraisal checks. You can skip directly to execution and review lease expiration terms.
        </p>
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] font-bold uppercase tracking-wider text-[11px] rounded-lg transition-all"
        >
          Proceed to Step 3
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 2: Exit Preparation</h3>
        <p className="text-xs text-slate-400">Complete pre-marketing checkpoints and finalize expected listing/lending parameters.</p>
      </div>

      {strategy === 'Sell' ? (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {/* Sell checklist */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Pre-Sale Marketing Checklist</h4>
            <div className="space-y-2 text-xs">
              {Object.keys(sellChecklist).map((key) => {
                const label = key
                  .replace(/([A-Z])/g, ' $1')
                  .replace(/^./, (str) => str.toUpperCase());
                return (
                  <button
                    key={key}
                    type="button"
                    onClick={() => handleToggleSellChecklist(key)}
                    className="flex items-center gap-2 text-left text-white w-full"
                  >
                    {sellChecklist[key] ? (
                      <CheckSquare className="w-4 h-4 text-[#7A9EAA] shrink-0" />
                    ) : (
                      <Square className="w-4 h-4 text-slate-600 shrink-0" />
                    )}
                    <span>{label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Sell Parameters */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-4">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Listing settings</h4>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[8px] font-bold uppercase text-slate-500">List Price ($)</label>
                <input
                  type="number"
                  value={listPrice || ''}
                  onChange={(e) => setListPrice(Number(e.target.value))}
                  className="w-full px-2.5 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs h-8"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[8px] font-bold uppercase text-slate-500">MLS Number</label>
                <input
                  type="text"
                  value={mlsNumber}
                  onChange={(e) => setMlsNumber(e.target.value)}
                  className="w-full px-2.5 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs h-8"
                />
              </div>
            </div>

            <div className="pt-3 border-t border-white/5 space-y-1 text-xs">
              <div className="flex justify-between">
                <span className="opacity-60">Est. Agent Commissions (6%)</span>
                <span>${Math.round(computedSellDetails.commission).toLocaleString()}</span>
              </div>
              <div className="flex justify-between">
                <span className="opacity-60">Est. Closing Costs (2%)</span>
                <span>${Math.round(computedSellDetails.closingCosts).toLocaleString()}</span>
              </div>
              <div className="flex justify-between text-[#7A9EAA] font-bold">
                <span>Net Estimated Proceeds</span>
                <span>${Math.round(computedSellDetails.netProceeds).toLocaleString()}</span>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
          {/* Refi checklist */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Refinance lending checklist</h4>
            <div className="space-y-2 text-xs">
              {Object.keys(refiChecklist).map((key) => {
                const label = key
                  .replace(/([A-Z])/g, ' $1')
                  .replace(/^./, (str) => str.toUpperCase());
                return (
                  <button
                    key={key}
                    type="button"
                    onClick={() => handleToggleRefiChecklist(key)}
                    className="flex items-center gap-2 text-left text-white w-full"
                  >
                    {refiChecklist[key] ? (
                      <CheckSquare className="w-4 h-4 text-[#7A9EAA] shrink-0" />
                    ) : (
                      <Square className="w-4 h-4 text-slate-600 shrink-0" />
                    )}
                    <span>{label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Refi parameters */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-4">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Refi loan parameters</h4>
            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-1">
                <label className="text-[7px] font-bold uppercase text-slate-500">Loan Amount ($)</label>
                <input
                  type="number"
                  value={newLoanAmount || ''}
                  onChange={(e) => setNewLoanAmount(Number(e.target.value))}
                  className="w-full px-2 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-[11px] h-8"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[7px] font-bold uppercase text-slate-500">Rate (%)</label>
                <input
                  type="number"
                  step="0.1"
                  value={newInterestRate || ''}
                  onChange={(e) => setNewInterestRate(Number(e.target.value))}
                  className="w-full px-2 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-[11px] h-8"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[7px] font-bold uppercase text-slate-500">Term (Yrs)</label>
                <input
                  type="number"
                  value={newLoanTermYears || ''}
                  onChange={(e) => setNewLoanTermYears(Number(e.target.value))}
                  className="w-full px-2 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-[11px] h-8"
                />
              </div>
            </div>

            <div className="pt-3 border-t border-white/5 space-y-1 text-xs">
              <div className="flex justify-between">
                <span className="opacity-60">Estimated Cash-Out</span>
                <span>${Math.round(computedRefiDetails.cashOut).toLocaleString()}</span>
              </div>
              <div className="flex justify-between">
                <span className="opacity-60">Estimated New Payment</span>
                <span>${Math.round(computedRefiDetails.newPayment).toLocaleString()}/mo</span>
              </div>
              <div className="flex justify-between text-[#7A9EAA] font-bold">
                <span>Projected DSCR</span>
                <span>{computedRefiDetails.dscr.toFixed(2)}</span>
              </div>
            </div>
          </div>
        </div>
      )}

      <div className="flex justify-between pt-4 border-t border-white/5">
        <span />
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] hover:opacity-90 font-bold uppercase tracking-wider text-[11px] rounded-lg transition-opacity"
        >
          Save & Continue
        </button>
      </div>
    </div>
  );
}

'use client';

import React from 'react';
import { Percent, CheckCircle2, AlertCircle } from 'lucide-react';

export interface RealizedReturnsSummaryProps {
  actualIRR: number | null;
  actualEquityMultiple: number | null;
  totalCashInvested: number;
  netProfit: number;
  completenessPercent: number; // 0 to 100
  missingFields?: string[];
}

export function RealizedReturnsSummary({
  actualIRR,
  actualEquityMultiple,
  totalCashInvested,
  netProfit,
  completenessPercent,
  missingFields = []
}: RealizedReturnsSummaryProps) {
  const isComplete = completenessPercent >= 100;

  const fmtCurrency = (val: number) =>
    val.toLocaleString('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  return (
    <div data-testid="realized-returns-summary" className="glass-card rounded-2xl p-6 space-y-5 border border-white/10 bg-[#121014]/80">
      <div className="flex items-center justify-between">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white flex items-center gap-2 font-outfit">
          <Percent className="w-4 h-4 text-[#7A9EAA]" />
          Returns Summary & Actualized Cash Flows
        </h3>
        <span
          data-testid="data-completeness-badge"
          className={`px-2.5 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${
            isComplete
              ? 'bg-emerald-500/15 text-emerald-400 border border-emerald-500/30'
              : 'bg-amber-500/15 text-amber-300 border border-amber-500/30'
          }`}
        >
          {isComplete ? '100% Data Complete' : `${Math.round(completenessPercent)}% Data Complete (partial data)`}
        </span>
      </div>

      {/* Completeness Meter */}
      <div className="space-y-1.5">
        <div className="flex justify-between text-[10px] font-bold uppercase tracking-wider text-slate-400">
          <span>Actuals Completeness Meter</span>
          <span>{Math.round(completenessPercent)}%</span>
        </div>
        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden border border-white/10">
          <div
            className={`h-full transition-all duration-500 ${isComplete ? 'bg-emerald-500' : 'bg-amber-500'}`}
            style={{ width: `${Math.min(100, completenessPercent)}%` }}
          />
        </div>
        {!isComplete && missingFields.length > 0 && (
          <p className="text-[10px] text-amber-400/90 flex items-center gap-1 mt-1">
            <AlertCircle className="w-3 h-3 shrink-0" />
            Missing inputs for 100% completeness: {missingFields.join(', ')}
          </p>
        )}
      </div>

      {/* Metrics Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 pt-2 border-t border-white/10">
        <div>
          <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Actualized IRR</span>
          <p className="text-xl font-bold text-emerald-400 tabular-nums mt-0.5">
            {actualIRR !== null ? `${actualIRR.toFixed(1)}%` : '—'}
          </p>
          {!isComplete && <span className="text-[9px] text-amber-400 font-semibold">partial data</span>}
        </div>
        <div>
          <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Equity Multiple</span>
          <p className="text-xl font-bold text-white tabular-nums mt-0.5">
            {actualEquityMultiple !== null ? `${actualEquityMultiple.toFixed(2)}x` : '—'}
          </p>
          {!isComplete && <span className="text-[9px] text-amber-400 font-semibold">partial data</span>}
        </div>
        <div>
          <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Total Cash Invested</span>
          <p className="text-xl font-bold text-white tabular-nums mt-0.5">{fmtCurrency(totalCashInvested)}</p>
        </div>
        <div>
          <span className="text-[10px] font-bold uppercase tracking-wider text-slate-400">Realized Net Profit</span>
          <p className={`text-xl font-bold tabular-nums mt-0.5 ${netProfit >= 0 ? 'text-emerald-400' : 'text-rose-400'}`}>
            {fmtCurrency(netProfit)}
          </p>
        </div>
      </div>
    </div>
  );
}

