'use client';

import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { SettlementLineItem } from '@/types/schema';
import { computeSettlementDefaults, recomputeSettlement } from '@/lib/math/calculatorUtils';
import { Receipt, Plus, Trash2, Lock, Unlock, Percent, DollarSign } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Settlement Ledger — Itemized Sell-Side Closing Costs

   Pre-populated with industry defaults. Each row is 
   editable. Real-time recomputation as sale price changes.
   ═══════════════════════════════════════════════════════ */

interface SettlementLedgerProps {
  projectId: string;
  salePrice: number;
}

export default function SettlementLedger({ projectId, salePrice }: SettlementLedgerProps) {
  const financials = useProjectStore(state => {
    const p = state.projects.find(d => d.id === projectId);
    return p?.financials;
  });
  const updateProjectFinancials = useProjectStore(state => state.updateProjectFinancials);

  // Initialize from store or defaults
  const [items, setItems] = useState<SettlementLineItem[]>(() =>
    financials?.settlementLedger?.length
      ? financials.settlementLedger
      : computeSettlementDefaults(salePrice)
  );

  // Recompute when sale price changes
  useEffect(() => {
    if (salePrice > 0) {
      setItems(prev => recomputeSettlement(prev, salePrice));
    }
  }, [salePrice]);

  // Persist to store on change
  const persistItems = useCallback((updated: SettlementLineItem[]) => {
    setItems(updated);
    updateProjectFinancials(projectId, { settlementLedger: updated });
  }, [projectId, updateProjectFinancials]);

  // Totals
  const sellerTotal = useMemo(() =>
    items.reduce((sum, i) => {
      if (i.paidBy === 'Seller') return sum + i.computedAmount;
      if (i.paidBy === 'Split') return sum + i.computedAmount / 2;
      return sum;
    }, 0),
    [items]
  );

  const buyerTotal = useMemo(() =>
    items.reduce((sum, i) => {
      if (i.paidBy === 'Buyer') return sum + i.computedAmount;
      if (i.paidBy === 'Split') return sum + i.computedAmount / 2;
      return sum;
    }, 0),
    [items]
  );

  const handleUpdateRate = (id: string, value: string) => {
    const updated = items.map(item => {
      if (item.id !== id || item.locked) return item;
      if (item.isPercentage) {
        const rate = Number(value) || 0;
        return { ...item, percentageRate: rate, computedAmount: salePrice * (rate / 100) };
      } else {
        const flat = Number(value) || 0;
        return { ...item, flatAmount: flat, computedAmount: flat };
      }
    });
    persistItems(updated);
  };

  const handleTogglePaidBy = (id: string) => {
    const cycle: Array<'Seller' | 'Buyer' | 'Split'> = ['Seller', 'Buyer', 'Split'];
    const updated = items.map(item => {
      if (item.id !== id || item.locked) return item;
      const idx = cycle.indexOf(item.paidBy);
      return { ...item, paidBy: cycle[(idx + 1) % cycle.length] };
    });
    persistItems(updated);
  };

  const handleRemove = (id: string) => {
    persistItems(items.filter(i => i.id !== id));
  };

  const handleAddCustom = () => {
    const newItem: SettlementLineItem = {
      id: `sl-custom-${Date.now()}`,
      label: 'Custom Fee',
      category: 'Other',
      isPercentage: false,
      flatAmount: 0,
      computedAmount: 0,
      paidBy: 'Seller',
      locked: false,
    };
    persistItems([...items, newItem]);
  };

  const handleLabelChange = (id: string, label: string) => {
    const updated = items.map(item =>
      item.id === id ? { ...item, label } : item
    );
    persistItems(updated);
  };

  return (
    <div className="glass-card border border-pw-border relative overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-pw-border bg-pw-black text-pw-white">
        <div className="flex items-center gap-2">
          <Receipt className="w-3.5 h-3.5" />
          <h3 className="text-xs font-black tracking-[0.3em] uppercase">Settlement_Ledger</h3>
        </div>
        <span className="text-[10px] font-bold text-text-secondary uppercase tracking-widest">
          {items.length} Line_Items
        </span>
      </div>

      {/* Table */}
      <div className="divide-y divide-pw-border">
        {/* Column Headers */}
        <div className="grid grid-cols-12 gap-2 px-6 py-3 bg-pw-glass-bg/50 text-[9px] font-black text-text-secondary uppercase tracking-widest border-b border-pw-border">
          <div className="col-span-4">Line Item</div>
          <div className="col-span-2 text-right">Rate / Amount</div>
          <div className="col-span-2 text-right">Computed $</div>
          <div className="col-span-2 text-center">Paid By</div>
          <div className="col-span-2 text-center">Action</div>
        </div>

        {/* Rows */}
        {items.map((item, idx) => (
          <div
            key={item.id}
            className={`grid grid-cols-12 gap-2 px-6 py-3 items-center transition-colors ${
              idx % 2 === 0 ? 'bg-pw-glass-bg/10' : 'bg-pw-glass-bg/20'
            } ${item.locked ? 'opacity-60' : 'hover:bg-pw-glass-bg/30'}`}
          >
            {/* Label */}
            <div className="col-span-4">
              {item.locked ? (
                <span className="text-xs font-bold text-text-primary">{item.label}</span>
              ) : (
                <input
                  type="text"
                  value={item.label}
                  onChange={e => handleLabelChange(item.id, e.target.value)}
                  className="text-xs font-bold text-text-primary bg-transparent w-full focus:outline-none border-b border-transparent focus:border-pw-accent"
                />
              )}
              <span className="text-[9px] text-text-secondary block mt-0.5">{item.category}</span>
            </div>

            {/* Rate / Amount Input */}
            <div className="col-span-2 text-right">
              <div className="flex items-center justify-end gap-1">
                <input
                  type="number"
                  step={item.isPercentage ? '0.1' : '100'}
                  value={item.isPercentage ? (item.percentageRate ?? 0) : (item.flatAmount ?? 0)}
                  onChange={e => handleUpdateRate(item.id, e.target.value)}
                  disabled={item.locked}
                  className="text-xs font-mono font-black text-right w-16 bg-transparent focus:outline-none border-b border-transparent focus:border-pw-accent disabled:cursor-not-allowed text-text-primary"
                />
                {item.isPercentage ? (
                  <Percent className="w-3 h-3 text-text-secondary flex-shrink-0" />
                ) : (
                  <DollarSign className="w-3 h-3 text-text-secondary flex-shrink-0" />
                )}
              </div>
            </div>

            {/* Computed Amount */}
            <div className="col-span-2 text-right">
              <span className="text-xs font-mono font-black text-text-primary">
                ${item.computedAmount.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
              </span>
            </div>

            {/* Paid By */}
            <div className="col-span-2 text-center">
              <button
                onClick={() => handleTogglePaidBy(item.id)}
                disabled={item.locked}
                className={`text-[9px] font-black uppercase tracking-wider px-3 py-1 border transition-all disabled:cursor-not-allowed ${
                  item.paidBy === 'Seller'
                    ? 'bg-color-error/10 border-color-error/30 text-color-error'
                    : item.paidBy === 'Buyer'
                    ? 'bg-pw-accent/10 border-pw-accent/30 text-pw-accent'
                    : 'bg-pw-muted/20 border-pw-border text-text-primary'
                }`}
              >
                {item.paidBy}
              </button>
            </div>

            {/* Actions */}
            <div className="col-span-2 flex justify-center gap-2">
              {!item.locked && (
                <button
                  onClick={() => handleRemove(item.id)}
                  className="p-1 text-text-secondary hover:text-color-error transition-colors"
                  aria-label={`Remove ${item.label}`}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </button>
              )}
              {item.locked ? (
                <Lock className="w-3.5 h-3.5 text-text-secondary" />
              ) : (
                <Unlock className="w-3.5 h-3.5 text-text-secondary opacity-30" />
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Footer: Totals + Add */}
      <div className="border-t border-pw-border px-6 py-4 bg-pw-glass-bg/30">
        <div className="flex items-center justify-between mb-4">
          <button
            onClick={handleAddCustom}
            className="flex items-center gap-1.5 pw-btn pw-btn--secondary pw-btn--sm text-[9px] font-black uppercase tracking-wider py-1.5 px-3"
          >
            <Plus className="w-3.5 h-3.5" /> Add_Line_Item
          </button>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div className="p-4 border border-pw-border bg-pw-glass-bg/40">
            <p className="text-[9px] font-black text-color-error uppercase tracking-widest mb-1">Seller_Liability</p>
            <p className="text-2xl font-black font-mono tracking-tighter text-text-primary">
              ${sellerTotal.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
            </p>
          </div>
          <div className="p-4 border border-pw-border bg-pw-glass-bg/40">
            <p className="text-[9px] font-black text-pw-accent uppercase tracking-widest mb-1">Buyer_Liability</p>
            <p className="text-2xl font-black font-mono tracking-tighter text-text-primary">
              ${buyerTotal.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Users, Phone, Mail, Star, Plus, CheckCircle, X } from 'lucide-react';
import toast from 'react-hot-toast';

/* ═══════════════════════════════════════════════════════
   Staging Vendor Manager — Phase 4 Module
   Manages staging vendors, photographers, and
   pre-listing service providers.
   ═══════════════════════════════════════════════════════ */

type VendorType = 'Staging Company' | 'Photographer' | 'Videographer' | 'Cleaning Service' | 'Landscaper';

interface Vendor {
  id: string;
  name: string;
  type: VendorType;
  phone: string;
  email: string;
  rate: string;
  rating: number; // 1-5
  status: 'Contacted' | 'Booked' | 'Completed' | 'Cancelled';
}

const STATUS_STYLES: Record<Vendor['status'], string> = {
  Contacted: 'bg-pw-glass-bg border-pw-border text-text-secondary',
  Booked: 'bg-pw-accent/10 border-pw-accent/30 text-pw-accent',
  Completed: 'bg-pw-black text-pw-white border-pw-border',
  Cancelled: 'bg-color-error/10 border-color-error/30 text-color-error',
};

const INITIAL_VENDORS: Vendor[] = [
  { id: '1', name: 'Meridian Staging Co.', type: 'Staging Company', phone: '(305) 555-0142', email: 'info@meridionstaging.com', rate: '$2,500 / mo', rating: 5, status: 'Booked' },
  { id: '2', name: 'Lens & Light Photography', type: 'Photographer', phone: '(305) 555-0198', email: 'book@lenslight.com', rate: '$450 / session', rating: 4, status: 'Contacted' },
  { id: '3', name: 'Drone Visions LLC', type: 'Videographer', phone: '(786) 555-0267', email: 'fly@dronevisions.io', rate: '$350 / session', rating: 5, status: 'Contacted' },
];

function StarRating({ rating, size = 'sm' }: { rating: number; size?: 'sm' | 'xs' }) {
  const cls = size === 'sm' ? 'w-3 h-3' : 'w-2.5 h-2.5';
  return (
    <div className="flex items-center gap-0.5">
      {Array.from({ length: 5 }).map((_, i) => (
        <Star key={i} className={`${cls} ${i < rating ? 'text-pw-accent fill-pw-accent' : 'text-pw-border'}`} />
      ))}
    </div>
  );
}

export default function StagingVendorManager() {
  const [vendors, setVendors] = useState<Vendor[]>(INITIAL_VENDORS);
  const [showAdd, setShowAdd] = useState(false);

  const advanceStatus = (id: string) => {
    const order: Vendor['status'][] = ['Contacted', 'Booked', 'Completed'];
    setVendors(vendors.map(v => {
      if (v.id === id) {
        const idx = order.indexOf(v.status);
        if (idx >= 0 && idx < order.length - 1) {
          const next = order[idx + 1];
          toast.success(`${v.name} → ${next}`, { style: { background: 'var(--pw-black)', color: 'var(--pw-white)' } });
          return { ...v, status: next };
        }
      }
      return v;
    }));
  };

  const handleAddVendor = () => {
    setVendors([
      ...vendors,
      {
        id: crypto.randomUUID(),
        name: '',
        type: 'Staging Company',
        phone: '',
        email: '',
        rate: '',
        rating: 3,
        status: 'Contacted',
      },
    ]);
    setShowAdd(false);
  };

  const bookedCount = vendors.filter(v => v.status === 'Booked' || v.status === 'Completed').length;

  return (
    <div className="glass-card border border-pw-border p-6">
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center space-x-2">
          <Users className="w-4 h-4 text-pw-accent" />
          <h3 className="text-xs font-black tracking-[0.3em] text-text-primary uppercase">Staging & Vendor Network</h3>
        </div>
        <div className="flex items-center gap-3">
          <span className="text-[10px] font-bold text-text-secondary uppercase tracking-wider">{bookedCount}/{vendors.length} secured</span>
          <button
            onClick={handleAddVendor}
            className="flex items-center gap-1 pw-btn pw-btn--secondary pw-btn--sm text-[9px] font-black uppercase tracking-wider py-1 px-3"
          >
            <Plus className="w-3 h-3" /> Add
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {vendors.map(vendor => (
          <div key={vendor.id} className="p-4 border border-pw-border hover:border-pw-accent transition group bg-pw-glass-bg/30">
            <div className="flex items-start justify-between mb-2">
              <div>
                <p className="text-sm font-semibold text-text-primary">{vendor.name || 'New Vendor'}</p>
                <p className="text-[10px] text-text-secondary uppercase tracking-widest mt-0.5">{vendor.type}</p>
              </div>
              <span className={`text-[9px] font-black uppercase tracking-wider px-2 py-0.5 border ${STATUS_STYLES[vendor.status]}`}>
                {vendor.status}
              </span>
            </div>

            <div className="flex items-center gap-4 text-[10px] text-text-secondary mt-2">
              {vendor.phone && (
                <span className="flex items-center gap-1"><Phone className="w-3 h-3 text-pw-accent" />{vendor.phone}</span>
              )}
              {vendor.email && (
                <span className="flex items-center gap-1"><Mail className="w-3 h-3 text-pw-accent" />{vendor.email}</span>
              )}
              {vendor.rate && (
                <span className="text-pw-accent font-semibold font-mono">{vendor.rate}</span>
              )}
            </div>

            <div className="flex items-center justify-between mt-3 pt-3 border-t border-pw-border">
              <StarRating rating={vendor.rating} />
              {vendor.status !== 'Completed' && vendor.status !== 'Cancelled' && (
                <button
                  onClick={() => advanceStatus(vendor.id)}
                  className="opacity-0 group-hover:opacity-100 text-[10px] text-pw-accent hover:text-pw-accent/80 font-black uppercase tracking-wider transition"
                >
                  Advance →
                </button>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { DollarSign, Landmark, RefreshCw, Key, ChevronRight, TrendingUp } from 'lucide-react';
import toast from 'react-hot-toast';

interface StrategyStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

export default function StrategyStep({
  initialData,
  onSave,
}: StrategyStepProps) {
  const f = initialData?.financials || {};

  // Input states
  const [strategy, setStrategy] = useState<string>(f.exitStrategy || 'Sell');
  const [targetDate, setTargetDate] = useState<string>(f.exitTargetDate || '');

  // Estimated values from properties
  const arValue = initialData?.estimatedARV || f.estimatedARV || 320000;
  const currentLoanBalance = f.loanAmount / 100 || 180000; // in dollars
  const projectedSalePrice = arValue;

  // Calculators
  const sellMetrics = useMemo(() => {
    const commission = projectedSalePrice * 0.06;
    const closingCosts = projectedSalePrice * 0.02;
    const payoff = currentLoanBalance;
    const netProceeds = projectedSalePrice - payoff - closingCosts - commission;
    const totalCashInvested = f.totalCashInvested / 100 || 80000;
    const roi = (netProceeds / totalCashInvested) * 100;
    return {
      netProceeds,
      roi,
      dom: 42, // average from RentCast Zip
    };
  }, [projectedSalePrice, currentLoanBalance, f.totalCashInvested]);

  const refinanceMetrics = useMemo(() => {
    const estimatedValue = projectedSalePrice;
    const maxLoan = estimatedValue * 0.75; // 75% LTV
    const cashOut = maxLoan - currentLoanBalance;
    const newMonthlyPayment = (maxLoan * 0.065) / 12; // 6.5% interest rate simple
    const projectedNOI = f.projectedNOI / 100 || 2200;
    const dscr = projectedNOI / (newMonthlyPayment * 12);
    return {
      cashOut,
      newPayment: newMonthlyPayment,
      dscr,
    };
  }, [projectedSalePrice, currentLoanBalance, f.projectedNOI]);

  const holdMetrics = useMemo(() => {
    const currentNOI = f.projectedNOI / 100 || 2200;
    const capRate = (currentNOI / projectedSalePrice) * 100;

    // 5-year projections (3% growth compounding)
    const year5Value = projectedSalePrice * Math.pow(1.03, 5);
    const year5Rent = (f.grossRent / 100 || 1800) * Math.pow(1.03, 5);
    return {
      capRate,
      year5Value,
      year5Rent,
    };
  }, [projectedSalePrice, f.projectedNOI, f.grossRent]);

  const handleContinue = async () => {
    const payload = {
      financials: {
        ...f,
        exitStrategy: strategy,
        exitTargetDate: targetDate,
        exitSellProceeds: sellMetrics.netProceeds * 100,
        exitRefiCashOut: refinanceMetrics.cashOut * 100,
        exitHoldCapRate: holdMetrics.capRate,
      },
    };
    await onSave(payload);
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 1: Exit Strategy Selection</h3>
        <p className="text-xs text-slate-400">Evaluate pro-forma returns across Sale, Refinance, and Hold strategies to define your target disposition.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {/* SELL CARD */}
        <div
          onClick={() => setStrategy('Sell')}
          className={`p-5 rounded-2xl border transition-all cursor-pointer flex flex-col justify-between min-h-[220px] ${
            strategy === 'Sell'
              ? 'bg-[#454955]/15 border-[#7A9EAA] shadow-[0_0_15px_rgba(122,158,170,0.15)] text-white'
              : 'bg-white/[0.01] border-white/5 text-slate-400 hover:border-white/10'
          }`}
        >
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Option 1</span>
              <DollarSign className="w-4 h-4 text-[#7A9EAA]" />
            </div>
            <h4 className="text-sm font-bold text-white">Sell Property</h4>
            <p className="text-[11px] opacity-80 leading-relaxed">Sell the asset on the open market and realize accumulated equity gains.</p>
          </div>

          <div className="pt-4 border-t border-white/5 space-y-1 text-xs">
            <div className="flex justify-between">
              <span className="opacity-60">Projected Net Proceeds</span>
              <span className="font-bold text-white">${Math.round(sellMetrics.netProceeds).toLocaleString()}</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">Estimated ROI</span>
              <span className="font-bold text-emerald-400">{sellMetrics.roi.toFixed(1)}%</span>
            </div>
            <div className="flex justify-between text-[10px]">
              <span className="opacity-60">Avg. Days on Market</span>
              <span className="font-semibold text-white">{sellMetrics.dom} Days</span>
            </div>
          </div>
        </div>

        {/* REFINANCE CARD */}
        <div
          onClick={() => setStrategy('Refinance')}
          className={`p-5 rounded-2xl border transition-all cursor-pointer flex flex-col justify-between min-h-[220px] ${
            strategy === 'Refinance'
              ? 'bg-[#454955]/15 border-[#7A9EAA] shadow-[0_0_15px_rgba(122,158,170,0.15)] text-white'
              : 'bg-white/[0.01] border-white/5 text-slate-400 hover:border-white/10'
          }`}
        >
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Option 2</span>
              <Landmark className="w-4 h-4 text-[#7A9EAA]" />
            </div>
            <h4 className="text-sm font-bold text-white">Refinance Equity</h4>
            <p className="text-[11px] opacity-80 leading-relaxed">Pull out cash-tax free with a new senior debt and keep holding as a rental.</p>
          </div>

          <div className="pt-4 border-t border-white/5 space-y-1 text-xs">
            <div className="flex justify-between">
              <span className="opacity-60">Projected Cash-Out</span>
              <span className="font-bold text-white">${Math.round(refinanceMetrics.cashOut).toLocaleString()}</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">New Debt Service</span>
              <span className="font-bold text-white">${Math.round(refinanceMetrics.newPayment).toLocaleString()}/mo</span>
            </div>
            <div className="flex justify-between text-[10px]">
              <span className="opacity-60">Projected DSCR</span>
              <span className="font-semibold text-[#7A9EAA]">{refinanceMetrics.dscr.toFixed(2)}</span>
            </div>
          </div>
        </div>

        {/* HOLD CARD */}
        <div
          onClick={() => setStrategy('Hold')}
          className={`p-5 rounded-2xl border transition-all cursor-pointer flex flex-col justify-between min-h-[220px] ${
            strategy === 'Hold'
              ? 'bg-[#454955]/15 border-[#7A9EAA] shadow-[0_0_15px_rgba(122,158,170,0.15)] text-white'
              : 'bg-white/[0.01] border-white/5 text-slate-400 hover:border-white/10'
          }`}
        >
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Option 3</span>
              <TrendingUp className="w-4 h-4 text-[#7A9EAA]" />
            </div>
            <h4 className="text-sm font-bold text-white">Hold Long-Term</h4>
            <p className="text-[11px] opacity-80 leading-relaxed">Keep the current financing setup active, building up equity from amortization.</p>
          </div>

          <div className="pt-4 border-t border-white/5 space-y-1 text-xs">
            <div className="flex justify-between">
              <span className="opacity-60">Projected Cap Rate</span>
              <span className="font-bold text-white">{holdMetrics.capRate.toFixed(2)}%</span>
            </div>
            <div className="flex justify-between">
              <span className="opacity-60">Year 5 Comp. Value</span>
              <span className="font-bold text-white">${Math.round(holdMetrics.year5Value).toLocaleString()}</span>
            </div>
            <div className="flex justify-between text-[10px]">
              <span className="opacity-60">Year 5 Rent</span>
              <span className="font-semibold text-white">${Math.round(holdMetrics.year5Rent).toLocaleString()}/mo</span>
            </div>
          </div>
        </div>
      </div>

      {/* Target date configuration */}
      <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-2 max-w-sm">
        <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Target Exit Date</label>
        <input
          type="date"
          value={targetDate}
          onChange={(e) => setTargetDate(e.target.value)}
          className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold h-9"
        />
      </div>

      <div className="flex justify-between pt-4 border-t border-white/5">
        <span />
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] hover:opacity-90 font-bold uppercase tracking-wider text-[11px] rounded-lg transition-opacity flex items-center gap-1.5"
        >
          Select & Continue <ChevronRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useMemo, useCallback } from 'react';
import { Project, TaxEstimate, LedgerItem } from '@/types/schema';
import { computeCapitalGainsTax } from '@/lib/math/calculatorUtils';
import { FileText, Download, Printer, FileSpreadsheet } from 'lucide-react';
import toast from 'react-hot-toast';
import { useProjectStore } from '@/store/projectStore';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

/* ═══════════════════════════════════════════════════════
   Tax Report Generator — PDF-Ready Capital Gains Summary

   Renders a printable tax report and provides browser-
   based PDF download via window.print() isolation.
   ═══════════════════════════════════════════════════════ */

interface TaxReportGeneratorProps {
  deal: Project;
}

export default function TaxReportGenerator({ deal }: TaxReportGeneratorProps) {
  const tax = useMemo(() => computeCapitalGainsTax(deal), [deal]);
  const salePrice = deal.financials?.actualSalePrice || deal.financials?.estimatedARV || 0;

  const ledgerItems = useProjectStore(state => state.ledgerItems[deal.id] || []);
  const approvedItems = useMemo(() => {
    return ledgerItems
      .filter((item) => item.status === 'Approved')
      .sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
  }, [ledgerItems]);

  const fmt = (n: number) =>
    `$${n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  const handleDownloadPDF = useCallback(() => {
    generateItemizedPDF(deal, tax, salePrice, approvedItems);
    toast.success('Itemized PDF downloaded');
  }, [deal, tax, salePrice, approvedItems]);

  const handleDownloadCSV = useCallback(() => {
    const csvContent = generateItemizedCSV(approvedItems);
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `${deal.propertyName || 'Property'}_Tax_Report.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success('CSV downloaded');
  }, [deal, approvedItems]);

  const handleCopyText = useCallback(() => {
    const text = generateReportText(deal, tax, salePrice);
    navigator.clipboard.writeText(text).then(() => {
      toast.success('Tax summary copied to clipboard', {
        style: { background: 'black', color: 'white', border: '1px solid #333' },
      });
    });
  }, [deal, tax, salePrice]);

  return (
    <div className="glass-card border border-pw-border">
      {/* Header */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-pw-border bg-pw-black text-pw-white">
        <div className="flex items-center gap-2">
          <FileText className="w-3.5 h-3.5" />
          <h3 className="text-xs font-black tracking-[0.3em] uppercase">
            Tax_Report_Generator
          </h3>
        </div>
        <span className="text-[10px] font-bold text-text-secondary uppercase tracking-widest">
          Schedule D / Form 8949
        </span>
      </div>

      {/* Preview */}
      <div className="px-6 py-6 space-y-4 bg-pw-glass-bg/30">
        <div className="bg-pw-glass-bg border border-pw-border p-5 space-y-3">
          <div className="pb-3 border-b border-pw-border">
            <p className="text-[10px] font-black text-text-secondary uppercase tracking-widest">
              Property: {deal.propertyName || 'Untitled'}
            </p>
            <p className="text-[9px] text-text-secondary">
              Generated {new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
            </p>
          </div>

          {/* Summary Table */}
          <div className="space-y-2 text-xs">
            <Row label="Sale Price" value={fmt(salePrice)} />
            <Row label="Cost Basis" value={fmt(tax.costBasis)} />
            <Row label="Sell-Side Costs" value={fmt(salePrice - tax.netProceeds)} />
            <Row label="Net Proceeds" value={fmt(tax.netProceeds)} bold />
            <div className="border-t border-pw-border my-2" />
            <Row label="Capital Gain / (Loss)" value={fmt(tax.capitalGain)} highlight={tax.capitalGain >= 0} />
            <Row label="Holding Period" value={`${tax.holdingPeriodDays} days (${tax.isLongTerm ? 'Long-Term' : 'Short-Term'})`} />
            <Row label="Estimated Tax Rate" value={`${tax.estimatedTaxRate}%`} />
            <Row label="Estimated Tax Liability" value={fmt(tax.estimatedTaxLiability)} negative />
            <div className="border-t border-pw-border my-2" />
            <Row label="Net After Tax" value={fmt(tax.netAfterTax)} bold highlight={tax.netAfterTax >= 0} />
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="px-6 py-4 border-t border-pw-border flex flex-col gap-3 sm:flex-row bg-pw-glass-bg/30">
        <button
          onClick={handleDownloadPDF}
          className="flex-1 flex items-center justify-center gap-2 pw-btn pw-btn--primary text-[10px] font-black py-3 uppercase tracking-[0.3em] transition-all"
        >
          <Printer className="w-3.5 h-3.5" /> Export_PDF
        </button>
        <button
          onClick={handleDownloadCSV}
          className="flex-1 flex items-center justify-center gap-2 pw-btn pw-btn--secondary text-[10px] font-black py-3 uppercase tracking-[0.3em] transition-all"
        >
          <FileSpreadsheet className="w-3.5 h-3.5" /> Export_CSV
        </button>
        <button
          onClick={handleCopyText}
          className="flex-1 flex items-center justify-center gap-2 pw-btn pw-btn--outline text-[10px] font-black py-3 uppercase tracking-[0.3em] transition-all"
        >
          <Download className="w-3.5 h-3.5" /> Copy_Text
        </button>
      </div>
    </div>
  );
}

// ─── Helper: Summary Row ──────────────────────────────
function Row({
  label,
  value,
  bold,
  highlight,
  negative,
}: {
  label: string;
  value: string;
  bold?: boolean;
  highlight?: boolean;
  negative?: boolean;
}) {
  return (
    <div className="flex justify-between items-center">
      <span className={`text-text-secondary ${bold ? 'font-black text-text-primary' : 'font-bold'}`}>
        {label}
      </span>
      <span
        className={`font-mono ${bold ? 'font-black text-sm' : 'font-bold'} ${
          highlight !== undefined
            ? highlight
              ? 'text-pw-accent'
              : 'text-color-error'
            : negative
            ? 'text-color-error'
            : 'text-text-primary'
        }`}
      >
        {value}
      </span>
    </div>
  );
}

// ─── Helper: Generate Itemized PDF ─────────────────────
function generateItemizedPDF(deal: Project, tax: TaxEstimate, salePrice: number, items: LedgerItem[]) {
  const doc = new jsPDF();
  const fmt = (n: number) =>
    `$${n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  // Header
  doc.addImage('/brand/PaperWorking_Black_full_Logo_.png', 'PNG', 14, 10, 30.4, 5);

  doc.setFontSize(10);
  doc.setFont('helvetica', 'bold');
  doc.setTextColor(33, 33, 33);
  doc.text('CAPITAL GAINS TAX ESTIMATE & ITEMIZED LEDGER', 14, 22);

  doc.setFontSize(9);
  doc.setFont('helvetica', 'normal');
  doc.setTextColor(100);
  doc.text(`Property: ${deal.propertyName || 'N/A'}`, 14, 30);
  doc.text(`Generated: ${new Date().toLocaleDateString()}`, 14, 35);

  // Summary Data for AutoTable
  const summaryData = [
    ['Sale Price', fmt(salePrice)],
    ['Cost Basis (Purchase + Rehab + Acq. + Holding)', fmt(tax.costBasis)],
    ['Sell-Side Costs', fmt(salePrice - tax.netProceeds)],
    ['Net Proceeds', fmt(tax.netProceeds)],
    ['Capital Gain / (Loss)', fmt(tax.capitalGain)],
    ['Holding Period', `${tax.holdingPeriodDays} days (${tax.isLongTerm ? 'Long-Term' : 'Short-Term'})`],
    ['Estimated Tax Rate', `${tax.estimatedTaxRate}%`],
    ['Estimated Tax Liability', fmt(tax.estimatedTaxLiability)],
    ['NET AFTER TAX', fmt(tax.netAfterTax)],
  ];

  autoTable(doc, {
    startY: 45,
    head: [['Summary', 'Amount']],
    body: summaryData,
    theme: 'grid',
    headStyles: { fillColor: [0, 0, 0], textColor: [255, 255, 255], fontStyle: 'bold' },
    columnStyles: {
      0: { cellWidth: 120 },
      1: { halign: 'right', fontStyle: 'bold' },
    },
    styles: { fontSize: 9 },
  });

  // Itemized Ledger
  const itemizedData = items.map(item => [
    new Date(item.createdAt).toLocaleDateString(),
    item.type.toUpperCase(),
    item.category,
    item.description,
    fmt(item.amount)
  ]);

  autoTable(doc, {
    startY: (doc as any).lastAutoTable.finalY + 15,
    head: [['Date', 'Type', 'Category', 'Description', 'Amount']],
    body: itemizedData,
    theme: 'grid',
    headStyles: { fillColor: [50, 50, 50], textColor: [255, 255, 255], fontStyle: 'bold' },
    columnStyles: {
      4: { halign: 'right' }
    },
    styles: { fontSize: 8 },
    margin: { bottom: 20 },
    didDrawPage: function (data) {
      // Footer text
      doc.setFontSize(8);
      doc.setTextColor(150);
      const str = 'Page ' + (doc.internal as unknown as { getNumberOfPages: () => number }).getNumberOfPages();
      doc.text(str, data.settings.margin.left, doc.internal.pageSize.height - 10);
      doc.text('This report is for informational purposes only. Not official tax advice.', data.settings.margin.left, doc.internal.pageSize.height - 15);
    }
  });

  doc.save(`${deal.propertyName || 'Property'}_Tax_Report.pdf`);
}

// ─── Helper: Generate Itemized CSV ─────────────────────
function generateItemizedCSV(items: LedgerItem[]): string {
  const headers = ['Date', 'Type', 'Category', 'Description', 'Status', 'Amount'];

  const rows = items.map(item => {
    return [
      new Date(item.createdAt).toLocaleDateString(),
      item.type,
      item.category,
      `"${item.description.replace(/"/g, '""')}"`, // Escape quotes for CSV
      item.status,
      item.amount.toString()
    ].join(',');
  });

  return [headers.join(','), ...rows].join('\\n');
}

// ─── Helper: Generate Plaintext Report ────────────────
function generateReportText(deal: Project, tax: TaxEstimate, salePrice: number): string {
  const fmt = (n: number) =>
    `$${n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  return [
    `PAPERWORKING — Capital Gains Tax Estimate`,
    `Property: ${deal.propertyName || 'N/A'}`,
    `Generated: ${new Date().toLocaleDateString()}`,
    `──────────────────────────────────────────`,
    `Sale Price:              ${fmt(salePrice)}`,
    `Cost Basis:              ${fmt(tax.costBasis)}`,
    `Sell-Side Costs:         ${fmt(salePrice - tax.netProceeds)}`,
    `Net Proceeds:            ${fmt(tax.netProceeds)}`,
    `──────────────────────────────────────────`,
    `Capital Gain / (Loss):   ${fmt(tax.capitalGain)}`,
    `Holding Period:          ${tax.holdingPeriodDays} days (${tax.isLongTerm ? 'Long-Term' : 'Short-Term'})`,
    `Estimated Tax Rate:      ${tax.estimatedTaxRate}%`,
    `Tax Liability:           ${fmt(tax.estimatedTaxLiability)}`,
    `──────────────────────────────────────────`,
    `NET AFTER TAX:           ${fmt(tax.netAfterTax)}`,
    ``,
    `⚠ Estimate only. Consult a CPA.`,
  ].join('\n');
}

'use client';

import React, { useMemo } from 'react';
import Link from 'next/link';
import type { Project } from '@/types/schema';
import { deriveAllMetrics } from '@/lib/metrics/reiMetrics';
import { PHASE_COLORS as CANONICAL_PHASES } from '@/lib/constants/phaseColors';

/* ═══════════════════════════════════════════════════════════════════
   ProjectCard — Shared project card used on Dashboard & Projects

   A glass-card surface rendering a single project with:
   ● Phase color stripe (left edge)
   ● Property name + address + type chip
   ● State pill (Draft / Live / Realized)
   ● KPI mini-strip (NOI, Cap Rate, Cash Flow) for active projects
   ● Progress bar for drafts
   ● Full-card link to /dashboard/projects/[id]/phase-[n]

   Variants:
   - "default"  — full card with KPIs (projects grid)
   - "compact"  — condensed card for dashboard recent list
   ═══════════════════════════════════════════════════════════════════ */

/* ── Phase Color Map ── */
const PHASE_COLORS: Record<number, { stripe: string; glow: string; label: string }> = {
  1: { stripe: CANONICAL_PHASES[1].hex, glow: CANONICAL_PHASES[1].bgHex, label: CANONICAL_PHASES[1].label },
  2: { stripe: CANONICAL_PHASES[2].hex, glow: CANONICAL_PHASES[2].bgHex, label: CANONICAL_PHASES[2].label },
  3: { stripe: CANONICAL_PHASES[3].hex, glow: CANONICAL_PHASES[3].bgHex, label: CANONICAL_PHASES[3].label },
  4: { stripe: CANONICAL_PHASES[4].hex, glow: CANONICAL_PHASES[4].bgHex, label: CANONICAL_PHASES[4].label },
};

/* ── Strategy to display label ── */
function getStrategyLabel(strategy?: string): string {
  if (!strategy) return 'Mixed';
  if (strategy === 'Sell' || strategy === 'Fix & Flip') return 'Fix & Flip';
  if (strategy === 'Rent' || strategy === 'Buy & Hold') return 'Rental';
  return 'Mixed';
}

/* ── Asset class chip label ── */
function getAssetLabel(assetClass?: string): string {
  if (!assetClass) return 'SFR';
  switch (assetClass) {
    case 'Residential':   return 'SFR';
    case 'Multi-Family':  return 'Multi';
    case 'Commercial':    return 'Commercial';
    case 'Land':          return 'Land';
    default:              return 'SFR';
  }
}

/* ── State classification ── */
type ProjectState = 'draft' | 'live' | 'realized';

function classifyState(project: Project): ProjectState {
  const s = project.status;
  if (s === 'exit') return 'realized';
  if (s === 'acquisition' || (!project.financials?.purchasePrice && !project.financials?.estimatedARV)) return 'draft';
  return 'live';
}

const STATE_PILLS: Record<ProjectState, { bg: string; text: string; label: string; pulse?: boolean }> = {
  draft:    { bg: 'rgba(156,163,175,0.15)', text: '#9CA3AF', label: 'DRAFT' },
  live:     { bg: 'rgba(63, 125, 32,0.15)',   text: '#3f7d20', label: 'LIVE', pulse: true },
  realized: { bg: 'rgba(59,130,246,0.15)',   text: '#3B82F6', label: 'REALIZED' },
};

/* ── Wizard completion heuristic for drafts ── */
function getWizardCompletion(project: Project): number {
  let filled = 0;
  let total = 6;
  if (project.propertyName) filled++;
  if (project.address) filled++;
  if (project.financials?.purchasePrice) filled++;
  if (project.financials?.estimatedARV || project.financials?.arv) filled++;
  if (project.dispositionType) filled++;
  if (project.assetClass) filled++;
  return Math.round((filled / total) * 100);
}

/* ── Format currency (compact) ── */
function fmtCurrency(value: number): string {
  if (Math.abs(value) >= 1_000_000) return `$${(value / 1_000_000).toFixed(1)}M`;
  if (Math.abs(value) >= 1_000) return `$${(value / 1_000).toFixed(1)}k`;
  return `$${value.toFixed(0)}`;
}

/* ══════════════════════════════════════════
   ProjectCard — Component
   ══════════════════════════════════════════ */

import toast from 'react-hot-toast';

export interface ProjectCardProps {
  project: Project;
  variant?: 'default' | 'compact';
  showKPIs?: boolean;
}

export function ProjectCard({
  project,
  variant = 'default',
  showKPIs = true,
}: ProjectCardProps) {
  const phase = project.currentPhase ?? 1;
  const phaseConfig = PHASE_COLORS[phase] ?? PHASE_COLORS[1];
  const state = classifyState(project);
  const pill = STATE_PILLS[state];
  const assetLabel = getAssetLabel(project.assetClass);
  const strategy = project.dispositionType === 'RENT'
    ? (project.subStrategy === 'BRRRR' ? 'Rent' : 'Buy & Hold')
    : (project.subStrategy === 'WHOLESALE' ? 'Sell' : 'Fix & Flip');
  const strategyLabel = getStrategyLabel(strategy);
  const hasPartners = (project.fractionalInvestors?.length ?? 0) > 0;
  const ownership = project.financials?.ownershipPercentage ?? 100;

  // Compute metrics for KPI strip
  const metrics = useMemo(() => {
    if (!showKPIs || state === 'draft') return null;
    return deriveAllMetrics(
      project.financials,
      project.financials?.estimatedCurrentValue,
      project.dispositionType,
      project.currentPhase,
      project.createdAt
    );
  }, [project, showKPIs, state]);

  // KPI values
  const noiValue = metrics?.noi ?? 0;
  const capRateValue = metrics?.capRate ?? 0;
  const cashFlowValue = metrics?.annualCashFlow ?? 0;

  const wizardCompletion = state === 'draft' ? getWizardCompletion(project) : 0;

  const linkHref = `/dashboard/projects/${project.id}/phase-${phase}`;
  const isCompact = variant === 'compact';

  const handleClick = (e: React.MouseEvent) => {
    if (typeof window !== 'undefined' && window.location.pathname.startsWith('/demo')) {
      e.preventDefault();
      toast.error('Demo Mode: Sign up to view detailed project workspaces.', {
        id: 'demo-click-guard',
        style: { background: '#111', color: '#fff', border: '1px solid #333' }
      });
    }
  };

  return (
    <Link
      href={linkHref}
      onClick={handleClick}
      className={`group block rounded-xl transition-all duration-200 
        hover:translate-y-[-2px] hover:shadow-[0_8px_30px_-8px_rgba(0,0,0,0.3)]
        focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary/50
        ${state === 'draft' ? 'opacity-75 hover:opacity-100' : ''}
      `}
    >
      <div
        className={`relative flex overflow-hidden rounded-xl backdrop-blur-xl
          ${isCompact ? 'min-h-[100px]' : 'min-h-[180px]'}
        `}
        style={{
          backgroundColor: 'rgba(255,255,255,0.03)',
          border: '1px solid rgba(255,255,255,0.06)',
        }}
      >
        {/* ── Phase Color Stripe (left edge) ── */}
        <div
          className="w-1 shrink-0 rounded-l-xl"
          style={{ backgroundColor: phaseConfig.stripe }}
        />

        {/* ── Card Content ── */}
        <div className={`flex-1 flex flex-col ${isCompact ? 'p-3 gap-2' : 'p-4 gap-3'}`}>
          {/* Row 1: Header — Name, pills, chips */}
          <div className="flex items-start justify-between gap-2">
            <div className="min-w-0 flex-1">
              <h3
                className={`font-semibold truncate tracking-tight ${isCompact ? 'text-sm' : 'text-base'}`}
                style={{ color: 'rgba(253,255,252,0.95)' }}
              >
                {project.propertyName}
              </h3>
              <p
                className="text-[11px] truncate mt-0.5 flex items-center gap-1"
                style={{ color: 'rgba(253,255,252,0.45)' }}
              >
                <span className="material-symbols-outlined text-[12px]">location_on</span>
                {project.address}
              </p>
            </div>

            {/* State pill */}
            <span
              className="shrink-0 inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider"
              style={{ backgroundColor: pill.bg, color: pill.text }}
            >
              {pill.pulse && (
                <span className="relative flex h-1.5 w-1.5">
                  <span
                    className="animate-ping absolute inline-flex h-full w-full rounded-full opacity-75"
                    style={{ backgroundColor: pill.text }}
                  />
                  <span
                    className="relative inline-flex rounded-full h-1.5 w-1.5"
                    style={{ backgroundColor: pill.text }}
                  />
                </span>
              )}
              {pill.label}
            </span>
          </div>

          {/* Row 2: Chips — Asset type, Strategy, Ownership, Phase */}
          <div className="flex flex-wrap items-center gap-1.5">
            {/* Asset type chip */}
            <span
              className="px-2 py-0.5 rounded text-[9px] font-semibold uppercase tracking-wider"
              style={{
                backgroundColor: 'rgba(255,255,255,0.06)',
                color: 'rgba(253,255,252,0.6)',
              }}
            >
              {assetLabel}
            </span>

            {/* Strategy chip */}
            <span
              className="px-2 py-0.5 rounded text-[9px] font-semibold uppercase tracking-wider"
              style={{
                backgroundColor: `${phaseConfig.stripe}15`,
                color: phaseConfig.stripe,
              }}
            >
              {strategyLabel}
            </span>

            {/* Phase chip */}
            <span
              className="px-2 py-0.5 rounded text-[9px] font-semibold uppercase tracking-wider"
              style={{
                backgroundColor: `${phaseConfig.stripe}10`,
                color: `${phaseConfig.stripe}cc`,
                border: `1px solid ${phaseConfig.stripe}20`,
              }}
            >
              P{phase} · {phaseConfig.label}
            </span>

            {/* Ownership chip (only if partners) */}
            {hasPartners && ownership < 100 && (
              <span
                className="px-2 py-0.5 rounded text-[9px] font-semibold uppercase tracking-wider"
                style={{
                  backgroundColor: 'rgba(69, 73, 85,0.1)',
                  color: '#454955',
                }}
              >
                {ownership}% owned
              </span>
            )}
          </div>

          {/* Row 3: KPI Mini-Strip (active projects only) */}
          {showKPIs && state !== 'draft' && metrics && !isCompact && (
            <div
              className="grid grid-cols-3 gap-3 mt-auto pt-3"
              style={{ borderTop: '1px solid rgba(255,255,255,0.05)' }}
            >
              <KPIMiniCell label="NOI" value={fmtCurrency(noiValue)} />
              <KPIMiniCell label="Cap Rate" value={`${capRateValue.toFixed(1)}%`} />
              <KPIMiniCell label="Cash Flow" value={fmtCurrency(cashFlowValue)} />
            </div>
          )}

          {/* Compact KPI row */}
          {showKPIs && state !== 'draft' && metrics && isCompact && (
            <div className="flex items-center gap-4 mt-auto">
              <span className="text-[10px] font-medium" style={{ color: 'rgba(253,255,252,0.5)' }}>
                NOI <span className="text-[11px] font-bold" style={{ color: 'rgba(253,255,252,0.85)', fontVariantNumeric: 'tabular-nums' }}>{fmtCurrency(noiValue)}</span>
              </span>
              <span className="text-[10px] font-medium" style={{ color: 'rgba(253,255,252,0.5)' }}>
                Cap <span className="text-[11px] font-bold" style={{ color: 'rgba(253,255,252,0.85)', fontVariantNumeric: 'tabular-nums' }}>{capRateValue.toFixed(1)}%</span>
              </span>
            </div>
          )}

          {/* Row 3 alt: Draft progress bar */}
          {state === 'draft' && !isCompact && (
            <div className="mt-auto pt-3 space-y-1.5" style={{ borderTop: '1px solid rgba(255,255,255,0.05)' }}>
              <div className="flex justify-between items-end">
                <span className="text-[10px] font-semibold uppercase tracking-wider" style={{ color: 'rgba(253,255,252,0.5)' }}>
                  Setup Progress
                </span>
                <span className="text-[10px] font-mono" style={{ color: 'rgba(253,255,252,0.4)', fontVariantNumeric: 'tabular-nums' }}>
                  {wizardCompletion}%
                </span>
              </div>
              <div className="h-1 w-full rounded-full overflow-hidden" style={{ backgroundColor: 'rgba(255,255,255,0.06)' }}>
                <div
                  className="h-full rounded-full transition-all duration-500"
                  style={{
                    width: `${wizardCompletion}%`,
                    backgroundColor: '#9CA3AF',
                  }}
                />
              </div>
              <span className="text-[10px] font-medium" style={{ color: '#F59E0B' }}>
                Resume Draft →
              </span>
            </div>
          )}

          {/* Draft CTA for compact */}
          {state === 'draft' && isCompact && (
            <span className="text-[10px] font-medium mt-auto" style={{ color: '#F59E0B' }}>
              Resume Draft →
            </span>
          )}
        </div>

        {/* Hover overlay */}
        <div
          className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none rounded-xl"
          style={{ backgroundColor: 'rgba(255,255,255,0.02)' }}
        />
      </div>
    </Link>
  );
}

/* ── KPI Mini Cell ── */
function KPIMiniCell({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <p
        className="text-[9px] font-semibold uppercase tracking-wider mb-0.5"
        style={{ color: 'rgba(253,255,252,0.4)' }}
      >
        {label}
      </p>
      <p
        className="text-sm font-bold"
        style={{ color: 'rgba(253,255,252,0.9)', fontVariantNumeric: 'tabular-nums' }}
      >
        {value}
      </p>
    </div>
  );
}

export default ProjectCard;

'use client';

import React, { useState } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { RoleGuard } from '@/components/RoleGuard';
import { UploadCloud, FileText, CheckCircle2, Sliders, Info } from 'lucide-react';
import { usePermissions } from '@/hooks/usePermissions';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { storage } from '@/lib/firebase/config';
import { Switch } from '../ui';

export default function LenderVault() {
  const currentProject = useProjectStore((state) => state.currentProject);
  const updateProjectFinancials = useProjectStore((state) => state.updateProjectFinancials);
  const [uploading, setUploading] = useState(false);
  const [rollPoints, setRollPoints] = useState(false);
  const [sellerConcessions, setSellerConcessions] = useState(false);


  const docs = currentProject?.financials?.preApprovalDocuments || [];

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files?.length || !currentProject) return;

    setUploading(true);
    try {
      const file = e.target.files[0];
      const storageRef = ref(storage, `projects/${currentProject.id}/lenderVault/${file.name}`);

      await uploadBytes(storageRef, file);
      const downloadURL = await getDownloadURL(storageRef);

      const newDocs = [...docs, downloadURL];

      updateProjectFinancials(currentProject.id, {
        preApprovalDocuments: newDocs
      });
    } catch (error) {
      console.error("Upload failed:", error);
    } finally {
      setUploading(false);
    }
  };

  if (!currentProject) return null;

  return (
    <div className="bg-bg-surface border border-border-accent rounded-xl p-6 shadow-sm">
      <h3 className="text-lg font-semibold text-text-primary border-b pb-4 mb-4">Lender Pre-Approval Vault</h3>

      {docs.length > 0 ? (
        <ul className="space-y-3 mb-6">
          {docs.map((docUrl, idx) => (
            <li key={idx} className="flex items-center justify-between p-3 bg-bg-primary rounded-lg border border-border-accent">
              <div className="flex items-center space-x-3 text-sm text-text-primary">
                <FileText className="w-4 h-4 text-[#454955]" />
                <span className="truncate max-w-[200px]">
                  {docUrl.split('/').pop()}
                </span>
              </div>
              <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-[#3f7d20]/15 text-[#3f7d20]">
                <CheckCircle2 className="w-3 h-3 mr-1" /> Verified
              </span>
            </li>
          ))}
        </ul>
      ) : (
        <p className="text-sm text-text-secondary mb-6 italic">No pre-approval documents uploaded yet.</p>
      )}

      {/* Write Access: Investors and General Contractors */}
      <RoleGuard 
        allowedRoles={['Lead Investor', 'General Contractor']} 
        fallback={
           <p className="text-xs text-text-secondary text-center uppercase tracking-wider py-2">
             Read-Only View Enabled for Lender
           </p>
        }
      >
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 mb-4">

            <div className="border border-border-accent rounded-xl p-4 bg-bg-primary flex flex-col justify-between space-y-4">
                <div>
                   <h4 className="text-sm font-semibold flex items-center text-text-primary mb-1"><Sliders className="w-4 h-4 mr-2 text-[#454955]"/> Fee Spreading Logistics</h4>
                   <p className="text-xs text-text-secondary">Structurally modify capital stack configurations prior to closing.</p>
                </div>

                <div className="space-y-3">
                    <label className="flex items-center justify-between cursor-pointer p-2 hover:bg-bg-primary rounded-md transition">
                        <span className="text-sm font-medium text-text-primary flex flex-col">
                            Roll Points Into Loan
                            <span className="text-xs text-text-secondary font-normal mt-0.5">Subtracts from upfront Cash-to-Close</span>
                        </span>
                        <Switch checked={rollPoints} onChange={() => setRollPoints(!rollPoints)} />
                    </label>

                    <label className="flex items-center justify-between cursor-pointer p-2 hover:bg-bg-primary rounded-md transition">
                        <span className="text-sm font-medium text-text-primary flex flex-col">
                            Apply Seller Concessions
                            <span className="text-xs text-text-secondary font-normal mt-0.5">Credits closing costs heavily</span>
                        </span>
                        <Switch checked={sellerConcessions} onChange={() => setSellerConcessions(!sellerConcessions)} />
                    </label>
                </div>
                { (rollPoints || sellerConcessions) && (
                   <div className="flex items-start text-xs text-text-secondary bg-[#454955]/10 p-2 rounded border border-[#454955]/20">
                      <Info className="w-3 h-3 mr-1.5 flex-shrink-0 mt-px text-[#454955]" />
                      Math has been internally adjusted. Check the Engine Room for final Cash-to-Close figures.
                   </div>
                )}
            </div>

            <div className="border-2 border-dashed border-border-accent rounded-xl p-6 text-center hover:bg-bg-primary transition-colors flex flex-col justify-center h-full">
              <UploadCloud className="w-8 h-8 text-text-secondary mx-auto mb-2" />
              <p className="text-sm font-medium text-text-primary mb-1">
                {uploading ? 'Uploading securely...' : 'Upload Pre-Approval PDF'}
              </p>
              <p className="text-xs text-text-secondary mb-4">Max size: 10MB</p>
              <input 
                 type="file" 
                 accept="application/pdf"
                 className="hidden" 
                 id="file-upload" 
                 onChange={handleFileUpload}
                 disabled={uploading}
              />
              <label 
                 htmlFor="file-upload"
                 className="inline-flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-md shadow-sm text-white bg-[#454955] hover:bg-[#454955]/90 cursor-pointer disabled:opacity-50"
              >
                 Browse Files
              </label>
            </div>

        </div>
      </RoleGuard>
    </div>
  );
}

