'use client';

import React, { useState, useEffect } from 'react';
import { Search, MapPin, Home, DollarSign, TrendingUp, ChevronRight, X, Ruler, Loader2 } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   PropertyDiscovery — MLS Search Hook + Property Card

   MLS typeahead via /api/mls/search → populates a "Property Card" with:
   • Property image placeholder
   • Bed/bath count, sqft
   • Owner's asking price (read-only from MLS or editable)
   • User's Target Purchase Price (MAO)
   • Estimated Rehab Budget
   ═══════════════════════════════════════════════════════ */

interface PropertyResult {
  id: string;
  address: string;
  city: string;
  state: string;
  zip: string;
  beds: number;
  baths: number;
  sqft: number;
  askingPrice: number;
  yearBuilt: number;
  imageUrl?: string;
}

interface Props {
  onPropertySelected?: (data: {
    address: string;
    askingPrice: number;
    targetPrice: number;
    rehabBudget: number;
    sqft: number;
  }) => void;
}

export default function PropertyDiscovery({ onPropertySelected }: Props) {
  const [searchQuery, setSearchQuery] = useState('');
  const [showResults, setShowResults] = useState(false);
  const [results, setResults] = useState<PropertyResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [searchError, setSearchError] = useState<string | null>(null);
  const [noResults, setNoResults] = useState(false);
  const [selectedProperty, setSelectedProperty] = useState<PropertyResult | null>(null);
  const [targetPrice, setTargetPrice] = useState('');
  const [rehabBudget, setRehabBudget] = useState('');

  useEffect(() => {
    if (!searchQuery.trim() || searchQuery.length < 2) {
      setResults([]);
      setNoResults(false);
      setSearchError(null);
      return;
    }

    const timer = setTimeout(async () => {
      setLoading(true);
      setSearchError(null);
      setNoResults(false);
      try {
        const res = await fetch(`/api/mls/search?q=${encodeURIComponent(searchQuery)}`);
        if (res.ok) {
          const data = await res.json();
          const list = Array.isArray(data) ? data : [];
          setResults(list);
          setNoResults(list.length === 0);
        } else {
          const body = await res.json().catch(() => ({}));
          setResults([]);
          setSearchError(body.error || 'MLS search unavailable — check back shortly.');
        }
      } catch (err) {
        console.error('Search failed', err);
        setResults([]);
        setSearchError('Could not reach MLS. Check your connection and try again.');
      } finally {
        setLoading(false);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [searchQuery]);

  const handleSelect = (property: PropertyResult) => {
    setSelectedProperty(property);
    setSearchQuery('');
    setShowResults(false);
    // Auto-fill MAO: 70% of asking = rough investor formula
    const mao = Math.round(property.askingPrice * 0.7);
    setTargetPrice(mao.toString());
  };

  const handleClear = () => {
    setSelectedProperty(null);
    setTargetPrice('');
    setRehabBudget('');
  };

  const handleApply = () => {
    if (!selectedProperty) return;
    onPropertySelected?.({
      address: `${selectedProperty.address}, ${selectedProperty.city}, ${selectedProperty.state} ${selectedProperty.zip}`,
      askingPrice: selectedProperty.askingPrice,
      targetPrice: parseFloat(targetPrice) || 0,
      rehabBudget: parseFloat(rehabBudget) || 0,
      sqft: selectedProperty.sqft,
    });
  };

  const totalCapitalNeeded = (parseFloat(targetPrice) || 0) + (parseFloat(rehabBudget) || 0);

  return (
    <div className="space-y-4">
      {/* Search Bar */}
      <div className="relative">
        <Search className="absolute left-4 top-1/2 -translate-y-1/2 w-4 h-4 text-text-secondary" />
        <input
          type="text"
          value={searchQuery}
          onChange={(e) => { setSearchQuery(e.target.value); setShowResults(true); }}
          onFocus={() => setShowResults(true)}
          placeholder="Search MLS by address, city, or zip..."
          className="w-full pl-11 pr-4 py-3 bg-bg-primary border border-border-accent rounded-xl text-sm focus:border-[#454955] focus:ring-1 focus:ring-[#454955] transition placeholder:text-text-secondary"
        />

        {/* Dropdown Results / States */}
        {showResults && searchQuery.length >= 2 && (
          <div className="absolute z-20 top-full mt-2 w-full bg-bg-surface border border-border-accent rounded-xl shadow-lg overflow-hidden">
            {loading && (
              <div className="flex items-center gap-2 px-4 py-3 text-sm text-text-secondary">
                <Loader2 className="w-4 h-4 animate-spin" /> Searching MLS…
              </div>
            )}
            {!loading && searchError && (
              <div className="px-4 py-3 text-sm text-red-600">{searchError}</div>
            )}
            {!loading && !searchError && noResults && (
              <div className="px-4 py-3 text-sm text-text-secondary">
                No active listings found for &ldquo;{searchQuery}&rdquo;.
              </div>
            )}
            {!loading && results.map(p => (
              <button
                key={p.id}
                onClick={() => handleSelect(p)}
                className="w-full flex items-center gap-3 px-4 py-3 hover:bg-[#F0F1F4] transition text-left"
              >
                <MapPin className="w-4 h-4 text-[#3a3e4a] shrink-0" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-text-primary truncate">{p.address}</p>
                  <p className="text-xs text-text-secondary">{p.city}, {p.state} {p.zip} · {p.beds}bd/{p.baths}ba · {p.sqft.toLocaleString()} sqft</p>
                </div>
                <span className="text-sm font-semibold text-text-primary">${p.askingPrice.toLocaleString()}</span>
                <ChevronRight className="w-4 h-4 text-gray-300" />
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Selected Property Card */}
      {selectedProperty && (
        <div className="bg-bg-surface border border-border-accent rounded-2xl overflow-hidden">
          {/* Property Header */}
          <div className="relative h-32 bg-gradient-to-br from-[#E8E9ED] to-[#F0F1F4] flex items-center justify-center">
            <Home className="w-12 h-12 text-[#8a8e9a]" />
            <button
              onClick={handleClear}
              className="absolute top-3 right-3 p-1.5 bg-bg-surface/80 rounded-full hover:bg-bg-surface transition"
            >
              <X className="w-3.5 h-3.5 text-text-secondary" />
            </button>
          </div>

          <div className="p-5 space-y-4">
            {/* Address & Details */}
            <div>
              <h3 className="text-base font-semibold text-text-primary">{selectedProperty.address}</h3>
              <p className="text-sm text-text-secondary">{selectedProperty.city}, {selectedProperty.state} {selectedProperty.zip}</p>
              <div className="flex items-center gap-4 mt-2">
                <span className="inline-flex items-center gap-1 text-xs text-text-secondary">
                  <Home className="w-3 h-3" /> {selectedProperty.beds}bd / {selectedProperty.baths}ba
                </span>
                <span className="inline-flex items-center gap-1 text-xs text-text-secondary">
                  <Ruler className="w-3 h-3" /> {selectedProperty.sqft.toLocaleString()} sqft
                </span>
                <span className="text-xs text-text-secondary">Built {selectedProperty.yearBuilt}</span>
              </div>
            </div>

            {/* Financial Inputs */}
            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="ag-label mb-1.5 block">Asking Price</label>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-secondary" />
                  <input
                    type="text"
                    readOnly
                    value={selectedProperty.askingPrice.toLocaleString()}
                    className="w-full pl-8 pr-3 py-2.5 bg-bg-primary border border-border-accent rounded-lg text-sm text-text-secondary cursor-not-allowed"
                  />
                </div>
              </div>
              <div>
                <label className="ag-label mb-1.5 block">Target Price (MAO)</label>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[#454955]" />
                  <input
                    type="number"
                    value={targetPrice}
                    onChange={(e) => setTargetPrice(e.target.value)}
                    placeholder="0"
                    className="w-full pl-8 pr-3 py-2.5 bg-bg-surface border border-border-accent rounded-lg text-sm focus:border-[#454955] focus:ring-1 focus:ring-[#454955] transition"
                  />
                </div>
              </div>
              <div>
                <label className="ag-label mb-1.5 block">Rehab Budget</label>
                <div className="relative">
                  <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-[#454955]" />
                  <input
                    type="number"
                    value={rehabBudget}
                    onChange={(e) => setRehabBudget(e.target.value)}
                    placeholder="0"
                    className="w-full pl-8 pr-3 py-2.5 bg-bg-surface border border-border-accent rounded-lg text-sm focus:border-[#454955] focus:ring-1 focus:ring-[#454955] transition"
                  />
                </div>
              </div>
            </div>

            {/* Summary */}
            <div className="flex items-center justify-between bg-[#F0F1F4] rounded-xl px-4 py-3">
              <div className="flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-[#3a3e4a]" />
                <span className="text-sm font-medium text-[#2E3140]">Total Capital Needed</span>
              </div>
              <span className="text-lg font-bold text-[#FDFFFC]">${totalCapitalNeeded.toLocaleString()}</span>
            </div>

            {/* Apply Button */}
            <button
              onClick={handleApply}
              disabled={!targetPrice}
              className="w-full py-2.5 bg-gray-900 text-white text-sm font-medium rounded-xl hover:bg-gray-800 disabled:bg-gray-200 disabled:text-text-secondary disabled:cursor-not-allowed transition"
            >
              Set as Active Property
            </button>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!selectedProperty && (
        <div className="flex flex-col items-center justify-center py-10 text-center">
          <div className="w-14 h-14 bg-[#F0F1F4] rounded-2xl flex items-center justify-center mb-3">
            <MapPin className="w-6 h-6 text-[#6E7480]" />
          </div>
          <p className="text-sm font-medium text-text-secondary mb-1">No property selected</p>
          <p className="text-xs text-text-secondary">Search the MLS to find your next deal</p>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Users, Mail, FileSignature, Clock, CheckCircle2, XCircle, Eye, UserPlus, Award, MoreHorizontal, Send } from 'lucide-react';
import type { InvestorCommitment, LOIStatus } from '@/types/schema';

/* ═══════════════════════════════════════════════════════
   SyndicationEngine — Investor Roster Data Table

   Columns: Name | Email | Pledged | LOI Status | Actions
   Features:
   • Returning Investor badge
   • Per-row "Send LOI" action
   • "Invite Investor" CTA
   ═══════════════════════════════════════════════════════ */

interface Props {
  investors: InvestorCommitment[];
  onInviteClick: () => void;
  onSendLOI: (investorId: string) => void;
  onViewLOI?: (investorId: string) => void;
}

const STATUS_CONFIG: Record<LOIStatus, { icon: React.ReactNode; color: string; bg: string }> = {
  Drafted:  { icon: <Clock className="w-3.5 h-3.5" />,          color: 'text-text-secondary',   bg: 'bg-bg-primary' },
  Sent:     { icon: <Send className="w-3.5 h-3.5" />,           color: 'text-blue-600',   bg: 'bg-blue-50' },
  Viewed:   { icon: <Eye className="w-3.5 h-3.5" />,            color: 'text-amber-600',  bg: 'bg-amber-50' },
  Signed:   { icon: <CheckCircle2 className="w-3.5 h-3.5" />,   color: 'text-pw-success', bg: 'bg-pw-success-container border border-pw-success-border' },
  Declined: { icon: <XCircle className="w-3.5 h-3.5" />,        color: 'text-red-500',    bg: 'bg-red-50' },
};

function formatCurrency(amount: number): string {
  if (amount >= 1_000_000) return `$${(amount / 1_000_000).toFixed(1)}M`;
  if (amount >= 1_000) return `$${(amount / 1_000).toFixed(0)}K`;
  return `$${amount.toLocaleString()}`;
}

export default function SyndicationEngine({ investors, onInviteClick, onSendLOI, onViewLOI }: Props) {
  const [hoveredRow, setHoveredRow] = useState<string | null>(null);

  const totalPledged = investors.reduce((sum, inv) => sum + inv.pledgedAmount, 0);
  const signedCount = investors.filter(i => i.loiStatus === 'Signed').length;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 bg-[#F0F1F4] rounded-xl flex items-center justify-center">
            <Users className="w-4.5 h-4.5 text-[#3a3e4a]" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-text-primary">Investment Team Roster</h3>
            <p className="text-xs text-text-secondary">
              {investors.length} investor{investors.length !== 1 ? 's' : ''} · {formatCurrency(totalPledged)} pledged · {signedCount} signed
            </p>
          </div>
        </div>
        <button
          onClick={onInviteClick}
          className="inline-flex items-center gap-2 px-4 py-2 bg-gray-900 text-white text-xs font-medium rounded-xl hover:bg-gray-800 transition"
        >
          <UserPlus className="w-3.5 h-3.5" />
          Invite Investor
        </button>
      </div>

      {/* Table */}
      {investors.length > 0 ? (
        <div className="bg-bg-surface border border-border-accent rounded-2xl overflow-hidden">
          {/* Table Header */}
          <div className="grid grid-cols-12 gap-2 px-5 py-3 bg-bg-primary border-b border-border-accent">
            <span className="col-span-3 ag-label">Investor</span>
            <span className="col-span-3 ag-label">Email</span>
            <span className="col-span-2 ag-label text-right">Pledged</span>
            <span className="col-span-2 ag-label text-center">LOI Status</span>
            <span className="col-span-2 ag-label text-right">Actions</span>
          </div>

          {/* Rows */}
          {investors.map((inv) => {
            const statusCfg = STATUS_CONFIG[inv.loiStatus];
            return (
              <div
                key={inv.id}
                className="grid grid-cols-12 gap-2 px-5 py-3.5 items-center border-b border-gray-50 last:border-b-0 hover:bg-bg-primary/50 transition-colors"
                onMouseEnter={() => setHoveredRow(inv.id)}
                onMouseLeave={() => setHoveredRow(null)}
              >
                {/* Name + Returning Badge */}
                <div className="col-span-3 flex items-center gap-2 min-w-0">
                  <div className="w-8 h-8 bg-[#E8E9ED] rounded-full flex items-center justify-center shrink-0">
                    <span className="text-xs font-semibold text-[#454955]">
                      {inv.investorName.split(' ').map(n => n[0]).join('').slice(0, 2)}
                    </span>
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-text-primary truncate">{inv.investorName}</p>
                    {inv.isReturning && (
                      <span className="inline-flex items-center gap-1 text-[10px] font-medium text-amber-700 bg-amber-50 px-1.5 py-0.5 rounded-full">
                        <Award className="w-2.5 h-2.5" />
                        {inv.previousDealCount} deal{inv.previousDealCount !== 1 ? 's' : ''}
                      </span>
                    )}
                  </div>
                </div>

                {/* Email */}
                <div className="col-span-3 min-w-0">
                  <p className="text-sm text-text-secondary truncate">{inv.investorEmail}</p>
                </div>

                {/* Pledged */}
                <div className="col-span-2 text-right">
                  <span className="text-sm font-semibold text-text-primary">
                    {formatCurrency(inv.pledgedAmount)}
                  </span>
                </div>

                {/* LOI Status */}
                <div className="col-span-2 flex justify-center">
                  <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium ${statusCfg.color} ${statusCfg.bg}`}>
                    {statusCfg.icon}
                    {inv.loiStatus}
                  </span>
                </div>

                {/* Actions */}
                <div className="col-span-2 flex items-center justify-end gap-1.5">
                  {inv.loiStatus === 'Drafted' && (
                    <button
                      onClick={() => onSendLOI(inv.id)}
                      className="inline-flex items-center gap-1 px-3 py-1.5 bg-[#3a3e4a] text-white text-xs font-medium rounded-lg hover:bg-[#454955] transition"
                    >
                      <FileSignature className="w-3 h-3" />
                      Send LOI
                    </button>
                  )}
                  {(inv.loiStatus === 'Sent' || inv.loiStatus === 'Viewed' || inv.loiStatus === 'Signed') && (
                    <button
                      onClick={() => onViewLOI?.(inv.id)}
                      className="inline-flex items-center gap-1 px-3 py-1.5 bg-bg-primary text-text-secondary text-xs font-medium rounded-lg hover:bg-gray-200 transition"
                    >
                      <Eye className="w-3 h-3" />
                      View
                    </button>
                  )}
                  {hoveredRow === inv.id && (
                    <button className="p-1.5 rounded-lg hover:bg-bg-primary transition">
                      <MoreHorizontal className="w-4 h-4 text-text-secondary" />
                    </button>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        /* Empty State */
        <div className="flex flex-col items-center justify-center py-12 text-center bg-bg-surface border border-dashed border-border-accent rounded-2xl">
          <div className="w-14 h-14 bg-[#F0F1F4] rounded-2xl flex items-center justify-center mb-3">
            <Users className="w-6 h-6 text-[#6E7480]" />
          </div>
          <p className="text-sm font-medium text-text-secondary mb-1">No investors yet</p>
          <p className="text-xs text-text-secondary mb-4">Start inviting members to your investment team</p>
          <button
            onClick={onInviteClick}
            className="inline-flex items-center gap-2 px-5 py-2.5 bg-gray-900 text-white text-xs font-medium rounded-xl hover:bg-gray-800 transition"
          >
            <UserPlus className="w-3.5 h-3.5" />
            Invite Your First Investor
          </button>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { DollarSign, Percent, Plus, Trash2, ShieldAlert, BarChart2 } from 'lucide-react';
import type { CapitalSource, CapitalSourceType, FundingCategory, FundingSourceStatus } from '@/types/schema';
import toast from 'react-hot-toast';

interface CapitalStackStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

export default function CapitalStackStep({
  initialData,
  onSave,
}: CapitalStackStepProps) {
  const f = initialData?.financials || {};
  const purchasePrice = (f.purchasePrice || 25000000) / 100;
  const rehabBudget = (f.projectedRehabCost || 2500000) / 100;
  const closingCosts = (f.fixedAcquisitionCosts || (purchasePrice * 0.03));
  const holdingReserves = 1200; // suggested reserve

  const totalProjectCost = purchasePrice + rehabBudget + closingCosts + holdingReserves;

  // Stored sources
  const [sources, setSources] = useState<CapitalSource[]>(() => {
    const stack = f.capitalStack || [];
    if (stack.length > 0) return stack;

    // Default fallback starting source
    return [
      {
        id: 'default-1',
        category: 'Conventional Financing',
        type: 'conventional_loan',
        amount: purchasePrice * 0.75,
        interestRate: 6.5,
        termMonths: 360,
        status: 'Exploring',
        notes: 'Primary financing',
      }
    ];
  });

  // Handle adding a source row
  const handleAddSource = () => {
    const newSource: CapitalSource = {
      id: `source_${Math.random().toString(36).substring(2, 9)}`,
      category: 'Conventional Financing',
      type: 'conventional_loan',
      amount: 10000,
      interestRate: 7.0,
      termMonths: 360,
      status: 'Exploring',
      notes: '',
    };
    setSources([...sources, newSource]);
  };

  // Handle updating a single cell field
  const handleUpdateField = (id: string, field: keyof CapitalSource, value: any) => {
    setSources(
      sources.map((s) => {
        if (s.id !== id) return s;
        const updated = { ...s, [field]: value };
        // Map UI category from type
        if (field === 'type') {
          let cat: FundingCategory = 'Conventional Financing';
          if (value === 'hard_money') cat = 'Hard Money Loans';
          else if (value === 'bridge') cat = 'Bridge Loans';
          else if (value === 'solo_cash') cat = 'Borrower Injection';
          else if (value === 'syndication_equity') cat = 'Syndication Equity';
          else if (value === 'co_buyer_equity') cat = 'Co-buying Equity';
          updated.category = cat;
        }
        return updated;
      })
    );
  };

  // Delete a source row
  const handleDeleteSource = (id: string) => {
    setSources(sources.filter((s) => s.id !== id));
  };

  // Perform computations
  const calculations = useMemo(() => {
    let totalRaised = 0;
    let totalDebt = 0;
    let weightedDebtRateSum = 0;
    let monthlyDebtService = 0;

    sources.forEach((s) => {
      const amt = s.amount || 0;
      totalRaised += amt;

      const isDebt = ['conventional_loan', 'hard_money', 'bridge', 'sba_504_bank', 'sba_504_cdc'].includes(s.type || '');
      if (isDebt) {
        totalDebt += amt;
        weightedDebtRateSum += amt * (s.interestRate || 0);

        // Compute monthly debt payment
        const r = (s.interestRate || 0) / 100 / 12;
        const n = s.termMonths || 360;
        let pmt = 0;
        if (s.notes?.toLowerCase().includes('interest only') || s.type === 'hard_money' || s.type === 'bridge') {
          // Interest-only payment
          pmt = amt * ((s.interestRate || 0) / 100) / 12;
        } else {
          // Amortized payment
          pmt = r > 0 ? (amt * r * Math.pow(1 + r, n)) / (Math.pow(1 + r, n) - 1) : amt / n;
        }
        monthlyDebtService += pmt;
      }
    });

    const gapSurplus = totalProjectCost - totalRaised;
    const blendedRate = totalDebt > 0 ? weightedDebtRateSum / totalDebt : 0;

    // Get NOI from acquisition scorecard
    const annualNoi = (f.grossRent || 1800) * 12 * 0.6; // derived estimate if absent
    const dscr = monthlyDebtService > 0 ? (annualNoi / 12) / monthlyDebtService : 0;

    return {
      totalRaised,
      totalDebt,
      gapSurplus,
      blendedRate,
      monthlyDebtService,
      dscr,
    };
  }, [sources, totalProjectCost, f]);

  // Color alerts configurations
  const gapPercent = Math.abs(calculations.gapSurplus) / totalProjectCost;
  const isUnderfunded = calculations.gapSurplus > 0;
  const isOvercapitalized = calculations.gapSurplus < 0 && gapPercent > 0.10;

  const alertState = isUnderfunded
    ? { color: 'border-rose-500/20 bg-rose-500/5 text-rose-400', label: 'Underfunded Gap', msg: `Your capital stack is missing $${calculations.gapSurplus.toLocaleString()} to meet the total project cost. Add more sources.` }
    : isOvercapitalized
    ? { color: 'border-amber-500/20 bg-amber-500/5 text-amber-400', label: 'Over-Capitalized', msg: `Surplus funds exceed 10% of project cost by $${Math.abs(calculations.gapSurplus).toLocaleString()}. Consider adjusting equity levels.` }
    : { color: 'border-emerald-500/20 bg-emerald-500/5 text-emerald-400', label: 'Fully Funded', msg: 'Capital stack matches target requirements. Ready to continue.' };

  const handleContinue = async () => {
    if (isUnderfunded) {
      toast.error('Capital stack is underfunded. Please cover the gap before continuing.');
      return;
    }

    const payload = {
      financials: {
        ...f,
        capitalStack: sources,
        loanAmount: calculations.totalDebt * 100, // Sync actual loan values
        loanInterestRate: calculations.blendedRate,
        annualDebtService: calculations.monthlyDebtService * 12,
        dscr: calculations.dscr,
      },
    };

    await onSave(payload);
  };

  // Stacked chart render widths
  const debtWidth = useMemo(() => {
    if (calculations.totalRaised === 0) return 0;
    return (calculations.totalDebt / calculations.totalRaised) * 100;
  }, [calculations.totalDebt, calculations.totalRaised]);

  const equityWidth = 100 - debtWidth;

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 1: Capital Stack Builder</h3>
        <p className="text-xs text-slate-400">Compose and reconcile capital sources against the total project cost budget.</p>
      </div>

      {/* Visual Stack Chart */}
      <div className="space-y-2 p-4 bg-white/[0.02] border border-white/5 rounded-xl">
        <div className="flex justify-between text-[10px] font-bold uppercase tracking-wider text-slate-400">
          <span>Capital Allocation breakdown</span>
          <span className="text-white text-xs font-semibold">
            ${calculations.totalRaised.toLocaleString()} Raised of ${totalProjectCost.toLocaleString()}
          </span>
        </div>
        <div className="w-full h-6 rounded-lg overflow-hidden flex border border-white/10 bg-white/5 font-mono text-[9px] font-bold text-center leading-6 text-black select-none">
          {debtWidth > 0 && (
            <div
              className="bg-sky-400 transition-all duration-300"
              style={{ width: `${debtWidth}%` }}
              title={`Debt: ${debtWidth.toFixed(1)}%`}
            >
              DEBT ({debtWidth.toFixed(0)}%)
            </div>
          )}
          {equityWidth > 0 && (
            <div
              className="bg-emerald-400 transition-all duration-300"
              style={{ width: `${equityWidth}%` }}
              title={`Equity: ${equityWidth.toFixed(1)}%`}
            >
              EQUITY ({equityWidth.toFixed(0)}%)
            </div>
          )}
        </div>
        <div className="flex justify-between items-center text-[9px] text-slate-500 font-semibold uppercase">
          <span>Debt: ${calculations.totalDebt.toLocaleString()}</span>
          <span>Equity: ${(calculations.totalRaised - calculations.totalDebt).toLocaleString()}</span>
        </div>
      </div>

      {/* Sources Table Inputs */}
      <div className="space-y-3">
        <div className="flex justify-between items-center">
          <span className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Funding Sources Ledger</span>
          <button
            type="button"
            onClick={handleAddSource}
            className="flex items-center gap-1 text-[10px] font-bold uppercase tracking-wider bg-white/5 border border-white/10 text-white hover:bg-white/10 px-3 py-1.5 rounded-lg transition-all"
          >
            <Plus className="w-3.5 h-3.5" /> Add Capital Source
          </button>
        </div>

        <div className="space-y-3 max-h-[300px] overflow-y-auto scrollbar-none pr-1">
          {sources.map((s, index) => (
            <div
              key={s.id}
              className="grid grid-cols-1 sm:grid-cols-12 gap-3 p-3 bg-white/[0.01] border border-white/5 hover:border-white/10 rounded-xl relative group transition-all"
            >
              {/* Type Select */}
              <div className="sm:col-span-3 space-y-1">
                <label className="text-[8px] font-bold uppercase text-slate-500">Source Type</label>
                <select
                  value={s.type}
                  onChange={(e) => handleUpdateField(s.id, 'type', e.target.value)}
                  className="w-full px-2 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
                >
                  <option value="conventional_loan" className="bg-[#181315]">Conventional Loan</option>
                  <option value="hard_money" className="bg-[#181315]">Hard Money Loan</option>
                  <option value="bridge" className="bg-[#181315]">Bridge Loan</option>
                  <option value="solo_cash" className="bg-[#181315]">Solo Cash Injection</option>
                  <option value="syndication_equity" className="bg-[#181315]">Syndication Equity</option>
                  <option value="co_buyer_equity" className="bg-[#181315]">JV/Co-buyer Equity</option>
                </select>
              </div>

              {/* Amount */}
              <div className="sm:col-span-3 space-y-1">
                <label className="text-[8px] font-bold uppercase text-slate-500">Amount ($)</label>
                <div className="relative">
                  <DollarSign className="absolute left-2.5 top-2.5 w-3 h-3 text-slate-500" />
                  <input
                    type="number"
                    value={s.amount || ''}
                    onChange={(e) => handleUpdateField(s.id, 'amount', Number(e.target.value))}
                    className="w-full pl-7 pr-2 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold h-8"
                  />
                </div>
              </div>

              {/* Interest Rate */}
              <div className="sm:col-span-2 space-y-1">
                <label className="text-[8px] font-bold uppercase text-slate-500">Rate (%)</label>
                <div className="relative">
                  <Percent className="absolute right-2.5 top-2.5 w-3 h-3 text-slate-500" />
                  <input
                    type="number"
                    step="0.1"
                    value={s.interestRate || ''}
                    disabled={!['conventional_loan', 'hard_money', 'bridge'].includes(s.type || '')}
                    onChange={(e) => handleUpdateField(s.id, 'interestRate', Number(e.target.value))}
                    className="w-full px-2 pr-7 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold h-8 disabled:opacity-40"
                  />
                </div>
              </div>

              {/* Term */}
              <div className="sm:col-span-2 space-y-1">
                <label className="text-[8px] font-bold uppercase text-slate-500">Term (Mo)</label>
                <input
                  type="number"
                  value={s.termMonths || ''}
                  disabled={!['conventional_loan', 'hard_money', 'bridge'].includes(s.type || '')}
                  onChange={(e) => handleUpdateField(s.id, 'termMonths', Number(e.target.value))}
                  className="w-full px-2 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold h-8 disabled:opacity-40"
                />
              </div>

              {/* Actions/Trash */}
              <div className="sm:col-span-2 flex items-end justify-end h-full">
                <button
                  type="button"
                  onClick={() => handleDeleteSource(s.id)}
                  className="p-2 border border-white/5 hover:border-red-500/20 text-slate-500 hover:text-rose-500 rounded-lg transition-all"
                >
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Alert Banner */}
      <div className={`p-4 border rounded-xl space-y-1 flex items-start gap-3 transition-all ${alertState.color}`}>
        <ShieldAlert className="w-5 h-5 shrink-0 mt-0.5" />
        <div>
          <h4 className="text-xs font-bold uppercase tracking-wider">{alertState.label}</h4>
          <p className="text-xs opacity-80 leading-relaxed mt-0.5">{alertState.msg}</p>
        </div>
      </div>

      {/* Sidebar Metrics Summary */}
      <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3 text-xs">
        <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA] flex items-center gap-1.5">
          <BarChart2 className="w-3.5 h-3.5" /> Projected Capital Pro-Forma
        </h4>
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-center">
          <div className="bg-white/5 p-2.5 rounded-xl">
            <p className="text-[9px] uppercase tracking-wider text-slate-500">Total Project Cost</p>
            <p className="text-sm font-bold text-white">${Math.round(totalProjectCost).toLocaleString()}</p>
          </div>
          <div className="bg-white/5 p-2.5 rounded-xl">
            <p className="text-[9px] uppercase tracking-wider text-slate-500">Blended Rate</p>
            <p className="text-sm font-bold text-white">{calculations.blendedRate.toFixed(2)}%</p>
          </div>
          <div className="bg-white/5 p-2.5 rounded-xl">
            <p className="text-[9px] uppercase tracking-wider text-slate-500">Monthly Debt Service</p>
            <p className="text-sm font-bold text-white">${Math.round(calculations.monthlyDebtService).toLocaleString()}/mo</p>
          </div>
          <div className="bg-white/5 p-2.5 rounded-xl">
            <p className="text-[9px] uppercase tracking-wider text-slate-500">Projected DSCR</p>
            <p className="text-sm font-bold text-emerald-400">{calculations.dscr.toFixed(2)}x</p>
          </div>
        </div>
      </div>

      <div className="flex justify-end pt-4 border-t border-white/5">
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] hover:opacity-90 font-bold uppercase tracking-wider text-[11px] rounded-lg transition-opacity"
        >
          Save & Continue
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { CheckSquare, Square, AlertCircle, FileText, Upload } from 'lucide-react';
import type { ClosingChecklistItem } from '@/types/schema';
import toast from 'react-hot-toast';

interface ClosingChecklistStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

const ITEMS_META = [
  { type: 'Earnest money deposited', notes: 'Verification of initial deposit with escrow' },
  { type: 'Financing contingency satisfied', notes: 'Lender commitment letter fully secured' },
  { type: 'Inspection contingency satisfied', notes: 'Physical parameters approved by investor' },
  { type: 'Appraisal received and accepted', notes: 'Lender appraisal value clearance' },
  { type: 'Title cleared', notes: 'Preliminary search resolved with no encumbrances' },
  { type: 'Insurance bound', notes: 'Hazard binder in place for closing' },
  { type: 'Closing disclosure reviewed and signed', notes: 'HUD-1 settlement statement sign off' },
  { type: 'Wire instructions verified', notes: 'Secured confirmation of title bank details' },
  { type: 'Final walkthrough scheduled', notes: 'Verify property condition prior to keys transfer' },
  { type: 'Closing funds wired', notes: 'Downpayment and fees wire initiated' },
];

export default function ClosingChecklistStep({
  initialData,
  onSave,
}: ClosingChecklistStepProps) {
  const f = initialData?.financials || {};

  // Track checked items
  const [items, setItems] = useState<ClosingChecklistItem[]>(() => {
    const list = initialData?.closingChecklist || [];
    if (list.length >= 10) return list;

    // Default prefill
    return ITEMS_META.map((meta, i) => {
      // Auto prefill some items if we have data
      let completed = false;
      if (meta.type === 'Earnest money deposited' && (f.emdReceiptUrl || f.emdVerified)) {
        completed = true;
      }
      if (meta.type === 'Title cleared' && f.vendorTitleStatus === 'Title cleared') {
        completed = true;
      }
      if (meta.type === 'Insurance bound' && f.vendorInsuranceStatus === 'Bound') {
        completed = true;
      }

      return {
        id: `cc_${i + 1}`,
        type: meta.type as any,
        completed,
        notes: meta.notes,
      };
    });
  });

  const toggleItem = (id: string) => {
    setItems(
      items.map((i) =>
        i.id === id
          ? {
              ...i,
              completed: !i.completed,
              completedAt: !i.completed ? new Date() : undefined,
            }
          : i
      )
    );
  };

  const handleUploadProof = (id: string) => {
    setItems(
      items.map((i) =>
        i.id === id
          ? {
              ...i,
              completed: true,
              documentUrl: '/mock/documents/uploaded_receipt.pdf',
              notes: `${i.notes} (Proof document uploaded)`,
            }
          : i
      )
    );
    toast.success('Document uploaded successfully!');
  };

  const completedCount = items.filter((i) => i.completed).length;
  const progressPercent = Math.round((completedCount / items.length) * 100);

  const handleContinue = async () => {
    const payload = {
      closingChecklist: items,
      financials: {
        ...f,
        // Sync clear to close flag if all items checked
        isClearToClose: completedCount === items.length,
        loanStatus: completedCount === items.length ? 'Clear-To-Close' : f.loanStatus,
      },
    };
    await onSave(payload);
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 4: Closing Checklist</h3>
        <p className="text-xs text-slate-400">Mark checklist milestones, upload proofs, and verify wire security gates.</p>
      </div>

      {/* Completeness Bar */}
      <div className="space-y-2">
        <div className="flex justify-between text-xs text-slate-400 font-bold uppercase tracking-wider">
          <span>Closing Milestones status</span>
          <span>{completedCount} of 10 Checked</span>
        </div>
        <div className="w-full h-2 bg-white/5 rounded-full overflow-hidden">
          <div
            className="h-full bg-[#7A9EAA] transition-all duration-300"
            style={{ width: `${progressPercent}%` }}
          />
        </div>
      </div>

      {/* Checklist items rows */}
      <div className="space-y-2.5 max-h-[350px] overflow-y-auto scrollbar-none pr-1">
        {items.map((item) => (
          <div
            key={item.id}
            className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 p-3 bg-white/[0.01] border border-white/5 hover:border-white/10 rounded-xl transition-all"
          >
            <button
              type="button"
              onClick={() => toggleItem(item.id)}
              className="flex items-start gap-3 text-left text-xs text-white max-w-md"
            >
              {item.completed ? (
                <CheckSquare className="w-4 h-4 text-[#7A9EAA] shrink-0 mt-0.5" />
              ) : (
                <Square className="w-4 h-4 text-slate-600 shrink-0 mt-0.5" />
              )}
              <div>
                <p className="font-bold">{item.type}</p>
                <p className="text-[10px] text-slate-400 mt-0.5 leading-relaxed">{item.notes}</p>
              </div>
            </button>

            <div className="flex items-center gap-2 self-end sm:self-center">
              <button
                type="button"
                onClick={() => handleUploadProof(item.id)}
                className="h-7 px-3 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-[9px] font-bold uppercase tracking-wider text-white flex items-center gap-1 transition-all"
              >
                <Upload className="w-3 h-3" /> {item.documentUrl ? 'Uploaded ✓' : 'Upload Proof'}
              </button>
            </div>
          </div>
        ))}
      </div>

      <div className="flex justify-between pt-4 border-t border-white/5">
        <span />
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] hover:opacity-90 font-bold uppercase tracking-wider text-[11px] rounded-lg transition-opacity"
        >
          Save & Continue
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { ShieldCheck, Loader2, Landmark, DollarSign, FileText, CheckCircle2, XCircle } from 'lucide-react';
import toast from 'react-hot-toast';

interface FinalReviewStepProps {
  projectId: string;
  initialData: any;
  onComplete: (hudData: { purchasePrice: number; titleFees: number; originationFees: number }) => Promise<void>;
}

export default function FinalReviewStep({
  projectId,
  initialData,
  onComplete,
}: FinalReviewStepProps) {
  const f = initialData?.financials || {};
  const purchasePrice = (f.purchasePrice || 25000000) / 100;
  const rehabBudget = (f.projectedRehabCost || 2500000) / 100;
  const closingCosts = (f.fixedAcquisitionCosts || (purchasePrice * 0.03));
  const holdingReserves = 1200;

  // Final HUD settlement adjustment inputs
  const [hudPurchasePrice, setHudPurchasePrice] = useState<number>(purchasePrice);
  const [titleFees, setTitleFees] = useState<number>(Math.round(closingCosts * 0.4)); // Title portion of closing costs
  const [originationFees, setOriginationFees] = useState<number>(Math.round(closingCosts * 0.6)); // Lender origination fee

  const [acknowledged, setAcknowledged] = useState(false);
  const [closing, setClosing] = useState(false);

  // Derived capital elements
  const capitalStack = f.capitalStack || [];
  let totalDebt = 0;
  let totalEquity = 0;
  capitalStack.forEach((s: any) => {
    const isDebt = ['conventional_loan', 'hard_money', 'bridge', 'sba_504_bank', 'sba_504_cdc'].includes(s.type || '');
    if (isDebt) totalDebt += s.amount || 0;
    else totalEquity += s.amount || 0;
  });

  const cashRequiredAtClosing = (hudPurchasePrice - totalDebt) + titleFees + originationFees + rehabBudget + holdingReserves;

  // Required docs evaluation
  const documentsCheck = useMemo(() => {
    const hasPsa = !!f.psaDocumentUrl;
    const hasEmd = !!f.emdReceiptUrl || !!f.emdVerified;
    const hasLenderCommit = capitalStack.some((s: any) => s.notes === 'uploaded_commitment_letter.pdf') || totalDebt === 0;

    return {
      hasPsa,
      hasEmd,
      hasLenderCommit,
      allPassed: hasPsa && hasEmd && hasLenderCommit,
    };
  }, [f, capitalStack, totalDebt]);

  const handleCloseDeal = async () => {
    if (!acknowledged) {
      toast.error('Please acknowledge that you have reviewed all closing documents.');
      return;
    }
    if (!documentsCheck.allPassed) {
      toast.error('Cannot close deal. Missing required documents (PSA, EMD, or Lender Commitment).');
      return;
    }

    setClosing(true);
    try {
      await onComplete({
        purchasePrice: hudPurchasePrice,
        titleFees,
        originationFees,
      });
      toast.success('Deal successfully closed!');
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Error processing deal closing.');
    } finally {
      setClosing(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 5: Final Review & Close</h3>
        <p className="text-xs text-slate-400">Reconcile final settlement statements, HUD closing costs, and finalize acquisition.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-5">

        {/* Left Side Summary Display */}
        <div className="md:col-span-2 space-y-4">

          {/* HUD Closing adjustments */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl grid grid-cols-2 sm:grid-cols-3 gap-3.5">
            <h4 className="col-span-2 sm:col-span-3 text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Final HUD Settlement Adjustments</h4>

            <div className="space-y-1 col-span-2 sm:col-span-1">
              <label className="text-[9px] font-bold uppercase tracking-wider text-slate-500">Final Purchase Price ($)</label>
              <input
                type="number"
                value={hudPurchasePrice || ''}
                onChange={(e) => setHudPurchasePrice(Number(e.target.value))}
                className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[9px] font-bold uppercase tracking-wider text-slate-500">Title & Escrow Fees ($)</label>
              <input
                type="number"
                value={titleFees || ''}
                onChange={(e) => setTitleFees(Number(e.target.value))}
                className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              />
            </div>

            <div className="space-y-1">
              <label className="text-[9px] font-bold uppercase tracking-wider text-slate-500">Lender Origination ($)</label>
              <input
                type="number"
                value={originationFees || ''}
                onChange={(e) => setOriginationFees(Number(e.target.value))}
                className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              />
            </div>
          </div>

          {/* Core metrics summary cards */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Project Parameters Summary</h4>
            <div className="grid grid-cols-2 gap-4 text-xs">
              <div className="bg-white/5 p-3 rounded-xl">
                <p className="text-[8px] uppercase tracking-wider text-slate-500">Total Purchase Price</p>
                <p className="text-sm font-bold text-white">${hudPurchasePrice.toLocaleString()}</p>
              </div>
              <div className="bg-white/5 p-3 rounded-xl">
                <p className="text-[8px] uppercase tracking-wider text-slate-500">Total Debt Stack</p>
                <p className="text-sm font-bold text-white">${totalDebt.toLocaleString()}</p>
              </div>
              <div className="bg-white/5 p-3 rounded-xl col-span-2">
                <p className="text-[8px] uppercase tracking-wider text-slate-500">Total Estimated Cash Required at Close</p>
                <p className="text-base font-extrabold text-emerald-400">${Math.round(cashRequiredAtClosing).toLocaleString()}</p>
                <p className="text-[9px] text-slate-500 mt-1">Includes direct acquisition, reserves, rehab cap, and closing costs.</p>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side Documents Checklist */}
        <div className="space-y-4">
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Required Documents audit</h4>

            <div className="space-y-2 text-xs">
              {/* PSA */}
              <div className="flex items-center justify-between p-2 bg-white/5 rounded-lg">
                <span className="text-slate-300">Executed PSA</span>
                {documentsCheck.hasPsa ? (
                  <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                ) : (
                  <XCircle className="w-4 h-4 text-rose-500" />
                )}
              </div>

              {/* EMD */}
              <div className="flex items-center justify-between p-2 bg-white/5 rounded-lg">
                <span className="text-slate-300">EMD Deposit Receipt</span>
                {documentsCheck.hasEmd ? (
                  <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                ) : (
                  <XCircle className="w-4 h-4 text-rose-500" />
                )}
              </div>

              {/* Lender commitment */}
              <div className="flex items-center justify-between p-2 bg-white/5 rounded-lg">
                <span className="text-slate-300">Lender Commitment</span>
                {documentsCheck.hasLenderCommit ? (
                  <CheckCircle2 className="w-4 h-4 text-emerald-400" />
                ) : (
                  <XCircle className="w-4 h-4 text-rose-500" />
                )}
              </div>
            </div>
          </div>

          {/* Acknowledgement check */}
          <div className="flex items-start gap-3 p-3 bg-white/5 border border-white/5 rounded-xl">
            <input
              type="checkbox"
              id="close-ack"
              checked={acknowledged}
              onChange={(e) => setAcknowledged(e.target.checked)}
              className="w-4 h-4 rounded text-black border-white/20 focus:ring-0 cursor-pointer mt-0.5"
            />
            <label htmlFor="close-ack" className="text-[10px] text-slate-300 uppercase font-semibold leading-relaxed cursor-pointer select-none">
              I have reviewed all HUD-1 settlement costs, title search certifications, and verified wiring instructions.
            </label>
          </div>

          {/* Action Close Deal */}
          <button
            type="button"
            onClick={handleCloseDeal}
            disabled={closing || !acknowledged || !documentsCheck.allPassed}
            className="w-full py-3.5 bg-emerald-500 text-black hover:opacity-90 disabled:opacity-40 disabled:cursor-not-allowed font-extrabold uppercase tracking-wider text-xs rounded-xl transition-all flex items-center justify-center gap-1.5 shadow-[0_0_20px_rgba(16,185,129,0.3)]"
          >
            {closing ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldCheck className="w-4.5 h-4.5" />}
            Confirm HUD & Close Deal
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Landmark, Mail, Calendar, Upload, AlertCircle, FileText, Send, Loader2 } from 'lucide-react';
import { useMarketplaceVendors } from '@/hooks/useMarketplaceVendors';
import type { CapitalSource } from '@/types/schema';
import toast from 'react-hot-toast';

interface FinancingStepProps {
  projectId: string;
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

export default function FinancingStep({
  projectId,
  initialData,
  onSave,
}: FinancingStepProps) {
  const f = initialData?.financials || {};
  const [sources, setSources] = useState<CapitalSource[]>(f.capitalStack || []);

  const [requestingQuoteId, setRequestingQuoteId] = useState<string | null>(null);

  // Suggest lenders from target ZIP using marketplace vendors hook
  const { vendors: marketplaceLenders } = useMarketplaceVendors('f4HardMoneyLenderVendor');

  // Handle single source details mutation
  const handleUpdateDetail = (id: string, updates: Partial<CapitalSource> | any) => {
    setSources(
      sources.map((s) => (s.id === id ? { ...s, ...updates } : s))
    );
  };

  const handleSendInvite = async (sourceId: string, partnerEmail: string) => {
    if (!partnerEmail || !partnerEmail.includes('@')) {
      toast.error('Specify a valid partner email address.');
      return;
    }

    toast.loading('Sending invitation email...');
    try {
      // Simulate invite API payload
      await new Promise((r) => setTimeout(r, 600));
      toast.dismiss();
      toast.success(`Invitation successfully dispatched to ${partnerEmail}!`);
      handleUpdateDetail(sourceId, { status: 'Applied' });
    } catch (err) {
      toast.dismiss();
      toast.error('Invitation failed.');
    }
  };

  const handleRequestQuote = async (lenderId: string) => {
    setRequestingQuoteId(lenderId);
    try {
      await new Promise((r) => setTimeout(r, 800));
      toast.success('Financing proposal quote request sent to lender!');
    } catch (err) {
      toast.error('Failed to request quote.');
    } finally {
      setRequestingQuoteId(null);
    }
  };

  const handleContinue = async () => {
    const payload = {
      financials: {
        ...f,
        capitalStack: sources,
      },
    };
    await onSave(payload);
  };

  const debtSources = sources.filter((s) =>
    ['conventional_loan', 'hard_money', 'bridge', 'sba_504_bank', 'sba_504_cdc'].includes(s.type || '')
  );

  const equitySources = sources.filter((s) =>
    ['solo_cash', 'syndication_equity', 'co_buyer_equity'].includes(s.type || '')
  );

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 2: Financing Details</h3>
        <p className="text-xs text-slate-400">Track lender application milestones and verify partner equity commitments.</p>
      </div>

      {/* Debt details cards */}
      {debtSources.length > 0 && (
        <div className="space-y-4">
          <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Debt Financing Tracks</h4>
          <div className="space-y-4">
            {debtSources.map((s) => (
              <div key={s.id} className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-4">
                <div className="flex justify-between items-center border-b border-white/5 pb-2">
                  <span className="text-xs font-bold text-white uppercase flex items-center gap-1.5">
                    <Landmark className="w-3.5 h-3.5 text-sky-400" /> {s.category} (${s.amount.toLocaleString()})
                  </span>
                  <span className="text-[10px] text-slate-500 font-mono">Rate: {s.interestRate}%</span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5">
                  {/* Lender Name */}
                  <div className="space-y-1">
                    <label className="text-[8px] font-bold uppercase text-slate-500">Lender Name</label>
                    <input
                      type="text"
                      value={s.lenderName || ''}
                      onChange={(e) => handleUpdateDetail(s.id, { lenderName: e.target.value })}
                      placeholder="e.g. Apex Bank"
                      className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
                    />
                  </div>

                  {/* Status Dropdown */}
                  <div className="space-y-1">
                    <label className="text-[8px] font-bold uppercase text-slate-500">Application Status</label>
                    <select
                      value={s.status || 'Exploring'}
                      onChange={(e) => handleUpdateDetail(s.id, { status: e.target.value })}
                      className="w-full px-2 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
                    >
                      <option value="Exploring" className="bg-[#181315]">Exploring</option>
                      <option value="Applied" className="bg-[#181315]">Applied</option>
                      <option value="Approved" className="bg-[#181315]">Approved</option>
                      <option value="Funded" className="bg-[#181315]">Cleared to Close</option>
                    </select>
                  </div>

                  {/* Lock Expiration */}
                  <div className="space-y-1">
                    <label className="text-[8px] font-bold uppercase text-slate-500">Rate Lock Expiration</label>
                    <input
                      type="date"
                      value={s.notes?.split('|')[0] || ''}
                      onChange={(e) => handleUpdateDetail(s.id, { notes: `${e.target.value}|${s.notes?.split('|')[1] || ''}` })}
                      className="w-full px-3 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs h-8"
                    />
                  </div>

                  {/* Appraisal dates */}
                  <div className="space-y-1">
                    <label className="text-[8px] font-bold uppercase text-slate-500">Appraisal Target Date</label>
                    <input
                      type="date"
                      value={s.notes?.split('|')[1] || ''}
                      onChange={(e) => handleUpdateDetail(s.id, { notes: `${s.notes?.split('|')[0] || ''}|${e.target.value}` })}
                      className="w-full px-3 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-xs h-8"
                    />
                  </div>

                  {/* Upload Document */}
                  <div className="sm:col-span-2 flex items-end">
                    <button
                      type="button"
                      onClick={() => handleUpdateDetail(s.id, { notes: 'uploaded_commitment_letter.pdf' })}
                      className="w-full h-8 px-4 bg-white/5 hover:bg-white/10 border border-white/10 rounded-lg text-[10px] font-bold uppercase tracking-wider text-white flex items-center justify-center gap-1.5 transition-all"
                    >
                      <Upload className="w-3.5 h-3.5" />
                      {s.notes === 'uploaded_commitment_letter.pdf' ? 'Commitment Letter Uploaded ✓' : 'Upload Loan Commitment Letter'}
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Equity details cards */}
      {equitySources.length > 0 && (
        <div className="space-y-4">
          <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Equity Partner Allocations</h4>
          <div className="space-y-4">
            {equitySources.map((s) => (
              <div key={s.id} className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-4">
                <div className="flex justify-between items-center border-b border-white/5 pb-2">
                  <span className="text-xs font-bold text-white uppercase flex items-center gap-1.5">
                    <Mail className="w-3.5 h-3.5 text-emerald-400" /> {s.category} (${s.amount.toLocaleString()})
                  </span>
                  <span className="text-[10px] text-slate-500 font-mono">Status: {s.status || 'Exploring'}</span>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-3 gap-3.5">
                  {/* Name */}
                  <div className="space-y-1">
                    <label className="text-[8px] font-bold uppercase text-slate-500">Partner / Contact Name</label>
                    <input
                      type="text"
                      value={s.lenderName || ''}
                      onChange={(e) => handleUpdateDetail(s.id, { lenderName: e.target.value })}
                      placeholder="e.g. Jane Capital"
                      className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
                    />
                  </div>

                  {/* Email */}
                  <div className="space-y-1">
                    <label className="text-[8px] font-bold uppercase text-slate-500">Contact Email</label>
                    <input
                      type="email"
                      value={s.notes || ''}
                      onChange={(e) => handleUpdateDetail(s.id, { notes: e.target.value })}
                      placeholder="investor@funds.com"
                      className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
                    />
                  </div>

                  {/* Action invite */}
                  <div className="flex items-end">
                    <button
                      type="button"
                      onClick={() => handleSendInvite(s.id, s.notes || '')}
                      className="w-full h-8 bg-emerald-500 hover:opacity-90 text-black rounded-lg text-[10px] font-bold uppercase tracking-wider flex items-center justify-center gap-1.5 transition-all"
                    >
                      <Send className="w-3.5 h-3.5" /> Invite / Verify Equity
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Suggested Marketplace Lenders Panel */}
      {marketplaceLenders.length > 0 && (
        <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
          <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Suggested Lenders matching target ZIP</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {marketplaceLenders.slice(0, 4).map((l) => (
              <div key={l.uid} className="p-3 bg-white/[0.01] border border-white/5 rounded-xl flex items-center justify-between">
                <div>
                  <p className="text-xs font-bold text-white">{l.companyName}</p>
                  <p className="text-[9px] text-slate-500">Avg Turnaround: {l.avgTurnaroundDays} Days • Rating: {l.overallRating}★</p>
                </div>
                <button
                  type="button"
                  onClick={() => handleRequestQuote(l.uid)}
                  disabled={requestingQuoteId === l.uid}
                  className="px-3 py-1.5 bg-white/10 hover:bg-white/15 rounded-lg text-[9px] font-bold uppercase tracking-wider text-white flex items-center gap-1 transition-all"
                >
                  {requestingQuoteId === l.uid ? <Loader2 className="w-3 h-3 animate-spin" /> : 'Request Quote'}
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="flex justify-between pt-4 border-t border-white/5">
        <span />
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] hover:opacity-90 font-bold uppercase tracking-wider text-[11px] rounded-lg transition-opacity"
        >
          Save & Continue
        </button>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { UserCheck, CheckCircle2, FileText, AlertCircle, Clock, Upload } from 'lucide-react';
import { useMarketplaceVendors } from '@/hooks/useMarketplaceVendors';
import toast from 'react-hot-toast';

interface VendorAssignmentStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

export default function VendorAssignmentStep({
  initialData,
  onSave,
}: VendorAssignmentStepProps) {
  const f = initialData?.financials || {};

  // Vendor assignment states
  const [titleVendorId, setTitleVendorId] = useState(f.diligenceTitleVendorId || '');
  const [attorneyVendorId, setAttorneyVendorId] = useState(f.diligenceAttorneyVendorId || '');
  const [appraiserVendorId, setAppraiserVendorId] = useState(f.diligenceAppraiserVendorId || '');
  const [insuranceVendorId, setInsuranceVendorId] = useState(f.diligenceInsuranceVendorId || '');
  const [inspectorVendorId, setInspectorVendorId] = useState(f.diligenceInspectionVendorId || '');

  // Status pipelines
  const [titleStatus, setTitleStatus] = useState<string>(f.vendorTitleStatus || 'Title search ordered');
  const [attorneyStatus, setAttorneyStatus] = useState<string>(f.vendorAttorneyStatus || 'Engagement letter signed');
  const [appraiserStatus, setAppraiserStatus] = useState<string>(f.vendorAppraiserStatus || 'Ordered');
  const [insuranceStatus, setInsuranceStatus] = useState<string>(f.vendorInsuranceStatus || 'Quote requested');

  // Load Marketplace Vendors using slots
  const { vendors: titleAgencies } = useMarketplaceVendors('f4TitleEscrowVendor');
  const { vendors: closingAttorneys } = useMarketplaceVendors('f4ClosingAttorneyVendor');
  const { vendors: appraisers } = useMarketplaceVendors('f4AppraiserVendor');
  const { vendors: insuranceBrokers } = useMarketplaceVendors('f4InsuranceBrokerVendor');
  const { vendors: inspectors } = useMarketplaceVendors('f4EnvironmentalVendor');

  // Countdown calculations
  const closingDate = f.loiTargetClosingDate || initialData?.closingDate;
  const daysRemaining = closingDate
    ? Math.max(0, Math.ceil((new Date(closingDate).getTime() - new Date().getTime()) / (1000 * 60 * 60 * 24)))
    : 30;

  const handleContinue = async () => {
    // Require Title and Closing Attorney to be assigned as per anti-pattern constraints
    if (!titleVendorId || !attorneyVendorId) {
      toast.error('Title Partner and Closing Attorney assignments are mandatory.');
      return;
    }

    const payload = {
      financials: {
        ...f,
        diligenceTitleVendorId: titleVendorId,
        diligenceAttorneyVendorId: attorneyVendorId,
        diligenceAppraisalVendorId: appraiserVendorId,
        diligenceInsuranceVendorId: insuranceVendorId,
        diligenceInspectionVendorId: inspectorVendorId,
        vendorTitleStatus: titleStatus,
        vendorAttorneyStatus: attorneyStatus,
        vendorAppraiserStatus: appraiserStatus,
        vendorInsuranceStatus: insuranceStatus,
      },
    };
    await onSave(payload);
  };

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 3: Vendor Assignment & Deliverables</h3>
        <p className="text-xs text-slate-400">Assign transaction professionals and track document deliverables timelines.</p>
      </div>

      {/* Due date header countdown */}
      <div className="p-3 bg-white/[0.02] border border-white/5 rounded-xl flex justify-between items-center text-xs">
        <span className="text-slate-400 font-semibold uppercase tracking-wider">Estimated Closing Window</span>
        <span className="text-[#7A9EAA] font-bold uppercase tracking-wider flex items-center gap-1">
          <Clock className="w-4 h-4 text-sky-400" /> {daysRemaining} Days Until Target Closing
        </span>
      </div>

      <div className="space-y-4">
        {/* Vendor Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">

          {/* Title & Escrow Partner */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-xs font-bold text-white uppercase flex items-center gap-1.5">
              <UserCheck className="w-4 h-4 text-sky-400" /> Title & Escrow Partner <span className="text-rose-500 text-xs">*</span>
            </h4>
            <div className="space-y-2">
              <select
                value={titleVendorId}
                onChange={(e) => setTitleVendorId(e.target.value)}
                className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
              >
                <option value="" className="bg-[#181315]">Select Title Agency...</option>
                {titleAgencies.map((v) => (
                  <option key={v.uid} value={v.uid} className="bg-[#181315]">{v.companyName}</option>
                ))}
              </select>

              <select
                value={titleStatus}
                onChange={(e) => setTitleStatus(e.target.value)}
                className="w-full px-2 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              >
                <option value="Title search ordered" className="bg-[#181315]">Title search ordered</option>
                <option value="Preliminary title received" className="bg-[#181315]">Preliminary title received</option>
                <option value="Title cleared" className="bg-[#181315]">Title cleared ✓</option>
              </select>
            </div>
          </div>

          {/* Real Estate Closing Attorney */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-xs font-bold text-white uppercase flex items-center gap-1.5">
              <UserCheck className="w-4 h-4 text-sky-400" /> Real Estate Attorney <span className="text-rose-500 text-xs">*</span>
            </h4>
            <div className="space-y-2">
              <select
                value={attorneyVendorId}
                onChange={(e) => setAttorneyVendorId(e.target.value)}
                className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
              >
                <option value="" className="bg-[#181315]">Select Attorney...</option>
                {closingAttorneys.map((v) => (
                  <option key={v.uid} value={v.uid} className="bg-[#181315]">{v.companyName}</option>
                ))}
              </select>

              <select
                value={attorneyStatus}
                onChange={(e) => setAttorneyStatus(e.target.value)}
                className="w-full px-2 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              >
                <option value="Engagement letter signed" className="bg-[#181315]">Engagement letter signed</option>
                <option value="Closing docs drafted" className="bg-[#181315]">Closing docs drafted</option>
                <option value="Docs reviewed" className="bg-[#181315]">Docs reviewed ✓</option>
              </select>
            </div>
          </div>

          {/* Appraiser Partner */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-xs font-bold text-white uppercase flex items-center gap-1.5">
              <UserCheck className="w-4 h-4 text-sky-400" /> Certified Appraiser
            </h4>
            <div className="space-y-2">
              <select
                value={appraiserVendorId}
                onChange={(e) => setAppraiserVendorId(e.target.value)}
                className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
              >
                <option value="" className="bg-[#181315]">Select Appraiser...</option>
                {appraisers.map((v) => (
                  <option key={v.uid} value={v.uid} className="bg-[#181315]">{v.companyName}</option>
                ))}
              </select>

              <select
                value={appraiserStatus}
                onChange={(e) => setAppraiserStatus(e.target.value)}
                className="w-full px-2 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              >
                <option value="Ordered" className="bg-[#181315]">Ordered</option>
                <option value="Inspection complete" className="bg-[#181315]">Inspection complete</option>
                <option value="Report received" className="bg-[#181315]">Report received ✓</option>
              </select>
            </div>
          </div>

          {/* Insurance Broker */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-xs font-bold text-white uppercase flex items-center gap-1.5">
              <UserCheck className="w-4 h-4 text-sky-400" /> Insurance Broker
            </h4>
            <div className="space-y-2">
              <select
                value={insuranceVendorId}
                onChange={(e) => setInsuranceVendorId(e.target.value)}
                className="w-full px-3 py-2 bg-white/5 border border-white/10 rounded-lg text-white text-xs"
              >
                <option value="" className="bg-[#181315]">Select Broker...</option>
                {insuranceBrokers.map((v) => (
                  <option key={v.uid} value={v.uid} className="bg-[#181315]">{v.companyName}</option>
                ))}
              </select>

              <select
                value={insuranceStatus}
                onChange={(e) => setInsuranceStatus(e.target.value)}
                className="w-full px-2 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
              >
                <option value="Quote requested" className="bg-[#181315]">Quote requested</option>
                <option value="Bound" className="bg-[#181315]">Bound</option>
                <option value="Policy issued" className="bg-[#181315]">Policy issued ✓</option>
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="flex justify-between pt-4 border-t border-white/5">
        <span />
        <button
          onClick={handleContinue}
          className="px-6 py-2.5 bg-[#7A9EAA] text-[#0d0a0b] hover:opacity-90 font-bold uppercase tracking-wider text-[11px] rounded-lg transition-opacity"
        >
          Save & Continue
        </button>
      </div>
    </div>
  );
}

