'use client';

import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import toast from 'react-hot-toast';
import { HOLD_CARD_REGISTRY, HoldCardDefinition, DispositionType, ScopeTier } from '@/lib/project/holdCardRegistry';
import { HoldWelcomeBanner } from './HoldWelcomeBanner';
import { RehabExpenseTracker } from '@/components/project/RehabExpenseTracker';
import TransactionLedger from '@/components/projects/TransactionLedger';

export interface HoldWorkspaceShellProps {
  projectId: string;
  address?: string;
  dispositionType?: DispositionType;
  scopeTier?: ScopeTier;
  userId?: string;
}

export function HoldWorkspaceShell({
  projectId,
  address = 'Demo Property',
  dispositionType = 'RENT',
  scopeTier = 'RENOVATE',
  userId = 'user_1',
}: HoldWorkspaceShellProps) {
  const router = useRouter();
  const [selectedCard, setSelectedCard] = useState<HoldCardDefinition | null>(null);
  const [cardDraftInput, setCardDraftInput] = useState<string>('');
  const [savedData, setSavedData] = useState<Record<string, string>>({});
  const [rehabExpenses, setRehabExpenses] = useState<any[]>([]);

  const handleSkipToExit = async () => {
    try {
      const projectRef = doc(db, 'projects', projectId);
      await updateDoc(projectRef, {
        currentPhase: 4,
        phaseStatus: 'Phase 4: Exit',
        status: 'exit',
        updatedAt: new Date().toISOString(),
      });
      toast.success('Skipped to Exit Phase!');
      router.push(`/dashboard/projects/${projectId}/phase-4`);
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to skip to Exit.');
    }
  };

  // Restore saved draft state from localStorage for save/resume testing
  useEffect(() => {
    const key = `pw_hold_drafts_${projectId}_${userId}`;
    const stored = localStorage.getItem(key);
    if (stored) {
      try {
        setSavedData(JSON.parse(stored));
      } catch (e) {
        console.error('Failed to parse draft state', e);
      }
    }
  }, [projectId, userId]);

  const handleOpenCard = (card: HoldCardDefinition) => {
    setSelectedCard(card);
    setCardDraftInput(savedData[card.id] || '');
  };

  const handleSaveCard = () => {
    if (!selectedCard) return;
    const updated = { ...savedData, [selectedCard.id]: cardDraftInput };
    setSavedData(updated);
    localStorage.setItem(`pw_hold_drafts_${projectId}_${userId}`, JSON.stringify(updated));
    setSelectedCard(null);
  };

  const columns = [
    { id: 'H1', title: 'H1 · RENOVATION PLAN' },
    { id: 'H2', title: 'H2 · RENOVATION TRACKING' },
    { id: 'H3', title: 'H3 · HOLDING COSTS' },
    { id: 'H4', title: 'H4 · MARKET & VALUE' },
    { id: 'H5', title: 'H5 · GO TO MARKET' },
  ];

  return (
    <div
      className="w-full min-h-screen p-8 font-sans"
      style={{
        background: 'var(--color-surface)',
        color: 'var(--color-on-surface)',
      }}
    >
      {/* ── Project Header & Shell ── */}
      <div
        className="flex flex-col space-y-4 mb-8 pb-6 border-b"
        style={{ borderColor: 'var(--color-outline-variant)' }}
      >
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <h1 className="text-2xl font-bold">{address}</h1>

            {/* Phase Chip — Canon: Hold */}
            <span
              className="px-3 py-1 text-xs font-semibold rounded-full border"
              style={{
                background: 'var(--color-primary-container)',
                color: 'var(--color-primary)',
                borderColor: 'var(--color-primary-container)',
              }}
            >
              Hold
            </span>

            {/* Read-Only Strategy Chip (Decision H-1 Law) */}
            <span
              className="px-3 py-1 text-xs font-semibold rounded-full border"
              style={{
                background: 'var(--color-surface-container)',
                color: 'var(--color-on-surface-variant)',
                borderColor: 'var(--color-outline-variant)',
              }}
              title="Strategy is read-only in Hold (Decision H-1)"
            >
              Strategy: {dispositionType}
            </span>
          </div>

          <div className="flex items-center space-x-4">
            <div
              className="text-xs flex items-center space-x-2 border-r pr-4 border-white/10"
              style={{ color: 'var(--color-on-surface-variant)' }}
            >
              <span>Scope Tier:</span>
              <span className="font-semibold" style={{ color: 'var(--color-on-surface)' }}>
                {scopeTier}
              </span>
            </div>

            {/* Launch Hold Wizard */}
            <button
              onClick={() => router.push(`/dashboard/projects/${projectId}/phase-3/wizard?strategy=${dispositionType}`)}
              className="px-4 py-2 bg-[#7A9EAA] hover:opacity-90 text-[#0d0a0b] font-bold uppercase tracking-wider text-[10px] rounded-lg transition-all shadow-[0_0_12px_rgba(122,158,170,0.15)]"
            >
              Launch Hold Wizard
            </button>

            {/* Skip to Exit for flips */}
            {dispositionType === 'SALE' && (
              <button
                onClick={handleSkipToExit}
                className="px-4 py-2 border border-[#7A9EAA]/30 hover:bg-[#7A9EAA]/5 text-white font-bold uppercase tracking-wider text-[10px] rounded-lg transition-all"
              >
                Skip to Exit
              </button>
            )}
          </div>
        </div>

        {/* Phase Progress Strip */}
        <div
          className="w-full h-2 rounded-full overflow-hidden flex"
          style={{ background: 'var(--color-surface-container)' }}
        >
          <div
            className="h-full w-3/5 transition-all duration-300"
            style={{ background: 'var(--color-primary)' }}
          />
        </div>
      </div>

      {/* ── Welcome Banner ── */}
      <HoldWelcomeBanner
        userId={userId}
        onSelectCard={(cardId) => {
          const target = HOLD_CARD_REGISTRY.find((c) => c.id === cardId);
          if (target) handleOpenCard(target);
        }}
      />

      {/* ── 5-Column Kanban Board ── */}
      <div className="grid grid-cols-1 md:grid-cols-3 lg:grid-cols-5 gap-6">
        {columns.map((col) => {
          const colCards = HOLD_CARD_REGISTRY.filter(
            (c) => c.columnId === col.id && c.revealCondition({ dispositionType, scopeTier })
          );

          return (
            <div
              key={col.id}
              className="flex flex-col border rounded-xl p-4 min-h-[500px]"
              style={{
                background: 'var(--color-surface-container-low)',
                borderColor: 'var(--color-outline-variant)',
              }}
            >
              <h2
                className="text-xs font-semibold tracking-wider uppercase mb-4"
                style={{ color: 'var(--color-on-surface-variant)' }}
              >
                {col.title}
              </h2>

              <div className="flex flex-col space-y-3">
                {colCards.map((card) => {
                  const hasSavedValue = !!savedData[card.id];

                  return (
                    <div
                      key={card.id}
                      onClick={() => handleOpenCard(card)}
                      className="border rounded-lg p-4 cursor-pointer transition-all duration-200 shadow-sm group"
                      style={{
                        background: 'var(--color-surface-dim)',
                        borderColor: 'var(--color-outline-variant)',
                      }}
                    >
                      <div className="flex items-center justify-between mb-2">
                        <span className="text-xs font-semibold" style={{ color: 'var(--color-primary)' }}>
                          {card.cardName}
                        </span>
                        {hasSavedValue ? (
                          <span
                            className="text-[10px] px-2 py-0.5 rounded font-medium"
                            style={{
                              background: 'var(--color-status-success-container)',
                              color: 'var(--color-status-success)',
                            }}
                          >
                            Saved
                          </span>
                        ) : (
                          <span
                            className="text-[10px] px-2 py-0.5 rounded font-medium"
                            style={{
                              background: 'var(--color-surface-container)',
                              color: 'var(--color-on-surface-variant)',
                            }}
                          >
                            Empty
                          </span>
                        )}
                      </div>

                      <p className="text-sm font-medium mb-2 transition-colors" style={{ color: 'var(--color-on-surface)' }}>
                        {card.questionText}
                      </p>

                      <p
                        className="text-xs line-clamp-2 italic"
                        style={{ color: 'var(--color-on-surface-variant)' }}
                      >
                        "{card.whyWeAsk}"
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Rehab Expense Tracker ── */}
      <div className="mt-12 max-w-5xl">
        <RehabExpenseTracker expenses={rehabExpenses} onChange={setRehabExpenses} />
      </div>

      {/* ── Bank Transaction Ledger (Plaid) ── */}
      <div className="mt-10 max-w-5xl">
        <TransactionLedger projectId={projectId} />
      </div>

      {/* ── Card Save/Resume Modal ── */}
      {selectedCard && (
        <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
          <div
            className="border rounded-xl max-w-lg w-full p-6 shadow-2xl space-y-6"
            style={{
              background: 'var(--color-surface)',
              borderColor: 'var(--color-outline-variant)',
            }}
          >
            <div>
              <span className="text-xs font-semibold uppercase tracking-wider" style={{ color: 'var(--color-primary)' }}>
                {selectedCard.cardName}
              </span>
              <h3 className="text-lg font-bold mt-1" style={{ color: 'var(--color-on-surface)' }}>
                {selectedCard.questionText}
              </h3>
              <p
                className="text-xs mt-1 italic"
                style={{ color: 'var(--color-on-surface-variant)' }}
              >
                "{selectedCard.whyWeAsk}"
              </p>
            </div>

            <div className="space-y-2">
              <label
                className="text-xs font-medium"
                style={{ color: 'var(--color-on-surface-variant)' }}
              >
                Entry / Draft Value
              </label>
              <textarea
                value={cardDraftInput}
                onChange={(e) => setCardDraftInput(e.target.value)}
                placeholder="Type entry or notes..."
                className="w-full rounded-lg p-3 text-sm outline-none transition-colors h-28 resize-none border"
                style={{
                  background: 'var(--color-surface-container)',
                  borderColor: 'var(--color-outline-variant)',
                  color: 'var(--color-on-surface)',
                }}
              />
            </div>

            <div
              className="flex items-center justify-end space-x-3 pt-2 border-t"
              style={{ borderColor: 'var(--color-outline-variant)' }}
            >
              <button
                onClick={() => setSelectedCard(null)}
                className="px-4 py-2 text-xs font-medium transition-colors"
                style={{ color: 'var(--color-on-surface-variant)' }}
              >
                Cancel
              </button>
              <button
                onClick={handleSaveCard}
                className="px-5 py-2 text-xs font-semibold rounded-lg transition-colors shadow-md"
                style={{
                  background: 'var(--color-primary)',
                  color: 'var(--color-on-surface)',
                }}
              >
                Save & Resume Later
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { FileText, Percent, Info, ExternalLink, UserPlus, FileCheck, CheckCircle2 } from 'lucide-react';
import toast from 'react-hot-toast';

interface LeaseUpStepProps {
  initialData: any;
  onSave: (data: any) => Promise<void>;
}

export default function LeaseUpStep({
  initialData,
  onSave,
}: LeaseUpStepProps) {
  const f = initialData?.financials || {};
  const beds = initialData?.beds ?? f.beds ?? 3;
  const baths = initialData?.baths ?? f.baths ?? 2;
  const address = initialData?.addressLine || initialData?.address || 'Property';

  // Checklist
  const [checklist, setChecklist] = useState<Record<string, boolean>>(() => {
    return f.leaseChecklist || {
      rehabComplete: false,
      utilitiesActive: false,
      cleaningDone: false,
      photosReady: false,
      rentAmountSet: false,
    };
  });

  // Rent
  const rentCastEstimate = 1850; // mock market estimate from RentCast
  const [targetRent, setTargetRent] = useState<number>(f.leaseTargetRent || 1800);

  // Marketing templates & description
  const features = useMemo(() => {
    const scope = f.rehabScope || [];
    const completed = scope.filter((s: any) => s.status === 'Complete').map((s: any) => s.item.toLowerCase());
    return completed.length > 0 ? completed.slice(0, 3).join(', ') : 'modern cabinetry and updated features';
  }, [f.rehabScope]);

  const generatedDescription = `Beautiful ${beds} Bed / ${baths} Bath home in ${address.split(',')[1] || 'prime location'}. Recently renovated with ${features}. Spacious living layout, ready to move in.`;

  const [platforms, setPlatforms] = useState<Record<string, boolean>>({
    zillow: false,
    apartments: false,
    facebook: false,
    craigslist: false,
  });

  // Tenant screening applicant list
  const [applicants, setApplicants] = useState<any[]>(() => {
    return f.leaseApplicants || [
      { id: 'app_1', name: 'John Doe', income: 6200, credit: 710, status: 'Pending' },
      { id: 'app_2', name: 'Sarah Connor', income: 7500, credit: 740, status: 'Lease Signed' },
    ];
  });

  // Lease parameters
  const [startDate, setStartDate] = useState(f.leaseStartDate || '');
  const [endDate, setEndDate] = useState(f.leaseEndDate || '');
  const [securityDeposit, setSecurityDeposit] = useState(f.leaseSecurityDeposit || 1800);

  const variancePct = useMemo(() => {
    return ((targetRent - rentCastEstimate) / rentCastEstimate) * 100;
  }, [targetRent, rentCastEstimate]);

  const toggleChecklist = (key: string) => {
    setChecklist({ ...checklist, [key]: !checklist[key] });
  };

  const handleLaunchPlatform = (key: string, url: string) => {
    setPlatforms({ ...platforms, [key]: true });
    window.open(url, '_blank');
    toast.success('Listing template copied to clipboard. Launching platform...');
  };

  const handleUpdateApplicantStatus = (id: string, status: string) => {
    setApplicants(applicants.map((a) => (a.id === id ? { ...a, status } : a)));
    toast.success(`Applicant status updated to ${status}.`);
  };

  const handleContinue = async () => {
    // Save checklist, targetRent, applicants, and lease variables
    const leaseSigned = applicants.some((a) => a.status === 'Lease Signed');

    const payload = {
      financials: {
        ...f,
        leaseChecklist: checklist,
        leaseTargetRent: targetRent,
        leaseApplicants: applicants,
        leaseStartDate: startDate,
        leaseEndDate: endDate,
        leaseSecurityDeposit: securityDeposit,
        leaseLeaseSigned: leaseSigned,
        grossRent: targetRent * 100, // Cents
      },
    };
    await onSave(payload);
  };

  // Expiration countdown
  const daysUntilLeaseEnd = useMemo(() => {
    if (!endDate) return 365;
    const diffTime = new Date(endDate).getTime() - new Date().getTime();
    return Math.max(0, Math.ceil(diffTime / (1000 * 60 * 60 * 24)));
  }, [endDate]);

  return (
    <div className="space-y-6">
      <div className="space-y-1">
        <h3 className="text-sm font-bold uppercase tracking-wider text-white">Step 2: Lease-Up</h3>
        <p className="text-xs text-slate-400">Validate property readiness checklist, generate listing templates, track tenant screenings, and save lease terms.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-5">

        {/* Left Side: Readiness & Rent Settings */}
        <div className="space-y-4">

          {/* Property Readiness */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Readiness checklist</h4>
            <div className="space-y-2 text-xs">
              {Object.keys(checklist).map((key) => {
                const label = key
                  .replace(/([A-Z])/g, ' $1')
                  .replace(/^./, (str) => str.toUpperCase());
                return (
                  <button
                    key={key}
                    type="button"
                    onClick={() => toggleChecklist(key)}
                    className="flex items-center gap-2 text-left text-white w-full"
                  >
                    {checklist[key] ? (
                      <CheckCircle2 className="w-4 h-4 text-[#7A9EAA] shrink-0" />
                    ) : (
                      <div className="w-4 h-4 rounded-full border border-slate-600 shrink-0" />
                    )}
                    <span>{label}</span>
                  </button>
                );
              })}
            </div>
          </div>

          {/* Rent setup */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-4">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Rent setting vs. RentCast comps</h4>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-1">
                <label className="text-[9px] font-bold uppercase text-slate-500">Target Monthly Rent ($)</label>
                <input
                  type="number"
                  value={targetRent || ''}
                  onChange={(e) => setTargetRent(Number(e.target.value))}
                  className="w-full px-3 py-1.5 bg-white/5 border border-white/10 rounded-lg text-white text-xs font-semibold"
                />
              </div>

              <div className="bg-white/5 p-2 rounded-xl text-center flex flex-col justify-center">
                <p className="text-[8px] uppercase tracking-wider text-slate-500">RentCast Market Estimate</p>
                <p className="text-sm font-bold text-white">${rentCastEstimate}/mo</p>
                <span className={`text-[9px] mt-0.5 ${variancePct >= 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
                  {variancePct >= 0 ? '+' : ''}{variancePct.toFixed(1)}% Variance
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Marketing Description & Checklist */}
        <div className="space-y-4">

          {/* Listing Generator */}
          <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
            <h4 className="text-[10px] font-bold uppercase tracking-widest text-slate-400">Listing Template Description</h4>
            <p className="text-xs text-slate-300 leading-relaxed bg-white/5 p-3 rounded-lg border border-white/5">
              {generatedDescription}
            </p>

            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                onClick={() => handleLaunchPlatform('zillow', 'https://zillow.com/rental-manager')}
                className="py-1.5 bg-white/5 hover:bg-white/10 text-white rounded-lg text-[9px] font-bold uppercase flex items-center justify-center gap-1 transition-all"
              >
                Zillow <ExternalLink className="w-3 h-3" />
              </button>
              <button
                type="button"
                onClick={() => handleLaunchPlatform('facebook', 'https://facebook.com/marketplace')}
                className="py-1.5 bg-white/5 hover:bg-white/10 text-white rounded-lg text-[9px] font-bold uppercase flex items-center justify-center gap-1 transition-all"
              >
                Facebook <ExternalLink className="w-3 h-3" />
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Tenant screening tracker */}
      <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl space-y-3">
        <h4 className="text-[10px] font-bold uppercase tracking-widest text-[#7A9EAA]">Tenant Screening Pipeline</h4>
        <div className="space-y-2 max-h-[160px] overflow-y-auto scrollbar-none pr-1">
          {applicants.map((a) => (
            <div key={a.id} className="p-2.5 bg-white/[0.01] border border-white/5 rounded-xl flex items-center justify-between text-xs">
              <div>
                <span className="font-bold text-white block">{a.name}</span>
                <span className="text-[9px] text-slate-500">Income: ${a.income.toLocaleString()}/mo • Credit: {a.credit || '—'}</span>
              </div>
              <div className="flex items-center gap-2">
                <select
                  value={a.status}
                  onChange={(e) => handleUpdateApplicantStatus(a.id, e.target.value)}
                  className="px-2 py-1 bg-white/5 border border-white/10 rounded-lg text-white text-[10px] font-semibold"
                >
                  <option value="Pending" className="bg-[#181315]">Pending</option>
                  <option value="Approved" className="bg-[#181315]">Approved</option>
                  <option value="Rejected" className="bg-[#181315]">Rejected</option>
                  <option value="Lease Signed" className="bg-[#181315]">Lease Signed ✓</option>
                </select>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Lease Terms Inputs */}
      <div className="p-4 bg-white/[0.02] border border-white/5 rounded-xl grid grid-cols-2 sm:grid-cols-4 gap-3.5">
        <h4 className="col-span-2 sm:col-span-4 text-[10px] font-bold uppercase tracking-widest text-slate-400">Lease Terms Agreement</h4>

        <div className="space-y-1">
