              <div>
                <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase mb-1">Est. Closing Date</label>
                <input
                  type="date"
                  value={finalClosingDate}
                  onChange={(e) => setFinalClosingDate(e.target.value)}
