/* ── Thread-level MoreMenu ─────────────────────────────
   Renders a ⋮ button that opens a small dropdown with
   real actions. Actions must have an onClick handler.
   ────────────────────────────────────────────────────── */
interface MoreMenuProps {
  onMarkUnread?: () => void;
}

function ThreadMoreMenu({ onMarkUnread }: MoreMenuProps) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  // Close on outside click
  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  return (
    <div ref={ref} className="relative">
      <button
        id="thread-more-menu-trigger"
        onClick={() => setOpen((v) => !v)}
        className="p-2 rounded-lg hover:bg-white/5 text-[#9E9DA0] transition-colors"
        aria-label="Thread actions"
        aria-expanded={open}
        aria-haspopup="true"
      >
        <span className="material-symbols-outlined" style={{ fontVariationSettings: "'FILL' 0" }}>more_vert</span>
      </button>

      {open && (
        <div
          id="thread-more-menu"
          role="menu"
          className="absolute right-0 top-full mt-1 w-48 rounded-xl border border-white/10 bg-[#161318] shadow-[0_8px_32px_-4px_rgba(0,0,0,0.6)] z-50 py-1 overflow-hidden"
        >
          {onMarkUnread ? (
            <button
              id="thread-menu-mark-unread"
              role="menuitem"
              onClick={() => { onMarkUnread(); setOpen(false); }}
              className="w-full flex items-center gap-3 px-4 py-2.5 text-sm text-[#9E9DA0] hover:bg-white/5 hover:text-white transition-colors text-left"
            >
              <span className="material-symbols-outlined text-base" style={{ fontVariationSettings: "'FILL' 0" }}>mark_email_unread</span>
              Mark as Unread
            </button>
          ) : (
            <p className="px-4 py-2.5 text-xs text-[#9E9DA0]/40 select-none">No actions available</p>
          )}
        </div>
      )}
    </div>
  );
}

interface ThreadDetailProps {
  thread: InboxThread;
  projectName?: string;
  onSendReply: (body: string) => Promise<void>;
  onBack?: () => void;
  /** Called when the user selects "Mark as Unread" from the ⋮ menu. */
  onMarkThreadUnread?: () => void;
}

function MessageBubble({ message, isMe }: { message: InboxMessage; isMe: boolean }) {
  const typeBadge = message.type === 'EMAIL_INBOUND'
    ? { label: 'Email', color: '#9E9DA0' }
    : message.type === 'EMAIL_OUTBOUND'
    ? { label: 'Sent', color: '#454955' }
    : null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 10 }}
      animate={{ opacity: 1, y: 0 }}
      className={`flex ${isMe ? 'justify-end' : 'justify-start'}`}
    >
      <div className={`max-w-[70%] flex flex-col ${isMe ? 'items-end' : 'items-start'}`}>
        {/* Sender + Time */}
        <div className="flex items-center gap-2 mb-1 px-1">
          <span className="text-xs font-bold text-[#9E9DA0]">
            {isMe ? 'You' : message.senderName}
          </span>
          {typeBadge && (
            <span
              className={`text-[10px] font-mono uppercase tracking-wider px-1.5 py-0.5 rounded-md border ${
                isMe ? 'text-[#454955] border-[#454955]/30 bg-[#454955]/10' : 'text-[#9E9DA0] border-white/10 bg-white/5'
              }`}
            >
              {typeBadge.label}
            </span>
          )}
          <span className="text-xs font-medium text-[#9E9DA0]">
            {message.createdAt.toLocaleTimeString('en-US', {
              hour: 'numeric',
              minute: '2-digit',
            })}
          </span>
        </div>

        {/* Bubble */}
        <div
          className={`px-5 py-3.5 text-sm leading-relaxed whitespace-pre-wrap backdrop-blur-md border ${
            isMe
              ? 'rounded-2xl rounded-tr-sm bg-[#454955]/10 border-[#454955]/20 text-[#9E9DA0] shadow-[inset_1px_1px_0px_rgba(69,73,85,0.1)]'
              : 'rounded-2xl rounded-tl-sm bg-[#161318]/80 border-white/10 text-[#9E9DA0] shadow-[inset_1px_1px_0px_rgba(255,255,255,0.05)]'
          }`}
        >
          {message.body}
        </div>
      </div>
    </motion.div>
  );
}

export default function ThreadDetail({ thread, projectName, onSendReply, onBack, onMarkThreadUnread }: ThreadDetailProps) {
  const { user } = useAuth();
  const [replyText, setReplyText] = useState('');
  const [sending, setSending] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Auto-scroll to bottom on new messages
  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [thread.messages.length]);

  const handleSend = async () => {
    const body = replyText.trim();
    if (!body || sending) return;

    setSending(true);
    try {
      await onSendReply(body);
      setReplyText('');
    } catch (err) {
      console.error('[ThreadDetail] Send failed:', err);
    } finally {
      setSending(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault();
      handleSend();
    }
  };

  // Sort messages oldest first for display
  const sortedMessages = [...thread.messages].sort(
    (a, b) => a.createdAt.getTime() - b.createdAt.getTime(),
  );

  // Clean subject line (remove tracking token)
  const displaySubject = thread.lastMessage.subject
    ?.replace(/\s*\[ref:deal_[^\]]+\]/g, '')
    || projectName
    || 'Conversation';

  return (
    <div className="flex-1 overflow-hidden z-10 flex flex-col bg-transparent">
      {/* Header Actions */}
      <div className="px-8 py-6 flex items-center justify-between border-b border-white/10 shrink-0 bg-[#0d0a0b]/50 backdrop-blur-sm">
        <div className="flex items-center gap-4">
          {onBack && (
            <button onClick={onBack} className="md:hidden p-2 -ml-2 rounded-lg hover:bg-white/5 text-[#9E9DA0] transition-colors">
              <ArrowLeft className="w-5 h-5" />
            </button>
          )}
          <div className="h-12 w-12 rounded-xl bg-[#0d0a0b]/60 backdrop-blur-xl border border-[#454955]/30 shadow-[inset_1px_1px_0px_rgba(69,73,85,0.1),0_0_15px_rgba(69,73,85,0.15)] flex items-center justify-center text-[#454955] font-bold text-lg">
            {(thread.lastMessage.senderName?.[0] || 'P').toUpperCase()}
          </div>
          <div>
            <h3 className="text-xl font-bold text-[#9E9DA0]">{displaySubject}</h3>
            <p className="text-[10px] font-mono text-[#9E9DA0] uppercase flex items-center gap-2 mt-0.5">
              <span>{thread.participantNames.slice(0, 3).join(', ')}</span>
              {thread.participantNames.length > 3 && <span>(+{thread.participantNames.length - 3})</span>}
              <span className="text-[#454955]">•</span>
              <span>{thread.messages.length} message{thread.messages.length !== 1 && 's'}</span>
            </p>
          </div>
        </div>
        <div className="flex gap-2">
          <ThreadMoreMenu onMarkUnread={onMarkThreadUnread} />
        </div>
      </div>

      {/* Messages */}
      <div
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-8 space-y-6"
      >
        <AnimatePresence>
          {sortedMessages.map((msg) => (
            <MessageBubble
              key={msg.id}
              message={msg}
              isMe={msg.senderUid === user?.uid}
            />
          ))}
        </AnimatePresence>
      </div>

      {/* Reply Area */}
      <footer className="p-6 border-t border-white/10 bg-[#0d0a0b]/50 backdrop-blur-sm shrink-0">
        <div className="relative max-w-4xl mx-auto">
          <textarea
            id="inbox-reply-input"
            placeholder="Type your reply... (⌘+Enter to send)"
            value={replyText}
            onChange={(e) => setReplyText(e.target.value)}
            onKeyDown={handleKeyDown}
            disabled={sending}
            className="w-full h-28 p-4 pr-16 rounded-xl border border-white/10 bg-[#0d0a0b]/80 text-sm resize-none focus:outline-none focus:border-[#454955]/50 transition-colors shadow-[inset_0_2px_10px_rgba(0,0,0,0.5)] text-[#9E9DA0] disabled:opacity-50 placeholder:text-[#9E9DA0]/40"
          />
          <button
            id="inbox-send-reply"
            onClick={handleSend}
            disabled={!replyText.trim() || sending}
            className="absolute bottom-4 right-4 p-3 rounded-xl bg-[#454955] text-[#0d0a0b] transition-all disabled:opacity-30 disabled:hover:scale-100 hover:scale-105 active:scale-95 luminous-glow flex items-center justify-center"
            aria-label="Send reply"
          >
            <Send className="w-5 h-5" />
          </button>
        </div>
      </footer>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Check, X, Search, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';
import { useAuth } from '@/context/AuthContext';
import { Notification } from '@/types/notification';

interface UnattributedTransactionCardProps {
  item: Notification;
  onAssignComplete: () => Promise<void>;
}

export default function UnattributedTransactionCard({
  item,
  onAssignComplete,
}: UnattributedTransactionCardProps) {
  const { user } = useAuth();
  const [projects, setProjects] = useState<any[]>([]);
  const [selectedProjectId, setSelectedProjectId] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(true);
  const [submitting, setSubmitting] = useState<boolean>(false);
  const [ignoring, setIgnoring] = useState<boolean>(false);
  const [searching, setSearching] = useState<boolean>(false);

  const metadata = item.objectReference?.metadata || {};
  const plaidId = metadata.plaidId as string;
  const txName = metadata.name as string || item.title || 'Unknown Transaction';
  const txAmount = Number(metadata.amount || 0);
  const txDate = metadata.date ? new Date(metadata.date as string) : new Date();
  const suggestedCategory = metadata.reiCategory as string || 'unknown';

  // Format amount
  const formattedAmount = (txAmount / 100).toLocaleString('en-US', {
    style: 'currency',
    currency: 'USD',
  });

  // Fetch projects on mount
  useEffect(() => {
    async function fetchProjects() {
      try {
        const idToken = await user?.getIdToken();
        const res = await fetch('/api/projects', {
          headers: {
            Authorization: `Bearer ${idToken}`,
          },
        });
        const data = await res.json();
        if (data.success) {
          setProjects(data.projects || []);
        } else {
          console.error('[UnattributedTransactionCard] Failed to fetch projects:', data.error);
        }
      } catch (err) {
        console.error('[UnattributedTransactionCard] Error fetching projects:', err);
      } finally {
        setLoading(false);
      }
    }

    if (user) {
      fetchProjects();
    }
  }, [user]);

  // Handle manual assign
  const handleAssign = async () => {
    if (!selectedProjectId) {
      toast.error('Please select a project');
      return;
    }

    setSubmitting(true);
    try {
      const idToken = await user?.getIdToken();
      const res = await fetch(`/api/transactions/${plaidId}/attribution`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${idToken}`,
        },
        body: JSON.stringify({ projectId: selectedProjectId }),
      });

      const data = await res.json();
      if (data.success) {
        toast.success('Transaction attributed successfully!', {
          style: { background: '#0d0d0d', color: '#fff' },
        });
        await onAssignComplete();
      } else {
        toast.error(data.error || 'Failed to attribute transaction');
      }
    } catch (err) {
      console.error(err);
      toast.error('Error attributing transaction');
    } finally {
      setSubmitting(false);
    }
  };

  // Handle ignore
  const handleIgnore = async () => {
    setIgnoring(true);
    try {
      const idToken = await user?.getIdToken();
      const res = await fetch(`/api/transactions/${plaidId}/attribution`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${idToken}`,
        },
        body: JSON.stringify({ projectId: null, ignore: true }),
      });

      const data = await res.json();
      if (data.success) {
        toast.success('Transaction ignored', {
          style: { background: '#0d0d0d', color: '#fff' },
        });
        await onAssignComplete();
      } else {
        toast.error(data.error || 'Failed to ignore transaction');
      }
    } catch (err) {
      console.error(err);
      toast.error('Error ignoring transaction');
    } finally {
      setIgnoring(false);
    }
  };

  // Handle search again (re-runs matching engine)
  const handleSearchAgain = async () => {
    setSearching(true);
    try {
      const idToken = await user?.getIdToken();
      const res = await fetch(`/api/transactions/${plaidId}/attribution/search`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${idToken}`,
        },
      });

      const data = await res.json();
      if (data.success && data.projectId) {
        setSelectedProjectId(data.projectId);
        toast.success(`Suggested project: ${data.projectName || data.projectId}`, {
          style: { background: '#0d0d0d', color: '#fff' },
        });
      } else {
        toast.error('No project match found. Choose manually.', {
          style: { background: '#0d0d0d', color: '#fff' },
        });
      }
    } catch (err) {
      console.error(err);
      toast.error('Failed to run matching search');
    } finally {
      setSearching(false);
    }
  };

  return (
    <div className="mt-4 p-5 rounded-2xl bg-white/5 border border-white/10 text-white space-y-4">
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-2 pb-3 border-b border-white/5">
        <div>
          <h4 className="text-sm font-bold tracking-wide">{txName}</h4>
          <p className="text-[10px] text-gray-400">
            Suggested Category: <span className="text-primary font-semibold">{suggestedCategory}</span>
          </p>
        </div>
        <div className="text-right">
          <span className="text-sm font-black text-white">{formattedAmount}</span>
          <p className="text-[10px] text-gray-400">{txDate.toLocaleDateString('en-US')}</p>
        </div>
      </div>

      <div className="space-y-4">
        {loading ? (
          <div className="flex items-center gap-2 text-xs text-gray-400 py-2">
            <Loader2 className="w-4 h-4 animate-spin text-primary" />
            Loading candidate projects...
          </div>
        ) : (
          <div>
            <label className="block text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">
              ASSIGN TO PROJECT
            </label>
            <select
              id={`select-project-${plaidId}`}
              value={selectedProjectId}
              onChange={(e) => setSelectedProjectId(e.target.value)}
              className="w-full px-4 py-3 bg-[#121014] border border-white/10 rounded-full text-white text-xs font-bold tracking-widest focus:outline-none focus:border-primary transition-all"
            >
              <option value="">Select a project...</option>
              {projects.map((proj) => (
                <option key={proj.id} value={proj.id} className="bg-[#121014]">
                  {proj.propertyName || proj.address || proj.id}
                </option>
              ))}
            </select>
          </div>
        )}

        <div className="flex flex-wrap items-center gap-2.5 pt-2">
          <button
            id={`btn-assign-${plaidId}`}
            onClick={handleAssign}
            disabled={submitting || ignoring || searching || !selectedProjectId}
            className="flex items-center gap-1.5 px-4 py-2.5 text-[11px] font-bold uppercase tracking-wider bg-white text-black hover:bg-white/90 disabled:opacity-50 transition-colors cursor-pointer"
          >
            {submitting ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <Check className="w-3.5 h-3.5" />
            )}
            Assign to Project
          </button>

          <button
            id={`btn-search-again-${plaidId}`}
            onClick={handleSearchAgain}
            disabled={submitting || ignoring || searching}
            className="flex items-center gap-1.5 px-4 py-2.5 text-[11px] font-bold uppercase tracking-wider bg-white/10 hover:bg-white/25 text-white disabled:opacity-50 transition-colors border border-white/10 cursor-pointer"
          >
            {searching ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <Search className="w-3.5 h-3.5" />
            )}
            Search Again
          </button>

          <button
            id={`btn-ignore-${plaidId}`}
            onClick={handleIgnore}
            disabled={submitting || ignoring || searching}
            className="flex items-center gap-1.5 px-4 py-2.5 text-[11px] font-bold uppercase tracking-wider bg-red-600/20 hover:bg-red-600/35 text-red-400 disabled:opacity-50 transition-colors border border-red-500/20 cursor-pointer"
          >
            {ignoring ? (
              <Loader2 className="w-3.5 h-3.5 animate-spin" />
            ) : (
              <X className="w-3.5 h-3.5" />
            )}
            Ignore
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { useQuery } from '@tanstack/react-query';
import { useAuth } from '@/context/AuthContext';
import { PortfolioComparisonChart } from '@/components/Charts/PortfolioComparisonChart';
import { ChevronDown, ArrowUpDown, TrendingUp, TrendingDown } from 'lucide-react';

const COMPARE_METRICS = [
  { id: 'cap_rate', name: 'Cap Rate' },
  { id: 'cash_on_cash', name: 'Cash-on-Cash Return' },
  { id: 'dscr', name: 'Debt Service Coverage (DSCR)' },
  { id: 'ltv', name: 'Loan-to-Value (LTV)' },
  { id: 'oer', name: 'Operating Expense Ratio (OER)' },
  { id: 'grm', name: 'Gross Rent Multiplier (GRM)' }
] as const;

type MetricId = typeof COMPARE_METRICS[number]['id'];

export function ComparisonSection() {
  const { user } = useAuth();
  const [selectedMetric, setSelectedMetric] = useState<MetricId>('cap_rate');
  const [sortOrder, setSortOrder] = useState<'none' | 'asc' | 'desc'>('none');

  // Query financial metrics with project breakdown
  const { data, isLoading, error } = useQuery({
    queryKey: ['insightsComparison', 'financial'],
    queryFn: async () => {
      if (!user) return null;
      const token = await user.getIdToken();
      const url = new URL('/api/insights/metrics', window.location.origin);
      url.searchParams.set('category', 'financial');
      url.searchParams.set('portfolio', 'true');
      url.searchParams.set('breakdown', 'true');

      const res = await fetch(url.toString(), {
        headers: {
          'Authorization': `Bearer ${token}`
        }
      });
      if (!res.ok) {
        throw new Error('Failed to fetch comparison metrics');
      }
      return res.json() as Promise<{
        hasLinkedBank: boolean;
        metrics: any[];
        projectBreakdowns: {
          projectId: string;
          projectName: string;
          metrics: Record<string, number | null>;
        }[];
      }>;
    },
    enabled: !!user,
  });

  // Calculate portfolio average value for the selected metric
  const averageValue = useMemo(() => {
    if (!data?.metrics) return null;
    const m = data.metrics.find(item => item.id === selectedMetric);
    return m?.value ?? null;
  }, [data, selectedMetric]);

  // Extract and sort comparison data points
  const chartPoints = useMemo(() => {
    if (!data?.projectBreakdowns) return [];

    // Map breakdown to points
    const points = data.projectBreakdowns
      .map(p => {
        const val = p.metrics[selectedMetric];
        return {
          projectId: p.projectId,
          projectName: p.projectName,
          value: val !== undefined && val !== null ? val : null
        };
      })
      // Filter out projects with missing values
      .filter((p): p is { projectId: string; projectName: string; value: number } => p.value !== null);

    // Apply sort if requested
    if (sortOrder === 'asc') {
      return [...points].sort((a, b) => a.value - b.value);
    } else if (sortOrder === 'desc') {
      return [...points].sort((a, b) => b.value - a.value);
    }
    return points;
  }, [data, selectedMetric, sortOrder]);

  const toggleSort = () => {
    if (sortOrder === 'none') {
      setSortOrder('desc');
    } else if (sortOrder === 'desc') {
      setSortOrder('asc');
    } else {
      setSortOrder('none');
    }
  };

  return (
    <div className="bg-white dark:bg-[#121014]/50 border border-slate-200 dark:border-white/10 rounded-2xl p-6 shadow-sm hover:shadow-md transition-shadow duration-300 space-y-6">

      {/* Header controls */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-100 dark:border-white/5 pb-4">
        <div>
          <h2 className="text-lg font-bold text-slate-900 dark:text-white font-outfit tracking-tight">
            Project Comparison
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
            Compare active real estate projects. Highlighting top 3 in green, bottom 3 in red.
          </p>
        </div>

        <div className="flex items-center gap-2">
          {/* Sort Button */}
          <button
            onClick={toggleSort}
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-semibold tracking-wide transition-all duration-200 active:scale-98 cursor-pointer ${
              sortOrder !== 'none'
                ? 'bg-slate-100 dark:bg-white/10 border-slate-300 dark:border-white/20 text-slate-900 dark:text-white'
                : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-white/10'
            }`}
            title="Sort projects by value"
          >
            <ArrowUpDown className="w-3.5 h-3.5" />
            Sort: {sortOrder === 'none' ? 'Default' : sortOrder === 'asc' ? 'Low to High' : 'High to Low'}
          </button>

          {/* Metric Selector Dropdown */}
          <div className="relative">
            <select
              value={selectedMetric}
              onChange={(e) => setSelectedMetric(e.target.value as MetricId)}
              className="appearance-none bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-lg py-1.5 pl-3 pr-8 text-xs font-semibold text-slate-800 dark:text-slate-200 focus:outline-none focus:ring-1 focus:ring-slate-700 cursor-pointer"
            >
              {COMPARE_METRICS.map((opt) => (
                <option key={opt.id} value={opt.id} className="dark:bg-slate-950">
                  {opt.name}
                </option>
              ))}
            </select>
            <ChevronDown className="w-3.5 h-3.5 absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none" />
          </div>
        </div>
      </div>

      {/* Comparison Chart Container */}
      {isLoading ? (
        <div className="h-[320px] w-full flex flex-col justify-end space-y-2 animate-pulse bg-slate-50/50 dark:bg-white/[0.01] border border-dashed border-slate-200 dark:border-white/5 rounded-2xl p-4">
          <div className="flex justify-between items-end h-full w-full gap-4 px-4">
            {[...Array(6)].map((_, i) => (
              <div 
                key={i} 
                className="bg-slate-200 dark:bg-white/10 rounded-t w-full" 
                style={{ height: `${30 + Math.cos(i * 1.5) * 40}%` }}
              />
            ))}
          </div>
          <div className="h-4 bg-slate-200 dark:bg-white/10 rounded w-1/4 mx-auto" />
        </div>
      ) : error ? (
        <div className="h-[320px] w-full flex items-center justify-center border border-dashed border-rose-200 dark:border-rose-500/20 bg-rose-500/5 rounded-2xl text-rose-500 text-xs font-medium px-4 text-center">
          Failed to load portfolio comparison data. Please check your network.
        </div>
      ) : chartPoints.length === 0 ? (
        <div className="h-[320px] w-full flex flex-col items-center justify-center border border-dashed border-slate-200 dark:border-white/10 rounded-2xl text-slate-400 dark:text-slate-500 text-xs font-medium p-4 text-center">
          No comparison points available. Ensure projects have valid financial records.
        </div>
      ) : (
        <PortfolioComparisonChart
          data={chartPoints}
          metricId={selectedMetric}
          averageValue={averageValue}
          height={320}
        />
      )}
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import ReactECharts from 'echarts-for-react';
import type { PortfolioMetricSnapshot } from '@/hooks/usePortfolioMetricSnapshots';
import type { Project } from '@/types/schema';
import { deriveActualMetrics } from '@/lib/insights/engine';

interface ChartProps {
  snapshots: PortfolioMetricSnapshot[];
}

interface TooltipParam {
  axisValue: string;
  seriesName: string;
  value: number;
  color: string;
}

function getBreachPoints(
  periods: string[],
  data: number[],
  checkFn: (val: number) => boolean
) {
  const points: any[] = [];
  data.forEach((val, idx) => {
    if (checkFn(val)) {
      points.push({
        name: 'Breach',
        coord: [periods[idx], val],
        symbol: 'pin',
        symbolSize: 14,
        itemStyle: { color: '#f43f5e' },
        label: {
          show: true,
          formatter: '!',
          color: '#ffffff',
          fontSize: 8,
          fontWeight: 'bold',
          position: 'inside',
          offset: [0, -1]
        }
      });
    }
  });
  return points;
}

export function ShortTermTrendChart({ snapshots }: ChartProps) {
  const sorted = useMemo(() => {
    return [...snapshots].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  }, [snapshots]);

  const periods = sorted.map((s) => s.period);
  const noiData = sorted.map((s) => s.noi ?? 0);
  const cfData = sorted.map((s) => s.monthlyCashFlow ?? 0);
  const vacancyData = sorted.map((s) => s.vacancyRate ?? 0);
  const oerData = sorted.map((s) => s.oer ?? 0);

  const option = {
    backgroundColor: 'transparent',
    tooltip: {
      trigger: 'axis',
      backgroundColor: '#1e1b20',
      borderColor: 'rgba(255,255,255,0.1)',
      textStyle: { color: '#9E9DA0', fontSize: 11, fontFamily: 'var(--font-plus-jakarta)' },
      formatter: (params: unknown) => {
        const arr = params as TooltipParam[];
        if (!arr || arr.length === 0) return '';
        let res = `<div class="font-plus-jakarta text-xs font-light text-[#9E9DA0] mb-1">${arr[0].axisValue}</div>`;
        arr.forEach((p) => {
          let valStr = String(p.value);
          if (p.seriesName === 'NOI' || p.seriesName === 'Cash Flow') {
            valStr = '$' + Math.round(p.value).toLocaleString();
          } else if (p.seriesName === 'Vacancy' || p.seriesName === 'OER') {
            valStr = p.value.toFixed(1) + '%';
          }
          res += `
            <div class="flex items-center justify-between gap-4 text-xs font-plus-jakarta">
              <span class="flex items-center gap-1.5 font-light text-[#C0BEC2]">
                <span class="w-2 h-2 rounded-full" style="background:${p.color}"></span>
                ${p.seriesName}
              </span>
              <span class="font-mono font-semibold text-white">${valStr}</span>
            </div>
          `;
        });
        return res;
      }
    },
    legend: {
      data: ['NOI', 'Cash Flow', 'Vacancy', 'OER'],
      selected: {
        'NOI': true,
        'Cash Flow': true,
        'Vacancy': false,
        'OER': false,
      },
      textStyle: { color: '#9E9DA0', fontSize: 10, fontFamily: 'var(--font-plus-jakarta)' },
      bottom: 0,
    },
    grid: { top: 35, right: 45, bottom: 45, left: 65 },
    xAxis: {
      type: 'category',
      data: periods,
      axisLine: { show: false },
      axisTick: { show: false },
      axisLabel: { color: '#9E9DA0', fontSize: 9, fontFamily: 'var(--font-plus-jakarta)' },
    },
    yAxis: [
      {
        type: 'value',
        name: 'Currency ($)',
        nameTextStyle: { color: '#859490', fontSize: 8, fontFamily: 'var(--font-plus-jakarta)' },
        axisLabel: {
          color: '#859490',
          fontSize: 9,
          fontFamily: 'var(--font-mono)',
          formatter: (v: number) => {
            if (v >= 1_000_000) return `$${(v / 1_000_000).toFixed(1)}M`;
            if (v >= 1_000) return `$${(v / 1_000).toFixed(0)}k`;
            return `$${v}`;
          }
        },
        splitLine: { lineStyle: { color: 'rgba(255,255,255,0.04)' } },
      },
      {
        type: 'value',
        name: 'Percentage (%)',
        nameTextStyle: { color: '#859490', fontSize: 8, fontFamily: 'var(--font-plus-jakarta)' },
        axisLabel: { color: '#859490', fontSize: 9, fontFamily: 'var(--font-mono)', formatter: '{value}%' },
        splitLine: { show: false },
      }
    ],
    series: [
      {
        name: 'NOI',
        type: 'line',
        data: noiData,
        smooth: true,
        lineStyle: { width: 2, color: '#3b82f6' },
        itemStyle: { color: '#3b82f6' },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(59, 130, 246, 0.15)' },
              { offset: 1, color: 'rgba(59, 130, 246, 0)' }
            ]
          }
        },
        symbol: 'circle',
        symbolSize: 6,
      },
      {
        name: 'Cash Flow',
        type: 'line',
        data: cfData,
        smooth: true,
        lineStyle: { width: 2, color: '#454955' },
        itemStyle: { color: '#454955' },
        areaStyle: {
          color: {
            type: 'linear',
            x: 0, y: 0, x2: 0, y2: 1,
            colorStops: [
              { offset: 0, color: 'rgba(69, 73, 85, 0.15)' },
              { offset: 1, color: 'rgba(69, 73, 85, 0)' }
            ]
          }
        },
        symbol: 'circle',
        symbolSize: 6,
        markPoint: {
          data: getBreachPoints(periods, cfData, (v) => v < 0)
        }
      },
      {
        name: 'Vacancy',
        type: 'line',
        yAxisIndex: 1,
        data: vacancyData,
        smooth: true,
        lineStyle: { width: 2, color: '#F06543' },
        itemStyle: { color: '#F06543' },
        symbol: 'circle',
        symbolSize: 6,
        markLine: {
          silent: true,
          lineStyle: { type: 'dashed', color: 'rgba(239, 68, 68, 0.3)' },
          data: [
            { yAxis: 10, label: { formatter: 'Vacancy Threshold (10%)', position: 'end', color: '#F06543', fontSize: 8 } }
          ]
        },
        markPoint: {
          data: getBreachPoints(periods, vacancyData, (v) => v > 10)
        }
      },
      {
        name: 'OER',
        type: 'line',
        yAxisIndex: 1,
        data: oerData,
        smooth: true,
        lineStyle: { width: 2, color: '#f59e0b' },
        itemStyle: { color: '#f59e0b' },
        symbol: 'circle',
        symbolSize: 6,
        markLine: {
          silent: true,
          lineStyle: { type: 'dashed', color: 'rgba(245, 158, 11, 0.3)' },
          data: [
            { yAxis: 40, label: { formatter: 'OER Target (40%)', position: 'start', color: '#f59e0b', fontSize: 8 } }
          ]
        },
        markPoint: {
          data: getBreachPoints(periods, oerData, (v) => v > 40)
        }
      }
    ],
  };

  return <ReactECharts option={option} style={{ height: 260, width: '100%' }} opts={{ renderer: 'canvas' }} />;
}

