    gross_rent_per_unit: 'income',
    vacancy_pct: 'income',
    tax: 'tax',
    insurance: 'tax',
    utilities: 'tax',
    management_pct: 'tax',
    management: 'tax',
    maintenance: 'tax',
    maintenance_pct: 'tax',
    HOA: 'tax',
    psa: 'psa',
    emdAmount: 'earnest_money',
    inspection: 'inspection',
    title: 'title',
  };
  return map[registryId] || registryId;
}

function getDocumentLabelForField(registryId: string): string {
  const map: Record<string, string> = {
