'use client';

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import {
  DollarSign, TrendingDown, TrendingUp, AlertTriangle,
  CheckCircle2, Building2, Percent, PieChart,
} from 'lucide-react';
import { computeOER } from '@/lib/metrics/reiMetrics';

/* ═══════════════════════════════════════════════════════════════
   EXPENSE RATIO COLLECTION TERMINAL
   Collects operating expense line-items and gross rental income,
   computes Expense Ratio = (Operating Expenses ÷ Gross Income) × 100
   Seed: $9,276 ÷ $23,400 = 39.64%

   Dual-scope: Project (individual) + Portfolio-wide (cumulative)
   ═══════════════════════════════════════════════════════════════ */

export interface ExpenseItem {
  id: string;
  label: string;
  monthlyAmount: number;
  color: string;
}

export interface ExpenseRatioValues {
  grossMonthlyRent: number;
  grossAnnualRent: number;
  totalMonthlyExpenses: number;
  totalAnnualExpenses: number;
  expenseRatio: number;
  items: ExpenseItem[];
  zone: 'excellent' | 'efficient' | 'review';
}

interface ExpenseRatioCollectionTerminalProps {
  defaults?: Partial<{
    grossMonthlyRent: number;
    items: ExpenseItem[];
  }>;
  onValuesChange?: (values: ExpenseRatioValues) => void;
  className?: string;
}

/* ── Seed expense breakdown matching $9,276 annual ── */
const SEED_ITEMS: ExpenseItem[] = [
  { id: '1', label: 'Property Taxes',    monthlyAmount: 279, color: '#454955' },
  { id: '2', label: 'Insurance',         monthlyAmount: 155, color: '#38bdf8' },
  { id: '3', label: 'Utilities',         monthlyAmount: 95,  color: '#64748b' },
  { id: '4', label: 'Property Mgmt',     monthlyAmount: 195, color: '#fb923c' },
  { id: '5', label: 'Maintenance',       monthlyAmount: 49,  color: '#fbbf24' },
];
// Total: 773/mo × 12 = $9,276

const COLORS = ['#454955', '#38bdf8', '#64748b', '#fb923c', '#fbbf24', '#3f7d20', '#F06543', '#94a3b8'];

/* ── Zone configuration ── */
const ZONE_CFG = {
  excellent: { label: 'Excellent', color: '#3f7d20', range: '<35%', icon: CheckCircle2 },
  efficient: { label: 'Efficient', color: '#fbbf24', range: '35–45%', icon: TrendingUp },
  review:    { label: 'Review',    color: '#F06543', range: '>45%',  icon: AlertTriangle },
} as const;

function getZone(ratio: number): 'excellent' | 'efficient' | 'review' {
  if (ratio < 35) return 'excellent';
  if (ratio <= 45) return 'efficient';
  return 'review';
}

/* ═══════════════════════════════════════════════════════════════
   EXPENSE LINE ITEM ROW
   ═══════════════════════════════════════════════════════════════ */

function ExpenseRow({
  item,
  totalExpenses,
  onChange,
  onRemove,
}: {
  item: ExpenseItem;
  totalExpenses: number;
  onChange: (updated: ExpenseItem) => void;
  onRemove: () => void;
}) {
  const pctOfTotal = totalExpenses > 0 ? (item.monthlyAmount / totalExpenses) * 100 : 0;

  return (
    <div className="flex items-center gap-3 py-2 border-b border-white/[0.04] group">
      {/* Color dot */}
      <span
        className="w-2.5 h-2.5 rounded-full flex-shrink-0"
        style={{ backgroundColor: item.color }}
      />

      {/* Label */}
      <input
        type="text"
        value={item.label}
        onChange={(e) => onChange({ ...item, label: e.target.value })}
        className="flex-1 bg-transparent text-sm text-[#C0BEC2] font-medium focus:outline-none
                   border-b border-transparent focus:border-white/20 transition-all"
        placeholder="Expense category"
      />

      {/* Monthly amount */}
      <div className="flex items-center gap-1">
        <span className="text-[10px] text-slate-600">$</span>
        <input
          type="number"
          value={item.monthlyAmount}
          onChange={(e) => onChange({ ...item, monthlyAmount: Math.max(0, Number(e.target.value) || 0) })}
          min={0}
          className="w-16 bg-white/[0.03] border border-white/[0.06] rounded px-2 py-1 text-xs text-[#C0BEC2]
                     font-mono tabular-nums text-right focus:outline-none focus:border-[#454955]/30 transition-all"
        />
        <span className="text-[9px] text-slate-600">/mo</span>
      </div>

      {/* % of total */}
      <span className="text-[10px] font-bold tabular-nums w-10 text-right" style={{ color: item.color }}>
        {pctOfTotal.toFixed(0)}%
      </span>

      {/* Remove */}
      <button
        onClick={onRemove}
        className="text-slate-700 hover:text-red-400 transition-colors opacity-0 group-hover:opacity-100 text-xs"
        title="Remove"
      >
        ×
      </button>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   MINI DONUT
   ═══════════════════════════════════════════════════════════════ */

function ExpenseDonut({ items, totalExpenses }: { items: ExpenseItem[]; totalExpenses: number }) {
  const r = 28;
  const circ = 2 * Math.PI * r;
  let cumOffset = 0;

  return (
    <svg width={72} height={72} viewBox="0 0 72 72">
      <circle cx="36" cy="36" r={r} fill="none" stroke="rgba(255,255,255,0.04)" strokeWidth="8" />
      {items.map((item) => {
        const pct = totalExpenses > 0 ? item.monthlyAmount / totalExpenses : 0;
        const segLen = circ * pct;
        const gap = circ - segLen;
        const offset = cumOffset;
        cumOffset += segLen;
        return (
          <circle
            key={item.id}
            cx="36"
            cy="36"
            r={r}
            fill="none"
            stroke={item.color}
            strokeWidth="8"
            strokeDasharray={`${segLen} ${gap}`}
            strokeDashoffset={-offset}
            transform="rotate(-90 36 36)"
            className="transition-all duration-500"
          />
        );
      })}
    </svg>
  );
}

/* ═══════════════════════════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════════════════════════ */

export function ExpenseRatioCollectionTerminal({
  defaults = {},
  onValuesChange,
  className = '',
}: ExpenseRatioCollectionTerminalProps) {
  const [grossMonthlyRent, setGrossMonthlyRent] = useState(defaults.grossMonthlyRent ?? 1950);
  const [items, setItems] = useState<ExpenseItem[]>(defaults.items ?? SEED_ITEMS);

  /* ── Computations ── */
  const computed = useMemo(() => {
    const totalMonthlyExpenses = items.reduce((sum, i) => sum + i.monthlyAmount, 0);
    const grossAnnualRent = grossMonthlyRent * 12;
    const totalAnnualExpenses = totalMonthlyExpenses * 12;
    const expenseRatio = computeOER(totalAnnualExpenses, grossAnnualRent);
    const zone = getZone(expenseRatio);

    return {
      grossMonthlyRent,
      grossAnnualRent,
      totalMonthlyExpenses,
      totalAnnualExpenses,
      expenseRatio,
      items,
      zone,
    };
  }, [grossMonthlyRent, items]);

  const stableOnChange = useCallback((values: ExpenseRatioValues) => {
    onValuesChange?.(values);
  }, [onValuesChange]);

  useEffect(() => {
    stableOnChange(computed);
  }, [computed, stableOnChange]);

  /* ── Item management ── */
  const handleItemChange = useCallback((idx: number, updated: ExpenseItem) => {
    setItems(prev => prev.map((item, i) => i === idx ? updated : item));
  }, []);

  const handleRemoveItem = useCallback((idx: number) => {
    setItems(prev => prev.filter((_, i) => i !== idx));
  }, []);

  const handleAddItem = useCallback(() => {
    setItems(prev => [...prev, {
      id: String(Date.now()),
      label: '',
      monthlyAmount: 0,
      color: COLORS[prev.length % COLORS.length],
    }]);
  }, []);

  /* ── Zone styling ── */
  const zoneCfg = ZONE_CFG[computed.zone];
  const ZoneIcon = zoneCfg.icon;

  /* ── Gradient bar position (25% to 60% mapped to 0-100) ── */
  const markerPct = Math.min(Math.max(((computed.expenseRatio - 25) / 35) * 100, 0), 100);

  return (
    <div
      className={`rounded-xl border border-white/10 p-6 space-y-4 ${className}`}
      style={{ background: 'rgba(24,33,39,0.7)', backdropFilter: 'blur(16px)' }}
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[#454955]/10 flex items-center justify-center">
            <PieChart className="w-4 h-4 text-[#454955]" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white">Expense Ratio</h3>
            <p className="text-[10px] text-[#6B6870] uppercase tracking-widest font-bold">
              Operating Costs Collection
            </p>
          </div>
        </div>
        <span
          className="px-2 py-0.5 rounded border text-[10px] font-bold uppercase tracking-wider"
          style={{
            color: zoneCfg.color,
            borderColor: `${zoneCfg.color}40`,
            background: `${zoneCfg.color}10`,
          }}
        >
          <ZoneIcon className="w-3 h-3 inline mr-0.5" />
          {zoneCfg.label}
        </span>
      </div>

      {/* ── Result hero ── */}
      <div
        className="rounded-xl border p-4 flex items-center justify-between transition-all duration-500"
        style={{ borderColor: `${zoneCfg.color}30`, background: `${zoneCfg.color}08` }}
      >
        <div className="flex items-center gap-3">
          <ExpenseDonut items={items} totalExpenses={computed.totalMonthlyExpenses} />
          <div>
            <p className="text-xs font-bold" style={{ color: zoneCfg.color }}>
              {computed.expenseRatio < 40 ? 'Below' : 'At'} the 40% threshold
            </p>
            <p className="text-[10px] text-[#6B6870] mt-0.5">
              ${computed.totalAnnualExpenses.toLocaleString()} of ${computed.grossAnnualRent.toLocaleString()} gross income
            </p>
          </div>
        </div>
        <div className="text-right">
          <span className="text-4xl font-bold tabular-nums tracking-tighter" style={{ color: zoneCfg.color }}>
            {computed.expenseRatio.toFixed(1)}
          </span>
          <span className="text-lg font-bold ml-0.5" style={{ color: zoneCfg.color }}>%</span>
          <p className="text-[9px] text-slate-600 mt-0.5">expense ratio</p>
        </div>
      </div>

      {/* ── Gradient zone bar ── */}
      <div className="space-y-1">
        <div
          className="relative h-2.5 rounded-full overflow-hidden"
          style={{ background: 'linear-gradient(to right, #3f7d20 0%, #fbbf24 50%, #F06543 100%)' }}
        >
          <div
            className="absolute top-1/2 -translate-y-1/2 -translate-x-1/2 w-3 h-3 rounded-full bg-white border-2 border-[#0d0a0b] shadow transition-all duration-500"
            style={{ left: `${markerPct}%` }}
          />
        </div>
        <div className="flex justify-between text-[8px] font-bold uppercase tracking-widest text-slate-600">
          <span>Excellent &lt;35%</span>
          <span>Efficient 35–45%</span>
          <span>Review &gt;45%</span>
        </div>
      </div>

      {/* ── Gross Rental Income input ── */}
      <div className="px-3 py-3 rounded-lg bg-white/[0.03] border border-white/[0.06]">
        <div className="flex items-center justify-between">
          <label className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870] flex items-center gap-1">
            <DollarSign className="w-3 h-3" /> Gross Monthly Rent
          </label>
          <div className="flex items-center gap-1">
            <span className="text-xs text-slate-600">$</span>
            <input
              type="number"
              value={grossMonthlyRent}
              onChange={(e) => setGrossMonthlyRent(Math.max(0, Number(e.target.value) || 0))}
              min={0}
              className="w-24 bg-white/[0.04] border border-white/[0.08] rounded px-2 py-1.5 text-sm text-white
                         font-mono tabular-nums text-right focus:outline-none focus:border-[#454955]/30 transition-all"
            />
            <span className="text-[9px] text-slate-600">/mo</span>
          </div>
        </div>
        <p className="text-[9px] text-slate-600 mt-1">
          Annual: ${computed.grossAnnualRent.toLocaleString()} — excludes vacancy (not an operating expense)
        </p>
      </div>

      {/* ── Expense line items ── */}
      <div>
        <div className="flex items-center justify-between mb-2">
          <span className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870]">
            Operating Expenses
          </span>
          <span className="text-[10px] font-bold tabular-nums text-[#9E9DA0]">
            ${computed.totalMonthlyExpenses.toLocaleString()}/mo
          </span>
        </div>

        <div className="max-h-56 overflow-y-auto pr-1">
          {items.map((item, idx) => (
            <ExpenseRow
              key={item.id}
              item={item}
              totalExpenses={computed.totalMonthlyExpenses}
              onChange={(u) => handleItemChange(idx, u)}
              onRemove={() => handleRemoveItem(idx)}
            />
          ))}
        </div>

        {/* Total */}
        <div className="flex items-center justify-between py-2 mt-1 border-t border-white/10">
          <span className="text-xs font-bold text-white">Total Annual OpEx</span>
          <span className="text-xs font-bold tabular-nums" style={{ color: zoneCfg.color }}>
            ${computed.totalAnnualExpenses.toLocaleString()}
          </span>
        </div>

        {/* Add expense */}
        <button
          onClick={handleAddItem}
          className="w-full py-2 mt-1 rounded-lg border border-dashed border-white/10 text-[10px] font-bold text-[#6B6870]
                     hover:border-[#454955]/30 hover:text-[#454955] transition-all flex items-center justify-center gap-1"
        >
          + Add Expense
        </button>
      </div>

      {/* ── Formula ── */}
      <div className="px-3 py-2 rounded-lg bg-white/[0.02] border border-white/[0.04]">
        <p className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Formula</p>
        <p className="text-[11px] text-[#9E9DA0] font-mono">
          Expense Ratio = (${computed.totalAnnualExpenses.toLocaleString()} ÷ ${computed.grossAnnualRent.toLocaleString()}) × 100 = {computed.expenseRatio.toFixed(1)}%
        </p>
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { BarChart3, ArrowDown, ArrowUp, Trophy, AlertTriangle, ChevronRight, Minus } from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   GRM COMPARISON CARD — Multi-Property Deal Compare
   Side-by-side comparison of GRM across portfolio deals.
   Formula: GRM = Property Price ÷ Gross Annual Rent
   Lower GRM = better rent-to-price ratio.
   ═══════════════════════════════════════════════════════════════ */

interface DealEntry {
  id: string;
  address: string;
  propertyPrice: number;
  grossAnnualRent: number;
  grm?: number; // if pre-computed
}

interface GRMComparisonCardProps {
  deals: DealEntry[];
  marketGRM?: number;
  className?: string;
}

/* ── Formatting ── */
const fmtCompact = (v: number): string => {
  if (v >= 1_000_000) return `$${(v / 1_000_000).toFixed(2)}M`;
  if (v >= 1000) return `$${(v / 1000).toFixed(0)}k`;
  return `$${v.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;
};

/* ── GRM color by value ── */
function grmColor(grm: number, marketGRM: number): string {
  if (grm <= marketGRM * 0.8) return '#14B8A6'; // strong buy — well below market
  if (grm <= marketGRM) return '#3B82F6';        // good — at or below market
  if (grm <= marketGRM * 1.2) return '#EAB308';  // caution — slightly above market
  return '#F06543';                               // overpriced
}

function grmSignal(grm: number, marketGRM: number): { label: string; className: string } {
  if (grm <= marketGRM * 0.8) return { label: 'Strong Buy', className: 'bg-[#6E7480]/10 border-[#6E7480]/20 text-[#6E7480]' };
  if (grm <= marketGRM) return { label: 'Buy', className: 'bg-blue-400/10 border-blue-400/20 text-blue-400' };
  if (grm <= marketGRM * 1.2) return { label: 'Hold', className: 'bg-amber-400/10 border-amber-400/20 text-amber-400' };
  return { label: 'Avoid', className: 'bg-red-400/10 border-red-400/20 text-red-400' };
}

/* ═══════════════════════════════════════════════════════════════
   HORIZONTAL GRM BAR — One per deal
   ═══════════════════════════════════════════════════════════════ */

function GRMBar({ grm, maxGRM, marketGRM }: { grm: number; maxGRM: number; marketGRM: number }) {
  const pct = Math.min((grm / maxGRM) * 100, 100);
  const marketPct = Math.min((marketGRM / maxGRM) * 100, 100);
  const color = grmColor(grm, marketGRM);

  return (
    <div className="relative h-2.5 rounded-full overflow-hidden bg-white/[0.04]">
      {/* Market reference line */}
      <div
        className="absolute top-0 bottom-0 w-px border-l border-dashed border-white/20 z-10"
        style={{ left: `${marketPct}%` }}
      />
      {/* Fill */}
      <div
        className="absolute inset-y-0 left-0 rounded-full transition-all duration-700 ease-out"
        style={{ width: `${pct}%`, backgroundColor: `${color}60` }}
      />
      {/* Needle */}
      <div
        className="absolute top-0 bottom-0 w-0.5 rounded transition-all duration-700"
        style={{ left: `${pct}%`, backgroundColor: color }}
      />
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════════════════════════ */

export function GRMComparisonCard({
  deals,
  marketGRM = 10.5,
  className = '',
}: GRMComparisonCardProps) {
  /* ── Compute GRMs ── */
  const rankedDeals = useMemo(() => {
    const computed = deals.map((d) => {
      const grm = d.grm ?? (d.grossAnnualRent > 0 ? Math.round((d.propertyPrice / d.grossAnnualRent) * 100) / 100 : 0);
      const vsMarket = grm - marketGRM;
      return { ...d, grm, vsMarket };
    });
    return computed.sort((a, b) => a.grm - b.grm); // best first
  }, [deals, marketGRM]);

  const maxGRM = useMemo(() => {
    const max = Math.max(...rankedDeals.map((d) => d.grm), marketGRM);
    return Math.ceil(max / 5) * 5 || 20; // round up to nearest 5
  }, [rankedDeals, marketGRM]);

  /* ── Summary stats ── */
  const stats = useMemo(() => {
    if (rankedDeals.length === 0) return { avgGRM: 0, bestDeal: null, worstDeal: null };
    const sum = rankedDeals.reduce((s, d) => s + d.grm, 0);
    return {
      avgGRM: sum / rankedDeals.length,
      bestDeal: rankedDeals[0],
      worstDeal: rankedDeals[rankedDeals.length - 1],
    };
  }, [rankedDeals]);

  if (deals.length === 0) {
    return (
      <div className={`rounded-xl border border-white/10 p-6 ${className}`} style={{ background: 'rgba(24,33,39,0.7)' }}>
        <p className="text-sm text-[#6B6870] text-center py-8">Add deals to compare GRM across properties.</p>
      </div>
    );
  }

  return (
    <div
      className={`rounded-xl border border-white/10 p-6 space-y-5 ${className}`}
      style={{ background: 'rgba(24,33,39,0.7)', backdropFilter: 'blur(16px)' }}
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-blue-400/10 flex items-center justify-center">
            <BarChart3 className="w-4 h-4 text-blue-400" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white">Deal Comparison</h3>
            <p className="text-[10px] text-[#6B6870] uppercase tracking-widest font-bold">Multi-Property GRM</p>
          </div>
        </div>
        <span className="text-[10px] text-[#6B6870] font-mono">
          {rankedDeals.length} deals · Mkt {marketGRM}x
        </span>
      </div>

      {/* ── Summary Row ── */}
      <div className="grid grid-cols-3 gap-3">
        <div className="rounded-lg bg-white/[0.03] border border-white/[0.06] p-3 text-center">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-1">Avg GRM</p>
          <p className="text-lg font-bold text-white tabular-nums">{stats.avgGRM.toFixed(1)}x</p>
        </div>
        <div className="rounded-lg bg-[#6E7480]/[0.04] border border-[#6E7480]/10 p-3 text-center">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-1 flex items-center justify-center gap-1">
            <Trophy className="w-3 h-3 text-[#6E7480]" /> Best
          </p>
          <p className="text-lg font-bold text-[#6E7480] tabular-nums">{stats.bestDeal?.grm.toFixed(1) ?? '—'}x</p>
        </div>
        <div className="rounded-lg bg-white/[0.03] border border-white/[0.06] p-3 text-center">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-1">Market</p>
          <p className="text-lg font-bold text-[#C0BEC2] tabular-nums">{marketGRM}x</p>
        </div>
      </div>

      {/* ── Deal Bars ── */}
      <div className="space-y-3">
        {rankedDeals.map((deal, idx) => {
          const signal = grmSignal(deal.grm, marketGRM);
          const isBest = idx === 0;
          return (
            <div key={deal.id} className="space-y-1.5">
              {/* Row header */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2 min-w-0">
                  {isBest && <Trophy className="w-3 h-3 text-[#6E7480] flex-shrink-0" />}
                  <span className="text-xs text-[#C0BEC2] font-medium truncate">{deal.address}</span>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  <span className="text-xs font-bold tabular-nums" style={{ color: grmColor(deal.grm, marketGRM) }}>
                    {deal.grm.toFixed(1)}x
                  </span>
                  <span className={`px-1.5 py-0.5 rounded border text-[8px] font-bold uppercase tracking-wider ${signal.className}`}>
                    {signal.label}
                  </span>
                </div>
              </div>

              {/* Bar */}
              <GRMBar grm={deal.grm} maxGRM={maxGRM} marketGRM={marketGRM} />

              {/* Details */}
              <div className="flex items-center gap-3 text-[9px] text-slate-600">
                <span>{fmtCompact(deal.propertyPrice)}</span>
                <span className="text-slate-700">÷</span>
                <span>{fmtCompact(deal.grossAnnualRent)}/yr</span>
                <span className="text-slate-700">·</span>
                <span className={deal.vsMarket < 0 ? 'text-[#6E7480]/70' : 'text-red-400/70'}>
                  {deal.vsMarket < 0 ? '' : '+'}{deal.vsMarket.toFixed(1)}x vs market
                </span>
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Scale footer ── */}
      <div className="flex justify-between text-[8px] text-slate-600 tabular-nums font-mono px-0.5 pt-1 border-t border-white/[0.04]">
        <span>0x</span>
        <span>Lower = Better</span>
        <span>{maxGRM}x</span>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo, useCallback, useEffect } from 'react';
import { Zap, DollarSign, Home, TrendingDown, TrendingUp, AlertTriangle, CheckCircle2, XCircle } from 'lucide-react';

/* ═══════════════════════════════════════════════════════════════
   GRM TRIAGE TERMINAL — A-Phase Quick Screen
   Two-input terminal for rapid deal screening via GRM.
   Formula: GRM = Property Price ÷ Gross Annual Rent
   Lower GRM = higher rent relative to price = better deal.
   ═══════════════════════════════════════════════════════════════ */

export interface GRMTriageValues {
  propertyPrice: number;
  grossMonthlyRent: number;
  grossAnnualRent: number;
  grm: number;
  signal: 'Pass' | 'Review' | 'Reject';
}

interface GRMTriageTerminalProps {
  defaultPropertyPrice?: number;
  defaultMonthlyRent?: number;
  marketGRM?: number;
  maxAcceptableGRM?: number;
  onValuesChange?: (values: GRMTriageValues) => void;
  className?: string;
}

/* ── GRM Signal Thresholds ── */
const SIGNAL_THRESHOLDS = {
  pass: 10,    // GRM < 10 = strong buy signal
  review: 13,  // 10-13 = needs further analysis
  // > 13 = reject / overpriced
} as const;

function getSignal(grm: number, maxGRM: number): 'Pass' | 'Review' | 'Reject' {
  if (grm <= 0) return 'Review';
  if (grm <= maxGRM * 0.75) return 'Pass';
  if (grm <= maxGRM) return 'Review';
  return 'Reject';
}

const SIGNAL_CONFIG = {
  Pass:   { color: '#14B8A6', icon: CheckCircle2, label: 'PASS — Strong Buy Signal',     bgClass: 'bg-[#6E7480]/10 border-[#6E7480]/20' },
  Review: { color: '#EAB308', icon: AlertTriangle, label: 'REVIEW — Needs Analysis',      bgClass: 'bg-amber-400/10 border-amber-400/20' },
  Reject: { color: '#F06543', icon: XCircle,       label: 'REJECT — Overpriced',          bgClass: 'bg-red-400/10 border-red-400/20' },
} as const;

/* ── Formatting ── */
const fmtUSD = (v: number): string =>
  `$${v.toLocaleString('en-US', { maximumFractionDigits: 0 })}`;

const fmtCompact = (v: number): string => {
  if (v >= 1_000_000) return `$${(v / 1_000_000).toFixed(2)}M`;
  if (v >= 1000) return `$${(v / 1000).toFixed(0)}k`;
  return fmtUSD(v);
};

/* ── Glass Input ── */
function TriageInput({
  label,
  sublabel,
  icon: Icon,
  value,
  onChange,
  step = 1000,
}: {
  label: string;
  sublabel: string;
  icon: React.ElementType;
  value: number;
  onChange: (v: number) => void;
  step?: number;
}) {
  return (
    <div className="group">
      <label className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-widest text-[#6B6870] mb-1">
        <Icon className="w-3 h-3" />
        {label}
      </label>
      <p className="text-[9px] text-slate-600 mb-1.5">{sublabel}</p>
      <div className="relative">
        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-sm text-[#6B6870] font-medium pointer-events-none">$</span>
        <input
          type="number"
          value={value}
          onChange={(e) => onChange(Number(e.target.value) || 0)}
          step={step}
          className="w-full rounded-lg border border-white/10 bg-white/[0.03] text-slate-200 text-sm
                     font-mono tabular-nums py-2.5 pl-7 pr-3 focus:outline-none focus:border-[#454955]/40
                     focus:ring-1 focus:ring-[#454955]/20 transition-all placeholder:text-slate-600"
        />
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════════════════════════ */

export function GRMTriageTerminal({
  defaultPropertyPrice = 279000,
  defaultMonthlyRent = 1950,
  marketGRM = 10.5,
  maxAcceptableGRM = 13,
  onValuesChange,
  className = '',
}: GRMTriageTerminalProps) {
  const [propertyPrice, setPropertyPrice] = useState(defaultPropertyPrice);
  const [monthlyRent, setMonthlyRent] = useState(defaultMonthlyRent);

  const computed = useMemo(() => {
    const grossAnnualRent = monthlyRent * 12;
    const grm = grossAnnualRent > 0
      ? Math.round((propertyPrice / grossAnnualRent) * 100) / 100
      : 0;
    const signal = getSignal(grm, maxAcceptableGRM);
    return { grossAnnualRent, grm, signal };
  }, [propertyPrice, monthlyRent, maxAcceptableGRM]);

  const signalConfig = SIGNAL_CONFIG[computed.signal];
  const SignalIcon = signalConfig.icon;

  // Notify parent
  useEffect(() => {
    if (onValuesChange) {
      onValuesChange({
        propertyPrice,
        grossMonthlyRent: monthlyRent,
        grossAnnualRent: computed.grossAnnualRent,
        grm: computed.grm,
        signal: computed.signal,
      });
    }
  }, [propertyPrice, monthlyRent, computed, onValuesChange]);

  /* ── GRM position relative to market ── */
  const vsMarket = computed.grm - marketGRM;
  const isBelowMarket = vsMarket < 0;

  /* ── Quick comparisons ── */
  const comparisons = [
    { label: 'Break-even Monthly', value: propertyPrice > 0 ? fmtUSD(Math.round(propertyPrice / (marketGRM * 12))) : '—', sublabel: `at ${marketGRM}x market GRM` },
    { label: 'Fair Value at Rent', value: fmtCompact(computed.grossAnnualRent * marketGRM), sublabel: `${monthlyRent > 0 ? fmtUSD(monthlyRent) : '—'}/mo × ${marketGRM}x` },
  ];

  return (
    <div
      className={`rounded-xl border border-white/10 p-6 space-y-5 ${className}`}
      style={{ background: 'rgba(24,33,39,0.7)', backdropFilter: 'blur(16px)' }}
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-amber-400/10 flex items-center justify-center">
            <Zap className="w-4 h-4 text-amber-400" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white">Quick Screen</h3>
            <p className="text-[10px] text-[#6B6870] uppercase tracking-widest font-bold">A-Phase Triage Terminal</p>
          </div>
        </div>
      </div>

      {/* ── 2 Input Fields ── */}
      <div className="grid grid-cols-2 gap-4">
        <TriageInput
          label="Property Price"
          sublabel="Purchase price or ARV"
          icon={Home}
          value={propertyPrice}
          onChange={setPropertyPrice}
          step={5000}
        />
        <TriageInput
          label="Monthly Rent"
          sublabel="Gross monthly rent"
          icon={DollarSign}
          value={monthlyRent}
          onChange={setMonthlyRent}
          step={50}
        />
      </div>

      {/* ── Signal Output ── */}
      <div
        className={`rounded-xl border p-4 flex items-center justify-between transition-all duration-500 ${signalConfig.bgClass}`}
      >
        <div className="flex items-center gap-3">
          <SignalIcon className="w-6 h-6 flex-shrink-0" style={{ color: signalConfig.color }} />
          <div>
            <p className="text-xs font-bold" style={{ color: signalConfig.color }}>{signalConfig.label}</p>
            <p className="text-[10px] text-[#6B6870] mt-0.5">
              GRM {computed.grm.toFixed(1)}x · {isBelowMarket ? 'below' : 'above'} market ({marketGRM}x)
            </p>
          </div>
        </div>
        <span className="text-3xl font-bold tabular-nums tracking-tighter" style={{ color: signalConfig.color }}>
          {computed.grm.toFixed(1)}x
        </span>
      </div>

      {/* ── vs Market Bar ── */}
      <div className="space-y-1.5">
        <div className="flex justify-between text-[9px] text-[#6B6870] font-bold uppercase tracking-wider">
          <span>vs Market ({marketGRM}x)</span>
          <span className={isBelowMarket ? 'text-[#6E7480]' : 'text-red-400'}>
            {isBelowMarket ? '' : '+'}{vsMarket.toFixed(1)}x
          </span>
        </div>
        <div className="relative h-3 rounded-full overflow-hidden bg-white/[0.04]">
          {/* Market position */}
          <div
            className="absolute top-0 bottom-0 w-px border-l border-dashed border-white/30"
            style={{ left: `${Math.min(marketGRM / 20 * 100, 100)}%` }}
          />
          {/* Current GRM fill */}
          <div
            className="absolute inset-y-0 left-0 rounded-full transition-all duration-700 ease-out"
            style={{
              width: `${Math.min(computed.grm / 20 * 100, 100)}%`,
              backgroundColor: `${signalConfig.color}60`,
            }}
          />
          {/* Needle */}
          <div
            className="absolute top-0 bottom-0 w-0.5 bg-white rounded transition-all duration-700"
            style={{ left: `${Math.min(computed.grm / 20 * 100, 100)}%` }}
          />
        </div>
        <div className="flex justify-between text-[8px] text-slate-600 tabular-nums font-mono">
          <span>0x</span><span>5x</span><span>10x</span><span>15x</span><span>20x</span>
        </div>
      </div>

      {/* ── Quick Comparisons ── */}
      <div className="grid grid-cols-2 gap-3">
        {comparisons.map((c) => (
          <div key={c.label} className="rounded-lg bg-white/[0.03] border border-white/[0.06] p-3">
            <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-1">{c.label}</p>
            <p className="text-sm font-bold text-white tabular-nums">{c.value}</p>
            <p className="text-[9px] text-slate-600 mt-0.5">{c.sublabel}</p>
          </div>
        ))}
      </div>

      {/* ── Formula reference ── */}
      <div className="px-3 py-2 rounded-lg bg-white/[0.02] border border-white/[0.04]">
        <p className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Formula</p>
        <p className="text-[11px] text-[#9E9DA0] font-mono">
          GRM = {fmtCompact(propertyPrice)} ÷ {fmtCompact(computed.grossAnnualRent)}/yr = {computed.grm.toFixed(1)}x
        </p>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo, useEffect, useCallback } from 'react';
