   ═══════════════════════════════════════════════════════════════ */

function localBuildIRRCashFlows(
  totalCashInvested: number,
  annualCashFlow: number,
  holdYears: number,
  purchasePrice: number,
  annualAppreciationPercent: number,
  loanAmount: number,
  loanInterestRate: number,
  loanTermYears: number,
  sellingCostsPercent = 8
): number[] {
  if (holdYears <= 0 || totalCashInvested <= 0) return [];
  const flows: number[] = [-totalCashInvested];
  const futureValue = purchasePrice * Math.pow(1 + annualAppreciationPercent / 100, holdYears);
  let remainingBalance = loanAmount;
  const monthlyRate = (loanInterestRate / 100) / 12;
  const totalPayments = loanTermYears * 12;

  if (monthlyRate > 0 && totalPayments > 0 && loanAmount > 0) {
    const monthlyPayment = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, totalPayments)) /
      (Math.pow(1 + monthlyRate, totalPayments) - 1);
    const paymentsMade = holdYears * 12;
    remainingBalance = loanAmount * Math.pow(1 + monthlyRate, paymentsMade) -
      monthlyPayment * ((Math.pow(1 + monthlyRate, paymentsMade) - 1) / monthlyRate);
    remainingBalance = Math.max(0, remainingBalance);
  }

  const sellingCosts = futureValue * (sellingCostsPercent / 100);
  const netSaleProceeds = futureValue - remainingBalance - sellingCosts;

  for (let y = 1; y <= holdYears; y++) {
    if (y === holdYears) {
      flows.push(annualCashFlow + netSaleProceeds);
    } else {
      flows.push(annualCashFlow);
    }
  }
  return flows;
}

function localComputeIRR(cashFlows: number[], maxIterations = 100, tolerance = 1e-7): number | null {
  if (cashFlows.length < 2) return null;
  let rate = 0.10;

  for (let i = 0; i < maxIterations; i++) {
    let npv = 0;
    let dNpv = 0;
    for (let t = 0; t < cashFlows.length; t++) {
      const pv = cashFlows[t] / Math.pow(1 + rate, t);
      npv += pv;
      if (t > 0) {
        dNpv -= (t * cashFlows[t]) / Math.pow(1 + rate, t + 1);
      }
    }
    if (Math.abs(dNpv) < 1e-12) break;
    const newRate = rate - npv / dNpv;
    if (Math.abs(newRate - rate) < tolerance) {
      return Math.round(newRate * 10000) / 10000;
    }
    rate = newRate;
    if (rate < -0.99 || rate > 10) break;
  }

  let low = -0.99;
  let high = 10.0;
  const getNpv = (r: number) => {
    let sum = 0;
    for (let t = 0; t < cashFlows.length; t++) {
      sum += cashFlows[t] / Math.pow(1 + r, t);
    }
    return sum;
  };

  let bracketFound = false;
  let prevVal = getNpv(low);
  const steps = 100;
  const stepSize = (high - low) / steps;

  for (let step = 1; step <= steps; step++) {
    const r = low + step * stepSize;
    const val = getNpv(r);
    if (prevVal * val <= 0) {
      low = r - stepSize;
      high = r;
      bracketFound = true;
      break;
    }
    prevVal = val;
  }

  if (!bracketFound) {
    low = -0.99;
    high = 100.0;
    const widerSteps = 200;
    const widerStepSize = (high - low) / widerSteps;
    prevVal = getNpv(low);
    for (let step = 1; step <= widerSteps; step++) {
      const r = low + step * widerStepSize;
      const val = getNpv(r);
      if (prevVal * val <= 0) {
        low = r - widerStepSize;
        high = r;
        bracketFound = true;
        break;
      }
      prevVal = val;
    }
  }

  if (bracketFound) {
    for (let j = 0; j < 100; j++) {
      const mid = (low + high) / 2;
      const npvMid = getNpv(mid);
      if (Math.abs(npvMid) < tolerance || (high - low) < tolerance) {
        return Math.round(mid * 10000) / 10000;
      }
      if (getNpv(low) * npvMid < 0) {
        high = mid;
      } else {
        low = mid;
      }
    }
  }
  return null;
}

export function IRRExitAssumptionsTerminal({
  defaults = {},
  onValuesChange,
  className = '',
}: IRRExitAssumptionsTerminalProps) {
  const [cashInvested, setCashInvested] = useState(defaults.totalCashInvested ?? 60000);
  const [annualCF, setAnnualCF] = useState(defaults.annualCashFlow ?? 5052);
  const [holdYears, setHoldYears] = useState(defaults.holdYears ?? 5);
  const [purchasePrice, setPurchasePrice] = useState(defaults.purchasePrice ?? 279000);
  const [appreciation, setAppreciation] = useState(defaults.appreciationPercent ?? 3);
  const [loanAmount, setLoanAmount] = useState(defaults.loanAmount ?? 223200);
  const [loanRate, setLoanRate] = useState(defaults.loanRate ?? 6.5);
  const [loanTerm, setLoanTerm] = useState(defaults.loanTermYears ?? 30);
  const [sellingCosts, setSellingCosts] = useState(defaults.sellingCostsPercent ?? 8);

  /* ── Compute IRR ── */
  const computed = useMemo(() => {
    const cashFlows = localBuildIRRCashFlows(
      cashInvested, annualCF, holdYears, purchasePrice,
      appreciation, loanAmount, loanRate, loanTerm, sellingCosts
    );
    const irr = localComputeIRR(cashFlows);
    return { cashFlows, irr };
  }, [cashInvested, annualCF, holdYears, purchasePrice, appreciation, loanAmount, loanRate, loanTerm, sellingCosts]);

  /* ── Exit value calculations ── */
  const exitMetrics = useMemo(() => {
    const futureValue = purchasePrice * Math.pow(1 + appreciation / 100, holdYears);
    const totalCashFlows = annualCF * holdYears;
    const exitProceeds = computed.cashFlows.length > 0 ? computed.cashFlows[computed.cashFlows.length - 1] : 0;
    const totalReturn = totalCashFlows + exitProceeds - cashInvested;
    const equityMultiple = cashInvested > 0 ? (totalCashFlows + exitProceeds) / cashInvested : 0;
    return { futureValue, totalCashFlows, exitProceeds, totalReturn, equityMultiple };
  }, [computed.cashFlows, cashInvested, annualCF, holdYears, purchasePrice, appreciation]);

  const stableOnChange = useCallback((values: IRRAssumptions) => {
    onValuesChange?.(values);
  }, [onValuesChange]);

  useEffect(() => {
    stableOnChange({
      totalCashInvested: cashInvested,
      annualCashFlow: annualCF,
      holdYears,
      purchasePrice,
      appreciationPercent: appreciation,
      loanAmount,
      loanRate,
      loanTermYears: loanTerm,
      sellingCostsPercent: sellingCosts,
      irr: computed.irr,
      cashFlows: computed.cashFlows,
    });
  }, [cashInvested, annualCF, holdYears, purchasePrice, appreciation, loanAmount, loanRate, loanTerm, sellingCosts, computed, stableOnChange]);

  const irrColor = computed.irr === null ? '#64748b' : computed.irr >= 0.15 ? '#3f7d20' : computed.irr >= 0.08 ? '#F59E0B' : '#F06543';
  const irrLabel = computed.irr === null ? 'N/A' : `${(computed.irr * 100).toFixed(1)}%`;
  const irrSignal = computed.irr === null ? 'Cannot Converge' : computed.irr >= 0.15 ? 'Strong Return' : computed.irr >= 0.08 ? 'Moderate' : 'Weak';

  const fmtUSD = (v: number) => `$${Math.abs(v).toLocaleString('en-US', { maximumFractionDigits: 0 })}`;

  return (
    <div
      className={`rounded-xl border border-white/10 p-6 space-y-5 ${className}`}
      style={{ background: 'rgba(24,33,39,0.7)', backdropFilter: 'blur(16px)' }}
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-pw-ocean/10 flex items-center justify-center">
            <Sparkles className="w-4 h-4 text-pw-ocean" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white">Exit Assumptions</h3>
            <p className="text-[10px] text-[#6B6870] uppercase tracking-widest font-bold">IRR Analysis Terminal</p>
          </div>
        </div>
      </div>

      {/* ── Hold Period ── */}
      <HoldPeriodSelector value={holdYears} onChange={setHoldYears} />

      {/* ── Investment Inputs ── */}
      <div className="grid grid-cols-2 gap-3">
        <GlassInput label="Cash Invested" sublabel="Total equity at t0" icon={DollarSign} value={cashInvested} onChange={setCashInvested} step={5000} />
        <GlassInput label="Annual Cash Flow" sublabel="Net annual from operations" icon={TrendingUp} value={annualCF} onChange={setAnnualCF} step={100} />
      </div>

      {/* ── Property + Exit ── */}
      <div className="grid grid-cols-2 gap-3">
        <GlassInput label="Purchase Price" icon={Building2} value={purchasePrice} onChange={setPurchasePrice} step={5000} />
        <GlassInput label="Appreciation" sublabel="Annual %" icon={Percent} value={appreciation} onChange={setAppreciation} suffix="%" step={0.5} />
      </div>

      {/* ── Loan Terms (collapsible feel) ── */}
      <div className="rounded-lg bg-white/[0.02] border border-white/[0.06] p-3 space-y-3">
        <p className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870]">Financing</p>
        <div className="grid grid-cols-3 gap-2">
          <GlassInput label="Loan" icon={DollarSign} value={loanAmount} onChange={setLoanAmount} step={5000} />
          <GlassInput label="Rate" icon={Percent} value={loanRate} onChange={setLoanRate} suffix="%" step={0.25} />
          <GlassInput label="Term" icon={Calendar} value={loanTerm} onChange={setLoanTerm} suffix="yr" step={1} min={1} />
        </div>
        <GlassInput label="Selling Costs" sublabel="Commissions + closing" icon={Percent} value={sellingCosts} onChange={setSellingCosts} suffix="%" step={0.5} />
      </div>

      {/* ── IRR Result ── */}
      <div className="rounded-xl border p-4 flex items-center justify-between transition-all duration-500"
        style={{ borderColor: `${irrColor}30`, background: `${irrColor}08` }}>
        <div className="flex items-center gap-3">
          <Calculator className="w-6 h-6 flex-shrink-0" style={{ color: irrColor }} />
          <div>
            <p className="text-xs font-bold" style={{ color: irrColor }}>{irrSignal}</p>
            <p className="text-[10px] text-[#6B6870] mt-0.5">{holdYears}-year hold scenario</p>
          </div>
        </div>
        <div className="text-right">
          <span className="text-4xl font-bold tabular-nums tracking-tighter" style={{ color: irrColor }}>
            {irrLabel}
          </span>
          <p className="text-[9px] text-slate-600 mt-0.5">IRR (annualized)</p>
        </div>
      </div>

      {/* ── Exit Metrics Row ── */}
      <div className="grid grid-cols-3 gap-2">
        {[
          { label: 'Future Value', value: fmtUSD(exitMetrics.futureValue), color: '#64748b' },
          { label: 'Total Return', value: `${exitMetrics.totalReturn >= 0 ? '+' : '-'}${fmtUSD(exitMetrics.totalReturn)}`, color: exitMetrics.totalReturn >= 0 ? '#3f7d20' : '#F06543' },
          { label: 'Equity Multiple', value: `${exitMetrics.equityMultiple.toFixed(2)}x`, color: '#454955' },
        ].map((m) => (
          <div key={m.label} className="rounded-lg bg-white/[0.03] border border-white/[0.06] p-3 text-center">
            <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">{m.label}</p>
            <p className="text-sm font-bold tabular-nums" style={{ color: m.color }}>{m.value}</p>
          </div>
        ))}
      </div>

      {/* ── Cash Flow Timeline ── */}
      <CashFlowTimeline flows={computed.cashFlows} />

      {/* ── Formula ── */}
      <div className="px-3 py-2 rounded-lg bg-white/[0.02] border border-white/[0.04]">
        <p className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Newton-Raphson Solver</p>
        <p className="text-[11px] text-[#9E9DA0] font-mono">
          IRR where NPV = Σ CF(t) / (1+r)^t = 0 → {irrLabel}
        </p>
      </div>
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import { TrendingUp, TrendingDown, Target, Layers, ArrowRight, Sparkles, Award, AlertTriangle } from 'lucide-react';
// Removed helper imports as they are engine internals

/* ═══════════════════════════════════════════════════════════════
   IRR SCENARIO COMPARISON CARD
   Computes IRR across multiple hold-period scenarios (3/5/7/10yr)
   with Base / Optimistic / Pessimistic variants.
   Displays ranked horizontal bars + signal badges + best scenario.
   ═══════════════════════════════════════════════════════════════ */

interface ScenarioInputs {
  totalCashInvested: number;
  annualCashFlow: number;
  purchasePrice: number;
  loanAmount: number;
  loanRate: number;
  loanTermYears: number;
  sellingCostsPercent?: number;
}

interface ScenarioVariant {
  label: string;
  appreciationPercent: number;
  cashFlowMultiplier: number;
  color: string;
}

interface IRRScenarioComparisonCardProps {
  inputs: ScenarioInputs;
  holdPeriods?: number[];
  hurdleRate?: number;
  className?: string;
}

const DEFAULT_HOLDS = [3, 5, 7, 10];

const VARIANTS: ScenarioVariant[] = [
  { label: 'Bear', appreciationPercent: 1.5, cashFlowMultiplier: 0.8, color: '#F06543' },
  { label: 'Base', appreciationPercent: 3.0, cashFlowMultiplier: 1.0, color: '#a1a1aa' },
  { label: 'Bull', appreciationPercent: 5.0, cashFlowMultiplier: 1.2, color: '#454955' },
];

/* ── Compute all scenarios ── */
interface ScenarioResult {
  holdYears: number;
  variant: string;
  irr: number | null;
  irrPct: string;
  color: string;
  cashFlows: number[];
  equityMultiple: number;
}

function localBuildIRRCashFlows(
  totalCashInvested: number,
  annualCashFlow: number,
  holdYears: number,
  purchasePrice: number,
  annualAppreciationPercent: number,
  loanAmount: number,
  loanInterestRate: number,
  loanTermYears: number,
  sellingCostsPercent = 8
): number[] {
  if (holdYears <= 0 || totalCashInvested <= 0) return [];
  const flows: number[] = [-totalCashInvested];
  const futureValue = purchasePrice * Math.pow(1 + annualAppreciationPercent / 100, holdYears);
  let remainingBalance = loanAmount;
  const monthlyRate = (loanInterestRate / 100) / 12;
  const totalPayments = loanTermYears * 12;

  if (monthlyRate > 0 && totalPayments > 0 && loanAmount > 0) {
    const monthlyPayment = loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, totalPayments)) /
      (Math.pow(1 + monthlyRate, totalPayments) - 1);
    const paymentsMade = holdYears * 12;
    remainingBalance = loanAmount * Math.pow(1 + monthlyRate, paymentsMade) -
      monthlyPayment * ((Math.pow(1 + monthlyRate, paymentsMade) - 1) / monthlyRate);
    remainingBalance = Math.max(0, remainingBalance);
  }

  const sellingCosts = futureValue * (sellingCostsPercent / 100);
  const netSaleProceeds = futureValue - remainingBalance - sellingCosts;

  for (let y = 1; y <= holdYears; y++) {
    if (y === holdYears) {
      flows.push(annualCashFlow + netSaleProceeds);
    } else {
      flows.push(annualCashFlow);
    }
  }
  return flows;
}

function localComputeIRR(cashFlows: number[], maxIterations = 100, tolerance = 1e-7): number | null {
  if (cashFlows.length < 2) return null;
  let rate = 0.10;

  for (let i = 0; i < maxIterations; i++) {
    let npv = 0;
    let dNpv = 0;
    for (let t = 0; t < cashFlows.length; t++) {
      const pv = cashFlows[t] / Math.pow(1 + rate, t);
      npv += pv;
      if (t > 0) {
        dNpv -= (t * cashFlows[t]) / Math.pow(1 + rate, t + 1);
      }
    }
    if (Math.abs(dNpv) < 1e-12) break;
    const newRate = rate - npv / dNpv;
    if (Math.abs(newRate - rate) < tolerance) {
      return Math.round(newRate * 10000) / 10000;
    }
    rate = newRate;
    if (rate < -0.99 || rate > 10) break;
  }

  let low = -0.99;
  let high = 10.0;
  const getNpv = (r: number) => {
    let sum = 0;
    for (let t = 0; t < cashFlows.length; t++) {
      sum += cashFlows[t] / Math.pow(1 + r, t);
    }
    return sum;
  };

  let bracketFound = false;
  let prevVal = getNpv(low);
  const steps = 100;
  const stepSize = (high - low) / steps;

  for (let step = 1; step <= steps; step++) {
    const r = low + step * stepSize;
    const val = getNpv(r);
    if (prevVal * val <= 0) {
      low = r - stepSize;
      high = r;
      bracketFound = true;
      break;
    }
    prevVal = val;
  }

  if (!bracketFound) {
    low = -0.99;
    high = 100.0;
    const widerSteps = 200;
    const widerStepSize = (high - low) / widerSteps;
    prevVal = getNpv(low);
    for (let step = 1; step <= widerSteps; step++) {
      const r = low + step * widerStepSize;
      const val = getNpv(r);
      if (prevVal * val <= 0) {
        low = r - widerStepSize;
        high = r;
        bracketFound = true;
        break;
      }
      prevVal = val;
    }
  }

  if (bracketFound) {
    for (let j = 0; j < 100; j++) {
      const mid = (low + high) / 2;
      const npvMid = getNpv(mid);
      if (Math.abs(npvMid) < tolerance || (high - low) < tolerance) {
        return Math.round(mid * 10000) / 10000;
      }
      if (getNpv(low) * npvMid < 0) {
        high = mid;
      } else {
        low = mid;
      }
    }
  }
  return null;
}

function computeScenarios(inputs: ScenarioInputs, holds: number[]): ScenarioResult[] {
  const results: ScenarioResult[] = [];

  for (const holdYears of holds) {
    for (const variant of VARIANTS) {
      const adjustedCF = inputs.annualCashFlow * variant.cashFlowMultiplier;
      const cashFlows = localBuildIRRCashFlows(
        inputs.totalCashInvested,
        adjustedCF,
        holdYears,
        inputs.purchasePrice,
        variant.appreciationPercent,
        inputs.loanAmount,
        inputs.loanRate,
        inputs.loanTermYears,
        inputs.sellingCostsPercent ?? 8
      );
      const irr = localComputeIRR(cashFlows);
      const totalInflows = cashFlows.slice(1).reduce((s, v) => s + v, 0);
      const equityMultiple = inputs.totalCashInvested > 0 ? totalInflows / inputs.totalCashInvested : 0;

      results.push({
        holdYears,
        variant: variant.label,
        irr,
        irrPct: irr !== null ? `${(irr * 100).toFixed(1)}%` : 'N/A',
        color: variant.color,
        cashFlows,
        equityMultiple,
      });
    }
  }

  return results;
}

/* ── Signal Badge ── */
function SignalBadge({ irr, hurdleRate }: { irr: number | null; hurdleRate: number }) {
  if (irr === null) return <span className="text-[8px] font-bold text-slate-600 uppercase">N/A</span>;

  const signals = [
    { min: hurdleRate + 0.05, label: 'Strong', color: '#3f7d20' },
    { min: hurdleRate, label: 'Pass', color: '#454955' },
    { min: 0, label: 'Weak', color: '#F59E0B' },
    { min: -Infinity, label: 'Loss', color: '#F06543' },
  ];

  const signal = signals.find((s) => irr >= s.min) ?? signals[signals.length - 1];

  return (
    <span
      className="px-1.5 py-0.5 rounded text-[8px] font-bold uppercase tracking-wider"
      style={{ color: signal.color, backgroundColor: `${signal.color}15`, border: `1px solid ${signal.color}25` }}
    >
      {signal.label}
    </span>
  );
}

/* ── IRR Bar ── */
function IRRBar({ irr, maxIrr, color }: { irr: number | null; maxIrr: number; color: string }) {
  const widthPct = irr !== null && maxIrr > 0 ? Math.min(Math.max((irr / maxIrr) * 100, 0), 100) : 0;
  return (
    <div className="h-2.5 rounded-full overflow-hidden bg-white/[0.04] flex-1">
      <div
        className="h-full rounded-full transition-all duration-500"
        style={{ width: `${widthPct}%`, backgroundColor: color }}
      />
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════════════════════════ */

export function IRRScenarioComparisonCard({
  inputs,
  holdPeriods = DEFAULT_HOLDS,
  hurdleRate = 0.12,
  className = '',
}: IRRScenarioComparisonCardProps) {
  const scenarios = useMemo(() => computeScenarios(inputs, holdPeriods), [inputs, holdPeriods]);

  const maxIrr = useMemo(() => {
    const irrs = scenarios.map((s) => s.irr).filter((v): v is number => v !== null);
    return irrs.length > 0 ? Math.max(...irrs) : 0.3;
  }, [scenarios]);

  /* ── Best scenario ── */
  const bestScenario = useMemo(() => {
    const valid = scenarios.filter((s) => s.irr !== null);
    if (valid.length === 0) return null;
    return valid.reduce((best, s) => (s.irr! > best.irr! ? s : best));
  }, [scenarios]);

  /* ── Group by hold period ── */
  const grouped = useMemo(() => {
    const map = new Map<number, ScenarioResult[]>();
    for (const s of scenarios) {
      const existing = map.get(s.holdYears) ?? [];
      existing.push(s);
      map.set(s.holdYears, existing);
    }
    return Array.from(map.entries()).sort(([a], [b]) => a - b);
  }, [scenarios]);

  /* ── Hurdle pass rate ── */
  const passRate = useMemo(() => {
    const valid = scenarios.filter((s) => s.irr !== null);
    const passing = valid.filter((s) => s.irr! >= hurdleRate);
    return valid.length > 0 ? (passing.length / valid.length) * 100 : 0;
  }, [scenarios, hurdleRate]);

  return (
    <div
      className={`rounded-xl border border-white/10 p-6 space-y-5 ${className}`}
      style={{ background: 'rgba(24,33,39,0.7)', backdropFilter: 'blur(16px)' }}
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-[#454955]/10 flex items-center justify-center">
            <Layers className="w-4 h-4 text-[#454955]" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white">Scenario Comparison</h3>
            <p className="text-[10px] text-[#6B6870] uppercase tracking-widest font-bold">IRR Intelligence</p>
          </div>
        </div>
        <div className="text-right">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870]">Hurdle Rate</p>
          <p className="text-sm font-bold text-[#6E7480] tabular-nums">{(hurdleRate * 100).toFixed(0)}%</p>
        </div>
      </div>

      {/* ── Best Scenario Highlight ── */}
      {bestScenario && (
        <div className="rounded-lg border border-[#454955]/20 bg-[#454955]/[0.06] p-3 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Award className="w-4 h-4 text-[#454955]" />
            <div>
              <p className="text-xs font-bold text-[#454955]">Best Scenario</p>
              <p className="text-[10px] text-[#6B6870]">{bestScenario.holdYears}-year {bestScenario.variant}</p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-2xl font-bold tabular-nums text-[#454955]">{bestScenario.irrPct}</span>
            <span className="text-[10px] text-[#6B6870]">{bestScenario.equityMultiple.toFixed(1)}x</span>
          </div>
        </div>
      )}

      {/* ── Scenario Groups ── */}
      <div className="space-y-4">
        {grouped.map(([holdYears, variants]) => (
          <div key={holdYears} className="space-y-1.5">
            <div className="flex items-center justify-between">
              <span className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870] flex items-center gap-1">
                <Calendar className="w-3 h-3" />
                {holdYears}-Year Hold
              </span>
            </div>

            {variants.map((s) => (
              <div key={`${s.holdYears}-${s.variant}`} className="flex items-center gap-2">
                <span className="w-10 text-[9px] font-bold uppercase tracking-wider text-right" style={{ color: s.color }}>
                  {s.variant}
                </span>
                <IRRBar irr={s.irr} maxIrr={maxIrr} color={s.color} />
                <span className="w-14 text-xs font-bold tabular-nums text-right" style={{ color: s.irr !== null ? s.color : '#64748b' }}>
                  {s.irrPct}
                </span>
                <SignalBadge irr={s.irr} hurdleRate={hurdleRate} />
              </div>
            ))}
          </div>
        ))}
      </div>

      {/* ── Summary Stats ── */}
      <div className="grid grid-cols-3 gap-2 pt-2 border-t border-white/[0.06]">
        <div className="text-center">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Scenarios</p>
          <p className="text-sm font-bold text-white tabular-nums">{scenarios.length}</p>
        </div>
        <div className="text-center">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Pass Rate</p>
          <p className="text-sm font-bold tabular-nums" style={{ color: passRate >= 50 ? '#14B8A6' : '#F59E0B' }}>
            {passRate.toFixed(0)}%
          </p>
        </div>
        <div className="text-center">
          <p className="text-[9px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Best IRR</p>
          <p className="text-sm font-bold text-[#454955] tabular-nums">{bestScenario?.irrPct ?? 'N/A'}</p>
        </div>
      </div>
    </div>
  );
}

/* ── Calendar icon used in grouped headers ── */
function Calendar(props: React.SVGProps<SVGSVGElement> & { className?: string }) {
  return (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor"
      strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" {...props}>
      <rect x="3" y="4" width="18" height="18" rx="2" ry="2" /><line x1="16" y1="2" x2="16" y2="6" />
      <line x1="8" y1="2" x2="8" y2="6" /><line x1="3" y1="10" x2="21" y2="10" />
    </svg>
  );
}

'use client';

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import {
  Home, Calendar, Users, AlertTriangle, CheckCircle2, XCircle,
  Plus, Trash2, BarChart3, Clock, Building2,
} from 'lucide-react';
import { deriveAllMetrics } from '@/lib/metrics/reiMetrics';

/* ═══════════════════════════════════════════════════════════════
   OCCUPANCY COLLECTION TERMINAL
   Collects tenant/lease data and vacant-day inputs per unit,
   computes occupancy rate = (Days Occupied ÷ Total Days) × 100
   Supports multi-unit tracking with individual vacancy entries.

   Stitch screens:
     40fd1015 - Tenants & Leases: Occupancy Collection (Mobile)
     5d26659a - Tenants & Leases: Occupancy Collection (Desktop)
     fedb8e0a - Tenants & Leases: Occupancy Collection (Mobile) v2
     529657b8 - Tenants & Leases: Occupancy Collection (Desktop) v2
   ═══════════════════════════════════════════════════════════════ */

export interface UnitOccupancy {
  id: string;
  unitLabel: string;
  tenantName: string;
  leaseStart: string;
  leaseEnd: string;
  vacantDays: number;
  status: 'occupied' | 'vacant' | 'notice';
}

export interface OccupancyValues {
  units: UnitOccupancy[];
  totalDays: number;
  occupancyRate: number;
  totalVacantDays: number;
  totalOccupiedDays: number;
  occupiedUnitCount: number;
  totalUnitCount: number;
}

interface OccupancyCollectionTerminalProps {
  defaults?: Partial<{ units: UnitOccupancy[]; totalDays: number }>;
  onValuesChange?: (values: OccupancyValues) => void;
  className?: string;
}

/* ── Seed data matching the spec: 92% / 29 vacant days / 365 total ── */
const SEED_UNITS: UnitOccupancy[] = [
  { id: '1', unitLabel: 'Unit 1A', tenantName: 'J. Rivera', leaseStart: '2025-06-01', leaseEnd: '2026-05-31', vacantDays: 0, status: 'occupied' },
  { id: '2', unitLabel: 'Unit 1B', tenantName: 'M. Chen', leaseStart: '2025-08-01', leaseEnd: '2026-07-31', vacantDays: 0, status: 'occupied' },
  { id: '3', unitLabel: 'Unit 2A', tenantName: '', leaseStart: '', leaseEnd: '', vacantDays: 29, status: 'vacant' },
  { id: '4', unitLabel: 'Unit 2B', tenantName: 'S. Okafor', leaseStart: '2025-04-15', leaseEnd: '2026-04-14', vacantDays: 0, status: 'occupied' },
];

/* ── Status config ── */
const STATUS_CFG = {
  occupied: { icon: CheckCircle2, color: '#14B8A6', bg: 'rgba(20,184,166,0.08)', label: 'Occupied' },
  vacant:   { icon: XCircle,      color: '#F06543', bg: 'rgba(239,68,68,0.08)',  label: 'Vacant'   },
  notice:   { icon: AlertTriangle, color: '#F59E0B', bg: 'rgba(245,158,11,0.08)', label: 'Notice'   },
} as const;

/* ═══════════════════════════════════════════════════════════════
   UNIT ROW
   ═══════════════════════════════════════════════════════════════ */

function UnitRow({
  unit,
  onChange,
  onRemove,
}: {
  unit: UnitOccupancy;
  onChange: (updated: UnitOccupancy) => void;
  onRemove: () => void;
}) {
  const cfg = STATUS_CFG[unit.status];
  const StatusIcon = cfg.icon;

  return (
    <div
      className="rounded-lg border p-3 space-y-2 transition-all"
      style={{ borderColor: `${cfg.color}20`, background: cfg.bg }}
    >
      {/* Top row: status + unit + remove */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <StatusIcon className="w-3.5 h-3.5 flex-shrink-0" style={{ color: cfg.color }} />
          <input
            type="text"
            value={unit.unitLabel}
            onChange={(e) => onChange({ ...unit, unitLabel: e.target.value })}
            className="bg-transparent text-xs font-bold text-white w-20 focus:outline-none border-b border-transparent focus:border-white/20"
            placeholder="Unit #"
          />
          <select
            value={unit.status}
            onChange={(e) => onChange({ ...unit, status: e.target.value as UnitOccupancy['status'] })}
            className="bg-transparent text-[9px] font-bold uppercase tracking-wider rounded px-1 py-0.5 border focus:outline-none cursor-pointer"
            style={{ color: cfg.color, borderColor: `${cfg.color}40` }}
          >
            <option value="occupied">Occupied</option>
            <option value="vacant">Vacant</option>
            <option value="notice">Notice</option>
          </select>
        </div>
        <button
          onClick={onRemove}
          className="text-slate-600 hover:text-red-400 transition-colors p-0.5"
          title="Remove unit"
        >
          <Trash2 className="w-3 h-3" />
        </button>
      </div>

      {/* Tenant + Lease */}
      <div className="grid grid-cols-3 gap-2">
        <div>
          <label className="text-[8px] font-bold uppercase tracking-widest text-slate-600">Tenant</label>
          <input
            type="text"
            value={unit.tenantName}
            onChange={(e) => onChange({ ...unit, tenantName: e.target.value })}
            placeholder="Vacant"
            className="w-full bg-white/[0.03] border border-white/[0.06] rounded px-2 py-1 text-[11px] text-[#C0BEC2]
                       focus:outline-none focus:border-[#454955]/30 transition-all"
          />
        </div>
        <div>
          <label className="text-[8px] font-bold uppercase tracking-widest text-slate-600 flex items-center gap-0.5">
            <Calendar className="w-2.5 h-2.5" /> Lease Start
          </label>
          <input
            type="date"
            value={unit.leaseStart}
            onChange={(e) => onChange({ ...unit, leaseStart: e.target.value })}
            className="w-full bg-white/[0.03] border border-white/[0.06] rounded px-2 py-1 text-[11px] text-[#C0BEC2]
                       focus:outline-none focus:border-[#454955]/30 transition-all"
          />
        </div>
        <div>
          <label className="text-[8px] font-bold uppercase tracking-widest text-slate-600 flex items-center gap-0.5">
            <Calendar className="w-2.5 h-2.5" /> Lease End
          </label>
          <input
            type="date"
            value={unit.leaseEnd}
            onChange={(e) => onChange({ ...unit, leaseEnd: e.target.value })}
            className="w-full bg-white/[0.03] border border-white/[0.06] rounded px-2 py-1 text-[11px] text-[#C0BEC2]
                       focus:outline-none focus:border-[#454955]/30 transition-all"
          />
        </div>
      </div>

      {/* Vacant Days */}
      <div className="flex items-center gap-2">
        <label className="text-[8px] font-bold uppercase tracking-widest text-slate-600 flex items-center gap-0.5 whitespace-nowrap">
          <Clock className="w-2.5 h-2.5" /> Vacant Days (T12)
        </label>
        <input
          type="number"
          value={unit.vacantDays}
          onChange={(e) => onChange({ ...unit, vacantDays: Math.max(0, Number(e.target.value) || 0) })}
          min={0}
          max={365}
          className="w-16 bg-white/[0.03] border border-white/[0.06] rounded px-2 py-1 text-[11px] text-[#C0BEC2]
                     font-mono tabular-nums focus:outline-none focus:border-[#454955]/30 transition-all"
        />
        {unit.vacantDays > 0 && (
          <span className="text-[9px] font-bold tabular-nums" style={{ color: unit.vacantDays > 30 ? '#F06543' : '#F59E0B' }}>
            {((unit.vacantDays / 365) * 100).toFixed(1)}% vacancy
          </span>
        )}
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════════════════
   MAIN COMPONENT
   ═══════════════════════════════════════════════════════════════ */

export function OccupancyCollectionTerminal({
  defaults = {},
  onValuesChange,
  className = '',
}: OccupancyCollectionTerminalProps) {
  const [units, setUnits] = useState<UnitOccupancy[]>(defaults.units ?? SEED_UNITS);
  const [totalDays, setTotalDays] = useState(defaults.totalDays ?? 365);

  /* ── Computations ── */
  const computed = useMemo(() => {
    const totalVacantDays = units.reduce((sum, u) => sum + u.vacantDays, 0);
    const totalPossibleDays = totalDays * units.length;
    const vacancyRatePercent = totalPossibleDays > 0 ? (totalVacantDays / totalPossibleDays) * 100 : 0;
    const tempFinancials = {
      purchasePrice: 100000,
      vacancyRatePercent,
    };
    const metrics = deriveAllMetrics(tempFinancials as any, undefined, 'RENT', 3);
    const occupancyRate = metrics.occupancyRate;
    const totalOccupiedDays = (totalDays * units.length) - totalVacantDays;
    const occupiedUnitCount = units.filter(u => u.status === 'occupied').length;

    return {
      totalVacantDays,
      occupancyRate,
      totalOccupiedDays,
      occupiedUnitCount,
      totalUnitCount: units.length,
    };
  }, [units, totalDays]);

  /* ── Per-unit occupancy rate (simpler view: seed formula) ── */
  const seedRate = useMemo(() => {
    const avgVacant = units.length > 0
      ? units.reduce((s, u) => s + u.vacantDays, 0) / units.length
      : 0;
    const vacancyRatePercent = totalDays > 0 ? (avgVacant / totalDays) * 100 : 0;
    const tempFinancials = {
      purchasePrice: 100000,
      vacancyRatePercent,
    };
    const metrics = deriveAllMetrics(tempFinancials as any, undefined, 'RENT', 3);
    return metrics.occupancyRate;
  }, [units, totalDays]);

  const stableOnChange = useCallback((values: OccupancyValues) => {
    onValuesChange?.(values);
  }, [onValuesChange]);

  useEffect(() => {
    stableOnChange({
      units,
      totalDays,
      occupancyRate: seedRate,
      totalVacantDays: computed.totalVacantDays,
      totalOccupiedDays: computed.totalOccupiedDays,
      occupiedUnitCount: computed.occupiedUnitCount,
      totalUnitCount: computed.totalUnitCount,
    });
  }, [units, totalDays, seedRate, computed, stableOnChange]);

  /* ── Unit management ── */
  const handleUnitChange = useCallback((idx: number, updated: UnitOccupancy) => {
    setUnits(prev => prev.map((u, i) => i === idx ? updated : u));
  }, []);

  const handleRemoveUnit = useCallback((idx: number) => {
    setUnits(prev => prev.filter((_, i) => i !== idx));
  }, []);

  const handleAddUnit = useCallback(() => {
    const nextNum = units.length + 1;
    setUnits(prev => [...prev, {
      id: String(Date.now()),
      unitLabel: `Unit ${nextNum}`,
      tenantName: '',
      leaseStart: '',
      leaseEnd: '',
      vacantDays: 0,
      status: 'vacant' as const,
    }]);
  }, [units.length]);

  /* ── Colors ── */
  const rateColor = seedRate >= 95 ? '#14B8A6' : seedRate >= 85 ? '#F59E0B' : '#F06543';
  const rateLabel = seedRate >= 95 ? 'Strong' : seedRate >= 85 ? 'Moderate' : 'At Risk';

  return (
    <div
      className={`rounded-xl border border-white/10 p-6 space-y-4 ${className}`}
      style={{ background: 'rgba(24,33,39,0.7)', backdropFilter: 'blur(16px)' }}
    >
      {/* ── Header ── */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-pw-success-container border border-pw-success-border flex items-center justify-center">
            <Building2 className="w-4 h-4 text-pw-success" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white">Tenants & Leases</h3>
            <p className="text-[10px] text-[#6B6870] uppercase tracking-widest font-bold">Occupancy Collection</p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <label className="text-[9px] font-bold uppercase tracking-widest text-slate-600">Period</label>
          <select
            value={totalDays}
            onChange={(e) => setTotalDays(Number(e.target.value))}
            className="bg-white/[0.03] border border-white/[0.06] rounded-lg px-2 py-1 text-xs text-[#C0BEC2]
                       focus:outline-none focus:border-[#454955]/30 transition-all cursor-pointer"
          >
            <option value={365}>Trailing 12M</option>
            <option value={90}>Quarter</option>
            <option value={30}>Month</option>
          </select>
        </div>
      </div>

      {/* ── Occupancy Result ── */}
      <div
        className="rounded-xl border p-4 flex items-center justify-between transition-all duration-500"
        style={{ borderColor: `${rateColor}30`, background: `${rateColor}08` }}
      >
        <div className="flex items-center gap-3">
          <Home className="w-6 h-6 flex-shrink-0" style={{ color: rateColor }} />
          <div>
            <p className="text-xs font-bold" style={{ color: rateColor }}>{rateLabel} Occupancy</p>
            <p className="text-[10px] text-[#6B6870] mt-0.5">
              {computed.totalVacantDays} vacant day{computed.totalVacantDays !== 1 ? 's' : ''} across {units.length} unit{units.length !== 1 ? 's' : ''}
            </p>
          </div>
        </div>
        <div className="text-right">
          <span className="text-4xl font-bold tabular-nums tracking-tighter" style={{ color: rateColor }}>
            {seedRate.toFixed(1)}
          </span>
          <span className="text-lg font-bold ml-0.5" style={{ color: rateColor }}>%</span>
          <p className="text-[9px] text-slate-600 mt-0.5">avg occupancy rate</p>
        </div>
      </div>

      {/* ── Unit-level summary bar ── */}
      <div className="flex gap-1 h-3 rounded-full overflow-hidden bg-white/[0.04]">
        {units.map((u) => {
          const widthPct = units.length > 0 ? 100 / units.length : 0;
          const cfg = STATUS_CFG[u.status];
          return (
            <div
              key={u.id}
              className="h-full transition-all duration-300"
              style={{ width: `${widthPct}%`, backgroundColor: cfg.color, opacity: 0.7 }}
              title={`${u.unitLabel}: ${cfg.label}`}
            />
          );
        })}
      </div>

      {/* ── Unit grid legend ── */}
      <div className="flex items-center gap-3 text-[9px]">
        {Object.entries(STATUS_CFG).map(([key, cfg]) => {
          const count = units.filter(u => u.status === key).length;
          return (
            <span key={key} className="flex items-center gap-1 font-bold" style={{ color: cfg.color }}>
              <span className="w-2 h-2 rounded-full" style={{ backgroundColor: cfg.color }} />
              {cfg.label}: {count}
            </span>
          );
        })}
      </div>

      {/* ── Unit Cards ── */}
      <div className="space-y-2 max-h-72 overflow-y-auto pr-1">
        {units.map((unit, idx) => (
          <UnitRow
            key={unit.id}
            unit={unit}
            onChange={(u) => handleUnitChange(idx, u)}
            onRemove={() => handleRemoveUnit(idx)}
          />
        ))}
      </div>

      {/* ── Add Unit Button ── */}
      <button
        onClick={handleAddUnit}
        className="w-full py-2.5 rounded-lg border border-dashed border-white/10 text-xs font-bold text-[#6B6870]
                   hover:border-[#454955]/30 hover:text-[#6E7480] transition-all flex items-center justify-center gap-1"
      >
        <Plus className="w-3 h-3" />
        Add Unit
      </button>

      {/* ── Formula ── */}
      <div className="px-3 py-2 rounded-lg bg-white/[0.02] border border-white/[0.04]">
        <p className="text-[10px] font-bold uppercase tracking-widest text-[#6B6870] mb-0.5">Formula</p>
        <p className="text-[11px] text-[#9E9DA0] font-mono">
          Occupancy = ({totalDays - Math.round(computed.totalVacantDays / units.length)} ÷ {totalDays}) × 100 = {seedRate.toFixed(1)}%
        </p>
      </div>
    </div>
  );
}

