        />
        <MetricCard
          label="Capital Deployed"
          value={`$${capitalValue}K`}
          change="+$124K this month"
          positive={true}
          icon={<DollarSign className="w-3.5 h-3.5 text-phase-3" />}
          delay={200}
        />
        <MetricCard
