"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useNotification } from "@/context/NotificationContext";
import { useAuth } from "@/context/AuthContext";
import { resolveBottomNav } from "@/lib/navigation/navContract";
import toast from "react-hot-toast";

export function BottomNav() {
  const pathname = usePathname();
  const { unreadTotal } = useNotification();
  const { profile } = useAuth();

  const handleNavClick = (e: React.MouseEvent, itemHref: string, itemName: string) => {
    if (typeof window !== 'undefined' && window.location.pathname.startsWith('/demo')) {
      if (itemHref === '/dashboard/command-center' || itemName === 'Portfolio') {
        e.preventDefault();
        window.location.href = '/demo';
        return;
      }
      e.preventDefault();
      toast.error(`Demo Mode: Sign up to access ${itemName} features.`, {
        id: 'demo-bottom-guard',
        style: { background: '#111', color: '#fff', border: '1px solid #333' }
      });
    }
  };

  const navItems = resolveBottomNav({
    role: profile?.role,
    accountType: profile?.accountType,
    subscriptionPlan: profile?.subscriptionPlan,
  });

  return (
    <nav
      className="md:hidden fixed bottom-0 w-full z-50 flex justify-around items-center px-2 pb-safe"
      style={{
        height: '72px',
        background: 'rgba(13,10,11,0.92)',
        backdropFilter: 'blur(24px)',
        borderTop: '1px solid rgba(255,255,255,0.06)',
        borderRadius: '16px 16px 0 0',
      }}
    >
      {navItems.map((item) => {
        const isActive = Boolean(pathname?.startsWith(item.href)) || (item.href === "/dashboard/command-center" && pathname === "/dashboard");
        return (
          <Link
            key={item.id}
            href={item.href}
            onClick={(e) => handleNavClick(e, item.href, item.label)}
            className="flex flex-col items-center justify-center relative py-2 px-3 transition-all duration-200"
            style={{
              color: isActive ? 'var(--color-primary)' : 'rgba(253,255,252,0.4)',
              transform: isActive ? 'scale(0.95)' : 'scale(1)',
            }}
          >
            <div className="relative">
              <span
                className="material-symbols-outlined text-[22px]"
                style={{ fontVariationSettings: isActive ? "'FILL' 1" : "'FILL' 0" }}
              >
                {item.icon}
              </span>
              {item.id === "inbox" && unreadTotal > 0 && (
                <span
                  className="absolute -top-1 -right-2 text-[8px] font-bold w-4 h-4 rounded-full flex items-center justify-center"
                  style={{
                    background: 'var(--color-primary)',
                    color: '#0d0a0b',
                    boxShadow: '0 0 6px rgba(69, 73, 85,0.5)',
                  }}
                >
                  {unreadTotal > 9 ? '9+' : unreadTotal}
                </span>
              )}
            </div>
            <span
              className="mt-1 uppercase tracking-tight"
              style={{
                fontSize: '9px',
                fontWeight: isActive ? 700 : 500,
                letterSpacing: '0.02em',
              }}
            >
              {item.label}
            </span>
            {/* Luminous dot indicator */}
            {isActive && (
              <div
                className="absolute -bottom-0.5 w-1 h-1 rounded-full"
                style={{
                  background: 'var(--color-primary)',
                  boxShadow: '0 0 10px 2px rgba(69, 73, 85,0.5)',
                }}
              />
            )}
          </Link>
        );
      })}
    </nav>
  );
}

'use client';

import React from 'react';
import { X, ChevronLeft, ChevronRight, CheckCircle2 } from 'lucide-react';

interface Step {
  id: string;
  label: string;
  status: 'pending' | 'active' | 'complete';
}

interface FocusedWorkflowLayoutProps {
  title: string;
  subtitle?: string;
  steps: Step[];
  currentStepIndex: number;
  onExit: () => void;
  onBack?: () => void;
  onNext?: () => void;
  isNextDisabled?: boolean;
  nextLabel?: string;
  children: React.ReactNode;
}

/**
 * FocusedWorkflowLayout
 * 
 * Provides a distraction-free, full-screen environment for critical workflows.
 * Mimics high-reliability systems (Clerky) with a split-pane structural pattern.
 */
export default function FocusedWorkflowLayout({
  title,
  subtitle,
  steps,
  currentStepIndex,
  onExit,
  onBack,
  onNext,
  isNextDisabled,
  nextLabel = 'Continue',
  children
}: FocusedWorkflowLayoutProps) {
  const progress = ((currentStepIndex + 1) / steps.length) * 100;

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-bg-surface text-text-primary overflow-hidden animate-in fade-in duration-300">

      {/* Structural Header */}
      <header className="h-20 border-b border-border-accent flex items-center justify-between px-margin-mobile lg:px-margin-desktop bg-bg-surface shrink-0">
        <div className="flex items-center gap-8">
          <div className="bg-pw-black text-pw-white px-3 py-1 font-black text-xs uppercase tracking-widest border border-pw-border">
            PW_PROTOCOL
          </div>
          <div>
            <h1 className="text-sm font-black uppercase tracking-widest">{title}</h1>
            {subtitle && <p className="text-xs text-text-secondary font-bold uppercase tracking-wider mt-1">{subtitle}</p>}
          </div>
        </div>

        <button 
          onClick={onExit}
          className="flex items-center gap-2 group hover:text-pw-accent transition-colors"
        >
          <span className="text-xs font-black uppercase tracking-widest">Exit_Stream</span>
          <X className="w-5 h-5 group-hover:rotate-90 transition-transform duration-300" />
        </button>
      </header>

      <div className="flex-1 flex overflow-hidden">

        {/* Sidebar Nav (Split-Pane Sidebar) */}
        <aside className="w-80 border-r border-border-accent bg-bg-primary flex flex-col p-12 shrink-0 overflow-y-auto">
          <div className="mb-12">
            <p className="text-xs font-black text-text-secondary uppercase tracking-widest mb-4">WORKFLOW_PROGRESS</p>
            <div className="flex items-end gap-3 mb-2">
              <span className="text-4xl font-black tracking-tighter tabular-nums">{Math.round(progress)}%</span>
              <span className="text-xs font-black text-pw-accent uppercase mb-2">Operational</span>
            </div>
            <div className="w-full h-1 bg-pw-border">
              <div 
                className="h-full bg-pw-accent transition-all duration-700 ease-in-out" 
                style={{ width: `${progress}%` }}
              />
            </div>
          </div>

          <nav className="space-y-8">
            {steps.map((step, idx) => {
              const isActive = idx === currentStepIndex;
              const isComplete = idx < currentStepIndex;
              const isFuture = idx > currentStepIndex;

              return (
                <div key={step.id} className="flex gap-6 relative">
                  {/* Step Connector Line */}
                  {idx !== steps.length - 1 && (
                    <div className={`absolute left-[13px] top-8 w-px h-12 ${isComplete ? 'bg-pw-accent' : 'bg-pw-border'}`} />
                  )}

                  <div className={`w-7 h-7 shrink-0 flex items-center justify-center font-mono text-xs font-black border transition-all ${
                    isActive ? 'bg-pw-black text-pw-white border-pw-border scale-110' :
                    isComplete ? 'bg-pw-accent text-pw-white border-pw-accent' :
                    'bg-bg-surface text-text-secondary border-border-accent'
                  }`}>
                    {isComplete ? <CheckCircle2 className="w-4 h-4" /> : idx + 1}
                  </div>

                  <div className="pt-1">
                    <p className={`text-xs font-black uppercase tracking-widest ${
                      isActive ? 'text-text-primary' : 
                      isComplete ? 'text-text-primary/60' : 
                      'text-text-secondary'
                    }`}>
                      {step.label}
                    </p>
                    {isActive && (
                      <span className="text-xs font-bold text-pw-accent uppercase tracking-tighter animate-pulse">
                        Input Required
                      </span>
                    )}
                  </div>
                </div>
              );
            })}
          </nav>

          <div className="mt-auto pt-12 border-t border-border-accent">
            <div className="flex items-center gap-3 grayscale opacity-30">
              <div className="w-2 h-2 rounded-full bg-pw-accent animate-pulse" />
              <span className="text-xs font-black uppercase tracking-widest text-text-primary">Ledger_Sync_Active</span>
            </div>
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="flex-1 bg-bg-surface overflow-y-auto p-margin-mobile lg:p-20 flex flex-col">
          <div className="max-w-3xl w-full mx-auto flex-1">
            {children}
          </div>

          {/* Persistent Footer Actions (Hierarchy Enrollment) */}
          <div className="max-w-3xl w-full mx-auto mt-20 pt-10 border-t border-border-accent flex justify-between items-center">
            {onBack ? (
              <button 
                onClick={onBack}
                className="flex items-center gap-3 text-xs font-black text-text-secondary hover:text-text-primary uppercase tracking-widest transition-all"
              >
                <ChevronLeft className="w-4 h-4" />
                Previous_Phase
              </button>
            ) : <div />}

            {onNext && (
              <button 
                onClick={onNext}
                disabled={isNextDisabled}
                className={`
                  flex items-center gap-6 px-10 py-5 font-black text-sm uppercase tracking-widest transition-all border
                  ${isNextDisabled 
                    ? 'bg-bg-primary text-text-secondary border-border-accent cursor-not-allowed opacity-50' 
                    : 'bg-pw-black text-pw-white border-pw-border hover:bg-pw-accent hover:border-pw-accent group'
                  }
                `}
              >
                <span>{nextLabel}</span>
                <ChevronRight className="w-5 h-5 group-hover:translate-x-2 transition-transform" />
              </button>
            )}
          </div>
        </main>
      </div>
    </div>
  );
}

