'use client';

import React, { useState, useEffect } from 'react';
import { X, Sparkles, ArrowRight } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';

export default function AnnouncementBanner() {
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Check if user has already dismissed this specific banner version
    const dismissed = localStorage.getItem('pw_announcement_v1');
    if (!dismissed) {
      setIsVisible(true);
    }
  }, []);

  const handleDismiss = () => {
    setIsVisible(false);
    localStorage.setItem('pw_announcement_v1', 'true');
  };

  return (
    <AnimatePresence>
      {isVisible && (
        <motion.div
          initial={{ height: 0, opacity: 0 }}
          animate={{ height: 'auto', opacity: 1 }}
          exit={{ height: 0, opacity: 0 }}
          className="relative z-50 bg-[var(--pw-glass-bg)] backdrop-blur-md text-[var(--color-on-surface)] border-b border-[var(--pw-border)] overflow-hidden font-sans"
        >
          <div className="max-w-7xl mx-auto px-6 py-2.5 flex items-center justify-between gap-4">
            <div className="flex-1 flex items-center justify-center gap-x-6">
              <div className="flex items-center gap-x-2">
                <Sparkles className="w-4 h-4 text-amber-500 dark:text-amber-400" />
                <span className="text-xs font-bold uppercase tracking-widest text-amber-500 dark:text-amber-400">New Release</span>
              </div>
              <p className="text-sm font-medium tracking-tight">
                PaperWorking 2.0 is live: Full portfolio analytics and deep-focus Kanban now available for all users.
              </p>
              <a 
                href="/blog/q2-market-update-inventory-deficit"
                className="flex items-center gap-x-1 underline decoration-[var(--pw-border)] underline-offset-4 hover:opacity-80 transition-all text-sm font-bold text-[var(--color-primary)] dark:text-[var(--color-primary-fixed)]"
              >
                Learn More <ArrowRight className="w-3 h-3" />
              </a>
            </div>

