'use client';

import React, { useEffect, useState, useCallback } from 'react';
import { RefreshCw, MapPin } from 'lucide-react';
import MarketVitalsCard from './MarketVitalsCard';
import ZoningScanPanel from './ZoningScanPanel';
import type { ZipDemographics } from '@/types/marketVitals';

// ── ZIP extraction ────────────────────────────────────────────

function extractZip(address: string): string {
  const match = address.match(/\b(\d{5})(?:-\d{4})?\b/);
  return match?.[1] ?? '';
}

// ── Main ──────────────────────────────────────────────────────

export interface MarketVitalsProps {
  /** Full property address — ZIP is extracted automatically. */
  address: string;
  /** Firestore project ID — passed to ZoningScanPanel for context. */
  projectId?: string;
  className?: string;
}

export default function MarketVitals({ address, projectId, className = '' }: MarketVitalsProps) {
  const zip = extractZip(address);

  const [demographics, setDemographics] = useState<ZipDemographics | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [fetchError, setFetchError] = useState<string | null>(null);

  const fetchDemographics = useCallback(async () => {
    if (!zip) {
      setFetchError('No ZIP code found in property address. Make sure the address includes a 5-digit ZIP.');
      return;
    }
    setIsLoading(true);
    setFetchError(null);
    setDemographics(null);

    try {
      const res = await fetch(`/api/market-vitals?zip=${zip}`);
      const json = await res.json();
      if (!res.ok) {
        setFetchError(json.error || 'Failed to load market vitals.');
        return;
      }
      setDemographics(json.demographics as ZipDemographics);
    } catch {
      setFetchError('Network error loading market vitals. Please retry.');
    } finally {
      setIsLoading(false);
    }
  }, [zip]);

  // Auto-fetch on mount when ZIP is present
  useEffect(() => {
    if (zip) fetchDemographics();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [zip]);

  return (
    <section className={`space-y-4 ${className}`} aria-label="Market Vitals">
      {/* Section header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <MapPin className="w-4 h-4" style={{ color: 'var(--pw-subtle)' }} />
          <h3 className="text-sm font-semibold uppercase tracking-[0.12em]" style={{ color: 'var(--text-primary)' }}>
            Market Vitals
          </h3>
          {zip && (
            <span
              className="text-[9px] font-bold px-2 py-0.5 rounded uppercase tracking-widest"
              style={{ background: 'var(--bg-canvas)', color: 'var(--pw-subtle)' }}
            >
              ZIP {zip}
            </span>
          )}
        </div>

        <button
          type="button"
          onClick={fetchDemographics}
          disabled={isLoading || !zip}
          className="flex items-center gap-1.5 text-[9px] font-bold uppercase tracking-widest transition-opacity disabled:opacity-40 hover:opacity-70"
          style={{ color: 'var(--pw-subtle)' }}
          aria-label="Refresh market vitals"
        >
          <RefreshCw className={`w-3 h-3 ${isLoading ? 'animate-spin' : ''}`} />
          {isLoading ? 'Loading…' : 'Refresh'}
        </button>
      </div>

      {/* No ZIP state */}
      {!zip && !isLoading && (
        <div
          className="rounded-lg border p-5 text-center"
          style={{ borderColor: 'var(--pw-border)', background: 'var(--pw-surface)' }}
        >
          <MapPin className="w-6 h-6 mx-auto mb-2" style={{ color: 'var(--pw-border)' }} />
          <p className="text-xs font-medium" style={{ color: 'var(--pw-muted)' }}>
            ZIP code not found in property address
          </p>
          <p className="text-[9px] mt-1" style={{ color: 'var(--pw-border)' }}>
            Current address: <span className="font-mono">{address || '—'}</span>
          </p>
          <p className="text-[9px] mt-1" style={{ color: 'var(--pw-border)' }}>
            Make sure the address includes a valid 5-digit ZIP code to load market demographics.
          </p>
        </div>
      )}

      {/* Error */}
      {fetchError && (
        <div
          className="rounded p-3 text-xs"
          style={{
            background: '#fef2f2',
            color: '#dc2626',
            border: '1px solid #fecaca',
          }}
        >
          {fetchError}
        </div>
      )}

      {/* Two-column layout: Demographics + Zoning */}
      {(zip || isLoading) && !fetchError && (
        <div className="grid grid-cols-1 xl:grid-cols-2 gap-4">
          <MarketVitalsCard
            demographics={demographics}
            isLoading={isLoading}
          />
          <ZoningScanPanel
            zip={zip}
            address={address}
            projectId={projectId}
          />
        </div>
      )}
    </section>
  );
}

'use client';

import React, { useMemo } from 'react';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  Area,
  AreaChart,
  Tooltip,
} from 'recharts';
import { TrendingUp, TrendingDown, Minus, Users, DollarSign, Home, Building2 } from 'lucide-react';
import type { ZipDemographics, MarketDataPoint } from '@/types/marketVitals';

// ── Helpers ───────────────────────────────────────────────────

function fmtCurrency(n: number): string {
  if (n >= 1_000_000) return `$${(n / 1_000_000).toFixed(2)}M`;
  if (n >= 1_000) return `$${Math.round(n / 1_000)}k`;
  return `$${n.toLocaleString('en-US')}`;
}

function fmtNumber(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(2)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`;
  return n.toLocaleString('en-US');
}

function growthColor(pct: number): string {
  if (pct > 0) return '#16a34a';
  if (pct < 0) return '#dc2626';
  return 'var(--text-secondary)';
}

function growthBg(pct: number): string {
  if (pct > 0) return '#f0fdf4';
  if (pct < 0) return '#fef2f2';
  return 'var(--bg-canvas)';
}

// ── Inline Sparkline ──────────────────────────────────────────

interface SparklineProps {
  data: MarketDataPoint[];
  color: string;
  height?: number;
}

function Sparkline({ data, color, height = 52 }: SparklineProps) {
  if (!data || data.length < 2) {
    return (
      <div
        style={{ height, background: 'var(--bg-canvas)', borderRadius: 4 }}
        className="w-full flex items-center justify-center"
      >
        <span className="text-[9px]" style={{ color: 'var(--pw-muted)' }}>
          No trend data
        </span>
      </div>
    );
  }

  return (
    <ResponsiveContainer width="100%" height={height}>
      <AreaChart data={data} margin={{ top: 4, right: 0, left: 0, bottom: 0 }}>
        <defs>
          <linearGradient id={`spark-${color.replace('#', '')}`} x1="0" y1="0" x2="0" y2="1">
            <stop offset="10%" stopColor={color} stopOpacity={0.18} />
            <stop offset="90%" stopColor={color} stopOpacity={0} />
          </linearGradient>
        </defs>
        <Tooltip
          content={({ active, payload }) => {
            if (!active || !payload?.length) return null;
            const pt = payload[0].payload as MarketDataPoint;
            return (
              <div
                className="text-[9px] font-mono px-2 py-1 rounded shadow-sm"
                style={{
                  background: 'var(--pw-surface)',
                  border: '1px solid var(--pw-border)',
                  color: 'var(--text-primary)',
                }}
              >
                {pt.year}: {typeof pt.value === 'number' && pt.value > 10_000
                  ? fmtCurrency(pt.value)
                  : fmtNumber(pt.value)}
              </div>
            );
          }}
          cursor={false}
        />
        <Area
          type="monotone"
          dataKey="value"
          stroke={color}
          strokeWidth={1.5}
          fill={`url(#spark-${color.replace('#', '')})`}
          dot={false}
          isAnimationActive
          animationDuration={600}
        />
      </AreaChart>
    </ResponsiveContainer>
  );
}

// ── KPI Tile ──────────────────────────────────────────────────

interface KPITileProps {
  label: string;
  value: string;
  sub?: string;
  growthPct?: number;
  growthLabel?: string;
  trend: MarketDataPoint[];
  trendColor: string;
  icon: React.ReactNode;
}

function KPITile({
  label,
  value,
  sub,
  growthPct,
  growthLabel,
  trend,
  trendColor,
  icon,
}: KPITileProps) {
  const hasGrowth = growthPct !== undefined;
  const GrowthIcon =
    !hasGrowth ? Minus : growthPct > 0 ? TrendingUp : growthPct < 0 ? TrendingDown : Minus;

  return (
    <div
      className="flex flex-col justify-between p-5 min-h-[160px]"
      style={{ background: 'var(--pw-surface)' }}
    >
      {/* Header row */}
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-2">
          <div
            className="flex items-center justify-center w-7 h-7 rounded"
            style={{ background: 'var(--bg-canvas)' }}
          >
            {icon}
          </div>
          <p className="text-[9px] font-bold uppercase tracking-[0.15em]" style={{ color: 'var(--pw-muted)' }}>
            {label}
          </p>
        </div>
        {hasGrowth && (
          <div
            className="flex items-center gap-1 px-1.5 py-0.5 rounded shrink-0"
            style={{ background: growthBg(growthPct!), color: growthColor(growthPct!) }}
          >
            <GrowthIcon className="w-2.5 h-2.5" aria-hidden="true" />
            <span className="text-[9px] font-bold">
              {growthPct! >= 0 ? '+' : ''}{growthPct!.toFixed(2)}%
            </span>
          </div>
        )}
      </div>

      {/* Value */}
      <div className="mt-2">
        <p
          className="text-xl font-normal tracking-tighter"
          style={{ color: 'var(--pw-black)', fontFamily: 'ui-monospace, monospace' }}
        >
          {value}
        </p>
        {sub && (
          <p className="text-[10px] mt-0.5" style={{ color: 'var(--pw-muted)' }}>
            {sub}
          </p>
        )}
        {growthLabel && (
          <p className="text-[8px] font-bold uppercase tracking-widest mt-1" style={{ color: 'var(--pw-border)' }}>
            {growthLabel}
          </p>
        )}
      </div>

      {/* Sparkline */}
      <div className="mt-3">
        <Sparkline data={trend} color={trendColor} height={48} />
      </div>
    </div>
  );
}

