              })}
              {' · '}Source: {scanResult.source}
              {' · '}
              For full GIS analysis run:&nbsp;
              <code className="font-mono text-[8px]">
                npx ts-node src/scripts/zoning-scraper.ts --address=&quot;{address}&quot; --state=XX
              </code>
            </p>
          </div>
        )}
      </div>
    </div>
