                                transition={{ duration: 0.4, ease: 'easeOut' }}
                                className={`absolute top-1 bottom-1 rounded-sm ${
                                  task.status === 'Complete'
                                    ? 'bg-[#595959]'
                                    : isCritical
                                      ? 'bg-[#595959]'
                                      : task.status === 'Blocked'
                                        ? 'bg-[#595959]'
                                        : task.status === 'In Progress'
                                          ? 'bg-[#F2F2F2]0'
