                      );
                    })}

                    {/* Add task */}
                    <button
                      onClick={addTask}
                      className="w-full flex items-center justify-center gap-1.5 py-2 border border-dashed border-border-accent text-xs text-text-secondary hover:bg-bg-primary transition mt-2"
