    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { motion } from 'framer-motion';
import { useProjectStore } from '@/store/projectStore';
import type { RehabScheduleTask, RehabStage } from '@/types/schema';
import { HardHat, Hammer, ClipboardCheck } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Rehab Phase Bar — 3-Stage Renovation Lifecycle

   Pre-Construction → Active Renovation → Punch List & Final

   A compact horizontal bar showing which stage the
   renovation is in, with completion progress per stage
   and milestone markers at stage boundaries.
   ═══════════════════════════════════════════════════════ */

const STAGE_META: Record<RehabStage, {
  label: string;
  shortLabel: string;
  icon: React.ReactNode;
  milestone: string;
}> = {
  'Pre-Construction': {
    label: 'Pre-Construction',
    shortLabel: 'Pre-Con',
    icon: <HardHat className="w-3 h-3" />,
    milestone: 'Permits Approved',
  },
  'Active Renovation': {
    label: 'Active Renovation',
    shortLabel: 'Active',
    icon: <Hammer className="w-3 h-3" />,
    milestone: 'Rough Inspections Clear',
  },
  'Punch List': {
    label: 'Punch List & Final',
    shortLabel: 'Punch',
    icon: <ClipboardCheck className="w-3 h-3" />,
    milestone: 'Final Walkthrough',
  },
};

const STAGES: RehabStage[] = ['Pre-Construction', 'Active Renovation', 'Punch List'];

interface StageData {
  stage: RehabStage;
  totalTasks: number;
  completeTasks: number;
  totalDays: number;
  progress: number;
}

function computeStageData(tasks: RehabScheduleTask[]): StageData[] {
  return STAGES.map(stage => {
    const stageTasks = tasks.filter(t => t.phase === stage);
    const completeTasks = stageTasks.filter(t => t.status === 'Complete').length;
    const totalDays = stageTasks.reduce((s, t) => s + t.durationDays, 0);
    const progress = stageTasks.length > 0 ? completeTasks / stageTasks.length : 0;

    return {
      stage,
      totalTasks: stageTasks.length,
      completeTasks,
      totalDays: Math.max(totalDays, 1),
      progress,
    };
  });
}

function findActiveStage(stages: StageData[]): RehabStage {
  for (const s of stages) {
    if (s.progress < 1 && s.totalTasks > 0) return s.stage;
  }
  // All complete or no tasks
  return stages.every(s => s.totalTasks === 0) ? 'Pre-Construction' : 'Punch List';
}

export default function RehabPhaseBar() {
  const currentProject = useProjectStore(s => s.currentProject);
  const tasks = currentProject?.rehabScheduleTasks ?? [];

  const stageData = useMemo(() => computeStageData(tasks), [tasks]);
  const activeStage = useMemo(() => findActiveStage(stageData), [stageData]);
  const totalDays = useMemo(
    () => stageData.reduce((s, d) => s + d.totalDays, 0),
    [stageData]
  );

  const hasTasks = tasks.length > 0;

  if (!currentProject) return null;

  return (
    <div className="bg-bg-surface border border-border-accent p-5 space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <p className="text-[9px] font-black text-text-secondary uppercase tracking-[0.3em]">
            Renovation Lifecycle
          </p>
          {hasTasks && (
            <p className="text-[10px] text-text-secondary mt-0.5">
              {tasks.filter(t => t.status === 'Complete').length} of {tasks.length} tasks complete
            </p>
          )}
        </div>
        {hasTasks && (
          <p className="text-[9px] font-black text-text-primary uppercase tracking-widest">
            {STAGE_META[activeStage].label}
          </p>
        )}
      </div>

      {!hasTasks ? (
        <div className="flex items-center justify-center py-4 border border-dashed border-border-accent">
          <p className="text-[9px] font-black text-text-secondary/40 uppercase tracking-[0.3em]">
            Add schedule tasks to see renovation stages
          </p>
        </div>
      ) : (
        <>
          {/* Segmented bar */}
          <div className="flex h-8 overflow-hidden bg-bg-primary">
            {stageData.map((s, i) => {
              const widthPct = (s.totalDays / totalDays) * 100;
              const isActive = s.stage === activeStage;
              const isComplete = s.progress >= 1;

              return (
                <div
                  key={s.stage}
                  className={`relative flex items-center justify-center overflow-hidden transition-all ${
                    i < stageData.length - 1 ? 'border-r border-bg-surface' : ''
                  }`}
                  style={{ width: `${widthPct}%` }}
                >
                  {/* Fill */}
                  <motion.div
                    initial={{ width: 0 }}
                    animate={{ width: `${s.progress * 100}%` }}
                    transition={{ duration: 0.6, ease: 'easeOut', delay: i * 0.15 }}
                    className={`absolute inset-y-0 left-0 ${
                      isComplete
                        ? 'bg-pw-black'
                        : isActive
                          ? 'bg-pw-black/70'
                          : 'bg-[#CCCCCC]'
                    }`}
                  />
                  {/* Label */}
                  <div className="relative z-10 flex items-center gap-1">
                    <span className={`${
                      s.progress > 0.4 ? 'text-white' : 'text-text-secondary'
                    }`}>
                      {STAGE_META[s.stage].icon}
                    </span>
                    <span className={`text-[8px] font-black uppercase tracking-widest hidden sm:inline ${
                      s.progress > 0.4 ? 'text-white' : 'text-text-secondary'
                    }`}>
                      {STAGE_META[s.stage].shortLabel}
                    </span>
                  </div>
                </div>
              );
            })}
          </div>

          {/* Stage details row */}
          <div className="grid grid-cols-3 gap-2">
            {stageData.map(s => {
              const isActive = s.stage === activeStage;
              return (
                <div
                  key={s.stage}
                  className={`px-3 py-2 text-center transition-colors ${
                    isActive
                      ? 'bg-bg-primary border border-pw-border'
                      : 'border border-border-accent'
                  }`}
                >
                  <p className="text-[8px] font-black text-text-secondary uppercase tracking-widest mb-0.5">
                    {STAGE_META[s.stage].shortLabel}
                  </p>
                  <p className="text-[10px] font-black text-text-primary tabular-nums">
                    {s.completeTasks}/{s.totalTasks}
                  </p>
                  <p className="text-[8px] text-text-secondary">
                    {STAGE_META[s.stage].milestone}
                  </p>
                </div>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

'use client';

import { useMemo } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { motion } from 'framer-motion';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  ReferenceLine,
} from 'recharts';
import { TrendingUp, TrendingDown, Minus } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Yesterday's Cost Card — Hold Phase (Phase 3)

   Answers the question: "What did yesterday cost me?"
   Combines per-diem interest, prorated holding costs,
   and average daily rehab spend into one number.
   Includes a 30-day sparkline and 7-day average delta.
   ═══════════════════════════════════════════════════════ */

interface DailyCost {
  day: number;
  total: number;
  interest: number;
  holding: number;
  rehab: number;
}

function fmt(n: number, decimals = 2): string {
  return `$${n.toLocaleString(undefined, {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  })}`;
}

export default function YesterdayCostCard() {
  const currentProject = useProjectStore(s => s.currentProject);
  const financials = currentProject?.financials;

  const { yesterday, sevenDayAvg, sparkline, breakdown } = useMemo(() => {
    const empty = {
      yesterday: 0,
      sevenDayAvg: 0,
      sparkline: [] as DailyCost[],
      breakdown: { interest: 0, holding: 0, rehab: 0 },
    };

    if (!financials) return empty;

    // Per-diem interest
    const loanAmount = financials.loanAmount || 0;
    const interestRate = financials.loanInterestRate || 0;
    const dailyInterest = loanAmount > 0 && interestRate > 0
      ? (loanAmount * (interestRate / 100)) / 365
      : 0;

    // Daily holding costs (non-interest)
    const holdingCosts = currentProject?.holdingCosts ?? [];
    const monthlyNonInterest = holdingCosts
      .filter(c => c.type !== 'Loan Interest')
      .reduce((sum, c) => sum + (c.monthlyAmount || 0), 0);
    const dailyHolding = monthlyNonInterest / 30.44;

    // Daily rehab spend (average of approved costs over elapsed days)
    const acquisitionDate = financials.acquisitionDate
      ? new Date(financials.acquisitionDate)
      : currentProject?.holdingCostClockStart
        ? new Date(currentProject.holdingCostClockStart)
        : null;

    const elapsedDays = acquisitionDate
      ? Math.max(1, Math.floor((Date.now() - acquisitionDate.getTime()) / 86_400_000))
      : 1;

    const totalApprovedRehab = (financials.costs || [])
      .filter(c => c.approved)
      .reduce((sum, c) => sum + c.amount, 0);
    const dailyRehab = elapsedDays > 0 ? totalApprovedRehab / elapsedDays : 0;

    // Yesterday's total
    const yesterdayTotal = dailyInterest + dailyHolding + dailyRehab;

    // Build sparkline data for last 30 days (or fewer if project is younger)
    const sparkDays = Math.min(30, elapsedDays);
    const points: DailyCost[] = [];
    for (let i = sparkDays; i >= 1; i--) {
      const dayTotal = dailyInterest + dailyHolding + dailyRehab;

      points.push({
        day: sparkDays - i + 1,
        total: Math.round(dayTotal * 100) / 100,
        interest: Math.round(dailyInterest * 100) / 100,
        holding: Math.round(dailyHolding * 100) / 100,
        rehab: Math.round(dailyRehab * 100) / 100,
      });
    }

    // 7-day average
    const last7 = points.slice(-7);
    const avg7 = last7.length > 0
      ? last7.reduce((s, p) => s + p.total, 0) / last7.length
      : 0;

    return {
      yesterday: yesterdayTotal,
      sevenDayAvg: avg7,
      sparkline: points,
      breakdown: {
        interest: dailyInterest,
        holding: dailyHolding,
        rehab: dailyRehab,
      },
    };
  }, [financials, currentProject]);

  const delta = sevenDayAvg > 0
    ? ((yesterday - sevenDayAvg) / sevenDayAvg) * 100
    : 0;
  const deltaAbs = Math.abs(delta);
  const isUp = delta > 1;
  const isDown = delta < -1;

  if (!currentProject) return null;

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.4, ease: 'easeOut' }}
      className="bg-pw-black overflow-hidden"
    >
      {/* Main content */}
      <div className="p-6 pb-2">
        <p className="text-label-sm font-black text-white/40 uppercase tracking-[0.4em] mb-3">
          Yesterday&apos;s Cost
        </p>

        {/* Big number */}
        <p className="text-4xl font-black text-white tabular-nums font-mono leading-none">
          {fmt(yesterday)}
        </p>

        {/* Breakdown line */}
        <p className="text-label-sm text-white/50 font-bold mt-2 tracking-wide">
          Interest {fmt(breakdown.interest, 0)}
          {' + '}Holding {fmt(breakdown.holding, 0)}
          {' + '}Rehab {fmt(breakdown.rehab, 0)}
        </p>
      </div>

      {/* Sparkline */}
      {sparkline.length > 2 && (
        <div className="h-16 w-full px-2">
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart data={sparkline} margin={{ top: 4, right: 0, bottom: 0, left: 0 }}>
              <defs>
                <linearGradient id="yesterdayFill" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0%" stopColor="#D97706" stopOpacity={0.3} />
                  <stop offset="100%" stopColor="#D97706" stopOpacity={0} />
                </linearGradient>
              </defs>
              <Area
                type="monotone"
                dataKey="total"
                stroke="#D97706"
                strokeWidth={1.5}
                fill="url(#yesterdayFill)"
                isAnimationActive={true}
                animationDuration={800}
              />
              {sevenDayAvg > 0 && (
                <ReferenceLine
                  y={sevenDayAvg}
                  stroke="#FFFFFF"
                  strokeOpacity={0.15}
                  strokeDasharray="3 3"
                />
              )}
            </AreaChart>
          </ResponsiveContainer>
        </div>
      )}

      {/* 7-day comparison footer */}
      <div className="px-6 pb-4 pt-1 flex items-center justify-end gap-1.5">
        {isUp && <TrendingUp className="w-3 h-3 text-[#595959]" />}
        {isDown && <TrendingDown className="w-3 h-3 text-[#1A1A1A]" />}
        {!isUp && !isDown && <Minus className="w-3 h-3 text-white/30" />}
        <span className={`text-label-sm font-black tracking-wide ${
          isUp ? 'text-[#595959]' : isDown ? 'text-[#1A1A1A]' : 'text-white/30'
        }`}>
          vs 7-day avg: {fmt(sevenDayAvg, 0)}
          {deltaAbs > 1 && ` ${isUp ? '↑' : '↓'}${deltaAbs.toFixed(0)}%`}
        </span>
      </div>
    </motion.div>
  );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { X, Rocket, Plus, UserPlus } from 'lucide-react';
import { useAuth } from '@/context/AuthContext';
import { doc, updateDoc, serverTimestamp } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';

/* ═══════════════════════════════════════════════════════
   FirstMetricCelebration — "Your first metric is live!"

   Phase B (Activate): CSS confetti animation (no library)
   with a modal celebrating the milestone.

   CTAs:
   • Add a second project
   • Invite a vendor / team member
   ═══════════════════════════════════════════════════════ */

interface FirstMetricCelebrationProps {
  onDismiss?: () => void;
  onAddProject?: () => void;
  onInviteVendor?: () => void;
}

export function FirstMetricCelebration({
  onDismiss,
  onAddProject,
  onInviteVendor,
}: FirstMetricCelebrationProps) {
  const { user } = useAuth();
  const [isClosing, setIsClosing] = useState(false);
  const [confettiPieces] = useState(() => generateConfetti(60));

  const handleDismiss = useCallback(async () => {
    setIsClosing(true);

    // Mark onboarding as completed
    if (user) {
      try {
        const userDocRef = doc(db, 'users', user.uid);
        await updateDoc(userDocRef, {
          onboardingCompleted: true,
          updatedAt: serverTimestamp(),
        });
      } catch {
        // Non-fatal
      }
    }

    // Fire event
    if (user) {
      user.getIdToken().then((idToken: string) => {
        fetch('/api/events', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${idToken}`
          },
          body: JSON.stringify({
            event: 'onboarding_celebration_dismissed',
            properties: {},
          }),
        }).catch(() => {});
      }).catch(() => {});
    }

    setTimeout(() => {
      onDismiss?.();
    }, 300);
  }, [user, onDismiss]);

  const handleAddProject = () => {
    handleDismiss();
    onAddProject?.();
  };

  const handleInvite = () => {
    handleDismiss();
    onInviteVendor?.();
  };

  return (
    <div
      className={`metric-lit fixed inset-0 z-[10000] flex items-center justify-center p-4 transition-opacity duration-300 ${
        isClosing ? 'opacity-0' : 'opacity-100'
      }`}
    >
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={handleDismiss}
      />

      {/* Confetti Layer */}
      <div className="confetti-canvas absolute inset-0 pointer-events-none overflow-hidden">
        {confettiPieces.map((piece, i) => (
          <div
            key={i}
            className="absolute"
            style={{
              left: `${piece.x}%`,
              top: '-5%',
              width: piece.size,
              height: piece.size * piece.aspectRatio,
              backgroundColor: piece.color,
              borderRadius: piece.isCircle ? '50%' : '2px',
              opacity: 0.9,
              animation: `confetti-fall ${piece.duration}s ${piece.delay}s ease-in forwards`,
              transform: `rotate(${piece.rotation}deg)`,
            }}
          />
        ))}
      </div>

      {/* Modal */}
      <div
        className="relative z-10 w-full max-w-md rounded-2xl border border-white/15 overflow-hidden"
        style={{
          background: 'linear-gradient(135deg, rgba(18, 28, 35, 0.97) 0%, rgba(13, 10, 11, 0.99) 100%)',
          backdropFilter: 'blur(24px)',
          boxShadow: '0 25px 60px -10px rgba(0, 0, 0, 0.6), 0 0 50px -5px rgba(69, 73, 85, 0.1)',
          animation: isClosing ? '' : 'celebration-scale-in 0.5s cubic-bezier(0.16, 1, 0.3, 1)',
        }}
      >
        {/* Close button */}
        <button
          onClick={handleDismiss}
          className="absolute top-4 right-4 text-[#9E9DA0]/60 hover:text-white transition-colors p-1 z-10"
          aria-label="Close"
        >
          <X className="w-4 h-4" />
        </button>

        {/* Hero Glow */}
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[200px] h-[120px] bg-[#454955]/20 blur-[80px] rounded-full pointer-events-none" />

        {/* Content */}
        <div className="relative p-8 text-center space-y-6">
          {/* Icon */}
          <div
            className="mx-auto w-16 h-16 rounded-2xl flex items-center justify-center"
            style={{
              background: 'linear-gradient(135deg, rgba(69, 73, 85, 0.2) 0%, rgba(69, 73, 85, 0.08) 100%)',
              boxShadow: '0 0 30px rgba(69, 73, 85, 0.2)',
              animation: 'celebration-bounce 1.5s ease-in-out infinite',
            }}
          >
            <Rocket className="w-8 h-8 text-[#454955]" style={{ animation: 'celebration-rocket 1.5s ease-in-out infinite' }} />
          </div>

          {/* Text */}
          <div className="space-y-3">
            <h2 className="text-[24px] leading-[32px] font-bold text-white tracking-tight">
              Your first metric is live!
            </h2>
            <p className="text-[14px] leading-[22px] text-[#9E9DA0] max-w-sm mx-auto">
              PaperWorking is now tracking your deal in real-time. As market data
              changes, your metrics update automatically.
            </p>
          </div>

          {/* Live Metric Preview */}
          <div
            className="inline-flex items-center gap-3 px-5 py-3 rounded-xl border border-[#454955]/20"
            style={{ background: 'rgba(69, 73, 85, 0.06)' }}
          >
            <div className="w-2 h-2 rounded-full bg-[#4ADE80] animate-pulse" />
            <span className="text-[13px] font-medium text-[#454955] uppercase tracking-wider">
              LIVE
            </span>
          </div>

          {/* CTA Buttons */}
          <div className="space-y-3 pt-2">
            <button
              onClick={handleAddProject}
              className="w-full flex items-center justify-center gap-2 h-12 rounded-xl text-[14px] font-semibold transition-all duration-200 hover:scale-[1.02] active:scale-[0.98]"
              style={{
                background: 'linear-gradient(135deg, #454955 0%, #454955 100%)',
                color: '#0d0a0b',
                boxShadow: '0 4px 20px rgba(69, 73, 85, 0.3)',
              }}
            >
              <Plus className="w-4 h-4" />
              Add a Second Project
            </button>

            <button
              onClick={handleInvite}
              className="w-full flex items-center justify-center gap-2 h-12 rounded-xl text-[14px] font-semibold border border-white/10 text-[#9E9DA0] hover:bg-white/5 transition-all duration-200"
            >
              <UserPlus className="w-4 h-4" />
              Invite a Vendor
            </button>

            <button
              onClick={handleDismiss}
              className="text-[12px] text-[#9E9DA0]/60 hover:text-[#9E9DA0] transition-colors pt-1"
            >
              Continue exploring
            </button>
          </div>
        </div>
      </div>

      {/* Inline keyframe animations */}
      <style jsx global>{`
        @keyframes confetti-fall {
          0% { transform: translateY(0) rotate(0deg); opacity: 1; }
          100% { transform: translateY(110vh) rotate(720deg); opacity: 0; }
        }
        @keyframes celebration-scale-in {
          0% { transform: scale(0.85); opacity: 0; }
          100% { transform: scale(1); opacity: 1; }
        }
        @keyframes celebration-bounce {
          0%, 100% { transform: translateY(0); }
          50% { transform: translateY(-4px); }
        }
        @keyframes celebration-rocket {
          0%, 100% { transform: rotate(-10deg); }
          50% { transform: rotate(10deg); }
        }
      `}</style>
    </div>
  );
}

/* ── Confetti Generation ── */

const CONFETTI_COLORS = [
  '#454955', // teal
  '#D4A843', // gold
  '#4ADE80', // green
  '#454955', // brand secondary accent
  '#60A5FA', // blue
  '#F06543', // red
  '#FBBF24', // amber
  '#ffffff', // white
];

interface ConfettiPiece {
  x: number;
  color: string;
  size: number;
  aspectRatio: number;
  rotation: number;
  duration: number;
  delay: number;
  isCircle: boolean;
}

function generateConfetti(count: number): ConfettiPiece[] {
  return Array.from({ length: count }, () => ({
    x: Math.random() * 100,
    color: CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)],
    size: 4 + Math.random() * 8,
    aspectRatio: 0.5 + Math.random() * 2,
    rotation: Math.random() * 360,
    duration: 2 + Math.random() * 3,
    delay: Math.random() * 1.5,
    isCircle: Math.random() > 0.6,
  }));
}

