  Loader2,
  X,
  ChevronDown,
  ChevronRight,
  Settings
} from 'lucide-react';

// ── Component-local types ─────────────────────────────────────
interface BudgetLine {
  id: string;
  category: string;
  resourceType: 'materials' | 'labor' | 'mixed';
  resourceDescription?: string;
  estimated: number;
}

interface ActualEntry {
  id: string;
  budgetLineId: string;
  vendor: string;
  description: string;
  amount: number;
  createdAt: string; // ISO string
}

interface W9Record {
  vendor: string;
  w9Received: boolean;
}

interface DrawEntry {
  id: string;
  description: string;
  totalAmount: number;
  drawnAmount: number;
  pendingAmount: number;
  status: 'Pending Inspector' | 'Approved' | 'Rejected';
  requestedAt: string;
}

interface PermitEntry {
  id: string;
  type: string;
  municipality: string;
  appliedAt: string | null;
  approvedAt: string | null;
  finalSignOffAt: string | null;
  status: 'Not Filed' | 'Filed' | 'Approved' | 'Final Sign-Off' | 'Denied';
}

interface TrackerData {
  budgetLines: BudgetLine[];
  actualEntries: ActualEntry[];
  w9Records: W9Record[];
  drawEntries: DrawEntry[];
  permitEntries: PermitEntry[];
  contingencyPct: number;
  totalLoanAmount: number;
}

// ── Helpers ───────────────────────────────────────────────────
