'use client';

import { useState } from 'react';
import { Settings, Save, Loader2, CheckCircle2, AlertCircle } from 'lucide-react';
import { getAuth } from 'firebase/auth';
import type { LenderRate } from '@/lib/providers/lenderRates';

/* ═══════════════════════════════════════════════════════════════
   LenderRatesAdmin — inline admin panel for updating lender rates.

   Only shown to users with orgRole 'Lead Investor' or 'Admin'.
   Calls PUT /api/admin/lender-rates with the updated rates array.
   After a successful save, Firestore onSnapshot in the parent
   component reflects the change automatically.
   ═══════════════════════════════════════════════════════════════ */

interface LenderRatesAdminProps {
  rates: LenderRate[];
  phaseColor?: string;
}

interface DraftRate {
  id: string;
  name: string;
  interestRate: string;
  points: string;
  lenderFeesDollars: string;
}

function toDraft(r: LenderRate): DraftRate {
  return {
    id:                r.id,
    name:              r.name,
    interestRate:      r.interestRate.toString(),
    points:            r.points.toString(),
    lenderFeesDollars: (r.lenderFeesCents / 100).toString(),
  };
}

export function LenderRatesAdmin({ rates, phaseColor = '#7A9EAA' }: LenderRatesAdminProps) {
  const [open, setOpen]     = useState(false);
  const [drafts, setDrafts] = useState<DraftRate[]>([]);
  const [saving, setSaving] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError]   = useState<string | null>(null);

  function openEditor() {
    setDrafts(rates.map(toDraft));
    setSuccess(false);
    setError(null);
    setOpen(true);
  }

  function updateDraft(idx: number, field: keyof DraftRate, value: string) {
    setDrafts((prev) => {
      const next = [...prev];
      next[idx] = { ...next[idx], [field]: value };
      return next;
    });
  }

  async function handleSave() {
    setSaving(true);
    setError(null);
    try {
      const payload = drafts.map((d) => {
        const interestRate    = parseFloat(d.interestRate);
        const points          = parseFloat(d.points);
        const lenderFeesCents = Math.round(parseFloat(d.lenderFeesDollars) * 100);
        if (isNaN(interestRate) || interestRate <= 0) throw new Error(`${d.name}: interest rate must be > 0`);
        if (isNaN(points) || points < 0) throw new Error(`${d.name}: points must be ≥ 0`);
        if (isNaN(lenderFeesCents) || lenderFeesCents < 0) throw new Error(`${d.name}: lender fees must be ≥ 0`);
        return { id: d.id, name: d.name.trim(), interestRate, points, lenderFeesCents };
      });

      const token = await getAuth().currentUser?.getIdToken();
      const res = await fetch('/api/admin/lender-rates', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ rates: payload }),
      });

      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body.error || `HTTP ${res.status}`);
      }

      setSuccess(true);
      setTimeout(() => setOpen(false), 1400);
    } catch (err: any) {
      setError(err.message ?? 'Failed to save rates');
    } finally {
      setSaving(false);
    }
  }

  return (
    <>
      <button
        onClick={openEditor}
        className="flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-[0.1em] px-2.5 py-1 rounded-md border transition-colors cursor-pointer hover:opacity-80"
        style={{ borderColor: phaseColor + '40', color: phaseColor }}
        title="Update lender rates (admin only)"
      >
        <Settings className="w-3 h-3" />
        Edit Rates
      </button>

      {open && (
        <div className="fixed inset-0 z-[300] flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div
            className="w-full max-w-lg rounded-xl shadow-2xl p-6 space-y-5"
            style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-ui)' }}
          >
            <div className="flex items-center justify-between">
              <h3 className="text-sm font-bold uppercase tracking-[0.14em]" style={{ color: 'var(--text-primary)' }}>
                Update Lender Rates
              </h3>
              <button
                onClick={() => setOpen(false)}
                className="text-xs opacity-50 hover:opacity-100 cursor-pointer"
                style={{ color: 'var(--text-secondary)' }}
              >
                ✕
              </button>
            </div>

            {error && (
              <div className="flex items-start gap-2 px-4 py-3 rounded-md text-xs" style={{ background: '#FEF2F2', border: '1px solid #FECACA', color: '#DC2626' }}>
                <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
                {error}
              </div>
            )}

            {success && (
              <div className="flex items-center gap-2 px-4 py-3 rounded-md text-xs" style={{ background: '#F0FDF4', border: '1px solid #BBF7D0', color: '#15803D' }}>
                <CheckCircle2 className="w-4 h-4 shrink-0" />
                Rates updated successfully.
              </div>
            )}

            {drafts.map((d, idx) => (
              <div key={d.id} className="space-y-3 rounded-lg p-4" style={{ background: 'var(--bg-canvas)', border: '1px solid var(--border-ui)' }}>
                <p className="text-[10px] font-bold uppercase tracking-[0.14em]" style={{ color: phaseColor }}>
                  {d.id} — {d.name}
                </p>
                <div className="grid grid-cols-3 gap-3">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase tracking-[0.08em]" style={{ color: 'var(--text-secondary)' }}>Rate %</label>
                    <input
                      type="number"
                      step="0.001"
                      min="0"
                      value={d.interestRate}
                      onChange={(e) => updateDraft(idx, 'interestRate', e.target.value)}
                      className="w-full px-2.5 py-2 rounded-md text-xs border outline-none focus:ring-1"
                      style={{ borderColor: 'var(--border-ui)', background: 'var(--bg-surface)', color: 'var(--text-primary)' }}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase tracking-[0.08em]" style={{ color: 'var(--text-secondary)' }}>Points</label>
                    <input
                      type="number"
                      step="0.1"
                      min="0"
                      value={d.points}
                      onChange={(e) => updateDraft(idx, 'points', e.target.value)}
                      className="w-full px-2.5 py-2 rounded-md text-xs border outline-none focus:ring-1"
                      style={{ borderColor: 'var(--border-ui)', background: 'var(--bg-surface)', color: 'var(--text-primary)' }}
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase tracking-[0.08em]" style={{ color: 'var(--text-secondary)' }}>Fees $</label>
                    <input
                      type="number"
                      step="50"
                      min="0"
                      value={d.lenderFeesDollars}
                      onChange={(e) => updateDraft(idx, 'lenderFeesDollars', e.target.value)}
                      className="w-full px-2.5 py-2 rounded-md text-xs border outline-none focus:ring-1"
                      style={{ borderColor: 'var(--border-ui)', background: 'var(--bg-surface)', color: 'var(--text-primary)' }}
                    />
                  </div>
                </div>
              </div>
            ))}

            <p className="text-[10px]" style={{ color: 'var(--text-secondary)' }}>
              Each rate is stamped with today's date as its <em>asOf</em> timestamp, clearing any stale indicator.
            </p>

            <div className="flex justify-end gap-3 pt-1">
              <button
                onClick={() => setOpen(false)}
                className="px-4 py-2 rounded-md text-[10px] font-bold uppercase tracking-[0.1em] border transition-colors cursor-pointer"
                style={{ borderColor: 'var(--border-ui)', color: 'var(--text-secondary)' }}
              >
                Cancel
              </button>
              <button
                onClick={handleSave}
                disabled={saving || success}
                className="px-4 py-2 rounded-md text-[10px] font-bold uppercase tracking-[0.1em] flex items-center gap-2 transition-opacity hover:opacity-90 disabled:opacity-50 cursor-pointer"
                style={{ background: phaseColor, color: '#fff' }}
              >
                {saving ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Save className="w-3.5 h-3.5" />}
                {saving ? 'Saving…' : 'Save Rates'}
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
}

import React, { useState, useRef } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { LoanStatus, RoleLinkedDocument } from '@/types/schema';
import { ref, uploadBytes, getDownloadURL } from 'firebase/storage';
import { storage } from '@/lib/firebase/config';
import { Loader2, UploadCloud, File as FileIcon, CheckCircle } from 'lucide-react';
import toast from 'react-hot-toast';

const STATUSES: LoanStatus[] = [
  'Pre-Approved',
  'In-Underwriting',
  'Appraisal-Ordered',
  'Clear-To-Close'
];

export const LoanProcessingPipeline: React.FC = () => {
  const currentProject = useProjectStore((s) => s.currentProject);
  const updateLoanStatus = useProjectStore((s) => s.updateLoanStatus);
  const updateRoleDocuments = useProjectStore((s) => s.updateRoleDocuments);

  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [isUploading, setIsUploading] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  if (!currentProject) return null;

  const handleStatusClick = (status: LoanStatus) => {
    updateLoanStatus(currentProject.id, status);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      setSelectedFile(e.target.files[0]);
    }
  };

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedFile) {
      toast.error('Please select a file to upload.');
      return;
    }

    setIsUploading(true);

    try {
      const fileRef = ref(storage, `projects/${currentProject.id}/financing/${Date.now()}_${selectedFile.name}`);
      const snapshot = await uploadBytes(fileRef, selectedFile);
      const downloadUrl = await getDownloadURL(snapshot.ref);

      const newDoc: RoleLinkedDocument = {
        id: crypto.randomUUID(),
        category: 'Financing' as any,
        fileName: selectedFile.name,
        fileUrl: downloadUrl,
        linkedRole: 'Loan Officer/Broker',
        uploadedAt: new Date(),
        verified: false,
        notes: ''
      };

      const existingDocs = currentProject.roleLinkedDocuments || [];
      updateRoleDocuments(currentProject.id, [...existingDocs, newDoc]);

      toast.success('Document securely uploaded!');
      setSelectedFile(null);
      if (fileInputRef.current) {
        fileInputRef.current.value = '';
      }
    } catch (error) {
      console.error('Upload failed:', error);
      toast.error('Failed to upload document.');
    } finally {
      setIsUploading(false);
    }
  };

  const loanDocs = (currentProject.roleLinkedDocuments || []).filter(
    (d) => d.linkedRole === 'Loan Officer/Broker'
  );

  return (
    <div className="p-6 bg-bg-surface rounded-xl shadow-sm border border-border-accent h-full flex flex-col">
      <h2 className="text-xl font-semibold mb-6 text-text-primary">Loan Processing Pipeline</h2>

      <div className="flex justify-between items-center bg-bg-primary p-2 rounded-lg border border-border-accent mb-8 overflow-x-auto gap-2">
        {STATUSES.map((status, index) => {
          const loanStatus = currentProject.loanStatus || 'Pre-Approved';
          const isActive = loanStatus === status;
          const isPast = STATUSES.indexOf(loanStatus) >= index && !isActive;

          return (
            <button
              key={status}
              onClick={() => handleStatusClick(status)}
              className={`flex-1 min-w-[130px] py-3 px-2 rounded-md text-sm font-medium transition-all text-center relative whitespace-nowrap cursor-pointer ${
                isActive
                  ? 'bg-blue-600 text-white shadow-md'
                  : isPast
                  ? 'bg-blue-100 text-blue-800 hover:bg-blue-200'
                  : 'bg-bg-surface text-text-secondary hover:bg-bg-primary'
              }`}
            >
              {status}
              {isPast && (
                <div className="absolute top-1/2 -right-3 -translate-y-1/2 text-blue-400 z-10 w-6 h-6 bg-blue-100 rounded-full flex items-center justify-center">
                  <CheckCircle className="w-4 h-4 ml-0.5" />
                </div>
              )}
            </button>
          );
        })}
      </div>

      <div className="bg-bg-primary p-5 rounded-lg border border-border-accent flex-1">
        <h3 className="text-lg font-medium text-text-primary mb-4">Lender Document Sub-Vault</h3>

        <form onSubmit={handleUpload} className="flex gap-4 mb-6">
          <div className="flex-1 relative">
            <input
              type="file"
              ref={fileInputRef}
              onChange={handleFileChange}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10"
              accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"
            />
            <div className={`w-full px-4 py-2 border rounded-lg flex items-center gap-3 transition-colors ${selectedFile ? 'border-blue-500 bg-blue-50/10' : 'border-border-accent bg-bg-surface'}`}>
              <UploadCloud className={`w-5 h-5 ${selectedFile ? 'text-blue-500' : 'text-text-secondary'}`} />
              <span className={`text-sm truncate ${selectedFile ? 'text-text-primary font-medium' : 'text-text-secondary'}`}>
                {selectedFile ? selectedFile.name : 'Click to select W2, Bank Statements, etc.'}
              </span>
            </div>
          </div>
          <button 
            type="submit" 
            disabled={!selectedFile || isUploading}
            className={`px-6 py-2 rounded-lg font-medium transition-all flex items-center gap-2 ${
              !selectedFile || isUploading 
                ? 'bg-gray-200 text-gray-500 cursor-not-allowed dark:bg-gray-800 dark:text-gray-400' 
                : 'bg-gray-900 text-white hover:bg-gray-800 shadow-sm cursor-pointer'
            }`}
          >
            {isUploading ? <Loader2 className="w-4 h-4 animate-spin" /> : 'Upload'}
          </button>
        </form>

        <div className="space-y-3 max-h-[300px] overflow-y-auto pr-2">
          {loanDocs.length === 0 ? (
            <p className="text-sm text-text-secondary italic text-center py-6 bg-bg-surface rounded border border-dashed border-border-accent">
              No lender documents uploaded yet.
            </p>
          ) : (
            loanDocs.map(doc => (
              <div key={doc.id} className="flex justify-between items-center p-3 bg-bg-surface border border-border-accent rounded-lg group hover:border-blue-300 transition-colors">
                <div className="flex items-center gap-3 overflow-hidden">
                  <FileIcon className="w-5 h-5 text-blue-500 flex-shrink-0" />
                  <a 
                    href={doc.fileUrl || '#'} 
                    target="_blank" 
                    rel="noopener noreferrer"
                    className="font-medium text-text-primary text-sm truncate hover:text-blue-600 transition-colors"
                  >
                    {doc.fileName}
                  </a>
                </div>
                <div className="flex items-center gap-4 flex-shrink-0">
                  <span className="text-xs text-text-secondary hidden sm:block">
                    {doc.uploadedAt ? new Date(doc.uploadedAt).toLocaleDateString() : 'Just now'}
                  </span>
                  <span className={`px-2.5 py-1 rounded-md text-[10px] font-bold tracking-wider uppercase border ${doc.verified ? 'bg-pw-success-container text-pw-success border-pw-success-border/50' : 'bg-yellow-500/15 text-yellow-400 border-pw-success-border/50'}`}>
                    {doc.verified ? 'Verified' : 'Pending'}
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { Negotiation } from '@/types/schema';

export const NegotiationLedger: React.FC = () => {
  const currentProject = useProjectStore((s) => s.currentProject);
  const submitOffer = useProjectStore((s) => s.submitOffer);
  const logCounterOffer = useProjectStore((s) => s.logCounterOffer);

  const [offerAmount, setOfferAmount] = useState<number | ''>('');
  const [emd, setEmd] = useState<number | ''>('');
  const [notes, setNotes] = useState('');

  if (!currentProject) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!offerAmount || !emd) return;

    submitOffer(currentProject.id, {
      offerAmount: Number(offerAmount),
      earnestMoneyDeposit: Number(emd),
      status: 'Pending',
      notes
    });

    setOfferAmount('');
    setEmd('');
    setNotes('');
  };

  const handleStatusUpdate = (negId: string, status: Negotiation['status'], counterOffer?: number) => {
    logCounterOffer(currentProject.id, negId, counterOffer || 0, status);
  };

  return (
    <div className="p-6 bg-bg-surface rounded-xl shadow-sm border border-border-accent">
      <h2 className="text-xl font-semibold mb-4 text-text-primary">Negotiation Ledger</h2>

      <div className="space-y-4 mb-8 max-h-[400px] overflow-y-auto pr-2">
        {currentProject.negotiations?.map((neg) => (
          <div key={neg.id} className="p-4 rounded-lg bg-bg-primary border border-border-accent">
            <div className="flex justify-between items-start mb-2">
              <div>
                <span className="text-sm text-text-secondary">{new Date(neg.date).toLocaleDateString()}</span>
                <h3 className="font-medium text-text-primary">Offer: ${(neg.offerAmount).toLocaleString()}</h3>
                <p className="text-sm text-text-secondary">EMD: ${(neg.earnestMoneyDeposit).toLocaleString()}</p>
                {neg.counterOffer ? <p className="text-sm font-medium text-orange-600 mt-1">Counter: ${(neg.counterOffer).toLocaleString()}</p> : null}
                {neg.notes && <p className="text-sm text-text-secondary mt-2 italic">"{neg.notes}"</p>}
              </div>
              <span className={`px-3 py-1 rounded-full text-xs font-medium ${
                neg.status === 'Accepted' ? 'bg-green-100 text-green-800' :
                neg.status === 'Rejected' ? 'bg-red-100 text-red-800' :
                'bg-yellow-100 text-yellow-800'
              }`}>
                {neg.status}
              </span>
            </div>

            {neg.status === 'Pending' && (
              <div className="mt-4 pt-4 border-t border-border-accent flex gap-2">
                <button
                  onClick={() => handleStatusUpdate(neg.id, 'Accepted')}
                  className="px-3 py-1.5 bg-green-50 text-green-700 hover:bg-green-100 rounded-md text-sm transition-colors cursor-pointer"
                >
                  Accept
                </button>
                <button
                  onClick={() => handleStatusUpdate(neg.id, 'Rejected')}
                  className="px-3 py-1.5 bg-red-50 text-red-700 hover:bg-red-100 rounded-md text-sm transition-colors cursor-pointer"
                >
                  Reject
                </button>
                <button
                  onClick={() => {
                    const counter = prompt('Enter counter offer amount:');
                    if (counter && !isNaN(Number(counter))) {
                      handleStatusUpdate(neg.id, 'Pending', Number(counter));
                    }
                  }}
                  className="px-3 py-1.5 bg-blue-50 text-blue-700 hover:bg-blue-100 rounded-md text-sm transition-colors cursor-pointer"
                >
                  Log Counter
                </button>
              </div>
            )}
          </div>
        ))}
        {(!currentProject.negotiations || currentProject.negotiations.length === 0) && (
          <div className="text-center py-8 text-text-secondary bg-bg-primary rounded-lg border border-dashed border-border-accent">
            No negotiations logged yet.
          </div>
        )}
      </div>

      <div className="pt-6 border-t border-border-accent">
        <h3 className="font-medium text-text-primary mb-4">Submit New Offer</h3>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium text-text-primary mb-1">Offer Amount</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary">$</span>
                <input
                  type="number"
                  required
                  value={offerAmount}
                  onChange={(e) => setOfferAmount(Number(e.target.value) || '')}
                  className="w-full pl-8 pr-3 py-2 border border-border-accent rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                  placeholder="0"
                />
              </div>
            </div>
            <div>
              <label className="block text-sm font-medium text-text-primary mb-1">Earnest Money Deposit</label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-text-secondary">$</span>
                <input
                  type="number"
                  required
                  value={emd}
                  onChange={(e) => setEmd(Number(e.target.value) || '')}
                  className="w-full pl-8 pr-3 py-2 border border-border-accent rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all"
                  placeholder="0"
                />
              </div>
            </div>
          </div>
          <div>
            <label className="block text-sm font-medium text-text-primary mb-1">Notes</label>
            <textarea
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={2}
              className="w-full px-3 py-2 border border-border-accent rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent outline-none transition-all resize-none"
              placeholder="Terms, conditions, target delivery date..."
            />
          </div>
          <button
            type="submit"
            className="w-full py-2.5 bg-gray-900 text-white rounded-lg hover:bg-gray-800 focus:ring-4 focus:ring-gray-200 transition-all font-medium cursor-pointer"
          >
            Log Offer
          </button>
        </form>
      </div>
    </div>
  );
};

