'use client';

import { useState } from 'react';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';
import { Mail, KeyRound, CheckCircle2, AlertCircle, RefreshCw, Send, HelpCircle } from 'lucide-react';

export default function ClaimHistorySection() {
  const { user, profile } = useAuth();
  const [emailToClaim, setEmailToClaim] = useState('');
  const [verificationCode, setVerificationCode] = useState('');
  const [step, setStep] = useState<'start' | 'verify' | 'success'>('start');
  const [loading, setLoading] = useState(false);

  const claimedEmails = profile?.claimedEmails || [];

  const handleStartClaim = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!emailToClaim || !emailToClaim.trim()) return;

    setLoading(true);
    try {
      const idToken = await user?.getIdToken();
      if (!idToken) {
        toast.error('You must be signed in.');
        setLoading(false);
        return;
      }

      const res = await fetch('/api/identity/claim/start', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({ claimEmail: emailToClaim.trim() }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Failed to start claim.');
      }

      toast.success('Verification code sent successfully!');
      setStep('verify');
    } catch (err: any) {
      toast.error(err.message || 'An error occurred.');
    } finally {
      setLoading(false);
    }
  };

  const handleVerifyClaim = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!verificationCode || !verificationCode.trim()) return;

    setLoading(true);
    try {
      const idToken = await user?.getIdToken();
      if (!idToken) {
        toast.error('You must be signed in.');
        setLoading(false);
        return;
      }

      const res = await fetch('/api/identity/claim/verify', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          claimEmail: emailToClaim.trim(),
          code: verificationCode.trim(),
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Failed to verify code.');
      }

      toast.success(data.message || 'Identity claimed successfully!');
      setStep('success');
    } catch (err: any) {
      toast.error(err.message || 'An error occurred.');
    } finally {
      setLoading(false);
    }
  };

  const handleReset = () => {
    setEmailToClaim('');
    setVerificationCode('');
    setStep('start');
  };

  if (!user) return null;

  return (
    <section className="col-span-12 glass-card rounded-2xl p-8 border border-white/5 relative overflow-hidden flex flex-col justify-between">
      {/* Ambient glow effect */}
      <div className="absolute -top-24 -right-24 w-64 h-64 bg-pw-primary/5 rounded-full blur-[120px] pointer-events-none" />

      {/* Header */}
      <div className="flex items-center justify-between border-b border-white/10 pb-4 mb-6">
        <div className="flex items-center gap-2.5">
          <span className="material-symbols-outlined text-pw-primary text-xl select-none">history</span>
          <h4 className="text-2xl font-bold text-pw-black tracking-tight">Claim Prior Email History</h4>
        </div>
      </div>

      <p className="text-sm text-pw-muted/95 mb-6 leading-relaxed max-w-2xl">
        Did you receive deal invitations, commitments, or team workspace invites under a different email address? 
        Claim that email to merge its transaction history and permissions into this account.
      </p>

      {/* Form content */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-start mb-6">
        <div>
          {step === 'start' && (
            <form onSubmit={handleStartClaim} className="space-y-4">
              <div>
                <label className="block text-xs font-semibold text-pw-muted uppercase tracking-wider mb-2">
                  Email Address to Claim
                </label>
                <div className="relative">
                  <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-pw-muted/50">
                    <Mail className="w-4 h-4" />
                  </span>
                  <input
                    type="email"
                    value={emailToClaim}
                    onChange={(e) => setEmailToClaim(e.target.value)}
                    placeholder="prior-email@example.com"
                    required
                    disabled={loading}
                    className="glass-input w-full text-sm pl-11 pr-4 py-3 text-pw-black placeholder:text-pw-muted/40"
                  />
                </div>
              </div>

              <button
                type="submit"
                disabled={loading || !emailToClaim}
                className="luminous-button w-full inline-flex items-center justify-center gap-2 font-semibold text-sm uppercase tracking-wider px-8 py-3.5 rounded-xl disabled:opacity-50 cursor-pointer transition-all duration-300 hover:scale-[1.01]"
              >
                {loading ? (
                  <RefreshCw className="w-4 h-4 animate-spin" />
                ) : (
                  <Send className="w-4 h-4" />
                )}
                Request Verification Code
              </button>
            </form>
          )}

          {step === 'verify' && (
            <form onSubmit={handleVerifyClaim} className="space-y-4">
              <div className="bg-pw-primary/5 border border-pw-primary/10 rounded-xl p-4 mb-4 flex gap-3">
                <HelpCircle className="w-5 h-5 text-pw-primary shrink-0 mt-0.5" />
                <p className="text-xs text-pw-muted leading-relaxed">
                  We sent a 6-digit verification code to <strong>{emailToClaim}</strong>. 
                  Check your inbox and enter it below to confirm you own this address.
                </p>
              </div>

              <div>
                <label className="block text-xs font-semibold text-pw-muted uppercase tracking-wider mb-2">
                  6-Digit Code
                </label>
                <div className="relative">
                  <span className="absolute left-3.5 top-1/2 -translate-y-1/2 text-pw-muted/50">
                    <KeyRound className="w-4 h-4" />
                  </span>
                  <input
                    type="text"
                    value={verificationCode}
                    onChange={(e) => setVerificationCode(e.target.value)}
                    placeholder="123456"
                    required
                    maxLength={6}
                    disabled={loading}
                    className="glass-input w-full text-sm pl-11 pr-4 py-3 tracking-[0.2em] font-mono text-pw-black placeholder:text-pw-muted/30 placeholder:tracking-normal"
                  />
                </div>
              </div>

              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={handleReset}
                  disabled={loading}
                  className="glass-button w-1/3 text-xs font-semibold uppercase tracking-wider py-3.5 rounded-xl border border-white/10 hover:bg-white/5 transition-all text-pw-black"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={loading || verificationCode.length < 6}
                  className="luminous-button w-2/3 inline-flex items-center justify-center gap-2 font-semibold text-sm uppercase tracking-wider py-3.5 rounded-xl disabled:opacity-50 cursor-pointer transition-all duration-300 hover:scale-[1.01]"
                >
                  {loading ? (
                    <RefreshCw className="w-4 h-4 animate-spin" />
                  ) : (
                    <CheckCircle2 className="w-4 h-4" />
                  )}
                  Verify & Claim
                </button>
              </div>
            </form>
          )}

          {step === 'success' && (
            <div className="space-y-4 text-center py-6 px-4 bg-emerald-500/5 border border-emerald-500/20 rounded-2xl">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-emerald-500/10 text-emerald-500 mb-2">
                <CheckCircle2 className="w-6 h-6 animate-bounce" />
              </div>
              <h5 className="text-lg font-bold text-pw-black">Identity History Merged</h5>
              <p className="text-xs text-pw-muted leading-relaxed max-w-sm mx-auto">
                Success! The transaction records, invitations, and permissions for <strong>{emailToClaim}</strong> have been linked to your profile.
              </p>
              <button
                type="button"
                onClick={handleReset}
                className="mt-4 text-xs font-semibold text-pw-primary hover:underline uppercase tracking-wider"
              >
                Claim Another Email
              </button>
            </div>
          )}
        </div>

        {/* Claimed list */}
        <div className="bg-pw-glass-bg/30 border border-white/5 rounded-2xl p-6 h-full flex flex-col justify-between">
          <div>
            <h5 className="text-xs font-semibold text-pw-muted uppercase tracking-wider mb-4 flex items-center gap-1.5 border-b border-white/5 pb-2">
              <CheckCircle2 className="w-4 h-4 text-pw-primary" />
              Claimed Email History
            </h5>

            {claimedEmails.length === 0 ? (
              <div className="py-8 text-center text-xs text-pw-muted/65 italic">
                No external email histories claimed yet.
              </div>
            ) : (
              <ul className="space-y-2.5 max-h-[160px] overflow-y-auto pr-1">
                {claimedEmails.map((email: string, idx: number) => (
                  <li 
                    key={idx} 
                    className="flex items-center justify-between text-sm px-3.5 py-2.5 rounded-xl bg-pw-glass-bg/60 border border-white/5"
                  >
                    <span className="text-pw-black font-medium">{email}</span>
                    <span className="inline-flex items-center gap-1 text-[10px] uppercase tracking-wider font-semibold text-emerald-500 bg-emerald-500/10 px-2.5 py-1 rounded-full">
                      <span className="w-1.5 h-1.5 rounded-full bg-emerald-500 animate-pulse" />
                      Verified & Merged
                    </span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

'use client';

import React, { useState, useMemo, useEffect } from 'react';
import { useAuth } from '@/context/AuthContext';
import { advanceProjectPhaseGate } from '@/actions/gate';
import { Check, X, ShieldAlert, Sparkles, Loader2 } from 'lucide-react';
import toast from 'react-hot-toast';

interface AcquisitionPhaseGateProps {
  project: any;
  totalRaisedCents: number;
  onSuccess: () => void;
  onStageSelect?: (stageKey: string) => void;
}

// Check scorecard hash locally to match page calculations
function getScorecardInputsHash(project: any): string {
  if (!project) return '';
  const f = (project.financials || {}) as any;
  const values = [
    f.purchasePrice ?? 0,
    f.listedPrice ?? 0,
    f.projectedRehabCost ?? 0,
    f.estimatedARV ?? 0,
    f.arv ?? 0,
    f.targetCapRate ?? 0,
    f.targetCoc ?? f.targetCoCReturn ?? 0,
    f.minDscr ?? f.targetMinDSCR ?? 0,
    f.maxPurchasePrice ?? f.targetMaxPurchasePrice ?? 0,
    f.gross_rent_per_unit ?? f.monthlyGrossRent ?? f.grossRent ?? 0,
    f.vacancy_pct ?? f.vacancyRatePercent ?? f.vacancyRate ?? 0,
    f.other_income ?? f.otherIncome ?? 0,
    f.tax ?? f.taxes ?? 0,
    f.insurance ?? 0,
    f.utilities ?? 0,
    f.management ?? 0,
    f.management_pct ?? 0,
    f.maintenance ?? 0,
    f.maintenance_pct ?? f.monthlyMaintenanceReserve ?? 0,
    f.otherExpenses ?? 0,
    f.downPaymentPercent ?? 0,
    f.loanInterestRate ?? f.interestRate ?? 0,
    f.loanTermYears ?? 0,
    project.dispositionType || '',
    project.subStrategy || '',
  ];
  return values.join('|');
}

// Confetti colors
const CONFETTI_COLORS = ['#ffb703', '#fb8500', '#219ebc', '#8ecae6', '#023047', '#ffffff'];

interface ConfettiPiece {
  x: number;
  color: string;
  size: number;
  rotation: number;
  duration: number;
  delay: number;
}

export function AcquisitionPhaseGate({
  project,
  totalRaisedCents,
  onSuccess,
  onStageSelect,
}: AcquisitionPhaseGateProps) {
  const f = (project?.financials || {}) as any;
  const { user } = useAuth();
  const [overrideReason, setOverrideReason] = useState(f.overrideReason || '');
  const [submitting, setSubmitting] = useState(false);
  const [celebrate, setCelebrate] = useState(false);
  const [confettiPieces, setConfettiPieces] = useState<ConfettiPiece[]>([]);

  // Generate confetti items
  const triggerConfetti = () => {
    const pieces = Array.from({ length: 80 }, () => ({
      x: Math.random() * 100,
      color: CONFETTI_COLORS[Math.floor(Math.random() * CONFETTI_COLORS.length)],
      size: 6 + Math.random() * 12,
      rotation: Math.random() * 360,
      duration: 3 + Math.random() * 4,
      delay: Math.random() * 2,
    }));
    setConfettiPieces(pieces);
    setCelebrate(true);
  };

  // Evaluation criteria checking
  const checkStatus = useMemo(() => {
    if (!project) return { isPassed: false, criteria: [] };

    const f = (project.financials || {}) as any;

    // 1. Deal established: address, property type, entry point recorded
    const isAddressRecorded = !!(project.address?.street || project.address || project.propertyName);
    const isPropertyTypeRecorded = !!(project.assetClass || project.propertyType || project.propertyClass);
    const isEntryPointRecorded = !!(project.entryPath || f.entryPath || project.project_entry_point || project.startingPhase || project.entryPoint);
    const hasDealEstablished = isAddressRecorded && isPropertyTypeRecorded && isEntryPointRecorded;

    // 2. Underwriting complete: scorecard 2.7 rendered from live derive call
    const isTurnkey = project.condition?.toLowerCase() === 'turnkey';
    const needsRehab = !isTurnkey;
    const needsARV = !isTurnkey && project.dispositionType === 'SALE';
    const rehabOk = !needsRehab || (f.projectedRehabCost ?? 0) > 0;
    const arvOk = !needsARV || (f.estimatedARV ?? 0) > 0 || (f.arv ?? 0) > 0;
    const incomeEntered = !!(
      (f.grossRent && f.grossRent > 0) ||
      (f.gross_rent_per_unit && f.gross_rent_per_unit > 0) ||
      (f.monthlyGrossRent && f.monthlyGrossRent > 0)
    );
    const expensesEntered = !!(
      f.tax !== undefined ||
      f.taxes !== undefined ||
      f.insurance !== undefined ||
      f.utilities !== undefined ||
      f.management !== undefined ||
      f.management_pct !== undefined ||
      f.maintenance !== undefined ||
      f.maintenance_pct !== undefined ||
      f.holdingCostTaxes !== undefined ||
      f.operatingExpenseTaxes !== undefined
    );
    const hash = getScorecardInputsHash(project);
    const scorecardAcknowledged = !!f.scorecardAcknowledged && f.acknowledgedInputsHash === hash;
    const hasUnderwritingComplete = incomeEntered && expensesEntered && rehabOk && arvOk && scorecardAcknowledged;

    // 3. Strategy declared: disposition_type set
    const hasStrategyDeclared = !!project.dispositionType;

    // 4. Offer accepted at known terms: accepted_price + executed contract recorded
    const hasAcceptedOffer = f.offerStatus === 'Accepted' && (f.purchasePrice > 0 || f.finalAgreedPrice > 0 || f.renegotiatedPrice > 0) && !!(f.psaDocumentUrl || f.psaDocumentName);

    // 5. Earnest money recorded
    const hasEarnestMoneyRecorded = !!(f.emdAmount && f.emdAmount > 0) && !!(f.emdReceiptUrl || f.emdClearedDate || f.emdVerified);

    // 6. Required diligence documents for the property type on file
    const hasRequiredDocs = !!(f.psaDocumentUrl || f.psaDocumentName) &&
      (!!(f.titleDocumentUrl || f.titleDocumentName) || !!(f.inspectionReportUrl || f.inspectionReportName || f.inspections?.length));

    // 7. All contingencies satisfied/waived, and a "proceed" decision recorded
    const hasNoPendingContingencies = !project.contingencies || project.contingencies.length === 0 || 
      project.contingencies.every((c: any) => c.isSatisfied || c.isWaived);
    const hasGoDecision = f.decision !== 'terminate' && f.decision !== undefined;
    const hasContingenciesAndGo = hasNoPendingContingencies && hasGoDecision;

    // 8. Capital plan set
    const isSolo = ['all-cash solo', 'solo-financed'].includes(f.capitalPlan) || f.fundingType === 'Solo';
    const targetCents = f.equityTerms?.funding_target || f.equityTarget || 0;
    const isCapitalPlanSet = isSolo || totalRaisedCents >= targetCents;

    const criteriaList = [
      { key: 'deal_established', label: 'Deal established: address, property type, entry point recorded', status: hasDealEstablished, ref: '#target' },
      { key: 'underwriting_complete', label: 'Underwriting complete: scorecard 2.7 rendered from live derive call', status: hasUnderwritingComplete, ref: '#underwrite' },
      { key: 'strategy_declared', label: 'Strategy declared: dispositionType set', status: hasStrategyDeclared, ref: '#underwrite' },
      { key: 'offer_accepted', label: 'Offer accepted at known terms: purchase price and executed contract recorded', status: hasAcceptedOffer, ref: '#offer' },
      { key: 'earnest_money', label: 'Earnest money recorded: deposit amount and receipt proof on file', status: hasEarnestMoneyRecorded, ref: '#offer' },
      { key: 'diligence_docs', label: 'Required diligence documents on file', status: hasRequiredDocs, ref: '#due_diligence' },
      { key: 'contingencies_satisfied', label: 'All contingencies satisfied/waived with proceed go-decision', status: hasContingenciesAndGo, ref: '#due_diligence' },
      { key: 'capital_plan_set', label: 'Capital plan set: solo confirmed or LOIs logged to equity target', status: isCapitalPlanSet, ref: '#raise_interest' }
    ];

    const isPassed = criteriaList.every(c => c.status);

    return {
      isPassed,
      criteria: criteriaList,
    };
  }, [project, totalRaisedCents]);

  const handleAdvance = async () => {
    if (!user) {
      toast.error('You must be logged in.');
      return;
    }

    if (!checkStatus.isPassed && !overrideReason.trim()) {
      toast.error('Please enter an override reason to bypass criteria.');
      return;
    }

    setSubmitting(true);
    try {
      const idToken = await user.getIdToken();
      const res = await advanceProjectPhaseGate(idToken, project.id, overrideReason);
      if (res.success) {
        triggerConfetti();
        toast.success(`Deal Advanced! Composite Risk Score: ${res.riskScore}`);
        setTimeout(() => {
          onSuccess();
        }, 3000);
      }
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to advance project phase.');
    } finally {
      setSubmitting(false);
    }
  };

  const hasFailingCriteria = checkStatus.criteria.some(c => !c.status);

  return (
    <div id="phase_gate" className="glass-card rounded-2xl border border-pw-border p-6 space-y-6 relative overflow-hidden">
      {/* Confetti animations overlay */}
      {celebrate && (
        <div className="absolute inset-0 pointer-events-none z-50 overflow-hidden">
          {confettiPieces.map((piece, i) => (
            <div
              key={i}
              className="absolute w-2 h-2 rounded-sm"
              style={{
                left: `${piece.x}%`,
                top: `-20px`,
                backgroundColor: piece.color,
                width: `${piece.size}px`,
                height: `${piece.size / 2}px`,
                transform: `rotate(${piece.rotation}deg)`,
                animation: `confetti-fall ${piece.duration}s ${piece.delay}s linear forwards`,
              }}
            />
          ))}
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm animate-fade-in">
            <div className="text-center p-8 bg-[var(--color-background)] rounded-2xl border border-pw-border shadow-2xl max-w-sm space-y-4">
              <div className="w-16 h-16 bg-[var(--pw-success-container)] text-[var(--pw-success)] rounded-full flex items-center justify-center mx-auto animate-bounce">
                <Sparkles className="w-8 h-8" />
              </div>
              <h3 className="text-2xl font-bold text-[var(--color-on-surface)]">Milestone Unlocked!</h3>
              <p className="text-sm text-[var(--color-muted)]">
                Acquisition complete. Project has successfully transitioned to Phase 2: Fund!
              </p>
            </div>
          </div>
        </div>
      )}

      <div>
        <h3 className="text-lg font-bold text-[var(--color-on-surface)] flex items-center gap-2">
          <ShieldAlert className="w-5 h-5 text-[var(--color-primary)]" />
          Acquisition Phase Gate
        </h3>
        <p className="text-sm text-[var(--color-muted)] mt-1">
          Each requirement is checked dynamically against live transaction data.
        </p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {checkStatus.criteria.map((item) => (
          <div
            key={item.key}
            className="flex items-center justify-between p-3 rounded-xl border border-pw-border bg-white/5 transition-all hover:bg-white/10"
          >
            <div className="flex items-center gap-3">
              <div
                className={`w-6 h-6 rounded-full flex items-center justify-center ${
                  item.status ? 'bg-[var(--pw-success-container)] text-[var(--pw-success)]' : 'bg-red-500/20 text-red-500'
                }`}
              >
                {item.status ? <Check className="w-3.5 h-3.5" /> : <X className="w-3.5 h-3.5" />}
              </div>
              <span className="text-xs font-semibold text-[var(--color-on-surface)]">{item.label}</span>
            </div>
            <a
              href={item.ref}
              onClick={(e) => {
                e.preventDefault();
                const stageKey = item.ref.replace('#', '');
                if (onStageSelect) {
                  onStageSelect(stageKey);
                }
                setTimeout(() => {
                  const tabBtn = document.getElementById(`stage-tab-${stageKey}`);
                  if (tabBtn) {
                    tabBtn.scrollIntoView({ behavior: 'smooth', block: 'center' });
                  }
                  const panel = document.getElementById(`stage-panel-${stageKey}`);
                  if (panel) {
                    panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
                    panel.classList.add('luminous-glow-brief');
                    setTimeout(() => panel.classList.remove('luminous-glow-brief'), 2000);
                  }
                }, 100);
              }}
              className="text-xs text-[var(--color-primary)] hover:underline font-bold"
            >
              Verify
            </a>
          </div>
        ))}
      </div>

      {hasFailingCriteria && (
        <div className="p-4 rounded-xl bg-red-500/10 border border-red-500/20 space-y-3">
          <div className="flex items-center gap-2 text-xs font-bold text-red-400">
            <ShieldAlert className="w-4 h-4" />
            CRITERIA BLOCKED: Advancing requires manual override justification.
          </div>
          <textarea
            value={overrideReason}
            onChange={(e) => setOverrideReason(e.target.value)}
            placeholder="Type your justification for manual override here..."
            className="w-full h-20 text-xs p-3 rounded-lg bg-black/30 border border-pw-border text-[var(--color-on-surface)] focus:outline-none focus:border-red-500/50"
          />
        </div>
      )}

      <div className="flex items-center justify-between pt-4 border-t border-pw-border">
        <div className="text-xs text-[var(--color-muted)]">
          {checkStatus.isPassed ? (
            <span className="text-[var(--pw-success)] font-bold">✓ All criteria satisfied</span>
          ) : (
            <span className="text-red-400 font-bold">✗ {checkStatus.criteria.filter(c => !c.status).length} criteria pending</span>
          )}
        </div>

        <button
          onClick={handleAdvance}
          disabled={submitting || (!checkStatus.isPassed && !overrideReason.trim())}
          className={`flex items-center gap-2 px-6 py-3 rounded-xl text-xs font-bold transition-all disabled:opacity-50 disabled:cursor-not-allowed ${
            checkStatus.isPassed
              ? 'bg-[var(--pw-success)] hover:bg-[var(--pw-success)]/90 text-[#0d0a0b]'
              : 'bg-red-500 hover:bg-red-500/80 text-white'
          }`}
        >
          {submitting ? (
            <Loader2 className="w-4 h-4 animate-spin" />
          ) : (
            <Sparkles className="w-4 h-4" />
          )}
          {checkStatus.isPassed || !overrideReason.trim() ? 'Lock Deal & Proceed to Fund' : 'Override & Proceed to Fund'}
        </button>
      </div>

      {/* Tailwind Confetti Animations keyframes in page */}
      <style jsx global>{`
        @keyframes confetti-fall {
          0% {
            transform: translateY(-20px) rotate(0deg);
          }
          100% {
            transform: translateY(100vh) rotate(720deg);
          }
        }
      `}</style>
    </div>
  );
}

'use client';

import React from 'react';
import { ProjectTeamMember, ProjectRole } from '@/types/schema';
import { z } from 'zod';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { CheckCircle2, AlertCircle, Copy, Check } from 'lucide-react';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';

const contactSchema = z.object({
  displayName: z.string().min(1, 'Name is required'),
  firm: z.string().optional(),
  email: z.string().email('Valid email is required'),
  phoneNumber: z.string().min(1, 'Phone number is required'),
});

type ContactFormData = z.infer<typeof contactSchema>;

interface AcquisitionTeamAssemblyProps {
  projectId: string;
  teamMembers: ProjectTeamMember[];
  onRefresh: () => void;
}

const REQUIRED_ROLES: ProjectRole[] = ['Real Estate Attorney', 'Title Company/Escrow Officer'];

export function AcquisitionTeamAssembly({ projectId, teamMembers, onRefresh }: AcquisitionTeamAssemblyProps) {
  const { user } = useAuth();

  const getMemberByRole = (role: ProjectRole) => teamMembers.find(m => m.projectRole === role && m.status !== 'removed');

  const handleSaveMember = async (role: ProjectRole, data: ContactFormData) => {
    if (!user) {
      toast.error('Not authenticated');
      return;
    }

    const existingMember = teamMembers.find(m => m.projectRole === role && m.status !== 'removed');
    const actionType = existingMember ? 'update_member' : 'add';

    const toastId = toast.loading('Saving contact details...');
    try {
      const idToken = await user.getIdToken();
      const { mutateProjectTeam } = await import('@/actions');
      const res = await mutateProjectTeam(idToken, projectId, actionType, {
        email: data.email,
        displayName: data.displayName,
        projectRole: role,
        phoneNumber: data.phoneNumber,
        firm: data.firm,
        memberId: existingMember?.id,
        permissions: { canView: true, canUpload: false, canComment: false },
      });

      if (res.success) {
        toast.success(`Saved contact for ${role}`, { id: toastId });
        onRefresh();
      }
    } catch (err: any) {
      toast.error(err.message || 'Failed to update team member.', { id: toastId });
    }
  };

  return (
    <div className="rounded-lg border shadow-sm" style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}>
      <div className="px-6 py-4 border-b" style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}>
        <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>Investment Team Assembly</h2>
        <p className="text-sm mt-1" style={{ color: 'var(--text-secondary)' }}>
          Assign required team members to proceed with the transaction.
        </p>
      </div>

      <div className="p-6 space-y-6">
        {REQUIRED_ROLES.map((role) => (
          <TeamMemberCard 
            key={role} 
            role={role} 
            member={getMemberByRole(role)} 
            onSave={(data) => handleSaveMember(role, data)} 
          />
        ))}
      </div>
    </div>
  );
}

function TeamMemberCard({ 
  role, 
  member, 
  onSave 
}: { 
  role: ProjectRole; 
  member?: ProjectTeamMember; 
  onSave: (data: ContactFormData) => void;
}) {
  const [isEditing, setIsEditing] = React.useState(!member);

  const { register, handleSubmit, formState: { errors } } = useForm<ContactFormData>({
    resolver: zodResolver(contactSchema),
    defaultValues: {
      displayName: member?.displayName || '',
      firm: member?.firm || '',
      email: member?.email || '',
      phoneNumber: member?.phoneNumber || '',
    }
  });

  const onSubmit = (data: ContactFormData) => {
    onSave(data);
    setIsEditing(false);
  };

  return (
    <div className="rounded-xl p-5 shadow-md transition-shadow hover:shadow-lg" style={{ border: '1px solid var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}>
      <div className="flex items-center justify-between mb-4">
        <h3 className="font-medium text-base flex items-center gap-2" style={{ color: 'var(--text-primary)' }}>
          {role}
          {member && !isEditing ? (
            <CheckCircle2 className="w-4 h-4 text-green-500" />
          ) : (
            <AlertCircle className="w-4 h-4 text-amber-500" />
          )}
        </h3>
        {member && !isEditing && (
          <button 
            type="button" 
            onClick={() => setIsEditing(true)}
            className="text-sm underline"
            style={{ color: 'var(--text-secondary)' }}
          >
            Edit
          </button>
        )}
      </div>

      {isEditing ? (
        <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>Full Name *</label>
              <input 
                {...register('displayName')}
                className="glass-input w-full px-3 py-2 text-sm"
                style={{ color: 'var(--text-primary)' }}
                placeholder="Jane Doe"
                aria-invalid={!!errors.displayName}
              />
              {errors.displayName && <p className="text-xs pw-error-text">{errors.displayName.message}</p>}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>Firm / Company</label>
              <input 
                {...register('firm')}
                className="glass-input w-full px-3 py-2 text-sm"
                style={{ color: 'var(--text-primary)' }}
                placeholder="ABC Law Firm"
                aria-invalid={!!errors.firm}
              />
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>Email Address *</label>
              <input 
                {...register('email')}
                className="glass-input w-full px-3 py-2 text-sm"
                style={{ color: 'var(--text-primary)' }}
                placeholder="jane@example.com"
                aria-invalid={!!errors.email}
              />
              {errors.email && <p className="text-xs pw-error-text">{errors.email.message}</p>}
            </div>

            <div className="space-y-2">
              <label className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>Phone Number</label>
              <input 
                {...register('phoneNumber')}
                className="glass-input w-full px-3 py-2 text-sm"
                style={{ color: 'var(--text-primary)' }}
                placeholder="(555) 123-4567"
                aria-invalid={!!errors.phoneNumber}
              />
              {errors.phoneNumber && <p className="text-xs pw-error-text">{errors.phoneNumber.message}</p>}
            </div>
          </div>

          <div className="flex justify-end gap-2 mt-4">
            {member && (
              <button 
                type="button"
                onClick={() => setIsEditing(false)}
                className="px-4 py-2 border rounded-md text-sm hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                style={{ borderColor: 'var(--border-ui)', color: 'var(--text-primary)' }}
              >
                Cancel
              </button>
            )}
            <button 
              type="submit"
              className="px-4 py-2 rounded-md text-sm font-medium text-white transition-colors"
              style={{ backgroundColor: 'var(--text-primary)' }}
            >
              Save Contact
            </button>
          </div>
        </form>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-6 text-sm">
          <div>
            <p className="font-medium text-xs uppercase tracking-wider mb-1" style={{ color: 'var(--text-secondary)' }}>Name & Firm</p>
            <p className="font-semibold text-base" style={{ color: 'var(--text-primary)' }}>{member?.displayName}</p>
            {member?.firm && <p className="text-sm" style={{ color: 'var(--text-secondary)' }}>{member.firm}</p>}
          </div>
          <div className="flex flex-col gap-3">
            <div>
              <p className="font-medium text-xs uppercase tracking-wider mb-1" style={{ color: 'var(--text-secondary)' }}>Email</p>
              <div className="flex items-center gap-2">
                <p style={{ color: 'var(--text-primary)' }}>{member?.email}</p>
                <CopyButton textToCopy={member?.email || ''} />
              </div>
            </div>
            <div>
              <p className="font-medium text-xs uppercase tracking-wider mb-1" style={{ color: 'var(--text-secondary)' }}>Phone</p>
              <div className="flex items-center gap-2">
                <p style={{ color: 'var(--text-primary)' }}>{member?.phoneNumber || '—'}</p>
                {member?.phoneNumber && <CopyButton textToCopy={member.phoneNumber} />}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

function CopyButton({ textToCopy }: { textToCopy: string }) {
  const [copied, setCopied] = React.useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(textToCopy);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Failed to copy', err);
    }
  };

  return (
    <button
      onClick={handleCopy}
      className="p-1.5 rounded-md hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors border border-transparent hover:border-gray-200 dark:hover:border-gray-700"
      title="Copy to clipboard"
    >
      {copied ? (
        <Check className="w-3.5 h-3.5 text-green-600" />
      ) : (
        <Copy className="w-3.5 h-3.5 text-gray-400 dark:text-gray-500 hover:text-gray-600 dark:hover:text-gray-300" />
      )}
    </button>
  );
}

