'use client';

import React, { useState, useEffect } from 'react';
import { Calendar, FileText, CheckCircle, Clock, Trash2, Info, Landmark } from 'lucide-react';
import type { Project } from '@/types/schema';
import toast from 'react-hot-toast';
import { uploadFile } from '@/lib/storage/uploadService';
import { IS_DEMO_MODE } from '@/lib/config/demo';

interface AttorneyCardProps {
  project: Project;
  onSaveFinancials: (updates: any) => Promise<void>;
  phaseColor?: string;
  readOnly?: boolean;
}

export function AttorneyCard({
  project,
  onSaveFinancials,
  phaseColor = '#595959',
  readOnly = false,
}: AttorneyCardProps) {
  const financials = project.financials || {};

  // Local Form states
  const [vendor, setVendor] = useState(financials.attorneyVendor || '');
  const [orderedDate, setOrderedDate] = useState(financials.attorneyOrderedDate || '');
  const [completedDate, setCompletedDate] = useState(financials.attorneyCompletedDate || '');
  const [findings, setFindings] = useState(financials.attorneyFindings || '');
  const [waived, setWaived] = useState(!!financials.attorneyWaived);
  const [waiverReason, setWaiverReason] = useState(financials.attorneyWaiverReason || '');

  // File Upload states
  const [uploadingDoc, setUploadingDoc] = useState(false);

  // Sync state with project updates
  useEffect(() => {
    setVendor(financials.attorneyVendor || '');
    setOrderedDate(financials.attorneyOrderedDate || '');
    setCompletedDate(financials.attorneyCompletedDate || '');
    setFindings(financials.attorneyFindings || '');
    setWaived(!!financials.attorneyWaived);
    setWaiverReason(financials.attorneyWaiverReason || '');
  }, [project]);

  const handleSaveField = async (fieldName: string, value: any) => {
    try {
      await onSaveFinancials({ [fieldName]: value });
    } catch (err) {
      console.error(`Failed to save ${fieldName}:`, err);
      toast.error('Failed to save changes');
    }
  };

  const handleUploadDoc = async () => {
    if (readOnly) return;

    if (IS_DEMO_MODE) {
      setUploadingDoc(true);
      await new Promise((resolve) => setTimeout(resolve, 1000));
      try {
        await onSaveFinancials({
          attorneyDocumentUrl: '/mock/documents/Attorney_Opinion_Letter.pdf',
          attorneyDocumentName: 'Attorney_Opinion_Letter.pdf',
        });
        toast.success('Attorney opinion letter uploaded! (Demo)');
      } catch (err) {
        console.error('Failed to upload Attorney opinion:', err);
        toast.error('Failed to upload Attorney opinion');
      } finally {
        setUploadingDoc(false);
      }
      return;
    }

    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.pdf,image/*';
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setUploadingDoc(true);
      const toastId = toast.loading(`Uploading ${file.name}...`);
      try {
        const res = await uploadFile({
          file,
          path: 'attorney_docs',
          projectId: project.id,
        });
        await onSaveFinancials({
          attorneyDocumentUrl: res.downloadUrl,
          attorneyDocumentName: file.name,
        });
        toast.success('Document uploaded successfully!', { id: toastId });
      } catch (err: any) {
        console.error('Upload failed:', err);
        toast.error(`Upload failed: ${err.message || 'Unknown error'}`, { id: toastId });
      } finally {
        setUploadingDoc(false);
      }
    };
    input.click();
  };

  const handleRemoveDoc = async () => {
    if (readOnly) return;
    try {
      await onSaveFinancials({
        attorneyDocumentUrl: null,
        attorneyDocumentName: null,
      });
      toast.success('Attorney opinion letter removed');
    } catch (err) {
      console.error('Failed to remove Attorney opinion:', err);
      toast.error('Failed to remove Attorney opinion');
    }
  };

  return (
    <div className="glass-card rounded-2xl p-6 border border-white/5 space-y-6 animate-in fade-in duration-300">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-white/5 pb-4">
        <div className="flex items-center gap-2">
          <Landmark className="w-5 h-5 animate-pulse" style={{ color: phaseColor }} />
          <h3 className="text-sm font-bold text-white uppercase tracking-wider">Attorney Review Tracker</h3>
        </div>
        <span className="text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider">Legal Document &amp; Close Audit</span>
      </div>

      {/* Waived Toggle */}
      <div className="flex items-center justify-between p-4 bg-white/5 border border-white/5 rounded-xl">
        <div className="flex flex-col gap-0.5">
          <span className="text-xs font-bold text-white uppercase tracking-wider">Waive Attorney Review Requirement</span>
          <span className="text-[10px] text-[#9E9DA0]/80">Waive legal counsel review for this transaction</span>
        </div>
        <button
          type="button"
          id="attorney-waive-toggle"
          disabled={readOnly}
          onClick={() => {
            const updated = !waived;
            setWaived(updated);
            handleSaveField('attorneyWaived', updated);
            if (!updated) {
              setWaiverReason('');
              handleSaveField('attorneyWaiverReason', '');
            }
          }}
          className={`px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded-lg border transition-all ${
            waived
              ? 'bg-amber-500/10 border-amber-500/30 text-amber-400 font-extrabold'
              : 'bg-white/5 border-white/5 text-[#9E9DA0] hover:bg-white/10 hover:text-white'
          }`}
        >
          {waived ? 'Waived' : 'Active'}
        </button>
      </div>

      {/* Waiver Reason Field */}
      {waived ? (
        <div className="space-y-2 animate-in fade-in slide-in-from-top-1 duration-200">
          <label className="block text-xs font-bold text-red-400 uppercase tracking-wider">
            Waiver Reason <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            id="attorney-waiver-reason"
            value={waiverReason}
            onChange={(e) => setWaiverReason(e.target.value)}
            onBlur={() => handleSaveField('attorneyWaiverReason', waiverReason)}
            disabled={readOnly}
            placeholder="Type reason for waiving attorney review (e.g. title company handles all closing legalities)"
            className="px-4 py-2 w-full bg-red-500/5 border border-red-500/20 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-red-400/50 disabled:opacity-50"
          />
        </div>
      ) : (
        <div className="space-y-6">
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {/* Attorney / Firm */}
            <div>
              <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Closing Attorney / Firm (Vendor)</label>
              <input
                type="text"
                id="attorney-vendor"
                value={vendor}
                onChange={(e) => setVendor(e.target.value)}
                onBlur={() => handleSaveField('attorneyVendor', vendor)}
                disabled={readOnly}
                placeholder="Enter attorney or law firm name"
                className="px-4 py-2 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50"
              />
            </div>

            {/* Dates */}
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Date Ordered</label>
                <input
                  type="date"
                  id="attorney-ordered-date"
                  value={orderedDate}
                  onChange={(e) => {
                    setOrderedDate(e.target.value);
                    handleSaveField('attorneyOrderedDate', e.target.value);
                  }}
                  disabled={readOnly}
                  className="px-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50"
                />
              </div>
              <div>
                <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Date Completed</label>
                <input
                  type="date"
                  id="attorney-completed-date"
                  value={completedDate}
                  onChange={(e) => {
                    setCompletedDate(e.target.value);
                    handleSaveField('attorneyCompletedDate', e.target.value);
                  }}
                  disabled={readOnly}
                  className="px-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50"
                />
              </div>
            </div>
          </div>

          {/* Structured Findings */}
          <div>
            <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Review Notes &amp; Findings</label>
            <textarea
              id="attorney-findings"
              value={findings}
              onChange={(e) => setFindings(e.target.value)}
              onBlur={() => handleSaveField('attorneyFindings', findings)}
              disabled={readOnly}
              placeholder="Detail contract review findings, title/deed exceptions review, or closing package status..."
              className="px-4 py-2 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50 h-20 resize-none"
            />
          </div>

          {/* Document Upload */}
          <div className="space-y-2 border-t border-white/5 pt-4">
            <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider">Attorney Opinion Letter / Approved Package</label>
            {financials.attorneyDocumentUrl ? (
              <div className="flex items-center justify-between p-3 bg-white/5 rounded-xl border border-white/5">
                <div className="flex items-center gap-2">
                  <FileText className="w-4 h-4 text-[#454955]" />
                  <span className="text-xs text-white font-bold">
                    {financials.attorneyDocumentName || 'Attorney_Opinion_Letter.pdf'}
                    {IS_DEMO_MODE && <span className="ml-2 text-[8px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 font-sans">Demo</span>}
                  </span>
                </div>
                {!readOnly && (
                  <button
                    onClick={handleRemoveDoc}
                    className="p-1 text-[#F06543] hover:bg-[#F06543]/10 rounded-lg transition-all"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                )}
              </div>
            ) : (
              <button
                type="button"
                id="attorney-upload-btn"
                onClick={handleUploadDoc}
                disabled={uploadingDoc || readOnly}
                className="w-full py-4 border border-dashed border-white/10 hover:border-white/20 rounded-xl flex flex-col items-center justify-center gap-2 bg-white/5 hover:bg-white/10 transition-all text-[#9E9DA0] hover:text-white disabled:opacity-50"
              >
                {uploadingDoc ? (
                  <>
                    <div className="w-5 h-5 border-2 rounded-full border-white/20 border-t-white animate-spin" />
                    <span className="text-[10px] font-bold uppercase tracking-wider">Uploading Letter...</span>
                  </>
                ) : (
                  <>
                    <FileText className="w-5 h-5" />
                    <span className="text-[10px] font-bold uppercase tracking-wider">
                      Upload Attorney Opinion Letter PDF {IS_DEMO_MODE && '(Demo)'}
                    </span>
                  </>
                )}
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { InvestorContact, ProjectFollower } from '@/types/schema';
import { Users, Mail, Phone, Upload, Trash2, ShieldAlert, CheckCircle, ToggleLeft, ToggleRight, XCircle } from 'lucide-react';
import { collection, onSnapshot, doc, writeBatch, deleteDoc, updateDoc, setDoc, query, orderBy, getDocs } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import toast from 'react-hot-toast';

interface AudienceManagerProps {
  projectId: string;
  readOnly?: boolean;
}

export function AudienceManager({ projectId, readOnly = false }: AudienceManagerProps) {
  const [contacts, setContacts] = useState<InvestorContact[]>([]);
  const [followers, setFollowers] = useState<ProjectFollower[]>([]);
  const [isImporting, setIsImporting] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // DM-37 States
  const [importSource, setImportSource] = useState<string>('');
  const [globalUnsubs, setGlobalUnsubs] = useState<string[]>([]);
  const [isAddFormOpen, setIsAddFormOpen] = useState(false);
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newPhone, setNewPhone] = useState('');
  const [newContactType, setNewContactType] = useState('Individual');
  const [newRelationship, setNewRelationship] = useState('Warm');
  const [newTicket, setNewTicket] = useState('');
  const [newSource, setNewSource] = useState('manual');

  const isE2E = typeof window !== 'undefined' && document.cookie.includes('__e2e_test');
  const contactsKey = `pw_e2e_contacts_${projectId}`;
  const followersKey = `pw_e2e_followers_${projectId}`;

  // Helper to trigger same-page reloads in E2E mode
  const triggerE2ERefresh = () => {
    window.dispatchEvent(new Event(`update_${contactsKey}`));
    window.dispatchEvent(new Event(`update_${followersKey}`));
  };

  // 1. Listen to manual contacts subcollection
  useEffect(() => {
    if (!projectId) return;

    if (isE2E) {
      const load = () => {
        try {
          const val = localStorage.getItem(contactsKey);
          setContacts(val ? JSON.parse(val) : []);
        } catch (e) {
          console.error(e);
        }
      };
      load();

      const handleStorage = (e: StorageEvent) => {
        if (e.key === contactsKey) load();
      };
      window.addEventListener('storage', handleStorage);
      const handleCustom = () => load();
      window.addEventListener(`update_${contactsKey}`, handleCustom);

      return () => {
        window.removeEventListener('storage', handleStorage);
        window.removeEventListener(`update_${contactsKey}`, handleCustom);
      };
    }

    const q = query(collection(db, 'projects', projectId, 'investor_contacts'), orderBy('createdAt', 'desc'));
    const unsub = onSnapshot(q, (snap) => {
      const docs = snap.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      })) as InvestorContact[];
      setContacts(docs);
    });
    return unsub;
  }, [projectId, isE2E]);

  // 2. Listen to followers subcollection
  useEffect(() => {
    if (!projectId) return;

    if (isE2E) {
      const load = () => {
        try {
          const val = localStorage.getItem(followersKey);
          setFollowers(val ? JSON.parse(val) : []);
        } catch (e) {
          console.error(e);
        }
      };
      load();

      const handleStorage = (e: StorageEvent) => {
        if (e.key === followersKey) load();
      };
      window.addEventListener('storage', handleStorage);
      const handleCustom = () => load();
      window.addEventListener(`update_${followersKey}`, handleCustom);

      return () => {
        window.removeEventListener('storage', handleStorage);
        window.removeEventListener(`update_${followersKey}`, handleCustom);
      };
    }

    const q = query(collection(db, 'projects', projectId, 'followers'));
    const unsub = onSnapshot(q, (snap) => {
      const docs = snap.docs.map((d) => ({
        id: d.id,
        ...d.data(),
      })) as ProjectFollower[];
      setFollowers(docs);
    });
    return unsub;
  }, [projectId, isE2E]);

  // Listen to global unsubscribes (DM-37)
  useEffect(() => {
    if (isE2E) {
      const load = () => {
        try {
          const val = localStorage.getItem('pw_e2e_global_unsubscribes');
          setGlobalUnsubs(val ? JSON.parse(val) : []);
        } catch (e) {
          console.error(e);
        }
      };
      load();
      window.addEventListener('storage', load);
      const handleCustom = () => load();
      window.addEventListener('update_pw_e2e_global_unsubscribes', handleCustom);
      return () => {
        window.removeEventListener('storage', load);
        window.removeEventListener('update_pw_e2e_global_unsubscribes', handleCustom);
      };
    }

    const unsub = onSnapshot(collection(db, 'unsubscribedEmails'), (snap) => {
      setGlobalUnsubs(snap.docs.map(d => d.id.toLowerCase()));
    });
    return unsub;
  }, [isE2E]);

  // Seed default mock followers if none exist, so counts match expectation
  useEffect(() => {
    const seedMockFollowers = async () => {
      if (!projectId) return;

      const mockFollowers: ProjectFollower[] = [
        {
          id: 'fol_1',
          name: 'Sarah Connor',
          email: 'sarah@resistance.io',
          phone: '555-0199',
          emailConsent: true,
          inAppConsent: true,
          followedAt: new Date().toISOString(),
        },
        {
          id: 'fol_2',
          name: 'John Connor',
          email: 'john@resistance.io',
          phone: '555-0100',
          emailConsent: true,
          inAppConsent: false,
          followedAt: new Date().toISOString(),
        },
        {
          id: 'fol_3',
          name: 'Investor Bob',
          email: 'bob@investor.com',
          phone: '555-0122',
          emailConsent: true,
          inAppConsent: true,
          followedAt: new Date().toISOString(),
        }
      ];

      if (isE2E) {
        try {
          const val = localStorage.getItem(followersKey);
          if (!val) {
            localStorage.setItem(followersKey, JSON.stringify(mockFollowers));
            triggerE2ERefresh();
          }
        } catch (e) {
          console.error(e);
        }
        return;
      }

      // Real Firebase seeding if none exist
      try {
        const snap = await getDocs(collection(db, 'projects', projectId, 'followers'));
        if (snap.empty) {
          for (const f of mockFollowers) {
            await setDoc(doc(db, 'projects', projectId, 'followers', f.id), f);
          }
        }
      } catch (err) {
        console.error('Failed to seed followers:', err);
      }
    };
    seedMockFollowers();
  }, [projectId, isE2E]);

  const getDeduplicatedAudience = () => {
    const map = new Map<string, {
      email: string;
      name: string;
      phone: string;
      sources: ('Contact' | 'Follower')[];
      emailConsent: boolean;
      inAppConsent: boolean;
      potentialTicket: number;
      type: string;
      relationship: string;
      contactId?: string;
      followerId?: string;
      source?: string;
      isPurchased?: boolean;
    }>();

    contacts.forEach((c) => {
      map.set(c.email.toLowerCase(), {
        email: c.email,
        name: c.name,
        phone: c.phone || '',
        sources: ['Contact'],
        emailConsent: c.emailConsent,
        inAppConsent: c.inAppConsent,
        potentialTicket: c.potentialTicket || 0,
        type: c.type || 'Individual',
        relationship: c.relationship || 'Warm',
        contactId: c.id,
        source: c.source || 'manual',
        isPurchased: c.isPurchased || false,
      });
    });

    followers.forEach((f) => {
      const emailLower = f.email.toLowerCase();
      const existing = map.get(emailLower);
      if (existing) {
        if (!existing.sources.includes('Follower')) {
          existing.sources.push('Follower');
        }
        existing.followerId = f.id;
        existing.emailConsent = existing.emailConsent && f.emailConsent;
        existing.inAppConsent = existing.inAppConsent || f.inAppConsent;
      } else {
        map.set(emailLower, {
          email: f.email,
          name: f.name,
          phone: f.phone || '',
          sources: ['Follower'],
          emailConsent: f.emailConsent,
          inAppConsent: f.inAppConsent,
          potentialTicket: 0,
          type: 'Individual',
          relationship: 'Follower Edge',
          followerId: f.id,
        });
      }
    });

    return Array.from(map.values());
  };

  const deduplicatedAudience = getDeduplicatedAudience();

  const totalAudience = deduplicatedAudience.length;
  const emailConsentedCount = deduplicatedAudience.filter((a) => a.emailConsent).length;
  const inAppConsentedCount = deduplicatedAudience.filter((a) => a.inAppConsent).length;

  const handleImportClick = () => {
    if (!importSource) {
      toast.error('Please specify the Import Source of the list before uploading.');
      return;
    }
    fileInputRef.current?.click();
  };

  const handleAddContact = async (e: React.FormEvent) => {
    e.preventDefault();
    const emailLower = newEmail.trim().toLowerCase();
    if (!newName.trim() || !emailLower) {
      toast.error('Name and Email are required.');
      return;
    }
    if (!emailLower.includes('@')) {
      toast.error('Invalid email address.');
      return;
    }
    if (!newSource) {
      toast.error('Please specify the source of the contact.');
      return;
    }
    if (globalUnsubs.includes(emailLower)) {
      toast.error('This email address has opted out of platform communications.');
      return;
    }

    const potentialTicket = newTicket ? Math.round(parseFloat(newTicket) * 100) : 0;
    const contactId = `contact_${Date.now()}`;
    const newContact: InvestorContact = {
      id: contactId,
      name: newName,
      email: emailLower,
      phone: newPhone,
      type: newContactType,
      relationship: newRelationship,
      potentialTicket: isNaN(potentialTicket) ? 0 : potentialTicket,
      emailConsent: true,
      inAppConsent: true,
      source: newSource,
      isPurchased: newSource === 'import_purchased',
      createdAt: new Date().toISOString(),
    };

    try {
      if (isE2E) {
        const existing = JSON.parse(localStorage.getItem(contactsKey) || '[]');
        localStorage.setItem(contactsKey, JSON.stringify([newContact, ...existing]));
        triggerE2ERefresh();
      } else {
        await setDoc(doc(db, 'projects', projectId, 'investor_contacts', contactId), newContact);
      }
      toast.success('Successfully added contact!');
      setNewName('');
      setNewEmail('');
      setNewPhone('');
      setNewTicket('');
      setNewContactType('Individual');
      setNewRelationship('Warm');
      setNewSource('manual');
      setIsAddFormOpen(false);
    } catch (err) {
      console.error(err);
      toast.error('Failed to add contact.');
    }
  };

  const handleCSVUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!importSource) {
      toast.error('Please specify the Import Source of the list.');
      return;
    }

    const reader = new FileReader();
    reader.onload = async (evt) => {
      const text = evt.target?.result as string;
      if (!text) return;

      setIsImporting(true);
      try {
        const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
        if (lines.length < 2) {
          toast.error('CSV file has no data rows');
          return;
        }

        const newContactsList: InvestorContact[] = [];
        let importCount = 0;
        const isPurchasedList = importSource === 'import_purchased';

        for (let i = 1; i < lines.length; i++) {
          const cols = lines[i].split(',').map((c) => c.replace(/(^["']|["']$)/g, '').trim());
          if (cols.length < 2) continue;

          const [name, email, phone, type, relationship, ticketStr, consentStr] = cols;
          if (!email || !email.includes('@')) continue;

          const potentialTicket = ticketStr ? Math.round(parseFloat(ticketStr) * 100) : 0;
          const emailConsent = consentStr ? consentStr.toLowerCase() === 'true' || consentStr === '1' : true;

          const contactId = `contact_${Date.now()}_${i}`;
          const newContact: InvestorContact = {
            id: contactId,
            name: name || 'Unnamed Investor',
            email: email.toLowerCase(),
            phone: phone || '',
            type: type || 'Individual',
            relationship: relationship || 'Warm',
            potentialTicket: isNaN(potentialTicket) ? 0 : potentialTicket,
            emailConsent,
            inAppConsent: true,
            source: importSource,
            isPurchased: isPurchasedList,
            createdAt: new Date().toISOString(),
          };

          newContactsList.push(newContact);
          importCount++;
        }

        if (isE2E) {
          const existing = JSON.parse(localStorage.getItem(contactsKey) || '[]');
          localStorage.setItem(contactsKey, JSON.stringify([...newContactsList, ...existing]));
          triggerE2ERefresh();
        } else {
          const batch = writeBatch(db);
          for (const c of newContactsList) {
            const ref = doc(db, 'projects', projectId, 'investor_contacts', c.id);
            batch.set(ref, c);
          }
          await batch.commit();
        }

        toast.success(`Successfully imported ${importCount} contacts!`);
      } catch (err) {
        console.error(err);
        toast.error('Failed to parse CSV file');
      } finally {
        setIsImporting(false);
        if (fileInputRef.current) fileInputRef.current.value = '';
      }
    };

    reader.readAsText(file);
  };

  const handleToggleConsent = async (
    email: string,
    channel: 'email' | 'inApp',
    currentVal: boolean,
    contactId?: string,
    followerId?: string
  ) => {
    if (readOnly) return;
    try {
      const newVal = !currentVal;
      const targetEmail = email.toLowerCase();

      if (isE2E) {
        const updatedContacts = contacts.map(c => 
          c.email.toLowerCase() === targetEmail 
            ? { ...c, [channel === 'email' ? 'emailConsent' : 'inAppConsent']: newVal } 
            : c
        );
        const updatedFollowers = followers.map(f => 
          f.email.toLowerCase() === targetEmail 
            ? { ...f, [channel === 'email' ? 'emailConsent' : 'inAppConsent']: newVal } 
            : f
        );
        localStorage.setItem(contactsKey, JSON.stringify(updatedContacts));
        localStorage.setItem(followersKey, JSON.stringify(updatedFollowers));
        triggerE2ERefresh();
      } else {
        const matchingContacts = contacts.filter((c) => c.email.toLowerCase() === targetEmail);
        const matchingFollowers = followers.filter((f) => f.email.toLowerCase() === targetEmail);

        for (const c of matchingContacts) {
          const ref = doc(db, 'projects', projectId, 'investor_contacts', c.id);
          await updateDoc(ref, {
            [channel === 'email' ? 'emailConsent' : 'inAppConsent']: newVal,
          });
        }

        for (const f of matchingFollowers) {
          const ref = doc(db, 'projects', projectId, 'followers', f.id);
          await updateDoc(ref, {
            [channel === 'email' ? 'emailConsent' : 'inAppConsent']: newVal,
          });
        }
      }

      toast.success(`Updated ${channel} consent for ${email}`);
    } catch (err) {
      console.error(err);
      toast.error('Failed to update consent');
    }
  };

  const handleUnsubscribeEverywhere = async (email: string) => {
    if (readOnly) return;
    try {
      const targetEmail = email.toLowerCase();

      if (isE2E) {
        const updatedContacts = contacts.map(c => 
          c.email.toLowerCase() === targetEmail ? { ...c, emailConsent: false } : c
        );
        const updatedFollowers = followers.map(f => 
          f.email.toLowerCase() === targetEmail ? { ...f, emailConsent: false } : f
        );
        localStorage.setItem(contactsKey, JSON.stringify(updatedContacts));
        localStorage.setItem(followersKey, JSON.stringify(updatedFollowers));
        triggerE2ERefresh();
      } else {
        const matchingContacts = contacts.filter((c) => c.email.toLowerCase() === targetEmail);
        const matchingFollowers = followers.filter((f) => f.email.toLowerCase() === targetEmail);

        for (const c of matchingContacts) {
          const ref = doc(db, 'projects', projectId, 'investor_contacts', c.id);
          await updateDoc(ref, { emailConsent: false });
        }

        for (const f of matchingFollowers) {
          const ref = doc(db, 'projects', projectId, 'followers', f.id);
          await updateDoc(ref, { emailConsent: false });
        }
      }

      toast.success(`Revoked email consent everywhere for: ${email}`);
    } catch (err) {
      console.error(err);
      toast.error('Failed to unsubscribe contact');
    }
  };

  const handleDeleteContact = async (id: string) => {
    if (readOnly) return;
    try {
      if (isE2E) {
        const updated = contacts.filter(c => c.id !== id);
        localStorage.setItem(contactsKey, JSON.stringify(updated));
        triggerE2ERefresh();
      } else {
        await deleteDoc(doc(db, 'projects', projectId, 'investor_contacts', id));
      }
      toast.success('Deleted contact from audience list');
    } catch (err) {
      console.error(err);
      toast.error('Failed to delete contact');
    }
  };

  return (
    <div className="glass-card rounded-2xl p-6 border border-white/5 space-y-6">
      {/* Header and Import button */}
      <div className="flex justify-between items-center border-b border-white/5 pb-4">
        <div>
          <h4 className="text-xs font-bold uppercase tracking-wider text-[#9E9DA0]">Audience & Consent Manager</h4>
          <p className="text-[10px] text-[#9E9DA0]/60 mt-1">Deduplicated email contacts & deal followers.</p>
        </div>

        <div className="flex items-center gap-2">
          <select
            value={importSource}
            onChange={(e) => setImportSource(e.target.value)}
            disabled={readOnly || isImporting}
            id="select-import-source"
            className="bg-zinc-900 border border-white/10 rounded px-2 py-1 text-xs text-white focus:outline-none focus:border-emerald-500"
          >
            <option value="">Select list source...</option>
            <option value="import_relational">Relational Network</option>
            <option value="import_purchased">Purchased List</option>
          </select>
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleCSVUpload}
            accept=".csv"
            className="hidden"
            id="csv-file-input"
          />
          <button
            onClick={handleImportClick}
            disabled={readOnly || isImporting}
            id="btn-import-csv"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wider bg-white/5 border border-white/10 hover:bg-white/10 text-white transition-all"
          >
            <Upload size={13} />
            {isImporting ? 'Importing...' : 'Import CSV'}
          </button>
          <button
            onClick={() => setIsAddFormOpen(!isAddFormOpen)}
            disabled={readOnly}
            id="btn-toggle-add-form"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wider bg-zinc-900 border border-white/10 hover:bg-white/5 text-white transition-all"
          >
            {isAddFormOpen ? 'Cancel' : 'Add Contact'}
          </button>
        </div>
      </div>

      {isAddFormOpen && (
        <form onSubmit={handleAddContact} className="p-4 bg-zinc-900/60 rounded-xl border border-white/5 space-y-4" id="add-contact-form">
          <h5 className="text-xs font-bold text-white uppercase tracking-wider">Add Single Contact</h5>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-3">
            <div>
              <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider block mb-1">Name</label>
              <input
                type="text"
                value={newName}
                onChange={(e) => setNewName(e.target.value)}
                placeholder="e.g. John Doe"
                className="w-full bg-black/40 border border-white/15 rounded-lg px-3 py-1.5 text-xs text-white focus:outline-none focus:border-emerald-500"
                required
                id="input-contact-name"
              />
            </div>
            <div>
              <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider block mb-1">Email</label>
              <input
                type="email"
                value={newEmail}
                onChange={(e) => setNewEmail(e.target.value)}
                placeholder="e.g. john@doe.com"
                className="w-full bg-black/40 border border-white/15 rounded-lg px-3 py-1.5 text-xs text-white focus:outline-none focus:border-emerald-500"
                required
                id="input-contact-email"
              />
            </div>
            <div>
              <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider block mb-1">Phone</label>
              <input
                type="text"
                value={newPhone}
                onChange={(e) => setNewPhone(e.target.value)}
                placeholder="e.g. 555-0100"
                className="w-full bg-black/40 border border-white/15 rounded-lg px-3 py-1.5 text-xs text-white focus:outline-none focus:border-emerald-500"
                id="input-contact-phone"
              />
            </div>
            <div>
              <label className="text-[10px] font-bold text-zinc-400 uppercase tracking-wider block mb-1">Type</label>
              <select
                value={newContactType}
                onChange={(e) => setNewContactType(e.target.value)}
