import React, { useEffect, useState } from 'react';
import { Contingency, ContingencyType } from '@/types/schema';
import { Clock, AlertTriangle, CheckCircle, FileText, Bell, Plus, Trash2, Calendar, User } from 'lucide-react';
import toast from 'react-hot-toast';
import { uploadFile } from '@/lib/storage/uploadService';
import { IS_DEMO_MODE } from '@/lib/config/demo';

interface ContingencyTrackerProps {
  contingencies: Contingency[];
  onChange: (contingencies: Contingency[]) => void;
  readOnly?: boolean;
  projectId?: string;
}

const DEFAULT_TYPES = ['Inspection', 'Financing', 'Appraisal'];

export function ContingencyTracker({ contingencies = [], onChange, readOnly = false, projectId }: ContingencyTrackerProps) {
  const [activeReminders, setActiveReminders] = useState<{ [key: string]: string }>({});
  const [uploadingIds, setUploadingIds] = useState<Record<string, boolean>>({});

  useEffect(() => {
    // Sync reminders log on mount or when contingencies change
    const newReminders: { [key: string]: string } = {};
    contingencies.forEach(c => {
      const days = calculateDaysRemaining(c.deadlineDate);
      if (days !== null && c.reminderSettings && !c.isSatisfied && !c.isWaived) {
        const isT7 = c.reminderSettings.includes('T-7') && days === 7;
        const isT3 = c.reminderSettings.includes('T-3') && days === 3;
        const isT1 = c.reminderSettings.includes('T-1') && days === 1;

        if (isT7) {
          newReminders[c.id] = 'T-7: 7 days until deadline';
          console.log(`[Contingency Reminder] [T-7] Contingency "${c.type}" (id: ${c.id}) is exactly 7 days away.`);
        } else if (isT3) {
          newReminders[c.id] = 'T-3: 3 days until deadline';
          console.log(`[Contingency Reminder] [T-3] Contingency "${c.type}" (id: ${c.id}) is exactly 3 days away.`);
        } else if (isT1) {
          newReminders[c.id] = 'T-1: 1 day until deadline!';
          console.log(`[Contingency Reminder] [T-1] Contingency "${c.type}" (id: ${c.id}) is due tomorrow!`);
        }
      }
    });
    setActiveReminders(newReminders);
  }, [contingencies]);

  const calculateDaysRemaining = (deadlineDate: any) => {
    if (!deadlineDate) return null;
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const deadline = deadlineDate instanceof Date
      ? deadlineDate
      : deadlineDate.toDate
        ? deadlineDate.toDate()
        : new Date(deadlineDate);

    if (isNaN(deadline.getTime())) return null;
    deadline.setHours(0, 0, 0, 0);

    const diffTime = deadline.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  const getProximityColor = (days: number | null) => {
    if (days === null) return 'bg-[#9E9DA0] text-[#9E9DA0]';
    if (days <= 1) return 'bg-[#E53E3E] text-[#E53E3E]'; // Red
    if (days <= 3) return 'bg-[#DD6B20] text-[#DD6B20]'; // Orange
    if (days <= 7) return 'bg-[#D69E2E] text-[#D69E2E]'; // Yellow
    return 'bg-[#319795] text-[#319795]'; // Teal/Green
  };

  const updateContingency = (id: string, updates: Partial<Contingency>) => {
    onChange(contingencies.map(c => c.id === id ? { ...c, ...updates } : c));
  };

  const addCustomContingency = () => {
    const defaultDate = new Date();
    defaultDate.setDate(defaultDate.getDate() + 10);
    const newC: Contingency = {
      id: crypto.randomUUID(),
      type: 'Custom',
      deadlineDate: defaultDate,
      isWaived: false,
      isSatisfied: false,
      party: 'Buyer',
      reminderSettings: ['T-7', 'T-3', 'T-1'],
    };
    onChange([...contingencies, newC]);
    toast.success('Added new custom contingency');
  };

  const deleteContingency = (id: string) => {
    onChange(contingencies.filter(c => c.id !== id));
    toast('Removed contingency');
  };

  const handleUploadDoc = async (id: string) => {
    if (readOnly) return;

    if (IS_DEMO_MODE) {
      setUploadingIds(prev => ({ ...prev, [id]: true }));
      await new Promise((resolve) => setTimeout(resolve, 800));
      updateContingency(id, {
        satisfiedDocUrl: `/mock/documents/contingency_${id}.pdf`,
        satisfiedDocName: 'contingency_proof_signed.pdf',
      });
      toast.success('Mock proof document uploaded! (Demo)');
      setUploadingIds(prev => ({ ...prev, [id]: false }));
      return;
    }

    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.pdf,image/*';
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setUploadingIds(prev => ({ ...prev, [id]: true }));
      const toastId = toast.loading(`Uploading ${file.name}...`);
      try {
        const res = await uploadFile({
          file,
          path: 'contingency_proofs',
          projectId: projectId || 'general',
        });
        updateContingency(id, {
          satisfiedDocUrl: res.downloadUrl,
          satisfiedDocName: file.name,
        });
        toast.success('Document uploaded successfully!', { id: toastId });
      } catch (err: any) {
        console.error('Upload failed:', err);
        toast.error(`Upload failed: ${err.message || 'Unknown error'}`, { id: toastId });
      } finally {
        setUploadingIds(prev => ({ ...prev, [id]: false }));
      }
    };
    input.click();
  };

  return (
    <div className="glass-card rounded-2xl p-6 border border-white/5 space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-xl bg-amber-500/10 text-amber-500">
            <Clock size={20} />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white uppercase tracking-wider text-left">Contingency Tracker &amp; Deadlines</h3>
            <p className="text-[10px] text-[#9E9DA0] text-left">Monitor critical milestones, reminder schedules, and satisfaction proof.</p>
          </div>
        </div>
        {!readOnly && (
          <button
            onClick={addCustomContingency}
            className="flex items-center gap-1 px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded-lg border border-[#454955]/30 text-[#454955] hover:bg-[#454955]/10 active:scale-95 transition-all"
          >
            <Plus size={14} /> Add Contingency
          </button>
        )}
      </div>

      {contingencies.length === 0 ? (
        <div className="p-8 text-center bg-white/5 border border-white/5 rounded-xl text-xs text-[#9E9DA0]">
          No contingencies loaded. Add one to start tracking.
        </div>
      ) : (
        <div className="space-y-4 text-left">
          {contingencies.map(c => {
            const days = calculateDaysRemaining(c.deadlineDate);
            const colorClass = getProximityColor(days);
            const formattedDate = c.deadlineDate
              ? new Date(c.deadlineDate).toISOString().split('T')[0]
              : '';

            const status = c.isSatisfied ? 'Satisfied' : c.isWaived ? 'Waived' : 'Pending';

            // Proof validation check
            const proofMissing = c.isSatisfied && !c.satisfiedDocUrl && !c.explicitConfirmation;

            return (
              <div
                key={c.id}
                className={`p-5 rounded-xl border transition-all space-y-4 ${
                  proofMissing
                    ? 'border-[#E53E3E]/40 bg-[#E53E3E]/5'
                    : 'border-white/5 bg-white/5 hover:border-white/10'
                }`}
              >
                {/* Active Notification Banner */}
                {activeReminders[c.id] && (
                  <div className="flex items-center gap-2 p-2 bg-amber-500/10 border border-amber-500/20 text-[10px] font-bold text-amber-500 rounded-lg animate-pulse">
                    <Bell size={12} className="shrink-0" />
                    <span>Active Reminder: {activeReminders[c.id]}</span>
                  </div>
                )}

                <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4">
                  {/* Left info */}
                  <div className="flex items-start gap-3">
                    <div className={`w-2.5 h-2.5 rounded-full mt-1 shrink-0 ${colorClass}`} />
                    <div>
                      <div className="flex items-center gap-2">
                        {readOnly ? (
                          <span className="text-xs font-bold text-white">{c.type}</span>
                        ) : (
                          <input
                            type="text"
                            value={c.type}
                            onChange={(e) => updateContingency(c.id, { type: e.target.value })}
                            className="bg-transparent text-xs font-bold text-white border-b border-white/10 focus:border-[#454955] focus:outline-none py-0.5"
                          />
                        )}
                        <span className="text-[9px] font-bold uppercase px-2 py-0.5 rounded bg-white/10 text-[#9E9DA0]">
                          {days !== null
                            ? days > 0
                              ? `${days}d left`
                              : days === 0
                                ? 'due today'
                                : `${Math.abs(days)}d past due`
                            : 'Date TBD'}
                        </span>
                      </div>
                      <div className="text-[10px] text-[#9E9DA0] mt-1 flex items-center gap-1.5">
                        <User size={10} />
                        <span>Responsible Party: </span>
                        {readOnly ? (
                          <span className="text-white font-semibold">{c.party || 'Buyer'}</span>
                        ) : (
                          <select
                            value={c.party || 'Buyer'}
                            onChange={(e) => updateContingency(c.id, { party: e.target.value })}
                            className="bg-transparent text-[10px] text-white font-semibold border-none focus:outline-none focus:ring-0 p-0 cursor-pointer"
                          >
                            <option value="Buyer">Buyer</option>
                            <option value="Seller">Seller</option>
                            <option value="Escrow">Escrow</option>
                            <option value="Lender">Lender</option>
                            <option value="Other">Other</option>
                          </select>
                        )}
                      </div>
                    </div>
                  </div>

                  {/* Inputs */}
                  <div className="flex flex-wrap items-center gap-4">
                    {/* Deadline Date */}
                    <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-bold uppercase tracking-wider text-[#9E9DA0]">Deadline</label>
                      <div className="relative flex items-center">
                        <Calendar size={12} className="absolute left-2 text-[#454955]" />
                        <input
                          type="date"
                          value={formattedDate}
                          disabled={readOnly}
                          onChange={(e) => {
                            if (e.target.value) {
                              const [year, month, day] = e.target.value.split('-').map(Number);
                              updateContingency(c.id, { deadlineDate: new Date(year, month - 1, day) });
                            }
                          }}
                          className="pl-7 pr-2 py-1 bg-[#161217] border border-white/10 rounded-lg text-[11px] text-white focus:outline-none focus:ring-1 focus:ring-[#454955] w-32"
                        />
                      </div>
                    </div>

                    {/* Status Select */}
                    <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-bold uppercase tracking-wider text-[#9E9DA0]">Status</label>
                      <select
                        id={`select-contingency-status-${c.id}`}
                        value={status}
                        disabled={readOnly}
                        onChange={(e) => {
                          const val = e.target.value;
                          updateContingency(c.id, {
                            isSatisfied: val === 'Satisfied',
                            isWaived: val === 'Waived',
                          });
                        }}
                        className="px-2 py-1 bg-[#161217] border border-white/10 rounded-lg text-[11px] text-white focus:outline-none focus:ring-1 focus:ring-[#454955] cursor-pointer"
                      >
                        <option value="Pending">Pending</option>
                        <option value="Satisfied">Satisfied</option>
                        <option value="Waived">Waived</option>
                      </select>
                    </div>

                    {/* Reminders Config */}
                    <div className="flex flex-col gap-1">
                      <label className="text-[9px] font-bold uppercase tracking-wider text-[#9E9DA0]">Reminders</label>
                      <div className="flex items-center gap-2 py-1.5">
                        {['T-7', 'T-3', 'T-1'].map(t => {
                          const settings = c.reminderSettings || [];
                          const checked = settings.includes(t);
                          return (
                            <label key={t} className="flex items-center gap-1 text-[10px] text-[#9E9DA0] cursor-pointer">
                              <input
                                type="checkbox"
                                checked={checked}
                                disabled={readOnly}
                                onChange={(e) => {
                                  const updated = e.target.checked
                                    ? [...settings, t]
                                    : settings.filter(item => item !== t);
                                  updateContingency(c.id, { reminderSettings: updated });
                                }}
                                className="rounded border-white/10 bg-white/5 text-primary focus:ring-primary w-3 h-3"
                              />
                              {t}
                            </label>
                          );
                        })}
                      </div>
                    </div>

                    {/* Delete button (only for custom ones) */}
                    {!readOnly && !DEFAULT_TYPES.includes(c.type) && (
                      <button
                        onClick={() => deleteContingency(c.id)}
                        className="p-1.5 hover:bg-white/15 rounded-lg text-[#E53E3E] transition-all self-end"
                        title="Remove contingency"
                      >
                        <Trash2 size={14} />
                      </button>
                    )}
                  </div>
                </div>

                {/* Proof Section (when Satisfied) */}
                {c.isSatisfied && (
                  <div className="pt-3 border-t border-white/5 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs bg-white/5 p-3 rounded-lg">
                    <div className="space-y-1">
                      <span className="text-[10px] text-[#9E9DA0] block font-bold uppercase">Satisfaction Verification</span>
                      {c.satisfiedDocUrl ? (
                        <div className="flex items-center gap-2 text-green-400">
                          <FileText size={12} />
                          <span className="font-mono text-[10px]">
                            {c.satisfiedDocName}
                            {IS_DEMO_MODE && <span className="ml-2 text-[8px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 font-sans">Demo</span>}
                          </span>
                        </div>
                      ) : c.explicitConfirmation ? (
                        <div className="flex items-center gap-2 text-[#454955]">
                          <CheckCircle size={12} />
                          <span>Explicitly Confirmed (No Document)</span>
                        </div>
                      ) : (
                        <span className="text-[#E53E3E] font-medium text-[10px] block">⚠️ Document proof or explicit confirm required.</span>
                      )}
                    </div>

                    {!readOnly && (
                      <div className="flex items-center gap-3">
                        <button
                          type="button"
                          onClick={() => handleUploadDoc(c.id)}
                          disabled={uploadingIds[c.id]}
                          className="px-2.5 py-1 bg-white/10 hover:bg-white/15 text-white font-medium text-[10px] rounded-lg transition-all disabled:opacity-50"
                        >
                          {uploadingIds[c.id] ? 'Uploading...' : c.satisfiedDocUrl ? `Replace Doc ${IS_DEMO_MODE ? '(Demo)' : ''}` : `Upload Proof Doc ${IS_DEMO_MODE ? '(Demo)' : ''}`}
                        </button>
                        <label className="flex items-center gap-1.5 text-[10px] text-[#9E9DA0] cursor-pointer">
                          <input
                            id={`checkbox-explicit-confirm-${c.id}`}
                            type="checkbox"
                            checked={!!c.explicitConfirmation}
                            onChange={(e) => updateContingency(c.id, { explicitConfirmation: e.target.checked })}
                            className="rounded border-white/10 bg-white/5 text-primary focus:ring-primary w-3.5 h-3.5"
                          />
                          Explicitly Confirm
                        </label>
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { ContractorBid } from '@/types/schema';
import { Plus, Users, Trash2, CheckCircle, ExternalLink } from 'lucide-react';
import toast from 'react-hot-toast';
import { NumberInput } from '@/components/ui/NumberInput';

interface ContractorBidsProps {
  bids: ContractorBid[];
  baseBudget: number;
  onChange: (bids: ContractorBid[]) => void;
}

export function ContractorBids({ bids, baseBudget, onChange }: ContractorBidsProps) {
  const [isAdding, setIsAdding] = useState(false);
  const [newBid, setNewBid] = useState<Partial<ContractorBid>>({
    contractorName: '',
    totalAmount: 0,
    status: 'Pending',
    notes: '',
  });

  const handleAdd = () => {
    if (!newBid.contractorName || !newBid.totalAmount) {
      toast.error('Contractor name and bid amount are required');
      return;
    }

    const bid: ContractorBid = {
      id: crypto.randomUUID(),
      contractorName: newBid.contractorName,
      totalAmount: Number(newBid.totalAmount),
      status: newBid.status as 'Pending' | 'Approved' | 'Rejected',
      notes: newBid.notes || '',
      submittedAt: new Date(),
    };

    onChange([...bids, bid]);
    setIsAdding(false);
    setNewBid({ contractorName: '', totalAmount: 0, status: 'Pending', notes: '' });
    toast.success('Contractor bid added');
  };

  const handleDelete = (id: string) => {
    onChange(bids.filter(b => b.id !== id));
    toast.success('Bid removed');
  };

  const updateStatus = (id: string, status: 'Pending' | 'Approved' | 'Rejected') => {
    const bid = bids.find(b => b.id === id);
    // If approving, we might want to reject all others, but we'll leave that to the user for now
    onChange(bids.map(b => b.id === id ? { ...b, status } : b));
    if (bid) {
      toast.success(`Bid by ${bid.contractorName} ${status.toLowerCase()}`);
      if (status === 'Approved') {
        try {
          import('@/store/uiStore').then(({ useUIStore }) => {
            useUIStore.getState().triggerSuccessfulAction('bid_approved');
          });
        } catch (err) {
          console.error('Failed to trigger bid_approved successful action:', err);
        }
      }
    }
  };

  return (
    <div className="p-6 rounded-lg shadow-sm border" style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Users className="w-5 h-5" style={{ color: 'var(--text-secondary)' }} />
          <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>Contractor Bids</h2>
        </div>
        <div className="text-right">
          <p className="text-sm" style={{ color: 'var(--text-secondary)' }}>Target Budget: <span className="font-semibold" style={{ color: 'var(--text-primary)' }}>${baseBudget.toLocaleString()}</span></p>
        </div>
      </div>

      <div className="space-y-4">
        {bids.map(bid => {
          const variance = bid.totalAmount - baseBudget;
          const variancePercent = baseBudget > 0 ? (variance / baseBudget) * 100 : 0;

          return (
            <div key={bid.id} className="p-4 rounded-md border flex flex-col gap-3" style={{ borderColor: 'var(--border-ui)' }}>
              <div className="flex items-center justify-between">
                <div>
                  <h4 className="font-medium" style={{ color: 'var(--text-primary)' }}>{bid.contractorName}</h4>
                  <div className="flex items-center gap-2 mt-1">
                    <span className={`px-2 py-0.5 rounded text-xs border ${
                      bid.status === 'Approved' ? 'bg-green-50 text-green-700 border-green-200' :
                      bid.status === 'Rejected' ? 'bg-red-50 text-red-700 border-red-200' :
                      'bg-yellow-50 text-yellow-700 border-yellow-200'
                    }`}>
                      {bid.status}
                    </span>
                    <span className="text-xs text-gray-500">
                      {new Date(bid.submittedAt).toLocaleDateString()}
                    </span>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <div className="text-right">
                    <div className="font-semibold text-lg" style={{ color: 'var(--text-primary)' }}>
                      ${bid.totalAmount.toLocaleString()}
                    </div>
                    {baseBudget > 0 && (
                      <div className={`text-xs ${variance > 0 ? 'text-red-600' : 'text-green-600'}`}>
                        {variance > 0 ? '+' : ''}{variance.toLocaleString()} ({variance > 0 ? '+' : ''}{variancePercent.toFixed(1)}%)
                      </div>
                    )}
                  </div>
                  <button onClick={() => handleDelete(bid.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-md transition-colors" title="Delete Bid">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
              </div>

              <div className="flex items-center justify-between pt-3 border-t border-gray-100">
                <div className="text-sm text-gray-600">
                  {bid.notes || 'No notes provided.'}
                </div>
                <div className="flex items-center gap-2">
                  {bid.status !== 'Approved' && (
                    <button 
                      onClick={() => updateStatus(bid.id, 'Approved')}
                      className="px-3 py-1 text-xs font-medium bg-green-50 text-green-700 rounded border border-green-200 hover:bg-green-100 transition-colors"
                    >
                      Approve
                    </button>
                  )}
                  {bid.status !== 'Rejected' && (
                    <button 
                      onClick={() => updateStatus(bid.id, 'Rejected')}
                      className="px-3 py-1 text-xs font-medium bg-red-50 text-red-700 rounded border border-red-200 hover:bg-red-100 transition-colors"
                    >
                      Reject
                    </button>
                  )}
                </div>
              </div>
            </div>
          );
        })}

        {bids.length === 0 && !isAdding && (
          <div className="text-center py-8 text-sm" style={{ color: 'var(--text-secondary)' }}>
            No contractor bids received yet.
          </div>
        )}

        {isAdding && (
          <div className="p-4 rounded-md border border-blue-200 bg-blue-50 space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium mb-1 text-gray-700">Contractor Name</label>
                <input
                  type="text"
                  placeholder="e.g., ABC Renovations"
                  value={newBid.contractorName}
                  onChange={e => setNewBid({...newBid, contractorName: e.target.value})}
                  className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm"
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1 text-gray-700">Total Bid Amount ($)</label>
                <NumberInput
                  value={newBid.totalAmount || undefined}
                  onChange={(v) => setNewBid({...newBid, totalAmount: v ?? 0})}
                  min={0}
                  step={0.01}
                  prefix="$"
                />
              </div>
              <div className="sm:col-span-2">
                <label className="block text-xs font-medium mb-1 text-gray-700">Notes (Optional)</label>
                <input
                  type="text"
                  placeholder="e.g., Includes all materials except fixtures"
                  value={newBid.notes}
                  onChange={e => setNewBid({...newBid, notes: e.target.value})}
                  className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-3 pt-2">
              <button
                onClick={() => setIsAdding(false)}
                className="px-4 py-2 text-sm font-medium text-gray-600 hover:text-gray-800"
              >
                Cancel
              </button>
              <button
                onClick={handleAdd}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-md transition-colors"
              >
                Save Bid
              </button>
            </div>
          </div>
        )}

        {!isAdding && (
          <button
            onClick={() => setIsAdding(true)}
            className="w-full py-3 rounded-md border-2 border-dashed flex items-center justify-center gap-2 hover:bg-gray-50 transition-colors"
            style={{ borderColor: 'var(--border-ui)', color: 'var(--text-secondary)' }}
          >
            <Plus className="w-4 h-4" />
            <span className="font-medium text-sm">Add Contractor Bid</span>
          </button>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { DrawScheduleItem } from '@/types/schema';
import { Plus, HandCoins, Trash2, CheckCircle, Clock, Calendar, AlertTriangle } from 'lucide-react';
import toast from 'react-hot-toast';
import { NumberInput } from '@/components/ui/NumberInput';

interface ContractorDrawScheduleProps {
  draws: DrawScheduleItem[];
  totalBudget: number;
  onChange: (draws: DrawScheduleItem[]) => void;
}

export function ContractorDrawSchedule({ draws, totalBudget, onChange }: ContractorDrawScheduleProps) {
  const [isAdding, setIsAdding] = useState(false);
  const [newDraw, setNewDraw] = useState<Partial<DrawScheduleItem>>({
    milestone: '',
    completionPercentage: 0,
    amount: 0,
    status: 'Pending',
    requestedAt: new Date(),
  });

  const handleAdd = () => {
    if (!newDraw.milestone || !newDraw.amount) {
      toast.error('Milestone description and amount are required');
      return;
    }

    const draw: DrawScheduleItem = {
      id: crypto.randomUUID(),
      milestone: newDraw.milestone,
      completionPercentage: Number(newDraw.completionPercentage) || 0,
      amount: Number(newDraw.amount),
      status: newDraw.status as 'Pending' | 'Requested' | 'Approved' | 'Paid',
      requestedAt: newDraw.requestedAt || new Date(),
    };

    onChange([...draws, draw]);
    setIsAdding(false);
    setNewDraw({ milestone: '', completionPercentage: 0, amount: 0, status: 'Pending', requestedAt: new Date() });
    toast.success('Payout milestone logged');
  };

  const handleDelete = (id: string) => {
    onChange(draws.filter(d => d.id !== id));
    toast.success('Payout milestone removed');
  };

  const updateStatus = (id: string, status: 'Pending' | 'Requested' | 'Approved' | 'Paid') => {
    onChange(draws.map(d => 
      d.id === id ? { 
        ...d, 
        status, 
        requestedAt: status === 'Requested' ? new Date() : d.requestedAt,
        paidAt: status === 'Paid' ? new Date() : d.paidAt
      } : d
    ));
  };

  // Sort draws by date (if available)
  const sortedDraws = [...draws].sort((a, b) => {
    const dateA = a.paidAt || a.requestedAt || new Date(0);
    const dateB = b.paidAt || b.requestedAt || new Date(0);
    return dateA.getTime() - dateB.getTime();
  });

  const totalDispersed = draws.filter(d => d.status === 'Paid').reduce((sum, d) => sum + d.amount, 0);
  const totalAllocated = draws.reduce((sum, d) => sum + d.amount, 0);
  const remainingCapital = totalBudget - totalDispersed;
  const isOverBudget = totalAllocated > totalBudget;

  const formatDate = (date?: Date) => {
    if (!date) return 'TBD';
    return new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
  };

  return (
    <div className="p-6 rounded-lg shadow-sm border bg-white" style={{ borderColor: 'var(--border-ui)' }}>
      {/* Header and Financial Summary */}
      <div className="flex flex-col md:flex-row md:items-center justify-between mb-8 gap-4">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-blue-50 rounded-lg">
            <HandCoins className="w-5 h-5 text-blue-600" />
          </div>
          <div>
            <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>Milestone Payout Tracker</h2>
            <p className="text-sm" style={{ color: 'var(--text-secondary)' }}>Log contractor draws and track available capital.</p>
          </div>
        </div>

        <div className="flex flex-wrap gap-4 text-sm">
          <div className="p-3 rounded-md border bg-gray-50 flex flex-col items-start min-w-[140px]">
            <span className="text-gray-500 font-medium">Rehab Budget</span>
            <span className="text-lg font-bold text-gray-900">${totalBudget.toLocaleString()}</span>
          </div>
          <div className="p-3 rounded-md border bg-blue-50 border-blue-100 flex flex-col items-start min-w-[140px]">
            <span className="text-blue-600 font-medium">Total Dispersed</span>
            <span className="text-lg font-bold text-blue-900">${totalDispersed.toLocaleString()}</span>
          </div>
          <div className={`p-3 rounded-md border flex flex-col items-start min-w-[140px] ${remainingCapital < 0 ? 'bg-red-50 border-red-100' : 'bg-green-50 border-green-100'}`}>
            <span className={`font-medium ${remainingCapital < 0 ? 'text-red-600' : 'text-green-600'}`}>Available Capital</span>
            <span className={`text-lg font-bold ${remainingCapital < 0 ? 'text-red-900' : 'text-green-900'}`}>
              ${remainingCapital.toLocaleString()}
            </span>
          </div>
        </div>
      </div>

      {isOverBudget && (
        <div className="mb-6 p-4 rounded-md bg-red-50 border border-red-200 flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
          <div>
            <h4 className="text-sm font-semibold text-red-800">Budget Warning</h4>
            <p className="text-sm text-red-700 mt-1">
              Total allocated payouts (${totalAllocated.toLocaleString()}) exceed the rehab budget (${totalBudget.toLocaleString()}).
            </p>
          </div>
        </div>
      )}

      {/* Timeline UI */}
      <div className="relative border-l-2 border-gray-100 ml-4 pl-6 pb-4 space-y-8">
        {sortedDraws.map((draw, index) => {
          const isPaid = draw.status === 'Paid';
          const isPending = draw.status === 'Pending';
          const isApproved = draw.status === 'Approved';

          let iconColorClass = 'bg-gray-200 text-gray-500';
          let icon = <Clock className="w-4 h-4" />;

          if (isPaid) {
            iconColorClass = 'bg-green-500 text-white border-green-500';
            icon = <CheckCircle className="w-4 h-4" />;
          } else if (isApproved) {
            iconColorClass = 'bg-blue-500 text-white border-blue-500';
          } else if (draw.status === 'Requested') {
            iconColorClass = 'bg-yellow-500 text-white border-yellow-500';
          }

          return (
            <div key={draw.id} className="relative">
              {/* Timeline dot */}
              <div className={`absolute -left-[35px] top-1 w-6 h-6 rounded-full border-2 border-white flex items-center justify-center ${iconColorClass}`}>
                {icon}
              </div>

              <div className={`p-4 rounded-lg border transition-all ${isPaid ? 'bg-gray-50/50 border-gray-200' : 'bg-white border-gray-200 shadow-sm'}`}>
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">

                  {/* Left Side: Info */}
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <span className={`px-2 py-0.5 text-xs font-medium rounded-full ${
                        isPaid ? 'bg-green-100 text-green-700' : 
                        isApproved ? 'bg-blue-100 text-blue-700' : 
                        isPending ? 'bg-gray-100 text-gray-700' : 
                        'bg-yellow-100 text-yellow-700'
                      }`}>
                        {draw.status.toUpperCase()}
                      </span>
                      <span className="text-xs text-gray-500 flex items-center gap-1">
                        <Calendar className="w-3 h-3" />
                        {formatDate(draw.paidAt || draw.requestedAt)}
                      </span>
                    </div>
                    <h3 className={`font-semibold text-lg ${isPaid ? 'text-gray-600 line-through decoration-gray-300' : 'text-gray-900'}`}>
                      {draw.milestone}
                    </h3>
                  </div>

                  {/* Right Side: Amount & Actions */}
                  <div className="flex items-center gap-4">
                    <div className="text-right">
                      <div className={`text-xl font-bold ${isPaid ? 'text-gray-500' : 'text-gray-900'}`}>
                        ${draw.amount.toLocaleString()}
                      </div>
                      {draw.completionPercentage > 0 && (
                        <div className="text-xs text-gray-500">{draw.completionPercentage}% of work</div>
                      )}
                    </div>

                    {!isPaid && (
                      <button onClick={() => handleDelete(draw.id)} className="p-2 text-red-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors">
                        <Trash2 className="w-4 h-4" />
                      </button>
                    )}
                  </div>
                </div>

                {/* Workflow Actions */}
                {!isPaid && (
                  <div className="mt-4 pt-3 border-t border-gray-100 flex flex-wrap gap-2">
                    {draw.status === 'Pending' && (
                      <button 
                        onClick={() => updateStatus(draw.id, 'Requested')}
                        className="px-3 py-1.5 text-xs font-medium bg-white text-gray-700 rounded-md border border-gray-300 hover:bg-gray-50 transition-colors shadow-sm"
                      >
                        Request Funds
                      </button>
                    )}
                    {draw.status === 'Requested' && (
                      <button 
                        onClick={() => updateStatus(draw.id, 'Approved')}
                        className="px-3 py-1.5 text-xs font-medium bg-blue-50 text-blue-700 rounded-md border border-blue-200 hover:bg-blue-100 transition-colors"
                      >
                        Approve Request
                      </button>
                    )}
                    {draw.status === 'Approved' && (
                      <button 
                        onClick={() => updateStatus(draw.id, 'Paid')}
                        className="px-3 py-1.5 text-xs font-medium bg-green-600 text-white rounded-md border border-green-700 hover:bg-green-700 transition-colors shadow-sm"
                      >
                        Confirm Payout
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          );
        })}

        {draws.length === 0 && !isAdding && (
          <div className="text-center py-10 rounded-lg border border-dashed border-gray-200">
            <HandCoins className="w-8 h-8 text-gray-300 mx-auto mb-2" />
            <p className="text-gray-500 text-sm">No payouts have been logged yet.</p>
          </div>
        )}

        {isAdding && (
          <div className="relative">
            <div className="absolute -left-[35px] top-1 w-6 h-6 rounded-full border-2 border-white bg-blue-100 text-blue-600 flex items-center justify-center">
              <Plus className="w-4 h-4" />
            </div>
            <div className="p-5 rounded-lg border border-blue-200 bg-blue-50 shadow-sm">
              <h4 className="font-semibold text-blue-900 mb-4">Log New Payout Milestone</h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
                <div>
                  <label className="block text-xs font-medium mb-1 text-gray-700">Associated Milestone</label>
                  <input
                    type="text"
                    placeholder="e.g., Demolition Completed"
                    value={newDraw.milestone}
                    onChange={e => setNewDraw({...newDraw, milestone: e.target.value})}
                    className="w-full px-3 py-2 rounded-md border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1 text-gray-700">Draw Date (Est.)</label>
                  <input
                    type="date"
                    value={newDraw.requestedAt ? new Date(newDraw.requestedAt).toISOString().split('T')[0] : ''}
                    onChange={e => setNewDraw({...newDraw, requestedAt: new Date(e.target.value)})}
                    className="w-full px-3 py-2 rounded-md border border-gray-300 bg-white focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1 text-gray-700">Amount Dispersed ($)</label>
                  <NumberInput
                    value={newDraw.amount || undefined}
                    onChange={(v) => setNewDraw({...newDraw, amount: v ?? 0})}
                    min={0}
                    step={0.01}
                    placeholder="0.00"
                    prefix="$"
                  />
                </div>
                <div>
                  <label className="block text-xs font-medium mb-1 text-gray-700">% of Overall Work (Optional)</label>
                  <NumberInput
                    value={newDraw.completionPercentage || undefined}
                    onChange={(v) => setNewDraw({...newDraw, completionPercentage: v ?? 0})}
                    min={0}
                    max={100}
                    placeholder="e.g. 25"
                    suffix="%"
                  />
                </div>
              </div>

              <div className="flex items-center justify-end gap-3 pt-4 border-t border-blue-100">
                <button
                  onClick={() => setIsAdding(false)}
                  className="px-4 py-2 text-sm font-medium text-blue-700 hover:bg-blue-100 rounded-md transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleAdd}
                  className="px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-md transition-colors shadow-sm"
                >
                  Add Milestone
                </button>
              </div>
            </div>
          </div>
        )}

        {!isAdding && (
          <div className="relative mt-4">
            <div className="absolute -left-[35px] top-1 w-6 h-6 rounded-full border-2 border-white bg-gray-100 text-gray-400 flex items-center justify-center">
              <Plus className="w-4 h-4" />
            </div>
            <button
              onClick={() => setIsAdding(true)}
              className="w-full py-4 rounded-lg border-2 border-dashed border-gray-200 flex items-center justify-center gap-2 hover:bg-gray-50 hover:border-gray-300 transition-colors text-gray-500 hover:text-gray-700"
            >
              <Plus className="w-4 h-4" />
              <span className="font-medium text-sm">Add Next Payout Milestone</span>
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useCallback } from 'react';
import { getAuth } from 'firebase/auth';
import { collection, onSnapshot, orderBy, query, doc, addDoc } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { uploadFile } from '@/lib/storage/uploadService';
import type { Commitment, CommitmentStatus, CapitalPartyType } from '@/types/schema';
import { 
  Users, 
  Plus, 
  Trash2, 
  Edit3, 
  Download, 
  AlertCircle, 
  FileText, 
  Loader2, 
  X,
  CheckCircle,
  HelpCircle
} from 'lucide-react';
import toast from 'react-hot-toast';

interface Props {
  projectId: string;
}

export function ContributionLedger({ projectId }: Props) {
  const [project, setProject] = useState<any>(null);
  const [commitments, setCommitments] = useState<Commitment[]>([]);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  // Modals state
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [activeCommitment, setActiveCommitment] = useState<Commitment | null>(null);

  // Form Fields
  const [formName, setFormName] = useState('');
  const [formEmail, setFormEmail] = useState('');
  const [formAmount, setFormAmount] = useState('');
  const [formPartyType, setFormPartyType] = useState<CapitalPartyType>('Investor');
  const [formStatus, setFormStatus] = useState<CommitmentStatus>('pledged');
  const [formNotes, setFormNotes] = useState('');
  const [formEvidence, setFormEvidence] = useState('');

  // ── 1. Listen to Project details ──
  useEffect(() => {
    if (!projectId) return;
    const unsub = onSnapshot(doc(db, 'projects', projectId), (snap) => {
      if (snap.exists()) {
        setProject(snap.data());
      }
    });
    return unsub;
  }, [projectId]);

  // ── 2. Listen to Commitments subcollection ──
  useEffect(() => {
    if (!projectId) return;

    // Check for E2E testing mock
    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_commitments_${projectId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          if (val) {
            setCommitments(JSON.parse(val));
          } else {
            setCommitments([]);
          }
          setLoading(false);
        } catch (e) {
          console.error(e);
        }
      };
      load();
      window.addEventListener('storage', (e) => {
        if (e.key === key) load();
      });
      return;
    }

    const q = query(
      collection(db, 'projects', projectId, 'commitments'),
      orderBy('createdAt', 'asc')
    );
    const unsub = onSnapshot(
      q,
      (snap) => {
        const docs = snap.docs.map((d) => ({
          id: d.id,
          ...d.data(),
          createdAt: d.data().createdAt?.toDate?.()?.toISOString() ?? null,
        })) as Commitment[];
        setCommitments(docs);
        setLoading(false);
      },
      (err) => {
        console.error('[ContributionLedger] Firestore onSnapshot error:', err);
        setLoading(false);
      }
    );
    return unsub;
  }, [projectId]);

  // Rollups & Calculations
  const raiseTarget = project?.financials?.capitalRaiseTarget || 0;
  const totalCommitted = commitments.reduce((sum, c) => sum + ((c.amountCents ?? 0) / 100), 0);
  const totalConfirmed = commitments.reduce((sum, c) => {
    const isFunded = c.status === 'funds-confirmed' || c.status === 'cleared';
    return sum + (isFunded ? ((c.amountCents ?? 0) / 100) : 0);
  }, 0);

  const committedPercent = raiseTarget > 0 ? Math.min(100, Math.round((totalCommitted / raiseTarget) * 100)) : 0;
  const confirmedPercent = raiseTarget > 0 ? Math.min(100, Math.round((totalConfirmed / raiseTarget) * 100)) : 0;

  // ── Actions ──
  const handleAddSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formName.trim()) {
      toast.error('Name is required.');
      return;
    }
    const cents = Math.round(parseFloat(formAmount) * 100);
    if (isNaN(cents) || cents <= 0) {
      toast.error('Amount must be positive.');
      return;
    }

    setSubmitting(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/commitments`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          name: formName.trim(),
          email: formEmail.trim() || null,
          amountCents: cents,
          partyType: formPartyType,
          status: formStatus,
          notes: formNotes.trim() || null,
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to create contribution record.');
      }

      toast.success('Contribution record added successfully.');
      setShowAddModal(false);
      resetForm();
    } catch (err: any) {
      toast.error(err.message || 'Error creating contribution record.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleEditSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!activeCommitment) return;
    if (!formName.trim()) {
      toast.error('Name is required.');
      return;
    }
    const cents = Math.round(parseFloat(formAmount) * 100);
    if (isNaN(cents) || cents <= 0) {
      toast.error('Amount must be positive.');
      return;
    }

    setSubmitting(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/commitments/${activeCommitment.id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          name: formName.trim(),
          email: formEmail.trim() || null,
          amountCents: cents,
          partyType: formPartyType,
          status: formStatus,
          notes: formNotes.trim() || null,
          evidence: formEvidence.trim() || null,
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to update contribution record.');
      }

      toast.success('Contribution record updated.');
      setShowEditModal(false);
      resetForm();
    } catch (err: any) {
      toast.error(err.message || 'Error updating contribution record.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (cId: string) => {
    if (!window.confirm('Are you sure you want to delete this contribution record?')) return;

    setSubmitting(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/commitments/${cId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to delete contribution record.');
      }

      toast.success('Contribution record removed.');
    } catch (err: any) {
      toast.error(err.message || 'Error deleting contribution record.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleExportPDF = async () => {
    try {
      const auth = getAuth();
      const user = auth.currentUser;
      const idToken = await user?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      toast.loading('Generating Capital Stack Statement PDF...', { id: 'pdf-export' });

      const response = await fetch(`/api/projects/${projectId}/capital-stack/export`, {
        headers: {
          'Authorization': `Bearer ${idToken}`
        }
      });
      if (!response.ok) throw new Error('Failed to generate PDF statement.');

      const blob = await response.blob();

      const address = (project?.address || projectId)
        .replace(/[^a-zA-Z0-9]+/g, '-')
        .replace(/^-+|-+$/g, '')
        .toLowerCase()
        .slice(0, 60);
      const dateStr = new Date().toISOString().split('T')[0];
      const filename = `capital-stack-statement-${address}-${dateStr}.pdf`;

      // Trigger local browser download
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = filename;
      document.body.appendChild(a);
      a.click();
      a.remove();

      // Upload generated PDF to project Files
      try {
        const file = new File([blob], filename, { type: 'application/pdf' });
        const uploadRes = await uploadFile({
          file,
          path: 'documents',
          projectId,
        });

        await addDoc(collection(db, 'projects', projectId, 'documents'), {
          category: 'Other',
          fileName: filename,
          fileUrl: uploadRes.downloadUrl,
          storagePath: uploadRes.storagePath,
          fileSize: file.size,
          mimeType: file.type,
          uploadedByUid: user?.uid || 'system',
          uploadedByName: user?.displayName || 'LeadInvestor',
          uploadedAt: new Date().toISOString(),
          notes: 'Capital Stack Statement (System Generated)',
        });

        toast.success('Capital Stack Statement PDF exported and saved to Project Files.', { id: 'pdf-export' });
      } catch (uploadErr) {
        console.error('[ContributionLedger] Failed to save statement to Project Files Storage:', uploadErr);
        toast.success('Capital Stack Statement PDF exported successfully (offline/project files skip).', { id: 'pdf-export' });
      }
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to export statement.', { id: 'pdf-export' });
    }
  };

  const resetForm = () => {
    setFormName('');
    setFormEmail('');
    setFormAmount('');
    setFormPartyType('Investor');
    setFormStatus('pledged');
    setFormNotes('');
    setFormEvidence('');
    setActiveCommitment(null);
  };

  const openEdit = (c: Commitment) => {
    setActiveCommitment(c);
    setFormName(c.name);
    setFormEmail(c.email || '');
    setFormAmount(String((c.amountCents ?? 0) / 100));
    setFormPartyType(c.partyType || 'Investor');
    setFormStatus(c.status);
    setFormNotes(c.notes || '');
    const lastTransition = c.transitions && c.transitions.length > 0 ? c.transitions[c.transitions.length - 1] : null;
    setFormEvidence(lastTransition?.evidence || '');
    setShowEditModal(true);
  };

  const getStatusBadgeStyles = (status: CommitmentStatus) => {
    switch (status) {
      case 'pledged':
      case 'soft-committed':
        return 'bg-[#FFF7ED] text-[#C2410C] border border-[#FED7AA]';
      case 'transferred':
      case 'docs-out':
        return 'bg-[#EFF6FF] text-[#1D4ED8] border border-[#BFDBFE]';
      case 'signed':
        return 'bg-[#F5F3FF] text-[#6D28D9] border border-[#DDD6FE]';
      case 'cleared':
      case 'funds-confirmed':
        return 'bg-[#ECFDF5] text-[#047857] border border-[#A7F3D0]';
      default:
        return 'bg-gray-100 text-gray-800 border border-gray-200';
    }
  };

  if (loading) {
    return (
      <div className="glass-card p-6 flex flex-col items-center justify-center min-h-[200px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#7A9EAA] mb-2" />
        <span className="text-xs text-pw-muted font-light uppercase tracking-wider">Loading Contribution Ledger...</span>
      </div>
    );
  }

  return (
    <div className="glass-card overflow-hidden">
      {/* Header */}
      <div className="px-6 pt-6 pb-4 flex flex-col md:flex-row md:items-center justify-between border-b border-pw-border bg-pw-bg/50">
        <div>
          <h2 className="text-[18px] leading-[24px] font-semibold text-pw-black flex items-center gap-2">
            <Users className="w-5 h-5 text-[#7A9EAA]" />
            Contribution Ledger & Capital Stack
          </h2>
          <p className="text-xs text-pw-muted font-light mt-0.5">
            Equity rollups driving capital stack funded bar and investor ownership allocation.
          </p>
        </div>
        <div className="mt-4 md:mt-0 flex gap-2">
          <button 
            onClick={handleExportPDF}
            className="pw-interactive px-3 py-1.5 border border-pw-border text-xs font-semibold uppercase tracking-wider text-pw-black bg-pw-white hover:bg-pw-bg flex items-center gap-1.5"
          >
            <Download className="w-3.5 h-3.5" />
            Export Statement PDF
          </button>
          <button 
            onClick={() => { resetForm(); setShowAddModal(true); }}
            className="pw-interactive px-3 py-1.5 text-xs font-semibold uppercase tracking-wider text-pw-white bg-[#7A9EAA] hover:bg-[#688a95] flex items-center gap-1.5"
          >
            <Plus className="w-3.5 h-3.5" />
            Add Entry
          </button>
        </div>
      </div>

      {/* Visual Funded Progress Bar */}
      <div className="p-6 border-b border-pw-border bg-pw-bg/20">
        <div className="flex justify-between items-center text-xs font-semibold text-pw-black mb-2">
          <div className="flex gap-4">
            <span className="flex items-center gap-1">
              <span className="w-2.5 h-2.5 bg-[#7A9EAA] rounded-full inline-block" />
              Confirmed: ${totalConfirmed.toLocaleString()} ({confirmedPercent}%)
            </span>
            <span className="flex items-center gap-1 text-pw-muted">
              <span className="w-2.5 h-2.5 bg-[#7A9EAA]/40 rounded-full inline-block border border-dashed border-[#7A9EAA]/60" />
              Committed: ${totalCommitted.toLocaleString()} ({committedPercent}%)
            </span>
          </div>
          <span className="text-pw-muted">Target Raise: ${raiseTarget.toLocaleString()}</span>
        </div>

        {/* Custom Progress bar */}
        <div className="w-full h-3.5 bg-pw-black/10 rounded-full overflow-hidden relative">
          {/* Shaded/Striped Committed Bar */}
          <div 
            className="absolute left-0 top-0 h-full bg-[#7A9EAA]/30 transition-all duration-500 rounded-full"
            style={{ width: `${committedPercent}%` }}
          />
          {/* Solid Confirmed Bar */}
          <div 
            className="absolute left-0 top-0 h-full bg-gradient-to-r from-[#7A9EAA] to-[#60828f] transition-all duration-500 rounded-full"
            style={{ width: `${confirmedPercent}%` }}
          />
        </div>
      </div>

      {/* Table view */}
      {commitments.length === 0 ? (
        <div className="p-8 text-center text-pw-muted">
          <AlertCircle className="w-8 h-8 mx-auto mb-2 opacity-40 text-pw-muted" />
          <p className="text-sm font-medium">No contribution records configured.</p>
          <p className="text-xs mt-1 font-light">Add LeadInvestor or Investor capital records using the action above.</p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs">
            <thead>
              <tr className="border-b border-pw-border bg-pw-bg/30 text-pw-muted uppercase font-bold tracking-wider">
                <th className="px-6 py-3">Party Name</th>
                <th className="px-6 py-3">Role</th>
                <th className="px-6 py-3">Status</th>
                <th className="px-6 py-3 text-right">Committed</th>
                <th className="px-6 py-3 text-right">Confirmed</th>
                <th className="px-6 py-3 text-right">Equity %</th>
                <th className="px-6 py-3 text-center">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-pw-border text-pw-black">
              {commitments.map((c) => {
                const isFunded = c.status === 'funds-confirmed' || c.status === 'cleared';
                const commVal = (c.amountCents ?? 0) / 100;
                const confVal = isFunded ? commVal : 0;
                const eqPct = raiseTarget > 0 ? (commVal / raiseTarget) * 100 : 0;

                return (
                  <tr key={c.id} className="hover:bg-pw-bg/10 transition-colors">
                    <td className="px-6 py-3">
                      <div className="font-semibold">{c.name}</div>
                      <div className="text-[10px] text-pw-muted font-light">{c.email || 'No email configured'}</div>
                    </td>
                    <td className="px-6 py-3 font-medium text-pw-muted">
                      {c.partyType || 'Investor'}
                    </td>
                    <td className="px-6 py-3">
                      <span className={`px-2 py-0.5 text-[10px] rounded-full uppercase font-medium tracking-wide ${getStatusBadgeStyles(c.status)}`}>
                        {c.status.replace('-', ' ')}
                      </span>
                    </td>
                    <td className="px-6 py-3 text-right font-medium">
                      ${commVal.toLocaleString()}
                    </td>
                    <td className="px-6 py-3 text-right font-bold text-[#047857]">
                      {isFunded ? `$${confVal.toLocaleString()}` : '$0.00'}
                    </td>
                    <td className="px-6 py-3 text-right font-semibold text-pw-muted">
                      {eqPct.toFixed(2)}%
                    </td>
                    <td className="px-6 py-3 text-center">
                      <div className="flex justify-center items-center gap-2">
                        <button 
                          onClick={() => openEdit(c)}
                          className="p-1 hover:text-[#7A9EAA] hover:bg-pw-bg rounded"
                          title="Edit Record"
                        >
                          <Edit3 className="w-3.5 h-3.5" />
                        </button>
                        <button 
                          onClick={() => handleDelete(c.id)}
                          className="p-1 hover:text-red-600 hover:bg-pw-bg rounded"
                          title="Delete Record"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Modal Add */}
      {showAddModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-pw-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="glass-card w-full max-w-md p-6 bg-pw-white border border-pw-border space-y-4">
            <div className="flex justify-between items-center border-b border-pw-border pb-3">
              <h3 className="text-sm font-semibold uppercase tracking-wider text-pw-black">
                Add Contribution Record
              </h3>
              <button onClick={() => setShowAddModal(false)} className="text-pw-muted hover:text-pw-black">
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleAddSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Party Name</label>
                <input 
                  type="text" 
                  value={formName} 
                  onChange={(e) => setFormName(e.target.value)} 
                  required
                  placeholder="e.g. Apex LeadInvestor Equity"
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Email (Optional)</label>
                <input 
                  type="email" 
                  value={formEmail} 
                  onChange={(e) => setFormEmail(e.target.value)} 
                  placeholder="e.g. leadInvestor@apexcapital.io"
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Role / Party Type</label>
                  <select 
                    value={formPartyType} 
                    onChange={(e) => setFormPartyType(e.target.value as CapitalPartyType)}
                    className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                  >
                    <option value="Investor">Investor</option>
                    <option value="LeadInvestor">LeadInvestor</option>
                    <option value="Co-GP">Co-GP</option>
                    <option value="Preferred Equity">Preferred Equity</option>
                  </select>
                </div>

                <div>
                  <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Initial Status</label>
                  <select 
                    value={formStatus} 
                    onChange={(e) => setFormStatus(e.target.value as CommitmentStatus)}
                    className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                  >
                    <option value="pledged">Pledged</option>
                    <option value="soft-committed">Soft Committed</option>
                    <option value="docs-out">Docs Out</option>
                    <option value="signed">Signed</option>
                    <option value="funds-confirmed">Funds Confirmed</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Committed Amount ($ USD)</label>
                <input 
                  type="number" 
                  step="0.01"
                  value={formAmount} 
                  onChange={(e) => setFormAmount(e.target.value)} 
                  required
                  placeholder="e.g. 50000"
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded font-medium"
                />
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Notes (Optional)</label>
                <textarea 
                  value={formNotes} 
                  onChange={(e) => setFormNotes(e.target.value)} 
                  rows={2}
                  placeholder="Additional context/evidence description..."
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-pw-border">
                <button 
                  type="button" 
                  onClick={() => setShowAddModal(false)}
                  className="px-3 py-1.5 border border-pw-border text-pw-black hover:bg-pw-bg uppercase font-bold tracking-wider"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  disabled={submitting}
                  className="px-3 py-1.5 text-pw-white bg-[#7A9EAA] hover:bg-[#688a95] uppercase font-bold tracking-wider flex items-center gap-1"
                >
                  {submitting && <Loader2 className="w-3 h-3 animate-spin" />}
                  Save Record
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal Edit */}
      {showEditModal && activeCommitment && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-pw-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="glass-card w-full max-w-md p-6 bg-pw-white border border-pw-border space-y-4">
            <div className="flex justify-between items-center border-b border-pw-border pb-3">
              <h3 className="text-sm font-semibold uppercase tracking-wider text-pw-black">
                Edit Contribution Record
              </h3>
              <button onClick={() => setShowEditModal(false)} className="text-pw-muted hover:text-pw-black">
                <X className="w-4 h-4" />
              </button>
            </div>

            <form onSubmit={handleEditSubmit} className="space-y-4 text-xs">
              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Party Name</label>
                <input 
                  type="text" 
                  value={formName} 
                  onChange={(e) => setFormName(e.target.value)} 
                  required
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Email</label>
                <input 
                  type="email" 
                  value={formEmail} 
                  onChange={(e) => setFormEmail(e.target.value)} 
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Role / Party Type</label>
                  <select 
                    value={formPartyType} 
                    onChange={(e) => setFormPartyType(e.target.value as CapitalPartyType)}
                    className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                  >
                    <option value="Investor">Investor</option>
                    <option value="LeadInvestor">LeadInvestor</option>
                    <option value="Co-GP">Co-GP</option>
                    <option value="Preferred Equity">Preferred Equity</option>
                  </select>
                </div>

                <div>
                  <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Status</label>
                  <select 
                    value={formStatus} 
                    onChange={(e) => setFormStatus(e.target.value as CommitmentStatus)}
                    className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                  >
                    <option value="pledged">Pledged</option>
                    <option value="soft-committed">Soft Committed</option>
                    <option value="docs-out">Docs Out</option>
                    <option value="signed">Signed</option>
                    <option value="funds-confirmed">Funds Confirmed</option>
                  </select>
                </div>
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Committed Amount ($ USD)</label>
                <input 
                  type="number" 
                  step="0.01"
                  value={formAmount} 
                  onChange={(e) => setFormAmount(e.target.value)} 
                  required
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded font-medium"
                />
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Evidence (e.g. Wire Reference)</label>
                <input 
                  type="text" 
                  value={formEvidence} 
                  onChange={(e) => setFormEvidence(e.target.value)} 
                  placeholder="Reference/confirmation number for signed/funded steps..."
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div>
                <label className="block font-medium mb-1 uppercase tracking-wider text-pw-muted">Notes (Optional)</label>
                <textarea 
                  value={formNotes} 
                  onChange={(e) => setFormNotes(e.target.value)} 
                  rows={2}
                  className="w-full p-2 border border-pw-border bg-pw-white focus:outline-none focus:border-[#7A9EAA] text-pw-black rounded"
                />
              </div>

              <div className="flex justify-end gap-2 pt-3 border-t border-pw-border">
                <button 
                  type="button" 
                  onClick={() => setShowEditModal(false)}
                  className="px-3 py-1.5 border border-pw-border text-pw-black hover:bg-pw-bg uppercase font-bold tracking-wider"
                >
                  Cancel
                </button>
                <button 
                  type="submit" 
                  disabled={submitting}
                  className="px-3 py-1.5 text-pw-white bg-[#7A9EAA] hover:bg-[#688a95] uppercase font-bold tracking-wider flex items-center gap-1"
                >
                  {submitting && <Loader2 className="w-3 h-3 animate-spin" />}
                  Save Changes
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useEffect, useState, useCallback } from 'react';
import { Users, TrendingUp, Plus, X, Loader2, AlertCircle } from 'lucide-react';
import { collection, onSnapshot, orderBy, query, where } from 'firebase/firestore';
import { getAuth } from 'firebase/auth';
import { db } from '@/lib/firebase/config';
import Link from 'next/link';

/* ═══════════════════════════════════════════════════════════════
   CrowdfundingTracker
   ───────────────────────────────────────────────────────────────
   Real-time capital raise tracker wired to:
     - Firestore  projects/{projectId}/commitments  (live read)
     - API  /api/projects/[id]/commitments          (writes)
     - API  /api/projects/[id]/commitments/[cId]    (PATCH/DELETE)

   All writes are token-authenticated server-side.
   Progress bar, investor list, and totals update in real time
   as commitments change (cross-tab / multi-user safe).
   ═══════════════════════════════════════════════════════════════ */

export interface Commitment {
  id: string;
  name: string;
  email?: string | null;
  amountCents: number;
  status: 'pledged' | 'transferred' | 'cleared';
  notes?: string | null;
  createdAt?: string | null;
}

interface CrowdfundingTrackerProps {
  projectId: string;
  /** Capital raise target in cents (e.g. rehabBudget or equity gap) */
  targetCents?: number;
  phaseColor?: string;
  /** Called whenever the total committed cents changes */
  onTotalChange?: (totalCents: number) => void;
}

const STATUS_LABELS: Record<Commitment['status'], string> = {
  pledged:     'Soft-Committed',
  transferred: 'LOI In Review',
  cleared:     'Confirmed Interest',
};
const STATUS_ORDER: Commitment['status'][] = ['pledged', 'transferred', 'cleared'];

const STATUS_COLORS: Record<Commitment['status'], { bg: string; text: string; border: string }> = {
  pledged:     { bg: '#FFF7ED', text: '#C2410C', border: '#FED7AA' },
  transferred: { bg: '#EFF6FF', text: '#1D4ED8', border: '#BFDBFE' },
  cleared:     { bg: '#F0FDF4', text: '#15803D', border: '#BBF7D0' },
};

function fmt(cents: number) {
  return `$${(cents / 100).toLocaleString('en-US', { minimumFractionDigits: 0 })}`;
}

async function getToken(): Promise<string | null> {
  const auth = getAuth();
  return auth.currentUser?.getIdToken() ?? null;
}

export function CrowdfundingTracker({
  projectId,
  targetCents = 0,
  phaseColor = '#595959',
  onTotalChange,
}: CrowdfundingTrackerProps) {
  const [commitments, setCommitments] = useState<Commitment[]>([]);
  const [synced, setSynced]           = useState(false);
  const [adding, setAdding]           = useState(false);
  const [saving, setSaving]           = useState(false);
  const [error, setError]             = useState<string | null>(null);

  /* ── Draft form state ── */
  const [draftName,   setDraftName]   = useState('');
  const [draftEmail,  setDraftEmail]  = useState('');
  const [draftAmount, setDraftAmount] = useState('');
  const [draftStatus, setDraftStatus] = useState<Commitment['status']>('pledged');

  /* ── Real-time Firestore subscription ── */
  useEffect(() => {
    if (!projectId) return;

    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_commitments_${projectId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          if (val) {
            setCommitments(JSON.parse(val));
          } else {
            setCommitments([]);
          }
          setSynced(true);
        } catch (e) {
          console.error(e);
        }
      };
      load();

      const handleStorage = (e: StorageEvent) => {
        if (e.key === key) load();
      };
      window.addEventListener('storage', handleStorage);
      const handleCustom = () => load();
      window.addEventListener(`update_${key}`, handleCustom);

      return () => {
        window.removeEventListener('storage', handleStorage);
        window.removeEventListener(`update_${key}`, handleCustom);
      };
    }

    const q = query(
      collection(db, 'projects', projectId, 'commitments'),
      orderBy('createdAt', 'asc')
    );
    const unsub = onSnapshot(
      q,
      (snap) => {
        const docs: Commitment[] = snap.docs.map((d) => ({
          id: d.id,
          name: d.data().name,
          email: d.data().email ?? null,
          amountCents: d.data().amountCents,
          status: d.data().status,
          notes: d.data().notes ?? null,
          createdAt: d.data().createdAt?.toDate?.().toISOString() ?? null,
        }));
        setCommitments(docs);
        setSynced(true);
      },
      (err) => {
        console.error('[CrowdfundingTracker] onSnapshot error:', err);
        setSynced(true);
      }
    );
    return unsub;
  }, [projectId]);

  const [negotiations, setNegotiations] = useState<any[]>([]);

  useEffect(() => {
    if (!projectId) return;

    const q = query(
      collection(db, 'negotiations'),
      where('projectId', '==', projectId)
    );

    const unsub = onSnapshot(
      q,
      (snap) => {
        const docs = snap.docs.map((d) => d.data());
        setNegotiations(docs);
      },
      (err) => {
        console.error('Load negotiations in tracker error:', err);
      }
    );

    return unsub;
  }, [projectId]);

  // Compute negotiation rollups
  const negSoftCents = negotiations
    .filter((n) => n.status !== 'transaction_confirmed' && n.status !== 'declined' && 
      (n.status === 'accepted' || n.status === 'terms_confirmed' || n.status === 'transaction_pending' || 
       (n.status === 'active' && !n.currentTerms?.isCounter)))
    .reduce((sum, n) => sum + (n.currentTerms?.contribution || 0), 0);

  const negCounterCents = negotiations
    .filter((n) => n.status === 'active' && n.currentTerms?.isCounter)
    .reduce((sum, n) => sum + (n.currentTerms?.contribution || 0), 0);

  /* ── Notify parent of total changes ── */
  const clearedCents     = commitments.filter(c => c.status === 'cleared').reduce((s, c) => s + c.amountCents, 0);
  const transferredCents = commitments.filter(c => c.status === 'transferred').reduce((s, c) => s + c.amountCents, 0);
  const pledgedCents     = commitments.filter(c => c.status === 'pledged').reduce((s, c) => s + c.amountCents, 0);
  const raisedCents      = clearedCents + transferredCents + pledgedCents + negSoftCents;
  const progressPct      = targetCents > 0 ? Math.min((raisedCents / targetCents) * 100, 100) : 0;

  useEffect(() => {
    onTotalChange?.(raisedCents);
  }, [raisedCents, onTotalChange]);

  /* ── Write helpers ── */
  const handleAdd = useCallback(async () => {
    const amt = Math.round(parseFloat(draftAmount.replace(/[^0-9.]/g, '')) * 100);
    if (!draftName.trim() || isNaN(amt) || amt <= 0) return;
    setSaving(true);
    setError(null);
    try {
      const token = await getToken();
      const res = await fetch(`/api/projects/${projectId}/commitments`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({
          name:        draftName.trim(),
          email:       draftEmail.trim() || undefined,
          amountCents: amt,
          status:      draftStatus,
        }),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body.error || `HTTP ${res.status}`);
      }
      setDraftName('');
      setDraftEmail('');
      setDraftAmount('');
      setDraftStatus('pledged');
      setAdding(false);
    } catch (err: any) {
      setError(err.message ?? 'Failed to add commitment');
    } finally {
      setSaving(false);
    }
  }, [projectId, draftName, draftEmail, draftAmount, draftStatus]);

  const handleCycleStatus = useCallback(async (c: Commitment) => {
    const idx = STATUS_ORDER.indexOf(c.status);
    const next = STATUS_ORDER[(idx + 1) % STATUS_ORDER.length];
    try {
      const token = await getToken();
      const res = await fetch(`/api/projects/${projectId}/commitments/${c.id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ status: next }),
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body.error || `HTTP ${res.status}`);
      }
    } catch (err: any) {
      setError(err.message ?? 'Failed to update status');
    }
  }, [projectId]);

  const handleRemove = useCallback(async (id: string) => {
    try {
      const token = await getToken();
      const res = await fetch(`/api/projects/${projectId}/commitments/${id}`, {
        method: 'DELETE',
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      });
      if (!res.ok) {
        const body = await res.json().catch(() => ({}));
        throw new Error(body.error || `HTTP ${res.status}`);
      }
    } catch (err: any) {
      setError(err.message ?? 'Failed to remove commitment');
    }
  }, [projectId]);

  /* ── Skeleton while Firestore hasn't fired yet ── */
  if (!synced) {
    return (
      <div
        className="rounded-lg overflow-hidden animate-pulse"
        style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-ui)' }}
      >
        <div className="h-12 rounded-t-lg" style={{ background: phaseColor + '80' }} />
        <div className="p-6 space-y-4">
          <div className="h-3 w-full rounded" style={{ background: 'var(--bg-canvas)' }} />
          <div className="h-3 w-3/4 rounded" style={{ background: 'var(--bg-canvas)' }} />
        </div>
      </div>
    );
  }

  return (
    <div
      className="rounded-lg overflow-hidden"
      style={{ background: 'var(--bg-surface)', border: '1px solid var(--border-ui)' }}
    >
      {/* ── Section header ── */}
      <div
        className="px-6 py-4 flex items-center gap-3"
        style={{ background: phaseColor }}
      >
        <Users className="w-4 h-4 shrink-0" style={{ color: '#FFFFFF' }} />
        <h2
          className="text-[10px] font-bold uppercase tracking-[0.18em] flex-1"
          style={{ color: '#FFFFFF' }}
        >
          Capital Interest Tracker
        </h2>
        <span
          className="text-[9px] font-bold uppercase tracking-[0.1em] px-2 py-0.5 rounded-full"
          style={{ background: 'rgba(255,255,255,0.18)', color: '#FFFFFF' }}
        >
          {commitments.length} investor{commitments.length !== 1 ? 's' : ''}
        </span>
      </div>

      <div className="p-6 space-y-5">

        {/* ── Error banner ── */}
        {error && (
          <div
            className="flex items-start gap-2 px-4 py-3 rounded-md text-xs"
            style={{ background: '#FEF2F2', border: '1px solid #FECACA', color: '#DC2626' }}
          >
            <AlertCircle className="w-4 h-4 mt-0.5 shrink-0" />
            <span>{error}</span>
            <button
              onClick={() => setError(null)}
              className="ml-auto shrink-0 opacity-60 hover:opacity-100"
              aria-label="Dismiss error"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>
        )}

        {/* ── Progress bar & Breakdown ── */}
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <span
              className="text-[10px] font-bold uppercase tracking-[0.14em]"
              style={{ color: 'var(--text-secondary)' }}
            >
              Soft-Committed vs. Target
            </span>
            <span
              className="text-lg font-bold tabular-nums"
              style={{ color: 'var(--text-primary)' }}
            >
              {fmt(raisedCents)}
            </span>
          </div>

          {/* Track */}
          <div
            className="h-3 rounded-full overflow-hidden shadow-inner"
            style={{ background: 'var(--bg-canvas)', border: '1px solid var(--border-ui)' }}
          >
            <div
              className="h-full transition-all duration-500"
              style={{
                width: `${targetCents > 0 ? Math.min((clearedCents / targetCents) * 100, 100) : 0}%`,
                background: '#16A34A',
                float: 'left',
              }}
            />
            <div
              className="h-full transition-all duration-500"
              style={{
                width: `${targetCents > 0 ? Math.min((transferredCents / targetCents) * 100, Math.max(0, 100 - (clearedCents / targetCents) * 100)) : 0}%`,
                background: '#3B82F6',
                float: 'left',
              }}
            />
            <div
              className="h-full transition-all duration-500"
              style={{
                width: `${targetCents > 0 ? Math.min((pledgedCents / targetCents) * 100, Math.max(0, 100 - ((clearedCents + transferredCents) / targetCents) * 100)) : 0}%`,
                background: '#F59E0B',
                float: 'left',
              }}
            />
          </div>

          {/* Numerical Breakdown */}
          <div className="grid grid-cols-4 gap-2 pt-3 text-left" style={{ borderTop: '1px solid var(--border-ui)' }}>
            <div className="flex flex-col gap-1">
              <span className="text-[9px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>
                Target
              </span>
              <span className="text-sm font-semibold tabular-nums" style={{ color: 'var(--text-primary)' }}>
                {targetCents > 0 ? fmt(targetCents) : '—'}
              </span>
            </div>
            <div className="flex flex-col gap-1 border-l pl-3" style={{ borderColor: 'var(--border-ui)' }}>
              <span className="text-[9px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>
                Soft-Committed
              </span>
              <span className="text-sm font-semibold tabular-nums" style={{ color: 'var(--text-primary)' }}>
                {fmt(raisedCents)}
              </span>
            </div>
            <div className="flex flex-col gap-1 border-l pl-3" style={{ borderColor: 'var(--border-ui)' }}>
              <span className="text-[9px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>
                Marketplace Soft
              </span>
              <span className="text-sm font-semibold tabular-nums text-[var(--color-primary)]">
                {fmt(negSoftCents)}
              </span>
            </div>
            <div className="flex flex-col gap-1 border-l pl-3" style={{ borderColor: 'var(--border-ui)' }}>
              <span className="text-[9px] font-bold uppercase tracking-[0.1em] text-amber-500" style={{ color: '#F59E0B' }}>
                Counters
              </span>
              <span className="text-sm font-semibold tabular-nums text-amber-500" style={{ color: '#F59E0B' }}>
                {fmt(negCounterCents)}
              </span>
            </div>
          </div>


          {/* Legend */}
          <div className="flex items-center gap-4 pt-1">
            {[
              { color: '#16A34A', label: 'Confirmed' },
              { color: '#3B82F6', label: 'LOI Pending' },
              { color: '#F59E0B', label: 'Soft-Committed' },
            ].map((l) => (
              <div key={l.label} className="flex items-center gap-1.5">
                <div className="w-2 h-2 rounded-full" style={{ background: l.color }} />
                <span className="text-[9px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>
                  {l.label}
                </span>
              </div>
            ))}
            {targetCents > 0 && (
              <span
                className="ml-auto text-[10px] font-bold tabular-nums"
                style={{ color: phaseColor }}
              >
                {Math.round(progressPct)}%
              </span>
            )}
          </div>
        </div>

        {/* ── Investor Table ── */}
        {commitments.length > 0 && (
          <div className="overflow-x-auto rounded-md" style={{ border: '1px solid var(--border-ui)' }}>
            <table className="w-full text-left border-collapse">
              <thead>
                <tr style={{ background: 'var(--bg-canvas)', borderBottom: '1px solid var(--border-ui)' }}>
                  <th className="px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>Investor</th>
                  <th className="px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>Amount</th>
                  <th className="px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-secondary)' }}>Status</th>
                  <th className="px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em] text-right" style={{ color: 'var(--text-secondary)' }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {commitments.map((c, idx) => {
                  const sc = STATUS_COLORS[c.status];
                  return (
                    <tr
                      key={c.id}
                      style={{ borderBottom: idx === commitments.length - 1 ? 'none' : '1px solid var(--border-ui)' }}
                    >
                      <td className="px-4 py-3">
                        <div className="flex items-center gap-3">
                          <div
                            className="w-6 h-6 rounded-full flex items-center justify-center shrink-0 text-[10px] font-bold"
                            style={{ background: phaseColor + '18', color: phaseColor }}
                          >
                            {c.name.charAt(0).toUpperCase()}
                          </div>
                          <div className="min-w-0">
                            <p className="text-xs font-semibold truncate" style={{ color: 'var(--text-primary)' }}>
                              {c.name}
                            </p>
                            {c.email && (
                              <p className="text-[10px] truncate" style={{ color: 'var(--text-secondary)' }}>
                                {c.email}
                              </p>
                            )}
                          </div>
                        </div>
                      </td>
                      <td className="px-4 py-3 text-xs font-medium tabular-nums" style={{ color: 'var(--text-primary)' }}>
                        {fmt(c.amountCents)}
                      </td>
                      <td className="px-4 py-3">
                        <button
                          onClick={() => handleCycleStatus(c)}
                          className="px-2.5 py-1 rounded-full text-[9px] font-bold uppercase tracking-[0.1em] border transition-all duration-150 hover:opacity-80 cursor-pointer"
                          style={{ background: sc.bg, color: sc.text, borderColor: sc.border }}
                          title="Click to advance status"
                        >
                          {STATUS_LABELS[c.status]}
                        </button>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <button
                          onClick={() => handleRemove(c.id)}
                          className="w-6 h-6 inline-flex items-center justify-center rounded-md transition-colors hover:bg-red-50 cursor-pointer"
                          aria-label="Remove commitment"
                        >
                          <X className="w-3 h-3" style={{ color: 'var(--text-secondary)' }} />
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* ── Marketplace Interest Log (Negotiation Threads) ── */}
        {negotiations.length > 0 && (
          <div className="space-y-3 pt-3" style={{ borderTop: '1px solid var(--border-ui)' }}>
            <h3 className="text-[10px] font-bold uppercase tracking-[0.16em] text-[var(--color-primary)]">
              Marketplace Interest Log (Active Negotiations)
            </h3>
