        {showHistory && (
          <div className="p-4 border-t border-white/5 bg-pw-night-bg/40 space-y-4 animate-in slide-in-from-top-1 duration-200">
            {history.length === 0 ? (
              <p className="text-xs text-[#9E9DA0]/60 text-center py-6">No invitation history log found.</p>
