'use client';

import React, { useState, useEffect } from 'react';
import type { Project } from '@/types/schema';
import { projectsService } from '@/lib/firebase/deals';
import toast from 'react-hot-toast';
import { Landmark, TrendingUp, Key } from 'lucide-react';

interface DeclareStrategyPanelProps {
  project: Project;
  onSaveSuccess: () => void;
}

export function DeclareStrategyPanel({
  project,
  onSaveSuccess,
}: DeclareStrategyPanelProps) {
  const selectedDisp = project.dispositionType;
  const selectedSub = project.subStrategy;

  const [isEditing, setIsEditing] = useState(!project.dispositionType);
  const [holdHorizon, setHoldHorizon] = useState<number | undefined>(project.holdHorizon ?? undefined);
  const [exitAssumption, setExitAssumption] = useState<string>(project.exitAssumption || '');

  useEffect(() => {
    if (!project.dispositionType) {
      setIsEditing(true);
    }
  }, [project.dispositionType]);

  useEffect(() => {
    setHoldHorizon(project.holdHorizon ?? undefined);
    setExitAssumption(project.exitAssumption || '');
  }, [project.holdHorizon, project.exitAssumption]);

  const dispositions = [
    {
      id: 'SALE',
      label: 'Sale',
      description: 'Acquire to sell the property (e.g., Fix & Flip, Wholesale)',
      icon: TrendingUp,
      subStrategies: [
        { id: 'FLIP', label: 'Fix & Flip' },
        { id: 'WHOLESALE', label: 'Wholesale' },
        { id: 'BUILD_SELL', label: 'Build & Sell' },
      ],
    },
    {
      id: 'RENT',
      label: 'Rent',
      description: 'Acquire to lease out for rental cash flow (e.g., BRRRR, Long Term)',
      icon: Landmark,
      subStrategies: [
        { id: 'LONG_TERM', label: 'Long Term' },
        { id: 'SHORT_TERM', label: 'Short Term' },
        { id: 'MID_TERM', label: 'Mid Term' },
        { id: 'BRRRR', label: 'BRRRR' },
      ],
    },
    {
      id: 'LEASE',
      label: 'Lease',
      description: 'Commercial or ground leasing strategy (e.g., Triple Net NNN)',
      icon: Key,
      subStrategies: [
        { id: 'NNN', label: 'NNN (Triple Net)' },
        { id: 'GROUND', label: 'Ground Lease' },
        { id: 'LEASE_OPTION', label: 'Lease Option' },
      ],
    },
  ] as const;

  const handleSelect = async (disp: 'SALE' | 'RENT' | 'LEASE', sub: string | null) => {
    if (!isEditing) return;
    try {
      await projectsService.updateProject(project.id, {
        dispositionType: disp,
        subStrategy: sub as any,
      });

      // Optimistic sync trigger for local postgres DB
      const token = (window as any).firebaseUserToken || '';
      await fetch(`/api/reil/projects/${project.id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          ...(token && { Authorization: `Bearer ${token}` }),
        },
        body: JSON.stringify({
          dispositionType: disp,
          subStrategy: sub,
        }),
      });

      toast.success('Strategy declared successfully!');
      onSaveSuccess();
    } catch (err) {
      console.error(err);
      toast.error('Failed to save strategy.');
    }
  };

  const handleSaveAdditionalFields = async (newHorizon = holdHorizon, newExit = exitAssumption) => {
    if (!isEditing) return;
    try {
      await projectsService.updateProject(project.id, {
        holdHorizon: newHorizon !== undefined ? Number(newHorizon) : undefined,
        exitAssumption: newExit || undefined,
      });

      // Sync to Postgres
      const token = (window as any).firebaseUserToken || '';
      await fetch(`/api/reil/projects/${project.id}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          ...(token && { Authorization: `Bearer ${token}` }),
        },
        body: JSON.stringify({
          holdHorizon: newHorizon !== undefined ? Number(newHorizon) : null,
          exitAssumption: newExit || null,
        }),
      });
      onSaveSuccess();
    } catch (err) {
      console.error(err);
      toast.error('Failed to save exit fields.');
    }
  };

  return (
    <div
      className="p-6 rounded-2xl flex flex-col gap-6"
      style={{
        background: 'var(--color-surface-container-low)',
        border: '1px solid var(--color-glass-card-border)',
        boxShadow: 'var(--color-glass-card-shadow)',
      }}
    >
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-bold" style={{ color: 'var(--color-on-surface)' }}>
            Declare Strategy
          </h3>
          <p className="text-xs" style={{ color: 'var(--color-on-surface-variant)' }}>
            Select the canonical disposition type and matching investment sub-strategy.
          </p>
        </div>
        {project.dispositionType && (
          <button
            onClick={() => setIsEditing(!isEditing)}
            className="px-3 py-1.5 text-xs font-semibold rounded-lg bg-white/5 border border-white/10 hover:bg-white/10 text-white transition-all"
            id="edit-strategy-btn"
          >
            {isEditing ? 'Cancel' : 'Edit'}
          </button>
        )}
      </div>

      {/* Dispositions Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        {dispositions.map((disp) => {
          const Icon = disp.icon;
          const isSelected = selectedDisp === disp.id;
          return (
            <div
              key={disp.id}
              onClick={() => isEditing && handleSelect(disp.id, null)}
              className={`p-4 rounded-xl flex flex-col gap-3 transition-all ${
                !isEditing ? 'cursor-not-allowed opacity-80' : 'cursor-pointer hover:scale-[1.01]'
              }`}
              style={{
                background: isSelected
                  ? 'var(--color-primary-container)'
                  : 'rgba(255, 255, 255, 0.02)',
                border: isSelected
                  ? '2px solid var(--color-primary)'
                  : '1px solid var(--color-glass-card-border)',
              }}
            >
              <div className="flex items-center gap-2">
                <div
                  className="w-8 h-8 rounded-lg flex items-center justify-center"
                  style={{
                    background: isSelected ? 'var(--color-primary)' : 'rgba(255, 255, 255, 0.05)',
                    color: isSelected ? 'var(--color-on-primary)' : 'var(--color-on-surface-variant)',
                  }}
                >
                  <Icon size={18} />
                </div>
                <span className="font-bold text-sm" style={{ color: 'var(--color-on-surface)' }}>
                  {disp.label}
                </span>
              </div>
              <p className="text-[11px] leading-relaxed" style={{ color: 'var(--color-on-surface-variant)' }}>
                {disp.description}
              </p>
            </div>
          );
        })}
      </div>

      {/* Sub Strategies list */}
      {selectedDisp && (
        <div className="flex flex-col gap-3 pt-2">
          <span className="text-[11px] font-bold uppercase tracking-wider" style={{ color: 'var(--color-on-surface-variant)' }}>
            Choose Sub-Strategy
          </span>
          <div className="flex flex-wrap gap-2">
            {dispositions
              .find((d) => d.id === selectedDisp)
              ?.subStrategies.map((sub) => {
                const isSelected = selectedSub === sub.id;
                return (
                  <button
                    key={sub.id}
                    disabled={!isEditing}
                    onClick={() => handleSelect(selectedDisp, sub.id)}
                    className="px-4 py-2 text-xs font-semibold rounded-lg transition-all"
                    style={{
                      background: isSelected ? 'var(--color-primary)' : 'rgba(255, 255, 255, 0.03)',
                      color: isSelected ? 'var(--color-on-primary)' : 'var(--color-on-surface)',
                      border: isSelected
                        ? '1px solid var(--color-primary)'
                        : '1px solid var(--color-glass-card-border)',
                      cursor: isEditing ? 'pointer' : 'not-allowed',
                    }}
                  >
                    {sub.label}
                  </button>
                );
              })}
          </div>
        </div>
      )}

      {/* Hold Horizon & Exit Assumption */}
      {selectedDisp && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-4 border-t border-white/5">
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold uppercase tracking-wider text-[#9E9DA0]">
              Hold Horizon (Years)
            </label>
            <input
              type="number"
              disabled={!isEditing}
              value={holdHorizon ?? ''}
              onChange={(e) => setHoldHorizon(e.target.value ? parseInt(e.target.value) : undefined)}
              onBlur={() => handleSaveAdditionalFields()}
              placeholder="e.g. 5"
              className="w-full p-3 rounded-lg text-sm bg-black/30 border border-white/10 text-white focus:outline-none focus:border-primary/50 disabled:opacity-50 disabled:cursor-not-allowed"
              id="hold-horizon-input"
            />
          </div>
          <div className="flex flex-col gap-1.5">
            <label className="text-xs font-bold uppercase tracking-wider text-[#9E9DA0]">
              Exit Assumption
            </label>
            <input
              type="text"
              disabled={!isEditing}
              value={exitAssumption}
              onChange={(e) => setExitAssumption(e.target.value)}
              onBlur={() => handleSaveAdditionalFields()}
              placeholder="e.g. 6.5% exit cap rate"
              className="w-full p-3 rounded-lg text-sm bg-black/30 border border-white/10 text-white focus:outline-none focus:border-primary/50 disabled:opacity-50 disabled:cursor-not-allowed"
              id="exit-assumption-input"
            />
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useRef } from "react";
import { UploadCloud, FileText, CheckCircle2, AlertCircle, Loader2, X } from "lucide-react";
import toast from "react-hot-toast";
import { useTheme } from "@/lib/utils/ThemeProvider";

export interface OptimisticFileItem {
  id: string;
  name: string;
  size: number;
  status: "uploading" | "completed" | "error";
  progress: number;
  error?: string;
}

interface DocumentUploadCardProps {
  projectId: string;
  category?: string;
  onUploadSuccess?: (doc: any) => void;
  uploadUrl?: string;
}

export function DocumentUploadCard({
  projectId,
  category = "General Disclosures",
  onUploadSuccess,
  uploadUrl,
}: DocumentUploadCardProps) {
  const { theme } = useTheme();
  const isDark = theme === "dark";
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [files, setFiles] = useState<OptimisticFileItem[]>([]);

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const selectedFiles = Array.from(e.target.files || []);
    if (selectedFiles.length === 0) return;

    for (const file of selectedFiles) {
      const tempId = `opt_${Date.now()}_${Math.random().toString(36).substr(2, 6)}`;
      const newFileItem: OptimisticFileItem = {
        id: tempId,
        name: file.name,
        size: file.size,
        status: "uploading",
        progress: 10,
      };

      // 1. INSTANT OPTIMISTIC UI ADDITION
      setFiles((prev) => [newFileItem, ...prev]);

      try {
        const formData = new FormData();
        formData.append("file", file);
        formData.append("category", category);
        formData.append("projectId", projectId);

        const targetUrl = uploadUrl || `/api/projects/${projectId}/documents`;
        const res = await fetch(targetUrl, {
          method: "POST",
          body: formData,
        });

        if (!res.ok) {
          throw new Error(`Upload failed with status ${res.status}`);
        }

        const data = await res.json();

        // 2. RECONCILE ON SUCCESS
        setFiles((prev) =>
          prev.map((item) =>
            item.id === tempId ? { ...item, status: "completed", progress: 100 } : item
          )
        );
        toast.success(`Uploaded ${file.name} successfully`);
        if (onUploadSuccess) onUploadSuccess(data);
      } catch (err: any) {
        // 3. ROLLBACK ON FAILURE
        setFiles((prev) => prev.filter((item) => item.id !== tempId));
        toast.error(`Failed to upload ${file.name}: ${err.message || "Server error"}`);
      }
    }

    if (fileInputRef.current) fileInputRef.current.value = "";
  };

  return (
    <div
      data-testid="document-upload-card"
      className="w-full p-5 rounded-2xl border border-solid transition-all"
      style={{
        background: isDark ? "rgba(18,16,20,0.85)" : "#FFFFFF",
        borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(69,73,85,0.12)",
      }}
    >
      <div className="flex items-center justify-between mb-4">
        <div>
          <h3
            className="text-sm font-bold truncate"
            style={{ color: isDark ? "#FDFFFC" : "#121317" }}
          >
            Document Upload Vault
          </h3>
          <p
            className="text-xs opacity-60 mt-0.5"
            style={{ color: isDark ? "#FDFFFC" : "#454955" }}
          >
            Category: {category}
          </p>
        </div>

        <button
          type="button"
          onClick={() => fileInputRef.current?.click()}
          className="px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 transition-all active:scale-95 cursor-pointer"
          style={{
            background: isDark ? "rgba(255,255,255,0.08)" : "rgba(69,73,85,0.08)",
            color: isDark ? "#FDFFFC" : "#121317",
            border: isDark ? "1px solid rgba(255,255,255,0.1)" : "1px solid rgba(69,73,85,0.15)",
          }}
        >
          <UploadCloud className="w-4 h-4 text-emerald-500" />
          <span>Upload File</span>
        </button>

        <input
          ref={fileInputRef}
          type="file"
          data-testid="file-upload-input"
          onChange={handleFileSelect}
          className="hidden"
        />
      </div>

      {/* Optimistic Files List */}
      {files.length > 0 && (
        <div className="space-y-2 mt-3">
          {files.map((file) => (
            <div
              key={file.id}
              data-testid="optimistic-file-row"
              className="p-3 rounded-xl border border-solid flex items-center justify-between gap-3 text-xs"
              style={{
                background: isDark ? "rgba(255,255,255,0.03)" : "rgba(69,73,85,0.02)",
                borderColor: isDark ? "rgba(255,255,255,0.06)" : "rgba(69,73,85,0.08)",
              }}
            >
              <div className="flex items-center gap-2.5 min-w-0">
                <FileText className="w-4 h-4 text-emerald-500 shrink-0" />
                <span
                  className="font-semibold truncate"
                  style={{ color: isDark ? "#FDFFFC" : "#121317" }}
                >
                  {file.name}
                </span>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                <span
                  data-testid="upload-status"
                  className="text-[11px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full"
                  style={{
                    background:
                      file.status === "uploading"
                        ? "rgba(245,158,11,0.12)"
                        : file.status === "completed"
                        ? "rgba(63,125,32,0.15)"
                        : "rgba(240,101,67,0.15)",
                    color:
                      file.status === "uploading"
                        ? "#F59E0B"
                        : file.status === "completed"
                        ? "#3f7d20"
                        : "#F06543",
                  }}
                >
                  {file.status === "uploading" ? (
                    <span className="flex items-center gap-1">
                      <Loader2 className="w-3 h-3 animate-spin" /> Uploading...
                    </span>
                  ) : file.status === "completed" ? (
                    <span className="flex items-center gap-1">
                      <CheckCircle2 className="w-3 h-3" /> Complete
                    </span>
                  ) : (
                    <span className="flex items-center gap-1">
                      <AlertCircle className="w-3 h-3" /> Error
                    </span>
                  )}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import React, { useState, useRef, useCallback, DragEvent, ChangeEvent } from 'react';
import { UploadCloud, File as FileIcon, Trash2, Loader2, Download, Folder, CheckCircle, XCircle, RefreshCw } from 'lucide-react';
import { RoleLinkedDocument, DocumentCategory } from '@/types/schema';
import { ref, uploadBytesResumable, getDownloadURL, deleteObject } from 'firebase/storage';
import { storage, auth as firebaseAuth } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';
interface DocumentVaultProps {
  projectId: string;
  documents?: RoleLinkedDocument[];
  onChange?: (documents: RoleLinkedDocument[]) => void;
  categories?: DocumentCategory[];
  title?: string;
  description?: string;
}

interface UploadProgress {
  id: string;
  fileName: string;
  progress: number;
  category: DocumentCategory;
}

const VAULT_CATEGORIES: DocumentCategory[] = [
  'Loan Processing Documents',
  'Real Estate Attorney Documents',
  'General Sale Disclosures'
];

export function DocumentVault({ 
  projectId, 
  documents = [], 
  onChange,
  categories = VAULT_CATEGORIES,
  title = "Phase 2 Vault",
  description = "Organize and upload documentation directly into strict categories."
}: DocumentVaultProps) {
  const [dragActiveCategory, setDragActiveCategory] = useState<DocumentCategory | null>(null);
  const [uploadingFiles, setUploadingFiles] = useState<UploadProgress[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [selectedCategory, setSelectedCategory] = useState<DocumentCategory | null>(null);
  const { user } = useAuth();
  const handleToggleVerification = useCallback((docId: string) => {
    if (onChange) {
      const updatedDocs = documents.map(doc => {
        if (doc.id === docId) {
          const nextVerified = !doc.verified;
          const nextStatus: 'Verified' | 'Under Review' = nextVerified ? 'Verified' : 'Under Review';
          return {
            ...doc,
            verified: nextVerified,
            status: nextStatus,
          };
        }
        return doc;
      });
      onChange(updatedDocs);
      const targetDoc = documents.find(d => d.id === docId);
      if (targetDoc) {
        toast.success(!targetDoc.verified ? 'Document verified successfully' : 'Document marked as Under Review');
      }
    }
  }, [documents, onChange]);

  const handleDragOver = (e: DragEvent<HTMLDivElement>, category: DocumentCategory) => {
    e.preventDefault();
    setDragActiveCategory(category);
  };

  const handleDragLeave = (e: DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    setDragActiveCategory(null);
  };

  const handleDrop = (e: DragEvent<HTMLDivElement>, category: DocumentCategory) => {
    e.preventDefault();
    setDragActiveCategory(null);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      handleFiles(Array.from(e.dataTransfer.files), category);
    }
  };

  const handleFileInput = (e: ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0 && selectedCategory) {
      handleFiles(Array.from(e.target.files), selectedCategory);
    }
    setSelectedCategory(null);
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  const openFileDialog = (category: DocumentCategory) => {
    setSelectedCategory(category);
    fileInputRef.current?.click();
  };

  const handleFiles = async (files: File[], category: DocumentCategory) => {
    if (!user) {
      toast.error('You must be logged in to upload documents');
      return;
    }

    const newDocs: RoleLinkedDocument[] = [];
    const newUploads = files.map(f => ({ id: crypto.randomUUID(), fileName: f.name, progress: 0, category }));
    setUploadingFiles(prev => [...prev, ...newUploads]);

    for (let i = 0; i < files.length; i++) {
      const file = files[i];
      const uploadId = newUploads[i].id;

      const fileRef = ref(storage, `projects/${projectId}/documents/${uploadId}_${file.name}`);
      const uploadTask = uploadBytesResumable(fileRef, file);

      try {
        await new Promise<void>((resolve, reject) => {
          uploadTask.on(
            'state_changed',
            (snapshot) => {
              const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
              setUploadingFiles(prev => prev.map(u => u.id === uploadId ? { ...u, progress } : u));
            },
            (error) => {
              console.error('Upload failed', error);
              toast.error(`Failed to upload ${file.name}`);
              setUploadingFiles(prev => prev.filter(u => u.id !== uploadId));
              reject(error);
            },
            async () => {
              try {
                const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);
                 const doc: RoleLinkedDocument = {
                  id: uploadId,
                  category,
                  fileName: file.name,
                  fileUrl: downloadURL,
                  linkedRole: 'Loan Officer/Broker', // Defaulting as we don't map specific roles here
                  uploadedByUid: user.uid,
                  uploadedByName: user.displayName || user.email || 'Unknown User',
                  uploadedAt: new Date(),
                  verified: false,
                  notes: '',
                  status: 'Uploaded'
                };
                newDocs.push(doc);
                setUploadingFiles(prev => prev.filter(u => u.id !== uploadId));
                resolve();
              } catch (err) {
                reject(err);
              }
            }
          );
        });
      } catch (err) {
        // Error handled in callback
      }
    }

    if (newDocs.length > 0 && onChange) {
      onChange([...documents, ...newDocs]);
      toast.success('Documents uploaded successfully');

      try {
        import('@/store/uiStore').then(({ useUIStore }) => {
          useUIStore.getState().triggerSuccessfulAction('document_uploaded');
        });
      } catch (err) {
        console.error('Failed to trigger document_uploaded successful action:', err);
      }
    }
  };

  const removeDocument = async (id: string, fileUrl?: string) => {
    if (fileUrl) {
      try {
        const fileRef = ref(storage, fileUrl);
        await deleteObject(fileRef);
      } catch (err) {
        console.error('Failed to delete file from storage:', err);
      }
    }
    if (onChange) {
      onChange(documents.filter(doc => doc.id !== id));
    }
  };

  return (
    <div className="p-6 rounded-lg shadow-sm border bg-bg-surface border-border-ui">
      <div className="mb-6">
        <h2 className="text-lg font-semibold text-text-primary">{title}</h2>
        <p className="text-sm mt-1 text-text-secondary">
          {description}
        </p>
      </div>

      <input
        type="file"
        ref={fileInputRef}
        onChange={handleFileInput}
        className="hidden"
        multiple
      />

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {categories.map((category) => {
          const categoryDocs = documents.filter(doc => doc.category === category);
          const categoryUploads = uploadingFiles.filter(u => u.category === category);
          const isDragging = dragActiveCategory === category;

          return (
            <div key={category} className="flex flex-col h-full">
              {/* Dropzone Card */}
              <div
                className="relative flex flex-col items-center justify-center p-6 rounded-xl transition-all cursor-pointer min-h-[200px] mb-4 bg-surface-container/30 backdrop-blur-xl border-t border-l border-white/10 shadow-lg overflow-hidden group"
                onDragOver={(e) => handleDragOver(e, category)}
                onDragLeave={handleDragLeave}
                onDrop={(e) => handleDrop(e, category)}
                onClick={() => openFileDialog(category)}
              >
                {/* Inner Dashed Border Indicator */}
                <div className={`absolute inset-3 border-2 border-dashed rounded-lg transition-all duration-300 pointer-events-none ${
                  isDragging 
                    ? 'border-primary bg-primary/10' 
                    : 'border-outline-variant/40 group-hover:border-primary/40 group-hover:bg-primary/5'
                }`} />

                <div className="relative z-10 flex flex-col items-center justify-center">
                  <div className={`w-14 h-14 mb-3 rounded-full flex items-center justify-center shadow-lg transition-all duration-300 ${
                    isDragging 
                      ? 'bg-surface-container-highest text-primary shadow-primary/15 scale-110' 
                      : 'bg-surface-container-highest text-text-secondary shadow-black/5 group-hover:scale-110'
                  }`}>
                    {isDragging ? <UploadCloud className="w-6 h-6" /> : <Folder className="w-6 h-6" />}
                  </div>
                  <h3 className="text-sm font-semibold text-center text-text-primary mb-1">
                    {category}
                  </h3>
                  <p className="text-xs text-center text-text-secondary">
                    Drop files here or click to browse
                  </p>
                </div>
              </div>

              {/* Uploads and Files List */}
              <div className="space-y-2">
                {categoryUploads.map((upload) => (
                  <div 
                    key={upload.id}
                    className="flex flex-col p-3 rounded-lg border-t border-l border-white/10 bg-surface-container/20 backdrop-blur-md shadow-sm"
                  >
                    <div className="flex items-center gap-3 mb-2">
                      <div className="p-1.5 rounded-md bg-surface-container/40 border border-white/5">
                        <Loader2 className="w-4 h-4 text-primary animate-spin" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-xs font-medium text-text-primary truncate">
                          {upload.fileName}
                        </p>
                        <p className="text-[10px] text-text-secondary">
                          {Math.round(upload.progress)}%
                        </p>
                      </div>
                    </div>
                    <div className="w-full bg-surface-container-highest rounded-full h-1 overflow-hidden">
                      <div 
                        className="bg-primary h-1 rounded-full transition-all duration-300" 
                        style={{ width: `${upload.progress}%` }}
                      ></div>
                    </div>
                  </div>
                ))}

                {categoryDocs.map((doc) => {
                  const status = doc.verified 
                    ? 'Verified' 
                    : (doc.status || 'Under Review');

                  const badgeStyles = {
                    'Verified': 'text-pw-success bg-pw-success-container border-pw-success-border',
                    'Under Review': 'text-amber-700 bg-amber-50 border-amber-200',
                    'Uploaded': 'text-blue-700 bg-blue-50 border-blue-200',
                    'Archived': 'text-gray-600 bg-gray-50 border-gray-200',
                  }[status] || 'text-gray-600 bg-gray-50 border-gray-200';

                  return (
                    <div key={doc.id}>
                      <div 
                        className="flex items-center justify-between p-3 rounded-md border bg-bg-default border-border-ui shadow-sm group cursor-default"
                      >
                        <div className="flex items-center gap-3 min-w-0">
                          <div className="p-1.5 rounded-md bg-white border border-border-ui flex-shrink-0">
                            <FileIcon className="w-4 h-4 text-blue-600" />
                          </div>
                          <div className="min-w-0">
                            <p className="text-xs font-medium text-text-primary truncate" title={doc.fileName}>
                              {doc.fileName}
                            </p>
                            <p className="text-[10px] text-text-secondary flex items-center gap-1.5 mt-0.5">
                              <span>
                                {doc.uploadedAt ? (doc.uploadedAt instanceof Date ? doc.uploadedAt : (doc.uploadedAt as any).toDate()).toLocaleDateString() : 'Unknown date'}
                              </span>
                              <span className={`text-[9px] font-bold uppercase px-1.5 py-0.2 rounded border ${badgeStyles}`}>
                                {status}
                              </span>
                            </p>
                          </div>
                        </div>

                        <div className="flex items-center gap-1 flex-shrink-0">
                          {/* File actions */}
                          <div className="flex items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button
                              onClick={(e) => { e.stopPropagation(); handleToggleVerification(doc.id); }}
                              className={`p-1.5 rounded transition-colors ${doc.verified ? 'hover:bg-amber-50 text-amber-600 hover:text-amber-700' : 'hover:bg-green-50 text-gray-400 hover:text-green-600'}`}
                              title={doc.verified ? "Mark as Under Review" : "Verify Document"}
                            >
                              <CheckCircle className="w-4 h-4" />
                            </button>
                            {doc.fileUrl && (
                              <a
                                href={doc.fileUrl}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="p-1.5 rounded hover:bg-gray-100 text-gray-500 hover:text-blue-600 transition-colors"
                                aria-label="Download"
                                onClick={(e) => e.stopPropagation()}
                              >
                                <Download className="w-4 h-4" />
                              </a>
                            )}
                            <button
                              onClick={(e) => { e.stopPropagation(); removeDocument(doc.id, doc.fileUrl); }}
                              className="p-1.5 rounded hover:bg-red-50 text-gray-400 hover:text-red-600 transition-colors"
                              aria-label="Delete"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
                {categoryDocs.length === 0 && categoryUploads.length === 0 && (
                  <div className="p-4 border border-dashed border-border-accent rounded-md flex justify-center items-center h-full">
                    <p className="text-xs text-text-secondary italic">No documents uploaded.</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { Calendar, CheckCircle, Clock, DollarSign } from 'lucide-react';
import { Checkbox } from '../ui';

interface EMDVerificationWidgetProps {
  emdAmount?: number;
  emdClearedDate?: Date | string | null;
  emdVerified?: boolean;
  onVerify: (verified: boolean, clearedDateStr: string | null) => void;
  phaseColor?: string;
  readOnly?: boolean;
}

export function EMDVerificationWidget({
  emdAmount = 0,
  emdClearedDate,
  emdVerified = false,
  onVerify,
  phaseColor = '#595959',
  readOnly = false,
}: EMDVerificationWidgetProps) {

  // Helper to parse the input date consistently
  const parseDate = (d: any): Date | null => {
    if (!d) return null;
    if (d instanceof Date) return d;
    if (d.toDate) return d.toDate(); // Firestore timestamp
    const parsed = new Date(d);
    return isNaN(parsed.getTime()) ? null : parsed;
  };

  const cDate = parseDate(emdClearedDate);

  // Formatting date to YYYY-MM-DD for the native input
  let dateString = '';
  if (cDate) {
    const year = cDate.getFullYear();
    const month = String(cDate.getMonth() + 1).padStart(2, '0');
    const day = String(cDate.getDate()).padStart(2, '0');
    dateString = `${year}-${month}-${day}`;
  }

  const formatCurrency = (value: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      minimumFractionDigits: 0,
      maximumFractionDigits: 0,
    }).format(value);
  };

  const handleCheckboxChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const checked = e.target.checked;
    // If checking, and there's no date string, default to today
    let newDateStr = dateString;
    if (checked && !dateString) {
      const today = new Date();
      const year = today.getFullYear();
      const month = String(today.getMonth() + 1).padStart(2, '0');
      const day = String(today.getDate()).padStart(2, '0');
      newDateStr = `${year}-${month}-${day}`;
    } else if (!checked) {
      newDateStr = '';
    }
    onVerify(checked, newDateStr);
  };

  const handleDateChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    onVerify(!!val, val); // If a date is selected, assume it is verified
  };

  return (
    <div className="rounded-lg overflow-hidden shadow-sm border mt-6" style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
      <div className="px-6 py-4 flex items-center justify-between gap-3" style={{ background: phaseColor }}>
        <div className="flex items-center gap-3">
          <DollarSign className="w-4 h-4" style={{ color: '#FFFFFF' }} />
          <h2 className="text-[10px] font-bold uppercase tracking-[0.18em]" style={{ color: '#FFFFFF' }}>
            Earnest Money Deposit (EMD)
          </h2>
        </div>
      </div>

      <div className="p-6 space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center gap-4 justify-between border-b pb-6" style={{ borderColor: 'var(--border-ui)' }}>
          <div>
            <label className="block text-sm font-bold mb-1" style={{ color: 'var(--text-primary)' }}>EMD Amount</label>
            <p className="text-xl font-medium" style={{ color: 'var(--text-primary)' }}>
              {formatCurrency(emdAmount)}
            </p>
          </div>

          <div className="flex items-center gap-3 bg-opacity-10 px-4 py-2 rounded-md border" style={{ 
            backgroundColor: emdVerified ? 'rgba(34, 197, 94, 0.1)' : 'rgba(245, 158, 11, 0.1)',
            borderColor: emdVerified ? '#3f7d20' : '#F59E0B',
            color: emdVerified ? '#166534' : '#92400E'
          }}>
            {emdVerified ? <CheckCircle className="w-5 h-5 text-green-600" /> : <Clock className="w-5 h-5 text-amber-600" />}
            <span className="text-sm font-bold">
              {emdVerified ? 'Cleared' : 'Pending Verification'}
            </span>
          </div>
        </div>

        <div className="space-y-4">
          <div className="flex items-start gap-3 p-4 rounded-md border transition-colors" style={{ borderColor: 'var(--border-ui)' }}>
            <div className="pt-0.5">
              <Checkbox
                checked={emdVerified}
                onChange={handleCheckboxChange}
                disabled={readOnly}
              />
            </div>
            <div 
              onClick={() => {
                if (!readOnly) {
                  handleCheckboxChange({ target: { checked: !emdVerified } } as any);
                }
              }}
              className="cursor-pointer select-none flex-1"
            >
              <p className="text-sm font-bold" style={{ color: 'var(--text-primary)' }}>Confirm EMD Wired</p>
              <p className="text-xs font-medium mt-1" style={{ color: 'var(--text-secondary)' }}>
                I verify that the earnest money deposit has been wired and cleared by the attorney/escrow account.
              </p>
            </div>
          </div>

          {emdVerified && (
            <div className="p-4 rounded-md border flex flex-col sm:flex-row sm:items-center justify-between gap-4" style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-default)' }}>
              <div>
                <label className="block text-sm font-bold mb-1" style={{ color: 'var(--text-primary)' }}>Funds Cleared Date</label>
                <p className="text-xs font-medium" style={{ color: 'var(--text-secondary)' }}>
                  Log exactly when the funds cleared the account
                </p>
              </div>

              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-4 w-4 text-gray-400" />
                </div>
                <input
                  type="date"
                  value={dateString}
                  onChange={handleDateChange}
                  disabled={readOnly}
                  className="pl-10 pr-4 py-2 w-full sm:w-auto rounded-md border text-sm font-medium focus:outline-none focus:ring-2 focus:ring-blue-500 disabled:opacity-50"
                  style={{ 
                    backgroundColor: 'var(--bg-default)',
                    borderColor: 'var(--border-ui)',
                    color: 'var(--text-primary)'
                  }}
                />
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Calendar, DollarSign, CheckCircle, Clock, ShieldAlert, Paperclip, Trash2 } from 'lucide-react';
import type { Project } from '@/types/schema';
import { toast } from 'react-hot-toast';
import { uploadFile } from '@/lib/storage/uploadService';
import { IS_DEMO_MODE } from '@/lib/config/demo';

interface EarnestMoneyCardProps {
  project: Project;
  onSaveFinancials: (updates: any) => Promise<void>;
  phaseColor?: string;
  readOnly?: boolean;
}

export function EarnestMoneyCard({
  project,
  onSaveFinancials,
  phaseColor = '#595959',
  readOnly = false,
}: EarnestMoneyCardProps) {
  const financials = project.financials || {};

  // Form states
  const [amountStr, setAmountStr] = useState(
    financials.emdAmount 
      ? (financials.emdAmount / 100).toString() 
      : financials.loiEarnestAmount 
      ? (financials.loiEarnestAmount / 100).toString() 
      : ''
  );
  const [escrowHolder, setEscrowHolder] = useState(financials.emdEscrowHolder || '');
  const [dueDate, setDueDate] = useState(financials.emdDueDate || '');
  const [clearedDate, setClearedDate] = useState('');
  const [refundableUntil, setRefundableUntil] = useState(financials.emdRefundableUntilDate || '');
  const [isHardDeposit, setIsHardDeposit] = useState(financials.emdIsHardDeposit || false);
  const [verified, setVerified] = useState(financials.emdVerified || false);
  const [receiptUrl, setReceiptUrl] = useState(financials.emdReceiptUrl || '');
  const [receiptName, setReceiptName] = useState(financials.emdReceiptName || '');
  const [uploadingReceipt, setUploadingReceipt] = useState(false);

  // Helper to parse date to YYYY-MM-DD
  const parseDateStr = (d: any): string => {
    if (!d) return '';
    const dateObj = d instanceof Date ? d : new Date(d);
    if (isNaN(dateObj.getTime())) return '';
    return dateObj.toISOString().split('T')[0];
  };

  useEffect(() => {
    setAmountStr(
      financials.emdAmount 
        ? (financials.emdAmount / 100).toString() 
        : financials.loiEarnestAmount 
        ? (financials.loiEarnestAmount / 100).toString() 
        : ''
    );
    setEscrowHolder(financials.emdEscrowHolder || '');
    setDueDate(financials.emdDueDate || '');
    setClearedDate(parseDateStr(financials.emdClearedDate));
    setRefundableUntil(financials.emdRefundableUntilDate || '');
    setIsHardDeposit(financials.emdIsHardDeposit || false);
    setVerified(financials.emdVerified || false);
    setReceiptUrl(financials.emdReceiptUrl || '');
    setReceiptName(financials.emdReceiptName || '');
  }, [project]);

  const handleSaveField = (fieldName: string, value: any) => {
    onSaveFinancials({ [fieldName]: value });
  };

  const handleAmountChange = (val: string) => {
    setAmountStr(val);
    const num = parseFloat(val);
    if (!isNaN(num) && num >= 0) {
      handleSaveField('emdAmount', Math.round(num * 100));
    } else if (val === '') {
      handleSaveField('emdAmount', 0);
    }
  };

  const handleClearedDateChange = (val: string) => {
    setClearedDate(val);
    const dObj = val ? new Date(val) : null;
    handleSaveField('emdClearedDate', dObj);
  };

  const handleVerifiedToggle = (checked: boolean) => {
    if (readOnly) return;

    // ENFORCEMENT: Deposited requires receipt attachment
    if (checked && !receiptUrl) {
      toast.error('Deposit Receipt PDF must be uploaded before confirming deposit clearance.');
      return;
    }

    setVerified(checked);
    let updates: any = { emdVerified: checked };
    if (checked && !clearedDate) {
      const today = new Date().toISOString().split('T')[0];
      setClearedDate(today);
      updates.emdClearedDate = new Date();
    } else if (!checked) {
      setClearedDate('');
      updates.emdClearedDate = null;
    }
    onSaveFinancials(updates);
  };

  const uploadReceipt = async () => {
    if (readOnly) return;

    if (IS_DEMO_MODE) {
      setUploadingReceipt(true);
      await new Promise((resolve) => setTimeout(resolve, 800));
      const mockUrl = '/mock/documents/Earnest_Money_Receipt_Signed.pdf';
      const mockName = 'Earnest_Money_Receipt_Signed.pdf';
      setReceiptUrl(mockUrl);
      setReceiptName(mockName);
      onSaveFinancials({
        emdReceiptUrl: mockUrl,
        emdReceiptName: mockName
      });
      toast.success('Earnest Money Receipt uploaded successfully! (Demo)');
      setUploadingReceipt(false);
      return;
    }

    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.pdf,image/*';
    input.onchange = async (e: any) => {
      const file = e.target.files?.[0];
      if (!file) return;
      setUploadingReceipt(true);
      const toastId = toast.loading(`Uploading ${file.name}...`);
      try {
        const res = await uploadFile({
          file,
          path: 'escrow_receipts',
          projectId: project.id,
        });
        setReceiptUrl(res.downloadUrl);
        setReceiptName(file.name);
        await onSaveFinancials({
          emdReceiptUrl: res.downloadUrl,
          emdReceiptName: file.name
        });
        toast.success('Document uploaded successfully!', { id: toastId });
      } catch (err: any) {
        console.error('Upload failed:', err);
        toast.error(`Upload failed: ${err.message || 'Unknown error'}`, { id: toastId });
      } finally {
        setUploadingReceipt(false);
      }
    };
    input.click();
  };

  const removeReceipt = () => {
    if (readOnly) return;
    setReceiptUrl('');
    setReceiptName('');
    setVerified(false);
    onSaveFinancials({
      emdReceiptUrl: '',
      emdReceiptName: '',
      emdVerified: false,
      emdClearedDate: null
    });
    setClearedDate('');
    toast.success('Receipt removed. Deposit cleared status reset.');
  };

  return (
    <div className="rounded-lg overflow-hidden border border-white/5 bg-white/5 space-y-6">
      {/* Header Banner */}
      <div className="px-6 py-4 flex items-center justify-between" style={{ background: phaseColor }}>
        <div className="flex items-center gap-3">
          <DollarSign className="w-4 h-4 text-white" />
          <h2 className="text-[10px] font-bold uppercase tracking-[0.18em] text-white">
            Earnest Money Deposit (EMD)
          </h2>
        </div>
        <div className="flex items-center gap-2 bg-white/10 px-3 py-1 rounded-full border border-white/10">
          {verified ? (
            <>
              <CheckCircle className="w-3.5 h-3.5 text-green-400 animate-pulse" />
              <span className="text-[9px] font-bold uppercase tracking-wider text-green-400">Deposited &amp; Cleared</span>
            </>
          ) : (
            <>
              <Clock className="w-3.5 h-3.5 text-amber-400" />
              <span className="text-[9px] font-bold uppercase tracking-wider text-amber-400">Pending Clear</span>
            </>
          )}
        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Core parameters */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">EMD Amount ($)</label>
            <div className="relative">
              <span className="absolute left-3 top-2 text-sm text-[#454955] font-medium">$</span>
              <input
                type="number"
                id="emd-amount"
                value={amountStr}
                onChange={(e) => handleAmountChange(e.target.value)}
                disabled={readOnly}
                placeholder="0"
                className="pl-8 pr-4 py-2 w-full bg-white/5 border border-white/10 rounded-lg text-sm text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50 font-medium"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Escrow Holder</label>
            <input
              type="text"
              id="emd-escrow-holder"
              value={escrowHolder}
              onChange={(e) => {
                setEscrowHolder(e.target.value);
                handleSaveField('emdEscrowHolder', e.target.value);
              }}
              disabled={readOnly}
              placeholder="e.g. Title Company, Escrow Agent"
              className="px-4 py-2 w-full bg-white/5 border border-white/10 rounded-lg text-sm text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50"
            />
          </div>
        </div>

        {/* Date parameters */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 border-b border-white/5 pb-6">
          <div>
            <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Deposit Due Date</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-2.5 h-4 w-4 text-[#454955]" />
              <input
                type="date"
                id="emd-due-date"
                value={dueDate}
                onChange={(e) => {
                  setDueDate(e.target.value);
                  handleSaveField('emdDueDate', e.target.value);
                }}
                disabled={readOnly}
                className="pl-10 pr-4 py-2 w-full bg-white/5 border border-white/10 rounded-lg text-sm text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Refundable Until</label>
            <div className="relative">
              <Calendar className="absolute left-3 top-2.5 h-4 w-4 text-[#454955]" />
              <input
                type="date"
                id="emd-refundable-date"
                value={refundableUntil}
                onChange={(e) => {
                  setRefundableUntil(e.target.value);
                  handleSaveField('emdRefundableUntilDate', e.target.value);
                }}
                disabled={readOnly}
                className="pl-10 pr-4 py-2 w-full bg-white/5 border border-white/10 rounded-lg text-sm text-white focus:outline-none focus:ring-2 focus:ring-[#454955] disabled:opacity-50"
              />
            </div>
          </div>

          <div className="flex flex-col justify-center">
            <span className="block text-xs font-bold text-[#9E9DA0] uppercase tracking-wider mb-2">Hard Deposit Status</span>
            <label className="flex items-center gap-3 cursor-pointer select-none">
              <input
                type="checkbox"
                id="emd-hard-deposit-toggle"
                checked={isHardDeposit}
                onChange={(e) => {
                  setIsHardDeposit(e.target.checked);
                  handleSaveField('emdIsHardDeposit', e.target.checked);
                }}
                disabled={readOnly}
                className="w-4 h-4 rounded bg-white/5 border-white/10 text-[#454955] focus:ring-0 cursor-pointer"
              />
              <span className="text-xs text-white">This EMD is Non-Refundable (Hard)</span>
            </label>
          </div>
        </div>

        {/* Receipt Upload Vault Section */}
        <div className="space-y-4">
          <div>
            <h4 className="text-xs font-bold uppercase tracking-wider text-[#9E9DA0]">Earnest Money Deposit Receipt</h4>
            <p className="text-[10px] text-[#9E9DA0]/60 mt-1">A signed escrow deposit receipt is required to mark the EMD as Deposited &amp; Cleared.</p>
          </div>

          {receiptUrl ? (
            <div className="flex items-center justify-between p-4 bg-white/5 rounded-xl border border-white/5">
              <div className="flex items-center gap-3">
                <Paperclip className="w-5 h-5 text-[#454955]" />
                <div>
                  <p className="text-xs font-bold text-white flex items-center gap-1.5" id="emd-receipt-filename">
                    {receiptName}
                    {IS_DEMO_MODE && <span className="text-[8px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20 font-sans">Demo</span>}
                  </p>
                  <a href={receiptUrl} target="_blank" rel="noreferrer" className="text-[10px] text-[#454955] hover:underline block mt-0.5">Download File</a>
                </div>
              </div>
              <button
                onClick={removeReceipt}
                id="remove-emd-receipt-btn"
                disabled={readOnly}
                className="text-xs text-[#F06543] hover:underline"
              >
                Remove
              </button>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center p-8 bg-white/5 border border-dashed border-white/10 rounded-xl">
              <Paperclip className="w-8 h-8 text-[#9E9DA0]/40 mb-2" />
              <p className="text-xs text-[#9E9DA0] mb-4">No receipt uploaded yet</p>
              <button
                onClick={uploadReceipt}
                id="upload-emd-receipt-btn"
                disabled={readOnly || uploadingReceipt}
                className="px-4 py-2 bg-white/5 border border-white/10 text-white rounded-lg text-xs font-bold uppercase tracking-wider hover:bg-white/10 transition-all disabled:opacity-50"
              >
                {uploadingReceipt ? 'Uploading...' : `Select & Upload Receipt PDF ${IS_DEMO_MODE ? '(Demo)' : ''}`}
              </button>
            </div>
          )}
        </div>

        {/* deposited check */}
        <div className="pt-4 border-t border-white/5">
          <div className={`p-4 rounded-xl border transition-all flex items-start gap-4 ${
            verified ? 'border-green-500/20 bg-green-500/5' : 'border-white/5 bg-white/5'
          }`}>
            <input
              type="checkbox"
              id="emd-verified-checkbox"
              checked={verified}
              onChange={(e) => handleVerifiedToggle(e.target.checked)}
              disabled={readOnly}
              className="mt-1 w-4 h-4 rounded bg-white/5 border-white/10 text-[#454955] focus:ring-0 cursor-pointer"
            />
            <div className="flex-1">
              <label htmlFor="emd-verified-checkbox" className="text-xs font-bold text-white block cursor-pointer select-none">
                Confirm EMD Cleared Escrow
              </label>
              <p className="text-[10px] text-[#9E9DA0] mt-1">
                By checking this, I verify that the earnest money deposit has been wired, cleared by the escrow holder, and receipt document is attached.
              </p>

              {verified && (
                <div className="mt-4 flex flex-col md:flex-row md:items-center gap-4 justify-between bg-black/20 p-3 rounded-lg border border-white/5">
                  <div>
                    <span className="text-[9px] uppercase font-bold text-[#9E9DA0] block">Funds Cleared Date</span>
                    <span className="text-xs text-white mt-1 block">
                      {clearedDate ? new Date(clearedDate).toLocaleDateString() : 'Today'}
                    </span>
                  </div>
                  <div className="relative">
                    <Calendar className="absolute left-2.5 top-2 h-3.5 w-3.5 text-[#454955]" />
                    <input
                      type="date"
                      id="emd-cleared-date-input"
                      value={clearedDate}
                      onChange={(e) => handleClearedDateChange(e.target.value)}
                      disabled={readOnly}
                      className="pl-8 pr-2 py-1 bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955] w-32"
                    />
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

