'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { HelpCircle, Sparkles, Check, ArrowLeft, ArrowRight, DollarSign, Info, Calculator } from 'lucide-react';
import toast from 'react-hot-toast';
import { IS_DEMO_MODE } from '@/lib/config/demo';

interface Props {
  projectId: string;
  financials: any;
  onSaveCategory: (category: string, amount: number) => Promise<void>;
  onAllCompleted: () => void;
}

interface RecurringProposal {
  id: string;
  category: string;
  merchant: string;
  amount: number; // cents
  frequency: string;
}

const PLAID_RECURRING_PROPOSALS: RecurringProposal[] = [
  { id: 'rec-001', category: 'tax', merchant: 'County Tax Collector', amount: 35000, frequency: 'Monthly' },
  { id: 'rec-002', category: 'insurance', merchant: 'Liberty Mutual', amount: 12500, frequency: 'Monthly' },
  { id: 'rec-003', category: 'security', merchant: 'ADT Security', amount: 3500, frequency: 'Monthly' },
  { id: 'rec-004', category: 'maintenance', merchant: 'Local Landscaping Co', amount: 7500, frequency: 'Monthly' },
  { id: 'rec-005', category: 'utilities', merchant: 'Con Edison', amount: 18500, frequency: 'Monthly' },
  { id: 'rec-006', category: 'management', merchant: 'Premier Property PM', amount: 15000, frequency: 'Monthly' },
  { id: 'rec-007', category: 'hoa', merchant: 'Oakridge HOA', amount: 4500, frequency: 'Monthly' },
  { id: 'rec-008', category: 'capex', merchant: 'Reserve Accrual (Sugg.)', amount: 10000, frequency: 'Monthly' }
];

interface StepConfig {
  key: string;
  label: string;
  dbField: string;
  legacyField?: string;
  desc: string;
  guidance: string;
}

const STEPS: StepConfig[] = [
  {
    key: 'tax',
    label: 'Property Tax',
    dbField: 'holding_cost_tax',
    legacyField: 'holdingCostTaxes',
    desc: 'Taxes levied by county/municipal authorities during the hold period.',
    guidance: 'Usually calculated by dividing the annual tax assessment by 12.'
  },
  {
    key: 'insurance',
    label: 'Insurance',
    dbField: 'holding_cost_insurance',
    legacyField: 'holdingCostInsurance',
    desc: 'Hazard, liability, and builder risk insurance premium carry.',
    guidance: 'Confirm monthly carry. Pre-filled from the Fund phase annual hazard premium divided by 12.'
  },
  {
    key: 'security',
    label: 'Security',
    dbField: 'holding_cost_security',
    legacyField: 'holdingCostSecurity',
    desc: 'Cost of temporary site monitoring, sensors, cameras, and alert systems.',
    guidance: 'Vital to prevent vandalism, copper theft, and unauthorized entries during renovation.'
  },
  {
    key: 'maintenance',
    label: 'Maintenance',
    dbField: 'holding_cost_maintenance',
    legacyField: 'holdingCostMaintenance',
    desc: 'Lawn mowing, snow removal, minor repairs, and preservation costs.',
    guidance: 'Crucial for avoiding municipal citations and keeping the asset in presentable condition.'
  },
  {
    key: 'utilities',
    label: 'Utilities',
    dbField: 'holding_cost_utilities',
    legacyField: 'holdingCostUtilities',
    desc: 'Electricity, water, gas, internet, and trash carry during renovation.',
    guidance: 'Utilities must remain active for HVAC systems, contractors, and staging.'
  },
  {
    key: 'management',
    label: 'Management',
    dbField: 'holding_cost_management',
    legacyField: 'holdingCostManagement',
    desc: 'Monthly project/property management administrative fees.',
    guidance: 'Fees paid to general contractors, project managers, or rental managers during hold.'
  },
  {
    key: 'hoa',
    label: 'HOA Fees',
    dbField: 'holding_cost_hoa',
    legacyField: 'hoaMonthly',
    desc: 'Monthly homeowner association or condominium fees.',
    guidance: 'Unavoidable monthly fee if the property is located in an HOA subdivision.'
  },
  {
    key: 'capex',
    label: 'CapEx Reserve',
    dbField: 'holding_cost_capex',
    legacyField: 'holdingCostCapex',
    desc: 'Proactive reserve set aside for future major replacements (roof, HVAC).',
    guidance: 'Setting a monthly reserve protects your target margin from unexpected equipment failures.'
  }
];

export function HoldingCostsWizard({ projectId, financials, onSaveCategory, onAllCompleted }: Props) {
  const [currentStepIdx, setCurrentStepIdx] = useState(0);
  const [inputValue, setInputValue] = useState('');
  const [isSaving, setIsSaving] = useState(false);

  const step = STEPS[currentStepIdx];

  // Derive Loan Carry
  const loanAmount = financials?.loanAmount || 0;
  const loanRate = financials?.loanRate || 0;
  const loanTermMonths = financials?.loanTermMonths || 0;
  const annualDebtService = financials?.annualDebtService || 0;

  const monthlyCarry = useMemo(() => {
    if (annualDebtService > 0) return annualDebtService / 12;
    // Calculate simple amortization
    if (loanAmount > 0 && loanTermMonths > 0) {
      const monthlyRate = (loanRate / 100) / 12;
      if (monthlyRate === 0) return loanAmount / loanTermMonths;
      return loanAmount * (monthlyRate * Math.pow(1 + monthlyRate, loanTermMonths)) / (Math.pow(1 + monthlyRate, loanTermMonths) - 1);
    }
    return 0;
  }, [annualDebtService, loanAmount, loanRate, loanTermMonths]);

  // Load existing database value or handle insurance F4.4 pre-fill
  useEffect(() => {
    const dbValue = financials?.[step.dbField] ?? financials?.[step.legacyField || ''];
    if (dbValue !== undefined && dbValue !== null) {
      setInputValue((dbValue / 100).toString());
    } else if (step.key === 'insurance' && financials?.insuranceCost) {
      // F4.4 Insurance Pre-fill confirmation
      const prefilledVal = Math.round(financials.insuranceCost / 12);
      setInputValue((prefilledVal / 100).toString());
      toast.success('Pre-filled monthly insurance premium from F4.4 annual quote!');
    } else {
      setInputValue('');
    }
  }, [currentStepIdx, financials, step]);

  const proposal = PLAID_RECURRING_PROPOSALS.find(p => p.category === step.key);

  const handleApplyProposal = () => {
    if (proposal) {
      setInputValue((proposal.amount / 100).toString());
      toast.success(`Applied Plaid proposed cost from ${proposal.merchant}`);
    }
  };

  const handleSave = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    const parsed = parseFloat(inputValue.replace(/,/g, ''));
    if (isNaN(parsed) || parsed < 0) {
      toast.error('Please enter a valid amount');
      return;
    }

    setIsSaving(true);
    try {
      await onSaveCategory(step.key, Math.round(parsed * 100));
      if (currentStepIdx < STEPS.length - 1) {
        setCurrentStepIdx(currentStepIdx + 1);
      } else {
        onAllCompleted();
      }
    } finally {
      setIsSaving(false);
    }
  };

  const handlePrev = () => {
    if (currentStepIdx > 0) {
      setCurrentStepIdx(currentStepIdx - 1);
    }
  };

  return (
    <div className="glass-card border border-white/5 rounded-xl p-5 space-y-5 text-left">
      {/* Header and Step Indicators */}
      <div className="flex justify-between items-center border-b border-white/5 pb-3">
        <div>
          <span className="text-[10px] text-[#7A9EAA] uppercase font-bold tracking-wider">
            Holding Costs Setup · Step {currentStepIdx + 1} of {STEPS.length}
          </span>
          <h3 className="text-sm font-bold text-white uppercase tracking-wide mt-0.5">
            {step.label} Cost
          </h3>
        </div>
        {/* Loan Carry Display (derived, read-only) */}
        <div className="bg-white/5 px-3 py-1.5 rounded-lg flex items-center gap-1.5 border border-white/5 text-right font-mono">
          <Calculator className="w-3.5 h-3.5 text-[#7A9EAA]" />
          <div>
            <p className="text-[8px] text-[#9E9DA0] uppercase font-bold">Monthly Debt Carry</p>
            <p className="text-xs font-bold text-white">${(monthlyCarry / 100).toFixed(2)}/mo</p>
          </div>
        </div>
      </div>

      {/* Description & Cost Guidance */}
      <div className="space-y-3 bg-[#454955]/10 border border-[#454955]/20 p-4 rounded-xl">
        <p className="text-xs text-white leading-relaxed">{step.desc}</p>
        <p className="text-[10px] text-[#9E9DA0] leading-normal flex items-start gap-1">
          <HelpCircle className="w-3.5 h-3.5 text-[#7A9EAA] shrink-0 mt-0.5" />
          <span>{step.guidance}</span>
        </p>
      </div>

      {/* Dynamic Plaid Proposals Section (Demo only) */}
      {IS_DEMO_MODE && proposal && (
        <div className="border border-[#7A9EAA]/30 bg-[#7A9EAA]/5 p-3 rounded-lg flex items-center justify-between gap-3 relative">
          <div className="flex items-center gap-2">
            <span className="relative flex h-2 w-2">
              <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-[#7A9EAA] opacity-75"></span>
              <span className="relative inline-flex rounded-full h-2 w-2 bg-[#7A9EAA]"></span>
            </span>
            <div className="text-[10px] text-[#9E9DA0]">
              <span className="font-bold text-[#7A9EAA]">Plaid Cost Proposal (Demo):</span> Found recurring bill of{' '}
              <strong className="text-white">${(proposal.amount / 100).toFixed(2)}/mo</strong> from{' '}
              <strong className="text-white">{proposal.merchant}</strong>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[8px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20">Demo</span>
            <button
              onClick={handleApplyProposal}
              type="button"
              className="text-[9px] font-bold bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white px-2 py-1 rounded transition shrink-0 flex items-center gap-0.5"
            >
              <Check className="w-3 h-3" /> Pre-fill
            </button>
          </div>
        </div>
      )}

      {/* Main input form */}
      <form onSubmit={handleSave} className="space-y-4">
        <div className="space-y-1">
          <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Monthly Cost Amount ($)</label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none text-[#9E9DA0]">
              $
            </div>
            <input
              type="text"
              required
              placeholder="e.g. 150.00"
              value={inputValue}
              onChange={e => setInputValue(e.target.value)}
              className="bg-black/30 border border-white/10 rounded-lg pl-8 pr-3 py-2.5 text-sm text-white w-full outline-none font-mono"
            />
          </div>
        </div>

        {/* Wizard Controls */}
        <div className="flex justify-between items-center pt-2 border-t border-white/5">
          <button
            type="button"
            onClick={handlePrev}
            disabled={currentStepIdx === 0}
            className={`text-xs font-bold px-3 py-2 rounded-lg transition flex items-center gap-1 ${
              currentStepIdx === 0
                ? 'text-[#9E9DA0]/40 cursor-not-allowed'
                : 'text-[#9E9DA0] hover:text-white bg-white/5 hover:bg-white/10'
            }`}
          >
            <ArrowLeft className="w-3.5 h-3.5" /> Previous
          </button>

          <button
            type="submit"
            disabled={isSaving}
            className="text-xs font-bold bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white px-4 py-2 rounded-lg transition flex items-center gap-1 shadow-md"
          >
            {isSaving
              ? 'Saving...'
              : currentStepIdx === STEPS.length - 1
              ? 'Confirm & Finish'
              : 'Save & Next'}{' '}
            <ArrowRight className="w-3.5 h-3.5" />
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { useAuth } from '@/context/AuthContext';
import { doc, updateDoc } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { deriveAllMetrics } from '@/lib/metrics/reiMetrics';
import type { Project } from '@/types/schema';
import { CheckCircle2, XCircle, ShieldAlert, Award, TrendingUp, DollarSign, Percent } from 'lucide-react';
import toast from 'react-hot-toast';

interface HurdleTestCardProps {
  project: Project;
  onSave: (updates: any) => Promise<void>;
}

export function HurdleTestCard({ project, onSave }: HurdleTestCardProps) {
  const { user, profile } = useAuth();

  // Normalize project financials
  const normalizedProject = useMemo(() => {
    const f = (project.financials || {}) as any;
    const copy = { ...project } as any;
    copy.financials = {
      ...f,
      purchasePrice: f.purchasePrice ? f.purchasePrice / 100 : 0,
      finalAgreedPrice: f.finalAgreedPrice ? f.finalAgreedPrice / 100 : undefined,
      renegotiatedPrice: f.renegotiatedPrice ? f.renegotiatedPrice / 100 : undefined,
      offer_price: f.offer_price ? f.offer_price / 100 : undefined,
      loanAmount: f.loanAmount ? f.loanAmount / 100 : 0,
      projectedRehabCost: f.projectedRehabCost ? f.projectedRehabCost / 100 : 0,
      estimatedARV: f.estimatedARV ? f.estimatedARV / 100 : 0,
      closingCosts: f.closingCosts ? f.closingCosts / 100 : (f.fixedAcquisitionCosts ? f.fixedAcquisitionCosts / 100 : 0),
      totalCashInvested: f.totalCashInvested ? f.totalCashInvested / 100 : 0,
      monthlyGrossRent: f.monthlyGrossRent ?? f.monthlyRent ?? 0,
      vacancyRatePercent: f.vacancyRatePercent ?? 7,
      holdingCostTaxes: f.holdingCostTaxes ?? 0,
      holdingCostInsurance: f.holdingCostInsurance ?? 0,
      holdingCostUtilities: f.holdingCostUtilities ?? 0,
      propertyManagementFeePercent: f.propertyManagementFeePercent ?? 0,
      monthlyMaintenanceReserve: f.monthlyMaintenanceReserve ?? 0,
      monthlyHOA: f.monthlyHOA ?? 0,
      loanInterestRate: f.loanInterestRate ?? 6.5,
      loanTermYears: f.loanTermYears ?? 30,
    };
    return copy;
  }, [project]);

  // Derive projected metrics
  const metrics = useMemo(() => {
    return deriveAllMetrics(
      normalizedProject.financials || {},
      undefined,
      normalizedProject.dispositionType,
      normalizedProject.currentPhase,
      normalizedProject.createdAt
    );
  }, [normalizedProject]);

  // Load project-specific thresholds or pre-fill from user-profile/localStorage/defaults
  const [thresholds, setThresholds] = useState({
    targetCapRate: 5.5,
    targetCoc: 8.0,
    minDscr: 1.25,
    maxPurchasePrice: 500000,
  });

  const [isInitializing, setIsInitializing] = useState(true);

  useEffect(() => {
    if (!project) return;

    // 1. Try project-level thresholds
    const pTargetCap = (project.financials as any)?.targetCapRate;
    const pTargetCoc = (project.financials as any)?.targetCoc;
    const pMinDscr = (project.financials as any)?.minDscr;
    const pMaxPrice = (project.financials as any)?.maxPurchasePrice;

    if (
      pTargetCap !== undefined ||
      pTargetCoc !== undefined ||
      pMinDscr !== undefined ||
      pMaxPrice !== undefined
    ) {
      setThresholds({
        targetCapRate: pTargetCap ?? 5.5,
        targetCoc: pTargetCoc ?? 8.0,
        minDscr: pMinDscr ?? 1.25,
        maxPurchasePrice: pMaxPrice ?? 500000,
      });
      setIsInitializing(false);
      return;
    }

    // 2. Fall back to user-level profile thresholds or localStorage
    const profileCap = profile?.buyBoxTargetCapRate;
    const profileCoc = profile?.buyBoxTargetCoc;
    const profileDscr = profile?.buyBoxMinDscr;
    const profileMaxPrice = profile?.buyBoxMaxPurchasePrice;

    let lsThresholds: any = null;
    try {
      const stored = localStorage.getItem('pw_user_buy_box_thresholds');
      if (stored) lsThresholds = JSON.parse(stored);
    } catch {
      // ignore
    }

    const resolved = {
      targetCapRate: profileCap ?? lsThresholds?.targetCapRate ?? 5.5,
      targetCoc: profileCoc ?? lsThresholds?.targetCoc ?? 8.0,
      minDscr: profileDscr ?? lsThresholds?.minDscr ?? 1.25,
      maxPurchasePrice: profileMaxPrice ?? lsThresholds?.maxPurchasePrice ?? 500000,
    };

    setThresholds(resolved);

    // Save user profile defaults onto this new project to pre-fill it persistently (AC2)
    const saveDefaults = async () => {
      try {
        await onSave({
          'financials.targetCapRate': resolved.targetCapRate,
          'financials.targetCoc': resolved.targetCoc,
          'financials.minDscr': resolved.minDscr,
          'financials.maxPurchasePrice': resolved.maxPurchasePrice,
        });
      } catch (err) {
        console.error('Failed to pre-fill project thresholds:', err);
      }
    };
    saveDefaults();
    setIsInitializing(false);
  }, [project.id, profile]);

  // Handle threshold modifications
  const handleThresholdUpdate = async (field: keyof typeof thresholds, val: number) => {
    setThresholds((prev) => {
      const next = { ...prev, [field]: val };
      try {
        localStorage.setItem('pw_user_buy_box_thresholds', JSON.stringify(next));
      } catch (e) {}
      return next;
    });

    try {
      // Save project-level thresholds
      const financialsKey = `financials.${field}`;
      await onSave({ [financialsKey]: val });

      // Save user profile thresholds (AC2 / persistence per user)
      if (user) {
        const userField = `buyBox${field.charAt(0).toUpperCase()}${field.slice(1)}`;
        await updateDoc(doc(db, 'users', user.uid), {
          [userField]: val,
        });
      }
    } catch (err) {
      console.error('Failed to save buy box threshold updates:', err);
      toast.error('Failed to save threshold changes');
    }
  };

  // Perform calculations
  const actualCapRate = (metrics as any).capRate ?? 0;
  const actualCoc = (metrics as any).cashOnCashReturn ?? 0;
  const actualDscr = (metrics as any).dscr ?? 0;
  const actualPurchasePrice = normalizedProject.financials?.purchasePrice ?? 0;

  // Maximum Allowable Offer (MAO) only shown for SALE disposition
  const isSale = project.dispositionType === 'SALE';
  const mao = (metrics as any).mao ?? 0;
  const arv = normalizedProject.financials?.estimatedARV ?? 0;
  const rehab = normalizedProject.financials?.projectedRehabCost ?? 0;

  // Hurdle checks
  const checks = {
    capRate: actualCapRate >= thresholds.targetCapRate,
    coc: actualCoc >= thresholds.targetCoc,
    dscr: actualDscr >= thresholds.minDscr,
    price: actualPurchasePrice <= thresholds.maxPurchasePrice,
    mao: !isSale || actualPurchasePrice <= mao,
  };

  // Overall verdict
  const hurdlePassed = checks.capRate && checks.coc && checks.dscr && checks.price && checks.mao;

  // Render Currency Format helper
  const fmtCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(val);
  };

  if (isInitializing) {
    return (
      <div className="rounded-xl border border-white/5 bg-[#161217] p-6 text-center text-xs text-[#9E9DA0]">
        Initializing Hurdle Test Parameters...
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-white/5 bg-[#161217] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-white/5 bg-white/[0.01] px-6 py-4">
        <div className="flex items-center gap-2.5">
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-white/5">
            <Award className="h-4 w-4 text-[#EA580C]" />
          </div>
          <div>
            <h4 className="text-xs font-bold uppercase tracking-widest text-white">Buy-Box &amp; Hurdle Test</h4>
            <p className="text-[9px] text-[#9E9DA0]">"Does this deal meet your investment parameters?"</p>
          </div>
        </div>

        {/* Verdict Badge */}
        <div className="flex items-center gap-2">
          <span className="text-[8px] uppercase tracking-wider text-[#9E9DA0] font-bold">Hurdle Verdict:</span>
          <span
            id="hurdle-overall-verdict"
            className={`px-3 py-1 rounded text-[10px] font-bold uppercase tracking-widest transition-all ${
              hurdlePassed
                ? 'bg-[var(--pw-success-container)] text-[var(--pw-success)] border border-[var(--pw-success)]/30'
                : 'bg-[#F06543]/20 text-[#F06543] border border-[#F06543]/30'
            }`}
          >
            {hurdlePassed ? 'APPROVED / PASS' : 'REJECTED / FAIL'}
          </span>
        </div>
      </div>

      <div className="p-6 space-y-6">
        {/* Threshold Inputs Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-4 gap-4">
          {/* Target Cap Rate */}
          <div className="bg-white/[0.01] border border-white/5 p-3 rounded-lg">
            <span className="block text-[8px] uppercase tracking-widest text-[#9E9DA0] font-bold mb-1.5">
              Target Cap Rate (%)
            </span>
            <div className="relative">
              <Percent className="absolute left-2.5 top-2 h-3 w-3 text-[#9E9DA0]" />
              <input
                id="threshold-cap-rate"
                type="number"
                step="0.01"
                value={thresholds.targetCapRate}
                onChange={(e) => handleThresholdUpdate('targetCapRate', parseFloat(e.target.value) || 0)}
                className="w-full pl-7 pr-2 py-1 rounded text-xs bg-[#161217] border border-white/10 text-white font-mono text-right"
              />
            </div>
          </div>

          {/* Target CoC */}
          <div className="bg-white/[0.01] border border-white/5 p-3 rounded-lg">
            <span className="block text-[8px] uppercase tracking-widest text-[#9E9DA0] font-bold mb-1.5">
              Target CoC Return (%)
            </span>
            <div className="relative">
              <Percent className="absolute left-2.5 top-2 h-3 w-3 text-[#9E9DA0]" />
              <input
                id="threshold-coc"
                type="number"
                step="0.01"
                value={thresholds.targetCoc}
                onChange={(e) => handleThresholdUpdate('targetCoc', parseFloat(e.target.value) || 0)}
                className="w-full pl-7 pr-2 py-1 rounded text-xs bg-[#161217] border border-white/10 text-white font-mono text-right"
              />
            </div>
          </div>

          {/* Min DSCR */}
          <div className="bg-white/[0.01] border border-white/5 p-3 rounded-lg">
            <span className="block text-[8px] uppercase tracking-widest text-[#9E9DA0] font-bold mb-1.5">
              Minimum DSCR
            </span>
            <div className="relative">
              <span className="absolute left-2.5 top-1.5 text-xs text-[#9E9DA0] font-bold">x</span>
              <input
                id="threshold-min-dscr"
                type="number"
                step="0.01"
                value={thresholds.minDscr}
                onChange={(e) => handleThresholdUpdate('minDscr', parseFloat(e.target.value) || 0)}
                className="w-full pl-7 pr-2 py-1 rounded text-xs bg-[#161217] border border-white/10 text-white font-mono text-right"
              />
            </div>
          </div>

          {/* Max Purchase Price */}
          <div className="bg-white/[0.01] border border-white/5 p-3 rounded-lg">
            <span className="block text-[8px] uppercase tracking-widest text-[#9E9DA0] font-bold mb-1.5">
              Max Purchase Price ($)
            </span>
            <div className="relative">
              <DollarSign className="absolute left-2.5 top-2 h-3 w-3 text-[#9E9DA0]" />
              <input
                id="threshold-max-price"
                type="number"
                value={thresholds.maxPurchasePrice}
                onChange={(e) => handleThresholdUpdate('maxPurchasePrice', parseFloat(e.target.value) || 0)}
                className="w-full pl-7 pr-2 py-1 rounded text-xs bg-[#161217] border border-white/10 text-white font-mono text-right"
              />
            </div>
          </div>
        </div>

        {/* MAO Calculations (SALE strategy only) */}
        {isSale && (
          <div id="mao-details-panel" className="p-4 rounded-lg bg-white/[0.02] border border-white/5 space-y-3">
            <div className="flex items-center justify-between">
              <span className="text-[10px] uppercase tracking-wider text-white font-bold">
                Maximum Allowable Offer (MAO)
              </span>
              <span id="mao-calculated-value" className="text-xs font-mono font-bold text-[#EA580C]">
                MAO: {fmtCurrency(mao)}
              </span>
            </div>
            <div className="grid grid-cols-3 gap-4 text-[10px] text-[#9E9DA0]">
              <div>
                <span className="block text-[#9E9DA0]/50">Estimated ARV:</span>
                <span className="font-mono text-white">{fmtCurrency(arv)}</span>
              </div>
              <div>
                <span className="block text-[#9E9DA0]/50">Rehab Budget:</span>
                <span className="font-mono text-white">{fmtCurrency(rehab)}</span>
              </div>
              <div>
                <span className="block text-[#9E9DA0]/50">MAO Formula:</span>
                <span className="font-mono text-white">ARV * 70% - Rehab</span>
              </div>
            </div>
          </div>
        )}

        {/* Per-Metric Pass/Fail Evaluator */}
        <div className="space-y-2.5 pt-2">
          <span className="block text-[8px] uppercase tracking-widest text-[#9E9DA0] font-bold">
            Evaluation Results
          </span>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {/* Cap Rate */}
            <div className="flex items-center justify-between p-3 rounded-lg border border-white/5 bg-white/[0.01]">
              <div className="space-y-0.5">
                <span className="block text-[10px] text-white/70 font-bold uppercase tracking-wider">Cap Rate</span>
                <span className="block text-[9px] text-[#9E9DA0] font-mono">
                  Projected: {actualCapRate.toFixed(2)}% vs Target: {thresholds.targetCapRate.toFixed(2)}%
                </span>
              </div>
              <div id="hurdle-check-caprate" className="flex items-center">
                {checks.capRate ? (
                  <CheckCircle2 className="h-5 w-5 text-[var(--pw-success)]" />
                ) : (
                  <XCircle className="h-5 w-5 text-[#F06543]" />
                )}
              </div>
            </div>

            {/* Cash-on-Cash */}
            <div className="flex items-center justify-between p-3 rounded-lg border border-white/5 bg-white/[0.01]">
              <div className="space-y-0.5">
                <span className="block text-[10px] text-white/70 font-bold uppercase tracking-wider">Cash-on-Cash Return</span>
                <span className="block text-[9px] text-[#9E9DA0] font-mono">
                  Projected: {actualCoc.toFixed(2)}% vs Target: {thresholds.targetCoc.toFixed(2)}%
                </span>
              </div>
              <div id="hurdle-check-coc" className="flex items-center">
                {checks.coc ? (
                  <CheckCircle2 className="h-5 w-5 text-[var(--pw-success)]" />
                ) : (
                  <XCircle className="h-5 w-5 text-[#F06543]" />
                )}
              </div>
            </div>

            {/* DSCR */}
            <div className="flex items-center justify-between p-3 rounded-lg border border-white/5 bg-white/[0.01]">
              <div className="space-y-0.5">
                <span className="block text-[10px] text-white/70 font-bold uppercase tracking-wider">Debt Service Coverage (DSCR)</span>
                <span className="block text-[9px] text-[#9E9DA0] font-mono">
                  Projected: {actualDscr.toFixed(2)}x vs Min: {thresholds.minDscr.toFixed(2)}x
                </span>
              </div>
              <div id="hurdle-check-dscr" className="flex items-center">
                {checks.dscr ? (
                  <CheckCircle2 className="h-5 w-5 text-[var(--pw-success)]" />
                ) : (
                  <XCircle className="h-5 w-5 text-[#F06543]" />
                )}
              </div>
            </div>

            {/* Purchase Price */}
            <div className="flex items-center justify-between p-3 rounded-lg border border-white/5 bg-white/[0.01]">
              <div className="space-y-0.5">
                <span className="block text-[10px] text-white/70 font-bold uppercase tracking-wider">Purchase Price Check</span>
                <span className="block text-[9px] text-[#9E9DA0] font-mono">
                  Price: {fmtCurrency(actualPurchasePrice)} vs Max: {fmtCurrency(thresholds.maxPurchasePrice)}
                </span>
              </div>
              <div id="hurdle-check-price" className="flex items-center">
                {checks.price ? (
                  <CheckCircle2 className="h-5 w-5 text-[var(--pw-success)]" />
                ) : (
                  <XCircle className="h-5 w-5 text-[#F06543]" />
                )}
              </div>
            </div>

            {/* MAO (if SALE disposition) */}
            {isSale && (
              <div className="flex items-center justify-between p-3 rounded-lg border border-white/5 bg-white/[0.01] sm:col-span-2">
                <div className="space-y-0.5">
                  <span className="block text-[10px] text-white/70 font-bold uppercase tracking-wider">MAO Check (Sale Strategy)</span>
                  <span className="block text-[9px] text-[#9E9DA0] font-mono">
                    Price: {fmtCurrency(actualPurchasePrice)} vs MAO limit: {fmtCurrency(mao)}
                  </span>
                </div>
                <div id="hurdle-check-mao" className="flex items-center">
                  {checks.mao ? (
                    <CheckCircle2 className="h-5 w-5 text-[var(--pw-success)]" />
                  ) : (
                    <XCircle className="h-5 w-5 text-[#F06543]" />
                  )}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Warning Indicator */}
        {!hurdlePassed && (
          <div id="hurdle-warning-banner" className="flex items-start gap-2.5 p-3 rounded-lg bg-[#F06543]/10 border border-[#F06543]/20 text-xs text-[#9E9DA0]">
            <ShieldAlert className="h-4 w-4 text-[#F06543] shrink-0 mt-0.5" />
            <div>
              <span className="block font-bold text-white mb-0.5">One or more hurdles are failing</span>
              <span>This project does not meet the specified Buy-Box criteria. You can only advance the deal by typing an emergency override justification reason.</span>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useMemo, useEffect } from 'react';
import { DollarSign, Percent, Sparkles, TrendingUp, HelpCircle } from 'lucide-react';
import type { Project } from '@/types/schema';
import toast from 'react-hot-toast';
import { deriveAllMetrics } from '@/lib/metrics/reiMetrics';

interface IncomeAssumptionsCardProps {
  project: Project;
  phaseColor?: string;
  onSave: (updates: any) => Promise<void>;
}

export function IncomeAssumptionsCard({
  project,
  phaseColor = '#ffac5a',
  onSave,
}: IncomeAssumptionsCardProps) {
  const unitCount = Math.max(1, project.units || 1);

  // Initialize per-unit rents
  const [unitRents, setUnitRents] = useState<number[]>(() => {
    if (project.financials?.unitRents && project.financials.unitRents.length === unitCount) {
      return [...project.financials.unitRents];
    }
    // Fallback: split gross_rent_per_unit evenly, or default to 0
    const totalRent = project.financials?.gross_rent_per_unit || 0;
    if (totalRent > 0) {
      const avg = Math.round((totalRent / unitCount) * 100) / 100;
      return Array(unitCount).fill(avg);
    }
    return Array(unitCount).fill(0);
  });

  // Initialize other income and vacancy percentage
  const [otherIncome, setOtherIncome] = useState<string>(() => {
    return project.financials?.other_income !== undefined && project.financials?.other_income !== null
      ? project.financials.other_income.toString()
      : '0';
  });

  const [vacancyPct, setVacancyPct] = useState<string>(() => {
    return project.financials?.vacancy_pct !== undefined && project.financials?.vacancy_pct !== null
      ? project.financials.vacancy_pct.toString()
      : '7'; // Default to middle of 5-8% range
  });

  const [isSaving, setIsSaving] = useState(false);

  // Sync state when project changes
  useEffect(() => {
    const existingRents = project.financials?.unitRents || [];
    let nextRents = [...existingRents];
    if (nextRents.length !== unitCount) {
      if (nextRents.length < unitCount) {
        const totalRent = project.financials?.gross_rent_per_unit || 0;
        const defaultRent = totalRent > 0 ? Math.round((totalRent / unitCount) * 100) / 100 : 0;
        while (nextRents.length < unitCount) {
          nextRents.push(defaultRent);
        }
      } else {
        nextRents = nextRents.slice(0, unitCount);
      }
    }
    setUnitRents(nextRents);

    setOtherIncome(
      project.financials?.other_income !== undefined && project.financials?.other_income !== null
        ? project.financials.other_income.toString()
        : '0'
    );

    setVacancyPct(
      project.financials?.vacancy_pct !== undefined && project.financials?.vacancy_pct !== null
        ? project.financials.vacancy_pct.toString()
        : '7'
    );
  }, [project.id, unitCount]);

  const handleUnitRentChange = (index: number, val: number) => {
    const next = [...unitRents];
    next[index] = Math.max(0, val);
    setUnitRents(next);
  };

  // Calculations (must match reiMetrics.ts exactly)
  const monthlyGrossRent = useMemo(() => {
    return unitRents.reduce((a, b) => a + b, 0);
  }, [unitRents]);

  const annualGrossRent = useMemo(() => {
    return monthlyGrossRent * 12;
  }, [monthlyGrossRent]);

  const otherIncomeVal = useMemo(() => {
    return parseFloat(otherIncome) || 0;
  }, [otherIncome]);

  const annualOtherIncome = useMemo(() => {
    return otherIncomeVal * 12;
  }, [otherIncomeVal]);

  const vacancyRate = useMemo(() => {
    return parseFloat(vacancyPct) || 0;
  }, [vacancyPct]);

  const annualVacancyLoss = useMemo(() => {
    return annualGrossRent * (vacancyRate / 100);
  }, [annualGrossRent, vacancyRate]);

  const annualEGI = useMemo(() => {
    return annualGrossRent + annualOtherIncome - annualVacancyLoss;
  }, [annualGrossRent, annualOtherIncome, annualVacancyLoss]);

  const monthlyEGI = useMemo(() => {
    return annualEGI / 12;
  }, [annualEGI]);

  const liveMetrics = useMemo(() => {
    const tempFinancials = {
      purchasePrice: 100000,
      monthlyGrossRent: monthlyGrossRent,
      other_income: otherIncomeVal,
      vacancyRatePercent: vacancyRate,
    };
    return deriveAllMetrics(tempFinancials as any, undefined, 'RENT', 1);
  }, [monthlyGrossRent, otherIncomeVal, vacancyRate]);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const updates = {
        'financials.gross_rent_per_unit': monthlyGrossRent,
        'financials.other_income': otherIncomeVal,
        'financials.vacancy_pct': vacancyRate,
        'financials.unitRents': unitRents,
      };

      await onSave(updates);
      toast.success('Income assumptions saved successfully!');
    } catch (err) {
      console.error('Failed to save income assumptions:', err);
      toast.error('Failed to save income assumptions');
    } finally {
      setIsSaving(false);
    }
  };

  const formatCurrency = (amount: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(amount);
  };

  return (
    <div className="rounded-xl border border-white/5 bg-[#161217] overflow-hidden">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-white/5 bg-white/[0.01] px-6 py-4">
        <div className="flex items-center gap-2.5">
          <div className="flex h-7 w-7 items-center justify-center rounded-lg bg-white/5">
            <TrendingUp className="h-4 w-4 text-[#ffac5a]" />
          </div>
          <div>
            <h4 className="text-xs font-bold uppercase tracking-widest text-white">Income Assumptions</h4>
            <p className="text-[9px] text-[#9E9DA0]">"What will this property realistically bring in?"</p>
          </div>
        </div>

        <button
          onClick={handleSave}
          disabled={isSaving}
          className="px-3 py-1 rounded bg-[#241e26] border border-white/10 hover:bg-white/5 text-white text-[9px] font-bold uppercase tracking-widest transition-colors flex items-center gap-1.5 disabled:opacity-50"
        >
          {isSaving ? 'Saving...' : 'Save Income'}
        </button>
      </div>

      <div className="p-6 space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Left Column: Per-unit inputs */}
          <div className="space-y-4">
            <div>
              <span className="block text-[8px] uppercase tracking-widest text-[#9E9DA0] font-bold mb-2">
                Unit Rents ({unitCount} leasable units)
              </span>
              <div className="space-y-2 max-h-[220px] overflow-y-auto pr-1">
                {unitRents.map((rent, idx) => (
                  <div key={idx} className="flex items-center justify-between bg-white/[0.01] border border-white/5 p-2 rounded-lg gap-3">
                    <span className="text-xs text-white/70 font-semibold uppercase tracking-wider text-[10px]">
                      Unit {idx + 1}
                    </span>
                    <div className="relative w-[130px]">
                      <DollarSign className="absolute left-2 top-1.5 h-3.5 w-3.5 text-[#9E9DA0]" />
                      <input
                        type="number"
                        value={rent || ''}
                        onChange={(e) => handleUnitRentChange(idx, parseFloat(e.target.value) || 0)}
                        placeholder={idx === 0 ? "Gross Monthly Rent" : "0"}
                        className="w-full pl-6 pr-2.5 rounded py-1 text-xs bg-[#161217] border border-white/10 text-white focus:outline-none focus:border-[#ffac5a] font-mono text-right"
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Other income input */}
            <div className="flex items-center justify-between bg-white/[0.01] border border-white/5 p-3 rounded-lg gap-3">
              <div>
                <span className="block text-[10px] text-white/70 font-semibold uppercase tracking-wider">Other Income</span>
                <span className="block text-[8px] text-[#9E9DA0] mt-0.5">Parking, laundry, storage, etc. (monthly)</span>
              </div>
              <div className="relative w-[130px]">
                <DollarSign className="absolute left-2 top-1.5 h-3.5 w-3.5 text-[#9E9DA0]" />
                <input
                  type="number"
                  value={otherIncome}
                  onChange={(e) => setOtherIncome(e.target.value)}
                  placeholder="0"
                  className="w-full pl-6 pr-2.5 rounded py-1 text-xs bg-[#161217] border border-white/10 text-white focus:outline-none focus:border-[#ffac5a] font-mono text-right"
                />
              </div>
            </div>
          </div>

          {/* Right Column: Vacancy and EGI Rollups */}
          <div className="space-y-6 flex flex-col justify-between">
            {/* Vacancy input */}
            <div className="bg-white/[0.01] border border-white/5 p-4 rounded-lg space-y-3">
              <div className="flex items-center justify-between">
                <div>
                  <span className="block text-[10px] text-white/70 font-semibold uppercase tracking-wider">Vacancy Allowance</span>
                  <span className="block text-[8px] text-[#9E9DA0] mt-0.5">Assumed market vacancy percentage</span>
                </div>
                <div className="relative w-[80px]">
                  <input
                    type="number"
                    value={vacancyPct}
                    onChange={(e) => setVacancyPct(e.target.value)}
                    placeholder="7"
                    className="w-full pr-6 pl-2.5 rounded py-1 text-xs bg-[#161217] border border-white/10 text-white focus:outline-none focus:border-[#ffac5a] font-mono text-right"
                  />
                  <Percent className="absolute right-2.5 top-1.5 h-3.5 w-3.5 text-[#9E9DA0]" />
                </div>
              </div>
              <div className="flex items-center gap-1.5 text-[8px] text-yellow-400/80 bg-yellow-400/5 border border-yellow-400/10 rounded px-2.5 py-1.5">
                <HelpCircle className="h-3 w-3 shrink-0" />
                <span>Default is typically 5%–8% depending on local asset submarket conditions.</span>
              </div>
            </div>

            {/* Live EGI display */}
            <div className="bg-white/[0.02] border border-white/10 p-5 rounded-lg space-y-4">
              <div className="flex items-center justify-between border-b border-white/5 pb-3">
                <div>
                  <span className="text-[10px] uppercase font-bold text-[#9E9DA0] tracking-wider">Scheduled Gross Rent</span>
                  <span className="block text-[8px] text-[#9E9DA0] mt-0.5">Sum of unit rents ({formatCurrency(monthlyGrossRent)} / mo)</span>
                </div>
                <span className="text-sm font-mono font-bold text-white">{formatCurrency(annualGrossRent)} / yr</span>
              </div>

              <div className="flex items-center justify-between border-b border-white/5 pb-3">
                <div>
                  <span className="text-[10px] uppercase font-bold text-[#9E9DA0] tracking-wider">Vacancy Loss</span>
                  <span className="block text-[8px] text-[#9E9DA0] mt-0.5">Based on {vacancyRate}% vacancy rate</span>
                </div>
                <span className="text-sm font-mono font-semibold text-red-400">-{formatCurrency(annualVacancyLoss)} / yr</span>
              </div>

              <div className="flex flex-col gap-3 pt-2 border-t border-white/5">
                <div className="flex items-center justify-between">
                  <div>
                    <span className="text-[10px] uppercase font-bold text-[#ffac5a] tracking-wider flex items-center gap-1">
                      <Sparkles className="h-3 w-3" /> Effective Gross Income (EGI)
                    </span>
                    <span className="block text-[8px] text-[#9E9DA0] mt-0.5">Local Calculated EGI</span>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-mono font-bold text-[#ffac5a] block">{formatCurrency(annualEGI)} / yr</span>
                    <span className="text-[9px] font-mono text-[#9E9DA0]">{formatCurrency(monthlyEGI)} / mo</span>
                  </div>
                </div>

                <div className="flex items-center justify-between bg-white/[0.02] border border-white/5 p-2 rounded-lg">
                  <div>
                    <span className="text-[9px] uppercase font-bold text-white/70 tracking-wider">Engine Function EGI</span>
                    <span className="block text-[8px] text-[#9E9DA0] mt-0.5">deriveAllMetrics() output</span>
                  </div>
                  <div className="text-right">
                    <span className="text-sm font-mono font-bold text-white block">
                      {formatCurrency(liveMetrics.noiComponents.egi ?? 0)} / yr
                    </span>
                    <span className="text-[9px] font-mono text-[#9E9DA0]">
                      {formatCurrency((liveMetrics.noiComponents.egi ?? 0) / 12)} / mo
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

