'use client';

import React, { useState, useEffect, useRef } from 'react';
import { Shield, Upload, FileText, CheckCircle2, Trash2, AlertCircle, Info, DollarSign, Calendar, MapPin } from 'lucide-react';
import type { Project, RoleLinkedDocument } from '@/types/schema';
import { ref, uploadBytesResumable, getDownloadURL, deleteObject } from 'firebase/storage';
import { storage } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import toast from 'react-hot-toast';

interface Props {
  project: Project;
  onSaveProject: (updates: Partial<Project>) => Promise<void>;
  readOnly?: boolean;
}

export function InsuranceBinderCard({ project, onSaveProject, readOnly = false }: Props) {
  const { user } = useAuth();
  const financials = project.financials || {};

  // Form states
  const [annualPremium, setAnnualPremium] = useState<string>('');
  const [effectiveDate, setEffectiveDate] = useState<string>('');
  const [hasFloodRider, setHasFloodRider] = useState<boolean>(false);
  const [hasEarthquakeRider, setHasEarthquakeRider] = useState<boolean>(false);
  const [floodZone, setFloodZone] = useState<string>('');
  const [earthquakeZone, setEarthquakeZone] = useState<string>('');

  // Upload state
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Sync state with project data on mount / change
  useEffect(() => {
    setAnnualPremium(financials.insuranceCost ? financials.insuranceCost.toString() : '');
    setEffectiveDate(financials.insuranceBinderEffectiveDate || '');
    setHasFloodRider(!!financials.hasFloodRider);
    setHasEarthquakeRider(!!financials.hasEarthquakeRider);
    setFloodZone(financials.floodZone || '');
    setEarthquakeZone(financials.earthquakeZone || '');
  }, [project.id, financials.insuranceCost, financials.insuranceBinderEffectiveDate, financials.hasFloodRider, financials.hasEarthquakeRider, financials.floodZone, financials.earthquakeZone]);

  // Resolve active Insurance Broker
  const brokerValue = financials.f4InsuranceBrokerVendor;
  const brokerName = !brokerValue
    ? null
    : typeof brokerValue === 'string'
      ? brokerValue
      : brokerValue.name || null;
  const brokerFirm = typeof brokerValue === 'object' && brokerValue?.firm ? brokerValue.firm : null;

  // ── File upload handler ──────────────────────────────────────────────────
  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('Only PDF documents are allowed.');
      return;
    }

    if (!user) {
      toast.error('Must be logged in to upload documents.');
      return;
    }

    setUploading(true);
    setUploadProgress(0);
    const toastId = toast.loading('Uploading insurance binder...');

    const uploadId = crypto.randomUUID();
    const fileRef = ref(storage, `projects/${project.id}/documents/${uploadId}_${file.name}`);
    const uploadTask = uploadBytesResumable(fileRef, file);

    uploadTask.on(
      'state_changed',
      (snapshot) => {
        const progress = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
        setUploadProgress(progress);
      },
      (error) => {
        console.error('Binder upload failed', error);
        toast.error(`Failed to upload ${file.name}`, { id: toastId });
        setUploading(false);
      },
      async () => {
        try {
          const downloadURL = await getDownloadURL(uploadTask.snapshot.ref);

          // Update financials
          const updatedFinancials = {
            ...financials,
            insuranceBinderUrl: downloadURL,
            insuranceBinderName: file.name,
          };

          // Create/update RoleLinkedDocument
          const updatedDocs = [...(project.roleLinkedDocuments || [])];
          const binderDocIndex = updatedDocs.findIndex((d) => d.category === 'Insurance Binder');
          const newDoc: RoleLinkedDocument = {
            id: binderDocIndex >= 0 ? updatedDocs[binderDocIndex].id : uploadId,
            category: 'Insurance Binder',
            fileName: file.name,
            fileUrl: downloadURL,
            linkedRole: 'Closing Agent',
            uploadedByUid: user.uid,
            uploadedByName: user.displayName || user.email || 'Teammate',
            uploadedAt: new Date(),
            verified: false,
            notes: effectiveDate ? `Effective Date: ${effectiveDate}` : '',
          };

          if (binderDocIndex >= 0) {
            updatedDocs[binderDocIndex] = newDoc;
          } else {
            updatedDocs.push(newDoc);
          }

          await onSaveProject({
            financials: updatedFinancials,
            roleLinkedDocuments: updatedDocs,
          });

          toast.success('Insurance binder uploaded successfully.', { id: toastId });
        } catch (err: any) {
          console.error(err);
          toast.error('Failed to link binder document.', { id: toastId });
        } finally {
          setUploading(false);
          if (fileInputRef.current) fileInputRef.current.value = '';
        }
      }
    );
  };

  // ── Delete document handler ──────────────────────────────────────────────
  const handleDeleteBinder = async () => {
    if (!window.confirm('Are you sure you want to remove the insurance binder?')) return;

    const toastId = toast.loading('Removing binder...');
    try {
      const fileUrl = financials.insuranceBinderUrl;
      if (fileUrl) {
        try {
          const fileRef = ref(storage, fileUrl);
          await deleteObject(fileRef);
        } catch (err) {
          console.error('Failed to delete file from storage:', err);
        }
      }

      // Update financials
      const updatedFinancials = {
        ...financials,
        insuranceBinderUrl: null,
        insuranceBinderName: null,
      };

      // Remove from RoleLinkedDocuments
      const updatedDocs = (project.roleLinkedDocuments || []).filter(
        (d) => d.category !== 'Insurance Binder'
      );

      await onSaveProject({
        financials: updatedFinancials,
        roleLinkedDocuments: updatedDocs,
      });

      toast.success('Insurance binder removed.', { id: toastId });
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to remove binder.', { id: toastId });
    }
  };

  // ── Save action updates monthly opex premium and annual premium ──────────
  const handleSaveDetails = async () => {
    const premiumVal = parseFloat(annualPremium) || 0;
    const monthlyPremium = Math.round((premiumVal / 12) * 100) / 100;

    const updatedFinancials = {
      ...financials,
      insuranceCost: premiumVal || undefined,
      insurance: premiumVal ? monthlyPremium : undefined,
      holdingCostInsurance: premiumVal ? monthlyPremium : undefined,
      insuranceBinderEffectiveDate: effectiveDate || null,
      hasFloodRider,
      hasEarthquakeRider,
      floodZone: hasFloodRider ? floodZone.trim() || null : null,
      earthquakeZone: hasEarthquakeRider ? earthquakeZone.trim() || null : null,
    };

    // Update notes in RoleLinkedDocument if it exists
    const updatedDocs = [...(project.roleLinkedDocuments || [])];
    const binderDocIndex = updatedDocs.findIndex((d) => d.category === 'Insurance Binder');
    if (binderDocIndex >= 0) {
      updatedDocs[binderDocIndex] = {
        ...updatedDocs[binderDocIndex],
        notes: effectiveDate ? `Effective Date: ${effectiveDate}` : '',
      };
    }

    try {
      await onSaveProject({
        financials: updatedFinancials,
        roleLinkedDocuments: updatedDocs,
      });
      toast.success('Insurance settings and opex premium updated!');
    } catch (err) {
      toast.error('Failed to update insurance details.');
    }
  };

  const binderUploaded = !!financials.insuranceBinderUrl;

  return (
    <div className="glass-card p-6 space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-pw-border pb-4">
        <div className="flex items-center gap-2.5">
          <Shield className="w-5 h-5 text-[#7A9EAA]" />
          <div>
            <h3 className="text-sm font-bold text-pw-black uppercase tracking-wider">Insurance Binder &amp; Riders</h3>
            <p className="text-[10px] text-pw-muted font-light mt-0.5">
              Confirm hazard premium, upload binding documents, and track hazard riders.
            </p>
          </div>
        </div>
        <span className="text-[9px] font-bold text-[#9E9DA0] uppercase tracking-wider">
          F4 Closing Checklist
        </span>
      </div>

      {/* Insurance Broker Assignment Slot Banner */}
      <div className="p-3 bg-gray-50/50 border border-pw-border rounded-lg text-xs space-y-1">
        <div className="flex items-center justify-between">
          <span className="font-bold text-pw-black uppercase tracking-wider text-[10px]">
            Insurance Broker Slot
          </span>
          {brokerName ? (
            <span className="px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider bg-green-50 text-green-700 rounded border border-green-200">
              Assigned
            </span>
          ) : (
            <span className="px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider bg-amber-50 text-amber-600 rounded border border-amber-200">
              Unassigned
            </span>
          )}
        </div>
        {brokerName ? (
          <p className="text-pw-black text-[11px] font-medium">
            Broker: <span className="font-semibold">{brokerName}</span>
            {brokerFirm && <span className="text-pw-muted font-light"> ({brokerFirm})</span>}
          </p>
        ) : (
          <p className="text-pw-muted text-[11px] font-light">
            No broker assigned. Assign an insurance broker in the Team slot above to coordinate quotes.
          </p>
        )}
      </div>

      {/* Upload Binder File Area */}
      <div className="space-y-3">
        <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider">
          Insurance Binder PDF *
        </label>

        {binderUploaded ? (
          <div className="p-4 border border-green-500/20 bg-green-500/5 rounded-lg flex items-center justify-between">
            <div className="flex items-center gap-2">
              <FileText className="w-5 h-5 text-green-600 animate-bounce" />
              <div>
                <a
                  href={financials.insuranceBinderUrl!}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="text-xs font-semibold text-pw-black hover:underline block truncate max-w-xs"
                >
                  {financials.insuranceBinderName || 'insurance_binder.pdf'}
                </a>
                <span className="text-[10px] text-green-600 font-medium">Binder Document Uploaded</span>
              </div>
            </div>
            {!readOnly && (
              <button
                type="button"
                onClick={handleDeleteBinder}
                className="p-1.5 text-red-500 hover:bg-red-50 rounded transition-all"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            )}
          </div>
        ) : (
          <div>
            <input
              type="file"
              accept=".pdf"
              ref={fileInputRef}
              onChange={handleFileUpload}
              className="hidden"
              id="insurance-binder-picker"
              disabled={uploading || readOnly}
            />
            <label
              htmlFor="insurance-binder-picker"
              className={`border-2 border-dashed border-pw-border rounded-lg p-5 text-center block cursor-pointer hover:bg-gray-50/50 transition-all ${
                uploading || readOnly ? 'opacity-50 cursor-not-allowed' : ''
              }`}
            >
              {uploading ? (
                <div className="space-y-2">
                  <div className="w-8 h-8 rounded-full border-2 border-t-transparent border-[#7A9EAA] animate-spin mx-auto" />
                  <span className="text-xs text-pw-muted font-medium block">
                    Uploading ({uploadProgress}%)…
                  </span>
                </div>
              ) : (
                <div className="space-y-1">
                  <Upload className="w-6 h-6 text-pw-muted mx-auto" />
                  <span className="text-xs text-pw-black font-semibold block">Upload Insurance Binder</span>
                  <span className="text-[10px] text-pw-muted font-light">PDF format only. Required to unlock actual values.</span>
                </div>
              )}
            </label>
          </div>
        )}
      </div>

      {/* Binder Details & Riders Form */}
      <div className="space-y-4 pt-2 border-t border-pw-border">
        {/* Effective Date & Annual Premium inputs */}
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider mb-1">
              Binder Effective Date
            </label>
            <div className="relative">
              <Calendar className="absolute left-2.5 top-2 h-3.5 w-3.5 text-pw-muted" />
              <input
                type="date"
                value={effectiveDate}
                onChange={(e) => setEffectiveDate(e.target.value)}
                disabled={readOnly}
                className="pl-8 pr-3 py-1.5 w-full border border-pw-border rounded text-xs text-pw-black bg-pw-white focus:outline-none focus:ring-1 focus:ring-[#7A9EAA]"
              />
            </div>
          </div>

          <div>
            <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider mb-1">
              Annual Premium ($)
            </label>
            <div className="relative">
              <DollarSign className="absolute left-2.5 top-2 h-3.5 w-3.5 text-pw-muted" />
              <input
                type="number"
                value={annualPremium}
                onChange={(e) => setAnnualPremium(e.target.value)}
                placeholder="e.g. 2400"
                disabled={!binderUploaded || readOnly}
                className={`pl-8 pr-3 py-1.5 w-full border border-pw-border rounded text-xs text-pw-black bg-pw-white focus:outline-none focus:ring-1 focus:ring-[#7A9EAA] font-mono ${
                  !binderUploaded ? 'opacity-50 cursor-not-allowed bg-gray-100' : ''
                }`}
              />
            </div>
            {!binderUploaded && (
              <span className="text-[9px] text-amber-600 font-semibold block mt-1 flex items-center gap-0.5">
                <AlertCircle className="w-2.5 h-2.5" /> Upload binder PDF first to unlock annual premium entry
              </span>
            )}
          </div>
        </div>

        {/* Dynamic calculation display disclaiming monthly NOI opex impact */}
        {annualPremium && binderUploaded && (
          <div className="p-3 bg-[#7A9EAA]/5 border border-[#7A9EAA]/20 rounded-lg flex items-start gap-2.5 text-xs text-pw-black">
            <Info className="w-4 h-4 text-[#7A9EAA] shrink-0 mt-0.5" />
            <div>
              <p className="font-semibold text-[11px] uppercase tracking-wider text-[#7A9EAA]">
                NOI / Expense Ledger Sync
              </p>
              <p className="text-[11px] text-pw-muted font-light mt-0.5">
                Annual premium of <span className="font-bold font-mono text-pw-black">${parseFloat(annualPremium).toLocaleString()}</span> writes a monthly opex expense of <span className="font-bold font-mono text-pw-black">${Math.round((parseFloat(annualPremium) / 12) * 100) / 100}</span> to the insurance category. Net Operating Income (NOI), Cash Flow, and DSCR are derived directly from this monthly value to prevent ledger drift (BUG-8 vigilance).
              </p>
            </div>
          </div>
        )}

        {/* Hazard Riders & Zone determinations */}
        <div className="space-y-3 pt-2 border-t border-pw-border">
          <span className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider">
            Hazard Riders &amp; Zone Determinations
          </span>

          <div className="space-y-3">
            {/* Flood Rider */}
            <div className="space-y-2">
              <button
                type="button"
                onClick={() => !readOnly && setHasFloodRider(!hasFloodRider)}
                className={`flex items-center gap-2 text-xs select-none ${
                  readOnly ? 'cursor-default' : 'cursor-pointer text-pw-black hover:text-black'
                }`}
              >
                <div
                  className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${
                    hasFloodRider ? 'bg-[#7A9EAA] border-[#7A9EAA]' : 'border-pw-border'
                  }`}
                >
                  {hasFloodRider && <CheckCircle2 className="w-2.5 h-2.5 text-white" />}
                </div>
                <span className="font-medium text-pw-black">Property Requires Flood Rider</span>
              </button>

              {hasFloodRider && (
                <div className="pl-6 space-y-1 animate-in slide-in-from-top-1 duration-150">
                  <label className="block text-[9px] font-bold text-pw-muted uppercase tracking-wider">
                    Flood Zone / Designation *
                  </label>
                  <div className="relative">
                    <MapPin className="absolute left-2.5 top-2 h-3.5 w-3.5 text-pw-muted" />
                    <input
                      type="text"
                      value={floodZone}
                      onChange={(e) => setFloodZone(e.target.value)}
                      placeholder="e.g. Zone AE, Zone A"
                      disabled={readOnly}
                      className="pl-8 pr-3 py-1.5 w-full border border-pw-border rounded text-xs text-pw-black bg-pw-white focus:outline-none focus:ring-1 focus:ring-[#7A9EAA]"
                    />
                  </div>
                  <span className="text-[9px] text-pw-muted font-light italic">
                    Zone determinations come from your lender/insurer.
                  </span>
                </div>
              )}
            </div>

            {/* Earthquake Rider */}
            <div className="space-y-2">
              <button
                type="button"
                onClick={() => !readOnly && setHasEarthquakeRider(!hasEarthquakeRider)}
                className={`flex items-center gap-2 text-xs select-none ${
                  readOnly ? 'cursor-default' : 'cursor-pointer text-pw-black hover:text-black'
                }`}
              >
                <div
                  className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${
                    hasEarthquakeRider ? 'bg-[#7A9EAA] border-[#7A9EAA]' : 'border-pw-border'
                  }`}
                >
                  {hasEarthquakeRider && <CheckCircle2 className="w-2.5 h-2.5 text-white" />}
                </div>
                <span className="font-medium text-pw-black">Property Requires Earthquake Rider</span>
              </button>

              {hasEarthquakeRider && (
                <div className="pl-6 space-y-1 animate-in slide-in-from-top-1 duration-150">
                  <label className="block text-[9px] font-bold text-pw-muted uppercase tracking-wider">
                    Earthquake Risk Category / Zone *
                  </label>
                  <div className="relative">
                    <MapPin className="absolute left-2.5 top-2 h-3.5 w-3.5 text-pw-muted" />
                    <input
                      type="text"
                      value={earthquakeZone}
                      onChange={(e) => setEarthquakeZone(e.target.value)}
                      placeholder="e.g. Zone 4, High Risk Category"
                      disabled={readOnly}
                      className="pl-8 pr-3 py-1.5 w-full border border-pw-border rounded text-xs text-pw-black bg-pw-white focus:outline-none focus:ring-1 focus:ring-[#7A9EAA]"
                    />
                  </div>
                  <span className="text-[9px] text-pw-muted font-light italic">
                    Zone determinations come from your lender/insurer.
                  </span>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Save button */}
        {!readOnly && (
          <div className="flex justify-end pt-2">
            <button
              onClick={handleSaveDetails}
              className="px-4 py-2 text-xs font-bold uppercase tracking-wider bg-[#7A9EAA] text-white rounded hover:bg-[#688a95] transition-all shadow-sm flex items-center gap-1.5"
            >
              <CheckCircle2 className="w-4 h-4" />
              Save Insurance details
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Calendar, FileText, CheckCircle, Clock, Trash2, Info, Landmark, ShieldAlert, Plus, DollarSign } from 'lucide-react';
import type { Project, InsuranceQuote } from '@/types/schema';
import toast from 'react-hot-toast';

interface InsuranceCardProps {
  project: Project;
  onSaveFinancials: (updates: any) => Promise<void>;
  phaseColor?: string;
  readOnly?: boolean;
}

export function InsuranceCard({
  project,
  onSaveFinancials,
  phaseColor = '#595959',
  readOnly = false,
}: InsuranceCardProps) {
  const financials = project.financials || {};
  const quotes: InsuranceQuote[] = financials.insuranceQuotes || [];

  // Form states for adding new quote
  const [carrier, setCarrier] = useState('');
  const [policyType, setPolicyType] = useState('HO-3 Homeowners');
  const [monthlyPremium, setMonthlyPremium] = useState('');
  const [coverageLimit, setCoverageLimit] = useState('');
  const [liabilityLimit, setLiabilityLimit] = useState('');
  const [lossOfRentLimit, setLossOfRentLimit] = useState('');
  const [hasFloodWindRider, setHasFloodWindRider] = useState(false);

  // Sync state helpers
  const handleSaveField = async (fieldName: string, value: any) => {
    try {
      await onSaveFinancials({ [fieldName]: value });
    } catch (err) {
      console.error(`Failed to save ${fieldName}:`, err);
      toast.error('Failed to save changes');
    }
  };

  const handleAddQuote = async (e: React.FormEvent) => {
    e.preventDefault();
    if (readOnly) return;
    if (!carrier.trim() || !monthlyPremium) {
      toast.error('Carrier and premium are required');
      return;
    }

    const premiumVal = parseFloat(monthlyPremium) || 0;
    const newQuote: InsuranceQuote = {
      id: crypto.randomUUID(),
      carrier: carrier.trim(),
      policyType,
      monthlyPremium: premiumVal,
      premium: premiumVal * 12, // Annual
      coverageLimit: parseFloat(coverageLimit) || 0,
      liabilityLimit: parseFloat(liabilityLimit) || 0,
      lossOfRentLimit: parseFloat(lossOfRentLimit) || 0,
      hasFloodWindRider,
      isAccepted: false,
    };

    const updatedQuotes = [...quotes, newQuote];
    try {
      await onSaveFinancials({ insuranceQuotes: updatedQuotes });
      toast.success('Insurance quote added!');
      // Reset form
      setCarrier('');
      setMonthlyPremium('');
      setCoverageLimit('');
      setLiabilityLimit('');
      setLossOfRentLimit('');
      setHasFloodWindRider(false);
    } catch (err) {
      console.error(err);
      toast.error('Failed to add quote');
    }
  };

  const handleDeleteQuote = async (id: string) => {
    if (readOnly) return;
    const updatedQuotes = quotes.filter(q => q.id !== id);
    try {
      await onSaveFinancials({ insuranceQuotes: updatedQuotes });
      toast.success('Quote deleted');
    } catch (err) {
      console.error(err);
      toast.error('Failed to delete quote');
    }
  };

  const handleAcceptQuote = async (quote: InsuranceQuote) => {
    if (readOnly) return;
    const updatedQuotes = quotes.map(q => ({
      ...q,
      isAccepted: q.id === quote.id,
    }));

    try {
      // Overwrite the estimate in financials.insurance with the accepted quote's monthly premium
      await onSaveFinancials({
        insuranceQuotes: updatedQuotes,
        insuranceCarrier: quote.carrier,
        insurancePolicyType: quote.policyType,
        insurance: quote.monthlyPremium, // updates the AQ-10 insurance estimate
      });
      toast.success(`Accepted ${quote.carrier} quote! Monthly premium updated to $${quote.monthlyPremium}.`);
    } catch (err) {
      console.error(err);
      toast.error('Failed to accept quote');
    }
  };

  const handleQuoteUploadDoc = async (quoteId: string) => {
    if (readOnly) return;
    const updatedQuotes = quotes.map(q => {
      if (q.id === quoteId) {
        return {
          ...q,
          documentUrl: `/mock/documents/Insurance_Quote_${q.carrier.replace(/\s+/g, '_')}.pdf`,
          documentName: `Insurance_Quote_${q.carrier.replace(/\s+/g, '_')}.pdf`,
        };
      }
      return q;
    });

    try {
      await onSaveFinancials({ insuranceQuotes: updatedQuotes });
      toast.success('Quote document uploaded!');
    } catch (err) {
      console.error(err);
      toast.error('Failed to upload document');
    }
  };

  return (
    <div className="glass-card rounded-2xl p-6 border border-white/5 space-y-6 animate-in fade-in duration-300">
      {/* Header */}
      <div className="flex items-center justify-between border-b border-white/5 pb-4">
        <div className="flex items-center gap-2">
          <ShieldAlert className="w-5 h-5 animate-pulse" style={{ color: phaseColor }} />
          <h3 className="text-sm font-bold text-white uppercase tracking-wider">Insurance Quotes Tracker</h3>
        </div>
        <span className="text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider">Hazard &amp; Liability Coverage</span>
      </div>

      {/* Quote input form */}
      {!readOnly && (
        <form onSubmit={handleAddQuote} className="p-4 bg-white/5 border border-white/5 rounded-xl space-y-4">
          <h4 className="text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider flex items-center gap-1.5">
            <Plus className="w-3.5 h-3.5" /> Add Premium Quote
          </h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {/* Carrier */}
            <div>
              <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1">Carrier (Vendor)</label>
              <input
                type="text"
                id="quote-carrier"
                value={carrier}
                onChange={(e) => setCarrier(e.target.value)}
                placeholder="e.g. State Farm, Liberty Mutual"
                className="px-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955]"
              />
            </div>
            {/* Policy Type */}
            <div>
              <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1">Policy Type</label>
              <select
                id="quote-policy-type"
                value={policyType}
                onChange={(e) => setPolicyType(e.target.value)}
                className="px-3 py-1.5 w-full bg-[#121014] border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955]"
              >
                <option value="HO-3 Homeowners">HO-3 Homeowners</option>
                <option value="DP-3 Dwelling Fire">DP-3 Dwelling Fire</option>
                <option value="Commercial General Liability">Commercial General Liability</option>
                <option value="Builders Risk / Vacant">Builders Risk / Vacant</option>
              </select>
            </div>
            {/* Monthly Premium */}
            <div>
              <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1">Monthly Premium ($)</label>
              <div className="relative">
                <DollarSign className="absolute left-2.5 top-2 h-3.5 w-3.5 text-[#9E9DA0]" />
                <input
                  type="number"
                  id="quote-monthly-premium"
                  value={monthlyPremium}
                  onChange={(e) => setMonthlyPremium(e.target.value)}
                  placeholder="e.g. 120"
                  className="pl-8 pr-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955] font-mono"
                />
              </div>
            </div>
            {/* Coverage Limit */}
            <div>
              <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1">Coverage Limit ($)</label>
              <input
                type="number"
                id="quote-coverage"
                value={coverageLimit}
                onChange={(e) => setCoverageLimit(e.target.value)}
                placeholder="e.g. 350000"
                className="px-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955] font-mono"
              />
            </div>
            {/* Liability Limit */}
            <div>
              <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1">Liability Limit ($)</label>
              <input
                type="number"
                id="quote-liability"
                value={liabilityLimit}
                onChange={(e) => setLiabilityLimit(e.target.value)}
                placeholder="e.g. 1000000"
                className="px-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955] font-mono"
              />
            </div>
            {/* Loss of Rent */}
            <div>
              <label className="block text-[10px] font-bold text-[#9E9DA0] uppercase tracking-wider mb-1">Loss of Rent ($)</label>
              <input
                type="number"
                id="quote-loss-of-rent"
                value={lossOfRentLimit}
                onChange={(e) => setLossOfRentLimit(e.target.value)}
                placeholder="e.g. 24000"
                className="px-3 py-1.5 w-full bg-white/5 border border-white/10 rounded-lg text-xs text-white focus:outline-none focus:ring-1 focus:ring-[#454955] font-mono"
              />
            </div>
          </div>

          <div className="flex items-center justify-between">
            {/* Flood/Wind Rider */}
            <div
              id="quote-flood-wind-toggle"
              onClick={() => setHasFloodWindRider(!hasFloodWindRider)}
              className="flex items-center gap-2 cursor-pointer select-none text-xs text-[#9E9DA0] hover:text-white"
            >
              <div className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${
                hasFloodWindRider ? 'bg-[#454955] border-[#454955]' : 'border-white/20'
              }`}>
                {hasFloodWindRider && <CheckCircle className="w-3.5 h-3.5 text-white" />}
              </div>
              <span>Includes Flood/Wind Rider</span>
            </div>

            <button
              type="submit"
              id="add-quote-submit-btn"
              className="px-4 py-2 bg-white/5 border border-white/10 hover:bg-white/10 text-white rounded-lg text-xs font-bold uppercase tracking-wider transition-all"
            >
              Add Quote
            </button>
          </div>
        </form>
      )}

      {/* List of Quotes */}
      <div className="space-y-4">
        {quotes.length === 0 ? (
          <div className="text-center py-6 text-xs text-[#9E9DA0]/60 border border-dashed border-white/5 rounded-xl">
            No premium quotes added yet.
          </div>
        ) : (
          <div className="grid grid-cols-1 gap-4">
            {quotes.map((quote) => (
              <div
                key={quote.id}
                id={`quote-card-${quote.id}`}
                className={`p-4 rounded-xl border transition-all space-y-3 relative ${
                  quote.isAccepted
                    ? 'border-green-500/30 bg-green-500/5'
                    : 'border-white/5 bg-white/[0.02] hover:bg-white/5'
                }`}
              >
                {/* Accept badge or accept button */}
                <div className="absolute top-4 right-4 flex items-center gap-2">
                  {quote.isAccepted ? (
                    <span className="px-2 py-0.5 text-[9px] font-bold uppercase tracking-wider bg-green-500/10 text-green-400 border border-green-500/20 rounded-full flex items-center gap-1">
                      <CheckCircle className="w-3 h-3 text-green-400" /> Accepted
                    </span>
                  ) : (
                    !readOnly && (
                      <button
                        type="button"
                        id={`accept-quote-btn-${quote.id}`}
                        onClick={() => handleAcceptQuote(quote)}
                        className="px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider bg-white/5 hover:bg-white/10 border border-white/10 text-white rounded-lg transition-all"
                      >
                        Accept Quote
                      </button>
                    )
                  )}
                  {!readOnly && (
                    <button
                      type="button"
                      onClick={() => handleDeleteQuote(quote.id)}
                      className="p-1 text-[#F06543] hover:bg-[#F06543]/10 rounded-lg transition-all"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </button>
                  )}
                </div>

                {/* Carrier & Policy details */}
                <div className="pr-24">
                  <h4 className="text-xs font-bold text-white uppercase tracking-wider">{quote.carrier}</h4>
                  <span className="text-[10px] text-[#9E9DA0]">{quote.policyType}</span>
                </div>

                {/* Limits & Premium details */}
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-xs">
                  <div>
                    <span className="block text-[9px] font-bold uppercase tracking-widest text-[#9E9DA0]">Monthly Premium</span>
                    <span className="font-mono text-white font-medium">${quote.monthlyPremium}</span>
                  </div>
                  <div>
                    <span className="block text-[9px] font-bold uppercase tracking-widest text-[#9E9DA0]">Coverage Limit</span>
                    <span className="font-mono text-white font-medium">${quote.coverageLimit.toLocaleString()}</span>
                  </div>
                  <div>
                    <span className="block text-[9px] font-bold uppercase tracking-widest text-[#9E9DA0]">Liability Limit</span>
                    <span className="font-mono text-white font-medium">${quote.liabilityLimit.toLocaleString()}</span>
                  </div>
                  <div>
                    <span className="block text-[9px] font-bold uppercase tracking-widest text-[#9E9DA0]">Rider Included</span>
                    <span className="font-mono text-white font-medium">{quote.hasFloodWindRider ? 'Yes (Flood/Wind)' : 'No'}</span>
                  </div>
                </div>

                {/* Doc attachment */}
                <div className="border-t border-white/5 pt-3 flex items-center justify-between">
                  <span className="text-[9px] font-bold uppercase tracking-widest text-[#9E9DA0]">Quote PDF Attachment</span>
                  {quote.documentUrl ? (
                    <div className="flex items-center gap-1.5 text-xs text-green-400">
                      <FileText className="w-3.5 h-3.5 text-green-500" />
                      <span className="font-bold">{quote.documentName}</span>
                    </div>
                  ) : (
                    <button
                      type="button"
                      id={`upload-quote-doc-${quote.id}`}
                      onClick={() => handleQuoteUploadDoc(quote.id)}
                      disabled={readOnly}
                      className="text-[9px] font-bold uppercase tracking-wider text-[#454955] hover:text-white transition-colors"
                    >
                      Upload Quote PDF
                    </button>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { db } from '@/lib/firebase/config';
import { collection, query, onSnapshot, orderBy, where, doc, getDoc } from 'firebase/firestore';
import type { InvestorInquiry } from '@/types/dealInquiry';
import { Send, Eye, EyeOff, Loader2, MessageSquare, Check, HelpCircle, Contact, UserCheck, ShieldAlert, Award } from 'lucide-react';
import toast from 'react-hot-toast';
import { getAuth } from 'firebase/auth';

interface InvestorQandATrackerProps {
  projectId: string;
}

export function InvestorQandATracker({ projectId }: InvestorQandATrackerProps) {
  const [activeTab, setActiveTab] = useState<'qna' | 'exchanges'>('qna');
  const [inquiries, setInquiries] = useState<InvestorInquiry[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [filter, setFilter] = useState<'all' | 'open' | 'answered'>('all');
  const [replyText, setReplyText] = useState('');
  const [submittingReply, setSubmittingReply] = useState(false);
  const [togglingShare, setTogglingShare] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  // Invitations / Card Exchange States
  const [invitations, setInvitations] = useState<any[]>([]);
  const [selectedExchangeId, setSelectedExchangeId] = useState<string | null>(null);
  const [leadInvestorCard, setLeadInvestorCard] = useState({
    name: '',
    email: '',
    phone: '',
    company: '',
  });
  const [submittingExchange, setSubmittingExchange] = useState(false);

  // 1. Subscribe to inquiries
  useEffect(() => {
    if (!projectId) return;

    const inquiriesRef = collection(db, 'projects', projectId, 'investorInquiries');
    const q = query(inquiriesRef, orderBy('updatedAt', 'desc'));

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        const list = snapshot.docs.map((doc) => {
          const data = doc.data();
          return {
            id: doc.id,
            projectId: data.projectId,
            invitationId: data.invitationId,
            investorName: data.investorName || 'Anonymous',
            investorEmail: data.investorEmail || '',
            status: data.status || 'open',
            isShared: !!data.isShared,
            message: data.message,
            messages: data.messages || [],
            createdAt: data.createdAt,
            updatedAt: data.updatedAt,
          } as InvestorInquiry;
        });
        setInquiries(list);
        setLoading(false);
      },
      (error) => {
        console.error('Error fetching inquiries:', error);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [projectId]);

  // 2. Subscribe to dealInvitations
  useEffect(() => {
    if (!projectId) return;

    const invitesRef = collection(db, 'dealInvitations');
    const q = query(invitesRef, where('projectId', '==', projectId));

    const unsubscribe = onSnapshot(q, (snapshot) => {
      const list = snapshot.docs.map((d) => ({ id: d.id, ...d.data() }));
      setInvitations(list);
    });

    return () => unsubscribe();
  }, [projectId]);

  // 3. Load LeadInvestor Card Profile Defaults
  useEffect(() => {
    const auth = getAuth();
    const currentUser = auth.currentUser;
    if (currentUser) {
      setLeadInvestorCard({
        name: currentUser.displayName || '',
        email: currentUser.email || '',
        phone: '',
        company: '',
      });

      const userRef = doc(db, 'users', currentUser.uid);
      getDoc(userRef)
        .then((snap) => {
          if (snap.exists()) {
            const u = snap.data();
            setLeadInvestorCard({
              name: u.displayName || currentUser.displayName || '',
              email: u.email || currentUser.email || '',
              phone: u.phone || '',
              company: u.company || u.companyName || '',
            });
          }
        })
        .catch((err) => console.warn('Failed to load user profile for card defaults:', err));
    }
  }, []);

  const activeInquiry = inquiries.find((i) => i.id === selectedId);

  const filteredInquiries = inquiries.filter((inq) => {
    if (filter === 'open') return inq.status === 'open';
    if (filter === 'answered') return inq.status === 'answered';
    return true;
  });

  const exchangeRequests = invitations.filter(
    (inv) => inv.status === 'interested'
  );

  const handleSendReply = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedId || !replyText.trim() || submittingReply) return;

    setSubmittingReply(true);
    try {
      const auth = getAuth();
      const token = await auth.currentUser?.getIdToken();
      if (!token) {
        toast.error('Authentication required.');
        setSubmittingReply(false);
        return;
      }

      const res = await fetch(`/api/projects/${projectId}/inquiries/${selectedId}/reply`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ text: replyText.trim() }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        setReplyText('');
        toast.success('Reply dispatched and investor notified via email.');
      } else {
        toast.error(data.error || 'Failed to send reply.');
      }
    } catch (err) {
      console.error('Reply failed:', err);
      toast.error('Failed to submit reply.');
    } finally {
      setSubmittingReply(false);
    }
  };

  const handleToggleShare = async (inquiryId: string, currentShared: boolean) => {
    if (togglingShare) return;
    setTogglingShare(inquiryId);

    try {
      const auth = getAuth();
      const token = await auth.currentUser?.getIdToken();
      if (!token) {
        toast.error('Authentication required.');
        setTogglingShare(null);
        return;
      }

      const nextShared = !currentShared;
      const res = await fetch(`/api/projects/${projectId}/inquiries/${inquiryId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ isShared: nextShared }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        toast.success(
          nextShared
            ? 'Thread published to public Q&A anonymously.'
            : 'Thread retracted from public Q&A.'
        );
      } else {
        toast.error(data.error || 'Failed to toggle sharing.');
      }
    } catch (err) {
      console.error('Toggle share failed:', err);
      toast.error('Failed to update sharing settings.');
    } finally {
      setTogglingShare(null);
    }
  };

  const handleAcceptExchange = async (invitationId: string) => {
    if (submittingExchange) return;
    setSubmittingExchange(true);

    try {
      const auth = getAuth();
      const token = await auth.currentUser?.getIdToken();
      if (!token) {
        toast.error('Authentication required.');
        setSubmittingExchange(false);
        return;
      }

      const res = await fetch(`/api/projects/${projectId}/invitations/${invitationId}/exchange`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ action: 'accept', disclosedCard: leadInvestorCard }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        toast.success('Business card exchange accepted and cards saved to Project Files.');
        setSelectedExchangeId(null);
      } else {
        toast.error(data.error || 'Failed to accept exchange.');
      }
    } catch (err) {
      console.error('Accept exchange failed:', err);
      toast.error('Failed to accept exchange.');
    } finally {
      setSubmittingExchange(false);
    }
  };

  const handleDeclineExchange = async (invitationId: string) => {
    if (submittingExchange) return;
    setSubmittingExchange(true);

    try {
      const auth = getAuth();
      const token = await auth.currentUser?.getIdToken();
      if (!token) {
        toast.error('Authentication required.');
        setSubmittingExchange(false);
        return;
      }

      const res = await fetch(`/api/projects/${projectId}/invitations/${invitationId}/exchange`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ action: 'decline' }),
      });

      const data = await res.json();
      if (res.ok && data.success) {
        toast.success('Exchange declined silently (no rejection notification sent to investor).');
      } else {
        toast.error(data.error || 'Failed to decline exchange.');
      }
    } catch (err) {
      console.error('Decline exchange failed:', err);
      toast.error('Failed to decline exchange.');
    } finally {
      setSubmittingExchange(false);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center p-8 text-center text-xs uppercase tracking-wider text-[#9E9DA0]">
        <Loader2 className="w-5 h-5 animate-spin mb-2" />
        Synchronizing Stage 6 Audience Panel...
      </div>
    );
  }

  const activeExchange = exchangeRequests.find((r) => r.id === selectedExchangeId);

  return (
    <div className="space-y-4">
      {/* Navigation Headers */}
      <div className="flex items-center justify-between border-b border-white/5 pb-4">
        <div className="flex gap-4">
          <button
            onClick={() => setActiveTab('qna')}
            className={`text-xs font-bold uppercase tracking-wider font-mono transition-all pb-1 border-b-2 ${
              activeTab === 'qna' ? 'text-white border-white' : 'text-[#9E9DA0] border-transparent hover:text-white'
            }`}
          >
            Q&A Threads ({inquiries.length})
          </button>
          <button
            onClick={() => setActiveTab('exchanges')}
            className={`text-xs font-bold uppercase tracking-wider font-mono transition-all pb-1 border-b-2 ${
              activeTab === 'exchanges' ? 'text-white border-white' : 'text-[#9E9DA0] border-transparent hover:text-white'
            }`}
          >
            Card Exchanges ({exchangeRequests.filter((r) => r.cardExchangeStatus === 'pending').length} Pending)
          </button>
        </div>

        {activeTab === 'qna' && (
          <div className="flex gap-1.5 bg-black/40 p-0.5 rounded-lg border border-white/5">
            {(['all', 'open', 'answered'] as const).map((opt) => (
              <button
                key={opt}
                onClick={() => setFilter(opt)}
                className={`px-2.5 py-1 rounded text-[10px] uppercase font-bold tracking-wider transition-all ${
                  filter === opt ? 'bg-white/10 text-white shadow' : 'text-[#9E9DA0] hover:text-white'
                }`}
              >
                {opt}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Tab 1: Q&A Threads */}
      {activeTab === 'qna' && (
        inquiries.length === 0 ? (
          <div className="flex flex-col items-center justify-center p-8 bg-black/20 rounded-xl border border-white/5 text-center text-xs text-[#9E9DA0]">
            <HelpCircle className="w-6 h-6 text-white/20 mb-2" />
            No investor questions received for this deal yet.
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-12 gap-6 min-h-[350px]">
            {/* Left panel: Threads List */}
            <div className="md:col-span-5 space-y-2 max-h-[450px] overflow-y-auto pr-1">
              {filteredInquiries.map((inq) => {
                const lastMsg = inq.messages[inq.messages.length - 1]?.text || inq.message || '';
                const isSelected = inq.id === selectedId;

                return (
                  <div
                    key={inq.id}
                    onClick={() => setSelectedId(inq.id)}
                    className={`p-3.5 rounded-xl border transition-all cursor-pointer select-none text-left ${
                      isSelected
                        ? 'bg-white/10 border-white/20 shadow'
                        : 'bg-white/5 border-white/5 hover:bg-white/10 hover:border-white/10'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <p className="text-xs font-bold text-white truncate max-w-[150px]">
                        {inq.investorName}
                      </p>
                      <span
                        className={`px-1.5 py-0.5 rounded text-[8px] uppercase tracking-wider font-mono font-bold ${
                          inq.status === 'open'
                            ? 'bg-amber-500/10 text-amber-500 border border-amber-500/20'
                            : 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20'
                        }`}
                      >
                        {inq.status}
                      </span>
                    </div>
                    <p className="text-[10px] text-[#9E9DA0] truncate mt-0.5">{inq.investorEmail}</p>
                    <p className="text-xs text-white/70 truncate mt-2 font-mono">{lastMsg}</p>
                    <div className="flex items-center justify-between mt-3 pt-2 border-t border-white/5">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleToggleShare(inq.id, inq.isShared);
                        }}
                        disabled={togglingShare === inq.id}
                        className={`flex items-center gap-1 text-[9px] uppercase tracking-wider font-bold transition-all hover:text-white ${
                          inq.isShared ? 'text-primary' : 'text-[#9E9DA0]'
                        }`}
                      >
                        {togglingShare === inq.id ? (
                          <Loader2 className="w-2.5 h-2.5 animate-spin" />
                        ) : inq.isShared ? (
                          <Eye className="w-3 h-3 text-emerald-500" />
                        ) : (
                          <EyeOff className="w-3 h-3 text-[#9E9DA0]" />
                        )}
                        {inq.isShared ? 'Shared' : 'Private'}
                      </button>
                      <span className="text-[9px] text-[#9E9DA0] font-mono">
                        {inq.messages.length} messages
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* Right panel: Thread Messages */}
            <div className="md:col-span-7 flex flex-col bg-black/30 border border-white/5 rounded-2xl overflow-hidden max-h-[450px]">
              {activeInquiry ? (
                <>
                  <div className="p-4 border-b border-white/5 flex justify-between items-center bg-black/20">
                    <div>
                      <p className="text-xs font-bold text-white font-mono">{activeInquiry.investorName}</p>
                      <p className="text-[10px] text-[#9E9DA0] mt-0.5">{activeInquiry.investorEmail}</p>
                    </div>
                    <button
                      onClick={() => handleToggleShare(activeInquiry.id, activeInquiry.isShared)}
                      disabled={togglingShare === activeInquiry.id}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-[9px] uppercase tracking-wider font-bold transition-all ${
                        activeInquiry.isShared
                          ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/20'
                          : 'bg-white/5 text-[#9E9DA0] border-white/10 hover:text-white'
                      }`}
                    >
                      {activeInquiry.isShared ? <Eye className="w-3.5 h-3.5" /> : <EyeOff className="w-3.5 h-3.5" />}
                      {activeInquiry.isShared ? 'Shared' : 'Make Shared'}
                    </button>
                  </div>

                  <div className="flex-1 p-4 space-y-3.5 overflow-y-auto max-h-[300px]">
                    {activeInquiry.messages.length === 0 ? (
                      <div className="flex flex-col gap-2 p-3 bg-white/5 border border-white/10 rounded-xl max-w-[85%] text-left">
                        <span className="text-[9px] font-bold text-primary font-mono uppercase">Investor</span>
                        <p className="text-xs text-white/90 whitespace-pre-wrap">{activeInquiry.message}</p>
                      </div>
                    ) : (
                      activeInquiry.messages.map((msg) => {
                        const isLeadInvestor = msg.sender === 'leadInvestor';
                        return (
                          <div
                            key={msg.id}
                            className={`flex flex-col gap-1 p-3 rounded-xl max-w-[85%] text-left ${
                              isLeadInvestor ? 'ml-auto bg-black/60 border border-[#454955]/30' : 'bg-white/5 border border-white/10'
                            }`}
                          >
                            <span className={`text-[9px] font-bold font-mono uppercase ${isLeadInvestor ? 'text-[#8a9b9b]' : 'text-primary'}`}>
                              {isLeadInvestor ? 'LeadInvestor' : 'Investor'}
                            </span>
                            <p className="text-xs text-white/90 whitespace-pre-wrap">{msg.text}</p>
                            <span className="text-[8px] text-[#9E9DA0] self-end mt-1 font-mono">
                              {new Date(msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                            </span>
                          </div>
                        );
                      })
                    )}
                  </div>

                  <form onSubmit={handleSendReply} className="p-3 border-t border-white/5 bg-black/20 flex gap-2">
                    <input
                      type="text"
                      value={replyText}
                      onChange={(e) => setReplyText(e.target.value)}
                      placeholder={`Reply to ${activeInquiry.investorName}...`}
                      required
                      maxLength={2000}
                      className="flex-1 px-4 py-2.5 bg-black/40 border border-white/10 rounded-xl text-xs text-white placeholder-white/30 focus:outline-none focus:border-primary transition-all"
                    />
                    <button
                      type="submit"
                      disabled={submittingReply || !replyText.trim()}
                      className="px-4 py-2.5 bg-white/10 hover:bg-white/20 border border-white/10 hover:border-white/20 rounded-xl text-white disabled:opacity-50 transition-all flex items-center justify-center gap-1.5"
                    >
                      {submittingReply ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Send className="w-3.5 h-3.5" />}
                      <span className="text-[10px] uppercase font-bold tracking-wider">Reply</span>
                    </button>
                  </form>
                </>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center p-8 text-xs text-[#9E9DA0] font-mono uppercase">
                  <HelpCircle className="w-7 h-7 text-white/10 mb-2 animate-bounce" />
                  Select a thread to respond
                </div>
              )}
            </div>
          </div>
        )
      )}

      {/* Tab 2: Business Card Exchanges */}
      {activeTab === 'exchanges' && (
        exchangeRequests.length === 0 ? (
          <div className="flex flex-col items-center justify-center p-8 bg-black/20 rounded-xl border border-white/5 text-center text-xs text-[#9E9DA0]">
            <Contact className="w-6 h-6 text-white/20 mb-2" />
            No business card exchange requests for this project.
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-12 gap-6 min-h-[350px]">
            {/* Left panel: Requests List */}
            <div className="md:col-span-5 space-y-2 max-h-[450px] overflow-y-auto pr-1">
              {exchangeRequests.map((req) => {
                const isSelected = req.id === selectedExchangeId;
                const statusLabel = req.cardExchangeStatus || 'pending';

                return (
                  <div
                    key={req.id}
                    onClick={() => setSelectedExchangeId(req.id)}
                    className={`p-3.5 rounded-xl border transition-all cursor-pointer select-none text-left ${
                      isSelected
                        ? 'bg-white/10 border-white/20 shadow'
                        : 'bg-white/5 border-white/5 hover:bg-white/10 hover:border-white/10'
                    }`}
                  >
                    <div className="flex items-center justify-between">
                      <p className="text-xs font-bold text-white truncate max-w-[150px]">
                        {req.inviteeBusinessCard?.name || req.inviteeName || 'Anonymous'}
                      </p>
                      <span
                        className={`px-1.5 py-0.5 rounded text-[8px] uppercase tracking-wider font-mono font-bold ${
                          statusLabel === 'pending'
                            ? 'bg-amber-500/10 text-amber-500 border border-amber-500/20'
                            : statusLabel === 'accepted'
                            ? 'bg-emerald-500/10 text-emerald-500 border border-emerald-500/20'
                            : 'bg-white/10 text-[#9E9DA0] border border-white/5'
                        }`}
                      >
                        {statusLabel}
                      </span>
                    </div>
                    <p className="text-[10px] text-[#9E9DA0] truncate mt-0.5">
                      {req.inviteeBusinessCard?.company || 'Co-Investor'}
                    </p>
                  </div>
                );
              })}
            </div>

            {/* Right panel: Exchange Approval Console */}
            <div className="md:col-span-7 flex flex-col bg-black/30 border border-white/5 rounded-2xl overflow-hidden max-h-[450px] p-6 justify-between">
              {activeExchange ? (
                <div className="space-y-6 flex flex-col justify-between h-full">
                  <div>
                    <h4 className="text-xs font-bold text-white uppercase tracking-wider font-mono mb-4">
                      Review Exchange Request
                    </h4>

                    {/* Invitee Business Card Details */}
                    <div className="relative overflow-hidden rounded-2xl border border-white/10 bg-white/[0.02] p-5 shadow-2xl backdrop-blur-md flex flex-col justify-between h-36">
                      <div>
                        <h4 className="text-xs font-bold text-white uppercase tracking-wider font-mono">
                          {activeExchange.inviteeBusinessCard?.name || activeExchange.inviteeName}
                        </h4>
                        <p className="text-[10px] text-[#8a9b9b]">
                          {activeExchange.inviteeBusinessCard?.company || 'Co-Investor'}
                        </p>
                      </div>
                      <div className="space-y-1 text-xs text-[#8a9b9b] font-mono">
                        <div className="flex items-center gap-2">
                          <span className="material-symbols-outlined text-xs text-[#454955]">mail</span>
                          <span>{activeExchange.inviteeBusinessCard?.email}</span>
                        </div>
                        {activeExchange.inviteeBusinessCard?.phone && (
                          <div className="flex items-center gap-2">
                            <span className="material-symbols-outlined text-xs text-[#454955]">call</span>
                            <span>{activeExchange.inviteeBusinessCard.phone}</span>
                          </div>
                        )}
                      </div>
                    </div>

                    <p className="text-[10px] text-[#9E9DA0] leading-relaxed mt-4">
                      Accepting the exchange will share your business card with this investor and automatically publish both cards as files into the project Files.
                    </p>
                  </div>

                  {activeExchange.cardExchangeStatus === 'pending' ? (
                    <div className="space-y-4 border-t border-white/5 pt-4">
                      {/* LeadInvestor card configuration details preview */}
                      <div className="space-y-2.5">
                        <label className="block text-[9px] font-bold text-[#8a9b9b] uppercase tracking-wider">
                          Verify Your Card details to Disclose:
                        </label>
                        <div className="grid grid-cols-2 gap-2">
                          <input
                            type="text"
                            placeholder="Name"
                            value={leadInvestorCard.name}
                            onChange={(e) => setLeadInvestorCard({ ...leadInvestorCard, name: e.target.value })}
                            className="p-2 bg-[#0d0a0b]/60 border border-white/10 rounded text-[10px] text-white focus:outline-none focus:border-primary"
                          />
                          <input
                            type="text"
                            placeholder="Company"
                            value={leadInvestorCard.company}
                            onChange={(e) => setLeadInvestorCard({ ...leadInvestorCard, company: e.target.value })}
                            className="p-2 bg-[#0d0a0b]/60 border border-white/10 rounded text-[10px] text-white focus:outline-none focus:border-primary"
                          />
                          <input
                            type="email"
                            placeholder="Email"
                            value={leadInvestorCard.email}
                            onChange={(e) => setLeadInvestorCard({ ...leadInvestorCard, email: e.target.value })}
                            className="p-2 bg-[#0d0a0b]/60 border border-white/10 rounded text-[10px] text-white focus:outline-none focus:border-primary col-span-2"
                          />
                        </div>
                      </div>

                      <div className="flex gap-2">
                        <button
                          onClick={() => handleDeclineExchange(activeExchange.id)}
                          disabled={submittingExchange}
                          className="flex-1 py-2 px-3 border border-red-500/20 hover:bg-red-500/5 text-red-400 font-bold text-[10px] uppercase tracking-wider rounded-xl transition"
                        >
                          Decline Request
                        </button>
                        <button
                          onClick={() => handleAcceptExchange(activeExchange.id)}
                          disabled={submittingExchange || !leadInvestorCard.name || !leadInvestorCard.email}
                          className="flex-1 py-2 px-3 bg-white/10 hover:bg-white/20 border border-white/15 text-white font-bold text-[10px] uppercase tracking-wider rounded-xl transition flex items-center justify-center gap-1.5"
                        >
                          {submittingExchange ? (
                            <Loader2 className="w-3 h-3 animate-spin" />
                          ) : (
                            <Check className="w-3.5 h-3.5 text-emerald-400" />
                          )}
                          Accept & Swap
                        </button>
                      </div>
                    </div>
                  ) : (
                    <div className="flex items-center gap-2 text-xs font-semibold text-emerald-400 border border-emerald-500/10 bg-emerald-950/15 p-3 rounded-xl">
                      <UserCheck className="w-4 h-4" />
                      Exchange settings finalized. Status: {activeExchange.cardExchangeStatus}
                    </div>
                  )}
                </div>
              ) : (
                <div className="flex-1 flex flex-col items-center justify-center text-center p-8 text-xs text-[#9E9DA0] font-mono uppercase">
                  <Contact className="w-7 h-7 text-white/10 mb-2 animate-bounce" />
                  Select an exchange request to review
                </div>
              )}
            </div>
          </div>
        )
      )}
    </div>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import { useTheme } from "@/lib/utils/ThemeProvider";

interface JourneyProgressHeaderProps {
  projectId: string;
  currentPhase: number;
}

const PHASES = [
  { phase: 1, label: "Phase 1: Acquisition", sublabel: "Wizard & Intake", href: (id: string) => `/dashboard/projects/${id}` },
  { phase: 2, label: "Phase 2: Fund", sublabel: "Underwriting Workspace", href: (id: string) => `/dashboard/projects/${id}/underwriting` },
  { phase: 3, label: "Phase 3: Operations", sublabel: "Actuals & Variance", href: (id: string) => `/dashboard/projects/${id}/operations` },
  { phase: 4, label: "Phase 4: Exit", sublabel: "Hold-vs-Sell & Disposition", href: (id: string) => `/dashboard/projects/${id}/phase-4` },
];

export function JourneyProgressHeader({ projectId, currentPhase }: JourneyProgressHeaderProps) {
  const { theme } = useTheme();
  const isDark = theme === "dark";

  return (
    <div
      data-testid="journey-progress-header"
      className="w-full p-4 mb-6 rounded-2xl border border-solid shadow-sm transition-all"
      style={{
        background: isDark
          ? "linear-gradient(135deg, rgba(30,27,32,0.85) 0%, rgba(18,16,20,0.95) 100%)"
          : "#FFFFFF",
        borderColor: isDark ? "rgba(255,255,255,0.08)" : "rgba(69,73,85,0.12)",
      }}
    >
      <div className="flex items-center justify-between overflow-x-auto custom-scrollbar gap-2 sm:gap-4 pb-1 sm:pb-0">
        {PHASES.map((p, idx) => {
          const isCompleted = p.phase < currentPhase;
          const isCurrent = p.phase === currentPhase;
          const isUpcoming = p.phase > currentPhase;

          const content = (
            <div
              className={`flex items-center gap-2.5 px-3 py-2 rounded-xl transition-all ${
                isCompleted ? "hover:bg-black/5 dark:hover:bg-white/5 cursor-pointer" : ""
              }`}
            >
              {/* Node indicator badge */}
              <div
                className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold transition-all flex-shrink-0 ${
                  isCurrent ? "ring-2 ring-offset-1" : ""
                }`}
                style={{
                  background: isCompleted
                    ? "rgba(63, 125, 32, 0.15)"
                    : isCurrent
                    ? "#627C85"
                    : isDark
                    ? "rgba(255,255,255,0.06)"
                    : "rgba(69,73,85,0.08)",
                  color: isCompleted
                    ? "#3f7d20"
                    : isCurrent
                    ? "#FFFFFF"
                    : isDark
                    ? "rgba(253,255,252,0.4)"
                    : "rgba(69,73,85,0.5)",
                }}
              >
                {isCompleted ? (
                  <span className="material-symbols-outlined text-[16px]">check</span>
                ) : (
                  p.phase
                )}
              </div>

              {/* Node text */}
              <div className="flex flex-col min-w-0">
                <span
                  className={`text-xs font-bold truncate ${
                    isCurrent ? "text-on-surface" : isCompleted ? "opacity-90" : "opacity-40"
                  }`}
                >
                  {p.label}
                </span>
                <span className="text-[10px] opacity-60 truncate hidden md:inline">
                  {p.sublabel}
                </span>
              </div>
            </div>
          );

          return (
            <React.Fragment key={p.phase}>
              {isCompleted ? (
                <Link href={p.href(projectId)} className="flex-1 min-w-[130px]">
                  {content}
                </Link>
              ) : (
                <div className="flex-1 min-w-[130px]">{content}</div>
              )}

              {/* Connecting line */}
              {idx < PHASES.length - 1 && (
                <div
                  className="hidden sm:block h-[2px] w-6 flex-shrink-0 rounded-full"
                  style={{
                    background: isCompleted
                      ? "#3f7d20"
                      : isDark
                      ? "rgba(255,255,255,0.08)"
                      : "rgba(69,73,85,0.12)",
                  }}
                />
              )}
            </React.Fragment>
          );
        })}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { FileText, Download, Edit3, ChevronUp, AlertTriangle, Check, Info } from 'lucide-react';
import { jsPDF } from 'jspdf';
import toast from 'react-hot-toast';

interface LOIGeneratorProps {
  project: any;
  onSave: (updates: any) => Promise<void>;
  phaseColor?: string;
}

export default function LOIGenerator({ project, onSave, phaseColor = 'var(--text-primary)' }: LOIGeneratorProps) {
  const [isDraftingOpen, setIsDraftingOpen] = useState(false);
  const [saving, setSaving] = useState(false);

  const f = project?.financials || {};

  // Form State
  const [buyerEntity, setBuyerEntity] = useState(f.loiBuyerEntity || '');
  const [offerAmount, setOfferAmount] = useState(f.offer_price ? f.offer_price / 100 : (f.purchasePrice ? f.purchasePrice / 100 : 0));
  const [earnestMoney, setEarnestMoney] = useState(f.loiEarnestAmount ? f.loiEarnestAmount / 100 : 1000);
  const [earnestRefundable, setEarnestRefundable] = useState(f.loiRefundable !== undefined ? f.loiRefundable : true);
  const [dueDiligenceDays, setDueDiligenceDays] = useState(f.loiDueDiligenceDays || 14);
  const [closingDays, setClosingDays] = useState(f.loiClosingDays || 30);
  const [targetClosingDate, setTargetClosingDate] = useState(f.loiTargetClosingDate || '');
  const [selectedContingencies, setSelectedContingencies] = useState<string[]>(f.loiContingencies || ['Inspection', 'Financing', 'Appraisal']);
  const [exclusivity, setExclusivity] = useState(f.loiExclusivity !== undefined ? f.loiExclusivity : false);
  const [exclusivityDays, setExclusivityDays] = useState(f.loiExclusivityDays || 30);
  const [expiration, setExpiration] = useState(f.loiExpiration || '');
  const [assignability, setAssignability] = useState(f.loiAssignability !== undefined ? f.loiAssignability : false);
  const [nonBinding, setNonBinding] = useState(f.loiNonBinding !== undefined ? f.loiNonBinding : true);

  const selfUpdatedFields = useRef<Record<string, any>>({});

  // Sync state if financials reload from an external update
  useEffect(() => {
    const syncField = (propVal: any, localVal: any, fieldKey: string, setter: (val: any) => void, transform?: (val: any) => any) => {
      const transformedProp = transform ? transform(propVal) : propVal;
      const lastSentVal = selfUpdatedFields.current[fieldKey];
      console.log(`[LOISyncDebug] fieldKey: ${fieldKey}, propVal: ${propVal}, localVal: ${localVal}, lastSentVal: ${lastSentVal}`);

      if (lastSentVal !== undefined) {
        if (propVal === lastSentVal) {
          console.log(`[LOISyncDebug] matching, clearing selfUpdated: ${fieldKey}`);
          delete selfUpdatedFields.current[fieldKey];
        } else {
          console.log(`[LOISyncDebug] mismatch, ignoring propVal ${propVal} for fieldKey ${fieldKey}`);
          return;
        }
      }

      if (transformedProp !== undefined && transformedProp !== localVal) {
        console.log(`[LOISyncDebug] updating local state for fieldKey: ${fieldKey} to ${transformedProp}`);
        setter(transformedProp);
      }
    };

    syncField(f.loiBuyerEntity, buyerEntity, 'loiBuyerEntity', setBuyerEntity);
    syncField(f.offer_price, offerAmount, 'offer_price', setOfferAmount, (v) => v / 100);
    syncField(f.loiEarnestAmount, earnestMoney, 'loiEarnestAmount', setEarnestMoney, (v) => v / 100);
    syncField(f.loiRefundable, earnestRefundable, 'loiRefundable', setEarnestRefundable);
    syncField(f.loiDueDiligenceDays, dueDiligenceDays, 'loiDueDiligenceDays', setDueDiligenceDays);
    syncField(f.loiClosingDays, closingDays, 'loiClosingDays', setClosingDays);
    syncField(f.loiTargetClosingDate, targetClosingDate, 'loiTargetClosingDate', setTargetClosingDate);
    syncField(f.loiContingencies, selectedContingencies, 'loiContingencies', setSelectedContingencies);
    syncField(f.loiExclusivity, exclusivity, 'loiExclusivity', setExclusivity);
    syncField(f.loiExclusivityDays, exclusivityDays, 'loiExclusivityDays', setExclusivityDays);
    syncField(f.loiExpiration, expiration, 'loiExpiration', setExpiration);
    syncField(f.loiAssignability, assignability, 'loiAssignability', setAssignability);
    syncField(f.loiNonBinding, nonBinding, 'loiNonBinding', setNonBinding);
  }, [project?.financials]);

  const toggleContingency = (name: string) => {
    setSelectedContingencies(prev =>
      prev.includes(name) ? prev.filter(c => c !== name) : [...prev, name]
    );
  };

  const formattedDate = new Date().toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  const formattedOffer = offerAmount > 0 
    ? `$${offerAmount.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` 
    : 'TBD';

  const formattedEMD = earnestMoney > 0 
    ? `$${earnestMoney.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}` 
    : 'TBD';

  // Build LOI text for preview & generation
  const buildLoiText = () => {
    const listContingencies = selectedContingencies.length > 0 
      ? selectedContingencies.join(', ')
      : 'None';

    const ddText = dueDiligenceDays > 0 
      ? `Buyer shall have a due diligence and inspection period of ${dueDiligenceDays} days from the execution date of the Purchase Agreement.`
      : 'No inspection or due diligence period is requested.';

    const closingDateText = targetClosingDate 
      ? `Closing shall occur on or before ${new Date(targetClosingDate).toLocaleDateString('en-US')}.`
      : `Closing shall occur within ${closingDays} days following the expiration of the Due Diligence Period.`;

    const exclusivityText = exclusivity 
      ? `Seller agrees to grant the Buyer exclusive negotiating rights for a period of ${exclusivityDays} days following the execution of this LOI.`
      : 'No exclusivity period is requested.';

    const assignabilityText = assignability 
      ? 'This LOI and any subsequent Purchase Agreement shall be assignable by the Buyer to any affiliated entity.'
      : 'This LOI is non-assignable without the Seller\'s prior written consent.';

    const expirationText = expiration 
      ? `This offer is open for acceptance until ${new Date(expiration).toLocaleString('en-US')}.`
      : `This offer shall expire 3 business days from the date hereof.`;

    const bindingStatusText = nonBinding 
      ? 'NON-BINDING STATUS: This Letter of Intent is entirely non-binding on the parties and serves solely as a statement of interest. Neither party shall be bound to purchase or sell the Property until a formal Purchase Agreement is executed.'
      : 'BINDING STATUS WARNING: THIS LETTER OF INTENT IS BINDING UPON BOTH PARTIES. BY SIGNING BELOW, SELLER AND BUYER AGREE TO BE LEGALLY BOUND BY THE TERMS OUTLINED HEREIN.';

    return `LETTER OF INTENT TO PURCHASE REAL ESTATE

Date: ${formattedDate}

Property Address: ${project?.address || '[Property Address]'}
Proposed Buyer: ${buyerEntity || '[Buyer Entity]'}

Dear Seller,

This Letter of Intent ("LOI") sets forth the key terms and conditions under which the Buyer proposes to purchase the above-referenced Property.

1. Purchase Price: The proposed purchase price for the Property is ${formattedOffer}.
2. Earnest Money Deposit: The Buyer will submit an earnest money deposit of ${formattedEMD} within 3 business days of contract execution. This deposit shall be ${earnestRefundable ? 'Refundable' : 'Non-Refundable'} during the due diligence period.
3. Due Diligence & Inspection: ${ddText}
4. Closing: ${closingDateText}
5. Contingencies: This transaction is contingent upon: ${listContingencies}.
6. Exclusivity: ${exclusivityText}
7. Assignability: ${assignabilityText}
8. Expiration: ${expirationText}

${bindingStatusText}

Sincerely,



_________________________
Buyer: ${buyerEntity || '[Buyer Entity]'}
`;
  };

  const loiText = buildLoiText();

  // Helper to compile and save PDF
  const generatePdfBlob = () => {
    const doc = new jsPDF({
      orientation: 'portrait',
      unit: 'in',
      format: 'letter'
    });

    doc.setFont('times', 'normal');
    doc.setFontSize(11);

    // Split text into lines that fit the page width (8.5 - 2 inches margins)
    const lines = doc.splitTextToSize(loiText, 6.5);
    doc.text(lines, 1, 1);
    return doc;
  };

  const handleDownloadPdf = () => {
    const doc = generatePdfBlob();
    const safeAddress = project?.address ? project.address.replace(/[^a-z0-9]/gi, '_').toLowerCase() : 'property';
    doc.save(`LOI_${safeAddress}.pdf`);
    toast.success('LOI PDF exported successfully');
  };

  const handleSendLoi = async () => {
    setSaving(true);
    try {
      const updates = {
        loiBuyerEntity: buyerEntity,
        offer_price: offerAmount * 100,
        loiEarnestAmount: earnestMoney * 100,
        loiRefundable: earnestRefundable,
        loiDueDiligenceDays: dueDiligenceDays,
        loiClosingDays: closingDays,
        loiTargetClosingDate: targetClosingDate,
        loiContingencies: selectedContingencies,
        loiExclusivity: exclusivity,
        loiExclusivityDays: exclusivityDays,
        loiExpiration: expiration,
        loiAssignability: assignability,
        loiNonBinding: nonBinding,
        loiUrl: `/mock/loi_${project?.id || 'doc'}.pdf`, // mock link
        offerStatus: 'Offer Sent'
      };

      await onSave(updates);
      toast.success('Letter of Intent saved and status changed to "Offer Sent"!');
    } catch (err) {
      console.error(err);
      toast.error('Failed to save LOI');
    } finally {
      setSaving(false);
    }
  };

  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Clean up timeout on unmount
  useEffect(() => {
    return () => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
      }
    };
  }, []);

  const handleAutoSaveField = (fields: any) => {
    selfUpdatedFields.current = { ...selfUpdatedFields.current, ...fields };
    if (saveTimeoutRef.current) {
      clearTimeout(saveTimeoutRef.current);
    }
    saveTimeoutRef.current = setTimeout(async () => {
      try {
        await onSave(fields);
      } catch (err) {
        console.error('Failed to autosave LOI fields:', err);
      }
    }, 400);
  };

  return (
    <div className="mt-4 pt-4" style={{ borderTop: '1px dashed var(--border-ui)' }}>
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <FileText className="w-4 h-4" style={{ color: phaseColor }} />
          <span className="text-xs font-bold uppercase tracking-[0.1em]" style={{ color: 'var(--text-primary)' }}>
            Letter of Intent (LOI) &amp; Agreement Builder
          </span>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={() => setIsDraftingOpen(!isDraftingOpen)}
            id="draft-loi-toggle"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-md transition-colors"
            style={{ background: 'var(--bg-inset)', border: '1px solid var(--border-ui)' }}
          >
            {isDraftingOpen ? (
              <ChevronUp className="w-3 h-3 text-gray-500" />
            ) : (
              <Edit3 className="w-3 h-3 text-gray-500" />
            )}
            <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-gray-600">
              {isDraftingOpen ? 'Close Editor' : 'Draft / Edit LOI'}
            </span>
          </button>

          <button
            onClick={handleDownloadPdf}
            id="export-loi-pdf-btn"
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-md transition-opacity hover:opacity-90 shadow-sm"
            style={{ background: phaseColor, color: '#FFFFFF' }}
          >
            <Download className="w-3.5 h-3.5" />
            <span className="text-[10px] font-bold uppercase tracking-[0.1em]">
              Export PDF
            </span>
          </button>
        </div>
      </div>

      {isDraftingOpen && (
        <div className="mt-6 flex flex-col xl:flex-row gap-6">
          {/* Left Pane: Form Inputs */}
          <div className="flex-1 space-y-4 max-h-[600px] overflow-y-auto pr-2 custom-scrollbar">
            <h3 className="text-xs font-bold uppercase tracking-[0.1em] text-gray-600 mb-2">LOI Terms &amp; Variables</h3>

            {/* Warning Banner */}
            {!nonBinding && (
              <div id="non-binding-warning" className="p-3 bg-red-950/40 border border-red-500/25 rounded-md flex items-start gap-2.5 animate-in fade-in duration-300">
                <AlertTriangle className="w-4 h-4 text-red-400 mt-0.5 shrink-0" />
                <div>
                  <span className="text-[10px] font-bold uppercase tracking-wider text-red-400 block">Binding Contract Warning</span>
                  <p className="text-[10px] text-red-200/90 leading-relaxed mt-0.5">
                    Removing the non-binding clause will turn this Letter of Intent into a legally binding purchase offer. Proceed with professional legal advice.
                  </p>
                </div>
              </div>
            )}

            <div className="space-y-4">
              {/* Buyer Entity */}
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                  Buyer Entity
                </label>
                <input
                  type="text"
                  id="loi-buyer-entity"
                  value={buyerEntity}
                  onChange={(e) => {
                    setBuyerEntity(e.target.value);
                    handleAutoSaveField({ loiBuyerEntity: e.target.value });
                  }}
                  className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                  style={{ borderColor: 'var(--border-ui)' }}
                  placeholder="e.g. Acme Holdings LLC"
                />
              </div>

              {/* Prefilled Price & Earnest Money */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Prefilled Price ($)
                  </label>
                  <input
                    type="number"
                    id="loi-offer-price"
                    value={offerAmount || ''}
                    onChange={(e) => {
                      setOfferAmount(Number(e.target.value));
                      handleAutoSaveField({ offer_price: Number(e.target.value) * 100 });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                    placeholder="Prefilled Price"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Earnest Money Deposit ($)
                  </label>
                  <input
                    type="number"
                    id="loi-earnest-money"
                    value={earnestMoney || ''}
                    onChange={(e) => {
                      setEarnestMoney(Number(e.target.value));
                      handleAutoSaveField({ loiEarnestAmount: Number(e.target.value) * 100 });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                    placeholder="e.g. 5000"
                  />
                </div>
              </div>

              {/* Earnest Refundability & DD Period */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    EMD Refundability
                  </label>
                  <select
                    id="loi-emd-refundable"
                    value={earnestRefundable ? 'true' : 'false'}
                    onChange={(e) => {
                      const val = e.target.value === 'true';
                      setEarnestRefundable(val);
                      handleAutoSaveField({ loiRefundable: val });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                  >
                    <option value="true">Refundable</option>
                    <option value="false">Non-Refundable</option>
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Due Diligence (Days)
                  </label>
                  <input
                    type="number"
                    id="loi-dd-days"
                    value={dueDiligenceDays || ''}
                    onChange={(e) => {
                      setDueDiligenceDays(Number(e.target.value));
                      handleAutoSaveField({ loiDueDiligenceDays: Number(e.target.value) });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                    placeholder="e.g. 14"
                  />
                </div>
              </div>

              {/* Closing Days & Target Date */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Closing Days after DD
                  </label>
                  <input
                    type="number"
                    id="loi-closing-days"
                    value={closingDays || ''}
                    onChange={(e) => {
                      setClosingDays(Number(e.target.value));
                      handleAutoSaveField({ loiClosingDays: Number(e.target.value) });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                    placeholder="e.g. 30"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Target Closing Date (Optional)
                  </label>
                  <input
                    type="date"
                    id="loi-closing-date"
                    value={targetClosingDate}
                    onChange={(e) => {
                      setTargetClosingDate(e.target.value);
                      handleAutoSaveField({ loiTargetClosingDate: e.target.value });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                  />
                </div>
              </div>

              {/* Exclusivity Clause */}
              <div className="p-3 bg-black/10 border border-white/5 rounded-md space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-gray-400">
                    Request Exclusivity Clause
                  </span>
                  <input
                    type="checkbox"
                    id="loi-exclusivity"
                    checked={exclusivity}
                    onChange={(e) => {
                      setExclusivity(e.target.checked);
                      handleAutoSaveField({ loiExclusivity: e.target.checked });
                    }}
                    className="w-4 h-4 rounded text-black border-white/20 focus:ring-0 cursor-pointer"
                  />
                </div>
                {exclusivity && (
                  <div className="animate-in slide-in-from-top-1 duration-200">
                    <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                      Exclusivity Period (Days)
                    </label>
                    <input
                      type="number"
                      id="loi-exclusivity-days"
                      value={exclusivityDays}
                      onChange={(e) => {
                        setExclusivityDays(Number(e.target.value));
                        handleAutoSaveField({ loiExclusivityDays: Number(e.target.value) });
                      }}
                      className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                      style={{ borderColor: 'var(--border-ui)' }}
                    />
                  </div>
                )}
              </div>

              {/* Offer Expiration & Assignability */}
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Offer Expiration Date
                  </label>
                  <input
                    type="date"
                    id="loi-expiration-date"
                    value={expiration}
                    onChange={(e) => {
                      setExpiration(e.target.value);
                      handleAutoSaveField({ loiExpiration: e.target.value });
                    }}
                    className="w-full px-3 py-2 text-sm rounded-md outline-none bg-black/20 border text-white"
                    style={{ borderColor: 'var(--border-ui)' }}
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-1">
                    Assignability
                  </label>
                  <div className="flex items-center gap-2 h-10">
                    <input
                      type="checkbox"
                      id="loi-assignability"
                      checked={assignability}
                      onChange={(e) => {
                        setAssignability(e.target.checked);
                        handleAutoSaveField({ loiAssignability: e.target.checked });
                      }}
                      className="w-4 h-4 rounded text-black border-white/20 focus:ring-0 cursor-pointer"
                    />
                    <span className="text-xs text-white">Assignable Offer</span>
                  </div>
                </div>
              </div>

              {/* Non-Binding Clause */}
              <div className="flex items-center justify-between p-3 bg-black/10 border border-white/5 rounded-md">
                <div className="flex flex-col gap-0.5">
                  <span className="text-[10px] font-bold uppercase tracking-[0.1em] text-white">
                    Non-Binding Clause
                  </span>
                  <span className="text-[9px] text-gray-400">
                    Keep checked to state this offer is non-binding
                  </span>
                </div>
                <input
                  type="checkbox"
                  id="loi-non-binding-checkbox"
                  checked={nonBinding}
                  onChange={(e) => {
                    console.log(`[LOISyncDebug] Checkbox changed: localChecked=${e.target.checked}`);
                    setNonBinding(e.target.checked);
                    handleAutoSaveField({ loiNonBinding: e.target.checked });
                  }}
                  className="w-4 h-4 rounded text-black border-white/20 focus:ring-0 cursor-pointer"
                />
              </div>

              {/* Contingencies Checkboxes */}
              <div>
                <label className="block text-[10px] font-bold uppercase tracking-[0.1em] text-gray-500 mb-2">
                  Active Contingencies
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {['Financing', 'Appraisal', 'Inspection', 'Title', 'Environmental', 'Survey'].map(c => {
                    const isSelected = selectedContingencies.includes(c);
                    return (
                      <button
                        key={c}
                        type="button"
                        onClick={() => {
                          const updated = selectedContingencies.includes(c)
                            ? selectedContingencies.filter(item => item !== c)
                            : [...selectedContingencies, c];
                          setSelectedContingencies(updated);
                          handleAutoSaveField({ loiContingencies: updated });
                        }}
                        className="flex items-center justify-between px-3 py-2 text-xs rounded-md border text-left transition-all"
                        style={{
                          background: isSelected ? 'rgba(255,255,255,0.03)' : 'transparent',
                          borderColor: isSelected ? phaseColor : 'rgba(255,255,255,0.05)',
                          color: isSelected ? '#FFFFFF' : 'var(--text-secondary)'
                        }}
                        id={`contingency-checkbox-${c.toLowerCase()}`}
                      >
                        <span>{c}</span>
                        {isSelected && <Check className="w-3.5 h-3.5" style={{ color: phaseColor }} />}
