'use client';

import React, { useState, useEffect } from 'react';
import { Project, ProjectFinancials, LeaseIncomeEntry, ActualLeaseTerms } from '@/types/schema';
import { DollarSign, Calendar, Plus, Trash2, Check, Sparkles, FileText, ArrowUpRight } from 'lucide-react';
import toast from 'react-hot-toast';
import { useProjectStore } from '@/store/projectStore';
import { IS_DEMO_MODE } from '@/lib/config/demo';

interface LeaseOperationsCardProps {
  project: Project;
  refresh: () => void;
  isLocked?: boolean;
}

interface PlaidAttributionProposal {
  id: string;
  amount: number;
  date: string;
  tenantName: string;
  source: 'plaid';
}

const mockPlaidProposals: PlaidAttributionProposal[] = [
  { id: 'lease-prop-1', amount: 4500, date: new Date().toISOString().split('T')[0], tenantName: 'Lexington Tech Corp', source: 'plaid' },
];

export default function LeaseOperationsCard({ project, refresh, isLocked }: LeaseOperationsCardProps) {
  const financials = project.financials || {};
  const leaseIncome = financials.lease_income || [];
  const leaseTerms = financials.lease_terms || { rateCents: 0, termMonths: 12, escalations: '', type: 'Gross' };

  const updateProjectFinancials = useProjectStore(state => state.updateProjectFinancials);

  // States
  const [proposals, setProposals] = useState<PlaidAttributionProposal[]>(mockPlaidProposals);
  const [isPlaidConnected, setIsPlaidConnected] = useState(false);
  const [showManualForm, setShowManualForm] = useState(false);

  // Term states
  const [rate, setRate] = useState(leaseTerms.rateCents ? String(leaseTerms.rateCents / 100) : '');
  const [termMonths, setTermMonths] = useState(String(leaseTerms.termMonths));
  const [escalations, setEscalations] = useState(leaseTerms.escalations || '');
  const [leaseType, setLeaseType] = useState<ActualLeaseTerms['type']>(leaseTerms.type);

  // Manual payment entry states
  const [manualAmount, setManualAmount] = useState('');
  const [manualDate, setManualDate] = useState(new Date().toISOString().split('T')[0]);

  // Sync terms when parent updates
  useEffect(() => {
    setRate(leaseTerms.rateCents ? String(leaseTerms.rateCents / 100) : '');
    setTermMonths(String(leaseTerms.termMonths));
    setEscalations(leaseTerms.escalations || '');
    setLeaseType(leaseTerms.type);
  }, [leaseTerms.rateCents, leaseTerms.termMonths, leaseTerms.escalations, leaseTerms.type]);

  // Save lease terms
  const handleSaveTerms = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      await updateProjectFinancials(project.id, {
        lease_terms: {
          rateCents: Math.round((Number(rate) || 0) * 100),
          termMonths: Number(termMonths) || 12,
          escalations,
          type: leaseType,
        },
      });
      toast.success('Lease terms updated successfully');
      refresh();
    } catch (err) {
      console.error(err);
      toast.error('Failed to update lease terms');
    }
  };

  // Add manual payment
  const handleAddManualPayment = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!manualAmount || !manualDate) {
      toast.error('Please enter amount and date');
      return;
    }

    const newEntry: LeaseIncomeEntry = {
      id: `lease-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      amount: Number(manualAmount),
      date: manualDate,
      confirmed: true,
      source: 'manual',
    };

    const updatedIncome = [...leaseIncome, newEntry];

    try {
      await updateProjectFinancials(project.id, {
        lease_income: updatedIncome,
      });
      toast.success('Lease payment logged successfully');
      setManualAmount('');
      setShowManualForm(false);
      refresh();
    } catch (err) {
      console.error(err);
      toast.error('Failed to log lease payment');
    }
  };

  // Confirm proposed Plaid payment
  const handleConfirmProposal = async (proposal: PlaidAttributionProposal) => {
    const newEntry: LeaseIncomeEntry = {
      id: `lease-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      amount: proposal.amount,
      date: proposal.date,
      confirmed: true,
      source: 'plaid',
    };

    const updatedIncome = [...leaseIncome, newEntry];

    try {
      await updateProjectFinancials(project.id, {
        lease_income: updatedIncome,
      });
      setProposals(prev => prev.filter(p => p.id !== proposal.id));
      toast.success(`Confirmed lease payment of $${proposal.amount}`);
      refresh();
    } catch (err) {
      console.error(err);
      toast.error('Failed to confirm lease payment');
    }
  };

  // Decline/Ignore proposed payment
  const handleDeclineProposal = (id: string) => {
    setProposals(prev => prev.filter(p => p.id !== id));
    toast.success('Proposal ignored');
  };

  // Delete payment entry
  const handleDeleteEntry = async (id: string) => {
    const updatedIncome = leaseIncome.filter(entry => entry.id !== id);
    try {
      await updateProjectFinancials(project.id, {
        lease_income: updatedIncome,
      });
      toast.success('Lease payment deleted');
      refresh();
    } catch (err) {
      console.error(err);
      toast.error('Failed to delete payment');
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
      {/* Left Column: Lease Terms Input */}
      <div
        className="lg:col-span-5 rounded-[8px] border overflow-hidden"
        style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}
      >
        <div
          className="px-6 py-4 border-b flex justify-between items-center"
          style={{ borderColor: 'var(--border-ui)' }}
        >
          <div>
            <h3 className="text-sm font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
              <FileText className="w-4 h-4 text-emerald-500" />
              Activated Lease Terms
            </h3>
            <p className="text-[10px] uppercase tracking-[0.15em] mt-0.5 text-[var(--text-tertiary)]">
              Specify active commercial/residential lease parameters
            </p>
          </div>
        </div>

        <form onSubmit={handleSaveTerms} className="p-6 space-y-4">
          <div className="space-y-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">
              Lease Rate ($ / Month)
            </label>
            <div className="relative group">
              <input
                type="number"
                placeholder="e.g. 4500"
                value={rate}
                onChange={e => setRate(e.target.value)}
                disabled={isLocked}
                className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
                required
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-1">
              <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">
                Term (Months)
              </label>
              <input
                type="number"
                placeholder="e.g. 12"
                value={termMonths}
                onChange={e => setTermMonths(e.target.value)}
                disabled={isLocked}
                className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
                required
              />
            </div>

            <div className="space-y-1">
              <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">
                Lease Type
              </label>
              <select
                value={leaseType}
                onChange={e => setLeaseType(e.target.value as ActualLeaseTerms['type'])}
                disabled={isLocked}
                className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none bg-[var(--bg-surface)] text-[var(--text-primary)]"
              >
                <option value="Gross">Gross</option>
                <option value="NNN">NNN</option>
                <option value="Modified_Gross">Modified Gross</option>
              </select>
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">
              Escalation Structure
            </label>
            <input
              type="text"
              placeholder="e.g. 3% annual escalation starting Year 2"
              value={escalations}
              onChange={e => setEscalations(e.target.value)}
              disabled={isLocked}
              className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
            />
          </div>

          {!isLocked && (
            <button
              type="submit"
              className="w-full mt-2 py-2 rounded text-[10px] font-bold uppercase tracking-widest bg-[var(--text-primary)] text-[var(--bg-surface)] hover:opacity-90 transition-all"
            >
              Update Lease Terms
            </button>
          )}
        </form>
      </div>

      {/* Right Column: Payments Ledger */}
      <div
        className="lg:col-span-7 rounded-[8px] border overflow-hidden"
        style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}
      >
        <div
          className="px-6 py-4 border-b flex justify-between items-center"
          style={{ borderColor: 'var(--border-ui)' }}
        >
          <div>
            <h3 className="text-sm font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
              <ArrowUpRight className="w-4 h-4 text-emerald-500" />
              Lease Payments &amp; Receipts
            </h3>
            <p className="text-[10px] uppercase tracking-[0.15em] mt-0.5 text-[var(--text-tertiary)]">
              Log payments received against lease schedule
            </p>
          </div>

          <div className="flex items-center gap-2">
            {IS_DEMO_MODE && (
              <button
                onClick={() => setIsPlaidConnected(!isPlaidConnected)}
                className="flex items-center gap-1 px-2.5 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest border transition-all"
                style={{
                  backgroundColor: isPlaidConnected ? 'rgba(16,185,129,0.1)' : 'transparent',
                  borderColor: isPlaidConnected ? '#10b981' : 'var(--border-ui)',
                  color: isPlaidConnected ? '#10b981' : 'var(--text-secondary)',
                }}
              >
                <Sparkles className="w-3 h-3 text-amber-500" />
                {isPlaidConnected ? 'Plaid Active (Demo)' : 'Connect Plaid (Demo)'}
              </button>
            )}

            {!isLocked && (
              <button
                onClick={() => setShowManualForm(!showManualForm)}
                className="flex items-center gap-1.5 px-2.5 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest transition-all bg-[var(--text-primary)] text-[var(--bg-surface)] hover:opacity-90"
              >
                <Plus className="w-3 h-3" />
                Log Payment
              </button>
            )}
          </div>
        </div>

        <div className="p-6 space-y-6">
          {/* Plaid Auto proposals */}
          {IS_DEMO_MODE && isPlaidConnected && proposals.length > 0 && (
            <div className="p-4 rounded-lg bg-[rgba(16,185,129,0.03)] border border-emerald-500/20 space-y-3 relative">
              <div className="absolute top-2 right-2 flex items-center">
                <span className="text-[8px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20">Demo</span>
              </div>
              <span className="text-[10px] font-bold uppercase tracking-widest text-emerald-400 flex items-center gap-1.5">
                <Sparkles className="w-3.5 h-3.5 text-amber-500 animate-pulse" />
                Plaid Detected Lease Transaction (Demo)
              </span>
              {proposals.map(p => (
                <div
                  key={p.id}
                  className="p-3 rounded bg-[var(--bg-canvas)] border border-[var(--border-ui)] flex items-center justify-between"
                >
                  <div>
                    <p className="text-xs font-bold text-[var(--text-primary)]">{p.tenantName}</p>
                    <p className="text-[10px] text-[var(--text-tertiary)]">{p.date}</p>
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-xs font-bold text-emerald-400 mr-2">${p.amount}</span>
                    <button
                      onClick={() => handleConfirmProposal(p)}
                      className="p-1 rounded hover:bg-emerald-500/10 text-emerald-400"
                    >
                      <Check className="w-4 h-4" />
                    </button>
                    <button
                      onClick={() => handleDeclineProposal(p.id)}
                      className="p-1 rounded hover:bg-rose-500/10 text-rose-400"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Manual Entry */}
          {showManualForm && (
            <form onSubmit={handleAddManualPayment} className="p-4 rounded border border-[var(--border-ui)] space-y-3">
              <h4 className="text-xs font-bold uppercase tracking-wider text-[var(--text-primary)]">
                Log Lease Payment Manually
              </h4>
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-tertiary)]">Amount ($)</label>
                  <input
                    type="number"
                    value={manualAmount}
                    onChange={e => setManualAmount(e.target.value)}
                    placeholder="e.g. 3000"
                    className="glass-input w-full text-xs py-2 px-3 focus:outline-none"
                    required
                  />
                </div>
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-tertiary)]">Payment Date</label>
                  <input
                    type="date"
                    value={manualDate}
                    onChange={e => setManualDate(e.target.value)}
                    className="glass-input w-full text-xs py-2 px-3 focus:outline-none"
                    required
                  />
                </div>
              </div>
              <div className="flex justify-end gap-3 pt-2">
                <button
                  type="button"
                  onClick={() => setShowManualForm(false)}
                  className="px-3 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest text-[var(--text-secondary)] hover:bg-[rgba(255,255,255,0.05)]"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-3 py-1.5 rounded text-[9px] font-bold uppercase tracking-widest bg-emerald-500 text-white hover:bg-emerald-600"
                >
                  Add Lease Payment
                </button>
              </div>
            </form>
          )}

          {/* Payments Table */}
          <div className="border border-[var(--border-ui)] rounded overflow-hidden">
            <table className="w-full text-left border-collapse text-xs">
              <thead>
                <tr className="bg-[rgba(255,255,255,0.02)] border-b border-[var(--border-ui)]">
                  <th className="p-3 font-bold uppercase tracking-widest text-[10px] text-[var(--text-tertiary)]">Date</th>
                  <th className="p-3 font-bold uppercase tracking-widest text-[10px] text-[var(--text-tertiary)]">Source</th>
                  <th className="p-3 font-bold uppercase tracking-widest text-[10px] text-[var(--text-tertiary)] text-right">Amount</th>
                  <th className="p-3 text-right"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-[var(--border-ui)]">
                {leaseIncome.length === 0 ? (
                  <tr>
                    <td colSpan={4} className="p-6 text-center text-[var(--text-tertiary)]">
                      No lease payments logged yet.
                    </td>
                  </tr>
                ) : (
                  leaseIncome.map(entry => (
                    <tr key={entry.id} className="hover:bg-[rgba(255,255,255,0.01)] transition-colors">
                      <td className="p-3 text-[var(--text-secondary)]">{entry.date}</td>
                      <td className="p-3">
                        <span
                          className="px-2 py-0.5 rounded-full text-[9px] font-bold uppercase tracking-wider"
                          style={{
                            backgroundColor: entry.source === 'plaid' ? 'rgba(16,185,129,0.1)' : 'rgba(255,255,255,0.05)',
                            color: entry.source === 'plaid' ? '#10b981' : 'var(--text-secondary)',
                          }}
                        >
                          {entry.source || 'manual'}
                        </span>
                      </td>
                      <td className="p-3 font-bold text-[var(--text-primary)] text-right">${entry.amount}</td>
                      <td className="p-3 text-right">
                        {!isLocked && (
                          <button
                            onClick={() => handleDeleteEntry(entry.id)}
                            className="p-1 rounded text-rose-500 hover:bg-rose-500/10 transition-colors"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { getAuth } from 'firebase/auth';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import type { LenderPackageItem } from '@/types/schema';
import { 
  FileText,
  Upload,
  CheckCircle2,
  Trash2,
  Plus,
  Clock,
  ExternalLink,
  Loader2,
  X,
  AlertCircle
} from 'lucide-react';
import toast from 'react-hot-toast';

interface Props {
  projectId: string;
}

export function LenderPackageTracker({ projectId }: Props) {
  const [items, setItems] = useState<LenderPackageItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [addingItem, setAddingItem] = useState(false);
  const [newItemName, setNewItemName] = useState('');
  const [uploadingItemId, setUploadingItemId] = useState<string | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 1. Listen to checklist subcollection
  useEffect(() => {
    if (!projectId) return;

    // Check for E2E testing mock
    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_lender_package_${projectId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          setItems(val ? JSON.parse(val) : []);
          setLoading(false);
        } catch (e) {
          console.error(e);
        }
      };
      load();
      window.addEventListener('storage', (e) => {
        if (e.key === key) load();
      });
      return;
    }

    const q = query(
      collection(db, 'projects', projectId, 'lenderPackage'),
      orderBy('createdAt', 'asc')
    );

    const unsub = onSnapshot(
      q,
      (snap) => {
        const docs = snap.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        })) as LenderPackageItem[];
        setItems(docs);
        setLoading(false);
      },
      (err) => {
        console.error('[LenderPackageTracker] subcollection read failed, trying to trigger seed:', err);
        // Trigger initial fetch/GET to auto-seed the customary items
        const triggerSeed = async () => {
          try {
            const auth = getAuth();
            const token = await auth.currentUser?.getIdToken();
            if (token) {
              const res = await fetch(`/api/projects/${projectId}/lender-package`, {
                headers: { 'Authorization': `Bearer ${token}` }
              });
              if (res.ok) {
                const data = await res.json();
                setItems(data.items || []);
              }
            }
          } catch (e) {
            console.error('Trigger seed failed:', e);
          } finally {
            setLoading(false);
          }
        };
        triggerSeed();
      }
    );

    return unsub;
  }, [projectId]);

  // Fallback trigger if no items exist on page load
  useEffect(() => {
    if (loading || items.length > 0) return;
    const triggerSeed = async () => {
      try {
        const auth = getAuth();
        const token = await auth.currentUser?.getIdToken();
        if (token) {
          const res = await fetch(`/api/projects/${projectId}/lender-package`, {
            headers: { 'Authorization': `Bearer ${token}` }
          });
          if (res.ok) {
            const data = await res.json();
            setItems(data.items || []);
          }
        }
      } catch (e) {
        console.error(e);
      }
    };
    triggerSeed();
  }, [projectId, loading, items.length]);

  const handleAddCustomItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItemName.trim()) return;

    setAddingItem(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/lender-package`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          name: newItemName.trim(),
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to add checklist item.');
      }

      setNewItemName('');
      toast.success('Custom checklist item added.');
    } catch (err: any) {
      toast.error(err.message || 'Error adding item.');
    } finally {
      setAddingItem(false);
    }
  };

  const handleDeleteItem = async (itemId: string, name: string) => {
    if (!window.confirm(`Are you sure you want to remove "${name}"?`)) return;

    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/lender-package/${itemId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to delete item.');
      }

      toast.success('Checklist item removed.');
    } catch (err: any) {
      toast.error(err.message || 'Error deleting item.');
    }
  };

  const handleUpdateCadence = async (itemId: string, cadence: 'none' | 'daily' | 'weekly') => {
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/lender-package/${itemId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          reminderCadence: cadence,
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to update cadence.');
      }

      toast.success('Reminder cadence updated.');
    } catch (err: any) {
      toast.error(err.message || 'Error updating cadence.');
    }
  };

  const handleFileUpload = async (itemId: string, e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('Only PDF documents are allowed.');
      return;
    }

    setUploadingItemId(itemId);
    const toastId = toast.loading('Uploading document to Project Files Debt folder...');

    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      // 1. Ensure Debt folder exists
      const folderRes = await fetch(`/api/projects/${projectId}/lender-package/debt-folder`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!folderRes.ok) {
        throw new Error('Failed to provision Debt folder in the Project Files.');
      }
      const { folderId } = await folderRes.json();

      // 2. Upload the file to documents endpoint
      const formData = new FormData();
      formData.append('file', file);
      formData.append('folderId', folderId);
      formData.append('category', 'Other');
      formData.append('documentType', 'other');

      const uploadRes = await fetch(`/api/projects/${projectId}/documents`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
        body: formData,
      });

      if (!uploadRes.ok) {
        const errData = await uploadRes.json();
        throw new Error(errData.error || 'Document upload failed.');
      }

      const { docId, downloadUrl } = await uploadRes.json();

      // 3. Update checklist item in database
      const updateRes = await fetch(`/api/projects/${projectId}/lender-package/${itemId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          status: 'Uploaded',
          fileId: docId,
          fileName: file.name,
          fileUrl: downloadUrl,
        }),
      });

      if (!updateRes.ok) {
        throw new Error('Failed to link document to checklist item.');
      }

      toast.success('Document uploaded and saved to Project Files Debt folder.', { id: toastId });
    } catch (err: any) {
      toast.error(err.message || 'Error uploading document.', { id: toastId });
    } finally {
      setUploadingItemId(null);
      if (e.target) e.target.value = '';
    }
  };

  const handleClearFile = async (itemId: string) => {
    if (!window.confirm('Are you sure you want to remove this document link?')) return;

    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/lender-package/${itemId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          status: 'Pending',
          fileId: null,
          fileName: null,
          fileUrl: null,
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to clear document.');
      }

      toast.success('Document removed.');
    } catch (err: any) {
      toast.error(err.message || 'Error clearing document.');
    }
  };

  if (loading) {
    return (
      <div className="glass-card p-6 flex flex-col items-center justify-center min-h-[150px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#7A9EAA] mb-2" />
        <span className="text-xs text-pw-muted font-light uppercase tracking-wider">Loading customary package checklist...</span>
      </div>
    );
  }

  const uploadedCount = items.filter(i => i.status === 'Uploaded').length;
  const totalCount = items.length;
  const completionPct = totalCount > 0 ? Math.round((uploadedCount / totalCount) * 100) : 0;

  return (
    <div className="glass-card p-6 space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center border-b border-pw-border pb-4 gap-4">
        <div className="flex-1">
          <h3 className="text-lg font-light uppercase tracking-widest text-pw-black flex items-center gap-2.5">
            <FileText className="w-5 h-5 text-[#7A9EAA]" />
            Lender Package (Customary Checklist)
          </h3>
          <p className="text-xs text-pw-muted font-light mt-1">
            Manage and upload the customary underwriting package required by the lender.
          </p>
          <div className="flex items-start gap-2.5 mt-3 p-3 bg-blue-50/40 border border-blue-100 rounded-lg text-[11px] text-blue-900 font-light leading-relaxed max-w-2xl">
            <AlertCircle className="w-4 h-4 text-blue-700 shrink-0 mt-0.5" />
            <p>
              These documents represent a <strong>customary lender package</strong> and are not absolute mandates. 
              You can adjust this checklist by adding or removing items to match your lender's specific requests.
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <div className="text-right">
            <span className="text-xs font-semibold text-pw-black block">{uploadedCount} of {totalCount} Uploaded</span>
            <span className="text-[10px] text-pw-muted block">{completionPct}% Complete</span>
          </div>
          <div className="w-16 bg-gray-200 h-2 rounded-full overflow-hidden border border-gray-300">
            <div className="bg-[#7A9EAA] h-full transition-all" style={{ width: `${completionPct}%` }} />
          </div>
        </div>
      </div>

      {/* Main checklist table */}
      <div className="space-y-3">
        {items.length === 0 ? (
          <div className="p-4 rounded border border-dashed border-pw-border text-center text-xs text-pw-muted font-light">
            No items in the customary package yet.
          </div>
        ) : (
          items.map((item) => {
            const isUploaded = item.status === 'Uploaded';
            const isUploading = uploadingItemId === item.id;

            return (
              <div 
                key={item.id}
                className={`p-3.5 border rounded-lg flex flex-col md:flex-row justify-between items-start md:items-center gap-3 transition-all ${
                  isUploaded 
                    ? 'border-emerald-200 bg-emerald-50/20' 
                    : 'border-pw-border bg-pw-white'
                }`}
              >
                {/* Info block */}
                <div className="flex items-start gap-3 shrink-0 max-w-full md:max-w-[45%]">
                  {isUploaded ? (
                    <CheckCircle2 className="w-5 h-5 text-emerald-600 shrink-0 mt-0.5" />
                  ) : (
                    <div className="w-5 h-5 rounded-full border border-gray-300 flex items-center justify-center shrink-0 mt-0.5">
                      <span className="w-1.5 h-1.5 rounded-full bg-gray-300" />
                    </div>
                  )}
                  <div className="min-w-0">
                    <span className="text-xs font-semibold text-pw-black block truncate">{item.name}</span>
                    {item.isCustom && (
                      <span className="px-1.5 py-0.5 rounded text-[8px] bg-purple-50 text-purple-700 border border-purple-200 uppercase font-black tracking-widest inline-block mt-0.5">
                        Custom
                      </span>
                    )}
                  </div>
                </div>

                {/* Upload Action */}
                <div className="flex items-center gap-3 w-full md:w-auto justify-between md:justify-end">
                  {isUploaded ? (
                    <div className="flex items-center gap-2 bg-emerald-50 border border-emerald-100 rounded px-2.5 py-1 text-xs">
                      <a 
                        href={item.fileUrl || '#'} 
                        target="_blank" 
                        rel="noopener noreferrer" 
                        className="text-emerald-800 hover:text-emerald-950 font-medium underline flex items-center gap-1 max-w-[120px] truncate"
                      >
                        {item.fileName}
                        <ExternalLink className="w-3 h-3" />
                      </a>
                      <button 
                        onClick={() => handleClearFile(item.id)}
                        className="text-emerald-700 hover:text-red-600 ml-1"
                        title="Remove file link"
                      >
                        <X className="w-3.5 h-3.5" />
                      </button>
                    </div>
                  ) : (
                    <div className="relative">
                      <input 
                        type="file"
                        accept="application/pdf"
                        onChange={(e) => handleFileUpload(item.id, e)}
                        className="hidden"
                        id={`file-upload-${item.id}`}
                        disabled={!!uploadingItemId}
                      />
                      <label 
                        htmlFor={`file-upload-${item.id}`}
                        className={`pw-interactive px-3 py-1.5 border border-pw-border text-[10px] font-bold uppercase tracking-wider bg-pw-white text-pw-black hover:bg-gray-50 flex items-center gap-1.5 rounded cursor-pointer transition-all ${
                          isUploading || uploadingItemId ? 'opacity-50 cursor-not-allowed' : ''
                        }`}
                      >
                        {isUploading ? (
                          <Loader2 className="w-3 h-3 animate-spin text-[#7A9EAA]" />
                        ) : (
                          <Upload className="w-3 h-3 text-pw-muted" />
                        )}
                        {isUploading ? 'Uploading...' : 'Upload PDF'}
                      </label>
                    </div>
                  )}

                  {/* Reminder Cadence */}
                  <div className="flex items-center gap-1.5">
                    <Clock className="w-3.5 h-3.5 text-pw-muted" />
                    <select 
                      value={item.reminderCadence}
                      onChange={(e) => handleUpdateCadence(item.id, e.target.value as any)}
                      className="bg-transparent border-0 text-[11px] text-pw-muted hover:text-pw-black font-light focus:ring-0 cursor-pointer outline-none"
                    >
                      <option value="none">No reminder</option>
                      <option value="daily">Daily reminder</option>
                      <option value="weekly">Weekly reminder</option>
                    </select>
                  </div>

                  {/* Delete Item */}
                  <button 
                    onClick={() => handleDeleteItem(item.id, item.name)}
                    className="text-pw-muted hover:text-red-600 transition-colors p-1"
                    title="Delete item"
                  >
                    <Trash2 className="w-4.5 h-4.5" />
                  </button>
                </div>
              </div>
            );
          })
        )}
      </div>

      {/* Add Custom Item Form */}
      <form onSubmit={handleAddCustomItem} className="border-t border-pw-border pt-4 flex gap-3">
        <input 
          type="text"
          placeholder="Add custom lender document ask (e.g. Credit Memo)..."
          value={newItemName}
          onChange={(e) => setNewItemName(e.target.value)}
          className="flex-1 bg-pw-bg border border-pw-border focus:border-[#7A9EAA] focus:ring-0 rounded-lg px-3 py-2 text-xs placeholder:text-pw-muted placeholder:font-light outline-none"
          disabled={addingItem}
        />
        <button 
          type="submit"
          disabled={!newItemName.trim() || addingItem}
          className={`pw-interactive px-4 py-2 text-xs font-semibold uppercase tracking-wider text-pw-white flex items-center gap-1 transition-all ${
            newItemName.trim() && !addingItem 
              ? 'bg-[#7A9EAA] hover:bg-[#688a95] shadow-sm' 
              : 'bg-gray-300 cursor-not-allowed'
          }`}
        >
          {addingItem ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Plus className="w-3.5 h-3.5" />}
          Add Item
        </button>
      </form>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { getAuth } from 'firebase/auth';
import { collection, onSnapshot, query, orderBy } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { calculateAmortization } from '@/lib/utils/reiCalculators';
import type { LoanEstimateCandidate, LoanRecord } from '@/types/schema';
import { 
  FileText,
  Upload,
  CheckCircle,
  Eye,
  Trash2,
  Check,
  Loader2,
  ArrowRight,
  TrendingDown,
  Info,
  DollarSign,
  Percent,
  Calendar,
  X
} from 'lucide-react';
import toast from 'react-hot-toast';

function SourceTagBadge({ source }: { source?: 'document' | 'manual' }) {
  if (source === 'document') {
    return (
      <span className="inline-flex items-center text-[9px] font-bold text-sky-600 bg-sky-50 border border-sky-100 px-1 rounded ml-1 uppercase font-sans select-none shrink-0" title="Source: Uploaded Document">
        DOC
      </span>
    );
  }
  return (
    <span className="inline-flex items-center text-[9px] font-bold text-amber-600 bg-amber-50 border border-amber-100 px-1 rounded ml-1 uppercase font-sans select-none shrink-0" title="Source: Manually Sourced">
      MANUAL
    </span>
  );
}

interface Props {
  projectId: string;
}

export function LoanEstimatesWorkflow({ projectId }: Props) {
  const [estimates, setEstimates] = useState<LoanEstimateCandidate[]>([]);
  const [loans, setLoans] = useState<LoanRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [submitting, setSubmitting] = useState(false);

  // Capture State (for Split-View Capture)
  const [captureDoc, setCaptureDoc] = useState<{
    fileId: string;
    fileName: string;
    fileUrl: string;
  } | null>(null);

  // Capture Form Inputs
  const [lenderName, setLenderName] = useState('');
  const [amount, setAmount] = useState('');
  const [rate, setRate] = useState('');
  const [termMonths, setTermMonths] = useState('360');
  const [points, setPoints] = useState('0');
  const [estimatedCosts, setEstimatedCosts] = useState('0');
  const [selectedLoanId, setSelectedLoanId] = useState('');

  // 1. Listen to active loans
  useEffect(() => {
    if (!projectId) return;

    // Check for E2E testing mock
    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_loans_${projectId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          setLoans(val ? JSON.parse(val) : []);
        } catch (e) {}
      };
      load();
      window.addEventListener('storage', (e) => {
        if (e.key === key) load();
      });
      return;
    }

    const unsub = onSnapshot(
      collection(db, 'projects', projectId, 'loans'),
      (snap) => {
        const docs = snap.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        })) as LoanRecord[];
        setLoans(docs);
        if (docs.length > 0) {
          setSelectedLoanId(docs[0].id);
        }
      }
    );
    return unsub;
  }, [projectId]);

  // 2. Listen to estimate candidates
  useEffect(() => {
    if (!projectId) return;

    // Check for E2E testing mock
    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_loan_estimates_${projectId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          setEstimates(val ? JSON.parse(val) : []);
          setLoading(false);
        } catch (e) {}
      };
      load();
      window.addEventListener('storage', (e) => {
        if (e.key === key) load();
      });
      return;
    }

    const q = query(
      collection(db, 'projects', projectId, 'loanEstimates'),
      orderBy('createdAt', 'asc')
    );

    const unsub = onSnapshot(
      q,
      (snap) => {
        const docs = snap.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        })) as LoanEstimateCandidate[];
        setEstimates(docs);
        setLoading(false);
      },
      (err) => {
        console.error('onSnapshot estimates error:', err);
        setLoading(false);
      }
    );
    return unsub;
  }, [projectId]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('Only PDF documents are allowed.');
      return;
    }

    setUploading(true);
    const toastId = toast.loading('Uploading Loan Estimate PDF...');

    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      // 1. Ensure Debt folder exists
      const folderRes = await fetch(`/api/projects/${projectId}/lender-package/debt-folder`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!folderRes.ok) {
        throw new Error('Failed to provision Debt folder in the Project Files.');
      }
      const { folderId } = await folderRes.json();

      // 2. Upload the file to documents endpoint
      const formData = new FormData();
      formData.append('file', file);
      formData.append('folderId', folderId);
      formData.append('category', 'Other');
      formData.append('documentType', 'closing_disclosure');

      const uploadRes = await fetch(`/api/projects/${projectId}/documents`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
        body: formData,
      });

      if (!uploadRes.ok) {
        const errData = await uploadRes.json();
        throw new Error(errData.error || 'Document upload failed.');
      }

      const { docId, downloadUrl } = await uploadRes.json();

      // Set to Capture State to trigger Split View
      setCaptureDoc({
        fileId: docId,
        fileName: file.name,
        fileUrl: downloadUrl,
      });

      toast.success('Document uploaded. Proceeding to split-view parameter capture.', { id: toastId });
    } catch (err: any) {
      toast.error(err.message || 'Error uploading document.', { id: toastId });
    } finally {
      setUploading(false);
      if (e.target) e.target.value = '';
    }
  };

  const handleSaveEstimate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!lenderName.trim()) {
      toast.error('Lender name is required.');
      return;
    }
    const parsedAmount = parseFloat(amount.replace(/[^0-9.]/g, ''));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      toast.error('Please enter a valid loan amount.');
      return;
    }
    const parsedRate = parseFloat(rate);
    if (isNaN(parsedRate) || parsedRate < 0) {
      toast.error('Please enter a valid interest rate.');
      return;
    }

    setSubmitting(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const payload = {
        lenderName: lenderName.trim(),
        amountCents: Math.round(parsedAmount * 100),
        interestRate: parsedRate,
        termMonths: parseInt(termMonths, 10),
        points: parseFloat(points) || 0,
        estimatedCostsCents: Math.round((parseFloat(estimatedCosts) || 0) * 100),
        fileId: captureDoc?.fileId || null,
        fileName: captureDoc?.fileName || null,
        fileUrl: captureDoc?.fileUrl || null,
        loanRecordId: selectedLoanId || null,
      };

      const res = await fetch(`/api/projects/${projectId}/loan-estimates`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to save estimate candidate.');
      }

      // Reset form states
      setLenderName('');
      setAmount('');
      setRate('');
      setTermMonths('360');
      setPoints('0');
      setEstimatedCosts('0');
      setCaptureDoc(null);

      toast.success('Loan estimate candidate successfully saved.');
    } catch (err: any) {
      toast.error(err.message || 'Error saving estimate candidate.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleChooseLoan = async (estimateId: string, lender: string) => {
    setSubmitting(true);
    const toastId = toast.loading(`Committing choice of ${lender} loan estimate...`);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/loan-estimates/${estimateId}/choose`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to select estimate.');
      }

      toast.success(`${lender} chosen as active loan route.`, { id: toastId });
    } catch (err: any) {
      toast.error(err.message || 'Error choosing loan estimate.', { id: toastId });
    } finally {
      setSubmitting(false);
    }
  };

  const handleDeleteEstimate = async (estimateId: string) => {
    if (!window.confirm('Delete this estimate candidate?')) return;

    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/loan-estimates/${estimateId}`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to delete estimate.');
      }

      toast.success('Estimate candidate removed.');
    } catch (err: any) {
      toast.error(err.message || 'Error deleting candidate.');
    }
  };

  if (loading) {
    return (
      <div className="glass-card p-6 flex flex-col items-center justify-center min-h-[150px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#7A9EAA] mb-2" />
        <span className="text-xs text-pw-muted font-light uppercase tracking-wider">Loading Loan Estimates...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* ── SPLIT-VIEW CAPTURE ── */}
      {captureDoc && (
        <div className="glass-card p-6 border border-[#7A9EAA]/40 bg-[#7A9EAA]/5 animate-in slide-in-from-top duration-300">
          <div className="flex justify-between items-center border-b border-pw-border pb-3 mb-4">
            <h4 className="text-sm font-black uppercase tracking-widest text-[#7A9EAA] flex items-center gap-2">
              <Eye className="w-4 h-4" />
              Split-View Capture: {captureDoc.fileName}
            </h4>
            <button 
              onClick={() => setCaptureDoc(null)}
              className="p-1 hover:bg-gray-100 rounded transition-all"
            >
              <X className="w-4 h-4 text-pw-muted" />
            </button>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6 h-[450px]">
            {/* Left Column: PDF Viewer */}
            <div className="border border-pw-border rounded overflow-hidden bg-pw-bg flex items-center justify-center h-full">
              <iframe 
                src={captureDoc.fileUrl} 
                className="w-full h-full" 
                title="Loan Estimate PDF"
              />
            </div>

            {/* Right Column: Capture Form */}
            <form onSubmit={handleSaveEstimate} className="flex flex-col justify-between h-full overflow-y-auto pr-1">
              <div className="space-y-3.5">
                <div className="p-3 bg-blue-50/50 border border-blue-100 rounded text-[11px] text-blue-900 leading-relaxed">
                  <span className="font-semibold block mb-0.5">Source-Tagged Upload</span>
                  Values captured below will be permanently tagged to this document. Use the PDF on the left to extract the details.
                </div>

                {loans.length > 1 && (
                  <div>
                    <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Target Active Loan</label>
                    <select 
                      value={selectedLoanId}
                      onChange={(e) => setSelectedLoanId(e.target.value)}
                      className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded p-2 text-xs outline-none"
                    >
                      {loans.map((l) => (
                        <option key={l.id} value={l.id}>{l.lenderName || l.instrument}</option>
                      ))}
                    </select>
                  </div>
                )}

                <div>
                  <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Lender Name</label>
                  <input 
                    type="text"
                    required
                    placeholder="e.g. Chase Commercial"
                    value={lenderName}
                    onChange={(e) => setLenderName(e.target.value)}
                    className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded p-2 text-xs outline-none"
                  />
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Loan Amount ($)</label>
                    <div className="relative">
                      <DollarSign className="absolute left-2.5 top-2.5 w-3.5 h-3.5 text-pw-muted" />
                      <input 
                        type="text"
                        required
                        placeholder="250,000"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                        className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded pl-8 pr-2.5 py-2 text-xs outline-none"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Interest Rate (%)</label>
                    <div className="relative">
                      <Percent className="absolute right-2.5 top-2.5 w-3.5 h-3.5 text-pw-muted" />
                      <input 
                        type="number"
                        step="0.001"
                        required
                        placeholder="6.5"
                        value={rate}
                        onChange={(e) => setRate(e.target.value)}
                        className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded pl-2.5 pr-8 py-2 text-xs outline-none"
                      />
                    </div>
                  </div>
                </div>

                <div className="grid grid-cols-3 gap-3">
                  <div>
                    <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Term (Months)</label>
                    <input 
                      type="number"
                      required
                      value={termMonths}
                      onChange={(e) => setTermMonths(e.target.value)}
                      className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded p-2 text-xs outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Orig. Points (%)</label>
                    <input 
                      type="number"
                      step="0.1"
                      value={points}
                      onChange={(e) => setPoints(e.target.value)}
                      className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded p-2 text-xs outline-none"
                    />
                  </div>
                  <div>
                    <label className="text-[10px] uppercase font-bold text-pw-muted block mb-1">Est. Costs ($)</label>
                    <input 
                      type="number"
                      value={estimatedCosts}
                      onChange={(e) => setEstimatedCosts(e.target.value)}
                      className="w-full bg-pw-white border border-pw-border focus:border-[#7A9EAA] rounded p-2 text-xs outline-none"
                    />
                  </div>
                </div>
              </div>

              <div className="flex justify-end gap-3 pt-4 border-t border-pw-border mt-4">
                <button 
                  type="button"
                  onClick={() => setCaptureDoc(null)}
                  className="px-4 py-2 border border-pw-border text-xs font-semibold uppercase tracking-wider text-pw-black hover:bg-gray-50 rounded"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  disabled={submitting}
                  className="px-4 py-2 bg-[#7A9EAA] hover:bg-[#688a95] text-xs font-semibold uppercase tracking-wider text-pw-white flex items-center gap-1.5 rounded transition-all shadow-sm"
                >
                  {submitting && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
                  Save Estimate Candidate
                  <ArrowRight className="w-3.5 h-3.5" />
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* ── DASHBOARD & COMPARISON ── */}
      <div className="glass-card p-6 space-y-6">
        <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center border-b border-pw-border pb-4 gap-4">
          <div>
            <h3 className="text-lg font-light uppercase tracking-widest text-pw-black flex items-center gap-2.5">
              <FileText className="w-5 h-5 text-[#7A9EAA]" />
              Loan Estimate Comparisons
            </h3>
            <p className="text-xs text-pw-muted font-light mt-1">
              Upload multiple estimates, evaluate their mathematical terms side-by-side, and commit the chosen structure.
            </p>
          </div>

          <div className="relative shrink-0">
            <input 
              type="file"
              accept="application/pdf"
              onChange={handleFileUpload}
              className="hidden"
              id="estimates-file-upload"
              disabled={uploading || !!captureDoc}
            />
            <label 
              htmlFor="estimates-file-upload"
              className={`pw-interactive px-4 py-2 bg-[#7A9EAA] hover:bg-[#688a95] text-xs font-semibold uppercase tracking-wider text-pw-white flex items-center gap-1.5 rounded cursor-pointer transition-all ${
                uploading || captureDoc ? 'opacity-50 cursor-not-allowed bg-gray-300' : 'shadow-sm'
              }`}
            >
              {uploading ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <Upload className="w-3.5 h-3.5" />
              )}
              Upload Loan Estimate
            </label>
          </div>
        </div>

        {/* Side-by-side Comparison Matrix */}
        {estimates.length === 0 ? (
          <div className="p-8 rounded border border-dashed border-pw-border text-center text-xs text-pw-muted font-light">
            No estimate candidates uploaded yet. Select "Upload Loan Estimate" to start.
          </div>
        ) : (
          <div className="overflow-x-auto border border-pw-border rounded-xl bg-pw-white shadow-sm">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-pw-border">
                  <th className="p-4 text-xs font-bold uppercase tracking-wider text-pw-muted w-[200px]">Parameter</th>
                  {estimates.map((est) => (
                    <th key={est.id} className={`p-4 text-xs font-bold uppercase tracking-wider text-pw-black min-w-[220px] border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                      <div className="flex justify-between items-start gap-2">
                        <div>
                          <div className="text-sm font-black text-pw-black flex items-center gap-1">
                            {est.lenderName}
                            <SourceTagBadge source={est.sourceTags?.lenderName || (est.fileId ? 'document' : 'manual')} />
                          </div>
                          {est.isChosen && (
                            <span className="inline-block mt-1 px-1.5 py-0.5 rounded text-[8px] bg-emerald-50 text-emerald-700 border border-emerald-200 font-bold uppercase tracking-wider">
                              Active Choice
                            </span>
                          )}
                        </div>
                        <button 
                          onClick={() => handleDeleteEstimate(est.id)}
                          disabled={submitting}
                          className="text-pw-muted hover:text-red-600 transition-colors p-1"
                          title="Delete estimate"
                        >
                          <Trash2 className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                <tr className="border-b border-pw-border hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-medium text-pw-muted">Loan Amount</td>
                  {estimates.map((est) => {
                    const val = est.amountCents / 100;
                    return (
                      <td key={est.id} className={`p-4 text-xs font-semibold text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                        ${val.toLocaleString()}
                        <SourceTagBadge source={est.sourceTags?.amountCents || (est.fileId ? 'document' : 'manual')} />
                      </td>
                    );
                  })}
                </tr>

                <tr className="border-b border-pw-border hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-medium text-pw-muted">Interest Rate</td>
                  {estimates.map((est) => (
                    <td key={est.id} className={`p-4 text-xs font-semibold text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                      {est.interestRate.toFixed(3)}%
                      <SourceTagBadge source={est.sourceTags?.interestRate || (est.fileId ? 'document' : 'manual')} />
                    </td>
                  ))}
                </tr>

                <tr className="border-b border-pw-border hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-medium text-pw-muted">Term (Months)</td>
                  {estimates.map((est) => (
                    <td key={est.id} className={`p-4 text-xs text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                      {est.termMonths} Mo ({Math.round(est.termMonths / 12)} Yr)
                      <SourceTagBadge source={est.sourceTags?.termMonths || (est.fileId ? 'document' : 'manual')} />
                    </td>
                  ))}
                </tr>

                <tr className="border-b border-pw-border hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-medium text-pw-muted">Origination Points</td>
                  {estimates.map((est) => {
                    const ptsVal = ((est.amountCents / 100) * est.points) / 100;
                    return (
                      <td key={est.id} className={`p-4 text-xs text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                        {est.points.toFixed(1)}% (${ptsVal.toLocaleString()})
                        <SourceTagBadge source={est.sourceTags?.points || (est.fileId ? 'document' : 'manual')} />
                      </td>
                    );
                  })}
                </tr>

                <tr className="border-b border-pw-border hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-medium text-pw-muted">Estimated Closing Costs</td>
                  {estimates.map((est) => {
                    const val = est.estimatedCostsCents / 100;
                    return (
                      <td key={est.id} className={`p-4 text-xs text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                        ${val.toLocaleString()}
                        <SourceTagBadge source={est.sourceTags?.estimatedCostsCents || (est.fileId ? 'document' : 'manual')} />
                      </td>
                    );
                  })}
                </tr>

                <tr className="border-b border-pw-border bg-gray-50/30 hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-bold text-pw-black">Implied Monthly Payment (P&I)</td>
                  {estimates.map((est) => {
                    const loanAmt = est.amountCents / 100;
                    const amortResult = calculateAmortization(loanAmt, est.interestRate, est.termMonths);
                    return (
                      <td key={est.id} className={`p-4 text-xs font-black text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                        ${Math.round(amortResult.monthlyPayment).toLocaleString()}
                        <span className="text-[9px] text-pw-muted font-normal block mt-0.5">calculated</span>
                      </td>
                    );
                  })}
                </tr>

                <tr className="border-b border-pw-border bg-gray-50/30 hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-bold text-pw-black">Implied Annual Debt Service</td>
                  {estimates.map((est) => {
                    const loanAmt = est.amountCents / 100;
                    const amortResult = calculateAmortization(loanAmt, est.interestRate, est.termMonths);
                    return (
                      <td key={est.id} className={`p-4 text-xs font-black text-[#7A9EAA] border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                        ${Math.round(amortResult.annualDebtService).toLocaleString()}
                        <span className="text-[9px] text-pw-muted font-normal block mt-0.5">calculated</span>
                      </td>
                    );
                  })}
                </tr>

                <tr className="border-b border-pw-border hover:bg-gray-50/50">
                  <td className="p-4 text-xs font-medium text-pw-muted">Source Document</td>
                  {estimates.map((est) => (
                    <td key={est.id} className={`p-4 text-xs text-pw-black border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                      {est.fileName ? (
                        <a 
                          href={est.fileUrl || '#'} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="text-[#7A9EAA] hover:underline flex items-center gap-1 mt-0.5 min-w-0"
                        >
                          <FileText className="w-3.5 h-3.5 text-[#7A9EAA] shrink-0" />
                          <span className="truncate max-w-[150px]">{est.fileName}</span>
                        </a>
                      ) : (
                        <span className="text-pw-muted italic">Manual Sourced</span>
                      )}
                    </td>
                  ))}
                </tr>

                <tr>
                  <td className="p-4 text-xs font-medium text-pw-muted">Action</td>
                  {estimates.map((est) => (
                    <td key={est.id} className={`p-4 text-xs border-l border-pw-border ${est.isChosen ? 'bg-[#7A9EAA]/5' : ''}`}>
                      {est.isChosen ? (
                        <div className="inline-flex px-3 py-1.5 bg-[#ECFDF5] text-[#047857] border border-[#A7F3D0] rounded text-[10px] font-bold uppercase tracking-wider items-center gap-1">
                          <Check className="w-3.5 h-3.5" />
                          Promoted
                        </div>
                      ) : (
                        <button 
                          onClick={() => handleChooseLoan(est.id, est.lenderName)}
                          disabled={submitting}
                          className="pw-interactive px-3 py-1.5 bg-[#7A9EAA] hover:bg-[#688a95] text-pw-white text-[10px] font-bold uppercase tracking-wider rounded transition-all shadow-sm"
                        >
                          Choose This Loan
                        </button>
                      )}
                    </td>
                  ))}
                </tr>
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { getAuth } from 'firebase/auth';
import { collection, onSnapshot, doc } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import type { LoanStatus, LoanRecord } from '@/types/schema';
import { 
  Check, 
  Loader2, 
  AlertCircle, 
  FileText, 
  Upload, 
  ExternalLink,
  DollarSign,
  TrendingDown,
  Building,
  CheckCircle2
} from 'lucide-react';
import toast from 'react-hot-toast';

interface Props {
  projectId: string;
}

const STATUSES: { id: LoanStatus; label: string; desc: string }[] = [
  { id: 'Application-Submitted', label: 'Application Submitted', desc: 'Loan application package sent to the lender.' },
  { id: 'Processing', label: 'Processing', desc: 'Lender processor reviews file and gathers credit logs.' },
  { id: 'Appraisal-Ordered', label: 'Appraisal Ordered', desc: 'Appraisal scheduled to confirm value of target asset.' },
  { id: 'Appraisal-Received', label: 'Appraisal Received', desc: 'Appraisal document received and asset LTV calculated.' },
  { id: 'Conditions-Issued', label: 'Conditions Issued', desc: 'Underwriter issues list of prior-to-doc checklist requirements.' },
  { id: 'Conditions-Cleared', label: 'Conditions Cleared', desc: 'All conditional underwriting requests resolved and approved.' },
  { id: 'Clear-To-Close', label: 'Clear to Close', desc: 'Final underwriting sign-off. Loan is ready to fund.' }
];

export function LoanProcessingPipeline({ projectId }: Props) {
  const [loans, setLoans] = useState<LoanRecord[]>([]);
  const [activeLoanId, setActiveLoanId] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [submitting, setSubmitting] = useState(false);

  // Unified Milestone Transition Modal States
  const [pendingTransitionStatus, setPendingTransitionStatus] = useState<LoanStatus | null>(null);
  const [transitionNote, setTransitionNote] = useState('');
  const [appraisedValue, setAppraisedValue] = useState('');
  const [uploadedFile, setUploadedFile] = useState<{ id: string; name: string; url: string } | null>(null);
  const [uploadingFile, setUploadingFile] = useState(false);
  const [transitionLog, setTransitionLog] = useState<any[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // 1. Listen to loans
  useEffect(() => {
    if (!projectId) return;

    // Check for E2E testing mock
    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_loans_${projectId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          const docs = val ? JSON.parse(val) : [];
          setLoans(docs);
          if (docs.length > 0 && !activeLoanId) {
            setActiveLoanId(docs[0].id);
          }
          setLoading(false);
        } catch (e) {}
      };
      load();
      window.addEventListener('storage', (e) => {
        if (e.key === key) load();
      });
      return;
    }

    const unsub = onSnapshot(
      collection(db, 'projects', projectId, 'loans'),
      (snap) => {
        const docs = snap.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        })) as LoanRecord[];
        setLoans(docs);
        if (docs.length > 0 && !activeLoanId) {
          setActiveLoanId(docs[0].id);
        }
        setLoading(false);
      },
      (err) => {
        console.error('onSnapshot loans error:', err);
        setLoading(false);
      }
    );
    return unsub;
  }, [projectId, activeLoanId]);

  // 2. Listen to transitions log
  useEffect(() => {
    if (!projectId || !activeLoanId) return;

    // Check for E2E testing mock
    if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
      const key = `pw_e2e_loan_transitions_${activeLoanId}`;
      const load = () => {
        try {
          const val = localStorage.getItem(key);
          setTransitionLog(val ? JSON.parse(val) : []);
        } catch (e) {}
      };
      load();
      window.addEventListener('storage', (e) => {
        if (e.key === key) load();
      });
      return;
    }

    const unsub = onSnapshot(
      collection(db, 'projects', projectId, 'loans', activeLoanId, 'transitions'),
      (snap) => {
        const docs = snap.docs.map((d) => ({
          id: d.id,
          ...d.data(),
        })).sort((a: any, b: any) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
        setTransitionLog(docs);
      },
      (err) => {
        console.error('onSnapshot transitions error:', err);
      }
    );
    return unsub;
  }, [projectId, activeLoanId]);

  const activeLoan = loans.find((l) => l.id === activeLoanId);

  const handleStatusChange = (targetStatus: LoanStatus) => {
    if (!activeLoanId || !activeLoan) return;
    setPendingTransitionStatus(targetStatus);
    setTransitionNote('');
    setUploadedFile(null);
    if (targetStatus === 'Appraisal-Received') {
      setAppraisedValue(activeLoan.appraisedValueCents ? (activeLoan.appraisedValueCents / 100).toString() : '');
      if (activeLoan.appraisalFileId && activeLoan.appraisalFileName && activeLoan.appraisalFileUrl) {
        setUploadedFile({
          id: activeLoan.appraisalFileId,
          name: activeLoan.appraisalFileName,
          url: activeLoan.appraisalFileUrl
        });
      }
    } else {
      if (activeLoan.fileId && activeLoan.fileName && activeLoan.fileUrl) {
        setUploadedFile({
          id: activeLoan.fileId,
          name: activeLoan.fileName,
          url: activeLoan.fileUrl
        });
      }
    }
  };

  const submitStatusChange = async (targetStatus: LoanStatus, extraData: any = {}) => {
    setSubmitting(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      const res = await fetch(`/api/projects/${projectId}/loans/${activeLoanId}`, {
        method: 'PATCH',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${idToken}`,
        },
        body: JSON.stringify({
          status: targetStatus,
          ...extraData
        }),
      });

      if (!res.ok) {
        const errData = await res.json();
        throw new Error(errData.error || 'Failed to update milestone.');
      }

      toast.success(`Milestone updated: ${targetStatus.replace(/-/g, ' ')}`);
      setPendingTransitionStatus(null);
    } catch (err: any) {
      toast.error(err.message || 'Error updating milestone.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) {
      toast.error('Only PDF documents are allowed.');
      return;
    }

    setUploadingFile(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication token required.');

      // 1. Ensure Debt folder exists
      const folderRes = await fetch(`/api/projects/${projectId}/lender-package/debt-folder`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
      });

      if (!folderRes.ok) throw new Error('Failed to ensure Debt folder.');
      const { folderId } = await folderRes.json();

      // 2. Upload document
      const formData = new FormData();
      formData.append('file', file);
      formData.append('folderId', folderId);
      formData.append('category', 'Debt');
      formData.append('documentType', 'closing_disclosure');

      const uploadRes = await fetch(`/api/projects/${projectId}/documents`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${idToken}`,
        },
        body: formData,
      });

      if (!uploadRes.ok) {
        const errData = await uploadRes.json();
        throw new Error(errData.error || 'Upload failed.');
      }

      const { docId, downloadUrl } = await uploadRes.json();
      setUploadedFile({
        id: docId,
        name: file.name,
        url: downloadUrl
      });
      toast.success('Document uploaded successfully.');
    } catch (err: any) {
      toast.error(err.message || 'Error uploading document.');
    } finally {
      setUploadingFile(false);
    }
  };

  const handleSaveMilestone = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!pendingTransitionStatus) return;

    const payload: any = {
      note: transitionNote.trim() || null
    };

    if (pendingTransitionStatus === 'Appraisal-Received') {
      const val = parseFloat(appraisedValue.replace(/[^0-9.]/g, ''));
      if (isNaN(val) || val <= 0) {
        toast.error('Please enter a valid appraised asset value.');
        return;
      }
      payload.appraisedValueCents = Math.round(val * 100);
      if (uploadedFile) {
        payload.appraisalFileId = uploadedFile.id;
        payload.appraisalFileName = uploadedFile.name;
        payload.appraisalFileUrl = uploadedFile.url;
      }
    } else {
      if (uploadedFile) {
        payload.fileId = uploadedFile.id;
        payload.fileName = uploadedFile.name;
        payload.fileUrl = uploadedFile.url;
      }
    }

    await submitStatusChange(pendingTransitionStatus, payload);
  };

  if (loading) {
    return (
      <div className="glass-card p-6 flex flex-col items-center justify-center min-h-[150px]">
        <Loader2 className="w-8 h-8 animate-spin text-[#7A9EAA] mb-2" />
        <span className="text-xs text-pw-muted font-light uppercase tracking-wider">Loading Milestones...</span>
      </div>
    );
  }

  if (loans.length === 0) {
    return (
      <div className="glass-card p-6 text-center text-xs text-pw-muted font-light border border-dashed border-pw-border">
        Configure a financing route to initialize underwriting milestones.
      </div>
    );
  }

  const activeIndex = activeLoan ? STATUSES.findIndex((s) => s.id === activeLoan.status) : -1;

  return (
    <div className="glass-card p-6 space-y-6">
      {/* Selector for multi-loans */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center border-b border-pw-border pb-4 gap-4">
        <div>
          <h3 className="text-lg font-light uppercase tracking-widest text-pw-black flex items-center gap-2.5">
            <Building className="w-5 h-5 text-[#7A9EAA]" />
            Underwriting Milestones
          </h3>
          <p className="text-xs text-pw-muted font-light mt-1">
            Track and log the underwriting pipeline steps for each configured project debt instrument.
          </p>
        </div>

        {loans.length > 1 && (
          <div className="flex gap-2 bg-gray-50 border border-pw-border p-1 rounded-lg">
            {loans.map((l) => (
              <button 
                key={l.id}
                onClick={() => setActiveLoanId(l.id)}
                className={`px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider transition-all rounded ${
                  activeLoanId === l.id 
                    ? 'bg-[#7A9EAA] text-pw-white shadow-sm' 
                    : 'text-pw-muted hover:text-pw-black hover:bg-gray-100'
                }`}
              >
                {l.lenderName || l.instrument}
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main milestones list */}
      <div className="relative pl-8 space-y-6">
        {/* Connecting Line */}
        <div className="absolute left-[15px] top-3 bottom-3 w-0.5 bg-gray-200" />

        {STATUSES.map((status, index) => {
          const isCompleted = index <= activeIndex;
          const isCurrent = index === activeIndex;

          return (
            <div 
              key={status.id}
              onClick={() => handleStatusChange(status.id)}
              className="relative flex gap-4 cursor-pointer group"
            >
              {/* Check Circle Indicator */}
              <div 
                className={`absolute -left-8 w-8 h-8 rounded-full border-2 flex items-center justify-center transition-all ${
                  isCompleted 
                    ? 'bg-[#7A9EAA] border-[#7A9EAA] text-pw-white' 
                    : 'bg-pw-white border-gray-300 text-gray-300 hover:border-[#7A9EAA]'
                }`}
              >
                {isCompleted ? (
                  <Check className="w-4.5 h-4.5 stroke-[3px]" />
                ) : (
                  <span className="text-[11px] font-bold">{index + 1}</span>
                )}
              </div>

              {/* Status details */}
              <div className="flex-1 min-w-0 pr-4">
                <div className="flex justify-between items-start">
                  <h4 className={`text-xs uppercase tracking-widest font-black transition-colors ${
                    isCurrent 
                      ? 'text-pw-black' 
                      : isCompleted 
                        ? 'text-pw-muted' 
                        : 'text-gray-400 group-hover:text-pw-black'
                  }`}>
                    {status.label}
                  </h4>
                  {isCurrent && (
                    <span className="px-2 py-0.5 rounded text-[8px] bg-blue-50 text-blue-700 border border-blue-200 uppercase font-black tracking-widest">
                      Active Step
                    </span>
                  )}
                </div>
                <p className="text-[11px] text-pw-muted font-light mt-0.5 leading-relaxed">
                  {status.desc}
                </p>

                {/* Appraisal Details inside Step block */}
                {status.id === 'Appraisal-Received' && activeLoan?.appraisedValueCents && (
                  <div className="mt-3 p-3 bg-gray-50 border border-pw-border rounded-lg max-w-md flex flex-col gap-2">
                    <div className="flex justify-between text-xs text-pw-black">
                      <span className="font-light">Appraised Asset Value</span>
                      <strong className="font-bold">${(activeLoan.appraisedValueCents / 100).toLocaleString()}</strong>
                    </div>
                    {activeLoan.ltvPercent && (
                      <div className="flex justify-between text-xs text-pw-black">
                        <span className="font-light">Calculated LTV Ratio</span>
                        <strong className="font-bold text-[#7A9EAA]">{activeLoan.ltvPercent.toFixed(2)}%</strong>
                      </div>
                    )}
                    {activeLoan.fileUrl && (
                      <div className="flex items-center gap-1.5 text-[10px] text-pw-muted font-light pt-1 border-t border-gray-200">
                        <FileText className="w-3.5 h-3.5 text-[#7A9EAA]" />
                        <a 
                          href={activeLoan.fileUrl} 
                          target="_blank" 
                          rel="noopener noreferrer" 
                          className="hover:underline flex items-center gap-0.5"
                        >
                          {activeLoan.appraisalFileName}
                          <ExternalLink className="w-2.5 h-2.5" />
                        </a>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── LTV ASSESSMENT ── */}
      {activeLoan && activeLoan.appraisedValueCents && activeLoan.amountCents && (
        <div className="p-4 bg-gray-50 border border-pw-border rounded-xl flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
          <div>
            <span className="text-[10px] uppercase font-bold text-pw-muted block tracking-wider">LTV Assessment</span>
            <div className="flex items-baseline gap-2 mt-1">
              <span className="text-xl font-light text-pw-black">
                {((activeLoan.amountCents / activeLoan.appraisedValueCents) * 100).toFixed(2)}%
              </span>
              <span className="text-xs text-pw-muted font-light">LTV (Live Calculation)</span>
            </div>
          </div>
          <div className="text-left sm:text-right border-l sm:border-l-0 sm:border-r border-pw-border pl-4 sm:pl-0 sm:pr-4">
            <span className="text-[10px] uppercase font-bold text-pw-muted block tracking-wider">Stored Value</span>
            <span className="text-base font-semibold text-[#7A9EAA]">
              {activeLoan.ltvPercent ? `${activeLoan.ltvPercent.toFixed(2)}%` : 'N/A'}
            </span>
          </div>
        </div>
      )}

      {/* ── TRANSITION LOG ── */}
      {transitionLog.length > 0 && (
        <div className="mt-8 pt-6 border-t border-pw-border space-y-4">
          <h4 className="text-xs uppercase font-black tracking-widest text-pw-black">Transition Activity Log</h4>
          <div className="space-y-3">
            {transitionLog.map((log) => (
              <div key={log.id} className="p-3 bg-gray-50 border border-pw-border rounded-lg text-xs space-y-1.5 transition-all hover:bg-gray-100/50">
                <div className="flex flex-col sm:flex-row justify-between text-pw-muted gap-1">
                  <span>
                    <strong className="text-pw-black font-semibold">
                      {log.fromStatus ? log.fromStatus.replace(/-/g, ' ') : 'Start'}
                    </strong>
                    {' → '}
                    <strong className="text-[#7A9EAA] font-bold">
                      {log.toStatus.replace(/-/g, ' ')}
                    </strong>
                  </span>
                  <span className="text-[10px]">
                    {new Date(log.timestamp).toLocaleDateString()} at {new Date(log.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
                {log.note && (
                  <p className="text-pw-black font-light leading-relaxed italic border-l-2 border-gray-300 pl-2 py-0.5 mt-1">
                    "{log.note}"
                  </p>
                )}
                {log.fileName && (
                  <div className="flex items-center gap-1.5 text-[10px] text-pw-muted font-light pt-1 border-t border-gray-200/60">
                    <FileText className="w-3.5 h-3.5 text-[#7A9EAA]" />
                    <a
                      href={log.fileUrl || '#'}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="hover:underline flex items-center gap-0.5 font-medium"
                    >
                      {log.fileName}
                      <ExternalLink className="w-2.5 h-2.5" />
                    </a>
                  </div>
                )}
                <div className="text-[9px] text-pw-muted text-right">
                  Logged by: {log.actor.name}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* ── UNIFIED TRANSITION MODAL ── */}
      {pendingTransitionStatus && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-pw-white border border-pw-border shadow-xl max-w-md w-full rounded-xl overflow-hidden animate-in zoom-in duration-200">
            <div className="flex justify-between items-center bg-[#7A9EAA] px-4 py-3 text-pw-white">
              <h4 className="text-xs uppercase font-black tracking-widest">
                Log Milestone: {pendingTransitionStatus.replace(/-/g, ' ')}
              </h4>
              <button 
                onClick={() => setPendingTransitionStatus(null)}
                className="hover:bg-white/10 p-1 rounded transition-colors"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

