                </div>
                <button
                  type="button"
                  onClick={() => setIsPlaidConnected(!isPlaidConnected)}
                  className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded border transition-colors ${
                    isPlaidConnected 
                      ? 'bg-emerald-500/10 text-emerald-500 border-emerald-500/30' 
