                      .filter(p => p.category === activeCategory)
                      .map(prop => (
                        <div 
                          key={prop.id} 
                          className="p-4 rounded-[8px] border bg-[var(--bg-canvas)] border-[var(--border-ui)] flex flex-col md:flex-row md:items-center justify-between gap-4"
