                            </div>
                          </div>
                        </div>
                      ))
                  ) : (
                    <p className="text-xs text-[var(--text-tertiary)] italic text-center py-4">
                      No pending Plaid proposals for {CATEGORY_META[activeCategory].label}.
                    </p>
                  )}
