                      </div>

                      {/* State buttons */}
                      <div className="flex gap-2">
                        <button
                          onClick={() => toggleContingencyState(c.id, 'isSatisfied')}
                          disabled={readOnly}
                          className={`px-2 py-1 text-[10px] font-bold rounded uppercase tracking-wider transition-all border ${
