                        >
                          Satisfied
                        </button>
                        <button
                          onClick={() => toggleContingencyState(c.id, 'isWaived')}
                          disabled={readOnly}
                          className={`px-2 py-1 text-[10px] font-bold rounded uppercase tracking-wider transition-all border ${
                            c.isWaived
                              ? 'bg-blue-500/20 border-blue-500/40 text-blue-400'
