                            }}
                          >
                            <div className={`w-5 h-5 rounded border-2 flex items-center justify-center shrink-0 mt-0.5 transition-colors ${isSelected ? 'border-[#454955] bg-[#454955]' : 'border-[#9E9DA0]/50'}`}>
