                            </div>
                            <div className="flex flex-col">
                              <span className="text-[14px] leading-[16px] font-semibold tracking-[0.02em] text-[#9E9DA0] mb-1">
                                {opt.label}
                              </span>
                              {opt.description && (
                                <span className="text-[14px] leading-[20px] text-[#9E9DA0]">
                                  {opt.description}
                                </span>
                              )}
                            </div>
                          </button>
