'use client';

import React, { useState, useEffect } from 'react';
import { Project } from '@/types/schema';
import { FileUp, UserPlus, CheckCircle, Circle, MessageSquare, Users, Loader2 } from 'lucide-react';
import { usePermissions } from '@/hooks/usePermissions';
import { useAuth } from '@/context/AuthContext';
import { Todo, DEFAULT_TODOS } from '@/lib/constants/todos';
import { isSubscriptionActive } from '@/lib/stripe/subscription';


export default function ProjectTodoList({ deal, phase = 1 }: { deal: Project, phase?: number }) {

  const [todos, setTodos] = useState<Todo[]>([]);
  const [assigningId, setAssigningId] = useState<string | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const { isLead, canEdit } = usePermissions();
  const { user, profile, loading } = useAuth();

  const isVendor = profile?.role === 'Vendor' || profile?.accountType === 'vendor';
  const hasActiveSub = profile ? isSubscriptionActive(profile) : false;
  const plan = loading ? 'Loading' : (hasActiveSub ? (profile?.subscriptionPlan || 'None') : 'None');
  const isReadOnly = isVendor || plan === 'Vendor Network';

  const showUpgradeBanner = !loading && (profile?.subscriptionPlan === 'None' || !profile?.subscriptionPlan);
  const showInactiveBanner = !loading && (profile?.subscriptionPlan && profile.subscriptionPlan !== 'None') && !hasActiveSub;
  const canComplete = !loading && canEdit && plan !== 'None' && !isReadOnly;
  const canAssign = !loading && isLead && plan !== 'None' && !isReadOnly;

  useEffect(() => {
    const currentTodos = (DEFAULT_TODOS[phase] || []).map(defaultTodo => {
      const savedTodo = deal.actionItems?.find((t: any) => t.id === defaultTodo.id);
      return savedTodo ? { ...defaultTodo, ...savedTodo } : defaultTodo;
    });
    setTodos(currentTodos);
  }, [phase, deal.actionItems]);

  const saveTodosToBackend = async (newTodos: Todo[]) => {
    if (!user) return;
    try {
      setIsSaving(true);
      const idToken = await user.getIdToken();

      const existingOtherPhaseTodos = (deal.actionItems || []).filter(
         (item: any) => !newTodos.find(t => t.id === item.id)
      );
      const allTodos = [...existingOtherPhaseTodos, ...newTodos];

      const res = await fetch('/api/projects/todos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
           idToken,
           projectId: deal.id,
           todos: allTodos
        })
      });

      if (!res.ok) {
        throw new Error('Failed to save action items');
      }
    } catch (err) {
      console.error('Failed to save todos to backend:', err);
    } finally {
      setIsSaving(false);
    }
  };

  const handleAction = async (id: string) => {
    if (!canComplete) return;

    let updatedTodos: Todo[] = [];
    let completedAction = false;
    setTodos(prev => {
      updatedTodos = prev.map(t => {
        if (t.id === id) {
          if (!t.completed) {
            completedAction = true;
          }
          return { ...t, completed: !t.completed };
        }
        return t;
      });
      return updatedTodos;
    });

    await saveTodosToBackend(updatedTodos);

    if (completedAction) {
      try {
        const { useUIStore } = await import('@/store/uiStore');
        useUIStore.getState().triggerSuccessfulAction('task_completed');
      } catch (err) {
        console.error('Failed to trigger task_completed successful action:', err);
      }
    }
  };

  const handleAssign = async (id: string, email: string) => {
    if (!canAssign) return;

    if (plan === 'Individual') {
      const currentUserEmail = profile?.email || user?.email || '';
      if (email !== '' && email !== currentUserEmail) return;
    }

    setIsSaving(true);

    // Handle specific assignment business logic via server action
    if (email !== '') {
      const taskLabel = todos.find(t => t.id === id)?.label || 'A task';
      try {
        const { assignTask } = await import('@/actions/team');
        await assignTask(deal.id, id, email, taskLabel);
      } catch (err) {
        console.error('Failed to assign task via server action:', err);
      }
    }

    let updatedTodos: Todo[] = [];
    setTodos(prev => {
      updatedTodos = prev.map(t => t.id === id ? { ...t, assignee: email, needsReassignment: false } : t);
      return updatedTodos;
    });
    setAssigningId(null);

    await saveTodosToBackend(updatedTodos);
  };

  return (
    <div className="space-y-4 w-full">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-xl font-medium tracking-tight text-text-primary">Action Items</h3>
        {isSaving && <Loader2 className="w-4 h-4 animate-spin text-text-secondary" />}
      </div>

      {showUpgradeBanner && (
        <div className="p-4 border border-pw-border bg-bg-surface text-text-primary flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
          <div>
            <p className="font-semibold text-sm">Upgrade Required</p>
            <p className="text-xs text-text-secondary mt-1">
              You are on the Free plan. Upgrade to assign tasks to team members and complete action items.
            </p>
          </div>
          <a
            href="/pricing"
            className="pw-btn pw-btn--sm pw-btn--primary whitespace-nowrap text-xs text-center font-bold"
          >
            Upgrade Now
          </a>
        </div>
      )}

      {showInactiveBanner && (
        <div className="p-4 border border-pw-border bg-bg-surface text-text-primary flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 mb-4">
          <div>
            <p className="font-semibold text-sm">Subscription Inactive</p>
            <p className="text-xs text-text-secondary mt-1">
              Your subscription is currently inactive or expired. Please update your billing info or reactivate your subscription to manage action items.
            </p>
          </div>
          <a
            href="/pricing"
            className="pw-btn pw-btn--sm pw-btn--primary whitespace-nowrap text-xs text-center font-bold"
          >
            Reactivate Now
          </a>
        </div>
      )}

      <div className="space-y-3">
        {todos.map(todo => (
          <div 
            key={todo.id} 
            className={`flex flex-col sm:flex-row items-start sm:items-center justify-between p-4 border transition-all ${todo.completed ? 'bg-bg-surface/40 border-pw-border' : (todo.needsReassignment ? 'bg-red-500/10 border-red-500' : 'bg-bg-surface border-pw-border')}`}
          >
            <div className="flex items-start gap-4 mb-3 sm:mb-0">
              <button 
                onClick={() => handleAction(todo.id)} 
                className="mt-1" 
                disabled={isSaving || !canComplete}
              >
                {todo.completed ? (
                  <CheckCircle className="w-5 h-5 text-text-primary" />
                ) : (
                  <Circle className="w-5 h-5 text-text-secondary opacity-50" />
                )}
              </button>
              <div>
                <p className={`font-semibold ${todo.completed ? 'text-text-secondary line-through' : 'text-text-primary'}`}>{todo.label}</p>
                <p className="text-sm text-text-secondary mt-1 max-w-md">{todo.description}</p>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
              <button
                onClick={() => handleAction(todo.id)}
                disabled={todo.completed || isSaving || !canComplete}
                className={`pw-btn pw-btn--sm ${todo.completed ? 'pw-btn--ghost text-text-secondary cursor-not-allowed' : 'pw-btn--primary'}`}
              >
                {todo.type === 'upload' && <FileUp className="w-3.5 h-3.5 mr-1.5" />}
                {todo.type === 'delegate' && <UserPlus className="w-3.5 h-3.5 mr-1.5" />}
                {todo.type === 'question' && <MessageSquare className="w-3.5 h-3.5 mr-1.5" />}
                {todo.completed ? 'Completed' : todo.actionText}
              </button>

              {canAssign && !todo.completed && todo.type === 'delegate' && (() => {
                const isMeAllowed = !todo.allowedRoles || 
                  todo.allowedRoles.includes(profile?.role || 'Guest') || 
                  todo.allowedRoles.includes(profile?.orgRole || 'Guest');
                const allowedTeamMembers = deal.projectTeam?.filter(
                  (m) => m.status === 'active' && 
                         m.email !== (profile?.email || user?.email) &&
                         (!todo.allowedRoles || todo.allowedRoles.includes(m.projectRole))
                ) || [];

                return (
                  <div className="mt-4 sm:mt-0 sm:ml-4 flex items-center gap-2">
                    {plan === 'Individual' ? (
                      isMeAllowed ? (
                        <div className="flex items-center gap-2">
                          {todo.assignee && todo.assignee !== (profile?.email || user?.email) && (
                            <span className="text-xs text-text-secondary mr-2 bg-bg-surface/50 px-2 py-1 border border-pw-border">
                              Assigned to: {todo.assignee}
                            </span>
                          )}
                          <button
                            onClick={() => {
                              const currentUserEmail = profile?.email || user?.email || '';
                              handleAssign(todo.id, todo.assignee === currentUserEmail ? '' : currentUserEmail);
                            }}
                            disabled={isSaving}
                            className="pw-btn pw-btn--sm pw-btn--secondary font-bold uppercase tracking-widest text-xs"
                          >
                            {todo.assignee === (profile?.email || user?.email) ? 'Unassign Me' : 'Assign to Me'}
                          </button>
                        </div>
                      ) : (
                        <span className="text-xs text-text-secondary italic">Restricted by Role Matrix</span>
                      )
                    ) : plan === 'Team' ? (
                      assigningId === todo.id ? (
                        <div className="flex items-center gap-2">
                          <input 
                            type="email"
                            placeholder="Enter email..."
                            defaultValue={todo.assignee || ''}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter') {
                                handleAssign(todo.id, e.currentTarget.value);
                              }
                            }}
                            className="pw-input text-xs w-48"
                            disabled={isSaving}
                            list={`team-members-${todo.id}`}
                            id={`assign-input-${todo.id}`}
                          />
                          <datalist id={`team-members-${todo.id}`}>
                            {isMeAllowed && (
                              <option value={profile?.email || user?.email || ''}>Me ({profile?.email || user?.email})</option>
                            )}
                            {allowedTeamMembers.map((m) => (
                              <option key={m.email} value={m.email}>
                                {m.displayName} - {m.projectRole}
                              </option>
                            ))}
                          </datalist>
                          <button 
                            onClick={() => {
                              const input = document.getElementById(`assign-input-${todo.id}`) as HTMLInputElement;
                              if (input) handleAssign(todo.id, input.value);
                            }}
                            disabled={isSaving}
                            className="pw-btn pw-btn--sm pw-btn--primary text-xs font-bold"
                          >
                            Save
                          </button>
                          <button 
                            onClick={() => setAssigningId(null)}
                            className="text-xs text-text-secondary hover:text-text-primary"
                          >
                            Cancel
                          </button>
                        </div>
                      ) : (
                        <button 
                          onClick={() => setAssigningId(todo.id)}
                          disabled={isSaving}
                          className="pw-btn pw-btn--sm pw-btn--secondary font-bold uppercase tracking-widest text-xs flex items-center gap-1.5"
                        >
                          <Users className="w-3.5 h-3.5" />
                          {todo.assignee ? `Assigned: ${todo.assignee}` : 'Assign'}
                        </button>
                      )
                    ) : null}
                  </div>
                );
              })()}

              {(!canAssign || todo.completed || todo.type !== 'delegate') && todo.assignee && (
                 <div className="mt-2 sm:mt-0 sm:ml-4">
                    <span className={`text-xs bg-bg-surface/50 px-2 py-1 border ${todo.needsReassignment ? 'border-red-500 text-red-500' : 'border-pw-border text-text-secondary'}`}>
                      Assigned to: {todo.assignee} {todo.needsReassignment ? '(Needs Reassignment)' : ''}
                    </span>
                 </div>
              )}
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { db } from '@/lib/firebase/config';
import { collection, query, orderBy, onSnapshot } from 'firebase/firestore';
import { useAuth } from '@/context/AuthContext';
import { updateAssignmentStatus } from '@/actions/vendorAssignment';
import { Loader2, Calendar, FileText, CheckCircle2, Clock, XCircle, AlertTriangle, ArrowUpRight } from 'lucide-react';
import toast from 'react-hot-toast';
import Link from 'next/link';

interface VendorAssignment {
  id: string;
  projectId: string;
  vendorId: string;
  vendorName: string;
  serviceType: string;
  status: 'PENDING' | 'ACCEPTED' | 'DECLINED' | 'COMPLETED' | 'CANCELLED';
  message?: string;
  quotedFee?: number;
  createdAt: any;
  updatedAt: any;
}

interface ProjectVendorsListProps {
  projectId: string;
}

const STATUS_BADGES: Record<string, { bg: string; text: string; icon: any }> = {
  PENDING: { bg: 'rgba(234, 179, 8, 0.1)', text: '#EAB308', icon: Clock },
  ACCEPTED: { bg: 'rgba(34, 197, 94, 0.1)', text: '#3f7d20', icon: CheckCircle2 },
  DECLINED: { bg: 'rgba(239, 68, 68, 0.1)', text: '#F06543', icon: XCircle },
  COMPLETED: { bg: 'rgba(59, 130, 246, 0.1)', text: '#3B82F6', icon: CheckCircle2 },
  CANCELLED: { bg: 'rgba(107, 114, 128, 0.1)', text: '#6B7280', icon: XCircle },
};

export function ProjectVendorsList({ projectId }: ProjectVendorsListProps) {
  const { user } = useAuth();
  const [assignments, setAssignments] = useState<VendorAssignment[]>([]);
  const [loading, setLoading] = useState(true);
  const [updatingId, setUpdatingId] = useState<string | null>(null);

  useEffect(() => {
    if (!projectId) return;

    const q = query(
      collection(db, 'projects', projectId, 'vendorAssignments'),
      orderBy('createdAt', 'desc')
    );

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        const list = snapshot.docs.map((doc) => ({
          id: doc.id,
          ...doc.data(),
        })) as VendorAssignment[];
        setAssignments(list);
        setLoading(false);
      },
      (error) => {
        console.error('Error listening to vendor assignments:', error);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [projectId]);

  const handleUpdateStatus = async (assignmentId: string, newStatus: 'CANCELLED' | 'COMPLETED') => {
    if (!user) return;
    setUpdatingId(assignmentId);
    try {
      const idToken = await user.getIdToken();
      const res = await updateAssignmentStatus(idToken, projectId, assignmentId, newStatus);
      if (res.success) {
        toast.success(`Assignment marked as ${newStatus.toLowerCase()}.`);
      } else {
        toast.error(res.error || 'Failed to update status.');
      }
    } catch (err: any) {
      console.error('Failed to update status:', err);
      toast.error('An unexpected error occurred. Please try again.');
    } finally {
      setUpdatingId(null);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center p-8 border rounded-lg" style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}>
        <Loader2 className="w-6 h-6 animate-spin" style={{ color: 'var(--text-secondary)' }} />
      </div>
    );
  }

  return (
    <div className="rounded-lg border shadow-sm" style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}>
      <div className="px-6 py-4 border-b flex justify-between items-center" style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}>
        <div>
          <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>Marketplace Vendor Requests</h2>
          <p className="text-sm mt-1" style={{ color: 'var(--text-secondary)' }}>
            Track active requests and assigned service providers from the Vendor Marketplace.
          </p>
        </div>
        <Link 
          href="/dashboard/marketplace"
          className="text-xs font-semibold px-3 py-1.5 rounded-lg border flex items-center gap-1.5 transition-colors"
          style={{ borderColor: 'var(--border-ui)', color: 'var(--text-primary)' }}
        >
          Marketplace
          <ArrowUpRight className="w-3.5 h-3.5" />
        </Link>
      </div>

      <div className="p-6">
        {assignments.length === 0 ? (
          <div className="text-center py-8 border border-dashed rounded-xl" style={{ borderColor: 'var(--border-ui)' }}>
            <AlertTriangle className="w-8 h-8 mx-auto mb-2 text-[#6B6870]" />
            <p className="text-sm font-medium" style={{ color: 'var(--text-primary)' }}>No active requests yet</p>
            <p className="text-xs mt-1 mb-4" style={{ color: 'var(--text-secondary)' }}>
              Find title attorneys, inspectors, contractors, and appraisers in the marketplace.
            </p>
            <Link
              href="/dashboard/marketplace"
              className="inline-flex items-center justify-center px-4 py-2 text-xs font-bold uppercase tracking-wider bg-[#454955] hover:bg-[#6E7480] text-black rounded transition-all"
            >
              Browse Vendors
            </Link>
          </div>
        ) : (
          <div className="space-y-4">
            {assignments.map((asg) => {
              const Badge = STATUS_BADGES[asg.status] || STATUS_BADGES.PENDING;
              const StatusIcon = Badge.icon;
              return (
                <div 
                  key={asg.id} 
                  className="rounded-xl p-5 border flex flex-col md:flex-row justify-between items-start md:items-center gap-4 transition-all"
                  style={{ borderColor: 'var(--border-ui)', backgroundColor: 'var(--bg-surface)' }}
                >
                  <div className="space-y-1">
                    <div className="flex items-center gap-2 flex-wrap">
                      <span 
                        className="px-2 py-0.5 text-[10px] font-bold rounded flex items-center gap-1 border"
                        style={{ backgroundColor: Badge.bg, borderColor: `${Badge.text}20`, color: Badge.text }}
                      >
                        <StatusIcon className="w-3 h-3" />
                        {asg.status}
                      </span>
                      <span className="text-xs font-semibold px-2 py-0.5 rounded border border-white/5 bg-white/5" style={{ color: 'var(--text-secondary)' }}>
                        {asg.serviceType}
                      </span>
                    </div>
                    <h3 className="font-semibold text-base pt-1" style={{ color: 'var(--text-primary)' }}>
                      {asg.vendorName}
                    </h3>
                    {asg.message && (
                      <p className="text-xs italic leading-relaxed pt-1" style={{ color: 'var(--text-secondary)' }}>
                        "{asg.message}"
                      </p>
                    )}
                  </div>

                  <div className="flex items-center gap-6 w-full md:w-auto shrink-0 justify-between md:justify-end border-t md:border-t-0 pt-3 md:pt-0" style={{ borderColor: 'var(--border-ui)' }}>
                    <div>
                      <p className="text-[10px] uppercase font-bold tracking-wider" style={{ color: 'var(--text-secondary)' }}>Quote / Fee</p>
                      <p className="text-base font-bold" style={{ color: 'var(--text-primary)' }}>
                        {asg.quotedFee ? `$${asg.quotedFee.toLocaleString()}` : '—'}
                      </p>
                    </div>

                    <div className="flex items-center gap-2">
                      {asg.status === 'PENDING' && (
                        <button
                          onClick={() => handleUpdateStatus(asg.id, 'CANCELLED')}
                          disabled={updatingId === asg.id}
                          className="px-4 py-2 border rounded text-xs font-semibold hover:bg-red-500/10 hover:text-red-500 transition-colors"
                          style={{ borderColor: 'var(--border-ui)', color: 'var(--text-secondary)' }}
                        >
                          {updatingId === asg.id ? '...' : 'Cancel'}
                        </button>
                      )}
                      {asg.status === 'ACCEPTED' && (
                        <button
                          onClick={() => handleUpdateStatus(asg.id, 'COMPLETED')}
                          disabled={updatingId === asg.id}
                          className="px-4 py-2 bg-[#454955] hover:bg-[#6E7480] text-black font-semibold rounded text-xs transition-colors"
                        >
                          {updatingId === asg.id ? '...' : 'Complete Work'}
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { usePlaidLink } from 'react-plaid-link';
import { doc, onSnapshot } from 'firebase/firestore';
import { db, storage } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import {
  Shield,
  FileCheck,
  Upload,
  RefreshCw,
  Clock,
  UserCheck,
  CheckCircle2,
  AlertCircle,
  FileText,
  Building,
  HelpCircle,
  ChevronDown,
  ChevronUp
} from 'lucide-react';
import toast from 'react-hot-toast';
import type { Project, ProofOfFundsStatus } from '@/types/schema';
import { IS_DEMO_MODE } from '@/lib/config/demo';

interface ProofOfFundsCardProps {
  projectId: string;
  refresh?: () => void;
}

export default function ProofOfFundsCard({ projectId, refresh }: ProofOfFundsCardProps) {
  const { user } = useAuth();
  const [project, setProject] = useState<Project | null>(null);
  const [loading, setLoading] = useState(true);
  const [uploadingSourceId, setUploadingSourceId] = useState<string | null>(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [syncingPlaid, setSyncingPlaid] = useState(false);
  const [expandedHistoryId, setExpandedHistoryId] = useState<string | null>(null);
  const [linkToken, setLinkToken] = useState<string | null>(null);

  // ── 1. Listen to Project Updates ──────────────────────────
  useEffect(() => {
    if (!projectId) return;
    const projectRef = doc(db, 'projects', projectId);
    const unsub = onSnapshot(
      projectRef,
      (snap) => {
        if (snap.exists()) {
          setProject({ id: snap.id, ...snap.data() } as Project);
        }
        setLoading(false);
      },
      (err) => {
        console.error('Failed to subscribe to project:', err);
        setLoading(false);
      }
    );
    return unsub;
  }, [projectId]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12 text-[#9E9DA0] text-xs gap-2">
        <RefreshCw className="w-4 h-4 animate-spin" />
        <span>Loading Proof of Funds status...</span>
      </div>
    );
  }

  if (!project) {
    return (
      <div className="p-6 text-center text-red-500 text-xs">
        Project not found.
      </div>
    );
  }

  // Determine if the current user is the Lead Investor / Owner
  const isLead =
    project.ownerUid === user?.uid ||
    project.members?.[user?.uid || '']?.role === 'Lead Investor';

  // Get proofOfFunds list
  const proofOfFunds: ProofOfFundsStatus[] = project.proofOfFunds || [];

  // Fallback to determine if equity sources exist
  const capitalStack = project.financials?.capitalStack || [];
  const equitySources = capitalStack.filter((s: any) =>
    s.category === 'Borrower Injection' ||
    s.category === 'Co-buying Equity' ||
    s.category === 'Syndication Equity'
  );

  // Match current list or display default if empty
  const activeList: Partial<ProofOfFundsStatus>[] = proofOfFunds.length > 0 
    ? proofOfFunds 
    : equitySources.length > 0 
      ? equitySources.map(s => ({
          id: s.id,
          sourceName: s.category,
          amount: s.amount,
          status: 'requested',
          history: []
        }))
      : [{
          id: 'default_solo_equity',
          sourceName: 'Borrower Injection (Solo Cash)',
          amount: project.financials?.purchasePrice || 0,
          status: 'requested',
          history: []
        }];

  // ── 2. Actions Handlers ───────────────────────────────────
  const handleUpdateStatus = async (
    sourceId: string,
    action: 'request' | 'upload' | 'verify',
    docPayload?: { documentId: string; documentName: string; documentUrl: string }
  ) => {
    if (!user) {
      toast.error('You must be signed in.');
      return;
    }

    try {
      const token = await user.getIdToken();
      const res = await fetch(`/api/projects/${projectId}/proof-of-funds`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          sourceId,
          action,
          ...docPayload,
        }),
      });

      const data = await res.json();
      if (!data.success) throw new Error(data.error || 'Failed to update status');

      toast.success(
        action === 'verify'
          ? 'Proof of Funds verified!'
          : action === 'request'
          ? 'Verification reset/requested.'
          : 'Document uploaded successfully!'
      );
      if (refresh) refresh();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Operation failed');
    }
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, sourceId: string) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadingSourceId(sourceId);
    setUploadProgress(0);

    const uploadId = crypto.randomUUID();
    const fileRef = ref(storage, `projects/${projectId}/documents/${uploadId}_${file.name}`);
    const uploadTask = uploadBytesResumable(fileRef, file);

    uploadTask.on(
      'state_changed',
      (snapshot) => {
        const progress = Math.round((snapshot.bytesTransferred / snapshot.totalBytes) * 100);
        setUploadProgress(progress);
      },
      (error) => {
        console.error('Upload failed', error);
        toast.error(`Failed to upload ${file.name}`);
        setUploadingSourceId(null);
      },
      async () => {
        try {
          const downloadUrl = await getDownloadURL(uploadTask.snapshot.ref);
          await handleUpdateStatus(sourceId, 'upload', {
            documentId: uploadId,
            documentName: file.name,
            documentUrl: downloadUrl,
          });
        } catch (err: any) {
          console.error(err);
          toast.error('Failed to link document.');
        } finally {
          setUploadingSourceId(null);
        }
      }
    );
  };

  const handleSyncPlaid = async (sourceId: string) => {
    setSyncingPlaid(true);
    try {
      const token = await user?.getIdToken();
      if (!token) throw new Error('Not authenticated');

      const res = await fetch(`/api/projects/${projectId}/proof-of-funds`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({
          sourceId,
          action: 'plaid_sync',
        }),
      });

      const data = await res.json();
      if (!data.success) throw new Error(data.error);

      toast.success('Plaid context balance synced!');
      if (refresh) refresh();
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to sync Plaid balance');
    } finally {
      setSyncingPlaid(false);
    }
  };

  const handleConnectPlaid = async () => {
    setSyncingPlaid(true);
    try {
      const token = await user?.getIdToken();
      if (!token) throw new Error('Not authenticated');

      const res = await fetch('/api/plaid/create-link-token', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      const data = await res.json();
      if (!data.success) throw new Error(data.error);

      if (data.link_token.startsWith('mock_link_token_')) {
        // Mock mode: perform direct mock sync
        await handleSyncPlaid(activeList[0]?.id || 'default_solo_equity');
      } else {
        setLinkToken(data.link_token);
      }
    } catch (err: any) {
      console.error(err);
      toast.error(err.message || 'Failed to initiate Plaid link');
      setSyncingPlaid(false);
    }
  };

  const { open, ready } = usePlaidLink({
    token: linkToken,
    onSuccess: async (publicToken, metadata) => {
      try {
        const token = await user?.getIdToken();
        const exchangeRes = await fetch('/api/plaid/exchange', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({ public_token: publicToken }),
        });

        const exchangeData = await exchangeRes.json();
        if (!exchangeData.success) throw new Error(exchangeData.error);

        // Now trigger sync to pull real balance
        await handleSyncPlaid(activeList[0]?.id || 'default_solo_equity');
        toast.success('Bank account linked successfully!');
      } catch (err: any) {
        console.error(err);
        toast.error('Failed to link bank account');
      } finally {
        setLinkToken(null);
        setSyncingPlaid(false);
      }
    },
    onExit: () => {
      setLinkToken(null);
      setSyncingPlaid(false);
    },
  });

  useEffect(() => {
    if (linkToken && ready) {
      open();
    }
  }, [linkToken, ready, open]);

  const fmtCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 0 }).format(val / 100);
  };

  return (
    <div className="space-y-6">
      {/* ── Info Banner ── */}
      <div className="bg-[#7A9EAA]/10 border border-[#7A9EAA]/25 rounded-xl p-3 text-xs text-white/90 space-y-1">
        <div className="flex items-center gap-2 font-bold text-[#7A9EAA]">
          <Shield className="w-4 h-4" />
          <span>Solvency Verification Protocol</span>
        </div>
        <p className="text-[10px] text-[#9E9DA0] leading-normal">
          In-scope equity sources must upload official Proof of Funds (PDF or statements) to the Project Files. 
          Only the designated Lead Investor can mark these files as verified to clear buyer solvency audits.
        </p>
      </div>

      {/* ── Equity Source Cards ── */}
      <div className="space-y-4">
        {activeList.map((item) => {
          const status = item.status || 'requested';
          const isVerified = status === 'verified';
          const isReceived = status === 'received';
          const hasDoc = !!item.documentUrl;

          return (
            <div
              key={item.id}
              className="bg-[#1C181E] border border-white/5 rounded-xl p-5 space-y-4 shadow-md"
            >
              {/* Header block */}
              <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
                <div className="space-y-0.5">
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-[#7A9EAA] uppercase tracking-wider">Equity Source</span>
                    <span
                      className={`text-[9px] font-black px-2 py-0.5 rounded-full uppercase tracking-wider ${
                        isVerified
                          ? 'bg-[var(--pw-success)]/10 text-[var(--pw-success)]'
                          : isReceived
                          ? 'bg-sky-500/10 text-sky-400'
                          : 'bg-amber-500/10 text-amber-400'
                      }`}
                    >
                      {status}
                    </span>
                  </div>
                  <h4 className="text-sm font-bold text-white leading-tight">{item.sourceName}</h4>
                  <p className="text-[10px] text-[#9E9DA0]/70">
                    Required commitment basis: <span className="font-bold text-white">{fmtCurrency(item.amount || 0)}</span>
                  </p>
                </div>

                {/* Status Badges or Indicators */}
                <div className="flex items-center gap-2 self-start sm:self-center">
                  {isVerified && (
                    <div className="flex items-center gap-1.5 text-xs text-[var(--pw-success)] font-medium bg-[var(--pw-success)]/5 px-2.5 py-1 rounded-lg border border-[var(--pw-success)]/20">
                      <FileCheck className="w-3.5 h-3.5" />
                      <span>Verified by {item.verifiedByName}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Action Buttons Area */}
              <div className="flex flex-wrap items-center gap-3 pt-2 border-t border-white/5">
                {/* Upload File Control */}
                {status !== 'verified' && (
                  <div className="relative">
                    <input
                      type="file"
                      accept=".pdf,.png,.jpg,.jpeg"
                      onChange={(e) => handleFileUpload(e, item.id!)}
                      disabled={uploadingSourceId === item.id}
                      className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed"
                    />
                    <button
                      disabled={uploadingSourceId === item.id}
                      className="bg-white/5 border border-white/10 hover:border-white/20 text-white px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all disabled:opacity-50"
                    >
                      {uploadingSourceId === item.id ? (
                        <>
                          <RefreshCw className="w-3.5 h-3.5 animate-spin" />
                          <span>Uploading ({uploadProgress}%)</span>
                        </>
                      ) : (
                        <>
                          <Upload className="w-3.5 h-3.5" />
                          <span>{hasDoc ? 'Re-upload PoF Document' : 'Upload Proof of Funds'}</span>
                        </>
                      )}
                    </button>
                  </div>
                )}

                {/* Lead Investor Verify / Reset Action */}
                {isLead && isReceived && (
                  <button
                    onClick={() => handleUpdateStatus(item.id!, 'verify')}
                    className="bg-[var(--pw-success)]/20 border border-[var(--pw-success)]/40 hover:bg-[var(--pw-success)]/30 text-[var(--pw-success)] px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all"
                  >
                    <UserCheck className="w-3.5 h-3.5" />
                    <span>Verify Proof of Funds</span>
                  </button>
                )}

                {isLead && isVerified && (
                  <button
                    onClick={() => handleUpdateStatus(item.id!, 'request')}
                    className="bg-red-500/10 border border-red-500/20 hover:bg-red-500/20 text-red-400 px-3 py-1.5 rounded-lg text-xs font-bold flex items-center gap-1.5 transition-all"
                  >
                    <AlertCircle className="w-3.5 h-3.5" />
                    <span>Revoke Verification</span>
                  </button>
                )}

                {/* View Document Link */}
                {hasDoc && (
                  <a
                    href={item.documentUrl!}
                    target="_blank"
                    rel="noreferrer"
                    className="text-[#7A9EAA] hover:text-[#9bc2d0] text-xs font-semibold flex items-center gap-1 py-1.5 px-2 hover:bg-white/5 rounded-lg transition-all"
                  >
                    <FileText className="w-3.5 h-3.5" />
                    <span className="truncate max-w-[150px]">{item.documentName}</span>
                  </a>
                )}
              </div>

              {/* Status History Timeline (Audit Logs) */}
              <div className="pt-2">
                <button
                  onClick={() => setExpandedHistoryId(expandedHistoryId === item.id ? null : item.id!)}
                  className="flex items-center gap-1 text-[10px] text-[#9E9DA0]/60 hover:text-white transition-all font-bold uppercase tracking-wider"
                >
                  <span>Audit History Logs</span>
                  {expandedHistoryId === item.id ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" />}
                </button>

                {expandedHistoryId === item.id && (
                  <div className="mt-3 space-y-2 border-l border-white/5 pl-3 ml-1.5 animate-in fade-in duration-200">
                    {item.history && item.history.length > 0 ? (
                      item.history.map((log, index) => (
                        <div key={index} className="text-[10px] text-[#9E9DA0]/80 space-y-0.5">
                          <div className="flex items-center gap-1.5">
                            <span className="w-1.5 h-1.5 rounded-full bg-white/20"></span>
                            <span className="font-bold text-white/90">Status changed to {log.status}</span>
                            <span className="text-[#9E9DA0]/50">•</span>
                            <span className="text-[#9E9DA0]/60">{new Date(log.updatedAt).toLocaleString()}</span>
                          </div>
                          <p className="pl-3 text-[#9E9DA0]/60">Updated by: {log.updatedByName}</p>
                        </div>
                      ))
                    ) : (
                      <p className="text-[10px] text-[#9E9DA0]/50 italic">No audit records found.</p>
                    )}
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── Plaid Context Balance Display (Visually Separate) ── */}
      {IS_DEMO_MODE && (
        <div className="bg-[#121014] border border-white/5 rounded-2xl p-6 space-y-4 relative overflow-hidden shadow-inner">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] pointer-events-none">
            <Building className="w-24 h-24 text-white" />
          </div>

          <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
            <div className="space-y-1">
              <span className="text-[9px] font-black text-white/40 tracking-wider bg-white/5 px-2 py-0.5 rounded-md uppercase">
                Plaid Bank Feed (Demo) (Context Reference Only)
              </span>
              <h4 className="text-sm font-bold text-white flex items-center gap-1.5">
                <span>Business Account Liquidity Context (Demo)</span>
              </h4>
              <p className="text-[10px] text-[#9E9DA0]/60 max-w-md leading-normal">
                Continuous live balance check to display liquidity context. This dashboard element does NOT constitute official escrow verification.
              </p>
            </div>

            <div className="flex flex-wrap items-center gap-2 self-start sm:self-center">
              {activeList[0]?.plaidAccountName ? (
                <>
                  <button
                    onClick={() => handleSyncPlaid(activeList[0]?.id || 'default_solo_equity')}
                    disabled={syncingPlaid}
