'use client';

import React, { useState, useEffect } from 'react';
import { CheckCircle2, Calendar, DollarSign, Info } from 'lucide-react';

interface Props {
  projectId: string;
  rehabSpend: any[];
  savedCompletedDate?: any;
  savedSpendTotal?: number;
  onSaveCompletion: (completedDate: string, spendTotal: number) => Promise<void>;
}

export function RenovationCompletionCard({
  projectId,
  rehabSpend,
  savedCompletedDate,
  savedSpendTotal,
  onSaveCompletion
}: Props) {
  const [completedDate, setCompletedDate] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Derive final spend total from ledger
  const currentLedgerTotal = rehabSpend.reduce((sum, e) => sum + (e.amount || 0), 0);

  // Set default/initial date
  useEffect(() => {
    if (savedCompletedDate) {
      let dateVal = '';
      if (typeof savedCompletedDate === 'string') {
        dateVal = savedCompletedDate.slice(0, 10);
      } else if (savedCompletedDate.toDate) {
        dateVal = savedCompletedDate.toDate().toISOString().slice(0, 10);
      } else if (savedCompletedDate instanceof Date) {
        dateVal = savedCompletedDate.toISOString().slice(0, 10);
      }
      setCompletedDate(dateVal);
    } else {
      // Default to today
      setCompletedDate(new Date().toISOString().slice(0, 10));
    }
  }, [savedCompletedDate]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!completedDate) return;
    setIsSubmitting(true);
    try {
      await onSaveCompletion(completedDate, currentLedgerTotal);
    } finally {
      setIsSubmitting(false);
    }
  };

  const isCompleted = !!savedCompletedDate;

  return (
    <div className="glass-card border border-white/5 rounded-xl p-5 space-y-4 text-left">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <CheckCircle2 className={`w-5 h-5 ${isCompleted ? 'text-green-500' : 'text-[#7A9EAA]'}`} />
          <span className="text-[14px] font-bold text-white uppercase tracking-wider">
            Renovation Completion (Card H2.2)
          </span>
        </div>
        {isCompleted && (
          <span className="bg-green-500/10 text-green-400 border border-green-500/20 text-[9px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider">
            Rehab Confirmed
          </span>
        )}
      </div>

      <p className="text-xs text-[#9E9DA0] leading-relaxed">
        Record the actual completion date and finalize the total renovation spend. This actualizes the underwritten budget using live ledger transactions.
      </p>

      {/* Completion Status Alert Banner */}
      {isCompleted ? (
        <div className="bg-green-500/10 border border-green-500/20 p-4 rounded-xl flex items-center gap-3">
          <CheckCircle2 className="w-5 h-5 text-green-500 shrink-0" />
          <div className="text-xs text-[#9E9DA0] leading-normal">
            Renovation confirmed complete on <strong className="text-white">{completedDate}</strong>.
            <br />
            Final spend total actualized at <strong className="text-[#7A9EAA]">${(savedSpendTotal ? savedSpendTotal / 100 : currentLedgerTotal / 100).toLocaleString(undefined, { minimumFractionDigits: 2 })}</strong>.
          </div>
        </div>
      ) : (
        <div className="bg-[#454955]/10 border border-[#454955]/20 p-4 rounded-xl flex items-start gap-2.5">
          <Info className="w-4 h-4 text-[#7A9EAA] shrink-0 mt-0.5" />
          <div className="text-[11px] text-[#9E9DA0] leading-normal">
            Ready to close out? Submitting will set <code className="text-white bg-white/5 px-1 py-0.25 rounded">rehab_completed_date</code> and write the current ledger total <strong className="text-[#7A9EAA]">${(currentLedgerTotal / 100).toLocaleString(undefined, { minimumFractionDigits: 2 })}</strong> to <code className="text-white bg-white/5 px-1 py-0.25 rounded">rehab_spend_total</code>.
          </div>
        </div>
      )}

      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-[#9E9DA0] flex items-center gap-1">
              <Calendar className="w-3 h-3 text-[#7A9EAA]" />
              Actual Completion Date
            </label>
            <input
              type="date"
              required
              value={completedDate}
              onChange={e => setCompletedDate(e.target.value)}
              className="bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none filter invert"
            />
          </div>

          <div className="space-y-1">
            <label className="text-[10px] uppercase font-bold text-[#9E9DA0] flex items-center gap-1">
              <DollarSign className="w-3 h-3 text-[#7A9EAA]" />
              Final Spend Confirmation
            </label>
            <input
              type="text"
              disabled
              value={`$${(currentLedgerTotal / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`}
              className="bg-black/10 border border-white/5 rounded-lg px-3 py-2 text-sm text-[#9E9DA0] w-full outline-none font-mono font-semibold"
            />
          </div>
        </div>

        <div className="flex justify-end pt-2">
          <button
            type="submit"
            disabled={isSubmitting || !completedDate}
            className={`text-xs font-bold px-4 py-2 rounded-lg transition ${
              isCompleted
                ? 'bg-white/5 text-[#9E9DA0] hover:bg-white/10 border border-white/10'
                : 'bg-[#7A9EAA] text-white hover:bg-[#7A9EAA]/80 shadow-md'
            }`}
          >
            {isSubmitting ? 'Saving...' : isCompleted ? 'Update Completion Details' : 'Confirm & Lock Completion'}
          </button>
        </div>
      </form>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { getAuth } from 'firebase/auth';
import { Info, HelpCircle, AlertTriangle, Check, X, ShieldAlert, Sparkles, CheckCircle2, History } from 'lucide-react';
import toast from 'react-hot-toast';
import { IS_DEMO_MODE } from '@/lib/config/demo';
import type { RehabSpendEntry, RehabSpendHistoryEntry } from '@/types/schema';

interface Props {
  projectId: string;
  rehabSpend: RehabSpendEntry[];
  onSpendChange: (updatedSpend: RehabSpendEntry[]) => void;
  totalBudget: number;
}

interface PlaidProposal {
  id: string;
  amount: number; // in cents
  date: string;
  merchant: string;
  suggestedCategory: 'CapEx' | 'Repairs & Maintenance';
  note: string;
}

const INITIAL_PLAID_PROPOSALS: PlaidProposal[] = [
  { id: 'tx-001', amount: 85000, date: '2026-07-15', merchant: 'The Home Depot', suggestedCategory: 'CapEx', note: 'Purchase of lumber and drywalls for framing' },
  { id: 'tx-002', amount: 12000, date: '2026-07-16', merchant: 'Sherwin-Williams', suggestedCategory: 'CapEx', note: 'Interior primer and trim paint' },
  { id: 'tx-003', amount: 4500, date: '2026-07-17', merchant: 'Ace Hardware', suggestedCategory: 'Repairs & Maintenance', note: 'Replacement washers and pipe sealant' }
];

export function RenovationSpendTracker({ projectId, rehabSpend, onSpendChange, totalBudget }: Props) {
  const [plaidProposals, setPlaidProposals] = useState<PlaidProposal[]>(INITIAL_PLAID_PROPOSALS);
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Add Form State
  const [addAmount, setAddAmount] = useState('');
  const [addDate, setAddDate] = useState(new Date().toISOString().slice(0, 10));
  const [addCategory, setAddCategory] = useState<'CapEx' | 'Repairs & Maintenance'>('CapEx');
  const [addNote, setAddNote] = useState('');

  // Edit Form State
  const [editAmount, setEditAmount] = useState('');
  const [editDate, setEditDate] = useState('');
  const [editCategory, setEditCategory] = useState<'CapEx' | 'Repairs & Maintenance'>('CapEx');
  const [editNote, setEditNote] = useState('');

  // Auto-attribution confirmation handler
  const handleConfirmProposal = (proposal: PlaidProposal, category: 'CapEx' | 'Repairs & Maintenance') => {
    const newEntry: RehabSpendEntry = {
      id: `spend-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
      amount: proposal.amount,
      date: proposal.date,
      category,
      note: `${proposal.merchant} (Plaid Auto-attributed): ${proposal.note}`,
      source: 'plaid',
      plaidTransactionId: proposal.id
    };

    onSpendChange([...rehabSpend, newEntry]);
    setPlaidProposals(prev => prev.filter(p => p.id !== proposal.id));
    toast.success(`Confirmed Plaid transaction from ${proposal.merchant}`);
  };

  const handleRejectProposal = (proposal: PlaidProposal) => {
    setPlaidProposals(prev => prev.filter(p => p.id !== proposal.id));
    toast.success('Plaid transaction dismissed');
  };

  // Add spend handler
  const handleAddSpend = (e: React.FormEvent) => {
    e.preventDefault();
    const parsedAmount = parseFloat(addAmount.replace(/,/g, ''));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (!addNote.trim()) {
      toast.error('Please enter a description note');
      return;
    }

    const newEntry: RehabSpendEntry = {
      id: `spend-${Date.now()}`,
      amount: Math.round(parsedAmount * 100),
      date: addDate,
      category: addCategory,
      note: addNote,
      source: 'manual'
    };

    onSpendChange([...rehabSpend, newEntry]);
    setAddAmount('');
    setAddNote('');
    setShowAddForm(false);
    toast.success('Renovation expense added');
  };

  // Edit save handler
  const handleSaveEdit = (id: string) => {
    const parsedAmount = parseFloat(editAmount.replace(/,/g, ''));
    if (isNaN(parsedAmount) || parsedAmount <= 0) {
      toast.error('Please enter a valid amount');
      return;
    }
    if (!editNote.trim()) {
      toast.error('Please enter a description note');
      return;
    }

    const entryToUpdate = rehabSpend.find(e => e.id === id);
    if (!entryToUpdate) return;

    const newAmount = Math.round(parsedAmount * 100);
    const hasChanges = entryToUpdate.amount !== newAmount ||
      entryToUpdate.date !== editDate ||
      entryToUpdate.category !== editCategory ||
      entryToUpdate.note !== editNote;

    if (!hasChanges) {
      setEditingId(null);
      return;
    }

    // Build history entry
    const historyEntry: RehabSpendHistoryEntry = {
      updatedAt: new Date().toISOString(),
      updatedBy: getAuth().currentUser?.email || 'user@paperworking.com',
      previousValue: {
        amount: entryToUpdate.amount,
        date: entryToUpdate.date,
        category: entryToUpdate.category,
        note: entryToUpdate.note
      }
    };

    const updatedList = rehabSpend.map(e => {
      if (e.id === id) {
        return {
          ...e,
          amount: newAmount,
          date: editDate,
          category: editCategory,
          note: editNote,
          history: [...(e.history || []), historyEntry]
        };
      }
      return e;
    });

    onSpendChange(updatedList);
    setEditingId(null);
    toast.success('Renovation expense updated');
  };

  // Delete handler
  const handleDeleteSpend = (id: string) => {
    if (confirm('Are you sure you want to delete this expense?')) {
      onSpendChange(rehabSpend.filter(e => e.id !== id));
      toast.success('Renovation expense deleted');
    }
  };

  return (
    <div className="space-y-6">
      {/* Dynamic Plaid Proposals Bar (Demo only) */}
      {IS_DEMO_MODE && plaidProposals.length > 0 && (
        <div className="border border-[#7A9EAA]/30 bg-[#7A9EAA]/5 p-4 rounded-xl space-y-3 relative">
          <div className="absolute top-2 right-2 flex items-center">
            <span className="text-[8px] font-bold text-amber-500 bg-amber-500/10 px-1.5 py-0.5 rounded border border-amber-500/20">Demo</span>
          </div>
          <div className="flex justify-between items-center">
            <span className="text-[12px] font-bold text-[#7A9EAA] flex items-center gap-1.5 uppercase tracking-wider">
              <Sparkles className="w-4 h-4 animate-pulse text-amber-500" />
              Plaid Auto-Attribution ({plaidProposals.length} Proposed Matches) (Demo)
            </span>
            <span className="text-[10px] text-[#9E9DA0]/80 mr-12">Confirm category to add to ledger</span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            {plaidProposals.map(proposal => (
              <div key={proposal.id} className="glass-card border border-white/5 p-3 rounded-lg flex flex-col justify-between gap-3 text-left">
                <div>
                  <div className="flex justify-between items-center w-full">
                    <span className="text-xs font-bold text-white line-clamp-1">{proposal.merchant}</span>
                    <span className="text-xs font-mono font-bold text-[#7A9EAA]">${(proposal.amount / 100).toFixed(2)}</span>
                  </div>
                  <p className="text-[10px] text-[#9E9DA0]/60 mt-0.5 font-mono">{proposal.date}</p>
                  <p className="text-[10px] text-[#9E9DA0] mt-2 line-clamp-2 italic">"{proposal.note}"</p>
                </div>
                <div className="flex justify-between items-center gap-2 pt-2 border-t border-white/5">
                  <button
                    onClick={() => handleRejectProposal(proposal)}
                    className="p-1 rounded hover:bg-red-500/10 text-red-400 transition"
                    title="Dismiss"
                  >
                    <X className="w-3.5 h-3.5" />
                  </button>
                  <div className="flex gap-1">
                    <button
                      onClick={() => handleConfirmProposal(proposal, 'Repairs & Maintenance')}
                      className="text-[9px] font-bold border border-white/10 hover:border-white/20 text-[#9E9DA0] px-2 py-0.5 rounded transition"
                    >
                      Maint.
                    </button>
                    <button
                      onClick={() => handleConfirmProposal(proposal, 'CapEx')}
                      className="text-[9px] font-bold bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white px-2 py-0.5 rounded transition flex items-center gap-0.5"
                    >
                      <Check className="w-2.5 h-2.5" /> CapEx
                    </button>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Tax Guidance Header Banner */}
      <div className="bg-[#454955]/10 border border-[#454955]/20 p-4 rounded-xl flex gap-3 text-left">
        <ShieldAlert className="w-5 h-5 text-[#7A9EAA] shrink-0 mt-0.5" />
        <div className="space-y-1">
          <h4 className="text-xs font-bold text-white uppercase tracking-wider">CapEx vs. Repairs &amp; Maintenance Classification</h4>
          <p className="text-[11px] text-[#9E9DA0] leading-relaxed">
            <strong>Capital Expenditures (CapEx/Improvements)</strong> add permanent value, extend the useful life of the asset, or adapt it to new uses (e.g. replacing a roof, complete HVAC overhaul). They must be capitalized and depreciated.
            <br />
            <strong>Repairs &amp; Maintenance (Expenses)</strong> keep the property in normal operating condition without adding significant value (e.g. patching drywall, fixing leaks). They can be expensed immediately.
          </p>
          <p className="text-[9px] text-[#9E9DA0]/50 italic flex items-center gap-1">
            <AlertTriangle className="w-3 h-3 text-[#ffb4ab]" />
            <span>This classification is provided for operational tracking only, not official tax advice. Consult a licensed CPA for regulatory tax filings.</span>
          </p>
        </div>
      </div>

      {/* Main spend log list */}
      <div className="glass-card border border-white/5 rounded-xl p-5 space-y-4">
        <div className="flex justify-between items-center">
          <span className="text-[14px] font-bold text-white uppercase tracking-wider">Spend Log ({rehabSpend.length} Entries)</span>
          <button
            onClick={() => setShowAddForm(!showAddForm)}
            className="text-xs font-bold bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white px-3 py-1.5 rounded-lg transition"
          >
            {showAddForm ? 'Cancel' : '+ Add Spend'}
          </button>
        </div>

        {/* Add Entry Form */}
        {showAddForm && (
          <form onSubmit={handleAddSpend} className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-4 text-left">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div className="space-y-1">
                <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Amount ($)</label>
                <input
                  type="text"
                  required
                  placeholder="e.g. 1,250.00"
                  value={addAmount}
                  onChange={e => setAddAmount(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Transaction Date</label>
                <input
                  type="date"
                  required
                  value={addDate}
                  onChange={e => setAddDate(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none filter invert"
                />
              </div>
              <div className="space-y-1">
                <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Category</label>
                <select
                  value={addCategory}
                  onChange={e => setAddCategory(e.target.value as any)}
                  className="bg-[#121014] border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none"
                >
                  <option value="CapEx">CapEx (Capital Improvements)</option>
                  <option value="Repairs & Maintenance">Repairs &amp; Maintenance</option>
                </select>
              </div>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Description / Notes</label>
              <input
                type="text"
                required
                placeholder="e.g. Home Depot plumbing fixtures"
                value={addNote}
                onChange={e => setAddNote(e.target.value)}
                className="bg-black/30 border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none"
              />
            </div>
            <div className="flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setShowAddForm(false)}
                className="text-xs text-[#9E9DA0] px-3 py-1.5 rounded bg-white/5 hover:bg-white/10 transition"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="text-xs text-white font-bold px-4 py-1.5 rounded bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 transition"
              >
                Add Transaction
              </button>
            </div>
          </form>
        )}

        {/* Spend Table */}
        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs border-collapse">
            <thead>
              <tr className="border-b border-white/10 text-[#9E9DA0] uppercase tracking-wider">
                <th className="py-2.5">Date</th>
                <th className="py-2.5">Category</th>
                <th className="py-2.5">Description</th>
                <th className="py-2.5 text-right">Amount</th>
                <th className="py-2.5 text-right">Actions</th>
              </tr>
            </thead>
            <tbody>
              {rehabSpend.length === 0 ? (
                <tr>
                  <td colSpan={5} className="py-8 text-center text-[#9E9DA0]">
                    No spend entries recorded. Add manual transactions or confirm Plaid matches above.
                  </td>
                </tr>
              ) : (
                rehabSpend.map(entry => {
                  const isEditing = editingId === entry.id;

                  return (
                    <tr key={entry.id} className="border-b border-white/5 hover:bg-white/5 transition-all align-top">
                      {isEditing ? (
                        <td colSpan={5} className="py-3">
                          <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-4 text-left">
                            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
                              <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Amount ($)</label>
                                <input
                                  type="text"
                                  value={editAmount}
                                  onChange={e => setEditAmount(e.target.value)}
                                  className="bg-black/30 border border-white/10 rounded px-2 py-1 text-xs text-white w-full outline-none font-mono"
                                />
                              </div>
                              <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Date</label>
                                <input
                                  type="date"
                                  value={editDate}
                                  onChange={e => setEditDate(e.target.value)}
                                  className="bg-black/30 border border-white/10 rounded px-2 py-1 text-xs text-white w-full outline-none filter invert"
                                />
                              </div>
                              <div className="space-y-1">
                                <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Category</label>
                                <select
                                  value={editCategory}
                                  onChange={e => setEditCategory(e.target.value as any)}
                                  className="bg-[#121014] border border-white/10 rounded px-2 py-1 text-xs text-white w-full outline-none"
                                >
                                  <option value="CapEx">CapEx</option>
                                  <option value="Repairs & Maintenance">Repairs &amp; Maint.</option>
                                </select>
                              </div>
                            </div>
                            <div className="space-y-1">
                              <label className="text-[10px] uppercase font-bold text-[#9E9DA0]">Description</label>
                              <input
                                type="text"
                                value={editNote}
                                onChange={e => setEditNote(e.target.value)}
                                className="bg-black/30 border border-white/10 rounded px-2 py-1 text-xs text-white w-full outline-none"
                              />
                            </div>
                            <div className="flex justify-end gap-2 text-[10px]">
                              <button
                                onClick={() => setEditingId(null)}
                                className="px-2 py-1 rounded bg-white/5 hover:bg-white/10 text-[#9E9DA0]"
                              >
                                Cancel
                              </button>
                              <button
                                onClick={() => handleSaveEdit(entry.id)}
                                className="px-2 py-1 rounded bg-[#7A9EAA] text-white font-bold"
                              >
                                Save Updates
                              </button>
                            </div>
                          </div>
                        </td>
                      ) : (
                        <>
                          <td className="py-3 text-[#9E9DA0] font-mono">{entry.date}</td>
                          <td className="py-3">
                            <span className={`px-2 py-0.5 rounded text-[10px] font-bold ${
                              entry.category === 'CapEx'
                                ? 'bg-[#7A9EAA]/15 text-[#7A9EAA]'
                                : 'bg-amber-500/15 text-amber-400'
                            }`}>
                              {entry.category}
                            </span>
                          </td>
                          <td className="py-3 text-white">
                            <div className="flex flex-col">
                              <span>{entry.note}</span>
                              {entry.source === 'plaid' && (
                                <span className="text-[9px] text-[#7A9EAA] mt-0.5 font-bold uppercase tracking-wider flex items-center gap-1">
                                  <Sparkles className="w-2.5 h-2.5" /> Plaid Attributed
                                </span>
                              )}
                              {entry.history && entry.history.length > 0 && (
                                <div className="mt-1 flex items-center gap-1 group relative">
                                  <span className="text-[9px] text-amber-400 font-bold flex items-center gap-0.5 cursor-help">
                                    <History className="w-2.5 h-2.5" /> Edited ({entry.history.length}x)
                                  </span>
                                  {/* Hover popup with audit trails */}
                                  <div className="absolute top-5 left-0 scale-0 group-hover:scale-100 bg-[#161318] border border-white/10 rounded-lg p-2.5 text-[9px] text-[#9E9DA0] w-64 z-20 shadow-2xl transition-all">
                                    <p className="font-bold text-white border-b border-white/10 pb-1 mb-1">Edit Audit History</p>
                                    <div className="space-y-1.5 max-h-32 overflow-y-auto">
                                      {entry.history.map((hist, idx) => (
                                        <div key={idx} className="border-b border-white/5 pb-1 last:border-0">
                                          <p className="text-white/80 font-semibold">{hist.updatedBy}</p>
                                          <p className="text-[8px]">{new Date(hist.updatedAt).toLocaleString()}</p>
                                          <p className="mt-0.5 text-amber-400/80">Prev: ${(hist.previousValue.amount / 100).toFixed(2)} | {hist.previousValue.category} | "{hist.previousValue.note}"</p>
                                        </div>
                                      ))}
                                    </div>
                                  </div>
                                </div>
                              )}
                            </div>
                          </td>
                          <td className="py-3 text-right font-mono font-semibold text-white">
                            ${(entry.amount / 100).toFixed(2)}
                          </td>
                          <td className="py-3 text-right">
                            <div className="flex gap-2 justify-end">
                              <button
                                onClick={() => {
                                  setEditingId(entry.id);
                                  setEditAmount((entry.amount / 100).toString());
                                  setEditDate(entry.date);
                                  setEditCategory(entry.category);
                                  setEditNote(entry.note);
                                }}
                                className="text-[10px] font-bold text-[#7A9EAA] hover:underline"
                              >
                                Edit
                              </button>
                              <button
                                onClick={() => handleDeleteSpend(entry.id)}
                                className="text-[10px] font-bold text-red-400 hover:underline"
                              >
                                Delete
                              </button>
                            </div>
                          </td>
                        </>
                      )}
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Sparkles, Megaphone, CheckSquare, Plus, Trash2, ArrowUpRight, DollarSign, Calendar, Globe, Square, CheckSquare as CheckedIcon } from 'lucide-react';
import toast from 'react-hot-toast';
import type { ListingAdLogEntry, ScreeningChecklistState, ScreeningChecklistItem } from '@/types/schema';

interface Props {
  projectId: string;
  targetRent?: number; // cents
  listingAds?: ListingAdLogEntry[];
  screeningChecklist?: ScreeningChecklistState;
  onSaveTargetRent: (rent: number) => Promise<void>;
  onAddListingAd: (ad: ListingAdLogEntry) => Promise<void>;
  onUpdateAdStatus: (id: string, status: 'active' | 'paused' | 'removed') => Promise<void>;
  onDeleteListingAd: (id: string) => Promise<void>;
  onSaveScreeningChecklist: (state: ScreeningChecklistState) => Promise<void>;
}

export function RentGoToMarket({
  projectId,
  targetRent = 0,
  listingAds = [],
  screeningChecklist = {
    creditScoreCheck: false,
    backgroundCheck: false,
    incomeVerification: false,
    priorEvictionsCheck: false,
    landlordReferences: false,
    customItems: []
  },
  onSaveTargetRent,
  onAddListingAd,
  onUpdateAdStatus,
  onDeleteListingAd,
  onSaveScreeningChecklist
}: Props) {
  const [rentInput, setRentInput] = useState(targetRent > 0 ? (targetRent / 100).toString() : '');
  const [showAddAd, setShowAddAd] = useState(false);
  const [adPlatform, setAdPlatform] = useState('Zillow');
  const [adRent, setAdRent] = useState(targetRent > 0 ? (targetRent / 100).toString() : '');
  const [adUrl, setAdUrl] = useState('');
  const [adDate, setAdDate] = useState(new Date().toISOString().slice(0, 10));
  const [newCustomLabel, setNewCustomLabel] = useState('');

  const handleSaveRent = async () => {
    const val = parseFloat(rentInput.replace(/,/g, ''));
    if (isNaN(val) || val < 0) {
      toast.error('Please enter a valid monthly rent');
      return;
    }
    await onSaveTargetRent(Math.round(val * 100));
    toast.success('Target rent updated');
  };

  const handleAddAdSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseFloat(adRent.replace(/,/g, ''));
    if (isNaN(val) || val <= 0) {
      toast.error('Please enter a valid listing rent');
      return;
    }

    const newAd: ListingAdLogEntry = {
      id: `ad-${Date.now()}`,
      platform: adPlatform,
      listingUrl: adUrl.trim() || null,
      status: 'active',
      listedDate: adDate,
      monthlyRent: Math.round(val * 100)
    };

    await onAddListingAd(newAd);
    setAdUrl('');
    setShowAddAd(false);
    toast.success(`Listing on ${adPlatform} recorded`);
  };

  const toggleCheck = async (key: keyof Omit<ScreeningChecklistState, 'customItems'>) => {
    const updated: ScreeningChecklistState = {
      ...screeningChecklist,
      [key]: !screeningChecklist[key]
    };
    await onSaveScreeningChecklist(updated);
    toast.success('Checklist updated');
  };

  const handleAddCustomItem = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCustomLabel.trim()) return;

    const newItem: ScreeningChecklistItem = {
      id: `item-${Date.now()}`,
      label: newCustomLabel.trim(),
      checked: false
    };

    const updated: ScreeningChecklistState = {
      ...screeningChecklist,
      customItems: [...(screeningChecklist.customItems || []), newItem]
    };

    await onSaveScreeningChecklist(updated);
    setNewCustomLabel('');
    toast.success('Custom requirement added');
  };

  const toggleCustomItem = async (id: string) => {
    const updatedItems = (screeningChecklist.customItems || []).map(item =>
      item.id === id ? { ...item, checked: !item.checked } : item
    );

    const updated: ScreeningChecklistState = {
      ...screeningChecklist,
      customItems: updatedItems
    };

    await onSaveScreeningChecklist(updated);
  };

  const deleteCustomItem = async (id: string) => {
    const updatedItems = (screeningChecklist.customItems || []).filter(item => item.id !== id);

    const updated: ScreeningChecklistState = {
      ...screeningChecklist,
      customItems: updatedItems
    };

    await onSaveScreeningChecklist(updated);
    toast.success('Requirement removed');
  };

  return (
    <div className="glass-card border border-white/5 rounded-xl p-5 space-y-6 text-left">
      {/* Header */}
      <div className="border-b border-white/5 pb-3">
        <span className="text-[10px] text-[#7A9EAA] uppercase font-bold tracking-wider">
          Go To Market (Card H5.R)
        </span>
        <h3 className="text-sm font-bold text-white uppercase tracking-wide mt-0.5">
          Rent Marketing &amp; Tenant Placement
        </h3>
      </div>

      {/* Target Rent Section */}
      <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-3">
        <h4 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
          <DollarSign className="w-4 h-4 text-[#7A9EAA]" />
          Target Monthly Rent
        </h4>
        <p className="text-[11px] text-[#9E9DA0]">
          Set the expected lease price for syndication and marketing projections.
        </p>
        <div className="flex gap-2">
          <input
            type="text"
            placeholder="e.g. 1,800.00"
            value={rentInput}
            onChange={e => setRentInput(e.target.value)}
            className="bg-black/35 border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none font-mono"
          />
          <button
            onClick={handleSaveRent}
            className="text-xs font-bold bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white px-4 py-2 rounded-lg transition shrink-0"
          >
            Save Target
          </button>
        </div>
      </div>

      {/* Listing / Ad Log Section */}
      <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-4">
        <div className="flex justify-between items-center">
          <h4 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
            <Megaphone className="w-4 h-4 text-[#7A9EAA]" />
            Active Advertising Logs
          </h4>
          <button
            onClick={() => setShowAddAd(!showAddAd)}
            className="text-[10px] font-bold text-[#7A9EAA] hover:underline"
          >
            {showAddAd ? 'Cancel' : '+ Add Listing Ad'}
          </button>
        </div>

        {showAddAd && (
          <form onSubmit={handleAddAdSubmit} className="bg-black/20 border border-white/10 p-3 rounded-lg space-y-3">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Platform</label>
                <select
                  value={adPlatform}
                  onChange={e => setAdPlatform(e.target.value)}
                  className="bg-[#121014] border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none"
                >
                  <option value="Zillow">Zillow</option>
                  <option value="Craigslist">Craigslist</option>
                  <option value="Facebook Marketplace">Facebook Marketplace</option>
                  <option value="Apartments.com">Apartments.com</option>
                  <option value="MLS/Syndication">MLS / Syndication</option>
                  <option value="Other">Other</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Listed Rent ($)</label>
                <input
                  type="text"
                  required
                  placeholder="e.g. 1850"
                  value={adRent}
                  onChange={e => setAdRent(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none font-mono"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Listed Date</label>
                <input
                  type="date"
                  required
                  value={adDate}
                  onChange={e => setAdDate(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none filter invert"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Listing URL (Optional)</label>
              <input
                type="url"
                placeholder="https://zillow.com/homedetails/..."
                value={adUrl}
                onChange={e => setAdUrl(e.target.value)}
                className="bg-black/30 border border-white/10 rounded-lg px-3 py-1.5 text-xs text-white w-full outline-none"
              />
            </div>

            <div className="flex justify-end gap-2 pt-1 text-[10px]">
              <button
                type="button"
                onClick={() => setShowAddAd(false)}
                className="text-[#9E9DA0] hover:underline"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white font-bold px-3 py-1.5 rounded"
              >
                Log Ad
              </button>
            </div>
          </form>
        )}

        {listingAds.length === 0 ? (
          <div className="py-4 text-center border border-dashed border-white/5 rounded-lg">
            <p className="text-xs text-[#9E9DA0]/50">No rental ads logged yet.</p>
          </div>
        ) : (
          <div className="space-y-2">
            {listingAds.map(ad => (
              <div key={ad.id} className="flex justify-between items-center bg-black/20 border border-white/5 p-2.5 rounded-lg text-xs">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-white">{ad.platform}</span>
                    <span className="text-mono text-[#9E9DA0]">
                      ${(ad.monthlyRent / 100).toLocaleString()}/mo
                    </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[9px] text-[#9E9DA0]">
                      Listed: {new Date(ad.listedDate).toLocaleDateString()}
                    </span>
                    {ad.listingUrl && (
                      <a
                        href={ad.listingUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="text-[9px] text-[#7A9EAA] hover:underline flex items-center gap-0.5"
                      >
                        View Ad <ArrowUpRight className="w-2.5 h-2.5" />
                      </a>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <select
                    value={ad.status}
                    onChange={e => onUpdateAdStatus(ad.id, e.target.value as any)}
                    className="bg-[#121014] border border-white/10 rounded px-1.5 py-1 text-[10px] text-white outline-none"
                  >
                    <option value="active">Active</option>
                    <option value="paused">Paused</option>
                    <option value="removed">Removed</option>
                  </select>
                  <button
                    onClick={() => onDeleteListingAd(ad.id)}
                    className="text-[#9E9DA0] hover:text-red-400 p-0.5"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Screening Checklist Section */}
      <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-4">
        <h4 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
          <CheckSquare className="w-4 h-4 text-[#7A9EAA]" />
          Tenant Screening Criteria
        </h4>
        <p className="text-[11px] text-[#9E9DA0]">
          Standardize checks that applicants must clear before lease approval.
        </p>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-xs">
          {[
            { key: 'creditScoreCheck', label: 'Credit Score verification' },
            { key: 'backgroundCheck', label: 'Criminal background check' },
            { key: 'incomeVerification', label: 'Income & employment proof' },
            { key: 'priorEvictionsCheck', label: 'Prior eviction search' },
            { key: 'landlordReferences', label: 'Previous landlord references' }
          ].map(chk => {
            const isChecked = !!(screeningChecklist as any)[chk.key];
            return (
              <div
                key={chk.key}
                onClick={() => toggleCheck(chk.key as any)}
                className={`flex items-center gap-2.5 p-2 rounded-lg border cursor-pointer select-none transition ${
                  isChecked
                    ? 'bg-[#7A9EAA]/10 border-[#7A9EAA]/30 text-white'
                    : 'bg-black/10 border-white/5 text-[#9E9DA0] hover:bg-black/20'
                }`}
              >
                {isChecked ? (
                  <CheckedIcon className="w-4 h-4 text-[#7A9EAA] shrink-0" />
                ) : (
                  <Square className="w-4 h-4 text-white/30 shrink-0" />
                )}
                <span>{chk.label}</span>
              </div>
            );
          })}
        </div>

        {/* Custom Screening Requirements */}
        <div className="border-t border-white/5 pt-3 space-y-3">
          <p className="text-[10px] text-[#9E9DA0] uppercase font-bold tracking-wider">
            Custom Screening Checks
          </p>

          <form onSubmit={handleAddCustomItem} className="flex gap-2">
            <input
              type="text"
              placeholder="e.g. Pet policy agreement signed, Co-signer required"
              value={newCustomLabel}
              onChange={e => setNewCustomLabel(e.target.value)}
              className="bg-black/35 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none"
            />
            <button
              type="submit"
              className="bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white font-bold px-3 py-1.5 rounded-lg text-xs shrink-0"
            >
              + Add
            </button>
          </form>

          {screeningChecklist.customItems && screeningChecklist.customItems.length > 0 && (
            <div className="space-y-1.5 text-xs">
              {screeningChecklist.customItems.map(item => (
                <div
                  key={item.id}
                  className="flex justify-between items-center bg-black/20 border border-white/5 p-2 rounded-lg"
                >
                  <div
                    onClick={() => toggleCustomItem(item.id)}
                    className="flex items-center gap-2.5 cursor-pointer select-none flex-grow text-left"
                  >
                    {item.checked ? (
                      <CheckedIcon className="w-4 h-4 text-[#7A9EAA] shrink-0" />
                    ) : (
                      <Square className="w-4 h-4 text-white/30 shrink-0" />
                    )}
                    <span className={item.checked ? 'line-through text-[#9E9DA0]' : 'text-white'}>
                      {item.label}
                    </span>
                  </div>
                  <button
                    onClick={() => deleteCustomItem(item.id)}
                    className="text-[#9E9DA0] hover:text-red-400 p-0.5 shrink-0"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

