import { issueSlotRfp, acceptSlotBid } from '@/actions/rfpBids';
import { useMarketplaceVendors, SLOT_LABELS } from '@/hooks/useMarketplaceVendors';
import type { F4RfpBid } from '@/types/schema';
import {
  FileText,
  Send,
  Loader2,
  CheckCircle2,
  XCircle,
  Clock,
  ChevronDown,
  ChevronUp,
  Plus,
  Trophy,
  ArrowDownUp,
  DollarSign,
  Timer,
  StickyNote,
  Star,
  Search,
  X,
} from 'lucide-react';
import toast from 'react-hot-toast';

interface Props {
  projectId: string;
}

// ── Slot definitions for the dropdown ─────────────────────────────────────
const ALL_SLOTS = Object.entries(SLOT_LABELS).map(([key, label]) => ({
  key,
  label,
}));

// ── Status badge ──────────────────────────────────────────────────────────
function StatusBadge({ status }: { status: string }) {
  const config: Record<string, { bg: string; text: string; icon: React.ReactNode }> = {
    PENDING: { bg: 'bg-amber-50 border-amber-200', text: 'text-amber-700', icon: <Clock className="w-2.5 h-2.5" /> },
    QUOTED: { bg: 'bg-blue-50 border-blue-200', text: 'text-blue-700', icon: <DollarSign className="w-2.5 h-2.5" /> },
    ACCEPTED: { bg: 'bg-green-50 border-green-200', text: 'text-green-700', icon: <CheckCircle2 className="w-2.5 h-2.5" /> },
    DECLINED: { bg: 'bg-red-50 border-red-200', text: 'text-red-600', icon: <XCircle className="w-2.5 h-2.5" /> },
    CANCELLED: { bg: 'bg-gray-100 border-gray-200', text: 'text-gray-500', icon: <X className="w-2.5 h-2.5" /> },
  };
  const c = config[status] || config.PENDING;
  return (
    <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider rounded border ${c.bg} ${c.text}`}>
      {c.icon} {status}
    </span>
  );
}

export function RfpBidsCard({ projectId }: Props) {
  const [bids, setBids] = useState<F4RfpBid[]>([]);
  const [loading, setLoading] = useState(true);
  const [issuing, setIssuing] = useState(false);
  const [acceptingId, setAcceptingId] = useState<string | null>(null);

  // RFP issuance form state
  const [showIssuePanel, setShowIssuePanel] = useState(false);
  const [selectedSlot, setSelectedSlot] = useState<string>('');
  const [selectedVendors, setSelectedVendors] = useState<string[]>([]);
  const [rfpMessage, setRfpMessage] = useState('');
  const [rfpUrgency, setRfpUrgency] = useState<'standard' | 'rush' | 'asap'>('standard');

  // Filter state
  const [filterSlot, setFilterSlot] = useState<string>('');

  // Marketplace vendor search
  const { vendors: marketplaceVendors, loading: vendorsLoading } = useMarketplaceVendors(
    selectedSlot || null
  );

  // ── Real-time bids listener ─────────────────────────────────────────────
  useEffect(() => {
    if (!projectId) return;
    const q = query(
      collection(db, 'projects', projectId, 'rfpBids'),
      orderBy('createdAt', 'desc')
    );
    const unsub = onSnapshot(q, (snap) => {
      const items = snap.docs.map((d) => ({ id: d.id, ...d.data() })) as F4RfpBid[];
      setBids(items);
      setLoading(false);
    });
    return unsub;
  }, [projectId]);

  // ── Group bids by rfpId ──────────────────────────────────────────────────
  const groupedBids = useMemo(() => {
    const filtered = filterSlot ? bids.filter((b) => b.slotKey === filterSlot) : bids;

    const groups: Record<string, { rfpId: string; slotKey: string; slotLabel: string; bids: F4RfpBid[] }> = {};
    for (const bid of filtered) {
      if (!groups[bid.rfpId]) {
        groups[bid.rfpId] = {
          rfpId: bid.rfpId,
          slotKey: bid.slotKey,
          slotLabel: SLOT_LABELS[bid.slotKey] || bid.slotKey,
          bids: [],
        };
      }
      groups[bid.rfpId].bids.push(bid);
    }

    return Object.values(groups);
  }, [bids, filterSlot]);

  // ── Vendor toggle ───────────────────────────────────────────────────────
  const toggleVendor = useCallback((uid: string) => {
    setSelectedVendors((prev) =>
      prev.includes(uid) ? prev.filter((v) => v !== uid) : [...prev, uid]
    );
  }, []);

  // ── Issue RFP ───────────────────────────────────────────────────────────
  const handleIssueRfp = async () => {
    if (!selectedSlot) {
      toast.error('Select a team slot.');
      return;
    }
    if (selectedVendors.length === 0) {
      toast.error('Select at least one vendor.');
      return;
    }

    setIssuing(true);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication required.');

      const res = await issueSlotRfp(
        idToken,
        projectId,
        selectedSlot,
        selectedVendors,
        rfpMessage.trim() || undefined,
        rfpUrgency
      );

      if (!res.success) throw new Error(res.error || 'Failed to issue RFP.');

      toast.success(`RFP issued to ${selectedVendors.length} vendor${selectedVendors.length > 1 ? 's' : ''}`);
      setShowIssuePanel(false);
      setSelectedSlot('');
      setSelectedVendors([]);
      setRfpMessage('');
      setRfpUrgency('standard');
    } catch (err: any) {
      toast.error(err.message || 'Failed to issue RFP.');
    } finally {
      setIssuing(false);
    }
  };

  // ── Accept bid ──────────────────────────────────────────────────────────
  const handleAcceptBid = async (bidId: string) => {
    setAcceptingId(bidId);
    try {
      const auth = getAuth();
      const idToken = await auth.currentUser?.getIdToken();
      if (!idToken) throw new Error('Authentication required.');

      const res = await acceptSlotBid(idToken, projectId, bidId);
      if (!res.success) throw new Error(res.error || 'Failed to accept bid.');

      toast.success('Vendor assigned from RFP.');
    } catch (err: any) {
      toast.error(err.message || 'Failed to accept bid.');
    } finally {
      setAcceptingId(null);
    }
  };

  // ── Find best values for highlighting ───────────────────────────────────
  const getBestValues = (rfpBids: F4RfpBid[]) => {
    const quotedBids = rfpBids.filter((b) => b.price != null && (b.status === 'QUOTED' || b.status === 'PENDING'));
    const bestPrice = quotedBids.length > 0 ? Math.min(...quotedBids.map((b) => b.price!)) : null;
    const fastestBids = rfpBids.filter((b) => b.turnaroundDays != null && b.turnaroundDays > 0);
    const bestTurnaround = fastestBids.length > 0 ? Math.min(...fastestBids.map((b) => b.turnaroundDays!)) : null;
    return { bestPrice, bestTurnaround };
  };

  if (loading) return null;

  return (
    <div className="glass-card p-6 space-y-4">
      {/* ── Header ──────────────────────────────────────────────────────── */}
      <div className="flex justify-between items-start border-b border-pw-border pb-4">
        <div>
          <h3 className="text-lg font-light uppercase tracking-widest text-pw-black flex items-center gap-2.5">
            <FileText className="w-5 h-5 text-[#7A9EAA]" />
            RFP & Bids
          </h3>
          <p className="text-xs text-pw-muted font-light mt-1">
            Issue requests for proposals to marketplace vendors, compare bids, and assign the winner.
          </p>
        </div>
        <button
          onClick={() => setShowIssuePanel(!showIssuePanel)}
          className="px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider bg-[#7A9EAA] text-white rounded hover:bg-[#688a95] transition-all shadow-sm flex items-center gap-1"
        >
          {showIssuePanel ? <ChevronUp className="w-3 h-3" /> : <Plus className="w-3 h-3" />}
          Issue RFP
        </button>
      </div>

      {/* ── Issue RFP Panel ─────────────────────────────────────────────── */}
      {showIssuePanel && (
        <div className="border border-pw-border rounded-lg p-4 bg-gray-50/50 space-y-4 animate-in fade-in duration-150">
          <h4 className="text-xs font-bold text-pw-black uppercase tracking-wider flex items-center gap-1.5">
            <Send className="w-3.5 h-3.5 text-[#7A9EAA]" />
            New Request for Proposals
          </h4>

          {/* Slot selector */}
          <div>
            <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider mb-1">
              Team Slot *
            </label>
            <select
              value={selectedSlot}
              onChange={(e) => {
                setSelectedSlot(e.target.value);
                setSelectedVendors([]);
              }}
              className="w-full px-3 py-1.5 border border-pw-border rounded text-sm bg-pw-white text-pw-black focus:outline-none focus:ring-1 focus:ring-[#7A9EAA]"
            >
              <option value="">Select a team slot…</option>
              {ALL_SLOTS.map((s) => (
                <option key={s.key} value={s.key}>
                  {s.label}
                </option>
              ))}
            </select>
          </div>

          {/* Vendor multi-select */}
          {selectedSlot && (
            <div>
              <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider mb-1">
                Select Vendors *
              </label>
              {vendorsLoading ? (
                <div className="flex items-center gap-2 text-xs text-pw-muted p-3">
                  <Loader2 className="w-3.5 h-3.5 animate-spin" />
                  Searching marketplace…
                </div>
              ) : marketplaceVendors.length === 0 ? (
                <div className="p-3 text-xs text-pw-muted border border-dashed border-pw-border rounded flex items-center gap-2">
                  <Search className="w-3.5 h-3.5" />
                  No verified vendors found for this service type.
                </div>
              ) : (
                <div className="border border-pw-border rounded divide-y divide-pw-border max-h-52 overflow-y-auto">
                  {marketplaceVendors.map((v) => {
                    const isSelected = selectedVendors.includes(v.uid);
                    return (
                      <button
                        key={v.uid}
                        type="button"
                        onClick={() => toggleVendor(v.uid)}
                        className={`w-full text-left px-3 py-2 flex items-center justify-between text-xs transition-all ${
                          isSelected
                            ? 'bg-[#7A9EAA]/10 border-l-2 border-l-[#7A9EAA]'
                            : 'hover:bg-gray-50'
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <div
                            className={`w-4 h-4 rounded border flex items-center justify-center transition-all ${
                              isSelected
                                ? 'bg-[#7A9EAA] border-[#7A9EAA]'
                                : 'border-pw-border'
                            }`}
                          >
                            {isSelected && <CheckCircle2 className="w-2.5 h-2.5 text-white" />}
                          </div>
                          <div>
                            <span className="font-semibold text-pw-black block">{v.companyName}</span>
                            <span className="text-pw-muted text-[10px]">
                              {v.feeRangeLabel} · {v.avgTurnaroundDays}d turnaround
                            </span>
                          </div>
                        </div>
                        <div className="flex items-center gap-1">
                          {v.verified && (
                            <span className="px-1 py-0.5 text-[8px] font-bold uppercase bg-green-50 text-green-600 rounded border border-green-200">
                              Verified
                            </span>
                          )}
                          {v.overallRating > 0 && (
                            <span className="flex items-center gap-0.5 text-[10px] text-amber-600">
                              <Star className="w-2.5 h-2.5 fill-amber-400" />
                              {v.overallRating.toFixed(1)}
                            </span>
                          )}
                        </div>
                      </button>
                    );
                  })}
                </div>
              )}
              {selectedVendors.length > 0 && (
                <p className="text-[10px] text-[#7A9EAA] font-semibold mt-1">
                  {selectedVendors.length} vendor{selectedVendors.length > 1 ? 's' : ''} selected
                </p>
              )}
            </div>
          )}

          {/* Message */}
          <div>
            <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider mb-1">
              Scope / Requirements
            </label>
            <textarea
              value={rfpMessage}
              onChange={(e) => setRfpMessage(e.target.value)}
              placeholder="Describe the scope of work, timelines, or specific requirements…"
              className="w-full px-3 py-1.5 border border-pw-border rounded text-sm bg-pw-white text-pw-black focus:outline-none focus:ring-1 focus:ring-[#7A9EAA] resize-none h-16"
            />
          </div>

          {/* Urgency */}
          <div>
            <label className="block text-[10px] font-bold text-pw-muted uppercase tracking-wider mb-1">
              Urgency
            </label>
            <div className="flex gap-2">
              {(['standard', 'rush', 'asap'] as const).map((level) => (
                <button
                  key={level}
                  type="button"
                  onClick={() => setRfpUrgency(level)}
                  className={`flex-1 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded border transition-all ${
                    rfpUrgency === level
                      ? level === 'asap'
                        ? 'bg-red-50 border-red-300 text-red-600'
                        : level === 'rush'
                          ? 'bg-amber-50 border-amber-300 text-amber-600'
                          : 'bg-[#7A9EAA]/10 border-[#7A9EAA] text-[#7A9EAA]'
                      : 'border-pw-border text-pw-muted hover:border-gray-300'
                  }`}
                >
                  {level}
                </button>
              ))}
            </div>
          </div>

          {/* Actions */}
          <div className="flex items-center justify-end gap-2 pt-1">
            <button
              onClick={() => setShowIssuePanel(false)}
              className="px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider border border-pw-border text-pw-muted rounded hover:bg-gray-50 transition-all"
            >
              Cancel
            </button>
            <button
              onClick={handleIssueRfp}
              disabled={issuing || !selectedSlot || selectedVendors.length === 0}
              className={`px-4 py-1.5 text-[10px] font-bold uppercase tracking-wider rounded flex items-center gap-1 transition-all ${
                issuing || !selectedSlot || selectedVendors.length === 0
                  ? 'bg-gray-300 text-white cursor-not-allowed'
                  : 'bg-[#7A9EAA] text-white hover:bg-[#688a95] shadow-sm'
              }`}
            >
              {issuing ? <Loader2 className="w-3 h-3 animate-spin" /> : <Send className="w-3 h-3" />}
              Issue RFP
            </button>
          </div>
        </div>
      )}

      {/* ── Filter bar ──────────────────────────────────────────────────── */}
      {bids.length > 0 && (
        <div className="flex items-center gap-2">
          <ArrowDownUp className="w-3.5 h-3.5 text-pw-muted" />
          <select
            value={filterSlot}
            onChange={(e) => setFilterSlot(e.target.value)}
            className="px-2 py-1 text-[10px] font-bold uppercase tracking-wider border border-pw-border rounded bg-pw-white text-pw-black focus:outline-none focus:ring-1 focus:ring-[#7A9EAA]"
          >
            <option value="">All Slots</option>
            {ALL_SLOTS.map((s) => (
              <option key={s.key} value={s.key}>
                {s.label}
              </option>
            ))}
          </select>
          <span className="text-[10px] text-pw-muted">
            {groupedBids.length} RFP round{groupedBids.length !== 1 ? 's' : ''}
          </span>
        </div>
      )}

      {/* ── Bid comparison groups ───────────────────────────────────────── */}
      {groupedBids.length > 0 ? (
        <div className="space-y-4">
          {groupedBids.map((group) => {
            const { bestPrice, bestTurnaround } = getBestValues(group.bids);
            const hasAccepted = group.bids.some((b) => b.status === 'ACCEPTED');

            return (
              <div key={group.rfpId} className="border border-pw-border rounded-lg overflow-hidden">
                {/* Group header */}
                <div className="px-4 py-2.5 bg-gray-50 border-b border-pw-border flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] font-bold text-pw-black uppercase tracking-wider">
                      {group.slotLabel}
                    </span>
                    <span className="text-[10px] text-pw-muted">
                      {group.bids.length} bid{group.bids.length !== 1 ? 's' : ''}
                    </span>
                  </div>
                  {hasAccepted && (
                    <span className="flex items-center gap-1 px-1.5 py-0.5 text-[9px] font-bold uppercase bg-green-50 text-green-700 rounded border border-green-200">
                      <Trophy className="w-2.5 h-2.5" /> Assigned
                    </span>
                  )}
                </div>

                {/* Comparison table */}
                <div className="overflow-x-auto">
                  <table className="w-full text-xs">
                    <thead>
                      <tr className="border-b border-pw-border bg-gray-50/50">
                        <th className="text-left px-4 py-2 text-[10px] font-bold text-pw-muted uppercase tracking-wider">
                          Vendor
                        </th>
                        <th className="text-right px-4 py-2 text-[10px] font-bold text-pw-muted uppercase tracking-wider">
                          <span className="flex items-center justify-end gap-1">
                            <DollarSign className="w-3 h-3" /> Price
                          </span>
                        </th>
                        <th className="text-right px-4 py-2 text-[10px] font-bold text-pw-muted uppercase tracking-wider">
                          <span className="flex items-center justify-end gap-1">
                            <Timer className="w-3 h-3" /> Turnaround
                          </span>
                        </th>
                        <th className="text-left px-4 py-2 text-[10px] font-bold text-pw-muted uppercase tracking-wider">
                          <span className="flex items-center gap-1">
                            <StickyNote className="w-3 h-3" /> Notes
                          </span>
                        </th>
                        <th className="text-center px-4 py-2 text-[10px] font-bold text-pw-muted uppercase tracking-wider">
                          Status
                        </th>
                        <th className="text-center px-4 py-2 text-[10px] font-bold text-pw-muted uppercase tracking-wider">
                          Action
                        </th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-pw-border">
                      {group.bids.map((bid) => {
                        const isBestPrice = bestPrice != null && bid.price === bestPrice && bid.price != null;
                        const isFastest = bestTurnaround != null && bid.turnaroundDays === bestTurnaround && bid.turnaroundDays != null;
                        const canAccept = bid.status === 'QUOTED' || bid.status === 'PENDING';

                        return (
                          <tr
                            key={bid.id}
                            className={`transition-colors ${
                              bid.status === 'ACCEPTED'
                                ? 'bg-green-50/30'
                                : bid.status === 'CANCELLED'
                                  ? 'bg-gray-50/50 opacity-60'
                                  : 'hover:bg-gray-50/30'
                            }`}
                          >
                            <td className="px-4 py-3">
                              <div>
                                <span className="font-semibold text-pw-black block">
                                  {bid.vendorCompanyName || bid.vendorName}
                                </span>
                              </div>
                            </td>
                            <td className="px-4 py-3 text-right">
                              {bid.price != null ? (
                                <span className={`font-bold ${isBestPrice ? 'text-green-600' : 'text-pw-black'}`}>
                                  ${bid.price.toLocaleString()}
                                  {isBestPrice && group.bids.filter((b) => b.price != null).length > 1 && (
                                    <span className="block text-[9px] text-green-500 font-semibold">Best</span>
                                  )}
                                </span>
                              ) : (
                                <span className="text-pw-muted">—</span>
                              )}
                            </td>
                            <td className="px-4 py-3 text-right">
                              {bid.turnaroundDays != null && bid.turnaroundDays > 0 ? (
                                <span className={`font-bold ${isFastest ? 'text-blue-600' : 'text-pw-black'}`}>
                                  {bid.turnaroundDays}d
                                  {isFastest && group.bids.filter((b) => b.turnaroundDays != null && b.turnaroundDays > 0).length > 1 && (
                                    <span className="block text-[9px] text-blue-500 font-semibold">Fastest</span>
                                  )}
                                </span>
                              ) : (
                                <span className="text-pw-muted">—</span>
                              )}
                            </td>
                            <td className="px-4 py-3 max-w-[200px]">
                              {bid.notes ? (
                                <span className="text-pw-muted line-clamp-2">{bid.notes}</span>
                              ) : (
                                <span className="text-pw-muted/50 italic">—</span>
                              )}
                            </td>
                            <td className="px-4 py-3 text-center">
                              <StatusBadge status={bid.status} />
                            </td>
                            <td className="px-4 py-3 text-center">
                              {canAccept && !hasAccepted && (
                                <button
                                  onClick={() => handleAcceptBid(bid.id)}
                                  disabled={acceptingId === bid.id}
                                  className={`px-3 py-1 text-[10px] font-bold uppercase tracking-wider rounded transition-all flex items-center gap-1 mx-auto ${
                                    acceptingId === bid.id
                                      ? 'bg-gray-300 text-white cursor-not-allowed'
                                      : 'bg-[#7A9EAA] text-white hover:bg-[#688a95] shadow-sm'
                                  }`}
                                >
                                  {acceptingId === bid.id ? (
                                    <Loader2 className="w-3 h-3 animate-spin" />
                                  ) : (
                                    <Trophy className="w-3 h-3" />
                                  )}
                                  Assign
                                </button>
                              )}
                              {bid.status === 'ACCEPTED' && (
                                <span className="flex items-center gap-1 text-green-600 text-[10px] font-bold uppercase justify-center">
                                  <CheckCircle2 className="w-3 h-3" /> Assigned
                                </span>
                              )}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        /* ── Empty state ──────────────────────────────────────────────────── */
        !showIssuePanel && (
          <div className="text-center py-8 space-y-3">
            <div className="w-12 h-12 rounded-xl bg-gray-100 text-pw-muted flex items-center justify-center mx-auto">
              <FileText className="w-6 h-6" />
            </div>
            <p className="text-xs text-pw-muted">
              No RFPs issued yet — issue an RFP from any team slot above.
            </p>
            <button
              onClick={() => setShowIssuePanel(true)}
              className="px-4 py-2 text-[10px] font-bold uppercase tracking-wider bg-[#7A9EAA] text-white rounded hover:bg-[#688a95] transition-all shadow-sm"
            >
              Issue First RFP
            </button>
          </div>
        )
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Sparkles, Megaphone, User, Mail, Phone, Building, Trash2, Plus, ArrowUpRight, DollarSign, Calendar, CheckSquare } from 'lucide-react';
import toast from 'react-hot-toast';
import type { F4VendorAssignment, ListingAdLogEntry } from '@/types/schema';

interface Props {
  projectId: string;
  listPriceSale?: number; // cents
  listingAgentVendor?: F4VendorAssignment | null;
  listingAds?: ListingAdLogEntry[];
  onSaveListPrice: (price: number) => Promise<void>;
  onSaveListingAgent: (agent: F4VendorAssignment | null) => Promise<void>;
  onAddListingAd: (ad: ListingAdLogEntry) => Promise<void>;
  onUpdateAdStatus: (id: string, status: 'active' | 'paused' | 'removed') => Promise<void>;
  onDeleteListingAd: (id: string) => Promise<void>;
}

export function SaleGoToMarket({
  projectId,
  listPriceSale = 0,
  listingAgentVendor = null,
  listingAds = [],
  onSaveListPrice,
  onSaveListingAgent,
  onAddListingAd,
  onUpdateAdStatus,
  onDeleteListingAd
}: Props) {
  const [priceInput, setPriceInput] = useState(listPriceSale > 0 ? (listPriceSale / 100).toString() : '');
  const [showAgentForm, setShowAgentForm] = useState(false);
  const [agentName, setAgentName] = useState(listingAgentVendor?.name || '');
  const [agentCompany, setAgentCompany] = useState(listingAgentVendor?.firm || '');
  const [agentEmail, setAgentEmail] = useState(listingAgentVendor?.email || '');
  const [agentPhone, setAgentPhone] = useState(listingAgentVendor?.phone || '');

  const [showAddAd, setShowAddAd] = useState(false);
  const [adPlatform, setAdPlatform] = useState('MLS/Syndication');
  const [adPrice, setAdPrice] = useState(listPriceSale > 0 ? (listPriceSale / 100).toString() : '');
  const [adUrl, setAdUrl] = useState('');
  const [adDate, setAdDate] = useState(new Date().toISOString().slice(0, 10));

  const handleSavePrice = async () => {
    const val = parseFloat(priceInput.replace(/,/g, ''));
    if (isNaN(val) || val < 0) {
      toast.error('Please enter a valid target list price');
      return;
    }
    await onSaveListPrice(Math.round(val * 100));
    toast.success('Target sale list price updated');
  };

  const handleSaveAgent = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!agentName.trim() || !agentCompany.trim() || !agentEmail.trim()) {
      toast.error('Please fill in Name, Brokerage, and Email');
      return;
    }

    const newAgent: F4VendorAssignment = {
      name: agentName.trim(),
      firm: agentCompany.trim(),
      email: agentEmail.trim(),
      phone: agentPhone.trim() || null,
      source: 'off_platform',
      assignedAt: new Date().toISOString(),
      assignedBy: 'user'
    };

    await onSaveListingAgent(newAgent);
    setShowAgentForm(false);
    toast.success('Listing agent assigned successfully');
  };

  const handleRemoveAgent = async () => {
    if (confirm('Are you sure you want to remove the assigned listing agent?')) {
      await onSaveListingAgent(null);
      setAgentName('');
      setAgentCompany('');
      setAgentEmail('');
      setAgentPhone('');
      toast.success('Listing agent removed');
    }
  };

  const handleAddAdSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const val = parseFloat(adPrice.replace(/,/g, ''));
    if (isNaN(val) || val <= 0) {
      toast.error('Please enter a valid listing price');
      return;
    }

    const newAd: ListingAdLogEntry = {
      id: `ad-${Date.now()}`,
      platform: adPlatform,
      listingUrl: adUrl.trim() || null,
      status: 'active',
      listedDate: adDate,
      monthlyRent: Math.round(val * 100) // we reuse monthlyRent for listed price cents
    };

    await onAddListingAd(newAd);
    setAdUrl('');
    setShowAddAd(false);
    toast.success(`Property listed on ${adPlatform}`);
  };

  return (
    <div className="glass-card border border-white/5 rounded-xl p-5 space-y-6 text-left">
      {/* Header */}
      <div className="border-b border-white/5 pb-3">
        <span className="text-[10px] text-[#7A9EAA] uppercase font-bold tracking-wider">
          Go To Market (Card H5.S)
        </span>
        <h3 className="text-sm font-bold text-white uppercase tracking-wide mt-0.5">
          Sale Marketing &amp; Disposition
        </h3>
      </div>

      {/* Target List Price Section */}
      <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-3">
        <h4 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
          <DollarSign className="w-4 h-4 text-[#7A9EAA]" />
          Target List Price
        </h4>
        <p className="text-[11px] text-[#9E9DA0]">
          Set the expected public listing price for MLS syndication.
        </p>
        <div className="flex gap-2">
          <input
            type="text"
            placeholder="e.g. 350,000.00"
            value={priceInput}
            onChange={e => setPriceInput(e.target.value)}
            className="bg-black/35 border border-white/10 rounded-lg px-3 py-2 text-sm text-white w-full outline-none font-mono"
          />
          <button
            onClick={handleSavePrice}
            className="text-xs font-bold bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white px-4 py-2 rounded-lg transition shrink-0"
          >
            Save Price
          </button>
        </div>
      </div>

      {/* Listing Agent Slot Section */}
      <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-4">
        <div className="flex justify-between items-center">
          <h4 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
            <User className="w-4 h-4 text-[#7A9EAA]" />
            Listing Agent Slot
          </h4>
          {!listingAgentVendor && !showAgentForm && (
            <button
              onClick={() => setShowAgentForm(true)}
              className="text-[10px] font-bold text-[#7A9EAA] hover:underline"
            >
              + Assign Agent
            </button>
          )}
        </div>

        {listingAgentVendor ? (
          <div className="flex justify-between items-start bg-black/20 border border-white/5 p-3 rounded-lg text-xs">
            <div className="space-y-1">
              <p className="font-bold text-white text-sm">{listingAgentVendor.name}</p>
              <div className="flex items-center gap-1.5 text-[#9E9DA0]">
                <Building className="w-3.5 h-3.5 text-[#7A9EAA]" />
                <span>{listingAgentVendor.firm}</span>
              </div>
              <div className="flex items-center gap-1.5 text-[#9E9DA0]">
                <Mail className="w-3.5 h-3.5 text-[#7A9EAA]" />
                <span>{listingAgentVendor.email}</span>
              </div>
              {listingAgentVendor.phone && (
                <div className="flex items-center gap-1.5 text-[#9E9DA0]">
                  <Phone className="w-3.5 h-3.5 text-[#7A9EAA]" />
                  <span>{listingAgentVendor.phone}</span>
                </div>
              )}
            </div>
            <button
              onClick={handleRemoveAgent}
              className="text-[#9E9DA0] hover:text-red-400 p-0.5"
              title="Remove Agent"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ) : showAgentForm ? (
          <form onSubmit={handleSaveAgent} className="bg-black/20 border border-white/10 p-3 rounded-lg space-y-3">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Agent Name</label>
                <input
                  type="text"
                  required
                  placeholder="John Doe"
                  value={agentName}
                  onChange={e => setAgentName(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2.5 py-1.5 text-xs text-white w-full outline-none"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Brokerage / Company</label>
                <input
                  type="text"
                  required
                  placeholder="Apex Real Estate Brokerage"
                  value={agentCompany}
                  onChange={e => setAgentCompany(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2.5 py-1.5 text-xs text-white w-full outline-none"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Email Address</label>
                <input
                  type="email"
                  required
                  placeholder="john.doe@brokerage.com"
                  value={agentEmail}
                  onChange={e => setAgentEmail(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2.5 py-1.5 text-xs text-white w-full outline-none"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Phone (Optional)</label>
                <input
                  type="text"
                  placeholder="(555) 019-2834"
                  value={agentPhone}
                  onChange={e => setAgentPhone(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2.5 py-1.5 text-xs text-white w-full outline-none"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-1 text-[10px]">
              <button
                type="button"
                onClick={() => setShowAgentForm(false)}
                className="text-[#9E9DA0] hover:underline"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white font-bold px-3 py-1.5 rounded"
              >
                Assign Agent
              </button>
            </div>
          </form>
        ) : (
          <div className="py-4 text-center border border-dashed border-white/5 rounded-lg">
            <p className="text-xs text-[#9E9DA0]/50">No listing agent assigned. Click "+ Assign Agent" to add brokerage details.</p>
          </div>
        )}
      </div>

      {/* Listing / Ad Log Section */}
      <div className="bg-white/5 border border-white/5 p-4 rounded-xl space-y-4">
        <div className="flex justify-between items-center">
          <h4 className="text-xs font-bold text-white uppercase tracking-wider flex items-center gap-1.5">
            <Megaphone className="w-4 h-4 text-[#7A9EAA]" />
            MLS &amp; Syndication Portals
          </h4>
          <button
            onClick={() => setShowAddAd(!showAddAd)}
            className="text-[10px] font-bold text-[#7A9EAA] hover:underline"
          >
            {showAddAd ? 'Cancel' : '+ Log Listing'}
          </button>
        </div>

        {showAddAd && (
          <form onSubmit={handleAddAdSubmit} className="bg-black/20 border border-white/10 p-3 rounded-lg space-y-3">
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Platform</label>
                <select
                  value={adPlatform}
                  onChange={e => setAdPlatform(e.target.value)}
                  className="bg-[#121014] border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none"
                >
                  <option value="MLS/Syndication">MLS / Syndication</option>
                  <option value="Redfin">Redfin</option>
                  <option value="Zillow">Zillow</option>
                  <option value="Realtor.com">Realtor.com</option>
                  <option value="Trulia">Trulia</option>
                  <option value="MLS Private Network">MLS Private Network</option>
                  <option value="Other">Other</option>
                </select>
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Listed Price ($)</label>
                <input
                  type="text"
                  required
                  placeholder="e.g. 350000"
                  value={adPrice}
                  onChange={e => setAdPrice(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none font-mono"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Listed Date</label>
                <input
                  type="date"
                  required
                  value={adDate}
                  onChange={e => setAdDate(e.target.value)}
                  className="bg-black/30 border border-white/10 rounded-lg px-2 py-1.5 text-xs text-white w-full outline-none filter invert"
                />
              </div>
            </div>

            <div className="space-y-1">
              <label className="text-[9px] uppercase font-bold text-[#9E9DA0]">Listing URL (Optional)</label>
              <input
                type="url"
                placeholder="https://redfin.com/homes/..."
                value={adUrl}
                onChange={e => setAdUrl(e.target.value)}
                className="bg-black/30 border border-white/10 rounded-lg px-3 py-1.5 text-xs text-white w-full outline-none"
              />
            </div>

            <div className="flex justify-end gap-2 pt-1 text-[10px]">
              <button
                type="button"
                onClick={() => setShowAddAd(false)}
                className="text-[#9E9DA0] hover:underline"
              >
                Cancel
              </button>
              <button
                type="submit"
                className="bg-[#7A9EAA] hover:bg-[#7A9EAA]/80 text-white font-bold px-3 py-1.5 rounded"
              >
                Log Listing
              </button>
            </div>
          </form>
        )}

        {listingAds.length === 0 ? (
          <div className="py-4 text-center border border-dashed border-white/5 rounded-lg">
            <p className="text-xs text-[#9E9DA0]/50">No property listings logged yet.</p>
          </div>
        ) : (
          <div className="space-y-2">
            {listingAds.map(ad => (
              <div key={ad.id} className="flex justify-between items-center bg-black/20 border border-white/5 p-2.5 rounded-lg text-xs">
                <div>
                  <div className="flex items-center gap-2">
                    <span className="font-bold text-white">{ad.platform}</span>
                    <span className="text-mono text-[#9E9DA0]">
                      ${(ad.monthlyRent / 100).toLocaleString()}
                    </span>
                  </div>
                  <div className="flex items-center gap-2 mt-1">
                    <span className="text-[9px] text-[#9E9DA0]">
                      Listed: {new Date(ad.listedDate).toLocaleDateString()}
                    </span>
                    {ad.listingUrl && (
                      <a
                        href={ad.listingUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="text-[9px] text-[#7A9EAA] hover:underline flex items-center gap-0.5"
                      >
                        View Listing <ArrowUpRight className="w-2.5 h-2.5" />
                      </a>
                    )}
                  </div>
                </div>

                <div className="flex items-center gap-3">
                  <select
                    value={ad.status}
                    onChange={e => onUpdateAdStatus(ad.id, e.target.value as any)}
                    className="bg-[#121014] border border-white/10 rounded px-1.5 py-1 text-[10px] text-white outline-none"
                  >
                    <option value="active">Active</option>
                    <option value="paused">Paused</option>
                    <option value="removed">Removed</option>
                  </select>
                  <button
                    onClick={() => onDeleteListingAd(ad.id)}
                    className="text-[#9E9DA0] hover:text-red-400 p-0.5"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import React, { useState, useRef } from 'react';
import { 
  Sparkles, DollarSign, Calendar, Check, AlertTriangle, 
  FileText, Lock, Plus, Trash2, ArrowUpRight, UploadCloud, Loader2
} from 'lucide-react';
import { Project, ProjectFinancials, Contingency, RoleLinkedDocument } from '@/types/schema';
import { useProjectStore } from '@/store/projectStore';
import { projectsService } from '@/lib/firebase/deals';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import { storage, auth as firebaseAuth } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import { IS_DEMO_MODE } from '@/lib/config/demo';
import toast from 'react-hot-toast';

interface SaleOperationsCardProps {
  project: Project;
  refresh: () => void;
  isLocked?: boolean;
}

export default function SaleOperationsCard({ project, refresh, isLocked = false }: SaleOperationsCardProps) {
  const { user } = useAuth();
  const financials = project.financials || {};
  const updateProjectFinancials = useProjectStore(state => state.updateProjectFinancials);

  // Component UI state
  const [isMarkingUnderContract, setIsMarkingUnderContract] = useState(false);
  const [contractPrice, setContractPrice] = useState('');
  const [targetClosingDate, setTargetClosingDate] = useState('');

  // Closing execution form states
  const [isClosingSale, setIsClosingSale] = useState(false);
  const [finalSalePrice, setFinalSalePrice] = useState(
    financials.sale_price ? financials.sale_price.toString() : ''
  );
  const [finalSellingCosts, setFinalSellingCosts] = useState(
    financials.selling_costs ? financials.selling_costs.toString() : ''
  );
  const [finalClosingDate, setFinalClosingDate] = useState(
    financials.sale_closed_date || ''
  );

  // Loading/Uploading states
  const [isSaving, setIsSaving] = useState(false);
  const [uploadingDocType, setUploadingDocType] = useState<string | null>(null);

  // Custom Contingency inputs
  const [showAddContingency, setShowAddContingency] = useState(false);
  const [customType, setCustomType] = useState('Inspection');
  const [customDays, setCustomDays] = useState('10');
  const [customParty, setCustomParty] = useState<'Buyer' | 'Seller'>('Buyer');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeUploadCategory, setActiveUploadCategory] = useState<string | null>(null);

  const saleUnderContract = financials.sale_under_contract || false;
  const saleClosed = !!(financials.sale_price && financials.sale_closed_date);

  // ── Transition to Under Contract ─────────────────────────────────────────
  const handleMarkUnderContract = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!contractPrice) {
      toast.error('Please enter a contract price');
      return;
    }

    setIsSaving(true);
    try {
      const priceNum = parseFloat(contractPrice.replace(/[^0-9.]/g, ''));
      if (isNaN(priceNum)) throw new Error('Invalid contract price');

      // Initialize default contingencies
      const today = new Date();
      const createContingency = (type: string, daysOut: number): Contingency => {
        const d = new Date(today);
        d.setDate(d.getDate() + daysOut);
        return {
          id: crypto.randomUUID(),
          type,
          deadlineDate: d,
          isSatisfied: false,
          isWaived: false,
          party: 'Buyer',
          reminderSettings: ['T-7', 'T-3', 'T-1'],
        };
      };

      const defaultContingencies = [
        createContingency('Inspection', 10),
        createContingency('Appraisal', 14),
        createContingency('Financing', 21),
      ];

      await updateProjectFinancials(project.id, {
        sale_under_contract: true,
        sale_contract_price: priceNum,
        sale_buyer_contingencies: defaultContingencies,
      });

      toast.success('Property is now under contract');
      setIsMarkingUnderContract(false);
      refresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to update contract status');
    } finally {
      setIsSaving(false);
    }
  };

  // ── Contingency helpers ───────────────────────────────────────────────────
  const handleUpdateContingency = async (id: string, updates: Partial<Contingency>) => {
    const list = financials.sale_buyer_contingencies || [];
    const updated = list.map(c => c.id === id ? { ...c, ...updates } : c);

    try {
      await updateProjectFinancials(project.id, {
        sale_buyer_contingencies: updated
      });
      toast.success('Contingency status updated');
      refresh();
    } catch (err: any) {
      toast.error('Failed to update contingency');
    }
  };

  const handleAddCustomContingency = async (e: React.FormEvent) => {
    e.preventDefault();
    const daysNum = parseInt(customDays);
    if (isNaN(daysNum)) return;

    const today = new Date();
    today.setDate(today.getDate() + daysNum);

    const newContingency: Contingency = {
      id: crypto.randomUUID(),
      type: customType,
      deadlineDate: today,
      isSatisfied: false,
      isWaived: false,
      party: customParty,
      reminderSettings: ['T-3', 'T-1'],
    };

    const updated = [...(financials.sale_buyer_contingencies || []), newContingency];

    try {
      await updateProjectFinancials(project.id, {
        sale_buyer_contingencies: updated
      });
      toast.success('Custom contingency added');
      setShowAddContingency(false);
      refresh();
    } catch (err: any) {
      toast.error('Failed to add contingency');
    }
  };

  const handleDeleteContingency = async (id: string) => {
    const updated = (financials.sale_buyer_contingencies || []).filter(c => c.id !== id);
    try {
      await updateProjectFinancials(project.id, {
        sale_buyer_contingencies: updated
      });
      toast.success('Contingency removed');
      refresh();
    } catch (err: any) {
      toast.error('Failed to remove contingency');
    }
  };

  const formatDeadlineDate = (deadlineDate: any) => {
    if (!deadlineDate) return '';
    const date = deadlineDate instanceof Date 
      ? deadlineDate 
      : deadlineDate.toDate 
        ? deadlineDate.toDate() 
        : new Date(deadlineDate);
    return isNaN(date.getTime()) ? '' : date.toLocaleDateString();
  };

  const calculateDaysRemaining = (deadlineDate: any) => {
    if (!deadlineDate) return 0;
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const deadline = deadlineDate instanceof Date
      ? deadlineDate
      : deadlineDate.toDate
        ? deadlineDate.toDate()
        : new Date(deadlineDate);

    if (isNaN(deadline.getTime())) return 0;
    deadline.setHours(0, 0, 0, 0);

    const diffTime = deadline.getTime() - today.getTime();
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
  };

  // ── Document management ───────────────────────────────────────────────────
  const getDocumentByCategory = (category: string) => {
    return (project.roleLinkedDocuments || []).find(d => d.category === category);
  };

  const triggerFileUpload = (category: string) => {
    setActiveUploadCategory(category);
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeUploadCategory) return;

    setUploadingDocType(activeUploadCategory);
    const toastId = toast.loading(`Uploading ${file.name}...`);

    try {
      let downloadURL = '';

      if (IS_DEMO_MODE) {
        downloadURL = `/mock/documents/${file.name}`;
      } else {
        const uploadId = crypto.randomUUID();
        const fileRef = ref(storage, `projects/${project.id}/sale/${uploadId}_${file.name}`);
        const uploadTask = uploadBytesResumable(fileRef, file);

        downloadURL = await new Promise((resolve, reject) => {
          uploadTask.on(
            'state_changed',
            null,
            (error) => reject(error),
            async () => {
              const url = await getDownloadURL(uploadTask.snapshot.ref);
              resolve(url);
            }
          );
        });
      }

      const updatedDocs = [...(project.roleLinkedDocuments || [])];
      const matchIndex = updatedDocs.findIndex(d => d.category === activeUploadCategory);

      const newDoc: RoleLinkedDocument = {
        id: matchIndex >= 0 ? updatedDocs[matchIndex].id : crypto.randomUUID(),
        category: activeUploadCategory as any,
        fileName: file.name,
        fileUrl: downloadURL,
        linkedRole: 'Closing Agent',
        uploadedByUid: user?.uid || 'user_123',
        uploadedByName: user?.displayName || user?.email || 'Lead Investor',
        uploadedAt: new Date(),
        verified: true,
        notes: `Uploaded for sale close-out`,
      };

      if (matchIndex >= 0) {
        updatedDocs[matchIndex] = newDoc;
      } else {
        updatedDocs.push(newDoc);
      }

      await projectsService.updateProject(project.id, {
        roleLinkedDocuments: updatedDocs
      });

      toast.success(`${activeUploadCategory} uploaded successfully`, { id: toastId });
      refresh();
    } catch (err: any) {
      console.error(err);
      toast.error('Failed to upload document', { id: toastId });
    } finally {
      setUploadingDocType(null);
      setActiveUploadCategory(null);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // ── Finalize Close of Sale ────────────────────────────────────────────────
  const handleFinalizeClose = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!finalSalePrice || !finalClosingDate) {
      toast.error('Please fill in closing price and date');
      return;
    }

    // Verify documents are uploaded
    const hasContract = !!getDocumentByCategory('Buyer Agreements');
    const hasSettlement = !!getDocumentByCategory('Final Settlement Statement');
    const hasDeed = !!getDocumentByCategory('Deed');

    if (!hasContract || !hasSettlement || !hasDeed) {
      toast.error('Please upload all required closing documents: Sale Contract, Settlement Statement, and Deed Out');
      return;
    }

    setIsSaving(true);
    try {
      const priceNum = parseFloat(finalSalePrice.replace(/[^0-9.]/g, ''));
      const costsNum = parseFloat(finalSellingCosts.replace(/[^0-9.]/g, '')) || 0;

      if (isNaN(priceNum)) throw new Error('Invalid sale price');

      // Update financials and mark project as realized/sold
      await updateProjectFinancials(project.id, {
        sale_price: priceNum,
        selling_costs: costsNum,
        sale_closed_date: finalClosingDate,
        actualSalePrice: priceNum, // Sync actualSalePrice for ccim engine
        sellingCosts: costsNum,
        soldDate: finalClosingDate as any,
      });

      // Update main project status to "exit"
      await projectsService.updateProject(project.id, {
        status: 'exit',
        phaseStatus: 'Phase 4: Exit',
      });

      toast.success('🎉 Transaction Closed! Property is officially Realized.');
      setIsClosingSale(false);
      refresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to finalize transaction');
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <div 
      className="grid grid-cols-1 lg:grid-cols-12 gap-6"
      style={{ color: 'var(--text-primary)' }}
    >
      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleFileChange} 
        className="hidden" 
        accept=".pdf,.png,.jpg,.jpeg,.doc,.docx"
      />

      {/* Left Column: Transaction Details */}
      <div 
        className="lg:col-span-5 rounded-[8px] border overflow-hidden"
        style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}
      >
        <div 
          className="px-6 py-4 border-b flex justify-between items-center"
          style={{ borderColor: 'var(--border-ui)' }}
        >
          <div>
            <h3 className="text-sm font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
              <FileText className="w-4 h-4 text-amber-500" />
              E1.S Sale Operations
            </h3>
            <p className="text-[10px] uppercase tracking-[0.15em] mt-0.5 text-[var(--text-tertiary)]">
              Handle property contract status and transaction closeout
            </p>
          </div>
          <div>
            {saleClosed ? (
              <span className="px-2.5 py-1 rounded-full text-[9px] font-bold uppercase tracking-wider bg-emerald-500/10 text-emerald-400 border border-emerald-500/20">
                Closed
              </span>
            ) : saleUnderContract ? (
              <span className="px-2.5 py-1 rounded-full text-[9px] font-bold uppercase tracking-wider bg-amber-500/10 text-amber-400 border border-amber-500/20 animate-pulse">
                Under Contract
              </span>
            ) : (
              <span className="px-2.5 py-1 rounded-full text-[9px] font-bold uppercase tracking-wider bg-white/5 text-[var(--text-secondary)] border border-white/10">
                Listed
              </span>
            )}
          </div>
        </div>

        {/* ─── STAGE 1: LISTED ─── */}
        {!saleUnderContract && !saleClosed && (
          <div className="p-6 space-y-6">
            {!isMarkingUnderContract ? (
              <div className="space-y-4">
                <p className="text-xs text-[var(--text-secondary)] leading-relaxed">
                  The property is currently marketed for sale. Once an offer is accepted and a formal contract is executed, transition this project to the Under Contract state to track due diligence timelines.
                </p>
                {!isLocked && (
                  <button
                    onClick={() => setIsMarkingUnderContract(true)}
                    className="w-full py-2.5 rounded text-[10px] font-bold uppercase tracking-widest bg-[var(--text-primary)] text-[var(--bg-surface)] hover:opacity-90 transition-all flex items-center justify-center gap-1.5"
                  >
                    <ArrowUpRight className="w-3.5 h-3.5" />
                    Mark Under Contract
                  </button>
                )}
              </div>
            ) : (
              <form onSubmit={handleMarkUnderContract} className="space-y-4">
                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">Contract Price ($)</label>
                  <input
                    type="number"
                    value={contractPrice}
                    onChange={e => setContractPrice(e.target.value)}
                    placeholder="e.g. 450000"
                    className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
                    required
                  />
                </div>
                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={() => setIsMarkingUnderContract(false)}
                    className="w-1/2 py-2 rounded text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)] hover:bg-white/5 border border-white/10"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    className="w-1/2 py-2 rounded text-[10px] font-bold uppercase tracking-widest bg-amber-500 text-black hover:bg-amber-600 transition-all"
                  >
                    Confirm Contract
                  </button>
                </div>
              </form>
            )}
          </div>
        )}

        {/* ─── STAGE 2: UNDER CONTRACT ─── */}
        {saleUnderContract && !saleClosed && (
          <div className="p-6 space-y-6">
            <div>
              <span className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-tertiary)]">Escrow Contract Price</span>
              <p className="text-2xl font-bold tracking-tight text-[var(--text-primary)] mt-1">
                ${financials.sale_contract_price?.toLocaleString() || '0'}
              </p>
            </div>

            {!isClosingSale ? (
              <div className="space-y-4">
                <p className="text-xs text-[var(--text-secondary)] leading-relaxed">
                  Due diligence checks are ongoing. Once all contingencies have been completed/satisfied and escrow closing statements are ready, initiate the transaction close.
                </p>
                {!isLocked && (
                  <button
                    onClick={() => setIsClosingSale(true)}
                    className="w-full py-2.5 rounded text-[10px] font-bold uppercase tracking-widest bg-emerald-500 text-white hover:bg-emerald-600 transition-all flex items-center justify-center gap-1.5"
                  >
                    <Check className="w-3.5 h-3.5" />
                    Close Sale
                  </button>
                )}
              </div>
            ) : (
              <form onSubmit={handleFinalizeClose} className="space-y-4">
                <h4 className="text-xs font-bold uppercase tracking-wider text-[var(--text-primary)]">Log Transaction Closing Terms</h4>

                <div className="space-y-1">
                  <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">Final Sale Price ($)</label>
                  <input
                    type="number"
                    value={finalSalePrice}
                    onChange={e => setFinalSalePrice(e.target.value)}
                    placeholder="e.g. 450000"
                    className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
                    required
                  />
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">Selling Costs / Fee ($)</label>
                    <input
                      type="number"
                      value={finalSellingCosts}
                      onChange={e => setFinalSellingCosts(e.target.value)}
                      placeholder="e.g. 24000"
                      className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
                    />
                  </div>
                  <div className="space-y-1">
                    <label className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">Closing Date</label>
                    <input
                      type="date"
                      value={finalClosingDate}
                      onChange={e => setFinalClosingDate(e.target.value)}
                      className="glass-input w-full text-xs py-2.5 px-3 focus:outline-none"
                      required
                    />
                  </div>
                </div>

                {/* Upload documentation reminder inside Close Sale Form */}
                <div className="p-3 rounded bg-[rgba(255,255,255,0.02)] border border-white/5 space-y-2">
                  <span className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)] block">Required Documents before Close:</span>
                  <div className="space-y-1 text-xs">
                    <div className="flex justify-between items-center">
                      <span className="text-[var(--text-tertiary)]">Sale Contract</span>
                      {getDocumentByCategory('Buyer Agreements') ? (
                        <span className="text-emerald-400 text-[10px] font-bold flex items-center gap-1">
                          <Check className="w-3 h-3" /> Uploaded
                        </span>
                      ) : (
                        <span className="text-rose-400 text-[10px] font-bold">Missing</span>
                      )}
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-[var(--text-tertiary)]">Settlement Statement</span>
                      {getDocumentByCategory('Final Settlement Statement') ? (
                        <span className="text-emerald-400 text-[10px] font-bold flex items-center gap-1">
                          <Check className="w-3 h-3" /> Uploaded
                        </span>
                      ) : (
                        <span className="text-rose-400 text-[10px] font-bold">Missing</span>
                      )}
                    </div>
                    <div className="flex justify-between items-center">
                      <span className="text-[var(--text-tertiary)]">Deed Out</span>
                      {getDocumentByCategory('Deed') ? (
                        <span className="text-emerald-400 text-[10px] font-bold flex items-center gap-1">
                          <Check className="w-3 h-3" /> Uploaded
                        </span>
                      ) : (
                        <span className="text-rose-400 text-[10px] font-bold">Missing</span>
                      )}
                    </div>
                  </div>
                </div>

                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={() => setIsClosingSale(false)}
                    className="w-1/2 py-2 rounded text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)] hover:bg-white/5 border border-white/10"
                  >
                    Back
                  </button>
                  <button
                    type="submit"
                    className="w-1/2 py-2 rounded text-[10px] font-bold uppercase tracking-widest bg-emerald-500 text-white hover:bg-emerald-600 transition-all"
                  >
                    Confirm Close
                  </button>
                </div>
              </form>
            )}
          </div>
        )}

        {/* ─── STAGE 3: CLOSED STATE ─── */}
        {saleClosed && (
          <div className="p-6 space-y-6">
            <div className="p-4 rounded-lg bg-[rgba(16,185,129,0.03)] border border-emerald-500/20 space-y-4">
              <span className="text-[10px] font-bold uppercase tracking-widest text-emerald-400 flex items-center gap-1.5">
                <Check className="w-3.5 h-3.5" />
                Transaction Finalized
              </span>

              <div className="grid grid-cols-2 gap-4 text-xs">
                <div>
                  <span className="text-[var(--text-tertiary)] block">Sale Price</span>
                  <span className="font-bold text-[var(--text-primary)] text-sm">${financials.sale_price?.toLocaleString()}</span>
                </div>
                <div>
                  <span className="text-[var(--text-tertiary)] block">Selling Costs</span>
                  <span className="font-bold text-[var(--text-primary)] text-sm">${financials.selling_costs?.toLocaleString()}</span>
                </div>
                <div>
                  <span className="text-[var(--text-tertiary)] block">Closing Date</span>
                  <span className="font-bold text-[var(--text-primary)] text-sm">{financials.sale_closed_date}</span>
                </div>
                <div>
                  <span className="text-[var(--text-tertiary)] block">Realized Net Profit</span>
                  <span className="font-bold text-emerald-400 text-sm">
                    ${(project as any).realizedNetProceeds?.toLocaleString() || financials.realizedNetProceeds?.toLocaleString() || '0'}
                  </span>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Right Column: Contingency Tracker & Document Vault uploads */}
      <div 
        className="lg:col-span-7 rounded-[8px] border overflow-hidden flex flex-col"
        style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}
      >
        <div 
          className="px-6 py-4 border-b flex justify-between items-center"
          style={{ borderColor: 'var(--border-ui)' }}
        >
          <div>
            <h3 className="text-sm font-bold tracking-tight text-[var(--text-primary)] flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-emerald-500" />
              Contingencies &amp; Closing Docs
            </h3>
            <p className="text-[10px] uppercase tracking-[0.15em] mt-0.5 text-[var(--text-tertiary)]">
              Validate contract checks and upload finalized escrow documents
            </p>
          </div>
        </div>

        <div className="p-6 space-y-6 flex-1 flex flex-col justify-between">
          {/* Buyer Contingency Checklist */}
          {saleUnderContract && (
            <div className="space-y-4">
              <div className="flex justify-between items-center">
                <span className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">Buyer Contingency Deadlines</span>
                {!isLocked && !saleClosed && (
                  <button
                    onClick={() => setShowAddContingency(!showAddContingency)}
                    className="flex items-center gap-1 px-2 py-1 rounded bg-white/5 border border-white/10 text-[9px] font-bold uppercase tracking-wider text-[var(--text-primary)]"
                  >
                    <Plus className="w-3 h-3" /> Add Custom
                  </button>
                )}
              </div>

              {showAddContingency && (
                <form onSubmit={handleAddCustomContingency} className="p-3.5 rounded bg-[rgba(255,255,255,0.02)] border border-white/5 space-y-3">
                  <div className="grid grid-cols-2 gap-3">
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold uppercase tracking-widest text-[var(--text-tertiary)]">Contingency Type</label>
                      <select
                        value={customType}
                        onChange={e => setCustomType(e.target.value)}
                        className="glass-input w-full text-xs py-1.5 px-2 bg-[var(--bg-surface)] text-[var(--text-primary)]"
                      >
                        <option value="Inspection">Inspection</option>
                        <option value="Appraisal">Appraisal</option>
                        <option value="Financing">Financing</option>
                        <option value="Survey">Survey</option>
                        <option value="Custom">Custom</option>
                      </select>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold uppercase tracking-widest text-[var(--text-tertiary)]">Days Until Deadline</label>
                      <input
                        type="number"
                        value={customDays}
                        onChange={e => setCustomDays(e.target.value)}
                        className="glass-input w-full text-xs py-1.5 px-2"
                        required
                      />
                    </div>
                  </div>
                  <div className="flex justify-end gap-2">
                    <button
                      type="button"
                      onClick={() => setShowAddContingency(false)}
                      className="px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider text-[var(--text-secondary)]"
                    >
                      Cancel
                    </button>
                    <button
                      type="submit"
                      className="px-2.5 py-1 text-[9px] font-bold uppercase tracking-wider bg-[var(--text-primary)] text-[var(--bg-surface)] rounded"
                    >
                      Add
                    </button>
                  </div>
                </form>
              )}

              <div className="space-y-2">
                {(financials.sale_buyer_contingencies || []).map((c) => {
                  const days = calculateDaysRemaining(c.deadlineDate);
                  const isDone = c.isSatisfied || c.isWaived;
                  return (
                    <div 
                      key={c.id}
                      className="p-3 rounded bg-[var(--bg-canvas)] border border-[var(--border-ui)] flex items-center justify-between"
                    >
                      <div className="flex items-center gap-3">
                        <input
                          type="checkbox"
                          checked={c.isSatisfied || false}
                          disabled={isLocked || saleClosed}
                          onChange={(e) => handleUpdateContingency(c.id, { isSatisfied: e.target.checked })}
                          className="w-4 h-4 rounded text-amber-500 focus:ring-amber-500 focus:ring-offset-0 bg-transparent border-[var(--border-ui)]"
                        />
                        <div>
                          <p className={`text-xs font-bold ${isDone ? 'line-through text-[var(--text-tertiary)]' : 'text-[var(--text-primary)]'}`}>
                            {c.type} Contingency
                          </p>
                          <p className="text-[10px] text-[var(--text-tertiary)] mt-0.5">
                            Deadline: {formatDeadlineDate(c.deadlineDate)}
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center gap-3">
                        {!isDone && (
                          <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider ${
                            days <= 3 ? 'bg-rose-500/10 text-rose-400' : 'bg-amber-500/10 text-amber-400'
                          }`}>
                            {days <= 0 ? 'Overdue' : `${days}d left`}
                          </span>
                        )}
                        {isDone && (
                          <span className="px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-wider bg-emerald-500/10 text-emerald-400">
                            Completed
                          </span>
                        )}
                        {!isLocked && !saleClosed && (
                          <button
                            onClick={() => handleDeleteContingency(c.id)}
                            className="p-1 rounded text-[var(--text-tertiary)] hover:text-rose-400"
                          >
                            <Trash2 className="w-3.5 h-3.5" />
                          </button>
                        )}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {!saleUnderContract && !saleClosed && (
            <div className="flex-1 flex items-center justify-center py-10 border border-dashed border-white/5 rounded-lg">
              <span className="text-[10px] uppercase tracking-wider text-[var(--text-tertiary)]">Contingency Tracker is Active when property is under contract</span>
            </div>
          )}

          {/* Document Vault Uploads Checklist */}
          <div className="space-y-4 pt-4 border-t border-white/5 flex-1 justify-end flex flex-col">
            <span className="text-[10px] font-bold uppercase tracking-widest text-[var(--text-secondary)]">Required Exit Documents</span>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-3">
              {[
                { category: 'Buyer Agreements', label: 'Sale Contract' },
                { category: 'Final Settlement Statement', label: 'Settlement Statement' },
                { category: 'Deed', label: 'Deed Out' }
              ].map((docItem) => {
                const docFile = getDocumentByCategory(docItem.category);
                const isUploading = uploadingDocType === docItem.category;

                return (
                  <div 
                    key={docItem.category}
                    className="p-3 rounded bg-[var(--bg-canvas)] border border-[var(--border-ui)] flex flex-col justify-between h-28"
                  >
                    <div>
                      <span className="text-[10px] font-bold uppercase tracking-wider text-[var(--text-primary)] block">
                        {docItem.label}
                      </span>
                      {docFile ? (
                        <span className="text-[9px] text-[var(--text-tertiary)] truncate block mt-1 max-w-full">
                          {docFile.fileName}
                        </span>
                      ) : (
                        <span className="text-[9px] text-rose-400 block mt-1">
                          Missing file
                        </span>
                      )}
                    </div>

                    {!isLocked && !saleClosed ? (
                      <button
                        onClick={() => triggerFileUpload(docItem.category)}
                        disabled={isUploading}
                        className="w-full py-1.5 rounded bg-white/5 border border-white/10 text-[9px] font-bold uppercase tracking-widest text-[var(--text-secondary)] hover:bg-white/10 transition-all flex items-center justify-center gap-1"
                      >
                        {isUploading ? (
                          <Loader2 className="w-3 h-3 animate-spin" />
                        ) : (
                          <UploadCloud className="w-3 h-3" />
                        )}
                        {docFile ? 'Replace' : 'Upload'}
                      </button>
                    ) : docFile ? (
                      <a
                        href={docFile.fileUrl}
                        target="_blank"
                        rel="noreferrer"
                        className="w-full py-1.5 rounded bg-emerald-500/10 border border-emerald-500/20 text-[9px] font-bold uppercase tracking-widest text-emerald-400 text-center block"
                      >
                        Download
                      </a>
                    ) : (
                      <span className="text-[9px] text-[var(--text-tertiary)] text-center py-1 block">
                        No doc
                      </span>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

