          </button>
        ) : (
          <button
            onClick={handleSubmit}
            disabled={!injectionTier || submitting}
            className={`px-5 py-2 text-xs font-semibold uppercase tracking-wider flex items-center gap-1.5 rounded transition-all ${
              !injectionTier || submitting
