    </div>
  );
}

import React, { useState } from 'react';
import { SiteVisitLog } from '@/types/schema';
import { Plus, ClipboardCheck, Trash2, Check, AlertTriangle } from 'lucide-react';
import toast from 'react-hot-toast';

interface SiteVisitLogTrackerProps {
  logs: SiteVisitLog[];
  onChange: (logs: SiteVisitLog[]) => void;
}

const VISIT_TYPES = ['Daily Check', 'Weekly Inspection', 'Milestone Review', 'Issue Report'] as const;

export function SiteVisitLogTracker({ logs, onChange }: SiteVisitLogTrackerProps) {
  const [isAdding, setIsAdding] = useState(false);
  const [newLog, setNewLog] = useState<Partial<SiteVisitLog>>({
    type: 'Weekly Inspection',
    visitedBy: '',
    notes: '',
    issuesFound: 0,
    photosUploaded: 0,
    resolved: false,
  });

  const handleAdd = () => {
    if (!newLog.visitedBy || !newLog.notes) {
      toast.error('Visitor name and notes are required');
      return;
    }

    const log: SiteVisitLog = {
      id: crypto.randomUUID(),
      date: new Date(),
      type: newLog.type as any,
      visitedBy: newLog.visitedBy,
      notes: newLog.notes,
      issuesFound: Number(newLog.issuesFound) || 0,
      photosUploaded: Number(newLog.photosUploaded) || 0,
      resolved: newLog.issuesFound && newLog.issuesFound > 0 ? (newLog.resolved || false) : true,
    };

    onChange([log, ...logs]);
    setIsAdding(false);
    setNewLog({
      type: 'Weekly Inspection',
      visitedBy: '',
      notes: '',
      issuesFound: 0,
      photosUploaded: 0,
      resolved: false,
    });
    toast.success('Site visit log added');
  };

  const handleDelete = (id: string) => {
    onChange(logs.filter(l => l.id !== id));
    toast.success('Visit log removed');
  };

  const toggleResolved = (id: string, currentResolved: boolean) => {
    onChange(logs.map(l => 
      l.id === id ? { ...l, resolved: !currentResolved } : l
    ));
  };

  const totalIssues = logs.reduce((sum, l) => sum + l.issuesFound, 0);
  const unresolvedIssues = logs.filter(l => !l.resolved && l.issuesFound > 0).reduce((sum, l) => sum + l.issuesFound, 0);

  return (
    <div className="p-6 rounded-lg shadow-sm border" style={{ backgroundColor: 'var(--bg-surface)', borderColor: 'var(--border-ui)' }}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <ClipboardCheck className="w-5 h-5" style={{ color: 'var(--text-secondary)' }} />
          <h2 className="text-lg font-semibold" style={{ color: 'var(--text-primary)' }}>Site Visit Logs</h2>
        </div>
        <div className="text-right">
          <p className="text-sm" style={{ color: 'var(--text-secondary)' }}>Total Visits: <span className="font-semibold" style={{ color: 'var(--text-primary)' }}>{logs.length}</span></p>
          {unresolvedIssues > 0 && (
            <p className="text-xs text-red-600 flex items-center gap-1 justify-end mt-1">
              <AlertTriangle className="w-3 h-3" />
              {unresolvedIssues} Unresolved Issues
            </p>
          )}
        </div>
      </div>

      <div className="space-y-4">
        {logs.map(log => {
          const hasIssues = log.issuesFound > 0;
          return (
            <div key={log.id} className="p-4 rounded-md border flex flex-col gap-3" style={{ borderColor: 'var(--border-ui)' }}>
              <div className="flex items-start justify-between">
                <div>
                  <div className="flex items-center gap-2">
                    <h4 className="font-medium" style={{ color: 'var(--text-primary)' }}>{log.type}</h4>
                    <span className="text-xs" style={{ color: 'var(--text-secondary)' }}>
                      {log.date instanceof Date ? log.date.toLocaleDateString() : new Date(log.date).toLocaleDateString()}
                    </span>
                  </div>
                  <p className="text-sm mt-1" style={{ color: 'var(--text-secondary)' }}>By: {log.visitedBy}</p>
                </div>
                <button onClick={() => handleDelete(log.id)} className="p-2 text-red-600 hover:bg-red-50 rounded-md transition-colors" title="Delete Log">
                  <Trash2 className="w-4 h-4" />
                </button>
              </div>

              <div className="text-sm bg-gray-50 p-3 rounded border border-gray-100 text-gray-700">
                {log.notes}
              </div>

              <div className="flex items-center justify-between mt-1">
                <div className="flex items-center gap-4 text-xs" style={{ color: 'var(--text-secondary)' }}>
                  <span>{log.photosUploaded} Photos</span>
                  {hasIssues && (
                    <span className={`font-medium ${log.resolved ? 'text-green-600' : 'text-red-600'}`}>
                      {log.issuesFound} {log.issuesFound === 1 ? 'Issue' : 'Issues'}
                    </span>
                  )}
                </div>
                {hasIssues && (
                  <button 
                    onClick={() => toggleResolved(log.id, log.resolved)}
                    className={`flex items-center gap-1 px-3 py-1.5 text-xs rounded-full border transition-colors ${
                      log.resolved 
                        ? 'bg-green-50 border-green-200 text-green-700 hover:bg-green-100' 
                        : 'bg-red-50 border-red-200 text-red-700 hover:bg-red-100'
                    }`}
                  >
                    <Check className="w-3 h-3" />
                    {log.resolved ? 'Resolved' : 'Mark Resolved'}
                  </button>
                )}
              </div>
            </div>
          );
        })}

        {logs.length === 0 && !isAdding && (
          <div className="text-center py-8 text-sm" style={{ color: 'var(--text-secondary)' }}>
            No site visits logged yet.
          </div>
        )}

        {isAdding && (
          <div className="p-4 rounded-md border border-blue-200 bg-blue-50 space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium mb-1 text-gray-700">Visit Type</label>
                <select
                  value={newLog.type}
                  onChange={e => setNewLog({...newLog, type: e.target.value as any})}
                  className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm"
                >
                  {VISIT_TYPES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs font-medium mb-1 text-gray-700">Visited By</label>
                <input
                  type="text"
                  placeholder="e.g., GC Name or Inspector"
                  value={newLog.visitedBy}
                  onChange={e => setNewLog({...newLog, visitedBy: e.target.value})}
                  className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium mb-1 text-gray-700">Visit Notes / Report</label>
              <textarea
                rows={3}
                placeholder="Details of the visit, progress made, etc."
                value={newLog.notes}
                onChange={e => setNewLog({...newLog, notes: e.target.value})}
                className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm resize-none"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className="block text-xs font-medium mb-1 text-gray-700">Issues Found (Optional)</label>
                <input
                  type="number"
                  min="0"
                  value={newLog.issuesFound || ''}
                  onChange={e => setNewLog({...newLog, issuesFound: Number(e.target.value)})}
                  className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm"
                />
              </div>
              <div>
                <label className="block text-xs font-medium mb-1 text-gray-700">Photos Uploaded (Optional)</label>
                <input
                  type="number"
                  min="0"
                  value={newLog.photosUploaded || ''}
                  onChange={e => setNewLog({...newLog, photosUploaded: Number(e.target.value)})}
                  className="w-full px-3 py-2 rounded-md border bg-white focus:ring-2 focus:ring-blue-500 focus:outline-none text-sm"
                />
              </div>
            </div>

            <div className="flex items-center justify-end gap-3 pt-2">
              <button
                onClick={() => setIsAdding(false)}
                className="px-4 py-2 text-sm font-medium text-gray-600 hover:text-gray-800"
              >
                Cancel
              </button>
              <button
                onClick={handleAdd}
                className="px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 rounded-md transition-colors"
              >
                Save Log
              </button>
            </div>
          </div>
        )}

        {!isAdding && (
          <button
            onClick={() => setIsAdding(true)}
            className="w-full py-3 rounded-md border-2 border-dashed flex items-center justify-center gap-2 hover:bg-gray-50 transition-colors"
            style={{ borderColor: 'var(--border-ui)', color: 'var(--text-secondary)' }}
          >
            <Plus className="w-4 h-4" />
            <span className="font-medium text-sm">Log New Visit</span>
          </button>
        )}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Landmark, Percent, Coins, ShieldAlert, Loader2, Edit, Trash2, CheckCircle } from 'lucide-react';
import toast from 'react-hot-toast';
import { NON_BINDING_DISCLOSURE } from '@/lib/constants/disclosure';

export interface IndicationData {
  type: 'percentage' | 'amount';
  value: number;
  currency: string | null;
  updatedAt: string;
}

interface SoftCommitWidgetProps {
  token: string;
  initialIndication?: IndicationData | null;
  onUpdate?: (indication: IndicationData | null) => void;
}

const SUPPORTED_CURRENCIES = ['USD', 'EUR', 'GBP', 'CAD'];

export function SoftCommitWidget({ token, initialIndication = null, onUpdate }: SoftCommitWidgetProps) {
  const [indication, setIndication] = useState<IndicationData | null>(initialIndication);
  const [isEditing, setIsEditing] = useState(!initialIndication);
  const [type, setType] = useState<'percentage' | 'amount'>(initialIndication?.type || 'amount');
  const [valInput, setValInput] = useState<string>(initialIndication?.value ? String(initialIndication.value) : '');
  const [currency, setCurrency] = useState<string>(initialIndication?.currency || 'USD');
  const [submitting, setSubmitting] = useState(false);

  const handleSave = async () => {
    const numVal = parseFloat(valInput);
    if (isNaN(numVal) || numVal <= 0) {
      toast.error('Please enter a positive numeric value.');
      return;
    }

    if (type === 'percentage' && numVal > 100) {
      toast.error('Percentage cannot exceed 100%.');
      return;
    }

    try {
      setSubmitting(true);

      const res = await fetch(`/api/invitations/${token}/indication`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type,
          value: numVal,
          currency: type === 'amount' ? currency : undefined
        })
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Failed to submit expression of interest');
      }

      const updated: IndicationData = {
        type,
        value: numVal,
        currency: type === 'amount' ? currency : null,
        updatedAt: new Date().toISOString()
      };

      setIndication(updated);
      setIsEditing(false);
      if (onUpdate) onUpdate(updated);
      toast.success('Expression of interest submitted successfully!');
    } catch (err: any) {
      toast.error(err.message || 'An error occurred.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleWithdraw = async () => {
    if (!window.confirm('Are you sure you want to withdraw your expression of interest? This action is immediate.')) {
      return;
    }

    try {
      setSubmitting(true);

      const res = await fetch(`/api/invitations/${token}/indication`, {
        method: 'DELETE'
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Failed to withdraw expression of interest');
      }

      setIndication(null);
      setValInput('');
      setIsEditing(true);
      if (onUpdate) onUpdate(null);
      toast.success('Expression of interest withdrawn.');
    } catch (err: any) {
      toast.error(err.message || 'An error occurred.');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div className="relative border border-zinc-800/80 bg-zinc-950/40 rounded-2xl p-6 backdrop-blur-md shadow-2xl space-y-6">
      {/* Glow highlight */}
      <div className="absolute inset-0 opacity-[0.02] pointer-events-none" style={{ backgroundImage: 'radial-gradient(circle at top right, #10b981 0%, transparent 60%)' }}></div>

      <div className="border-b border-zinc-800/80 pb-4">
        <h3 className="text-md font-bold tracking-wider text-zinc-100 flex items-center gap-2">
          <Coins className="w-5 h-5 text-emerald-500" />
          INDICATION OF INTEREST (SOFT COMMIT)
        </h3>
        <p className="text-xs text-zinc-500 font-mono mt-1">Submit a non-binding expression of interest in this project</p>
      </div>

      {/* Prominent, Non-Dismissible, Non-Collapsed Disclosure Block */}
      <div className="p-4 rounded-xl border border-amber-900/40 bg-amber-950/10 flex items-start gap-3 select-none">
        <ShieldAlert className="w-5 h-5 text-amber-500 shrink-0 mt-0.5" />
        <p className="text-xs text-amber-500/90 leading-relaxed font-sans font-medium">
          <strong>Non-Binding Disclosure:</strong> {NON_BINDING_DISCLOSURE}
        </p>
      </div>

      {isEditing ? (
        <div className="space-y-4">
          {/* Format Selector Toggle */}
          <div className="flex rounded-lg bg-zinc-900 p-0.5 border border-zinc-800/60 w-fit">
            <button
              type="button"
              onClick={() => setType('amount')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-bold uppercase transition-all ${
                type === 'amount' ? 'bg-zinc-800 text-emerald-400 shadow-inner' : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              <Landmark className="w-3.5 h-3.5" />
              Currency Amount
            </button>
            <button
              type="button"
              onClick={() => setType('percentage')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-bold uppercase transition-all ${
                type === 'percentage' ? 'bg-zinc-800 text-emerald-400 shadow-inner' : 'text-zinc-500 hover:text-zinc-300'
              }`}
            >
              <Percent className="w-3.5 h-3.5" />
              Project Share (%)
            </button>
          </div>

          <div className="flex flex-col sm:flex-row gap-3">
            {type === 'amount' && (
              <div className="w-32 shrink-0">
                <label className="block text-[10px] uppercase font-mono tracking-widest text-zinc-500 mb-1.5">Currency</label>
                <select
                  value={currency}
                  onChange={(e) => setCurrency(e.target.value)}
                  className="w-full h-11 px-3 bg-zinc-900 border border-zinc-800 rounded-lg text-sm text-zinc-200 focus:outline-none focus:border-emerald-500/50 transition-colors font-mono"
                >
                  {SUPPORTED_CURRENCIES.map((cur) => (
                    <option key={cur} value={cur}>{cur}</option>
                  ))}
                </select>
              </div>
            )}

            <div className="flex-1">
              <label className="block text-[10px] uppercase font-mono tracking-widest text-zinc-500 mb-1.5">
                {type === 'amount' ? 'Indicated Amount' : 'Indicated Share Percentage'}
              </label>
              <div className="relative">
                <input
                  type="number"
                  placeholder={type === 'amount' ? 'e.g. 50,000' : 'e.g. 5'}
                  value={valInput}
                  onChange={(e) => setValInput(e.target.value)}
                  min="0.01"
                  step="any"
                  className="w-full h-11 px-3 bg-zinc-900 border border-zinc-800 rounded-lg text-sm text-zinc-200 focus:outline-none focus:border-emerald-500/50 transition-colors font-mono"
                />
                {type === 'percentage' && (
                  <span className="absolute right-3.5 top-3.5 text-xs text-zinc-500 font-mono">%</span>
                )}
              </div>
            </div>
          </div>

          <div className="flex items-center gap-3 pt-2">
            <button
              type="button"
              onClick={handleSave}
              disabled={submitting}
              className="flex items-center justify-center gap-2 h-10 px-5 rounded-lg bg-emerald-500 text-black hover:bg-emerald-400 font-bold text-xs uppercase tracking-wider transition-colors disabled:opacity-50"
            >
              {submitting ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <CheckCircle className="w-3.5 h-3.5" />
              )}
              Save Indication
            </button>
            {indication && (
              <button
                type="button"
                onClick={() => setIsEditing(false)}
                className="h-10 px-4 rounded-lg border border-zinc-800 text-zinc-400 hover:text-zinc-200 text-xs font-bold uppercase tracking-wider transition-all"
              >
                Cancel
              </button>
            )}
          </div>
        </div>
      ) : (
        <div className="p-5 rounded-xl border border-zinc-800 bg-zinc-950/80 space-y-4">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-[10px] font-mono uppercase tracking-widest text-zinc-500">Your Current Indication</p>
              <p className="text-2xl font-mono font-bold text-emerald-400 mt-1">
                {indication?.type === 'amount'
                  ? `${indication.currency} ${Number(indication.value).toLocaleString()}`
                  : `${indication?.value}%`}
              </p>
            </div>
            <div className="flex gap-2">
              <button
                type="button"
                onClick={() => {
                  setType(indication!.type);
                  setValInput(String(indication!.value));
                  if (indication!.currency) setCurrency(indication!.currency);
                  setIsEditing(true);
                }}
                className="flex items-center justify-center w-8 h-8 rounded-lg bg-zinc-900 border border-zinc-800 hover:border-zinc-700 text-zinc-400 hover:text-zinc-200 transition-colors"
                title="Edit Indication"
              >
                <Edit className="w-4 h-4" />
              </button>
              <button
                type="button"
                onClick={handleWithdraw}
                className="flex items-center justify-center w-8 h-8 rounded-lg bg-zinc-900 border border-zinc-800 hover:border-red-900/50 text-zinc-400 hover:text-red-400 transition-colors"
                title="Withdraw Indication"
              >
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          </div>

          <p className="text-[10px] text-zinc-500 font-mono italic">
            Submitted/Updated at: {new Date(indication!.updatedAt).toLocaleString()}
          </p>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useEffect, useMemo } from 'react';
import { Compass, User, TrendingUp, Edit3, X, CheckCircle2, Loader2, AlertTriangle, Link as LinkIcon, DollarSign, Calendar, FileText } from 'lucide-react';
import type { Project } from '@/types/schema';

interface SourceSellerMarketSnapshotProps {
  project: Project;
  phaseColor?: string;
  onSave: (updates: any) => Promise<void>;
}

export function SourceSellerMarketSnapshot({
  project,
  phaseColor = '#595959',
  onSave,
}: SourceSellerMarketSnapshotProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  // Initialize form state
  const [formData, setFormData] = useState({
    // Source details
    leadSource: project.leadSource || '',
    listingUrl: project.listingUrl || '',
    askingPrice: project.askingPriceCents ? (project.askingPriceCents / 100).toString() : '',
    subjectDom: project.subjectDom != null ? project.subjectDom.toString() : '',
    leadAgent: project.leadAgent || '',
    dateIdentified: project.dateIdentified
      ? new Date(project.dateIdentified).toISOString().split('T')[0]
      : '',

    // Seller details
    sellerName: project.sellerName || '',
    sellerType: project.sellerType || '',
    sellerMotivation: project.sellerMotivation || '',
    sellerContact: project.sellerContact || '',

    // Market details
    submarket: project.submarket || '',
    medianSalesPrice: project.medianSalesPriceCents ? (project.medianSalesPriceCents / 100).toString() : '',
    medianRent: project.medianRentCents ? (project.medianRentCents / 100).toString() : '',
    marketVacancyRate: project.marketVacancyRate != null ? project.marketVacancyRate.toString() : '',
    hazardFlag: !!project.hazardFlag,
    hazardNote: project.hazardNote || '',
  });

  // Re-sync form state when project changes externally
  useEffect(() => {
    setFormData({
      leadSource: project.leadSource || '',
      listingUrl: project.listingUrl || '',
      askingPrice: project.askingPriceCents ? (project.askingPriceCents / 100).toString() : '',
      subjectDom: project.subjectDom != null ? project.subjectDom.toString() : '',
      leadAgent: project.leadAgent || '',
      dateIdentified: project.dateIdentified
        ? new Date(project.dateIdentified).toISOString().split('T')[0]
        : '',
      sellerName: project.sellerName || '',
      sellerType: project.sellerType || '',
      sellerMotivation: project.sellerMotivation || '',
      sellerContact: project.sellerContact || '',
      submarket: project.submarket || '',
      medianSalesPrice: project.medianSalesPriceCents ? (project.medianSalesPriceCents / 100).toString() : '',
      medianRent: project.medianRentCents ? (project.medianRentCents / 100).toString() : '',
      marketVacancyRate: project.marketVacancyRate != null ? project.marketVacancyRate.toString() : '',
      hazardFlag: !!project.hazardFlag,
      hazardNote: project.hazardNote || '',
    });
  }, [project]);

  // Live rent-to-price ratio calculation
  const liveRentToPriceRatio = useMemo(() => {
    const rent = parseFloat(formData.medianRent);
    const price = parseFloat(formData.medianSalesPrice);
    if (isNaN(rent) || isNaN(price) || price === 0) return null;
    return (rent / price) * 100;
  }, [formData.medianRent, formData.medianSalesPrice]);

  const handleSave = async () => {
    setIsSaving(true);
    try {
      const updates: any = {
        // Source
        leadSource: formData.leadSource || null,
        listingUrl: formData.listingUrl || null,
        askingPriceCents: formData.askingPrice ? Math.round(parseFloat(formData.askingPrice) * 100) : null,
        subjectDom: formData.subjectDom ? parseInt(formData.subjectDom, 10) : null,
        leadAgent: formData.leadAgent || null,
        dateIdentified: formData.dateIdentified ? new Date(formData.dateIdentified).toISOString() : null,

        // Seller
        sellerName: formData.sellerName || null,
        sellerType: formData.sellerType || null,
        sellerMotivation: formData.sellerMotivation || null,
        sellerContact: formData.sellerContact || null,

        // Market
        submarket: formData.submarket || null,
        medianSalesPriceCents: formData.medianSalesPrice ? Math.round(parseFloat(formData.medianSalesPrice) * 100) : null,
        medianRentCents: formData.medianRent ? Math.round(parseFloat(formData.medianRent) * 100) : null,
        marketVacancyRate: formData.marketVacancyRate ? parseFloat(formData.marketVacancyRate) : null,
        hazardFlag: formData.hazardFlag,
        hazardNote: formData.hazardFlag ? formData.hazardNote || null : null,
      };

      // Ensure financials.listedPrice and listedPrice are kept in sync with askingPrice
      updates['financials.listedPrice'] = updates.askingPriceCents;
      updates.listedPrice = updates.askingPriceCents;

      // Prefill purchasePrice if not already set (AQ-5 / AQ-15 integration)
      if (!project.financials?.purchasePrice && updates.askingPriceCents) {
        updates['financials.purchasePrice'] = updates.askingPriceCents;
      }

      await onSave(updates);
      setIsEditing(false);
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
    } catch (err) {
      console.error('Failed to save snapshot:', err);
    } finally {
      setIsSaving(false);
    }
  };

  const formatCurrency = (amount?: number) => {
    if (amount === undefined || amount === null || isNaN(amount)) return '—';
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(amount);
  };

  const isSellerComplete = !!(formData.sellerName || formData.sellerType);

  return (
    <section className="space-y-6">
      {/* Group Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <FileText className="w-5 h-5 text-white" />
          <h3 className="text-sm font-bold text-white uppercase tracking-wider">
            Deal, Seller &amp; Market Snapshot
          </h3>
          {showSuccess && (
            <span className="text-[10px] font-bold uppercase tracking-widest px-2.5 py-0.5 rounded-full bg-green-500/20 text-green-100 flex items-center gap-1">
              <CheckCircle2 className="w-3 h-3" /> Saved
            </span>
          )}
        </div>
        {!isEditing ? (
          <button
            onClick={() => setIsEditing(true)}
            className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/10 hover:bg-white/20 transition-colors text-white text-[10px] font-bold uppercase tracking-widest"
          >
            <Edit3 className="w-3 h-3" /> Edit Snapshot
          </button>
        ) : (
          <button
            onClick={() => {
              setIsEditing(false);
              // Revert
              setFormData({
                leadSource: project.leadSource || '',
                listingUrl: project.listingUrl || '',
                askingPrice: project.askingPriceCents ? (project.askingPriceCents / 100).toString() : '',
                subjectDom: project.subjectDom != null ? project.subjectDom.toString() : '',
                leadAgent: project.leadAgent || '',
                dateIdentified: project.dateIdentified
                  ? new Date(project.dateIdentified).toISOString().split('T')[0]
                  : '',
                sellerName: project.sellerName || '',
                sellerType: project.sellerType || '',
                sellerMotivation: project.sellerMotivation || '',
                sellerContact: project.sellerContact || '',
                submarket: project.submarket || '',
                medianSalesPrice: project.medianSalesPriceCents ? (project.medianSalesPriceCents / 100).toString() : '',
                medianRent: project.medianRentCents ? (project.medianRentCents / 100).toString() : '',
                marketVacancyRate: project.marketVacancyRate != null ? project.marketVacancyRate.toString() : '',
                hazardFlag: !!project.hazardFlag,
                hazardNote: project.hazardNote || '',
              });
            }}
            className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-white/10 hover:bg-white/20 transition-colors text-white text-[10px] font-bold uppercase tracking-widest"
          >
            <X className="w-3 h-3" /> Cancel
          </button>
        )}
      </div>

      {/* Snapshot Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">

        {/* CARD 1: Source Snapshot */}
        <div className="rounded-xl overflow-hidden border border-white/5 bg-[#161217]" style={{ backdropFilter: 'blur(16px)' }}>
          <div className="px-5 py-3 border-b border-white/5 flex items-center gap-2.5 bg-white/[0.02]">
            <Compass className="w-4 h-4 text-[#9E9DA0]" />
            <h4 className="text-[11px] font-bold uppercase tracking-wider text-white">Source Snapshot</h4>
          </div>
          <div className="p-5 space-y-4">
            {isEditing ? (
              <>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Lead Source</label>
                  <input
                    type="text"
                    value={formData.leadSource}
                    onChange={(e) => setFormData({ ...formData, leadSource: e.target.value })}
                    className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955]"
                    placeholder="e.g. MLS, Direct Mail"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Listing URL</label>
                  <input
                    type="text"
                    value={formData.listingUrl}
                    onChange={(e) => setFormData({ ...formData, listingUrl: e.target.value })}
                    className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955]"
                    placeholder="e.g. https://redfin.com/..."
                  />
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Asking Price ($)</label>
                    <input
                      type="number"
                      value={formData.askingPrice}
                      onChange={(e) => setFormData({ ...formData, askingPrice: e.target.value })}
                      className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955] font-mono"
                      placeholder="e.g. 295000"
                    />
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Subject DOM</label>
                    <input
                      type="number"
                      value={formData.subjectDom}
                      onChange={(e) => setFormData({ ...formData, subjectDom: e.target.value })}
                      className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955] font-mono"
                      placeholder="e.g. 14"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Agent</label>
                  <input
                    type="text"
                    value={formData.leadAgent}
                    onChange={(e) => setFormData({ ...formData, leadAgent: e.target.value })}
                    className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955]"
                    placeholder="e.g. Jane Doe, RE/MAX"
                  />
                </div>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Date Identified</label>
                  <input
                    type="date"
                    value={formData.dateIdentified}
                    onChange={(e) => setFormData({ ...formData, dateIdentified: e.target.value })}
                    className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955] font-mono"
                    style={{ colorScheme: 'dark' }}
                  />
                </div>
              </>
            ) : (
              <div className="space-y-3.5 text-xs">
                <div>
                  <span className="block text-[9px] uppercase tracking-widest text-[#9E9DA0]">Lead Source</span>
                  <span className="font-semibold text-white">{project.leadSource || '—'}</span>
                </div>
                <div>
                  <span className="block text-[9px] uppercase tracking-widest text-[#9E9DA0]">Listing URL</span>
                  {project.listingUrl ? (
                    <a
                      href={project.listingUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-[#7A9EAA] hover:underline flex items-center gap-1 font-medium truncate"
                    >
                      <LinkIcon className="w-3 h-3 shrink-0" /> Link
                    </a>
                  ) : (
                    <span className="text-[#9E9DA0] italic">None provided</span>
                  )}
                </div>
                <div className="grid grid-cols-2 gap-2">
                  <div>
                    <span className="block text-[9px] uppercase tracking-widest text-[#9E9DA0]">Asking Price</span>
                    <span className="font-bold text-white font-mono">{project.askingPriceCents ? formatCurrency(project.askingPriceCents / 100) : '—'}</span>
                  </div>
                  <div>
                    <span className="block text-[9px] uppercase tracking-widest text-[#9E9DA0]">Subject DOM</span>
                    <span className="font-semibold text-white font-mono">{project.subjectDom != null ? `${project.subjectDom} days` : '—'}</span>
                  </div>
                </div>
                <div>
                  <span className="block text-[9px] uppercase tracking-widest text-[#9E9DA0]">Listing Agent</span>
                  <span className="font-semibold text-white">{project.leadAgent || '—'}</span>
                </div>
                <div>
                  <span className="block text-[9px] uppercase tracking-widest text-[#9E9DA0]">Date Identified</span>
                  <span className="font-semibold text-white font-mono">
                    {project.dateIdentified
                      ? new Date(project.dateIdentified).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
                      : '—'}
                  </span>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* CARD 2: Seller Snapshot */}
        <div className="rounded-xl overflow-hidden border border-white/5 bg-[#161217]" style={{ backdropFilter: 'blur(16px)' }}>
          <div className="px-5 py-3 border-b border-white/5 flex items-center justify-between bg-white/[0.02]">
            <div className="flex items-center gap-2.5">
              <User className="w-4 h-4 text-[#9E9DA0]" />
              <h4 className="text-[11px] font-bold uppercase tracking-wider text-white">Seller Snapshot</h4>
            </div>
            <span
              className={`text-[9px] font-bold uppercase tracking-widest px-2 py-0.5 rounded-full ${
                isSellerComplete ? 'bg-green-500/10 text-green-400 border border-green-500/25' : 'bg-yellow-500/10 text-yellow-400 border border-yellow-500/25'
              }`}
            >
              {isSellerComplete ? '✓ Complete' : '○ Name or Type Required'}
            </span>
          </div>
          <div className="p-5 space-y-4">
            {isEditing ? (
              <>
                <div>
                  <label className="block text-[10px] font-bold uppercase tracking-widest text-[#9E9DA0] mb-1.5">Seller Name</label>
                  <input
                    type="text"
                    value={formData.sellerName}
                    onChange={(e) => setFormData({ ...formData, sellerName: e.target.value })}
                    className="w-full rounded-lg px-3 py-2 text-xs bg-[#241e26] border border-white/10 text-white focus:outline-none focus:border-[#454955]"
                    placeholder="e.g. John Smith"
                  />
