// ─── Kind icon ────────────────────────────────────────────────────────────────

function kindIcon(kind: TodoKind, color: string) {
  const map: Record<TodoKind, string> = {
    question: "chat_bubble",
    checkbox: "check_circle",
    upload:   "upload_file",
    assign:   "person_add",
    date:     "calendar_today",
    dollar:   "attach_money",
  };
  return (
    <span
      className="material-symbols-outlined text-[16px] flex-shrink-0 mt-0.5"
      style={{ color, fontVariationSettings: "'FILL' 0" }}
    >
      {map[kind]}
    </span>
  );
}

// ─── Single todo row ──────────────────────────────────────────────────────────

function TodoRow({
  item,
  state,
  phaseColor,
  onChange,
}: {
  item:       TodoItem;
  state:      TodoState;
  phaseColor: string;
  onChange:   (s: Partial<TodoState>) => void;
}) {
  const [expanded, setExpanded] = useState(false);

  const toggleDone = useCallback(() => onChange({ done: !state.done }), [state.done, onChange]);

  const rowBg = state.done
    ? "rgba(255,255,255,0.01)"
    : "rgba(255,255,255,0.025)";

  return (
    <div
      className="rounded-xl overflow-hidden transition-all duration-150"
      style={{ background: rowBg, border: "1px solid rgba(255,255,255,0.06)" }}
    >
      {/* Main row */}
      <div className="flex items-start gap-3 px-4 py-3">
        {/* Checkbox */}
        <button
          onClick={toggleDone}
          className="mt-0.5 w-5 h-5 rounded-md flex-shrink-0 flex items-center justify-center transition-all duration-150"
          style={{
            background:  state.done ? `${phaseColor}22` : "rgba(255,255,255,0.06)",
            border:      `1.5px solid ${state.done ? phaseColor : "rgba(255,255,255,0.15)"}`,
          }}
          aria-checked={state.done}
          role="checkbox"
        >
          {state.done && (
            <span className="material-symbols-outlined text-[12px]" style={{ color: phaseColor, fontVariationSettings: "'FILL' 1" }}>
              check
            </span>
          )}
        </button>

        {/* Kind icon */}
        {kindIcon(item.kind, state.done ? "rgba(253,255,252,0.25)" : phaseColor)}

        {/* Content */}
        <div className="flex-1 min-w-0">
          <p
            className="text-[13px] leading-snug"
            style={{
              color:          state.done ? "rgba(253,255,252,0.35)" : "rgba(253,255,252,0.85)",
              textDecoration: state.done ? "line-through" : "none",
            }}
          >
            {item.question}
            {item.required && !state.done && (
              <span className="ml-1.5 text-[10px] font-bold" style={{ color: phaseColor }}>*</span>
            )}
          </p>
          {item.hint && !state.done && (
            <p className="text-[11px] mt-0.5" style={{ color: "rgba(253,255,252,0.30)" }}>
              {item.hint}
            </p>
          )}
        </div>

        {/* Expand / assign button */}
        <div className="flex items-center gap-2 flex-shrink-0">
          {item.assignable && !state.done && (
            <button
              onClick={() => setExpanded(v => !v)}
              className="text-[10px] font-semibold px-2 py-1 rounded-lg transition-opacity hover:opacity-70"
              style={{
                background: `${phaseColor}12`,
                color:      phaseColor,
                border:     `1px solid ${phaseColor}25`,
              }}
            >
              Assign
            </button>
          )}
          {(item.kind === "question" || item.kind === "dollar" || item.kind === "date") && !state.done && (
            <button
              onClick={() => setExpanded(v => !v)}
              className="flex items-center"
              aria-label="Enter answer"
            >
              <span
                className="material-symbols-outlined text-[16px] transition-transform duration-150"
                style={{
                  color: "rgba(253,255,252,0.25)",
                  transform: expanded ? "rotate(180deg)" : "rotate(0deg)",
                }}
              >
                expand_more
              </span>
            </button>
          )}
        </div>
      </div>

      {/* Expanded panel */}
      {expanded && !state.done && (
        <div
          className="px-4 pb-4 pt-1 space-y-2"
          style={{ borderTop: "1px solid rgba(255,255,255,0.05)" }}
        >
          {/* Assignee field */}
          {item.assignable && (
            <div className="space-y-1">
              <label className="text-[10px] font-bold uppercase tracking-widest" style={{ color: "rgba(253,255,252,0.35)" }}>
                Assign to (email or team member)
              </label>
              <input
                className="w-full rounded-lg px-3 py-2 text-[13px] outline-none bg-transparent"
                style={{
                  background: "rgba(14,22,28,0.8)",
                  border:     "1px solid rgba(255,255,255,0.09)",
                  color:      "rgba(253,255,252,0.85)",
                }}
                placeholder="name@example.com or @teammate"
                value={state.assignee ?? ""}
                onChange={e => onChange({ assignee: e.target.value })}
              />
              <p className="text-[10px]" style={{ color: "rgba(253,255,252,0.25)" }}>
                Invitees need a Standard PaperWorking account to access this project.
              </p>
            </div>
          )}

          {/* Answer field */}
          {(item.kind === "question" || item.kind === "dollar" || item.kind === "date") && (
            <div className="space-y-1">
              <label className="text-[10px] font-bold uppercase tracking-widest" style={{ color: "rgba(253,255,252,0.35)" }}>
                {item.kind === "dollar" ? "Amount ($)" : item.kind === "date" ? "Date" : "Your answer"}
              </label>
              <input
                className="w-full rounded-lg px-3 py-2 text-[13px] outline-none bg-transparent"
                type={item.kind === "date" ? "date" : "text"}
                inputMode={item.kind === "dollar" ? "decimal" : "text"}
                style={{
                  background: "rgba(14,22,28,0.8)",
                  border:     "1px solid rgba(255,255,255,0.09)",
                  color:      "rgba(253,255,252,0.85)",
                }}
                placeholder={item.kind === "dollar" ? "0.00" : item.kind === "date" ? "" : item.hint ?? "Type your answer…"}
                value={state.value ?? ""}
                onChange={e => onChange({ value: e.target.value })}
              />
            </div>
          )}

          {/* Upload cue */}
          {item.kind === "upload" && (
            <div
              className="flex items-center gap-2 rounded-lg px-3 py-2.5 cursor-pointer transition-opacity hover:opacity-70"
              style={{ background: `${phaseColor}10`, border: `1px dashed ${phaseColor}30` }}
            >
              <span className="material-symbols-outlined text-[18px]" style={{ color: phaseColor }}>upload</span>
              <span className="text-[12px] font-medium" style={{ color: phaseColor }}>
                Click to upload or drag a file
              </span>
            </div>
          )}

          <button
            onClick={() => { setExpanded(false); onChange({ done: true }); }}
            className="text-[11px] font-semibold px-3 py-1.5 rounded-lg transition-opacity hover:opacity-70"
            style={{ background: `${phaseColor}18`, color: phaseColor }}
          >
            Mark complete
          </button>
        </div>
      )}
    </div>
  );
}

// ─── Main export ───────────────────────────────────────────────────────────────

interface PhaseTodoListProps {
  phase:      number;  // 1–4
  phaseColor: string;
  projectId?: string;
}

export function PhaseTodoList({ phase, phaseColor }: PhaseTodoListProps) {
  const def = PHASE_TODOS[phase];
  const [states, setStates] = useState<Record<string, TodoState>>(() => {
    const init: Record<string, TodoState> = {};
    def?.todos.forEach(t => { init[t.id] = { done: false }; });
    return init;
  });

  if (!def) return null;

  const doneCount = Object.values(states).filter(s => s.done).length;
  const totalCount = def.todos.length;
  const pct = Math.round((doneCount / totalCount) * 100);

  const handleChange = useCallback(
    (id: string, patch: Partial<TodoState>) =>
      setStates(prev => ({ ...prev, [id]: { ...prev[id], ...patch } })),
    [],
  );

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-[14px] font-bold" style={{ color: "rgba(253,255,252,0.90)", letterSpacing: "-0.01em" }}>
            {def.heading}
          </h3>
          <p className="text-[11px] mt-0.5" style={{ color: "rgba(253,255,252,0.38)" }}>
            {doneCount} of {totalCount} tasks complete
          </p>
        </div>
        <span
          className="text-[12px] font-bold tabular-nums px-2.5 py-1 rounded-full"
          style={{ background: `${phaseColor}18`, color: phaseColor }}
        >
          {pct}%
        </span>
      </div>

      {/* Progress bar */}
      <div className="h-1.5 rounded-full overflow-hidden" style={{ background: "rgba(255,255,255,0.06)" }}>
        <div
          className="h-full rounded-full transition-all duration-500"
          style={{ width: `${pct}%`, background: phaseColor }}
        />
      </div>

      {/* Todo items */}
      <div className="space-y-2">
        {def.todos.map(item => (
          <TodoRow
            key={item.id}
            item={item}
            state={states[item.id] ?? { done: false }}
            phaseColor={phaseColor}
            onChange={patch => handleChange(item.id, patch)}
          />
        ))}
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { X, Folder, Shield, Send, CheckCircle2, ChevronDown, Lock } from 'lucide-react';
import { Project, VendorProfile } from '@/types/schema';
import { useProjectStore } from '@/store/projectStore';

interface RequestQuoteModalProps {
  vendor: VendorProfile;
  isOpen: boolean;
  onClose: () => void;
}

export default function RequestQuoteModal({ vendor, isOpen, onClose }: RequestQuoteModalProps) {
  const { projects } = useProjectStore();
  const [selectedDealId, setSelectedDealId] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [shareFolders, setShareFolders] = useState({
    acquisition: true,
    financials: false,
    permits: false
  });

  const selectedDeal = projects.find(d => d.id === selectedDealId);

  const handleSubmit = async () => {
    setIsSubmitting(true);
    setIsSubmitting(false);
    setIsSuccess(true);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-6">
      <div 
        onClick={onClose}
        className="absolute inset-0 bg-black/65 backdrop-blur-md"
      />

      <div className="relative w-full max-w-xl bg-pw-glass-bg border border-pw-border backdrop-blur-[20px] rounded-2xl shadow-2xl overflow-hidden">
        <button 
          onClick={onClose}
          className="absolute top-8 right-8 w-8 h-8 flex items-center justify-center rounded-full transition-colors text-pw-black hover:bg-pw-glass-bg/25 z-10"
        >
          <X className="w-6 h-6 text-pw-black" />
        </button>

        <AnimatePresence mode="wait">
          {!isSuccess ? (
            <div className="p-12">
              <header className="mb-8">
                <p className="block text-[10px] font-black text-pw-muted uppercase tracking-[0.3em] mb-3">Procurement Request</p>
                <h2 className="text-3xl font-bold tracking-tight text-pw-black mb-1 uppercase">Transmit Briefing</h2>
                <p className="text-[10px] font-black text-pw-muted uppercase tracking-[0.3em]">Entity: {vendor.companyName}</p>
              </header>

              <div className="space-y-8">
                {/* Deal Selection */}
                <div>
                  <label className="block text-[10px] font-black text-pw-muted uppercase tracking-[0.3em] mb-3">Target Portfolio Asset</label>
                  <div className="relative">
                    <select 
                      className="glass-input w-full px-6 py-4 text-xs font-bold rounded-2xl focus:outline-none transition-colors appearance-none cursor-pointer text-pw-black"
                      value={selectedDealId}
                      onChange={(e) => setSelectedDealId(e.target.value)}
                    >
                      <option value="">SELECT SOURCE PROPERTY...</option>
                      {projects.map(deal => (
                        <option key={deal.id} value={deal.id}>{deal.propertyName}</option>
                      ))}
                    </select>
                    <ChevronDown className="absolute right-6 top-1/2 -translate-y-1/2 w-4 h-4 text-pw-muted pointer-events-none" />
                  </div>
                </div>

                {/* Secure Sharing Context */}
                <div>
                  <div className="flex items-center gap-3 mb-4">
                    <Lock className="w-4 h-4 text-pw-black" />
                    <h3 className="text-[10px] font-black text-pw-black uppercase tracking-[0.2em]">Restricted Document Provisioning</h3>
                  </div>
                  <div className="border border-pw-border divide-y divide-pw-border bg-pw-glass-bg/50 rounded-2xl overflow-hidden">
                    <FolderCheckbox 
                      label="Acquisition & Title" 
                      description="Purchase terms and preliminary title commitment."
                      checked={shareFolders.acquisition} 
                      onChange={() => setShareFolders({...shareFolders, acquisition: !shareFolders.acquisition})}
                    />
                    <FolderCheckbox 
                      label="Asset Financials" 
                      description="Operating ledger and tax projections."
                      checked={shareFolders.financials} 
                      onChange={() => setShareFolders({...shareFolders, financials: !shareFolders.financials})}
                    />
                    <FolderCheckbox 
                      label="Technical Filings" 
                      description="Environmental reports and city permits."
                      checked={shareFolders.permits} 
                      onChange={() => setShareFolders({...shareFolders, permits: !shareFolders.permits})}
                    />
                  </div>
                </div>

                <div className="p-6 bg-pw-black text-pw-white flex items-start gap-6 rounded-2xl shadow-inner border border-white/10">
                  <Shield className="w-5 h-5 shrink-0 opacity-50" />
                  <p className="text-[10px] font-bold text-pw-white/70 leading-relaxed uppercase tracking-[0.2em]">
                    Security protocol: Investor pledges and sensitive cap-table data remain isolated. Only specified folders are exposed.
                  </p>
                </div>

                <button 
                  disabled={!selectedDealId || isSubmitting}
                  onClick={handleSubmit}
                  className="pw-btn pw-btn--primary pw-btn--pill w-full py-4 text-pw-white font-black text-xs uppercase tracking-[0.3em] transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
                >
                  {isSubmitting ? 'Transmitting Data...' : 'Dispatch Request'}
                </button>
              </div>
            </div>
          ) : (
            <div className="p-16 text-center">
              <div className="w-20 h-20 rounded-full border-4 border-pw-border flex items-center justify-center mx-auto mb-10 bg-pw-glass-bg">
                <CheckCircle2 className="w-10 h-10 text-pw-black" />
              </div>
              <h3 className="text-3xl font-bold tracking-tight text-pw-black mb-4 uppercase">Transmission Confirmed</h3>
              <p className="text-xs text-pw-muted font-bold max-w-[300px] mx-auto leading-relaxed uppercase tracking-widest mb-12">
                {vendor.companyName} has been authorized to access the requested project documents for audit and proposal drafting.
              </p>
              <button 
                onClick={onClose}
                className="pw-btn pw-btn--primary pw-btn--pill px-12 py-4 text-pw-white font-black text-xs uppercase tracking-[0.3em] transition-colors"
              >
                Close Connection
              </button>
            </div>
          )}
        </AnimatePresence>
      </div>
    </div>
  );
}

