'use client';

import React, { useMemo } from 'react';
import { useProjectStore, selectActiveProjectMetrics } from '@/store/projectStore';
import { TrendingUp, AlertTriangle, DollarSign, Target } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Rehab Metrics Dashboard — Phase 3 (The Engine Room)
   3 live widgets:
     1. Target ARV
     2. Rehab Budget Contingency (% remaining of 10-20% buffer)
     3. Projected ROI
   ═══════════════════════════════════════════════════════ */

export default function RehabMetricsDashboard() {
  const currentProject = useProjectStore(s => s.currentProject);
  const dealMetrics = useProjectStore(selectActiveProjectMetrics);

  const metrics = useMemo(() => {
    const arv = currentProject?.financials?.estimatedARV ?? 0;
    const purchasePrice = currentProject?.financials?.purchasePrice ?? 0;

    // Total rehab spend = rehab module tasks (approved) + rehabExpenses
    const rehabTaskCosts =
      currentProject?.rehab?.tasks
        ?.filter(t => t.status === 'Complete' || t.status === 'In Progress')
        .reduce((s, t) => s + t.estimatedCost, 0) ?? 0;

    const rehabExpenseCosts =
      currentProject?.rehabExpenses?.reduce((s, e) => s + e.amount, 0) ?? 0;

    const totalRehabSpent = rehabTaskCosts + rehabExpenseCosts;

    // Budget contingency
    const baseBudget = currentProject?.rehab?.baseBudget ?? 0;
    const bufferPct = currentProject?.rehab?.contingencyBufferPercentage ?? 0.15;
    const contingencyAmount = baseBudget * bufferPct;
    const bufferedBudget = baseBudget + contingencyAmount;
    const overBudget = totalRehabSpent > baseBudget;
    const contingencyUsed = overBudget ? Math.min(totalRehabSpent - baseBudget, contingencyAmount) : 0;
    const contingencyRemaining = contingencyAmount > 0 ? ((contingencyAmount - contingencyUsed) / contingencyAmount) * 100 : 100;

    // Projected ROI
    const holdingCostTotal =
      currentProject?.holdingCosts?.reduce((s, c) => s + c.monthlyAmount * c.totalMonths, 0) ?? 0;

    const totalInvestment = purchasePrice + totalRehabSpent + holdingCostTotal + dealMetrics.closingCostsBuy;
    const netProfit = arv - totalInvestment - dealMetrics.closingCostsSell;
    const roi = totalInvestment > 0 ? (netProfit / totalInvestment) * 100 : 0;

    return {
      arv,
      totalRehabSpent,
      baseBudget,
      bufferedBudget,
      contingencyRemaining,
      contingencyUsed,
      contingencyAmount,
      overBudget,
      bufferPct,
      roi,
      netProfit,
      totalInvestment,
    };
  }, [currentProject, dealMetrics]);

  // Color helpers
  const roiColor = metrics.roi >= 20 ? 'text-green-600' : metrics.roi >= 10 ? 'text-amber-600' : 'text-red-600';
  const roiBg = metrics.roi >= 20 ? 'bg-green-50' : metrics.roi >= 10 ? 'bg-amber-50' : 'bg-red-50';
  const contColor = metrics.contingencyRemaining >= 80 ? 'text-green-600' : metrics.contingencyRemaining >= 50 ? 'text-amber-600' : 'text-red-600';
  const contBg = metrics.contingencyRemaining >= 80 ? 'bg-green-50' : metrics.contingencyRemaining >= 50 ? 'bg-amber-50' : 'bg-red-50';
  const contBarColor = metrics.contingencyRemaining >= 80 ? 'bg-green-500' : metrics.contingencyRemaining >= 50 ? 'bg-amber-500' : 'bg-red-500';

  return (
    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
      {/* Widget 1: Target ARV */}
      <div className="bg-bg-surface rounded-xl shadow-sm border border-border-accent p-5 flex flex-col">
        <div className="flex items-center gap-2 mb-3">
          <Target className="w-4 h-4 text-text-secondary" />
          <p className="text-xs font-medium uppercase tracking-widest text-text-secondary">Target ARV</p>
        </div>
        <p className="text-3xl font-normal tracking-tight text-text-primary mb-2">
          ${metrics.arv.toLocaleString()}
        </p>
        <div className="mt-auto text-xs text-text-secondary">
          <div className="flex justify-between">
            <span>Rehab Spent</span>
            <span className="font-mono">${metrics.totalRehabSpent.toLocaleString()}</span>
          </div>
          <div className="flex justify-between mt-0.5">
            <span>Total Investment</span>
            <span className="font-mono">${metrics.totalInvestment.toLocaleString()}</span>
          </div>
        </div>
      </div>

      {/* Widget 2: Budget Contingency */}
      <div className={`rounded-xl shadow-sm border border-border-accent p-5 flex flex-col ${contBg}`}>
        <div className="flex items-center gap-2 mb-3">
          <AlertTriangle className={`w-4 h-4 ${contColor}`} />
          <p className="text-xs font-medium uppercase tracking-widest text-text-secondary">
            Rehab Contingency ({(metrics.bufferPct * 100).toFixed(0)}%)
          </p>
        </div>
        <p className={`text-3xl font-normal tracking-tight mb-1 ${contColor}`}>
          {metrics.contingencyRemaining.toFixed(1)}%
        </p>
        <p className="text-xs text-text-secondary mb-3">
          ${(metrics.contingencyAmount - metrics.contingencyUsed).toLocaleString()} of ${metrics.contingencyAmount.toLocaleString()} remaining
        </p>

        {/* Visual bar */}
        <div className="mt-auto">
          <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
            <div
              className={`h-full ${contBarColor} rounded-full transition-all duration-500`}
              style={{ width: `${Math.max(0, Math.min(100, metrics.contingencyRemaining))}%` }}
            />
          </div>
          <div className="flex justify-between mt-1 text-xs text-text-secondary">
            <span>Budget: ${metrics.baseBudget.toLocaleString()}</span>
            <span>Buffered: ${metrics.bufferedBudget.toLocaleString()}</span>
          </div>
        </div>
      </div>

      {/* Widget 3: Projected ROI */}
      <div className={`rounded-xl shadow-sm border border-border-accent p-5 flex flex-col ${roiBg}`}>
        <div className="flex items-center gap-2 mb-3">
          <TrendingUp className={`w-4 h-4 ${roiColor}`} />
          <p className="text-xs font-medium uppercase tracking-widest text-text-secondary">Projected ROI</p>
        </div>
        <p className={`text-3xl font-normal tracking-tight mb-1 ${roiColor}`}>
          {metrics.roi.toFixed(1)}%
        </p>
        <p className="text-xs text-text-secondary mb-3">
          Net Profit: <span className={`font-mono ${metrics.netProfit >= 0 ? 'text-green-600' : 'text-red-600'}`}>
            {metrics.netProfit >= 0 ? '' : '-'}${Math.abs(metrics.netProfit).toLocaleString()}
          </span>
        </p>

        {/* ROI gauge bar */}
        <div className="mt-auto">
          <div className="h-2 bg-gray-200 rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-[#7f7f7f] to-[#595959] rounded-full transition-all duration-500"
              style={{ width: `${Math.min(100, Math.max(0, metrics.roi))}%` }}
            />
          </div>
          <div className="flex justify-between mt-1 text-xs text-text-secondary">
            <span>0%</span>
            <span className="font-medium">Target: 20%+</span>
            <span>100%</span>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useCallback, useMemo } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { useAuth } from '@/context/AuthContext';
import type { LedgerItem } from '@/types/schema';
import {
  HardHat,
  ChevronDown,
  ChevronRight,
  Plus,
  Trash2,
  CheckCircle,
  Circle,
  AlertTriangle,
  Banknote,
  Users,
  FileCheck,
  TrendingUp,
  Loader2,
} from 'lucide-react';

// ── Component-local types ─────────────────────────────────────
// Persisted as extra fields on project.rehab via updateRehabModule.
// The store merge spreads the object, so extra keys survive JSON serialization.

interface BudgetLine {
  id: string;
  category: string;
  estimated: number;
}

interface ActualEntry {
  id: string;
  budgetLineId: string;
  vendor: string;
  description: string;
  amount: number;
  createdAt: string; // ISO string — avoids Date serialization issues
}

interface W9Record {
  vendor: string;
  w9Received: boolean;
}

interface DrawEntry {
  id: string;
  description: string;
  totalAmount: number;
  drawnAmount: number;
  pendingAmount: number;
  status: 'Pending Inspector' | 'Approved' | 'Rejected';
  requestedAt: string;
}

interface PermitEntry {
  id: string;
  type: string;
  municipality: string;
  appliedAt: string | null;
  approvedAt: string | null;
  finalSignOffAt: string | null;
  status: 'Not Filed' | 'Filed' | 'Approved' | 'Final Sign-Off' | 'Denied';
}

interface TrackerData {
  budgetLines: BudgetLine[];
  actualEntries: ActualEntry[];
  w9Records: W9Record[];
  drawEntries: DrawEntry[];
  permitEntries: PermitEntry[];
  contingencyPct: number;
  totalLoanAmount: number;
}

// ── Helpers ───────────────────────────────────────────────────

const EMPTY_TRACKER: TrackerData = {
  budgetLines: [],
  actualEntries: [],
  w9Records: [],
  drawEntries: [],
  permitEntries: [],
  contingencyPct: 0.15,
  totalLoanAmount: 0,
};

const DEFAULT_CATEGORIES = [
  'Demo', 'Foundation', 'Framing', 'Roofing', 'Plumbing',
  'Electrical', 'HVAC', 'Drywall', 'Flooring', 'Painting', 'Landscaping', 'Other',
];

function toLedgerCategory(cat: string): LedgerItem['category'] {
  const map: Record<string, LedgerItem['category']> = {
    Plumbing: 'Plumbing',
    Electrical: 'Electrical',
    Framing: 'Framing',
    HVAC: 'HVAC',
    Foundation: 'Foundation',
    Other: 'Other',
  };
  return map[cat] ?? 'General';
}

const fmt = (n: number) =>
  `$${n.toLocaleString(undefined, { minimumFractionDigits: 0, maximumFractionDigits: 0 })}`;

const PERMIT_BADGE: Record<PermitEntry['status'], string> = {
  'Not Filed': 'bg-bg-primary text-text-secondary',
  'Filed': 'bg-blue-50 text-blue-700',
  'Approved': 'bg-[#3f7d20]/15 text-[#3f7d20]',
  'Final Sign-Off': 'bg-[#3f7d20]/15 text-[#3f7d20]',
  'Denied': 'bg-[#F06543]/15 text-[#F06543]',
};

const DRAW_BADGE: Record<DrawEntry['status'], string> = {
  'Pending Inspector': 'bg-amber-50 text-amber-700',
  'Approved': 'bg-[#3f7d20]/15 text-[#3f7d20]',
  'Rejected': 'bg-[#F06543]/15 text-[#F06543]',
};

// ── Component ─────────────────────────────────────────────────

export default function RehabTracker() {
  const currentProject = useProjectStore(s => s.currentProject);
  const updateRehabModule = useProjectStore(s => s.updateRehabModule);
  const setLedgerItems = useProjectStore(s => s.setLedgerItems);
  const getLedgerItemsForProject = useProjectStore(s => s.getLedgerItemsForProject);
  const { user } = useAuth();
  const [isSaving, setIsSaving] = useState(false);

  const [data, setData] = useState<TrackerData>(() => {
    const stored = (currentProject?.rehab as any)?.rehabTracker as TrackerData | undefined;
    return stored ?? EMPTY_TRACKER;
  });

  const [open, setOpen] = useState({
    budget: true,
    contingency: true,
    contractors: false,
    draws: false,
    permits: false,
  });
  const toggle = (k: keyof typeof open) => setOpen(s => ({ ...s, [k]: !s[k] }));

  // ── Persist to store + ledger rollup ─────────────────────────
  const persist = useCallback(
    async (next: TrackerData) => {
      setData(next);
      if (!currentProject) return;

      const baseBudget = next.budgetLines.reduce((s, l) => s + l.estimated, 0);

      const rehabUpdates = {
        rehabTracker: next,
        baseBudget,
        contingencyBufferPercentage: next.contingencyPct,
      };

      updateRehabModule(currentProject.id, rehabUpdates as any);

      // Roll every actual cost entry into the global TransactionLedger so
      // recalculateMetrics() picks them up as 'Approved' renovation costs.
      const existing = getLedgerItemsForProject(currentProject.id);
      const nonTracker = existing.filter(i => !i.id.startsWith('rehab-tracker-'));
      const trackerItems: LedgerItem[] = next.actualEntries.map(e => ({
        id: `rehab-tracker-${e.id}`,
        projectId: currentProject.id,
        organizationId: currentProject.organizationId,
        type: 'expense' as const,
        category: toLedgerCategory(
          next.budgetLines.find(l => l.id === e.budgetLineId)?.category ?? 'Other'
        ),
        description: `${e.description} — ${e.vendor}`,
        amount: e.amount,
        status: 'Approved' as const,
        submittedByUid: 'rehab-tracker',
        createdAt: new Date(e.createdAt),
      }));
      setLedgerItems(currentProject.id, [...nonTracker, ...trackerItems]);

      if (!user) return;
      try {
        setIsSaving(true);
        const idToken = await user.getIdToken();

        await fetch('/api/projects/rehab', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
             idToken,
             projectId: currentProject.id,
             updates: rehabUpdates
          })
        });
      } catch (err) {
        console.error('Failed to save rehab state to backend', err);
      } finally {
        setIsSaving(false);
      }
    },
    [currentProject, updateRehabModule, getLedgerItemsForProject, setLedgerItems, user]
  );

  // ── Derived values ────────────────────────────────────────────
  const { budgetLines, actualEntries, w9Records, drawEntries, permitEntries, contingencyPct, totalLoanAmount } = data;

  const actualsByLine = useMemo(() => {
    const map: Record<string, number> = {};
    actualEntries.forEach(e => { map[e.budgetLineId] = (map[e.budgetLineId] ?? 0) + e.amount; });
    return map;
  }, [actualEntries]);

  const totalEstimated = budgetLines.reduce((s, l) => s + l.estimated, 0);
  const totalActual = actualEntries.reduce((s, e) => s + e.amount, 0);
  const totalVariance = totalEstimated - totalActual;

  const contingencyAmount = totalEstimated * contingencyPct;
  const overBudgetTotal = budgetLines.reduce((s, l) => {
    const actual = actualsByLine[l.id] ?? 0;
    return actual > l.estimated ? s + (actual - l.estimated) : s;
  }, 0);
  const contingencyUsedPct = contingencyAmount > 0
    ? Math.min((overBudgetTotal / contingencyAmount) * 100, 100)
    : 0;

  const vendorTotals = useMemo(() => {
    const map: Record<string, number> = {};
    actualEntries.forEach(e => { if (e.vendor) map[e.vendor] = (map[e.vendor] ?? 0) + e.amount; });
    return map;
  }, [actualEntries]);

  const totalDrawn = drawEntries.reduce((s, d) => s + d.drawnAmount, 0);
  const totalPendingDraw = drawEntries.reduce((s, d) => s + d.pendingAmount, 0);
  const drawPct = totalLoanAmount > 0 ? Math.min((totalDrawn / totalLoanAmount) * 100, 100) : 0;

  // ── Budget form state ─────────────────────────────────────────
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [budgetCat, setBudgetCat] = useState(DEFAULT_CATEGORIES[0]);
  const [budgetEst, setBudgetEst] = useState('');

  const addBudgetLine = () => {
    if (!budgetEst) return;
    persist({
      ...data,
      budgetLines: [...budgetLines, { id: `bl-${Date.now()}`, category: budgetCat, estimated: parseFloat(budgetEst) || 0 }],
    });
    setBudgetEst('');
    setShowBudgetForm(false);
  };

  const removeBudgetLine = (id: string) =>
    persist({
      ...data,
      budgetLines: budgetLines.filter(l => l.id !== id),
      actualEntries: actualEntries.filter(e => e.budgetLineId !== id),
    });

  // ── Actual cost entry state (inline per row) ──────────────────
  const [activeActualRow, setActiveActualRow] = useState<string | null>(null);
  const [actualVendor, setActualVendor] = useState('');
  const [actualDesc, setActualDesc] = useState('');
  const [actualAmt, setActualAmt] = useState('');

  const addActualEntry = (lineId: string) => {
    if (!actualAmt || !actualVendor) return;
    const entry: ActualEntry = {
      id: `ae-${Date.now()}`,
      budgetLineId: lineId,
      vendor: actualVendor,
      description: actualDesc || actualVendor,
      amount: parseFloat(actualAmt) || 0,
      createdAt: new Date().toISOString(),
    };
    const nextW9 = w9Records.find(r => r.vendor === actualVendor)
      ? w9Records
      : [...w9Records, { vendor: actualVendor, w9Received: false }];
    persist({ ...data, actualEntries: [...actualEntries, entry], w9Records: nextW9 });
    setActualVendor('');
    setActualDesc('');
    setActualAmt('');
    setActiveActualRow(null);
  };

  // ── Draw form state ───────────────────────────────────────────
  const [showDrawForm, setShowDrawForm] = useState(false);
  const [drawDesc, setDrawDesc] = useState('');
  const [drawTotal, setDrawTotal] = useState('');
  const [drawDrawn, setDrawDrawn] = useState('');
  const [drawPending, setDrawPending] = useState('');

  const addDrawEntry = () => {
    if (!drawDesc || !drawTotal) return;
    persist({
      ...data,
      drawEntries: [...drawEntries, {
        id: `de-${Date.now()}`,
        description: drawDesc,
        totalAmount: parseFloat(drawTotal) || 0,
        drawnAmount: parseFloat(drawDrawn) || 0,
        pendingAmount: parseFloat(drawPending) || 0,
        status: 'Pending Inspector',
        requestedAt: new Date().toISOString(),
      }],
    });
    setDrawDesc(''); setDrawTotal(''); setDrawDrawn(''); setDrawPending('');
    setShowDrawForm(false);
  };

  const updateDrawStatus = (id: string, status: DrawEntry['status']) =>
    persist({ ...data, drawEntries: drawEntries.map(d => d.id === id ? { ...d, status } : d) });

  // ── Permit form state ─────────────────────────────────────────
  const [showPermitForm, setShowPermitForm] = useState(false);
  const [permitType, setPermitType] = useState('');
  const [permitMuni, setPermitMuni] = useState('');

  const addPermit = () => {
    if (!permitType) return;
    persist({
      ...data,
      permitEntries: [...permitEntries, {
        id: `pe-${Date.now()}`,
        type: permitType,
        municipality: permitMuni,
        appliedAt: null,
        approvedAt: null,
        finalSignOffAt: null,
        status: 'Not Filed',
      }],
    });
    setPermitType(''); setPermitMuni('');
    setShowPermitForm(false);
  };

  const advancePermit = (id: string) => {
    const today = new Date().toISOString().slice(0, 10);
    persist({
      ...data,
      permitEntries: permitEntries.map(p => {
        if (p.id !== id) return p;
        if (p.status === 'Not Filed') return { ...p, status: 'Filed' as const, appliedAt: today };
