import React, { useState } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { Project, PendingReceipt, CostEntry } from '@/types/schema';
import { CheckCircle, XCircle, AlertTriangle, Paperclip, CheckSquare, Calendar as CalendarIcon, Loader2 } from 'lucide-react';
import { verifyContingencyBuffer } from '@/lib/contingencyEnforcer';
import toast from 'react-hot-toast';
import ESignAction from '@/components/shared/ESignAction';
import TeamChatWidget from '@/components/shared/TeamChatWidget';
import { projectsService } from '@/lib/firebase/projects';

export default function TriageQueue() {
    const projects = useProjectStore(state => state.projects);
    const ledgerItems = useProjectStore(state => state.ledgerItems);

    const handleApproveReceipt = async (deal: Project, item: any) => {
        // Enforce Contingency Buffer
        const validation = verifyContingencyBuffer(deal, item);

        if (!validation.canApprove) {
            toast.error(`CONTINGENCY BREACH: This approval forces the budget over the 15% buffer constraint by $${validation.exceedsBy.toLocaleString()}.`, { duration: 6000, icon: '🛑' });
            return;
        }

        try {
            await projectsService.updateLedgerItem(deal.id, item.id, { 
                status: 'Approved',
                updatedAt: new Date()
            });
            toast.success(`Expense Approved & Posted to global ledger.`);
        } catch (error) {
            toast.error('Failed to update ledger item.');
        }
    };

    const handleRejectReceipt = async (projectId: string, itemId: string) => {
        try {
            await projectsService.updateLedgerItem(projectId, itemId, { 
                status: 'Rejected',
                updatedAt: new Date()
            });
            toast('Expense Rejected and purged from Triage.', { icon: '🗑️' });
        } catch (error) {
            toast.error('Failed to reject item.');
        }
    };

    const pendingReceiptsData = projects.flatMap(deal => {
        const items = ledgerItems[deal.id] || [];
        return items
          .filter(item => item.status === 'Pending')
          .map(item => ({ receipt: item, deal }));
    });


    const [isSyncingGcal, setIsSyncingGcal] = useState(false);

    const handleGcalSync = async () => {
        setIsSyncingGcal(true);
        toast.loading('Syncing inspection schedule to Google Calendar...', { id: 'gcal' });
        try {
            const res = await fetch('/api/calendar/sync', { method: 'POST' });
            if (!res.ok) {
                const data = await res.json().catch(() => ({}));
                throw new Error(data.error || `Sync failed (${res.status})`);
            }
            toast.success('Synced to Google Calendar!', { id: 'gcal' });
        } catch (err: any) {
            toast.error(err.message || 'Failed to sync calendar', { id: 'gcal' });
        } finally {
            setIsSyncingGcal(false);
        }
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="lg:col-span-2 space-y-8">
            <div className="bg-bg-surface rounded-xl shadow-sm border border-border-accent">
               <div className="p-4 border-b border-border-accent flex justify-between items-center bg-bg-primary/50">
                   <h3 className="text-lg font-medium">Contingency Triage Matrix</h3>
                   <span className="bg-orange-100 text-orange-800 text-xs font-bold px-2.5 py-1 rounded-full uppercase tracking-wider">
                       {pendingReceiptsData.length} Action Required
                   </span>
               </div>

               <div className="p-0">
                  {pendingReceiptsData.length === 0 ? (
                      <div className="p-12 text-center text-text-secondary">
                          <CheckSquare className="w-12 h-12 mx-auto mb-3 text-green-300 opacity-50" />
                          <p>The Triage Queue is clear.</p>
                      </div>
                  ) : (
                      <div className="divide-y divide-gray-100">
                           {pendingReceiptsData.map(({ receipt, deal }) => {
                               const validation = verifyContingencyBuffer(deal, receipt);
                               const isDanger = validation.projectedTotal > validation.rehabBudgetBase; // Passed baseline but under buffer
                               const isBreach = !validation.canApprove;

                               return (
                                   <div key={receipt.id} className={`flex flex-col md:flex-row p-6 gap-6 ${isBreach ? 'bg-red-50/30' : ''}`}>
                                       {/* Image Viewer */}
                                       <div className="md:w-1/3 bg-bg-primary rounded-lg aspect-auto flex items-center justify-center relative overflow-hidden border border-border-accent min-h-[200px]">
                                            {receipt.receiptUrl ? (
                                                <img src={receipt.receiptUrl} alt="Receipt Evidence" loading="lazy" className="absolute inset-0 w-full h-full object-cover opacity-90 mix-blend-multiply" />
                                            ) : (
                                                <div className="flex flex-col items-center justify-center text-text-tertiary">
                                                    <Paperclip className="w-8 h-8 mb-2 opacity-20" />
                                                    <span className="text-xs uppercase tracking-widest font-semibold opacity-50">No Receipt Uploaded</span>
                                                </div>
                                            )}
                                            <div className="z-10 absolute bottom-3 right-3 bg-black/60 backdrop-blur text-white text-xs px-2 py-1 rounded flex items-center">
                                               <Paperclip className="w-3 h-3 mr-1"/> {receipt.receiptUrl ? 'Attached Evidence' : 'No Evidence'}
                                            </div>
                                       </div>

                                       {/* Data Validation Side */}
                                       <div className="md:w-2/3 flex flex-col pl-4">
                                           <div className="flex justify-between items-start">
                                               <div>
                                                   <p className="text-xs text-text-secondary uppercase tracking-widest mb-1">{deal.propertyName}</p>
                                                   <h4 className="text-xl font-bold text-text-primary">${receipt.amount.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h4>
                                                   <p className="text-sm text-text-secondary border border-border-accent bg-bg-primary px-2 py-0.5 rounded inline-block mt-2">{receipt.description}</p>
                                               </div>

                                               <div className="text-right">
                                                   <p className="text-xs text-text-secondary">Submitted by: <span className="font-medium text-text-primary">General Contractor</span></p>
                                                   <p className="text-xs text-text-secondary mt-1">{new Date(receipt.createdAt).toLocaleString()}</p>
                                               </div>
                                           </div>

                                           {/* Buffer Intelligence */}
                                           <div className="mt-6">
                                               <div className="flex justify-between text-xs mb-1">
                                                   <span className="text-text-secondary">Base Budget: ${validation.rehabBudgetBase.toLocaleString()}</span>
                                                   <span className="text-text-secondary flex items-center"><AlertTriangle className="w-3 h-3 mr-1 text-orange-400"/> Max Buffer: ${validation.rehabBudgetBuffered.toLocaleString()}</span>
                                               </div>
                                               <div className="w-full bg-gray-200 rounded-full h-2">
                                                   <div 
                                                       className={`h-2 rounded-full ${isBreach ? 'bg-red-500' : isDanger ? 'bg-orange-400' : 'bg-blue-500'}`} 
                                                       style={{ width: `${Math.min(100, (validation.projectedTotal / validation.rehabBudgetBuffered) * 100)}%` }}></div>
                                               </div>
                                               <p className={`text-xs mt-2 font-medium ${isBreach ? 'text-red-600' : isDanger ? 'text-orange-600' : 'text-text-secondary'}`}>
                                                   {isBreach 
                                                       ? `WARNING: Exceeds Contingency Enforcer by $${validation.exceedsBy.toLocaleString()}` 
                                                       : isDanger 
                                                       ? `CAUTION: Tapping into 15% Contingency Escrow (${(((validation.projectedTotal-validation.rehabBudgetBase)/(validation.rehabBudgetBuffered-validation.rehabBudgetBase))*100).toFixed(1)}% utilized)` 
                                                       : 'Safe: Operates within original scope parameters.'}
                                               </p>
                                           </div>

                                           {/* Triage Action Constraints */}
                                           <div className="mt-auto pt-6 flex flex-col gap-3">
                                               <div className="flex gap-3">
                                                    <button onClick={() => handleApproveReceipt(deal, receipt)} disabled={isBreach} className="flex-1 bg-green-600 hover:bg-green-700 disabled:bg-gray-300 disabled:cursor-not-allowed text-white py-2 rounded-lg text-sm font-medium transition flex items-center justify-center">
                                                        <CheckCircle className="w-4 h-4 mr-2" /> Approve & Post
                                                    </button>
                                                    <button onClick={() => handleRejectReceipt(deal.id, receipt.id)} className="flex-x bg-bg-surface border border-border-accent hover:bg-red-50 hover:border-red-300 hover:text-red-600 text-text-primary px-6 py-2 rounded-lg text-sm font-medium transition flex items-center justify-center">
                                                        <XCircle className="w-4 h-4 mr-2" /> Reject
                                                    </button>
                                               </div>

                                               <div className="flex items-center gap-3 mt-1 pt-3 border-t border-border-accent">
                                                    <ESignAction 
                                                        documentName={`Lien Waiver - ${receipt.description}`}
                                                        signeeRole="General Contractor"
                                                        onSigned={() => {}} 
                                                    />
                                                    <button onClick={handleGcalSync} disabled={isSyncingGcal} className="bg-blue-50 text-blue-700 border border-blue-200 hover:bg-blue-100 px-3 py-1.5 rounded-lg text-xs font-semibold flex items-center gap-1.5 transition disabled:opacity-50">
                                                        {isSyncingGcal ? <Loader2 className="w-3.5 h-3.5 animate-spin"/> : <CalendarIcon className="w-3.5 h-3.5" />}
                                                        Sync GCal
                                                    </button>
                                               </div>
                                           </div>
                                       </div>
                                   </div>
                               );
                           })}
                      </div>
                  )}
               </div>
            </div>
            </div>

            <div className="lg:col-span-1 space-y-6">
                <TeamChatWidget projectId={pendingReceiptsData[0]?.deal?.id || 'triage'} />
            </div>
        </div>
    );
}

'use client';

import React, { useMemo } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { Building, Wallet, Landmark, Scale } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Balance Sheet — Point-in-Time Snapshot
   ─────────────────────────────────────────────────────
   Assets: Property inventory + Cash
   Liabilities: Hard money debt + Private lender equity
   Equity: Assets - Liabilities
   ═══════════════════════════════════════════════════════ */

function formatCurrency(val: number): string {
  const neg = val < 0;
  return `${neg ? '-' : ''}$${Math.abs(val).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
}

interface BSSection {
  label: string;
  amount: number;
  indent?: boolean;
  bold?: boolean;
  highlight?: boolean;
}

export default function BalanceSheet() {
  const projects = useProjectStore(s => s.projects);

  const bs = useMemo(() => {
    // ─── ASSETS ───────────────────────────────────
    let propertyInventory = 0;       // Active projects at value
    let cashFromSales = 0;           // Net proceeds from sold projects
    let totalInvestorContributions = 0;

    // ─── LIABILITIES ─────────────────────────────
    let hardMoneyDebt = 0;          // Outstanding loan balances
    let privateLenderEquity = 0;    // Fractional investor contributions

    const assetDetails: { name: string; value: number; status: string }[] = [];
    const liabilityDetails: { name: string; value: number; type: string }[] = [];

    projects.forEach(deal => {
      const fin = deal.financials;
      if (!fin) return;

      if (deal.status === 'exit' && deal.dispositionType === 'SALE') {
        // Sold projects become cash
        const salePrice = fin.actualSalePrice || 0;
        const buyerComm = salePrice * ((fin.buyersAgentCommission || 0) / 100);
        const sellerComm = salePrice * ((fin.sellersAgentCommission || 0) / 100);
        const basicClosingCosts = fin.finalClosingCosts || 0;

        // Include ledger-based exit costs
        let ledgerExitCosts = 0;
        deal.exitCosts?.forEach(ec => {
          if (ec.isPercentage && ec.percentageRate) {
            ledgerExitCosts += (ec.percentageRate / 100) * salePrice;
          } else {
            ledgerExitCosts += ec.amount;
          }
        });

        const netProceeds = salePrice - buyerComm - sellerComm - basicClosingCosts - ledgerExitCosts;
        cashFromSales += netProceeds;
        assetDetails.push({ name: deal.propertyName, value: netProceeds, status: 'Sold → Cash' });
      } else {
        // Active projects are inventory at current valuation
        // Use purchase price + rehab spend as "book value"
        const bookValue = (fin.purchasePrice || 0) +
          (fin.costs?.filter(c => c.approved).reduce((s, c) => s + c.amount, 0) || 0);
        propertyInventory += bookValue;
        assetDetails.push({ name: deal.propertyName, value: bookValue, status: deal.status });

        // Outstanding debt on active projects
        const loanAmt = fin.loanAmount || 0;
        if (loanAmt > 0) {
          hardMoneyDebt += loanAmt;
          liabilityDetails.push({ name: `Loan: ${deal.propertyName}`, value: loanAmt, type: 'Hard Money' });
        }
      }

      // Private investor equity (fractional investors)
      deal.fractionalInvestors?.forEach(inv => {
        if (inv.status === 'confirmed') {
          privateLenderEquity += inv.contributionAmount;
          totalInvestorContributions += inv.contributionAmount;
          liabilityDetails.push({ name: `${inv.name} (${inv.equityPercentage}%)`, value: inv.contributionAmount, type: 'Investor Equity' });
        }
      });
    });

    const totalAssets = propertyInventory + cashFromSales;
    const totalLiabilities = hardMoneyDebt + privateLenderEquity;
    const ownerEquity = totalAssets - totalLiabilities;

    return {
      propertyInventory,
      cashFromSales,
      totalAssets,
      hardMoneyDebt,
      privateLenderEquity,
      totalLiabilities,
      ownerEquity,
      assetDetails,
      liabilityDetails,
    };
  }, [projects]);

  const assetLines: BSSection[] = [
    { label: 'ASSETS', amount: 0, bold: true },
