'use client';

import React, { useMemo } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { AlertTriangle, ArrowDownCircle, ArrowUpCircle, TrendingDown } from 'lucide-react';

/* ═══════════════════════════════════════════════════════
   Cash Flow Statement — Monthly Money In / Money Out
   ─────────────────────────────────────────────────────
   Tracks liquidity to ensure the user doesn't run out
   of cash mid-rehab. Red flags negative balance months.
   ═══════════════════════════════════════════════════════ */

interface MonthBucket {
  key: string;           // "2026-01"
  label: string;         // "Jan 2026"
  inflows: number;       // Money coming in
  outflows: number;      // Money going out
  netCashFlow: number;   // inflows - outflows
  cumulativeBalance: number;
  inflowDetails: { label: string; amount: number }[];
  outflowDetails: { label: string; amount: number }[];
}

function formatCurrency(val: number): string {
  const neg = val < 0;
  return `${neg ? '-' : ''}$${Math.abs(val).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
}

function getMonthKey(date: Date | string): string {
  const d = new Date(date);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

function getMonthLabel(key: string): string {
  const [y, m] = key.split('-');
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  return `${months[parseInt(m) - 1]} ${y}`;
}

export default function CashFlowStatement() {
  const projects = useProjectStore(s => s.projects);

  const monthlyData = useMemo(() => {
    const buckets: Record<string, { inflows: number; outflows: number; inflowDetails: { label: string; amount: number }[]; outflowDetails: { label: string; amount: number }[] }> = {};

    const ensureBucket = (key: string) => {
      if (!buckets[key]) buckets[key] = { inflows: 0, outflows: 0, inflowDetails: [], outflowDetails: [] };
    };

    projects.forEach(deal => {
      const fin = deal.financials;
      if (!fin) return;
      const propName = deal.propertyName;

      // Outflow — Purchase Price (at deal creation)
      if (deal.createdAt) {
        const key = getMonthKey(deal.createdAt);
        ensureBucket(key);
        const pp = fin.purchasePrice || 0;
        if (pp > 0) {
          buckets[key].outflows += pp;
          buckets[key].outflowDetails.push({ label: `Purchase: ${propName}`, amount: pp });
        }
      }

      // Outflow — Approved Cost Entries (rehab)
      fin.costs?.forEach(cost => {
        if (!cost.approved || !cost.createdAt) return;
        const key = getMonthKey(cost.createdAt);
        ensureBucket(key);
        buckets[key].outflows += cost.amount;
        buckets[key].outflowDetails.push({ label: `${cost.category || 'Rehab'}: ${cost.description}`, amount: cost.amount });
      });

      // Outflow — Rehab Expenses
      deal.rehabExpenses?.forEach(exp => {
        if (!exp.paid || !exp.createdAt) return;
        const key = getMonthKey(exp.createdAt);
        ensureBucket(key);
        buckets[key].outflows += exp.amount;
        buckets[key].outflowDetails.push({ label: `${exp.category}: ${exp.description}`, amount: exp.amount });
      });

      // Outflow — Holding Costs (spread over months)
      deal.holdingCosts?.forEach(hc => {
        // Distribute across months from deal start
        const startDate = new Date(deal.createdAt || new Date());
        for (let m = 0; m < hc.monthsPaid; m++) {
          const mDate = new Date(startDate);
          mDate.setMonth(mDate.getMonth() + m);
          const key = getMonthKey(mDate);
          ensureBucket(key);
          buckets[key].outflows += hc.monthlyAmount;
          buckets[key].outflowDetails.push({ label: `${hc.type}: ${propName}`, amount: hc.monthlyAmount });
        }
      });

      // Inflow — Sale Proceeds
      if (deal.status === 'exit' && deal.dispositionType === 'SALE' && fin.actualSalePrice && fin.soldDate) {
        const key = getMonthKey(fin.soldDate);
        ensureBucket(key);
        buckets[key].inflows += fin.actualSalePrice;
        buckets[key].inflowDetails.push({ label: `Sale: ${propName}`, amount: fin.actualSalePrice });
      }

      // Inflow — Investor Pledges (confirmed)
      deal.pledges?.forEach(pledge => {
        if (pledge.status !== 'confirmed' || !pledge.pledgedAt) return;
        const key = getMonthKey(pledge.pledgedAt);
        ensureBucket(key);
        buckets[key].inflows += pledge.pledgeAmount;
        buckets[key].inflowDetails.push({ label: `Pledge: ${pledge.investorName}`, amount: pledge.pledgeAmount });
      });
    });

    // Sort by month key and compute cumulative
    const sortedKeys = Object.keys(buckets).sort();
    let cumulative = 0;
    const result: MonthBucket[] = sortedKeys.map(key => {
      const b = buckets[key];
      const net = b.inflows - b.outflows;
      cumulative += net;
      return {
        key,
        label: getMonthLabel(key),
        inflows: b.inflows,
        outflows: b.outflows,
        netCashFlow: net,
        cumulativeBalance: cumulative,
        inflowDetails: b.inflowDetails,
        outflowDetails: b.outflowDetails,
      };
    });

    return result;
  }, [projects]);

  const totalInflows = monthlyData.reduce((s, m) => s + m.inflows, 0);
  const totalOutflows = monthlyData.reduce((s, m) => s + m.outflows, 0);
  const negativeMonths = monthlyData.filter(m => m.cumulativeBalance < 0);

  // Expanded month detail state
  const [expandedMonth, setExpandedMonth] = React.useState<string | null>(null);

  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="border-b-2 border-gray-900 pb-2">
        <h4 className="text-sm font-bold tracking-widest uppercase text-text-primary">
          Cash Flow Statement
        </h4>
        <p className="text-xs text-text-secondary mt-0.5">
          Portfolio — Monthly Liquidity Tracker · {new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
        </p>
      </div>

      {/* Cash Crunch Warning */}
      {negativeMonths.length > 0 && (
        <div className="flex items-start gap-3 p-4 bg-red-50 border border-red-200 rounded-lg">
          <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
          <div>
            <p className="text-sm font-semibold text-red-800">Liquidity Warning</p>
            <p className="text-xs text-red-600 mt-0.5">
              {negativeMonths.length} month{negativeMonths.length > 1 ? 's' : ''} show negative cumulative balance.
              Cash reserves may be insufficient during active rehab periods.
            </p>
          </div>
        </div>
      )}

      {/* Summary Tiles */}
      <div className="grid grid-cols-3 gap-3">
        <div className="p-3 bg-pw-success-container rounded-lg text-center border border-pw-success-border">
          <ArrowDownCircle className="w-4 h-4 text-pw-success mx-auto mb-1" />
          <p className="text-xs uppercase tracking-widest text-pw-success">Total Inflows</p>
          <p className="text-lg font-normal text-pw-success">{formatCurrency(totalInflows)}</p>
        </div>
        <div className="p-3 bg-red-50 rounded-lg text-center border border-red-100">
          <ArrowUpCircle className="w-4 h-4 text-red-500 mx-auto mb-1" />
          <p className="text-xs uppercase tracking-widest text-red-600">Total Outflows</p>
          <p className="text-lg font-normal text-red-700">{formatCurrency(totalOutflows)}</p>
        </div>
        <div className={`p-3 rounded-lg text-center border ${totalInflows - totalOutflows >= 0 ? 'bg-bg-primary border-border-accent' : 'bg-red-50 border-red-100'}`}>
          <TrendingDown className="w-4 h-4 text-text-secondary mx-auto mb-1" />
          <p className="text-xs uppercase tracking-widest text-text-secondary">Net Cash Flow</p>
          <p className={`text-lg font-normal ${totalInflows - totalOutflows >= 0 ? 'text-text-primary' : 'text-red-600'}`}>
            {formatCurrency(totalInflows - totalOutflows)}
          </p>
        </div>
      </div>

      {/* Monthly Table */}
      {monthlyData.length === 0 ? (
        <div className="p-10 text-center text-sm text-text-secondary border-2 border-dashed border-border-accent rounded-xl">
          No transaction data available. Add projects with financial entries to populate the cash flow.
        </div>
      ) : (
        <div className="border border-border-accent rounded-lg overflow-hidden">
          <table className="w-full text-sm" id="cashflow-statement-table">
            <thead>
              <tr className="bg-bg-primary">
                <th className="text-left px-4 py-2.5 text-xs font-bold uppercase tracking-widest text-text-secondary">Month</th>
                <th className="text-right px-4 py-2.5 text-xs font-bold uppercase tracking-widest text-pw-success">Inflows</th>
                <th className="text-right px-4 py-2.5 text-xs font-bold uppercase tracking-widest text-red-500">Outflows</th>
                <th className="text-right px-4 py-2.5 text-xs font-bold uppercase tracking-widest text-text-secondary">Net Cash</th>
                <th className="text-right px-4 py-2.5 text-xs font-bold uppercase tracking-widest text-text-secondary">Balance</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {monthlyData.map(month => (
                <React.Fragment key={month.key}>
                  <tr
                    onClick={() => setExpandedMonth(expandedMonth === month.key ? null : month.key)}
                    className={`cursor-pointer transition-colors ${
                      month.cumulativeBalance < 0 ? 'bg-red-50 hover:bg-red-100' : 'hover:bg-bg-primary'
                    }`}
                  >
                    <td className="px-4 py-2.5 font-medium text-text-primary">{month.label}</td>
                    <td className="px-4 py-2.5 text-right font-mono text-pw-success">
                      {month.inflows > 0 ? formatCurrency(month.inflows) : '—'}
                    </td>
                    <td className="px-4 py-2.5 text-right font-mono text-red-600">
                      {month.outflows > 0 ? `(${formatCurrency(month.outflows)})` : '—'}
                    </td>
                    <td className={`px-4 py-2.5 text-right font-mono ${month.netCashFlow >= 0 ? 'text-text-primary' : 'text-red-600'}`}>
                      {formatCurrency(month.netCashFlow)}
                    </td>
                    <td className={`px-4 py-2.5 text-right font-mono font-semibold ${month.cumulativeBalance >= 0 ? 'text-text-primary' : 'text-red-700'}`}>
                      {formatCurrency(month.cumulativeBalance)}
                      {month.cumulativeBalance < 0 && (
                        <AlertTriangle className="w-3 h-3 text-red-500 inline ml-1" />
                      )}
                    </td>
                  </tr>
                  {/* Expanded detail */}
                  {expandedMonth === month.key && (
                    <tr>
                      <td colSpan={5} className="px-4 py-3 bg-bg-primary">
                        <div className="grid grid-cols-2 gap-4 text-xs">
                          <div>
                            <p className="font-semibold text-pw-success mb-1">Inflow Details</p>
                            {month.inflowDetails.length === 0 ? (
                              <p className="text-text-secondary italic">No inflows this month</p>
                            ) : (
                              month.inflowDetails.map((d, i) => (
                                <div key={i} className="flex justify-between py-0.5">
                                  <span className="text-text-secondary">{d.label}</span>
                                  <span className="font-mono text-pw-success">{formatCurrency(d.amount)}</span>
                                </div>
                              ))
                            )}
                          </div>
                          <div>
                            <p className="font-semibold text-red-600 mb-1">Outflow Details</p>
                            {month.outflowDetails.length === 0 ? (
                              <p className="text-text-secondary italic">No outflows this month</p>
                            ) : (
                              month.outflowDetails.map((d, i) => (
                                <div key={i} className="flex justify-between py-0.5">
                                  <span className="text-text-secondary truncate mr-2">{d.label}</span>
                                  <span className="font-mono text-red-600">{formatCurrency(d.amount)}</span>
                                </div>
                              ))
                            )}
                          </div>
                        </div>
                      </td>
                    </tr>
                  )}
                </React.Fragment>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { FileDown, FileText } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import toast from 'react-hot-toast';
import { computeFlipMetrics, computeAutopsyMetrics } from '@/lib/metrics';

export default function LenderPackagePdf() {
  const projects = useProjectStore(state => state.projects);
  const [selectedDealId, setSelectedDealId] = useState<string>('');

  const handleGeneratePdf = () => {
    if (!selectedDealId) return toast.error("Select a deal to generate a package.");
    const deal = projects.find(d => d.id === selectedDealId);
    if (!deal) return;

    try {
      const doc = new jsPDF();

      // Header
      doc.addImage('/brand/PaperWorking_Black_full_Logo_.png', 'PNG', 14, 10, 30.4, 5);

      doc.setFontSize(20);
      doc.setTextColor(33, 33, 33);
      doc.text("LENDER EXECUTIVE SUMMARY", 14, 25);

      doc.setFontSize(11);
      doc.setTextColor(100, 100, 100);
      doc.text(`Generated on: ${new Date().toLocaleDateString()}`, 14, 32);

      // Property Info
      doc.setFontSize(14);
      doc.setTextColor(33, 33, 33);
      doc.text(`Target Property: ${deal.propertyName}`, 14, 44);
      doc.setFontSize(11);
      doc.text(`Address: ${deal.address}`, 14, 50);
      doc.text(`Current Phase: ${deal.status.toUpperCase()}`, 14, 56);

      // Projected metrics via @metrics
      const flip = computeFlipMetrics(deal);
      const approvedCostEntries = deal.financials.costs?.filter(c => c.approved) || [];

      // Realized metrics via @metrics (Sold deals only)
      let realizedROIHeadline = "N/A (Property Active)";
      if (deal.status === 'exit' && deal.dispositionType === 'SALE') {
        const autopsy = computeAutopsyMetrics(deal);
        realizedROIHeadline = `${autopsy.roi.toFixed(1)}% (Profit: $${Math.round(autopsy.netProfit).toLocaleString()})`;
      }

      // Tables
      autoTable(doc, {
        startY: 69,
        head: [['Metric', 'Value']],
        body: [
          ['Purchase Price', `$${(deal.financials.purchasePrice || 0).toLocaleString()}`],
          ['After-Repair Value (ARV)', `$${flip.arv.toLocaleString()}`],
          ['Estimated Rehab Budget', `$${flip.rehabBudget.toLocaleString()}`],
          ['Actual Rehab Spend (To-Date)', `$${flip.rehabActual.toLocaleString()}`],
          ['Projected Profit', `$${Math.round(flip.netProjectedProfit).toLocaleString()}`],
          ['Projected ROI', `${flip.roi.toFixed(1)}%`],
          ['Realized Performance', realizedROIHeadline],
        ],
        theme: 'grid',
        headStyles: { fillColor: [41, 128, 185], textColor: 255 },
        styles: { fontSize: 11, cellPadding: 4 },
      });

      // Rehab Breakdown Line Items
      if (approvedCostEntries.length > 0) {
        const finalY = (doc as any).lastAutoTable.finalY || 65;
        doc.setFontSize(14);
        doc.text("Rehab & Value-Add Expenditures", 14, finalY + 15);

        const costRows = approvedCostEntries.map(c => [
          new Date(c.createdAt).toLocaleDateString(),
          c.category || 'Other',
          c.description,
          `$${c.amount.toLocaleString()}`,
        ]);

        autoTable(doc, {
          startY: finalY + 20,
          head: [['Date', 'Category', 'Description', 'Amount']],
          body: costRows,
          theme: 'striped',
          headStyles: { fillColor: [100, 100, 100] },
        });
      }

      // Output Document
      const filename = `Lender_Package_${deal.propertyName.replace(/\s+/g, '_')}.pdf`;
      doc.save(filename);
      toast.success(`Generated Lender Package: ${filename}`);
    } catch (e) {
      console.error(e);
      toast.error("Failed to generate PDF. Check console.");
    }
  };

  return (
    <div className="bg-bg-surface border border-border-accent rounded-xl p-6 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-4">
      <div>
         <h3 className="text-lg font-bold text-text-primary flex items-center gap-2"><FileText className="w-5 h-5 text-blue-600"/> Lender Package Generator</h3>
         <p className="text-sm text-text-secondary mt-1">Export professional PDF reports combining ARV, actual rehabs, and ROI to secure funding.</p>
      </div>
      <div className="flex gap-3">
         <select
           value={selectedDealId}
           onChange={(e) => setSelectedDealId(e.target.value)}
           className="border border-border-accent rounded-lg text-sm p-2 bg-bg-primary focus:ring-2 focus:ring-blue-500 focus:outline-none min-w-[200px]"
         >
           <option value="" disabled>Select Property...</option>
           {projects.map(d => (
              <option key={d.id} value={d.id}>{d.propertyName} ({d.status})</option>
           ))}
         </select>
         <button
           onClick={handleGeneratePdf}
           disabled={!selectedDealId}
           className="bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:bg-blue-700 transition active:scale-95 disabled:opacity-50 flex items-center justify-center gap-2 min-w-[150px]"
         >
           <FileDown className="w-4 h-4" />
           Download PDF
         </button>
      </div>
    </div>
  );
}

