'use client';

import React, { useState, useCallback } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { storage, auth } from '@/lib/firebase/config';
import { ref, uploadBytesResumable, getDownloadURL } from 'firebase/storage';
import type { SettlementDocument, SettlementDocumentType, ExitCostLineItem, ExitCostCategory } from '@/types/schema';
import {
  Upload,
  FileCheck2,
  Clock,
  CheckCircle2,
  AlertCircle,
  ChevronDown,
  ChevronRight,
  Save,
  X,
  FileText,
  DollarSign,
  Loader2,
} from 'lucide-react';
import toast from 'react-hot-toast';

/* ═══════════════════════════════════════════════════════
   Settlement Document Portal
   ─────────────────────────────────────────────────────
   HUD-1 / Closing Disclosure Upload & Verification
    Document vault structure with manual override form
   ═══════════════════════════════════════════════════════ */

const ACCEPTED_TYPES = ['application/pdf', 'image/jpeg', 'image/png'];

interface VerificationField {
  key: keyof Pick<SettlementDocument, 'extractedAcquisitionCost' | 'extractedDispositionCost' | 'extractedLoanPayoff' | 'extractedTitleFees' | 'extractedRecordingFees' | 'extractedTransferTaxes'>;
  label: string;
}

const VERIFICATION_FIELDS: VerificationField[] = [
  { key: 'extractedAcquisitionCost', label: 'Total Acquisition Cost' },
  { key: 'extractedDispositionCost', label: 'Total Disposition Cost' },
  { key: 'extractedLoanPayoff', label: 'Loan Payoff Amount' },
  { key: 'extractedTitleFees', label: 'Title & Escrow Fees' },
  { key: 'extractedRecordingFees', label: 'Recording Fees' },
  { key: 'extractedTransferTaxes', label: 'Transfer Taxes' },
];

export default function SettlementDocPortal() {
  const projects = useProjectStore(s => s.projects);
  const updateSettlementDocuments = useProjectStore(s => s.updateSettlementDocuments);
  const updateProjectFinancials = useProjectStore(s => s.updateProjectFinancials);
  const updateExitCosts = useProjectStore(s => s.updateExitCosts);

  const [selectedDealId, setSelectedDealId] = useState<string>('');
  const [expandedDocId, setExpandedDocId] = useState<string | null>(null);
  const [showUpload, setShowUpload] = useState(false);
  const [dragOver, setDragOver] = useState(false);

  // Upload & Processing state
  const [isUploading, setIsUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isProcessing, setIsProcessing] = useState(false);

  // Upload form state
  const [uploadType, setUploadType] = useState<SettlementDocumentType>('HUD-1');
  const [uploadFile, setUploadFile] = useState<File | null>(null);

  const selectedDeal = projects.find(d => d.id === selectedDealId);
  const documents = selectedDeal?.settlementDocuments || [];

  const handleFileSelect = useCallback((file: File) => {
    if (!ACCEPTED_TYPES.includes(file.type)) {
      toast.error('Invalid file type. Please upload a PDF, JPEG, or PNG.');
      return;
    }
    if (file.size > 25 * 1024 * 1024) {
      toast.error('File too large. Maximum 25MB.');
      return;
    }
    setUploadFile(file);
  }, []);

  const handleDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files[0];
    if (file) handleFileSelect(file);
  }, [handleFileSelect]);

  const handleUpload = async () => {
    if (!selectedDealId || !uploadFile) {
      toast.error('Select a deal and file first.');
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      // 1. Upload to Firebase Storage
      const storagePath = `projects/${selectedDealId}/settlement_docs/${Date.now()}_${uploadFile.name}`;
      const storageRef = ref(storage, storagePath);
      const uploadTask = uploadBytesResumable(storageRef, uploadFile);

      const downloadUrl = await new Promise<string>((resolve, reject) => {
        uploadTask.on(
          'state_changed',
          (snapshot) => {
            const progress = (snapshot.bytesTransferred / snapshot.totalBytes) * 100;
            setUploadProgress(progress);
          },
          (error) => reject(error),
          async () => {
            const url = await getDownloadURL(uploadTask.snapshot.ref);
            resolve(url);
          }
        );
      });

      setIsUploading(false);
      setIsProcessing(true);
      toast.loading('Processing document...', { id: 'process-toast' });

      const newDoc: SettlementDocument = {
        id: crypto.randomUUID(),
        projectId: selectedDealId,
        type: uploadType,
        fileName: uploadFile.name,
        fileUrl: downloadUrl,
        uploadedAt: new Date(),
        verified: false,
        extractedAcquisitionCost: 0,
        extractedDispositionCost: 0,
        extractedLoanPayoff: 0,
        extractedTitleFees: 0,
        extractedRecordingFees: 0,
        extractedTransferTaxes: 0,
        notes: `Uploaded manually on ${new Date().toLocaleDateString()}. Please enter details.`,
      };

      const updatedDocs = [...documents, newDoc];
      updateSettlementDocuments(selectedDealId, updatedDocs);

      setIsProcessing(false);
      toast.dismiss('process-toast');
      toast.success(`${uploadType} uploaded successfully!`, { icon: '✨' });

      setUploadFile(null);
      setShowUpload(false);
      setExpandedDocId(newDoc.id); // Expand the newly added doc for verification
    } catch (error: any) {
      console.error('Upload Error:', error);
      setIsUploading(false);
      setIsProcessing(false);
      toast.error(`Upload failed: ${error.message}`);
    }
  };

  const updateDocField = (docId: string, field: string, value: unknown) => {
    if (!selectedDealId) return;
    const updated = documents.map(d =>
      d.id === docId ? { ...d, [field]: value } : d
    );
    updateSettlementDocuments(selectedDealId, updated);
  };

  const verifyDocument = (docId: string) => {
    if (!selectedDealId) return;
    const updated = documents.map(d =>
      d.id === docId ? { ...d, verified: true, verifiedAt: new Date() } : d
    );
    updateSettlementDocuments(selectedDealId, updated);
    toast.success('Document verified and values locked.', { icon: '✅' });
  };

  const removeDocument = (docId: string) => {
    if (!selectedDealId) return;
    const updated = documents.filter(d => d.id !== docId);
    updateSettlementDocuments(selectedDealId, updated);
    toast.success('Document removed.');
  };

  const applyToExitHub = (doc: SettlementDocument) => {
    if (!doc.verified) {
      toast.error('Verify the document before applying values.');
      return;
    }

    if (!selectedDealId) return;

    // 1. Update Core Financials (Purchase Price & Loan Payoff)
    updateProjectFinancials(selectedDealId, {
      purchasePrice: doc.extractedAcquisitionCost || selectedDeal?.financials.purchasePrice,
      loanAmount: doc.extractedLoanPayoff || selectedDeal?.financials.loanAmount,
    });

    // 2. Map Fees to Exit Ledger
    const existingExitCosts = selectedDeal?.exitCosts || [];
    const newExitCosts: ExitCostLineItem[] = [...existingExitCosts];

    const feeMappings: { label: string; amount?: number; category: ExitCostCategory }[] = [
      { label: `Title & Escrow Fees (${doc.type})`, amount: doc.extractedTitleFees, category: 'Other' },
      { label: `Recording Fees (${doc.type})`, amount: doc.extractedRecordingFees, category: 'Other' },
      { label: `Transfer Taxes (${doc.type})`, amount: doc.extractedTransferTaxes, category: 'Other' },
    ];

    feeMappings.forEach(fee => {
      if (fee.amount && fee.amount > 0) {
        // Check if already added to avoid duplicates if user clicks twice
        const exists = existingExitCosts.some(e => e.label === fee.label);
        if (!exists) {
          newExitCosts.push({
            id: crypto.randomUUID(),
            category: fee.category,
            label: fee.label,
            amount: fee.amount,
            isPercentage: false,
            paid: true,
            paidAt: new Date(),
            notes: `Extracted from ${doc.fileName}`,
          });
        }
      }
    });

    if (newExitCosts.length > existingExitCosts.length) {
      updateExitCosts(selectedDealId, newExitCosts);
    }

    toast.success('Settlement values applied to Exit Hub financials.', { 
      icon: '🔗',
      duration: 4000 
    });
  };


  return (
    <div className="space-y-5">
      {/* Header */}
      <div className="border-b-2 border-gray-900 pb-2">
        <h4 className="text-sm font-bold tracking-widest uppercase text-text-primary">
          Settlement Document Portal
        </h4>
        <p className="text-xs text-text-secondary mt-0.5">
          Upload HUD-1 & Closing Disclosure documents for cost extraction
        </p>
      </div>

      {/* Deal Selector */}
      <div className="flex flex-wrap items-center gap-3">
        <select
          value={selectedDealId}
          onChange={e => setSelectedDealId(e.target.value)}
          className="border border-border-accent rounded-lg text-sm py-2 px-3 focus:ring-1 focus:ring-gray-400 outline-none bg-bg-surface min-w-[220px]"
        >
          <option value="" disabled>Select Property...</option>
          {projects.map(d => (
            <option key={d.id} value={d.id}>{d.propertyName} ({d.status})</option>
          ))}
        </select>

        {selectedDealId && (
          <button
            onClick={() => setShowUpload(!showUpload)}
            className="flex items-center gap-1.5 bg-gray-900 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-800 transition active:scale-95"
          >
            <Upload className="w-4 h-4" />
            Upload Document
          </button>
        )}
      </div>

      {/* Upload Zone */}
      {showUpload && selectedDealId && (
        <div className="border border-border-accent rounded-xl p-5 bg-bg-primary space-y-4">
          <div className="flex items-center justify-between">
            <h5 className="text-sm font-semibold text-text-primary">New Settlement Document</h5>
            <button onClick={() => { setShowUpload(false); setUploadFile(null); }} className="text-text-secondary hover:text-text-secondary">
              <X className="w-4 h-4" />
            </button>
          </div>

          {/* Type Selector */}
          <div className="flex gap-3">
            {(['HUD-1', 'Closing Disclosure'] as SettlementDocumentType[]).map(type => (
              <button
                key={type}
                onClick={() => setUploadType(type)}
                className={`flex-1 py-2.5 rounded-lg text-sm font-medium border transition ${
                  uploadType === type
                    ? 'bg-gray-900 text-white border-gray-900'
                    : 'bg-bg-surface text-text-primary border-border-accent hover:border-gray-400'
                }`}
              >
                {type}
              </button>
            ))}
          </div>

          {/* Drop Zone */}
          <div
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
            className="relative rounded-xl p-8 text-center cursor-pointer transition-all bg-surface-container/30 backdrop-blur-xl border-t border-l border-white/10 shadow-lg min-h-[180px] flex flex-col items-center justify-center overflow-hidden group"
            onClick={() => {
              const input = document.createElement('input');
              input.type = 'file';
              input.accept = '.pdf,.jpg,.jpeg,.png';
              input.onchange = e => {
                const f = (e.target as HTMLInputElement).files?.[0];
                if (f) handleFileSelect(f);
              };
              input.click();
            }}
          >
            {/* Inner Dashed Border Indicator */}
            <div className={`absolute inset-3 border-2 border-dashed rounded-lg transition-all duration-300 pointer-events-none ${
              dragOver 
                ? 'border-primary bg-primary/10' 
                : 'border-outline-variant/40 group-hover:border-primary/40 group-hover:bg-primary/5'
            }`} />

            {uploadFile ? (
              <div className="relative z-10 flex flex-col items-center gap-2">
                <div className="w-14 h-14 mb-1 rounded-full bg-surface-container-highest flex items-center justify-center text-pw-success shadow-lg shadow-pw-success/10">
                  <FileCheck2 className="w-6 h-6" />
                </div>
                <div className="flex items-center justify-center gap-2">
                  <span className="text-sm font-medium text-text-primary">{uploadFile.name}</span>
                  <span className="text-xs text-text-secondary">({(uploadFile.size / 1024).toFixed(0)} KB)</span>
                </div>
              </div>
            ) : (
              <div className="relative z-10 flex flex-col items-center gap-2">
                <div className="w-14 h-14 mb-1 rounded-full bg-surface-container-highest flex items-center justify-center text-primary shadow-lg shadow-primary/10 group-hover:scale-110 transition-transform duration-300">
                  <Upload className="w-6 h-6" />
                </div>
                <p className="text-sm font-medium text-text-primary">Drop file here or click to browse</p>
                <p className="text-xs text-text-secondary">PDF, JPEG, PNG — Max 25MB</p>
              </div>
            )}
          </div>

          {/* Upload Button */}
          <button
            onClick={handleUpload}
            disabled={!uploadFile || isUploading || isProcessing}
            className="w-full luminous-button py-3 rounded-lg text-sm font-semibold disabled:opacity-40 flex items-center justify-center gap-2"
          >
            {isUploading ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                Uploading ({uploadProgress.toFixed(0)}%)
              </>
            ) : isProcessing ? (
              <>
                <Loader2 className="w-4 h-4 animate-spin" />
                Processing Document...
              </>
            ) : (
              <>Upload {uploadType}</>
            )}
          </button>
        </div>
      )}

      {/* Document List */}
      {selectedDealId && (
        <div className="space-y-3">
          {documents.length === 0 ? (
            <div className="p-10 text-center text-sm text-text-secondary border-2 border-dashed border-border-accent rounded-xl">
              <FileText className="w-8 h-8 mx-auto mb-2 text-gray-300" />
              No settlement documents uploaded for this property.
            </div>
          ) : (
            documents.map(doc => (
              <div key={doc.id} className="border border-border-accent rounded-lg overflow-hidden bg-bg-surface">
                {/* Document Header */}
                <div
                  className="flex items-center justify-between px-4 py-3 cursor-pointer hover:bg-bg-primary transition"
                  onClick={() => setExpandedDocId(expandedDocId === doc.id ? null : doc.id)}
                >
                  <div className="flex items-center gap-3">
                    {expandedDocId === doc.id ? (
                      <ChevronDown className="w-4 h-4 text-text-secondary" />
                    ) : (
                      <ChevronRight className="w-4 h-4 text-text-secondary" />
                    )}
                    <FileText className="w-4 h-4 text-blue-600" />
                    <div>
                      <p className="text-sm font-medium text-text-primary">{doc.fileName}</p>
                      <p className="text-xs text-text-secondary">
                        {doc.type} · Uploaded {doc.uploadedAt ? new Date(doc.uploadedAt).toLocaleDateString() : 'N/A'}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {doc.verified ? (
                      <span className="flex items-center gap-1 px-2 py-0.5 bg-pw-success-container text-pw-success border border-pw-success-border rounded text-xs font-bold uppercase">
                        <CheckCircle2 className="w-3 h-3" /> Verified
                      </span>
                    ) : (
                      <span className="flex items-center gap-1 px-2 py-0.5 bg-amber-50 text-amber-700 border border-amber-200 rounded text-xs font-bold uppercase">
                        <Clock className="w-3 h-3" /> Pending Review
                      </span>
                    )}
                  </div>
                </div>

                {/* Expanded Verification Form */}
                {expandedDocId === doc.id && (
                  <div className="border-t border-border-accent px-4 py-4 bg-bg-primary space-y-4">
                    <div className="flex items-start gap-2 p-3 bg-blue-50 border border-blue-200 rounded-lg">
                      <AlertCircle className="w-4 h-4 text-blue-600 flex-shrink-0 mt-0.5" />
                      <p className="text-xs text-blue-700">
                        Enter values from the settlement statement below. These will be used to update your deal's exit financials when applied.
                      </p>
                    </div>

                    <div className="grid grid-cols-2 gap-3">
                      {VERIFICATION_FIELDS.map(field => (
                        <div key={field.key} className="space-y-1">
                          <label className="text-xs font-medium text-text-secondary">{field.label}</label>
                          <div className="flex items-center gap-1 border border-border-accent rounded-lg bg-bg-surface overflow-hidden">
                            <DollarSign className="w-3.5 h-3.5 text-text-secondary ml-2" />
                            <input
                              type="number"
                              value={doc[field.key] ?? ''}
                              onChange={e => updateDocField(doc.id, field.key, parseFloat(e.target.value) || 0)}
                              placeholder="0.00"
                              disabled={doc.verified}
                              className="w-full text-sm py-2 pr-3 outline-none disabled:bg-bg-primary disabled:text-text-secondary"
                            />
                          </div>
                        </div>
                      ))}
                    </div>

                    {/* Notes */}
                    <div className="space-y-1">
                      <label className="text-xs font-medium text-text-secondary">Notes</label>
                      <textarea
                        value={doc.notes || ''}
                        onChange={e => updateDocField(doc.id, 'notes', e.target.value)}
                        disabled={doc.verified}
                        rows={2}
                        placeholder="Any discrepancies or notes..."
                        className="w-full text-sm border border-border-accent rounded-lg p-3 outline-none focus:ring-1 focus:ring-gray-400 disabled:bg-bg-primary resize-none"
                      />
                    </div>

                    {/* Actions */}
                    <div className="flex items-center gap-3 pt-2">
                      {!doc.verified && (
                        <button
                          onClick={() => verifyDocument(doc.id)}
                          className="flex items-center gap-1.5 bg-pw-success text-[#0d0a0b] px-4 py-2 rounded-lg text-sm font-medium hover:bg-pw-success/90 transition active:scale-95"
                        >
                          <CheckCircle2 className="w-4 h-4" /> Verify & Lock Values
                        </button>
                      )}
                      {doc.verified && (
                        <button
                          onClick={() => applyToExitHub(doc)}
                          className="flex items-center gap-1.5 bg-blue-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-blue-700 transition active:scale-95"
                        >
                          <Save className="w-4 h-4" /> Apply to Exit Hub
                        </button>
                      )}
                      <button
                        onClick={() => removeDocument(doc.id)}
                        className="text-sm text-text-secondary hover:text-red-600 transition"
                      >
                        Remove
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ))
          )}
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { FileDown, FileSpreadsheet, Loader2 } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import toast from 'react-hot-toast';

/* ═══════════════════════════════════════════════════════
   Statement Exporter — PDF & CSV Export Toolbar
   ─────────────────────────────────────────────────────
   Generates professional exports of P&L, Cash Flow,
   and Balance Sheet data. CPA-ready formatting.
   ═══════════════════════════════════════════════════════ */

type StatementType = 'pl' | 'cashflow' | 'balance';

function fmt(val: number): string {
  const neg = val < 0;
  return `${neg ? '-' : ''}$${Math.abs(val).toLocaleString(undefined, { maximumFractionDigits: 0 })}`;
}

export default function StatementExporter({ activeStatement }: { activeStatement: StatementType }) {
  const projects = useProjectStore(s => s.projects);
  const currentProject = useProjectStore(s => s.currentProject);
  const [generating, setGenerating] = useState<'pdf' | 'csv' | null>(null);

  const dateStr = new Date().toISOString().split('T')[0];

  const fetchExportData = async (format: 'pdf' | 'csv') => {
    const targetDeals = currentProject ? [currentProject] : projects;
    const response = await fetch('/api/reporting/export', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        format,
        type: activeStatement,
        projects: targetDeals
      })
    });

    if (!response.ok) {
      throw new Error('Server returned an error while processing the export');
    }

    return response;
  };

  // ─── PDF Generation ──────────────────────────────────
  const generatePdf = async () => {
    setGenerating('pdf');
    toast.loading('Generating PDF...', { id: 'stmt-pdf' });

    try {
      const response = await fetchExportData('pdf');
      const result = await response.json();

      if (!result.success) throw new Error(result.error);

      const data = result.data;

      const doc = new jsPDF();
      const title = activeStatement === 'pl' ? 'Profit & Loss Statement' :
                   activeStatement === 'cashflow' ? 'Cash Flow Statement' : 'Balance Sheet';

      // Header
      doc.addImage('/brand/PaperWorking_Black_full_Logo_.png', 'PNG', 14, 10, 30.4, 5);

      doc.setFontSize(20);
      doc.setTextColor(33, 33, 33);
      doc.text(title, 14, 23);
      doc.setFontSize(10);
      doc.setTextColor(120, 120, 120);
      doc.text(`Generated by PaperWorking · ${new Date().toLocaleDateString()}`, 14, 30);
      doc.setDrawColor(33, 33, 33);
      doc.setLineWidth(0.5);
      doc.line(14, 33, 196, 33);

      if (activeStatement === 'pl') {
        autoTable(doc, {
          startY: 38,
          head: [['Account', 'Amount']],
          body: data,
          theme: 'plain',
          styles: { fontSize: 10, cellPadding: 3 },
          headStyles: { fillColor: [245, 245, 245], textColor: [80, 80, 80], fontStyle: 'bold', fontSize: 8 },
          columnStyles: { 0: { cellWidth: 120 }, 1: { halign: 'right', fontStyle: 'normal' } },
          didParseCell: (hookData) => {
            const text = hookData.cell.raw as string;
            if (text && ['Revenue', 'Cost of Goods Sold', 'GROSS PROFIT', 'Operating Expenses', 'NET PROFIT / (LOSS)', 'Total Revenue', 'Total COGS', 'Total Operating Expenses'].includes(text)) {
              hookData.cell.styles.fontStyle = 'bold';
              if (text.includes('GROSS') || text.includes('NET')) {
                hookData.cell.styles.fillColor = [245, 245, 245];
              }
            }
          },
        });
      } else if (activeStatement === 'balance') {
        autoTable(doc, {
          startY: 38,
          head: [['Account', 'Amount']],
          body: data,
          theme: 'plain',
          styles: { fontSize: 10, cellPadding: 3 },
          headStyles: { fillColor: [245, 245, 245], textColor: [80, 80, 80], fontStyle: 'bold', fontSize: 8 },
          columnStyles: { 0: { cellWidth: 120 }, 1: { halign: 'right' } },
          didParseCell: (hookData) => {
            const text = hookData.cell.raw as string;
            if (text && ['ASSETS', 'LIABILITIES', "OWNER'S EQUITY", 'Total Assets', 'Total Liabilities'].includes(text)) {
              hookData.cell.styles.fontStyle = 'bold';
              hookData.cell.styles.fillColor = [245, 245, 245];
            }
          },
        });
      } else {
        autoTable(doc, {
          startY: 38,
          head: [data[0]],
          body: data.slice(1),
          theme: 'grid',
          styles: { fontSize: 9, cellPadding: 3 },
          headStyles: { fillColor: [80, 80, 80], textColor: 255, fontSize: 8 },
          columnStyles: { 1: { halign: 'right' }, 2: { halign: 'right' }, 3: { halign: 'right' }, 4: { halign: 'right' } },
        });
      }

      const propName = currentProject?.propertyName?.replace(/\s+/g, '_') || 'Portfolio';
      const filename = `PaperWorking_${title.replace(/\s+/g, '_')}_${propName}_${dateStr}.pdf`;
      doc.save(filename);
      toast.success(`Downloaded: ${filename}`, { id: 'stmt-pdf', icon: '📊' });
    } catch (e) {
      console.error(e);
      toast.error('PDF generation failed. Check console.', { id: 'stmt-pdf' });
    } finally {
      setGenerating(null);
    }
  };

  // ─── CSV Generation ──────────────────────────────────
  const generateCsv = async () => {
    setGenerating('csv');
    toast.loading('Generating CSV...', { id: 'stmt-csv' });

    try {
      const response = await fetchExportData('csv');
      const csvString = await response.text();

      let title = '';
      if (activeStatement === 'pl') {
        title = 'Profit_Loss';
      } else if (activeStatement === 'balance') {
        title = 'Balance_Sheet';
      } else {
        title = 'Cash_Flow';
      }

      const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const propName = currentProject?.propertyName?.replace(/\s+/g, '_') || 'Portfolio';
      link.href = url;
      link.setAttribute('download', `PaperWorking_${title}_${propName}_${dateStr}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      toast.success(`CSV exported successfully!`, { id: 'stmt-csv', icon: '📋' });
    } catch (e) {
      console.error(e);
      toast.error('CSV export failed.', { id: 'stmt-csv' });
    } finally {
      setGenerating(null);
    }
  };

  const labels: Record<StatementType, string> = {
    pl: 'P&L Statement',
    cashflow: 'Cash Flow Statement',
    balance: 'Balance Sheet',
  };

  return (
    <div className="flex flex-wrap items-center justify-between gap-3 p-4 bg-bg-primary rounded-xl border border-border-accent">
      <div>
        <p className="text-sm font-semibold text-text-primary">Export: {labels[activeStatement]}</p>
        <p className="text-xs text-text-secondary">CPA-ready formatting with full line-item detail</p>
      </div>
      <div className="flex gap-2">
        <button
          onClick={generatePdf}
          disabled={generating !== null}
          className="flex items-center gap-1.5 bg-gray-900 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-800 transition active:scale-95 disabled:opacity-50"
        >
          {generating === 'pdf' ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileDown className="w-4 h-4" />}
          {generating === 'pdf' ? 'Generating...' : 'Download PDF'}
        </button>
        <button
          onClick={generateCsv}
          disabled={generating !== null}
          className="flex items-center gap-1.5 bg-bg-surface text-text-primary px-4 py-2 rounded-lg text-sm font-medium border border-border-accent hover:bg-bg-primary transition active:scale-95 disabled:opacity-50"
        >
          {generating === 'csv' ? <Loader2 className="w-4 h-4 animate-spin" /> : <FileSpreadsheet className="w-4 h-4" />}
          {generating === 'csv' ? 'Exporting...' : 'Export CSV'}
        </button>
      </div>
    </div>
  );
}

import React from 'react';
import { useProjectStore } from '@/store/projectStore';
import { DownloadCloud, FileText } from 'lucide-react';
import toast from 'react-hot-toast';

export default function TaxExportCsvButton() {
  const projects = useProjectStore(state => state.projects);

  const handleExportCsv = () => {
    try {
      // 1. Compile the Data
      const csvRows = [];
      // Headers
      csvRows.push(['Date', 'Property', 'Status', 'Category', 'Description', 'Amount', 'Approved by UID']);

      let rowCount = 0;

      projects.forEach(deal => {
        // 1. Core Rehab/Operating Costs
        const approvedCosts = deal.financials?.costs?.filter(c => c.approved) || [];
        approvedCosts.forEach(cost => {
          csvRows.push([
            cost.createdAt ? new Date(cost.createdAt).toISOString().split('T')[0] : 'N/A',
            `"${deal.propertyName.replace(/"/g, '""')}"`,
            deal.status,
            cost.category || 'Other',
            `"${cost.description.replace(/"/g, '""')}"`,
            cost.amount.toString(),
            cost.addedBy || 'N/A'
          ]);
          rowCount++;
        });

        // 2. Acquisition Cost Basis Ledger
        if (deal.costBasisLedger) {
          const cb = deal.costBasisLedger;
          const allAcquisition = [
            ...(cb.directAcquisition || []),
            ...(cb.financing || []),
            ...(cb.preClosing || [])
          ];
          allAcquisition.forEach(item => {
            csvRows.push([
              item.paidAt ? new Date(item.paidAt).toISOString().split('T')[0] : 'N/A',
              `"${deal.propertyName.replace(/"/g, '""')}"`,
              deal.status,
              'Acquisition/Capitalized',
              `"${item.label.replace(/"/g, '""')}"`,
              item.amount.toString(),
              'System'
            ]);
            rowCount++;
          });
        }

        // 3. Exit Costs Ledger
        if (deal.exitCosts) {
          deal.exitCosts.forEach(item => {
            csvRows.push([
              item.paidAt ? new Date(item.paidAt).toISOString().split('T')[0] : 'N/A',
              `"${deal.propertyName.replace(/"/g, '""')}"`,
              deal.status,
              `Exit - ${item.category}`,
              `"${item.label.replace(/"/g, '""')}"`,
              item.amount.toString(),
              'System'
            ]);
            rowCount++;
          });
        }
      });

      if (rowCount === 0) {
        toast.error("No approved ledger entries found to export.", { icon: '📄' });
        return;
      }

      // 2. Generate CSV String
      const csvString = csvRows.map(row => row.join(',')).join('\n');

      // 3. Create Blob & Trigger Download
      const blob = new Blob([csvString], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `Tax_Export_Engine_Room_${new Date().toISOString().split('T')[0]}.csv`);
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

      toast.success(`Successfully exported ${rowCount} ledger entries!`, { icon: '📊' });
    } catch (e) {
      console.error(e);
      toast.error("Failed to generate CSV export.");
    }
  };

  return (
    <button 
      onClick={handleExportCsv}
      className="flex items-center gap-2 bg-gray-900 text-white px-4 py-2 mt-4 sm:mt-0 rounded-lg text-sm font-medium hover:bg-gray-800 transition active:scale-95 shadow-sm"
    >
      <DownloadCloud className="w-4 h-4" /> Export Schedule E / K-1 Data (CSV)
    </button>
  );
}

import React from 'react';
