'use client';

import React, { useState, useCallback } from 'react';
import { useAuth } from '@/context/AuthContext';
import { createNewDeal } from '@/actions';
import toast from 'react-hot-toast';

/* ═══════════════════════════════════════════════════════════════
   ManualLeadModal — Slide-over form for adding a manual lead

   Saves via the `createNewDeal` server action which writes to
   the `projects` collection with status='Lead'. The real-time
   Firestore listener (useAllDealsSync) auto-refreshes the list.
   ═══════════════════════════════════════════════════════════════ */

interface ManualLeadModalProps {
  open: boolean;
  onClose: () => void;
}

const PROPERTY_TYPES = ['Residential', 'Multi-Family', 'Commercial', 'Land'] as const;

const US_STATES = [
  'AL','AK','AZ','AR','CA','CO','CT','DE','FL','GA',
  'HI','ID','IL','IN','IA','KS','KY','LA','ME','MD',
  'MA','MI','MN','MS','MO','MT','NE','NV','NH','NJ',
  'NM','NY','NC','ND','OH','OK','OR','PA','RI','SC',
  'SD','TN','TX','UT','VT','VA','WA','WV','WI','WY','DC',
];

interface FormData {
  address: string;
  city: string;
  state: string;
  zip: string;
  propertyType: typeof PROPERTY_TYPES[number];
  source: string;
  notes: string;
}

const initialFormData: FormData = {
  address: '',
  city: '',
  state: '',
  zip: '',
  propertyType: 'Residential',
  source: 'Manual',
  notes: '',
};

export default function ManualLeadModal({ open, onClose }: ManualLeadModalProps) {
  const { user } = useAuth();
  const [form, setForm] = useState<FormData>(initialFormData);
  const [submitting, setSubmitting] = useState(false);

  const handleChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
      const { name, value } = e.target;
      setForm((prev) => ({ ...prev, [name]: value }));
    },
    [],
  );

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!user) {
      toast.error('You must be logged in.');
      return;
    }

    // Basic validation
    if (!form.address.trim()) {
      toast.error('Address is required.');
      return;
    }

    setSubmitting(true);
    try {
      const idToken = await user.getIdToken();

      // Build the full address string for the project record
      const parts = [form.address.trim()];
      if (form.city.trim()) parts.push(form.city.trim());
      if (form.state.trim()) parts.push(form.state.trim());
      if (form.zip.trim()) parts.push(form.zip.trim());
      const fullAddress = parts.join(', ');

      await createNewDeal(idToken, {
        propertyName: form.address.trim(),
        address: fullAddress,
        assetClass: form.propertyType,
        leadSource: form.source || 'Manual',
        notes: form.notes.trim(),
      });

      toast.success('Lead added successfully!');
      setForm(initialFormData);
      onClose();
    } catch (err: any) {
      console.error('Failed to add manual lead:', err);
      toast.error(err.message || 'Failed to add lead. Please try again.');
    } finally {
      setSubmitting(false);
    }
  };

  const handleBackdropClick = (e: React.MouseEvent) => {
    if (e.target === e.currentTarget) onClose();
  };

  if (!open) return null;

  const inputClasses =
    'w-full rounded-lg border border-pw-border bg-white/5 px-3 py-2.5 text-sm text-text-primary placeholder:text-text-secondary/50 focus:outline-none focus:ring-1 focus:ring-[#6E7480]/40 focus:border-[#6E7480]/40 transition-colors';
  const labelClasses = 'block text-xs font-semibold text-text-secondary tracking-wider uppercase mb-1.5';

  return (
    <div
      className="fixed inset-0 z-50 flex justify-end bg-black/50 backdrop-blur-sm animate-in fade-in duration-200"
      onClick={handleBackdropClick}
    >
      {/* Slide-over panel */}
      <div className="glass-card w-full max-w-md h-full border-l border-pw-border overflow-y-auto animate-in slide-in-from-right duration-300">
        {/* Header */}
        <div className="sticky top-0 z-10 flex items-center justify-between border-b border-pw-border p-5 bg-inherit backdrop-blur-xl">
          <div>
            <h2 className="text-lg font-bold text-text-primary">Add Manual Lead</h2>
            <p className="text-xs text-text-secondary mt-0.5">Enter property details to add to your sourcing pipeline</p>
          </div>
          <button
            onClick={onClose}
            className="pw-interactive rounded-full p-1.5 hover:bg-white/10 transition-colors"
            aria-label="Close"
          >
            <svg width="20" height="20" viewBox="0 0 20 20" fill="none" className="text-text-secondary">
              <path d="M15 5L5 15M5 5l10 10" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        {/* Form */}
        <form onSubmit={handleSubmit} className="p-5 space-y-5">
          {/* Address */}
          <div>
            <label htmlFor="lead-address" className={labelClasses}>
              Address <span className="text-red-400">*</span>
            </label>
            <input
              id="lead-address"
              name="address"
              type="text"
              value={form.address}
              onChange={handleChange}
              placeholder="123 Main Street"
              className={inputClasses}
              required
            />
          </div>

          {/* City + State Row */}
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label htmlFor="lead-city" className={labelClasses}>City</label>
              <input
                id="lead-city"
                name="city"
                type="text"
                value={form.city}
                onChange={handleChange}
                placeholder="Miami"
                className={inputClasses}
              />
            </div>
            <div>
              <label htmlFor="lead-state" className={labelClasses}>State</label>
              <select
                id="lead-state"
                name="state"
                value={form.state}
                onChange={handleChange}
                className={inputClasses}
              >
                <option value="">Select…</option>
                {US_STATES.map((s) => (
                  <option key={s} value={s}>{s}</option>
                ))}
              </select>
            </div>
          </div>

          {/* Zip */}
          <div>
            <label htmlFor="lead-zip" className={labelClasses}>Zip Code</label>
            <input
              id="lead-zip"
              name="zip"
              type="text"
              value={form.zip}
              onChange={handleChange}
              placeholder="33101"
              maxLength={10}
              className={inputClasses}
            />
          </div>

          {/* Property Type */}
          <div>
            <label htmlFor="lead-propertyType" className={labelClasses}>Property Type</label>
            <select
              id="lead-propertyType"
              name="propertyType"
              value={form.propertyType}
              onChange={handleChange}
              className={inputClasses}
            >
              {PROPERTY_TYPES.map((t) => (
                <option key={t} value={t}>{t}</option>
              ))}
            </select>
          </div>

          {/* Source */}
          <div>
            <label htmlFor="lead-source" className={labelClasses}>Source</label>
            <input
              id="lead-source"
              name="source"
              type="text"
              value={form.source}
              onChange={handleChange}
              placeholder="Manual"
              className={inputClasses}
            />
          </div>

          {/* Notes */}
          <div>
            <label htmlFor="lead-notes" className={labelClasses}>Notes</label>
            <textarea
              id="lead-notes"
              name="notes"
              value={form.notes}
              onChange={handleChange}
              placeholder="Any additional context about this lead…"
              rows={3}
              className={inputClasses + ' resize-none'}
            />
          </div>

          {/* Actions */}
          <div className="flex items-center gap-3 pt-3 border-t border-pw-border">
            <button
              type="button"
              onClick={onClose}
              className="flex-1 px-4 py-2.5 rounded-full border border-pw-border text-sm font-semibold text-text-secondary hover:bg-white/5 transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={submitting}
              className="flex-1 pw-interactive pw-btn pw-btn--primary rounded-full text-sm font-semibold disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center gap-2"
            >
              {submitting ? (
                <>
                  <div className="w-4 h-4 border-2 border-t-transparent border-current rounded-full animate-spin" />
                  Saving…
                </>
              ) : (
                'Add Lead'
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect, useRef } from 'react';
import { MessageSquare, X, Send, Clock, Sparkles } from 'lucide-react';
import { useEntitlements } from '@/hooks/useEntitlements';
import toast from 'react-hot-toast';
import { useAuth } from '@/context/AuthContext';
import { defaultSupportProvider, SupportMessage } from '@/lib/providers/support';
import { db } from '@/lib/firebase/config';
import { doc, onSnapshot } from 'firebase/firestore';

export default function SupportWidget() {
  const { planId } = useEntitlements();
  const { user } = useAuth();
  const [isOpen, setIsOpen] = useState(false);
  const [isBusinessHours, setIsBusinessHours] = useState(true);
  const [message, setMessage] = useState('');
  const [chatLog, setChatLog] = useState<SupportMessage[]>([]);
  const [isTyping, setIsTyping] = useState(false);
  const [ticketId, setTicketId] = useState<string | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);

  // Derive Plan Label and SLA response hours
  const planLabel = planId === 'team' ? 'Team' : planId === 'individual' ? 'Investor' : 'Solo';
  const slaText = planId === 'team' ? '2 hours' : planId === 'individual' ? '8 hours' : '24 hours';

  // Check business hours on component mount
  useEffect(() => {
    const checkBusinessHours = () => {
      try {
        const estTime = new Date().toLocaleString('en-US', { timeZone: 'America/New_York' });
        const estDate = new Date(estTime);
        const day = estDate.getDay(); // 0: Sun, 1: Mon, ..., 6: Sat
        const hours = estDate.getHours();

        // Monday (1) to Friday (5), 9:00 AM (9) to 5:00 PM (17)
        const active = day >= 1 && day <= 5 && hours >= 9 && hours < 17;
        setIsBusinessHours(active);
      } catch (e) {
        // Fallback to local time if timezone lookup fails
        const localDate = new Date();
        const day = localDate.getDay();
        const hours = localDate.getHours();
        const active = day >= 1 && day <= 5 && hours >= 9 && hours < 17;
        setIsBusinessHours(active);
      }
    };

    checkBusinessHours();
    // Re-check every minute
    const interval = setInterval(checkBusinessHours, 60000);
    return () => clearInterval(interval);
  }, []);

  // Scroll to bottom on new messages
  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatLog, isTyping]);

  // Load open ticket or initialize welcome message
  useEffect(() => {
    if (isOpen && user && !ticketId) {
      const loadOpenTicket = async () => {
        try {
          const ticket = await defaultSupportProvider.getOpenTicket(user.uid);
          if (ticket && ticket.id) {
            setTicketId(ticket.id);
            setChatLog(ticket.messages);
          } else {
            const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            const welcomeText = isBusinessHours
              ? `Hi there! Thanks for reaching out to PaperWorking Support. How can we help you with your real estate deals today?`
              : `Hello! We are currently off business hours (Mon-Fri 9am-5pm EST). Since you're on our ${planLabel} plan, we'll respond within ${slaText}. Please leave your question or feedback below and we'll get back to you!`;

            setChatLog([
              {
                sender: 'agent',
                text: welcomeText,
                time: timeStr,
                timestamp: new Date().toISOString(),
              },
            ]);
          }
        } catch (e) {
          console.error('[SupportWidget] Error loading ticket:', e);
        }
      };
      loadOpenTicket();
    }
  }, [isOpen, user, isBusinessHours, planLabel, slaText, ticketId]);

  // Subscribe to real-time updates for active ticket
  useEffect(() => {
    if (!ticketId || !user) return;

    const providerType = (
      process.env.NEXT_PUBLIC_SUPPORT_PROVIDER ||
      process.env.SUPPORT_PROVIDER ||
      'mock'
    ).toLowerCase();

    if (providerType === 'firestore') {
      const unsubscribe = onSnapshot(
        doc(db, 'supportTickets', ticketId),
        (snapshot) => {
          if (snapshot.exists()) {
            const data = snapshot.data();
            if (data && data.messages) {
              setChatLog(data.messages);
            }
          }
        },
        (err) => {
          console.error('[SupportWidget] onSnapshot error:', err);
        }
      );
      return () => unsubscribe();
    }
  }, [ticketId, user]);

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!message.trim() || !user) return;

    const userMsgText = message;
    setMessage('');

    const timeStr = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const userMsg: SupportMessage = {
      sender: 'user',
      text: userMsgText,
      time: timeStr,
      timestamp: new Date().toISOString(),
    };

    // Optimistically update UI
    setChatLog((prev) => [...prev, userMsg]);

    try {
      let activeTicketId = ticketId;
      if (!activeTicketId) {
        // Create new ticket including all existing messages
        const initialMessages = [...chatLog, userMsg];
        const newId = await defaultSupportProvider.createTicket(
          user.uid,
          user.email || '',
          planLabel,
          initialMessages
        );
        setTicketId(newId);
        activeTicketId = newId;
      } else {
        // Append user message to existing ticket
        await defaultSupportProvider.addMessage(activeTicketId, userMsg);
      }

      // Simulate live typing or automated support responses
      setIsTyping(true);
      setTimeout(async () => {
        setIsTyping(false);
        const replyTime = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

        let responseText = "Thanks for your query! We have recorded your question and a support representative is reviewing it now.";
        if (userMsgText.toLowerCase().includes('noi')) {
          responseText = "NOI (Net Operating Income) is calculated as Gross Income minus Operating Expenses. Check out our /help/noi guide for formulas and detail!";
        } else if (userMsgText.toLowerCase().includes('cash flow')) {
          responseText = "Cash Flow is NOI minus Debt Service. Check out our /help/cash-flow guide to see how to improve it!";
        } else if (userMsgText.toLowerCase().includes('billing') || userMsgText.toLowerCase().includes('upgrade')) {
          responseText = "You can manage your subscription plan and billing cards on the /dashboard/settings/billing page.";
        } else if (!isBusinessHours) {
          responseText = `Ticket recorded successfully! A support engineer will review this and reply within ${slaText} to your account email.`;
        }

        const agentMsg: SupportMessage = {
          sender: 'agent',
          text: responseText,
          time: replyTime,
          timestamp: new Date().toISOString(),
        };

        if (activeTicketId) {
          await defaultSupportProvider.addMessage(activeTicketId, agentMsg);
        }

        // For mock/local fallback, optimistically append agent message
        const providerType = (
          process.env.NEXT_PUBLIC_SUPPORT_PROVIDER ||
          process.env.SUPPORT_PROVIDER ||
          'mock'
        ).toLowerCase();
        if (providerType !== 'firestore') {
          setChatLog((prev) => [...prev, agentMsg]);
        }

        if (!isBusinessHours) {
          toast.success(`Support Ticket Submitted. Response within ${slaText}!`);
        }
      }, 1200);

    } catch (err: any) {
      console.error('[SupportWidget] Error sending message:', err);
      toast.error('Failed to send support message. Please try again.');
    }
  };


  return (
    <div className="fixed bottom-6 right-6 z-50">
      {/* Floating Chat Bubble */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="w-14 h-14 rounded-full bg-transparent hover:scale-105 active:scale-95 flex items-center justify-center transition-all duration-200 cursor-pointer"
          style={{
            border: '2px solid var(--pw-success)',
            boxShadow: '0 4px 20px rgba(0,0,0,0.25)',
          }}
          aria-label="Open support chat"
        >
          <MessageSquare className="w-6 h-6 text-pw-success" />
        </button>
      )}

      {/* Chat Window */}
      {isOpen && (
        <div
          className="w-80 sm:w-96 h-[480px] rounded-2xl border border-[var(--pw-border)] bg-surface-container/95 backdrop-blur-2xl shadow-2xl flex flex-col overflow-hidden transition-all duration-300"
          style={{
            background: 'linear-gradient(180deg, rgba(13,10,11,0.98) 0%, rgba(13,10,11,0.99) 100%)',
          }}
        >
          {/* Header */}
          <div className="p-4 border-b border-[var(--pw-border)] bg-white/5 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 rounded-full bg-pw-success-container flex items-center justify-center border border-pw-success-border/30">
                <Sparkles className="w-4 h-4 text-pw-success" />
              </div>
              <div>
                <h4 className="text-sm font-bold text-[var(--pw-black)]">PaperWorking Support</h4>
                <div className="flex items-center gap-1 mt-0.5">
                  <span className={`w-1.5 h-1.5 rounded-full ${isBusinessHours ? 'bg-pw-success' : 'bg-amber-500'}`} />
                  <span className="text-[10px] text-[var(--pw-muted)]">
                    {isBusinessHours ? 'Live Chat Active' : `Offline (SLA: ${slaText})`}
                  </span>
                </div>
              </div>
            </div>
            <button
              onClick={() => setIsOpen(false)}
              className="p-1 rounded-lg hover:bg-white/10 text-[var(--pw-muted)] hover:text-[var(--pw-black)] transition-colors"
            >
              <X className="w-5 h-5" />
            </button>
          </div>

          {/* Messages Area */}
          <div className="flex-1 p-4 overflow-y-auto space-y-4 custom-scrollbar">
            {chatLog.map((msg, i) => (
              <div key={i} className={`flex ${msg.sender === 'user' ? 'justify-end' : 'justify-start'}`}>
                <div
                  className={`max-w-[75%] rounded-xl px-3 py-2 text-xs leading-relaxed ${
                    msg.sender === 'user'
                      ? 'bg-pw-success text-[#0d0a0b] rounded-br-none'
                      : 'bg-white/5 border border-[var(--pw-border)] text-[var(--pw-black)] rounded-bl-none'
                  }`}
                >
                  <p>{msg.text}</p>
                  <span className="text-[8px] text-white/40 block text-right mt-1">{msg.time}</span>
                </div>
              </div>
            ))}

            {isTyping && (
              <div className="flex justify-start">
                <div className="bg-white/5 border border-[var(--pw-border)] rounded-xl rounded-bl-none px-3 py-2 text-xs text-[var(--pw-muted)] flex items-center gap-1">
                  <span className="w-1.5 h-1.5 rounded-full bg-pw-success animate-bounce" />
                  <span className="w-1.5 h-1.5 rounded-full bg-pw-success animate-bounce [animation-delay:0.2s]" />
                  <span className="w-1.5 h-1.5 rounded-full bg-pw-success animate-bounce [animation-delay:0.4s]" />
                </div>
              </div>
            )}
            <div ref={chatEndRef} />
          </div>

          {/* Footer Input */}
          <form onSubmit={handleSendMessage} className="p-3 border-t border-[var(--pw-border)] bg-white/5 flex gap-2">
            <input
              type="text"
              placeholder="Ask a question..."
              value={message}
              onChange={(e) => setMessage(e.target.value)}
              className="flex-1 bg-white/5 border border-[var(--pw-border)] rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-pw-success transition-colors text-[var(--pw-black)] placeholder:text-[var(--pw-muted)]"
            />
            <button
              type="submit"
              className="p-2 rounded-lg bg-pw-success hover:bg-pw-success/90 text-[#0d0a0b] flex items-center justify-center transition-colors cursor-pointer"
            >
              <Send className="w-4 h-4" />
            </button>
          </form>
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useState, useMemo } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { Users, Plus, Trash2, DollarSign, Percent } from 'lucide-react';
import type { FractionalInvestor } from '@/types/schema';
import toast from 'react-hot-toast';

/* ═══════════════════════════════════════════════════════
   InvestorEquityTable — Investor Visualization

   Renders all fractional investors on the current deal:
     - Stacked horizontal bar showing equity distribution
     - Table rows with Name, Equity %, $ Contribution
     - Inline "Add Investor" row
   ═══════════════════════════════════════════════════════ */

const EQUITY_COLORS = [
  'bg-pw-black/80',
  'bg-pw-black/60',
  'bg-pw-black/40',
  'bg-pw-black/20',
  'bg-pw-accent/80',
  'bg-pw-accent/60',
  'bg-pw-accent/40',
  'bg-pw-accent/20',
];

interface Props {
  projectId: string;
}

export default function InvestorEquityTable({ projectId }: Props) {
  const currentProject = useProjectStore((s) => s.projects.find((d) => d.id === projectId));
  const updateInvestors = useProjectStore((s) => s.updateInvestors);
  const investors = currentProject?.fractionalInvestors || [];
  const isJTWROS = currentProject?.financials?.titleHolding === 'JTWROS';

  const [showAddRow, setShowAddRow] = useState(false);
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newPercent, setNewPercent] = useState('');
  const [newAmount, setNewAmount] = useState('');

  const totalEquity = useMemo(
    () => investors.reduce((sum, inv) => sum + inv.equityPercentage, 0),
    [investors]
  );
  const totalContribution = useMemo(
    () => investors.reduce((sum, inv) => sum + inv.contributionAmount, 0),
    [investors]
  );

  const handleAdd = () => {
    const isJTWROS = currentProject?.financials?.titleHolding === 'JTWROS';
    const percent = isJTWROS ? 0 : parseFloat(newPercent);
    const amount = parseFloat(newAmount);

    if (!newName.trim() || !newEmail.trim()) {
      toast.error('Name and email are required.');
      return;
    }
    if (!isJTWROS) {
      if (isNaN(percent) || percent <= 0 || percent > 100) {
        toast.error('Equity must be between 0 and 100%.');
        return;
      }
      if (totalEquity + percent > 100) {
        toast.error(`Cannot exceed 100% equity. ${(100 - totalEquity).toFixed(1)}% available.`);
        return;
      }
    }

    const newInvestor: FractionalInvestor = {
      id: `inv_${Date.now()}`,
      name: newName.trim(),
      email: newEmail.trim(),
      equityPercentage: isJTWROS ? 0 : percent,
      contributionAmount: isNaN(amount) ? 0 : amount,
      status: 'confirmed',
      confirmedAt: new Date(),
    };

    let updatedInvestors = [...investors, newInvestor];
    if (isJTWROS) {
      const count = updatedInvestors.length;
      if (count > 0) {
        const basePct = Math.floor((100 / count) * 100) / 100;
        const remainder = Math.round((100 - basePct * count) * 100) / 100;
        updatedInvestors = updatedInvestors.map((inv, idx) => ({
          ...inv,
          equityPercentage: Math.round((idx === 0 ? basePct + remainder : basePct) * 100) / 100,
        }));
      }
    }

    updateInvestors(projectId, updatedInvestors);
    if (isJTWROS) {
      toast.success(`${newInvestor.name} added. Equity splits adjusted equally for JTWROS.`);
    } else {
      toast.success(`${newInvestor.name} added with ${percent}% equity.`);
    }
    setNewName('');
    setNewEmail('');
    setNewPercent('');
    setNewAmount('');
    setShowAddRow(false);
  };

  const handleRemove = (investorId: string) => {
    let updatedInvestors = investors.filter((inv) => inv.id !== investorId);
    const isJTWROS = currentProject?.financials?.titleHolding === 'JTWROS';
    if (isJTWROS) {
      const count = updatedInvestors.length;
      if (count > 0) {
        const basePct = Math.floor((100 / count) * 100) / 100;
        const remainder = Math.round((100 - basePct * count) * 100) / 100;
        updatedInvestors = updatedInvestors.map((inv, idx) => ({
          ...inv,
          equityPercentage: Math.round((idx === 0 ? basePct + remainder : basePct) * 100) / 100,
        }));
      }
    }
    updateInvestors(projectId, updatedInvestors);
    toast.success('Investor removed.');
  };

  return (
    <div className="glass-card overflow-hidden">
      {/* Header */}
      <div className="px-6 pt-6 pb-4 flex items-center justify-between">
        <div>
          <h3 className="text-sm font-semibold text-pw-black tracking-tight flex items-center gap-2">
            <Users className="w-4 h-4 text-pw-accent" />
            Investor Equity Table
          </h3>
          <p className="text-xs text-pw-muted mt-0.5">Cap table for this deal.</p>
        </div>
        <div className="text-right">
          <p className="text-[10px] font-bold text-pw-muted uppercase tracking-wider">Allocated</p>
          <p className={`text-lg font-normal ${totalEquity > 100 ? 'text-error' : 'text-pw-black'}`}>
            {totalEquity.toFixed(1)}%
          </p>
        </div>
      </div>

      {/* Stacked Equity Bar */}
      {investors.length > 0 && (
        <div className="mx-6 mb-4">
          <div className="w-full h-6 bg-surface-container overflow-hidden flex border border-pw-border">
            {investors.map((inv, i) => (
              <div
                key={inv.id}
                className={`${EQUITY_COLORS[i % EQUITY_COLORS.length]} transition-all duration-500 flex items-center justify-center`}
                style={{ width: `${inv.equityPercentage}%` }}
                title={`${inv.name}: ${inv.equityPercentage}%`}
              >
                {inv.equityPercentage >= 8 && (
                  <span className="text-[10px] font-bold text-white truncate px-1">
                    {inv.equityPercentage}%
                  </span>
                )}
              </div>
            ))}
            {totalEquity < 100 && (
              <div
                className="bg-surface-container flex items-center justify-center"
                style={{ width: `${100 - totalEquity}%` }}
              >
                <span className="text-[10px] text-pw-muted font-medium">
                  {(100 - totalEquity).toFixed(1)}% unallocated
                </span>
              </div>
            )}
          </div>
        </div>
      )}

      {/* Table */}
      <div className="border-t border-pw-border overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-surface-container-highest/50 backdrop-blur-md border-b border-pw-border">
              <th className="px-6 py-4 font-label-md text-label-md text-outline uppercase tracking-wider">Investor</th>
              <th className="px-6 py-4 font-label-md text-label-md text-outline uppercase tracking-wider text-right">Equity %</th>
