'use client';

import React, { createContext, useContext, useEffect, useRef, useState, useSyncExternalStore } from 'react';
import {
  User,
  onAuthStateChanged,
  signInWithEmailAndPassword,
  createUserWithEmailAndPassword,
  signOut,
  GoogleAuthProvider,
  FacebookAuthProvider,
  signInWithPopup,
  isSignInWithEmailLink,
  signInWithEmailLink,
  getMultiFactorResolver,
  MultiFactorResolver,
} from 'firebase/auth';
import { doc, setDoc, getDoc, deleteDoc, serverTimestamp, onSnapshot } from 'firebase/firestore';
import { auth, db } from '@/lib/firebase/config';
import type { UserProfile, AccountType } from '@/types/user';
import toast from 'react-hot-toast';
import { getTokenExpiryMinutes } from '@/lib/auth/sessionService';
import SessionExpiredModal from '@/components/auth/SessionExpiredModal';
import MFAChallengeModal from '@/components/auth/MFAChallengeModal';
import posthog from 'posthog-js';
import { useProjectStore } from '@/store/projectStore';
import { usePropertyStore } from '@/store/propertyStore';
import { useUserStore } from '@/store/userStore';
import { logger } from '@/lib/logger';

/* ═══════════════════════════════════════════════════════
   PaperWorking — AuthContext (Phase 3.0)

   Single source of truth for Firebase Authentication.
   Provides:
     • user / loading / error state
     • login / register / logout / resetPassword actions
     • Social SSO: Google & Facebook via signInWithRedirect
       (production-grade — works on all browsers incl. mobile Safari)
     • Magic Link (Passwordless) Auth
     • Automatic server-side session cookie sync
     • Plan intent persistence for checkout resumption
   ═══════════════════════════════════════════════════════ */

interface AuthContextType {
  user: User | null;
  profile: UserProfile | null;
  loading: boolean;
  isAuthenticating: boolean; // true while a social popup / email login is in flight
  /** true once /api/auth/session POST has succeeded and __session cookie is confirmed set */
  sessionReady: boolean;
  error: string | null;
  login: (email: string, password: string) => Promise<void>;
  register: (email: string, password: string, displayName: string, accountType?: AccountType) => Promise<void>;
  loginWithGoogle: () => Promise<boolean>;
  loginWithFacebook: () => Promise<boolean>;
  sendMagicLink: (email: string) => Promise<void>;
  verifyMagicLink: (email: string, url: string) => Promise<boolean>;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
  clearError: () => void;
  /** H-5: Force-refresh the ID token and re-sync the session cookie if the
   *  token has less than 5 minutes of lifetime remaining. Call this on every
   *  hard layout mount to catch near-expiry tokens during SPA navigation. */
  refreshSession: () => Promise<void>;
  /** Present when a sign-in triggered the MFA challenge step. */
  mfaResolver: MultiFactorResolver | null;
  /** Called by MFAChallengeModal once the TOTP code is verified. */
  resolveMFASignIn: () => void;
  /** Called by MFAChallengeModal when the user cancels the challenge. */
  cancelMFAChallenge: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Ensures a user document exists in Firestore for social sign-ins.
 * Does not overwrite existing roles or org IDs for returning users.
 * 
 * IMPORTANT: This function is deliberately non-throwing. A Firestore
 * failure here must NOT block the auth flow — the user is already
 * signed in with Firebase Auth, so we let them proceed to the dashboard
 * and the profile will be created on the next attempt or via server-side logic.
 */
async function provisionSocialUser(user: User): Promise<boolean> {
  try {
    const userDocRef = doc(db, 'users', user.uid);
    const userDocSnap = await getDoc(userDocRef);

    if (!userDocSnap.exists()) {
      // Check if the user selected an account type before social sign-in
      const pendingAccountType = (typeof window !== 'undefined'
        ? window.localStorage.getItem('pw_pending_account_type')
        : null) as AccountType | null;
      const acctType: AccountType = pendingAccountType || 'investor';

      // Read consent metadata from localStorage if present
      const consentIP = (typeof window !== 'undefined' ? window.localStorage.getItem('pw_pending_consent_ip') : null) || '127.0.0.1';
      const consentVersion = (typeof window !== 'undefined' ? window.localStorage.getItem('pw_pending_consent_version') : null) || 'v1.0';

      // Read UTM parameters and referral code from localStorage
      const firstUtmStr = typeof window !== 'undefined' ? window.localStorage.getItem('pw_first_utm') : null;
      const lastUtmStr = typeof window !== 'undefined' ? window.localStorage.getItem('pw_last_utm') : null;
      const firstUtm = firstUtmStr ? JSON.parse(firstUtmStr) : null;
      const lastUtm = lastUtmStr ? JSON.parse(lastUtmStr) : null;
      const referredBy = typeof window !== 'undefined' ? window.localStorage.getItem('pw_referral_code') : null;

      const dispName = user.displayName || 'User';
      const referralCode = `${dispName.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Math.random().toString(36).substring(2, 7)}`;

      const personalOrgId = `org_${user.uid.slice(0, 8)}`;

      await setDoc(userDocRef, {
        uid: user.uid,
        email: user.email,
        displayName: dispName,
        role: acctType === 'vendor' ? 'Vendor' : 'Lead Investor',
        accountType: acctType,
        personalOrganizationId: personalOrgId,
        memberships: {},
        subscriptionPlan: 'None',
        subscriptionStatus: 'inactive',
        tosConsentVersion: consentVersion,
        tosConsentIP: consentIP,
        tosConsentTimestamp: serverTimestamp(),
        referralCode,
        referredBy: referredBy || null,
        firstUtm,
        lastUtm,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });

      // Bootstrap the personal organization document so API routes can verify membership
      await setDoc(doc(db, 'organizations', personalOrgId), {
        ownerUid: user.uid,
        name: `${dispName}'s Workspace`,
        type: 'personal',
        subscriptionPlan: 'None',
        subscriptionStatus: 'inactive',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });

      // Clean up the pending flags
      if (typeof window !== 'undefined') {
        window.localStorage.removeItem('pw_pending_account_type');
        window.localStorage.removeItem('pw_pending_consent_ip');
        window.localStorage.removeItem('pw_pending_consent_version');
        window.localStorage.removeItem('pw_referral_code');
      }

      // Fire PostHog signup completed event
      posthog.capture('signup_completed', {
        email: user.email,
        accountType: acctType,
        ...firstUtm,
      });

      if (user.email) {
        await reconcilePendingSubscription(user.uid, user.email);
      }

      if (typeof window !== 'undefined') {
        const pendingInviteToken = window.sessionStorage.getItem('pw_pending_invite_token');
        if (pendingInviteToken) {
          try {
            const idToken = await user.getIdToken();
            await fetch('/api/identity/claim/bind-token', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${idToken}`,
              },
              body: JSON.stringify({ token: pendingInviteToken }),
            });
            window.sessionStorage.removeItem('pw_pending_invite_token');
          } catch (e) {
            console.error('Failed to bind invite history:', e);
          }
        }
      }

      return true;
    }

    return false;
  } catch (err) {
    // Non-fatal: user is already authenticated with Firebase Auth.
    // Profile doc can be created later via onSnapshot or server-side.
    logger.error('[provisionSocialUser] Firestore write failed (non-fatal)', err);
    return false;
  }
}

/**
 * Reconciles a pending guest-checkout subscription with a newly created user.
 * If the user checked out as a guest before registering, their subscription
 * metadata is stored in `pending_subscriptions/{email}` by the webhook.
 * This function links it to the new user document and cleans up.
 */
async function reconcilePendingSubscription(uid: string, email: string): Promise<void> {
  try {
    const pendingRef = doc(db, 'pending_subscriptions', email);
    const pendingSnap = await getDoc(pendingRef);

    if (pendingSnap.exists()) {
      const pending = pendingSnap.data();
      const userDocRef = doc(db, 'users', uid);

      await setDoc(userDocRef, {
        subscriptionPlan: pending.plan || 'None',
        subscriptionStatus: pending.subscriptionStatus || 'active',
        stripeCustomerId: pending.stripeCustomerId,
        stripeSubscriptionId: pending.stripeSubscriptionId,
        ...(pending.trialEnd ? { trialEnd: pending.trialEnd } : {}),
        updatedAt: serverTimestamp(),
      }, { merge: true });

      // Clean up the pending record
      await deleteDoc(pendingRef);
      logger.info('[reconcilePendingSubscription] Linked pending subscription', { userId: uid });
    }
  } catch (err) {
    // Non-fatal — the subscription will still exist in Stripe
    // and can be linked manually or on next webhook event.
    logger.error('[reconcilePendingSubscription] Failed (non-fatal)', err);
  }
}

/**
 * Syncs the Firebase ID token to a server-side HttpOnly cookie.
 * Called on every auth state change so the middleware can verify sessions.
 */
async function syncSessionCookie(user: User | null) {
  if (typeof window !== 'undefined') {
    (window as any).__sessionSyncCompleted = false;
    (window as any).__sessionSyncFailed = false;
  }
  if (user) {
    try {
      logger.debug('[syncSessionCookie] Starting — getting token');
      const idToken = await user.getIdToken();
      logger.debug('[syncSessionCookie] Token retrieved, posting to /api/auth/session');
      const res = await fetch('/api/auth/session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ idToken }),
      });
      logger.debug('[syncSessionCookie] Response received', { status: res.status });
      const data = await res.json().catch(() => ({}));
      if (!res.ok) {
        logger.error('[syncSessionCookie] API error', undefined, { status: res.status });
        throw new Error(`Session API failed: ${res.status} ${data.error || ''} ${data.detail || ''}`);
      }
      logger.debug('[syncSessionCookie] Success');
      if (typeof window !== 'undefined') {
        (window as any).__sessionSyncCompleted = true;
      }
      // Verify the cookie was actually set by checking document.cookie
      const hasCookie = document.cookie.includes('__sub=') || document.cookie.includes('__session_id=');
      logger.debug('[syncSessionCookie] Cookie verification', { hasCookie });
    } catch (err: any) {
      logger.error('[syncSessionCookie] Failed', err);
      if (typeof window !== 'undefined') {
        (window as any).__sessionSyncFailed = err.message || true;
      }
      throw err; // Propagate the error so auth flows (login/register) can catch it
    }
  } else {
    try {
      logger.debug('[syncSessionCookie] Clearing session');
      await fetch('/api/auth/session', { method: 'DELETE' });
    } catch (err) {
      logger.error('Failed to clear session cookie', err);
    }
  }
}

/** Token refresh interval — 50 minutes (Firebase ID tokens expire in 60 minutes) */
const TOKEN_REFRESH_MS = 50 * 60 * 1000;

function getCookie(name: string): string | null {
  if (typeof document === 'undefined') return null;
  const match = document.cookie.match(new RegExp('(^| )' + name + '=([^;]+)'));
  if (match) return decodeURIComponent(match[2]);
  return null;
}

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);
  const [isAuthenticating, setIsAuthenticating] = useState(false);
  const [sessionReady, setSessionReady] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [sessionExpiredVisible, setSessionExpiredVisible] = useState(false);
  const [mfaResolver, setMfaResolver] = useState<MultiFactorResolver | null>(null);
  const refreshTimerRef = useRef<ReturnType<typeof setInterval> | null>(null);
  // Ref mirror of isAuthenticating so onAuthStateChanged (a stale closure)
  // can read the current value without being recreated on every render.
  const syncLockRef = useRef(false);
  // Guards against wiping Zustand stores during Firebase's initial auth resolution.
  // Firebase fires onAuthStateChanged(null) before it hydrates the persisted user
  // from IndexedDB on hard refresh. Without this guard every hard refresh wipes
  // in-memory store state before the real user event arrives.
  const hasFirstAuthEventFiredRef = useRef(false);

  // 1. Hydrate useUserStore for mock or demo sessions
  useEffect(() => {
    const isMock = typeof document !== 'undefined' && document.cookie.includes('mock_session_token_123');
    const isDemo = typeof window !== 'undefined' && window.location.pathname.startsWith('/demo');
    if (isMock) {
      const mockUid = getCookie('mock_user_uid') || 'user_lead_investor_seed';
      const mockEmail = getCookie('mock_user_email') || 'marcus@apexcapital.io';
      const mockName = getCookie('mock_user_name') || 'Marcus Aurelius';
      const mockRole = getCookie('mock_user_role') || (typeof window !== 'undefined' && window.location.pathname.startsWith('/admin') ? 'Platform Admin' : 'Lead Investor');
      const mockOrgId = getCookie('mock_user_org_id') || 'org_paperworking_seed';
      const mockAccountType = getCookie('mock_user_account_type') || (mockRole === 'Vendor' ? 'vendor' : 'investor');
      const mockSubPlan = getCookie('mock_user_subscription_plan') || 'Team';

      setUser({
        uid: mockUid,
        email: mockEmail,
        emailVerified: true,
        displayName: mockName,
        getIdToken: async () => 'mock_token',
      } as any);
      setProfile({
        uid: mockUid,
        email: mockEmail,
        name: mockName,
        role: mockRole,
        accountType: mockAccountType,
        subscriptionPlan: mockSubPlan,
        subscriptionStatus: mockSubPlan === 'None' ? 'inactive' : 'active',
        organizationId: mockOrgId,
        onboardingCompleted: true,
        onboardingIntent: 'investor',
      } as any);
      setSessionReady(true);
      setLoading(false);
      useUserStore.setState({
        accountTier: mockSubPlan as any,
        maxSeats: mockSubPlan === 'Team' ? 10 : 1,
        hasActiveSubscription: mockSubPlan !== 'None',
      });
    } else if (isDemo) {
      useUserStore.setState({
        accountTier: 'Team',
        maxSeats: 10,
        hasActiveSubscription: true,
      });
    }
  }, []);

  // 2. Listen to auth state changes + sync session cookie
  useEffect(() => {
    let profileUnsubscribe: (() => void) | null = null;

    const unsubscribe = onAuthStateChanged(auth, async (firebaseUser) => {
      const isMock = typeof document !== 'undefined' && document.cookie.includes('mock_session_token_123');
      if (isMock) {
        const mockUid = getCookie('mock_user_uid') || 'user_lead_investor_seed';
        const mockEmail = getCookie('mock_user_email') || 'marcus@apexcapital.io';
        const mockName = getCookie('mock_user_name') || 'Marcus Aurelius';
        const mockRole = getCookie('mock_user_role') || 'Lead Investor';
        const mockOrgId = getCookie('mock_user_org_id') || 'org_paperworking_seed';
        const mockAccountType = getCookie('mock_user_account_type') || (mockRole === 'Vendor' ? 'vendor' : 'investor');
        const mockSubPlan = getCookie('mock_user_subscription_plan') || 'Team';

        setUser({
          uid: mockUid,
          email: mockEmail,
          emailVerified: true,
          displayName: mockName,
          getIdToken: async () => 'mock_token',
        } as any);
        setProfile({
          uid: mockUid,
          email: mockEmail,
          name: mockName,
          role: mockRole,
          accountType: mockAccountType,
          subscriptionPlan: mockSubPlan,
          subscriptionStatus: mockSubPlan === 'None' ? 'inactive' : 'active',
          organizationId: mockOrgId,
          onboardingCompleted: true,
          onboardingIntent: 'investor',
        } as any);
        setSessionReady(true);
        setLoading(false);
        return;
      }

      if (profileUnsubscribe) {
        profileUnsubscribe();
        profileUnsubscribe = null;
      }

      // Clear any previous refresh timer
      if (refreshTimerRef.current) {
        clearInterval(refreshTimerRef.current);
        refreshTimerRef.current = null;
      }

      if (firebaseUser) {
        hasFirstAuthEventFiredRef.current = true;

        // Fire email_verified once when Firebase first marks the account verified
        if (firebaseUser.emailVerified && typeof window !== 'undefined') {
          const verifKey = `pw_email_verified_fired_${firebaseUser.uid}`;
          if (!window.localStorage.getItem(verifKey)) {
            window.localStorage.setItem(verifKey, '1');
            try { posthog.capture('email_verified', { uid: firebaseUser.uid }); } catch { /* non-fatal */ }
          }
        }

        // H-5: Proactive token refresh on auth-state fire (covers hard page loads).
        // getIdTokenResult(false) reads the cached token without a network call.
        // If <5 min remain, force-refresh NOW before syncSessionCookie runs.
        try {
          const minsLeft = await getTokenExpiryMinutes(firebaseUser);
          if (minsLeft !== null && minsLeft < 5) {
            await firebaseUser.getIdToken(true);
          }
        } catch { /* non-fatal — syncSessionCookie below will still force-refresh */ }

        const docRef = doc(db, 'users', firebaseUser.uid);
        profileUnsubscribe = onSnapshot(docRef, (snap) => {
          if (snap.exists()) {
            const profileData = snap.data() as UserProfile;
            // Legacy/partial docs may lack uid — the authenticated user is the
            // source of truth. TenantContext relies on profile.uid existing.
            setProfile({ ...profileData, uid: profileData.uid || firebaseUser.uid });

            // Authoritatively hydrate the Zustand store
            const plan = profileData.subscriptionPlan ?? 'None';
            const tier = plan === 'Team' ? 'Team' : 'Individual';
            const hasActiveSub =
              profileData.subscriptionStatus === 'active' ||
              profileData.subscriptionStatus === 'trialing';

            useUserStore.setState({
              accountTier: tier,
              maxSeats: tier === 'Team' ? 10 : 1,
              hasActiveSubscription: hasActiveSub,
            });
          }
        });

        // Start token refresh interval — keeps __session cookie valid
        refreshTimerRef.current = setInterval(async () => {
          try {
            await firebaseUser.getIdToken(true);
            await syncSessionCookie(firebaseUser);
          } catch (err: any) {
            logger.error('Token refresh failed', err);

            if (err?.code === 'auth/network-request-failed') {
              // Transient network issue — surface a toast; session may still be valid
              toast.error('Network error — your session may expire soon. Check your connection.', {
                id: 'token-refresh-network',
                duration: 8000,
              });
            } else {
              // H-3: Fatal auth failure (token revoked, user disabled, etc.) —
              // show the session-expired modal. safeLogout() runs inside the modal.
              setSessionExpiredVisible(true);
            }
          }
        }, TOKEN_REFRESH_MS);
      } else {
        setProfile(null);
        // Only wipe stores on a genuine sign-out — not during Firebase's initial
        // auth resolution, which fires null before the persisted user is hydrated.
        if (hasFirstAuthEventFiredRef.current) {
          useProjectStore.getState().clearStore();
          usePropertyStore.getState().clearStore();
          useUserStore.setState({
            accountTier: 'Individual',
            teamMembers: [],
            maxSeats: 1,
            hasActiveSubscription: false,
          });
        }
        hasFirstAuthEventFiredRef.current = true;
      }

      if (firebaseUser) {
        // If a login handler (social / email) already owns the sync, skip it
        // here. The handler sets sessionReady after its own sync succeeds.
        // When NOT locked we own the sync — only set the user if it succeeds,
        // so the login-page user-watcher never navigates without a cookie.
        if (syncLockRef.current) {
          setUser(firebaseUser);
          setLoading(false);
        } else {
          try {
            await syncSessionCookie(firebaseUser);
            setSessionReady(true);
            setUser(firebaseUser);
          } catch (cookieErr) {
            logger.error('[AuthContext] syncSessionCookie failed — signing out to prevent redirect loop', cookieErr);
            setSessionReady(false);
            setUser(null);
            signOut(auth).catch(() => {});
          } finally {
            setLoading(false);
          }
        }
      } else {
        // User signed out — clear cookie best-effort, then clear state.
        setSessionReady(false);
        try {
          if (!syncLockRef.current) {
            await syncSessionCookie(null);
          }
        } catch { /* best effort */ } finally {
          setUser(null);
          setLoading(false);
        }
      }
    });

    return () => {
      unsubscribe();
      if (profileUnsubscribe) profileUnsubscribe();
      if (refreshTimerRef.current) {
        clearInterval(refreshTimerRef.current);
        refreshTimerRef.current = null;
      }
    };
  }, []);

  const clearError = () => setError(null);

  function getAuthErrorMessage(code: string): string {
    switch (code) {
      case 'auth/invalid-email': return 'Please enter a valid email address.';
      case 'auth/user-disabled': return 'This account has been disabled. Contact support.';
      case 'auth/user-not-found':
      case 'auth/wrong-password':
      case 'auth/invalid-credential': return 'Invalid email or password.';
      case 'auth/email-already-in-use': return 'An account with this email already exists.';
      case 'auth/account-exists-with-different-credential':
        return 'This email is already linked to another sign-in method. Try signing in with Google or email/password instead.';
      case 'auth/weak-password': return 'Password must be at least 8 characters.';
      case 'auth/too-many-requests': return 'Account temporarily locked. Try resetting your password.';
      case 'auth/network-request-failed': return 'Network error. Check your connection.';
      case 'auth/popup-closed-by-user': return 'Sign-in was cancelled. Please try again.';
      case 'auth/popup-blocked': return 'Pop-up was blocked by your browser. Please allow pop-ups for this site and try again.';
      case 'auth/redirect-cancelled-by-user': return 'Sign-in redirect was cancelled.';
      case 'auth/internal-error': return 'Authentication service error. Please try again in a moment.';
      case 'auth/unauthorized-domain': return 'This domain is not authorized for sign-in. Contact support.';
      default: return 'An unexpected error occurred. Please try again.';
    }
  }

  /**
   * If Firebase auth succeeded but the session cookie could not be created
   * (network failure, Admin SDK error, CSRF reject, etc.), the Firebase user
   * is signed in but the middleware has no __session cookie to check.
   * The login-page user-watcher would see user=truthy and navigate to
   * /dashboard, which the middleware rejects → redirect to /login → remount
   * → fresh navigatingRef → same navigation → infinite loop.
   *
   * Fix: sign out from Firebase so onAuthStateChanged(null) fires, clears the
   * React user state, and the user-watcher does NOT navigate.
   */
  async function deauthOnCookieFailure() {
    if (auth.currentUser) {
      try { await signOut(auth); } catch { /* best effort — user state will clear via onAuthStateChanged */ }
    }
  }

  const resolveMFASignIn = () => {
    // Called by MFAChallengeModal after resolveSignIn() succeeds.
    // onAuthStateChanged fires with the signed-in user and handles
    // syncSessionCookie + setSessionReady — no duplication needed here.
    setMfaResolver(null);
  };

  const cancelMFAChallenge = async () => {
    setMfaResolver(null);
    // Sign out any partially-authenticated Firebase state so the login
    // form can be retried cleanly.
    await deauthOnCookieFailure();
  };

  const login = async (email: string, password: string) => {
    setError(null);
    useProjectStore.getState().clearStore();
    usePropertyStore.getState().clearStore();
    // Lock out onAuthStateChanged's own sync so this function is the single
    // authoritative sync — same pattern as loginWithGoogle / loginWithFacebook.
    syncLockRef.current = true;
    setIsAuthenticating(true);
    try {
      const { user: loggedInUser } = await signInWithEmailAndPassword(auth, email, password);
      await syncSessionCookie(loggedInUser);
      setSessionReady(true);
    } catch (err: any) {
      if (err.code === 'auth/multi-factor-auth-required') {
        // MFA challenge — store the resolver and show the challenge modal.
        // Do NOT throw: the login page must not treat this as an error.
        setMfaResolver(getMultiFactorResolver(auth, err));
      } else {
        setError(getAuthErrorMessage(err.code));
        setSessionReady(false);
        await deauthOnCookieFailure();
        throw err;
      }
    } finally {
      syncLockRef.current = false;
      setIsAuthenticating(false);
    }
  };

  const register = async (email: string, password: string, displayName: string, accountType: AccountType = 'investor') => {
    setError(null);
    useProjectStore.getState().clearStore();
    usePropertyStore.getState().clearStore();
    syncLockRef.current = true;
    setIsAuthenticating(true);
    try {
      let clientIp = '127.0.0.1';
      try {
        const ipRes = await fetch('/api/auth/ip');
        if (ipRes.ok) {
          const ipData = await ipRes.json();
          clientIp = ipData.ip || '127.0.0.1';
        }
      } catch (e) {
        logger.error('Failed to fetch client IP', e);
      }

      // Read UTM parameters and referral code from localStorage
      const firstUtmStr = typeof window !== 'undefined' ? window.localStorage.getItem('pw_first_utm') : null;
      const lastUtmStr = typeof window !== 'undefined' ? window.localStorage.getItem('pw_last_utm') : null;
      const firstUtm = firstUtmStr ? JSON.parse(firstUtmStr) : null;
      const lastUtm = lastUtmStr ? JSON.parse(lastUtmStr) : null;
      const referredBy = typeof window !== 'undefined' ? window.localStorage.getItem('pw_referral_code') : null;

      const referralCode = `${displayName.toLowerCase().replace(/[^a-z0-9]/g, '-')}-${Math.random().toString(36).substring(2, 7)}`;

      const { user: newUser } = await createUserWithEmailAndPassword(auth, email, password);
      const personalOrgId = `org_${newUser.uid.slice(0, 8)}`;

      await setDoc(doc(db, 'users', newUser.uid), {
        uid: newUser.uid,
        email: newUser.email,
        displayName,
        role: accountType === 'vendor' ? 'Vendor' : 'Lead Investor',
        accountType,
        personalOrganizationId: personalOrgId,
        memberships: {},
        subscriptionPlan: 'None',
        subscriptionStatus: 'inactive',
        tosConsentVersion: 'v1.0',
        tosConsentIP: clientIp,
        tosConsentTimestamp: serverTimestamp(),
        referralCode,
        referredBy: referredBy || null,
        firstUtm,
        lastUtm,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });

      // Bootstrap the personal organization document so API routes can verify membership
      await setDoc(doc(db, 'organizations', personalOrgId), {
        ownerUid: newUser.uid,
        name: `${displayName}'s Workspace`,
        type: 'personal',
        subscriptionPlan: 'None',
        subscriptionStatus: 'inactive',
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });

      // Clean up the pending flags
      if (typeof window !== 'undefined') {
        window.localStorage.removeItem('pw_pending_account_type');
        window.localStorage.removeItem('pw_pending_consent_ip');
        window.localStorage.removeItem('pw_pending_consent_version');
        window.localStorage.removeItem('pw_referral_code');
      }

      // Fire PostHog signup completed event
      posthog.capture('signup_completed', {
        email: newUser.email,
        accountType,
        ...firstUtm,
      });

      if (newUser.email) {
        await reconcilePendingSubscription(newUser.uid, newUser.email);
      }

      if (typeof window !== 'undefined') {
        const pendingInviteToken = window.sessionStorage.getItem('pw_pending_invite_token');
        if (pendingInviteToken) {
          try {
            const idToken = await newUser.getIdToken();
            await fetch('/api/identity/claim/bind-token', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Authorization': `Bearer ${idToken}`,
              },
              body: JSON.stringify({ token: pendingInviteToken }),
            });
            window.sessionStorage.removeItem('pw_pending_invite_token');
          } catch (e) {
            console.error('Failed to bind invite history:', e);
          }
        }
      }

      await syncSessionCookie(newUser);
      setSessionReady(true);
    } catch (err: any) {
      setError(getAuthErrorMessage(err.code));
      setSessionReady(false);
      await deauthOnCookieFailure();
      throw err;
    } finally {
      syncLockRef.current = false;
      setIsAuthenticating(false);
    }
  };

  const loginWithGoogle = async (): Promise<boolean> => {
    setError(null);
    useProjectStore.getState().clearStore();
    usePropertyStore.getState().clearStore();
    syncLockRef.current = true;
    setIsAuthenticating(true);
    try {
      const provider = new GoogleAuthProvider();
      provider.addScope('email');
      provider.addScope('profile');
      const result = await signInWithPopup(auth, provider);
      const isNewUser = await provisionSocialUser(result.user);
      await syncSessionCookie(result.user);
      setSessionReady(true);
      return isNewUser;
    } catch (err: any) {
      if (err.code === 'auth/multi-factor-auth-required') {
        setMfaResolver(getMultiFactorResolver(auth, err));
        return false;
      } else {
        setError(getAuthErrorMessage(err.code));
        setSessionReady(false);
        await deauthOnCookieFailure();
        throw err;
      }
    } finally {
      syncLockRef.current = false;
      setIsAuthenticating(false);
    }
  };

  const loginWithFacebook = async (): Promise<boolean> => {
    setError(null);
    useProjectStore.getState().clearStore();
    usePropertyStore.getState().clearStore();
    syncLockRef.current = true;
    setIsAuthenticating(true);
    try {
      const provider = new FacebookAuthProvider();
      provider.addScope('email');
      provider.addScope('public_profile');
      const result = await signInWithPopup(auth, provider);
      const isNewUser = await provisionSocialUser(result.user);
      await syncSessionCookie(result.user);
      setSessionReady(true);
      return isNewUser;
    } catch (err: any) {
      if (err.code === 'auth/multi-factor-auth-required') {
        setMfaResolver(getMultiFactorResolver(auth, err));
        return false;
      } else {
        setError(getAuthErrorMessage(err.code));
        setSessionReady(false);
        await deauthOnCookieFailure();
        throw err;
      }
    } finally {
      syncLockRef.current = false;
      setIsAuthenticating(false);
    }
  };

  const sendMagicLink = async (email: string) => {
    setError(null);
    try {
      const res = await fetch('/api/auth/magic-link', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to send magic link');
      }
      window.localStorage.setItem('emailForSignIn', email);
    } catch (err: any) {
      setError(err.message || 'Failed to send magic link');
      throw err;
    }
  };

  const verifyMagicLink = async (email: string, url: string): Promise<boolean> => {
    setError(null);
    useProjectStore.getState().clearStore();
    usePropertyStore.getState().clearStore();
    syncLockRef.current = true;
    setIsAuthenticating(true);
    try {
      if (isSignInWithEmailLink(auth, url)) {
        const { user: magicUser } = await signInWithEmailLink(auth, email, url);
        const isNewUser = await provisionSocialUser(magicUser);
        await syncSessionCookie(magicUser);
        setSessionReady(true);
        window.localStorage.removeItem('emailForSignIn');
        return isNewUser;
      } else {
        throw new Error('Invalid magic link.');
      }
    } catch (err: any) {
      setError(getAuthErrorMessage(err.code || ''));
      setSessionReady(false);
      await deauthOnCookieFailure();
      throw err;
    } finally {
      syncLockRef.current = false;
      setIsAuthenticating(false);
    }
  };

  const logout = async () => {
    setError(null);
    useProjectStore.getState().clearStore();
    usePropertyStore.getState().clearStore();
    try {
      await signOut(auth);
    } catch (err: any) {
      setError(getAuthErrorMessage(err.code));
      throw err;
    }
  };

  const resetPassword = async (email: string) => {
    setError(null);
    try {
      const res = await fetch('/api/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email }),
      });
      if (!res.ok) {
        const data = await res.json().catch(() => ({}));
        throw new Error(data.error || 'Failed to request password reset');
      }
    } catch (err: any) {
      setError(err.message || 'Failed to request password reset');
      throw err;
    }
  };

  /**
   * H-5: Call on every hard layout mount (SPA navigation).
   * onAuthStateChanged only fires on browser reload — not on Next.js client-side
   * route transitions. This method closes that window: if the cached ID token
   * has less than 5 minutes left, it force-refreshes and re-syncs the session
   * cookie before the layout renders any authenticated content.
   */
  const refreshSession = async (): Promise<void> => {
    const currentUser = auth.currentUser;
    if (!currentUser) return;
    try {
      const minsLeft = await getTokenExpiryMinutes(currentUser);
      if (minsLeft !== null && minsLeft < 5) {
        await syncSessionCookie(currentUser);
      }
    } catch {
      // Non-fatal — the 50-min interval will retry
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        profile,
        loading,
        isAuthenticating,
        sessionReady,
        error,
        login,
        register,
        loginWithGoogle,
        loginWithFacebook,
        sendMagicLink,
        verifyMagicLink,
        logout,
        resetPassword,
        clearError,
        refreshSession,
        mfaResolver,
        resolveMFASignIn,
        cancelMFAChallenge,
      }}
    >
      {children}
      {/* H-3: Session-expired modal */}
      {sessionExpiredVisible && (
        <SessionExpiredModal onDismiss={() => setSessionExpiredVisible(false)} />
      )}
      {/* MFA challenge — shown when any sign-in method requires a TOTP second factor */}
      {mfaResolver && (
        <MFAChallengeModal
          resolver={mfaResolver}
          onResolved={resolveMFASignIn}
          onCancel={cancelMFAChallenge}
        />
      )}
    </AuthContext.Provider>
  );
}

// Stable no-op store subscription — the "is mounted" snapshot never changes
// after hydration, so there is nothing to subscribe to.
const noopSubscribe = () => () => {};

export function useAuth() {
  const context = useContext(AuthContext);

  // The mock-session and /demo overrides below read document.cookie /
  // window.location — client-only signals that don't exist during SSR. Applying
  // them on the first client render diverges from the server-rendered HTML and
  // triggers a hydration mismatch (e.g. avatar initial "U" vs "T"). useSyncExternalStore
  // returns the server snapshot (false) during SSR and the first hydration render,
  // then the client snapshot (true), so the override applies only after hydration.
  const mounted = useSyncExternalStore(
    noopSubscribe,
    () => true,
    () => false
  );

  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }

  if (!mounted) return context;

  const isMockSession = document.cookie.includes('mock_session_token_123');

  if (isMockSession) {
    const orgCookie = typeof document !== 'undefined'
      ? document.cookie.split('; ').find(row => row.startsWith('__org='))?.split('=')[1]
      : null;
    const mockUserOrgIdCookie = typeof document !== 'undefined'
      ? document.cookie.split('; ').find(row => row.startsWith('mock_user_org_id='))?.split('=')[1]
      : null;
    const personalOrgId = mockUserOrgIdCookie || orgCookie || 'org_placeholder';

    const uidCookie = typeof document !== 'undefined'
      ? document.cookie.split('; ').find(row => row.startsWith('mock_user_uid='))?.split('=')[1]
      : null;
    const emailCookie = typeof document !== 'undefined'
      ? document.cookie.split('; ').find(row => row.startsWith('mock_user_email='))?.split('=')[1]
      : null;
    const nameCookie = typeof document !== 'undefined'
      ? document.cookie.split('; ').find(row => row.startsWith('mock_user_name='))?.split('=')[1]
      : null;
    const roleCookie = typeof document !== 'undefined'
      ? document.cookie.split('; ').find(row => row.startsWith('mock_user_role='))?.split('=')[1]
      : null;

    const decodedEmail = emailCookie ? decodeURIComponent(emailCookie) : 'test@paperworking.co';
    const decodedName = nameCookie ? decodeURIComponent(nameCookie) : 'Test User';
    const decodedRole = roleCookie ? decodeURIComponent(roleCookie) : 'Lead Investor';

    const mockUser = {
      uid: uidCookie || 'user_123',
      email: decodedEmail,
      displayName: decodedName,
      getIdToken: async () => 'mock_token',
      getIdTokenResult: async () => ({ token: 'mock_token', claims: {} }),
    } as any;

    const mockProfile = {
      uid: uidCookie || 'user_123',
      email: decodedEmail,
      displayName: decodedName,
      role: decodedRole,
      personalOrganizationId: personalOrgId,
      subscriptionPlan: 'Team',
      subscriptionStatus: 'active',
      onboardingCompleted: true,
      onboardingIntent: 'investor',
    } as any;

    return {
      ...context,
      user: context.user || mockUser,
      profile: context.profile || mockProfile,
      loading: false,
    };
  }

  // If client-side and path starts with /demo, override user/profile for seamless demo mode
  if (typeof window !== 'undefined' && window.location.pathname.startsWith('/demo')) {
    const demoUser = {
      uid: 'demo_user',
      email: 'demo@paperworking.co',
      displayName: 'Demo Investor',
      getIdToken: async () => 'demo_token',
      getIdTokenResult: async () => ({ token: 'demo_token', claims: {} }),
    } as any;

    const demoProfile = {
      uid: 'demo_user',
      email: 'demo@paperworking.co',
      displayName: 'Demo Investor',
      role: 'Lead Investor',
      personalOrganizationId: 'org_demo_seed',
      subscriptionPlan: 'Team',
      subscriptionStatus: 'active',
    } as any;

    return {
      ...context,
      user: context.user || demoUser,
      profile: context.profile || demoProfile,
      loading: false,
    };
  }

  return context;
}

