source:
'use client';

import React, { createContext, useContext, useEffect, useState, useCallback, useRef } from 'react';
import {
  collection,
  query,
  where,
  onSnapshot,
  doc,
  updateDoc,
  writeBatch,
  Timestamp,
  deleteDoc,
  arrayUnion,
  addDoc,
} from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import { NotificationType } from '@/types/notification';
import toast from 'react-hot-toast';
import { requestPushPermissionAndGetToken, onForegroundMessage } from '@/lib/firebase/messaging';

export type InboxTabType = 'all' | 'opportunities' | 'tasks' | 'vendors' | 'team' | 'system';

const SENSITIVE_NOTIFICATION_TYPES: NotificationType[] = [
  'BILLING_CHARGED',
  'RECEIPT_APPROVAL',
  'BURN_RATE_WARNING',
  'OVER_IMPROVEMENT_ALERT',
  'VENDOR_BID',
  'INVEST_INVITE'
];

export function mapNotificationTypeToTab(type: NotificationType): InboxTabType {
  switch (type) {
    case 'PHASE_TRANSITION':
    case 'DEADLINE_ALERT':
    case 'OVER_IMPROVEMENT_ALERT':
    case 'BURN_RATE_WARNING':
    case 'INVEST_INVITE':
      return 'opportunities';
    case 'TASK_COMPLETE':
    case 'TASK_ASSIGNED':
    case 'LENDER_CHECKLIST_REMINDER':
      return 'tasks';
    case 'VENDOR_BID':
    case 'VENDOR_LEAD':
      return 'vendors';
    case 'TEAM_INVITE':
    case 'TEAM_INVITE_REMINDER':
    case 'DOCUMENT_SIGNED':
      return 'team';
    case 'BILLING_CHARGED':
    case 'RECEIPT_APPROVAL':
    default:
      return 'system';
  }
}

interface NotificationContextType {
  unreadCounts: Record<InboxTabType, number>;
  unreadTotal: number;
  loading: boolean;
  markAsRead: (id: string, type: NotificationType) => Promise<void>;
  markAllRead: (items: { id: string; type: NotificationType }[]) => Promise<void>;
  archiveItem: (id: string, wasUnread: boolean, type: NotificationType) => Promise<void>;
  deleteItem: (id: string, wasUnread: boolean, type: NotificationType) => Promise<void>;
  bulkArchive: (itemsToArchive: { id: string; wasUnread: boolean; type: NotificationType }[]) => Promise<void>;
}

const NotificationContext = createContext<NotificationContextType | undefined>(undefined);

export function NotificationProvider({ children }: { children: React.ReactNode }) {
  const { user, profile } = useAuth();
  const uid = user?.uid;

  const [unreadCounts, setUnreadCounts] = useState<Record<InboxTabType, number>>({
    all: 0,
    opportunities: 0,
    tasks: 0,
    vendors: 0,
    team: 0,
    system: 0,
  });
  const [loading, setLoading] = useState(true);

  // Keep a ref of counts for rollback / reference
  const countsRef = useRef(unreadCounts);
  countsRef.current = unreadCounts;

  // Register push notifications when user logs in (respecting opt-out settings)
  useEffect(() => {
    if (!uid || profile?.preferences?.pushEnabled === false) return;

    let unsubscribeForeground: (() => void) | null = null;

    const registerPush = async () => {
      try {
        const token = await requestPushPermissionAndGetToken();
        if (token) {
          await updateDoc(doc(db, 'users', uid), {
            fcmTokens: arrayUnion(token)
          });

          // Listen to foreground notifications
          unsubscribeForeground = onForegroundMessage((payload) => {
            const title = payload.notification?.title || payload.data?.title || 'Critical Alert';
            const body = payload.notification?.body || payload.data?.body || '';
            toast.success(`${title}: ${body}`, {
              icon: '🔔',
              duration: 6000
            });
          });
        }
      } catch (err) {
        console.warn('[NotificationContext] Push registration failed (non-fatal):', err);
      }
    };

    registerPush();

    return () => {
      if (unsubscribeForeground) unsubscribeForeground();
    };
  }, [uid, profile?.preferences?.pushEnabled]);

  // Throttled client activity tracker updating lastActiveAt in Firestore
  useEffect(() => {
    if (!uid) return;

    let lastSyncTime = 0;
    const SYNC_INTERVAL = 2 * 60 * 1000; // 2 minutes

    const syncActivity = async () => {
      const now = Date.now();
      if (now - lastSyncTime < SYNC_INTERVAL) return;

      try {
        lastSyncTime = now;
        await updateDoc(doc(db, 'users', uid), {
          lastActiveAt: Timestamp.now()
        });
        console.log('[NotificationContext] Synced client activity (lastActiveAt).');
      } catch (err) {
        console.error('[NotificationContext] Failed to sync activity:', err);
      }
    };

    const handleActivity = () => {
      syncActivity();
    };

    // Sync immediately upon mount / login
    syncActivity();

    window.addEventListener('focus', handleActivity);
    window.addEventListener('click', handleActivity);
    window.addEventListener('keydown', handleActivity);
    window.addEventListener('scroll', handleActivity);
    window.addEventListener('mousemove', handleActivity);

    return () => {
      window.removeEventListener('focus', handleActivity);
      window.removeEventListener('click', handleActivity);
      window.removeEventListener('keydown', handleActivity);
      window.removeEventListener('scroll', handleActivity);
      window.removeEventListener('mousemove', handleActivity);
    };
  }, [uid]);

  useEffect(() => {
    if (!uid) {
      setUnreadCounts({
        all: 0,
        opportunities: 0,
        tasks: 0,
        vendors: 0,
        team: 0,
        system: 0,
      });
      setLoading(false);
      return;
    }

    setLoading(true);

    const unreadQuery = query(
      collection(db, 'notifications'),
      where('recipientId', '==', uid),
      where('archived', '==', false),
      where('read', '==', false)
    );

    const unsubscribe = onSnapshot(
      unreadQuery,
      (snapshot) => {
        const counts: Record<InboxTabType, number> = {
          all: 0,
          opportunities: 0,
          tasks: 0,
          vendors: 0,
          team: 0,
          system: 0,
        };

        snapshot.docs.forEach((doc) => {
          const type = doc.data().type as NotificationType;
          const tab = mapNotificationTypeToTab(type);
          counts.all++;
          counts[tab]++;
        });

        setUnreadCounts(counts);
        setLoading(false);
      },
      (err) => {
        console.error('[NotificationContext] Unread count listener error:', err);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [uid]);

  const markAsRead = useCallback(async (id: string, type: NotificationType) => {
    // Optimistic decrement
    const tab = mapNotificationTypeToTab(type);
    setUnreadCounts((prev) => ({
      ...prev,
      all: Math.max(0, prev.all - 1),
      [tab]: Math.max(0, prev[tab] - 1),
    }));

    try {
      await updateDoc(doc(db, 'notifications', id), {
        read: true,
        readAt: Timestamp.now(),
      });

      if (SENSITIVE_NOTIFICATION_TYPES.includes(type)) {
        await addDoc(collection(db, 'auditLog'), {
          type: 'sensitive_notification_access',
          userId: uid,
          notificationId: id,
          notificationType: type,
          action: 'read',
          at: Timestamp.now()
        });
      }
    } catch (err) {
      console.error('[NotificationContext] markAsRead error:', err);
      // Rollback
      setUnreadCounts(countsRef.current);
      throw err;
    }
  }, [uid]);

  const markAllRead = useCallback(async (unreadItems: { id: string; type: NotificationType }[]) => {
    if (unreadItems.length === 0) return;

    // Optimistic decrement
    setUnreadCounts((prev) => {
      const next = { ...prev };
      unreadItems.forEach((item) => {
        const tab = mapNotificationTypeToTab(item.type);
        next.all = Math.max(0, next.all - 1);
        next[tab] = Math.max(0, next[tab] - 1);
      });
      return next;
    });

    try {
      const batch = writeBatch(db);
      const now = Timestamp.now();
      unreadItems.forEach((item) => {
        batch.update(doc(db, 'notifications', item.id), {
          read: true,
          readAt: now,
        });
      });
      await batch.commit();

      for (const item of unreadItems) {
        if (SENSITIVE_NOTIFICATION_TYPES.includes(item.type)) {
          await addDoc(collection(db, 'auditLog'), {
            type: 'sensitive_notification_access',
            userId: uid,
            notificationId: item.id,
            notificationType: item.type,
            action: 'read_bulk',
            at: now
          });
        }
      }
    } catch (err) {
      console.error('[NotificationContext] markAllRead error:', err);
      setUnreadCounts(countsRef.current);
      throw err;
    }
  }, [uid]);

  const archiveItem = useCallback(async (id: string, wasUnread: boolean, type: NotificationType) => {
    if (wasUnread) {
      const tab = mapNotificationTypeToTab(type);
      setUnreadCounts((prev) => ({
        ...prev,
        all: Math.max(0, prev.all - 1),
        [tab]: Math.max(0, prev[tab] - 1),
      }));
    }

    try {
      await updateDoc(doc(db, 'notifications', id), {
        archived: true,
      });

      if (SENSITIVE_NOTIFICATION_TYPES.includes(type)) {
        await addDoc(collection(db, 'auditLog'), {
          type: 'sensitive_notification_access',
          userId: uid,
          notificationId: id,
          notificationType: type,
          action: 'archive',
          at: Timestamp.now()
        });
      }
    } catch (err) {
      console.error('[NotificationContext] archiveItem error:', err);
      if (wasUnread) setUnreadCounts(countsRef.current);
      throw err;
    }
  }, [uid]);

  const deleteItem = useCallback(async (id: string, wasUnread: boolean, type: NotificationType) => {
    if (wasUnread) {
      const tab = mapNotificationTypeToTab(type);
      setUnreadCounts((prev) => ({
        ...prev,
        all: Math.max(0, prev.all - 1),
        [tab]: Math.max(0, prev[tab] - 1),
      }));
    }

    try {
      await deleteDoc(doc(db, 'notifications', id));

      if (SENSITIVE_NOTIFICATION_TYPES.includes(type)) {
        await addDoc(collection(db, 'auditLog'), {
          type: 'sensitive_notification_access',
          userId: uid,
          notificationId: id,
          notificationType: type,
          action: 'delete',
          at: Timestamp.now()
        });
      }
    } catch (err) {
      console.error('[NotificationContext] deleteItem error:', err);
      if (wasUnread) setUnreadCounts(countsRef.current);
      throw err;
    }
  }, [uid]);

  const bulkArchive = useCallback(async (items: { id: string; wasUnread: boolean; type: NotificationType }[]) => {
    if (items.length === 0) return;

    // Optimistic decrement
    setUnreadCounts((prev) => {
      const next = { ...prev };
      items.forEach((item) => {
        if (item.wasUnread) {
          const tab = mapNotificationTypeToTab(item.type);
          next.all = Math.max(0, next.all - 1);
          next[tab] = Math.max(0, next[tab] - 1);
        }
      });
      return next;
    });

    try {
      const batch = writeBatch(db);
      const now = Timestamp.now();
      items.forEach((item) => {
        batch.update(doc(db, 'notifications', item.id), {
          archived: true,
        });
      });
      await batch.commit();

      for (const item of items) {
        if (SENSITIVE_NOTIFICATION_TYPES.includes(item.type)) {
          await addDoc(collection(db, 'auditLog'), {
            type: 'sensitive_notification_access',
            userId: uid,
            notificationId: item.id,
            notificationType: item.type,
            action: 'archive_bulk',
            at: now
          });
        }
      }
    } catch (err) {
      console.error('[NotificationContext] bulkArchive error:', err);
      setUnreadCounts(countsRef.current);
      throw err;
    }
  }, [uid]);

  return (
    <NotificationContext.Provider
      value={{
        unreadCounts,
        unreadTotal: unreadCounts.all,
        loading,
        markAsRead,
        markAllRead,
        archiveItem,
        deleteItem,
        bulkArchive,
      }}
    >
      {children}
    </NotificationContext.Provider>
  );
}

export function useNotification() {
  const context = useContext(NotificationContext);
  if (context === undefined) {
    throw new Error('useNotification must be used within a NotificationProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useMemo, useState, useCallback } from 'react';
import { useProjectStore } from '@/store/projectStore';
import { PHASE_UNLOCK_HINTS } from '@/lib/constants/phaseMessages';

interface PhaseGateContextValue {
  /** Set of lane IDs that are currently locked. */
  lockedLanes: Set<string>;
  /** Returns the toast message to show when a locked lane is attempted. */
  lockMessage: (laneId: string) => string;
  /** Currently focused deal ID — persists across lane transitions. */
  selectedDealId: string | null;
  setSelectedDealId: (id: string | null) => void;
}

const PhaseGateContext = createContext<PhaseGateContextValue>({
  lockedLanes: new Set(),
  lockMessage: () => '',
  selectedDealId: null,
  setSelectedDealId: () => {},
});

export function usePhaseGate() {
  return useContext(PhaseGateContext);
}

export function PhaseGateProvider({ children }: { children: React.ReactNode }) {
  const projects = useProjectStore((s) => s.projects);
  const [selectedDealId, setSelectedDealId] = useState<string | null>(null);

  const lockedLanes = useMemo<Set<string>>(() => {
    const locked = new Set<string>();

    // pipeline: unlocks when user has ≥ 1 project
    if (projects.length === 0) locked.add('pipeline');

    // evaluation: unlocks when any deal is in fund phase
    const hasUnderContract = projects.some((p) => p.status === 'fund');
    if (!hasUnderContract) locked.add('evaluation');

    // closing: unlocks when any Phase2Snapshot.isClearToClose is true or in a later phase
    const hasClearToClose = projects.some(
      (p) => (p as any).isClearToClose === true || p.status === 'hold' || p.status === 'exit'
    );
    if (!hasClearToClose) locked.add('closing');

    // rehab: unlocks when any deal is in hold phase
    const hasRenovating = projects.some((p) => p.status === 'hold');
    if (!hasRenovating) locked.add('rehab');

    // exit: unlocks when any deal is in exit phase
    const hasListed = projects.some((p) => p.status === 'exit');
    if (!hasListed) locked.add('exit');

    // findandfund (0) and engine (5) are always unlocked — never added

    return locked;
  }, [projects]);

  const lockMessage = useCallback(
    (laneId: string) => PHASE_UNLOCK_HINTS[laneId] ?? `Complete earlier phases to unlock this workspace.`,
    []
  );

  return (
    <PhaseGateContext.Provider value={{ lockedLanes, lockMessage, selectedDealId, setSelectedDealId }}>
      {children}
    </PhaseGateContext.Provider>
  );
}

'use client';

import React, {
  createContext,
  useContext,
  useEffect,
  useState,
  useMemo,
  useCallback,
} from 'react';
import { useWorkspaceProject } from '@/app/dashboard/projects/[id]/layout';
import { projectsService } from '@/lib/firebase/deals';
import type {
  PhaseSnapshotMap,
  PhaseSnapshotKey,
  Phase1Snapshot,
  Phase2Snapshot,
  Phase3Snapshot,
} from '@/types/schema';

/* ═══════════════════════════════════════════════════════════════
   ProjectPipelineContext

   Single source of truth for cross-phase financial inheritance.

   Architecture:
   ┌─ Phase 1 (ProjectCalculator) ─────────────────────────────────┐
   │  saves → project.financials.{purchasePrice, ARV, ...}      │
   │  on advance → writes phaseSnapshots/phase-1 (immutable)    │
   └────────────────────────────────────────────────────────────┘
             ▼
   ProjectPipelineContext  (this file)
             │  derives phase1Live from live project.financials
             │  fetches immutable snapshots from Firestore
             ▼
   Phase 2, 3, 4 pages via usePipelineData() / usePhaseSummary()

   No additional Firestore listener is opened — the context piggy-
   backs on the project object from WorkspaceContext (fetched once
   by the workspace layout shell).
   ═══════════════════════════════════════════════════════════════ */

// ── Live Phase 1 financial summary (derived from project.financials) ──
export interface Phase1Live {
  purchasePrice:         number;
  estimatedARV:          number;
  loanAmount:            number;
  loanInterestRate:      number;
  loanOriginationPoints: number;
  projectedRehabCost:    number;
  estimatedTimelineDays: number;
  fixedAcquisitionCosts: number;
  maxOffer:              number;
}

// ── Full pipeline data shape exposed to consumers ─────────────
export interface PipelineData {
  /** Live Phase 1 values read directly from project.financials.
   *  Available in every phase; these are the "current" inputs. */
  phase1Live: Phase1Live;

  /** Immutable snapshots from completed phases (may be partial). */
  snapshots: PhaseSnapshotMap;

  /** Derived all-in cost: purchasePrice + capitalizedBasis + rehabActual + holdingTotal.
   *  Used by Phase 4 P&L seed without re-entry. */
  derivedAllInCost: number;

  /** True if the given phase has been formally advanced past. */
  isPhaseComplete: (key: PhaseSnapshotKey) => boolean;

  /** Whether the pipeline context is still loading snapshots. */
  snapshotsLoading: boolean;
}

// ── Context default (pre-load safe values) ────────────────────
const EMPTY_PHASE1: Phase1Live = {
  purchasePrice:         0,
  estimatedARV:          0,
  loanAmount:            0,
  loanInterestRate:      0,
  loanOriginationPoints: 0,
  projectedRehabCost:    0,
  estimatedTimelineDays: 0,
  fixedAcquisitionCosts: 0,
  maxOffer:              0,
};

const PipelineContext = createContext<PipelineData>({
  phase1Live:       EMPTY_PHASE1,
  snapshots:        {},
  derivedAllInCost: 0,
  isPhaseComplete:  () => false,
  snapshotsLoading: true,
});

// ── Provider ──────────────────────────────────────────────────
export function ProjectPipelineProvider({ children }: { children: React.ReactNode }) {
  const { project } = useWorkspaceProject();
  const [snapshots, setSnapshots] = useState<PhaseSnapshotMap>({});
  const [snapshotsLoading, setSnapshotsLoading] = useState(true);

  // Fetch immutable snapshots once per project ID
  useEffect(() => {
    if (!project?.id) return;
    let active = true;

    setSnapshotsLoading(true);
    projectsService.getPhaseSnapshots(project.id)
      .then(map => { if (active) { setSnapshots(map); setSnapshotsLoading(false); } })
      .catch(() => { if (active) setSnapshotsLoading(false); });

    return () => { active = false; };
  }, [project?.id]);

  // Derive Phase 1 live values from project.financials (always current)
  const phase1Live = useMemo<Phase1Live>(() => {
    const f = project?.financials;
    if (!f) return EMPTY_PHASE1;
    return {
      purchasePrice:         f.purchasePrice         ?? 0,
      estimatedARV:          f.estimatedARV           ?? 0,
      loanAmount:            f.loanAmount             ?? 0,
      loanInterestRate:      f.loanInterestRate       ?? 0,
      loanOriginationPoints: f.loanOriginationPoints  ?? 0,
      projectedRehabCost:    f.projectedRehabCost     ?? 0,
      estimatedTimelineDays: f.estimatedTimelineDays  ?? 0,
      fixedAcquisitionCosts: f.fixedAcquisitionCosts  ?? 0,
      maxOffer:              f.maxOffer               ?? 0,
    };
  }, [project?.financials]);

  // Derived all-in cost: purchasePrice + capitalized basis + rehab actuals + holding
  const derivedAllInCost = useMemo(() => {
    const basis = phase1Live.purchasePrice;

    // Capitalized basis from Phase 2 cost ledger (if captured)
    const p2 = snapshots['phase-2'];
    const capitalizedBasis = p2?.initialCapitalizedBasis ?? 0;

    // Rehab actuals + holding totals from Phase 3 snapshot (if captured)
    const p3 = snapshots['phase-3'];
    const rehabActual  = p3?.totalRehabActual  ?? (project?.financials?.projectedRehabCost ?? 0);
    const holdingTotal = p3?.totalHoldingCosts ?? 0;

    return basis + capitalizedBasis + rehabActual + holdingTotal;
  }, [phase1Live.purchasePrice, snapshots, project?.financials?.projectedRehabCost]);

  const isPhaseComplete = useCallback((key: PhaseSnapshotKey): boolean => {
    return key in snapshots;
  }, [snapshots]);

  const value = useMemo<PipelineData>(() => ({
    phase1Live,
    snapshots,
    derivedAllInCost,
    isPhaseComplete,
    snapshotsLoading,
  }), [phase1Live, snapshots, derivedAllInCost, isPhaseComplete, snapshotsLoading]);

  return (
    <PipelineContext.Provider value={value}>
      {children}
    </PipelineContext.Provider>
  );
}

// ── Consumer hooks ────────────────────────────────────────────

/** Access the full pipeline data object. */
export function usePipelineData(): PipelineData {
  return useContext(PipelineContext);
}

/**
 * Typed per-phase summary accessor.
 *
 * Usage in Phase 3:
 *   const snap = usePhaseSummary('phase-1');
 *   // snap is Phase1Snapshot | undefined
 *
 * Falls back to live project.financials for phase-1 when no snapshot
 * exists (i.e., the user hasn't formally advanced yet).
 */
export function usePhaseSummary(key: 'phase-1'): Phase1Snapshot | Phase1Live;
export function usePhaseSummary(key: 'phase-2'): Phase2Snapshot | undefined;
export function usePhaseSummary(key: 'phase-3'): Phase3Snapshot | undefined;
export function usePhaseSummary(key: PhaseSnapshotKey) {
  const { snapshots, phase1Live } = usePipelineData();

  if (key === 'phase-1') {
    // Return immutable snapshot if captured, otherwise live values
    return (snapshots['phase-1'] as Phase1Snapshot | undefined) ?? phase1Live;
  }
  if (key === 'phase-2') {
    return snapshots['phase-2'] as Phase2Snapshot | undefined;
  }
  return snapshots['phase-3'] as Phase3Snapshot | undefined;
}

