'use client';

import { useState, useCallback, useEffect } from 'react';
import type { BridgeOpenHouseResult } from '@/types/bridge';

interface OpenHouseCalendarState {
  openHouses: BridgeOpenHouseResult[];
  loading: boolean;
  error: string | null;
}

/**
 * Hook for the Open House Calendar — fetches upcoming open houses.
 * Auto-fetches on mount; can be refreshed manually.
 */
export function useOpenHouseCalendar(autoFetch = true) {
  const [state, setState] = useState<OpenHouseCalendarState>({
    openHouses: [],
    loading: false,
    error: null,
  });

  const fetchOpenHouses = useCallback(async (listingKey?: string, top = 30) => {
    setState(prev => ({ ...prev, loading: true, error: null }));

    try {
      const params = new URLSearchParams();
      if (listingKey) params.set('listingKey', listingKey);
      params.set('top', String(top));

      const res = await fetch(`/api/bridge/openhouses?${params.toString()}`);
      if (!res.ok) throw new Error('Fetch failed');

      const data = await res.json();

      if (data.unavailable) {
        setState({
          openHouses: [],
          loading: false,
          error: 'Open house calendar is temporarily unavailable.',
        });
        return;
      }

      setState({
        openHouses: data.results ?? [],
        loading: false,
        error: null,
      });
    } catch {
      setState(prev => ({
        ...prev,
        loading: false,
        error: 'Failed to load open houses.',
      }));
    }
  }, []);

  useEffect(() => {
    if (autoFetch) {
      fetchOpenHouses();
    }
  }, [autoFetch, fetchOpenHouses]);

  return {
    ...state,
    fetchOpenHouses,
  };
}

'use client';

import { useCallback } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/context/AuthContext';

export type SubscriptionTier = 'free' | 'paid' | 'guest';

/**
 * Derives the user's access tier from their Firestore profile.
 *
 * - guest: arrived via a crowdfund/collaborator invite link (has inviteToken + invitedToProjectId)
 * - paid:  active or past_due subscription (not a guest)
 * - free:  no active subscription (new signups, canceled accounts)
 */
function deriveTier(profile: any): SubscriptionTier {
  if (!profile) return 'free';
  if (profile.inviteToken && profile.invitedToProjectId) return 'guest';
  const status: string = profile.subscriptionStatus ?? '';
  if (status === 'active' || status === 'trialing' || status === 'past_due') return 'paid';
  return 'free';
}

/**
 * usePaywall
 *
 * Single source of truth for subscription-gated actions.
 *
 * Usage:
 *   const { isPaid, isGuest, requireSubscription } = usePaywall();
 *   <button onClick={() => requireSubscription(() => openWizard())}>New Project</button>
 *
 * requireSubscription runs the action if the user is paid, otherwise
 * performs a hard router.push('/pricing').
 */
export function usePaywall() {
  const { profile } = useAuth();
  const router = useRouter();

  const tier = deriveTier(profile);

  const requireSubscription = useCallback(
    (action: () => void) => {
      if (tier === 'paid') {
        action();
      } else {
        router.push('/pricing');
      }
    },
    [tier, router],
  );

  return {
    tier,
    isPaid: tier === 'paid',
    isGuest: tier === 'guest',
    isFree: tier === 'free',
    requireSubscription,
  };
}

import { useAuth } from '@/context/AuthContext';
import { Role, Permission, ProjectMember } from '@/types/schema';
import { AuthorizationService } from '@/lib/auth/AuthorizationService';

/* ═══════════════════════════════════════════════════════
   usePermissions Hook — SSA-Grade Access Control

   Centralized logic for gating dashboard actions.
   Usage:
   const { can, role } = usePermissions();
   if (can('projects.edit')) { ... }
   ═══════════════════════════════════════════════════════ */

export function usePermissions(projectMember?: ProjectMember) {
  const { profile } = useAuth();

  // Default to a safe fallback role if user profile is missing role
  const role: Role = profile?.role || profile?.orgRole || 'Guest';

  const can = (permission: Permission) => {
    return AuthorizationService.can({ user: profile as any, projectMember }, permission);
  };

  const isLead = role === 'Lead Investor' || role === 'Admin' || role === 'Platform Admin';
  const isAdmin = role === 'Admin' || role === 'Platform Admin';
  const isContractor = role === 'General Contractor';
  const isFinanceTeam = isLead || role === 'Accountant';
  const isLender = role === 'Lender';

  // Convenience: can the current user edit project content (todos, financials)?
  const canEdit = can('projects.edit');

  return { 
    can, 
    role, 
    isLead,
    isAdmin,
    isContractor,
    isFinanceTeam,
    isLender,
    canEdit,
  };
}

"use client";

import { useMemo } from "react";
import { useProjectStore } from "@/store/projectStore";
import {
  computeNOIComponents,
  computeCapRate,
  computeCoCReturn,
  computeDSCR,
  computeOER,
  computeGRM,
  computeAnnualDebtService,
  deriveAllProjectMetrics,
  computeDOM,
} from "@/lib/metrics/reiMetrics";
import type { Project } from "@/types/schema";

// ─── Interfaces ──────────────────────────────────────────────────────────────

export interface StressParameters {
  vacancyRate: number; // e.g. 5 for 5% (slider 0-25)
  interestRateSpike: number; // e.g. 1 for +1% (slider 0-3)
  opexOverrun: number; // e.g. 20 for +20% (slider 0-50)
  taxReassessment: number; // e.g. 30 for +30% (slider 0-40)
  rentGrowthOverride?: number; // annual rent growth override (percentage e.g. 3)
  expenseGrowthOverride?: number; // annual expense growth override (percentage e.g. 2.5)
}

export interface AmortizationMonth {
  month: number;
  payment: number;
  interest: number;
  principal: number;
  remainingBalance: number;
}

export interface ProFormaYear {
  year: number;
  propertyValue: number;
  grossRentalIncome: number;
  otherIncome: number;
  vacancyLoss: number;
  egi: number;
  opex: number;
  noi: number;
  debtService: number;
  preTaxCashFlow: number;
  cumulativeCashFlow: number;
  appreciation: number;
  principalPaydown: number;
  netProfit: number;
  coc: number;
  roi: number;
  capRate: number;
  dscr: number;
  oer: number;
  grm: number;
  priceToRent: number;
}

export interface ProjectInsights {
  id: string;
  propertyName: string;
  dispositionType?: string;
  subStrategy?: string;
  currentPhase?: number;
  purchasePrice: number;
  propertyValue: number;
  noi: number;
  egi: number;
  opex: number;
  capRate: number;
  annualPreTaxCashFlow: number;
  totalCashInvested: number;
  coc: number;
  roi: number;
  netProfit: number;
  totalInvestment: number;
  dscr: number;
  oer: number;
  grm: number;
  priceToRent: number;
  dom: number | null;
  isWorkingCapital: boolean;
  proForma: ProFormaYear[];
}

export interface PortfolioRollup {
  totalNOI: number;
  averageCapRate: number;
  averageCoC: number;
  averageROI: number;
  averageDSCR: number;
  averageOER: number;
  averageGRM: number;
  priceToRentRatio: number;
  averageDOM: number;
}

// ─── Helpers & Utilities ─────────────────────────────────────────────────────

/**
 * Standard median helper
 */
function median(values: number[]): number {
  if (values.length === 0) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const half = Math.floor(sorted.length / 2);
  if (sorted.length % 2 !== 0) {
    return sorted[half];
  }
  return (sorted[half - 1] + sorted[half]) / 2;
}

/**
 * Standard average helper
 */
function average(values: number[]): number {
  if (values.length === 0) return 0;
  return values.reduce((sum, v) => sum + v, 0) / values.length;
}

/**
 * Monthly Amortization Schedule Solver
 * Incorporates Month 360 (or final month) Amortization Drift Reconciliation Guard.
 */
export function generateAmortizationSchedule(
  loanAmount: number,
  annualInterestRatePercent: number,
  loanTermMonths: number
): AmortizationMonth[] {
  if (loanAmount <= 0 || loanTermMonths <= 0) return [];

  const r = annualInterestRatePercent / 100 / 12;
  const n = loanTermMonths;
  let monthlyPayment = 0;

  if (annualInterestRatePercent > 0) {
    const pow = Math.pow(1 + r, n);
    monthlyPayment = (loanAmount * r * pow) / (pow - 1);
  } else {
    monthlyPayment = loanAmount / n;
  }

  // Round monthly payment to cents
  monthlyPayment = Math.round(monthlyPayment * 100) / 100;

  const schedule: AmortizationMonth[] = [];
  let balance = loanAmount;

  for (let m = 1; m <= n; m++) {
    if (balance <= 0) {
      schedule.push({
        month: m,
        payment: 0,
        interest: 0,
        principal: 0,
        remainingBalance: 0,
      });
      continue;
    }

    let interest = 0;
    if (annualInterestRatePercent > 0) {
      interest = Math.round(balance * r * 100) / 100;
    }

    let principal = Math.round((monthlyPayment - interest) * 100) / 100;

    // Check if it's the final month of the loan
    const isFinalMonth = m === n;
    if (isFinalMonth || principal >= balance) {
      // Amortization Drift Reconciliation Guard:
      // Force the final principal portion to equal exactly the remaining balance
      principal = balance;
      const finalPayment = Math.round((principal + interest) * 100) / 100;
      balance = 0;
      schedule.push({
        month: m,
        payment: finalPayment,
        interest,
        principal,
        remainingBalance: 0,
      });
    } else {
      balance = Math.round((balance - principal) * 100) / 100;
      schedule.push({
        month: m,
        payment: monthlyPayment,
        interest,
        principal,
        remainingBalance: balance,
      });
    }
  }

  return schedule;
}

/**
 * Calculates a 10-year pro forma projection for a single project.
 */
export function calculate10YearProForma(
  project: Project,
  stressParams?: StressParameters
): ProFormaYear[] {
  const financials = project.financials || {};
  const purchasePrice = financials.purchasePrice ?? financials.targetPrice ?? financials.targetPurchasePrice ?? 0;
  const initialPropertyValue = financials.estimatedCurrentValue ?? financials.estimatedARV ?? purchasePrice;

  // 1. Core initial values from reiMetrics components
  const baseComponents = computeNOIComponents(financials, project.dispositionType, project.currentPhase ?? 1);
  const baseRentalIncome = baseComponents.grossRentalIncome;
  const baseOtherIncome = baseComponents.otherIncome;
  const baseTaxes = baseComponents.propertyTaxes;

  // 2. Extract growth/appreciation assumptions
  let rentGrowthRate = 3; // default 3% rent growth
  if (stressParams?.rentGrowthOverride !== undefined) {
    rentGrowthRate = stressParams.rentGrowthOverride;
  } else if (financials.annualRentGrowthPercent !== undefined) {
    rentGrowthRate = financials.annualRentGrowthPercent;
  }

  const rentGrowth = rentGrowthRate / 100;
  const expGrowth = (stressParams?.expenseGrowthOverride !== undefined ? stressParams.expenseGrowthOverride : 2.5) / 100; // default 2.5% inflation
  const appreciation = (financials.annualAppreciationPercent ?? 4) / 100; // default 4% appreciation

  // 3. Setup Debt and Amortization details
  const loanAmount = financials.loanAmount ?? 0;
  let loanRate = financials.loanInterestRate ?? 0;
  if (stressParams?.interestRateSpike) {
    loanRate += stressParams.interestRateSpike;
  }
  const loanTermYears = financials.loanTermYears ?? 30;
  const loanTermMonths = loanTermYears * 12;

  const amortization = generateAmortizationSchedule(loanAmount, loanRate, loanTermMonths);

  // 4. Denominators for yields
  const derived = deriveAllProjectMetrics(project);
  const totalInvestment = derived.totalInvestment > 0 ? derived.totalInvestment : purchasePrice;
  const totalCashInvested = financials.financingCashInvested ?? computeTotalCashInvestedFallback(project);

  const proForma: ProFormaYear[] = [];
  let cumulativeCashFlow = 0;

  for (let year = 1; year <= 10; year++) {
    // Escalate rental income and other income (YoY growth starts in Year 2)
    const rentEscalationFactor = Math.pow(1 + rentGrowth, year - 1);
    const grossRentalIncome = baseRentalIncome * rentEscalationFactor;
    const otherIncome = baseOtherIncome * rentEscalationFactor;

    // Apply vacancy rate (absolute rate override or project value)
    const vacancyRatePct = stressParams?.vacancyRate !== undefined
      ? stressParams.vacancyRate
      : (financials.vacancyRatePercent ?? financials.vacancyRate ?? 7);
    const vacancyLoss = grossRentalIncome * (vacancyRatePct / 100);
    const egi = grossRentalIncome + otherIncome - vacancyLoss;

    // Escalate operating expenses (taxes, insurance, utilities, maintenance, pm, hoa)
    const expEscalationFactor = Math.pow(1 + expGrowth, year - 1);

    // Tax reassessment adjusts Year 1 taxes immediately
    const taxFactor = 1 + (stressParams?.taxReassessment ?? 0) / 100;
    const adjustedBaseTaxes = baseTaxes * taxFactor;

    // Build rest of operating expenses
    const opexOtherThanTaxes = baseComponents.totalOperatingExpenses - baseTaxes;

    // Scale expenses by inflation, then apply general opex overrun factor if present
    let opex = (adjustedBaseTaxes + opexOtherThanTaxes) * expEscalationFactor;
    if (stressParams?.opexOverrun) {
      opex = opex * (1 + stressParams.opexOverrun / 100);
    }

    const noi = egi - opex;

    // Value appreciation
    const propertyValue = initialPropertyValue * Math.pow(1 + appreciation, year - 1);

    // Amortization details for Year t (months 12*(t-1) + 1 to 12*t)
    let debtService = 0;
    let principalPaidYear = 0;
    let finalMonthIdx = year * 12 - 1;
    let outstandingBalance = 0;

    if (amortization.length > 0) {
      const startMonthIdx = (year - 1) * 12;
      const endMonthIdx = Math.min(year * 12, amortization.length);

      for (let m = startMonthIdx; m < endMonthIdx; m++) {
        debtService += amortization[m].payment;
        principalPaidYear += amortization[m].principal;
      }
      // Outstanding balance is at the end of the last month of the year
      const lastYearMonth = Math.min(finalMonthIdx, amortization.length - 1);
      outstandingBalance = lastYearMonth >= 0 ? amortization[lastYearMonth].remainingBalance : 0;
    }

    const preTaxCashFlow = noi - debtService;
    cumulativeCashFlow += preTaxCashFlow;

    const propertyAppreciation = propertyValue - purchasePrice;
    const cumulativePrincipalPaydown = amortization.length > 0 
      ? loanAmount - outstandingBalance 
      : 0;

    // Net Profit: Cumulative cash flow + appreciation + principal paydown
    const netProfit = cumulativeCashFlow + propertyAppreciation + cumulativePrincipalPaydown;

    // Metrics calculations
    const capRate = propertyValue > 0 ? (noi / propertyValue) * 100 : 0;
    const coc = totalCashInvested > 0 ? (preTaxCashFlow / totalCashInvested) * 100 : 0;
    const roi = totalInvestment > 0 ? (netProfit / totalInvestment) * 100 : 0;
    const dscr = debtService > 0 ? noi / debtService : (noi > 0 ? 999 : 0);
    const oer = egi > 0 ? (opex / egi) * 100 : 0;
    const grm = grossRentalIncome > 0 ? purchasePrice / grossRentalIncome : 0;
    const priceToRent = grossRentalIncome > 0 ? purchasePrice / grossRentalIncome : 0;

    proForma.push({
      year,
      propertyValue,
      grossRentalIncome,
      otherIncome,
      vacancyLoss,
      egi,
      opex,
      noi,
      debtService,
      preTaxCashFlow,
      cumulativeCashFlow,
      appreciation: propertyAppreciation,
      principalPaydown: cumulativePrincipalPaydown,
      netProfit,
      coc,
      roi,
      capRate,
      dscr,
      oer,
      grm,
      priceToRent,
    });
  }

  return proForma;
}

/**
 * Fallback calculator for out-of-pocket cash invested in a deal
 */
function computeTotalCashInvestedFallback(project: Project): number {
  const financials = project.financials || {};
  const purchasePrice = financials.purchasePrice ?? financials.targetPrice ?? financials.targetPurchasePrice ?? 0;
  const isAllCash = financials.financingType === 'All Cash';
  const loanAmount = financials.loanAmount ?? 0;
  const downPayment = isAllCash ? purchasePrice : Math.max(0, purchasePrice - loanAmount);

  // upfront rehab (Acquisition)
  const upfrontRehab = financials.upfrontRehab ?? 0;

  // closing costs (Acquisition-projected, awaiting actual)
  let closingCosts = financials.closingCosts ?? financials.targetClosingCosts ?? financials.fixedAcquisitionCosts ?? 0;
  if (closingCosts === 0 && financials.totalCashInvested != null && financials.totalCashInvested > 0) {
    closingCosts = Math.max(0, financials.totalCashInvested - downPayment - upfrontRehab);
  }

  const emdVerified = financials.emdVerified ?? false;
  const emdAmount = financials.emdAmount ?? financials.loiEarnestAmount ?? 0;

  const baseCash = downPayment + closingCosts + upfrontRehab;

  if (emdVerified) {
    return baseCash + emdAmount;
  }
  return baseCash;
}

// ─── Main Hook ───────────────────────────────────────────────────────────────

/**
 * Ingests portfolio properties, applies risk stress testing parameters, and resolves pro formas and rollup cards.
 */
export function usePortfolioInsights(
  projectsOverride?: Project[],
  stressParams?: StressParameters
) {
  const storeProjects = useProjectStore((s) => s.projects);
  const projects = projectsOverride !== undefined ? projectsOverride : storeProjects;

  return useMemo(() => {
    if (!projects || projects.length === 0) {
      return {
        projectInsights: [],
        stabilizedProjects: [],
        workingCapitalProjects: [],
        portfolioRollup: {
          totalNOI: 0,
          averageCapRate: 0,
          averageCoC: 0,
          averageROI: 0,
          averageDSCR: 0,
          averageOER: 0,
          averageGRM: 0,
          priceToRentRatio: 0,
          averageDOM: 0,
        },
        portfolioProForma: Array.from({ length: 10 }, (_, i) => ({
          year: i + 1,
          propertyValue: 0,
          grossRentalIncome: 0,
          otherIncome: 0,
          vacancyLoss: 0,
          egi: 0,
          opex: 0,
          noi: 0,
          debtService: 0,
          preTaxCashFlow: 0,
          cumulativeCashFlow: 0,
          appreciation: 0,
          principalPaydown: 0,
          netProfit: 0,
          coc: 0,
          roi: 0,
          capRate: 0,
          dscr: 0,
          oer: 0,
          grm: 0,
          priceToRent: 0,
        })),
      };
    }

    // 1. Process all projects and determine working capital vs. stabilized status
    const allProjectInsights = projects.map((p) => {
      const financials = p.financials || {};
      const purchasePrice = financials.purchasePrice ?? financials.targetPrice ?? financials.targetPurchasePrice ?? 0;
      const propertyValue = financials.estimatedCurrentValue ?? financials.estimatedARV ?? purchasePrice;

      // Check working capital classification:
      // - dispositionType === 'SALE'
      // - status === 'Renovating'
      // - currentPhase <= 3 (acquisition, rehab, finding deals)
      const isWorkingCapital =
        p.dispositionType === "SALE" ||
        p.status === "hold" ||
        (p.currentPhase !== undefined && p.currentPhase <= 3);

      // Generate 10-year pro forma trajectory
      const proForma = calculate10YearProForma(p, stressParams);
      const yr1 = proForma[0];

      return {
        id: p.id,
        propertyName: p.propertyName || "Unnamed Property",
        dispositionType: p.dispositionType,
        subStrategy: p.subStrategy,
        currentPhase: p.currentPhase,
        purchasePrice,
        propertyValue,
        noi: yr1.noi,
        egi: yr1.egi,
        opex: yr1.opex,
        capRate: yr1.capRate,
        annualPreTaxCashFlow: yr1.preTaxCashFlow,
        totalCashInvested: financials.financingCashInvested ?? computeTotalCashInvestedFallback(p),
        coc: yr1.coc,
        roi: yr1.roi,
        netProfit: yr1.netProfit,
        totalInvestment: yr1.propertyValue - yr1.appreciation, // base total investment helper
        dscr: yr1.dscr,
        oer: yr1.oer,
        grm: yr1.grm,
        priceToRent: yr1.priceToRent,
        dom: computeDOM(financials.listingDate, financials.soldDate),
        isWorkingCapital,
        proForma,
      };
    });

    // 2. Split into separate groups
    const stabilizedProjects = allProjectInsights.filter((x) => !x.isWorkingCapital);
    const workingCapitalProjects = allProjectInsights.filter((x) => x.isWorkingCapital);

    // 3. Stabilized Portfolio Rollups (so flips do not skew metrics)
    const stabilizedRollupProjects = stabilizedProjects.length > 0 ? stabilizedProjects : allProjectInsights;

    const totalNOI = stabilizedRollupProjects.reduce((sum, x) => sum + x.noi, 0);

    const validPrices = stabilizedRollupProjects.map((x) => x.purchasePrice).filter((x) => x > 0);
    const validRents = stabilizedRollupProjects.map((x) => x.egi).filter((x) => x > 0);

    const medianPrice = median(validPrices);
    const avgAnnualRent = average(validRents);
    const portfolioPriceToRent = avgAnnualRent > 0 ? medianPrice / avgAnnualRent : 0;

    const averageCapRate = average(stabilizedRollupProjects.map((x) => x.capRate).filter((x) => x > 0));
    const averageCoC = average(stabilizedRollupProjects.map((x) => x.coc).filter((x) => x > 0));
    const averageROI = average(stabilizedRollupProjects.map((x) => x.roi).filter((x) => x > 0));
    const averageDSCR = average(stabilizedRollupProjects.map((x) => x.dscr).filter((x) => x > 0 && x !== 999));
    const averageOER = average(stabilizedRollupProjects.map((x) => x.oer).filter((x) => x > 0));
    const averageGRM = average(stabilizedRollupProjects.map((x) => x.grm).filter((x) => x > 0));

    const validDOMs = stabilizedRollupProjects.map((x) => x.dom).filter((x) => x !== null && x !== undefined && x > 0) as number[];
    const averageDOM = validDOMs.length > 0 ? average(validDOMs) : 0;

    // 4. Aggregate 10-year pro forma across all stabilized projects
    const portfolioProForma: ProFormaYear[] = Array.from({ length: 10 }, (_, i) => {
      const year = i + 1;
      let yearPropertyValue = 0;
      let yearGrossRentalIncome = 0;
      let yearOtherIncome = 0;
      let yearVacancyLoss = 0;
      let yearEgi = 0;
      let yearOpex = 0;
      let yearNoi = 0;
      let yearDebtService = 0;
      let yearPreTaxCashFlow = 0;
      let yearCumulativeCashFlow = 0;
      let yearAppreciation = 0;
      let yearPrincipalPaydown = 0;
      let yearNetProfit = 0;

      let purchasePriceSum = 0;
      let totalCashInvestedSum = 0;
      let totalInvestmentSum = 0;

      stabilizedRollupProjects.forEach((proj) => {
        const pf = proj.proForma[i];
        yearPropertyValue += pf.propertyValue;
        yearGrossRentalIncome += pf.grossRentalIncome;
        yearOtherIncome += pf.otherIncome;
        yearVacancyLoss += pf.vacancyLoss;
        yearEgi += pf.egi;
        yearOpex += pf.opex;
        yearNoi += pf.noi;
        yearDebtService += pf.debtService;
        yearPreTaxCashFlow += pf.preTaxCashFlow;
        yearCumulativeCashFlow += pf.cumulativeCashFlow;
        yearAppreciation += pf.appreciation;
        yearPrincipalPaydown += pf.principalPaydown;
        yearNetProfit += pf.netProfit;

        purchasePriceSum += proj.purchasePrice;
        totalCashInvestedSum += proj.totalCashInvested;

        // Find totalInvestment
        const derived = projects.find(p => p.id === proj.id);
        const inv = derived ? (deriveAllProjectMetrics(derived).totalInvestment) : proj.purchasePrice;
        totalInvestmentSum += inv > 0 ? inv : proj.purchasePrice;
      });

      const coc = totalCashInvestedSum > 0 ? (yearPreTaxCashFlow / totalCashInvestedSum) * 100 : 0;
      const roi = totalInvestmentSum > 0 ? (yearNetProfit / totalInvestmentSum) * 100 : 0;
      const capRate = yearPropertyValue > 0 ? (yearNoi / yearPropertyValue) * 100 : 0;
      const dscr = yearDebtService > 0 ? yearNoi / yearDebtService : (yearNoi > 0 ? 999 : 0);
      const oer = yearEgi > 0 ? (yearOpex / yearEgi) * 100 : 0;
      const grm = yearGrossRentalIncome > 0 ? purchasePriceSum / yearGrossRentalIncome : 0;
      const priceToRent = yearGrossRentalIncome > 0 ? purchasePriceSum / yearGrossRentalIncome : 0;

      return {
        year,
        propertyValue: yearPropertyValue,
        grossRentalIncome: yearGrossRentalIncome,
        otherIncome: yearOtherIncome,
        vacancyLoss: yearVacancyLoss,
        egi: yearEgi,
        opex: yearOpex,
        noi: yearNoi,
        debtService: yearDebtService,
        preTaxCashFlow: yearPreTaxCashFlow,
        cumulativeCashFlow: yearCumulativeCashFlow,
        appreciation: yearAppreciation,
        principalPaydown: yearPrincipalPaydown,
        netProfit: yearNetProfit,
        coc,
        roi,
        capRate,
        dscr,
        oer,
        grm,
        priceToRent,
      };
    });

    return {
      projectInsights: allProjectInsights,
      stabilizedProjects,
      workingCapitalProjects,
      portfolioRollup: {
        totalNOI,
        averageCapRate,
        averageCoC,
        averageROI,
        averageDSCR,
        averageOER,
        averageGRM,
        priceToRentRatio: portfolioPriceToRent,
        averageDOM,
      },
      portfolioProForma,
    };
  }, [projects, stressParams]);
}

import { useEffect, useState } from 'react';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import { useTenant } from '@/context/TenantContext';
import { PropertyMetricSnapshot, Project } from '@/types/schema';

export interface PortfolioMetricSnapshot {
  organizationId: string;
  period: string;
  periodType: 'monthly' | 'quarterly' | 'annual';
  date: Date;

  // 10 financial metrics + IRR
  noi: number | null;
  annualCashFlow: number | null;
  monthlyCashFlow: number | null;
  capRate: number | null;
  cashOnCashReturn: number | null;
  grossRentMultiplier: number | null;
  dscr: number | null;
  ltv: number | null;
  oer: number | null;
  occupancyRate: number | null;
  vacancyRate: number | null;
  irr: number | null;
  appreciation: number | null;

  // Aggregated component fields
  propertyValue: number | null;
  totalCashInvested: number | null;
  grossRentalIncome: number | null;
  annualDebtService: number | null;
  loanAmount: number | null;
  totalOperatingExpenses: number | null;
  grossOperatingIncome: number | null;
  occupiedUnits: number | null;
  numberOfUnits: number | null;
}

/**
 * A client hook to retrieve dynamically aggregated, portfolio-weighted time-series snapshots
 * for the current authenticated user's organization.
 * 
 * @param periodType - Optional filter for the type of period ('monthly' | 'quarterly' | 'annual').
 * @param projects - Optional list of projects used to apply ownershipPercentage scaling for 'myShare' scope.
 * @param scope - Optional scope ('property' | 'myShare').
 */
export function usePortfolioMetricSnapshots(
  periodType?: 'monthly' | 'quarterly' | 'annual',
  projects?: Project[],
  scope?: 'property' | 'myShare'
) {
  const { profile } = useAuth();
  const { activeTenantId } = useTenant();
  const [snapshots, setSnapshots] = useState<PortfolioMetricSnapshot[]>([]);
  const [rawSnapshots, setRawSnapshots] = useState<PropertyMetricSnapshot[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const orgId = activeTenantId;
    if (typeof window !== 'undefined' && window.location.pathname.startsWith('/demo')) {
      const demoPortfolioSnapshots = [
        {
          organizationId: 'org_demo_seed',
          period: '2026-01',
          periodType: 'monthly',
          date: new Date('2026-01-01'),
          noi: 12000,
          annualCashFlow: 8000,
          monthlyCashFlow: 666,
          capRate: 6.2,
          cashOnCashReturn: 8.5,
          grossRentMultiplier: 10,
          dscr: 1.25,
          ltv: 75,
          oer: 38,
          occupancyRate: 90,
          irr: 12,
          appreciation: 3,
          propertyValue: 500000,
          totalCashInvested: 150000,
          grossRentalIncome: 3500,
          annualDebtService: 24000,
          loanAmount: 375000,
          totalOperatingExpenses: 1330,
          grossOperatingIncome: 3170,
          occupiedUnits: 9,
          numberOfUnits: 10,
        },
        {
          organizationId: 'org_demo_seed',
          period: '2026-02',
          periodType: 'monthly',
          date: new Date('2026-02-01'),
          noi: 12500,
          annualCashFlow: 8500,
          monthlyCashFlow: 708,
          capRate: 6.3,
          cashOnCashReturn: 8.7,
          grossRentMultiplier: 9.8,
          dscr: 1.27,
          ltv: 74,
          oer: 37.5,
          occupancyRate: 92,
          irr: 12.5,
          appreciation: 3.2,
          propertyValue: 510000,
          totalCashInvested: 150000,
          grossRentalIncome: 3600,
          annualDebtService: 24000,
          loanAmount: 370000,
          totalOperatingExpenses: 1350,
          grossOperatingIncome: 3250,
          occupiedUnits: 9,
          numberOfUnits: 10,
        },
        {
          organizationId: 'org_demo_seed',
          period: '2026-03',
          periodType: 'monthly',
          date: new Date('2026-03-01'),
          noi: 13000,
          annualCashFlow: 9000,
          monthlyCashFlow: 750,
          capRate: 6.5,
          cashOnCashReturn: 9.0,
          grossRentMultiplier: 9.6,
          dscr: 1.30,
          ltv: 72,
          oer: 36.8,
          occupancyRate: 95,
          irr: 13,
          appreciation: 3.5,
          propertyValue: 520000,
          totalCashInvested: 150000,
          grossRentalIncome: 3700,
          annualDebtService: 24000,
          loanAmount: 365000,
          totalOperatingExpenses: 1360,
          grossOperatingIncome: 3340,
          occupiedUnits: 10,
          numberOfUnits: 10,
        }
      ] as any[];

      setSnapshots(demoPortfolioSnapshots);

      const demoProjects = projects && projects.length > 0 ? projects : [
        { id: 'proj_demo_1', propertyName: 'Demo Property 1' },
        { id: 'proj_demo_2', propertyName: 'Demo Property 2' }
      ] as any[];

      const mockRaw: PropertyMetricSnapshot[] = [];
      demoPortfolioSnapshots.forEach((ps) => {
        demoProjects.forEach((proj, idx) => {
          const multiplier = 0.9 + (idx * 0.2); // project 1 gets 0.9x, project 2 gets 1.1x
          mockRaw.push({
            id: `snap_${proj.id}_${ps.period}`,
            projectId: proj.id,
            organizationId: ps.organizationId,
            period: ps.period,
            periodType: ps.periodType,
            date: ps.date,
            noi: ps.noi ? ps.noi * multiplier : null,
            annualCashFlow: ps.annualCashFlow ? ps.annualCashFlow * multiplier : null,
            monthlyCashFlow: ps.monthlyCashFlow ? ps.monthlyCashFlow * multiplier : null,
            capRate: ps.capRate ? ps.capRate * multiplier : null,
            cashOnCashReturn: ps.cashOnCashReturn ? ps.cashOnCashReturn * multiplier : null,
            grossRentMultiplier: ps.grossRentMultiplier ? ps.grossRentMultiplier / multiplier : null,
            dscr: ps.dscr ? ps.dscr * multiplier : null,
            ltv: ps.ltv ? ps.ltv * multiplier : null,
            oer: ps.oer ? ps.oer / multiplier : null,
            occupancyRate: ps.occupancyRate ? Math.min(100, ps.occupancyRate * multiplier) : null,
            vacancyRate: ps.occupancyRate ? 100 - Math.min(100, ps.occupancyRate * multiplier) : null,
            irr: ps.irr ? ps.irr * multiplier : null,
            appreciation: ps.appreciation ? ps.appreciation * multiplier : null,
            propertyValue: ps.propertyValue ? ps.propertyValue * multiplier : null,
            totalCashInvested: ps.totalCashInvested ? ps.totalCashInvested * multiplier : null,
            grossRentalIncome: ps.grossRentalIncome ? ps.grossRentalIncome * multiplier : null,
            annualDebtService: ps.annualDebtService ? ps.annualDebtService * multiplier : null,
            loanAmount: ps.loanAmount ? ps.loanAmount * multiplier : null,
            totalOperatingExpenses: ps.totalOperatingExpenses ? ps.totalOperatingExpenses * multiplier : null,
            grossOperatingIncome: ps.grossOperatingIncome ? ps.grossOperatingIncome * multiplier : null,
            occupiedUnits: ps.occupiedUnits ? Math.round(ps.occupiedUnits * multiplier) : null,
            numberOfUnits: ps.numberOfUnits ? Math.round(ps.numberOfUnits * multiplier) : null,
          } as any);
        });
      });

      setRawSnapshots(mockRaw);
      setLoading(false);
      return;
    }

    if (!orgId || orgId === 'org_placeholder') {
      setSnapshots([]);
      setLoading(false);
      return;
    }

    setLoading(true);
    setError(null);

    const q = query(
      collection(db, 'propertyMetricSnapshots'),
      where('organizationId', '==', orgId)
    );

    const unsubscribe = onSnapshot(
      q,
      (snapshot) => {
        const rawDocs = snapshot.docs.map((d) => {
          const data = d.data();
          return {
            ...data,
            id: d.id,
            date: data.date?.toDate?.() ?? data.date ?? new Date(),
            createdAt: data.createdAt?.toDate?.() ?? data.createdAt ?? new Date(),
          } as PropertyMetricSnapshot;
        });

        // Filter by periodType in memory
        let filteredDocs = periodType
          ? rawDocs.filter((doc) => doc.periodType === periodType)
          : rawDocs;

        // Filter by active projects if provided
        if (projects) {
          const projectIds = new Set(projects.map((p) => p.id));
          filteredDocs = filteredDocs.filter((doc) => projectIds.has(doc.projectId));
        }

        // Group snapshots by period
        const groups: Record<string, PropertyMetricSnapshot[]> = {};
        for (const doc of filteredDocs) {
          if (!groups[doc.period]) {
            groups[doc.period] = [];
          }
          groups[doc.period].push(doc);
        }

        // Aggregate for each period
        const aggregated: PortfolioMetricSnapshot[] = Object.keys(groups).map((period) => {
          const groupSnapshots = groups[period];
          const firstSnapshot = groupSnapshots[0];

          // Sum helper for basic metrics
          const sumField = (field: keyof PropertyMetricSnapshot): { sum: number; hasValue: boolean } => {
            let sum = 0;
            let hasValue = false;
            for (const s of groupSnapshots) {
              const val = s[field];
              if (val !== null && typeof val === 'number') {
                let factor = 1;
                if (scope === 'myShare' && projects) {
                  const proj = projects.find(p => p.id === s.projectId);
                  if (proj) {
                    factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                  }
                }
                sum += val * factor;
                hasValue = true;
              }
            }
            return { sum, hasValue };
          };

          const noiData = sumField('noi');
          const acfData = sumField('annualCashFlow');
          const mcfData = sumField('monthlyCashFlow');
          const valData = sumField('propertyValue');
          const cashInvestedData = sumField('totalCashInvested');
          const rentalIncomeData = sumField('grossRentalIncome');
          const debtServiceData = sumField('annualDebtService');
          const loanAmountData = sumField('loanAmount');
          const operatingExpensesData = sumField('totalOperatingExpenses');
          const grossOperatingIncomeData = sumField('grossOperatingIncome');
          const occupiedUnitsData = sumField('occupiedUnits');
          const numberOfUnitsData = sumField('numberOfUnits');

          // Summed components
          const noi = noiData.hasValue ? noiData.sum : null;
          const annualCashFlow = acfData.hasValue ? acfData.sum : null;
          const monthlyCashFlow = mcfData.hasValue ? mcfData.sum : null;
          const propertyValue = valData.hasValue ? valData.sum : null;
          const totalCashInvested = cashInvestedData.hasValue ? cashInvestedData.sum : null;
          const grossRentalIncome = rentalIncomeData.hasValue ? rentalIncomeData.sum : null;
          const annualDebtService = debtServiceData.hasValue ? debtServiceData.sum : null;
          const loanAmount = loanAmountData.hasValue ? loanAmountData.sum : null;
          const totalOperatingExpenses = operatingExpensesData.hasValue ? operatingExpensesData.sum : null;
          const grossOperatingIncome = grossOperatingIncomeData.hasValue ? grossOperatingIncomeData.sum : null;
          const occupiedUnits = occupiedUnitsData.hasValue ? occupiedUnitsData.sum : null;
          const numberOfUnits = numberOfUnitsData.hasValue ? numberOfUnitsData.sum : null;

          // Cap Rate: Sum(noi) / Sum(propertyValue) * 100
          let capRateNoiSum = 0;
          let capRateValSum = 0;
          let hasCapRate = false;
          for (const s of groupSnapshots) {
            if (s.noi !== null && s.propertyValue !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              capRateNoiSum += s.noi * factor;
              capRateValSum += s.propertyValue * factor;
              hasCapRate = true;
            }
          }
          const capRate = (hasCapRate && capRateValSum > 0) ? (capRateNoiSum / capRateValSum) * 100 : null;

          // Cash-on-Cash Return: Sum(annualCashFlow) / Sum(totalCashInvested) * 100
          let cocCashFlowSum = 0;
          let cocInvestedSum = 0;
          let hasCoc = false;
          for (const s of groupSnapshots) {
            if (s.annualCashFlow !== null && s.totalCashInvested !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              cocCashFlowSum += s.annualCashFlow * factor;
              cocInvestedSum += s.totalCashInvested * factor;
              hasCoc = true;
            }
          }
          const cashOnCashReturn = (hasCoc && cocInvestedSum > 0) ? (cocCashFlowSum / cocInvestedSum) * 100 : null;

          // GRM: Sum(propertyValue) / Sum(grossRentalIncome)
          let grmValSum = 0;
          let grmRentalSum = 0;
          let hasGrm = false;
          for (const s of groupSnapshots) {
            if (s.propertyValue !== null && s.grossRentalIncome !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              grmValSum += s.propertyValue * factor;
              grmRentalSum += s.grossRentalIncome * factor;
              hasGrm = true;
            }
          }
          const grossRentMultiplier = (hasGrm && grmRentalSum > 0) ? (grmValSum / grmRentalSum) : null;

          // DSCR: Sum(noi) / Sum(annualDebtService)
          let dscrNoiSum = 0;
          let dscrDebtSum = 0;
          let hasDscr = false;
          for (const s of groupSnapshots) {
            if (s.noi !== null && s.annualDebtService !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              dscrNoiSum += s.noi * factor;
              dscrDebtSum += s.annualDebtService * factor;
              hasDscr = true;
            }
          }
          const dscr = (hasDscr && dscrDebtSum > 0) ? (dscrNoiSum / dscrDebtSum) : null;

          // LTV: Sum(loanAmount) / Sum(propertyValue) * 100
          let ltvLoanSum = 0;
          let ltvValSum = 0;
          let hasLtv = false;
          for (const s of groupSnapshots) {
            if (s.loanAmount !== null && s.propertyValue !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              ltvLoanSum += s.loanAmount * factor;
              ltvValSum += s.propertyValue * factor;
              hasLtv = true;
            }
          }
          const ltv = (hasLtv && ltvValSum > 0) ? (ltvLoanSum / ltvValSum) * 100 : null;

          // OER: Sum(totalOperatingExpenses) / Sum(grossRentalIncome) * 100
          let oerExpensesSum = 0;
          let oerRentalSum = 0;
          let hasOer = false;
          for (const s of groupSnapshots) {
            if (s.totalOperatingExpenses !== null && s.grossRentalIncome !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              oerExpensesSum += s.totalOperatingExpenses * factor;
              oerRentalSum += s.grossRentalIncome * factor;
              hasOer = true;
            }
          }
          const oer = (hasOer && oerRentalSum > 0) ? (oerExpensesSum / oerRentalSum) * 100 : null;

          // Occupancy Rate: Sum(occupiedUnits) / Sum(numberOfUnits) * 100
          // If no units are defined at all, fall back to simple average of occupancyRate
          let occupancyRate = null;
          let occupiedUnitsSum = 0;
          let totalUnitsSum = 0;
          let hasOccupancy = false;
          for (const s of groupSnapshots) {
            if (s.occupiedUnits !== null && s.numberOfUnits !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              occupiedUnitsSum += s.occupiedUnits * factor;
              totalUnitsSum += s.numberOfUnits * factor;
              hasOccupancy = true;
            }
          }
          if (hasOccupancy && totalUnitsSum > 0) {
            occupancyRate = (occupiedUnitsSum / totalUnitsSum) * 100;
          } else {
            let occSum = 0;
            let occCount = 0;
            for (const s of groupSnapshots) {
              if (s.occupancyRate !== null) {
                occSum += s.occupancyRate;
                occCount++;
              }
            }
            occupancyRate = occCount > 0 ? occSum / occCount : null;
          }

          // Weighted IRR: Sum(irr * totalCashInvested) / Sum(totalCashInvested)
          let irrWeightedSum = 0;
          let irrInvestedSum = 0;
          let hasIrr = false;
          for (const s of groupSnapshots) {
            if (s.irr !== null && s.totalCashInvested !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              irrWeightedSum += s.irr * (s.totalCashInvested * factor);
              irrInvestedSum += s.totalCashInvested * factor;
              hasIrr = true;
            }
          }
          const irr = (hasIrr && irrInvestedSum > 0) ? (irrWeightedSum / irrInvestedSum) : null;

          // Weighted Appreciation: Sum(appreciation * propertyValue) / Sum(propertyValue)
          let appreciationWeightedSum = 0;
          let appreciationValSum = 0;
          let hasAppreciation = false;
          for (const s of groupSnapshots) {
            const app = (s as any).appreciation;
            if (app !== null && app !== undefined && s.propertyValue !== null) {
              let factor = 1;
              if (scope === 'myShare' && projects) {
                const proj = projects.find(p => p.id === s.projectId);
                if (proj) {
                  factor = ((proj.financials as any)?.ownershipPercentage ?? 100) / 100;
                }
              }
              appreciationWeightedSum += app * (s.propertyValue * factor);
              appreciationValSum += s.propertyValue * factor;
              hasAppreciation = true;
            }
          }
          const appreciation = (hasAppreciation && appreciationValSum > 0) ? (appreciationWeightedSum / appreciationValSum) : null;

          return {
            organizationId: orgId,
            period,
            periodType: firstSnapshot.periodType,
            date: firstSnapshot.date,

            noi,
            annualCashFlow,
            monthlyCashFlow,
            capRate,
            cashOnCashReturn,
            grossRentMultiplier,
            dscr,
            ltv,
            oer,
            occupancyRate,
            vacancyRate: occupancyRate !== null ? 100 - occupancyRate : null,
            irr,
            appreciation,

            propertyValue,
            totalCashInvested,
            grossRentalIncome,
            annualDebtService,
            loanAmount,
            totalOperatingExpenses,
            grossOperatingIncome,
            occupiedUnits,
            numberOfUnits,
          };
        });

        // Sort chronologically (ascending by date)
        const sortedAggregated = aggregated.sort((a, b) => {
          const timeA = new Date(a.date).getTime();
          const timeB = new Date(b.date).getTime();
          if (timeA !== timeB) return timeA - timeB;
          return a.period.localeCompare(b.period);
        });

        setRawSnapshots(filteredDocs);
        setSnapshots(sortedAggregated);
        setLoading(false);
      },
      (err) => {
        console.error('[usePortfolioMetricSnapshots] listener error:', err);
        setError(err);
        setLoading(false);
      }
    );

    return () => unsubscribe();
  }, [activeTenantId, periodType, projects, scope]);

  return { snapshots, rawSnapshots, loading, error };
}

import { useEffect } from 'react';
import { collection, query, where, onSnapshot } from 'firebase/firestore';
import { db } from '@/lib/firebase/config';
import { useAuth } from '@/context/AuthContext';
import { useTenant } from '@/context/TenantContext';
import { usePropertyStore } from '@/store/propertyStore';
import { PropertyAsset, FinancialTransaction } from '@/types/schema';

/* ═══════════════════════════════════════════════════════════════
   usePortfolioSync — Real-time Firestore Synchronization Hook

   Opens two parallel onSnapshot listeners, both scoped by
   organizationId, and pipes their data into the Zustand
   propertyStore. A user can never receive another tenant's data.

   Usage: call once at the top of any page that renders portfolio
   data. The underlying Firestore subscriptions are automatically
   cleaned up when the component unmounts.
   ═══════════════════════════════════════════════════════════════ */

export function usePortfolioSync() {
  const { profile } = useAuth();
  const { activeTenantId } = useTenant();
  const setProperties = usePropertyStore((s) => s.setProperties);
  const setTransactions = usePropertyStore((s) => s.setTransactions);
  const setIsLoading = usePropertyStore((s) => s.setIsLoading);
  const setError = usePropertyStore((s) => s.setError);

  useEffect(() => {
    const orgId = activeTenantId;

    // Guard: hold in loading state until the auth profile resolves with
    // a real org ID. 'org_placeholder' is the transient value written
    // during the onboarding window — never query Firestore against it.
    if (!orgId || orgId === 'org_placeholder') {
      return;
    }

    if (typeof window !== 'undefined' && window.location.pathname.startsWith('/demo')) {
      return;
    }

    setIsLoading(true);
    setError(null);

    let propertiesLoaded = false;
    let transactionsLoaded = false;

    // Helper: mark loading complete only after both listeners have
    // delivered their first snapshot.
    const checkBothLoaded = () => {
      if (propertiesLoaded && transactionsLoaded) {
        setIsLoading(false);
      }
    };

    // ── Listener 1: properties ──────────────────────────────────
    // SECURITY: where clause enforces strict tenant isolation.
    const propertiesQ = query(
      collection(db, 'properties'),
      where('organizationId', '==', orgId),
    );

    const unsubProperties = onSnapshot(
      propertiesQ,
      (snapshot) => {
        const docs = snapshot.docs.map((d) => {
          const data = d.data();
          return {
            ...data,
            id: d.id,
            // Coerce Firestore Timestamps → JS Date
            purchaseDate: data.purchaseDate?.toDate?.() ?? data.purchaseDate ?? new Date(),
            createdAt: data.createdAt?.toDate?.() ?? data.createdAt ?? new Date(),
            updatedAt: data.updatedAt?.toDate?.() ?? data.updatedAt ?? new Date(),
          } as PropertyAsset;
        });
        setProperties(docs);
        propertiesLoaded = true;
        checkBothLoaded();
      },
      (err) => {
        console.error('[usePortfolioSync] properties listener error:', err);
        setError(
          'Unable to load your portfolio properties. Please check your connection and try again.',
        );
        setIsLoading(false);
      },
    );

    // ── Listener 2: transactions ────────────────────────────────
    // SECURITY: same organizationId scope as above.
    const transactionsQ = query(
      collection(db, 'transactions'),
      where('organizationId', '==', orgId),
    );

    const unsubTransactions = onSnapshot(
      transactionsQ,
      (snapshot) => {
        const docs = snapshot.docs.map((d) => {
          const data = d.data();
          return {
            ...data,
            id: d.id,
            // Coerce Firestore Timestamp → JS Date
            date: data.date?.toDate?.() ?? data.date ?? new Date(),
          } as FinancialTransaction;
        });
        setTransactions(docs);
        transactionsLoaded = true;
        checkBothLoaded();
      },
      (err) => {
        console.error('[usePortfolioSync] transactions listener error:', err);
        setError(
          'Unable to load your financial transactions. Please check your connection and try again.',
        );
        setIsLoading(false);
      },
    );

    // Cleanup: unsubscribe both listeners on unmount or orgId change
    return () => {
      unsubProperties();
      unsubTransactions();
    };
  }, [
    activeTenantId,
    setProperties,
    setTransactions,
    setIsLoading,
    setError,
  ]);
}

'use client';

import { useMemo } from 'react';
import { WizardQuestion, getNestedField } from '@/lib/utils/projectWizardSchema';

export interface AddressFieldErrors {
  street?: string;
  city?: string;
  state?: string;
  zip?: string;
}

export function useProjectFormValidation(formData: any, activeQuestion: WizardQuestion) {
  // Address field validation
  const addressErrors: AddressFieldErrors = useMemo(() => {
    const errors: AddressFieldErrors = {};
    const street = formData.street || '';
    const city = formData.city || '';
    const state = formData.state || '';
    const zip = formData.zip || '';

    if (!street.trim()) errors.street = 'Street is required';
    if (!city.trim())   errors.city   = 'City is required';
    if (!state.trim())  errors.state  = 'State is required';
    if (!zip.trim())    errors.zip    = 'ZIP is required';
    return errors;
  }, [formData.street, formData.city, formData.state, formData.zip]);

  const isAddressComplete = Object.keys(addressErrors).length === 0;

  // Acquisition Date validation
  const acquisitionDateError: string | null = useMemo(() => {
    const dateVal = formData.financials?.acquisitionDate || formData.acquisitionDate;
    if (!dateVal) return null;

    const selected = new Date(dateVal + 'T00:00:00');
    if (isNaN(selected.getTime())) return 'Invalid date format.';

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selected > today) {
      return 'Project start date cannot be in the future.';
    }

    const oneYearAgo = new Date(today);
    oneYearAgo.setFullYear(oneYearAgo.getFullYear() - 1);

    if (selected < oneYearAgo) {
      return 'Date cannot be older than 1 year from today.';
    }

    return null;
  }, [formData.financials?.acquisitionDate, formData.acquisitionDate]);

  // General field validation for the active question
  const validationError: string | null = useMemo(() => {
    if (!activeQuestion) return null;

    const val = getNestedField(formData, activeQuestion.field);

    // Required check
    if (activeQuestion.required) {
      if (activeQuestion.id === 'address' || activeQuestion.id === 'location') {
        const addressValid = !!formData.mlsListingKey || isAddressComplete;
        if (!addressValid) return 'Please specify a valid property address.';
        if (activeQuestion.id === 'location' && !formData.assetClass) return 'Please select a structure type.';
      } else if (activeQuestion.type === 'phase-selection') {
        if (!formData.startingPhase) return 'Please select a phase.';
      } else if (activeQuestion.type === 'multi-select') {
        if (!Array.isArray(val) || val.length === 0) {
          return `${activeQuestion.prompt} is required.`;
        }
      } else if (val === undefined || val === null || val === '') {
        return `${activeQuestion.prompt} is required.`;
      }
    }

    // Type specific checks
    if (activeQuestion.type === 'currency' || activeQuestion.type === 'number') {
      if (val !== undefined && val !== null && val !== '') {
        const num = parseFloat(val);
        if (isNaN(num)) return 'Value must be a valid number.';
        if (num < 0) return 'Value cannot be negative.';
        if (activeQuestion.required && num <= 0) return 'Value must be greater than zero.';
      }
    }

    if (activeQuestion.id === 'acquisitionDate' && acquisitionDateError) {
      return acquisitionDateError;
    }

    if (activeQuestion.id === 'leadEmail' && val) {
      const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!emailRegex.test(String(val))) {
        return 'Please enter a valid email address.';
      }
    }

    return null;
  }, [activeQuestion, formData, isAddressComplete, acquisitionDateError]);

  const isValid = validationError === null;

  return {
    isValid,
    validationError,
    addressErrors,
    isAddressComplete,
    acquisitionDateError,
  };
}

