import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';

export interface User360Data {
  identity: {
    uid: string;
    email: string;
    displayName: string;
    emailVerified: boolean;
    disabled: boolean;
    role: string;
    accountType: string;
    createdAt: string;
    lastLoginAt: string;
    customClaims: Record<string, any>;
  };
  billing: {
    stripeCustomerId: string | null;
    subscriptionPlan: string;
    subscriptionStatus: string;
    mrr: number;
    nextBillingDate: string | null;
    paymentMethod: string | null;
  };
  plaidConnections: Array<{
    id: string;
    itemId: string;
    institutionName: string;
    accountMask: string | null;
    status: string;
    syncErrorCount: number;
    lastSyncErrorMessage: string | null;
    createdAt: string;
    updatedAt: string;
  }>;
  organizations: Array<{
    organizationId: string;
    projectId: string;
    projectDisplayName: string;
    role: string;
    invitedAt: string;
    acceptedAt: string | null;
  }>;
  activityTimeline: Array<{
    id: string;
    action: string;
    details: string;
    timestamp: string;
    severity: string;
    source: 'audit_log' | 'gate_event';
  }>;
}

/**
 * User 360 Data Federation Engine (Amendment B & D)
 * Real-time read-only federation from Firebase Auth, Firestore, Prisma PostgreSQL, and Plaid connections.
 */
export async function fetchUser360Data(targetUid: string): Promise<User360Data | null> {
  try {
    // 1. Firebase Auth user object
    let authUser: any = null;
    try {
      authUser = await adminAuth.getUser(targetUid);
    } catch {
      // Fallback if not found in Firebase Auth directly
    }

    // 2. Firestore profile document
    const userDoc = await adminDb.collection('users').doc(targetUid).get();
    const userData = userDoc.exists ? userDoc.data() : {};

    const email = authUser?.email || userData?.email || '';
    const displayName = userData?.displayName || userData?.name || authUser?.displayName || email.split('@')[0] || 'Unknown';
    const role = userData?.role || userData?.profile?.role || (authUser?.customClaims?.role as string) || 'investor';
    const accountType = userData?.accountType || 'investor';
    const disabled = authUser?.disabled || false;
    const emailVerified = authUser?.emailVerified || false;

    // Dates
    const createdAt = authUser?.metadata?.creationTime
      ? new Date(authUser.metadata.creationTime).toISOString()
      : userData?.createdAt?.toDate
      ? userData.createdAt.toDate().toISOString()
      : new Date().toISOString();

    const lastLoginAt = authUser?.metadata?.lastSignInTime
      ? new Date(authUser.metadata.lastSignInTime).toISOString()
      : userData?.lastLoginAt?.toDate
      ? userData.lastLoginAt.toDate().toISOString()
      : createdAt;

    // 3. Billing details (read from Firestore profile per Amendment B)
    const stripeCustomerId = userData?.stripeCustomerId || null;
    const subscriptionPlan = userData?.subscriptionPlan || 'Individual';
    const subscriptionStatus = userData?.subscriptionStatus || 'inactive';

    // 4. Plaid Connections from Prisma
    let plaidConnections: User360Data['plaidConnections'] = [];
    try {
      if (prisma && prisma.plaidConnection) {
        const conns = await prisma.plaidConnection.findMany({
          where: { userId: targetUid },
          orderBy: { createdAt: 'desc' },
        });

        plaidConnections = conns.map((c) => ({
          id: c.id,
          itemId: c.itemId,
          institutionName: c.institutionName || 'Bank Account',
          accountMask: c.accountMask || null,
          status: c.status,
          syncErrorCount: c.syncErrorCount,
          lastSyncErrorMessage: c.lastSyncErrorMessage || null,
          createdAt: c.createdAt.toISOString(),
          updatedAt: c.updatedAt.toISOString(),
        }));
      }
    } catch {
      // Fallback
    }

    // 5. Organizations & Collaborations from Prisma ProjectCollaborator (Amendment D)
    let organizations: User360Data['organizations'] = [];
    try {
      if (prisma && prisma.projectCollaborator) {
        const collabs = await prisma.projectCollaborator.findMany({
          where: { userId: targetUid },
          include: { project: true },
          orderBy: { invitedAt: 'desc' },
        });

        organizations = collabs.map((c) => ({
          organizationId: (c.project as any)?.entityName || (c.project as any)?.createdById || `org_${c.projectId}`,
          projectId: c.projectId,
          projectDisplayName: c.project?.displayName || c.project?.addressLine || 'Property Project',
          role: c.role,
          invitedAt: c.invitedAt.toISOString(),
          acceptedAt: c.acceptedAt ? c.acceptedAt.toISOString() : null,
        }));
      }
    } catch {
      // Fallback
    }

    // 6. Federated Activity Timeline (PostgreSQL AdminAuditLog + Firestore gate_events)
    const activityTimeline: User360Data['activityTimeline'] = [];

    // Audit logs from Postgres
    try {
      if (prisma && prisma.adminAuditLog) {
        const auditLogs = await prisma.adminAuditLog.findMany({
          where: { actorUid: targetUid },
          orderBy: { timestamp: 'desc' },
          take: 50,
        });

        auditLogs.forEach((l) => {
          activityTimeline.push({
            id: l.id,
            action: l.action,
            details: l.reasonCode ? `Reason: ${l.reasonCode}` : (l.metadata ? JSON.stringify(l.metadata) : 'Executed successfully'),
            timestamp: l.timestamp.toISOString(),
            severity: l.severity,
            source: 'audit_log',
          });
        });
      }
    } catch {
      // Fallback
    }

    // Gate events from Firestore
    try {
      const gateSnap = await adminDb
        .collection('gate_events')
        .where('userUid', '==', targetUid)
        .orderBy('timestamp', 'desc')
        .limit(20)
        .get();

      gateSnap.docs.forEach((doc) => {
        const d = doc.data();
        const ts = d.timestamp?.toDate ? d.timestamp.toDate().toISOString() : new Date().toISOString();
        activityTimeline.push({
          id: doc.id,
          action: d.eventType || 'gate_transition',
          details: d.notes || d.fromPhase ? `${d.fromPhase} -> ${d.toPhase}` : 'Gate phase updated',
          timestamp: ts,
          severity: 'info',
          source: 'gate_event',
        });
      });
    } catch {
      // Gate events fallback
    }

    // Sort federated timeline descending
    activityTimeline.sort((a, b) => (b.timestamp > a.timestamp ? 1 : -1));

    return {
      identity: {
        uid: targetUid,
        email,
        displayName,
        emailVerified,
        disabled,
        role,
        accountType,
        createdAt,
        lastLoginAt,
        customClaims: authUser?.customClaims || {},
      },
      billing: {
        stripeCustomerId,
        subscriptionPlan,
        subscriptionStatus,
        mrr: subscriptionPlan === 'Team' ? 120 : subscriptionPlan === 'Vendor Network' ? 250 : 0,
        nextBillingDate: null,
        paymentMethod: null,
      },
      plaidConnections,
      organizations,
      activityTimeline,
    };
  } catch (error) {
    console.error('[fetchUser360Data] Failed:', error);
    return null;
  }
}

import crypto from 'crypto';
import { adminAuth, adminDb } from '@/lib/firebase/admin';
import { logAdminAudit } from '@/lib/audit/auditLogger';
import { getEmailProvider } from '@/lib/email/getEmailProvider';

export type SensitiveActionType = 'EMAIL_CHANGE' | 'PASSWORD_RESET' | 'MFA_RESET';

export interface InitiationResult {
  success: boolean;
  verificationId?: string;
  expiresAt?: string;
  error?: string;
}

export interface ConfirmationResult {
  success: boolean;
  message?: string;
  error?: string;
}

/**
 * Initiates verification-before-change gate for sensitive admin actions (Amendment E).
 * Generates a 6-digit OTP code, stores it with a 15-minute TTL, and emails the user via SendGrid.
 */
export async function initiateSensitiveActionVerification(params: {
  targetUid: string;
  actionType: SensitiveActionType;
  adminUid: string;
  adminEmail: string;
  newEmail?: string;
  ipAddress?: string;
  userAgent?: string;
}): Promise<InitiationResult> {
  try {
    // Fetch target user email
    let targetEmail = '';
    try {
      const userRecord = await adminAuth.getUser(params.targetUid);
      targetEmail = userRecord.email || '';
    } catch {
      const doc = await adminDb.collection('users').doc(params.targetUid).get();
      targetEmail = doc.data()?.email || '';
    }

    if (!targetEmail) {
      return { success: false, error: 'Target user email not found' };
    }

    // Generate 6-digit code
    const code = Math.floor(100000 + Math.random() * 900000).toString();
    const expiresAt = new Date(Date.now() + 15 * 60 * 1000); // 15 min
    const verificationId = crypto.randomUUID();

    // Store verification code in Firestore
    await adminDb.collection('verification_codes').doc(verificationId).set({
      verificationId,
      targetUid: params.targetUid,
      targetEmail,
      actionType: params.actionType,
      code,
      newEmail: params.newEmail || null,
      adminUid: params.adminUid,
      createdAt: new Date(),
      expiresAt,
      used: false,
    });

    // Send code via SendGrid System Email Adapter (E-1, E-3)
    const emailProvider = getEmailProvider();
    const actionName =
      params.actionType === 'EMAIL_CHANGE'
        ? 'Email Address Change'
        : params.actionType === 'PASSWORD_RESET'
        ? 'Password Reset'
        : 'MFA Reset';

    await emailProvider.sendEmail({
      from: 'security@mail.paperworking.co',
      to: [targetEmail],
      subject: `Security Verification Code: ${actionName}`,
      templateKey: 'ACCT-SECURITY-OTP',
      messageClass: 'E',
      text: `An administrative action (${actionName}) was requested for your PaperWorking account.\n\nYour 6-digit verification code is: ${code}\n\nThis code expires in 15 minutes. If you did not request this, please contact hi@paperworking.co immediately.`,
      html: `
        <div style="font-family: sans-serif; max-width: 500px; padding: 24px; border: 1px solid #e5e5e5; border-radius: 8px;">
          <h2 style="color: #0d0d0d; margin-top: 0;">Security Verification Request</h2>
          <p style="color: #454955; font-size: 14px;">An administrative action <strong>(${actionName})</strong> was requested for your PaperWorking account.</p>
          <p style="color: #454955; font-size: 14px;">To authorize this change, provide the following 6-digit verification code to your administrator:</p>
          <div style="background: #f4f4f5; padding: 16px; text-align: center; border-radius: 6px; margin: 20px 0;">
            <span style="font-family: monospace; font-size: 28px; font-weight: bold; letter-spacing: 4px; color: #0d0d0d;">${code}</span>
          </div>
          <p style="color: #888; font-size: 12px;">This code will expire in 15 minutes. If you did not request this, please contact PaperWorking Security immediately.</p>
        </div>
      `,
    });

    // Log initiation to audit log
    await logAdminAudit({
      actorUid: params.adminUid,
      actorEmail: params.adminEmail,
      actorRole: 'Platform Admin',
      action: `admin:initiate_${params.actionType.toLowerCase()}`,
      targetResource: 'users',
      targetResourceId: params.targetUid,
      status: 'SUCCESS',
      ipAddress: params.ipAddress || '127.0.0.1',
      userAgent: params.userAgent,
      severity: 'warning',
      metadata: {
        verificationId,
        actionType: params.actionType,
        targetEmail,
        newEmail: params.newEmail || null,
        expiresAt: expiresAt.toISOString(),
      },
    });

    return {
      success: true,
      verificationId,
      expiresAt: expiresAt.toISOString(),
    };
  } catch (error: any) {
    console.error('[initiateSensitiveActionVerification] Failed:', error);
    return { success: false, error: error?.message || 'Initiation failed' };
  }
}

/**
 * Confirms verification code and executes sensitive account mutation (Amendment E).
 */
export async function confirmSensitiveActionVerification(params: {
  verificationId: string;
  code: string;
  adminUid: string;
  adminEmail: string;
  ipAddress?: string;
  userAgent?: string;
}): Promise<ConfirmationResult> {
  try {
    const codeRef = adminDb.collection('verification_codes').doc(params.verificationId);
    const codeSnap = await codeRef.get();

    if (!codeSnap.exists) {
      return { success: false, error: 'Verification session not found' };
    }

    const data = codeSnap.data();
    if (!data || data.used) {
      return { success: false, error: 'Verification code has already been used' };
    }

    const expiresAt = data.expiresAt?.toDate ? data.expiresAt.toDate() : new Date(data.expiresAt);
    if (new Date() > expiresAt) {
      return { success: false, error: 'Verification code has expired (15-min limit exceeded)' };
    }

    if (data.code !== params.code.trim()) {
      return { success: false, error: 'Invalid verification code' };
    }

    const targetUid = data.targetUid;
    const actionType: SensitiveActionType = data.actionType;

    // Execute requested mutation
    if (actionType === 'EMAIL_CHANGE') {
      if (!data.newEmail) return { success: false, error: 'New email address missing' };
      await adminAuth.updateUser(targetUid, { email: data.newEmail, emailVerified: false });
      await adminDb.collection('users').doc(targetUid).set({ email: data.newEmail, updatedAt: new Date() }, { merge: true });
    } else if (actionType === 'PASSWORD_RESET') {
      const resetLink = await adminAuth.generatePasswordResetLink(data.targetEmail);
      const emailProvider = getEmailProvider();
      await emailProvider.sendEmail({
        from: 'security@mail.paperworking.co',
        to: [data.targetEmail],
        subject: 'Reset your PaperWorking password',
        templateKey: 'ACCT-PASSWORD-RESET',
        messageClass: 'E',
        text: `Use the link below to set a new password. It expires in 60 minutes and can be used once.\n\n${resetLink}\n\nIf you didn't request this, no action is needed and your password is unchanged.`,
        html: `<p>Use the link below to set a new password. It expires in 60 minutes and can be used once.</p><p><a href="${resetLink}">Reset password</a></p><p style="color:#888;font-size:12px;">If you didn't request this, no action is needed and your password is unchanged.</p>`,
      });
    } else if (actionType === 'MFA_RESET') {
      await adminAuth.revokeRefreshTokens(targetUid);
      await adminDb.collection('users').doc(targetUid).set({ mfaEnabled: false, updatedAt: new Date() }, { merge: true });
    }

    // Mark code as used
    await codeRef.update({ used: true, confirmedAt: new Date() });

    // Log execution to audit log
    await logAdminAudit({
      actorUid: params.adminUid,
      actorEmail: params.adminEmail,
      actorRole: 'Platform Admin',
      action: `admin:confirm_${actionType.toLowerCase()}`,
      targetResource: 'users',
      targetResourceId: targetUid,
      status: 'SUCCESS',
      ipAddress: params.ipAddress || '127.0.0.1',
      userAgent: params.userAgent,
      severity: 'critical',
      metadata: {
        verificationId: params.verificationId,
        actionType,
        targetUid,
        newEmail: data.newEmail || null,
      },
    });

    return {
      success: true,
      message: `Action ${actionType} successfully verified and executed.`,
    };
  } catch (error: any) {
    console.error('[confirmSensitiveActionVerification] Failed:', error);
    return { success: false, error: error?.message || 'Confirmation failed' };
  }
}

