export function getBankingProvider(): BankingProvider {
  const providerType = process.env.BANKING_PROVIDER || 'mock';
  if (providerType === 'plaid') {
    // Dynamic import/require to prevent bundling server Plaid Node SDK on client components
    const { PlaidProvider } = require('./plaid-provider');
    return new PlaidProvider();
  }
  return new MockBankingProvider();
}

import { Configuration, PlaidApi, PlaidEnvironments, Products, CountryCode } from 'plaid';
import { BankingProvider, AccountBalance, BankingTransactionsResponse, BankingTransaction, MortgageLiability } from './index';

export class PlaidProvider implements BankingProvider {
  private plaidClient: PlaidApi;

  constructor() {
    const clientId = process.env.PLAID_CLIENT_ID;
    const secret = process.env.PLAID_SECRET;
    const env = process.env.PLAID_ENV || 'sandbox';

    if (!clientId || !secret) {
      throw new Error('PLAID_CLIENT_ID and PLAID_SECRET are required for Plaid provider');
    }

    // Resolve plaid env
    const basePath = PlaidEnvironments[env];
    if (!basePath) {
      throw new Error(`Invalid PLAID_ENV: ${env}`);
    }

    const configuration = new Configuration({
      basePath,
      baseOptions: {
        headers: {
          'PLAID-CLIENT-ID': clientId,
          'PLAID-SECRET': secret,
        },
      },
    });

    this.plaidClient = new PlaidApi(configuration);
  }

  async createLinkToken(userId: string): Promise<string> {
    try {
      // Determine which products to request based on env flag
      const liabilitiesEnabled = process.env.PLAID_LIABILITIES_ENABLED !== 'false';
      const products: Products[] = [Products.Auth, Products.Transactions];
      if (liabilitiesEnabled) {
        products.push(Products.Liabilities);
      }

      const response = await this.plaidClient.linkTokenCreate({
        user: { client_user_id: userId },
        client_name: 'PaperWorking',
        products,
        country_codes: [CountryCode.Us],
        language: 'en',
        // Note: 'use_case' / DTM footer is configured in the Plaid Dashboard,
        // not in the link token request for most Plaid plans.
      });
      return response.data.link_token;
    } catch (error: any) {
      console.error('[PlaidProvider] Failed to create link token:', error.response?.data ?? error.message);
      throw new Error(`Failed to create Plaid link token: ${error.response?.data?.error_message ?? error.message}`);
    }
  }

  async exchangePublicToken(userId: string, publicToken: string): Promise<{ accessToken: string; itemId: string }> {
    try {
      const response = await this.plaidClient.itemPublicTokenExchange({
        public_token: publicToken,
      });
      return {
        accessToken: response.data.access_token,
        itemId: response.data.item_id,
      };
    } catch (error: any) {
      console.error('[PlaidProvider] Failed to exchange public token:', error.response?.data ?? error.message);
      throw new Error(`Failed to exchange Plaid public token: ${error.response?.data?.error_message ?? error.message}`);
    }
  }

  async getAccountBalance(accessToken: string, accountId?: string): Promise<AccountBalance> {
    try {
      const response = await this.plaidClient.accountsBalanceGet({
        access_token: accessToken,
      });

      const accounts = response.data.accounts;
      if (!accounts || accounts.length === 0) {
        throw new Error('No accounts found for Plaid connection');
      }

      // Select matching account or default to first depository, then fallback to first account
      const matchedAccount = accountId
        ? accounts.find((acc) => acc.account_id === accountId)
        : accounts.find((acc) => acc.type === 'depository') || accounts[0];

      if (!matchedAccount) {
        throw new Error(`Account matching ${accountId || 'depository'} not found`);
      }

      const currentBalance = matchedAccount.balances.current ?? 0;
      const balanceInCents = Math.round(currentBalance * 100);
      const name = `${matchedAccount.name} (*${matchedAccount.mask || '0000'})`;

      return {
        accountName: name,
        balance: balanceInCents,
        lastUpdated: new Date().toISOString(),
      };
    } catch (error: any) {
      console.error('[PlaidProvider] Failed to fetch account balance:', error.response?.data ?? error.message);
      throw new Error(`Failed to fetch Plaid balance: ${error.response?.data?.error_message ?? error.message}`);
    }
  }

  async getTransactions(params: {
    accessToken: string;
    startDate: string;
    endDate: string;
    cursor?: string;
  }): Promise<BankingTransactionsResponse> {
    try {
      const response = await this.plaidClient.transactionsSync({
        access_token: params.accessToken,
        cursor: params.cursor,
      });

      const data = response.data;
      const added = (data.added || []).map((t) => ({
        plaidId: t.transaction_id,
        accountId: t.account_id,
        amount: Math.round(t.amount * 100), // convert to cents
        date: new Date(t.date),
        name: t.name,
        category: t.category || [],
        merchantName: t.merchant_name || null,
        pending: t.pending,
      }));

      const modified = (data.modified || []).map((t) => ({
        plaidId: t.transaction_id,
        accountId: t.account_id,
        amount: Math.round(t.amount * 100),
        date: new Date(t.date),
        name: t.name,
        category: t.category || [],
        merchantName: t.merchant_name || null,
        pending: t.pending,
      }));

      const removed = (data.removed || []).map((t) => t.transaction_id).filter(Boolean) as string[];

      return {
        added,
        modified,
        removed,
        nextCursor: data.next_cursor,
        hasMore: data.has_more,
      };
    } catch (error: any) {
      console.error('[PlaidProvider] Failed to sync transactions:', error.response?.data ?? error.message);
      throw new Error(`Failed to sync Plaid transactions: ${error.response?.data?.error_message ?? error.message}`);
    }
  }

  /**
   * Fetches mortgage liability data for all loan accounts linked to this Item.
   * Requires Products.Liabilities to be included in the link token.
   * Silently returns [] if the item has no mortgage accounts.
   */
  async getLiabilities(accessToken: string): Promise<MortgageLiability[]> {
    try {
      const response = await this.plaidClient.liabilitiesGet({
        access_token: accessToken,
      });

      const mortgages = response.data.liabilities.mortgage || [];

      return mortgages.map((m: any) => ({
        accountId: m.account_id,
        // Plaid SDK field name varies by version: lender_name or originator_name
        lender: (m.lender_name ?? m.originator_name) ?? null,
        balance: Math.round(((m.outstanding_principal_balance ?? m.current_loan_amount) ?? 0) * 100),
        originalBalance: (m.origination_principal_amount ?? m.original_principal_balance) != null
          ? Math.round((m.origination_principal_amount ?? m.original_principal_balance) * 100)
          : null,
        interestRatePct: m.interest_rate?.percentage ?? null,
        apr: m.apr_percentage ?? m.interest_rate?.percentage ?? null,
        nextPaymentDueDate: m.next_payment_due_date ?? null,
        nextPaymentAmount: m.next_monthly_payment != null
          ? Math.round(m.next_monthly_payment * 100)
          : null,
        ytdInterestPaid: m.ytd_interest_paid != null
          ? Math.round(m.ytd_interest_paid * 100)
          : null,
        escrowBalance: m.escrow_balance != null
          ? Math.round(m.escrow_balance * 100)
          : null,
        lastPaymentAmount: m.last_payment_amount != null
          ? Math.round(m.last_payment_amount * 100)
          : null,
        lastPaymentDate: m.last_payment_date ?? null,
      }));
    } catch (error: any) {
      // PRODUCT_NOT_READY or PRODUCTS_NOT_SUPPORTED are non-fatal — item has no mortgages
      const code = error.response?.data?.error_code ?? '';
      if (
        code === 'PRODUCT_NOT_READY' ||
        code === 'PRODUCTS_NOT_SUPPORTED' ||
        code === 'NO_LIABILITY_ACCOUNTS'
      ) {
        return [];
      }
      console.error('[PlaidProvider] Failed to fetch liabilities:', error.response?.data ?? error.message);
      throw new Error(`Failed to fetch Plaid liabilities: ${error.response?.data?.error_message ?? error.message}`);
    }
  }
}

import {
  FinancialTransactionCategory,
  FinancialTransactionDirection,
  FinancialTransactionSource,
  FinancialTransactionStatus,
  Prisma,
} from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { KpiAutoReporter } from '@/lib/analytics/kpiAutoReporter';

export interface ConditionRule {
  field:
    | 'AMOUNT'
    | 'PAYEE_NAME'
    | 'DESCRIPTION'
    | 'MERCHANT_NAME'
    | 'ACCOUNT_ID'
    | 'DATE_RANGE'
    | 'DAY_OF_MONTH'
    | 'TRANSACTION_TYPE'
    | 'PLAID_PERSONAL_FINANCE_CATEGORY'
    | 'PLAID_COUNTERPARTY_NAME';
  operator:
    | 'EQUALS'
    | 'NOT_EQUALS'
    | 'CONTAINS'
    | 'STARTS_WITH'
    | 'ENDS_WITH'
    | 'GREATER_THAN'
    | 'LESS_THAN'
    | 'RANGE'
    | 'NEAR_DAY_OF_MONTH'
    | 'REGEX';
  value: any;
}

export interface RuleActionConfig {
  category: FinancialTransactionCategory;
  subCategory?: string;
  autoApprove: boolean;
  assignToLeaseId?: string;
  taxTreatment?: string;
}

export interface RuleMatch {
  ruleId: string;
  category: FinancialTransactionCategory;
  subCategory?: string;
  autoApprove: boolean;
  assignToLeaseId?: string;
  taxTreatment?: string;
}

export interface SmartSuggestion {
  suggestedRuleName: string;
  ruleType: string;
  conditions: ConditionRule[];
  action: RuleActionConfig;
  historicalMatchCount: number;
  explanation: string;
}

export class RulesEngine {
  /**
   * Evaluates a single condition against a transaction across all 10 fields and operators.
   */
  static evaluateCondition(cond: ConditionRule, tx: any): boolean {
    const { field, operator, value } = cond;

    switch (field) {
      case 'PAYEE_NAME': {
        const valStr = String(value || '').toLowerCase();
        const payeeStr = (tx.payee || '').toLowerCase();
        if (operator === 'EQUALS') return payeeStr === valStr;
        if (operator === 'CONTAINS') return payeeStr.includes(valStr);
        if (operator === 'STARTS_WITH') return payeeStr.startsWith(valStr);
        if (operator === 'ENDS_WITH') return payeeStr.endsWith(valStr);
        if (operator === 'REGEX') {
          try {
            return new RegExp(String(value), 'i').test(payeeStr);
          } catch {
            return false;
          }
        }
        return false;
      }

      case 'DESCRIPTION': {
        const valStr = String(value || '').toLowerCase();
        const descStr = (tx.description || tx.payee || '').toLowerCase();
        if (operator === 'CONTAINS') return descStr.includes(valStr);
        if (operator === 'EQUALS') return descStr === valStr;
        return false;
      }

      case 'MERCHANT_NAME': {
        const valStr = String(value || '').toLowerCase();
        const merchStr = (tx.merchantName || tx.payee || '').toLowerCase();
        if (operator === 'CONTAINS') return merchStr.includes(valStr);
        if (operator === 'EQUALS') return merchStr === valStr;
        return false;
      }

      case 'ACCOUNT_ID': {
        const valStr = String(value || '');
        const accId = String(tx.plaidAccountId || tx.accountId || '');
        return accId === valStr;
      }

      case 'AMOUNT': {
        const numVal = Number(value);
        const txAmt = Math.abs(Number(tx.amount));
        if (operator === 'EQUALS') return Math.abs(txAmt - numVal) <= 0.05;
        if (operator === 'GREATER_THAN') return txAmt > numVal;
        if (operator === 'LESS_THAN') return txAmt < numVal;
        if (operator === 'RANGE') {
          const [min, max] = Array.isArray(value) ? value.map(Number) : [0, 0];
          return txAmt >= min && txAmt <= max;
        }
        return false;
      }

      case 'DATE_RANGE': {
        const [start, end] = Array.isArray(value) ? value.map((v) => new Date(v)) : [new Date(0), new Date()];
        const txDate = new Date(tx.transactionDate || tx.date);
        return txDate >= start && txDate <= end;
      }

      case 'DAY_OF_MONTH': {
        const targetDay = Number(value) || 1;
        const txDay = new Date(tx.transactionDate || tx.date).getDate();
        if (operator === 'EQUALS') return txDay === targetDay;
        const diff = Math.abs(txDay - targetDay);
        return diff <= 2 || diff >= 28; // ±2 days
      }

      case 'TRANSACTION_TYPE': {
        const targetDir = String(value).toUpperCase();
        const txDir = String(tx.direction).toUpperCase();
        return txDir === targetDir;
      }

      case 'PLAID_PERSONAL_FINANCE_CATEGORY': {
        const valStr = String(value || '').toUpperCase();
        const pfc = JSON.stringify(tx.plaidPersonalFinanceCategory || '').toUpperCase();
        return pfc.includes(valStr);
      }

      case 'PLAID_COUNTERPARTY_NAME': {
        const valStr = String(value || '').toLowerCase();
        const counterparty = (tx.plaidCounterpartyName || tx.payee || '').toLowerCase();
        if (operator === 'CONTAINS') return counterparty.includes(valStr);
        if (operator === 'EQUALS') return counterparty === valStr;
        return false;
      }

      default:
        return false;
    }
  }

  /**
   * Evaluates a transaction against active project rules ordered by priority ASC.
   * First matching rule wins.
   */
  static async evaluate(tx: any, projectId: string): Promise<RuleMatch | null> {
    const rules = await prisma.transactionRule.findMany({
      where: { projectId, isActive: true },
      orderBy: [{ priority: 'asc' }, { createdAt: 'desc' }],
    });

    for (const rule of rules) {
      const conditions = (rule.conditions as unknown as ConditionRule[]) ?? [];
      const action = (rule.action as unknown as RuleActionConfig) ?? {};

      const matches = conditions.every((cond) => this.evaluateCondition(cond, tx));
      if (matches) {
        return {
          ruleId: rule.id,
          category: action.category ?? (rule.action as any)?.category,
          subCategory: action.subCategory,
          autoApprove: action.autoApprove ?? false,
          assignToLeaseId: action.assignToLeaseId,
          taxTreatment: action.taxTreatment,
        };
      }
    }

    return null;
  }

  /**
   * Generates a pre-populated rule from an approved transaction.
   * autoApprove defaults to false until 3 manual confirmations.
   */
  static async createRuleFromTransaction(transactionId: string, userId: string): Promise<any> {
    const tx = await prisma.financialTransaction.findUnique({
      where: { id: transactionId },
    });

    if (!tx) throw new Error(`Transaction ${transactionId} not found`);

    const amt = Math.abs(Number(tx.amount));
    const isRent = tx.category === 'RENT_INCOME';

    const conditions: ConditionRule[] = [
      { field: 'PAYEE_NAME', operator: 'CONTAINS', value: tx.payee },
      { field: 'AMOUNT', operator: 'RANGE', value: [Math.max(0, amt - 5), amt + 5] },
    ];

    if (isRent) {
      const day = new Date(tx.transactionDate).getDate();
      conditions.push({ field: 'DAY_OF_MONTH', operator: 'NEAR_DAY_OF_MONTH', value: day });
    }

    if (tx.plaidPersonalFinanceCategory) {
      conditions.push({
        field: 'PLAID_PERSONAL_FINANCE_CATEGORY',
        operator: 'CONTAINS',
        value: (tx.plaidPersonalFinanceCategory as any).detailed || 'RENT',
      });
    }

    const action: RuleActionConfig = {
      category: tx.category,
      autoApprove: false, // User must explicitly enable after 3 confirmations
      assignToLeaseId: tx.matchedLeaseId || undefined,
    };

    return prisma.transactionRule.create({
      data: {
        userId,
        projectId: tx.projectId,
        name: `Auto-categorize ${tx.payee}`,
        ruleType: 'PLAID_AUTO_CATEGORIZE',
        priority: 100,
        conditions: conditions as any,
        action: action as any,
      },
    });
  }

  /**
   * Applies a specific rule to all PENDING_REVIEW transactions in the project.
   */
  static async applyRule(ruleId: string): Promise<{ affectedCount: number; autoApprovedCount: number }> {
    const rule = await prisma.transactionRule.findUnique({
      where: { id: ruleId },
    });

    if (!rule || !rule.isActive) {
      throw new Error(`Rule ${ruleId} not found or inactive`);
    }

    const conditions = (rule.conditions as unknown as ConditionRule[]) ?? [];
    const action = (rule.action as unknown as RuleActionConfig) ?? {};

    const pending = await prisma.financialTransaction.findMany({
      where: { projectId: rule.projectId, status: 'PENDING_REVIEW' },
    });

    let affectedCount = 0;
    let autoApprovedCount = 0;

    for (const tx of pending) {
      const matches = conditions.every((cond) => this.evaluateCondition(cond, tx));

      if (matches) {
        affectedCount++;
        const shouldAutoApprove = action.autoApprove ?? false;
        const newStatus: FinancialTransactionStatus = shouldAutoApprove
          ? 'AUTO_APPROVED'
          : 'MANUALLY_APPROVED';

        await prisma.financialTransaction.update({
          where: { id: tx.id },
          data: {
            category: action.category || tx.category,
            status: newStatus,
            recurringRuleId: rule.id,
            matchedLeaseId: action.assignToLeaseId || tx.matchedLeaseId,
            updatedAt: new Date(),
          },
        });

        if (shouldAutoApprove) {
          autoApprovedCount++;
          await KpiAutoReporter.processApprovedTransaction(tx.id);
        }
      }
    }

    await prisma.transactionRule.update({
      where: { id: ruleId },
      data: {
        matchCount: { increment: affectedCount },
        lastMatchedAt: new Date(),
      },
    });

    return { affectedCount, autoApprovedCount };
  }

  /**
   * Analyzes historical transactions in a project to generate smart rule suggestions (3+ pattern occurrences).
   */
  static async getSmartSuggestions(projectId: string): Promise<SmartSuggestion[]> {
    const ninetyDaysAgo = new Date();
    ninetyDaysAgo.setDate(ninetyDaysAgo.getDate() - 90);

    const approved = await prisma.financialTransaction.findMany({
      where: {
        projectId,
        status: { in: ['AUTO_APPROVED', 'MANUALLY_APPROVED'] },
        transactionDate: { gte: ninetyDaysAgo },
      },
    });

    const payeeGroups: Record<string, typeof approved> = {};
    for (const t of approved) {
      const key = t.payee.trim().toLowerCase();
      if (!key) continue;
      if (!payeeGroups[key]) payeeGroups[key] = [];
      payeeGroups[key].push(t);
    }

    const suggestions: SmartSuggestion[] = [];

    for (const [, group] of Object.entries(payeeGroups)) {
      if (group.length >= 3) {
        const sample = group[0];
        const amt = Math.abs(Number(sample.amount));
        const isRent = sample.category === 'RENT_INCOME';

        const conds: ConditionRule[] = [
          { field: 'PAYEE_NAME', operator: 'CONTAINS', value: sample.payee },
          { field: 'AMOUNT', operator: 'RANGE', value: [Math.max(0, amt - 10), amt + 10] },
        ];

        suggestions.push({
          suggestedRuleName: `Auto-approve ${sample.payee}`,
          ruleType: isRent ? 'REVENUE_RULE' : 'EXPENSE_RULE',
          conditions: conds,
          action: {
            category: sample.category,
            autoApprove: true,
          },
          historicalMatchCount: group.length,
          explanation: `Appeared ${group.length} times in the last 90 days with consistent amount ~$${amt}. Would have matched ${group.length} transactions last month.`,
        });
      }
    }

    return suggestions;
  }
}

import {
  FinancialTransactionCategory,
  FinancialTransactionDirection,
  Prisma,
} from '@prisma/client';
import { prisma } from '@/lib/prisma';

export type PrimaryClassification =
  | 'REVENUE'
  | 'EXPENSE'
  | 'LIABILITY_PAYMENT'
  | 'TRANSFER'
  | 'UNCERTAIN';

export interface SplitSuggestionItem {
  amount: number; // in dollars
  category: FinancialTransactionCategory;
  reason: string;
}

export interface IdentificationResult {
  primaryClassification: PrimaryClassification;
  paperWorkingCategory: FinancialTransactionCategory;
  confidenceScore: number; // 0.0 to 1.0
  reasoning: string[]; // human-readable explanation
  suggestedLeaseId?: string;
  isRecurring: boolean;
  isSplitSuggested: boolean;
  splitSuggestion?: SplitSuggestionItem[];
}

export interface LeaseContext {
  id: string;
  tenantName: string;
  monthlyRent: number; // in dollars
  rentDueDay: number; // 1-31
  securityDeposit?: number; // in dollars
  startDate?: Date;
  endDate?: Date;
}

export interface MortgageContext {
  id: string;
  lender?: string | null;
  balance: number; // in dollars
  nextPaymentAmount?: number | null; // in dollars
  interestRatePct?: number | null;
  escrowBalance?: number | null;
}

export interface RawTransactionInput {
  name: string;
  amount: number | Prisma.Decimal;
  category?: string[];
  personalFinanceCategory?: { primary?: string; detailed?: string } | null;
  postedDate?: Date | null;
  merchantName?: string | null;
  direction?: FinancialTransactionDirection;
  paymentChannel?: string | null;
}

export class TransactionIdentificationEngine {
  /**
   * Identifies and classifies a Plaid transaction into PaperWorking's
   * investment accounting framework.
   */
  static async identify(
    transaction: RawTransactionInput,
    projectId?: string,
    contextOverride?: { leases?: LeaseContext[]; mortgage?: MortgageContext }
  ): Promise<IdentificationResult> {
    const reasoning: string[] = [];
    let primary: PrimaryClassification = 'UNCERTAIN';
    let category: FinancialTransactionCategory = FinancialTransactionCategory.UNCATEGORIZED;
    let confidence = 0.3;
    let suggestedLeaseId: string | undefined;
    let isRecurring = false;
    let isSplitSuggested = false;
    let splitSuggestion: SplitSuggestionItem[] | undefined;

    const rawAmt = typeof transaction.amount === 'number' ? transaction.amount : Number(transaction.amount);
    const amountDollar = Math.abs(rawAmt);
    const isCredit = transaction.direction === 'CREDIT' || rawAmt < 0;
    const name = transaction.name || '';
    const merchantName = transaction.merchantName || '';
    const fullName = `${name} ${merchantName}`.toLowerCase();
    const pfc = transaction.personalFinanceCategory || {};

    let leases = contextOverride?.leases ?? [];
    let mortgage = contextOverride?.mortgage;

    // Load active leases context from existing transactions if not overridden
    if (projectId && (!contextOverride || !contextOverride.leases)) {
      try {
        const pastRent = await prisma.financialTransaction.findFirst({
          where: { projectId, category: 'RENT_INCOME' },
          select: { amount: true, payee: true },
        });
        if (pastRent) {
          leases.push({
            id: `lease_${projectId}_historical`,
            tenantName: pastRent.payee || 'Tenant',
            monthlyRent: Number(pastRent.amount),
            rentDueDay: 1,
          });
        }
      } catch {
        /* fallback to in-memory context */
      }
    }

    // ── STEP 1: Plaid AI Category Mapping ──────────────────────────────────────
    const primaryPfc = (pfc.primary || '').toUpperCase();
    const detailedPfc = (pfc.detailed || '').toUpperCase();

    if (primaryPfc === 'INCOME') {
      primary = 'REVENUE';
      if (detailedPfc.includes('RENT')) {
        category = FinancialTransactionCategory.RENT_INCOME;
        confidence = 0.9;
        reasoning.push('Plaid AI classified as INCOME / RENT.');
      } else if (detailedPfc.includes('INTEREST')) {
        category = FinancialTransactionCategory.INTEREST_INCOME;
        confidence = 0.88;
        reasoning.push('Plaid AI classified as INTEREST_INCOME.');
      } else if (detailedPfc.includes('DIVIDEND')) {
        category = FinancialTransactionCategory.MISC_INCOME;
        confidence = 0.85;
        reasoning.push('Plaid AI classified as DIVIDEND income.');
      } else {
        category = FinancialTransactionCategory.MISC_INCOME;
        confidence = 0.75;
        reasoning.push(`Plaid AI classified as INCOME (${detailedPfc || 'general'}).`);
      }
    } else if (primaryPfc === 'TRANSFER_IN') {
      if (/zelle|venmo|cashapp|cash app|paypal/i.test(fullName)) {
        primary = 'REVENUE';
        category = FinancialTransactionCategory.RENT_INCOME;
        confidence = 0.8;
        reasoning.push('Incoming digital transfer (Zelle/Venmo/CashApp) matched rent income pattern.');
      } else {
        primary = 'TRANSFER';
        category = FinancialTransactionCategory.INTER_ACCOUNT_TRANSFER;
        confidence = 0.75;
        reasoning.push('Plaid AI classified as TRANSFER_IN.');
      }
    } else if (primaryPfc === 'LOAN_PAYMENTS' || /mortgage|loan payment/i.test(fullName)) {
      primary = 'LIABILITY_PAYMENT';
      category = FinancialTransactionCategory.MORTGAGE_INTEREST;
      confidence = 0.9;
      reasoning.push('Matched mortgage/loan payment classification.');
    } else if (primaryPfc === 'RENT_AND_UTILITIES') {
      if (isCredit) {
        primary = 'REVENUE';
        category = FinancialTransactionCategory.RENT_INCOME;
        confidence = 0.85;
        reasoning.push('Reimbursement under RENT_AND_UTILITIES mapped to REVENUE.');
      } else {
        primary = 'EXPENSE';
        if (detailedPfc.includes('ELECTRIC')) category = FinancialTransactionCategory.UTILITIES;
        else if (detailedPfc.includes('GAS')) category = FinancialTransactionCategory.UTILITIES;
        else if (detailedPfc.includes('WATER')) category = FinancialTransactionCategory.UTILITIES;
        else if (detailedPfc.includes('SEWER')) category = FinancialTransactionCategory.UTILITIES;
        else if (detailedPfc.includes('TRASH')) category = FinancialTransactionCategory.UTILITIES;
        else if (detailedPfc.includes('HOA')) category = FinancialTransactionCategory.HOA_FEES;
        else category = FinancialTransactionCategory.UTILITIES;
        confidence = 0.85;
        reasoning.push(`Plaid AI classified as RENT_AND_UTILITIES (${detailedPfc}).`);
      }
    } else if (primaryPfc === 'HOME_IMPROVEMENT') {
      if (amountDollar >= 2500) {
        primary = 'EXPENSE';
        category = FinancialTransactionCategory.CAPITAL_EXPENDITURE;
        confidence = 0.92;
        reasoning.push(`Home improvement >= $2,500 threshold ($${amountDollar.toLocaleString()}) classified as CapEx.`);
      } else {
        primary = 'EXPENSE';
        category = FinancialTransactionCategory.MAINTENANCE_REPAIR;
        confidence = 0.85;
        reasoning.push(`Home improvement < $2,500 threshold ($${amountDollar.toLocaleString()}) classified as Maintenance & Repair.`);
      }
    } else if (primaryPfc === 'GENERAL_SERVICES') {
      primary = 'EXPENSE';
      if (detailedPfc.includes('REPAIR') || detailedPfc.includes('LOCKSMITH')) category = FinancialTransactionCategory.MAINTENANCE_REPAIR;
      else if (detailedPfc.includes('CLEANING')) category = FinancialTransactionCategory.CLEANING_TURNOVER;
      else if (detailedPfc.includes('LANDSCAPING')) category = FinancialTransactionCategory.LANDSCAPING_SNOW;
      else if (detailedPfc.includes('PEST')) category = FinancialTransactionCategory.PEST_CONTROL;
      else category = FinancialTransactionCategory.MAINTENANCE_REPAIR;
      confidence = 0.82;
      reasoning.push(`Plaid AI classified as GENERAL_SERVICES (${detailedPfc}).`);
    } else if (primaryPfc === 'INSURANCE') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.PROPERTY_INSURANCE;
      confidence = 0.88;
      reasoning.push('Plaid AI classified as INSURANCE.');
    } else if (primaryPfc === 'TAX') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.PROPERTY_TAX;
      confidence = 0.9;
      reasoning.push('Plaid AI classified as TAX.');
    } else if (primaryPfc === 'BANK_FEES') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.BANK_CREDIT_CARD_FEES;
      confidence = 0.9;
      reasoning.push('Plaid AI classified as BANK_FEES.');
    } else if (primaryPfc === 'LEGAL') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.LEGAL_PROFESSIONAL;
      confidence = 0.88;
      reasoning.push('Plaid AI classified as LEGAL.');
    } else if (primaryPfc === 'ACCOUNTING') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.ACCOUNTING_BOOKKEEPING;
      confidence = 0.88;
      reasoning.push('Plaid AI classified as ACCOUNTING.');
    } else if (primaryPfc === 'ADVERTISING') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.MARKETING_ADVERTISING;
      confidence = 0.88;
      reasoning.push('Plaid AI classified as ADVERTISING.');
    } else if (primaryPfc === 'SOFTWARE') {
      primary = 'EXPENSE';
      category = FinancialTransactionCategory.SOFTWARE_TECHNOLOGY;
      confidence = 0.88;
      reasoning.push('Plaid AI classified as SOFTWARE.');
    }

    // ── STEP 2: Revenue Identification (Rent & Income Heuristics) ─────────────
    if (isCredit) {
      if (/hud|section 8|section8|housing authority|pha\b/i.test(fullName)) {
        primary = 'REVENUE';
        category = FinancialTransactionCategory.RENT_INCOME;
        confidence = 0.96;
        reasoning.push('Government housing / Section 8 payment identified.');
      } else if (/appfolio|buildium|rentmanager|rent manager|cozy|tenantease|stessa/i.test(fullName)) {
        primary = 'REVENUE';
        category = FinancialTransactionCategory.RENT_INCOME;
        confidence = 0.90;
        reasoning.push('Property management software rent deposit identified.');
      }

      for (const lease of leases) {
        if (!lease.monthlyRent) continue;
        const diff = Math.abs(amountDollar - lease.monthlyRent);

        if (diff <= 1.0) {
          primary = 'REVENUE';
          category = FinancialTransactionCategory.RENT_INCOME;
          confidence = Math.max(confidence, 0.92);
          suggestedLeaseId = lease.id;
          reasoning.push(`Exact rent amount match ($${amountDollar}) for tenant ${lease.tenantName}.`);

          if (fullName.includes(lease.tenantName.toLowerCase())) {
            confidence = Math.min(1.0, confidence + 0.08);
            reasoning.push(`Tenant name '${lease.tenantName}' matched payee.`);
          }
          break;
        } else if (amountDollar >= lease.monthlyRent * 0.5 && amountDollar < lease.monthlyRent * 0.99) {
          primary = 'REVENUE';
          category = FinancialTransactionCategory.RENT_INCOME;
          confidence = Math.max(confidence, 0.78);
          suggestedLeaseId = lease.id;
          reasoning.push(`Partial rent payment ($${amountDollar} of $${lease.monthlyRent}) for tenant ${lease.tenantName}.`);
          break;
        } else if (amountDollar > lease.monthlyRent * 1.3) {
          primary = 'REVENUE';
          category = FinancialTransactionCategory.RENT_INCOME;
          confidence = Math.max(confidence, 0.85);
          suggestedLeaseId = lease.id;
          isSplitSuggested = true;
          const remainder = Math.round((amountDollar - lease.monthlyRent) * 100) / 100;
          splitSuggestion = [
            {
              amount: lease.monthlyRent,
              category: FinancialTransactionCategory.RENT_INCOME,
              reason: `Monthly rent for ${lease.tenantName}`,
            },
            {
              amount: remainder,
              category: FinancialTransactionCategory.LATE_FEE_INCOME,
              reason: `Overpayment balance (suggested late fee or deposit)`,
            },
          ];
          reasoning.push(`Rent overpayment detected ($${amountDollar} vs $${lease.monthlyRent} rent). Split suggested.`);
          break;
        }
      }
    }

    // ── STEP 3: Expense Identification & CapEx Threshold ──────────────────────
    if (!isCredit && primary !== 'LIABILITY_PAYMENT') {
      const capexKeywords = /roof|hvac|foundation|renovation|rehab|construction|lumber|decking|boiler/i;
      if (capexKeywords.test(fullName)) {
        if (amountDollar >= 2500) {
          primary = 'EXPENSE';
          category = FinancialTransactionCategory.CAPITAL_EXPENDITURE;
          confidence = 0.92;
          reasoning.push(`CapEx keyword & amount >= $2,500 threshold ($${amountDollar.toLocaleString()}).`);
        } else {
          primary = 'EXPENSE';
          category = FinancialTransactionCategory.MAINTENANCE_REPAIR;
          confidence = 0.85;
          reasoning.push(`CapEx keyword & amount < $2,500 threshold ($${amountDollar.toLocaleString()}) → Maintenance.`);
        }
      }

      if (/state farm|allstate|liberty mutual|farmers insurance|nationwide/i.test(fullName)) {
        primary = 'EXPENSE';
        category = FinancialTransactionCategory.PROPERTY_INSURANCE;
        confidence = 0.92;
        reasoning.push('Enriched counterparty matched Property Insurance provider.');
      } else if (/duke energy|con edison|peco|pg&e|national grid|eversource/i.test(fullName)) {
        primary = 'EXPENSE';
        category = FinancialTransactionCategory.UTILITIES;
        confidence = 0.92;
        reasoning.push('Enriched counterparty matched Utility provider.');
      } else if (/home depot|lowe's|lowes|ace hardware|menards/i.test(fullName)) {
        primary = 'EXPENSE';
        category = amountDollar >= 2500 ? FinancialTransactionCategory.CAPITAL_EXPENDITURE : FinancialTransactionCategory.SUPPLIES;
        confidence = 0.85;
        reasoning.push(`Building material supplier match ($${amountDollar}).`);
      }
    }

    // ── STEP 4: Liability Payment Identification (Mortgage/Debt) ─────────────
    if (!isCredit && (/mortgage|wells fargo home|chase mortgage|quicken loans|rocket mortgage|piti/i.test(fullName) || primary === 'LIABILITY_PAYMENT')) {
      primary = 'LIABILITY_PAYMENT';
      category = FinancialTransactionCategory.MORTGAGE_INTEREST;
      confidence = 0.94;
      reasoning.push('Mortgage servicer / loan payment identified.');

      if (mortgage?.nextPaymentAmount || amountDollar > 500) {
        isSplitSuggested = true;
        const estInterest = Math.round(amountDollar * 0.55 * 100) / 100;
        const estPrincipal = Math.round(amountDollar * 0.30 * 100) / 100;
        const estEscrow = Math.round((amountDollar - estInterest - estPrincipal) * 100) / 100;

        splitSuggestion = [
          {
            amount: estInterest,
            category: FinancialTransactionCategory.MORTGAGE_INTEREST,
            reason: 'Estimated mortgage interest portion',
          },
          {
            amount: estPrincipal,
            category: FinancialTransactionCategory.MORTGAGE_PRINCIPAL,
            reason: 'Estimated principal reduction portion',
          },
          {
            amount: estEscrow,
            category: FinancialTransactionCategory.MORTGAGE_ESCROW_PAYMENT,
            reason: 'Estimated escrow portion (taxes & insurance)',
          },
        ];
        reasoning.push('Suggested 3-way PITI mortgage split (Interest / Principal / Escrow).');
      } else {
        reasoning.push('Connect mortgage account to calculate exact PITI principal/interest split.');
      }
    }

    // ── STEP 5: Transfer Identification (Non-P&L) ────────────────────────────
    if (/owner draw|owner distribution|capital draw/i.test(fullName)) {
      primary = 'TRANSFER';
      category = FinancialTransactionCategory.OWNER_DISTRIBUTION;
      confidence = 0.95;
      reasoning.push('Matched owner distribution / draw pattern.');
    } else if (/capital contribution|capital injection|owner investment/i.test(fullName)) {
      primary = 'TRANSFER';
      category = FinancialTransactionCategory.CAPITAL_CONTRIBUTION;
      confidence = 0.95;
      reasoning.push('Matched capital contribution pattern.');
    } else if (/security deposit|sec dep/i.test(fullName)) {
      primary = 'TRANSFER';
      category = isCredit ? FinancialTransactionCategory.SECURITY_DEPOSIT_RECEIVED : FinancialTransactionCategory.SECURITY_DEPOSIT_RETURNED;
      confidence = 0.94;
      reasoning.push(`Security deposit ${isCredit ? 'received' : 'returned'} pattern matched.`);
    }

    // ── STEP 7: Recurring Pattern Detection ──────────────────────────────────
    if (primary !== 'UNCERTAIN' && (amountDollar > 0 || name.length > 0)) {
      if (
        category === FinancialTransactionCategory.RENT_INCOME ||
        category === FinancialTransactionCategory.MORTGAGE_INTEREST ||
        category === FinancialTransactionCategory.PROPERTY_INSURANCE ||
        category === FinancialTransactionCategory.PROPERTY_TAX ||
        category === FinancialTransactionCategory.HOA_FEES ||
        category === FinancialTransactionCategory.SOFTWARE_TECHNOLOGY
      ) {
        isRecurring = true;
        reasoning.push('Marked as recurring based on financial category characteristics.');
      }
    }

    if (primary === 'UNCERTAIN') {
      if (isCredit) {
        primary = 'REVENUE';
        category = FinancialTransactionCategory.MISC_INCOME;
        confidence = 0.45;
        reasoning.push('Fallback credit mapped to MISC_INCOME.');
      } else {
        primary = 'EXPENSE';
        category = FinancialTransactionCategory.UNCATEGORIZED;
        confidence = 0.35;
        reasoning.push('Unrecognized debit transaction. Marked PENDING_REVIEW.');
      }
    }

    return {
      primaryClassification: primary,
      paperWorkingCategory: category,
      confidenceScore: Math.min(1.0, Math.max(0.0, Math.round(confidence * 100) / 100)),
      reasoning,
      suggestedLeaseId,
      isRecurring,
      isSplitSuggested,
      splitSuggestion,
    };
  }
}

import {
  FinancialTransactionCategory,
  FinancialTransactionDirection,
  FinancialTransactionSource,
  FinancialTransactionStatus,
  Prisma,
} from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { sseEventBus } from '@/lib/events/eventBus';

export type CustomRuleType =
  | 'REVENUE_RULE'
  | 'EXPENSE_RULE'
  | 'LIABILITY_RULE'
  | 'TRANSFER_RULE'
  | 'RECURRING_MANUAL_RULE';

export interface ConditionItem {
  field:
    | 'PAYEE_NAME'
    | 'AMOUNT'
    | 'AMOUNT_RANGE'
    | 'DESCRIPTION'
    | 'DAY_OF_MONTH'
    | 'PLAID_PERSONAL_FINANCE_CATEGORY';
  operator:
    | 'EQUALS'
    | 'NOT_EQUALS'
    | 'CONTAINS'
    | 'STARTS_WITH'
    | 'ENDS_WITH'
    | 'GREATER_THAN'
    | 'LESS_THAN'
    | 'BETWEEN'
    | 'NEAR_DAY_OF_MONTH';
  value: any;
}

export interface RuleActionData {
  category: FinancialTransactionCategory;
  autoApprove: boolean;
  assignToLeaseId?: string;
  taxTreatment?: string;
  splits?: Array<{ amount: number; category: FinancialTransactionCategory; reason: string }>;
}

export interface RuleInput {
  name: string;
  projectId: string;
  userId: string;
  ruleType: CustomRuleType;
  conditions: ConditionItem[];
  action: RuleActionData;
  isActive?: boolean;
  priority?: number;
}

export interface TransactionInput {
  id?: string;
  payee: string;
  description?: string | null;
  amount: number; // in dollars
  direction: FinancialTransactionDirection;
  date: Date;
  plaidPfc?: string | null;
}

export interface SuggestedRule {
  suggestedRuleName: string;
  ruleType: CustomRuleType;
  conditions: ConditionItem[];
  action: RuleActionData;
  historicalMatchCount: number;
}

export class TransactionRuleEngine {
  /**
   * Evaluates a single condition against a transaction input.
   */
  static evaluateCondition(condition: ConditionItem, tx: TransactionInput): boolean {
    const { field, operator, value } = condition;

    switch (field) {
      case 'PAYEE_NAME': {
        const valStr = String(value || '').toLowerCase();
        const payeeStr = (tx.payee || '').toLowerCase();
        if (operator === 'EQUALS') return payeeStr === valStr;
        if (operator === 'NOT_EQUALS') return payeeStr !== valStr;
        if (operator === 'CONTAINS') return payeeStr.includes(valStr);
        if (operator === 'STARTS_WITH') return payeeStr.startsWith(valStr);
        if (operator === 'ENDS_WITH') return payeeStr.endsWith(valStr);
        return false;
      }

      case 'DESCRIPTION': {
        const valStr = String(value || '').toLowerCase();
        const descStr = (tx.description || tx.payee || '').toLowerCase();
        if (operator === 'CONTAINS') return descStr.includes(valStr);
        if (operator === 'EQUALS') return descStr === valStr;
        return false;
      }

      case 'AMOUNT': {
        const numVal = Number(value);
        const txAmt = Math.abs(tx.amount);
        if (operator === 'EQUALS') return Math.abs(txAmt - numVal) <= 0.05;
        if (operator === 'GREATER_THAN') return txAmt > numVal;
        if (operator === 'LESS_THAN') return txAmt < numVal;
        return false;
      }

      case 'AMOUNT_RANGE': {
        const [min, max] = Array.isArray(value) ? value.map(Number) : [0, 0];
        const txAmt = Math.abs(tx.amount);
        return txAmt >= min && txAmt <= max;
      }

      case 'DAY_OF_MONTH': {
        const targetDay = Number(value) || 1;
        const txDay = new Date(tx.date).getDate();
        const diff = Math.abs(txDay - targetDay);
        return diff <= 2 || diff >= 28; // ±2 days or month wrap
      }

      case 'PLAID_PERSONAL_FINANCE_CATEGORY': {
        const valStr = String(value || '').toUpperCase();
        const txPfc = (tx.plaidPfc || '').toUpperCase();
        return txPfc.includes(valStr);
      }

      default:
        return false;
    }
  }

  /**
   * Tests a rule set against an in-memory array of transactions (Dry Run).
   */
  static testRule(
    conditions: ConditionItem[],
    transactions: TransactionInput[]
  ): { matchCount: number; matchedTransactionIds: string[] } {
    const matched = transactions.filter((tx) =>
      conditions.every((cond) => this.evaluateCondition(cond, tx))
    );

    return {
      matchCount: matched.length,
      matchedTransactionIds: matched.map((m) => m.id || '').filter(Boolean),
    };
  }

  /**
   * Applies a specific database rule to all matching PENDING_REVIEW transactions for a project.
   */
  static async applyRule(ruleId: string): Promise<{ matchedCount: number; approvedCount: number }> {
    const dbRule = await prisma.transactionRule.findUnique({
      where: { id: ruleId },
    });

    if (!dbRule || !dbRule.isActive) {
      throw new Error(`Rule ${ruleId} not found or inactive`);
    }

    const conditions = (dbRule.conditions as unknown as ConditionItem[]) ?? [];
    const action = (dbRule.action as unknown as RuleActionData) ?? {};

    // Load PENDING_REVIEW transactions for this project
    const pending = await prisma.financialTransaction.findMany({
      where: {
        projectId: dbRule.projectId,
        status: 'PENDING_REVIEW',
      },
    });

    let matchedCount = 0;
    let approvedCount = 0;

    for (const ft of pending) {
      const txInput: TransactionInput = {
        id: ft.id,
        payee: ft.payee,
        description: ft.description,
        amount: Number(ft.amount),
        direction: ft.direction,
        date: ft.transactionDate,
      };

      const matches = conditions.every((cond) => this.evaluateCondition(cond, txInput));

      if (matches) {
        matchedCount++;
        const shouldAutoApprove = action.autoApprove ?? true;

        await prisma.financialTransaction.update({
          where: { id: ft.id },
          data: {
            category: action.category ?? ft.category,
            status: shouldAutoApprove ? 'AUTO_APPROVED' : 'MANUALLY_APPROVED',
            confidenceScore: 1.0,
            recurringRuleId: dbRule.id,
            matchedLeaseId: action.assignToLeaseId ?? ft.matchedLeaseId,
            updatedAt: new Date(),
          },
        });

        if (shouldAutoApprove) approvedCount++;
      }
    }

    // Update rule metadata
    await prisma.transactionRule.update({
      where: { id: ruleId },
      data: {
        matchCount: { increment: matchedCount },
        lastMatchedAt: new Date(),
      },
    });

    if (matchedCount > 0) {
      sseEventBus.emit(`transactions:approved:${dbRule.projectId}`, {
        count: approvedCount,
        timestamp: new Date().toISOString(),
      });
      sseEventBus.emit(`kpi:updated:${dbRule.projectId}`, {
        timestamp: new Date().toISOString(),
      });
    }

    return { matchedCount, approvedCount };
  }

  /**
   * Analyzes historical transactions in a project to generate smart rule suggestions.
   */
  static async generateSuggestions(projectId: string): Promise<SuggestedRule[]> {
    const transactions = await prisma.financialTransaction.findMany({
      where: { projectId },
      orderBy: { transactionDate: 'desc' },
      take: 100,
    });

    // Group transactions by payee name
    const payeeGroups: Record<string, typeof transactions> = {};
    for (const t of transactions) {
      const key = t.payee.trim().toLowerCase();
      if (!key) continue;
      if (!payeeGroups[key]) payeeGroups[key] = [];
      payeeGroups[key].push(t);
    }

    const suggestions: SuggestedRule[] = [];

    for (const [, group] of Object.entries(payeeGroups)) {
      if (group.length >= 2) {
        const sample = group[0];
        const isCredit = sample.direction === 'CREDIT';
        const ruleType: CustomRuleType = isCredit ? 'REVENUE_RULE' : 'EXPENSE_RULE';
        const sampleAmt = Number(sample.amount);

        const conds: ConditionItem[] = [
          { field: 'PAYEE_NAME', operator: 'CONTAINS', value: sample.payee },
          { field: 'AMOUNT_RANGE', operator: 'BETWEEN', value: [Math.max(0, sampleAmt - 10), sampleAmt + 10] },
        ];

        suggestions.push({
          suggestedRuleName: `Auto-approve ${sample.payee}`,
          ruleType,
          conditions: conds,
          action: {
            category: sample.category,
            autoApprove: true,
          },
          historicalMatchCount: group.length,
        });
      }
    }

    return suggestions;
  }

  /**
   * Daily scheduler for RECURRING_MANUAL_RULE entries (runs daily at 6 AM).
   */
  static async runRecurringRuleScheduler(): Promise<number> {
    console.info('[TransactionRuleEngine] Running 6 AM recurring rule scheduler...');

    const recurringRules = await prisma.transactionRule.findMany({
      where: {
        isActive: true,
      },
    });

    let generatedCount = 0;
    for (const rule of recurringRules) {
      const action = (rule.action as unknown as RuleActionData) ?? {};
      const shouldGenerate = (action as any).generateTransaction ?? false;

      if (shouldGenerate) {
        generatedCount++;
        const category = action.category ?? FinancialTransactionCategory.UNCATEGORIZED;
        const autoApprove = action.autoApprove ?? false;
        const amount = (action as any).generateAmount ?? 1000;
        const payee = (action as any).generatePayee ?? rule.name;
        const isCredit = category === 'RENT_INCOME' || category.includes('INCOME');

        const ftStatus: FinancialTransactionStatus = autoApprove ? 'AUTO_APPROVED' : 'DRAFT';

        await prisma.financialTransaction.create({
          data: {
            projectId: rule.projectId,
            userId: rule.userId,
            source: FinancialTransactionSource.RULE_GENERATED,
            recurringRuleId: rule.id,
            amount: new Prisma.Decimal(amount),
            direction: isCredit ? 'CREDIT' : 'DEBIT',
            transactionDate: new Date(),
            payee,
            description: `Scheduled manual entry from rule: ${rule.name}`,
            category,
            status: ftStatus,
            confidenceScore: 1.0,
          },
        });

        await prisma.transactionRule.update({
          where: { id: rule.id },
          data: {
            matchCount: { increment: 1 },
            lastMatchedAt: new Date(),
          },
        });

        if (autoApprove) {
          sseEventBus.emit(`transactions:approved:${rule.projectId}`, {
            count: 1,
            timestamp: new Date().toISOString(),
          });
          sseEventBus.emit(`kpi:updated:${rule.projectId}`, {
            timestamp: new Date().toISOString(),
          });
        }
      }
    }

    console.info(`[TransactionRuleEngine] Scheduler completed. Generated ${generatedCount} recurring transactions.`);
    return generatedCount;
  }
}

/**
 * Lightweight server-side in-memory cache for organization dashboards.
 * Expiry is set to 60 seconds. Can be cleared on project mutations.
 */

interface CacheEntry {
  data: any;
  expiresAt: number;
}

const CACHE_TTL_MS = 300000; // 5 minutes
const dashboardCacheMap = new Map<string, CacheEntry>();

export function getDashboardCache(orgId: string): any | null {
  const entry = dashboardCacheMap.get(orgId);
  if (!entry) return null;

  if (Date.now() > entry.expiresAt) {
    dashboardCacheMap.delete(orgId);
    return null;
  }

  return entry.data;
}

export function setDashboardCache(orgId: string, data: any): void {
  dashboardCacheMap.set(orgId, {
    data,
    expiresAt: Date.now() + CACHE_TTL_MS,
  });
}

export function clearDashboardCache(orgId: string): void {
  dashboardCacheMap.delete(orgId);
}

import { TaxEstimate } from '@/types/schema';

export function computeGrossProfit(salePrice: number, purchasePrice: number): number {
  return salePrice - purchasePrice;
}

export function computeSaleCommissions(salePrice: number, buyerPct: number, sellerPct: number): number {
  return salePrice * ((buyerPct + sellerPct) / 100);
}

export function computeNetProceeds(
  salePrice: number,
  commissions: number,
  attorneyFees: number,
  closingCosts: number,
  sellingCosts: number,
  sellerConcessions: number = 0,
  otherMarketing: number = 0
): number {
  return salePrice - (commissions + attorneyFees + closingCosts + sellingCosts + sellerConcessions + otherMarketing);
}

export function computeRealizedROI(netProfit: number, totalCashInvested: number): number {
  if (totalCashInvested <= 0) return 0;
  return (netProfit / totalCashInvested) * 100;
}

export function computeOwnerShareReturn(
  netProfit: number, 
  ownershipPct: number, 
  ownerCashInvested: number
): { ownerProfit: number, ownerROI: number, ownerCashBack: number } {
  const fraction = ownershipPct / 100;
  const ownerProfit = netProfit * fraction;
  const ownerCashBack = ownerCashInvested + ownerProfit;
  const ownerROI = ownerCashInvested > 0 ? (ownerProfit / ownerCashInvested) * 100 : 0;

  return { ownerProfit, ownerROI, ownerCashBack };
}

export function computeHoldingPeriodDays(acquisitionDate: any, saleDate: any): number {
  if (!acquisitionDate || !saleDate) return 0;

  const start = acquisitionDate.toDate ? acquisitionDate.toDate() : new Date(acquisitionDate);
  const end = saleDate.toDate ? saleDate.toDate() : new Date(saleDate);

  const diffTime = Math.abs(end.getTime() - start.getTime());
  return Math.ceil(diffTime / (1000 * 60 * 60 * 24));
}

export function isLongTermHold(holdDays: number): boolean {
  return holdDays > 365;
}

export function computeQuickTaxEstimate(
  costBasis: number, 
  netProceeds: number, 
  holdDays: number, 
  marginalRate: number = 32 // default fallback
): TaxEstimate {
  const capitalGain = Math.max(0, netProceeds - costBasis);
  const isLongTerm = isLongTermHold(holdDays);

  // IRS guidelines: Short-term uses ordinary income bracket, Long-term uses capital gains (typically 15% or 20%)
  const effectiveRate = isLongTerm ? 15 : marginalRate; 

  const estimatedTaxLiability = capitalGain * (effectiveRate / 100);
  const netAfterTax = capitalGain - estimatedTaxLiability;

  return {
    holdingPeriodDays: holdDays,
    isLongTerm,
    costBasis,
    netProceeds,
    capitalGain,
    estimatedTaxRate: effectiveRate,
    estimatedTaxLiability,
    netAfterTax
  };
}

export function computeRefiEquityExtracted(refiLoanAmount: number, existingLoanBalance: number): number {
  return Math.max(0, refiLoanAmount - existingLoanBalance);
}

export function computeRefiNewMonthlyPayment(loanAmount: number, rate: number, termYears: number): number {
  if (loanAmount <= 0 || rate <= 0 || termYears <= 0) return 0;
  const monthlyRate = (rate / 100) / 12;
  const numPayments = termYears * 12;

  return (loanAmount * monthlyRate * Math.pow(1 + monthlyRate, numPayments)) / 
         (Math.pow(1 + monthlyRate, numPayments) - 1);
}

/**
 * ── Financial Engine — PaperWorking
 * Precision-based real estate accounting logic using integer arithmetic (cents).
 * 
 * Formula: Net Profit = Sale Price - (Purchase Price + Closing Costs + Renovation Costs + Holding Costs)
 */

export interface ProfitVariance {
  projectedProfit: number;
  actualProfit: number;
  variance: number;
  percentageVariance: number;
}

/**
 * Calculates the core profit formula.
 * All inputs and outputs are in Cents (integers).
 */
export function calculateNetProfit(
  salePrice: number,
  purchasePrice: number,
  closingCosts: number,
  renovationCosts: number,
  holdingCosts: number
): number {
  return salePrice - (purchasePrice + closingCosts + renovationCosts + holdingCosts);
}

/**
 * Formats cents into a dollar string for UI display.
 */
export function formatCentsToDollars(cents: number): string {
  const dollars = cents / 100;
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: 'USD',
  }).format(dollars);
}

/**
 * Aggregate multiple deal financials into a performance snapshot.
 */
export function aggregateFinancials(financials: any[]) {
  return financials.reduce((acc, curr) => {
    acc.totalPurchasePrice += curr.purchasePrice || 0;
    acc.totalSalePrice += curr.salePrice || 0;
    acc.totalClosingCosts += curr.closingCosts || 0;
    acc.totalRenovationCosts += curr.renovationCosts || 0;
    acc.totalHoldingCosts += curr.holdingCosts || 0;
    return acc;
  }, {
    totalPurchasePrice: 0,
    totalSalePrice: 0,
    totalClosingCosts: 0,
    totalRenovationCosts: 0,
    totalHoldingCosts: 0,
  });
}

/**
 * Calculates the Waterfall distribution based on priority roles.
 */
export interface WaterfallDistribution {
  payee: string;
  role: string;
  amount: number;
}

export function calculateWaterfall(
  availableCash: number,
  payoutRules: { role: string, payee: string, amount: number }[]
): WaterfallDistribution[] {
  let remaining = availableCash;
  const distribution: WaterfallDistribution[] = [];

  // Simple priority order logic can be added here
  for (const rule of payoutRules) {
    const payout = Math.min(remaining, rule.amount);
    distribution.push({
      payee: rule.payee,
      role: rule.role,
      amount: payout
    });
    remaining -= payout;
  }

  return distribution;
}

import { Project, PendingReceipt } from '@/types/schema';

/**
 * Validates if an expected receipt approval violates the 15% contingency 
 * enforcement buffer placed on top of the original planned rehab budget.
 */
export function verifyContingencyBuffer(deal: Project, receiptToApprove: { amount: number }): {
   canApprove: boolean;
   rehabBudgetBase: number;
   rehabBudgetBuffered: number;
   currentApprovedTotal: number;
   projectedTotal: number;
   exceedsBy: number;
} {
  const rehab = deal.rehab;

  const rehabBudgetBase = rehab?.baseBudget || 0;
  const contingencyBufferPct = rehab?.contingencyBufferPercentage || 0.15; // 15% default

  const rehabBudgetBuffered = rehabBudgetBase * (1 + contingencyBufferPct);

  // Find all approved costs in the ledger that map to rehab 
  // (In a real system, you might tag CostEntry with a type='rehab')
  // We'll calculate conservatively treating all approved costs as consuming the budget, 
  // or specifically costs that don't match acquiring/holding logic.
  const currentApprovedTotal = deal.financials.costs
    .filter(c => c.approved)
    .reduce((sum, cost) => sum + cost.amount, 0);

  const projectedTotal = currentApprovedTotal + receiptToApprove.amount;

  const canApprove = projectedTotal <= rehabBudgetBuffered;
  const exceedsBy = projectedTotal - rehabBudgetBuffered;

  return {
    canApprove,
    rehabBudgetBase,
    rehabBudgetBuffered,
    currentApprovedTotal,
    projectedTotal,
    exceedsBy: Math.max(0, exceedsBy)
  };
}

import { adminDb } from '@/lib/firebase/admin';

export interface GateCriterionSnapshot {
  key: string;
  label: string;
  status: boolean;
}

export interface PhaseGateEventRecord {
  id: string;
  projectId: string;
  fromPhase: string;
  toPhase: string;
  actorId: string;
  actorRole: string;
  actorName?: string;
  actorEmail?: string;
  criteriaSnapshot: GateCriterionSnapshot[];
  overrideReason: string | null;
  createdAt: string;
}

// In-memory store fallback for test environments or offline state
const inMemoryGateEvents: PhaseGateEventRecord[] = [];

export async function recordGateEvent(eventData: PhaseGateEventRecord): Promise<PhaseGateEventRecord> {
  // Always record in memory store for fast synchronous test assertion fallback
  inMemoryGateEvents.push(eventData);

  let isE2eTest = false;
  try {
    const { cookies } = require('next/headers');
    const cookieStore = await cookies();
    isE2eTest = cookieStore?.get('__e2e_test')?.value === '1';
  } catch {}

  if (isE2eTest) {
    return eventData;
  }

  try {
    if (adminDb && typeof adminDb.collection === 'function') {
      const nowStr = eventData.createdAt || new Date().toISOString();
      const payload = {
        ...eventData,
        createdAt: nowStr,
      };

      // Write to root phase_gate_events collection
      await adminDb.collection('phase_gate_events').doc(eventData.id).set(payload);

      // Also write to subcollection under project
      await adminDb
        .collection('projects')
        .doc(eventData.projectId)
        .collection('gateEvents')
        .doc(eventData.id)
        .set(payload);
    }
  } catch (err) {
    console.error('[gateEventsStore] Error persisting to Firestore:', err);
  }

  return eventData;
}

export async function getGateEventsByProject(projectId: string): Promise<PhaseGateEventRecord[]> {
  const eventsMap = new Map<string, PhaseGateEventRecord>();

  // Load from in-memory fallback
  for (const e of inMemoryGateEvents) {
    if (e.projectId === projectId) {
      eventsMap.set(e.id, e);
    }
  }

  let isE2eTest = false;
  try {
    const { cookies } = require('next/headers');
    const cookieStore = await cookies();
    isE2eTest = cookieStore?.get('__e2e_test')?.value === '1';
  } catch {}

  if (isE2eTest) {
    return Array.from(eventsMap.values()).sort(
      (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
    );
  }

  try {
    if (adminDb && typeof adminDb.collection === 'function') {
      const snap = await adminDb
        .collection('projects')
        .doc(projectId)
        .collection('gateEvents')
        .get();

      if (snap && snap.docs) {
        for (const doc of snap.docs) {
          const data = doc.data() as PhaseGateEventRecord;
          eventsMap.set(doc.id, {
            ...data,
            id: doc.id,
          });
        }
      }

      // Also check root collection
      const rootSnap = await adminDb
        .collection('phase_gate_events')
        .where('projectId', '==', projectId)
        .get();

      if (rootSnap && rootSnap.docs) {
        for (const doc of rootSnap.docs) {
          const data = doc.data() as PhaseGateEventRecord;
          eventsMap.set(doc.id, {
            ...data,
            id: doc.id,
          });
        }
      }
    }
  } catch (err) {
    console.error('[gateEventsStore] Error reading Firestore gate events:', err);
  }

  return Array.from(eventsMap.values()).sort(
    (a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()
  );
}

export function clearInMemoryGateEvents() {
  inMemoryGateEvents.length = 0;
}

