          }
        }
      }),
      comps: {
        create: (input.comps !== undefined ? input.comps : [
          { addressLine: "123 Comp St", soldPriceCents: 25000000, soldDate: "2026-01-01", sqft: 1500, distanceMiles: 0.5, condition: "Good" },
