import { DealInvitation, DealInterest } from './engagementUtils';

/**
 * Strips quoted email reply history and standard signatures.
 */
export function stripQuotedHistoryAndSignatures(text: string): string {
  if (!text) return '';

  const lines = text.split(/\r?\n/);
  const cleanLines: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();

    // 1. Quoted lines starting with >
    if (trimmed.startsWith('>')) {
      break;
    }

    // 2. Standard reply headers
    if (
      /^on\s+.*wrote:$/i.test(trimmed) ||
      /^from:\s+/i.test(trimmed) ||
      /^to:\s+/i.test(trimmed) ||
      trimmed.startsWith('---') ||
      trimmed.startsWith('_____') ||
      /^sent\s+from\s+my/i.test(trimmed)
    ) {
      break;
    }

    // 3. Signature markers
    if (
      trimmed === '--' ||
      trimmed === 'Regards,' ||
      trimmed === 'Thanks,' ||
      trimmed === 'Sincerely,' ||
      trimmed === 'Best regards,' ||
      trimmed === 'Best,'
    ) {
      break;
    }

    cleanLines.push(line);
  }

  return cleanLines.join('\n').trim();
}

export type DealThreadEventType =
  | 'INVITE_SENT'
  | 'INTEREST_EXPRESSED'
  | 'DECLINED'
  | 'OWNER_MESSAGE'
  | 'INBOUND_EMAIL_REPLY';

export interface DealThreadEvent {
  id: string;
  dealId: string;
  dealSlug: string;
  eventType: DealThreadEventType;
  senderName: string;
  senderEmail: string;
  timestamp: string;
  content: string;
  badgeLabel?: string;
  metadata?: {
    token?: string;
    businessCard?: {
      displayName: string;
      email: string;
      phone?: string;
      company?: string;
    };
    amountIntent?: number;
    percentIntent?: number;
    viaEmail?: boolean;
  };
}

export interface UserDealsHistory {
  createdDeals: any[];
  invitedDeals: { deal: any; invite: DealInvitation }[];
  committedDeals: { deal: any; interest: DealInterest }[];
}

/**
 * Filters all deals into "My Deals" categories for a specific user ID and email:
 * 1. Created Deals: deals created/owned by currentUserId
 * 2. Invited Deals: deals where invitedEmail matches user email
 * 3. Committed Deals: deals where userId matches currentUserId and status is COMMITTED or WAITLIST
 */
export function filterUserDealsHistory(
  allDeals: any[],
  allInvitations: DealInvitation[],
  allInterests: DealInterest[],
  currentUserId: string,
  userEmail: string
): UserDealsHistory {
  const normalizedEmail = (userEmail || '').toLowerCase().trim();

  // 1. Created / Owned Deals
  const createdDeals = allDeals.filter(
    (deal) => deal.ownerId === currentUserId || deal.owner?.userId === currentUserId || deal.owner?.email === normalizedEmail
  );

  // 2. Invited Deals
  const invitedDeals = allInvitations
    .filter((inv) => inv.invitedEmail.toLowerCase().trim() === normalizedEmail || inv.invitedUserId === currentUserId)
    .map((invite) => {
      const deal = allDeals.find((d) => d.id === invite.dealId || d.slug === invite.dealSlug) || {
        id: invite.dealId,
        slug: invite.dealSlug,
        displayAddress: invite.dealSlug,
        status: invite.status,
      };
      return { deal, invite };
    });

  // 3. Committed Deals
  const committedDeals = allInterests
    .filter((int) => int.userId === currentUserId && (int.status === 'COMMITTED' || int.status === 'WAITLIST'))
    .map((interest) => {
      const deal = allDeals.find((d) => d.id === interest.dealId) || {
        id: interest.dealId,
        displayAddress: 'Property Address',
        status: 'LISTED',
      };
      return { deal, interest };
    });

  return {
    createdDeals,
    invitedDeals,
    committedDeals,
  };
}

/**
 * Formats a single thread event for display in the communications trail.
 */
export function formatDealThreadEvent(event: DealThreadEvent) {
  let badgeLabel = 'System Event';
  let badgeColor = 'bg-slate-500/10 text-slate-400 border-slate-500/30';

  switch (event.eventType) {
    case 'INVITE_SENT':
      badgeLabel = 'Invitation Sent';
      badgeColor = 'bg-blue-500/10 text-blue-400 border-blue-500/30';
      break;
    case 'INTEREST_EXPRESSED':
      badgeLabel = 'Interest Expressed';
      badgeColor = 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30';
      break;
    case 'DECLINED':
      badgeLabel = 'Invitation Declined';
      badgeColor = 'bg-slate-500/10 text-slate-400 border-slate-500/30';
      break;
    case 'OWNER_MESSAGE':
      badgeLabel = 'Owner Message';
      badgeColor = 'bg-violet-500/10 text-violet-400 border-violet-500/30';
      break;
    case 'INBOUND_EMAIL_REPLY':
      badgeLabel = 'via Email';
      badgeColor = 'bg-amber-500/10 text-amber-400 border-amber-500/30';
      break;
  }

  return {
    ...event,
    badgeLabel: event.badgeLabel || badgeLabel,
    badgeColor,
    formattedDate: new Date(event.timestamp).toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    }),
  };
}

/**
 * Inbound Email Webhook Payload Parser Fixture:
 * Processes raw email webhook payload, cleans body history, extracts token,
 * and formats an INBOUND_EMAIL_REPLY thread event labeled "via Email".
 */
export function parseInboundEmailPayload(payload: {
  From: string;
  Subject: string;
  TextBody: string;
  To?: string;
  MailboxHash?: string;
  MessageID?: string;
}): { success: boolean; event?: DealThreadEvent; error?: string } {
  if (!payload || !payload.From) {
    return { success: false, error: 'Missing From header in email payload.' };
  }

  // Extract Token from To header or MailboxHash
  let token: string | null = null;
  const recipient = payload.To || '';
  const match = recipient.match(/reply\+([a-zA-Z0-9_-]+)@/);
  if (match) {
    token = match[1];
  } else if (payload.MailboxHash) {
    token = payload.MailboxHash;
  }

  const cleanedBody = stripQuotedHistoryAndSignatures(payload.TextBody || '');
  const senderEmail = payload.From.toLowerCase().trim();
  const senderName = payload.From.split('@')[0];

  const event: DealThreadEvent = {
    id: `msg_email_${Date.now()}`,
    dealId: 'deal_inbound',
    dealSlug: 'deal_inbound',
    eventType: 'INBOUND_EMAIL_REPLY',
    senderName,
    senderEmail,
    timestamp: new Date().toISOString(),
    content: cleanedBody || '(No message body)',
    badgeLabel: 'via Email',
    metadata: {
      token: token || undefined,
      viaEmail: true,
    },
  };

  return {
    success: true,
    event,
  };
}

import type { Project } from '@/types/schema';
import type { DealListing, PublishGateResult, VisibilityMode, PublishGateCriterion } from '@/types/listing';

/**
 * Pure evaluation function that assesses whether a Project/Listing meets the
 * criteria to be published or transitioned to a loosen visibility mode.
 */
export function evaluatePublishGate(
  project: Project,
  listing: Partial<DealListing>,
  targetMode: VisibilityMode
): PublishGateResult {
  const criteria: PublishGateCriterion[] = [];
  const financials = project.financials || {};

  // 1. Control Status Set
  // "control status set" -> Owned, Under Contract, Option, or Exclusive Right
  const validControlStatuses = ['owned', 'under-contract', 'option', 'exclusive_right'];
  const controlStatus = project.controlStatus || (project as any).control_status || (listing as any).controlStatus;
  const isControlStatusSet = !!controlStatus && validControlStatuses.includes(controlStatus.toLowerCase());

  criteria.push({
    key: 'control_status_set',
    label: 'Control status set (Owned, Under Contract, Option, or Exclusive Right)',
    status: isControlStatusSet,
    isRed: true,
    detail: isControlStatusSet ? `Set to: ${controlStatus}` : 'Control status is not set or invalid',
  });

  // 2. Required Inputs Present
  // "required inputs present for every metric the target visibility will display"
  // Check if financed
  const modality = project.fundingPlan?.modality || [];
  const isFinanced =
    modality.some((m: string) =>
      ['conventional_loan', 'sba_504', 'hard_money', 'bridge'].includes(m)
    ) ||
    (project.loans && project.loans.length > 0) ||
    (financials.capitalStack || []).some((s: any) =>
      [
        'Conventional Financing',
        'Hard Money Loans',
        'SBA 504 Bank First Lien',
        'SBA 504 CDC Debenture',
        'Bridge Loans',
      ].includes(s.category)
    );

  const missingInputs: string[] = [];

  // Purchase Price
  const purchasePrice = financials.purchasePrice || financials.targetPurchasePrice;
  if (!purchasePrice || purchasePrice <= 0) missingInputs.push('Purchase Price');

  // Gross Rent
  const grossRent = (financials as any).grossRent || financials.gross_rent_per_unit || financials.actualRentalIncome || financials.monthlyGrossRent;
  if (!grossRent || grossRent <= 0) missingInputs.push('Monthly Gross Rent');

  // Vacancy Rate
  if (financials.vacancy_pct === undefined || financials.vacancy_pct === null) missingInputs.push('Vacancy Rate %');

  // Operating Expenses (Tax & Insurance)
  if (financials.tax === undefined || financials.tax === null) missingInputs.push('Taxes');
  if (financials.insurance === undefined || financials.insurance === null) missingInputs.push('Insurance');
  if (financials.utilities === undefined || financials.utilities === null) missingInputs.push('Utilities');
  if (financials.management_pct === undefined || financials.management_pct === null) missingInputs.push('Property Mgmt Fee');
  if (financials.maintenance === undefined && financials.maintenance_pct === undefined) missingInputs.push('Maintenance Reserve');

  // Funding Target
  const fundingTarget = (project as any).equityTerms?.funding_target || (project as any).equityTerms?.fundingTarget || (financials as any).equityTarget || financials.capitalRaiseTarget;
  if (!fundingTarget || fundingTarget <= 0) missingInputs.push('Funding Target');

  // Loan terms if financed
  if (isFinanced) {
    const loanAmount = financials.loanAmount || financials.targetLoanAmount || (project.loans && project.loans.length > 0);
    if (!loanAmount) missingInputs.push('Loan Amount');

    const interestRate = financials.loanInterestRate || financials.targetLoanInterestRate || (project.loans && project.loans.length > 0);
    if (!interestRate) missingInputs.push('Loan Interest Rate');

    const term = financials.loanTermYears || financials.targetLoanTermYears || (project.loans && project.loans.length > 0);
    if (!term) missingInputs.push('Loan Term');
  }

  const isUnderwritingInputsComplete = missingInputs.length === 0;
  criteria.push({
    key: 'underwriting_inputs_complete',
    label: 'Underwriting inputs complete for target visibility metrics',
    status: isUnderwritingInputsComplete,
    isRed: true,
    detail: isUnderwritingInputsComplete 
      ? 'All required metrics fields populated' 
      : `Missing fields: ${missingInputs.join(', ')}`,
  });

  // 3. Disclosure Acknowledged
  // "disclosure acknowledged for the chosen mode"
  const isDisclosureAcknowledged = listing.disclosureAcknowledgedForMode === targetMode || (listing as any).disclosureAcknowledgedModes?.includes(targetMode);
  criteria.push({
    key: 'disclosure_acknowledged',
    label: `Disclosure acknowledged for visibility mode: ${targetMode}`,
    status: !!isDisclosureAcknowledged,
    isRed: true,
    detail: isDisclosureAcknowledged 
      ? 'Disclosure acknowledged successfully' 
      : `Disclosure for ${targetMode} has not been acknowledged`,
  });

  // 4. Scope Tier and Disposition Type Set
  // "scope tier and disposition_type set"
  const dispositionType = project.dispositionType || (project as any).disposition_type || (project as any).strategyType;
  const isDispositionTypeSet = !!dispositionType && ['RENT', 'SALE', 'LEASE'].includes(dispositionType.toUpperCase());

  const rawTier = project.rehabTier || (project as any).renovationTier || (project as any).scopeTier;
  const isScopeTierSet = !!rawTier && ['STAGE', 'REFURBISH', 'RENOVATE', 'GUT', 'DEVELOP'].includes(rawTier.toUpperCase());

  const isStrategyAndScopeSet = isDispositionTypeSet && isScopeTierSet;
  let strategyDetail = '';
  if (!isDispositionTypeSet) strategyDetail += 'Disposition type not set. ';
  if (!isScopeTierSet) strategyDetail += 'Scope tier not set. ';
  if (isStrategyAndScopeSet) strategyDetail = `Disposition: ${dispositionType}, Scope: ${rawTier}`;

  criteria.push({
    key: 'scope_tier_and_strategy_set',
    label: 'Scope tier and disposition type strategy set',
    status: isStrategyAndScopeSet,
    isRed: true,
    detail: strategyDetail || 'Both scope tier and strategy are configured',
  });

  const passed = criteria.every((c) => c.status);

  return {
    passed,
    evaluatedAt: new Date().toISOString(),
    criteria,
  };
}

/**
 * R3 — Hold Agent: Edit History Utility
 * 
 * Builds field-level diff entries for the append-only holdEditHistory audit trail.
 * Compares old vs new values for a set of tracked financial fields and produces
 * HoldEditHistoryEntry records for any changes detected.
 */

import { HoldEditHistoryEntry, ProjectFinancials } from '@/types/schema';

/**
 * Tracked financial fields for edit history.
 * These are the Hold-phase fields that generate audit entries on change.
 */
export const HOLD_TRACKED_FIELDS: string[] = [
  // Rehab
  'rehabTier',
  'rehabBudget',
  'projectedRehabCost',
  'rehabActual',
  'actualRehabCost',
  'rehabDoneDate',
  'rehabTierBudgetLow',
  'rehabTierBudgetHigh',

  // Holding Costs
  'holdingCostTaxes',
  'holdingCostInsurance',
  'holdingCostUtilities',
  'monthlyHOA',
  'holdingCostMaintenance',
  'holdingCostManagement',
  'totalMonthlyHoldingCost',
  'holdStartDate',

  // Rental Operations
  'propertyManagementFee',
  'monthlyMaintenanceReserve',
  'actualRentalIncome',
  'otherMonthlyIncome',
  'daysOccupied',
  'occupiedUnits',

  // Valuation
  'estimatedCurrentValue',
];

/**
 * Compare old and new financials to produce field-level diff entries.
 * Only fields in HOLD_TRACKED_FIELDS that actually changed are included.
 * 
 * @param oldFinancials - The financial state before the edit
 * @param newFinancials - The financial state after the edit
 * @param uid - The UID of the user making the edit
 * @returns Array of HoldEditHistoryEntry for changed fields
 */
export const EXIT_TRACKED_FIELDS: string[] = [
  'exitType', 'actualSalePrice', 'sellingCosts', 'exitAttorneyFees', 'exitMarketingCost',
  'soldDate', 'listingDate', 'buyersAgentCommission', 'sellersAgentCommission',
  'finalClosingCosts', 'isStabilized', 'stabilizationDate', 'rentalMarketingCost',
  'refiLoanAmount', 'refiInterestRate', 'refiLoanTermYears', 'refiCashOut', 'refiDate',
  'marginalTaxBracket', 'estimatedCurrentValue'
];

export function buildEditHistoryEntries(
  oldFinancials: Partial<ProjectFinancials>,
  newFinancials: Partial<ProjectFinancials>,
  uid: string
): HoldEditHistoryEntry[] {
  const entries: HoldEditHistoryEntry[] = [];
  const now = new Date();

  for (const field of HOLD_TRACKED_FIELDS) {
    const oldVal = (oldFinancials as any)?.[field];
    const newVal = (newFinancials as any)?.[field];

    // Normalize for comparison: treat undefined/null/'' as equivalent
    const normalizedOld = normalizeValue(oldVal);
    const normalizedNew = normalizeValue(newVal);

    if (normalizedOld !== normalizedNew) {
      entries.push({
        field,
        oldValue: oldVal ?? null,
        newValue: newVal ?? null,
        editedAt: now,
        editedByUid: uid,
      });
    }
  }

  return entries;
}

/**
 * Compare old and new financials to produce field-level diff entries for Exit phase.
 * Only fields in EXIT_TRACKED_FIELDS that actually changed are included.
 */
export function buildExitEditHistoryEntries(
  oldFinancials: Partial<ProjectFinancials>,
  newFinancials: Partial<ProjectFinancials>,
  uid: string
): HoldEditHistoryEntry[] {
  const entries: HoldEditHistoryEntry[] = [];
  const now = new Date();

  for (const field of EXIT_TRACKED_FIELDS) {
    const oldVal = (oldFinancials as any)?.[field];
    const newVal = (newFinancials as any)?.[field];

    const normalizedOld = normalizeValue(oldVal);
    const normalizedNew = normalizeValue(newVal);

    if (normalizedOld !== normalizedNew) {
      entries.push({
        field,
        oldValue: oldVal ?? null,
        newValue: newVal ?? null,
        editedAt: now,
        editedByUid: uid,
      });
    }
  }

  return entries;
}

/**
 * Normalize a value for comparison.
 * Converts numbers to strings, treats empty string/undefined/null as 'null',
 * and handles Date objects.
 */
function normalizeValue(val: any): string {
  if (val === undefined || val === null || val === '') return 'null';

  // Handle Firestore Timestamps
  if (typeof val === 'object' && val.toDate) {
    return val.toDate().toISOString();
  }

  // Handle Date objects
  if (val instanceof Date) {
    return val.toISOString();
  }

  return String(val);
}

import { IEmailProvider, EmailDispatchPayload, EmailDispatchResult } from '../emailProvider';

/**
 * SendGrid Email Adapter — Real SendGrid REST API v3 Implementation (EM Series v2)
 *
 * Dispatches emails via POST https://api.sendgrid.com/v3/mail/send
 * Enforces all verified provider facts (F-1...F-15) and founder gates (E-1...E-12):
 * - F-2: Every From address must be on @mail.paperworking.co (or @reply.paperworking.co)
 * - F-3: text/plain MUST precede text/html in the content array
 * - F-4: 202 Accepted recorded as accepted, never as delivery
 * - F-5: bypass_list_management forbidden; bypass_unsubscribe_management for Class E only
 * - F-6: ASM group_id and groups_to_display passed per-send
 * - F-8: RFC 8058 List-Unsubscribe headers
 * - F-12: Coarse categories only (max 10, strings only, zero PII)
 * - F-13: Zero PII in custom_args (< 10,000 bytes total)
 * - Rule 9: Zero SendGrid SDK dependencies outside this module
 * - Rule 10: Kill switch halts all outbound mail without redeploy
 */
export class SendGridEmailAdapter implements IEmailProvider {
  readonly name = 'sendgrid' as const;

  async sendEmail(payload: EmailDispatchPayload): Promise<EmailDispatchResult> {
    // 1. Global Kill Switch Check (EM-3)
    if (process.env.EMAIL_GLOBAL_KILL_SWITCH === 'true') {
      const killSwitchMsg = '[SendGridEmailAdapter] 🛑 Outbound email halted by EMAIL_GLOBAL_KILL_SWITCH.';
      console.warn(killSwitchMsg);
      return {
        success: false,
        messageId: '',
        mock: false,
        provider: 'sendgrid',
        error: 'GLOBAL_KILL_SWITCH_ACTIVE',
      };
    }

    const apiKey = process.env.SENDGRID_API_KEY;

    // 2. Explicit Mock Environment Transport Check (Rule 10)
    if (!apiKey || process.env.SYSTEM_EMAIL_PROVIDER === 'mock' || process.env.EMAIL_PROVIDER === 'mock') {
      const mockId = `mock_sg_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      console.warn(
        '[SendGridEmailAdapter] ⚠️ SENDGRID_API_KEY is missing or mock mode active — test dispatch:\n' +
          `  To: ${payload.to.join(', ')}\n` +
          `  From: ${payload.from || 'notifications@mail.paperworking.co'}\n` +
          `  Subject: ${payload.subject}`
      );
      return {
        success: true,
        messageId: mockId,
        mock: true,
        provider: 'sendgrid',
        acceptedAt: new Date().toISOString(),
      };
    }

    // 3. Sender Identity Domain Validation (F-2, E-2, E-3)
    const defaultFrom = process.env.SENDGRID_FROM_EMAIL || 'notifications@mail.paperworking.co';
    const fromEmail = (payload.from || defaultFrom).toLowerCase().trim();

    const allowedSubdomains = ['@mail.paperworking.co', '@reply.paperworking.co'];
    const hasValidSubdomain = allowedSubdomains.some((dom) => fromEmail.endsWith(dom));

    if (!hasValidSubdomain && process.env.NODE_ENV !== 'test') {
      const errDomain = `[SendGridEmailAdapter] ❌ Rejected send: From address "${fromEmail}" is not on an authenticated sending subdomain (@mail.paperworking.co / @reply.paperworking.co) per F-2 and E-2.`;
      console.error(errDomain);
      this.emitTelemetry('system_email_send_failed', {
        provider: 'sendgrid',
        error: 'INVALID_FROM_DOMAIN',
        from: fromEmail,
        templateKey: payload.templateKey,
      });
      return {
        success: false,
        messageId: '',
        mock: false,
        provider: 'sendgrid',
        error: 'INVALID_FROM_DOMAIN: From address must be on @mail.paperworking.co',
      };
    }

    // 4. Content Array Construction — Plain-text MUST precede HTML (F-3, Rule 6)
    const plainText = payload.text || payload.html.replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();
    const content = [
      {
        type: 'text/plain',
        value: plainText,
      },
      {
        type: 'text/html',
        value: payload.html,
      },
    ];

    // 5. Construct SendGrid Payload
    const body: Record<string, any> = {
      personalizations: [
        {
          to: payload.to.map((email) => ({ email })),
        },
      ],
      from: { email: fromEmail },
      subject: payload.subject,
      content,
    };

    // Reply-To (E-3, E-11, F-11)
    const defaultReplyTo = 'hi@paperworking.co';
    body.reply_to = { email: payload.replyTo || defaultReplyTo };

    // 6. Zero-PII custom_args (F-13)
    const customArgs: Record<string, string> = {
      send_record_id: payload.sendRecordId || `sr_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
      template_key: payload.templateKey || 'UNREGISTERED_KEY',
    };
    if (payload.messageClass) {
      customArgs.message_class = payload.messageClass;
    }
    body.custom_args = customArgs;

    // 7. Coarse Categories — Max 10, string only, zero PII (F-12)
    const categories: string[] = [
      payload.messageClass ? `class_${payload.messageClass.toLowerCase()}` : 'class_e',
      payload.category ? payload.category.toLowerCase().slice(0, 50) : 'transactional',
    ];
    if (payload.templateKey) {
      categories.push(payload.templateKey.toLowerCase().slice(0, 50));
    }
    body.categories = Array.from(new Set(categories)).slice(0, 10);

    // 8. Suppression & Mail Settings — bypass_list_management is strictly FORBIDDEN (F-5)
    const mailSettings: Record<string, any> = {};

    if (payload.messageClass === 'E') {
      // Class E transactional bypasses unsubscribe suppression only (F-5)
      mailSettings.bypass_unsubscribe_management = { enable: true };
    }

    // CI Sandbox Mode (F-4)
    if (payload.sandboxMode || process.env.SENDGRID_SANDBOX_MODE === 'true') {
      mailSettings.sandbox_mode = { enable: true };
    }

    if (Object.keys(mailSettings).length > 0) {
      body.mail_settings = mailSettings;
    }

    // 9. Unsubscribe Group (ASM) Configuration (F-6)
    if (payload.asmGroupId) {
      body.asm = {
        group_id: payload.asmGroupId,
        groups_to_display: payload.asmGroupsToDisplay || [payload.asmGroupId],
      };
    }

    // 10. RFC 8058 One-Click Unsubscribe Headers (F-8)
    const headers: Record<string, string> = {};
    if (payload.listUnsubscribeHeader) {
      headers['List-Unsubscribe'] = payload.listUnsubscribeHeader;
      if (payload.listUnsubscribePostHeader) {
        headers['List-Unsubscribe-Post'] = payload.listUnsubscribePostHeader;
      }
    }
    if (payload.templateKey) {
      headers['X-PW-Template-Key'] = payload.templateKey;
    }
    if (Object.keys(headers).length > 0) {
      body.headers = headers;
    }

    // 11. Dispatch Request to SendGrid API v3
    try {
      const res = await fetch('https://api.sendgrid.com/v3/mail/send', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${apiKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });

      const isSuccess = typeof res.ok === 'boolean' ? res.ok : (res.status >= 200 && res.status < 300);
      if (!isSuccess) {
        const errorText = await res.text();
        const errorMessage = `SendGrid API error (${res.status}): ${errorText}`;
        console.error(`[SendGridEmailAdapter] ❌ ${errorMessage}`);

        this.emitTelemetry('system_email_send_failed', {
          provider: 'sendgrid',
          error: errorMessage,
          status: res.status,
          recipientCount: payload.to.length,
          templateKey: payload.templateKey,
        });

        return {
          success: false,
          messageId: '',
          mock: false,
          provider: 'sendgrid',
          error: errorMessage,
        };
      }

      // Status 202 Accepted (or 200 Sandbox) represents acceptance for processing, NOT delivery (F-4, Rule 14)
      const headerMsgId = res.headers.get('x-message-id');
      const messageId = headerMsgId || `sg_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;

      this.emitTelemetry('system_email_accepted', {
        provider: 'sendgrid',
        messageId,
        recipientCount: payload.to.length,
        templateKey: payload.templateKey,
        sandbox: !!payload.sandboxMode,
      });

      return {
        success: true,
        messageId,
        mock: false,
        provider: 'sendgrid',
        acceptedAt: new Date().toISOString(),
      };
    } catch (err: any) {
      const errorMessage = err.message || 'Unknown network error';
      console.error('[SendGridEmailAdapter] ❌ Network error dispatching email:', errorMessage);

      this.emitTelemetry('system_email_send_failed', {
        provider: 'sendgrid',
        error: errorMessage,
        recipientCount: payload.to.length,
        templateKey: payload.templateKey,
      });

      return {
        success: false,
        messageId: '',
        mock: false,
        provider: 'sendgrid',
        error: errorMessage,
      };
    }
  }

  private emitTelemetry(event: string, properties: Record<string, any>) {
    try {
      const posthogKey = process.env.NEXT_PUBLIC_POSTHOG_KEY;
      if (posthogKey && typeof fetch !== 'undefined') {
        fetch('https://app.posthog.com/capture/', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            api_key: posthogKey,
            event,
            properties: {
              ...properties,
              distinct_id: properties.distinct_id || 'system_email_provider',
            },
          }),
        }).catch(() => {});
      }
    } catch {
      // Fire-and-forget telemetry failure
    }
  }
}

