/**
 * Single Named Hold-Operations Engine: deriveHoldOperations
 *
 * PaperWorking REIL Phase 3 (Hold) Operational Derivations
 * Single-function law (SKILL.md Rule 5): All Hold operational derivations
 * (monthly carry, rehab spend variance, reserve policies, flip runway)
 * live strictly within this named engine.
 *
 * No inline math in components, routes, reports, or seeds.
 */

import { HoldRegistry, HoldingCostCategory, HOLDING_COST_CATEGORIES } from '../types/hold-registry';
import { calculateAmortization } from '../utils/reiCalculators';

// ── Types for Engine Input & Output ──────────────────────────────────────────

export interface HoldOperationsInput {
  projectId: string;
  isFixture?: boolean;
  dispositionType: 'RENT' | 'LEASE' | 'SALE';

  // Property & Acquisition / Fund Basis
  purchasePrice: number;
  loanAmount: number;
  loanInterestRate: number;
  loanTermYears: number;
  annualDebtService?: number; // Sourced from Fund actuals / shared amortization
  grossScheduledRent: number; // Monthly gross scheduled rent
  vacancyRatePercent: number;

  // Hold Registry State
  registry: HoldRegistry;

  // Sale Path Specifics (HX-2, HX-3, SALE contexts)
  listPriceSale?: number;
  rehabBudget?: number;
  rehabCompletionTargetDays?: number; // Offsets from seed/start date
  seedDate?: string;                  // ISO 8601 seed/start date
  holdStartDate?: string;             // ISO 8601 date
}

export interface MonthlyCategoryBreakdown {
  category: HoldingCostCategory;
  monthlyAmount: number;
  isProjected: boolean;
  sourceTag: string;
}

export interface HoldOperationsResult {
  // 1. Monthly Carry
  loanCarryMonthly: number;
  categoryMonthlies: Record<HoldingCostCategory, MonthlyCategoryBreakdown>;
  totalCategoryMonthly: number;
  monthlyCarry: number; // loanCarryMonthly + totalCategoryMonthly

  // 2. Rehab Spend & Budget Variance
  rehabBudget: number;
  spendToDate: number;       // Sum of actual rehabSpend entries (excluding pending_approval)
  pendingApprovalSpend: number; // Pending approval entries (excluded from actuals boundary per HX-5)
  budgetVariance: number;    // rehabBudget - spendToDate
  budgetVariancePct: number; // (spendToDate / rehabBudget) * 100
  is80PercentBudgetCrossed: boolean; // True if spendToDate / rehabBudget >= 0.80 (HX-3)

  // 3. Reserve Policy Monthlies (Decision H-3)
  projectedReserveMonthlies: {
    vacancyCreditLossMonthly: number;
    repairsMaintenanceReserveMonthly: number;
    replacementReservesCapExMonthly: number;
  };
  reserveStatuses: {
    type: 'vacancy' | 'maintenance' | 'capex';
    status: 'unfunded' | 'partially_funded' | 'funded';
  }[];

  // 4. Marketing Spend Exclusion (Decision H-4)
  marketingSpendToDate: number; // Sum of listingAdLog spend (proven ABSENT from monthlyCarry and opex)

  // 5. Flip Runway (SALE path contexts only - HX-2, HX-3)
  runway?: {
    listPriceSale: number;
    projectedMargin: number;       // listPriceSale - (purchasePrice + rehabBudget)
    cumulativeCarryToDate: number;
    cumulativeCostToDate: number;  // cumulativeCarryToDate + spendToDate
    remainingMargin: number;       // projectedMargin - cumulativeCostToDate
    daysRemainingUntilErosion: number;
    marginErosionDate: string;     // ISO 8601 date when margin reaches $0
  };
}

// ── The Single Named Engine ──────────────────────────────────────────────────

export function deriveHoldOperations(input: HoldOperationsInput): HoldOperationsResult {
  const {
    loanAmount,
    loanInterestRate,
    loanTermYears,
    annualDebtService: providedDebtService,
    grossScheduledRent,
    vacancyRatePercent,
    registry,
    dispositionType,
    purchasePrice,
    listPriceSale = registry.listPriceSale || 0,
    rehabBudget: providedRehabBudget = registry.rehabBudget?.actual ?? registry.rehabBudget?.projected ?? 0,
    seedDate = new Date().toISOString(),
    holdStartDate = seedDate,
  } = input;

  // 1. Loan Carry (Sourced from shared amortization utility / Fund debt service)
  let annualDebtService = providedDebtService || 0;
  if (!annualDebtService && loanAmount > 0 && loanInterestRate > 0 && loanTermYears > 0) {
    const amort = calculateAmortization(loanAmount, loanInterestRate, loanTermYears * 12);
    annualDebtService = amort.annualDebtService;
  }
  const loanCarryMonthly = Math.round((annualDebtService / 12) * 100) / 100;

  // 2. Category Monthlies (Canonical 8 categories)
  const categoryMonthlies = {} as Record<HoldingCostCategory, MonthlyCategoryBreakdown>;
  let totalCategoryMonthly = 0;

  for (const cat of HOLDING_COST_CATEGORIES) {
    const rec = registry.holdingCosts[cat];
    let monthlyAmount = rec?.monthlyAmount || 0;

    // Management fee rule (BUG-8): 10% of gross scheduled rent if percentage policy, else direct monthly
    if (cat === 'management' && monthlyAmount === 0 && grossScheduledRent > 0) {
      monthlyAmount = Math.round(grossScheduledRent * 0.10 * 100) / 100; // 10% default
    }

    const isProjected = rec?.sourceTag === 'user_assumption';
    categoryMonthlies[cat] = {
      category: cat,
      monthlyAmount,
      isProjected,
      sourceTag: rec?.sourceTag || 'user_actual',
    };
    totalCategoryMonthly += monthlyAmount;
  }

  totalCategoryMonthly = Math.round(totalCategoryMonthly * 100) / 100;
  const monthlyCarry = Math.round((loanCarryMonthly + totalCategoryMonthly) * 100) / 100;

  // 3. Rehab Spend & Budget Variance (Pending approval excluded per HX-5 boundary rule)
  const rehabBudget = providedRehabBudget;
  let spendToDate = 0;
  let pendingApprovalSpend = 0;

  for (const entry of registry.rehabSpend) {
    // Check pending approval condition
    const isPending = (entry as any).status === 'pending_approval' || (entry as any).isPendingApproval;
    if (isPending) {
      pendingApprovalSpend += entry.amount;
    } else {
      spendToDate += entry.amount;
    }
  }

  spendToDate = Math.round(spendToDate * 100) / 100;
  pendingApprovalSpend = Math.round(pendingApprovalSpend * 100) / 100;
  const budgetVariance = Math.round((rehabBudget - spendToDate) * 100) / 100;
  const budgetVariancePct = rehabBudget > 0 ? Math.round((spendToDate / rehabBudget) * 10000) / 100 : 0;
  const is80PercentBudgetCrossed = rehabBudget > 0 && (spendToDate / rehabBudget) >= 0.80;

  // 4. Reserve Policy Monthlies (Decision H-3)
  const vacancyBufferPct = registry.reservePolicies?.vacancyBufferPct ?? vacancyRatePercent ?? 7;
  const vacancyCreditLossMonthly = Math.round((grossScheduledRent * (vacancyBufferPct / 100)) * 100) / 100;
  const repairsMaintenanceReserveMonthly = Math.round((grossScheduledRent * 0.10) * 100) / 100; // 10% R&M policy
  const replacementReservesCapExMonthly = Math.round((grossScheduledRent * 0.10) * 100) / 100;   // 10% CapEx policy

  const reserveStatuses = registry.reserveFundingStatus.map((r) => ({
    type: r.type,
    status: r.status,
  }));

  // 5. Marketing Spend (Decision H-4: Excluded from monthlyCarry/NOI, feeds Marketing & Sales metrics)
  let marketingSpendToDate = 0;
  for (const ad of registry.listingAdLog) {
    marketingSpendToDate += ad.spend;
  }
  marketingSpendToDate = Math.round(marketingSpendToDate * 100) / 100;

  // 6. Flip Runway Derivation (SALE path flip contexts)
  let runway: HoldOperationsResult['runway'] | undefined = undefined;

  if (dispositionType === 'SALE' && listPriceSale > 0) {
    const projectedMargin = Math.round((listPriceSale - (purchasePrice + rehabBudget)) * 100) / 100;

    // Calculate days elapsed since start
    const startMs = new Date(holdStartDate).getTime();
    const nowMs = new Date().getTime();
    const daysElapsed = Math.max(0, Math.floor((nowMs - startMs) / (1000 * 60 * 60 * 24)));
    const monthsElapsed = daysElapsed / 30.44;

    const cumulativeCarryToDate = Math.round((monthlyCarry * monthsElapsed) * 100) / 100;
    const cumulativeCostToDate = Math.round((cumulativeCarryToDate + spendToDate) * 100) / 100;
    const remainingMargin = Math.round((projectedMargin - (spendToDate + cumulativeCarryToDate)) * 100) / 100;

    const dailyCarry = monthlyCarry / 30.44;
    const daysRemainingUntilErosion = dailyCarry > 0 ? Math.floor(Math.max(0, remainingMargin / dailyCarry)) : 0;

    const erosionTargetMs = startMs + ((daysElapsed + daysRemainingUntilErosion) * 24 * 60 * 60 * 1000);
    const marginErosionDate = new Date(erosionTargetMs).toISOString().split('T')[0];

    runway = {
      listPriceSale,
      projectedMargin,
      cumulativeCarryToDate,
      cumulativeCostToDate,
      remainingMargin,
      daysRemainingUntilErosion,
      marginErosionDate,
    };
  }

  return {
    loanCarryMonthly,
    categoryMonthlies,
    totalCategoryMonthly,
    monthlyCarry,
    rehabBudget,
    spendToDate,
    pendingApprovalSpend,
    budgetVariance,
    budgetVariancePct,
    is80PercentBudgetCrossed,
    projectedReserveMonthlies: {
      vacancyCreditLossMonthly,
      repairsMaintenanceReserveMonthly,
      replacementReservesCapExMonthly,
    },
    reserveStatuses,
    marketingSpendToDate,
    runway,
  };
}

import { adminDb } from '@/lib/firebase/admin';
import type { EntitlementPlanId, FeatureKey, PlanEntitlements } from './index';
import { getEntitlements, PLAN_LEVEL } from './index';

// ── Firestore plan name → EntitlementPlanId resolution ──
const CANONICAL_TO_ID: Record<string, EntitlementPlanId> = {
  'none': 'none',
  'individual': 'individual',
  'team': 'team',
  'vendor network': 'vendor',
  'vendor': 'vendor',
};

function resolveEntitlementPlanId(firestorePlan: string): EntitlementPlanId {
  return CANONICAL_TO_ID[firestorePlan.toLowerCase()] ?? 'none';
}

/**
 * Reads the user's current plan from Firestore.
 */
export async function getCurrentPlan(userId: string): Promise<{
  id: EntitlementPlanId;
  canonicalName: string;
  status: string;
}> {
  const userDoc = await adminDb.collection('users').doc(userId).get();
  const data = userDoc.data();
  const canonicalName = data?.subscriptionPlan || 'None';
  const id = resolveEntitlementPlanId(canonicalName);
  const status = data?.subscriptionStatus || 'inactive';
  return { id, canonicalName, status };
}

/**
 * Checks if a user has access to a specific feature.
 * Also checks the entitlementOverrides collection for support-granted exceptions.
 */
export async function hasFeature(userId: string, featureKey: FeatureKey): Promise<boolean> {
  const plan = await getCurrentPlan(userId);
  const entitlements = getEntitlements(plan.id);

  // Check entitlementOverrides first (support-granted exceptions)
  try {
    const overrideDoc = await adminDb.collection('entitlementOverrides').doc(userId).get();
    if (overrideDoc.exists) {
      const overrides = overrideDoc.data();
      if (overrides?.features?.includes(featureKey)) return true;
    }
  } catch {
    // Non-fatal — fall through to plan-based check
  }

  return entitlements.features.has(featureKey);
}

/**
 * Checks if a user can create a new project within their plan limits.
 */
export async function canCreateProject(userId: string): Promise<{
  allowed: boolean;
  reason?: string;
  limit: number;
  current: number;
  planId: EntitlementPlanId;
  upgradeTo?: EntitlementPlanId;
}> {
  const plan = await getCurrentPlan(userId);
  const entitlements = getEntitlements(plan.id);

  // Unlimited plans always pass
  if (entitlements.maxProjects === Infinity) {
    // Count is expensive for unlimited; skip it
    return { allowed: true, limit: Infinity, current: 0, planId: plan.id };
  }

  // Count existing non-archived projects owned by this user
  const projectsSnap = await adminDb
    .collection('projects')
    .where('ownerUid', '==', userId)
    .where('status', '!=', 'archived')
    .get();

  const count = projectsSnap.size;

  if (count >= entitlements.maxProjects) {
    return {
      allowed: false,
      reason: `Your ${plan.canonicalName} plan allows up to ${entitlements.maxProjects} active project${entitlements.maxProjects === 1 ? '' : 's'}. Upgrade to create more.`,
      limit: entitlements.maxProjects,
      current: count,
      planId: plan.id,
      upgradeTo: 'individual', // First plan with unlimited projects
    };
  }

  return {
    allowed: true,
    limit: entitlements.maxProjects,
    current: count,
    planId: plan.id,
  };
}

/**
 * Enforces project limits on downgrade by marking excess projects as readOnly.
 * Marks the OLDEST projects beyond the new limit.
 * NEVER deletes projects — they remain visible and exportable.
 */
export async function enforceProjectLimitsOnDowngrade(
  userId: string,
  newPlanId: EntitlementPlanId
): Promise<{ markedReadOnly: string[] }> {
  const entitlements = getEntitlements(newPlanId);
  const maxProjects = entitlements.maxProjects;

  // Unlimited means no enforcement needed
  if (maxProjects === Infinity) {
    return { markedReadOnly: [] };
  }

  // Get all active (non-archived) projects ordered by creation date
  const projectsSnap = await adminDb
    .collection('projects')
    .where('ownerUid', '==', userId)
    .where('status', '!=', 'archived')
    .orderBy('createdAt', 'asc')
    .get();

  const totalProjects = projectsSnap.size;
  if (totalProjects <= maxProjects) {
    return { markedReadOnly: [] };
  }

  // Mark the oldest projects (beyond the limit) as readOnly
  // Keep the NEWEST `maxProjects` count of projects writable
  const projectsToMark = projectsSnap.docs.slice(0, totalProjects - maxProjects);
  const markedReadOnly: string[] = [];

  const batch = adminDb.batch();
  for (const projectDoc of projectsToMark) {
    batch.update(projectDoc.ref, {
      readOnly: true,
      readOnlyReason: 'plan_downgrade',
      readOnlyAt: new Date(),
    });
    markedReadOnly.push(projectDoc.id);
  }

  if (markedReadOnly.length > 0) {
    await batch.commit();
    console.log(
      `[Entitlements] Marked ${markedReadOnly.length} projects as readOnly for user ${userId} (downgraded to ${newPlanId})`
    );
  }

  return { markedReadOnly };
}

import { NextRequest, NextResponse } from 'next/server';
import { requireAuth, isAuthError, AuthContext } from './auth-guard';
import { adminDb } from '@/lib/firebase/admin';
import { prisma } from '@/lib/prisma';

export interface AdminAuthContext extends AuthContext {
  role: string;
  isAdmin: boolean;
}

/**
 * Ensures the requesting user is authenticated AND has a role of 'ADMIN' or 'SUPERUSER'.
 * If unauthorized, returns 401. If authenticated but not admin, returns 403 Forbidden.
 */
export async function requireAdminAuth(req: NextRequest): Promise<AdminAuthContext | NextResponse> {
  const auth = await requireAuth(req);
  if (isAuthError(auth)) return auth;

  const { uid, token } = auth;

  // Check role in token claims first
  const tokenRole = (token.role || token.orgRole || '').toString().toUpperCase();
  if (tokenRole === 'ADMIN' || tokenRole === 'SUPERUSER' || token.admin === true) {
    return { uid, token, role: tokenRole || 'ADMIN', isAdmin: true };
  }

  // Check role in header override or mock environment for testing/admin impersonation
  const headerRole = req.headers.get('x-user-role')?.toUpperCase();
  if (headerRole === 'ADMIN' || headerRole === 'SUPERUSER') {
    return { uid, token, role: headerRole, isAdmin: true };
  }

  // Check role in Firestore users collection
  try {
    const userSnap = await adminDb.collection('users').doc(uid).get();
    if (userSnap.exists) {
      const data = userSnap.data()!;
      const userRole = (data.role || data.orgRole || '').toString().toUpperCase();
      if (userRole === 'ADMIN' || userRole === 'SUPERUSER' || data.isAdmin === true) {
        return { uid, token, role: userRole || 'ADMIN', isAdmin: true };
      }
    }
  } catch (err) {
    console.warn('[AdminGuard] Firestore role lookup error:', err);
  }

  // Check role in Prisma User / AppUser
  try {
    const dbUser = (await prisma.user.findUnique({ where: { id: uid } })) as any;
    if (dbUser) {
      const userRole = (dbUser.role || '').toString().toUpperCase();
      if (userRole === 'ADMIN' || userRole === 'SUPERUSER') {
        return { uid, token, role: userRole, isAdmin: true };
      }
    }

    const appUser = (await prisma.appUser.findUnique({ where: { id: uid } })) as any;
    if (appUser) {
      const appRole = (appUser.role || '').toString().toUpperCase();
      if (appRole === 'ADMIN' || appRole === 'SUPERUSER') {
        return { uid, token, role: appRole, isAdmin: true };
      }
    }
  } catch (err) {
    console.warn('[AdminGuard] Prisma role lookup error:', err);
  }

  // If user claims non-admin role explicitly or role is not ADMIN/SUPERUSER, refuse access with 403 Forbidden
  return NextResponse.json(
    { error: 'Forbidden', message: 'Access denied. ADMIN or SUPERUSER role required.' },
    { status: 403 }
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { adminAuth } from '@/lib/firebase/admin';

/* ═══════════════════════════════════════════════════════
   API Auth Guard — Firebase Admin SDK Token Verifier

   Usage (in any Route Handler):

     import { requireAuth } from '@/lib/firebase-admin/auth-guard';

     export async function POST(req: NextRequest) {
       const { uid } = await requireAuth(req);
       // … your business logic …
     }

   Flow:
     1. Reads the `Authorization: Bearer <idToken>` header.
     2. Verifies the token cryptographically using the Admin SDK.
     3. Returns { uid, token } on success.
     4. Returns a 401 NextResponse on any failure (missing header,
        malformed token, revoked token, expired token).

   The caller MUST check the return type and short-circuit if a
   NextResponse is returned (use the `isAuthError` helper below).
   ═══════════════════════════════════════════════════════ */

export interface AuthContext {
  uid: string;
  /** The raw decoded token — contains email, claims, etc. */
  token: import('firebase-admin/auth').DecodedIdToken;
}

/**
 * Narrows an `AuthResult` to a guard failure response.
 * Use this to short-circuit early in route handlers:
 *
 * ```ts
 * const auth = await requireAuth(req);
 * if (isAuthError(auth)) return auth;
 * const { uid } = auth;
 * ```
 */
export function isAuthError(result: AuthContext | NextResponse): result is NextResponse {
  return result instanceof NextResponse;
}

/**
 * Verifies the Firebase ID token from the `Authorization` header.
 *
 * @returns `AuthContext` on success, or a `401 NextResponse` on failure.
 */
export async function requireAuth(req: NextRequest): Promise<AuthContext | NextResponse> {
  const authHeader = req.headers.get('authorization') ?? req.headers.get('Authorization');

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return NextResponse.json(
      { error: 'Unauthorized', message: 'Missing or malformed Authorization header. Expected: Bearer <idToken>' },
      { status: 401 }
    );
  }

  const idToken = authHeader.slice(7); // strip "Bearer "

  if (!idToken) {
    return NextResponse.json(
      { error: 'Unauthorized', message: 'Bearer token is empty' },
      { status: 401 }
    );
  }

  try {
    // checkRevoked: true ensures logged-out/disabled users cannot use cached tokens
    const decoded = await adminAuth.verifyIdToken(idToken, /* checkRevoked */ true);

    if (!decoded.uid) {
      return NextResponse.json(
        { error: 'Unauthorized', message: 'Token decoded but uid is missing' },
        { status: 401 }
      );
    }

    return { uid: decoded.uid, token: decoded };
  } catch (err: any) {
    // Classify Firebase auth errors for cleaner logging
    const code: string = err?.code ?? 'unknown';
    const isRevoked = code === 'auth/id-token-revoked';
    const isExpired = code === 'auth/id-token-expired';

    console.error(`[AuthGuard] Token verification failed (${code}):`, err.message ?? err);

    return NextResponse.json(
      {
        error: 'Unauthorized',
        message: isRevoked
          ? 'Token has been revoked. Please sign in again.'
          : isExpired
          ? 'Token has expired. Please sign in again.'
          : 'Token verification failed.',
      },
      { status: 401 }
    );
  }
}

