/* ── REI Status → Lifecycle Phase Mapping ──
   When a user creates a project that's already mid-lifecycle
   (e.g., "Rehabbing"), we start it at the correct phase
   instead of always Phase 1. */
function derivePhaseFromREIStatus(reiStatus?: string): {
  phaseStatus: string;
  currentPhase: number;
  status: string;
} {
  switch (reiStatus) {
    case 'Target':
      return { phaseStatus: 'Phase 1: Acquisition', currentPhase: 1, status: 'acquisition' };
    case 'In Contract':
    case 'Acquired':
      return { phaseStatus: 'Phase 2: Fund', currentPhase: 2, status: 'fund' };
    case 'Rehabbing':
    case 'Under Construction':
    case 'Renting':
      return { phaseStatus: 'Phase 3: Hold', currentPhase: 3, status: 'hold' };
    case 'For Sale':
    case 'realized':
    case 'Sold':
      return { phaseStatus: 'Phase 4: Exit', currentPhase: 4, status: 'exit' };
    default:
      return { phaseStatus: 'Phase 1: Acquisition', currentPhase: 1, status: 'acquisition' };
  }
}

function sanitizeFirestorePayload(payload: any) {
  if (!payload) return;
  if (payload.financials) {
    const keysToPrune = [
      'purchasePrice',
      'estimatedARV',
      'arv',
      'listedPrice',
      'targetPurchasePrice',
      'capitalRaiseTarget',
      'committedCapital',
      'actualRehabCost',
      'rehabBudget',
      'rehabActual',
      'actualRentalIncome',
      'fixedAcquisitionCosts',
      'emdAmount',
      'counterPriceCents',
      'loanAmount',
      'loanInterestRate',
      'loanTermYears',
      'loanOriginationPoints',
      'estimatedTimelineDays',
      'projectedRehabCost',
      'maxOffer'
    ];
    for (const key of keysToPrune) {
      delete payload.financials[key];
    }
  }
  delete payload.propertyFacts;
  delete payload.comps;
}

