      const { phaseStatus, currentPhase, status } = derivePhaseFromREIStatus(reiStatus);

      // If a dateOfSale is provided, the deal is already sold → Phase 4
      const hasSoldDate = !!(dealData.financials as any)?.soldDate;
      const finalPhaseStatus = hasSoldDate ? 'Phase 4: Closing & Exit' : phaseStatus;
      const finalPhase = hasSoldDate ? 4 : currentPhase;
      const finalStatus = hasSoldDate ? 'Sold' : status;

      const deal: Project = {
        ...dealData as any,
        id: newDoc.id,
        organizationId,
        // ── Smart Phase Initialization ──
        // Derived from the REI status the user selected in the wizard
        phaseStatus: finalPhaseStatus,
        currentPhase: finalPhase,
        status: finalStatus,
        createdAt: new Date(),
        updatedAt: new Date(),
        ownerUid: dealData.ownerUid || 'user_123',
        // CRITICAL BUG FIX: Initialize members map so creator has access via firestore.rules
        members: {
          [dealData.ownerUid || 'user_123']: {
            role: 'Lead Investor',
            addedAt: new Date(),
          }
        }
      };

      const firestorePayload = JSON.parse(JSON.stringify(deal));
      sanitizeFirestorePayload(firestorePayload);

      await setDoc(newDoc, {
        ...firestorePayload,
        createdAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });

      // Reconstruct history so charts populate immediately
      try {
        await reconstructHistoryForProject(deal);
      } catch (err) {
        console.error('Failed to reconstruct history for project:', err);
      }

      // SYNC: Trigger Postgres replication for the new deal
      try {
        await financialsSyncService.syncProjectFinancials(deal);
      } catch (err) {
        console.error('Failed to sync project financials on creation:', err);
      }

      return newDoc.id;
    } catch (error) {
      console.error('Critical Failure: Could not record deal in Firestore.', error);
      throw error;
    }
  },

  /**
   * Update project meta-data (status, address, etc)
   */
  async updateProject(projectId: string, updates: Partial<Project>) {
    try {
      if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
        let attempts = 0;
        const maxAttempts = 3;
        let lastErr;
        while (attempts < maxAttempts) {
          try {
            attempts++;
            const res = await fetch(`/api/reil/projects/${projectId}`, {
              method: 'PATCH',
              headers: { 
                'Content-Type': 'application/json',
                'Authorization': 'Bearer mock_token'
              },
              body: JSON.stringify(updates),
            });
            if (!res.ok) {
              throw new Error(`HTTP error! status: ${res.status}`);
            }
            return;
          } catch (err) {
            lastErr = err;
            if (attempts >= maxAttempts) throw err;
            await new Promise((resolve) => setTimeout(resolve, 50));
          }
        }
        throw lastErr;
      }
      const dealRef = doc(db, 'projects', projectId);

      // ── Automation Hook: Phase Progression ──
      if (updates.financials?.offerStatus === 'Accepted') {
        updates.phaseStatus = 'Phase 2: Fund';
        updates.currentPhase = 2;
        updates.status = 'fund';
      }

      const firestoreUpdates = JSON.parse(JSON.stringify(updates));
      sanitizeFirestorePayload(firestoreUpdates);

      await updateDoc(dealRef, {
        ...firestoreUpdates,
        updatedAt: serverTimestamp(),
      });

      // SYNC: Fetch full project and update Postgres
      const fullDeal = await this.getProject(projectId);
      if (fullDeal) {
        try {
          await financialsSyncService.syncProjectFinancials(fullDeal);
        } catch (err) {
          console.error('Failed to sync project financials on update:', err);
        }
        try {
          await reconstructHistoryForProject(fullDeal);
        } catch (err) {
          console.error('Failed to reconstruct history on update:', err);
        }
      }
    } catch (error) {
       console.error(`Status Shift Error: Failed to synchronize update for deal ${projectId}`, error);
       throw error;
    }
  },

  /**
   * Add a line item to the ledgerItems sub-collection
   */
  async addLedgerItem(projectId: string, organizationId: string, item: Partial<LedgerItem>) {
    try {
      const ledgerRef = collection(db, 'projects', projectId, 'ledgerItems');
      const docData = {
        ...item,
        projectId,
        organizationId,
        createdAt: serverTimestamp(),
        status: item.status || 'Pending',
      };

      const docRef = await addDoc(ledgerRef, docData);

      // SYNC: Trigger batch sync for the deal's ledger
      const items = await this.getLedgerItems(projectId);
      try {
        await financialsSyncService.syncLedgerItems(projectId, organizationId, items);
      } catch (err) {
        console.error('Failed to sync ledger items on add:', err);
      }

      return docRef.id;
    } catch (error) {
       console.error(`Ledger Integrity Breach: Failed to record item for deal ${projectId}`, error);
       throw error;
    }
  },

  /**
   * Update or Approve/Reject a ledger item
   */
  async updateLedgerItem(projectId: string, itemId: string, updates: Partial<LedgerItem>) {
    try {
      const itemRef = doc(db, 'projects', projectId, 'ledgerItems', itemId);
      await updateDoc(itemRef, {
        ...updates,
        updatedAt: serverTimestamp(),
      });

      // SYNC: Recalculate and sync the entire ledger to ensure SQL consistency
      const snapshot = await getDoc(doc(db, 'projects', projectId));
      const orgId = snapshot.data()?.organizationId;
      if (orgId) {
        const items = await this.getLedgerItems(projectId);
        try {
          await financialsSyncService.syncLedgerItems(projectId, orgId, items);
        } catch (err) {
          console.error('Failed to sync ledger items on update:', err);
        }
      }
    } catch (error) {
       console.error(`Approval Failure: Failed to modify ledger item ${itemId}`, error);
       throw error;
    }
  },

  /**
   * Real-time listener for a single deal's ledger
   */
  subscribeToLedger(projectId: string, onUpdate: (items: LedgerItem[]) => void) {
    const ledgerRef = collection(db, 'projects', projectId, 'ledgerItems');
    const q = query(ledgerRef, orderBy('createdAt', 'desc'));

    return onSnapshot(q, (snapshot) => {
      const items = snapshot.docs.map(d => ({ id: d.id, ...d.data() } as LedgerItem));
      onUpdate(items);
    });
  },

  /**
   * Fetch a single project by ID
   */
  async getProject(projectId: string) {
    try {
      if (typeof window === 'undefined') {
        return null;
      }
      if (document.cookie.includes('__e2e_test')) {
        const res = await fetch(`/api/reil/projects/${projectId}`, {
          headers: {
            'Authorization': 'Bearer mock_token'
          }
        });
        if (res.ok) {
          const data = await res.json();
          return (data.project || data) as Project;
        }
        return null;
      }
      const dealRef = doc(db, 'projects', projectId);
      const snapshot = await getDoc(dealRef);
      if (snapshot.exists()) {
        return { id: snapshot.id, ...snapshot.data() } as Project;
      }
      return null;
    } catch (error) {
       console.error(`Fetch Failure: Could not retrieve project ${projectId}`, error);
       throw error;
    }
  },

  /**
   * Find projects by MLS ID (ListingKey)
   * Essential for webhook ingestion where ListingKey is the primary identifier.
   */
  async getProjectsByMlsId(mlsId: string) {
    try {
      const projectsRef = collection(db, 'projects');
      const q = query(projectsRef, where('mls_id', '==', mlsId));
      const snapshot = await getDocs(q);

      return snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })) as Project[];
    } catch (error) {
      console.error(`Search Failure: Could not find projects for mls_id ${mlsId}`, error);
      throw error;
    }
  },

  /**
   * Fetch all ledger items for a deal (internal use for sync)
   */
  async getLedgerItems(projectId: string) {
    const ledgerRef = collection(db, 'projects', projectId, 'ledgerItems');
    const snapshot = await getDocs(ledgerRef);
    return snapshot.docs.map(d => ({ id: d.id, ...d.data() } as LedgerItem));
  },

  /**
   * Create a vendor quote request
   */
  async createVendorRequest(projectId: string, vendorUid: string, message: string, quotedFee?: number) {
    try {
      const requestsRef = collection(db, 'projects', projectId, 'vendorRequests');
      const docData = {
        projectId,
        vendorUid,
        message,
        quotedFee,
        status: 'PENDING',
        requestedAt: serverTimestamp(),
      };

      const docRef = await addDoc(requestsRef, docData);
      return docRef.id;
    } catch (error) {
      console.error(`Vendor Request Error: Failed to create request for vendor ${vendorUid}`, error);
      throw error;
    }
  },

  /**
   * Finalize and archive a project, updating portfolio aggregates on the Organization.
   */
  async closeProjectAndArchive(projectId: string, organizationId: string, exitStrategy: 'Sell' | 'Rent' | 'Lease') {
    try {
      // 1. Fetch the project and calculate final outcome using canonical math
      const deal = await this.getProject(projectId);
      if (!deal) throw new Error('Project not found');

      const metrics = computeAutopsyMetrics(deal);
      const profit = metrics.netProfit;
      const roi = metrics.roi;

      const closedOutcome = profit >= 0 ? 'won' : 'lost';
      const targetStatus = closedOutcome === 'won' ? 'closed_won' : 'closed_lost';

      // 2. Update Project status and lock it globally
      const dealRef = doc(db, 'projects', projectId);
      await updateDoc(dealRef, {
        status: targetStatus,
        phaseStatus: 'Phase 4: Closing & Exit',
        locked: true,
        'financials.closedOutcome': closedOutcome,
        'financials.netRealizedProfit': profit,
        'financials.totalROI': roi,
        updatedAt: serverTimestamp(),
      });

      // 3. Aggregate all closed projects for this organization
      const projectsRef = collection(db, 'projects');
      const q = query(
        projectsRef,
        where('organizationId', '==', organizationId),
        where('status', 'in', ['closed_won', 'closed_lost', 'Sold', 'Rented'])
      );
      const snapshot = await getDocs(q);

      let totalProfit = 0;
      let totalAllInCost = 0;
      const closedCount = snapshot.docs.length;

      snapshot.docs.forEach(docSnap => {
        const data = docSnap.data() as Project;
        const p = data.financials?.netRealizedProfit || 0;
        const c = data.financials?.totalAllInCost || 0;
        totalProfit += p;
        totalAllInCost += c;
      });

      // Capital-weighted average ROI calculation
      const avgROI = totalAllInCost > 0 ? (totalProfit / totalAllInCost) * 100 : 0;

      // 4. Update Organization aggregates for the global dashboard
      const orgRef = doc(db, 'organizations', organizationId);
      await updateDoc(orgRef, {
        totalProjectsClosed: closedCount,
        totalNetRealizedProfit: totalProfit,
        averagePortfolioROI: avgROI,
        updatedAt: serverTimestamp(),
      });

      return { closedOutcome, profit, roi };
    } catch (error) {
      console.error('Failed to close and archive project:', error);
      throw error;
    }
  },

  /**
   * Subscribe to vendor requests for a project
   */
  subscribeToVendorRequests(projectId: string, onUpdate: (requests: any[]) => void) {
    const requestsRef = collection(db, 'projects', projectId, 'vendorRequests');
    const q = query(requestsRef, orderBy('requestedAt', 'desc'));

    return onSnapshot(q, (snapshot) => {
      const items = snapshot.docs.map(d => ({ id: d.id, ...d.data() }));
      onUpdate(items);
    });
  },

  /**
   * Write an immutable snapshot of a phase’s financial state.
   * Called exactly once when the user advances past a phase.
   * Also atomically bumps Project.currentPhase to the next value.
   *
   * Sub-collection path: projects/{projectId}/phaseSnapshots/{phaseKey}
   */
  async capturePhaseSnapshot(
    projectId: string,
    phaseKey: PhaseSnapshotKey,
    data: Phase1Snapshot | Phase2Snapshot | Phase3Snapshot
  ): Promise<void> {
    try {
      // 1. Write snapshot document (setDoc = deterministic ID = idempotent)
      const snapshotRef = doc(db, 'projects', projectId, 'phaseSnapshots', phaseKey);
      await setDoc(snapshotRef, {
        ...data,
        capturedAt: serverTimestamp(),
      });

      // 2. Atomically bump currentPhase on the parent project
      const phaseNumber: Record<PhaseSnapshotKey, number> = {
        'phase-1': 2,
        'phase-2': 3,
        'phase-3': 4,
      };
      const dealRef = doc(db, 'projects', projectId);
      await updateDoc(dealRef, {
        currentPhase: phaseNumber[phaseKey],
        lastPhaseTransitionAt: serverTimestamp(),
        updatedAt: serverTimestamp(),
      });
    } catch (error) {
      console.error(`Pipeline Error: Failed to capture ${phaseKey} snapshot for ${projectId}`, error);
      throw error;
    }
  },

  /**
   * Fetch all captured phase snapshots for a project.
   * Returns a PhaseSnapshotMap (partial — only completed phases are present).
   * Used by ProjectPipelineContext on mount.
   */
  async getPhaseSnapshots(projectId: string): Promise<PhaseSnapshotMap> {
    try {
      const snapshotsRef = collection(db, 'projects', projectId, 'phaseSnapshots');
      const snapshotDocs = await getDocs(snapshotsRef);
      const map: PhaseSnapshotMap = {};

      snapshotDocs.forEach(docSnap => {
        const key = docSnap.id as PhaseSnapshotKey;
        const raw = docSnap.data();
        // Coerce Firestore Timestamps → JS Date
        const capturedAt = raw.capturedAt?.toDate ? raw.capturedAt.toDate() : new Date();

        if (key === 'phase-1') {
          map['phase-1'] = { ...raw, capturedAt } as Phase1Snapshot;
        } else if (key === 'phase-2') {
          map['phase-2'] = { ...raw, capturedAt } as Phase2Snapshot;
        } else if (key === 'phase-3') {
          map['phase-3'] = { ...raw, capturedAt } as Phase3Snapshot;
        }
      });

      return map;
    } catch (error) {
      console.error(`Pipeline Error: Failed to fetch snapshots for ${projectId}`, error);
      return {};
    }
  },
};

import { adminDb } from '@/lib/firebase/admin';

/**
 * Merges a user's prior history associated with a claimed email address into their verified userId.
 * This includes updating dealInvitations, investor_contacts, followers, commitments, and project equityParties.
 */
export async function mergeIdentityHistory(userId: string, claimEmail: string, userDisplayName?: string): Promise<void> {
  const emailLower = claimEmail.toLowerCase().trim();

  // 1. Update dealInvitations
  const invitesSnap = await adminDb.collection('dealInvitations')
    .where('inviteeEmail', '==', emailLower)
    .get();
  for (const doc of invitesSnap.docs) {
    await doc.ref.update({
      inviteeUid: userId,
      ...(userDisplayName ? { inviteeName: userDisplayName } : {}),
    });
  }

  // 2. Update investor_contacts
  const contactsSnap = await adminDb.collectionGroup('investor_contacts')
    .where('email', '==', emailLower)
    .get();
  for (const doc of contactsSnap.docs) {
    await doc.ref.update({ uid: userId });
  }

  // 3. Update followers (key doc by userId and delete old non-userId doc)
  const followersSnap = await adminDb.collectionGroup('followers')
    .where('email', '==', emailLower)
    .get();
  for (const doc of followersSnap.docs) {
    const data = doc.data();
    const newRef = doc.ref.parent.doc(userId);
    await newRef.set({
      ...data,
      id: userId,
    });
    if (doc.id !== userId) {
      await doc.ref.delete();
    }
  }

  // 4. Update commitments
  const commitmentsSnap = await adminDb.collectionGroup('commitments')
    .where('email', '==', emailLower)
    .get();
  for (const doc of commitmentsSnap.docs) {
    await doc.ref.update({ uid: userId });
  }

  // 5. Update project equityParties
  const projectsSnap = await adminDb.collection('projects').get();
  for (const doc of projectsSnap.docs) {
    const data = doc.data();
    if (data.equityParties && Array.isArray(data.equityParties)) {
      let updated = false;
      const newParties = data.equityParties.map((p: any) => {
        if (p.email && p.email.toLowerCase() === emailLower) {
          updated = true;
          return { ...p, memberId: userId };
        }
        return p;
      });
      if (updated) {
        await doc.ref.update({ equityParties: newParties });
      }
    }
  }
}

'use client';

import { getApp, getApps } from 'firebase/app';
import { getMessaging, getToken, onMessage, Messaging } from 'firebase/messaging';

// Initialize messaging lazily on client-side only
let messagingInstance: Messaging | null = null;

export function getClientMessaging(): Messaging | null {
  if (typeof window === 'undefined') return null;

  if (!messagingInstance) {
    try {
      // Check if service worker is supported in the browser
      if ('serviceWorker' in navigator && 'PushManager' in window) {
        const app = getApps().length > 0 ? getApp() : null;
        if (app) {
          messagingInstance = getMessaging(app);
        }
      }
    } catch (err) {
      console.warn('[FCM Client] Failed to initialize getMessaging:', err);
    }
  }
  return messagingInstance;
}

/**
 * Requests push permission and returns the FCM device token if granted.
 */
export async function requestPushPermissionAndGetToken(): Promise<string | null> {
  if (typeof window === 'undefined') return null;

  try {
    // 1. Check browser support
    if (!('serviceWorker' in navigator) || !('PushManager' in window)) {
      console.warn('[FCM Client] Service worker or Push notifications not supported in this browser.');
      return null;
    }

    // 2. Request Notification Permission
    const permission = await Notification.requestPermission();
    if (permission !== 'granted') {
      console.log('[FCM Client] Notification permission was denied/ignored:', permission);
      return null;
    }

    // 3. Register the service worker explicitly
    const registration = await navigator.serviceWorker.register('/firebase-messaging-sw.js', {
      scope: '/'
    });
    console.log('[FCM Client] Service Worker registered with scope:', registration.scope);

    // Wait for the service worker registration to transition to 'activated' state if it isn't already
    await new Promise<void>((resolve) => {
      if (registration.active && registration.active.state === 'activated') {
        resolve();
        return;
      }

      const isActivated = () => registration.active && registration.active.state === 'activated';

      let resolved = false;
      let checkInterval: any = null;
      let timeoutId: any = null;

      const finish = () => {
        if (resolved) return;
        resolved = true;

        if (checkInterval) clearInterval(checkInterval);
        if (timeoutId) clearTimeout(timeoutId);

        registration.removeEventListener('updatefound', onUpdateFound);
        if (registration.installing) {
          registration.installing.removeEventListener('statechange', onStateChange);
        }
        if (registration.waiting) {
          registration.waiting.removeEventListener('statechange', onStateChange);
        }
        if (registration.active) {
          registration.active.removeEventListener('statechange', onStateChange);
        }

        resolve();
      };

      const onStateChange = () => {
        if (isActivated()) {
          finish();
        }
      };

      const onUpdateFound = () => {
        const newWorker = registration.installing;
        if (newWorker) {
          newWorker.addEventListener('statechange', onStateChange);
        }
        if (isActivated()) {
          finish();
        }
      };

      registration.addEventListener('updatefound', onUpdateFound);

      if (registration.installing) {
        registration.installing.addEventListener('statechange', onStateChange);
      }
      if (registration.waiting) {
        registration.waiting.addEventListener('statechange', onStateChange);
      }
      if (registration.active) {
        registration.active.addEventListener('statechange', onStateChange);
      }

      // Polling fallback to ensure we catch the activation status in all scenarios
      checkInterval = setInterval(() => {
        if (registration.installing) {
          registration.installing.addEventListener('statechange', onStateChange);
        }
        if (registration.waiting) {
          registration.waiting.addEventListener('statechange', onStateChange);
        }
        if (registration.active) {
          registration.active.addEventListener('statechange', onStateChange);
        }

        if (isActivated()) {
          finish();
        }
      }, 50);

      // Bounded safety timeout (10 seconds) to prevent hanging the promise indefinitely
      timeoutId = setTimeout(finish, 10000);
    });

    // 4. Retrieve token from FCM
    const messagingClient = getClientMessaging();
    if (!messagingClient) return null;

    const vapidKey = process.env.NEXT_PUBLIC_FIREBASE_VAPID_KEY;
    if (!vapidKey) {
      console.error('[FCM Client] NEXT_PUBLIC_FIREBASE_VAPID_KEY is not defined in environment variables.');
      return null;
    }

    const token = await getToken(messagingClient, {
      vapidKey,
      serviceWorkerRegistration: registration
    });

    return token;
  } catch (error) {
    console.error('[FCM Client] Error getting token:', error);
    return null;
  }
}

/**
 * Registers a callback for receiving foreground notifications.
 */
export function onForegroundMessage(callback: (payload: any) => void) {
  const messagingClient = getClientMessaging();
  if (!messagingClient) return () => {};

  return onMessage(messagingClient, (payload) => {
    console.log('[FCM Client] Foreground message received: ', payload);
    callback(payload);
  });
}

import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { deepDiff } from '@/lib/utils/deepDiff';
import { writeActivityLog } from './activityLogWriter';
import { writeMetricSnapshots } from './snapshotWriter';

/* ═══════════════════════════════════════════════════════
   Project Write Wrapper — Tracked Updates

   Wraps a Firestore project update with automatic:
     1. Before/after diffing
     2. Activity log append (audit trail)
     3. Metric snapshot recomputation

   Use this wrapper instead of raw Firestore writes when
   you need audit + snapshot side effects. For high-
   frequency writes where the overhead isn't wanted (e.g.
   real-time field edits in the UI), use the underlying
   Firestore write directly and batch the snapshot/log
   via the nightly cron.

   IMPORTANT: This runs server-side only (uses firebase-admin).
   ═══════════════════════════════════════════════════════ */

export interface ProjectWriteResult {
  success: boolean;
  changesDetected: number;
  snapshotWritten: boolean;
}

/**
 * Wraps a project update with automatic snapshot and audit log writes.
 *
 * Flow:
 *   1. Read current project document (before state)
 *   2. Apply updates to Firestore
 *   3. Diff before/after to get changed fields
 *   4. Call writeActivityLog with the changes
 *   5. Call writeMetricSnapshots with the updated project
 *
 * @param projectId  The Firestore project document ID
 * @param userId     The UID of the user making the change
 * @param updates    Partial update payload (same shape as updateDoc)
 * @param source     How the change originated
 * @returns          Summary of what happened
 */
export async function updateProjectWithTracking(
  projectId: string,
  userId: string,
  updates: Record<string, any>,
  source: 'manual' | 'vendor' | 'system' = 'manual'
): Promise<ProjectWriteResult> {
  const projectRef = adminDb.collection('projects').doc(projectId);

  // 1. Read the current state (before)
  const beforeSnap = await projectRef.get();
  if (!beforeSnap.exists) {
    throw new Error(`Project ${projectId} not found`);
  }
  const beforeData = beforeSnap.data()!;

  // 2. Apply the update to Firestore
  await projectRef.update({
    ...updates,
    updatedAt: FieldValue.serverTimestamp(),
  });

  // 3. Compute the "after" state by merging locally
  //    (avoids a second read — the only difference is our updates + updatedAt)
  const afterData = mergeUpdates(beforeData, updates);

  // 4. Diff before/after
  const changes = deepDiff(beforeData, afterData);

  // 5. Write activity log (non-blocking — errors are logged but don't fail the update)
  const logPromise = writeActivityLog(projectId, userId, changes, source).catch(
    (err) => {
      console.error(`[ProjectWriteWrapper] Activity log write failed for ${projectId}:`, err?.message);
    }
  );

  // 5b. Write timeline edit activity
  let timelinePromise = Promise.resolve();
  if (changes.length > 0) {
    const { trackDealActivity } = require('@/lib/invitations/activityTimeline');
    const fieldsChanged = changes.map((c: any) => c.fieldPath).join(', ');
    timelinePromise = trackDealActivity(
      projectId,
      projectId,
      userId,
      'edit',
      { editSummary: `Updated fields: ${fieldsChanged}` }
    ).catch((err: any) => {
      console.error(`[ProjectWriteWrapper] Timeline edit write failed for ${projectId}:`, err?.message);
    });
  }

  // 6. Write metric snapshots (non-blocking)
  let snapshotWritten = false;
  const snapshotPromise = writeMetricSnapshots(projectId, afterData)
    .then(() => {
      snapshotWritten = true;
    })
    .catch((err) => {
      console.error(`[ProjectWriteWrapper] Snapshot write failed for ${projectId}:`, err?.message);
    });

  // Wait for side effects to complete
  await Promise.all([logPromise, snapshotPromise, timelinePromise]);

  return {
    success: true,
    changesDetected: changes.length,
    snapshotWritten,
  };
}

/**
 * Merges flat and dot-notation updates into an existing data object.
 * Handles Firestore dot-notation paths like 'financials.purchasePrice'.
 */
function mergeUpdates(
  existing: Record<string, any>,
  updates: Record<string, any>
): Record<string, any> {
  // Deep clone existing to avoid mutation
  const result = JSON.parse(JSON.stringify(existing));

  for (const [key, value] of Object.entries(updates)) {
    // Skip FieldValue sentinels (like serverTimestamp) — they resolve server-side
    if (value && typeof value === 'object' && '_methodName' in value) continue;

    if (key.includes('.')) {
      // Dot-notation path: 'financials.purchasePrice' → nested set
      const parts = key.split('.');
      let current = result;
      for (let i = 0; i < parts.length - 1; i++) {
        if (current[parts[i]] === undefined || typeof current[parts[i]] !== 'object') {
          current[parts[i]] = {};
        }
        current = current[parts[i]];
      }
      current[parts[parts.length - 1]] = value;
    } else {
      // Simple key
      if (typeof value === 'object' && value !== null && !Array.isArray(value) && typeof result[key] === 'object' && result[key] !== null) {
        // Merge objects (Firestore updateDoc merges top-level objects)
        result[key] = { ...result[key], ...value };
      } else {
        result[key] = value;
      }
    }
  }

  return result;
}

import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import type { Project } from '@/types/schema';
import {
  computeProjectSnapshotData,
  parseFirestoreDate,
} from '@/lib/metrics/snapshotService';

/* ═══════════════════════════════════════════════════════
   Snapshot Writer — Server-Side Metric Snapshot Engine

   Called after a project document is updated (server-side).
   Recomputes all REI metrics using the canonical
   `deriveAllMetrics` engine and writes/updates snapshot
   documents in the `propertyMetricSnapshots` collection.

   Key format: `${projectId}_${period}`
   Period: current month "YYYY-MM"

   Uses the existing `computeProjectSnapshotData` from
   snapshotService.ts for consistency — the same logic
   that reconstructHistoryForProject uses.
   ═══════════════════════════════════════════════════════ */

/**
 * Computes the current period key in "YYYY-MM" format.
 */
function getCurrentPeriod(): { period: string; date: Date } {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  return {
    period: `${year}-${month}`,
    date: new Date(year, now.getMonth(), 1),
  };
}

/**
 * Builds a Project-like object from raw Firestore admin data.
 * Handles Firestore Timestamp → Date coercion for the fields
 * that deriveAllMetrics needs.
 */
function normalizeProjectData(
  projectId: string,
  data: FirebaseFirestore.DocumentData
): Project {
  return {
    ...data,
    id: projectId,
    createdAt: data.createdAt ? parseFirestoreDate(data.createdAt) : new Date(),
    updatedAt: data.updatedAt ? parseFirestoreDate(data.updatedAt) : new Date(),
  } as Project;
}

export interface SnapshotWriteResult {
  snapshotsWritten: number;
  metricsSummary: {
    noi: number | null;
    capRate: number | null;
    cashOnCashReturn: number | null;
    dscr: number | null;
  };
}

/**
 * Called after a project document is updated.
 * Recomputes all metrics and writes a snapshot for the current period.
 *
 * @param projectId   The Firestore document ID
 * @param projectData The full project document data (after update)
 * @returns           Summary of what was written
 */
export async function writeMetricSnapshots(
  projectId: string,
  projectData: FirebaseFirestore.DocumentData
): Promise<SnapshotWriteResult> {
  const project = normalizeProjectData(projectId, projectData);
  const { period, date } = getCurrentPeriod();

  // Use the existing canonical snapshot computation function
  const snapshotData = computeProjectSnapshotData(project, period, 'monthly', date);

  // Write the current-month snapshot
  const docId = snapshotData.id; // `${projectId}_${period}`
  const docRef = adminDb.collection('propertyMetricSnapshots').doc(docId);

  await docRef.set(
    {
      ...snapshotData,
      createdAt: FieldValue.serverTimestamp(),
    },
    { merge: true }
  );

  return {
    snapshotsWritten: 1,
    metricsSummary: {
      noi: snapshotData.noi ?? null,
      capRate: snapshotData.capRate ?? null,
      cashOnCashReturn: snapshotData.cashOnCashReturn ?? null,
      dscr: snapshotData.dscr ?? null,
    },
  };
}

/**
 * Batch-process multiple projects for cron usage.
 * Processes projects sequentially to avoid overwhelming Firestore.
 *
 * @param projectIds  Array of project IDs to process (max 100)
 * @returns           Summary of batch operation
 */
export async function writeMetricSnapshotsBatch(
  projectIds: string[]
): Promise<{
  projectsProcessed: number;
  snapshotsWritten: number;
  errors: Array<{ projectId: string; error: string }>;
}> {
  const errors: Array<{ projectId: string; error: string }> = [];
  let snapshotsWritten = 0;
  let projectsProcessed = 0;

  const { period, date } = getCurrentPeriod();
  const BATCH_SIZE = 400; // Firestore batch write limit safety margin
  let batch = adminDb.batch();
  let batchCount = 0;

  for (const projectId of projectIds) {
    try {
      const docSnap = await adminDb.collection('projects').doc(projectId).get();
      if (!docSnap.exists) {
        errors.push({ projectId, error: 'Project document not found' });
        continue;
      }

      const project = normalizeProjectData(projectId, docSnap.data()!);
      const snapshotData = computeProjectSnapshotData(project, period, 'monthly', date);

      const docRef = adminDb.collection('propertyMetricSnapshots').doc(snapshotData.id);
      batch.set(
        docRef,
        { ...snapshotData, createdAt: FieldValue.serverTimestamp() },
        { merge: true }
      );

      batchCount++;
      snapshotsWritten++;
      projectsProcessed++;

      // Commit batch when reaching limit
      if (batchCount >= BATCH_SIZE) {
        await batch.commit();
        batch = adminDb.batch();
        batchCount = 0;
      }
    } catch (err: any) {
      errors.push({ projectId, error: err.message ?? String(err) });
    }
  }

  // Commit remaining batch
  if (batchCount > 0) {
    await batch.commit();
  }

  return { projectsProcessed, snapshotsWritten, errors };
}

import { adminDb } from '@/lib/firebase/admin';
import type { FractionalInvestor, CommitmentStatus, CapitalPartyType, ContributionEntry } from '@/types/schema';

/* ═══════════════════════════════════════════════════════════════
   syncFractionalInvestors — Commitment → fractionalInvestors[] bridge

   The commitments subcollection is the source of truth for capital
   raises. Legacy equity/distribution calculators still read
   project.fractionalInvestors[], so API routes call these helpers
   after every commitment write to keep both views aligned.
   ═══════════════════════════════════════════════════════════════ */

export type CommitmentSyncInput = {
  id: string;
  name: string;
  email: string | null;
  amountCents: number;
  status: CommitmentStatus;
  partyType?: CapitalPartyType;
};

type LegacyInvestorStatus = FractionalInvestor['status'];

const STATUS_MAP: Record<CommitmentStatus, LegacyInvestorStatus> = {
  pledged: 'invited',
  'soft-committed': 'invited',
  transferred: 'pending_subscription',
  'docs-out': 'pending_subscription',
  signed: 'pending_subscription',
  cleared: 'confirmed',
  'funds-confirmed': 'confirmed',
};

function computeEquityPercentage(
  contributionAmount: number,
  fin: Record<string, number | undefined>,
): number {
  const equityBase =
    fin.capitalRaiseTarget || fin.purchasePrice || fin.projectedRehabCost || 0;
  if (equityBase <= 0) return 0;
  return Number(((contributionAmount / equityBase) * 100).toFixed(4));
}

function buildInvestorEntry(
  commitment: CommitmentSyncInput,
  fin: Record<string, number | undefined>,
): FractionalInvestor {
  const contributionAmount = commitment.amountCents / 100;

  return {
    id: commitment.id,
    email: commitment.email || '',
    name: commitment.name,
    equityPercentage: computeEquityPercentage(contributionAmount, fin),
    contributionAmount,
    status: STATUS_MAP[commitment.status],
    partyType: commitment.partyType || 'Investor',
  };
}

export async function syncFractionalInvestorFromCommitment(
  projectId: string,
  commitment: CommitmentSyncInput,
): Promise<void> {
  const projectRef = adminDb.collection('projects').doc(projectId);
  const snap = await projectRef.get();
  if (!snap.exists) return;

  const data = snap.data()!;
  const fin = (data.financials ?? {}) as Record<string, number | undefined>;
  const investor = buildInvestorEntry(commitment, fin);

  const list: FractionalInvestor[] = [...(data.fractionalInvestors ?? [])];
  const idx = list.findIndex((entry) => entry.id === commitment.id);

  if (idx >= 0) {
    list[idx] = { ...list[idx], ...investor };
  } else {
    list.push(investor);
  }

  // Sync project.contributions as ContributionEntry rows
  const contributions: ContributionEntry[] = [...(data.contributions ?? [])];
  const cIdx = contributions.findIndex((entry) => entry.id === commitment.id);
  const newContribution: ContributionEntry = {
    id: commitment.id,
    projectId,
    partyName: commitment.name,
    email: commitment.email,
    amountCents: commitment.amountCents,
    status: commitment.status,
    evidenceDocId: null,
    evidenceDocUrl: null,
    partyType: commitment.partyType || 'Investor',
    createdAt: data.createdAt ? new Date(data.createdAt.toDate ? data.createdAt.toDate() : data.createdAt).toISOString() : new Date().toISOString(),
  };

  if (cIdx >= 0) {
    contributions[cIdx] = { ...contributions[cIdx], ...newContribution };
  } else {
    contributions.push(newContribution);
  }

  await projectRef.update({
    fractionalInvestors: list,
    contributions: contributions,
  });
}

export async function removeFractionalInvestorForCommitment(
  projectId: string,
  commitmentId: string,
): Promise<void> {
  const projectRef = adminDb.collection('projects').doc(projectId);
  const snap = await projectRef.get();
  if (!snap.exists) return;

  const data = snap.data()!;
  const list: FractionalInvestor[] = (data.fractionalInvestors ?? []).filter(
    (entry: FractionalInvestor) => entry.id !== commitmentId,
  );
  const contributions = (data.contributions ?? []).filter(
    (entry: any) => entry.id !== commitmentId,
  );

  await projectRef.update({
    fractionalInvestors: list,
    contributions: contributions,
  });
}

