// Standard USPS abbreviations for street type normalization
const STREET_TYPE_ABBREVIATIONS: Record<string, string> = {
  'street': 'St',
  'st': 'St',
  'st.': 'St',
  'avenue': 'Ave',
  'ave': 'Ave',
  'ave.': 'Ave',
