  'trl': 'Trl',
  'way': 'Way',
  'parkway': 'Pkwy',
  'pkwy': 'Pkwy',
  'highway': 'Hwy',
  'hwy': 'Hwy',
  'expressway': 'Expy',
  'expy': 'Expy',
  'freeway': 'Fwy',
