  'pike': 'Pike',
  'turnpike': 'Tpke',
  'tpke': 'Tpke',
  'square': 'Sq',
  'sq': 'Sq',
  'loop': 'Loop',
  'crossing': 'Xing',
  'xing': 'Xing',
  'alley': 'Aly',
  'aly': 'Aly',
  'pass': 'Pass',
};

// Unit type abbreviations
const UNIT_TYPE_ABBREVIATIONS: Record<string, string> = {
  'apartment': 'Apt',
  'apt': 'Apt',
  'apt.': 'Apt',
  'suite': 'Ste',
  'ste': 'Ste',
  'ste.': 'Ste',
  'unit': 'Unit',
  '#': 'Unit',
  'no': 'Unit',
  'no.': 'Unit',
  'number': 'Unit',
  'room': 'Rm',
  'rm': 'Rm',
  'floor': 'Fl',
  'fl': 'Fl',
  'building': 'Bldg',
  'bldg': 'Bldg',
};

const titleCase = (str: string) => {
  return str.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ');
};

/**
 * Derives a canonical address string from address components.
 * Pure function — no side effects, no API calls.
 * This is the SOLE producer of canonicalAddress values in the system.
 */
export function canonicalizeAddress(components: AddressComponents): string {
  const streetNum = components.streetNumber.trim();
  const routeParts = components.route.trim().split(' ').filter(Boolean);

  // Normalize street type
  if (routeParts.length > 0) {
    const lastWord = routeParts[routeParts.length - 1].toLowerCase();
    if (STREET_TYPE_ABBREVIATIONS[lastWord]) {
      routeParts[routeParts.length - 1] = STREET_TYPE_ABBREVIATIONS[lastWord];
    }
  }

  const routeStr = routeParts.map((p, i) => i === routeParts.length - 1 ? (STREET_TYPE_ABBREVIATIONS[p.toLowerCase()] || titleCase(p)) : titleCase(p)).join(' ');

  let streetStr = `${streetNum} ${routeStr}`;

  let unitStr = '';
  if (components.unitNumber) {
    let unit = components.unitNumber.trim();
    // basic splitting to separate prefix and number if they are in one string
    let unitParts = unit.split(' ').filter(Boolean);
    if (unitParts.length === 1) {
      if (unit.toLowerCase().startsWith('apt') && unit.length > 3) {
         unitParts = ['Apt', unit.slice(3).replace(/^[\.\s]+/, '')];
      } else if (unit.toLowerCase().startsWith('ste') && unit.length > 3) {
         unitParts = ['Ste', unit.slice(3).replace(/^[\.\s]+/, '')];
      } else if (unit.startsWith('#')) {
         unitParts = ['#', unit.slice(1)];
      } else if (/^\d+/.test(unit)) {
         unitParts = ['Unit', unit]; // just a number
      }
    }

    if (unitParts.length > 0) {
      const firstWord = unitParts[0].toLowerCase();
      if (UNIT_TYPE_ABBREVIATIONS[firstWord]) {
         unitParts[0] = UNIT_TYPE_ABBREVIATIONS[firstWord];
      } else if (unitParts.length === 1 && !UNIT_TYPE_ABBREVIATIONS[firstWord] && !/^\d+/.test(firstWord)) {
         // keep it as is, likely just single word like "Basement"
      } else if (unitParts.length === 1 && /^\d+/.test(firstWord)) {
         unitParts = ['Unit', firstWord];
      }
      unitStr = ' ' + unitParts.map((p, i) => i === 0 ? titleCase(p) : p.toUpperCase()).join(' ');
    }
  }

  const city = titleCase(components.city.trim());
  const state = components.state.trim().toUpperCase();

  // Trim zip
  let zip = components.zip.trim();
  if (zip.length > 5) {
    const zipMatch = zip.match(/^(\d{5})[- ]?(\d{4})?/);
    if (zipMatch) {
      zip = zipMatch[2] ? `${zipMatch[1]}-${zipMatch[2]}` : zipMatch[1];
    }
  }

  return `${streetStr}${unitStr}, ${city}, ${state} ${zip}`;
}

/**
 * Generates a URL-safe deal slug from a canonical address.
 * Collision-suffixed deterministically.
 */
export function generateDealSlug(
  canonicalAddress: string,
  existingSlugs: string[]
): string {
  // 1. Remove ZIP (everything after last comma+space+state)
  // "123 Main St Apt 2, Miami, FL 33101" -> "123 Main St Apt 2, Miami, FL"
  let slugBase = canonicalAddress;
  const parts = canonicalAddress.split(',');
  if (parts.length >= 2) {
    const lastPart = parts[parts.length - 1].trim();
    const stateZipParts = lastPart.split(' ').filter(Boolean);
    if (stateZipParts.length >= 2) {
       // Assuming format is State Zip, remove the zip part
       const state = stateZipParts[0];
       parts[parts.length - 1] = ' ' + state;
       slugBase = parts.join(',');
    }
  }

  // 2. Lowercase
  let slug = slugBase.toLowerCase();

  // 3. Replace commas with nothing
  slug = slug.replace(/,/g, '');

  // 4. Replace spaces with hyphens
  slug = slug.replace(/\s+/g, '-');

  // 5. Strip non-alphanumeric except hyphens
  slug = slug.replace(/[^a-z0-9\-]/g, '');

  // 6. Dedupe consecutive hyphens
  slug = slug.replace(/-+/g, '-');

  // Remove trailing or leading hyphens
  slug = slug.replace(/^-|-$/g, '');

  // 7. & 8. Check collision and append "-2", "-3" etc.
  let finalSlug = slug;
  let counter = 2;
  while (existingSlugs.includes(finalSlug)) {
    finalSlug = `${slug}-${counter}`;
    counter++;
  }

  return finalSlug;
}

import { getRegistryField } from '@/lib/metrics/acquisitionVariableRegistry';
import type { Project, VariableSourceTag } from '@/types/schema';

/**
 * Resolves the provenance (source tag) for a given registry field ID on a project.
 * Falls back to registry default if not explicitly defined in project document.
 */
export function getVariableProvenance(
  fieldId: string,
  project: Project,
  slot?: 'projected' | 'actual'
): VariableSourceTag {
  // 1. Check project-level sourceTags map
  const financials = project.financials || {};
  const sourceTags = (financials.sourceTags || {}) as Record<string, string>;

  // Look up slot-specific tag first (e.g. purchasePrice_projected, purchasePrice_actual)
  if (slot) {
    const slotKey = `${fieldId}_${slot}`;
    if (sourceTags[slotKey]) {
      return sourceTags[slotKey] as VariableSourceTag;
    }
  }

  if (sourceTags[fieldId]) {
    return sourceTags[fieldId] as VariableSourceTag;
  }

  // Fallback to slot suffixes if slot is not specified
  if (!slot) {
    const projectedKey = `${fieldId}_projected`;
    if (sourceTags[projectedKey]) {
      return sourceTags[projectedKey] as VariableSourceTag;
    }
    const actualKey = `${fieldId}_actual`;
    if (sourceTags[actualKey]) {
      return sourceTags[actualKey] as VariableSourceTag;
    }
  }

  // 2. Fall back to registry default
  const regField = getRegistryField(fieldId);
  if (regField) {
    return regField.defaultSourceTag;
  }

  // Default to user_assumption if all else fails
  return 'user_assumption';
}

/**
 * Calculates a coverage-based deal completeness indicator.
 * Scans the project for required variables and returns the percentage filled.
 */
export function calculateDealCompleteness(project: Project): {
  score: number;
  total: number;
  filled: number;
  missing: string[];
} {
  const financials = project.financials || {};

  // Check if financed
  const modality = project.fundingPlan?.modality || [];
  const isFinanced =
    modality.some((m) =>
      ['conventional_loan', 'sba_504', 'hard_money', 'bridge'].includes(m)
    ) ||
    (project.loans && project.loans.length > 0) ||
    (financials.capitalStack || []).some((s: any) =>
      [
        'Conventional Financing',
        'Hard Money Loans',
        'SBA 504 Bank First Lien',
        'SBA 504 CDC Debenture',
        'Bridge Loans',
      ].includes(s.category)
    );

  // List of required underwriting variables and check functions
  const checks: Array<{ name: string; key: string; isFilled: () => boolean }> = [
    {
      name: 'Purchase Price',
      key: 'purchase_price',
      isFilled: () => {
        const p = financials.purchasePrice || financials.targetPurchasePrice;
        return typeof p === 'number' && p > 0;
      },
    },
    {
      name: 'Monthly Gross Rent',
      key: 'gross_rent_per_unit',
      isFilled: () => {
        const r = financials.gross_rent_per_unit || financials.actualRentalIncome;
        return typeof r === 'number' && r > 0;
      },
    },
    {
      name: 'Vacancy Rate %',
      key: 'vacancy_pct',
      isFilled: () => {
        const v = financials.vacancy_pct;
        return typeof v === 'number' && v >= 0;
      },
    },
    {
      name: 'Taxes',
      key: 'tax',
      isFilled: () => {
        const t = financials.tax;
        return typeof t === 'number' && t >= 0;
      },
    },
    {
      name: 'Insurance',
      key: 'insurance',
      isFilled: () => {
        const i = financials.insurance;
        return typeof i === 'number' && i >= 0;
      },
    },
    {
      name: 'Utilities',
      key: 'utilities',
      isFilled: () => {
        const u = financials.utilities;
        return typeof u === 'number' && u >= 0;
      },
    },
    {
      name: 'Property Mgmt Fee',
      key: 'management_pct',
      isFilled: () => {
        const m = financials.management_pct;
        return typeof m === 'number' && m >= 0;
      },
    },
    {
      name: 'Maintenance Reserve',
      key: 'maintenance',
      isFilled: () => {
        const mt = financials.maintenance || financials.maintenance_pct;
        return typeof mt === 'number' && mt >= 0;
      },
    },
    {
      name: 'Funding Target',
      key: 'funding_target',
      isFilled: () => {
        const f = financials.equityTerms?.funding_target;
        return typeof f === 'number' && f > 0;
      },
    },
  ];

  // If financed, append loan terms
  if (isFinanced) {
    checks.push(
      {
        name: 'Loan Amount',
        key: 'loan_amount',
        isFilled: () => {
          const l = financials.loanAmount || financials.targetLoanAmount || (project.loans && project.loans.length > 0);
          return !!l;
        },
      },
      {
        name: 'Loan Interest Rate',
        key: 'loan_interest_rate',
        isFilled: () => {
          const r = financials.loanInterestRate || financials.targetLoanInterestRate || (project.loans && project.loans.length > 0);
          return !!r;
        },
      },
      {
        name: 'Loan Term',
        key: 'loan_term',
        isFilled: () => {
          const t = financials.loanTermYears || financials.targetLoanTermYears || (project.loans && project.loans.length > 0);
          return !!t;
        },
      }
    );
  }

  const missing: string[] = [];
  let filled = 0;

  checks.forEach((c) => {
    if (c.isFilled()) {
      filled++;
    } else {
      missing.push(c.name);
    }
  });

  const total = checks.length;
  const score = total > 0 ? Math.round((filled / total) * 100) : 0;

  return { score, total, filled, missing };
}

import type { Project, PropertyMetricSnapshot } from '@/types/schema';
import { 
  deriveAllMetrics, 
  computeNOIComponents, 
  computeTotalCashInvested, 
