      value: `$${totalFees.toLocaleString()}`,
      rawValue: totalFees,
      unit: '$',
      trend: 'up',
      benchmark: '$25,000 / qtr',
      category: 'Financial Metrics',
    },
    {
      id: 'kpi_marcus_avg_assignment_fee',
      name: 'Average Assignment Fee',
      value: `$${avgFee.toLocaleString()}`,
      rawValue: avgFee,
      unit: '$',
      trend: 'up',
      benchmark: '$8,000 / deal',
      category: 'Financial Metrics',
