export type DealActivityType =
  | 'invite'
  | 'open'
  | 'question'
  | 'answer'
  | 'decline'
  | 'interest'
  | 'exchange'
  | 'indication'
  | 'edit'
  | 'republish'
  | 'mode_change';

export interface DealActivity {
  id: string;
  projectId: string;
  dealId: string;
  actorUid: string;
  type: DealActivityType;
  metadata: {
    inviteeEmail?: string;
    inviteeName?: string;
    questionText?: string;
    answerText?: string;
    amountCents?: number;
    oldVisibilityMode?: string;
    newVisibilityMode?: string;
    editSummary?: string;
    [key: string]: any;
  };
  createdAt: any;
}

/**
 * Persists an application-level deal activity timeline event.
 */
export async function trackDealActivity(
  projectId: string,
  dealId: string,
  actorUid: string,
  type: DealActivityType,
  metadata: Record<string, any> = {}
): Promise<string> {
  try {
    const docRef = adminDb.collection('dealActivityTimeline').doc();
    const entry = {
      id: docRef.id,
      projectId,
      dealId,
      actorUid,
      type,
      metadata,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
    };
    await docRef.set(entry);
    return docRef.id;
  } catch (err: any) {
    console.error('[trackDealActivity Error]', err.message);
    return '';
  }
}

/**
 * Filter timeline activities securely based on viewer identity and role.
 */
export async function filterTimelineForUser(
  activities: DealActivity[],
  viewerUid: string,
  viewerEmail: string,
  isLeadInvestorOrTeammate: boolean
): Promise<DealActivity[]> {
  if (isLeadInvestorOrTeammate) {
    return activities;
  }

  // Retrieve any claimed emails to authorize view of historical records
  const userSnap = await adminDb.collection('users').doc(viewerUid).get();
  const claimedEmails: string[] = userSnap.exists ? (userSnap.data()?.claimedEmails || []) : [];

  const lowerEmail = viewerEmail.toLowerCase().trim();
  const allUserEmails = [lowerEmail, ...claimedEmails.map(e => e.toLowerCase().trim())].filter(Boolean);

  const GENERAL_TYPES = new Set<DealActivityType>(['edit', 'republish', 'mode_change']);

  return activities.filter((act) => {
    // 1. General events (deal listing edits, republished, mode changes) are safe to show
    if (GENERAL_TYPES.has(act.type)) {
      return true;
    }

    // 2. Otherwise, check if user is the direct actor or invitee subject
    if (act.actorUid === viewerUid) {
      return true;
    }

    const inviteeEmail = act.metadata?.inviteeEmail?.toLowerCase().trim();
    if (inviteeEmail && allUserEmails.includes(inviteeEmail)) {
      return true;
    }

    return false;
  });
}

import { adminDb } from '@/lib/firebase/admin';
import type { PlaceIdRefreshResult, Property } from '@/types/propertyTypes';
import { PLACE_ID_REFRESH_INTERVAL_MS, COORDINATE_TTL_MS } from '@/types/propertyTypes';
import { telemetry } from '@/lib/telemetry';

/**
 * Refreshes placeId and coordinates for properties older than 12 months.
 * Processes in batches to respect Google API rate limits.
 * Billed to 'id-refresh' SKU.
 */
export async function refreshStaleProperties(options?: {
  batchSize?: number;  // Default 50
  dryRun?: boolean;    // If true, report but don't update
}): Promise<PlaceIdRefreshResult> {
  const batchSize = options?.batchSize || 50;
  const dryRun = options?.dryRun ?? false;

  const now = Date.now();
  const cutoff = now - PLACE_ID_REFRESH_INTERVAL_MS;

  const snapshot = await adminDb
    .collection('properties')
    .where('placeIdVerifiedAt', '<', cutoff)
    .limit(batchSize)
    .get();

  const result: PlaceIdRefreshResult = {
    processed: 0,
    refreshed: 0,
    deprecated: 0,
    failed: 0,
    errors: []
  };

  if (snapshot.empty) {
    return result;
  }

  const PLACES_API_KEY = process.env.GOOGLE_PLACES_API_KEY;

  if (!PLACES_API_KEY) {
    throw new Error('Google API key not configured');
  }

  for (const doc of snapshot.docs) {
    const property = doc.data() as Property;
    result.processed++;

    try {
      const url = `https://places.googleapis.com/v1/places/${property.placeId}`;
      const response = await fetch(url, {
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': PLACES_API_KEY,
          'X-Goog-FieldMask': 'id,location'
        }
      });

      if (!response.ok) {
        throw new Error(`Places API returned ${response.status}`);
      }

      const data = await response.json();
      const newPlaceId = data.id;
      const lat = data.location?.latitude;
      const lng = data.location?.longitude;

      if (!newPlaceId || lat == null || lng == null) {
        throw new Error('Invalid response from Places API');
      }

      const isDeprecated = newPlaceId !== property.placeId;

      if (!dryRun) {
        const updateData: Partial<Property> = {
          placeIdVerifiedAt: now,
          updatedAt: new Date()
        };

        if (isDeprecated) {
          updateData.placeId = newPlaceId;

          // Update all referencing projects
          const projectsQuery = await adminDb
            .collection('projects')
            .where('propertyId', '==', property.id)
            .get();

          if (!projectsQuery.empty) {
            const batch = adminDb.batch();
            projectsQuery.docs.forEach(pDoc => {
              batch.update(pDoc.ref, { placeId: newPlaceId });
            });
            await batch.commit();
          }
        }

        updateData.coordinates = {
          lat,
          lng,
          cachedAt: now,
          expiresAt: now + COORDINATE_TTL_MS
        };

        await doc.ref.update(updateData);
      }

      if (isDeprecated) {
        result.deprecated++;
      } else {
        result.refreshed++;
      }

      telemetry.capture({
        distinctId: 'system-job',
        event: 'place_id_refreshed',
        properties: {
          sku: 'id-refresh',
          propertyId: property.id,
          deprecated: isDeprecated
        }
      });

    } catch (error: any) {
      result.failed++;
      result.errors.push({ propertyId: property.id, error: error.message });
    }
  }

  return result;
}

/* ═══════════════════════════════════════════════════════
   PaperWorking — Obfuscation Engine (AQ-27)

   Single config object + pure functions that transform
   a full DealListing into a public DealListingTeaser.
   This is the ONE place that controls what non-subscribers
   see. No full address, no exact terms, no documents.
   ═══════════════════════════════════════════════════════ */

import type { DealListing, DealListingTeaser, ObfuscationMap } from '@/types/listing';

// ── The Config Object ────────────────────────────────────
// One object governs all obfuscation. Change this to
// adjust what the public teaser reveals.
export const OBFUSCATION_MAP: ObfuscationMap = {
  address:             { strategy: 'neighborhood' },
  capRate:             { strategy: 'range', bandPct: 1 },
  cashOnCash:          { strategy: 'range', bandPct: 2 },
  projectedROI:        { strategy: 'range', bandPct: 5 },
  askingPriceCents:    { strategy: 'approximate' },
  fundingTarget:       { strategy: 'approximate' },
  minTicket:           { strategy: 'approximate' },
  equityOfferedPct:    { strategy: 'hidden' },
  documents:           { strategy: 'hidden' },
  leadInvestorContact: { strategy: 'hidden' },
  terms:               { strategy: 'summary' },
} as const;

// ── Pure Helpers ─────────────────────────────────────────

/**
 * Rounds a percentage to the nearest band and returns a range string.
 * Example: obfuscateRange(4.73, 1) → "4–5%"
 */
export function obfuscateRange(value: number | undefined, bandPct: number): string | undefined {
  if (value == null || isNaN(value)) return undefined;
  const low = Math.floor(value / bandPct) * bandPct;
  const high = low + bandPct;
  return `${low}–${high}%`;
}

/**
 * Rounds cents to a human-friendly approximate string.
 * Example: obfuscateApproximate(9750000) → "~$100K"
 *          obfuscateApproximate(125000000) → "~$1.3M"
 */
export function obfuscateApproximate(cents: number | undefined): string | undefined {
  if (cents == null || isNaN(cents)) return undefined;
  const dollars = cents / 100;

  if (dollars >= 1_000_000) {
    const millions = Math.round(dollars / 100_000) / 10; // one decimal
    return `~$${millions}M`;
  }
  if (dollars >= 1_000) {
    const thousands = Math.round(dollars / 1_000) * 1_000;
    if (thousands >= 1_000_000) {
      return `~$${(thousands / 1_000_000).toFixed(1)}M`;
    }
    return `~$${(thousands / 1_000).toFixed(0)}K`;
  }
  // Below $1K — just round to nearest $100
  const rounded = Math.round(dollars / 100) * 100;
  return `~$${rounded}`;
}

/**
 * Builds a DealListingTeaser from a full DealListing.
 * This is the ONLY function that should produce teaser data.
 * It strips all sensitive fields and applies the obfuscation map.
 */
export function buildTeaserFromListing(listing: DealListing): DealListingTeaser {
  const map = OBFUSCATION_MAP;

  // Single headline figure: asking price if available, otherwise funding target
  const headlinePrice = obfuscateApproximate(listing.askingPriceCents);
  const headlineFunding = listing.equityTerms?.fundingTarget
    ? `Seeking ${obfuscateApproximate(listing.equityTerms.fundingTarget)}`
    : undefined;

  return {
    id: listing.id,
    projectId: listing.projectId,
    propertyId: listing.propertyId,
    placeId: listing.placeId,
    status: listing.status,

    // Location — city and state (no full street address)
    propertyName: listing.propertyName,
    neighborhood: listing.neighborhood || `${listing.city}, ${listing.state}`,
    city: listing.city,
    state: listing.state,
    assetClass: listing.assetClass,
    subStrategy: listing.subStrategy,
    latitude: listing.latitude,
    longitude: listing.longitude,

    // ONE Headline Figure (Asking price or Raise target)
    askingPriceApprox: headlinePrice,
    fundingTargetApprox: !headlinePrice ? headlineFunding : undefined,

    // Gated fields — suppressed from public teaser payload
    capRateRange: undefined,
    cashOnCashRange: undefined,
    projectedROIRange: undefined,
    minTicketApprox: undefined,
    leadInvestorName: 'Lead Investor', // Generic label; lister identity gated behind auth

    // Counters
    followCount: listing.followCount,
    viewCount: listing.viewCount,

    // Timestamps
    publishedAt: listing.publishedAt,
    isCrowdfunding: listing.isCrowdfunding ?? false,
  };
}

const PII_KEYS = new Set([
  'email',
  'password',
  'ssn',
  'taxid',
  'card',
  'bank',
  'address',
  'phone',
  'phonenumber',
  'street',
  'city',
  'state',
  'zipcode',
  'zip',
  'fullname',
  'name',
]);

function redactPII(obj: any): any {
  if (obj === null || obj === undefined) return obj;
  if (typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) {
    return obj.map(redactPII);
  }

  const redacted: any = {};
  for (const [key, val] of Object.entries(obj)) {
    if (PII_KEYS.has(key.toLowerCase())) {
      redacted[key] = '[REDACTED]';
    } else if (typeof val === 'object') {
      redacted[key] = redactPII(val);
    } else {
      redacted[key] = val;
    }
  }
  return redacted;
}

interface LogContext {
  userId?: string;
  traceId?: string;
  projectId?: string;
  [key: string]: any;
}

class StructuredLogger {
  private formatLog(level: 'DEBUG' | 'INFO' | 'WARN' | 'ERROR', message: string, context?: LogContext) {
    const payload = {
      timestamp: new Date().toISOString(),
      level,
      message,
      ...(context ? redactPII(context) : {}),
    };
    return JSON.stringify(payload);
  }

  debug(message: string, context?: LogContext) {
    if (process.env.NODE_ENV !== 'production' || process.env.LOG_LEVEL === 'debug') {
      console.log(this.formatLog('DEBUG', message, context));
    }
  }

  info(message: string, context?: LogContext) {
    console.log(this.formatLog('INFO', message, context));
  }

  warn(message: string, context?: LogContext) {
    console.warn(this.formatLog('WARN', message, context));
  }

  error(message: string, error?: Error | unknown, context?: LogContext) {
    const errObj = error instanceof Error 
      ? { errorName: error.name, errorMessage: error.message, errorStack: error.stack }
      : { rawError: error };

    console.error(
      this.formatLog('ERROR', message, {
        ...errObj,
        ...context,
      })
    );
  }
}

export const logger = new StructuredLogger();

import Stripe from 'stripe';
import { z } from 'zod';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY || '', {
  // @ts-ignore - using latest api version
  apiVersion: '2026-03-25.dahlia',
  timeout: 30000,
  maxNetworkRetries: 3,
});

/**
 * PaperWorking Stripe MCP Tools
 */

export const verify_subscription = {
  name: 'verify_subscription',
  description: 'Verify the subscription tier and status for a specific customer.',
  schema: z.object({
    customerId: z.string().describe('The Stripe Customer ID.'),
  }),
  handler: async ({ customerId }: { customerId: string }) => {
    try {
      const subscriptions = await stripe.subscriptions.list({
        customer: customerId,
        status: 'active',
        limit: 1,
      });

      if (subscriptions.data.length === 0) {
        return {
          content: [{ type: 'text', text: 'No active subscription found.' }]
        };
      }

      const sub = subscriptions.data[0];
      const planName = sub.items.data[0]?.price?.nickname || 'Standard';
      const amount = sub.items.data[0]?.price?.unit_amount || 0;

      return {
        content: [{ 
          type: 'text', 
          text: `Active Subscription: ${planName} ($${(amount / 100).toFixed(2)}/mo). Status: ${sub.status}.` 
        }]
      };
    } catch (error: any) {
      return {
        content: [{ type: 'text', text: `Failed to verify subscription: ${error.message}` }]
      };
    }
  }
};

/**
 * Golden test — runs all 10 metric wrappers against a realistic seed project
 * and asserts values match the underlying reiMetrics engine.
 *
 * The SEED_PROJECT fixture mirrors a typical rental property analysis.
 * Expected values are derived by calling deriveAllMetrics() directly
 * and using its outputs as golden reference values.
 */

import { deriveAllMetrics, computeTotalCashInvested, computeAnnualDebtService } from '../reiMetrics';
import { computeNOIMetric } from '../computeNOI';
import { computeCashFlowMetric } from '../computeCashFlow';
import { computeCapRateMetric } from '../computeCapRate';
