/**
 * whatChanged tests — verifies that modifying specific fields
 * triggers the correct set of metric recomputations.
 */

import { whatChanged, METRIC_DEPENDENCIES } from '../whatChanged';
import type { MetricId } from '../types';

const BASE_PROJECT = {
  financials: {
    purchasePrice: 200000,
    estimatedARV: 250000,
    monthlyGrossRent: 2000,
    vacancyRatePercent: 5,
    holdingCostTaxes: 200,
    holdingCostInsurance: 100,
    monthlyMaintenanceReserve: 50,
    propertyManagementFeePercent: 10,
    loanAmount: 160000,
    loanInterestRate: 7,
    loanTermYears: 30,
    projectedRehabCost: 20000,
    fixedAcquisitionCosts: 5000,
    projectedHoldTimeMonths: 60,
    annualAppreciationPercent: 3,
    numberOfUnits: 1,
    occupiedUnits: 1,
  },
  dispositionType: 'RENT',
  subStrategy: 'LONG_TERM',
  currentPhase: 1,
};

function clone(obj: any) {
  return JSON.parse(JSON.stringify(obj));
}

describe('whatChanged', () => {
  test('identical projects → no changes', () => {
    const result = whatChanged(BASE_PROJECT, clone(BASE_PROJECT));
    expect(result).toHaveLength(0);
  });

  test('changing rent triggers NOI, CASH_FLOW, CAP_RATE, COC, GRM, DSCR, IRR, OER', () => {
    const after = clone(BASE_PROJECT);
    after.financials.monthlyGrossRent = 2500;

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('NOI');
    expect(changed).toContain('CASH_FLOW');
    expect(changed).toContain('CAP_RATE');
    expect(changed).toContain('COC');
    expect(changed).toContain('GRM');
    expect(changed).toContain('DSCR');
    expect(changed).toContain('IRR');
    expect(changed).toContain('OER');
    // OCCUPANCY and APPRECIATION should NOT be affected
    expect(changed).not.toContain('OCCUPANCY');
    expect(changed).not.toContain('APPRECIATION');
  });

  test('changing purchase price triggers CAP_RATE, COC, GRM, IRR, APPRECIATION', () => {
    const after = clone(BASE_PROJECT);
    after.financials.purchasePrice = 220000;

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('CAP_RATE');
    expect(changed).toContain('COC');
    expect(changed).toContain('IRR');
    expect(changed).toContain('APPRECIATION');
  });

  test('changing loan amount triggers CASH_FLOW, COC, DSCR, IRR', () => {
    const after = clone(BASE_PROJECT);
    after.financials.loanAmount = 180000;

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('CASH_FLOW');
    expect(changed).toContain('COC');
    expect(changed).toContain('DSCR');
    expect(changed).toContain('IRR');
  });

  test('changing vacancy triggers NOI, CASH_FLOW, CAP_RATE, COC, DSCR, OER, OCCUPANCY', () => {
    const after = clone(BASE_PROJECT);
    after.financials.vacancyRatePercent = 10;

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('NOI');
    expect(changed).toContain('CASH_FLOW');
    expect(changed).toContain('CAP_RATE');
    expect(changed).toContain('OCCUPANCY');
    expect(changed).toContain('OER');
  });

  test('changing dispositionType triggers multiple metrics', () => {
    const after = clone(BASE_PROJECT);
    after.dispositionType = 'SALE';

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('NOI');
    expect(changed).toContain('OCCUPANCY');
  });

  test('changing ARV triggers GRM and APPRECIATION', () => {
    const after = clone(BASE_PROJECT);
    after.financials.estimatedARV = 300000;

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('GRM');
    expect(changed).toContain('APPRECIATION');
  });

  test('changing numberOfUnits triggers only OCCUPANCY', () => {
    const after = clone(BASE_PROJECT);
    after.financials.numberOfUnits = 4;

    const changed = whatChanged(BASE_PROJECT, after);

    expect(changed).toContain('OCCUPANCY');
    // Should not trigger financial metrics
    expect(changed).not.toContain('NOI');
    expect(changed).not.toContain('CASH_FLOW');
  });

  test('METRIC_DEPENDENCIES covers all 10 metrics', () => {
    const ids: MetricId[] = ['NOI', 'CASH_FLOW', 'CAP_RATE', 'COC', 'GRM', 'DSCR', 'IRR', 'OCCUPANCY', 'OER', 'APPRECIATION'];
    for (const id of ids) {
      expect(METRIC_DEPENDENCIES[id]).toBeDefined();
      expect(METRIC_DEPENDENCIES[id]!.length).toBeGreaterThan(0);
    }
  });
});

/**
 * D10 — Annualized Appreciation Rate wrapper.
 * CAGR = ((EndValue / Basis) ^ (1/Years)) - 1.
 * Delegates to reiMetrics.computeAnnualizedAppreciationRate.
 *
 * NOTE: This wrapper mirrors the logic in deriveAllMetrics for how yearsHeld
 * and currentOrSaleValue are resolved. It uses projectedHoldTimeMonths as
 * the hold period when no acquisition date is present (evaluation mode).
 */

import type { MetricResult } from './types';
import { computeAnnualizedAppreciationRate, computeYearsHeld } from './reiMetrics';
import { resolveState, incomplete, num, parseDate } from './helpers';

export interface AppreciationProjectInput {
  financials?: {
    purchasePrice?: number;
    targetPrice?: number;
    targetPurchasePrice?: number;
    fixedAcquisitionCosts?: number;
    estimatedARV?: number;
    estimatedCurrentValue?: number;
    projectedSalePrice?: number;
    actualSalePrice?: number;
    soldDate?: any;
    acquisitionDate?: any;
    projectedHoldTimeMonths?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  createdAt?: any;
  [key: string]: any;
}

export function computeAppreciationMetric(project: AppreciationProjectInput): MetricResult {
  const fin = project.financials;

  const purchasePrice = num(fin?.purchasePrice) ?? num(fin?.targetPrice) ?? num(fin?.targetPurchasePrice);
  if (purchasePrice === undefined || purchasePrice === 0) {
    return incomplete(['financials.purchasePrice']);
  }

  const fixedAcquisitionCosts = num(fin?.fixedAcquisitionCosts) ?? 0;

  // Determine end value
  const isRealized = fin?.soldDate != null && fin?.actualSalePrice != null && (num(fin?.actualSalePrice) ?? 0) > 0;
  const currentOrSaleValue = isRealized
    ? num(fin?.actualSalePrice) ?? 0
    : (num(fin?.projectedSalePrice) ?? num(fin?.estimatedCurrentValue) ?? num(fin?.estimatedARV) ?? purchasePrice);

  if (currentOrSaleValue <= 0) {
    return incomplete(['financials.estimatedARV or financials.actualSalePrice']);
  }

  // Determine hold period using exact same logic as deriveAllMetrics
  let yearsHeld = computeYearsHeld(
    fin?.acquisitionDate,
    isRealized ? fin?.soldDate : null,
    project.createdAt
  );

  const parsedAcqDate = parseDate(fin?.acquisitionDate);
  const elapsedDays = parsedAcqDate && !isRealized
    ? (new Date().getTime() - parsedAcqDate.getTime()) / (1000 * 60 * 60 * 24)
    : 0;

  if (!isRealized && elapsedDays < 30) {
    yearsHeld = Math.max(1, (num(fin?.projectedHoldTimeMonths) ?? 60) / 12);
  }

  const rate = computeAnnualizedAppreciationRate(
    purchasePrice,
    fixedAcquisitionCosts,
    currentOrSaleValue,
    yearsHeld,
  );

  return {
    value: rate,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.purchasePrice': purchasePrice,
      'financials.fixedAcquisitionCosts': fixedAcquisitionCosts,
      'financials.currentOrSaleValue': currentOrSaleValue,
      'financials.yearsHeld': yearsHeld,
    },
    inputsMissing: [],
  };
}

/**
 * D3 — Capitalization Rate wrapper.
 * CapRate = NOI / PurchasePrice × 100.
 * Delegates to reiMetrics.computeCapRate.
 */

import type { MetricResult } from './types';
import { computeNOI, computeCapRate } from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface CapRateProjectInput {
  financials?: {
    purchasePrice?: number;
    targetPrice?: number;
    targetPurchasePrice?: number;
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    netOperatingIncome?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeCapRateMetric(project: CapRateProjectInput): MetricResult {
  const fin = project.financials;
  const missing: string[] = [];

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  const hasPrecomputedNOI = fin?.netOperatingIncome != null;

  if (!hasPrecomputedNOI && (rent === undefined || rent === 0)) {
    missing.push('financials.monthlyGrossRent');
  }

  const purchasePrice = num(fin?.purchasePrice) ?? num(fin?.targetPrice) ?? num(fin?.targetPurchasePrice);
  if (purchasePrice === undefined || purchasePrice === 0) {
    missing.push('financials.purchasePrice');
  }

  if (missing.length > 0) return incomplete(missing);

  const noi = computeNOI(fin as any, project.dispositionType, project.currentPhase);
  const capRate = computeCapRate(noi, purchasePrice!);

  const inputsUsed: Record<string, number> = {
    'financials.purchasePrice': purchasePrice!,
  };
  if (rent !== undefined) inputsUsed['financials.monthlyGrossRent'] = rent;
  if (hasPrecomputedNOI) inputsUsed['financials.netOperatingIncome'] = fin!.netOperatingIncome!;

  return {
    value: capRate,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D2 — Cash Flow wrapper.
 * CashFlow = NOI − Annual Debt Service.
 * Delegates to reiMetrics.computeNOI + computeAnnualDebtService + computeCashFlow.
 */

import type { MetricResult } from './types';
import {
  computeNOI,
  computeAnnualDebtService,
  computeCashFlow,
} from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface CashFlowProjectInput {
  financials?: {
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    netOperatingIncome?: number;
    loanAmount?: number;
    loanInterestRate?: number;
    loanTermYears?: number;
    financingType?: string;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeCashFlowMetric(project: CashFlowProjectInput): MetricResult {
  const fin = project.financials;

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  const hasPrecomputedNOI = fin?.netOperatingIncome != null;

  if (!hasPrecomputedNOI && (rent === undefined || rent === 0)) {
    return incomplete(['financials.monthlyGrossRent']);
  }

  const noi = computeNOI(fin as any, project.dispositionType, project.currentPhase);

  // Debt service — zero for all-cash deals
  const loanAmount = num(fin?.loanAmount) ?? 0;
  const loanRate = num(fin?.loanInterestRate) ?? 0;
  const loanTermYears = num(fin?.loanTermYears) ?? 30;
  const annualDS = computeAnnualDebtService(loanAmount, loanRate, loanTermYears * 12);

  const { annual } = computeCashFlow(noi, annualDS);

  const inputsUsed: Record<string, number> = {};
  if (rent !== undefined) inputsUsed['financials.monthlyGrossRent'] = rent;
  if (hasPrecomputedNOI) inputsUsed['financials.netOperatingIncome'] = fin!.netOperatingIncome!;
  if (loanAmount > 0) {
    inputsUsed['financials.loanAmount'] = loanAmount;
    inputsUsed['financials.loanInterestRate'] = loanRate;
    inputsUsed['financials.loanTermYears'] = loanTermYears;
  }

  return {
    value: annual,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D4 — Cash-on-Cash Return wrapper.
 * CoC = AnnualCashFlow / TotalCashInvested × 100.
 * Delegates to reiMetrics.computeCoCReturn + computeTotalCashInvested.
 */

import type { MetricResult } from './types';
import {
  computeNOI,
  computeAnnualDebtService,
  computeCashFlow,
  computeTotalCashInvested,
  computeCoCReturn,
} from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface CoCProjectInput {
  financials?: {
    purchasePrice?: number;
    targetPrice?: number;
    targetPurchasePrice?: number;
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    netOperatingIncome?: number;
    loanAmount?: number;
    loanInterestRate?: number;
    loanTermYears?: number;
    fixedAcquisitionCosts?: number;
    emdAmount?: number;
    projectedRehabCost?: number;
    holdingCostTaxes?: number;
    holdingCostInsurance?: number;
    holdingCostUtilities?: number;
    projectedHoldTimeMonths?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeCoCMetric(project: CoCProjectInput): MetricResult {
  const fin = project.financials;
  const missing: string[] = [];

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  const hasPrecomputedNOI = fin?.netOperatingIncome != null;

  if (!hasPrecomputedNOI && (rent === undefined || rent === 0)) {
    missing.push('financials.monthlyGrossRent');
  }

  const purchasePrice = num(fin?.purchasePrice) ?? num(fin?.targetPrice) ?? num(fin?.targetPurchasePrice);
  if (purchasePrice === undefined || purchasePrice === 0) {
    missing.push('financials.purchasePrice');
  }

  if (missing.length > 0) return incomplete(missing);

  const noi = computeNOI(fin as any, project.dispositionType, project.currentPhase);

  const loanAmount = num(fin?.loanAmount) ?? 0;
  const loanRate = num(fin?.loanInterestRate) ?? 0;
  const loanTermYears = num(fin?.loanTermYears) ?? 30;
  const annualDS = computeAnnualDebtService(loanAmount, loanRate, loanTermYears * 12);

  const { annual: annualCashFlow } = computeCashFlow(noi, annualDS);
  const totalCashInvested = computeTotalCashInvested(fin as any);

  if (totalCashInvested === 0) {
    return incomplete(['financials.purchasePrice (totalCashInvested is 0)']);
  }

  const coc = computeCoCReturn(annualCashFlow, totalCashInvested);

  const inputsUsed: Record<string, number> = {
    'financials.purchasePrice': purchasePrice!,
    'financials.totalCashInvested': totalCashInvested,
  };
  if (rent !== undefined) inputsUsed['financials.monthlyGrossRent'] = rent;
  if (loanAmount > 0) inputsUsed['financials.loanAmount'] = loanAmount;

  return {
    value: coc,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D6 — Debt Service Coverage Ratio wrapper.
 * DSCR = NOI / AnnualDebtService.
 * Returns n/a for all-cash deals (no debt).
 * Delegates to reiMetrics.computeDSCR.
 */

import type { MetricResult } from './types';
import {
  computeNOI,
  computeAnnualDebtService,
  computeDSCR,
} from './reiMetrics';
import { resolveState, incomplete, notApplicable, num } from './helpers';

export interface DSCRProjectInput {
  financials?: {
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    netOperatingIncome?: number;
    loanAmount?: number;
    loanInterestRate?: number;
    loanTermYears?: number;
    financingType?: string;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeDSCRMetric(project: DSCRProjectInput): MetricResult {
  const fin = project.financials;

  // All-cash → DSCR not applicable
  const loanAmount = num(fin?.loanAmount) ?? 0;
  if (loanAmount === 0 || fin?.financingType === 'All Cash') {
    return notApplicable();
  }

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  const hasPrecomputedNOI = fin?.netOperatingIncome != null;

  if (!hasPrecomputedNOI && (rent === undefined || rent === 0)) {
    return incomplete(['financials.monthlyGrossRent']);
  }

  const noi = computeNOI(fin as any, project.dispositionType, project.currentPhase);
  const loanRate = num(fin?.loanInterestRate) ?? 0;
  const loanTermYears = num(fin?.loanTermYears) ?? 30;
  const annualDS = computeAnnualDebtService(loanAmount, loanRate, loanTermYears * 12);

  const dscr = computeDSCR(noi, annualDS);

  const inputsUsed: Record<string, number> = {
    'financials.loanAmount': loanAmount,
    'financials.loanInterestRate': loanRate,
    'financials.loanTermYears': loanTermYears,
  };
  if (rent !== undefined) inputsUsed['financials.monthlyGrossRent'] = rent;

  return {
    value: dscr === Infinity ? 999 : dscr,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D9 — Operating Expense Ratio wrapper.
 * OER = TotalOperatingExpenses / GrossRentalIncome × 100.
 * Delegates to reiMetrics.computeNOIComponents + computeOER.
 */

import type { MetricResult } from './types';
import { computeNOIComponents, computeOER } from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface ExpenseRatioProjectInput {
  financials?: {
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeExpenseRatioMetric(project: ExpenseRatioProjectInput): MetricResult {
  const fin = project.financials;

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  if (rent === undefined || rent === 0) {
    return incomplete(['financials.monthlyGrossRent']);
  }

  const components = computeNOIComponents(fin as any, project.dispositionType, project.currentPhase);
  const grossOperatingIncome = components.grossRentalIncome + components.otherIncome;
  const oer = computeOER(components.totalOperatingExpenses, grossOperatingIncome);

  const inputsUsed: Record<string, number> = {
    'financials.monthlyGrossRent': rent,
    'financials.totalOperatingExpenses': components.totalOperatingExpenses,
    'financials.grossOperatingIncome': grossOperatingIncome,
  };

  return {
    value: oer,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D5 — Gross Rent Multiplier wrapper.
 * GRM = PropertyPrice / GrossAnnualRent.
 * Delegates to reiMetrics.computeGRM.
 */

import type { MetricResult } from './types';
import { computeGRM } from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface GRMProjectInput {
  financials?: {
    purchasePrice?: number;
    targetPrice?: number;
    targetPurchasePrice?: number;
    estimatedARV?: number;
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  [key: string]: any;
}

export function computeGRMMetric(project: GRMProjectInput): MetricResult {
  const fin = project.financials;
  const missing: string[] = [];

  // GRM = Purchase Price ÷ Gross Annual Rent (PRD §4.2.2)
  // Uses acquisition cost, not ARV — ARV is the exit value, not the entry price.
  const propertyValue =
    num(fin?.purchasePrice) ??
    num(fin?.targetPrice) ??
    num(fin?.targetPurchasePrice) ??
    num(fin?.estimatedARV);

  if (propertyValue === undefined || propertyValue === 0) {
    missing.push('financials.purchasePrice');
  }

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  if (rent === undefined || rent === 0) {
    missing.push('financials.monthlyGrossRent');
  }

  if (missing.length > 0) return incomplete(missing);

  const grossAnnualRent = rent! * 12;
  const grm = computeGRM(propertyValue!, grossAnnualRent);

  return {
    value: grm,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.propertyValue': propertyValue!,
      'financials.monthlyGrossRent': rent!,
    },
    inputsMissing: [],
  };
}

/**
 * D7 — Internal Rate of Return wrapper.
 * Builds IRR cash-flow array and solves via Newton-Raphson.
 * Delegates to reiMetrics.buildIRRCashFlows + computeIRR.
 */

import type { MetricResult } from './types';
import {
  computeNOI,
  computeAnnualDebtService,
  computeCashFlow,
  computeTotalCashInvested,
  computeIRR,
  buildIRRCashFlows,
} from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface IRRProjectInput {
  financials?: {
    purchasePrice?: number;
    targetPrice?: number;
    targetPurchasePrice?: number;
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    netOperatingIncome?: number;
    loanAmount?: number;
    loanInterestRate?: number;
    loanTermYears?: number;
    fixedAcquisitionCosts?: number;
    emdAmount?: number;
    projectedRehabCost?: number;
    holdingCostTaxes?: number;
    holdingCostInsurance?: number;
    holdingCostUtilities?: number;
    projectedHoldTimeMonths?: number;
    annualAppreciationPercent?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeIRRMetric(project: IRRProjectInput): MetricResult {
  const fin = project.financials;
  const missing: string[] = [];

  const purchasePrice = num(fin?.purchasePrice) ?? num(fin?.targetPrice) ?? num(fin?.targetPurchasePrice);
  if (purchasePrice === undefined || purchasePrice === 0) {
    missing.push('financials.purchasePrice');
  }

  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);
  const hasPrecomputedNOI = fin?.netOperatingIncome != null;
  if (!hasPrecomputedNOI && (rent === undefined || rent === 0)) {
    missing.push('financials.monthlyGrossRent');
  }

  if (missing.length > 0) return incomplete(missing);

  const noi = computeNOI(fin as any, project.dispositionType, project.currentPhase);
  const loanAmount = num(fin?.loanAmount) ?? 0;
  const loanRate = num(fin?.loanInterestRate) ?? 0;
  const loanTermYears = num(fin?.loanTermYears) ?? 30;
  const annualDS = computeAnnualDebtService(loanAmount, loanRate, loanTermYears * 12);
  const { annual: annualCashFlow } = computeCashFlow(noi, annualDS);

  const totalCashInvested = computeTotalCashInvested(fin as any);
  if (totalCashInvested <= 0) return incomplete(['financials.purchasePrice (totalCashInvested is 0)']);

  const holdMonths = num(fin?.projectedHoldTimeMonths) ?? 60;
  const holdYears = Math.max(1, Math.round(holdMonths / 12));
  const appreciation = num(fin?.annualAppreciationPercent) ?? 3;

  const cashFlows = buildIRRCashFlows(
    totalCashInvested,
    annualCashFlow,
    holdYears,
    purchasePrice!,
    appreciation,
    loanAmount,
    loanRate,
    loanTermYears,
  );

  const irr = computeIRR(cashFlows);
  const irrPercent = irr !== null ? Math.round(irr * 100 * 100) / 100 : null;

  const inputsUsed: Record<string, number> = {
    'financials.purchasePrice': purchasePrice!,
    'financials.totalCashInvested': totalCashInvested,
    'financials.projectedHoldTimeMonths': holdMonths,
  };
  if (rent !== undefined) inputsUsed['financials.monthlyGrossRent'] = rent;
  if (loanAmount > 0) inputsUsed['financials.loanAmount'] = loanAmount;

  if (irrPercent === null) {
    // Solver did not converge — still return with the inputs we tried
    return {
      value: null,
      state: 'incomplete',
      inputsUsed,
      inputsMissing: ['IRR solver did not converge'],
    };
  }

  return {
    value: irrPercent,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D1 — Net Operating Income (NOI) wrapper.
 * Delegates computation to reiMetrics.computeNOI / computeNOIComponents.
 */

import type { MetricResult } from './types';
import { computeNOI, computeNOIComponents } from './reiMetrics';
import { resolveState, incomplete, num } from './helpers';

export interface NOIProjectInput {
  financials?: {
    monthlyGrossRent?: number;
    projectedMonthlyRent?: number;
    projectedRent?: number;
    netOperatingIncome?: number;
    vacancyRatePercent?: number;
    vacancyRate?: number;
    holdingCostTaxes?: number;
    operatingExpenseTaxes?: number;
    holdingCostInsurance?: number;
    operatingExpenseInsurance?: number;
    holdingCostUtilities?: number;
    holdingCostSecurity?: number;
    propertyManagementFeePercent?: number;
    propertyManagementFee?: number;
    monthlyMaintenanceReserve?: number;
    maintenanceReserves?: number;
    monthlyHOA?: number;
    otherMonthlyIncome?: number;
    grossIncomeParking?: number;
    grossIncomeLaundry?: number;
    projectedOpex?: number;
    actualRentalIncome?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeNOIMetric(project: NOIProjectInput): MetricResult {
  const fin = project.financials;

  // Require at least some rent input
  const rent = num(fin?.monthlyGrossRent) ?? num(fin?.projectedMonthlyRent) ?? num(fin?.projectedRent);



  if (rent === undefined || rent === 0) {
    return incomplete(['financials.monthlyGrossRent']);
  }

  // Call the existing engine
  const components = computeNOIComponents(fin as any, project.dispositionType, project.currentPhase);

  const inputsUsed: Record<string, number> = {
    'financials.monthlyGrossRent': rent,
  };
  const vacancyPct = num(fin?.vacancyRatePercent) ?? num(fin?.vacancyRate);
  if (vacancyPct !== undefined) inputsUsed['financials.vacancyRatePercent'] = vacancyPct;

  const taxes = num(fin?.holdingCostTaxes) ?? num(fin?.operatingExpenseTaxes);
  if (taxes !== undefined) inputsUsed['financials.holdingCostTaxes'] = taxes;

  const insurance = num(fin?.holdingCostInsurance) ?? num(fin?.operatingExpenseInsurance);
  if (insurance !== undefined) inputsUsed['financials.holdingCostInsurance'] = insurance;

  const maintenance = num(fin?.monthlyMaintenanceReserve) ?? num(fin?.maintenanceReserves);
  if (maintenance !== undefined) inputsUsed['financials.monthlyMaintenanceReserve'] = maintenance;

  const security = num(fin?.holdingCostSecurity);
  if (security !== undefined) inputsUsed['financials.holdingCostSecurity'] = security;

  const mgmtPct = num(fin?.propertyManagementFeePercent);
  if (mgmtPct !== undefined) inputsUsed['financials.propertyManagementFeePercent'] = mgmtPct;

  return {
    value: components.noi,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * D8 — Occupancy Rate wrapper.
 * Handles three modes: unit-based, day-based, and vacancy-assumption fallback.
 * Delegates to reiMetrics.computeOccupancyRate.
 */

import type { MetricResult } from './types';
import { computeOccupancyRate } from './reiMetrics';
import { resolveState, num } from './helpers';

export interface OccupancyProjectInput {
  financials?: {
    numberOfUnits?: number;
    occupiedUnits?: number;
    vacancyRatePercent?: number;
    vacancyRate?: number;
    daysOccupied?: number;
    totalHoldDays?: number;
    [key: string]: any;
  };
  currentPhase?: number;
  dispositionType?: string;
  [key: string]: any;
}

export function computeOccupancyMetric(project: OccupancyProjectInput): MetricResult {
  const fin = project.financials;

  const rawDisp = project.dispositionType;
  const mappedDisp: Record<string, string> = {
    'Buy & Hold': 'RENT',
    'Rent': 'RENT',
    'Fix & Flip': 'SALE',
    'Sell': 'SALE',
    'Wholesale': 'SALE',
    'buy-and-hold': 'RENT',
    'LTR': 'RENT',
  };
  const dispositionType = rawDisp ? (mappedDisp[rawDisp] ?? rawDisp) : undefined;

  // Flip/sell strategies → occupancy is 0 by definition
  if (dispositionType === 'SALE') {
    return {
      value: 0,
      state: resolveState(project.currentPhase),
      inputsUsed: {},
      inputsMissing: [],
    };
  }

  // Mode 1: day-based occupancy (actual tracking)
  const daysOccupied = num(fin?.daysOccupied);
  const totalHoldDays = num(fin?.totalHoldDays);
  if (daysOccupied !== undefined && totalHoldDays !== undefined && totalHoldDays > 0) {
    const rate = Math.round((daysOccupied / totalHoldDays) * 100 * 100) / 100;
    return {
      value: rate,
      state: resolveState(project.currentPhase),
      inputsUsed: {
        'financials.daysOccupied': daysOccupied,
        'financials.totalHoldDays': totalHoldDays,
      },
      inputsMissing: [],
    };
  }

  // Mode 2: unit-based occupancy
  const numberOfUnits = num(fin?.numberOfUnits) ?? 1;
  const occupiedUnits = num(fin?.occupiedUnits) ?? numberOfUnits;
  const unitOccupancy = computeOccupancyRate(occupiedUnits, numberOfUnits);

  // Mode 3: vacancy assumption fallback
  const vacancyPct = num(fin?.vacancyRatePercent) ?? num(fin?.vacancyRate) ?? 7;
  let occupancy: number;

  if (unitOccupancy === 100 && vacancyPct > 0) {
    occupancy = 100 - vacancyPct;
  } else {
    occupancy = unitOccupancy;
  }

  const inputsUsed: Record<string, number> = {};
  if (fin?.numberOfUnits !== undefined) inputsUsed['financials.numberOfUnits'] = numberOfUnits;
  if (fin?.occupiedUnits !== undefined) inputsUsed['financials.occupiedUnits'] = occupiedUnits;
  inputsUsed['financials.vacancyRatePercent'] = vacancyPct;

  return {
    value: occupancy,
    state: resolveState(project.currentPhase),
    inputsUsed,
    inputsMissing: [],
  };
}

/**
 * Supplemental metrics calculations with strict REIL phase gating.
 */

import type { MetricResult } from './types';
import {
  computeNOIComponents,
  computeAnnualDebtService,
  computeTotalCashInvested,
  deriveAllProjectMetrics,
} from './reiMetrics';
import { resolveState, incomplete, notApplicable, num } from './helpers';

// Helper to enforce phase gates
function checkPhaseGate(
  currentPhase: number | undefined,
  allowedPhases: number[]
): boolean {
  if (currentPhase === undefined) return false;
  return allowedPhases.includes(currentPhase);
}

// 1. LTV (Loan-to-Value) — Fund, Hold (Phase 2, 3)
export function computeLTVMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [2, 3])) {
    return notApplicable();
  }

  const activeLoan = project.loans?.find((l: any) => (l.status as string) === 'Locked') || 
                     project.loans?.find((l: any) => (l.status as string) === 'Approved') ||
                     project.loans?.[0];
  const appraisedValue = activeLoan?.appraisedValueCents != null ? Number(activeLoan.appraisedValueCents) / 100 : undefined;
  const purchasePrice = num(project.financials?.purchasePrice) ?? num(project.financials?.targetPrice) ?? num(project.financials?.targetPurchasePrice) ?? 0;
  const propertyValue = appraisedValue ?? num(project.financials?.estimatedCurrentValue) ?? purchasePrice;

  const activeLoanAmount = activeLoan?.amountCents != null ? Number(activeLoan.amountCents) / 100 : undefined;
  const loanAmount = activeLoanAmount ?? num(project.financials?.loanAmount) ?? 0;

  if (propertyValue <= 0) {
    return incomplete(['financials.purchasePrice']);
  }

  const calculatedLTV = (loanAmount / propertyValue) * 100;

  return {
    value: Math.round(calculatedLTV * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.loanAmount': loanAmount,
      'financials.purchasePrice': propertyValue,
    },
    inputsMissing: [],
  };
}

// 2. Debt Yield — Fund, Hold (Phase 2, 3)
export function computeDebtYieldMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [2, 3])) {
    return notApplicable();
  }

  const fin = project.financials;
  const loanAmount = num(fin?.loanAmount);
  if (loanAmount === undefined || loanAmount === 0) {
    return notApplicable(); // All-cash deals do not have debt yield
  }

  // NOI is required
  const rent =
    num(fin?.monthlyGrossRent) ??
    num(fin?.projectedMonthlyRent) ??
    num(fin?.projectedRent);
  if (rent === undefined || rent === 0) {
    return incomplete(['financials.monthlyGrossRent']);
  }

  const components = computeNOIComponents(
    fin || {},
    project.dispositionType,
    project.currentPhase
  );

  return {
    value: Math.round((components.noi / loanAmount) * 100 * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.loanAmount': loanAmount,
      'financials.monthlyGrossRent': rent,
    },
    inputsMissing: [],
  };
}

// 3. Equity Multiple — Hold, Exit (Phase 3, 4)
export function computeEquityMultipleMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3, 4])) {
    return notApplicable();
  }

  const fin = project.financials;
  const totalCashInvested =
    num(fin?.financingCashInvested) ?? computeTotalCashInvested(fin || {});
  if (!totalCashInvested || totalCashInvested <= 0) {
    return incomplete(['financials.financingCashInvested']);
  }

  const purchasePrice =
    num(fin?.purchasePrice) ??
    num(fin?.targetPrice) ??
    num(fin?.targetPurchasePrice) ??
    0;
  const propertyValue =
    num(fin?.estimatedCurrentValue) ??
    num(fin?.estimatedARV) ??
    purchasePrice;

  const components = computeNOIComponents(
    fin || {},
    project.dispositionType,
    project.currentPhase
  );
  const annualDebtService = computeAnnualDebtService(
    num(fin?.loanAmount) ?? 0,
    num(fin?.loanInterestRate) ?? 0,
    (num(fin?.loanTermYears) ?? 30) * 12
  );
  const annualCashFlow = components.noi - annualDebtService;

  const finalPropertyValue = num(fin?.actualSalePrice) ?? propertyValue;

  // Standard pro-forma return assumes 10-year hold of operations plus current or exit value
  const totalReturn = annualCashFlow * 10 + finalPropertyValue;

  return {
    value: Math.round((totalReturn / totalCashInvested) * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.financingCashInvested': totalCashInvested,
      'financials.purchasePrice': propertyValue,
    },
    inputsMissing: [],
  };
}

// 4. Break-Even Occupancy — Hold (Phase 3)
export function computeBreakEvenOccupancyMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3])) {
    return notApplicable();
  }

  const fin = project.financials;
  const components = computeNOIComponents(
    fin || {},
    project.dispositionType,
    project.currentPhase
  );
  const annualDebtService = computeAnnualDebtService(
    num(fin?.loanAmount) ?? 0,
    num(fin?.loanInterestRate) ?? 0,
    (num(fin?.loanTermYears) ?? 30) * 12
  );

  const grossPotentialRent =
    components.grossRentalIncome + components.otherIncome;
  if (grossPotentialRent === 0) {
    return incomplete(['financials.monthlyGrossRent']);
  }

  const value =
    ((components.totalOperatingExpenses + annualDebtService) /
      grossPotentialRent) *
    100;

  return {
    value: Math.round(Math.min(value, 100) * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.monthlyGrossRent':
        num(fin?.monthlyGrossRent) ??
        num(fin?.projectedMonthlyRent) ??
        num(fin?.projectedRent) ??
        0,
    },
    inputsMissing: [],
  };
}

// 5. Capital Reserves / CapEx Funded (months) — Hold (Phase 3)
export function computeCapitalReservesMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3])) {
    return notApplicable();
  }

  const fin = project.financials;
  const capitalReserves = num(fin?.capitalReserves);
  const maintenance =
    num(fin?.monthlyMaintenanceReserve) ?? num(fin?.maintenanceReserves);

  if (capitalReserves === undefined) {
    return incomplete(['financials.capitalReserves']);
  }
  if (maintenance === undefined || maintenance === 0) {
    return incomplete(['financials.monthlyMaintenanceReserve']);
  }

  return {
    value: Math.round((capitalReserves / maintenance) * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.capitalReserves': capitalReserves,
      'financials.monthlyMaintenanceReserve': maintenance,
    },
    inputsMissing: [],
  };
}

// 6. Payback Period — Hold, Exit (Phase 3, 4)
export function computePaybackPeriodMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3, 4])) {
    return notApplicable();
  }

  const fin = project.financials;
  const totalCashInvested =
    num(fin?.financingCashInvested) ?? computeTotalCashInvested(fin || {});
  const components = computeNOIComponents(
    fin || {},
    project.dispositionType,
    project.currentPhase
  );
  const annualDebtService = computeAnnualDebtService(
    num(fin?.loanAmount) ?? 0,
    num(fin?.loanInterestRate) ?? 0,
    (num(fin?.loanTermYears) ?? 30) * 12
  );
  const annualCashFlow = components.noi - annualDebtService;

  if (totalCashInvested <= 0) {
    return incomplete(['financials.financingCashInvested']);
  }
  if (annualCashFlow <= 0) {
    return incomplete(['financials.monthlyGrossRent']); // cash flow <= 0 means payback period is not achievable
  }

  return {
    value: Math.round((totalCashInvested / annualCashFlow) * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.financingCashInvested': totalCashInvested,
      'financials.monthlyGrossRent':
        num(fin?.monthlyGrossRent) ??
        num(fin?.projectedMonthlyRent) ??
        num(fin?.projectedRent) ??
        0,
    },
    inputsMissing: [],
  };
}

// 7. Tenant Turnover Rate — Hold (Phase 3)
export function computeTenantTurnoverMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3])) {
    return notApplicable();
  }

  const fin = project.financials;
  const directRate = num(fin?.tenantTurnoverRate);
  if (directRate !== undefined) {
    return {
      value: directRate,
      state: resolveState(project.currentPhase),
      inputsUsed: { 'financials.tenantTurnoverRate': directRate },
      inputsMissing: [],
    };
  }

  const moveOuts = num(fin?.numberOfMoveOuts);
  const units = num(fin?.numberOfUnits) ?? num(project.numberOfUnits) ?? 1;

  if (moveOuts === undefined) {
    return incomplete(['financials.tenantTurnoverRate']);
  }

  return {
    value: Math.round((moveOuts / units) * 100 * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.numberOfMoveOuts': moveOuts,
      'financials.numberOfUnits': units,
    },
    inputsMissing: [],
  };
}

// 8. Lease Renewal Rate — Hold (Phase 3)
export function computeLeaseRenewalMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3])) {
    return notApplicable();
  }

  const fin = project.financials;
  const directRate = num(fin?.leaseRenewalRate);
  if (directRate !== undefined) {
    return {
      value: directRate,
      state: resolveState(project.currentPhase),
      inputsUsed: { 'financials.leaseRenewalRate': directRate },
      inputsMissing: [],
    };
  }

  const renewals = num(fin?.numberOfRenewals);
  const moveOuts = num(fin?.numberOfMoveOuts) ?? 0;
  const totalLeasesExpiring = renewals !== undefined ? renewals + moveOuts : 0;

  if (renewals === undefined || totalLeasesExpiring === 0) {
    return incomplete(['financials.leaseRenewalRate']);
  }

  return {
    value: Math.round((renewals / totalLeasesExpiring) * 100 * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.numberOfRenewals': renewals,
      'financials.numberOfMoveOuts': moveOuts,
    },
    inputsMissing: [],
  };
}

// 9. Maintenance Cost Per Unit — Hold (Phase 3)
export function computeMaintenanceCostPerUnitMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [3])) {
    return notApplicable();
  }

  const fin = project.financials;
  const maintenance =
    num(fin?.monthlyMaintenanceReserve) ?? num(fin?.maintenanceReserves) ?? 0;
  const units = num(fin?.numberOfUnits) ?? num(project.numberOfUnits) ?? 1;

  if (maintenance === 0) {
    return incomplete(['financials.monthlyMaintenanceReserve']);
  }

  return {
    value: Math.round(((maintenance * 12) / units) * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.monthlyMaintenanceReserve': maintenance,
      'financials.numberOfUnits': units,
    },
    inputsMissing: [],
  };
}

// 10. Days on Market (DOM) — Acquisition, Exit (Phase 1, 4)
export function computeDOMMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [1, 4])) {
    return notApplicable();
  }

  const fin = project.financials;
  const directDom = num(fin?.daysOnMarket);
  if (directDom !== undefined) {
    return {
      value: directDom,
      state: resolveState(project.currentPhase),
      inputsUsed: { 'financials.daysOnMarket': directDom },
      inputsMissing: [],
    };
  }

  const listDate = fin?.listingDate;
  if (!listDate) {
    return incomplete(['financials.listingDate']);
  }

  const start = new Date(listDate);
  const end = fin?.soldDate ? new Date(fin.soldDate) : new Date();

  if (isNaN(start.getTime()) || isNaN(end.getTime())) {
    return incomplete(['financials.listingDate']);
  }

  return {
    value: Math.max(0, Math.round((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24))),
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.listingDate': listDate.toString(),
    },
    inputsMissing: [],
  };
}

// 11. Budget Variance — Acquisition, Fund (Phase 1, 2)
export function computeBudgetVarianceMetric(project: any): MetricResult {
  if (!checkPhaseGate(project.currentPhase, [1, 2])) {
    return notApplicable();
  }

  const fin = project.financials;
  const budget = (fin?.rehab_budget ? fin.rehab_budget / 100 : num(fin?.rehabBudget)) ?? num(fin?.projectedRehabCost);
  const actual = num(fin?.rehabActual) ?? num(fin?.actualRehabCost) ?? 0;

  if (!budget) {
    return incomplete(['financials.rehabBudget']);
  }

  return {
    value: Math.round(((actual - budget) / budget) * 100 * 100) / 100,
    state: resolveState(project.currentPhase),
    inputsUsed: {
      'financials.rehabBudget': budget,
      'financials.rehabActual': actual,
    },
    inputsMissing: [],
  };
}

