/**
 * Shared helpers for structured metric wrappers.
 * Pure functions — no I/O, no React, no Firestore.
 */

import type { MetricState, MetricResult } from './types';

/**
 * Determine the MetricState from a project's currentPhase.
 *
 * Phase 1 (Find & Fund) → 'projected'
 * Phase 2 (Acquisition) → 'projected' (or 'actual' if purchase closed — caller decides)
 * Phase 3 (Hold)         → 'live'
 * Phase 4 (Exit)         → 'realized'
 * Unknown                → 'projected' (safe default)
 */
export function resolveState(currentPhase: number | undefined): MetricState {
  switch (currentPhase) {
    case 1: return 'projected';
    case 2: return 'projected'; // caller may override to 'actual' after close
    case 3: return 'live';
    case 4: return 'realized';
    default: return 'projected';
  }
}

/**
 * Build an incomplete MetricResult — used when required inputs are missing.
 */
export function incomplete(missing: string[]): MetricResult {
  return {
    value: null,
    state: 'incomplete',
    inputsUsed: {},
    inputsMissing: missing,
  };
}

/**
 * Build a not-applicable MetricResult — used when the metric does not apply.
 */
export function notApplicable(): MetricResult {
  return {
    value: null,
    state: 'n/a',
    inputsUsed: {},
    inputsMissing: [],
  };
}

/**
 * Safe number extraction — returns undefined for null/undefined/NaN.
 */
export function num(val: unknown): number | undefined {
  if (val == null) return undefined;
  const n = Number(val);
  return Number.isFinite(n) ? n : undefined;
}

/**
 * Get a nested property from a project object using a dot-separated path.
 */
export function getPath(obj: Record<string, any>, path: string): unknown {
  return path.split('.').reduce((acc, key) => acc?.[key], obj);
}

/**
 * Safe date parser — handles strings, numbers, Date objects, and Firestore Timestamps.
 */
export function parseDate(val: unknown): Date | null {
  if (!val) return null;
  if (val instanceof Date) return val;
  if (typeof val === 'object' && val !== null && 'toDate' in val && typeof (val as any).toDate === 'function') {
    return (val as any).toDate();
  }
  if (typeof val === 'object' && val !== null && '_seconds' in val) {
    return new Date((val as any)._seconds * 1000);
  }
  if (typeof val === 'string' || typeof val === 'number') {
    const d = new Date(val);
    return isNaN(d.getTime()) ? null : d;
  }
  return null;
}

import { deriveAllProjectMetrics } from './reiMetrics';

export type MetricCategoryKey = 'financial' | 'operational' | 'portfolio' | 'marketing' | 'compliance';
export type MetricUnitKey = 'currency' | 'percent' | 'ratio' | 'days' | 'count';

export interface MetricRegistryEntry {
  id: string;
  name: string;
  category: MetricCategoryKey;
  formula: string;
  unit: MetricUnitKey;
  compute: (project: any, portfolio?: any[]) => number | null;
  benchmark: {
    good: number | null;
    warning: number | null;
    bad: number | null;
  };
}

// Map registry lowercase metric ID to KPI33Block key inside active metrics
const KEY_MAP: Record<string, string> = {
  noi: 'NOI',
  cap_rate: 'CAP_RATE',
  cash_on_cash: 'COC',
  irr: 'IRR',
  cash_flow: 'CASH_FLOW',
  grm: 'GRM',
  dscr: 'DSCR',
  ltv: 'LTV',
  oer: 'OER',
  equity_to_value: 'EQUITY_TO_VALUE',
  interest_coverage: 'INTEREST_COVERAGE',
  roi: 'ROI',
  capex: 'CAPEX',
  goi: 'GOI',
  aar: 'AAR',
  equity_multiple: 'EQUITY_MULTIPLE',
  revenue_growth: 'REVENUE_GROWTH',
  occupancy_rate: 'OCCUPANCY',
  tenant_turnover: 'TENANT_TURNOVER',
  avg_rent_price: 'AVG_RENT_PER_PROPERTY',
  lease_renewal: 'LEASE_RENEWAL',
  maintenance_per_unit: 'MAINTENANCE_COST_PER_UNIT',
  days_on_market: 'DOM',
  construction_per_sqft: 'CONSTRUCTION_COST_SQFT',
  portfolio_value_growth: 'PORTFOLIO_VALUE_GROWTH',
  payback_period: 'PAYBACK_PERIOD',
  yoy_variance: 'YOY_SOLD_PRICE_VARIANCE',
  sold_per_inventory: 'SOLD_PER_INVENTORY',
  demand_growth: 'DEMAND_GROWTH',
  listing_to_meeting: 'LISTING_TO_MEETING',
  avg_commission: 'AVG_COMMISSION',
  risk_score: 'RISK_SCORE',
  compliance_rate: 'COMPLIANCE_RATE',
};

/**
 * Inputs a metric genuinely needs before its value can mean anything.
 *
 * The core formulas in `reiMetrics.ts` return 0 rather than null when their
 * inputs are absent — a deliberate choice there, since 0 is a valid arithmetic
 * result and other consumers rely on a number. But on the Insights dashboard
 * that produced "Cap Rate 0.0%" for a project with no purchase price, which
 * reads as a real measurement rather than missing data.
 *
 * This guard sits at the registry layer so `reiMetrics.ts` is untouched: if
 * none of a metric's required inputs are present, the metric is unknown, not
 * zero. A metric absent from this map is passed straight through.
 */
const RENT   = ['monthlyGrossRent', 'projectedMonthlyRent', 'gross_rent_per_unit'];
const VALUE  = ['purchasePrice', 'listedPrice', 'estimatedARV', 'currentValue'];
const EQUITY = ['downPayment', 'totalCashInvested', 'purchasePrice', 'listedPrice'];
const DEBT   = ['monthlyDebtService', 'annualDebtService', 'loanAmount'];

/**
 * Each entry is a list of GROUPS, and every group must be satisfied by at
 * least one present field. A ratio needs both sides: LTV without a property
 * value is not 0% leverage, it is unknown — which is precisely the bug this
 * guard exists to prevent.
 */
const REQUIRED_INPUTS: Record<string, string[][]> = {
  noi:               [RENT],
  cap_rate:          [RENT, VALUE],
  cash_on_cash:      [RENT, EQUITY],
  irr:               [RENT, VALUE],
  cash_flow:         [RENT],
  grm:               [RENT, VALUE],
  dscr:              [RENT, DEBT],
  ltv:               [['loanAmount'], VALUE],
  oer:               [RENT],
  goi:               [RENT],
  occupancy_rate:    [RENT],
  equity_to_value:   [VALUE],
  interest_coverage: [RENT, DEBT],
  equity_multiple:   [RENT, EQUITY],
  payback_period:    [RENT, EQUITY],
};

/** True when every required input group has at least one usable number. */
function hasRequiredInputs(project: unknown, metricId: string): boolean {
  const groups = REQUIRED_INPUTS[metricId];
  if (!groups) return true; // unguarded metric — pass through

  const financials =
    project && typeof project === 'object'
      ? (project as { financials?: unknown }).financials
      : undefined;
  if (!financials || typeof financials !== 'object') return false;

  const bag = financials as Record<string, unknown>;
  const present = (key: string) => {
    const v = bag[key];
    // A recorded 0 is treated as a data gap, not a measurement: a property
    // does not have a $0 purchase price or $0 rent in any real record.
    return typeof v === 'number' && Number.isFinite(v) && v !== 0;
  };

  return groups.every((group) => group.some(present));
}

/**
 * Computes a single metric value for a project.
 * Derives all metrics via core engine and extracts the appropriate phase value (actual vs projected).
 *
 * Returns null — never 0 — when the metric's required inputs are absent, so the
 * UI can render an em dash instead of a misleading zero.
 */
export function computeSingleMetric(project: any, metricId: string): number | null {
  if (!project) return null;
  if (!hasRequiredInputs(project, metricId)) return null;
  try {
    const derived = deriveAllProjectMetrics(project);
    const kpiKey = KEY_MAP[metricId];
    if (!kpiKey || !derived.kpi33) return null;

    const kpiVal = (derived.kpi33 as any)[kpiKey];
    if (!kpiVal) return null;

    // Derived values default to actual if project is in Hold or Exit phase, otherwise projected
    const isActual =
      project.phase === 'hold' ||
      project.phase === 'exit' ||
      project.status === 'hold' ||
      project.status === 'exit';

    const val = isActual ? kpiVal.actual : kpiVal.projected;
    return val !== undefined && val !== null ? val : null;
  } catch (err) {
    console.error(`[Metric Registry] Error computing ${metricId}:`, err);
    return null;
  }
}

/**
 * Returns the raw null reason for a metric if it is currently not calculable.
 */
export function computeSingleMetricNullReason(project: any, metricId: string): string | null {
  if (!project) return null;
  try {
    const derived = deriveAllProjectMetrics(project);
    const kpiKey = KEY_MAP[metricId];
    if (!kpiKey || !derived.kpi33) return null;

    const kpiVal = (derived.kpi33 as any)[kpiKey];
    if (!kpiVal) return null;

    const isActual =
      project.phase === 'hold' ||
      project.phase === 'exit' ||
      project.status === 'hold' ||
      project.status === 'exit';

    const reason = isActual ? kpiVal.actualNullReason : kpiVal.projectedNullReason;
    return reason || null;
  } catch (err) {
    return null;
  }
}

/**
 * Aggregates a metric value across all projects in the portfolio.
 * - Currency, count, days: Sum
 * - Percent, ratio: Weighted average based on project purchase price
 */
export function aggregatePortfolio(
  metricId: string,
  portfolio: any[],
  unit: MetricUnitKey
): number | null {
  if (!portfolio || portfolio.length === 0) return null;

  const validProjects = portfolio
    .map(p => {
      const val = computeSingleMetric(p, metricId);
      // Purchase price as weighting factor (fallback to 1 if missing or 0)
      const purchasePrice = p.financials?.purchasePrice ?? p.purchasePrice ?? 1;
      const weight = purchasePrice > 0 ? purchasePrice : 1;
      return { val, weight };
    })
    .filter(item => item.val !== null && !isNaN(item.val!));

  if (validProjects.length === 0) return null;

  if (unit === 'percent' || unit === 'ratio') {
    let totalWeight = 0;
    let weightedSum = 0;
    for (const p of validProjects) {
      weightedSum += p.val! * p.weight;
      totalWeight += p.weight;
    }
    return totalWeight > 0 ? weightedSum / totalWeight : null;
  } else {
    // Sum for currency, count, days
    return validProjects.reduce((sum, p) => sum + p.val!, 0);
  }
}

/**
 * Centralised compute router for the metric registry.
 */
function createCompute(metricId: string, unit: MetricUnitKey) {
  return (project: any, portfolio?: any[]): number | null => {
    if (portfolio && portfolio.length > 0) {
      return aggregatePortfolio(metricId, portfolio, unit);
    }
    return computeSingleMetric(project, metricId);
  };
}

