import type { Project } from "@/types/schema";
import type { NotificationType } from "@/types/notification";
import { compute1031Deadlines } from "@/lib/utils/exchange1031";

export interface DerivedWorkflowNotification {
  id: string;
  projectId: string;
  projectName: string;
  type: NotificationType;
  priority: "critical" | "warning" | "info";
  title: string;
  body: string;
  deepLinkUrl: string;
  createdAt: Date;
  read?: boolean;
}

export const WORKFLOW_EVENT_TYPES: NotificationType[] = [
  "gate_criteria_failing",
  "gate_override_executed",
  "variance_threshold_tripped",
  "exchange_1031_deadline",
  "checklist_item_overdue",
  "document_upload_completed",
];

function projectLabel(p: Project): string {
  return p.propertyName || p.address || "Unnamed Project";
}

function daysUntil(dateStrOrObj: string | Date | undefined): number | null {
  if (!dateStrOrObj) return null;
  const d = dateStrOrObj instanceof Date ? dateStrOrObj : new Date(dateStrOrObj);
  if (isNaN(d.getTime())) return null;
  return Math.ceil((d.getTime() - Date.now()) / 86_400_000);
}

/**
 * Derives workflow notifications dynamically from active projects and evaluates
 * user-level preference suppression toggles.
 */
export function deriveWorkflowNotifications(
  projects: Project[],
  preferences?: Record<string, boolean>
): DerivedWorkflowNotification[] {
  const notifications: DerivedWorkflowNotification[] = [];

  for (const p of projects) {
    const pid = p.id;
    const name = projectLabel(p);
    const f = p.financials;
    const phase = p.currentPhase ?? 1;

    // 1. gate_criteria_failing: missing or blocked criteria
    if (phase === 2 && f && f.purchasePrice && !f.loanAmount && !p.isClearToClose) {
      if (preferences?.gate_criteria_failing !== false) {
        notifications.push({
          id: `gate-fail-${pid}`,
          projectId: pid,
          projectName: name,
          type: "gate_criteria_failing",
          priority: "warning",
          title: `Phase Gate Blocked: ${name}`,
          body: `Phase 2 acquisition gate requires financing details to reach Clear-to-Close.`,
          deepLinkUrl: `/dashboard/projects/${pid}?tab=timeline`,
          createdAt: new Date(),
        });
      }
    }

    // 2. gate_override_executed: override event logged
    const gateEvents = (p as any).phaseGateEvents;
    if (Array.isArray(gateEvents) && gateEvents.some((e: any) => e.overrideReason)) {
      if (preferences?.gate_override_executed !== false) {
        const lastOverride = [...gateEvents].reverse().find((e: any) => e.overrideReason);
        notifications.push({
          id: `gate-override-${pid}-${lastOverride?.id || 'event'}`,
          projectId: pid,
          projectName: name,
          type: "gate_override_executed",
          priority: "critical",
          title: `Phase Gate Override Executed: ${name}`,
          body: `An owner override was logged with reason: "${lastOverride?.overrideReason?.slice(0, 50)}..."`,
          deepLinkUrl: `/dashboard/projects/${pid}?tab=timeline`,
          createdAt: lastOverride?.createdAt ? new Date(lastOverride.createdAt) : new Date(),
        });
      }
    }

    // 3. variance_threshold_tripped: Phase 3 operational NOI variance > ±10% for 2+ consecutive periods
    const fin: any = p.financials;
    if (phase === 3 && fin) {
      const actuals = Array.isArray(fin.propertyActuals) ? fin.propertyActuals : [];
      const baseNoi = fin.budgetBaseline?.monthlyNoi || 2000;
      const consecutiveExceeded = actuals.length >= 2 && actuals.filter((a: any) => {
        const noi = a.noi ?? (a.grossRent - a.operatingExpenses);
        return Math.abs(((noi - baseNoi) / baseNoi) * 100) > 10;
      }).length >= 2;

      if ((fin.operationalVarianceAlert || consecutiveExceeded) && preferences?.variance_threshold_tripped !== false) {
        notifications.push({
          id: `variance-tripped-${pid}`,
          projectId: pid,
          projectName: name,
          type: "variance_threshold_tripped",
          priority: "critical",
          title: `Operational NOI Variance Alert: ${name}`,
          body: `Operational NOI variance exceeded ±10% threshold for 2+ consecutive periods.`,
          deepLinkUrl: `/dashboard/projects/${pid}/operations`,
          createdAt: new Date(),
        });
      }
    }

    // 4. exchange_1031_deadline: 1031 exchange sale date set & identification (45d) or exchange (180d) deadline within 14 days
    if (f?.soldDate) {
      const { identificationDeadline, exchangeDeadline } = compute1031Deadlines(f.soldDate);
      const daysToId = daysUntil(identificationDeadline);
      const daysToEx = daysUntil(exchangeDeadline);

      const isApproaching = (daysToId !== null && daysToId >= 0 && daysToId <= 14) ||
                            (daysToEx !== null && daysToEx >= 0 && daysToEx <= 14);

      if (isApproaching && preferences?.exchange_1031_deadline !== false) {
        const closestDays = daysToId !== null && daysToId >= 0 && daysToId <= 14 ? daysToId : daysToEx;
        notifications.push({
          id: `1031-deadline-${pid}`,
          projectId: pid,
          projectName: name,
          type: "exchange_1031_deadline",
          priority: "critical",
          title: `1031 Statutory Deadline Approaching: ${name}`,
          body: `1031 exchange statutory deadline is in ${closestDays} days. Ensure replacement properties are identified.`,
          deepLinkUrl: `/dashboard/projects/${pid}/phase-4`,
          createdAt: new Date(),
        });
      }
    }

    // 5. checklist_item_overdue: overdue action items or disposition tasks
    if (Array.isArray(p.actionItems)) {
      for (const task of p.actionItems) {
        const isDone = task.completed || task.status === "done" || task.status === "complete";
        if (!isDone && task.dueDate) {
          const days = daysUntil(task.dueDate);
          if (days !== null && days < 0 && preferences?.checklist_item_overdue !== false) {
            const taskTitle = task.label || task.title || "Checklist Task";
            notifications.push({
              id: `task-overdue-${pid}-${task.id || taskTitle}`,
              projectId: pid,
              projectName: name,
              type: "checklist_item_overdue",
              priority: "warning",
              title: `Task Overdue: ${taskTitle}`,
              body: `Task "${taskTitle}" on ${name} was due ${Math.abs(days)} days ago.`,
              deepLinkUrl: `/dashboard/projects/${pid}?tab=tasks`,
              createdAt: new Date(),
            });
          }
        }
      }
    }

    // 6. document_upload_completed: document uploads completed
    const docs = (p as any).preApprovalDocuments;
    if (Array.isArray(docs) && docs.length > 0) {
      if (preferences?.document_upload_completed !== false) {
        const lastDoc = docs[docs.length - 1];
        notifications.push({
          id: `doc-upload-${pid}-${lastDoc.slice(-8)}`,
          projectId: pid,
          projectName: name,
          type: "document_upload_completed",
          priority: "info",
          title: `Document Uploaded: ${name}`,
          body: `A project document (${lastDoc.split('/').pop() || 'file'}) was successfully uploaded.`,
          deepLinkUrl: `/dashboard/projects/${pid}?tab=documents`,
          createdAt: new Date(),
        });
      }
    }
  }

  // Priority order: critical → warning → info
  const TIER: Record<string, number> = { critical: 0, warning: 1, info: 2 };
  return notifications.sort((a, b) => TIER[a.priority] - TIER[b.priority]);
}

/**
 * ═══════════════════════════════════════════════════════
 * PaperWorking — Lifecycle Alert Engine
 *
 * Server-side engine that evaluates project lifecycle
 * deadlines and fires proactive notifications.
 *
 * Triggers:
 *   - Lease renewal: 60 days before expiry
 *   - Property tax: based on known tax due dates
 *   - Insurance renewal: 30 days before expiry
 *   - Valuation review: 6 months since last update
 *
 * Debounce: 7 days for deadlines, 30 days for valuation.
 * Designed to be called from a cron route (daily cadence).
 * ═══════════════════════════════════════════════════════
 */

import { adminDb } from '@/lib/firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';
import { NotificationService } from '@/lib/services/notificationService';
import {
  type LifecycleAlertType,
  ALERT_METADATA,
  buildAlertTitle,
  buildAlertBody,
  buildAlertDeepLink,
  type AlertContentParams,
} from './notificationTypes';

// ── Types ─────────────────────────────────────────────────────────────────────

export interface LifecycleAlertEvaluation {
  alertType: LifecycleAlertType;
  triggered: boolean;
  daysUntil: number | null;
  /** The deadline date, if known */
  deadlineDate?: Date;
}

export interface LifecycleAlertResult {
  projectId: string;
  evaluations: LifecycleAlertEvaluation[];
  alertsFired: LifecycleAlertType[];
  alertsDebounced: LifecycleAlertType[];
}

export interface LifecycleAlertBatchResult {
  projectsScanned: number;
  totalAlertsFired: number;
  totalAlertsDebounced: number;
  errors: Array<{ projectId: string; error: string }>;
  results: LifecycleAlertResult[];
}

// ── Debounce Check ────────────────────────────────────────────────────────────

const DEBOUNCE_COLLECTION = 'metricAlertDebounce'; // Shared with metric alerts

async function isDebounced(
  projectId: string,
  alertType: LifecycleAlertType
): Promise<boolean> {
  const meta = ALERT_METADATA[alertType];
  const debounceMs = meta.debounceHours * 60 * 60 * 1000;
  const cutoff = new Date(Date.now() - debounceMs);

  const docId = `${projectId}_${alertType}`;
  const docRef = adminDb.collection(DEBOUNCE_COLLECTION).doc(docId);
  const doc = await docRef.get();

  if (!doc.exists) return false;

  const lastFiredAt = doc.data()?.lastFiredAt;
  if (!lastFiredAt) return false;

  const lastFiredDate = lastFiredAt.toDate ? lastFiredAt.toDate() : new Date(lastFiredAt);
  return lastFiredDate > cutoff;
}

async function recordAlertFired(
  projectId: string,
  alertType: LifecycleAlertType
): Promise<void> {
  const docId = `${projectId}_${alertType}`;
  await adminDb.collection(DEBOUNCE_COLLECTION).doc(docId).set(
    {
      projectId,
      alertType,
      lastFiredAt: FieldValue.serverTimestamp(),
    },
    { merge: true }
  );
}

// ── Date Helpers ──────────────────────────────────────────────────────────────

function toDate(val: any): Date | null {
  if (!val) return null;
  if (val.toDate) return val.toDate();
  const d = new Date(val);
  return isNaN(d.getTime()) ? null : d;
}

function daysBetween(from: Date, to: Date): number {
  return Math.round((to.getTime() - from.getTime()) / (1000 * 60 * 60 * 24));
}

function daysSince(date: Date): number {
  return daysBetween(date, new Date());
}

// ── Lifecycle Evaluators ──────────────────────────────────────────────────────

/**
 * Lease Renewal: 60 days before estimated lease end.
 * Uses acquisitionDate + 12 months as a naive lease end estimate for
 * Buy & Hold / Rent strategy projects, unless an explicit lease end is stored.
 */
function evaluateLeaseRenewal(
  projectData: FirebaseFirestore.DocumentData
): LifecycleAlertEvaluation {
  const isRental = projectData.dispositionType === 'RENT';

  if (!isRental) {
    return { alertType: 'LEASE_RENEWAL_DUE', triggered: false, daysUntil: null };
  }

  const acquisitionDate = toDate(projectData.financials?.acquisitionDate);
  if (!acquisitionDate) {
    return { alertType: 'LEASE_RENEWAL_DUE', triggered: false, daysUntil: null };
  }

  // Estimate lease end as 12 months from acquisition (annual lease assumption)
  const leaseEnd = new Date(acquisitionDate);
  leaseEnd.setFullYear(leaseEnd.getFullYear() + 1);

  // If lease end is in the past, bump it forward by years until it's in the future
  const now = new Date();
  while (leaseEnd < now) {
    leaseEnd.setFullYear(leaseEnd.getFullYear() + 1);
  }

  const daysUntil = daysBetween(now, leaseEnd);
  const threshold = 60; // days

  return {
    alertType: 'LEASE_RENEWAL_DUE',
    triggered: daysUntil <= threshold && daysUntil >= 0,
    daysUntil,
    deadlineDate: leaseEnd,
  };
}

/**
 * Property Tax: Alerts when property tax deadlines approach.
 * Uses common US semi-annual tax dates: April 10 and December 10.
 * Fires 30 days before each deadline.
 */
function evaluatePropertyTax(
  _projectData: FirebaseFirestore.DocumentData
): LifecycleAlertEvaluation {
  const now = new Date();
  const year = now.getFullYear();

  // Common US property tax due dates (varies by jurisdiction)
  const taxDates = [
    new Date(year, 3, 10),   // April 10
    new Date(year, 11, 10),  // December 10
    new Date(year + 1, 3, 10), // April 10 next year
  ];

  // Find the next upcoming tax date
  const nextDue = taxDates.find(d => d > now);
  if (!nextDue) {
    return { alertType: 'PROPERTY_TAX_DUE', triggered: false, daysUntil: null };
  }

  const daysUntil = daysBetween(now, nextDue);
  const threshold = 30; // days

  return {
    alertType: 'PROPERTY_TAX_DUE',
    triggered: daysUntil <= threshold && daysUntil >= 0,
    daysUntil,
    deadlineDate: nextDue,
  };
}

/**
 * Insurance Renewal: 30 days before annual insurance renewal.
 * Estimates renewal date as 12 months from acquisition.
 */
function evaluateInsuranceRenewal(
  projectData: FirebaseFirestore.DocumentData
): LifecycleAlertEvaluation {
  const acquisitionDate = toDate(projectData.financials?.acquisitionDate);
  if (!acquisitionDate) {
    return { alertType: 'INSURANCE_RENEWAL_DUE', triggered: false, daysUntil: null };
  }

  // Insurance policies typically renew annually from purchase
  const renewalDate = new Date(acquisitionDate);
  renewalDate.setFullYear(renewalDate.getFullYear() + 1);

  const now = new Date();
  while (renewalDate < now) {
    renewalDate.setFullYear(renewalDate.getFullYear() + 1);
  }

  const daysUntil = daysBetween(now, renewalDate);
  const threshold = 30; // days

  return {
    alertType: 'INSURANCE_RENEWAL_DUE',
    triggered: daysUntil <= threshold && daysUntil >= 0,
    daysUntil,
    deadlineDate: renewalDate,
  };
}

/**
 * Valuation Review: 6 months since last property value update.
 * Checks updatedAt or estimatedCurrentValue update timestamp.
 */
function evaluateValuationReview(
  projectData: FirebaseFirestore.DocumentData
): LifecycleAlertEvaluation {
  // Use project updatedAt as a proxy for when financials were last reviewed
  const lastUpdate = toDate(projectData.updatedAt);
  if (!lastUpdate) {
    return { alertType: 'VALUATION_REVIEW_DUE', triggered: false, daysUntil: null };
  }

  const daysSinceUpdate = daysSince(lastUpdate);
  const threshold = 180; // 6 months in days

  return {
    alertType: 'VALUATION_REVIEW_DUE',
    triggered: daysSinceUpdate >= threshold,
    daysUntil: daysSinceUpdate >= threshold ? 0 : threshold - daysSinceUpdate,
  };
}

// ── Main Evaluation ───────────────────────────────────────────────────────────

/**
 * Evaluates all lifecycle alerts for a single project.
 */
export async function evaluateLifecycleAlerts(
  projectId: string,
  projectData: FirebaseFirestore.DocumentData
): Promise<LifecycleAlertResult> {
  const address = projectData.address ?? projectData.propertyName ?? 'Unknown Property';
  const ownerUid = projectData.ownerUid;

  if (!ownerUid) {
    console.warn(`[LifecycleAlertEngine] Project ${projectId} has no ownerUid, skipping.`);
    return { projectId, evaluations: [], alertsFired: [], alertsDebounced: [] };
  }

  // Run all evaluations
  const evaluations: LifecycleAlertEvaluation[] = [
    evaluateLeaseRenewal(projectData),
    evaluatePropertyTax(projectData),
    evaluateInsuranceRenewal(projectData),
    evaluateValuationReview(projectData),
  ];

  const alertsFired: LifecycleAlertType[] = [];
  const alertsDebounced: LifecycleAlertType[] = [];

  for (const evaluation of evaluations) {
    if (!evaluation.triggered) continue;

    // Check debounce
    const debounced = await isDebounced(projectId, evaluation.alertType);
    if (debounced) {
      alertsDebounced.push(evaluation.alertType);
      continue;
    }

    // Build notification content
    const contentParams: AlertContentParams = {
      address,
      daysUntil: evaluation.daysUntil ?? undefined,
    };

    const title = buildAlertTitle(evaluation.alertType, contentParams);
    const body = buildAlertBody(evaluation.alertType, contentParams);
    const deepLinkUrl = buildAlertDeepLink(projectId, evaluation.alertType);
    const meta = ALERT_METADATA[evaluation.alertType];

    try {
      await NotificationService.createNotification({
        recipientId: ownerUid,
        type: meta.notificationType,
        actor: {
          uid: 'system',
          name: 'PaperWorking Lifecycle Engine',
        },
        objectReference: {
          projectId,
          dealAddress: address,
          time: evaluation.daysUntil != null
            ? `${evaluation.daysUntil} day${evaluation.daysUntil !== 1 ? 's' : ''}`
            : undefined,
          metadata: {
            alertType: evaluation.alertType,
            daysUntil: evaluation.daysUntil,
            deadlineDate: evaluation.deadlineDate?.toISOString(),
            title,
            body,
          },
        },
        deepLinkUrl,
        expiresAt: evaluation.deadlineDate,
      });

      await recordAlertFired(projectId, evaluation.alertType);
      alertsFired.push(evaluation.alertType);

      console.log(
        `[LifecycleAlertEngine] Fired ${evaluation.alertType} for ${address} (${projectId}): ` +
        `daysUntil=${evaluation.daysUntil}`
      );
    } catch (err) {
      console.error(
        `[LifecycleAlertEngine] Failed to fire ${evaluation.alertType} for ${projectId}:`,
        err
      );
    }
  }

  return { projectId, evaluations, alertsFired, alertsDebounced };
}

// ── Batch Scanner (for cron) ──────────────────────────────────────────────────

/**
 * Scans all active projects and evaluates lifecycle alerts.
 * Designed to be called daily from a cron route.
 *
 * @param organizationId Optional — scope to a single tenant
 * @param limit          Max projects to scan per run (default 200)
 */
export async function scanAllProjectsForLifecycleAlerts(
  organizationId?: string,
  limit = 200
): Promise<LifecycleAlertBatchResult> {
  const errors: Array<{ projectId: string; error: string }> = [];
  const results: LifecycleAlertResult[] = [];
  let totalAlertsFired = 0;
  let totalAlertsDebounced = 0;

  // Query active projects (not closed/sold)
  let query = adminDb.collection('projects')
    .where('status', 'in', ['Active', 'Under Contract', 'Renovating', 'Rented'])
    .limit(limit);

  if (organizationId) {
    query = adminDb.collection('projects')
      .where('organizationId', '==', organizationId)
      .where('status', 'in', ['Active', 'Under Contract', 'Renovating', 'Rented'])
      .limit(limit);
  }

  const snapshot = await query.get();

  for (const doc of snapshot.docs) {
    try {
      const result = await evaluateLifecycleAlerts(doc.id, doc.data());
      results.push(result);
      totalAlertsFired += result.alertsFired.length;
      totalAlertsDebounced += result.alertsDebounced.length;
    } catch (err: any) {
      errors.push({ projectId: doc.id, error: err.message ?? String(err) });
    }
  }

  console.log(
    `[LifecycleAlertEngine] Batch scan complete: ${snapshot.docs.length} projects, ` +
    `${totalAlertsFired} alerts fired, ${totalAlertsDebounced} debounced, ${errors.length} errors`
  );

  return {
    projectsScanned: snapshot.docs.length,
    totalAlertsFired,
    totalAlertsDebounced,
    errors,
    results,
  };
}

/**
 * src/lib/notifications/transactionNotifications.ts
 *
 * TransactionNotificationService — per-transaction email alerts.
 *
 * Entry points:
 *   onTransactionApproved(transactionId)  — call after any FinancialTransaction approval
 *   sendDailyDigest(userId)               — call from daily cron
 *   sendWeeklySummary(userId)             — call from weekly cron (Monday 9 AM)
 *   flushHourlyBatches()                  — call from hourly cron for HOURLY_BATCH users
 *
 * Email delivery via CommunicationEngine (Resend). Mocked in dev when RESEND_API_KEY absent.
 * Idempotency via SentEmailLog unique constraint (transactionId, templateType).
 * Batching via Firestore queued_emails collection (same pattern as the rest of the app).
 */

import { Prisma, FinancialTransactionCategory, FinancialTransactionStatus, EmailDigestMode, EmailAlertThreshold } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { adminDb } from '@/lib/firebase/admin';
import { getEmailProvider } from '@/lib/email/getEmailProvider';
import {
  CATEGORY_TO_TEMPLATE,
  type TransactionEmailTemplate,
  generateRentPaymentEmail,
  generateExpensePaidEmail,
  generateMortgagePaymentEmail,
  generateCapExEmail,
  generateAutoApprovedEmail,
  generateDailyDigestEmail,
  generateWeeklySummaryEmail,
} from '@/lib/emails/templates/TransactionNotificationEmails';

// ─── Constants ────────────────────────────────────────────────────────────────

const APP_URL = process.env.NEXT_PUBLIC_APP_URL || 'https://paperworking.co';
const FROM_EMAIL = process.env.RESEND_FROM_EMAIL || 'notifications@paperworking.co';

/**
 * All 12 categories from the spec that are enabled by default.
 * Stored as string[] in Prisma (Postgres text[]).
 */
export const DEFAULT_ALERT_CATEGORIES: FinancialTransactionCategory[] = [
  'RENT_INCOME',
  'LATE_FEE_INCOME',
  'PET_RENT_INCOME',
  'PROPERTY_TAX',
  'PROPERTY_INSURANCE',
  'MAINTENANCE_REPAIR',
  'UTILITIES',
  'MORTGAGE_PRINCIPAL',
  'MORTGAGE_INTEREST',
  'CAPITAL_EXPENDITURE',
  'SECURITY_DEPOSIT_RECEIVED',
  'OWNER_DISTRIBUTION',
];

const HIGH_CONFIDENCE_THRESHOLD = 0.85;

// ─── Internal helpers ─────────────────────────────────────────────────────────

/**
 * Resolves user email from Prisma AppUser table.
 */
async function getUserEmail(userId: string): Promise<string | null> {
  const user = await prisma.appUser.findUnique({
    where: { id: userId },
    select: { email: true },
  });
  return user?.email ?? null;
}

/**
 * Sends an email via configured system email provider (SendGrid, Resend, or Mock).
 */
async function dispatchEmail(opts: {
  to: string;
  subject: string;
  html: string;
  text: string;
}): Promise<{ messageId: string; mock: boolean }> {
  const provider = getEmailProvider();
  const res = await provider.sendEmail({
    to: [opts.to],
    subject: opts.subject,
    html: opts.html,
    text: opts.text,
  });

  if (!res.success) {
    throw new Error(`[TransactionNotifications] Email dispatch error (${res.provider}): ${res.error || 'Failed to send'}`);
  }

  return { messageId: res.messageId, mock: res.mock };
}

// ─── Main Service ─────────────────────────────────────────────────────────────

export class TransactionNotificationService {
  // ── Preferences helper ──────────────────────────────────────────────────────

  /**
   * Loads user notification preferences, creating defaults on first access.
   */
  static async getOrCreatePreferences(userId: string) {
    const existing = await prisma.userNotificationPreferences.findUnique({
      where: { userId },
    });
    if (existing) return existing;

    return prisma.userNotificationPreferences.create({
      data: {
        userId,
        emailTransactionAlerts: true,
        emailAlertCategories: DEFAULT_ALERT_CATEGORIES as string[],
        emailAlertMinAmount: new Prisma.Decimal(0),
        emailDigestMode: 'IMMEDIATE',
        emailAlertThreshold: 'ALL',
      },
    });
  }

  // ── Idempotent send ─────────────────────────────────────────────────────────

  /**
   * Idempotency-checked send. Writes SentEmailLog before dispatch.
   * Skips silently if (transactionId, templateType) already exists.
   */
  static async sendEmail(opts: {
    userId: string;
    to: string;
    subject: string;
    html: string;
    text: string;
    templateType: TransactionEmailTemplate;
    transactionId?: string;
  }): Promise<void> {
    // Governance Guard: Exclude synthetic investor crew accounts from outbound email dispatch
    if (opts.to && (opts.to.includes('+crew') || opts.to.endsWith('@paperworking.co'))) {
      console.info(`[TransactionNotifications] Skipped outbound email for synthetic test account: ${opts.to}`);
      return;
    }

    // Idempotency check — unique constraint on (transactionId, templateType)
    if (opts.transactionId) {
      try {
        await prisma.sentEmailLog.create({
          data: {
            userId: opts.userId,
            transactionId: opts.transactionId,
            templateType: opts.templateType,
            status: 'pending',
          },
        });
      } catch (err: unknown) {
        // Unique constraint violation = already sent
        if (
          err instanceof Prisma.PrismaClientKnownRequestError &&
          err.code === 'P2002'
        ) {
          console.info(
            `[TransactionNotifications] Duplicate blocked: ${opts.templateType} / ${opts.transactionId}`,
          );
          return;
        }
        throw err;
      }
    }

    let messageId = '';
    let status: 'sent' | 'failed' | 'mocked' = 'sent';

    try {
      const result = await dispatchEmail({
        to: opts.to,
        subject: opts.subject,
        html: opts.html,
        text: opts.text,
      });
      messageId = result.messageId;
      status = result.mock ? 'mocked' : 'sent';
    } catch (err) {
      status = 'failed';
      console.error('[TransactionNotifications] Dispatch failed:', err);
      // Update status in SentEmailLog if it was created
      if (opts.transactionId) {
        await prisma.sentEmailLog
          .update({
            where: {
              transactionId_templateType: {
                transactionId: opts.transactionId,
                templateType: opts.templateType,
              },
            },
            data: { status: 'failed' },
          })
          .catch(() => {/* swallow — SentEmailLog row may not exist for digest sends */});
      }
      return; // Don't throw — notification failures are non-fatal
    }

    // Update SentEmailLog with final messageId + status
    if (opts.transactionId) {
      await prisma.sentEmailLog
        .update({
          where: {
            transactionId_templateType: {
              transactionId: opts.transactionId,
              templateType: opts.templateType,
            },
          },
          data: { status, messageId },
        })
        .catch(() => {/* swallow */});
    }
  }

  // ── Hourly batch queue ──────────────────────────────────────────────────────

  /**
   * Enqueues a transaction for hourly batch delivery to the user's Firestore queue.
   * Uses the existing `queued_emails` collection pattern.
   */
  static async queueForBatch(userId: string, transactionId: string): Promise<void> {
    const docId = `txn_batch_${userId}_${transactionId}_${Date.now()}`;
    await adminDb.collection('queued_emails').doc(docId).set({
      id: docId,
      type: 'transaction_notification_batch',
      userId,
      transactionId,
      status: 'pending',
      queuedAt: new Date(),
      flushAt: null, // filled by flushHourlyBatches
    });
  }

  /**
   * Flushes all pending HOURLY_BATCH emails for all users.
   * Called by the hourly cron job.
   * Sends one email per user grouping all queued transactionIds.
   */
  static async flushHourlyBatches(): Promise<void> {
    const snap = await adminDb
      .collection('queued_emails')
      .where('type', '==', 'transaction_notification_batch')
      .where('status', '==', 'pending')
      .get();

    if (snap.empty) return;

    // Group by userId
    const byUser = new Map<string, string[]>();
    for (const doc of snap.docs) {
      const d = doc.data();
      const existing = byUser.get(d.userId) ?? [];
      existing.push(d.transactionId as string);
      byUser.set(d.userId, existing);
    }

    const batch = adminDb.batch();
    for (const doc of snap.docs) {
      batch.update(doc.ref, { status: 'flushing', flushAt: new Date() });
    }
    await batch.commit();

    // Send a batched digest email per user
    for (const [userId, txnIds] of byUser.entries()) {
      try {
        const userEmail = await getUserEmail(userId);
        if (!userEmail) continue;

        const txns = await prisma.financialTransaction.findMany({
          where: { id: { in: txnIds }, userId },
          include: { project: { select: { displayName: true, addressLine: true, id: true } } },
          orderBy: { transactionDate: 'desc' },
        });

        const totalIn = txns
          .filter((t) => t.direction === 'CREDIT')
          .reduce((s, t) => s + Number(t.amount), 0);
        const totalOut = txns
          .filter((t) => t.direction === 'DEBIT')
          .reduce((s, t) => s + Number(t.amount), 0);

        const { subject, html, text } = generateDailyDigestEmail({
          userId,
          date: new Date(),
          individualAlertsToday: 0,
          transactions: txns.map((t) => ({
            amount: t.direction === 'DEBIT' ? -Number(t.amount) : Number(t.amount),
            payee: t.payee,
            category: t.category,
            status: t.status,
          })),
          totalIn,
          totalOut,
          netCashFlow: totalIn - totalOut,
        });

        await TransactionNotificationService.sendEmail({
          userId,
          to: userEmail,
          subject,
          html,
          text,
          templateType: 'TRANSACTION_DAILY_DIGEST',
          // No transactionId — batch digest is not idempotency-keyed per transaction
        });
      } catch (err) {
        console.error(`[TransactionNotifications] Batch flush failed for user ${userId}:`, err);
      }
    }

    // Mark all as done
    const doneBatch = adminDb.batch();
    for (const doc of snap.docs) {
      doneBatch.update(doc.ref, { status: 'done' });
    }
    await doneBatch.commit();
  }

  // ── Primary entry point ─────────────────────────────────────────────────────

  /**
   * Called after any FinancialTransaction is approved.
   * Applies all preference gates, selects the correct template, and dispatches.
   */
  static async onTransactionApproved(transactionId: string): Promise<void> {
    // 1. Load transaction with all needed relations
    // NOTE: We fetch user email separately to avoid Prisma deep-include type inference
    // narrowing that loses the nested relation types under certain tsconfig strictness.
    const txn = await prisma.financialTransaction.findUnique({
      where: { id: transactionId },
      include: {
        project: {
          select: { id: true, displayName: true, addressLine: true },
        },
        plaidLiability: {
          select: {
            lastStatementBalance: true,
            nextPaymentAmount: true,
            nextPaymentDueDate: true,
            lastPaymentAmount: true,
          },
        },
        recurringRule: {
          select: { id: true, name: true },
        },
      },
    });

    if (!txn) {
      console.warn(`[TransactionNotifications] Transaction ${transactionId} not found`);
      return;
    }

    const userId = txn.userId;
    // Fetch user email via the dedicated helper (avoids deep include type narrowing)
    const userEmail = await getUserEmail(userId);
    if (!userEmail) {
      console.warn(`[TransactionNotifications] No email for user ${userId}, skipping`);
      return;
    }

    // 2. Load/create preferences
    const prefs = await TransactionNotificationService.getOrCreatePreferences(userId);

    // 3. Gate: master switch
    if (!prefs.emailTransactionAlerts) return;

    // 4. Gate: category filter
    if (!prefs.emailAlertCategories.includes(txn.category)) return;

    // 5. Gate: amount threshold
    const amount = Number(txn.amount);
    const minAmount = Number(prefs.emailAlertMinAmount);
    if (amount < minAmount) return;

    // 6. Gate: confidence threshold
    if (
      prefs.emailAlertThreshold === 'HIGH_CONFIDENCE_ONLY' &&
      (txn.confidenceScore == null || txn.confidenceScore < HIGH_CONFIDENCE_THRESHOLD)
    ) {
      return;
    }

    // 7. Gate: manual approval only
    if (
      prefs.emailAlertThreshold === 'MANUAL_APPROVAL_ONLY' &&
      txn.status === 'AUTO_APPROVED'
    ) {
      return;
    }

    // 8. Select template
    // Auto-approved by rule takes precedence over category template
    const templateType: TransactionEmailTemplate =
      txn.status === ('AUTO_APPROVED' as FinancialTransactionStatus) && txn.recurringRule
        ? 'AUTO_APPROVED_BY_RULE'
        : CATEGORY_TO_TEMPLATE[txn.category] ?? 'EXPENSE_PAID';

    const projectName =
      txn.project.displayName || txn.project.addressLine || 'Your Property';
    const projectId = txn.project.id;

    // 9. Build template context and generate email content
    let subject: string;
    let html: string;
    let text: string;

    if (templateType === 'AUTO_APPROVED_BY_RULE' && txn.recurringRule) {
      ({ subject, html, text } = generateAutoApprovedEmail({
        amount,
        payee: txn.payee,
        category: txn.category,
        transactionDate: txn.transactionDate,
        projectName,
        projectId,
        ruleName: txn.recurringRule.name,
        ruleId: txn.recurringRule.id,
        transactionId: txn.id,
      }));
    } else if (templateType === 'RENT_PAYMENT_RECEIVED') {
      ({ subject, html, text } = generateRentPaymentEmail({
        amount,
        payee: txn.payee,
        tenantName: null,
        unitNumber: null,
        transactionDate: txn.transactionDate,
        projectName,
        projectId,
        cashOnCashPct: (txn.kpiImpactSnapshot as Record<string, number> | null)
          ?.cashOnCashReturnPct ?? null,
        monthlyCashFlow: (txn.kpiImpactSnapshot as Record<string, number> | null)
          ?.monthlyCashFlow ?? null,
        grossRentYtd: (txn.kpiImpactSnapshot as Record<string, number> | null)
          ?.grossRentYtd ?? null,
      }));
    } else if (templateType === 'MORTGAGE_PAYMENT_PROCESSED') {
      const liability = txn.plaidLiability;
      ({ subject, html, text } = generateMortgagePaymentEmail({
        totalAmount: amount,
        principal: null,
        interest: null,
        escrow: null,
        newLoanBalance: liability?.lastStatementBalance != null ? Number(liability.lastStatementBalance) : null,
        nextPaymentDate: liability?.nextPaymentDueDate ?? null,
        transactionDate: txn.transactionDate,
        projectName,
        projectId,
        dscr: (txn.kpiImpactSnapshot as Record<string, number> | null)?.dscr ?? null,
        ytdInterestPaid: null,
      }));
    } else if (templateType === 'CAPITAL_EXPENDITURE_RECORDED') {
      ({ subject, html, text } = generateCapExEmail({
        amount,
        description: txn.description,
        payee: txn.payee,
        transactionDate: txn.transactionDate,
        projectName,
        projectId,
      }));
    } else {
      // EXPENSE_PAID (default)
      ({ subject, html, text } = generateExpensePaidEmail({
        amount,
        payee: txn.payee,
        category: txn.category,
        subCategory: txn.subCategory,
        transactionDate: txn.transactionDate,
        projectName,
        projectId,
        operatingExpensesMtd: null,
        noi: (txn.kpiImpactSnapshot as Record<string, number> | null)?.noi ?? null,
        cashFlow: (txn.kpiImpactSnapshot as Record<string, number> | null)?.annualCashFlow ?? null,
      }));
    }

    // 10. Dispatch or queue
    if (prefs.emailDigestMode === 'IMMEDIATE') {
      await TransactionNotificationService.sendEmail({
        userId,
        to: userEmail,
        subject,
        html,
        text,
        templateType,
        transactionId: txn.id,
      });
    } else if (prefs.emailDigestMode === 'HOURLY_BATCH') {
      await TransactionNotificationService.queueForBatch(userId, txn.id);
    } else {
      // DAILY_DIGEST — enqueue with a day-level flush key
      const docId = `txn_daily_${userId}_${txn.id}`;
      await adminDb.collection('queued_emails').doc(docId).set({
        id: docId,
        type: 'transaction_notification_daily',
        userId,
        transactionId: txn.id,
        status: 'pending',
        queuedAt: new Date(),
      });
    }
  }

  // ── Daily digest ────────────────────────────────────────────────────────────

  /**
   * Sends a daily digest email for the given user.
   * Summarises all transactions approved today.
   */
  static async sendDailyDigest(userId: string): Promise<void> {
    const userEmail = await getUserEmail(userId);
    if (!userEmail) return;

    const prefs = await TransactionNotificationService.getOrCreatePreferences(userId);
    if (!prefs.emailTransactionAlerts) return;

    const today = new Date();
    const startOfDay = new Date(today.getFullYear(), today.getMonth(), today.getDate());
    const endOfDay = new Date(startOfDay.getTime() + 86_400_000);

    const txns = await prisma.financialTransaction.findMany({
      where: {
        userId,
        status: { in: ['AUTO_APPROVED', 'MANUALLY_APPROVED'] },
        reviewedAt: { gte: startOfDay, lt: endOfDay },
      },
      include: { project: { select: { id: true, displayName: true, addressLine: true } } },
      orderBy: { transactionDate: 'desc' },
    });

    // Count individual alerts sent today
    const alertsToday = await prisma.sentEmailLog.count({
      where: {
        userId,
        sentAt: { gte: startOfDay, lt: endOfDay },
        templateType: { not: 'TRANSACTION_DAILY_DIGEST' },
      },
    });

    const totalIn = txns
      .filter((t) => t.direction === 'CREDIT')
      .reduce((s, t) => s + Number(t.amount), 0);
    const totalOut = txns
      .filter((t) => t.direction === 'DEBIT')
      .reduce((s, t) => s + Number(t.amount), 0);

    const { subject, html, text } = generateDailyDigestEmail({
      userId,
      date: today,
      individualAlertsToday: alertsToday,
      transactions: txns.map((t) => ({
        amount: t.direction === 'DEBIT' ? -Number(t.amount) : Number(t.amount),
        payee: t.payee,
        category: t.category,
        status: t.status,
      })),
      totalIn,
      totalOut,
      netCashFlow: totalIn - totalOut,
    });

    await TransactionNotificationService.sendEmail({
      userId,
      to: userEmail,
      subject,
      html,
      text,
      templateType: 'TRANSACTION_DAILY_DIGEST',
      // No transactionId — digest is not per-transaction idempotency-keyed
    });
  }

  // ── Weekly summary ──────────────────────────────────────────────────────────

  /**
   * Sends the Monday 9 AM weekly investment summary for all projects of a user.
   * For multi-project portfolios, sends one combined email.
   */
  static async sendWeeklySummary(userId: string): Promise<void> {
    const userEmail = await getUserEmail(userId);
    if (!userEmail) return;

    const prefs = await TransactionNotificationService.getOrCreatePreferences(userId);
    if (!prefs.emailTransactionAlerts) return;

    const now = new Date();
    // Week: last 7 days
    const weekEnd = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const weekStart = new Date(weekEnd.getTime() - 7 * 86_400_000);

    // Get all projects for the user
    const projects = await prisma.reilProject.findMany({
      where: { createdById: userId },
      select: { id: true, displayName: true, addressLine: true },
      take: 10,
    });

    if (projects.length === 0) return;

    // For simplicity, send one email per user for their primary (first) project
    // or an aggregate if multi-project
    const project = projects[0];
    const projectName = project.displayName || project.addressLine || 'Your Property';

    const txns = await prisma.financialTransaction.findMany({
      where: {
        userId,
        projectId: project.id,
        transactionDate: { gte: weekStart, lt: weekEnd },
        status: { in: ['AUTO_APPROVED', 'MANUALLY_APPROVED'] },
      },
    });

    const rentCollected = txns
      .filter((t) => t.direction === 'CREDIT' && ['RENT_INCOME', 'LATE_FEE_INCOME', 'PET_RENT_INCOME'].includes(t.category))
      .reduce((s, t) => s + Number(t.amount), 0);

    const expensesPaid = txns
      .filter((t) => t.direction === 'DEBIT' && !['MORTGAGE_PRINCIPAL', 'MORTGAGE_INTEREST', 'MORTGAGE_ESCROW_PAYMENT', 'CAPITAL_EXPENDITURE'].includes(t.category))
      .reduce((s, t) => s + Number(t.amount), 0);

    const mortgagePaid = txns
      .filter((t) => ['MORTGAGE_PRINCIPAL', 'MORTGAGE_INTEREST', 'MORTGAGE_ESCROW_PAYMENT'].includes(t.category))
      .reduce((s, t) => s + Number(t.amount), 0);

    const netCashFlow = rentCollected - expensesPaid - mortgagePaid;

    // Top expense category
    const expenseByCat: Record<string, number> = {};
    for (const t of txns.filter((t) => t.direction === 'DEBIT')) {
      expenseByCat[t.category] = (expenseByCat[t.category] ?? 0) + Number(t.amount);
    }
    const topEntry = Object.entries(expenseByCat).sort(([, a], [, b]) => b - a)[0];

    const { subject, html, text } = generateWeeklySummaryEmail({
      projectName,
      projectId: project.id,
      weekStart,
      weekEnd,
      rentCollected,
      rentExpected: 0, // TODO: pull from Lease model when available
      expensesPaid,
      mortgagePaid,
      netCashFlow,
      topExpenseCategory: topEntry?.[0] ?? null,
      topExpenseAmount: topEntry?.[1] ?? null,
    });

    await TransactionNotificationService.sendEmail({
      userId,
      to: userEmail,
      subject,
      html,
      text,
      templateType: 'TRANSACTION_WEEKLY_SUMMARY',
    });
  }
}

/**
 * Phase 3 Operations & Asset Management Variance Engine
 * Single source of truth for budget baselines, actuals NOI, variance grading,
 * live rent roll occupancy, and consecutive period alert tracking.
 * All canonical metric values (NOI, Occupancy Rate) are sourced via deriveAllProjectMetrics.
 */

import { deriveAllProjectMetrics } from '@/lib/metrics/reiMetrics';
import type { Project } from '@/types/schema';
import type { UnderwritingAssumptions } from '@/lib/finance/metrics';

export interface PropertyActualEntry {
  id: string;
  projectId: string;
  period: string; // YYYY-MM
  grossRent: number;
  operatingExpenses: number;
  noi: number;
  capex?: number;
  notes?: string;
  createdAt?: string;
}

export interface RentRollItem {
  id: string;
  projectId: string;
  unit: string;
  tenantName?: string;
  leaseStart?: string;
  leaseEnd?: string;
  monthlyRent: number;
  status: 'occupied' | 'vacant' | 'notice';
  createdAt?: string;
}

export interface BudgetBaselineData {
  snapshottedAt: string;
  monthlyGrossRent: number;
  monthlyExpenses: number;
  monthlyNoi: number;
  underwritingAssumptions?: UnderwritingAssumptions;
}

export type VarianceStatus = 'green' | 'amber' | 'red';

export interface VarianceResult {
  actual: number;
  baseline: number;
  varianceAmount: number;
  variancePercent: number; // Signed percentage (e.g. +3.5 or -12.4)
  absPercent: number;
  status: VarianceStatus; // green: <= ±5%, amber: <= ±10%, red: > ±10%
}

/**
 * Calculate Variance between Actual and Baseline value
 * For Revenue/NOI: Actual > Baseline is positive variance (good).
 * For Expenses: Actual > Baseline is positive expense overage (higher cost).
 * Status Grading:
 * - Green: |variancePercent| <= 5%
 * - Amber: 5% < |variancePercent| <= 10%
 * - Red: |variancePercent| > 10%
 */
export function calculateVariance(actual: number, baseline: number): VarianceResult {
  const varianceAmount = actual - baseline;
  if (baseline === 0) {
    const status: VarianceStatus = actual === 0 ? 'green' : 'red';
    return {
      actual,
      baseline,
      varianceAmount,
      variancePercent: 0,
      absPercent: 0,
      status,
    };
  }

  const variancePercent = Number(((varianceAmount / baseline) * 100).toFixed(2));
  const absPercent = Math.abs(variancePercent);

  let status: VarianceStatus = 'green';
  if (absPercent > 10) {
    status = 'red';
  } else if (absPercent > 5) {
    status = 'amber';
  }

  return {
    actual,
    baseline,
    varianceAmount,
    variancePercent,
    absPercent,
    status,
  };
}

/**
 * Calculate Cumulative Variance across all entered periods
 */
export function calculateCumulativeVariance(
  actuals: PropertyActualEntry[],
  monthlyBaseline: BudgetBaselineData
) {
  const periodCount = actuals.length;
  if (periodCount === 0) {
    return {
      grossRent: calculateVariance(0, 0),
      operatingExpenses: calculateVariance(0, 0),
      noi: calculateVariance(0, 0),
      totalCapex: 0,
      periodCount: 0,
    };
  }

  const totalActualGrossRent = actuals.reduce((sum, a) => sum + a.grossRent, 0);
  const totalActualExpenses = actuals.reduce((sum, a) => sum + a.operatingExpenses, 0);
  const totalActualNoi = actuals.reduce((sum, a) => sum + (a.noi ?? (a.grossRent - a.operatingExpenses)), 0);
  const totalCapex = actuals.reduce((sum, a) => sum + (a.capex || 0), 0);

  const cumBaselineGrossRent = monthlyBaseline.monthlyGrossRent * periodCount;
  const cumBaselineExpenses = monthlyBaseline.monthlyExpenses * periodCount;
  const cumBaselineNoi = monthlyBaseline.monthlyNoi * periodCount;

  return {
    grossRent: calculateVariance(totalActualGrossRent, cumBaselineGrossRent),
    operatingExpenses: calculateVariance(totalActualExpenses, cumBaselineExpenses),
    noi: calculateVariance(totalActualNoi, cumBaselineNoi),
    totalCapex,
    periodCount,
  };
}

/**
 * Check if 2+ consecutive periods have significant variance (> ±10% on NOI or Gross Rent)
 */
export function checkConsecutiveVarianceAlert(
  actuals: PropertyActualEntry[],
  baseline: BudgetBaselineData
): boolean {
  if (actuals.length < 2) return false;

  const sorted = [...actuals].sort((a, b) => a.period.localeCompare(b.period));

  let consecutiveCount = 0;

  for (const act of sorted) {
    const noiVar = calculateVariance(act.noi ?? (act.grossRent - act.operatingExpenses), baseline.monthlyNoi);
    const rentVar = calculateVariance(act.grossRent, baseline.monthlyGrossRent);

    if (noiVar.absPercent > 10 || rentVar.absPercent > 10) {
      consecutiveCount++;
      if (consecutiveCount >= 2) return true;
    } else {
      consecutiveCount = 0;
    }
  }

  return false;
}

/**
 * Freeze and snapshot budget baseline from project underwriting / financials
 * Sourced via deriveAllProjectMetrics.
 */
export function snapshotBudgetBaseline(project: Project): BudgetBaselineData {
  const existing = (project.financials as any)?.budgetBaseline;
  if (existing && existing.monthlyGrossRent > 0) {
    return existing; // Return frozen baseline
  }

  const derived = deriveAllProjectMetrics(project);
  const f: any = project.financials || {};
  const monthlyGrossRent = f.monthlyGrossRent ?? (f.purchasePrice ? (f.purchasePrice * 0.01) / 12 : 2500);
  const monthlyExpenses = f.monthlyExpenses ?? 800;
  const monthlyNoi = Math.round(((derived.noi ?? 0) / 12) * 100) / 100;

  return {
    snapshottedAt: new Date().toISOString(),
    monthlyGrossRent,
    monthlyExpenses,
    monthlyNoi,
    underwritingAssumptions: {
      purchasePrice: f.purchasePrice || 250000,
      rehabCost: f.projectedRehabCost ?? f.rehabBudget ?? 30000,
      monthlyGrossRent,
      monthlyExpenses,
      rentGrowthRate: f.rentGrowthRate ?? 3.0,
      expenseGrowthRate: f.expenseGrowthRate ?? 2.5,
      vacancyRate: f.vacancyRate ?? 5.0,
      capexReservePct: f.capexReservePct ?? 5.0,
      loanAmount: f.loanAmount || 200000,
      interestRate: f.loanInterestRate ?? 6.5,
      amortizationYears: 30,
      exitCapRate: f.exitCapRate ?? 6.0,
      holdingPeriodYears: 5,
    },
  };
}

