/**
 * PlacesRateLimit — DM-3 Server-Side Rate Limiting
 *
 * Redis sliding window counter per authenticated user per endpoint.
 * Non-blocking: if Redis is unavailable, the request proceeds (fail-open).
 */

import redis from '@/lib/redis';

export type PlacesEndpoint =
  | 'autocomplete'
  | 'placeDetails'
  | 'geocode'
  | 'addressValidation'
  | 'staticMaps'
  | 'streetView'
  | 'cardExchange';

const RATE_LIMITS: Record<PlacesEndpoint, { max: number; windowSeconds: number }> = {
  autocomplete:       { max: 60,  windowSeconds: 60 },
  placeDetails:       { max: 20,  windowSeconds: 60 },
  geocode:            { max: 30,  windowSeconds: 60 },
  addressValidation:  { max: 10,  windowSeconds: 60 },
  staticMaps:         { max: 100, windowSeconds: 60 },
  streetView:         { max: 100, windowSeconds: 60 },
  cardExchange:       { max: 15,  windowSeconds: 60 },
};

const PREFIX = 'places:ratelimit:';

function isRedisReady(): boolean {
  try {
    return redis.status === 'ready';
  } catch {
    return false;
  }
}

export interface RateLimitResult {
  allowed: boolean;
  remaining: number;
  limit: number;
  retryAfterSeconds?: number;
}

/**
 * Check and increment the rate limit counter for a user + endpoint.
 * Uses Redis INCR with TTL (sliding window approximation).
 *
 * Returns { allowed, remaining, limit, retryAfterSeconds? }.
 * If Redis is unavailable, always returns allowed: true (fail-open).
 */
export async function checkRateLimit(
  uid: string,
  endpoint: PlacesEndpoint,
): Promise<RateLimitResult> {
  const config = RATE_LIMITS[endpoint];
  if (!config) {
    return { allowed: true, remaining: 999, limit: 999 };
  }

  if (!isRedisReady()) {
    // Fail-open: if Redis is down, don't block requests
    return { allowed: true, remaining: config.max, limit: config.max };
  }

  const key = `${PREFIX}${uid}:${endpoint}`;

  try {
    const current = await redis.incr(key);

    // Set TTL on first increment
    if (current === 1) {
      await redis.expire(key, config.windowSeconds);
    }

    if (current > config.max) {
      const ttl = await redis.ttl(key);
      return {
        allowed: false,
        remaining: 0,
        limit: config.max,
        retryAfterSeconds: ttl > 0 ? ttl : config.windowSeconds,
      };
    }

    return {
      allowed: true,
      remaining: config.max - current,
      limit: config.max,
    };
  } catch {
    // Redis error — fail-open
    return { allowed: true, remaining: config.max, limit: config.max };
  }
}

/**
 * Utility to create a NextResponse for rate limit exceeded.
 */
export function rateLimitResponse(result: RateLimitResult) {
  const { NextResponse } = require('next/server');
  return NextResponse.json(
    {
      error: 'Rate limit exceeded',
      limit: result.limit,
      retryAfterSeconds: result.retryAfterSeconds,
    },
    {
      status: 429,
      headers: {
        'Retry-After': String(result.retryAfterSeconds || 60),
        'X-RateLimit-Limit': String(result.limit),
        'X-RateLimit-Remaining': '0',
      },
    },
  );
}

import crypto from 'crypto';
import { Configuration, PlaidApi, PlaidEnvironments } from 'plaid';
import * as Sentry from '@sentry/nextjs';

export type WebhookVerificationReason =
  | 'missing_header'
  | 'no_kid'
  | 'malformed_jwt'
  | 'unknown_kid'
  | 'bad_signature'
  | 'expired'
  | 'body_hash_mismatch';

export interface WebhookVerificationResult {
  isValid: boolean;
  reason?: WebhookVerificationReason;
}

// Module-scoped in-memory cache for Plaid verification JWKs
const jwkCache = new Map<string, any>();

/**
 * Clear the in-memory JWK cache (useful for test setup/teardown).
 */
export function clearJwkCache(): void {
  jwkCache.clear();
}

/**
 * Get a cached JWK by key ID (kid).
 */
export function getCachedJwk(kid: string): any | undefined {
  return jwkCache.get(kid);
}

/**
 * Manually populate a cached JWK (useful for test suites).
 */
export function setCachedJwk(kid: string, jwk: any): void {
  jwkCache.set(kid, jwk);
}

/**
 * Resolves or instantiates a Plaid API client from environment variables.
 */
function getPlaidClient(): PlaidApi | null {
  const clientId = process.env.PLAID_CLIENT_ID;
  const secret = process.env.PLAID_SECRET;
  const env = process.env.PLAID_ENV || 'sandbox';

  if (!clientId || !secret) {
    return null;
  }

  const basePath = PlaidEnvironments[env] ?? PlaidEnvironments.sandbox;
  const configuration = new Configuration({
    basePath,
    baseOptions: {
      headers: {
        'PLAID-CLIENT-ID': clientId,
        'PLAID-SECRET': secret,
      },
    },
  });

  return new PlaidApi(configuration);
}

/**
 * Fetches a webhook verification JWK from Plaid's /webhook_verification_key/get endpoint.
 * Caches the JWK in module scope.
 */
async function fetchWebhookVerificationKey(
  kid: string,
  customPlaidClient?: PlaidApi
): Promise<any | null> {
  // Check in-memory cache first
  if (jwkCache.has(kid)) {
    return jwkCache.get(kid);
  }

  try {
    const client = customPlaidClient ?? getPlaidClient();
    if (!client) {
      return null;
    }

    const response = await client.webhookVerificationKeyGet({ key_id: kid });
    const jwk = response.data?.key;
    if (jwk) {
      jwkCache.set(kid, jwk);
      return jwk;
    }
  } catch {
    // Non-fatal error fetch handling — returns null so caller handles rejection
  }

  return null;
}

/**
 * Verifies an ES256 JWT signature against a JWK using Node.js crypto.
 */
function verifyEs256Signature(
  signingInput: string,
  signatureB64Url: string,
  jwk: any
): boolean {
  try {
    const publicKey = crypto.createPublicKey({
      key: jwk,
      format: 'jwk',
    });

    const signature = Buffer.from(signatureB64Url, 'base64url');

    // 1. Try ieee-p1363 (standard 64-byte raw r||s signature format for ES256 JWTs)
    try {
      const isValidP1363 = crypto.verify(
        'SHA256',
        Buffer.from(signingInput, 'utf8'),
        {
          key: publicKey,
          dsaEncoding: 'ieee-p1363',
        },
        signature
      );
      if (isValidP1363) return true;
    } catch {
      // Fall through to DER verification
    }

    // 2. Fallback to DER encoding if ieee-p1363 fails
    return crypto.verify(
      'SHA256',
      Buffer.from(signingInput, 'utf8'),
      publicKey,
      signature
    );
  } catch {
    return false;
  }
}

/**
 * Timing-safe comparison of SHA-256 body hashes.
 */
function verifyBodyHash(rawBody: string, expectedHash: string): boolean {
  const computedHash = crypto.createHash('sha256').update(rawBody, 'utf8').digest('hex');
  if (computedHash.length !== expectedHash.length) {
    return false;
  }
  return crypto.timingSafeEqual(Buffer.from(computedHash, 'utf8'), Buffer.from(expectedHash, 'utf8'));
}

/**
 * Verifies the Plaid-Verification JWT header against Plaid's official verification protocol:
 * 1. Checks Plaid-Verification header existence.
 * 2. Decodes JWT header to extract kid.
 * 3. Fetches & caches JWK from Plaid's /webhook_verification_key/get endpoint.
 * 4. Verifies ES256 JWT signature.
 * 5. Validates iat freshness (max 5 minutes / 300s).
 * 6. Validates SHA-256 hash of raw request body against request_body_sha256 claim.
 */
export async function verifyPlaidWebhook(
  headerValue: string | null | undefined,
  rawBody: string,
  options?: {
    customPlaidClient?: PlaidApi;
    nowSeconds?: number;
    requestPath?: string;
  }
): Promise<WebhookVerificationResult> {
  const timestamp = new Date().toISOString();
  const requestPath = options?.requestPath ?? '/api/webhooks/plaid';

  const logRejection = (reason: WebhookVerificationReason) => {
    console.warn(
      `[Plaid Webhook Verification] Rejected request: reason=${reason}, path=${requestPath}, timestamp=${timestamp}`
    );
    try {
      Sentry.captureMessage(`[Plaid Webhook] Verification rejected: ${reason}`, {
        level: 'warning',
        tags: { reason, path: requestPath },
      });
    } catch {
      // Non-fatal Sentry error handling
    }
  };

  // a. Read Plaid-Verification header
  if (!headerValue || !headerValue.trim()) {
    logRejection('missing_header');
    return { isValid: false, reason: 'missing_header' };
  }

  // b. Decode JWT
  const parts = headerValue.trim().split('.');
  if (parts.length !== 3) {
    logRejection('malformed_jwt');
    return { isValid: false, reason: 'malformed_jwt' };
  }

  const [headerB64, payloadB64, signatureB64] = parts;

  let header: { kid?: string; alg?: string };
  let payload: { iat?: number; request_body_sha256?: string };

  try {
    header = JSON.parse(Buffer.from(headerB64, 'base64url').toString('utf8'));
    payload = JSON.parse(Buffer.from(payloadB64, 'base64url').toString('utf8'));
  } catch {
    logRejection('malformed_jwt');
    return { isValid: false, reason: 'malformed_jwt' };
  }

  const kid = header.kid;
  if (!kid || typeof kid !== 'string') {
    logRejection('no_kid');
    return { isValid: false, reason: 'no_kid' };
  }

  // c. Fetch JWK (with module-scoped cache)
  let jwk = await fetchWebhookVerificationKey(kid, options?.customPlaidClient);
  if (!jwk) {
    logRejection('unknown_kid');
    return { isValid: false, reason: 'unknown_kid' };
  }

  // d. Verify signature against JWK
  const signingInput = `${headerB64}.${payloadB64}`;
  let isSigValid = verifyEs256Signature(signingInput, signatureB64, jwk);

  // Key rotation handling: if signature failed and key was cached, refresh key once
  if (!isSigValid && jwkCache.has(kid)) {
    jwkCache.delete(kid);
    jwk = await fetchWebhookVerificationKey(kid, options?.customPlaidClient);
    if (jwk) {
      isSigValid = verifyEs256Signature(signingInput, signatureB64, jwk);
    }
  }

  if (!isSigValid) {
    logRejection('bad_signature');
    return { isValid: false, reason: 'bad_signature' };
  }

  // e. Validate iat (5 minute window = 300 seconds, with 10s skew allowance)
  const iat = payload.iat;
  const now = options?.nowSeconds ?? Math.floor(Date.now() / 1000);

  if (typeof iat !== 'number' || now - iat > 300 || iat - now > 10) {
    logRejection('expired');
    return { isValid: false, reason: 'expired' };
  }

  // f. Validate request_body_sha256
  const requestBodySha256 = payload.request_body_sha256;
  if (typeof requestBodySha256 !== 'string' || !verifyBodyHash(rawBody, requestBodySha256)) {
    logRejection('body_hash_mismatch');
    return { isValid: false, reason: 'body_hash_mismatch' };
  }

  return { isValid: true };
}

/**
 * Prisma 7 requires a driver adapter — new PrismaClient() alone throws.
 * We use PrismaNeonHttp (HTTP transport) which works in serverless/edge.
 * @prisma/adapter-neon must be installed: npm i @prisma/adapter-neon
 */
import { PrismaClient } from '@prisma/client';
import { PrismaNeonHttp } from '@prisma/adapter-neon';

export function sanitizeDbRecord<T>(record: T): any {
  if (record === null || record === undefined) return record;

  if (typeof record === 'bigint') {
    return record <= BigInt(Number.MAX_SAFE_INTEGER)
      ? Number(record)
      : record.toString();
  }

  if (record instanceof Date) {
    return record;
  }

  if (Array.isArray(record)) {
    return record.map(sanitizeDbRecord);
  }

  if (typeof record === 'object') {
    const result: Record<string, any> = {};
    for (const key of Object.keys(record)) {
      result[key] = sanitizeDbRecord((record as any)[key]);
    }
    return result;
  }

  return record;
}

function createPrismaClient(): PrismaClient {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is not set');

  if (process.env.PRISMA_USE_WS === 'true') {
    const { PrismaNeon } = require('@prisma/adapter-neon');
    const { Pool, neonConfig } = require('@neondatabase/serverless');
    const ws = require('ws');
    neonConfig.webSocketConstructor = ws;

    // Parse connection string to populate standard PG env vars for pg-client
    const match = url.match(/postgresql:\/\/([^:]+):([^@]+)@([^:/]+)(?::(\d+))?\/([^?]+)/);
    if (match) {
      process.env.PGUSER = match[1];
      process.env.PGPASSWORD = match[2];
      process.env.PGHOST = match[3];
      process.env.PGPORT = match[4] || '5432';
      process.env.PGDATABASE = match[5];
    }

    const pool = new Pool({ connectionString: url });
    const adapter = new PrismaNeon(pool);
    return new PrismaClient({ adapter });
  }

  const adapter = new PrismaNeonHttp(url, {});
  return new PrismaClient({ adapter });
}

declare global {
  var _prisma: PrismaClient | undefined;
}

function getPrismaClient(): PrismaClient {
  if (!globalThis._prisma) {
    globalThis._prisma = createPrismaClient();
  }
  return globalThis._prisma;
}

// Proxy defers construction until first DB call — safe at build time.
const prisma: PrismaClient = new Proxy({} as PrismaClient, {
  get(_target, prop: string | symbol) {
    return (getPrismaClient() as any)[prop];
  },
});

export { getPrismaClient, prisma };
export default prisma;

import type { Project } from '@/types/schema';
import type { InsightsEngineInputs } from '@/lib/services/insightsEngine';
import { computeNOIComponents } from '@/lib/metrics/reiMetrics';

/**
 * Human-readable labels for the fields required to compute a projection.
 * Used by the missing-data gate UI.
 */
export const REQUIRED_INSIGHTS_FIELDS = ['Purchase Price', 'Monthly Gross Rent'];

/**
 * Maps a single Project's financials to InsightsEngineInputs.
 *
 * Returns null when either required input is absent — callers must show
 * the missing-data gate rather than rendering any projection charts.
 *
 * Never throws; always returns InsightsEngineInputs | null.
 */
export function projectToInsightsInputs(project: Project): InsightsEngineInputs | null {
  const f = project.financials;
  if (!f) return null;

  const purchasePrice =
    f.purchasePrice || f.targetPurchasePrice || (f as any).targetPrice || 0;

  const monthlyGrossRent =
    f.monthlyGrossRent ?? f.projectedMonthlyRent ?? f.projectedRent ?? 0;

  // Gate: both required inputs must be non-zero
  if (purchasePrice <= 0 || monthlyGrossRent <= 0) return null;

  const rehabBudget = f.rehabBudget || f.projectedRehabCost || f.rehabActual || 0;
  const loanAmount = f.loanAmount ?? 0;
  const downPayment = Math.max(0, purchasePrice - loanAmount);
  const interestRate = f.loanInterestRate ?? 6.0;
  const amortizationTerm = f.loanTermYears ?? f.amortizationYears ?? 30;
  const otherMonthlyIncome =
    f.otherMonthlyIncome ??
    ((f.grossIncomeParking ?? 0) + (f.grossIncomeLaundry ?? 0));
  const grossScheduledIncome = (monthlyGrossRent + otherMonthlyIncome) * 12;
  const vacancyRate = f.vacancyRatePercent ?? (f.vacancyRate ?? 5);

  const noiComponents = computeNOIComponents(f, project.dispositionType, project.currentPhase);
  const operatingExpenses = noiComponents.totalOperatingExpenses;

  const medianHomePrice =
    f.estimatedCurrentValue ||
    f.estimatedARV ||
    purchasePrice * 1.05;

  return {
    purchasePrice,
    rehabBudget,
    downPayment,
    interestRate,
    amortizationTerm,
    grossScheduledIncome,
    operatingExpenses,
    vacancyRate,
    marketData: {
      daysOnMarket: 45,
      medianHomePrice,
      averageRent: monthlyGrossRent,
    },
  };
}

