    });
  }

  async getValueEstimate(addressOrPlaceId: string): Promise<ValueEstimate> {
    await new Promise(r => setTimeout(r, 300));
    const h = hashCode(addressOrPlaceId);
    const price = seeded(h, 250_000, 1_200_000);
    return {
      priceCents: price * 100,
      priceLowCents: Math.round(price * 0.85) * 100,
      priceHighCents: Math.round(price * 1.15) * 100,
      source: "mock",
      fetchedAt: new Date(),
    };
  }
}

export class RentCastPropertyProvider implements PropertyDataProvider {
  private client: import('@/lib/providers/rentcast').RentCastClient;

  constructor(client: import('@/lib/providers/rentcast').RentCastClient) {
    this.client = client;
  }

  private async getRentEstimateWithWidening(address: string, maxRadius = 5, daysOld = 180): Promise<any> {
    const { logger } = require('@/lib/logger');
    try {
      return await this.client.getRentEstimate({ address, maxRadius, daysOld });
    } catch (err) {
      const isCompError = err instanceof Error && (
        err.message.toLowerCase().includes('comp') ||
        err.message.toLowerCase().includes('insufficient') ||
        err.message.toLowerCase().includes('comparables')
      );
      if (isCompError) {
        if (maxRadius === 5 && daysOld === 180) {
          logger.warn(`[RentCast Property Provider] Not enough comps at 5mi/180d, retrying at 10mi/365d...`);
          return this.getRentEstimateWithWidening(address, 10, 365);
        } else if (maxRadius === 10 && daysOld === 365) {
          logger.warn(`[RentCast Property Provider] Not enough comps at 10mi/365d, retrying at 15mi/730d...`);
          return this.getRentEstimateWithWidening(address, 15, 730);
        }
      }
      throw err;
    }
  }

  private async getValueEstimateWithWidening(address: string, maxRadius = 5, daysOld = 180): Promise<any> {
    const { logger } = require('@/lib/logger');
    try {
      return await this.client.getValueEstimate({ address, maxRadius, daysOld });
    } catch (err) {
      const isCompError = err instanceof Error && (
        err.message.toLowerCase().includes('comp') ||
        err.message.toLowerCase().includes('insufficient') ||
        err.message.toLowerCase().includes('comparables')
      );
      if (isCompError) {
        if (maxRadius === 5 && daysOld === 180) {
          logger.warn(`[RentCast Property Provider] Not enough comps at 5mi/180d, retrying at 10mi/365d...`);
          return this.getValueEstimateWithWidening(address, 10, 365);
        } else if (maxRadius === 10 && daysOld === 365) {
          logger.warn(`[RentCast Property Provider] Not enough comps at 10mi/365d, retrying at 15mi/730d...`);
          return this.getValueEstimateWithWidening(address, 15, 730);
        }
      }
      throw err;
    }
  }

  async getFacts(addressOrPlaceId: string): Promise<PropertyFacts> {
    try {
      // Fire /properties, getRentEstimate, and getValueEstimate in parallel
      const [propResult, rentResult, valueResult] = await Promise.allSettled([
        this.client.getProperties({ address: addressOrPlaceId }),
        this.getRentEstimateWithWidening(addressOrPlaceId),
        this.getValueEstimateWithWidening(addressOrPlaceId),
      ]);

      const properties = propResult.status === 'fulfilled' ? propResult.value : null;
      const rentData   = rentResult.status === 'fulfilled' ? rentResult.value : null;
      const valueData  = valueResult.status === 'fulfilled' ? valueResult.value : null;

      const subject = (properties && properties.length > 0) ? properties[0] : null;

      if (!subject) {
        throw new PropertyNotFoundError(`No property record found for: ${addressOrPlaceId}`);
      }

      // ── Extract last sale from history ──────────────────────────────────────
      let lastSoldPrice: number | undefined;
      let lastSoldDate: Date | undefined;
      if (subject.history && typeof subject.history === 'object') {
        const saleEntries = Object.values(subject.history)
          .filter((h) => h.event === 'Sale' && h.price)
          .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
        if (saleEntries.length > 0) {
          lastSoldPrice = saleEntries[0].price;
          lastSoldDate = new Date(saleEntries[0].date);
        }
      }
      if (!lastSoldDate && subject.lastSaleDate) {
        lastSoldDate = new Date(subject.lastSaleDate);
      }

      // ── Extract most recent tax assessment & property tax ───────────────────
      let annualPropertyTaxCents: number | undefined;
      let taxAssessedValueCents: number | undefined;
      let taxAssessedLandValCents: number | undefined;
      let taxAssessedImprovementsValCents: number | undefined;
      let taxYear: number | undefined;

      if (subject.propertyTaxes && typeof subject.propertyTaxes === 'object') {
        const taxEntries = Object.values(subject.propertyTaxes)
          .sort((a: any, b: any) => b.year - a.year);
        if (taxEntries.length > 0) {
          const latestTax = taxEntries[0] as any;
          annualPropertyTaxCents = Math.round(latestTax.total * 100);
          taxYear = latestTax.year;
        }
      }

      if (subject.taxAssessments && typeof subject.taxAssessments === 'object') {
        const assessEntries = Object.values(subject.taxAssessments)
          .sort((a: any, b: any) => b.year - a.year);
        if (assessEntries.length > 0) {
          const latestAssess = assessEntries[0] as any;
          taxAssessedValueCents = Math.round(latestAssess.value * 100);
          if (latestAssess.land !== undefined && latestAssess.land !== null) {
            taxAssessedLandValCents = Math.round(latestAssess.land * 100);
          }
          if (latestAssess.improvements !== undefined && latestAssess.improvements !== null) {
            taxAssessedImprovementsValCents = Math.round(latestAssess.improvements * 100);
          }
          if (!taxYear) taxYear = latestAssess.year;
        }
      }

      // ── HOA ────────────────────────────────────────────────────────────────
      const hoaMonthlyCents = subject.hoa?.fee
        ? Math.round(subject.hoa.fee * 100)
        : undefined;

      // For multi-family, estRentCents is per-unit (RentCast lookupSubjectAttributes=true default).
      const unitCount: number | undefined = (subject.units ?? 0) > 1 ? subject.units : undefined;
      const estRentPerUnit = rentData?.rent ? Math.round(rentData.rent * 100) : undefined;
      const totalBuildingRentCents = (estRentPerUnit && unitCount) ? estRentPerUnit * unitCount : undefined;

      return {
        photoUrl: undefined,
        beds:               subject.bedrooms  || undefined,
        baths:              subject.bathrooms || undefined,
        sqft:               subject.squareFootage || undefined,
        yearBuilt:          subject.yearBuilt || undefined,
        lotSqft:            subject.lotSize   || undefined,
        propertyType:       subject.propertyType || undefined,
        units:              unitCount,
        totalBuildingRentCents,
        listPriceCents:     undefined,
        estRentCents:       estRentPerUnit,
        lastSoldPriceCents: lastSoldPrice ? Math.round(lastSoldPrice * 100) : undefined,
        lastSoldDate,
        annualPropertyTaxCents,
        taxAssessedValueCents,
        taxAssessedLandValCents,
        taxAssessedImprovementsValCents,
        taxYear,
        hoaMonthlyCents,
        taxSource:          'rentcast',
        estRentLowCents:    rentData?.rentRangeLow ? Math.round(rentData.rentRangeLow * 100) : undefined,
        estRentHighCents:   rentData?.rentRangeHigh ? Math.round(rentData.rentRangeHigh * 100) : undefined,
        avmPriceCents:      valueData?.price ? Math.round(valueData.price * 100) : undefined,
        avmPriceLowCents:   valueData?.priceRangeLow ? Math.round(valueData.priceRangeLow * 100) : undefined,
        avmPriceHighCents:  valueData?.priceRangeHigh ? Math.round(valueData.priceRangeHigh * 100) : undefined,
        sourceProvider:     'RentCast API',
        fetchedAt:          new Date(),
      };
    } catch (err: any) {
      if (err?.name === 'RentCastNotFoundError' || err?.code === 'not_found' || err instanceof PropertyNotFoundError) {
        throw new PropertyNotFoundError(`No property record found for: ${addressOrPlaceId}`);
      }
      throw err;
    }
  }

  async getComps(addressOrPlaceId: string): Promise<Comp[]> {
    try {
      const valueData = await this.getValueEstimateWithWidening(addressOrPlaceId);
      if (!valueData) return [];
      const comparables = valueData.comparables || [];

      return comparables.map((c: any) => ({
        addressLine:    c.formattedAddress || 'Unknown Address',
        soldPriceCents: c.price ? Math.round(c.price * 100) : null,
        soldDate:       c.listedDate ? new Date(c.listedDate) : null,
        beds:           c.bedrooms  || undefined,
        baths:          c.bathrooms || undefined,
        sqft:           c.squareFootage || undefined,
        distanceMiles:  c.distance,
        compType:       "SALE",
        priceCents:     c.price ? Math.round(c.price * 100) : undefined,
        correlation:    c.correlation,
        daysOnMarket:   c.daysOnMarket || undefined,
        status:         c.status || 'Sold',
        listedDate:     c.listedDate ? new Date(c.listedDate) : undefined,
      }));
    } catch {
      return [];
    }
  }

  async getRentalComps(addressOrPlaceId: string): Promise<RentalComp[]> {
    try {
      const rentData = await this.getRentEstimateWithWidening(addressOrPlaceId);
      if (!rentData) return [];
      const comparables = rentData.comparables || [];

      return comparables.map((c: any) => ({
        addressLine:    c.formattedAddress || 'Unknown Address',
        rentPriceCents: c.price ? Math.round(c.price * 100) : 0,
        distanceMiles:  c.distance,
        daysOnMarket:   c.daysOnMarket || undefined,
        correlation:    c.correlation,
        status:         c.status || 'Rented',
        beds:           c.bedrooms || undefined,
        baths:          c.bathrooms || undefined,
        sqft:           c.squareFootage || undefined,
        listedDate:     c.listedDate ? new Date(c.listedDate) : undefined,
      }));
    } catch {
      return [];
    }
  }

  async getValueEstimate(addressOrPlaceId: string): Promise<ValueEstimate> {
    try {
      const valueData = await this.getValueEstimateWithWidening(addressOrPlaceId);
      if (!valueData) {
        throw new PropertyNotFoundError(`Could not generate value estimate for: ${addressOrPlaceId}`);
      }
      return {
        priceCents:     Math.round(valueData.price * 100),
        priceLowCents:  Math.round(valueData.priceRangeLow * 100),
        priceHighCents: Math.round(valueData.priceRangeHigh * 100),
        source:         'rentcast',
        fetchedAt:      new Date(),
      };
    } catch (err: any) {
      if (err?.name === 'RentCastNotFoundError' || err?.code === 'not_found' || err instanceof PropertyNotFoundError) {
        throw new PropertyNotFoundError(`Could not generate value estimate for: ${addressOrPlaceId}`);
      }
      throw err;
    }
  }
}


// ─── Unavailable provider — returned when a real provider is configured but the
// API key is absent. Throws rather than silently falling back to mock data,
// preventing prod deployments from serving fake data undetected.
export class UnavailablePropertyProvider implements PropertyDataProvider {
  constructor(private readonly reason: string) {}
  async getFacts(): Promise<PropertyFacts> { throw new Error(this.reason); }
  async getComps(): Promise<Comp[]> { throw new Error(this.reason); }
  async getRentalComps(): Promise<RentalComp[]> { throw new Error(this.reason); }
  async getValueEstimate(): Promise<ValueEstimate> { throw new Error(this.reason); }
}

// ─── Factory ──────────────────────────────────────────────────────────────────

export function getPropertyProvider(type?: string): PropertyDataProvider {
  const providerType = (type || process.env.PROPERTY_DATA_PROVIDER || "mock").toLowerCase();

  switch (providerType) {
    case "rentcast": {
      const { getRentCastClient } = require('@/lib/providers/rentcast');
      const client = getRentCastClient();
      if (!client) {
        return new UnavailablePropertyProvider(
          'PROPERTY_DATA_PROVIDER=rentcast but RENTCAST_API_KEY is not set. ' +
          'Set the key or change PROPERTY_DATA_PROVIDER to "mock" for local dev.'
        );
      }
      return new RentCastPropertyProvider(client);
    }
    case "attom": {
      const key = process.env.ATTOM_API_KEY;
      if (!key) {
        return new UnavailablePropertyProvider(
          'PROPERTY_DATA_PROVIDER=attom but ATTOM_API_KEY is not set.'
        );
      }
      return new AttomPropertyProvider(key);
    }
    case "mashvisor": {
      const key = process.env.MASHVISOR_API_KEY;
      if (!key) {
        return new UnavailablePropertyProvider(
          'PROPERTY_DATA_PROVIDER=mashvisor but MASHVISOR_API_KEY is not set.'
        );
      }
      return new MashvisorPropertyProvider(key);
    }
    case "mock":
    default:
      return new MockPropertyDataProvider();
  }
}

export const defaultPropertyProvider: PropertyDataProvider = getPropertyProvider();

export interface RentListing {
  id: string;
  formattedAddress: string;
  price: number;
  status: string;
  listedDate: string;
  removedDate: string | null;
  daysOnMarket: number | null;
}

export interface RentHistoryProvider {
  getRentalHistory(address: string): Promise<RentListing[]>;
}

// ─── Deterministic Hashing Helpers ──────────────────────────────────────────
function getAddressHash(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = (Math.imul(31, h) + str.charCodeAt(i)) | 0;
  }
  return Math.abs(h);
}

function getSeededValue(seed: number, min: number, max: number): number {
  const s = ((seed * 1664525 + 1013904223) >>> 0);
  return min + (s % (max - min + 1));
}

// ─── Mock Adapter ────────────────────────────────────────────────────────────
export class MockRentHistoryAdapter implements RentHistoryProvider {
  async getRentalHistory(address: string): Promise<RentListing[]> {
    // Simulate network delay
    await new Promise((r) => setTimeout(r, 600));

    const h = getAddressHash(address);
    const basePrice = getSeededValue(h, 1500, 3200);

    // Create 2 historical/active listings deterministically based on address hash
    const listings: RentListing[] = [];

    // 1. Historical listing (inactive)
    const price1 = basePrice - 150;
    const listedDate1 = new Date();
    listedDate1.setFullYear(listedDate1.getFullYear() - 2); // 2 years ago
    const removedDate1 = new Date();
    removedDate1.setFullYear(removedDate1.getFullYear() - 1); // 1 year ago

    listings.push({
      id: `mock-listing-1-${h}`,
      formattedAddress: address,
      price: price1,
      status: 'Inactive',
      listedDate: listedDate1.toISOString(),
      removedDate: removedDate1.toISOString(),
      daysOnMarket: 365,
    });

    // 2. Current/Recent listing (Active)
    const price2 = basePrice;
    const listedDate2 = new Date();
    listedDate2.setMonth(listedDate2.getMonth() - 6); // 6 months ago

    listings.push({
      id: `mock-listing-2-${h}`,
      formattedAddress: address,
      price: price2,
      status: 'Active',
      listedDate: listedDate2.toISOString(),
      removedDate: null,
      daysOnMarket: 180,
    });

    return listings;
  }
}

// ─── RentCast API Adapter ─────────────────────────────────────────────────────
export class RentCastRentHistoryAdapter implements RentHistoryProvider {
  private readonly apiKey: string;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  async getRentalHistory(address: string): Promise<RentListing[]> {
    console.log(`📡 [RentCast API] Fetching rental listings for address: ${address}`);

    const url = `https://api.rentcast.io/v1/listings/rental/long-term?address=${encodeURIComponent(address)}&limit=10`;

    try {
      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'X-Api-Key': this.apiKey,
          'Accept': 'application/json',
        },
      });

      if (!response.ok) {
        const errText = await response.text();
        console.error(`[RentCast API Error] Status ${response.status}: ${errText}`);
        throw new Error(`RentCast API responded with status ${response.status}`);
      }

      const data = await response.json();
      if (!Array.isArray(data)) {
        return [];
      }

      return data.map((item: any) => ({
        id: item.id || `rentcast-${item.latitude}-${item.longitude}`,
        formattedAddress: item.formattedAddress || address,
        price: Number(item.price) || 0,
        status: item.status || 'Active',
        listedDate: item.listedDate || new Date().toISOString(),
        removedDate: item.removedDate || null,
        daysOnMarket: item.daysOnMarket !== undefined ? Number(item.daysOnMarket) : null,
      }));
    } catch (error) {
      console.error('[RentCast API Connection Error]', error);
      throw error;
    }
  }
}

// ─── Provider Factory ─────────────────────────────────────────────────────────
export function getRentHistoryProvider(type?: string): RentHistoryProvider {
  const providerType = (type || process.env.RENTHISTORY_PROVIDER || 'mock').toLowerCase();

  if (providerType === 'rentcast') {
    const apiKey = process.env.RENTCAST_API_KEY;
    if (!apiKey) {
      console.warn('⚠️ [RENT HISTORY PROVIDER] RENTCAST_API_KEY is missing. Falling back to MockRentHistoryAdapter.');
      return new MockRentHistoryAdapter();
    }
    return new RentCastRentHistoryAdapter(apiKey);
  }

  return new MockRentHistoryAdapter();
}

export const defaultRentHistoryProvider = getRentHistoryProvider();

// ─── RentCast Firestore Cache Layer ──────────────────────────────────────────
// Every RentCast response is cached in Firestore with fetchedAt and per-endpoint TTL.
// Collection: vendorCache/rentcast/{endpoint}_{normalizedParams}
// Cache is always checked first; includes a forceRefresh option.
// Logs hit/miss telemetry so API spend is observable.

import { logger } from '@/lib/logger';
import type { CachedResponse } from './types';
import { ENDPOINT_TTLS } from './types';

// ─── Helpers ─────────────────────────────────────────────────────────────────

/**
 * Normalize params into a stable, filesystem-safe cache key.
 * Lowercases, sorts params, strips whitespace.
 */
export function buildCacheKey(endpoint: string, params: Record<string, string | number | undefined>): string {
  const normalizedParams = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== '')
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([k, v]) => `${k}=${String(v).toLowerCase().trim()}`)
    .join('&');

  // Replace characters that Firestore document IDs don't like
  const safeKey = `${endpoint}__${normalizedParams}`
    .replace(/\//g, '_')
    .replace(/\s+/g, '_')
    .replace(/[^a-zA-Z0-9_=&.-]/g, '_');

  return safeKey;
}

function getTTL(endpoint: string): number {
  // Match the longest prefix
  for (const [key, ttl] of Object.entries(ENDPOINT_TTLS)) {
    if (endpoint.startsWith(key)) return ttl;
  }
  return 7 * 24 * 60 * 60; // Default: 7 days
}

// ─── Cache Operations ────────────────────────────────────────────────────────

// Lazy import to avoid importing firebase-admin on the client side
let _db: FirebaseFirestore.Firestore | null = null;
async function getDb(): Promise<FirebaseFirestore.Firestore> {
  if (!_db) {
    const { adminDb } = await import('@/lib/firebase/admin');
    _db = adminDb;
  }
  return _db;
}

const CACHE_COLLECTION = 'vendorCache';
const CACHE_SUBCOLLECTION = 'rentcast';

/**
 * Get a cached response if it exists and hasn't expired.
 * Returns null on miss or expiry.
 */
export async function getCached<T>(cacheKey: string): Promise<CachedResponse<T> | null> {
  try {
    const db = await getDb();
    const docRef = db
      .collection(CACHE_COLLECTION)
      .doc(CACHE_SUBCOLLECTION)
      .collection('responses')
      .doc(cacheKey);

    const snap = await docRef.get();

    if (!snap.exists) {
      logger.debug('[RentCast Cache] MISS (not found)', { cacheKey });
      return null;
    }

    const cached = snap.data() as CachedResponse<T>;
    const expiresAt = new Date(cached.expiresAt).getTime();

    if (Date.now() > expiresAt) {
      logger.info('[RentCast Cache] MISS (expired)', {
        cacheKey,
        expiredAt: cached.expiresAt,
      });
      return null;
    }

    logger.info('[RentCast Cache] HIT', {
      cacheKey,
      endpoint: cached.endpoint,
      fetchedAt: cached.fetchedAt,
      expiresAt: cached.expiresAt,
    });

    return cached;
  } catch (err) {
    // Cache failures are non-fatal — fall through to live API
    logger.warn('[RentCast Cache] Read error (non-fatal)', { cacheKey });
    return null;
  }
}

/**
 * Write a response to the cache with the appropriate TTL.
 */
export async function setCached<T>(
  cacheKey: string,
  endpoint: string,
  data: T,
): Promise<void> {
  try {
    const db = await getDb();
    const ttlSeconds = getTTL(endpoint);
    const now = new Date();
    const expiresAt = new Date(now.getTime() + ttlSeconds * 1000);

    const entry: CachedResponse<T> = {
      data,
      fetchedAt: now.toISOString(),
      endpoint,
      cacheKey,
      ttlSeconds,
      expiresAt: expiresAt.toISOString(),
    };

    await db
      .collection(CACHE_COLLECTION)
      .doc(CACHE_SUBCOLLECTION)
      .collection('responses')
      .doc(cacheKey)
      .set(entry);

    logger.info('[RentCast Cache] SET', {
      cacheKey,
      endpoint,
      ttlSeconds,
      expiresAt: expiresAt.toISOString(),
    });
  } catch (err) {
    // Cache write failures are non-fatal
    logger.warn('[RentCast Cache] Write error (non-fatal)', { cacheKey });
  }
}

/**
 * Invalidate a specific cache entry.
 */
export async function invalidateCache(cacheKey: string): Promise<void> {
  try {
    const db = await getDb();
    await db
      .collection(CACHE_COLLECTION)
      .doc(CACHE_SUBCOLLECTION)
      .collection('responses')
      .doc(cacheKey)
      .delete();

    logger.info('[RentCast Cache] INVALIDATED', { cacheKey });
  } catch (err) {
    logger.warn('[RentCast Cache] Invalidation error (non-fatal)', { cacheKey });
  }
}

/**
 * Log a RentCast API call for volume statistics.
 */
export async function logApiCall(endpoint: string): Promise<void> {
  try {
    const db = await getDb();
    const now = new Date();
    const docRef = db.collection('rentcastCallLogs').doc();
    await docRef.set({
      endpoint,
      timestamp: now.toISOString(),
      year: now.getFullYear(),
      month: now.getMonth() + 1, // 1-indexed
      day: now.getDate(),
    });
    logger.debug('[RentCast Telemetry] Logged API call', { endpoint });
  } catch (err) {
    logger.warn('[RentCast Telemetry] Failed to log API call', { endpoint, err });
  }
}

// ─── RentCast API Client ─────────────────────────────────────────────────────
// The single entry point for all RentCast API calls.
// Nothing else in the codebase calls RentCast directly.
//
// Features:
//   • Cache-first with Firestore-backed TTL cache
//   • Token bucket rate limiting (20 req/s)
//   • Retry with exponential backoff on 429/5xx
//   • Typed error mapping — never throws raw vendor errors
//   • Structured logging + telemetry

import { logger } from '@/lib/logger';
import { rentCastLimiter } from './limiter';
import { buildCacheKey, getCached, setCached, logApiCall } from './cache';
import {
  RentCastError,
  RentCastRateLimitError,
  RentCastServerError,
  RentCastNetworkError,
  mapRentCastError,
} from './errors';
import type {
  RentCastProperty,
  RentCastValueEstimate,
  RentCastRentEstimate,
  RentCastMarketData,
  RentCastListing,
  PropertyLookupParams,
  AVMValueParams,
  AVMRentParams,
  MarketParams,
  ListingParams,
} from './types';

// ─── Constants ───────────────────────────────────────────────────────────────

const BASE_URL = 'https://api.rentcast.io/v1';
const MAX_RETRIES = 3;
const INITIAL_BACKOFF_MS = 500;

// ─── Internal Fetch with Retry ───────────────────────────────────────────────

interface FetchOpts {
  endpoint: string;
  params: Record<string, string | number | undefined>;
  apiKey: string;
  forceRefresh?: boolean;
}

async function fetchWithRetry<T>(opts: FetchOpts): Promise<T> {
  const { endpoint, params, apiKey, forceRefresh } = opts;

  // 1. Build cache key and check cache (unless forced)
  const cacheKey = buildCacheKey(endpoint, params);

  if (!forceRefresh) {
    const cached = await getCached<T>(cacheKey);
    if (cached) {
      return cached.data;
    }
  }

  // 2. Build URL
  const queryParts = Object.entries(params)
    .filter(([, v]) => v !== undefined && v !== '')
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(String(v))}`)
    .join('&');

  const url = `${BASE_URL}/${endpoint}${queryParts ? `?${queryParts}` : ''}`;

  const headers = {
    'X-Api-Key': apiKey,
    'Accept': 'application/json',
  };

  // 3. Retry loop with backoff
  let lastError: RentCastError | null = null;

  for (let attempt = 0; attempt < MAX_RETRIES; attempt++) {
    // Respect rate limit
    await rentCastLimiter.acquire();

    try {
      logger.debug(`[RentCast Client] Fetching /${endpoint} (attempt ${attempt + 1})`, {
        url: url.replace(apiKey, '***'),
      });

      const res = await fetch(url, { headers });

      if (res.ok) {
        const data = (await res.json()) as T;

        // Write to cache and log call (fire-and-forget)
        setCached(cacheKey, endpoint, data).catch(() => {});
        logApiCall(endpoint).catch(() => {});

        logger.info(`[RentCast Client] ✅ /${endpoint} success`, { cacheKey });
        return data;
      }

      // Parse error body
      let errorBody: any;
      try {
        errorBody = await res.json();
      } catch {
        errorBody = { message: res.statusText };
      }

      const error = mapRentCastError(res.status, errorBody, endpoint);

      // Only retry on 429 or 5xx
      if (error instanceof RentCastRateLimitError || error instanceof RentCastServerError) {
        lastError = error;
        const backoff = INITIAL_BACKOFF_MS * Math.pow(2, attempt);
        logger.warn(`[RentCast Client] Retryable error on /${endpoint}, backing off ${backoff}ms`, {
          status: res.status,
          attempt: attempt + 1,
        });
        await new Promise(r => setTimeout(r, backoff));
        continue;
      }

      // Non-retryable errors throw immediately
      throw error;

    } catch (err) {
      if (err instanceof RentCastError) {
        throw err;
      }
      // Network / unknown errors — retry
      lastError = new RentCastNetworkError(
        err instanceof Error ? err.message : 'Network error',
        endpoint,
      );
      const backoff = INITIAL_BACKOFF_MS * Math.pow(2, attempt);
      logger.warn(`[RentCast Client] Network error on /${endpoint}, backing off ${backoff}ms`, {
        attempt: attempt + 1,
      });
      await new Promise(r => setTimeout(r, backoff));
    }
  }

  // All retries exhausted
  throw lastError ?? new RentCastError('All retries exhausted', { endpoint });
}

// ─── RentCast Client Class ───────────────────────────────────────────────────

export class RentCastClient {
  private readonly apiKey: string;

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  // ── /properties ──────────────────────────────────────────────────────────

  /**
   * Fetch property records by address. Returns an array (usually 1 result).
   * Includes attributes, last sale, tax assessments, property taxes, history.
   */
  async getProperties(
    params: PropertyLookupParams,
    forceRefresh = false,
  ): Promise<RentCastProperty[]> {
    return fetchWithRetry<RentCastProperty[]>({
      endpoint: 'properties',
      params: { address: params.address },
      apiKey: this.apiKey,
      forceRefresh,
    });
  }

  // ── /avm/value ───────────────────────────────────────────────────────────

  /**
   * Automated Valuation Model — returns an estimated value and sale comparables.
   * Passing the full address lets lookupSubjectAttributes default to true.
   */
  async getValueEstimate(
    params: AVMValueParams,
    forceRefresh = false,
  ): Promise<RentCastValueEstimate> {
    return fetchWithRetry<RentCastValueEstimate>({
      endpoint: 'avm/value',
      params: {
        address: params.address,
        compCount: params.compCount,
        maxRadius: params.maxRadius,
        daysOld: params.daysOld,
      },
      apiKey: this.apiKey,
      forceRefresh,
    });
  }

  // ── /avm/rent/long-term ──────────────────────────────────────────────────

  /**
   * Rent estimate with rental comparables.
   */
  async getRentEstimate(
    params: AVMRentParams,
    forceRefresh = false,
  ): Promise<RentCastRentEstimate> {
    return fetchWithRetry<RentCastRentEstimate>({
      endpoint: 'avm/rent/long-term',
      params: {
        address: params.address,
        compCount: params.compCount,
        maxRadius: params.maxRadius,
        daysOld: params.daysOld,
      },
      apiKey: this.apiKey,
      forceRefresh,
    });
  }

  // ── /markets ─────────────────────────────────────────────────────────────

  /**
   * Zip-level sale & rental market statistics with ~12 months history.
   */
  async getMarketStats(
    params: MarketParams,
    forceRefresh = false,
  ): Promise<RentCastMarketData> {
    return fetchWithRetry<RentCastMarketData>({
      endpoint: 'markets',
      params: { zipCode: params.zipCode },
      apiKey: this.apiKey,
      forceRefresh,
    });
  }

  // ── /listings/sale ───────────────────────────────────────────────────────

  /**
   * Active sale listings.
   */
  async getSaleListings(
    params: ListingParams,
    forceRefresh = false,
  ): Promise<RentCastListing[]> {
    return fetchWithRetry<RentCastListing[]>({
      endpoint: 'listings/sale',
      params: {
        address: params.address,
        zipCode: params.zipCode,
        city: params.city,
        state: params.state,
        limit: params.limit,
        offset: params.offset,
        status: params.status,
        bedrooms: params.bedrooms,
        bathrooms: params.bathrooms,
        propertyType: params.propertyType,
        minPrice: params.minPrice,
        maxPrice: params.maxPrice,
      },
      apiKey: this.apiKey,
      forceRefresh,
    });
  }

  // ── /listings/rental ─────────────────────────────────────────────────────

  /**
   * Active rental listings (long-term).
   */
  async getRentalListings(
    params: ListingParams,
    forceRefresh = false,
  ): Promise<RentCastListing[]> {
    return fetchWithRetry<RentCastListing[]>({
      endpoint: 'listings/rental',
      params: {
        address: params.address,
        zipCode: params.zipCode,
        city: params.city,
        state: params.state,
        limit: params.limit,
        offset: params.offset,
        status: params.status,
        bedrooms: params.bedrooms,
        bathrooms: params.bathrooms,
        propertyType: params.propertyType,
        minPrice: params.minPrice,
        maxPrice: params.maxPrice,
      },
      apiKey: this.apiKey,
      forceRefresh,
    });
  }
}

// ─── RentCast Typed Error Hierarchy ───────────────────────────────────────────
// Mirrors the BridgeError pattern from src/lib/types/errors.ts.
// Never exposes raw vendor errors to callers.

export class RentCastError extends Error {
  public readonly status?: number;
  public readonly code?: string;
  public readonly endpoint: string;
  public readonly timestamp: number;

  constructor(message: string, opts: { status?: number; code?: string; endpoint: string }) {
    super(message);
    this.name = 'RentCastError';
    this.status = opts.status;
    this.code = opts.code;
    this.endpoint = opts.endpoint;
    this.timestamp = Date.now();
  }
}

/** 400 — bad request / missing parameters */
export class RentCastBadRequestError extends RentCastError {
  constructor(message: string, endpoint: string) {
    super(message, { status: 400, code: 'bad_request', endpoint });
    this.name = 'RentCastBadRequestError';
  }
}

/** 401/403 — invalid or inactive API key */
export class RentCastAuthError extends RentCastError {
  constructor(message: string, endpoint: string, status: number = 401) {
    super(message, { status, code: 'auth_error', endpoint });
    this.name = 'RentCastAuthError';
  }
}

/** 404 — address not found / no data available */
export class RentCastNotFoundError extends RentCastError {
  constructor(message: string, endpoint: string) {
    super(message, { status: 404, code: 'not_found', endpoint });
    this.name = 'RentCastNotFoundError';
  }
}

/** 429 — rate limit exceeded */
export class RentCastRateLimitError extends RentCastError {
  public readonly retryAfterMs?: number;

  constructor(message: string, endpoint: string, retryAfterMs?: number) {
    super(message, { status: 429, code: 'rate_limit', endpoint });
    this.name = 'RentCastRateLimitError';
    this.retryAfterMs = retryAfterMs;
  }
}

/** 5xx — server errors */
export class RentCastServerError extends RentCastError {
  constructor(message: string, endpoint: string, status: number = 500) {
    super(message, { status, code: 'server_error', endpoint });
    this.name = 'RentCastServerError';
  }
}

/** Billing/subscription inactive */
export class RentCastBillingError extends RentCastError {
  constructor(message: string, endpoint: string) {
    super(message, { status: 403, code: 'billing/subscription-inactive', endpoint });
    this.name = 'RentCastBillingError';
  }
}

/** Not enough comps to generate estimate — non-fatal, callers handle gracefully */
export class RentCastInsufficientDataError extends RentCastError {
  constructor(message: string, endpoint: string) {
    super(message, { status: 200, code: 'insufficient_data', endpoint });
    this.name = 'RentCastInsufficientDataError';
  }
}

/** Network / timeout errors */
export class RentCastNetworkError extends RentCastError {
  constructor(message: string, endpoint: string) {
    super(message, { status: undefined, code: 'network_error', endpoint });
    this.name = 'RentCastNetworkError';
  }
}

// ─── Error Mapping ───────────────────────────────────────────────────────────

/**
 * Maps a raw HTTP response to a typed RentCastError.
 * Called by the client after receiving a non-ok response.
 */
export function mapRentCastError(
  status: number,
  body: any,
  endpoint: string,
): RentCastError {
  const message = body?.message || body?.error || `RentCast API error (${status})`;

  // Billing-specific 403
  if (status === 403 && body?.error === 'billing/subscription-inactive') {
    return new RentCastBillingError(message, endpoint);
  }

  switch (status) {
    case 400:
      return new RentCastBadRequestError(message, endpoint);
    case 401:
      return new RentCastAuthError(message, endpoint, 401);
    case 403:
      return new RentCastAuthError(message, endpoint, 403);
    case 404:
      return new RentCastNotFoundError(message, endpoint);
    case 429: {
      return new RentCastRateLimitError(message, endpoint);
    }
    default:
      if (status >= 500) {
        return new RentCastServerError(message, endpoint, status);
      }
      return new RentCastError(message, { status, endpoint });
  }
}

import { adminDb } from '@/lib/firebase/admin';
import type { TitleProvider } from './titleProvider';
import type { TitleWorkflowState, TitleCommitmentData, TitleDefect } from '@/types/schema';
import { FieldValue } from 'firebase-admin/firestore';

export class ManualTitleAdapter implements TitleProvider {
  async getWorkflowState(projectId: string): Promise<TitleWorkflowState> {
    const doc = await adminDb.collection('projects').doc(projectId).get();
    if (!doc.exists) {
      throw new Error('Project not found');
    }
    const data = doc.data();
    return data?.closingRoom?.titleWorkflow || { status: 'order_opened' };
  }

  async openOrder(projectId: string, actorUid: string, actorName: string): Promise<TitleWorkflowState> {
    const state: TitleWorkflowState = {
      status: 'order_opened',
      orderOpenedAt: new Date().toISOString(),
      orderOpenedByUid: actorUid,
      orderOpenedByName: actorName,
      defects: [],
    };

    await adminDb.collection('projects').doc(projectId).update({
      'closingRoom.titleWorkflow': state,
      'closingRoom.chainOfTitleStatus': 'pending',
      updatedAt: FieldValue.serverTimestamp(),
    });

    return state;
  }

  async receiveCommitment(
    projectId: string,
    data: TitleCommitmentData,
    actorUid: string,
    actorName: string
  ): Promise<TitleWorkflowState> {
    const currentState = await this.getWorkflowState(projectId);

    const state: TitleWorkflowState = {
      ...currentState,
      status: 'commitment_received',
      commitment: data,
    };

    await adminDb.collection('projects').doc(projectId).update({
      'closingRoom.titleWorkflow': state,
      'closingRoom.chainOfTitleStatus': 'pending',
      updatedAt: FieldValue.serverTimestamp(),
    });

    return state;
  }

  async addDefect(
    projectId: string,
    description: string,
    actorUid: string,
    actorName: string
  ): Promise<TitleWorkflowState> {
    const currentState = await this.getWorkflowState(projectId);
    const defects = [...(currentState.defects || [])];

    const newDefect: TitleDefect = {
      id: crypto.randomUUID(),
      description,
      status: 'pending',
    };
    defects.push(newDefect);

    const state: TitleWorkflowState = {
      ...currentState,
      status: 'defects_identified',
      defects,
    };

    await adminDb.collection('projects').doc(projectId).update({
      'closingRoom.titleWorkflow': state,
      'closingRoom.chainOfTitleStatus': 'failed', // Failed while defects are open
      updatedAt: FieldValue.serverTimestamp(),
    });

    return state;
  }

  async resolveDefect(
    projectId: string,
    defectId: string,
    notes: string,
    documentUrl: string | null,
    documentName: string | null,
    actorUid: string,
    actorName: string
  ): Promise<TitleWorkflowState> {
    const currentState = await this.getWorkflowState(projectId);
    const defects = (currentState.defects || []).map((d) => {
      if (d.id !== defectId) return d;
      return {
        ...d,
        status: 'resolved' as const,
        notes,
        documentUrl,
        documentName,
        resolvedAt: new Date().toISOString(),
        resolvedByUid: actorUid,
        resolvedByName: actorName,
      };
    });

    // Check if all defects resolved
    const allCured = defects.every((d) => d.status === 'resolved');
    const newStatus = allCured ? 'cleared' as const : 'defects_identified' as const;
    const chainStatus = allCured ? 'verified' as const : 'failed' as const;

    const state: TitleWorkflowState = {
      ...currentState,
      status: newStatus,
      defects,
      ...(allCured && {
        clearedAt: new Date().toISOString(),
        clearedByUid: actorUid,
        clearedByName: actorName,
      }),
    };

    await adminDb.collection('projects').doc(projectId).update({
      'closingRoom.titleWorkflow': state,
      'closingRoom.chainOfTitleStatus': chainStatus,
      updatedAt: FieldValue.serverTimestamp(),
    });

    return state;
  }

  async clearTitle(projectId: string, actorUid: string, actorName: string): Promise<TitleWorkflowState> {
    const currentState = await this.getWorkflowState(projectId);

    // Verify all defects are cured
    const hasPendingDefects = (currentState.defects || []).some((d) => d.status === 'pending');
    if (hasPendingDefects) {
      throw new Error('Cannot clear title with unresolved defects');
    }

    const state: TitleWorkflowState = {
      ...currentState,
      status: 'cleared',
      clearedAt: new Date().toISOString(),
      clearedByUid: actorUid,
      clearedByName: actorName,
    };

    await adminDb.collection('projects').doc(projectId).update({
      'closingRoom.titleWorkflow': state,
      'closingRoom.chainOfTitleStatus': 'verified',
      updatedAt: FieldValue.serverTimestamp(),
    });

    return state;
  }
}

