/**
 * 📉 EconomicDataService
 * 
 * Specialized service for Zillow Group Economic Data (ZGEcon).
 * Provides macro-economic indicators for high-level market analysis.
 */
export class EconomicDataService {
  private readonly MARKET_REPORT_ENDPOINT = '/zgecon/marketreport';

  /**
   * Fetches the macro market report for a specific state.
   * @param stateCodeFips The 2-digit FIPS code for the state (e.g., '06' for California).
   */
  async fetchMarketReport(stateCodeFips: string): Promise<MarketReport[]> {
    if (!stateCodeFips) {
      throw new Error('❌ [ECONOMIC DATA] stateCodeFips is required.');
    }

    console.log(`📡 [ECONOMIC DATA] Fetching market report for state FIPS: ${stateCodeFips}`);

    const response = await apiClient.get<any>(this.MARKET_REPORT_ENDPOINT, {
      params: { 
        stateCodeFIPS: stateCodeFips
      }
    });

    // ZGEcon often returns results in a wrapper
    const parsed = ZGEconResponseSchema.parse(response.data);
    return parsed.results.map(r => MarketReportSchema.parse(r));
  }
}

export const economicDataService = new EconomicDataService();

/**
 * R0 — Field History Service
 * Records edits to high-impact financial fields as an audit trail.
 * Storage: Firestore sub-collection `projects/{projectId}/fieldHistory/{autoId}`
 *
 * High-impact fields tracked by default:
 * purchasePrice, estimatedARV, loanAmount, loanInterestRate, actualSalePrice,
 * monthlyGrossRent, rehabActual, rehabBudget, estimatedCurrentValue,
 * totalCashInvested, closingCosts, sellingCosts, ownershipPercentage
 */

import { db } from '../firebase/config';
import {
  collection,
  addDoc,
  query,
  where,
  orderBy,
  getDocs,
  Timestamp,
} from 'firebase/firestore';
import type { FieldEditEntry } from '@/types/schema';

const TRACKED_FIELDS = new Set([
  'purchasePrice',
  'estimatedARV',
  'loanAmount',
  'loanInterestRate',
  'actualSalePrice',
  'monthlyGrossRent',
  'rehabActual',
  'rehabBudget',
  'estimatedCurrentValue',
  'totalCashInvested',
  'closingCosts',
  'sellingCosts',
  'ownershipPercentage',
]);

/**
 * Returns true if a field should be version-tracked.
 */
export function isTrackedField(field: string): boolean {
  return TRACKED_FIELDS.has(field);
}

/**
 * Records a field edit in the project's fieldHistory sub-collection.
 * Only records if the field is in the tracked set and the value actually changed.
 */
export async function recordFieldEdit(
  projectId: string,
  field: string,
  previousValue: number,
  newValue: number,
  changedByUid: string,
  reason?: string
): Promise<void> {
  if (!isTrackedField(field)) return;
  if (previousValue === newValue) return;

  const historyRef = collection(db, 'projects', projectId, 'fieldHistory');
  await addDoc(historyRef, {
    field,
    previousValue,
    newValue,
    changedAt: Timestamp.now(),
    changedByUid,
    reason: reason || null,
  });
}

/**
 * Records multiple field edits in a batch.
 * Compares old and new financials to detect changes in tracked fields.
 */
export async function recordFinancialChanges(
  projectId: string,
  oldFinancials: Record<string, any>,
  newFinancials: Record<string, any>,
  changedByUid: string,
  reason?: string
): Promise<void> {
  const historyRef = collection(db, 'projects', projectId, 'fieldHistory');

  for (const field of TRACKED_FIELDS) {
    const oldVal = oldFinancials[field];
    const newVal = newFinancials[field];

    // Only record if both are numeric and different
    if (
      typeof oldVal === 'number' &&
      typeof newVal === 'number' &&
      oldVal !== newVal
    ) {
      await addDoc(historyRef, {
        field,
        previousValue: oldVal,
        newValue: newVal,
        changedAt: Timestamp.now(),
        changedByUid,
        reason: reason || null,
      });
    }
  }
}

/**
 * Retrieves the full edit history for a project, optionally filtered by field.
 * Returns entries sorted newest-first.
 */
export async function getFieldHistory(
  projectId: string,
  field?: string
): Promise<FieldEditEntry[]> {
  const historyRef = collection(db, 'projects', projectId, 'fieldHistory');

  let q;
  if (field) {
    q = query(
      historyRef,
      where('field', '==', field),
      orderBy('changedAt', 'desc')
    );
  } else {
    q = query(historyRef, orderBy('changedAt', 'desc'));
  }

  const snapshot = await getDocs(q);
  return snapshot.docs.map((doc) => {
    const data = doc.data();
    return {
      id: doc.id,
      field: data.field,
      previousValue: data.previousValue,
      newValue: data.newValue,
      changedAt: data.changedAt?.toDate?.() ?? new Date(data.changedAt),
      changedByUid: data.changedByUid,
      reason: data.reason || undefined,
    };
  });
}

import { communicationService } from './communicationService';
import { adminDb } from '../firebase/admin';
import { FieldValue } from 'firebase-admin/firestore';

/**
 * Strips quoted email reply history and standard signatures.
 */
export function stripQuotedHistoryAndSignatures(text: string): string {
  if (!text) return '';

  const lines = text.split(/\r?\n/);
  const cleanLines: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();

    // 1. Quoted lines starting with >
    if (trimmed.startsWith('>')) {
      break;
    }

    // 2. Standard reply headers
    if (
      /^on\s+.*wrote:$/i.test(trimmed) ||
      /^from:\s+/i.test(trimmed) ||
      /^to:\s+/i.test(trimmed) ||
      trimmed.startsWith('---') ||
      trimmed.startsWith('_____') ||
      /^sent\s+from\s+my/i.test(trimmed)
    ) {
      break;
    }

    // 3. Signature markers
    if (
      trimmed === '--' ||
      trimmed === 'Regards,' ||
      trimmed === 'Thanks,' ||
      trimmed === 'Sincerely,' ||
      trimmed === 'Best regards,' ||
      trimmed === 'Best,'
    ) {
      break;
    }

    cleanLines.push(line);
  }

  return cleanLines.join('\n').trim();
}

/**
 * InboundEmailHandler
 * Processes raw JSON payloads from SendGrid/Postmark webhooks.
 * Validates invitations via the reply token, strips quoted history/signatures,
 * and stitches emails directly into Q&A thread.
 */
export const inboundEmailHandler = {
  /**
   * Main entry point for webhook processing.
   */
  async processInbound(payload: any) {
    const { From, Subject, TextBody, MessageID } = payload;

    // 1. Extract Token from Recipient (To address or MailboxHash or envelope.to)
    let token: string | null = null;
    const recipient = payload.To || payload.to || '';
    const toMatch = recipient.match(/reply\+([a-zA-Z0-9_-]+)@/);
    if (toMatch) {
      token = toMatch[1];
    }

    if (!token && payload.MailboxHash) {
      token = payload.MailboxHash;
    }

    if (!token && payload.envelope?.to) {
      const envTo = Array.isArray(payload.envelope.to) ? payload.envelope.to[0] : payload.envelope.to;
      const envMatch = String(envTo).match(/reply\+([a-zA-Z0-9_-]+)@/);
      if (envMatch) {
        token = envMatch[1];
      }
    }

    if (!token) {
      console.warn(`[INBOUND REJECTED] No token found in recipient address: ${recipient}`);
      return { success: false, reason: 'unrecognized_thread' };
    }

    try {
      // 2. Resolve Invitation and Verify Token
      let snap = await adminDb
        .collection('dealInvitations')
        .where('token', '==', token)
        .limit(1)
        .get();

      let isDealInvitation = true;
      if (snap.empty) {
        snap = await adminDb
          .collection('invitations')
          .where('token', '==', token)
          .limit(1)
          .get();
        if (!snap.empty) {
          isDealInvitation = false;
        }
      }

      if (snap.empty) {
        console.warn(`[INBOUND REJECTED] Invitation token ${token} does not exist.`);
        return { success: false, reason: 'unrecognized_thread' };
      }

      const invDoc = snap.docs[0];
      const invRef = invDoc.ref;
      const rawInv = invDoc.data();
      const inv = isDealInvitation
        ? {
            id: rawInv.id,
            token: rawInv.token,
            email: rawInv.inviteeEmail,
            name: rawInv.inviteeName || 'Anonymous Investor',
            projectId: rawInv.projectId,
            invitedByUid: rawInv.inviterUid || 'system',
            status: rawInv.status,
            createdAt: rawInv.createdAt,
            expiresAt: rawInv.expiresAt || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
            version: rawInv.version || 1,
            visibilityMode: rawInv.visibilityMode || 'PRIVATE',
            listingId: rawInv.listingId || '',
          }
        : rawInv;

      // 3. Expiry check
      const expiresAt: Date = inv.expiresAt?.toDate ? inv.expiresAt.toDate() : new Date(inv.expiresAt);
      if (expiresAt < new Date()) {
        console.warn(`[INBOUND REJECTED] Invitation link has expired.`);
        return { success: false, reason: 'link_expired' };
      }

      const projectId = inv.projectId;

      // 4. Resolve Organization ID
      const dealSnap = await adminDb.collection('projects').doc(projectId).get();
      if (!dealSnap.exists) {
        console.warn(`[INBOUND REJECTED] Project ${projectId} does not exist.`);
        return { success: false, reason: 'deal_not_found' };
      }

      const projectData = dealSnap.data()!;
      const organizationId = projectData.organizationId;
      if (!organizationId) {
        console.error(`[CRITICAL] Project ${projectId} organizationId is missing.`);
        return { success: false, reason: 'corrupt_data_state' };
      }

      // 5. Clean body
      const cleanedBody = stripQuotedHistoryAndSignatures(TextBody || payload.text || '');

      // 6. Stitch message into investorInquiries subcollection
      const inquiriesSnap = await adminDb
        .collection('projects')
        .doc(projectId)
        .collection('investorInquiries')
        .where('invitationId', '==', invRef.id)
        .get();

      const now = FieldValue.serverTimestamp();
      const newMessage = {
        id: `msg_${Date.now()}_${Math.random().toString(36).slice(2, 6)}`,
        sender: 'investor',
        text: cleanedBody,
        createdAt: new Date().toISOString(),
      };

      if (!inquiriesSnap.empty) {
        const threadDoc = inquiriesSnap.docs[0];
        const data = threadDoc.data();
        const messagesList = data.messages || [];

        if (messagesList.length >= 20) {
          console.warn(`[INBOUND REJECTED] Message thread limit reached for invitation ${invRef.id}`);
          return { success: false, reason: 'thread_limit_reached' };
        }

        await threadDoc.ref.update({
          messages: FieldValue.arrayUnion(newMessage),
          status: 'open',
          updatedAt: now,
        });
      } else {
        await adminDb
          .collection('projects')
          .doc(projectId)
          .collection('investorInquiries')
          .add({
            projectId,
            invitationId: invRef.id,
            investorName: inv.name || 'Anonymous Investor',
            investorEmail: inv.email || null,
            message: cleanedBody,
            status: 'open',
            isShared: false,
            messages: [newMessage],
            createdAt: now,
            updatedAt: now,
          });
      }

      // 7. Write to dealLedger
      const ledgerRef = adminDb.collection('projects').doc(projectId).collection('dealLedger').doc();
      await ledgerRef.set({
        id: ledgerRef.id,
        projectId,
        listingId: inv.listingId || '',
        eventType: 'INVITATION_RESPONSE',
        performedBy: inv.invitedByUid || 'system',
        inviteeEmail: inv.email || 'unknown',
        version: inv.version || 1,
        visibilityMode: inv.visibilityMode || 'PRIVATE',
        timestamp: new Date().toISOString(),
        metadata: {
          invitationId: invRef.id,
          status: 'question',
          question: cleanedBody,
        },
      });

      // 8. Log the message in communicationService
      await communicationService.logMessage(projectId, organizationId, {
        senderEmail: From,
        senderName: inv.name || From.split('@')[0],
        type: 'EMAIL_INBOUND',
        subject: Subject,
        body: cleanedBody,
        providerMessageId: MessageID || null,
      });

      console.log(`[INBOUND SUCCESS] Email ${MessageID} stitched into thread for invitation ${invRef.id}`);
      return { success: true, projectId };
    } catch (error) {
      console.error('[INBOUND ERROR] Webhook processing failed:', error);
      return { success: false, reason: 'internal_server_error' };
    }
  },
};

import { updateAssignmentStatus } from '@/actions/vendorAssignment';
import { approveLedgerItem } from '@/actions/index';
import { projectsService } from '@/lib/firebase/projects';
import { db } from '@/lib/firebase/config';
import { collection, query, where, getDocs, doc, updateDoc, getDoc } from 'firebase/firestore';

export async function executeInboxAction(
  item: any, // Notification
  idToken: string,
  userEmail: string
): Promise<{ success: boolean; message: string }> {
  const projectId = item.objectReference?.projectId;
  if (!projectId) {
    throw new Error('Project context missing from notification.');
  }

  if (item.type === 'VENDOR_BID') {
    // 1. Resolve assignmentId
    let assignmentId = item.objectReference?.metadata?.assignmentId || item.objectReference?.assignmentId;

    if (!assignmentId) {
      // Robust lookup: find PENDING assignment matching vendor name
      const vendorName = item.objectReference?.vendor || item.actor?.name;
      const assignmentsRef = collection(db, 'projects', projectId, 'vendorAssignments');
      const q = query(assignmentsRef, where('status', '==', 'PENDING'));
      const snap = await getDocs(q);

      const matched = snap.docs.find(d => {
        const data = d.data();
        return data.vendorName === vendorName || data.vendorCompanyName === vendorName;
      });

      if (matched) {
        assignmentId = matched.id;
      }
    }

    if (!assignmentId) {
      throw new Error('Could not resolve vendor assignment reference.');
    }

    // 2. Parse quotedFee
    const amountStr = item.objectReference?.amount || '';
    const quotedFee = parseFloat(amountStr.replace(/[^0-9.]/g, '')) || 0;

    // 3. Call server action
    const res = await updateAssignmentStatus(idToken, projectId, assignmentId, 'ACCEPTED', quotedFee);
    if (!res.success) {
      throw new Error(res.error || 'Failed to approve vendor assignment.');
    }

    return { success: true, message: 'Vendor assignment approved successfully.' };

  } else if (item.type === 'RECEIPT_APPROVAL') {
    // 1. Check sub-collection ledgerItems
    let itemId = item.objectReference?.metadata?.ledgerItemId || item.objectReference?.ledgerItemId;

    if (!itemId) {
      // Robust lookup: search in projects/{projectId}/ledgerItems subcollection
      const ledgersRef = collection(db, 'projects', projectId, 'ledgerItems');
      const q = query(ledgersRef, where('status', '==', 'Pending'));
      const snap = await getDocs(q);

      // Try matching by amount
      const amountStr = item.objectReference?.amount || '';
      const amount = parseFloat(amountStr.replace(/[^0-9.]/g, '')) || 0;

      const matched = snap.docs.find(d => {
        const data = d.data();
        return data.amount === amount;
      });

      if (matched) {
        itemId = matched.id;
      }
    }

    if (itemId) {
      // Call server action to approve ledger item
      const res = await approveLedgerItem(idToken, projectId, itemId);
      if (!res.success) {
        throw new Error('Failed to approve ledger item.');
      }
      return { success: true, message: 'Ledger item approved successfully.' };
    } else {
      // 2. Fallback: Legacy costs array update
      const docRef = doc(db, 'projects', projectId);
      const snap = await getDoc(docRef);
      if (!snap.exists()) throw new Error('Project not found');

      const projectData = snap.data();
      const amountStr = item.objectReference?.amount || '';
      const amount = parseFloat(amountStr.replace(/[^0-9.]/g, '')) || 0;

      const currentCosts = projectData.financials?.costs || [];

      // Idempotency check: already approved?
      const alreadyApproved = currentCosts.some((cost: any) => cost.amount === amount && cost.approved === true);
      if (alreadyApproved) {
        return { success: true, message: 'Receipt cost entry already approved.' };
      }

      let foundCost = false;
      const updatedCosts = currentCosts.map((cost: any) => {
        if (cost.amount === amount && (cost.status === 'Pending Triage' || !cost.approved)) {
          foundCost = true;
          return { ...cost, approved: true, status: 'Approved' };
        }
        return cost;
      });

      if (!foundCost) {
        throw new Error('Could not resolve receipt cost entry in project.');
      }

      await projectsService.updateProject(projectId, {
        financials: {
          ...projectData.financials,
          costs: updatedCosts
        }
      });

      return { success: true, message: 'Receipt cost entry approved successfully.' };
    }

  } else if (item.type === 'INVEST_INVITE') {
    // 1. Resolve invitation token
    let token = item.objectReference?.metadata?.token || item.objectReference?.token;

    if (!token) {
      // Robust lookup: search in invitations collection
      const invitationsRef = collection(db, 'invitations');
      const q = query(
        invitationsRef, 
        where('projectId', '==', projectId), 
        where('status', '==', 'pending')
      );
      const snap = await getDocs(q);

      const matched = snap.docs.find(d => {
        const data = d.data();
        return data.email === userEmail;
      });

      if (matched) {
        token = matched.data().token;
      } else if (snap.docs.length > 0) {
        // Fallback to first pending invitation for the project if email doesn't match
        token = snap.docs[0].data().token;
      }
    }

    if (!token) {
      throw new Error('Could not resolve invitation token.');
    }

    // 2. Call response API
    const res = await fetch('/api/invitations/respond', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        token,
        action: 'accept',
        signatureDataUrl: 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg=='
      })
    });

    if (!res.ok) {
      const errData = await res.json().catch(() => ({}));
      throw new Error(errData.error || 'Failed to accept invitation.');
    }

    return { success: true, message: 'Invitation accepted successfully.' };

  } else if (item.type === 'TEAM_INVITE' || item.type === 'TEAM_INVITE_REMINDER') {
    const tokenMatch = item.deepLinkUrl?.match(/[?&]token=([^&]+)/);
    const token = tokenMatch ? tokenMatch[1] : null;

    if (!token) {
      throw new Error('Could not resolve invitation token from notification.');
    }

    const { acceptTeamInvitation } = await import('@/actions/team');
    await acceptTeamInvitation(token);
    return { success: true, message: 'Team invitation accepted successfully.' };
  }

  throw new Error('Unsupported action execution type.');
}

/**
 * src/lib/services/memberReplicationWorker.ts
 *
 * Orchestrates MLS Member (agent) data synchronization via the
 * Bridge /{dataset}/Member endpoint. Mirrors the ReplicationWorker
 * pattern used for Properties, but targets the Member resource.
 *
 * Watermark key: "member_watermark"
 */

import apiClient from '../apiClient';
import prisma from '../prisma';
import bridgeConfig from '../../config/bridge';
import { bridgeWorkerService } from './bridgeWorkerService';
import { BridgeMemberSchema, type BridgeMember } from '../types/bridge';
import { ingestMembers } from './memberIngestor';
import { BridgeRateLimitError, BridgeServerError } from '../types/errors';

const MAX_RETRIES = 3;
const WATERMARK_ID = 'member_watermark';

function retryDelayMs(error: unknown, attempt: number): number {
  if (error instanceof BridgeRateLimitError && error.resetAt) {
    const nowSeconds = Math.floor(Date.now() / 1000);
    return Math.max((error.resetAt - nowSeconds) * 1000, 1000);
  }
  const cap = Math.min(2000 * Math.pow(2, attempt), 60_000);
  return Math.floor(Math.random() * cap);
}

function isRetriable(error: unknown): boolean {
  return error instanceof BridgeRateLimitError || error instanceof BridgeServerError;
}

async function sleep(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function fetchWithRetry(url: string): Promise<any> {
  for (let attempt = 0; attempt <= MAX_RETRIES; attempt++) {
    try {
      return await apiClient.get(url);
    } catch (error) {
      if (!isRetriable(error) || attempt === MAX_RETRIES) throw error;
      const delay = retryDelayMs(error, attempt);
      console.warn(`⏳ [MEMBER REPLICATION] Retriable error on attempt ${attempt + 1}. Retrying in ${delay}ms.`, (error as Error).message);
      await sleep(delay);
    }
  }
}

/**
 * 🧑‍💼 MemberReplicationWorker
 *
 * Syncs the Member (agent) resource from Bridge Interactive into
 * the local Prisma `Member` table. Uses watermark-based incremental sync.
 */
class MemberReplicationWorker {
  private readonly MAX_BATCH_SIZE = 500;

  private get basePath(): string {
    const vId = bridgeConfig.BRIDGE_VIRTUAL_DATASET_ID;
    return vId ? `${vId}/Member` : 'Member';
  }

  async sync(): Promise<{ success: boolean; syncedCount: number; error?: string }> {
    try {
      const state = await prisma.bridgeSyncState.findUnique({
        where: { id: WATERMARK_ID },
      });

      let watermark = state?.mostRecentModificationTimestamp;
      if (!watermark) {
        watermark = new Date();
        watermark.setDate(watermark.getDate() - 90); // 90-day initial lookback for agents
      }

      console.log(`🚀 [MEMBER REPLICATION] Starting sync from watermark: ${watermark.toISOString()}`);

      const selectFields = [
        'MemberKey', 'MemberMlsId', 'MemberFirstName', 'MemberLastName',
        'MemberFullName', 'MemberEmail', 'MemberDirectPhone', 'MemberMobilePhone',
        'MemberStateLicense', 'MemberDesignation',
        'OfficeName', 'OfficeKey', 'OfficeMlsId',
        'Media', 'ModificationTimestamp',
      ].join(',');

      const initialUrl = `${this.basePath}?$filter=ModificationTimestamp gt ${watermark.toISOString()}&$top=${this.MAX_BATCH_SIZE}&$select=${selectFields}&$orderby=ModificationTimestamp asc`;

      return await this.runChain(initialUrl);
    } catch (error: any) {
      console.error('❌ [MEMBER REPLICATION] Critical sync failure:', error);
      return { success: false, syncedCount: 0, error: error.message };
    }
  }

  private async runChain(initialUrl: string): Promise<{ success: boolean; syncedCount: number }> {
    let nextUrl: string | null = initialUrl;
    let totalSynced = 0;

    while (nextUrl) {
      if (await bridgeWorkerService.isPaused()) {
        console.warn('🛑 [MEMBER REPLICATION] Circuit breaker active. Suspending worker.');
        break;
      }

      const response = await fetchWithRetry(nextUrl);
      const rawRecords: any[] = response.data?.value || [];

      if (rawRecords.length === 0) {
        console.log('✅ [MEMBER REPLICATION] No new records. Sync complete.');
        break;
      }

      console.log(`📥 [MEMBER REPLICATION] Processing batch of ${rawRecords.length} members...`);

      // Parse raw records through Zod, fallback to raw if parse fails
      const records: BridgeMember[] = rawRecords.map(r => {
        const res = BridgeMemberSchema.safeParse(r);
        return res.success ? res.data : (r as BridgeMember);
      });

      totalSynced += await ingestMembers(records);

      // Update watermark from the last record
      const lastRecord = records[records.length - 1];
      if (lastRecord.ModificationTimestamp) {
        await this.updateWatermark(new Date(lastRecord.ModificationTimestamp));
      }

      // Resolve nextLink
      let rawNext = response.data?.['@odata.nextLink'];
      if (!rawNext) {
        const linkHeader = response.headers['link'] || response.headers['odata-nextlink'];
        if (linkHeader) {
          const match = /<([^>]+)>;\s*rel="next"/i.exec(linkHeader);
          rawNext = match ? match[1] : linkHeader;
        }
      }

      nextUrl = rawNext
        ? (rawNext.includes('/OData/') ? rawNext.split('/OData/')[1] : rawNext)
        : null;
    }

    console.log(`🎉 [MEMBER REPLICATION] Sync complete. Total members ingested: ${totalSynced}`);
    return { success: true, syncedCount: totalSynced };
  }

  private async updateWatermark(timestamp: Date): Promise<void> {
    await prisma.bridgeSyncState.upsert({
      where: { id: WATERMARK_ID },
      update: { mostRecentModificationTimestamp: timestamp },
      create: { id: WATERMARK_ID, mostRecentModificationTimestamp: timestamp },
    });
  }
}

export const memberReplicationWorker = new MemberReplicationWorker();

