/**
 * 🛰️ BridgeFeedHandler
 * 
 * specializes in analyzing RESO 'FeedTypes' metadata to identify data licensing sources.
 * critical for compliance (IDX vs VOW) when working with combined virtual datasets.
 */

export type FeedTypeSource = 'IDX' | 'VOW' | 'BROKER' | 'OFFER_COMP' | 'UNKNOWN';

export interface BridgeRecord {
  ListingId?: string;
  FeedTypes?: string[];
  [key: string]: any;
}

export class BridgeFeedHandler {
  /**
   * Logs a breakdown of licensing sources for a batch of records.
   * Helps audit cross-feed data redistribution compliance.
   */
  static logSourceBreakdown(records: BridgeRecord[]): void {
    if (!records || records.length === 0) return;

    const stats = {
      idx: 0,
      vow: 0,
      both: 0,
      other: 0,
      missing: 0
    };

    records.forEach(record => {
      const types = record.FeedTypes || [];

      if (types.length === 0) {
        stats.missing++;
        return;
      }

      const hasIdx = types.includes('IDX');
      const hasVow = types.includes('VOW');

      if (hasIdx && hasVow) stats.both++;
      else if (hasIdx) stats.idx++;
      else if (hasVow) stats.vow++;
      else stats.other++;
    });

    console.log('📊 [BRIDGE FEED AUDIT] License Source Breakdown:');
    console.table({
      'IDX Only': stats.idx,
      'VOW Only': stats.vow,
      'Combined (IDX+VOW)': stats.both,
      'Other Distribution': stats.other,
      'Untagged Records': stats.missing
    });
  }

  /**
   * Identifies the primary source for a single record.
   */
  static getPrimarySource(record: BridgeRecord): FeedTypeSource {
    const types = record.FeedTypes || [];
    if (types.includes('VOW')) return 'VOW';
    if (types.includes('IDX')) return 'IDX';
    if (types.includes('Brokerage')) return 'BROKER';
    return 'UNKNOWN';
  }

  /**
   * 🧼 Data Sanitization: Strips non-RESO namespaced fields.
   * If a field cannot be normalized to RESO standards, Bridge prefixes it with a namespace 
   * (e.g., 'Namespace.Field' or 'Custom:Field'). 
   */
  static sanitize(record: BridgeRecord): BridgeRecord {
    const sanitized: BridgeRecord = {};
    const NAMESPACE_REGEX = /[\.:]/;

    Object.keys(record).forEach(key => {
      // Logic: If the key contains a dot or colon, it's a namespaced/custom field that hasn't 
      // been normalized to RESO standard. We strip these to keep the database clean.
      if (!NAMESPACE_REGEX.test(key)) {
        sanitized[key] = record[key];
      }
    });

    return sanitized;
  }
}

import { ODataFilter } from './ODataFilter';

/**
 * 🌉 BridgeQueryBuilder
 * 
 * A utility class for constructing RESO-compliant OData v4 query strings
 * specifically for the Zillow Bridge Interactive API.
 * 
 * Features:
 * - Fluent interface for common OData parameters.
 * - Secure URL encoding for all filter values.
 * - Handles complex filter clustering (logical AND/OR).
 * - Implements default 'StandardStatus eq Active'.
 * 
 * LOGIC GUARDRAIL: $expand is NOT supported for Media. 
 * Bridge API embeds highest resolution media directly in Property records by default.
 */
export class BridgeQueryBuilder {
  private params: Map<string, string> = new Map();
  private filterBuilder: ODataFilter = new ODataFilter();

  /**
   * Disables the default 'StandardStatus eq 'Active'' filter for this query instance.
   */
  ignoreDefaults(): this {
    this.filterBuilder.withoutDefaults();
    return this;
  }

  /**
   * Selects specific fields to return ($select).
   * @param fields Array of field names.
   */
  select(fields: string[]): this {
    this.params.set('$select', fields.join(','));
    return this;
  }

  /**
   * Limits the number of results ($top).
   * @param limit Number of records.
   */
  top(limit: number): this {
    this.params.set('$top', limit.toString());
    return this;
  }

  /**
   * Skips a number of results for pagination ($skip).
   * @param offset Number of records to skip.
   */
  skip(offset: number): this {
    this.params.set('$skip', offset.toString());
    return this;
  }

  /**
   * Orders results by field(s) ($orderby).
   * @param field Field name.
   * @param direction 'asc' or 'desc'.
   */
  orderBy(field: string, direction: 'asc' | 'desc' = 'asc'): this {
    const current = this.params.get('$orderby');
    const entry = `${field} ${direction}`;
    this.params.set('$orderby', current ? `${current},${entry}` : entry);
    return this;
  }

  /**
   * Adds a comparison filter ($filter).
   */
  filter(field: string, op: 'eq' | 'gt' | 'lt' | 'ne' | 'ge' | 'le', value: string | number | boolean): this {
    if (op === 'eq') {
      this.filterBuilder.eq(field, value);
    } else if (op === 'gt') {
      this.filterBuilder.gt(field, value);
    } else if (op === 'lt') {
      this.filterBuilder.lt(field, value);
    } else {
      // For operators not yet in ODataFilter, we handle manually but still leverage the builder
      // This is a temporary measure while ODataFilter expands
      (this.filterBuilder as any).conditions.push(`${field} ${op} ${this.formatValue(value)}`);
    }
    return this;
  }

  /**
   * Adds a case-insensitive 'eq' condition using tolower().
   */
  eqIgnoreCase(field: string, value: string): this {
    this.filterBuilder.eqIgnoreCase(field, value);
    return this;
  }

  /**
   * Adds a geospatial distance filter ($filter=geo.distance(Coordinates, POINT(lon lat)) lt radius).
   */
  near(lat: number, lon: number, radiusInMiles: number, field = 'Coordinates'): this {
    this.filterBuilder.near(field, lat, lon, radiusInMiles);
    return this;
  }

  /**
   * Adds simple Web API proximity parameters (near=lon,lat&radius=Nmi).
   * Used for non-OData proximity search on specific Bridge endpoints.
   */
  nearSimple(lat: number, lon: number, radiusInMiles: number): this {
    this.params.set('near', `${lon},${lat}`);
    this.params.set('radius', `${radiusInMiles}mi`);
    return this;
  }

  /**
   * Adds a 'contains' string filter.
   */
  contains(field: string, value: string): this {
    this.filterBuilder.contains(field, value);
    return this;
  }

  /**
   * Adds a 'startswith' string filter for autocomplete.
   */
  startsWith(field: string, value: string): this {
    this.filterBuilder.startsWith(field, value);
    return this;
  }

  /**
   * Adds an 'endswith' string filter for autocomplete.
   */
  endsWith(field: string, value: string): this {
    this.filterBuilder.endsWith(field, value);
    return this;
  }

  /**
   * Adds an OData 'any' collection lambda filter ($filter=Field/any(a: a eq 'value')).
   * Used for fields like Heating, Appliances, etc.
   */
  any(field: string, values: string | string[]): this {
    this.filterBuilder.any(field, values);
    return this;
  }

  /**
   * Adds an OData 'all' collection lambda filter ($filter=Field/all(a: a eq 'value')).
   */
  all(field: string, values: string | string[]): this {
    this.filterBuilder.all(field, values);
    return this;
  }

  /**
   * Date extraction filters (year, month, day).
   */
  year(value: number, field = 'CloseDate', op: 'eq'|'gt'|'lt'|'ge'|'le' = 'eq'): this {
    this.filterBuilder.year(field, op, value);
    return this;
  }

  month(value: number, field = 'CloseDate', op: 'eq'|'gt'|'lt'|'ge'|'le' = 'eq'): this {
    this.filterBuilder.month(field, op, value);
    return this;
  }

  /**
   * High-level financial quarter helper.
   */
  quarter(yearValue: number, q: 1|2|3|4, field = 'CloseDate'): this {
    this.filterBuilder.quarter(field, yearValue, q);
    return this;
  }

  /**
   * Complex geospatial polygon search.
   */
  intersects(points: { lat: number, lon: number }[], field = 'Coordinates'): this {
    this.filterBuilder.intersects(field, points);
    return this;
  }

  /**
   * Includes the total count of matching records in the response ($count=true).
   * Returns @odata.count in the response body alongside the value array.
   * Essential for pagination UX (e.g. "Showing 1–8 of 247 results").
   */
  count(): this {
    this.params.set('$count', 'true');
    return this;
  }

  /**
   * Expands navigation properties ($expand).
   * LOGIC GUARDRAIL: $expand is NOT supported for Media.
   * Supported expansions include: ListAgent, ListOffice, BuyerAgent, BuyerOffice.
   */
  expand(field: string): this {
    if (field === 'Media') return this;
    if (!this.params.has('$expand')) {
      this.params.set('$expand', field);
    } else {
      const current = this.params.get('$expand');
      this.params.set('$expand', `${current},${field}`);
    }
    return this;
  }

  /**
   * Filters for records modified recently (default 24h).
   * @param duration ISO 8601 duration (e.g. 'P1D', 'PT1H')
   */
  modifiedSince(duration: string): this {
    this.filterBuilder.recentlyModified(duration);
    return this;
  }

  private formatValue(value: string | number | boolean): string {
    if (typeof value === 'string') {
      const escaped = value.replace(/'/g, "''");
      return `'${encodeURIComponent(escaped).replace(/'/g, "%27")}'`;
    }
    return encodeURIComponent(value.toString());
  }

  /**
   * Compiles parameters into a final query string.
   */
  build(): string {
    const filterStr = this.filterBuilder.build();
    if (filterStr) {
      this.params.set('$filter', filterStr);
    }

    // 🛡️ OData v4 Sync Guardrail:
    // If $select is used, expanded fields MUST also be explicitly in the $select list.
    const expandVal = this.params.get('$expand');
    const selectVal = this.params.get('$select');

    if (expandVal && selectVal) {
      const expands = expandVal.split(',');
      const selects = new Set(selectVal.split(','));

      let modified = false;
      expands.forEach(field => {
        if (!selects.has(field)) {
          selects.add(field);
          modified = true;
        }
      });

      if (modified) {
        this.params.set('$select', Array.from(selects).join(','));
      }
    }

    const queryParts: string[] = [];
    this.params.forEach((value, key) => {
      queryParts.push(`${key}=${value}`);
    });

    return queryParts.length > 0 ? `?${queryParts.join('&')}` : '';
  }
}

'use client';

import React, { createContext, useContext, useMemo, ReactNode, useState, useEffect, useCallback } from 'react';
import { useSettingsStore } from '@/store/settingsStore';
import {
  getContrastColor,
  getContrastRatio,
  PW_COLORS,
  type PWColor,
} from '@/lib/utils/contrast';

// ─── Theme Toggle Context ────────────────────────────────────────────────────

type ThemeMode = 'light' | 'dark';

interface ThemeToggleContextValue {
  theme: ThemeMode;
  toggleTheme: () => void;
  setTheme: (mode: ThemeMode) => void;
}

const ThemeToggleContext = createContext<ThemeToggleContextValue>({
  theme: 'dark',
  toggleTheme: () => {},
  setTheme: () => {},
});

export function useTheme(): ThemeToggleContextValue {
  return useContext(ThemeToggleContext);
}

// ─── Types ───────────────────────────────────────────────────────────────────

interface SurfaceContextValue {
  /** The background color of the closest ancestor SurfaceProvider */
  bg: string;
  /** The highest-contrast text color for this surface */
  text: '#0d0d0d' | '#ffffff';
  /** Whether this surface uses white text (i.e., is a dark surface) */
  isOnDark: boolean;
  /** WCAG contrast ratio of text on this bg */
  ratio: number;
  /** Muted text — checked to still pass WCAG AA on this bg */
  mutedText: string;
  /** Hover overlay color for interactive elements on this surface */
  hoverOverlay: string;
  /** Active/pressed overlay color for interactive elements */
  activeOverlay: string;
  /** Focus ring color — always full-contrast opposite of bg */
  focusRingColor: string;
}

// ─── Context ─────────────────────────────────────────────────────────────────

const SurfaceContext = createContext<SurfaceContextValue>({
  bg:             PW_COLORS.bg,
  text:           PW_COLORS.black,
  isOnDark:       false,
  ratio:          17.1,
  mutedText:      PW_COLORS.muted,
  hoverOverlay:   'rgba(0,0,0,0.06)',
  activeOverlay:  'rgba(0,0,0,0.12)',
  focusRingColor: PW_COLORS.black,
});

// ─── Surface Provider ────────────────────────────────────────────────────────

interface SurfaceProviderProps {
  bg: string;
  children: ReactNode;
}

/**
 * Registers a surface background color so all descendant components can
 * call useSurface() to get the correct contrast colors without prop-drilling.
 *
 * @example
 *   <SurfaceProvider bg="#595959">
 *     <PhaseClosedCard />
 *   </SurfaceProvider>
 */
export function SurfaceProvider({ bg, children }: SurfaceProviderProps) {
  const value = useMemo<SurfaceContextValue>(() => {
    const text     = getContrastColor(bg);
    const isOnDark = text === PW_COLORS.white;
    const ratio    = getContrastRatio(bg, text);

    // Muted text: PW muted token if it passes WCAG AA, else primary text color
    let mutedText: string = text;
    try {
      const mutedToken = isOnDark ? PW_COLORS.white : PW_COLORS.muted;
      const mutedRatio = getContrastRatio(bg, mutedToken);
      if (mutedRatio >= 4.5) mutedText = mutedToken;
    } catch { /* fallback already set */ }

    return {
      bg,
      text,
      isOnDark,
      ratio,
      mutedText,
      hoverOverlay:   isOnDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.06)',
      activeOverlay:  isOnDark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.12)',
      focusRingColor: isOnDark ? PW_COLORS.white           : PW_COLORS.black,
    };
  }, [bg]);

  return (
    <SurfaceContext.Provider value={value}>
      {children}
    </SurfaceContext.Provider>
  );
}

// ─── Hook ────────────────────────────────────────────────────────────────────

/**
 * Returns the current surface context — background color and all computed
 * contrast values. Must be called inside a SurfaceProvider.
 *
 * Falls back to the default PW canvas (#f2f2f2 → dark text) if no
 * SurfaceProvider is in scope.
 *
 * @example
 *   function PhaseLabel() {
 *     const { text, mutedText, isOnDark } = useSurface();
 *     return <p style={{ color: mutedText }}>Phase 04 · Closed</p>;
 *   }
 */
export function useSurface(): SurfaceContextValue {
  return useContext(SurfaceContext);
}

// ─── Root Theme Provider ─────────────────────────────────────────────────────

interface ThemeProviderProps {
  children: ReactNode;
}

/**
 * Root-level provider. Wraps the entire app so all components
 * have access to the surface context and theme toggle without extra configuration.
 *
 * Theme is persisted in localStorage under "pw-theme".
 * The <html> element receives data-theme="light"|"dark" and class "light"|"dark".
 *
 * Add this in src/app/layout.tsx around {children}.
 */
export function ThemeProvider({ children }: ThemeProviderProps) {
  const theme = 'dark';

  const applyTheme = useCallback((mode: ThemeMode) => {
    const root = document.documentElement;
    root.setAttribute('data-theme', 'dark');
    root.classList.remove('light');
    root.classList.add('dark');
    try { localStorage.setItem('pw-theme', 'dark'); } catch { /* SSR guard */ }
  }, []);

  // Sync on mount: always force dark theme
  useEffect(() => {
    applyTheme('dark');
  }, [applyTheme]);

  const setTheme = useCallback((_mode: ThemeMode) => {
    // No-op to lock to dark mode
  }, []);

  const toggleTheme = useCallback(() => {
    // No-op to lock to dark mode
  }, []);

  const bg = PW_COLORS.nightBg; // Locked night background token

  return (
    <ThemeToggleContext.Provider value={{ theme, toggleTheme, setTheme }}>
      <SurfaceProvider bg={bg}>
        {children}
      </SurfaceProvider>
    </ThemeToggleContext.Provider>
  );
}

import { deepDiff } from '../deepDiff';

describe('deepDiff', () => {
  // ── Basic scalar changes ──────────────────────────────

  it('returns empty array when objects are identical', () => {
    const obj = { a: 1, b: 'hello', c: true };
    expect(deepDiff(obj, { ...obj })).toEqual([]);
  });

  it('detects changed scalar values', () => {
    const before = { a: 1, b: 'hello' };
    const after = { a: 2, b: 'hello' };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'a', oldValue: 1, newValue: 2 },
    ]);
  });

  it('detects multiple changed fields', () => {
    const before = { a: 1, b: 'hello', c: true };
    const after = { a: 2, b: 'world', c: true };
    const result = deepDiff(before, after);
    expect(result).toHaveLength(2);
    expect(result).toContainEqual({ fieldPath: 'a', oldValue: 1, newValue: 2 });
    expect(result).toContainEqual({ fieldPath: 'b', oldValue: 'hello', newValue: 'world' });
  });

  // ── Added and removed keys ────────────────────────────

  it('detects added keys', () => {
    const before = { a: 1 };
    const after = { a: 1, b: 2 };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'b', oldValue: null, newValue: 2 },
    ]);
  });

  it('detects removed keys (value becomes undefined)', () => {
    const before = { a: 1, b: 2 };
    const after = { a: 1 };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'b', oldValue: 2, newValue: null },
    ]);
  });

  // ── Nested object diffing ─────────────────────────────

  it('diffs nested objects with dot-notation paths', () => {
    const before = { financials: { purchasePrice: 200000, loanAmount: 150000 } };
    const after = { financials: { purchasePrice: 210000, loanAmount: 150000 } };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'financials.purchasePrice', oldValue: 200000, newValue: 210000 },
    ]);
  });

  it('diffs deeply nested objects', () => {
    const before = { a: { b: { c: { d: 1 } } } };
    const after = { a: { b: { c: { d: 2 } } } };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'a.b.c.d', oldValue: 1, newValue: 2 },
    ]);
  });

  it('detects when a nested object is added', () => {
    const before = { a: 1 };
    const after = { a: 1, nested: { x: 10 } };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'nested.x', oldValue: null, newValue: 10 },
    ]);
  });

  // ── Array changes ─────────────────────────────────────

  it('detects array changes', () => {
    const before = { tags: ['a', 'b'] };
    const after = { tags: ['a', 'b', 'c'] };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'tags', oldValue: ['a', 'b'], newValue: ['a', 'b', 'c'] },
    ]);
  });

  it('returns empty array when arrays are identical', () => {
    const before = { tags: [1, 2, 3] };
    const after = { tags: [1, 2, 3] };
    expect(deepDiff(before, after)).toEqual([]);
  });

  it('detects array order changes', () => {
    const before = { items: [1, 2, 3] };
    const after = { items: [3, 2, 1] };
    const result = deepDiff(before, after);
    expect(result).toHaveLength(1);
    expect(result[0].fieldPath).toBe('items');
  });

  // ── Null and undefined handling ───────────────────────

  it('detects null to value change', () => {
    const before = { a: null };
    const after = { a: 42 };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'a', oldValue: null, newValue: 42 },
    ]);
  });

  it('detects value to null change', () => {
    const before = { a: 42 };
    const after = { a: null };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'a', oldValue: 42, newValue: null },
    ]);
  });

  it('treats both undefined as no change', () => {
    const before: any = { a: undefined };
    const after: any = { a: undefined };
    expect(deepDiff(before, after)).toEqual([]);
  });

  // ── Empty objects ─────────────────────────────────────

  it('handles empty before object', () => {
    const result = deepDiff({}, { a: 1 });
    expect(result).toEqual([
      { fieldPath: 'a', oldValue: null, newValue: 1 },
    ]);
  });

  it('handles empty after object', () => {
    const result = deepDiff({ a: 1 }, {});
    expect(result).toEqual([
      { fieldPath: 'a', oldValue: 1, newValue: null },
    ]);
  });

  it('handles both empty objects', () => {
    expect(deepDiff({}, {})).toEqual([]);
  });

  // ── Type changes ──────────────────────────────────────

  it('detects type changes (number → string)', () => {
    const before = { a: 42 };
    const after = { a: '42' };
    const result = deepDiff(before, after);
    expect(result).toEqual([
      { fieldPath: 'a', oldValue: 42, newValue: '42' },
    ]);
  });

  it('detects type changes (object → scalar)', () => {
    const before = { a: { nested: 1 } };
    const after = { a: 'flat' };
    const result = deepDiff(before, after);
    expect(result).toHaveLength(1);
    expect(result[0].fieldPath).toBe('a');
  });

  // ── Date handling ─────────────────────────────────────

  it('normalizes Dates to ISO strings for comparison', () => {
    const date = new Date('2026-01-15T00:00:00.000Z');
    const before = { created: date };
    const after = { created: date };
    // Same date → no change
    expect(deepDiff(before, after)).toEqual([]);
  });

  it('detects Date value changes', () => {
    const before = { created: new Date('2026-01-01') };
    const after = { created: new Date('2026-06-01') };
    const result = deepDiff(before, after);
    expect(result).toHaveLength(1);
    expect(result[0].fieldPath).toBe('created');
  });

  // ── Firestore Timestamp-like objects ──────────────────

  it('normalizes Firestore Timestamp-like objects', () => {
    const ts1 = { _seconds: 1700000000 };
    const ts2 = { _seconds: 1700000000 };
    const before = { created: ts1 };
    const after = { created: ts2 };
    // Same timestamp → no change
    expect(deepDiff(before, after)).toEqual([]);
  });

  it('normalizes objects with toDate() method', () => {
    const ts1 = { toDate: () => new Date('2026-01-01T00:00:00.000Z') };
    const ts2 = { toDate: () => new Date('2026-01-01T00:00:00.000Z') };
    expect(deepDiff({ t: ts1 }, { t: ts2 })).toEqual([]);
  });

  // ── Real-world ProjectFinancials-like scenario ────────

  it('diffs a realistic project financials update', () => {
    const before = {
      status: 'acquisition',
      financials: {
        purchasePrice: 200000,
        loanAmount: 150000,
        projectedRehabCost: 30000,
        monthlyGrossRent: 1800,
      },
      members: { uid1: { role: 'Lead Investor' } },
    };
    const after = {
      status: 'acquisition',
      financials: {
        purchasePrice: 210000, // changed
        loanAmount: 150000,
        projectedRehabCost: 35000, // changed
        monthlyGrossRent: 1800,
      },
      members: { uid1: { role: 'Lead Investor' } },
    };

    const result = deepDiff(before, after);
    expect(result).toHaveLength(2);
    expect(result).toContainEqual({
      fieldPath: 'financials.purchasePrice',
      oldValue: 200000,
      newValue: 210000,
    });
    expect(result).toContainEqual({
      fieldPath: 'financials.projectedRehabCost',
      oldValue: 30000,
      newValue: 35000,
    });
  });
});

/**
 * contrast.ts — PaperWorking WCAG 2.1 Contrast Engine
 *
 * Provides pure-function contrast checkers and React hooks so every component
 * that renders on a dynamic background automatically selects the
 * highest-contrast text / interactive-state colors from the design system.
 *
 * Algorithm: WCAG 2.1 relative luminance → contrast ratio
 * Reference: https://www.w3.org/TR/WCAG21/#contrast-minimum
 *
 * Pre-computed results for the PaperWorking palette (for documentation):
 *   #f2f2f2 → #0d0d0d  (17.1:1  — WCAG AAA)
 *   #cccccc → #0d0d0d  (10.5:1  — WCAG AAA)
 *   #a5a5a5 → #0d0d0d  ( 5.6:1  — WCAG AA, dark wins by 0.9:1)
 *   #7f7f7f → #ffffff  ( 4.6:1  — WCAG AA, light wins)
 *   #595959 → #ffffff  ( 7.2:1  — WCAG AAA)
 *   #0d0d0d → #ffffff  (19.6:1  — WCAG AAA)
 *   #ffffff → #0d0d0d  (21.0:1  — WCAG AAA)
 *
 * Public API surface:
 *   Core math:
 *     hexToRgb()          — parse hex → [R, G, B]
 *     getLuminance()      — WCAG relative luminance
 *     getContrastRatio()  — contrast ratio between two colors
 *     getContrastColor()  — best text color (#0d0d0d | #ffffff) for a bg
 *     requiresLightText() — boolean shorthand
 *     getContrastClass()  — CSS class string for Tailwind
 *
 *   Interactive styles (inline style objects):
 *     getAccessibleButtonStyles()  — full 4-state style set for a given bg
 *
 *   React hooks:
 *     useContrastColor()    — memoized text color value
 *     useContrastStyle()    — memoized color + class + WCAG pass/fail
 *     useAdaptiveText()     — all-in-one: color + class + ratio + level
 *     useInteractiveStyles()— 4-state style objects for interactive elements
 *
 *   Dev utilities:
 *     auditPalette()        — WCAG table for all PW palette combinations
 */

import { useMemo, CSSProperties } from 'react';

// ─── PaperWorking brand tokens ────────────────────────────────────────────────

export const PW_COLORS = {
  black:         '#0d0d0d',
  white:         '#ffffff',
  bg:            '#f2f2f2',
  transactional: '#cccccc',
  surface:       '#ffffff',
  border:        '#d4d4d4',
  fg:            '#3d3d3d',
  muted:         '#7f7f7f',
  subtle:        '#a5a5a5',
  accent:        '#454955',

  // Deal lifecycle phases
  phaseSourceing: '#f2f2f2',
  phaseContract:  '#cccccc',
  phaseRehab:     '#a5a5a5',
  phaseListed:    '#7f7f7f',
  phaseClosed:    '#595959',

  // Vault surface (external investor portal)
  vault:          '#1a1a1a',

  // Night background token (locked theme)
  nightBg:        '#121014',
} as const;

export type PWColor = (typeof PW_COLORS)[keyof typeof PW_COLORS];

// ─── Core WCAG math ──────────────────────────────────────────────────────────

/**
 * Converts a single 8-bit channel value (0–255) to its linear light value
 * using the sRGB transfer function defined by WCAG 2.1.
 */
function toLinear(channel8bit: number): number {
  const c = channel8bit / 255;
  return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
}

/**
 * Parses a 3- or 6-digit hex color string into its [R, G, B] components (0–255).
 * Throws if the string is not a valid hex color.
 */
export function hexToRgb(hex: string): [number, number, number] {
  const clean = hex.replace('#', '').trim();

  if (clean.length === 3) {
    return [
      parseInt(clean[0] + clean[0], 16),
      parseInt(clean[1] + clean[1], 16),
      parseInt(clean[2] + clean[2], 16),
    ];
  }

  if (clean.length === 6) {
    return [
      parseInt(clean.slice(0, 2), 16),
      parseInt(clean.slice(2, 4), 16),
      parseInt(clean.slice(4, 6), 16),
    ];
  }

  throw new Error(`[contrast] Invalid hex color: "${hex}"`);
}

/**
 * Computes the WCAG 2.1 relative luminance of a hex color.
 * Returns a value in the range [0, 1] where 0 = pure black, 1 = pure white.
 */
export function getLuminance(hex: string): number {
  const [r, g, b] = hexToRgb(hex);
  return 0.2126 * toLinear(r) + 0.7152 * toLinear(g) + 0.0722 * toLinear(b);
}

/**
 * Computes the WCAG 2.1 contrast ratio between two hex colors.
 * Returns a value in [1, 21] where 1 = no contrast, 21 = black on white.
 */
export function getContrastRatio(hex1: string, hex2: string): number {
  const l1 = getLuminance(hex1);
  const l2 = getLuminance(hex2);
  const lighter = Math.max(l1, l2);
  const darker  = Math.min(l1, l2);
  return (lighter + 0.05) / (darker + 0.05);
}

// ─── Primary color selectors ─────────────────────────────────────────────────

type ContrastResult = '#0d0d0d' | '#ffffff';
type WCAGLevel = 'AAA' | 'AA' | 'AA-large' | 'FAIL';

function wcagLevel(ratio: number): WCAGLevel {
  if (ratio >= 7.0)  return 'AAA';
  if (ratio >= 4.5)  return 'AA';
  if (ratio >= 3.0)  return 'AA-large';
  return 'FAIL';
}

/**
 * Returns the highest-contrast text color (PW near-black or white)
 * for a given background hex color.
 *
 * Uses PaperWorking brand tokens (#0d0d0d, #ffffff) rather than pure black/white.
 *
 * @example
 *   getContrastColor('#7f7f7f') // → '#ffffff'
 *   getContrastColor('#f2f2f2') // → '#0d0d0d'
 *   getContrastColor('#a5a5a5') // → '#0d0d0d'  (dark wins by narrow margin)
 */
export function getContrastColor(backgroundHex: string): ContrastResult {
  try {
    const darkRatio  = getContrastRatio(backgroundHex, PW_COLORS.black);
    const lightRatio = getContrastRatio(backgroundHex, PW_COLORS.white);
    return lightRatio > darkRatio ? PW_COLORS.white : PW_COLORS.black;
  } catch {
    return PW_COLORS.black;
  }
}

/**
 * Returns true if the given background requires light (white) text to meet
 * WCAG AA minimum contrast (4.5:1 for normal text).
 */
export function requiresLightText(backgroundHex: string): boolean {
  return getContrastColor(backgroundHex) === PW_COLORS.white;
}

/**
 * Returns a CSS class string for text color based on background.
 * Maps to utility classes defined in globals.css.
 *
 * @example
 *   getContrastClass('#595959') // → 'pw-text-on-dark'
 *   getContrastClass('#f2f2f2') // → 'pw-text-on-light'
 */
export function getContrastClass(backgroundHex: string): 'pw-text-on-dark' | 'pw-text-on-light' {
  return requiresLightText(backgroundHex) ? 'pw-text-on-dark' : 'pw-text-on-light';
}

// ─── Interactive element style factory ───────────────────────────────────────

/**
 * All four interaction states as inline CSSProperties objects.
 * Use this when a component renders on a dynamic/unknown background
 * and you cannot rely on static CSS class selectors.
 */
export interface InteractiveStateStyles {
  /** Default state — highest-contrast text on bg */
  default: CSSProperties;
  /** Hover state — subtle bg overlay, same text color */
  hover: CSSProperties;
  /** Focus/active state — 2px outline ring, same text color */
  focus: CSSProperties;
  /** Disabled state — 38% opacity, not-allowed cursor */
  disabled: CSSProperties;
  /** Whether this surface needs light (white) text */
  isOnDark: boolean;
}

/**
 * Returns inline style objects for all four interaction states of an
 * interactive element on the given background.
 *
 * The returned hover/focus overlays are always computed against the
 * background — dark surfaces get a white-alpha overlay, light surfaces
 * get a black-alpha overlay. This is mathematically guaranteed to
 * provide a perceivable state change regardless of background hue.
 *
 * @example
 *   const styles = getAccessibleButtonStyles('#595959');
 *   // Use styles.default on the element, swap to styles.hover on :hover etc.
 */
export function getAccessibleButtonStyles(backgroundHex: string): InteractiveStateStyles {
  const isOnDark = requiresLightText(backgroundHex);
  const textColor = getContrastColor(backgroundHex);

  // Overlay colors: white-alpha on dark surfaces, black-alpha on light
  const hoverOverlay   = isOnDark ? 'rgba(255,255,255,0.10)' : 'rgba(0,0,0,0.06)';
  const activeOverlay  = isOnDark ? 'rgba(255,255,255,0.18)' : 'rgba(0,0,0,0.12)';
  // Focus ring color: always full-contrast opposite
  const focusRingColor = isOnDark ? PW_COLORS.white : PW_COLORS.black;

  return {
    isOnDark,
    default: {
      color: textColor,
      backgroundColor: 'transparent',
      border: 'none',
      cursor: 'pointer',
      transition: 'background-color 0.15s ease, opacity 0.15s ease',
    },
    hover: {
      color: textColor,
      backgroundColor: hoverOverlay,
    },
    focus: {
      color: textColor,
      outline: `2px solid ${focusRingColor}`,
      outlineOffset: '3px',
    },
    disabled: {
      color: textColor,
      opacity: 0.38,
      cursor: 'not-allowed',
      pointerEvents: 'none',
    },
  };
}

// ─── React hooks ─────────────────────────────────────────────────────────────

/**
 * React hook that memoizes contrast computation.
 * Safe to call on every render — WCAG math only re-runs when backgroundHex changes.
 *
 * @example
 *   function MyPanel({ bg }: { bg: string }) {
 *     const textColor = useContrastColor(bg);
 *     return <div style={{ background: bg, color: textColor }}>Content</div>;
 *   }
 */
export function useContrastColor(backgroundHex: string): ContrastResult {
  return useMemo(() => getContrastColor(backgroundHex), [backgroundHex]);
}

/**
 * React hook that returns both the contrast color and its CSS class string.
 */
export function useContrastStyle(backgroundHex: string): {
  color: ContrastResult;
  className: 'pw-text-on-dark' | 'pw-text-on-light';
  ratio: number;
  passesAA: boolean;
  passesAAA: boolean;
} {
  return useMemo(() => {
    const color = getContrastColor(backgroundHex);
    const ratio = getContrastRatio(backgroundHex, color);
    return {
      color,
      className: color === PW_COLORS.white ? 'pw-text-on-dark' : 'pw-text-on-light',
      ratio,
      passesAA:  ratio >= 4.5,
      passesAAA: ratio >= 7.0,
    };
  }, [backgroundHex]);
}

/**
 * All-in-one adaptive text hook. Returns everything a component needs to
 * render text correctly on a dynamic background — color, CSS class, ratio,
 * and WCAG compliance level. This is the preferred hook for new components.
 *
 * @example
 *   function PhaseCard({ bg, label }: { bg: string; label: string }) {
 *     const text = useAdaptiveText(bg);
 *     return (
 *       <div style={{ backgroundColor: bg }}>
 *         <span style={{ color: text.color }}>{label}</span>
 *         {text.level === 'FAIL' && <span>⚠ Low contrast</span>}
 *       </div>
 *     );
 *   }
 */
export function useAdaptiveText(backgroundHex: string): {
  /** The hex text color to apply — either #0d0d0d or #ffffff */
  color: ContrastResult;
  /** CSS utility class — 'pw-text-on-dark' | 'pw-text-on-light' */
  className: 'pw-text-on-dark' | 'pw-text-on-light';
  /** WCAG contrast ratio (rounded to 2dp) */
  ratio: number;
  /** WCAG compliance level */
  level: WCAGLevel;
  /** True if this surface requires white text */
  isOnDark: boolean;
  /** Muted text color — still passes AA on this surface */
  mutedColor: string;
} {
  return useMemo(() => {
    const color   = getContrastColor(backgroundHex);
    const ratio   = getContrastRatio(backgroundHex, color);
    const isOnDark = color === PW_COLORS.white;

    // Muted text: use the design system muted value if it passes AA,
    // otherwise fall back to the primary contrast color at 65% opacity.
    let mutedColor: string;
    try {
      const mutedToken = isOnDark ? PW_COLORS.white : PW_COLORS.muted;
      const mutedRatio = getContrastRatio(backgroundHex, mutedToken);
      mutedColor = mutedRatio >= 4.5 ? mutedToken : color;
    } catch {
      mutedColor = color;
    }

    return {
      color,
      className: isOnDark ? 'pw-text-on-dark' : 'pw-text-on-light',
      ratio: Math.round(ratio * 100) / 100,
      level: wcagLevel(ratio),
      isOnDark,
      mutedColor,
    };
  }, [backgroundHex]);
}

/**
 * Returns inline style objects for all four interaction states.
 * Prefer this hook when rendering interactive elements (buttons, tabs,
 * menu items) on programmatic / user-defined backgrounds.
 *
 * @example
 *   function DynamicButton({ bg, label }: { bg: string; label: string }) {
 *     const [hovered, setHovered] = useState(false);
 *     const [focused, setFocused] = useState(false);
 *     const s = useInteractiveStyles(bg);
 *     return (
 *       <button
 *         style={focused ? s.focus : hovered ? s.hover : s.default}
 *         onMouseEnter={() => setHovered(true)}
 *         onMouseLeave={() => setHovered(false)}
 *         onFocus={() => setFocused(true)}
 *         onBlur={() => setFocused(false)}
 *       >
 *         {label}
 *       </button>
 *     );
 *   }
 */
export function useInteractiveStyles(backgroundHex: string): InteractiveStateStyles {
  return useMemo(() => getAccessibleButtonStyles(backgroundHex), [backgroundHex]);
}

// ─── Palette audit helper (dev-only) ─────────────────────────────────────────

/**
 * Returns a report of contrast ratios for all PaperWorking palette combinations.
 * Use in development to validate the design system.
 *
 * @example
 *   if (process.env.NODE_ENV === 'development') {
 *     console.table(auditPalette());
 *   }
 */
export function auditPalette(): Record<string, {
  darkText: string;
  lightText: string;
  winner: string;
  ratio: string;
  level: WCAGLevel;
}> {
  const report: Record<string, {
    darkText: string;
    lightText: string;
    winner: string;
    ratio: string;
    level: WCAGLevel;
  }> = {};

  for (const [name, hex] of Object.entries(PW_COLORS)) {
    try {
      const darkRatio  = getContrastRatio(hex, PW_COLORS.black);
      const lightRatio = getContrastRatio(hex, PW_COLORS.white);
      const winner     = lightRatio > darkRatio ? 'white (#ffffff)' : 'dark (#0d0d0d)';
      const winRatio   = Math.max(darkRatio, lightRatio);
      report[`${name} (${hex})`] = {
        darkText:  `${darkRatio.toFixed(2)}:1`,
        lightText: `${lightRatio.toFixed(2)}:1`,
        winner,
        ratio: `${winRatio.toFixed(2)}:1`,
        level: wcagLevel(winRatio),
      };
    } catch {
      // Skip non-hex values (e.g. CSS variable references)
    }
  }

  return report;
}

/**
 * Deep Diff Utility
 *
 * Compares two objects recursively, returning an array of changed leaf values
 * with their dot-notation field paths. Used by the activity log system to
 * produce granular audit entries.
 *
 * Design decisions:
 *   - Arrays are compared by JSON equality (not element-wise) to keep the
 *     audit log entries atomic. A future version could diff arrays element-wise
 *     if the UX needs it.
 *   - `undefined` and missing keys are treated as equivalent (both mean "absent").
 *   - Firestore Timestamps are coerced to ISO strings before comparison.
 */

export interface FieldChange {
  fieldPath: string;
  oldValue: any;
  newValue: any;
}

/**
 * Coerce Firestore Timestamps and Dates to ISO strings for stable comparison.
 * Returns the original value for everything else.
 */
function normalizeValue(val: any): any {
  if (val === null || val === undefined) return val;
  // Firestore admin Timestamp
  if (typeof val?.toDate === 'function') return val.toDate().toISOString();
  // Firestore Timestamp-like objects
  if (val?._seconds !== undefined) return new Date(val._seconds * 1000).toISOString();
  // JS Date
  if (val instanceof Date) return val.toISOString();
  return val;
}

/**
 * Check if a value is a plain object (not array, date, null, etc.)
 */
function isPlainObject(val: any): val is Record<string, any> {
  return (
    val !== null &&
    typeof val === 'object' &&
    !Array.isArray(val) &&
    !(val instanceof Date) &&
    typeof val?.toDate !== 'function' &&
    val?._seconds === undefined
  );
}

/**
 * Deep diff two objects, returning array of {fieldPath, oldValue, newValue}
 * for all changed leaf values.
 *
 * @param before  The previous state of the object
 * @param after   The new state of the object
 * @param prefix  Internal: current dot-notation path (for recursion)
 * @returns       Array of field changes (empty if objects are equal)
 */
export function deepDiff(
  before: Record<string, any>,
  after: Record<string, any>,
  prefix = ''
): FieldChange[] {
  const changes: FieldChange[] = [];

  // Collect all unique keys from both objects
  const allKeys = new Set<string>([
    ...Object.keys(before ?? {}),
    ...Object.keys(after ?? {}),
  ]);

  for (const key of allKeys) {
    const fullPath = prefix ? `${prefix}.${key}` : key;

    const rawOld = before?.[key];
    const rawNew = after?.[key];

    const oldVal = normalizeValue(rawOld);
    const newVal = normalizeValue(rawNew);

    // Both undefined/missing → no change
    if (oldVal === undefined && newVal === undefined) continue;

    // Both are plain objects → recurse
    if (isPlainObject(rawOld) && isPlainObject(rawNew)) {
      changes.push(...deepDiff(rawOld, rawNew, fullPath));
      continue;
    }

    // One is a plain object and the other is null/undefined → recurse with empty
    if (isPlainObject(rawNew) && (rawOld === undefined || rawOld === null)) {
      changes.push(...deepDiff({}, rawNew, fullPath));
      continue;
    }
    if (isPlainObject(rawOld) && (rawNew === undefined || rawNew === null)) {
      changes.push(...deepDiff(rawOld, {}, fullPath));
      continue;
    }

    // One is a plain object and the other is a different type (type changed) → leaf change
    if (isPlainObject(rawOld) !== isPlainObject(rawNew)) {
      changes.push({ fieldPath: fullPath, oldValue: oldVal, newValue: newVal });
      continue;
    }

    // Arrays → compare by JSON serialization
    if (Array.isArray(oldVal) || Array.isArray(newVal)) {
      const oldJson = JSON.stringify(oldVal ?? null);
      const newJson = JSON.stringify(newVal ?? null);
      if (oldJson !== newJson) {
        changes.push({ fieldPath: fullPath, oldValue: oldVal, newValue: newVal });
      }
      continue;
    }

    // Scalar comparison
    if (oldVal !== newVal) {
      changes.push({
        fieldPath: fullPath,
        oldValue: oldVal ?? null,
        newValue: newVal ?? null,
      });
    }
  }

  return changes;
}

/**
 * 1031 Exchange Deadline Calculator
 * 
 * Rules per IRC §1031:
 * - Identification Deadline: Exactly 45 calendar days after the sale date (closing date).
 * - Exchange Deadline: Exactly 180 calendar days after the sale date (or due date of tax return, whichever is earlier).
 * 
 * Computes exact target dates and remaining day countdowns. Handles leap years, month boundaries, and timezones safely.
 */

export interface Exchange1031Deadlines {
  saleDate: string; // ISO format (YYYY-MM-DD)
  identificationDeadline: string; // YYYY-MM-DD
  exchangeDeadline: string; // YYYY-MM-DD
  daysRemainingIdentification: number;
  daysRemainingExchange: number;
  isIdentificationExpired: boolean;
  isExchangeExpired: boolean;
}

import { ReplacementProperty } from '@/types/schema';

function parseToUTCMidnight(dateInput: Date | string): Date {
  if (!dateInput) {
    return new Date(Date.UTC(2026, 5, 1));
  }
  if (typeof dateInput === 'string') {
    const parts = dateInput.split('T')[0].split('-');
    if (parts.length === 3) {
      const year = parseInt(parts[0], 10);
      const month = parseInt(parts[1], 10) - 1;
      const day = parseInt(parts[2], 10);
      if (!isNaN(year) && !isNaN(month) && !isNaN(day)) {
        return new Date(Date.UTC(year, month, day));
      }
    }
    const d = new Date(dateInput);
    if (isNaN(d.getTime())) {
      return new Date(Date.UTC(2026, 5, 1));
    }
    return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  } else {
    if (isNaN(dateInput.getTime())) {
      return new Date(Date.UTC(2026, 5, 1));
    }
    return new Date(Date.UTC(dateInput.getFullYear(), dateInput.getMonth(), dateInput.getDate()));
  }
}

/**
 * Computes 1031 exchange deadlines given a sale date string or Date object.
 */
export function compute1031Deadlines(
  saleDateInput: Date | string,
  referenceDateInput: Date | string = new Date()
): Exchange1031Deadlines {
  const saleUTC = parseToUTCMidnight(saleDateInput);
  const refUTC = parseToUTCMidnight(referenceDateInput);

  // 45 days after sale date
  const identUTC = new Date(saleUTC.getTime() + 45 * 24 * 60 * 60 * 1000);
  // 180 days after sale date
  const exchangeUTC = new Date(saleUTC.getTime() + 180 * 24 * 60 * 60 * 1000);

  const MS_PER_DAY = 1000 * 60 * 60 * 24;

  const daysRemainingIdentification = Math.ceil((identUTC.getTime() - refUTC.getTime()) / MS_PER_DAY);
  const daysRemainingExchange = Math.ceil((exchangeUTC.getTime() - refUTC.getTime()) / MS_PER_DAY);

  const formatISO = (d: Date) => d.toISOString().split('T')[0];

  return {
    saleDate: formatISO(saleUTC),
    identificationDeadline: formatISO(identUTC),
    exchangeDeadline: formatISO(exchangeUTC),
    daysRemainingIdentification: Math.max(0, daysRemainingIdentification),
    daysRemainingExchange: Math.max(0, daysRemainingExchange),
    isIdentificationExpired: daysRemainingIdentification < 0,
    isExchangeExpired: daysRemainingExchange < 0,
  };
}

import { Project } from '@/types/schema';
import { DEFAULT_TODOS } from '@/lib/constants/todos';

/**
 * Computes the completion percentage for a specific phase of a project.
 * Calculation: (completed todos in phase / total todos in phase) * 100
 */
export function computePhaseProgress(project: Project, phase: number): number {
  const defaults = DEFAULT_TODOS[phase] || [];
  if (defaults.length === 0) return 0;

  const currentTodos = defaults.map(defaultTodo => {
    const savedTodo = project.actionItems?.find((t: any) => t.id === defaultTodo.id);
    return savedTodo ? { ...defaultTodo, ...savedTodo } : defaultTodo;
  });

  const completedCount = currentTodos.filter(todo => todo.completed).length;
  return Math.round((completedCount / currentTodos.length) * 100);
}

