// ── Census API fetch (no browser needed) ──────────────────────

interface CensusYearData {
  year: number;
  population: number;
  medianIncome: number;
  medianHomeValue: number;
}

async function fetchCensusAPI(zip: string): Promise<CensusYearData[]> {
  console.log('\n📡  [Census API] Fetching ACS 5-Year batch data…');
  const YEARS = [2023, 2022, 2021, 2020, 2019, 2018, 2017, 2016, 2015, 2014];
  const VARS = 'B01003_001E,B19013_001E,B25077_001E';
  const KEY = process.env.CENSUS_API_KEY ? `&key=${process.env.CENSUS_API_KEY}` : '';

  const rows: CensusYearData[] = [];

  for (const year of YEARS) {
    try {
      const url = `https://api.census.gov/data/${year}/acs/acs5?get=${VARS}&for=zip%20code%20tabulation%20area:${zip}${KEY}`;
      const res = await fetch(url);
      if (!res.ok) continue;
      const data = (await res.json()) as string[][];
      if (!Array.isArray(data) || data.length < 2) continue;
      const [headers, values] = data;
      const get = (k: string) => {
        const i = headers.indexOf(k);
        return i >= 0 ? parseInt(values[i], 10) || 0 : 0;
      };
      rows.push({
        year,
        population: get('B01003_001E'),
        medianIncome: get('B19013_001E'),
        medianHomeValue: get('B25077_001E'),
      });
    } catch {
      continue;
    }
  }

  return rows.sort((a, b) => a.year - b.year);
}

// ── Formatting helpers ────────────────────────────────────────

function fmtNum(n?: number): string {
  if (n == null || n <= 0) return '—';
  return n.toLocaleString('en-US');
}
function fmtUSD(n?: number): string {
  if (n == null || n <= 0) return '—';
  return `$${n.toLocaleString('en-US')}`;
}
function computeGrowth(rows: CensusYearData[], key: keyof CensusYearData, lookback: number): string {
  if (rows.length < 2) return '—';
  const latest = rows[rows.length - 1];
  const cutoff = latest.year - lookback;
  const baseline = rows.find((r) => r.year >= cutoff) ?? rows[0];
  const base = Number(baseline[key]);
  const curr = Number(latest[key]);
  if (!base) return '—';
  const pct = ((curr - base) / base) * 100;
  return `${pct >= 0 ? '+' : ''}${pct.toFixed(2)}%`;
}

// ── Main ──────────────────────────────────────────────────────

async function main() {
  console.log(`\n🔍  Market Vitals — Multi-Source Scraper`);
  console.log(`📍  ZIP: ${ZIP}`);
  console.log(`📂  Sources: ${SOURCE === 'all' ? 'Social Explorer + NAR + Census' : SOURCE}`);
  console.log('═'.repeat(60));

  // 1. Always fetch Census API data (fast, reliable, no browser)
  const censusRows = await fetchCensusAPI(ZIP);
  const latest = censusRows.length > 0 ? censusRows[censusRows.length - 1] : null;

  // 2. Browser-based scraping
  const browser = await chromium.launch({ headless: !SCREENSHOT });
  const snapshots: DemographicSnapshot[] = [];

  try {
    if (SOURCE === 'all' || SOURCE === 'social') {
      const se = await scrapeSocialExplorer(browser, ZIP);
      if (se) snapshots.push(se);
    }

    if (SOURCE === 'all' || SOURCE === 'nar') {
      const nar = await scrapeNARResearch(browser, ZIP);
      if (nar) snapshots.push(nar);
    }

    if (SOURCE === 'all' || SOURCE === 'census') {
      const cr = await scrapeCensusReporter(browser, ZIP);
      if (cr) snapshots.push(cr);
    }
  } finally {
    await browser.close();
  }

  // 3. Compose output
  const growthPop5yr = computeGrowth(censusRows, 'population', 5);
  const growthPop10yr = computeGrowth(censusRows, 'population', 10);
  const growthIncome5yr = computeGrowth(censusRows, 'medianIncome', 5);
  const growthIncome10yr = computeGrowth(censusRows, 'medianIncome', 10);

  if (OUTPUT === 'json') {
    const output = {
      zip: ZIP,
      fetchedAt: new Date().toISOString(),
      censusAPI: {
        source: 'U.S. Census Bureau ACS 5-Year Estimates',
        summary: latest
          ? {
              population: latest.population,
              medianIncome: latest.medianIncome,
              medianHomeValue: latest.medianHomeValue,
              populationGrowth5yr: growthPop5yr,
              populationGrowth10yr: growthPop10yr,
              incomeGrowth5yr: growthIncome5yr,
              incomeGrowth10yr: growthIncome10yr,
            }
          : null,
        trend: censusRows,
      },
      browserSources: snapshots,
    };
    console.log(JSON.stringify(output, null, 2));
  } else {
    // Summary table
    console.log(`\n${'═'.repeat(60)}`);
    console.log(`📍  ZIP ${ZIP} — Market Vitals Summary`);
    console.log(`${'═'.repeat(60)}`);

    if (latest) {
      console.log(`\n   Census API (ACS ${latest.year})`);
      console.log(`   ${'─'.repeat(40)}`);
      console.log(`   Population        : ${fmtNum(latest.population)}`);
      console.log(`   Median HH Income  : ${fmtUSD(latest.medianIncome)}`);
      console.log(`   Median Home Value : ${fmtUSD(latest.medianHomeValue)}`);
      console.log(`   Pop Growth  5yr   : ${growthPop5yr}`);
      console.log(`   Pop Growth  10yr  : ${growthPop10yr}`);
      console.log(`   Income Growth 5yr : ${growthIncome5yr}`);
      console.log(`   Income Growth 10yr: ${growthIncome10yr}`);

      console.log(`\n   📅  10-Year Trend`);
      console.log(`   ${'─'.repeat(50)}`);
      console.log(
        `   ${'Year'.padEnd(6)}${'Population'.padEnd(14)}${'Med. Income'.padEnd(16)}${'Home Value'}`,
      );
      for (const r of censusRows) {
        console.log(
          `   ${String(r.year).padEnd(6)}${fmtNum(r.population).padEnd(14)}${fmtUSD(r.medianIncome).padEnd(16)}${fmtUSD(r.medianHomeValue)}`,
        );
      }
    }

    // Browser source results
    for (const snap of snapshots) {
      console.log(`\n   ${snap.source}`);
      console.log(`   ${'─'.repeat(40)}`);
      console.log(`   URL: ${snap.sourceUrl}`);
      if (snap.population) console.log(`   Population       : ${fmtNum(snap.population)}`);
      if (snap.medianHouseholdIncome)
        console.log(`   Median HH Income : ${fmtUSD(snap.medianHouseholdIncome)}`);
      if (snap.medianHomeValue)
        console.log(`   Median Home Value: ${fmtUSD(snap.medianHomeValue)}`);
      if (snap.medianAge) console.log(`   Median Age       : ${snap.medianAge}`);
      if (snap.ownerOccupiedPct)
        console.log(`   Owner-Occupied   : ${snap.ownerOccupiedPct}%`);

      if (snap.additionalMetrics && Object.keys(snap.additionalMetrics).length > 0) {
        console.log(`   Additional Data:`);
        for (const [k, v] of Object.entries(snap.additionalMetrics)) {
          if (v.length < 100) {
            console.log(`     ${k}: ${v}`);
          }
        }
      }
      if (snap.screenshotPath) console.log(`   Screenshot: ${snap.screenshotPath}`);
    }
  }

  console.log(`\n✅  Done. ${snapshots.length + 1} source(s) queried.\n`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

import { create } from 'zustand';
import { db } from '@/lib/firebase/config';
import { doc, updateDoc, getDoc } from 'firebase/firestore';
import type { NotificationCategory, CategoryPreference } from '@/types/user';

/* ═══════════════════════════════════════════════════════
   Notification Preferences Store

   Manages:
   • Granular per-category preference toggles (inbox, email, push)
   • Global email and push notification opt-out controls
   • Timezone-aware quiet hours DND window
   • Real-time or optimistic synchronization with Firestore /users/{uid}
   ═══════════════════════════════════════════════════════ */

interface NotificationPreferencesState {
  loading: boolean;
  saving: boolean;
  categories: Record<NotificationCategory, CategoryPreference>;
  emailEnabled: boolean;
  pushEnabled: boolean;
  autoArchiveDays: number;
  quietHours: {
    enabled: boolean;
    start: string;
    end: string;
    timezone: string;
  };

  // Actions
  loadPreferences: (userId: string) => Promise<void>;
  updateCategoryPreference: (userId: string, category: NotificationCategory, channel: keyof CategoryPreference, enabled: boolean) => Promise<void>;
  updateGlobalToggle: (userId: string, channel: 'email' | 'push', enabled: boolean) => Promise<void>;
  updateQuietHours: (userId: string, updates: Partial<NotificationPreferencesState['quietHours']>) => Promise<void>;
  updateAutoArchiveDays: (userId: string, days: number) => Promise<void>;
}

export const DEFAULT_CATEGORY_PREFERENCES: Record<NotificationCategory, CategoryPreference> = {
  syndication: { inbox: true, email: true, push: true },
  bids: { inbox: true, email: true, push: false },
  tasks: { inbox: true, email: true, push: false },
  deadlines: { inbox: true, email: true, push: true },
  billing: { inbox: true, email: true, push: false },
  alerts: { inbox: true, email: true, push: true },
};

export const useNotificationPreferencesStore = create<NotificationPreferencesState>((set, get) => ({
  loading: false,
  saving: false,
  categories: DEFAULT_CATEGORY_PREFERENCES,
  emailEnabled: true,
  pushEnabled: true,
  autoArchiveDays: 30,
  quietHours: {
    enabled: false,
    start: '22:00',
    end: '08:00',
    timezone: typeof window !== 'undefined' ? Intl.DateTimeFormat().resolvedOptions().timeZone : 'America/New_York',
  },

  loadPreferences: async (userId: string) => {
    set({ loading: true });
    try {
      const userRef = doc(db, 'users', userId);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const data = userSnap.data();
        const prefs = data.preferences;

        // Merge user preferences with system default templates
        const mergedCategories = { ...DEFAULT_CATEGORY_PREFERENCES };
        if (prefs?.categories) {
          Object.keys(DEFAULT_CATEGORY_PREFERENCES).forEach((catKey) => {
            const cat = catKey as NotificationCategory;
            if (prefs.categories[cat]) {
              mergedCategories[cat] = {
                inbox: prefs.categories[cat].inbox !== false,
                email: prefs.categories[cat].email !== false,
                push: prefs.categories[cat].push !== false,
              };
            }
          });
        }

        // Enforce billing and deadlines cannot be disabled (critical billing/security guardrails)
        mergedCategories.billing.inbox = true;
        mergedCategories.billing.email = true;
        mergedCategories.deadlines.inbox = true;
        mergedCategories.deadlines.email = true;

        set({
          categories: mergedCategories,
          emailEnabled: prefs?.emailEnabled !== false,
          pushEnabled: prefs?.pushEnabled !== false,
          autoArchiveDays: Number(prefs?.autoArchiveDays) || 30,
          quietHours: {
            enabled: prefs?.quietHours?.enabled === true,
            start: prefs?.quietHours?.start || '22:00',
            end: prefs?.quietHours?.end || '08:00',
            timezone: prefs?.quietHours?.timezone || (typeof window !== 'undefined' ? Intl.DateTimeFormat().resolvedOptions().timeZone : 'America/New_York') || 'America/New_York',
          },
        });
      }
    } catch (err) {
      console.error('Failed to load notification preferences:', err);
    } finally {
      set({ loading: false });
    }
  },

  updateCategoryPreference: async (userId: string, category: NotificationCategory, channel: keyof CategoryPreference, enabled: boolean) => {
    // Guardrail: Prevent disabling critical billing or deadlines for inbox/email
    if ((category === 'billing' || category === 'deadlines') && (channel === 'inbox' || channel === 'email') && !enabled) {
      return;
    }

    set({ saving: true });

    // Optimistic update
    const previousCategories = get().categories;
    const nextCategories = {
      ...previousCategories,
      [category]: {
        ...previousCategories[category],
        [channel]: enabled,
      },
    };

    set({ categories: nextCategories });

    try {
      const userRef = doc(db, 'users', userId);
      await updateDoc(userRef, {
        [`preferences.categories.${category}.${channel}`]: enabled,
      });
    } catch (err) {
      console.error('Failed to update category preference:', err);
      // Rollback to previous state on failure
      set({ categories: previousCategories });
      throw err;
    } finally {
      set({ saving: false });
    }
  },

  updateGlobalToggle: async (userId: string, channel: 'email' | 'push', enabled: boolean) => {
    set({ saving: true });

    const key = channel === 'email' ? 'emailEnabled' : 'pushEnabled';
    const previousVal = get()[key === 'emailEnabled' ? 'emailEnabled' : 'pushEnabled'];

    set({ [key]: enabled } as any);

    try {
      const userRef = doc(db, 'users', userId);
      await updateDoc(userRef, {
        [`preferences.${key}`]: enabled,
      });
    } catch (err) {
      console.error(`Failed to update global ${channel} toggle:`, err);
      // Rollback
      set({ [key]: previousVal } as any);
      throw err;
    } finally {
      set({ saving: false });
    }
  },

  updateQuietHours: async (userId: string, updates: Partial<NotificationPreferencesState['quietHours']>) => {
    set({ saving: true });

    const previousQuietHours = get().quietHours;
    const nextQuietHours = {
      ...previousQuietHours,
      ...updates,
    };

    set({ quietHours: nextQuietHours });

    try {
      const userRef = doc(db, 'users', userId);
      const updatePayload: Record<string, any> = {};

      if (updates.enabled !== undefined) updatePayload['preferences.quietHours.enabled'] = updates.enabled;
      if (updates.start !== undefined) updatePayload['preferences.quietHours.start'] = updates.start;
      if (updates.end !== undefined) updatePayload['preferences.quietHours.end'] = updates.end;
      if (updates.timezone !== undefined) updatePayload['preferences.quietHours.timezone'] = updates.timezone;

      await updateDoc(userRef, updatePayload);
    } catch (err) {
      console.error('Failed to update quiet hours:', err);
      // Rollback
      set({ quietHours: previousQuietHours });
      throw err;
    } finally {
      set({ saving: false });
    }
  },

  updateAutoArchiveDays: async (userId: string, days: number) => {
    set({ saving: true });
    const previousDays = get().autoArchiveDays;
    set({ autoArchiveDays: days });
    try {
      const userRef = doc(db, 'users', userId);
      await updateDoc(userRef, {
        'preferences.autoArchiveDays': days,
      });
    } catch (err) {
      console.error('Failed to update autoArchiveDays:', err);
      set({ autoArchiveDays: previousDays });
      throw err;
    } finally {
      set({ saving: false });
    }
  },
}));

import { create } from 'zustand';
import { persist, createJSONStorage } from 'zustand/middleware';
import { Project, CostEntry, ProjectFinancials, ProjectTeamMember, FractionalInvestor, HistoricalProperty, ProspectProperty, FundingPledge, CostBasisLedger, RoleLinkedDocument, RehabExpense, HoldingCostEntry, SiteVisitLog, ClosingChecklistItem, ExitCostLineItem, SettlementDocument, LedgerItem, LOIDocument, InvestorCommitment, GuestPortalToken, Negotiation, Contingency, LoanStatus, DueDiligenceItem, RehabScheduleTask } from '@/types/schema';
import { deriveAllProjectMetrics } from '@/lib/metrics';
import type { ActiveProjectMetrics } from '@/lib/metrics';


/* ═══════════════════════════════════════════════════════════════
   Deal Store — Global State Engine for the Active Deal

   Architecture:
   ─────────────
   1. Portfolio-level metrics (across ALL projects)
   2. Per-deal derived metrics (activeProjectMetrics) for the currentProject
   3. Explicit cross-panel dispatch actions
   4. Zustand persist middleware → localStorage survival

   Cross-Panel Data Flow:
   ──────────────────────
   EvaluationPanel → dispatches purchasePrice, holdingCosts, closingCostsBuy
   EnginePanel     → dispatches renovationCosts (sum of approved costs)
   ExitPanel       → READS combined state via activeProjectMetrics (no mutations)

   Net Profit Formula (auto-derived):
   ───────────────────────────────────
   NetProfit = SalePrice - (PurchasePrice + ClosingCostsBuy/Sell
               + RenovationCosts + HoldingCosts)
   ═══════════════════════════════════════════════════════════════ */

// ─── Portfolio-Level Metrics ─────────────────────────────────
interface ProjectMetrics {
  totalApprovedCosts: number;
  totalPendingCosts: number;
  projectedProfit: number;
  projectedROI: number;
  activeProjects: number;
  totalCapitalCosts: number;
  totalHoldingCosts: number;
  // Phase 6 Contingency Enforcer
  rehabBudgetBase: number;
  rehabBudgetBuffered: number;
  triagePendingCount: number;
  // Phase 7 Realized Exit Metrics
  totalRealizedProfit: number;
  totalInvestedCapitalRealized: number;
  averageRealizedROI: number;
  soldProjects: number;
}

// ─── Per-Deal Derived Metrics ────────────────────────────────
// Auto-calculated whenever currentProject or its financials change.
// Consumed by ExitPanel / NetEngine without re-deriving locally.


// ─── Store Interface ─────────────────────────────────────────
interface ProjectState {
  projects: Project[];
  projectsSynced: boolean; // true once the first Firestore snapshot has fired
  currentProject: Project | null;
  ledgerItems: Record<string, LedgerItem[]>; // projectId -> items
  metrics: ProjectMetrics;
  activeProjectMetrics: ActiveProjectMetrics;

  whatIfOffsetMonths: number;

  // Core Actions
  setDeals: (projects: Project[]) => void;
  setLedgerItems: (projectId: string, items: LedgerItem[]) => void;
  setDeal: (deal: Project) => void;
  clearDeal: () => void;
  clearStore: () => void;
  addProject: (project: Project) => void;
  setWhatIfOffset: (months: number) => void;

  // Cross-Panel Financial Dispatch
  updateProjectFinancials: (projectId: string, updates: Partial<ProjectFinancials>) => void;
  updateProjectExit: (projectId: string, updates: Partial<Project['exit']>) => void;
  updateClosingRoom: (projectId: string, updates: Partial<Project['closingRoom']>) => void;
  updateRehabModule: (projectId: string, updates: Partial<Project['rehab']>) => void;
  updateProjectTeam: (projectId: string, team: ProjectTeamMember[]) => void;
  updateInvestors: (projectId: string, investors: FractionalInvestor[]) => void;
  updateProjectActionItems: (projectId: string, actionItems: any[]) => void;

  // Find & Fund Actions
  updateHistoricalProperties: (projectId: string, properties: HistoricalProperty[]) => void;
  updateProspects: (projectId: string, prospects: ProspectProperty[]) => void;
  updatePledges: (projectId: string, pledges: FundingPledge[]) => void;

  // LOI & Syndication Actions
  updateLOIDocuments: (projectId: string, docs: LOIDocument[]) => void;
  updateInvestorCommitments: (projectId: string, commitments: InvestorCommitment[]) => void;
  updateGuestPortalTokens: (projectId: string, tokens: GuestPortalToken[]) => void;

  // Acquisition & Due Diligence Actions
  updateCostBasis: (projectId: string, ledger: CostBasisLedger) => void;
  updateRoleDocuments: (projectId: string, docs: RoleLinkedDocument[]) => void;
  submitOffer: (projectId: string, offer: Omit<Negotiation, 'id' | 'date'>) => void;
  logCounterOffer: (projectId: string, negotiationId: string, counterOffer: number, status?: Negotiation['status']) => void;
  updateLoanStatus: (projectId: string, status: LoanStatus) => void;
  updateContingencies: (projectId: string, contingencies: Contingency[]) => void;
  updateDueDiligenceChecklist: (projectId: string, checklist: DueDiligenceItem[]) => void;
  transitionToPhase3: (projectId: string, finalHUDCosts: { purchasePrice: number, titleFees: number, originationFees: number }) => { success: boolean; error?: string };

  // Rehab Expansion Actions
  updateRehabExpenses: (projectId: string, expenses: RehabExpense[]) => void;
  updateHoldingCosts: (projectId: string, costs: HoldingCostEntry[]) => void;
  updateSiteVisitLogs: (projectId: string, logs: SiteVisitLog[]) => void;
  updateRehabScheduleTasks: (projectId: string, tasks: RehabScheduleTask[]) => void;

  // Closing Settlement Actions
  updateClosingChecklist: (projectId: string, items: ClosingChecklistItem[]) => void;
  updateExitCosts: (projectId: string, costs: ExitCostLineItem[]) => void;

  // Financial Statement Generator Actions
  updateSettlementDocuments: (projectId: string, docs: SettlementDocument[]) => void;

  // Recalculation (fires automatically on every mutation)
  recalculateMetrics: () => void;

  // Selectors
  getSelectedProject: () => Project | null;
  getLedgerItemsForProject: (projectId: string) => LedgerItem[];
}

// ─── Default Values ──────────────────────────────────────────
const initialMetrics: ProjectMetrics = {
  totalApprovedCosts: 0,
  totalPendingCosts: 0,
  projectedProfit: 0,
  projectedROI: 0,
  activeProjects: 0,
  totalCapitalCosts: 0,
  totalHoldingCosts: 0,
  rehabBudgetBase: 0,
  rehabBudgetBuffered: 0,
  triagePendingCount: 0,
  totalRealizedProfit: 0,
  totalInvestedCapitalRealized: 0,
  averageRealizedROI: 0,
  soldProjects: 0,
};

const initialActiveProjectMetrics: ActiveProjectMetrics = {
  purchasePrice: 0,
  renovationCosts: 0,
  closingCostsBuy: 0,
  closingCostsSell: 0,
  holdingCosts: 0,
  salePrice: 0,
  netProfit: 0,
  roi: 0,
  annualizedIrr: 0,
  holdDays: 0,
  totalInvestment: 0,
};

// ─── Per-Deal Calculator ─────────────────────────────────────
// Delegates calculation to the pure metrics engine
function deriveActiveProjectMetrics(deal: Project | null, whatIfOffsetMonths: number, ledgerItems: LedgerItem[] = []): ActiveProjectMetrics {
  if (!deal) return initialActiveProjectMetrics;
  return deriveAllProjectMetrics(deal, whatIfOffsetMonths, ledgerItems);
}

// ─── Zustand Store with Persist Middleware ────────────────────
export const useProjectStore = create<ProjectState>()(
  persist(
    (set, get) => ({
      projects: [],
      projectsSynced: false,
      currentProject: null,
      ledgerItems: {},
      metrics: initialMetrics,
      activeProjectMetrics: initialActiveProjectMetrics,
      whatIfOffsetMonths: 0,

      // ─── What-If Simulator ───────────────────────────────
      setWhatIfOffset: (months) => {
        set({ whatIfOffsetMonths: months });
        get().recalculateMetrics();
      },

      // ─── Portfolio Actions ───────────────────────────────
      setDeals: (projects) => {
        set({ projects, projectsSynced: true });
        const { currentProject } = get();
        if (currentProject) {
          const u = projects.find(d => d.id === currentProject.id);
          if (u) set({ currentProject: u });
        }
        get().recalculateMetrics();
      },

      setLedgerItems: (projectId, items) => {
        set((state) => ({
          ledgerItems: {
            ...state.ledgerItems,
            [projectId]: items
          }
        }));
        get().recalculateMetrics();
      },

      setDeal: (deal) => {
        set({ currentProject: deal });
        // Immediately derive metrics for the newly selected deal
        const { whatIfOffsetMonths, ledgerItems } = get();
        const items = ledgerItems[deal.id] || [];
        set({ activeProjectMetrics: deriveActiveProjectMetrics(deal, whatIfOffsetMonths, items) });
      },

      clearDeal: () => {
        set({ currentProject: null, activeProjectMetrics: initialActiveProjectMetrics });
      },

      clearStore: () => {
        set({
          projects: [],
          projectsSynced: false,
          currentProject: null,
          ledgerItems: {},
          metrics: initialMetrics,
          activeProjectMetrics: initialActiveProjectMetrics,
          whatIfOffsetMonths: 0,
        });
      },

      addProject: (project) => {
        const { projects } = get();
        set({ projects: [...projects, project] });
        get().recalculateMetrics();
      },

      // ─── Cross-Panel Financial Dispatch ──────────────────
      // EvaluationPanel dispatches: purchasePrice, loanAmount, loanInterestRate, etc.
      // EnginePanel dispatches: costs (approved), rehab tasks, permit status
      // ExitPanel dispatches: actualSalePrice, commissions, finalClosingCosts
      updateProjectFinancials: async (projectId, updates) => {
        const { projects, currentProject } = get();

        // 1. Snapshot previous state for rollback
        const previousProjects = projects.map(d => ({
          ...d,
          financials: { ...d.financials }
        }));
        const previousCurrentProject = currentProject
          ? { ...currentProject, financials: { ...currentProject.financials } }
          : null;

        // 2. Optimistic Update in Zustand store
        const updatedDeals = projects.map(d => {
          if (d.id === projectId) {
            return {
              ...d,
              financials: {
                ...d.financials,
                ...updates
              } as Project['financials']
            };
          }
          return d;
        });

        set({ projects: updatedDeals });
        if (currentProject?.id === projectId) {
          const u = updatedDeals.find(d => d.id === projectId);
          if (u) set({ currentProject: u });
        }
        get().recalculateMetrics();

        // 3. Persist to authoritative store (Firestore via PATCH API)
        try {
          if (typeof window !== 'undefined' && window.location.pathname.startsWith('/demo')) {
            // Demo mode is client-only
            return;
          }

          let token = '';
          if (typeof window !== 'undefined' && document.cookie.includes('__e2e_test')) {
            token = 'mock_token_123';
          } else {
            const { auth } = await import('@/lib/firebase/config');
            const userToken = await auth.currentUser?.getIdToken();
            if (!userToken) {
              throw new Error('Not authenticated. Please log in again.');
            }
            token = userToken;
          }

          const res = await fetch(`/api/projects/${projectId}`, {
            method: 'PATCH',
            headers: {
              'Content-Type': 'application/json',
              Authorization: `Bearer ${token}`,
            },
            body: JSON.stringify({ financials: updates }),
          });

          if (!res.ok) {
            const errData = await res.json().catch(() => ({}));
            throw new Error(errData.error || `Server responded with ${res.status}`);
          }

          const result = await res.json();
          if (!result.success) {
            throw new Error(result.error || 'Server failed to save financials.');
          }
        } catch (err: any) {
          console.error('[projectStore] updateProjectFinancials persist failed:', err);
          const { default: toast } = await import('react-hot-toast');
          toast.error(err.message || 'Failed to save changes. Reverting to server state.');

          // 4. Rollback to persisted truth on failure
          set({ projects: previousProjects });
          if (previousCurrentProject) {
            set({ currentProject: previousCurrentProject });
          }
          get().recalculateMetrics();
        }
      },

      updateProjectExit: (projectId, updates) => {
        const { projects, currentProject } = get();

        const updatedDeals = projects.map(d => {
          if (d.id === projectId) {
            return {
              ...d,
              exit: {
                ...d.exit,
                ...updates
              } as Project['exit']
            };
          }
          return d;
        });

        set({ projects: updatedDeals });
        if (currentProject?.id === projectId) {
          const u = updatedDeals.find(d => d.id === projectId);
          if (u) set({ currentProject: u });
        }
        get().recalculateMetrics();
      },

      updateClosingRoom: (projectId, updates) => {
        const { projects, currentProject } = get();

        const updatedDeals = projects.map(d => {
          if (d.id === projectId) {
            return {
              ...d,
              closingRoom: {
                ...d.closingRoom,
                ...updates
              } as Project['closingRoom']
            };
          }
          return d;
        });

        set({ projects: updatedDeals });
        if (currentProject?.id === projectId) {
          const u = updatedDeals.find(d => d.id === projectId);
          if (u) set({ currentProject: u });
        }
