              rehab: {
                ...(d.rehab || defaultRehab),
                ...updates
              } as Project['rehab']
            };
          }
          return d;
        });

        set({ projects: updatedDeals });

        // Auto-update metrics whenever rehab state changes
        get().recalculateMetrics();

        if (currentProject?.id === projectId) {
