      // ─── Financial Statement Generator Mutations ─────────
      updateSettlementDocuments: (projectId, docs) => {
        const { projects, currentProject } = get();
        const updatedDeals = projects.map(d =>
          d.id === projectId ? { ...d, settlementDocuments: docs } : d
        );
